/* Feng codegen implementation. See codegen.h for the supported feature slice.
 *
 * Production-grade rules followed:
 *   - All I/O strings are heap-allocated and freed; no leaks on the success path.
 *   - All emit_* paths propagate errors via the codegen context; once an error
 *     is set, subsequent emits become no-ops and the entry returns false.
 *   - Generated C is GNU C11; the host compile path enables GNU extensions
 *     for the exception backend's label-address strategy.
 *   - String literal allocations are deduplicated per literal site via a
 *     file-static FengString* slot, so each literal allocates exactly once.
 *   - Strings are managed objects; managed locals are released on scope exit
 *     (incl. returns and break/continue paths via cleanup-frame walking).
 */
#include "codegen/codegen.h"
#include <ctype.h>
#include <inttypes.h>
#include <math.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "lexer/token.h"
#include "parser/parser.h"

/* ===================== string buffer ===================== */

typedef struct Buf {
    char  *data;
    size_t length;
    size_t capacity;
} Buf;

static void buf_init(Buf *b) {
    b->data = NULL;
    b->length = 0;
    b->capacity = 0;
}

static void buf_free(Buf *b) {
    free(b->data);
    b->data = NULL;
    b->length = 0;
    b->capacity = 0;
}

static bool buf_reserve(Buf *b, size_t extra) {
    size_t need = b->length + extra + 1;
    if (need <= b->capacity) return true;
    size_t cap = b->capacity ? b->capacity : 64;
    while (cap < need) cap *= 2;
    char *p = realloc(b->data, cap);
    if (!p) return false;
    b->data = p;
    b->capacity = cap;
    return true;
}

static void buf_append(Buf *b, const char *s, size_t n) {
    if (!buf_reserve(b, n)) return;
    memcpy(b->data + b->length, s, n);
    b->length += n;
    b->data[b->length] = '\0';
}

static void buf_append_cstr(Buf *b, const char *s) {
    buf_append(b, s, strlen(s));
}

static void buf_append_fmt(Buf *b, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    va_list ap2;
    va_copy(ap2, ap);
    int n = vsnprintf(NULL, 0, fmt, ap);
    va_end(ap);
    if (n < 0) { va_end(ap2); return; }
    if (!buf_reserve(b, (size_t)n)) { va_end(ap2); return; }
    vsnprintf(b->data + b->length, b->capacity - b->length, fmt, ap2);
    b->length += (size_t)n;
    va_end(ap2);
}

/* Append an explicit byte sequence as one escaped C string literal. Fixed
 * three-digit octal escapes preserve embedded NUL and cannot consume bytes
 * that follow the escape. */
static void buf_append_c_bytes_literal(Buf *b,
                                       const char *bytes,
                                       size_t length) {
    size_t index;

    buf_append_cstr(b, "\"");
    for (index = 0U; index < length; ++index) {
        unsigned char value = (unsigned char)bytes[index];

        if (value == '"' || value == '\\') {
            buf_append_fmt(b, "\\%c", (char)value);
        } else if (value >= 0x20U && value <= 0x7eU) {
            buf_append(b, bytes + index, 1U);
        } else {
            buf_append_fmt(b, "\\%03o", (unsigned int)value);
        }
    }
    buf_append_cstr(b, "\"");
}

/* Append NUL-terminated text as one escaped C string literal. */
static void buf_append_c_string_literal(Buf *b, const char *text) {
    buf_append_c_bytes_literal(b, text, strlen(text));
}

/* ===================== type kinds ===================== */

typedef enum CGTypeKind {
    CG_TYPE_UNKNOWN = 0,
    CG_TYPE_VOID,
    CG_TYPE_BOOL,
    CG_TYPE_I8, CG_TYPE_I16, CG_TYPE_I32, CG_TYPE_I64,
    CG_TYPE_U8, CG_TYPE_U16, CG_TYPE_U32, CG_TYPE_U64,
    CG_TYPE_F32, CG_TYPE_F64,
    CG_TYPE_POINTER,
    CG_TYPE_STRING,
    CG_TYPE_ARRAY,        /* element kind held separately when needed */
    CG_TYPE_OBJECT,       /* user-defined type — Phase 1A iter 2 */
    CG_TYPE_SPEC,         /* fat object-form spec value (Step 4b — value model) */
    CG_TYPE_CALLABLE,     /* callable-form spec value (closure pointer) */
    CG_TYPE_GENERIC_PARAM,/* erased type-parameter slot (G6 — generics) */
    CG_TYPE_DEFER         /* sentinel: scope-local defer registration entry.
                           * Not a real type; only used by cg_release_scope to
                           * recognise defer cleanup nodes mixed into the
                           * locals list (docs/engineering/feng-defer-dev.md §5.6.1). */
} CGTypeKind;

struct UserType;     /* forward */
struct UserSpec;     /* forward (Step 4b) */
typedef struct CG CG;

static bool cg_user_type_is_abi(const struct UserType *t);
static bool cg_user_spec_index(const CG *cg, const struct UserSpec *spec, size_t *out_index);
static const struct UserSpec *cg_user_spec_by_index(const CG *cg, size_t index);

typedef struct CGType {
    CGTypeKind kind;
    /* For arrays/pointers: nested CGType (heap-owned). NULL otherwise. */
    struct CGType *element;
    /* For OBJECT: borrowed pointer to the registered UserType. NULL otherwise.
     * The UserType is owned by the CG context and outlives every CGType. */
    const struct UserType *user;
    /* For SPEC/CALLABLE: borrowed pointer to the registered UserSpec. NULL
     * otherwise. The UserSpec is owned by the CG context and outlives every
     * CGType. */
    const struct UserSpec *user_spec;
    /* For nominal enums lowered as i32: borrowed pointer to the enum decl so
     * codegen can preserve enum identity for equality/default-value paths
     * while still emitting the stable int32_t ABI surface. */
    const FengDecl *enum_decl;
    /* For GENERIC_PARAM (G6): 0-based index into the enclosing generic
     * function's type_params array (e.g. 0 for T, 1 for U). */
    size_t generic_param_index;
    /* For ARRAY: true when the array has writable elements (T[!]). */
    bool array_element_writable;
} CGType;

static void cg_type_ref_free(FengTypeRef *ref);
static FengTypeRef *cg_type_ref_from_cgtype(const CG *cg,
                                            const CGType *type,
                                            FengToken token);
static void cg_append_type_ref_display(Buf *out, const FengTypeRef *ref);
static const FengProgram *cg_type_ref_decl_identity(const CG *cg,
                                                    const FengTypeRef *ref,
                                                    FengSlice *out_name);
static const FengProgram *cg_type_ref_decl_identity_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program,
    FengSlice *out_name);
/* Qualifies single-segment user type names to fully-qualified form for debug
 * display_type strings. Only used in the debug path. */
static FengTypeRef *cg_debug_qualify_type_ref(const CG *cg,
                                              const FengTypeRef *ref);
static FengTypeRef *cg_debug_qualify_type_ref_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program);

typedef enum CGValueKind {
    CG_VK_TRIVIAL = 0,
    CG_VK_MANAGED_POINTER,
    CG_VK_AGGREGATE
} CGValueKind;

typedef enum CGAggregateDefaultInitKind {
    CG_AGGREGATE_DEFAULT_INIT_NONE = 0,
    CG_AGGREGATE_DEFAULT_INIT_ZERO_BYTES,
    CG_AGGREGATE_DEFAULT_INIT_DESCRIPTOR
} CGAggregateDefaultInitKind;

typedef void (*CGAggregateSlotRowEmitter)(Buf *out,
                                          const char *field_base_offsetof_expr,
                                          const CGType *type);
typedef void (*CGAggregateCleanupPushEmitter)(Buf *out,
                                              const char *cname,
                                              const CGType *type);
typedef void (*CGAggregateCleanupZeroEmitter)(Buf *out,
                                              const char *cname,
                                              const CGType *type);

/* Static codegen facts for value-model aggregates. These facts describe the
 * generated descriptor and flattened managed-slot surface used by runtime
 * aggregate APIs without adding any runtime query path. */
typedef struct CGAggregateFacts {
    CGValueKind value_kind;
    const char *descriptor_name;
    const char *value_struct_name;
    size_t pointer_slot_count;
    CGAggregateDefaultInitKind default_init_kind;
    CGAggregateSlotRowEmitter emit_pointer_slot_rows;
    CGAggregateCleanupPushEmitter emit_cleanup_push;
    CGAggregateCleanupZeroEmitter emit_cleanup_zero;
} CGAggregateFacts;

/* Compile-time symbols for one concrete ValueBox<T>. Strings are owned so
 * callers can use one uniform cleanup path for builtin, enum, and user-value
 * boxes without exposing symbol-lifetime differences. */
typedef struct CGValueBoxInfo {
    char *struct_name;
    char *descriptor_name;
} CGValueBoxInfo;

static bool cg_aggregate_facts(const CGType *t, CGAggregateFacts *out);
static char *cg_enum_trivial_descriptor_name(const CG *cg,
                                             const FengDecl *enum_decl);
static char *cg_enum_value_box_struct_name(const CG *cg,
                                           const FengDecl *enum_decl);
static char *cg_enum_value_box_descriptor_name(const CG *cg,
                                               const FengDecl *enum_decl);
static bool cg_ensure_enum_emitted(CG *cg, const FengDecl *decl);
static char *cg_managed_pointer_descriptor_expr(const CGType *t);
static bool cg_type_is_tuple_user(const CGType *t);
static bool cg_type_is_value_user(const CGType *t);
static bool cg_type_is_value_semantics(const CGType *t);
static bool cg_user_type_is_value_semantics(const struct UserType *t);
static bool cg_update_value_type_descriptor_names(CG *cg);
static bool cg_type_has_value_box(const CGType *type);
static void cg_value_box_info_dispose(CGValueBoxInfo *info);
static bool cg_value_box_info_for_type(CG *cg,
                                       const CGType *type,
                                       FengToken blame,
                                       CGValueBoxInfo *out_info);

static CGType *cgtype_new(CGTypeKind k) {
    CGType *t = calloc(1, sizeof *t);
    if (t) t->kind = k;
    return t;
}

static void cgtype_free(CGType *t) {
    if (!t) return;
    cgtype_free(t->element);
    free(t);
}

static CGType *cgtype_clone(const CGType *t) {
    if (!t) return NULL;
    CGType *c = cgtype_new(t->kind);
    if (!c) return NULL;
    c->element = cgtype_clone(t->element);
    c->user = t->user;
    c->user_spec = t->user_spec;
    c->enum_decl = t->enum_decl;
    c->generic_param_index = t->generic_param_index;
    c->array_element_writable = t->array_element_writable;
    return c;
}

static CGType *cgtype_new_enum(const FengDecl *enum_decl) {
    CGType *type = cgtype_new(CG_TYPE_I32);

    if (type != NULL) {
        type->enum_decl = enum_decl;
    }
    return type;
}

/* Value-kind classifier for codegen-side dispatch on per-field lifetime
 * emission. Mirrors the runtime three-way classification described in
 * docs/engineering/feng-value-model-delivered.md §3.3 / §7.2:
 *
 *   CG_VK_TRIVIAL          — bit-copyable, no participation in ARC.
 *   CG_VK_MANAGED_POINTER  — single managed pointer (string / array / object).
 *   CG_VK_AGGREGATE        — by-value compound carrying one or more
 *                            FENG_SLOT_POINTER slots inside (currently the
 *                            object-form fat spec value layout; future
 *                            aggregate kinds classify through
 *                            cg_aggregate_facts).
 *
 * `cgtype_is_managed` is preserved as a thin wrapper around this classifier
 * so the many ARC-emit call sites continue to read naturally; new code that
 * needs to branch by kind should call cgtype_value_kind directly. */
static CGValueKind cgtype_value_kind(const CGType *t) {
    if (!t) return CG_VK_TRIVIAL;
    CGAggregateFacts aggregate_facts;
    if (cg_aggregate_facts(t, &aggregate_facts)) {
        return aggregate_facts.value_kind;
    }
    switch (t->kind) {
        case CG_TYPE_STRING:
        case CG_TYPE_ARRAY:
        case CG_TYPE_OBJECT:
        case CG_TYPE_CALLABLE:
            return CG_VK_MANAGED_POINTER;
        case CG_TYPE_GENERIC_PARAM:
            /* Erased type: ARC dispatch happens at the generic call-site via
             * the FengGenericParamDescriptor; the placeholder itself is not
             * managed through the normal ARC path. */
            return CG_VK_TRIVIAL;
        default:
            return CG_VK_TRIVIAL;
    }
}

static bool cgtype_is_managed(const CGType *t) {
    return cgtype_value_kind(t) == CG_VK_MANAGED_POINTER;
}

static bool cgtype_is_aggregate(const CGType *t) {
    return cgtype_value_kind(t) == CG_VK_AGGREGATE;
}

/* docs/engineering/feng-defer-dev.md §5.6.1: DEFER sentinel kind for scope-local defer
 * registration entries. cgtype_is_defer is checked by cg_release_scope to
 * dispatch on defer nodes mixed into the locals list. */
static bool cgtype_is_defer(const CGType *t) {
    return t != NULL && t->kind == CG_TYPE_DEFER;
}

static bool cgtype_is_by_value_struct(const CGType *t) {
    CGAggregateFacts facts;
    return t != NULL &&
           cg_aggregate_facts(t, &facts) &&
           facts.value_struct_name != NULL;
}

static bool cgtype_is_integer(CGTypeKind k) {
    return k == CG_TYPE_I8 || k == CG_TYPE_I16 || k == CG_TYPE_I32 || k == CG_TYPE_I64 ||
           k == CG_TYPE_U8 || k == CG_TYPE_U16 || k == CG_TYPE_U32 || k == CG_TYPE_U64;
}

static bool cgtype_is_signed(CGTypeKind k) {
    return k == CG_TYPE_I8 || k == CG_TYPE_I16 || k == CG_TYPE_I32 || k == CG_TYPE_I64;
}

static bool cgtype_is_float(CGTypeKind k) {
    return k == CG_TYPE_F32 || k == CG_TYPE_F64;
}

static bool cgtype_is_numeric(CGTypeKind k) {
    return cgtype_is_integer(k) || cgtype_is_float(k);
}

static bool cg_type_kind_is_scalar_builtin(CGTypeKind k) {
    return k == CG_TYPE_BOOL ||
           k == CG_TYPE_I8 || k == CG_TYPE_I16 || k == CG_TYPE_I32 || k == CG_TYPE_I64 ||
           k == CG_TYPE_U8 || k == CG_TYPE_U16 || k == CG_TYPE_U32 || k == CG_TYPE_U64 ||
           k == CG_TYPE_F32 || k == CG_TYPE_F64;
}

/* Return the statically known runtime ValueBox<T> symbols for one canonical
 * builtin scalar. This is a compile-time switch; generated code performs no
 * runtime type selection. */
static bool cg_scalar_value_box_names(CGTypeKind kind,
                                      const char **out_struct_name,
                                      const char **out_descriptor_name) {
    if (out_struct_name == NULL || out_descriptor_name == NULL) return false;
    switch (kind) {
        case CG_TYPE_BOOL:
            *out_struct_name = "FengValueBox__bool";
            *out_descriptor_name = "feng_value_box_bool_descriptor";
            return true;
        case CG_TYPE_I8:
            *out_struct_name = "FengValueBox__i8";
            *out_descriptor_name = "feng_value_box_i8_descriptor";
            return true;
        case CG_TYPE_I16:
            *out_struct_name = "FengValueBox__i16";
            *out_descriptor_name = "feng_value_box_i16_descriptor";
            return true;
        case CG_TYPE_I32:
            *out_struct_name = "FengValueBox__i32";
            *out_descriptor_name = "feng_value_box_i32_descriptor";
            return true;
        case CG_TYPE_I64:
            *out_struct_name = "FengValueBox__i64";
            *out_descriptor_name = "feng_value_box_i64_descriptor";
            return true;
        case CG_TYPE_U8:
            *out_struct_name = "FengValueBox__u8";
            *out_descriptor_name = "feng_value_box_u8_descriptor";
            return true;
        case CG_TYPE_U16:
            *out_struct_name = "FengValueBox__u16";
            *out_descriptor_name = "feng_value_box_u16_descriptor";
            return true;
        case CG_TYPE_U32:
            *out_struct_name = "FengValueBox__u32";
            *out_descriptor_name = "feng_value_box_u32_descriptor";
            return true;
        case CG_TYPE_U64:
            *out_struct_name = "FengValueBox__u64";
            *out_descriptor_name = "feng_value_box_u64_descriptor";
            return true;
        case CG_TYPE_F32:
            *out_struct_name = "FengValueBox__f32";
            *out_descriptor_name = "feng_value_box_f32_descriptor";
            return true;
        case CG_TYPE_F64:
            *out_struct_name = "FengValueBox__f64";
            *out_descriptor_name = "feng_value_box_f64_descriptor";
            return true;
        default: return false;
    }
}

static int cgtype_int_rank(CGTypeKind k) {
    switch (k) {
        case CG_TYPE_I8: case CG_TYPE_U8:  return 1;
        case CG_TYPE_I16: case CG_TYPE_U16: return 2;
        case CG_TYPE_I32: case CG_TYPE_U32: return 3;
        case CG_TYPE_I64: case CG_TYPE_U64: return 4;
        default: return 0;
    }
}

static const char *cgtype_to_c(CGTypeKind k) {
    switch (k) {
        case CG_TYPE_VOID: return "void";
        case CG_TYPE_BOOL: return "bool";
        case CG_TYPE_I8: return "int8_t";
        case CG_TYPE_I16: return "int16_t";
        case CG_TYPE_I32: return "int32_t";
        case CG_TYPE_I64: return "int64_t";
        case CG_TYPE_U8: return "uint8_t";
        case CG_TYPE_U16: return "uint16_t";
        case CG_TYPE_U32: return "uint32_t";
        case CG_TYPE_U64: return "uint64_t";
        case CG_TYPE_F32: return "float";
        case CG_TYPE_F64: return "double";
        case CG_TYPE_POINTER: return "void *";
        case CG_TYPE_STRING: return "FengString *";
        case CG_TYPE_ARRAY: return "FengArray *";
        case CG_TYPE_OBJECT: return "void *";
        case CG_TYPE_CALLABLE: return "void *";
        case CG_TYPE_GENERIC_PARAM: return "void *"; /* erased; actual dispatch via descriptor */
        default: return "void";
    }
}

static char *cg_descriptor_expr_from_symbol(const char *symbol_name) {
    Buf b;

    if (symbol_name == NULL) {
        return NULL;
    }
    buf_init(&b);
    buf_append_fmt(&b, "&%s", symbol_name);
    return b.data;
}

static char *cg_trivial_descriptor_expr(const CG *cg, const CGType *t) {
    const char *symbol_name = NULL;

    if (t == NULL) {
        return NULL;
    }
    if (t->enum_decl != NULL) {
        char *enum_desc_name = cg_enum_trivial_descriptor_name(cg, t->enum_decl);
        char *expr = cg_descriptor_expr_from_symbol(enum_desc_name);

        free(enum_desc_name);
        return expr;
    }
    switch (t->kind) {
        case CG_TYPE_BOOL: symbol_name = "feng_bool_descriptor"; break;
        case CG_TYPE_I8: symbol_name = "feng_i8_descriptor"; break;
        case CG_TYPE_I16: symbol_name = "feng_i16_descriptor"; break;
        case CG_TYPE_I32: symbol_name = "feng_i32_descriptor"; break;
        case CG_TYPE_I64: symbol_name = "feng_i64_descriptor"; break;
        case CG_TYPE_U8: symbol_name = "feng_u8_descriptor"; break;
        case CG_TYPE_U16: symbol_name = "feng_u16_descriptor"; break;
        case CG_TYPE_U32: symbol_name = "feng_u32_descriptor"; break;
        case CG_TYPE_U64: symbol_name = "feng_u64_descriptor"; break;
        case CG_TYPE_F32: symbol_name = "feng_f32_descriptor"; break;
        case CG_TYPE_F64: symbol_name = "feng_f64_descriptor"; break;
        case CG_TYPE_POINTER: symbol_name = "feng_pointer_descriptor"; break;
        case CG_TYPE_OBJECT: {
            CGAggregateFacts facts;

            if (cg_aggregate_facts(t, &facts) &&
                facts.value_kind == CG_VK_TRIVIAL) {
                symbol_name = facts.descriptor_name;
            }
            break;
        }
        default:
            break;
    }
    return cg_descriptor_expr_from_symbol(symbol_name);
}

static bool cg_array_data_pointer_element_is_lowerable(const CGType *element_type);

static bool cg_array_data_pointer_type_is_lowerable(const CGType *array_type);

static void cg_emit_array_data_pointer_c_type(Buf *b, const CGType *array_type);

static bool cg_pointer_inner_is_lowerable(const CGType *t) {
    if (t == NULL) {
        return false;
    }
    switch (t->kind) {
        case CG_TYPE_BOOL:
        case CG_TYPE_I8:
        case CG_TYPE_I16:
        case CG_TYPE_I32:
        case CG_TYPE_I64:
        case CG_TYPE_U8:
        case CG_TYPE_U16:
        case CG_TYPE_U32:
        case CG_TYPE_U64:
        case CG_TYPE_F32:
        case CG_TYPE_F64:
        case CG_TYPE_STRING:
        case CG_TYPE_POINTER:
        case CG_TYPE_CALLABLE:
            return true;
        case CG_TYPE_ARRAY:
            return cg_array_data_pointer_type_is_lowerable(t);
        case CG_TYPE_OBJECT:
            return cg_user_type_is_abi(t->user);
        default:
            return false;
    }
}

static bool cg_decl_has_field_members(const FengDecl *decl) {
    size_t member_index;

    if (decl == NULL || decl->kind != FENG_DECL_TYPE) {
        return false;
    }

    for (member_index = 0U; member_index < decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = decl->as.type_decl.members[member_index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_FIELD) {
            return true;
        }
    }

    return false;
}

/* When generating user-type pointer references we use `<struct>` *` so the
 * field accesses are direct member loads. The generic `void *` form above is
 * used only for fall-back / unknown user types, which never reach the body.
 */
typedef struct UserType UserType;

typedef struct UserField {
    char   *feng_name;     /* e.g., "name" */
    char   *c_name;        /* sanitised */
    CGType *type;          /* heap-owned */
    const FengTypeMember *member; /* borrowed AST member, for declaration initializers */
} UserField;

typedef struct UserMethod {
    char   *feng_name;     /* e.g., "say" */
    char   *c_name;        /* mangled e.g. Feng__feng__examples__User__say */
    CGType *return_type;   /* heap-owned */
    CGType **param_types;  /* heap-owned, length param_count */
    char  **param_names;
    size_t  param_count;
    bool    is_variadic;   /* true when the last param is a variadic T... */
    const FengTypeMember *member;
} UserMethod;

typedef enum CGGenericLayoutFact {
    CG_GENERIC_LAYOUT_UNKNOWN = 0,
    CG_GENERIC_LAYOUT_COMPUTING,
    CG_GENERIC_LAYOUT_FIXED,
    CG_GENERIC_LAYOUT_REIFIED
} CGGenericLayoutFact;

typedef struct TypeStaticBinding {
    char   *feng_name;
    char   *c_name;
    char   *c_ensure_init_name;
    char   *c_inited_name;
    CGType *type;
    bool    is_var;
    bool    exports_public_surface;
    const FengTypeMember *member;
    const UserType *owner_type;
} TypeStaticBinding;

struct UserType {
    char   *feng_name;
    char   *c_struct_name;     /* e.g., Feng__feng__examples__User */
    char   *c_desc_name;       /* e.g., FengTypeDesc__feng__examples__User */
    /* Symbol name of the codegen-emitted release_children callback. NULL
     * when the type has no managed fields (no callback is generated and the
     * descriptor's release_children slot is left NULL). */
    char   *c_release_children_name;
    /* User finalizer (`fn ~T()`). NULL when the type declares none.
     * c_finalizer_name is the symbol of the codegen-emitted thunk that
     * adapts the runtime FengFinalizerFn(void *self) signature to the
     * generated method body; it owns the malloc'd string. */
    const FengTypeMember *finalizer;
    char   *c_finalizer_name;
    /* Symbol name of the codegen-emitted "default zero" factory. This
     * function is only emitted when the type is eligible for default-zero
     * initialisation (no participation in an object-reference cycle). For
     * cyclic types the slot stays NULL and any binding/field that would need
     * a default zero of this type is rejected at semantic time. */
    char   *c_default_zero_name;
    char   *c_aggregate_slots_name;
    char   *c_aggregate_default_name;
    char   *c_aggregate_desc_name;
    char   *c_value_box_struct_name;
    char   *c_value_box_desc_name;
    char   *c_value_box_release_children_name;
    bool    is_abi_type;
    char   *c_abi_layout_name;
    char   *c_abi_ptr_name;
    char   *c_abi_base_offset_name;
    char   *c_abi_value_name;
    char   *c_abi_box_name;
    UserField  *fields;
    size_t      field_count;
    UserMethod *constructors;
    size_t      constructor_count;
    UserMethod *methods;
    size_t      method_count;
    TypeStaticBinding *static_bindings;
    size_t      static_binding_count;
    UserMethod *static_methods;
    size_t      static_method_count;
    const FengDecl *decl;
    bool is_generic_instance;
    /* True only for the stack-owned owner view used while emitting one
     * generic shared method. Its fields provide open layout information, but
     * nominal operations must resolve the persistent registered instance. */
    bool is_ephemeral_generic_owner_view;
    const FengDecl *generic_origin_decl;
    FengTypeRef **generic_type_args;
    size_t generic_type_arg_count;
    char **generic_context_type_param_names;
    size_t *generic_context_type_param_constraint_indices;
    size_t generic_context_type_param_count;
    const FengProgram *instantiation_program;
    /* Owning program — set when the type shell is registered while emitting
     * that program. Used by cg_find_user_type to enforce per-program
     * (module / `use`) visibility so two distinct types that happen to share
     * a simple name in different modules cannot be conflated. */
    const FengProgram *owner_program;
    /* Cached physical-layout fact for this exact type instance. Each value
     * type computes the fact from its direct fields; a nested value field
     * supplies its own cached fact. */
    CGGenericLayoutFact generic_layout_fact;
};

/** Return whether a user type represents an instance of a generic origin. */
static bool cg_user_type_is_generic_origin_instance(const UserType *type) {
    return type != NULL &&
           type->is_generic_instance &&
           type->generic_origin_decl != NULL &&
           type->generic_origin_decl->kind == FENG_DECL_TYPE &&
           type->generic_origin_decl->as.type_decl.type_param_count > 0U;
}

/** Return whether a generated generic instance owns per-closed static state. */
static bool cg_user_type_uses_static_binding_states(const UserType *type) {
    return cg_user_type_is_generic_origin_instance(type) &&
           type->generic_context_type_param_count == 0U &&
           type->static_binding_count > 0U;
}

/** Build the C symbol of a generic instance's static binding state table. */
static char *cg_user_type_static_binding_states_name_dup(const UserType *type) {
    Buf name;

    if (type == NULL || type->c_struct_name == NULL) {
        return NULL;
    }
    buf_init(&name);
    buf_append_fmt(&name, "%s__static_binding_states", type->c_struct_name);
    return name.data;
}

/** Resolve a static binding's declaration-order index within its owner. */
static bool cg_type_static_binding_index(const TypeStaticBinding *binding,
                                         size_t *out_index) {
    const UserType *owner;

    if (binding == NULL || binding->owner_type == NULL) {
        return false;
    }
    owner = binding->owner_type;
    for (size_t index = 0U; index < owner->static_binding_count; ++index) {
        if (&owner->static_bindings[index] == binding) {
            if (out_index != NULL) {
                *out_index = index;
            }
            return true;
        }
    }
    return false;
}

/** Build the lvalue expression for one generic instance static state entry. */
static char *cg_type_static_binding_state_expr_dup(
    const TypeStaticBinding *binding) {
    char *states_name;
    size_t index;
    Buf expression;

    if (!cg_type_static_binding_index(binding, &index)) {
        return NULL;
    }
    states_name = cg_user_type_static_binding_states_name_dup(
        binding->owner_type);
    if (states_name == NULL) {
        return NULL;
    }
    buf_init(&expression);
    buf_append_fmt(&expression, "%s[%zu]", states_name, index);
    free(states_name);
    return expression.data;
}

static bool cg_user_type_is_abi(const struct UserType *t) {
    return t != NULL && t->is_abi_type;
}

static bool cg_user_type_is_tuple(const struct UserType *t) {
    return t != NULL &&
           t->decl != NULL &&
           t->decl->kind == FENG_DECL_TYPE &&
           t->decl->as.type_decl.is_tuple;
}

static bool cg_type_is_tuple_user(const CGType *t) {
    return t != NULL && t->kind == CG_TYPE_OBJECT && cg_user_type_is_tuple(t->user);
}

/* @value type check: true when the UserType represents a `@value type` decl. */
static bool cg_user_type_is_value(const struct UserType *t) {
    return t != NULL &&
           t->decl != NULL &&
           t->decl->kind == FENG_DECL_TYPE &&
           t->decl->as.type_decl.is_value;
}

/* Tuples and explicitly annotated @value types share the aggregate
 * representation and descriptor ABI. */
static bool cg_type_decl_is_value_semantics(const FengDecl *decl) {
    return decl != NULL &&
           decl->kind == FENG_DECL_TYPE &&
           (decl->as.type_decl.is_tuple || decl->as.type_decl.is_value);
}

static bool cg_type_is_value_user(const CGType *t) {
    return t != NULL && t->kind == CG_TYPE_OBJECT && cg_user_type_is_value(t->user);
}

/* Convenience: true for any value-semantics aggregate (tuple or @value).
 * Both share the same codegen path: inline struct layout, aggregate
 * descriptors, field-wise equality, no FengManagedHeader. */
static bool cg_type_is_value_semantics(const CGType *t) {
    return cg_type_is_tuple_user(t) || cg_type_is_value_user(t);
}

/* Return whether equality for this lowered managed-pointer category is
 * defined as direct reference identity. String is intentionally excluded
 * because it has content equality, while value-semantics user types use
 * their aggregate equality descriptors. */
static bool cg_type_has_reference_identity_equality(const CGType *t) {
    if (t == NULL) {
        return false;
    }
    return t->kind == CG_TYPE_ARRAY ||
           t->kind == CG_TYPE_CALLABLE ||
           (t->kind == CG_TYPE_OBJECT && !cg_type_is_value_semantics(t));
}

static bool cg_user_type_is_value_semantics(const struct UserType *t) {
    return cg_user_type_is_tuple(t) || cg_user_type_is_value(t);
}


/* Initialise generated symbols owned by value-type lowering. The aggregate
 * descriptor represents the by-value struct; the box descriptor is used
 * only when a value-type value becomes an object-form spec subject.
 * Serves both tuple and @value type decls. */
static bool cg_init_user_type_value_symbols(UserType *t) {
    Buf slots_name;
    Buf aggregate_default_name;
    Buf aggregate_desc_name;
    Buf box_struct_name;
    Buf box_desc_name;
    Buf box_release_name;

    if (!cg_user_type_is_value_semantics(t)) {
        return true;
    }

    buf_init(&slots_name);
    buf_init(&aggregate_default_name);
    buf_init(&aggregate_desc_name);
    buf_init(&box_struct_name);
    buf_init(&box_desc_name);
    buf_init(&box_release_name);

    buf_append_fmt(&slots_name, "%s__aggregate_slots", t->c_struct_name);
    buf_append_fmt(&aggregate_default_name, "%s__aggregate_default", t->c_struct_name);
    buf_append_fmt(&aggregate_desc_name, "%s__aggregate_desc", t->c_struct_name);
    buf_append_fmt(&box_struct_name, "%s__spec_box", t->c_struct_name);
    buf_append_fmt(&box_desc_name, "%s__spec_box_desc", t->c_struct_name);
    buf_append_fmt(&box_release_name, "%s__spec_box_release_children", t->c_struct_name);

    t->c_aggregate_slots_name = slots_name.data;
    t->c_aggregate_default_name = aggregate_default_name.data;
    t->c_aggregate_desc_name = aggregate_desc_name.data;
    t->c_value_box_struct_name = box_struct_name.data;
    t->c_value_box_desc_name = box_desc_name.data;
    t->c_value_box_release_children_name = box_release_name.data;

    return t->c_aggregate_slots_name != NULL &&
           t->c_aggregate_default_name != NULL &&
           t->c_aggregate_desc_name != NULL &&
           t->c_value_box_struct_name != NULL &&
           t->c_value_box_desc_name != NULL &&
           t->c_value_box_release_children_name != NULL;
}

/* Stable C ABI selected from a generic declaration slot before substituting
 * its generic arguments. Closed instances retain this selection so open and
 * closed code always use one function prototype. */
typedef enum CGCallableABIKind {
    CG_CALLABLE_ABI_DIRECT = 0,
    CG_CALLABLE_ABI_ERASED_POINTER,
    CG_CALLABLE_ABI_ADDRESS
} CGCallableABIKind;

/* Spec registry. Object-form specs lower to by-value fat structs; callable-
 * form specs lower to managed closure pointers plus a constraint-surface
 * witness with a single erased `invoke` slot. */
typedef struct UserSpecMember {
    char   *feng_name;          /* e.g., "greet" */
    char   *c_field_name;       /* sanitised — slot name in the witness struct */
    enum {
        USM_KIND_FIELD = 0,     /* spec field — read-or-borrow/setter slots */
        USM_KIND_METHOD         /* spec method — single function-pointer slot */
    } kind;
    /* For FIELD: the field's declared type. For METHOD: the method return type. */
    CGType  *type;
    /* Stable ABI selected from the generic spec's original declaration slot.
     * FIELD uses this for both getter return and setter value; METHOD uses it
     * for the return slot. Closed and open instances of one generic spec must
     * retain the same classification. */
    CGCallableABIKind value_abi_kind;
    /* FIELD only: true when the spec declared `var` (mutable). `let` and the
     * default both record false; only `var` triggers a setter slot in the
     * witness struct (see cg_emit_user_spec_definition). */
    bool     is_var;
    /* True when the spec declared `static`; static slots omit the implicit
     * `_subject` parameter and are satisfied by type-level (or fit static)
     * implementations rather than instance fields/methods. */
    bool     is_static;
    /* METHOD only: declared parameter types (excluding the implicit subject). */
    CGType **param_types;
    CGCallableABIKind *param_abi_kinds;
    char   **param_names;       /* informational, mirrors signature */
    size_t   param_count;
    const FengTypeMember *member;
    /* INTERSECTION-form only: declarations that Semantic normalized to this
     * same requirement slot. The primary `member` remains the first-seen
     * declaration used to source the merged witness function pointer; aliases
     * let direct calls and method values recover that slot from any equivalent
     * declaration identity without repeating signature selection. The array is
     * compiler-owned; pointed-to members remain AST-owned. */
    const FengTypeMember **member_aliases;
    size_t member_alias_count;
    /* INTERSECTION-form only: C field name in the leaf member-spec witness
     * supplying this merged slot. It remains independent from c_field_name,
     * which may be renamed for a legal overload in the merged witness. */
    char *source_c_field_name;
    /* INTERSECTION-form only: pointer to the flattened member spec decl this
     * slot was cloned from. Used by cg_ensure_witness_instance_for_type to
     * locate the subject's per-member-spec witness when assembling the merged
     * witness constant. NULL for OBJECT/UNION/CALLABLE forms (where slots are
     * either own or inherited from parent specs, satisfied directly by the
     * subject type). The decl is AST-owned and stable across cg->user_specs
     * realloc, so no refresh is needed (unlike UserSpec* which would require
     * refresh tracking). */
    const FengDecl *source_member_decl;
    /* 9.9: for INTERSECTION-form generic instances only, the substituted
     * member type ref (e.g. `Eq<IntBox>` when the intersection is
     * `Comparable<IntBox>` with member `Eq<T>`). Used to locate the correct
     * member-spec generic instance (not the generic context) when assembling
     * the merged witness. NULL for non-generic intersections (where
     * source_member_decl suffices, because the member spec has no type args
     * and cg_find_user_spec_by_decl finds the right UserSpec) and for other
     * forms. Owned by this UserSpecMember (heap-allocated via
     * cg_type_ref_clone); stable across cg->user_specs realloc because it is
     * a heap pointer, not a UserSpec* index. */
    FengTypeRef *source_member_type_ref;
} UserSpecMember;

static bool cg_user_spec_member_compatible(const UserSpecMember *src,
                                           const UserSpecMember *dst);

/* Return whether one instance-field witness slot must preserve the identity
 * of the implementing field's storage. Fixed value-semantics aggregates need
 * this for mutating method receivers; ADDRESS is the stable declaration-side
 * ABI for open generic fields that may close to such a value. Static fields
 * have independent storage semantics and retain their existing getter ABI. */
static bool cg_spec_field_uses_storage_borrow(
    const UserSpecMember *member) {
    return member != NULL &&
           member->kind == USM_KIND_FIELD &&
           !member->is_static &&
           (cg_type_is_value_semantics(member->type) ||
            member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS);
}

typedef struct UserSpec {
    char   *feng_name;                /* e.g., "Named" */
    FengSpecForm form;
    char   *c_value_struct_name;      /* e.g., FengSpecValue__feng__sample__Named */
    char   *c_witness_struct_name;    /* e.g., FengSpecWitness__feng__sample__Named */
    /* Value-model descriptor symbols (see docs/engineering/feng-value-model-delivered.md
     * §3, §7.2). For object-form specs the aggregate has exactly one
     * managed slot — the `subject` pointer at offset 0 of the value
     * struct. The descriptor is emitted unconditionally so per-field
     * flatten / release helpers (§7.2 / §7.4) can refer to it once a spec
     * value appears as an object field or array element. */
    char   *c_aggregate_slots_name;    /* e.g., FengSpecAggSlots__M__S */
    char   *c_aggregate_default_name;  /* e.g., FengSpecAggDefault__M__S */
    char   *c_aggregate_init_fn_name;  /* e.g., FengSpecAggInit__M__S */
    char   *c_aggregate_desc_name;     /* e.g., FengSpecAgg__M__S */
    /* Default-zero machinery (docs/engineering/feng-spec-codegen-delivered.md §6). The
     * hidden subject type is a real managed object emitted purely to
     * back default spec values; the default witness reads / writes its
     * fields and returns per-type defaults from method slots. */
    char   *c_default_subject_struct_name; /* e.g., FengSpecDefault__M__S__Subject */
    char   *c_default_subject_desc_name;   /* e.g., FengSpecDefault__M__S__Subject_desc */
    char   *c_default_subject_new_name;    /* e.g., FengSpecDefault__M__S__new_subject */
    char   *c_default_witness_name;        /* e.g., FengSpecDefaultWitness__M__S */
    char   *c_closure_struct_name;         /* callable-form only */
    char   *c_closure_desc_name;           /* callable-form only */
    char   *c_abi_fn_ptr_typedef_name;     /* callable-form @abi function-pointer surface */
    char   *c_default_callable_noop_name;  /* callable-form noop invoke (default-zero) */
    char   *c_default_callable_new_name;   /* callable-form factory  (default-zero) */
    UserSpecMember *members;
    size_t          member_count;
    /* Direct object-form parents in source declaration order. Indices remain
     * stable when cg->user_specs reallocates and identify exact generic
     * instances such as Parent<int>. */
    size_t         *direct_parent_spec_indices;
    size_t          direct_parent_spec_count;
    bool            members_registered;
    bool            members_registering;
    CGType         *callable_return_type;
    CGCallableABIKind callable_return_abi_kind;
    CGType        **callable_param_types;
    CGCallableABIKind *callable_param_abi_kinds;
    size_t          callable_param_count;
    bool            callable_is_variadic;
    CGType        **union_member_types;
    size_t          union_member_count;
    const FengDecl *decl;
    bool            is_generic_instance;
    const FengDecl *generic_origin_decl;
    FengTypeRef   **generic_type_args;
    size_t          generic_type_arg_count;
    char          **generic_context_type_param_names;
    size_t          generic_context_type_param_count;
    /* Program whose source reference requested this concrete instance.
     * It supplies visibility for substituted consumer-owned type arguments,
     * while owner_program remains the generic spec declaration's program. */
    const FengProgram *instantiation_program;
    /* Owning program — see UserType.owner_program. */
    const FengProgram *owner_program;
    /* Cached physical-layout fact for union-form values. Object,
     * intersection and callable specs have fixed carrier layouts. */
    CGGenericLayoutFact generic_layout_fact;
} UserSpec;

typedef struct GenericSpecDecl {
    const FengDecl    *decl;
    const FengProgram *owner_program;
} GenericSpecDecl;

/* `fit T :: S { ... }` registry (Step 4b-γ). One entry per fit declaration.
 * Codegen treats fit-body methods as if they were ordinary methods on T,
 * but mangles their C symbols with the fit's per-module index so two fits
 * for the same target T cannot collide. The witness emitter (FIT_METHOD
 * source kind) looks up the matching UserMethod by its source `member`
 * pointer to recover the symbol to call. */
typedef struct UserFit {
    const FengDecl *decl;
    const UserType *target;       /* resolved target T (named single-segment) */
    size_t          target_index; /* index into CG.user_types; stable across realloc */
    const UserSpec **specs;       /* resolved spec list from `fit T :: S, ...` */
    size_t         *spec_indices; /* indices into CG.user_specs; stable across realloc */
    size_t          spec_count;
    UserMethod     *methods;      /* fit-body methods, c_name mangled with index */
    size_t          method_count;
    size_t          index;        /* per-program 0-based declaration order */
    char           *c_prefix;     /* stable module/target/visibility/ordinal prefix */
    const FengProgram *owner_program;
} UserFit;

typedef struct BuiltinFit {
    const FengDecl *decl;
    CGType         *target_type;
    FengTypeParam  *target_type_params;
    size_t          target_type_param_count;
    const UserSpec **specs;
    size_t          spec_count;
    UserMethod     *methods;
    size_t          method_count;
    char           *c_prefix;
    const FengProgram *owner_program;
} BuiltinFit;

static char *cg_builtin_fit_fdesc_expr(CG *cg,
                                       const BuiltinFit *bf,
                                       const UserMethod *method,
                                       const CGType *element_type,
                                       const FengToken *blame);

static char *cg_managed_pointer_descriptor_expr(const CGType *t) {
    const char *symbol_name = NULL;

    if (t == NULL) {
        return NULL;
    }
    switch (t->kind) {
        case CG_TYPE_STRING:
            symbol_name = "feng_string_descriptor";
            break;
        case CG_TYPE_ARRAY:
            symbol_name = "feng_array_descriptor";
            break;
        case CG_TYPE_OBJECT:
            if (t->user != NULL && !cg_type_is_value_semantics(t) &&
                t->user->c_desc_name != NULL) {
                symbol_name = t->user->c_desc_name;
            }
            break;
        case CG_TYPE_CALLABLE:
            if (t->user_spec != NULL && t->user_spec->c_closure_desc_name != NULL) {
                symbol_name = t->user_spec->c_closure_desc_name;
            }
            break;
        default:
            break;
    }
    return cg_descriptor_expr_from_symbol(symbol_name);
}


static char *cg_user_type_c_name(const CGType *t) __attribute__((unused));
static char *cg_user_type_c_name(const CGType *t) {
    /* Caller owns the returned malloc'd string. */
    if (t->kind != CG_TYPE_OBJECT || !t->user ||
        t->user->c_struct_name == NULL) {
        return strdup("void *");
    }
    Buf b; buf_init(&b);
    buf_append_fmt(&b, "struct %s *", t->user->c_struct_name);
    return b.data;
}

/* Emit a C type spec for a CGType into a buffer. For OBJECT we emit the full
 * struct pointer form so the generated C does not rely on `void *` casts.
 * For SPEC (Step 4b) we emit `struct FengSpecValue__M__S` (by-value, no
 * pointer star) — fat-spec values live on the stack / in argument slots and
 * are passed by value. */
static void cg_emit_c_type(Buf *b, const CGType *t) {
    if (t && t->kind == CG_TYPE_POINTER) {
        if (t->element == NULL) {
            buf_append_cstr(b, "void *");
            return;
        }
        if (t->element->kind == CG_TYPE_ARRAY) {
            cg_emit_array_data_pointer_c_type(b, t->element);
            return;
        }
        if (t->element->kind == CG_TYPE_POINTER) {
            cg_emit_c_type(b, t->element);
            buf_append_cstr(b, " *");
            return;
        }
        if (t->element->kind == CG_TYPE_STRING) {
            buf_append_cstr(b, "char *");
            return;
        }
        if (t->element->kind == CG_TYPE_OBJECT &&
            t->element->user != NULL &&
            t->element->user->is_abi_type) {
            if (t->element->user->c_abi_layout_name != NULL) {
                buf_append_fmt(b, "struct %s *", t->element->user->c_abi_layout_name);
            } else {
                buf_append_fmt(b, "struct %s *",
                               t->element->user->c_struct_name != NULL
                                   ? t->element->user->c_struct_name : "void");
            }
            return;
        }
        if (t->element->kind == CG_TYPE_CALLABLE && t->element->user_spec != NULL &&
            t->element->user_spec->c_abi_fn_ptr_typedef_name != NULL) {
            buf_append_cstr(b, t->element->user_spec->c_abi_fn_ptr_typedef_name);
            return;
        }
        buf_append_cstr(b, cgtype_to_c(t->element->kind));
        buf_append_cstr(b, " *");
        return;
    }
    CGAggregateFacts aggregate_facts;
    if (t && cg_aggregate_facts(t, &aggregate_facts) && aggregate_facts.value_struct_name) {
        buf_append_fmt(b, "struct %s", aggregate_facts.value_struct_name);
        return;
    }
    if (t && t->kind == CG_TYPE_OBJECT && t->user) {
        if (t->user->c_struct_name != NULL) {
            buf_append_fmt(b, "struct %s *", t->user->c_struct_name);
        } else {
            /* Erased generic-owner self still has a nominal UserType view,
             * but no single closed C struct tag. Its shared ABI is void *. */
            buf_append_cstr(b, "void *");
        }
        return;
    }
    if (t && t->kind == CG_TYPE_CALLABLE && t->user_spec) {
        buf_append_fmt(b, "struct %s *",
                       t->user_spec->c_closure_struct_name != NULL
                           ? t->user_spec->c_closure_struct_name : "void");
        return;
    }
    buf_append_cstr(b, cgtype_to_c(t ? t->kind : CG_TYPE_VOID));
}

/* Emit a callable parameter type using the stable open/closed ABI. */
static void cg_emit_callable_abi_param_type(Buf *out,
                                            const CGType *type,
                                            CGCallableABIKind abi_kind) {
    switch (abi_kind) {
        case CG_CALLABLE_ABI_ERASED_POINTER:
            buf_append_cstr(out, "void *");
            break;
        case CG_CALLABLE_ABI_ADDRESS:
            buf_append_cstr(out, "const void *");
            break;
        case CG_CALLABLE_ABI_DIRECT:
        default:
            cg_emit_c_type(out, type);
            break;
    }
}

/* Adapt one canonical callable ABI parameter back to the exact Feng C type
 * expected by a statically known function or method body. */
static void cg_append_callable_abi_argument_value(Buf *out,
                                                  const CGType *type,
                                                  CGCallableABIKind abi_kind,
                                                  const char *argument_name) {
    if (abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        /* The address points to one value slot. Put const on that slot, not
         * on a managed value's pointee: `T * const *` dereferences to the
         * original managed `T *`, while `const T **` would silently change
         * the Feng value type and make ownership helpers discard const. */
        buf_append_cstr(out, "(*(");
        cg_emit_c_type(out, type);
        buf_append_fmt(out, " const *)%s)", argument_name);
    } else if (abi_kind == CG_CALLABLE_ABI_ERASED_POINTER) {
        buf_append_cstr(out, "((");
        cg_emit_c_type(out, type);
        buf_append_fmt(out, ")%s)", argument_name);
    } else {
        buf_append_cstr(out, argument_name);
    }
}

/* Emit the C return type of a callable invoke entry. Address-form Feng
 * returns are written through a trailing `_out` parameter, while a known
 * managed-reference family keeps its pointer-sized return representation. */
static void cg_emit_callable_abi_return_type(Buf *out,
                                             const CGType *type,
                                             CGCallableABIKind abi_kind) {
    if (abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "void");
    } else if (abi_kind == CG_CALLABLE_ABI_ERASED_POINTER) {
        buf_append_cstr(out, "void *");
    } else {
        cg_emit_c_type(out, type);
    }
}

/* Append the hidden result address required by an address-form callable
 * return after all source-level parameters. */
static void cg_append_callable_abi_out_parameter(
    Buf *out,
    CGCallableABIKind return_abi_kind) {
    if (return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, ", void *_out");
    }
}

/* Emit the exact canonical closure-invoke function-pointer type for a
 * callable spec. This is used when converting the codegen-private erased
 * descriptor slot back to the origin ABI before assigning closure.invoke. */
static void cg_emit_callable_invoke_pointer_type(Buf *out,
                                                 const UserSpec *spec) {
    cg_emit_callable_abi_return_type(out,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_cstr(out, " (*)(void *");
    for (size_t i = 0U; i < spec->callable_param_count; ++i) {
        buf_append_cstr(out, ", ");
        cg_emit_callable_abi_param_type(out,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
    }
    if (spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, ", void *");
    }
    buf_append_cstr(out, ")");
}

/* Adapt an argument received through one callable ABI to another compatible
 * callable ABI without allocating or consulting runtime metadata. */
static void cg_append_callable_abi_bridge_argument(
    Buf *out,
    const CGType *type,
    CGCallableABIKind source_abi_kind,
    CGCallableABIKind destination_abi_kind,
    const char *argument_name) {
    if (destination_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        if (source_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(out, argument_name);
        } else {
            buf_append_fmt(out, "(const void *)&%s", argument_name);
        }
        return;
    }
    if (destination_abi_kind == CG_CALLABLE_ABI_ERASED_POINTER) {
        if (source_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(out, "(void *)(*(");
            cg_emit_c_type(out, type);
            buf_append_fmt(out, " const *)%s)", argument_name);
        } else {
            buf_append_fmt(out, "(void *)%s", argument_name);
        }
        return;
    }
    if (source_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "(*(const ");
        cg_emit_c_type(out, type);
        buf_append_fmt(out, " *)%s)", argument_name);
    } else if (source_abi_kind == CG_CALLABLE_ABI_ERASED_POINTER) {
        buf_append_cstr(out, "((");
        cg_emit_c_type(out, type);
        buf_append_fmt(out, ")%s)", argument_name);
    } else {
        buf_append_cstr(out, argument_name);
    }
}

static const UserType *cg_abi_value_user_type(const CGType *t) {
    return t != NULL && t->kind == CG_TYPE_OBJECT &&
           t->user != NULL && t->user->is_abi_type &&
           t->user->c_abi_layout_name != NULL ? t->user : NULL;
}

static void cg_emit_c_abi_surface_type(Buf *b, const CGType *t) {
    const UserType *abi_user = cg_abi_value_user_type(t);

    if (abi_user != NULL && abi_user->c_abi_layout_name != NULL) {
        buf_append_fmt(b, "struct %s", abi_user->c_abi_layout_name);
        return;
    }

    cg_emit_c_type(b, t);
}

/* Heap-allocated form. Caller frees. */
static char *cg_ctype_dup(const CGType *t) {
    Buf b; buf_init(&b);
    cg_emit_c_type(&b, t);
    return b.data ? b.data : strdup("void");
}

/* ===================== local scope ===================== */

typedef struct Local {
    char     *name;     /* Feng identifier */
    char     *c_name;   /* mangled C identifier, unique within the function */
    CGType   *type;
    bool      is_param; /* parameters are not released by the frame (caller owns) */
    bool      is_unknown_exception;
    /* Whether source-level mutability is known for this local. Compiler-only
     * temporaries leave this false; user bindings, parameters and `self`
     * record their declared mutability explicitly. */
    bool      binding_mutability_known;
    /* True only for a source-level `var` binding whose slot may be rebound.
     * This compile-time fact lets assignment lowering prove when a managed
     * reference identity remains stable without adding ARC operations. */
    bool      binding_is_rebindable;
    /* The C expression names an address that already points at the Feng
     * value's storage. Taking its address again would pass a pointer to the
     * storage pointer instead of a pointer to the value. */
    bool      is_storage_address;
    /* A direct generic parameter value is represented by descriptor-sized
     * erased storage.  The descriptor and size are cached once when the
     * storage is declared; lifecycle dispatch uses those cached names. */
    bool      uses_erased_generic_storage;
    /* True when erased storage owns only aggregate managed slots. Shared
     * callable argument lowering borrows managed-pointer values while still
     * owning an independent copy of value-semantics aggregates. */
    bool      erased_generic_cleanup_aggregate_only;
    char     *erased_generic_descriptor_c_name;
    char     *erased_generic_size_c_name;
    /* A layout-reified by-value aggregate is represented by descriptor-sized
     * address storage rather than by the open generic C placeholder struct.
     * The descriptor/size expressions are cached when the storage is
     * declared and reused by cleanup, so the generated program does not
     * reload the dependency table for the same local. */
    bool      uses_reified_storage;
    char     *reified_descriptor_c_name;
    char     *reified_size_c_name;
    char     *capture_cell_c_name;
    char     *capture_cell_struct_name;
    char     *capture_cell_desc_name;
    /* Descriptor-sized captures use a one-element FengArray as their
     * existing capture-cell allocation so the payload keeps its concrete
     * runtime size without adding a second allocation. */
    bool      capture_cell_uses_dynamic_storage;
} Local;

typedef struct Scope {
    struct Scope *parent;
    Local        *items;
    size_t        count;
    size_t        capacity;
    bool          is_loop;       /* this scope is a loop body root */
    /* If non-NULL, `continue` inside this loop emits `goto <continue_label>;`
     * instead of C `continue;`. Used by the three-clause `for` form so a
     * `continue` jumps to the update step (which lives after the body block,
     * before the next iteration of the C `for(;;)`). The string is owned by
     * the codegen instance (lives in cur_body's identifier pool) and freed
     * by the caller that created the scope. */
    const char   *continue_label;
    /* try_depth observed at the moment this scope was pushed. Used by
     * break/continue to clean active try/catch frames when jumping out of
     * generated try/catch code. */
    int           try_depth_at_entry;
    /* Each scope frame also holds a list of indices into items[] in original
     * insertion order; release-on-exit walks them in reverse. */
} Scope;

static Scope *scope_push(Scope *parent) {
    Scope *s = calloc(1, sizeof *s);
    if (!s) return NULL;
    s->parent = parent;
    s->try_depth_at_entry = parent ? parent->try_depth_at_entry : 0;
    return s;
}

/* Release every heap-owned metadata field of one compiler local record. */
static void local_metadata_free(Local *local) {
    if (local == NULL) {
        return;
    }
    free(local->name);
    free(local->c_name);
    free(local->capture_cell_c_name);
    free(local->capture_cell_struct_name);
    free(local->capture_cell_desc_name);
    free(local->erased_generic_descriptor_c_name);
    free(local->erased_generic_size_c_name);
    free(local->reified_descriptor_c_name);
    free(local->reified_size_c_name);
    cgtype_free(local->type);
    memset(local, 0, sizeof(*local));
}

/* Discard compiler metadata for locals at and after `new_count`. Generated
 * runtime cleanup must already have been emitted for every owning entry. */
static void scope_discard_suffix(Scope *scope, size_t new_count) {
    if (scope == NULL || new_count > scope->count) {
        return;
    }
    for (size_t index = scope->count; index > new_count; --index) {
        local_metadata_free(&scope->items[index - 1U]);
    }
    scope->count = new_count;
}

static void scope_pop_free(Scope *s) {
    if (!s) return;
    for (size_t i = 0; i < s->count; i++) {
        local_metadata_free(&s->items[i]);
    }
    free(s->items);
    free(s);
}

static bool scope_add(Scope *s, const char *name, const char *c_name,
                      CGType *type, bool is_param) {
    if (s->count + 1 > s->capacity) {
        size_t cap = s->capacity ? s->capacity * 2 : 8;
        Local *p = realloc(s->items, cap * sizeof *p);
        if (!p) return false;
        s->items = p;
        s->capacity = cap;
    }
    Local *l = &s->items[s->count++];
    l->name = strdup(name);
    l->c_name = strdup(c_name);
    l->type = type;
    l->is_param = is_param;
    l->is_unknown_exception = false;
    l->binding_mutability_known = false;
    l->binding_is_rebindable = false;
    l->is_storage_address = false;
    l->uses_erased_generic_storage = false;
    l->erased_generic_cleanup_aggregate_only = false;
    l->erased_generic_descriptor_c_name = NULL;
    l->erased_generic_size_c_name = NULL;
    l->uses_reified_storage = false;
    l->reified_descriptor_c_name = NULL;
    l->reified_size_c_name = NULL;
    l->capture_cell_c_name = NULL;
    l->capture_cell_struct_name = NULL;
    l->capture_cell_desc_name = NULL;
    l->capture_cell_uses_dynamic_storage = false;
    return l->name && l->c_name;
}

/* Record source-level mutability for the most recently registered local.
 * FENG_MUTABILITY_DEFAULT is the immutable default used by parameters. */
static bool scope_mark_last_binding_mutability(Scope *s,
                                               FengMutability mutability) {
    if (s == NULL || s->count == 0U) {
        return false;
    }
    s->items[s->count - 1U].binding_mutability_known = true;
    s->items[s->count - 1U].binding_is_rebindable =
        mutability == FENG_MUTABILITY_VAR;
    return true;
}

/* Copy already-resolved binding mutability onto the most recent alias.
 * Unknown compiler-only sources remain unknown and therefore conservative. */
static bool scope_copy_last_binding_mutability(Scope *s,
                                               const Local *source) {
    if (s == NULL || s->count == 0U || source == NULL) {
        return false;
    }
    s->items[s->count - 1U].binding_mutability_known =
        source->binding_mutability_known;
    s->items[s->count - 1U].binding_is_rebindable =
        source->binding_is_rebindable;
    return true;
}

/* Record that the C expression of the most recently registered local already
 * denotes its Feng value storage. This is compile-time representation
 * metadata and emits no runtime operation. */
static bool scope_mark_last_storage_address(Scope *s) {
    if (s == NULL || s->count == 0U) {
        return false;
    }
    s->items[s->count - 1U].is_storage_address = true;
    return true;
}

/* Record descriptor-sized storage for one direct generic parameter local.
 * This metadata is compile-time-only; generated code uses the cached C
 * locals supplied by the declaration site. */
static bool scope_mark_last_erased_generic_storage(
    Scope *s,
    const char *descriptor_c_name,
    const char *size_c_name) {
    Local *local;

    if (s == NULL || s->count == 0U || descriptor_c_name == NULL ||
        size_c_name == NULL) {
        return false;
    }
    local = &s->items[s->count - 1U];
    local->is_storage_address = true;
    local->uses_erased_generic_storage = true;
    local->erased_generic_descriptor_c_name = strdup(descriptor_c_name);
    local->erased_generic_size_c_name = strdup(size_c_name);
    return local->erased_generic_descriptor_c_name != NULL &&
           local->erased_generic_size_c_name != NULL;
}

/* Record erased argument storage whose managed-pointer representation is
 * borrowed but whose aggregate representation owns a by-value copy. */
static bool scope_mark_last_erased_generic_argument_storage(
    Scope *s,
    const char *descriptor_c_name,
    const char *size_c_name) {
    if (!scope_mark_last_erased_generic_storage(
            s, descriptor_c_name, size_c_name)) {
        return false;
    }
    s->items[s->count - 1U].erased_generic_cleanup_aggregate_only = true;
    return true;
}

/* Record the address-storage representation of the most recently registered
 * local. The caller retains ownership of the supplied strings. */
static bool scope_mark_last_reified_storage(Scope *s,
                                            const char *descriptor_c_name,
                                            const char *size_c_name) {
    Local *local;

    if (s == NULL || s->count == 0U || descriptor_c_name == NULL) {
        return false;
    }
    local = &s->items[s->count - 1U];
    local->is_storage_address = true;
    local->uses_reified_storage = true;
    local->reified_descriptor_c_name = strdup(descriptor_c_name);
    local->reified_size_c_name = size_c_name != NULL ? strdup(size_c_name) : NULL;
    return local->reified_descriptor_c_name != NULL &&
           (size_c_name == NULL || local->reified_size_c_name != NULL);
}

/* docs/engineering/feng-defer-dev.md §5.6.2: thin wrapper that registers a defer entry in
 * the scope's locals list. `defer_fn_name` is the generated static function
 * name; `defer_closure_name` is the generated stack-allocated closure struct
 * variable name (may be NULL when the defer body captures nothing); the type
 * is the CG_TYPE_DEFER sentinel. Re-uses scope_add so Scope structure,
 * scope_pop_free, and scope_lookup are unchanged. */
static bool scope_add_defer(Scope *s,
                            const char *defer_fn_name,
                            const char *defer_closure_name,
                            CGType *defer_type) {
    return scope_add(s, defer_fn_name,
                     defer_closure_name != NULL ? defer_closure_name : "",
                     defer_type, false);
}

static bool scope_mark_unknown_exception(Scope *s, const char *name, size_t len) {
    for (Scope *cur = s; cur; cur = cur->parent) {
        for (size_t i = cur->count; i > 0; i--) {
            Local *l = &cur->items[i - 1];
            if (strlen(l->name) == len && memcmp(l->name, name, len) == 0) {
                l->is_unknown_exception = true;
                return true;
            }
        }
    }
    return false;
}

static const Local *scope_lookup(const Scope *s, const char *name, size_t len) {
    for (const Scope *cur = s; cur; cur = cur->parent) {
        for (size_t i = cur->count; i > 0; i--) {
            const Local *l = &cur->items[i - 1];
            if (strlen(l->name) == len && memcmp(l->name, name, len) == 0) {
                return l;
            }
        }
    }
    return NULL;
}

/* ===================== codegen context ===================== */

/* Registered code-generation metadata for one exact extern declaration. */
typedef struct ExternFn {
    char    *feng_name;        /* Feng declaration name */
    char    *generated_c_name; /* Module- and signature-qualified C identifier */
    char    *native_symbol;    /* Imported native symbol; defaults to `feng_name` */
    CGType **param_types;
    size_t   param_count;
    CGType  *return_type;
    FengAnnotationKind calling_convention;
    bool     uses_runtime_contract;
    size_t   fixed_param_count; /* >0: first N params are fixed, rest are C variadic */
    const FengDecl *decl;
    const FengProgram *owner_program;
} ExternFn;

typedef struct FreeFn {
    char     *feng_name;
    char     *c_name;
    char     *c_abi_name;
    CGType  **param_types;
    char    **param_names;
    size_t    param_count;   /* total params, including the variadic T[] param */
    CGType   *return_type;
    bool      is_abi;
    bool      is_variadic;   /* true when the last param is a variadic T... */
    const FengDecl *decl;
    const FengProgram *owner_program;
} FreeFn;

static bool cg_free_fn_has_abi_wrapper(const FreeFn *fn) {
    return fn != NULL && fn->is_abi && fn->c_abi_name != NULL;
}

typedef struct ModuleBinding {
    char    *feng_name;
    char    *c_name;          /* e.g., _feng_g_examples_user — globally unique */
    char    *c_ensure_init_name; /* e.g., _feng_ensure_g__examples__user */
    char    *c_inited_name;   /* e.g., _feng_g__examples__user__inited */
    CGType  *type;            /* heap-owned */
    bool     is_var;          /* false = let, true = var */
    bool     exports_public_surface;
    const FengBinding *binding;
    const FengProgram *owner_program;
} ModuleBinding;

/* ---- Generic function registry (G6) ----
 * One entry per generic function declaration (type_param_count > 0).  These
 * are NOT registered as FreeFns; they are emitted with a separate C
 * signature that uses void* params + FengGenericParamDescriptor descriptors
 * and a void-return + _out parameter convention. */
typedef struct GenericFn {
    char   *feng_name;          /* Feng identifier, e.g. "identity" */
    char   *c_name;             /* Mangled C symbol, e.g. "feng__mod__identity" */
    size_t  type_param_count;
    char  **type_param_names;   /* ["T", "U", ...] — heap-owned strings */
    const FengDecl    *decl;
    const FengProgram *owner_program;
} GenericFn;

typedef struct GenericTypeDecl {
    const FengDecl    *decl;
    const FengProgram *owner_program;
} GenericTypeDecl;

typedef enum CGNamedGenericTargetKind {
    CG_NAMED_GENERIC_TARGET_NONE = 0,
    CG_NAMED_GENERIC_TARGET_TYPE,
    CG_NAMED_GENERIC_TARGET_SPEC
} CGNamedGenericTargetKind;

/* Declaration identity for a named generic reference. The owner program is
 * the declaration context, not the later generic-instantiation call site. */
typedef struct CGNamedGenericTarget {
    CGNamedGenericTargetKind kind;
    const FengDecl *decl;
    const FengProgram *owner_program;
    const GenericTypeDecl *type;
    const GenericSpecDecl *spec;
} CGNamedGenericTarget;

/* One compile-time node in the statically emitted closed callable descriptor
 * graph. `emitting` breaks recursive cycles after the shell declaration has
 * been published; runtime never constructs or looks up these nodes. */
typedef struct CGClosedCallableDescriptorNode {
    char *key;
    char *c_name;
    bool emitting;
    bool emitted;
} CGClosedCallableDescriptorNode;

/* One compile-time node for a statically closed builtin array descriptor.
 * The generated program only takes the address of the emitted read-only
 * object; it never constructs or looks up a closed descriptor at runtime. */
typedef struct CGClosedArrayDescriptorNode {
    char *key;
    char *c_name;
} CGClosedArrayDescriptorNode;

/* One compile-time node for a closed generic-parameter descriptor. The key
 * contains the complete initializer so equivalent call sites reuse one
 * read-only object without giving its address language-level identity. */
typedef struct CGClosedGenericParamDescriptorNode {
    char *key;
    char *c_name;
} CGClosedGenericParamDescriptorNode;

/* Generated support shared by ordinary fixed-layout binding and reified
 * method-value formation. All strings are owned by the CG registry. */
typedef struct CGCallableMethodValueSupport {
    const struct UserSpec *spec;
    const struct UserType *owner;
    const struct UserMethod *method;
    char *c_target_fn;
    char *c_bind_fn;
    char *c_adapter_fn;
    char *c_closure_struct;
    char *c_closure_desc;
} CGCallableMethodValueSupport;

/* Generated support for one receiver-free static method value. The closed
 * function descriptor fixes the owner, optional fit, method arguments and
 * callable target; generated runtime code only borrows the immortal closure. */
typedef struct CGCallableStaticMethodValueSupport {
    const struct UserSpec *spec;
    const FengTypeMember *member;
    const FengDecl *fit_decl;
    char *descriptor_c_name;
    char *c_adapter_fn;
    char *c_var;
} CGCallableStaticMethodValueSupport;

/* Generated support for one object/intersection spec method value. The
 * extended closure keeps the ordinary callable prefix, plus the receiver's
 * immutable witness pointer; `_self` retains the captured subject. */
typedef struct CGCallableSpecMethodValueSupport {
    const struct UserSpec *target_spec;
    const struct UserSpec *receiver_spec;
    const FengTypeMember *member;
    char *c_bind_fn;
    char *c_adapter_fn;
    char *c_closure_struct;
    char *c_closure_desc;
} CGCallableSpecMethodValueSupport;

/* Generated support for one closed constrained-generic receiver method value.
 * The closed descriptor identity fixes both the concrete receiver layout and
 * the constraint witness used by the adapter. */
typedef struct CGCallableGenericSpecMethodValueSupport {
    const struct UserSpec *target_spec;
    const struct UserSpec *receiver_spec;
    const FengTypeMember *member;
    char *descriptor_c_name;
    char *c_adapter_fn;
    char *c_closure_struct;
    char *c_closure_desc;
    bool has_inline_receiver;
} CGCallableGenericSpecMethodValueSupport;

/* Compile-time-only binding plan for a method-value adapter that enters a
 * generic provider shared body directly. Every expression is fully closed by
 * the consumer; generated code performs no runtime selection or lookup. */
typedef struct CGReifiedCallableMethodTarget {
    const char *shared_c_name;
    const char *owner_descriptor_expr;
    const char *function_descriptor_expr;
    const char *const *method_descriptor_exprs;
    size_t method_descriptor_count;
    const bool *param_uses_address;
} CGReifiedCallableMethodTarget;

/* Optional static initializer for the callable-value facet of one closed
 * FengFunctionDescriptor. Every string is a complete generated C expression
 * borrowed only for the duration of descriptor emission. */
typedef struct CGClosedCallableValueInit {
    const char *surface_key;
    const char *static_value_expr;
    const char *closure_desc_expr;
    const char *invoke_expr;
    const char *aggregate_capture_desc_expr;
    const char *aggregate_capture_offset_expr;
} CGClosedCallableValueInit;

/* Compile-time source of reified dependency slots for one shared body. The
 * generated program performs no source test: codegen selects a fixed `_td`
 * or `_desc` expression for every slot access. */
typedef enum CGReifiedDependencySource {
    CG_REIFIED_DEP_SOURCE_TYPE,
    CG_REIFIED_DEP_SOURCE_FUNCTION
} CGReifiedDependencySource;

/* Select the field-initialization semantics for a synthetic or declared
 * generic constructor-shaped shared body. */
typedef enum CGGenericConstructorInitMode {
    CG_GENERIC_CONSTRUCTOR_INIT_DECLARED,
    CG_GENERIC_CONSTRUCTOR_INIT_DEFAULT_ZERO
} CGGenericConstructorInitMode;

typedef struct CG {
    /* Output sections concatenated at the end. */
    Buf headers;        /* #include / extern decls / forward decls */
    Buf enum_defs;      /* enum defs; isolated so lazy emission stays file-scoped */
    Buf type_defs;      /* struct/spec defs (Phase 1A iter 2) */
    Buf statics;        /* static caches: literal slots */
    Buf fn_protos;      /* forward declarations for free fn / methods */
    Buf fn_defs;        /* function bodies */
    Buf eh_defs;        /* LSDA region declarations and registration */
    Buf witness_defs;   /* spec witness thunks + tables (Step 4b);
                           kept separate so emission from inside an
                           in-progress function body cannot splice into
                           that function's text. Concatenated after
                           fn_defs in cg_finalize. */

    /* Per-function emission state. */
    Buf      *cur_body; /* current function body buffer */
    Scope    *cur_scope;
    int       tmp_counter;
    int       local_counter;
    int       label_counter;
    size_t    lambda_counter;
    size_t    capture_cell_counter;
    size_t    defer_counter;     /* per-codegen-instance monotonic id for
                                  * __defer_<module>_<id> static functions
                                  * and their closure struct types */
    int       loop_depth;
    bool      in_loop_with_break;
    CGType   *cur_return_type;
    bool      cur_fn_is_main;
    bool      cur_function_has_frame_marker;

    /* Module info. */
    char     *module_mangle;     /* e.g., "feng__examples" */
    char     *module_dot_name;   /* e.g., "feng.examples" */

    /* Symbol tables. */
    ExternFn *externs;
    size_t    extern_count;
    size_t    extern_capacity;
    FreeFn   *free_fns;
    size_t    free_fn_count;
    size_t    free_fn_capacity;
    UserType *user_types;
    size_t    user_type_count;
    size_t    user_type_capacity;
    /* Spec registry. Sibling of user_types. Each entry holds either the
     * object-form fat-spec layout or the callable-form closure metadata,
     * plus the shared constraint-surface witness metadata. */
    struct UserSpec *user_specs;
    size_t           user_spec_count;
    size_t           user_spec_capacity;
    struct {
        const struct UserSpec *spec;
        const FengDecl *function_decl;
        /* Non-NULL only for a reified generic function-value surface. */
        char *descriptor_c_name;
        char *c_adapter_fn;
        char *c_var;
    } *callable_fn_values;
    size_t callable_fn_value_count;
    size_t callable_fn_value_capacity;
    CGCallableStaticMethodValueSupport *callable_static_method_values;
    size_t callable_static_method_value_count;
    size_t callable_static_method_value_capacity;
    CGCallableMethodValueSupport *callable_method_values;
    size_t callable_method_value_count;
    size_t callable_method_value_capacity;
    CGCallableSpecMethodValueSupport *callable_spec_method_values;
    size_t callable_spec_method_value_count;
    size_t callable_spec_method_value_capacity;
    CGCallableGenericSpecMethodValueSupport *callable_generic_spec_method_values;
    size_t callable_generic_spec_method_value_count;
    size_t callable_generic_spec_method_value_capacity;
    /* Fit registry (Step 4b-γ). Sibling of user_specs. Each entry models
     * one `fit T :: S { ... }` so witness emission for FIT_METHOD source
     * can look up the C symbol of the fit-body method to call. */
    struct UserFit  *user_fits;
    size_t           user_fit_count;
    size_t           user_fit_capacity;
    struct BuiltinFit *builtin_fits;
    size_t             builtin_fit_count;
    size_t             builtin_fit_capacity;
    /* Witness-table emission cache (Step 4b): one entry per (type, spec) pair
     * for which a witness instance has been emitted into fn_protos/fn_defs.
     * Avoids duplicate emission across multiple coercion sites. */
    struct {
        const struct UserType *t;
        const struct UserSpec *s;
        char *c_var;     /* e.g., "Witness__feng__sample__User__as__feng__sample__Named" */
    } *witness_tables;
    size_t witness_table_count;
    size_t witness_table_capacity;
    struct {
        const struct UserSpec *src;
        const struct UserSpec *dst;
        char *c_var;
    } *spec_slot_witness_tables;
    size_t spec_slot_witness_table_count;
    size_t spec_slot_witness_table_capacity;
    size_t spec_slot_witness_counter;
    struct {
        const struct UserType *type;
        const struct UserSpec *spec;
        char *c_var;
    } *value_box_witness_tables;
    size_t value_box_witness_table_count;
    size_t value_box_witness_table_capacity;
    /* Enum/builtin/array witness cache. The semantic subject key is stable
     * for the analysis lifetime; storage distinguishes borrowed scalar
     * subjects from boxed owners. */
    struct {
        FengSemanticSubjectKey subject_key;
        FengSpecObjectSubjectStorageKind storage;
        const struct UserSpec *spec;
        char *c_var;
    } *subject_witness_tables;
    size_t subject_witness_table_count;
    size_t subject_witness_table_capacity;
    struct {
        const struct UserSpec *root;
        const struct UserSpec *target;
        char *c_var;
    } *default_parent_witnesses;
    size_t default_parent_witness_count;
    size_t default_parent_witness_capacity;
    size_t subject_witness_counter;
    ModuleBinding *module_bindings;
    size_t         module_binding_count;
    size_t         module_binding_capacity;
    /* Imported open generic instances can independently expose the same
     * exported shared method. Prototypes are compile-time declarations and
     * are deduplicated by their final C symbol. */
    char          **imported_generic_shared_proto_names;
    size_t          imported_generic_shared_proto_count;
    size_t          imported_generic_shared_proto_capacity;

    /* try/catch state: how many active try frames are open in the current
     * function. Used to refuse break / continue across them in 1A. */
    int       try_depth;
    int       active_exception_frame_count;
    int       active_caught_unwind_count;
    size_t    eh_region_count;
    size_t    eh_label_counter;

    /* String literal cache: each unique literal (by content) gets one static. */
    struct {
        char  *content;   /* raw bytes (may include NULs not supported in 1A) */
        size_t length;
        char  *c_var;     /* generated static var name */
    } *string_literals;
    size_t string_literal_count;
    size_t string_literal_capacity;

    /* Borrowed from feng_codegen_emit_program: lets descriptor emission look
     * up Phase 1B cyclicity markers without re-running SCC. */
    const FengSemanticAnalysis *analysis;
    const FengCodegenOptions *options;
    FengCodegenMapingInfo debug_info;

    /* Currently active source program for diagnostics and per-module
     * symbol resolution. Set/reset at the boundaries of every per-program
     * pass and around per-(type|spec|fit) operations dispatched from a
     * global walk. cg_fail uses it to populate FengCodegenError.path so
     * multi-file projects report the *real* file the failing token came
     * from rather than falling back to whichever source happens to be
     * first in the input list. cg_find_user_type / cg_find_user_spec use
     * it to filter candidate symbols by per-program visibility so two
     * unrelated `User` types in different modules cannot collide. */
    const FengProgram *cur_program;
    const char *current_frame_backend_symbol;
    const char *debug_line_source_path;
    char *debug_line_logical_uri;
    unsigned int last_emitted_line_directive;
    FengToken current_stmt_anchor_token;
    bool current_stmt_anchor_active;

    /* Error state. */
    FengCodegenError *error;
    bool failed;

    /* ---- Generic codegen state (G6) ---- */
    /* Registry: generic function declarations. */
    GenericFn *generic_fns;
    size_t     generic_fn_count;
    size_t     generic_fn_capacity;
    /* Registry: open generic type declarations (concrete instances are
     * registered into user_types[] once their type arguments are known). */
    GenericTypeDecl *generic_type_decls;
    size_t           generic_type_decl_count;
    size_t           generic_type_decl_capacity;
    /* Registry: open generic spec declarations (concrete instances are
     * registered into user_specs[] once their type arguments are known). */
    GenericSpecDecl *generic_spec_decls;
    size_t           generic_spec_decl_count;
    size_t           generic_spec_decl_capacity;
    /* Per-function emission state when inside a generic function body.
     * `in_generic_fn` is the gate; the parallel arrays are borrowed from the
     * GenericFn being emitted and must not be freed by this block. */
    bool         in_generic_fn;
    bool         generic_return_uses_out;
    /* Callable invoke bodies use the same `_out` value-transfer protocol
     * without changing generic name/type resolution for the lambda body. */
    bool         callable_return_uses_out;
    size_t       generic_fn_type_param_count;
    char       **generic_fn_type_param_names;   /* borrowed — do NOT free */
    size_t       ambient_type_param_count;
    char       **ambient_type_param_names;      /* borrowed — do NOT free */
    const struct UserSpec **generic_fn_type_param_constraints; /* borrowed */
    /* Concrete type-arg substitution scope: when emitting field initializers
     * for a concrete generic instance (e.g. Holder<i32>), the origin decl's
     * type parameters (e.g. T) must be substituted with the instance's
     * concrete type_args (e.g. i32) so that nested constructor calls in
     * field initializers (e.g. `Inner<T>()` → `Inner<i32>()`) resolve to
     * the concrete instance rather than the open generic instance.
     * `concrete_subst_param_count` == 0 means no active substitution. */
    size_t       concrete_subst_param_count;
    const FengTypeParam *concrete_subst_params;  /* borrowed — origin decl's type_params */
    FengTypeRef *const *concrete_subst_type_args; /* borrowed — instance's generic_type_args */
    size_t       concrete_subst_type_arg_count;
    /* C descriptor argument names for each type param ("_T", "_U", …).
     * Heap-owned; freed when in_generic_fn is cleared. */
    const char **generic_fn_type_param_descs;
    /* C identifier for the current shared callable's closed invocation
     * descriptor. Lambdas copy this static descriptor pointer into their
     * environment when their invoke body needs the same reified slots. */
    const char  *generic_function_descriptor_c_name;
    bool         in_generic_type_method;
    const FengDecl *generic_type_method_decl;
    const char  *generic_type_method_field_offsets_name;
    /* §2.6.6 前置：共享体内创建依赖泛型的托管对象时，用于查找
     * reified_type_deps 索引。按 cg_reifiable_sort_key 排序。
     * rtd_via_desc 为 true 时生成 _desc->reified_type_deps[i]（BuiltinFit），
     * 为 false 时生成 _td->reified_type_deps[i]（泛型类型方法）。 */
    char       **generic_type_method_rtd_descs;
    size_t       generic_type_method_rtd_count;
    bool         generic_type_method_rtd_via_desc;
    /* §2.6.1-§2.6.4：共享体内操作依赖泛型的聚合类型时，用于查找
     * reified_agg_deps 索引。按 cg_reifiable_sort_key 排序。
     * rad_via_desc 为 true 时生成 _desc->reified_agg_deps[i]，
     * 为 false 时生成 _td->reified_agg_deps[i]。 */
    char       **generic_type_method_rad_descs;
    size_t       generic_type_method_rad_count;
    bool         generic_type_method_rad_via_desc;
    char       **generic_callable_dep_keys;
    size_t       generic_callable_dep_count;
    /* True for function/member dependency sets carried by `_desc`; false
     * for owner dependency sets carried by `_td`. */
    bool         generic_callable_dep_via_desc;
    CGClosedCallableDescriptorNode *closed_callable_descriptor_nodes;
    size_t       closed_callable_descriptor_node_count;
    size_t       closed_callable_descriptor_node_capacity;
    CGClosedArrayDescriptorNode *closed_array_descriptor_nodes;
    size_t       closed_array_descriptor_node_count;
    size_t       closed_array_descriptor_node_capacity;
    CGClosedGenericParamDescriptorNode *closed_generic_param_descriptor_nodes;
    size_t       closed_generic_param_descriptor_node_count;
    size_t       closed_generic_param_descriptor_node_capacity;
    char       **captured_binding_names;
    size_t       captured_binding_name_count;
    bool         current_callable_captures_self;
    const struct UserFit *current_user_fit;

    /* On-demand imported-enum emission tracking (pointer-identity dedup). */
    const FengDecl **emitted_enum_decls;
    size_t           emitted_enum_decl_count;
    size_t           emitted_enum_decl_capacity;

    /* Expression-level union narrowing for non-identifier match targets
     * (e.g. self.member). Entries are pushed before branch resolution and
     * restored via a save-point after it. */
    struct CGExprNarrowing {
        const FengExpr *target_expr;
        char           *c_expr;
        CGType         *type;
    }               *expr_narrowings;
    size_t           expr_narrowing_count;
    size_t           expr_narrowing_capacity;
} CG;

/* Return true when a shared generic body must obtain the aggregate
 * descriptor from its reified dependency table. Value-semantics types need
 * it for layout; object specs need the concrete instance's lifecycle and
 * default-value authority even though their fat-value layout is fixed. */
static bool cg_value_needs_reified_layout(const CG *cg, const CGType *type) {
    bool has_open_generic_identity;

    if (cg == NULL || type == NULL ||
        (!cg->in_generic_type_method && !cg->in_generic_fn)) {
        return false;
    }
    has_open_generic_identity =
        (cg_type_is_value_semantics(type) && type->user != NULL &&
         type->user->generic_context_type_param_count > 0U) ||
        (type->kind == CG_TYPE_SPEC && type->user_spec != NULL &&
         type->user_spec->generic_context_type_param_count > 0U);
    return has_open_generic_identity;
}

/* Return true when an open generic reference instance must locate every
 * field through its closed descriptor. A field that does not itself mention
 * a type parameter may still move when an earlier field has reified layout. */
static bool cg_reference_needs_reified_field_layout(const CG *cg,
                                                    const CGType *type) {
    return cg != NULL && type != NULL &&
           (cg->in_generic_type_method || cg->in_generic_fn) &&
           type->kind == CG_TYPE_OBJECT && type->user != NULL &&
           !cg_type_is_value_semantics(type) &&
           type->user->generic_context_type_param_count > 0U;
}

static bool cg_type_layout_depends_on_generic_parameter(const CGType *type);

/* Compute and cache one value type's physical-layout fact. This function
 * inspects only direct fields; nested value fields answer through their own
 * cached fact. Managed references and fixed fat values are classified by the
 * field-type query and are never expanded here. */
static CGGenericLayoutFact cg_user_type_generic_layout_fact(UserType *type) {
    if (type == NULL || !cg_user_type_is_value_semantics(type)) {
        return CG_GENERIC_LAYOUT_FIXED;
    }
    if (type->generic_layout_fact == CG_GENERIC_LAYOUT_FIXED ||
        type->generic_layout_fact == CG_GENERIC_LAYOUT_REIFIED) {
        return type->generic_layout_fact;
    }
    if (type->generic_layout_fact == CG_GENERIC_LAYOUT_COMPUTING) {
        /* By-value cycles are rejected before codegen. Treat malformed input
         * conservatively without attempting an unbounded traversal. */
        return CG_GENERIC_LAYOUT_REIFIED;
    }

    type->generic_layout_fact = CG_GENERIC_LAYOUT_COMPUTING;
    for (size_t index = 0U; index < type->field_count; ++index) {
        if (cg_type_layout_depends_on_generic_parameter(
                type->fields[index].type)) {
            type->generic_layout_fact = CG_GENERIC_LAYOUT_REIFIED;
            return type->generic_layout_fact;
        }
    }
    type->generic_layout_fact = CG_GENERIC_LAYOUT_FIXED;
    return type->generic_layout_fact;
}

/* Compute and cache one union-form spec's physical-layout fact. A union's
 * payload must accommodate every member, so one descriptor-sized member
 * makes the complete union descriptor-sized as well. */
static CGGenericLayoutFact cg_user_spec_generic_layout_fact(UserSpec *spec) {
    if (spec == NULL || spec->form != FENG_SPEC_FORM_UNION) {
        return CG_GENERIC_LAYOUT_FIXED;
    }
    if (spec->generic_layout_fact == CG_GENERIC_LAYOUT_FIXED ||
        spec->generic_layout_fact == CG_GENERIC_LAYOUT_REIFIED) {
        return spec->generic_layout_fact;
    }
    if (spec->generic_layout_fact == CG_GENERIC_LAYOUT_COMPUTING) {
        /* Illegal by-value cycles are rejected before codegen. Preserve a
         * bounded, conservative answer for malformed input. */
        return CG_GENERIC_LAYOUT_REIFIED;
    }

    spec->generic_layout_fact = CG_GENERIC_LAYOUT_COMPUTING;
    for (size_t index = 0U; index < spec->union_member_count; ++index) {
        if (cg_type_layout_depends_on_generic_parameter(
                spec->union_member_types[index])) {
            spec->generic_layout_fact = CG_GENERIC_LAYOUT_REIFIED;
            return spec->generic_layout_fact;
        }
    }
    spec->generic_layout_fact = CG_GENERIC_LAYOUT_FIXED;
    return spec->generic_layout_fact;
}

/* Query the physical-layout fact supplied by a field type. */
static bool cg_type_layout_depends_on_generic_parameter(const CGType *type) {
    if (type == NULL) {
        return false;
    }
    if (type->kind == CG_TYPE_GENERIC_PARAM) {
        return true;
    }
    if (cg_type_is_value_semantics(type) && type->user != NULL) {
        return cg_user_type_generic_layout_fact((UserType *)type->user) ==
               CG_GENERIC_LAYOUT_REIFIED;
    }
    if (type->kind == CG_TYPE_SPEC && type->user_spec != NULL &&
        type->user_spec->form == FENG_SPEC_FORM_UNION) {
        return cg_user_spec_generic_layout_fact(
                   (UserSpec *)type->user_spec) == CG_GENERIC_LAYOUT_REIFIED;
    }
    return false;
}

/* Shared generic bodies receive erased type parameters and every value-
 * semantics type that still references the active generic context by address.
 * Dynamic layouts need the descriptor-sized storage protocol; fixed layouts
 * still need one nominally neutral C surface because their open and closed
 * instance structs have distinct tags. Closed values retain their direct C
 * ABI. */
static bool cg_shared_generic_param_uses_address(const CGType *type) {
    return type != NULL &&
           (type->kind == CG_TYPE_GENERIC_PARAM ||
            (cg_type_is_value_semantics(type) &&
             type->user != NULL &&
             type->user->generic_context_type_param_count > 0U) ||
            (cgtype_is_aggregate(type) &&
             cg_type_layout_depends_on_generic_parameter(type)));
}

/* Return true only for values whose physical local storage must be obtained
 * from a reified aggregate descriptor. Object-form specs also need a reified
 * descriptor for lifecycle authority, but their {subject,witness} layout is
 * fixed and therefore remains an ordinary C value. */
static bool cg_type_uses_reified_storage(const CG *cg, const CGType *type) {
    return cg_value_needs_reified_layout(cg, type) &&
           cgtype_is_aggregate(type) &&
           cg_type_layout_depends_on_generic_parameter(type);
}

/* Descriptor external visibility: requires both module and type to be PUBLIC. */
static bool cg_user_type_descriptor_is_externally_visible(const CG *cg, const UserType *t) {
    if (cg == NULL || t == NULL) {
        return false;
    }
    /* For generic instances, check the origin decl's visibility and owner program. */
    const FengDecl *decl = t->is_generic_instance ? t->generic_origin_decl : t->decl;
    const FengProgram *owner_prog = t->owner_program != NULL ? t->owner_program : cg->cur_program;
    if (decl == NULL || owner_prog == NULL) {
        return false;
    }
    return owner_prog->module_visibility == FENG_VISIBILITY_PUBLIC &&
           decl->visibility == FENG_VISIBILITY_PUBLIC;
}

/* Spec descriptor external visibility: requires both module and spec to be PUBLIC. */
static bool cg_user_spec_descriptor_is_externally_visible(const CG *cg, const UserSpec *spec) {
    if (cg == NULL || spec == NULL) {
        return false;
    }
    /* For generic instances, check the origin decl's visibility and owner program. */
    const FengDecl *decl = spec->is_generic_instance ? spec->generic_origin_decl : spec->decl;
    const FengProgram *owner_prog = spec->owner_program != NULL ? spec->owner_program : cg->cur_program;
    if (decl == NULL || owner_prog == NULL) {
        return false;
    }
    return owner_prog->module_visibility == FENG_VISIBILITY_PUBLIC &&
           decl->visibility == FENG_VISIBILITY_PUBLIC;
}

