static bool cg_debug_add_variable_record_cstr_cgtype(CG *cg,
                                                     const char *backend_name,
                                                     const char *display_name,
                                                     const char *read_expr,
                                                     const CGType *type,
                                                     FengCodegenMapingVariableKind kind,
                                                     FengToken blame) {
    char *display_type = cg_debug_dup_display_type_from_cgtype(cg, type, blame);
    bool ok;

    if (display_type == NULL) {
        return cg_fail(cg, blame, "CE0001", "codegen: missing debug display type");
    }
    ok = cg_debug_add_variable_record_cstr_typed(cg,
                                                 backend_name,
                                                 display_name,
                                                 read_expr,
                                                 display_type,
                                                 kind,
                                                 blame);

    free(display_type);
    return ok;
}

static bool cg_debug_add_variable_record_slice_cgtype(CG *cg,
                                                      const char *backend_name,
                                                      FengSlice display_name,
                                                      const char *read_expr,
                                                      const CGType *type,
                                                      FengCodegenMapingVariableKind kind,
                                                      FengToken blame) {
    char *display_type = cg_debug_dup_display_type_from_cgtype(cg, type, blame);
    bool ok;

    if (display_type == NULL) {
        return cg_fail(cg, blame, "CE0001", "codegen: missing debug display type");
    }
    ok = cg_debug_add_variable_record_slice_typed(cg,
                                                  backend_name,
                                                  display_name,
                                                  read_expr,
                                                  display_type,
                                                  kind,
                                                  blame);

    free(display_type);
    return ok;
}

static bool cg_debug_add_user_type_field_records(CG *cg,
                                                 const UserType *type,
                                                 FengToken blame) {
    CGType parent_type;
    char *parent_display_type;

    if (!cg_debug_enabled(cg) || type == NULL || type->field_count == 0U) {
        return true;
    }
    memset(&parent_type, 0, sizeof(parent_type));
    parent_type.kind = CG_TYPE_OBJECT;
    parent_type.user = type;
    parent_display_type = cg_debug_dup_display_type_from_cgtype_from_program(
        cg,
        &parent_type,
        type->owner_program,
        blame);
    if (parent_display_type == NULL) {
        return true;
    }
    for (size_t index = 0U; index < type->field_count; ++index) {
        const UserField *field = &type->fields[index];
        char *field_display_type;
        Buf read_expr;

        if (field->feng_name == NULL || field->c_name == NULL || field->type == NULL) {
            continue;
        }
        field_display_type = cg_debug_dup_display_type_from_cgtype_from_program(
            cg,
            field->type,
            type->owner_program,
            blame);
        if (field_display_type == NULL) {
            continue;
        }
        buf_init(&read_expr);
        buf_append_fmt(&read_expr, "->%s", field->c_name);
        if (read_expr.data == NULL ||
            !feng_codegen_maping_info_add_variable_with_parent_display_type(
                &cg->debug_info,
                NULL,
                NULL,
                field->feng_name,
                read_expr.data,
                field_display_type,
                parent_display_type,
                FENG_CODEGEN_MAPING_VARIABLE_FIELD)) {
            free(read_expr.data);
            free(field_display_type);
            free(parent_display_type);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory recording debug field");
        }
        free(read_expr.data);
        free(field_display_type);
    }
    free(parent_display_type);
    return true;
}

static bool cg_debug_add_current_frame_module_binding_records(CG *cg,
                                                              FengToken blame) {
    size_t index;

    if (!cg_debug_enabled(cg) ||
        cg->current_frame_backend_symbol == NULL ||
        cg->cur_program == NULL) {
        return true;
    }

    for (index = 0U; index < cg->module_binding_count; ++index) {
        const ModuleBinding *binding = cg->module_bindings + index;
        FengToken binding_token = binding->binding != NULL ? binding->binding->token : blame;

        if (binding->owner_program != cg->cur_program ||
            binding->c_name == NULL ||
            binding->feng_name == NULL ||
            binding->type == NULL) {
            continue;
        }
        if (!cg_debug_add_variable_record_cstr_cgtype(cg,
                                                      binding->c_name,
                                                      binding->feng_name,
                                                      NULL,
                                                      binding->type,
                                                      FENG_CODEGEN_MAPING_VARIABLE_BINDING,
                                                      binding_token)) {
            return false;
        }
    }
    return true;
}

/* Resolves the current source file to its logical PKG_NAME:// URI. */
static bool cg_debug_prepare_line_source(CG *cg) {
    FengCodegenMapingResolvedSource resolved = {0};

    if (cg == NULL ||
        cg->options == NULL ||
        !cg->options->emit_line_directives ||
        cg->cur_program == NULL ||
        cg->cur_program->path == NULL) {
        return true;
    }
    if (cg->debug_line_source_path != NULL &&
        strcmp(cg->debug_line_source_path, cg->cur_program->path) == 0) {
        return true;
    }

    free(cg->debug_line_logical_uri);
    cg->debug_line_logical_uri = NULL;
    cg->debug_line_source_path = cg->cur_program->path;
    cg->last_emitted_line_directive = 0U;
    if (!feng_codegen_maping_resolve_source(cg->options->debug_source_mappings,
                                   cg->options->debug_source_mapping_count,
                                   cg->cur_program->path,
                                   &resolved)) {
        cg->debug_line_source_path = NULL;
        return cg_fail(cg,
                       cg->cur_program->module_token,
                       "CE0002", "codegen: missing debug source mapping for '%s'",
                       cg->cur_program->path);
    }

    cg->debug_line_logical_uri = resolved.logical_uri;
    resolved.logical_uri = NULL;
    feng_codegen_maping_resolved_source_dispose(&resolved);
    return true;
}

/* Emits one logical-source `#line` directive into the current function body. */
static bool cg_emit_line_directive(CG *cg, FengToken token) {
    if (cg == NULL ||
        cg->options == NULL ||
        !cg->options->emit_line_directives ||
        cg->cur_body == NULL ||
        token.line == 0U) {
        return true;
    }
    if (!cg_debug_prepare_line_source(cg) || cg->debug_line_logical_uri == NULL) {
        return false;
    }
    if (cg->last_emitted_line_directive == token.line) {
        return true;
    }
    buf_append_fmt(cg->cur_body,
                   "#line %u \"%s\"\n",
                   token.line,
                   cg->debug_line_logical_uri);
    cg->last_emitted_line_directive = token.line;
    return true;
}

static bool cg_emit_line_directive_force(CG *cg, FengToken token) {
    if (cg == NULL ||
        cg->options == NULL ||
        !cg->options->emit_line_directives ||
        cg->cur_body == NULL ||
        token.line == 0U) {
        return true;
    }
    if (!cg_debug_prepare_line_source(cg) || cg->debug_line_logical_uri == NULL) {
        return false;
    }
    buf_append_fmt(cg->cur_body,
                   "#line %u \"%s\"\n",
                   token.line,
                   cg->debug_line_logical_uri);
    cg->last_emitted_line_directive = token.line;
    return true;
}

static void cg_emit_current_stmt_line_directive_force(CG *cg) {
    if (cg == NULL || !cg->current_stmt_anchor_active) {
        return;
    }
    (void)cg_emit_line_directive_force(cg, cg->current_stmt_anchor_token);
}

/* ===================== mangling ===================== */

static bool cg_build_generic_param_constraints(CG *cg,
                                               const FengTypeParam *type_params,
                                               size_t type_param_count,
                                               FengToken blame,
                                               const UserSpec ***out_constraints) {
    *out_constraints = NULL;
    if (type_param_count == 0) return true;

    const UserSpec **constraints = calloc(type_param_count, sizeof *constraints);
    if (!constraints) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    size_t *constraint_indices = calloc(type_param_count, sizeof *constraint_indices);
    if (!constraint_indices) {
        free(constraints);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0; i < type_param_count; ++i) {
        constraint_indices[i] = (size_t)-1;
    }

    char **type_param_names = calloc(type_param_count, sizeof *type_param_names);
    if (type_param_names == NULL) {
        free(constraint_indices);
        free(constraints);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0; i < type_param_count; ++i) {
        type_param_names[i] = strndup(type_params[i].name.data,
                                      type_params[i].name.length);
        if (type_param_names[i] == NULL) {
            cg_free_cstr_array(type_param_names, i);
            free(constraint_indices);
            free(constraints);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }

    bool saved_in_generic_fn = cg->in_generic_fn;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;

    cg->in_generic_fn = true;
    cg->generic_fn_type_param_count = type_param_count;
    cg->generic_fn_type_param_names = type_param_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;

    for (size_t i = 0; i < type_param_count; ++i) {
        if (!type_params[i].constraint) continue;

        CGType *constraint_type = NULL;
        if (!cg_resolve_type(cg, type_params[i].constraint,
                             &type_params[i].token, &constraint_type)) {
            cg->in_generic_fn = saved_in_generic_fn;
            cg->generic_fn_type_param_count = saved_tp_count;
            cg->generic_fn_type_param_names = saved_tp_names;
            cg->generic_fn_type_param_constraints = saved_tp_constraints;
            cg->generic_fn_type_param_descs = saved_tp_descs;
            cg_free_cstr_array(type_param_names, type_param_count);
            free(constraint_indices);
            free(constraints);
            return false;
        }
        if (!constraint_type ||
            (constraint_type->kind != CG_TYPE_SPEC &&
             constraint_type->kind != CG_TYPE_CALLABLE) ||
            constraint_type->user_spec == NULL) {
            cgtype_free(constraint_type);
            cg->in_generic_fn = saved_in_generic_fn;
            cg->generic_fn_type_param_count = saved_tp_count;
            cg->generic_fn_type_param_names = saved_tp_names;
            cg->generic_fn_type_param_constraints = saved_tp_constraints;
            cg->generic_fn_type_param_descs = saved_tp_descs;
            cg_free_cstr_array(type_param_names, type_param_count);
            free(constraint_indices);
            free(constraints);
            return cg_fail(cg, type_params[i].token,
                "CE0003", "codegen: generic constraint for '%.*s' must be a spec supported by codegen",
                (int)type_params[i].name.length,
                type_params[i].name.data);
        }

        if (!cg_user_spec_index(cg, constraint_type->user_spec,
                                &constraint_indices[i])) {
            cgtype_free(constraint_type);
            cg->in_generic_fn = saved_in_generic_fn;
            cg->generic_fn_type_param_count = saved_tp_count;
            cg->generic_fn_type_param_names = saved_tp_names;
            cg->generic_fn_type_param_constraints = saved_tp_constraints;
            cg->generic_fn_type_param_descs = saved_tp_descs;
            cg_free_cstr_array(type_param_names, type_param_count);
            free(constraint_indices);
            free(constraints);
            return cg_fail(cg, type_params[i].token,
                           "CE0004", "codegen: internal: generic constraint spec was not registered");
        }
        cgtype_free(constraint_type);
    }

    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_cstr_array(type_param_names, type_param_count);

    for (size_t i = 0; i < type_param_count; ++i) {
        constraints[i] = cg_user_spec_by_index(cg, constraint_indices[i]);
    }
    free(constraint_indices);
    *out_constraints = constraints;
    return true;
}

static const UserSpec *cg_generic_param_constraint_spec(const CG *cg, size_t index) {
    if (!cg->generic_fn_type_param_constraints ||
        index >= cg->generic_fn_type_param_count) {
        return NULL;
    }
    return cg->generic_fn_type_param_constraints[index];
}

static const char *cg_generic_param_desc_name(const CG *cg, size_t index) {
    if (!cg->generic_fn_type_param_descs ||
        index >= cg->generic_fn_type_param_count) {
        return NULL;
    }
    return cg->generic_fn_type_param_descs[index];
}

static const char *cg_generic_param_name(const CG *cg, size_t index) {
    if (cg->generic_fn_type_param_names != NULL &&
        index < cg->generic_fn_type_param_count &&
        cg->generic_fn_type_param_names[index] != NULL) {
        return cg->generic_fn_type_param_names[index];
    }
    if (cg->ambient_type_param_names != NULL &&
        index < cg->ambient_type_param_count &&
        cg->ambient_type_param_names[index] != NULL) {
        return cg->ambient_type_param_names[index];
    }
    return NULL;
}

static const char *cg_generic_param_desc_name_for_name(const CG *cg,
                                                       const char *type_param_name) {
    if (type_param_name == NULL ||
        cg->generic_fn_type_param_names == NULL ||
        cg->generic_fn_type_param_descs == NULL) {
        return NULL;
    }
    for (size_t i = 0U; i < cg->generic_fn_type_param_count; ++i) {
        const char *name = cg->generic_fn_type_param_names[i];
        const char *desc = cg->generic_fn_type_param_descs[i];

        if (name != NULL && desc != NULL && strcmp(name, type_param_name) == 0) {
            return desc;
        }
    }
    return NULL;
}

static bool cg_append_user_type_context_descriptor_args(CG *cg,
                                                        Buf *out,
                                                        const UserType *owner_type,
                                                        FengToken blame) {
    if (owner_type == NULL || owner_type->generic_context_type_param_count == 0U) {
        return true;
    }

    /* @value type 的构造函数/方法接收 FengAggregateDescriptor（非 FengTypeDescriptor），
     * 从 reified_agg_deps 查找。 */
    if (cg_user_type_is_value(owner_type)) {
        for (size_t ri = 0U; ri < cg->generic_type_method_rad_count; ri++) {
            if (cg->generic_type_method_rad_descs[ri] != NULL &&
                strcmp(owner_type->c_aggregate_desc_name,
                       cg->generic_type_method_rad_descs[ri]) == 0) {
                const char *src = cg->generic_type_method_rad_via_desc
                                      ? "_desc" : "_td";
                buf_append_fmt(out,
                    ", (const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]",
                    src, ri);
                return true;
            }
        }
        return cg_fail(cg, blame,
                       "CE0005", "codegen: no reified_agg_dep found for @value type method call");
    }

    for (size_t ri = 0U; ri < cg->generic_type_method_rtd_count; ri++) {
        if (cg->generic_type_method_rtd_descs[ri] != NULL &&
            strcmp(owner_type->c_desc_name,
                   cg->generic_type_method_rtd_descs[ri]) == 0) {
            const char *src = cg->generic_type_method_rtd_via_desc ? "_desc" : "_td";
            buf_append_fmt(out, ", %s->reified_type_deps[%zu]", src, ri);
            return true;
        }
    }
    return cg_fail(cg, blame,
                   "CE0005", "codegen: no reified_type_dep found for generic type method call");
}

/* Return the RTD expression for a managed open-instance descriptor previously
 * indexed by the active shared-body context. Caller frees. */
static char *cg_rtd_expr_for_managed_descriptor(CG *cg,
                                                 const char *descriptor_name,
                                                 FengToken blame) {
    if (cg == NULL || descriptor_name == NULL) {
        cg_fail(cg, blame,
                "CE0007", "codegen: missing managed descriptor for generic dependency");
        return NULL;
    }
    for (size_t ri = 0U; ri < cg->generic_type_method_rtd_count; ++ri) {
        if (cg->generic_type_method_rtd_descs[ri] != NULL &&
            strcmp(descriptor_name,
                   cg->generic_type_method_rtd_descs[ri]) == 0) {
            const char *src = cg->generic_type_method_rtd_via_desc
                                  ? "_desc" : "_td";
            Buf b;

            buf_init(&b);
            buf_append_fmt(&b, "%s->reified_type_deps[%zu]", src, ri);
            return b.data;
        }
    }
    cg_fail(cg, blame,
            "CE0007", "codegen: no reified_type_dep found for generic managed dependency '%s'",
            descriptor_name);
    return NULL;
}

/* Return the RTD expression string (e.g. "_td->reified_type_deps[2]") for a
 * generic UserType inside a shared body.  Caller frees.  Returns NULL and
 * emits an error on failure.
 * @value types use reified_agg_deps (FengAggregateDescriptor) instead of
 * reified_type_deps (FengTypeDescriptor). */
static char *cg_rtd_expr_for_type(CG *cg,
                                  const UserType *ut,
                                  FengToken blame) {
    if (ut == NULL || ut->generic_context_type_param_count == 0U) {
        cg_fail(cg, blame,
                "CE0006", "codegen: cg_rtd_expr_for_type called on non-generic type");
        return NULL;
    }

    /* The open instance of the current generic owner is represented by the
     * shared body's `_td` argument itself; it is not (and must not be)
     * duplicated in the owner's derived dependency slots. */
    if (cg->generic_type_method_decl != NULL &&
        ut->generic_origin_decl == cg->generic_type_method_decl) {
        return strdup("_td");
    }

    if (cg_user_type_is_value(ut)) {
        for (size_t ri = 0U; ri < cg->generic_type_method_rad_count; ri++) {
            if (cg->generic_type_method_rad_descs[ri] != NULL &&
                strcmp(ut->c_aggregate_desc_name,
                       cg->generic_type_method_rad_descs[ri]) == 0) {
                const char *src = cg->generic_type_method_rad_via_desc
                                      ? "_desc" : "_td";
                Buf b; buf_init(&b);
                buf_append_fmt(&b,
                    "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]",
                    src, ri);
                return b.data;
            }
        }
        cg_fail(cg, blame,
                "CE0007", "codegen: no reified_agg_dep found for @value cross-type call");
        return NULL;
    }

    return cg_rtd_expr_for_managed_descriptor(cg, ut->c_desc_name, blame);
}

static char *cg_generic_witness_subject_expr(const char *desc_name,
                                             const char *slot_expr) {
    Buf b; buf_init(&b);
    buf_append_fmt(&b,
        "((%s->kind == FENG_VALUE_MANAGED_POINTER) ? *(void *const *)(%s) : (void *)(%s))",
        desc_name, slot_expr, slot_expr);
    return b.data;
}

/* Replace any non-alphanumeric/underscore byte in `src` with '_' to keep C
 * identifiers valid. Caller frees. */
static char *cg_sanitize(const char *src, size_t len) {
    char *out = malloc(len + 1);
    if (!out) return NULL;
    for (size_t i = 0; i < len; i++) {
        unsigned char c = (unsigned char)src[i];
        out[i] = (isalnum(c) || c == '_') ? (char)c : '_';
    }
    out[len] = '\0';
    return out;
}

static char *cg_module_mangle(const FengSlice *segments, size_t count) {
    Buf b; buf_init(&b);
    for (size_t i = 0; i < count; i++) {
        if (i) buf_append_cstr(&b, "__");
        char *seg = cg_sanitize(segments[i].data, segments[i].length);
        if (!seg) { buf_free(&b); return NULL; }
        buf_append_cstr(&b, seg);
        free(seg);
    }
    return b.data ? b.data : strdup("");
}

static char *cg_module_dot(const FengSlice *segments, size_t count) {
    Buf b; buf_init(&b);
    for (size_t i = 0; i < count; i++) {
        if (i) buf_append_cstr(&b, ".");
        buf_append(&b, segments[i].data, segments[i].length);
    }
    return b.data ? b.data : strdup("");
}

static char *cg_fn_mangle(const char *module_mangle, const FengSlice *name) {
    Buf b; buf_init(&b);
    buf_append_cstr(&b, "feng__");
    buf_append_cstr(&b, module_mangle);
    buf_append_cstr(&b, "__");
    char *n = cg_sanitize(name->data, name->length);
    if (!n) { buf_free(&b); return NULL; }
    buf_append_cstr(&b, n);
    free(n);
    return b.data;
}

/* Encode one CGType into a compact suffix fragment used for overload-aware
 * symbol mangling. The encoding is reversible-by-collision-class only — its
 * single requirement is that two CGTypes that differ in any way produce
 * different fragments. We re-use the runtime-stable c_struct_name /
 * c_value_struct_name for user-defined types so a future ABI rename of those
 * symbols also updates every overload signature consistently. */
static bool cg_encode_type_short(const CGType *t, Buf *out) {
    if (!t) { buf_append_cstr(out, "void"); return true; }
    switch (t->kind) {
        case CG_TYPE_VOID:   buf_append_cstr(out, "void");   return true;
        case CG_TYPE_BOOL:   buf_append_cstr(out, "b");      return true;
        case CG_TYPE_I8:     buf_append_cstr(out, "i8");     return true;
        case CG_TYPE_I16:    buf_append_cstr(out, "i16");    return true;
        case CG_TYPE_I32:    buf_append_cstr(out, "i32");    return true;
        case CG_TYPE_I64:    buf_append_cstr(out, "i64");    return true;
        case CG_TYPE_U8:     buf_append_cstr(out, "u8");     return true;
        case CG_TYPE_U16:    buf_append_cstr(out, "u16");    return true;
        case CG_TYPE_U32:    buf_append_cstr(out, "u32");    return true;
        case CG_TYPE_U64:    buf_append_cstr(out, "u64");    return true;
        case CG_TYPE_F32:    buf_append_cstr(out, "f32");    return true;
        case CG_TYPE_F64:    buf_append_cstr(out, "f64");    return true;
        case CG_TYPE_POINTER:
            buf_append_cstr(out, "P_");
            return cg_encode_type_short(t->element, out);
        case CG_TYPE_STRING: buf_append_cstr(out, "s");      return true;
        case CG_TYPE_OBJECT:
            if (!t->user) { buf_append_cstr(out, "O_unknown"); return true; }
            buf_append_cstr(out, "O_");
            buf_append_cstr(out, t->user->c_struct_name);
            return true;
        case CG_TYPE_SPEC:
            if (!t->user_spec || t->user_spec->c_value_struct_name == NULL) { buf_append_cstr(out, "S_unknown"); return true; }
            buf_append_cstr(out, "S_");
            buf_append_cstr(out, t->user_spec->c_value_struct_name);
            return true;
        case CG_TYPE_CALLABLE:
            if (!t->user_spec || t->user_spec->c_closure_struct_name == NULL) { buf_append_cstr(out, "C_unknown"); return true; }
            buf_append_cstr(out, "C_");
            buf_append_cstr(out, t->user_spec->c_closure_struct_name);
            return true;
        case CG_TYPE_ARRAY:
            buf_append_cstr(out, t->array_element_writable ? "AW_" : "A_");
            return cg_encode_type_short(t->element, out);
        default:
            buf_append_cstr(out, "X");
            return true;
    }
}

/* Build the "__from__<param-types>" suffix that disambiguates overloads.
 * docs/specifications/feng-function.md §5 / docs/specifications/feng-type.md §5 require that overloads
 * differ by parameter signature, so encoding only the parameter types is
 * sufficient (return type is not part of the overload key). The suffix is
 * applied unconditionally — even single, unambiguous declarations gain it —
 * so symbol shape stays predictable and deterministic for every callable.
 * No-arg functions encode as `__from__void`.
 *
 * When is_generic is true, the suffix is prefixed with "_G" (yielding
 * "_G__from__...") to distinguish a generic callable's shared-body symbol
 * from a non-generic overload that happens to share the same parameter
 * types (e.g. parse(json: string) vs parse<T>(json: string)).  In Feng,
 * generic arity participates in overload resolution, so these are distinct
 * callables; C however cannot distinguish them without an extra marker.
 *
 * Returns a malloc'd string; caller frees. */
static char *cg_build_param_suffix(CGType *const *param_types, size_t count,
                                   bool is_variadic, bool is_generic) {
    Buf b; buf_init(&b);
    if (is_generic) {
        buf_append_cstr(&b, "_G__from__");
    } else {
        buf_append_cstr(&b, "__from__");
    }
    if (count == 0) {
        buf_append_cstr(&b, "void");
    } else {
        for (size_t i = 0; i < count; i++) {
            if (i) buf_append_cstr(&b, "__");
            /* Variadic last parameter: prefix with "V" to distinguish
             * func f(x: T...) from func f(x: T[]) in the mangled name. */
            if (is_variadic && i == count - 1U) {
                buf_append_cstr(&b, "V");
            }
            if (!cg_encode_type_short(param_types[i], &b)) {
                buf_free(&b);
                return NULL;
            }
        }
    }
    return b.data ? b.data : strdup(is_generic ? "_G__from__void" : "__from__void");
}

/* Append the param-type suffix to an existing c_name buffer. Frees the old
 * c_name and returns the new heap-owned string. */
static char *cg_append_param_suffix(char *c_name, CGType *const *param_types,
                                    size_t count, bool is_variadic,
                                    bool is_generic) {
    char *suffix = cg_build_param_suffix(param_types, count, is_variadic, is_generic);
    if (!suffix) { free(c_name); return NULL; }
    Buf b; buf_init(&b);
    buf_append_cstr(&b, c_name);
    buf_append_cstr(&b, suffix);
    free(c_name);
    free(suffix);
    return b.data;
}

static char *cg_local_cname(CG *cg, const char *feng_name, size_t len) {
    char *base = cg_sanitize(feng_name, len);
    if (!base) return NULL;
    Buf b; buf_init(&b);
    buf_append_fmt(&b, "_l_%s_%d", base, cg->local_counter++);
    free(base);
    return b.data;
}

static char *cg_fresh_temp(CG *cg, const char *prefix) {
    Buf b; buf_init(&b);
    buf_append_fmt(&b, "%s%d", prefix, cg->tmp_counter++);
    return b.data;
}

/* Add one real binding name to a compiler-side name set. Destructuring empty
 * positions carry an empty slice and deliberately create no binding. */
static bool cg_capture_name_list_add(char ***items,
                                     size_t *count,
                                     size_t *capacity,
                                     FengSlice name) {
    if (name.length == 0U) {
        return true;
    }
    if (name.data == NULL) {
        return false;
    }
    for (size_t i = 0; i < *count; ++i) {
        if (strlen((*items)[i]) == name.length &&
            memcmp((*items)[i], name.data, name.length) == 0) {
            return true;
        }
    }
    if (*count + 1 > *capacity) {
        size_t next = *capacity ? *capacity * 2 : 8;
        char **grown = realloc(*items, next * sizeof **items);
        if (grown == NULL) {
            return false;
        }
        *items = grown;
        *capacity = next;
    }
    (*items)[*count] = strndup(name.data, name.length);
    if ((*items)[*count] == NULL) {
        return false;
    }
    *count += 1;
    return true;
}

static bool cg_collect_capture_requirements_in_expr(const FengExpr *expr,
                                                    char ***out_names,
                                                    size_t *out_count,
                                                    size_t *out_capacity,
                                                    bool *out_captures_self);

static bool cg_collect_capture_requirements_in_block_inner(const FengBlock *block,
                                                           char ***out_names,
                                                           size_t *out_count,
                                                           size_t *out_capacity,
                                                           bool *out_captures_self);

static bool cg_collect_capture_requirements_in_stmt(const FengStmt *stmt,
                                                    char ***out_names,
                                                    size_t *out_count,
                                                    size_t *out_capacity,
                                                    bool *out_captures_self) {
    if (stmt == NULL) return true;
    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return cg_collect_capture_requirements_in_block_inner(
                stmt->as.block, out_names, out_count, out_capacity, out_captures_self);
        case FENG_STMT_BINDING:
            if (!cg_collect_capture_requirements_in_expr(stmt->as.binding.initializer,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         out_captures_self)) {
                return false;
            }
            return true;
        case FENG_STMT_ASSIGN:
            return cg_collect_capture_requirements_in_expr(stmt->as.assign.target,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_expr(stmt->as.assign.value,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_STMT_EXPR:
        case FENG_STMT_TRY:
            return cg_collect_capture_requirements_in_expr(stmt->as.expr,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_STMT_IF:
            for (size_t i = 0; i < stmt->as.if_stmt.clause_count; ++i) {
                const FengIfClause *clause = &stmt->as.if_stmt.clauses[i];
                if (!cg_collect_capture_requirements_in_expr(clause->condition,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self) ||
                    !cg_collect_capture_requirements_in_block_inner(clause->block,
                                                                    out_names,
                                                                    out_count,
                                                                    out_capacity,
                                                                    out_captures_self)) {
                    return false;
                }
            }
            return cg_collect_capture_requirements_in_block_inner(stmt->as.if_stmt.else_block,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity,
                                                                  out_captures_self);
        case FENG_STMT_MATCH:
            if (!cg_collect_capture_requirements_in_expr(stmt->as.match_stmt.target,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         out_captures_self)) {
                return false;
            }
            for (size_t i = 0; i < stmt->as.match_stmt.branch_count; ++i) {
                const FengMatchBranch *branch = &stmt->as.match_stmt.branches[i];
                for (size_t j = 0; j < branch->label_count; ++j) {
                    const FengMatchLabel *label = &branch->labels[j];
                    if (!cg_collect_capture_requirements_in_expr(label->value,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity,
                                                                 out_captures_self) ||
                        !cg_collect_capture_requirements_in_expr(label->range_low,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity,
                                                                 out_captures_self) ||
                        !cg_collect_capture_requirements_in_expr(label->range_high,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity,
                                                                 out_captures_self)) {
                        return false;
                    }
                }
                if (!cg_collect_capture_requirements_in_block_inner(branch->body,
                                                                    out_names,
                                                                    out_count,
                                                                    out_capacity,
                                                                    out_captures_self)) {
                    return false;
                }
            }
            return cg_collect_capture_requirements_in_block_inner(stmt->as.match_stmt.else_block,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity,
                                                                  out_captures_self);
        case FENG_STMT_WHILE:
            return cg_collect_capture_requirements_in_expr(stmt->as.while_stmt.condition,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_block_inner(stmt->as.while_stmt.body,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity,
                                                                  out_captures_self);
        case FENG_STMT_FOR:
            if (stmt->as.for_stmt.is_for_in) {
                return cg_collect_capture_requirements_in_expr(stmt->as.for_stmt.iter_expr,
                                                               out_names,
                                                               out_count,
                                                               out_capacity,
                                                               out_captures_self) &&
                       cg_collect_capture_requirements_in_expr(stmt->as.for_stmt.iter_binding.initializer,
                                                               out_names,
                                                               out_count,
                                                               out_capacity,
                                                               out_captures_self) &&
                       cg_collect_capture_requirements_in_block_inner(stmt->as.for_stmt.body,
                                                                      out_names,
                                                                      out_count,
                                                                      out_capacity,
                                                                      out_captures_self);
            }
            return cg_collect_capture_requirements_in_stmt(stmt->as.for_stmt.init,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_expr(stmt->as.for_stmt.condition,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_stmt(stmt->as.for_stmt.update,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_block_inner(stmt->as.for_stmt.body,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity,
                                                                  out_captures_self);
        case FENG_STMT_RETURN:
            return cg_collect_capture_requirements_in_expr(stmt->as.return_value,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_STMT_THROW:
            return cg_collect_capture_requirements_in_expr(stmt->as.throw_value,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_STMT_BREAK:
        case FENG_STMT_CONTINUE:
            return true;
        case FENG_STMT_DEFER:
            /* defer 块内的语句对绑定/字段的引用会被此处递归分析，
             * 视为 lambda 体内对外的捕获需求（与 if/while 块体一致）。 */
            return cg_collect_capture_requirements_in_block_inner(stmt->as.defer_block,
                                                                   out_names,
                                                                   out_count,
                                                                   out_capacity,
                                                                   out_captures_self);
    }
    return true;
}

static bool cg_collect_capture_requirements_in_block_inner(const FengBlock *block,
                                                           char ***out_names,
                                                           size_t *out_count,
                                                           size_t *out_capacity,
                                                           bool *out_captures_self) {
    if (block == NULL) return true;
    for (size_t i = 0; i < block->statement_count; ++i) {
        if (!cg_collect_capture_requirements_in_stmt(block->statements[i],
                                                     out_names,
                                                     out_count,
                                                     out_capacity,
                                                     out_captures_self)) {
            return false;
        }
    }
    return true;
}

static bool cg_collect_capture_requirements_in_expr(const FengExpr *expr,
                                                    char ***out_names,
                                                    size_t *out_count,
                                                    size_t *out_capacity,
                                                    bool *out_captures_self) {
    if (expr == NULL) return true;
    switch (expr->kind) {
        case FENG_EXPR_ARRAY_LITERAL:
            for (size_t i = 0; i < expr->as.array_literal.count; ++i) {
                if (!cg_collect_capture_requirements_in_expr(expr->as.array_literal.items[i],
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_TUPLE_LITERAL:
            for (size_t i = 0; i < expr->as.tuple_literal.count; ++i) {
                if (!cg_collect_capture_requirements_in_expr(expr->as.tuple_literal.items[i],
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_OBJECT_LITERAL:
            if (!cg_collect_capture_requirements_in_expr(expr->as.object_literal.target,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         out_captures_self)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.object_literal.field_count; ++i) {
                if (!cg_collect_capture_requirements_in_expr(expr->as.object_literal.fields[i].value,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_GENERIC_TARGET:
            return cg_collect_capture_requirements_in_expr(expr->as.generic_target.target,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_EXPR_CALL:
            if (!cg_collect_capture_requirements_in_expr(expr->as.call.callee,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         out_captures_self)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.call.arg_count; ++i) {
                if (!cg_collect_capture_requirements_in_expr(expr->as.call.args[i],
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_MEMBER:
            return cg_collect_capture_requirements_in_expr(expr->as.member.object,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_EXPR_INDEX:
            return cg_collect_capture_requirements_in_expr(expr->as.index.object,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_expr(expr->as.index.index,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_EXPR_UNARY:
            return cg_collect_capture_requirements_in_expr(expr->as.unary.operand,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_EXPR_BINARY:
            return cg_collect_capture_requirements_in_expr(expr->as.binary.left,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_expr(expr->as.binary.right,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_EXPR_LAMBDA:
            for (size_t i = 0; i < expr->as.lambda.capture_count; ++i) {
                if (expr->as.lambda.captures[i].kind != FENG_LAMBDA_CAPTURE_LOCAL) {
                    continue;
                }
                if (!cg_capture_name_list_add(out_names,
                                              out_count,
                                              out_capacity,
                                              expr->as.lambda.captures[i].name)) {
                    return false;
                }
            }
            if (expr->as.lambda.captures_self) {
                *out_captures_self = true;
            }
            return true;
        case FENG_EXPR_CAST:
            return cg_collect_capture_requirements_in_expr(expr->as.cast.value,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_EXPR_IF:
            return cg_collect_capture_requirements_in_expr(expr->as.if_expr.condition,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self) &&
                   cg_collect_capture_requirements_in_block_inner(expr->as.if_expr.then_block,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity,
                                                                  out_captures_self) &&
                   cg_collect_capture_requirements_in_block_inner(expr->as.if_expr.else_block,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity,
                                                                  out_captures_self);
        case FENG_EXPR_MATCH:
            if (!cg_collect_capture_requirements_in_expr(expr->as.match_expr.target,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         out_captures_self)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.match_expr.branch_count; ++i) {
                const FengMatchBranch *branch = &expr->as.match_expr.branches[i];
                for (size_t j = 0; j < branch->label_count; ++j) {
                    const FengMatchLabel *label = &branch->labels[j];
                    if (!cg_collect_capture_requirements_in_expr(label->value,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity,
                                                                 out_captures_self) ||
                        !cg_collect_capture_requirements_in_expr(label->range_low,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity,
                                                                 out_captures_self) ||
                        !cg_collect_capture_requirements_in_expr(label->range_high,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity,
                                                                 out_captures_self)) {
                        return false;
                    }
                }
                if (!cg_collect_capture_requirements_in_block_inner(branch->body,
                                                                    out_names,
                                                                    out_count,
                                                                    out_capacity,
                                                                    out_captures_self)) {
                    return false;
                }
            }
            return cg_collect_capture_requirements_in_block_inner(expr->as.match_expr.else_block,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity,
                                                                  out_captures_self);
        case FENG_EXPR_TRY:
            if (!cg_collect_capture_requirements_in_expr(expr->as.try_expr.body,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         out_captures_self)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.try_expr.clause_count; ++i) {
                if (!cg_collect_capture_requirements_in_block_inner(expr->as.try_expr.clauses[i].body,
                                                                    out_names,
                                                                    out_count,
                                                                    out_capacity,
                                                                    out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_ARRAY_NEW:
            return cg_collect_capture_requirements_in_expr(expr->as.array_new.size,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           out_captures_self);
        case FENG_EXPR_MATCH_OP:
            if (!cg_collect_capture_requirements_in_expr(expr->as.match_op.target,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         out_captures_self)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.match_op.label_count; ++i) {
                const FengMatchLabel *label = &expr->as.match_op.labels[i];
                if (!cg_collect_capture_requirements_in_expr(label->value,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self) ||
                    !cg_collect_capture_requirements_in_expr(label->range_low,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self) ||
                    !cg_collect_capture_requirements_in_expr(label->range_high,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_IDENTIFIER:
        case FENG_EXPR_SELF:
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
            return true;
    }
    return true;
}

static bool cg_current_callable_captures_name(const CG *cg,
                                              const char *name,
                                              size_t len) {
    if (cg == NULL || name == NULL) return false;
    for (size_t i = 0; i < cg->captured_binding_name_count; ++i) {
        if (strlen(cg->captured_binding_names[i]) == len &&
            memcmp(cg->captured_binding_names[i], name, len) == 0) {
            return true;
        }
    }
    return false;
}

static bool cg_compute_capture_requirements_in_block(const FengBlock *block,
                                                     char ***out_names,
                                                     size_t *out_count,
                                                     bool *out_captures_self) {
    size_t capacity = 0U;

    *out_names = NULL;
    *out_count = 0U;
    *out_captures_self = false;
    if (!cg_collect_capture_requirements_in_block_inner(block,
                                                        out_names,
                                                        out_count,
                                                        &capacity,
                                                        out_captures_self)) {
        if (*out_names != NULL) {
            for (size_t i = 0; i < *out_count; ++i) free((*out_names)[i]);
            free(*out_names);
        }
        *out_names = NULL;
        *out_count = 0U;
        *out_captures_self = false;
        return false;
    }
    return true;
}

static bool cg_emit_capture_cell_type(CG *cg,
                                      const CGType *value_type,
                                      FengToken blame,
                                      char **out_struct_name,
                                      char **out_desc_name) {
    Buf sb;
    Buf db;
    Buf *td = &cg->type_defs;
    bool any_nontrivial = false;

    buf_init(&sb);
    buf_init(&db);
    buf_append_fmt(&sb, "FengCaptureCell__%s__%zu",
                   cg->module_mangle ? cg->module_mangle : "mod",
                   cg->capture_cell_counter);
    buf_append_fmt(&db, "FengCaptureCellDesc__%s__%zu",
                   cg->module_mangle ? cg->module_mangle : "mod",
                   cg->capture_cell_counter);
    cg->capture_cell_counter += 1;
    if (sb.data == NULL || db.data == NULL) {
        buf_free(&sb);
        buf_free(&db);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_fmt(td, "struct %s {\n", sb.data);
    buf_append_cstr(td, "    FengManagedHeader _hdr;\n    ");
    cg_emit_c_type(td, value_type);
    buf_append_cstr(td, " value;\n};\n\n");

    any_nontrivial = cgtype_value_kind(value_type) != CG_VK_TRIVIAL;
    if (any_nontrivial) {
        buf_append_fmt(td,
            "static void %s__release_children(void *_self) {\n"
            "    struct %s *_o = (struct %s *)_self;\n",
            db.data,
            sb.data,
            sb.data);
        if (!cg_emit_field_release(cg, td, "value", value_type, blame)) {
            free(sb.data);
            free(db.data);
            return false;
        }
        buf_append_cstr(td, "}\n\n");

        buf_append_fmt(td,
            "static const FengManagedFieldDescriptor %s__managed_fields[] = {\n",
            db.data);
        if (!cg_emit_field_managed_descriptors(cg, td, sb.data, "value", value_type, blame)) {
            free(sb.data);
            free(db.data);
            return false;
        }
        buf_append_cstr(td, "};\n\n");
    }

    if (any_nontrivial) {
        size_t managed_count = cg_field_managed_descriptor_count(cg, value_type, blame);
        if (cg->failed) {
            free(sb.data);
            free(db.data);
            return false;
        }
        buf_append_fmt(td,
            "static const FengTypeDescriptor %s = {\n"
            "    .name = \"%s\",\n"
            "    .size = sizeof(struct %s),\n"
            "    .finalizer = NULL,\n"
            "    .release_children = %s__release_children,\n"
            "    .is_potentially_cyclic = true,\n"
            "    .managed_field_count = %zu,\n"
            "    .managed_fields = %s__managed_fields,\n"
            "    .equal_fn = NULL,\n"
            "    .reified_generic_params_count = 0,\n"
            "};\n\n",
            db.data,
            sb.data,
            sb.data,
            db.data,
            managed_count,
            db.data);
    } else {
        buf_append_fmt(td,
            "static const FengTypeDescriptor %s = {\n"
            "    .name = \"%s\",\n"
            "    .size = sizeof(struct %s),\n"
            "    .finalizer = NULL,\n"
            "    .release_children = NULL,\n"
            "    .is_potentially_cyclic = false,\n"
            "    .managed_field_count = 0,\n"
            "    .managed_fields = NULL,\n"
            "    .equal_fn = NULL,\n"
            "    .reified_generic_params_count = 0,\n"
            "};\n\n",
            db.data,
            sb.data,
            sb.data);
    }

    *out_struct_name = sb.data;
    *out_desc_name = db.data;
    return true;
}

static bool cg_scope_add_capture_alias(Scope *scope,
                                       FengSlice name,
                                       const char *value_expr,
                                       const char *cell_expr,
                                       const char *cell_struct_name,
                                       const char *cell_desc_name,
                                       const CGType *value_type,
                                       bool uses_dynamic_storage) {
    CGType *alias_type = cgtype_clone(value_type);
    if (alias_type == NULL ||
        !scope_add(scope, "__capture_alias__", value_expr, alias_type, true)) {
        cgtype_free(alias_type);
        return false;
    }
    Local *added = &scope->items[scope->count - 1U];
    free(added->name);
    added->name = strndup(name.data, name.length);
    added->capture_cell_c_name = strdup(cell_expr);
    added->capture_cell_struct_name = cell_struct_name != NULL
                                          ? strdup(cell_struct_name)
                                          : NULL;
    added->capture_cell_desc_name = cell_desc_name != NULL
                                        ? strdup(cell_desc_name)
                                        : NULL;
    added->capture_cell_uses_dynamic_storage = uses_dynamic_storage;
    return added->name != NULL &&
           added->capture_cell_c_name != NULL &&
           (uses_dynamic_storage ||
            (added->capture_cell_struct_name != NULL &&
             added->capture_cell_desc_name != NULL));
}

static bool cg_emit_capture_cell_init_from_expr(CG *cg,
                                                const char *cell_expr,
                                                const char *value_expr,
                                                const CGType *value_type,
                                                FengToken blame,
                                                bool owns_ref) {
    if (cgtype_is_managed(value_type)) {
        if (owns_ref) {
            buf_append_fmt(cg->cur_body, "    %s->value = %s;\n", cell_expr, value_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    %s->value = %s; feng_retain(%s->value);\n",
                           cell_expr,
                           value_expr,
                           cell_expr);
        }
        return true;
    }
    if (cgtype_is_aggregate(value_type)) {
        if (owns_ref) {
            buf_append_fmt(cg->cur_body, "    %s->value = %s;\n", cell_expr, value_expr);
        } else {
            const char *desc = cg_aggregate_desc_name(value_type);
            if (desc == NULL) {
                return cg_fail(cg, blame,
                    "CE0008", "codegen: missing aggregate descriptor for capture cell");
            }
            buf_append_fmt(cg->cur_body,
                           "    %s->value = %s; feng_aggregate_retain(&%s->value, &%s);\n",
                           cell_expr,
                           value_expr,
                           cell_expr,
                           desc);
        }
        return true;
    }
    {
        char *cty = cg_ctype_dup(value_type);
        if (cty == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "    %s->value = (%s)(%s);\n",
                       cell_expr,
                       cty,
                       value_expr);
        free(cty);
    }
    return true;
}

static bool cg_emit_capture_cell_default_init(CG *cg,
                                              const char *cell_expr,
                                              const CGType *value_type,
                                              FengToken blame) {
    if (cgtype_is_aggregate(value_type)) {
        Buf lvalue;
        bool ok;
        buf_init(&lvalue);
        buf_append_fmt(&lvalue, "%s->value", cell_expr);
        if (lvalue.data == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_cstr(cg->cur_body, "    ");
        ok = cg_append_aggregate_default_init_call(cg->cur_body, value_type, lvalue.data);
        buf_free(&lvalue);
        if (!ok) {
            return cg_fail(cg, blame,
                "CE0009", "codegen: missing aggregate default-init rule for capture cell");
        }
        buf_append_cstr(cg->cur_body, ";\n");
        return true;
    }
    {
        char *def_expr = NULL;
        if (!cg_default_value_expr(cg, value_type, &blame, &def_expr)) {
            return false;
        }
        buf_append_fmt(cg->cur_body, "    %s->value = %s;\n", cell_expr, def_expr);
        free(def_expr);
    }
    return true;
}

/* Return whether a type denotes the erased `self` of the generic owner whose
 * shared body is currently being emitted. The nominal view may be absent in
 * legacy callers or present as a local open-owner view; both use `_td` as the
 * closed layout authority. */
static bool cg_type_is_current_generic_owner(const CG *cg,
                                             const CGType *value_type) {
    const FengDecl *origin;

    if (cg == NULL || value_type == NULL ||
        value_type->kind != CG_TYPE_OBJECT ||
        cg->generic_type_method_decl == NULL) {
        return false;
    }
    if (value_type->user == NULL) {
        return true;
    }
    origin = value_type->user->generic_origin_decl != NULL
                 ? value_type->user->generic_origin_decl
                 : value_type->user->decl;
    return value_type->user->generic_context_type_param_count > 0U &&
           origin == cg->generic_type_method_decl;
}

/* Return whether the current erased generic-owner self has value semantics. */
static bool cg_type_is_current_generic_owner_value(const CG *cg,
                                                   const CGType *value_type) {
    return cg_type_is_current_generic_owner(cg, value_type) &&
           value_type->user != NULL &&
           cg_user_type_is_value_semantics(value_type->user);
}

/* Return whether one captured binding needs concrete-size storage selected
 * by runtime descriptors. The dynamic path reuses the capture cell's single
 * heap allocation as a one-element kinded array; fixed-layout captures keep
 * the generated typed cell used before generic capture support. */
static bool cg_capture_cell_uses_dynamic_storage(const CG *cg,
                                                 const CGType *value_type) {
    return value_type != NULL &&
           (value_type->kind == CG_TYPE_GENERIC_PARAM ||
            cg_type_uses_reified_storage(cg, value_type) ||
            cg_type_is_current_generic_owner_value(cg, value_type));
}

/* Cache the descriptor and concrete size used by one dynamic capture cell.
 * Direct generic values retain their generic-parameter descriptor authority;
 * descriptor-sized aggregates retain their concrete aggregate descriptor. */
static bool cg_emit_dynamic_capture_storage_metadata(
    CG *cg,
    const CGType *value_type,
    FengToken blame,
    char **out_descriptor_c_name,
    char **out_size_c_name) {
    char *descriptor_name = NULL;
    char *size_name = NULL;

    if (cg == NULL || value_type == NULL || out_descriptor_c_name == NULL ||
        out_size_c_name == NULL) {
        return false;
    }
    if (value_type->kind == CG_TYPE_GENERIC_PARAM) {
        const char *descriptor = cg_generic_param_desc_name(
            cg, value_type->generic_param_index);

        size_name = cg_fresh_temp(cg, "_capture_size");
        descriptor_name = descriptor != NULL ? strdup(descriptor) : NULL;
        if (descriptor_name == NULL || size_name == NULL) {
            free(descriptor_name);
            free(size_name);
            return cg_fail(cg,
                           blame,
                           descriptor == NULL ? "CE0097" : "IE0001",
                           descriptor == NULL
                               ? "codegen: dynamic capture is missing its generic parameter descriptor"
                               : "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "    const size_t %s = feng_generic_value_size(%s);\n",
                       size_name,
                       descriptor_name);
    } else {
        char *descriptor_expr =
            cg_type_is_current_generic_owner_value(cg, value_type)
                ? strdup("_td")
                : cg_reified_aggregate_descriptor_expr_dup(
                      cg, value_type, blame);

        descriptor_name = cg_fresh_temp(cg, "_capture_rad");
        size_name = cg_fresh_temp(cg, "_capture_size");
        if (descriptor_expr == NULL || descriptor_name == NULL ||
            size_name == NULL) {
            free(descriptor_expr);
            free(descriptor_name);
            free(size_name);
            if (!cg->failed) {
                cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }
            return false;
        }
        buf_append_fmt(cg->cur_body,
                       "    const FengAggregateDescriptor *%s = %s;\n"
                       "    const size_t %s = %s->size;\n",
                       descriptor_name,
                       descriptor_expr,
                       size_name,
                       descriptor_name);
        free(descriptor_expr);
    }

    *out_descriptor_c_name = descriptor_name;
    *out_size_c_name = size_name;
    return true;
}

/* Bind one direct-generic or descriptor-sized aggregate capture. FengArray
 * already supplies concrete-size inline storage, element lifecycle metadata,
 * ARC ownership, and cycle traversal, so this remains one capture-cell
 * allocation and requires no runtime ABI extension. */
static bool cg_scope_bind_dynamic_capture_cell(
    CG *cg,
    Scope *scope,
    FengSlice name,
    const CGType *value_type,
    FengToken blame,
    const char *source_expr,
    bool has_source,
    bool source_owns_ref,
    bool record_debug_variable,
    FengCodegenMapingVariableKind debug_kind) {
    char *descriptor_name = NULL;
    char *size_name = NULL;
    char *cell_var = NULL;
    char *value_expr = NULL;
    CGType *cell_type = NULL;
    bool ok = false;

    if (!cg_emit_dynamic_capture_storage_metadata(cg,
                                                   value_type,
                                                   blame,
                                                   &descriptor_name,
                                                   &size_name)) {
        return false;
    }
    cell_var = cg_local_cname(cg, name.data, name.length);
    if (cell_var == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    if (value_type->kind == CG_TYPE_GENERIC_PARAM) {
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new_kinded("
            "%s->kind, "
            "%s->kind == FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS "
            "? (const FengAggregateDescriptor *)%s->descriptor : NULL, "
            "%s->kind == FENG_VALUE_MANAGED_POINTER "
            "? (const FengTypeDescriptor *)%s->descriptor : NULL, "
            "%s, (size_t)1);\n",
            cell_var,
            descriptor_name,
            descriptor_name,
            descriptor_name,
            descriptor_name,
            descriptor_name,
            size_name);
        if (has_source) {
            buf_append_fmt(cg->cur_body,
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(feng_array_data(%s), %s, %s);\n"
                "            break;\n"
                "        case FENG_VALUE_MANAGED_POINTER:\n",
                descriptor_name,
                cell_var,
                source_expr,
                size_name);
            if (source_owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "            *(void **)feng_array_data(%s) = "
                    "*(void **)%s;\n"
                    "            *(void **)%s = NULL;\n",
                    cell_var,
                    source_expr,
                    source_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "            *(void **)feng_array_data(%s) = "
                    "*(void *const *)%s;\n"
                    "            feng_retain(*(void **)feng_array_data(%s));\n",
                    cell_var,
                    source_expr,
                    cell_var);
            }
            buf_append_cstr(cg->cur_body,
                "            break;\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n");
            if (source_owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "            feng_aggregate_take(feng_array_data(%s), "
                    "(void *)%s, (const FengAggregateDescriptor *)%s->descriptor);\n",
                    cell_var,
                    source_expr,
                    descriptor_name);
            } else {
                buf_append_fmt(cg->cur_body,
                    "            feng_aggregate_assign(feng_array_data(%s), "
                    "%s, (const FengAggregateDescriptor *)%s->descriptor);\n",
                    cell_var,
                    source_expr,
                    descriptor_name);
            }
            buf_append_cstr(cg->cur_body,
                "            break;\n"
                "    }\n");
        }
    } else {
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new_kinded("
            "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, %s, NULL, %s, "
            "(size_t)1);\n",
            cell_var,
            descriptor_name,
            size_name);
        if (has_source) {
            buf_append_fmt(cg->cur_body,
                source_owns_ref
                    ? "    feng_aggregate_take(feng_array_data(%s), (void *)%s, %s);\n"
                    : "    feng_aggregate_assign(feng_array_data(%s), %s, %s);\n",
                cell_var,
                source_expr,
                descriptor_name);
        }
    }

    cell_type = cgtype_new(CG_TYPE_ARRAY);
    if (cell_type == NULL ||
        !scope_add(scope, "__capture_cell__", cell_var, cell_type, false)) {
        cgtype_free(cell_type);
        cell_type = NULL;
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cell_type = NULL;
    cg_emit_cleanup_push_for_managed_local(cg, cell_var);

    {
        Buf value_buf;
        buf_init(&value_buf);
        buf_append_fmt(&value_buf, "((void *)feng_array_data(%s))", cell_var);
        value_expr = value_buf.data;
    }
    if (value_expr == NULL ||
        !cg_scope_add_capture_alias(scope,
                                    name,
                                    value_expr,
                                    cell_var,
                                    NULL,
                                    NULL,
                                    value_type,
                                    true)) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (value_type->kind == CG_TYPE_GENERIC_PARAM) {
        if (!scope_mark_last_erased_generic_storage(scope,
                                                     descriptor_name,
                                                     size_name)) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    } else if (!scope_mark_last_reified_storage(scope,
                                                descriptor_name,
                                                size_name)) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (record_debug_variable &&
        !cg_debug_add_variable_record_slice_cgtype(cg,
                                                   cell_var,
                                                   name,
                                                   value_expr,
                                                   value_type,
                                                   debug_kind,
                                                   blame)) {
        goto cleanup;
    }

    ok = true;

cleanup:
    free(descriptor_name);
    free(size_name);
    free(cell_var);
    free(value_expr);
    cgtype_free(cell_type);
    return ok;
}

static bool cg_scope_bind_capture_cell(CG *cg,
                                       Scope *scope,
                                       FengSlice name,
                                       const CGType *value_type,
                                       FengToken blame,
                                       const char *source_expr,
                                       bool has_source,
                                       bool source_owns_ref,
                                       bool record_debug_variable,
                                       FengCodegenMapingVariableKind debug_kind) {
    char *cell_struct_name = NULL;
    char *cell_desc_name = NULL;
    char *cell_var = NULL;
    char *value_expr = NULL;
    CGType *cell_type = NULL;
    bool ok = false;

    if (cg_capture_cell_uses_dynamic_storage(cg, value_type)) {
        return cg_scope_bind_dynamic_capture_cell(cg,
                                                  scope,
                                                  name,
                                                  value_type,
                                                  blame,
                                                  source_expr,
                                                  has_source,
                                                  source_owns_ref,
                                                  record_debug_variable,
                                                  debug_kind);
    }

    if (!cg_emit_capture_cell_type(cg,
                                   value_type,
                                   blame,
                                   &cell_struct_name,
                                   &cell_desc_name)) {
        return false;
    }
    cell_var = cg_local_cname(cg, name.data, name.length);
    if (cell_var == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    buf_append_fmt(cg->cur_body,
                   "    struct %s *%s = (struct %s *)feng_object_new(&%s);\n",
                   cell_struct_name,
                   cell_var,
                   cell_struct_name,
                   cell_desc_name);
    if (has_source) {
        if (!cg_emit_capture_cell_init_from_expr(cg,
                                                 cell_var,
                                                 source_expr,
                                                 value_type,
                                                 blame,
                                                 source_owns_ref)) {
            goto cleanup;
        }
    } else if (!cg_emit_capture_cell_default_init(cg, cell_var, value_type, blame)) {
        goto cleanup;
    }

    cell_type = cgtype_new(CG_TYPE_OBJECT);
    if (cell_type == NULL ||
        !scope_add(scope, "__capture_cell__", cell_var, cell_type, false)) {
        cgtype_free(cell_type);
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cell_type = NULL;
    cg_emit_cleanup_push_for_managed_local(cg, cell_var);

    {
        Buf value_buf;
        buf_init(&value_buf);
        buf_append_fmt(&value_buf, "(%s->value)", cell_var);
        value_expr = value_buf.data;
    }
    if (value_expr == NULL ||
        !cg_scope_add_capture_alias(scope,
                                    name,
                                    value_expr,
                                    cell_var,
                                    cell_struct_name,
                                    cell_desc_name,
                                    value_type,
                                    false)) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (record_debug_variable &&
        !cg_debug_add_variable_record_slice_cgtype(cg,
                                                   cell_var,
                                                   name,
                                                   value_expr,
                                                   value_type,
                                                   debug_kind,
                                                   blame)) {
        goto cleanup;
    }

    ok = true;

cleanup:
    free(cell_struct_name);
    free(cell_desc_name);
    free(cell_var);
    free(value_expr);
    cgtype_free(cell_type);
    return ok;
}

/* ===================== type resolution ===================== */

typedef struct BuiltinTypeMap {
    const char *name;
    CGTypeKind  kind;
} BuiltinTypeMap;

static const BuiltinTypeMap k_builtin_types[] = {
    {"void",   CG_TYPE_VOID},
    {"bool",   CG_TYPE_BOOL},
    {"i8",     CG_TYPE_I8},   {"i16", CG_TYPE_I16},
    {"i32",    CG_TYPE_I32},  {"i64", CG_TYPE_I64},
    {"u8",     CG_TYPE_U8},   {"u16", CG_TYPE_U16},
    {"u32",    CG_TYPE_U32},  {"u64", CG_TYPE_U64},
    {"f32",    CG_TYPE_F32},  {"f64", CG_TYPE_F64},
    {"string", CG_TYPE_STRING},
};

/* Compare two module qualified names (segment slices) for exact equality. */
static bool cg_module_segments_equal(const FengSlice *a, size_t an,
                                     const FengSlice *b, size_t bn) {
    if (an != bn) return false;
    for (size_t i = 0; i < an; i++) {
        if (a[i].length != b[i].length) return false;
        if (memcmp(a[i].data, b[i].data, a[i].length) != 0) return false;
    }
    return true;
}

static bool cg_slice_equals(FengSlice a, FengSlice b) {
    return a.length == b.length &&
           (a.length == 0U || memcmp(a.data, b.data, a.length) == 0);
}

/* True iff `consumer` can see top-level decls owned by `provider`:
 *   - same program (a decl always sees itself / its own siblings); or
 *   - same module across different files (semantic groups them together); or
 *   - `consumer` lists `provider`'s module name in its `use` declarations.
 * The visibility check is deliberately structural and does NOT consult
 * `open` markers \u2014 semantic has already accepted the program as well-typed,
 * so any name the user wrote is by construction visible. We only need to
 * pick the *correct* candidate when multiple modules expose a same-simple-named
 * type, which is the exact bug this guards against. */
static FengSemanticModuleOrigin cg_program_origin(const CG *cg,
                                                  const FengProgram *prog);

static bool cg_program_can_see(const CG *cg,
                               const FengProgram *consumer,
                               const FengProgram *provider) {
    if (!consumer || !provider) return true;       /* not yet pinned */
    if (consumer == provider) return true;
    if (cg_module_segments_equal(consumer->module_segments,
                                 consumer->module_segment_count,
                                 provider->module_segments,
                                 provider->module_segment_count)) {
        return true;
    }
    /* Synthesized programs from imported packages carry no use-declarations;
     * their type refs were validated during the original compilation. */
    if (cg != NULL &&
        cg_program_origin(cg, consumer) ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    for (size_t i = 0; i < consumer->use_count; i++) {
        const FengUseDecl *u = &consumer->uses[i];
        if (cg_module_segments_equal(u->segments, u->segment_count,
                                     provider->module_segments,
                                     provider->module_segment_count)) {
            return true;
        }
    }
    return false;
}

static FengSemanticModuleOrigin cg_program_origin(const CG *cg,
                                                  const FengProgram *prog) {
    if (cg == NULL || cg->analysis == NULL || prog == NULL) {
        return FENG_SEMANTIC_MODULE_ORIGIN_LOCAL;
    }

    for (size_t module_index = 0; module_index < cg->analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &cg->analysis->modules[module_index];

        for (size_t program_index = 0; program_index < module->program_count; ++program_index) {
            if (module->programs[program_index] == prog) {
                return module->origin;
            }
        }
    }

    return FENG_SEMANTIC_MODULE_ORIGIN_LOCAL;
}

/* Check a declaration's visibility from an explicit source program. */
static bool cg_decl_visible_to_program(const CG *cg,
                                       const FengProgram *consumer_program,
                                       const FengProgram *owner_program,
                                       FengVisibility visibility) {
    if (cg == NULL || consumer_program == NULL || owner_program == NULL) {
        return true;
    }
    if (owner_program == consumer_program ||
        cg_module_segments_equal(owner_program->module_segments,
                                 owner_program->module_segment_count,
                                 consumer_program->module_segments,
                                 consumer_program->module_segment_count)) {
        return true;
    }

    return visibility == FENG_VISIBILITY_PUBLIC &&
           cg_program_can_see(cg, consumer_program, owner_program);
}

/* Check a declaration's visibility from the program currently being emitted. */
static bool cg_decl_visible_from_program(const CG *cg,
                                         const FengProgram *owner_program,
                                         FengVisibility visibility) {
    return cg_decl_visible_to_program(cg,
                                      cg != NULL ? cg->cur_program : NULL,
                                      owner_program,
                                      visibility);
}

static const FengSemanticModule *cg_find_semantic_module_by_segments(const CG *cg,
                                                                     const FengSlice *segments,
                                                                     size_t segment_count) {
    size_t module_index;

    if (cg == NULL || cg->analysis == NULL) {
        return NULL;
    }

    for (module_index = 0U; module_index < cg->analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &cg->analysis->modules[module_index];

        if (cg_module_segments_equal(module->segments,
                                     module->segment_count,
                                     segments,
                                     segment_count)) {
            return module;
        }
    }

    return NULL;
}

/* Resolve an import alias in an explicit source program. */
static const FengSemanticModule *cg_find_alias_target_module_from_program(
    const CG *cg,
    const FengProgram *consumer_program,
    FengSlice alias) {
    if (cg == NULL || consumer_program == NULL) {
        return NULL;
    }

    for (size_t use_index = 0U; use_index < consumer_program->use_count; ++use_index) {
        const FengUseDecl *use_decl = &consumer_program->uses[use_index];

        if (!use_decl->has_alias || !cg_slice_equals(use_decl->alias, alias)) {
            continue;
        }

        return cg_find_semantic_module_by_segments(cg,
                                                   use_decl->segments,
                                                   use_decl->segment_count);
    }

    return NULL;
}

/* Check a fully qualified declaration reference from an explicit program. */
static bool cg_decl_visible_from_full_path_to_program(
    const CG *cg,
    const FengProgram *consumer_program,
    const FengProgram *owner_program,
    FengVisibility visibility) {
    if (cg == NULL || consumer_program == NULL || owner_program == NULL) {
        return true;
    }
    if (owner_program == consumer_program ||
        cg_module_segments_equal(owner_program->module_segments,
                                 owner_program->module_segment_count,
                                 consumer_program->module_segments,
                                 consumer_program->module_segment_count)) {
        return true;
    }
    return owner_program->module_visibility == FENG_VISIBILITY_PUBLIC &&
           visibility == FENG_VISIBILITY_PUBLIC;
}

/* Resolve a named type reference using the program where that reference was
 * declared, independently of the program that later triggers code generation. */
static bool cg_named_type_ref_targets_owner_program_from(
    const CG *cg,
    const FengProgram *reference_program,
    const FengTypeRef *ref,
    const FengProgram *owner_program,
    FengVisibility visibility,
    FengSlice decl_name) {
    const FengSlice *segments;
    size_t segment_count;

    if (cg == NULL || ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        owner_program == NULL) {
        return false;
    }

    segments = ref->as.named.segments;
    segment_count = ref->as.named.segment_count;
    if (segment_count == 0U ||
        !cg_slice_equals(segments[segment_count - 1U], decl_name)) {
        return false;
    }

    if (segment_count == 1U) {
        return cg_decl_visible_to_program(cg,
                                          reference_program,
                                          owner_program,
                                          visibility);
    }

    if (segment_count == 2U) {
        const FengSemanticModule *alias_target =
            cg_find_alias_target_module_from_program(cg,
                                                     reference_program,
                                                     segments[0]);

        if (alias_target != NULL &&
            cg_module_segments_equal(alias_target->segments,
                                     alias_target->segment_count,
                                     owner_program->module_segments,
                                     owner_program->module_segment_count)) {
            return cg_decl_visible_to_program(cg,
                                              reference_program,
                                              owner_program,
                                              visibility);
        }
    }

    if (!cg_module_segments_equal(segments,
                                  segment_count - 1U,
                                  owner_program->module_segments,
                                  owner_program->module_segment_count)) {
        return false;
    }

    return cg_decl_visible_from_full_path_to_program(cg,
                                                     reference_program,
                                                     owner_program,
                                                     visibility);
}

/* Resolve a named type reference from the program currently being emitted. */
static bool cg_named_type_ref_targets_owner_program(const CG *cg,
                                                    const FengTypeRef *ref,
                                                    const FengProgram *owner_program,
                                                    FengVisibility visibility,
                                                    FengSlice decl_name) {
    return cg_named_type_ref_targets_owner_program_from(
        cg,
        cg != NULL ? cg->cur_program : NULL,
        ref,
        owner_program,
        visibility,
        decl_name);
}

static const FengProgram *cg_find_decl_owner_program(const CG *cg, const FengDecl *decl) {
    size_t module_index;

    if (cg == NULL || cg->analysis == NULL || decl == NULL) {
        return NULL;
    }

    for (module_index = 0U; module_index < cg->analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &cg->analysis->modules[module_index];
        size_t program_index;

        for (program_index = 0U; program_index < module->program_count; ++program_index) {
            const FengProgram *program = module->programs[program_index];
            size_t decl_index;

            for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                if (program->declarations[decl_index] == decl) {
                    return program;
                }
            }
        }
    }

    return NULL;
}

/* Return whether one private method belongs to the stable package symbol
 * domain. Local providers consume only the outer driver's abstract symbol
 * query; imported declarations are already the package-public projection. */
static bool cg_member_is_package_symbol_dependency(
    const CG *cg,
    const FengDecl *owner_decl,
    const FengTypeMember *member) {
    const FengProgram *owner_program;
    const FengCodegenPackageSymbolQuery *query;

    if (cg == NULL || owner_decl == NULL || member == NULL ||
        owner_decl->visibility != FENG_VISIBILITY_PUBLIC ||
        member->kind != FENG_TYPE_MEMBER_METHOD ||
        member->visibility != FENG_VISIBILITY_PRIVATE ||
        cg_member_is_mixable_seal_static(member)) {
        return false;
    }
    owner_program = cg_find_decl_owner_program(cg, owner_decl);
    if (owner_program != NULL &&
        cg_program_origin(cg, owner_program) ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    query = cg->options != NULL ? cg->options->package_symbols : NULL;
    return query != NULL && query->contains_source_node != NULL &&
           query->contains_source_node(query->user, member);
}

static bool cg_member_uses_package_callable_surface(
    const CG *cg,
    const FengDecl *owner_decl,
    const FengTypeMember *member) {
    if (cg == NULL || owner_decl == NULL || member == NULL ||
        member->kind != FENG_TYPE_MEMBER_METHOD ||
        owner_decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return false;
    }
    return member->visibility != FENG_VISIBILITY_PRIVATE ||
           cg_member_is_mixable_seal_static(member) ||
           feng_semantic_member_is_package_spec_implementation_dependency(
               cg->analysis,
               member);
}

/* Reuse the open static-field codegen path for every language-open member and
 * for a seal member selected by a package-public nominal spec relation. The
 * latter remains seal in .ft and is not exposed to ordinary member lookup. */
static bool cg_member_uses_package_static_binding_codegen(
    const CG *cg,
    const FengDecl *owner_decl,
    const FengTypeMember *member) {
    const FengProgram *owner_program;

    if (cg == NULL || owner_decl == NULL || member == NULL ||
        owner_decl->kind != FENG_DECL_TYPE ||
        owner_decl->visibility != FENG_VISIBILITY_PUBLIC ||
        member->kind != FENG_TYPE_MEMBER_FIELD ||
        !member->is_static) {
        return false;
    }
    if (member->visibility != FENG_VISIBILITY_PRIVATE) {
        return true;
    }

    owner_program = cg_find_decl_owner_program(cg, owner_decl);
    if (cg_program_origin(cg, owner_program) ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return feng_semantic_member_is_selected_spec_witness_implementation(
            cg->analysis,
            member);
    }
    return feng_semantic_member_is_package_spec_implementation_dependency(
        cg->analysis,
        member);
}

static char *cg_enum_typedef_name(const CG *cg, const FengDecl *enum_decl) {
    const FengProgram *owner_program;
    char *module_mangle;
    char *enum_name;
    Buf b;

    if (enum_decl == NULL || enum_decl->kind != FENG_DECL_ENUM) {
        return NULL;
    }

    owner_program = cg_find_decl_owner_program(cg, enum_decl);
    if (owner_program == NULL) {
        return NULL;
    }

    module_mangle = cg_module_mangle(owner_program->module_segments,
                                     owner_program->module_segment_count);
    enum_name = cg_sanitize(enum_decl->as.enum_decl.name.data,
                            enum_decl->as.enum_decl.name.length);
    if (module_mangle == NULL || enum_name == NULL) {
        free(module_mangle);
        free(enum_name);
        return NULL;
    }

    buf_init(&b);
    buf_append_cstr(&b, "FengEnum__");
    buf_append_cstr(&b, module_mangle);
    buf_append_cstr(&b, "__");
    buf_append_cstr(&b, enum_name);

    free(module_mangle);
    free(enum_name);
    return b.data;
}

static char *cg_enum_trivial_descriptor_name(const CG *cg, const FengDecl *enum_decl) {
    const FengProgram *owner_program;
    char *module_mangle;
    char *enum_name;
    Buf b;

    if (cg == NULL || enum_decl == NULL || enum_decl->kind != FENG_DECL_ENUM) {
        return NULL;
    }
    owner_program = cg_find_decl_owner_program(cg, enum_decl);
    if (owner_program == NULL) {
        return NULL;
    }
    module_mangle = cg_module_mangle(owner_program->module_segments,
                                     owner_program->module_segment_count);
    enum_name = cg_sanitize(enum_decl->as.enum_decl.name.data,
                            enum_decl->as.enum_decl.name.length);
    if (module_mangle == NULL || enum_name == NULL) {
        free(module_mangle);
        free(enum_name);
        return NULL;
    }
    buf_init(&b);
    buf_append_cstr(&b, "FengEnumDesc__");
    buf_append_cstr(&b, module_mangle);
    buf_append_cstr(&b, "__");
    buf_append_cstr(&b, enum_name);
    free(module_mangle);
    free(enum_name);
    return b.data;
}

/* Build the existing per-type box struct symbol for one named enum. */
static char *cg_enum_value_box_struct_name(const CG *cg,
                                           const FengDecl *enum_decl) {
    char *typedef_name = cg_enum_typedef_name(cg, enum_decl);
    Buf name;

    if (typedef_name == NULL) return NULL;
    buf_init(&name);
    buf_append_fmt(&name, "%s__spec_box", typedef_name);
    free(typedef_name);
    return name.data;
}

/* Build the declaration-unique box descriptor symbol for one named enum. */
static char *cg_enum_value_box_descriptor_name(const CG *cg,
                                               const FengDecl *enum_decl) {
    char *struct_name = cg_enum_value_box_struct_name(cg, enum_decl);
    Buf name;

    if (struct_name == NULL) return NULL;
    buf_init(&name);
    buf_append_fmt(&name, "%s_desc", struct_name);
    free(struct_name);
    return name.data;
}

/* Build the private equality helper symbol owned by one enum box descriptor. */
static char *cg_enum_value_box_equal_name(const CG *cg,
                                          const FengDecl *enum_decl) {
    char *descriptor_name =
        cg_enum_value_box_descriptor_name(cg, enum_decl);
    Buf name;

    if (descriptor_name == NULL) return NULL;
    buf_init(&name);
    buf_append_fmt(&name, "%s__equal", descriptor_name);
    free(descriptor_name);
    return name.data;
}

static char *cg_enum_item_c_name(const CG *cg,
                                 const FengDecl *enum_decl,
                                 FengSlice item_name) {
    char *typedef_name;
    char *sanitized_item_name;
    Buf b;

    typedef_name = cg_enum_typedef_name(cg, enum_decl);
    sanitized_item_name = cg_sanitize(item_name.data, item_name.length);
    if (typedef_name == NULL || sanitized_item_name == NULL) {
        free(typedef_name);
        free(sanitized_item_name);
        return NULL;
    }

    buf_init(&b);
    buf_append_cstr(&b, typedef_name);
    buf_append_cstr(&b, "__");
    buf_append_cstr(&b, sanitized_item_name);

    free(typedef_name);
    free(sanitized_item_name);
    return b.data;
}

static const FengDecl *cg_find_public_binding_decl_in_module(const FengSemanticModule *module,
                                                             FengSlice name) {
    size_t program_index;

    if (module == NULL) {
        return NULL;
    }

    for (program_index = 0U; program_index < module->program_count; ++program_index) {
        const FengProgram *program = module->programs[program_index];
        size_t decl_index;

        for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
            const FengDecl *decl = program->declarations[decl_index];

            if (decl->kind == FENG_DECL_GLOBAL_BINDING &&
                decl->visibility == FENG_VISIBILITY_PUBLIC &&
                cg_slice_equals(decl->as.binding.name, name)) {
                return decl;
            }
        }
    }

    return NULL;
}

static const FengDecl *cg_find_visible_binding_decl(const CG *cg, const char *name, size_t len) {
    const FengDecl *visible = NULL;
    size_t module_index;

    if (cg == NULL || cg->analysis == NULL) {
        return NULL;
    }

    for (module_index = 0U; module_index < cg->analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &cg->analysis->modules[module_index];
        size_t program_index;

        for (program_index = 0U; program_index < module->program_count; ++program_index) {
            const FengProgram *program = module->programs[program_index];
            size_t decl_index;

            for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl->kind != FENG_DECL_GLOBAL_BINDING ||
                    decl->as.binding.name.length != len ||
                    memcmp(decl->as.binding.name.data, name, len) != 0) {
                    continue;
                }
                if (cg->cur_program != NULL && program == cg->cur_program) {
                    return decl;
                }
                if (cg_decl_visible_from_program(cg, program, decl->visibility) && visible == NULL) {
                    visible = decl;
                }
            }
        }
    }

    return visible;
}

/* Resolve the module and final member name for either `alias.member` or
 * `module.path.member`. Semantic analysis has already enforced visibility;
 * codegen only recovers the canonical provider declaration. */
static const FengSemanticModule *cg_resolve_module_member_target(
    const CG *cg,
    const FengExpr *expr,
    FengSlice *out_member_name) {
    FengSlice *segments;
    size_t segment_count = 0U;
    const FengSemanticModule *module = NULL;

    if (out_member_name != NULL) {
        memset(out_member_name, 0, sizeof(*out_member_name));
    }
    if (cg == NULL || expr == NULL || out_member_name == NULL ||
        expr->kind != FENG_EXPR_MEMBER || expr->as.member.object == NULL) {
        return NULL;
    }

    segments = cg_expr_path_segments_alloc(expr, &segment_count);
    if (segments != NULL && segment_count > 1U && cg->cur_scope != NULL &&
        scope_lookup(cg->cur_scope,
                     segments[0].data,
                     segments[0].length) != NULL) {
        free(segments);
        return NULL;
    }

    if (cg->cur_program != NULL &&
        expr->as.member.object->kind == FENG_EXPR_IDENTIFIER) {
        module = cg_find_alias_target_module_from_program(
            cg,
            cg->cur_program,
            expr->as.member.object->as.identifier);
        if (module != NULL) {
            *out_member_name = expr->as.member.member;
            free(segments);
            return module;
        }
    }

    if (segments != NULL && segment_count > 1U) {
        module = cg_find_semantic_module_by_segments(cg,
                                                     segments,
                                                     segment_count - 1U);
        if (module != NULL) {
            *out_member_name = segments[segment_count - 1U];
        }
    }
    free(segments);
    return module;
}

static const FengDecl *cg_resolve_imported_module_binding_decl(const CG *cg,
                                                               const FengExpr *expr) {
    if (cg == NULL || expr == NULL) {
        return NULL;
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER: {
            const FengDecl *decl = cg_find_visible_binding_decl(cg,
                                                                expr->as.identifier.data,
                                                                expr->as.identifier.length);
            const FengProgram *owner = cg_find_decl_owner_program(cg, decl);

            if (decl == NULL || owner == NULL ||
                cg_program_origin(cg, owner) != FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                return NULL;
            }
            return decl;
        }

        case FENG_EXPR_MEMBER: {
            FengSlice member_name;
            const FengSemanticModule *module =
                cg_resolve_module_member_target(cg, expr, &member_name);

            if (module != NULL) {
                return cg_find_public_binding_decl_in_module(module,
                                                             member_name);
            }
            return NULL;
        }
        default:
            return NULL;
    }
}

static char *cg_decode_annotation_string_literal(CG *cg,
                                                 const FengExpr *expr,
                                                 const char *role) {
    const char *raw;
    size_t raw_length;
    const char *body;
    size_t body_length;
    char *decoded;
    size_t decoded_index = 0U;

    if (expr == NULL || expr->kind != FENG_EXPR_STRING) {
        cg_fail(cg,
                expr != NULL ? expr->token : (FengToken){0},
                "CE0010", "codegen: extern annotation %s argument must resolve to a string literal",
                role != NULL ? role : "string");
        return NULL;
    }

    raw = expr->as.string.data;
    raw_length = expr->as.string.length;
    if (raw_length < 2U || raw == NULL || raw[0] != '"' || raw[raw_length - 1U] != '"') {
        cg_fail(cg, expr->token, "CE0011", "codegen: malformed extern annotation string literal");
        return NULL;
    }

    body = raw + 1U;
    body_length = raw_length - 2U;
    decoded = (char *)malloc(body_length + 1U);
    if (decoded == NULL) {
        cg_fail(cg, expr->token, "IE0001", "codegen: out of memory");
        return NULL;
    }

    for (size_t index = 0U; index < body_length; ++index) {
        char ch = body[index];

        if (ch == '\\' && index + 1U < body_length) {
            char esc = body[++index];

            switch (esc) {
                case '\\': decoded[decoded_index++] = '\\'; break;
                case '"':  decoded[decoded_index++] = '"'; break;
                case 'n':  decoded[decoded_index++] = '\n'; break;
                case 'r':  decoded[decoded_index++] = '\r'; break;
                case 't':  decoded[decoded_index++] = '\t'; break;
                case '0':  decoded[decoded_index++] = '\0'; break;
                default:
                    free(decoded);
                    cg_fail(cg, expr->token, "CE0012", "codegen: unknown extern annotation string escape '\\%c'", esc);
                    return NULL;
            }
        } else {
            decoded[decoded_index++] = ch;
        }
    }
    decoded[decoded_index] = '\0';
    return decoded;
}

static char *cg_resolve_extern_annotation_string_arg(CG *cg,
                                                     const FengExpr *expr,
                                                     const char *role) {
    const FengDecl *decl;

    if (expr == NULL) {
        cg_fail(cg,
                (FengToken){0},
                "CE0013", "codegen: extern annotation %s argument is missing",
                role != NULL ? role : "string");
        return NULL;
    }
    if (expr->kind == FENG_EXPR_STRING) {
        return cg_decode_annotation_string_literal(cg, expr, role);
    }
    if (expr->kind != FENG_EXPR_IDENTIFIER) {
        cg_fail(cg,
                expr->token,
                "CE0014", "codegen: extern annotation %s argument must be a string literal or visible let binding",
                role != NULL ? role : "string");
        return NULL;
    }

    decl = cg_find_visible_binding_decl(cg,
                                        expr->as.identifier.data,
                                        expr->as.identifier.length);
    if (decl == NULL || decl->kind != FENG_DECL_GLOBAL_BINDING ||
        decl->as.binding.mutability == FENG_MUTABILITY_VAR ||
        decl->as.binding.initializer == NULL ||
        decl->as.binding.initializer->kind != FENG_EXPR_STRING) {
        cg_fail(cg,
                expr->token,
                "CE0015", "codegen: extern annotation %s argument must be a string literal or visible let binding initialized directly with a string literal",
                role != NULL ? role : "string");
        return NULL;
    }

    return cg_decode_annotation_string_literal(cg, decl->as.binding.initializer, role);
}

static const FengAnnotation *cg_find_calling_convention_annotation(
    const FengAnnotation *annotations,
    size_t annotation_count);

static char *cg_extern_c_symbol_name(CG *cg,
                                     const FengDecl *decl,
                                     const FengCallableSignature *sig) {
    const FengAnnotation *callconv;

    if (sig == NULL) {
        return NULL;
    }

    callconv = decl != NULL
        ? cg_find_calling_convention_annotation(decl->annotations, decl->annotation_count)
        : NULL;
    if (callconv != NULL && callconv->arg_count > 1U) {
        return cg_resolve_extern_annotation_string_arg(cg,
                                                       callconv->args[1],
                                                       "C function name");
    }

    return strndup(sig->name.data, sig->name.length);
}

static bool cg_binding_public_surface_names(const CG *cg,
                                            const FengDecl *decl,
                                            char **out_slot_name,
                                            char **out_ensure_init_name) {
    const FengProgram *owner_program;
    char *slot_name = NULL;
    char *module_mangle = NULL;
    char *binding_name = NULL;
    Buf ensure_init;

    if (out_slot_name != NULL) {
        *out_slot_name = NULL;
    }
    if (out_ensure_init_name != NULL) {
        *out_ensure_init_name = NULL;
    }
    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_GLOBAL_BINDING) {
        return false;
    }

    owner_program = cg_find_decl_owner_program(cg, decl);
    if (owner_program == NULL) {
        return false;
    }

    module_mangle = cg_module_mangle(owner_program->module_segments,
                                     owner_program->module_segment_count);
    binding_name = cg_sanitize(decl->as.binding.name.data,
                               decl->as.binding.name.length);
    if (module_mangle == NULL || binding_name == NULL) {
        free(module_mangle);
        free(binding_name);
        return false;
    }

    buf_init(&ensure_init);
    slot_name = cg_fn_mangle(module_mangle, &decl->as.binding.name);
    if (slot_name == NULL) {
        free(module_mangle);
        free(binding_name);
        buf_free(&ensure_init);
        return false;
    }
    buf_append_fmt(&ensure_init,
                   "feng__%s__%s__ensure_init__from__void",
                   module_mangle,
                   binding_name);
    free(module_mangle);
    free(binding_name);
    if (ensure_init.data == NULL) {
        free(slot_name);
        return false;
    }

    if (out_slot_name != NULL) {
        *out_slot_name = slot_name;
    } else {
        free(slot_name);
    }
    if (out_ensure_init_name != NULL) {
        *out_ensure_init_name = ensure_init.data;
    } else {
        free(ensure_init.data);
    }
    return true;
}

static bool cg_emit_imported_binding_expr(CG *cg,
                                          const FengDecl *decl,
                                          ExprResult *out);

static bool cg_emit_enum_decl(CG *cg, const FengDecl *decl) {
    char *typedef_name;
    char *descriptor_name;
    char *box_struct_name;
    char *box_descriptor_name;
    char *box_equal_name;
    char *module_dot_name;
    const FengProgram *owner_program;
    size_t item_index;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_ENUM) {
        return true;
    }

    typedef_name = cg_enum_typedef_name(cg, decl);
    descriptor_name = cg_enum_trivial_descriptor_name(cg, decl);
    box_struct_name = cg_enum_value_box_struct_name(cg, decl);
    box_descriptor_name = cg_enum_value_box_descriptor_name(cg, decl);
    box_equal_name = cg_enum_value_box_equal_name(cg, decl);
    owner_program = cg_find_decl_owner_program(cg, decl);
    module_dot_name = owner_program != NULL
                          ? cg_module_dot(owner_program->module_segments,
                                          owner_program->module_segment_count)
                          : NULL;
    if (typedef_name == NULL || descriptor_name == NULL ||
        box_struct_name == NULL || box_descriptor_name == NULL ||
        box_equal_name == NULL || module_dot_name == NULL) {
        free(typedef_name);
        free(descriptor_name);
        free(box_struct_name);
        free(box_descriptor_name);
        free(box_equal_name);
        free(module_dot_name);
        return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory emitting enum typedef");
    }

    bool ext_visible = (owner_program != NULL &&
                        owner_program->module_visibility == FENG_VISIBILITY_PUBLIC &&
                        decl->visibility == FENG_VISIBILITY_PUBLIC);
    buf_append_fmt(&cg->enum_defs, "typedef int32_t %s;\n", typedef_name);
    buf_append_fmt(&cg->enum_defs,
                   ext_visible
                       ? "const FengTrivialDescriptor %s __attribute__((weak)) = {\n"
                       : "static const FengTrivialDescriptor %s = {\n",
                   descriptor_name);
    buf_append_fmt(&cg->enum_defs,
                   "    .name = \"%s.%.*s\",\n"
                   "    .size = sizeof(%s),\n"
                   "    .equal_fn = NULL,\n"
                   "};\n",
                   module_dot_name,
                   (int)decl->as.enum_decl.name.length,
                   decl->as.enum_decl.name.data,
                   typedef_name);
    buf_append_fmt(&cg->enum_defs,
                   "struct %s {\n"
                   "    FengManagedHeader _hdr;\n"
                   "    %s value;\n"
                   "};\n"
                   "static bool %s(const void *_left, const void *_right) {\n"
                   "    const struct %s *_left_box = (const struct %s *)_left;\n"
                   "    const struct %s *_right_box = (const struct %s *)_right;\n"
                   "    return _left_box->value == _right_box->value;\n"
                   "}\n",
                   box_struct_name,
                   typedef_name,
                   box_equal_name,
                   box_struct_name,
                   box_struct_name,
                   box_struct_name,
                   box_struct_name);
    buf_append_fmt(&cg->enum_defs,
                   ext_visible
                       ? "const FengTypeDescriptor %s __attribute__((weak)) = {\n"
                       : "static const FengTypeDescriptor %s = {\n",
                   box_descriptor_name);
    buf_append_fmt(&cg->enum_defs,
                   "    .name = \"%s.%.*s.__enum_box\",\n"
                   "    .size = sizeof(struct %s),\n"
                   "    .finalizer = NULL,\n"
                   "    .release_children = NULL,\n"
                   "    .is_potentially_cyclic = false,\n"
                   "    .managed_field_count = 0,\n"
                   "    .managed_fields = NULL,\n"
                   "    .equal_fn = &%s,\n"
                   "};\n",
                   module_dot_name,
                   (int)decl->as.enum_decl.name.length,
                   decl->as.enum_decl.name.data,
                   box_struct_name,
                   box_equal_name);
    for (item_index = 0U; item_index < decl->as.enum_decl.item_count; ++item_index) {
        const FengEnumItem *item = &decl->as.enum_decl.items[item_index];
        int64_t value = item->has_explicit_value
                            ? item->explicit_value
                            : (int64_t)item_index;
        char *item_c_name = cg_enum_item_c_name(cg, decl, item->name);

        if (item_c_name == NULL) {
            free(typedef_name);
            free(descriptor_name);
            free(box_struct_name);
            free(box_descriptor_name);
            free(box_equal_name);
            free(module_dot_name);
            return cg_fail(cg, item->token, "IE0001", "codegen: out of memory emitting enum item constant");
        }

        buf_append_fmt(&cg->enum_defs,
                       "static const %s %s = ((int32_t)%" PRId64 ");\n",
                       typedef_name,
                       item_c_name,
                       value);
        free(item_c_name);
    }
    buf_append_cstr(&cg->enum_defs, "\n");

    free(typedef_name);
    free(descriptor_name);
    free(box_struct_name);
    free(box_descriptor_name);
    free(box_equal_name);
    free(module_dot_name);
    return true;
}

/* Ensure an imported enum's typedef + constants have been emitted exactly once.
 * No-op for local enums (already emitted by cg_pass_emit_enum_decls). */
static bool cg_ensure_enum_emitted(CG *cg, const FengDecl *decl) {
    const FengProgram *owner;
    size_t i;

    if (decl == NULL || decl->kind != FENG_DECL_ENUM) return true;

    owner = cg_find_decl_owner_program(cg, decl);
    if (owner == NULL) return true;
    if (cg_program_origin(cg, owner) != FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }

    for (i = 0U; i < cg->emitted_enum_decl_count; ++i) {
        if (cg->emitted_enum_decls[i] == decl) return true;
    }

    if (cg->emitted_enum_decl_count >= cg->emitted_enum_decl_capacity) {
        size_t new_cap = cg->emitted_enum_decl_capacity == 0U
                             ? 8U
                             : cg->emitted_enum_decl_capacity * 2U;
        const FengDecl **tmp = realloc(cg->emitted_enum_decls,
                                       new_cap * sizeof(*tmp));
        if (tmp == NULL) {
            return cg_fail(cg, decl->token,
                           "CE0016", "codegen: out of memory tracking emitted enum");
        }
        cg->emitted_enum_decls = tmp;
        cg->emitted_enum_decl_capacity = new_cap;
    }
    cg->emitted_enum_decls[cg->emitted_enum_decl_count++] = decl;

    return cg_emit_enum_decl(cg, decl);
}

static const FengDecl *cg_find_public_enum_decl_in_module(const FengSemanticModule *module,
                                                           FengSlice name) {
    size_t program_index;

    if (module == NULL) {
        return NULL;
    }

    for (program_index = 0U; program_index < module->program_count; ++program_index) {
        const FengProgram *program = module->programs[program_index];
        size_t decl_index;

        for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
            const FengDecl *decl = program->declarations[decl_index];

            if (decl->kind == FENG_DECL_ENUM && decl->visibility == FENG_VISIBILITY_PUBLIC &&
                cg_slice_equals(decl->as.enum_decl.name, name)) {
                return decl;
            }
        }
    }

    return NULL;
}

static const FengDecl *cg_find_visible_enum_decl(const CG *cg, const char *name, size_t len) {
    const FengDecl *visible = NULL;
    size_t module_index;

    if (cg == NULL || cg->analysis == NULL) {
        return NULL;
    }

    for (module_index = 0U; module_index < cg->analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &cg->analysis->modules[module_index];
        size_t program_index;

        for (program_index = 0U; program_index < module->program_count; ++program_index) {
            const FengProgram *program = module->programs[program_index];
            size_t decl_index;

            for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl->kind != FENG_DECL_ENUM || decl->as.enum_decl.name.length != len ||
                    memcmp(decl->as.enum_decl.name.data, name, len) != 0) {
                    continue;
                }
                if (cg->cur_program != NULL && program == cg->cur_program) {
                    return decl;
                }
                if (cg_decl_visible_from_program(cg, program, decl->visibility) && visible == NULL) {
                    visible = decl;
                }
            }
        }
    }

    return visible;
}

static const FengDecl *cg_resolve_type_target_enum_decl(const CG *cg, const FengExpr *target_expr) {
    if (cg == NULL || target_expr == NULL) {
        return NULL;
    }

    switch (target_expr->kind) {
        case FENG_EXPR_IDENTIFIER:
            return cg_find_visible_enum_decl(cg,
                                             target_expr->as.identifier.data,
                                             target_expr->as.identifier.length);

        case FENG_EXPR_MEMBER: {
            FengSlice member_name;
            const FengSemanticModule *module =
                cg_resolve_module_member_target(cg,
                                                target_expr,
                                                &member_name);

            if (module != NULL) {
                return cg_find_public_enum_decl_in_module(module,
                                                          member_name);
            }
            return NULL;
        }

        default:
            return NULL;
    }
}

static const UserType *cg_find_user_type(const CG *cg, const char *name, size_t len) {
    /* Prefer a match owned by the program currently being emitted, then any
     * match visible from it. Falling back to the global list (when nothing
     * matches under visibility filtering) preserves single-file / legacy
     * behaviour and keeps cross-program emit-time helpers (e.g. fit-target
     * resolution before cur_program has been pinned) working. */
    const UserType *visible = NULL;
    for (size_t i = 0; i < cg->user_type_count; i++) {
        const UserType *ut = &cg->user_types[i];
        if (strlen(ut->feng_name) != len ||
            memcmp(ut->feng_name, name, len) != 0) continue;
        if (cg->cur_program && ut->owner_program == cg->cur_program) {
            return ut;                 /* own-program wins outright */
        }
        if (!cg->cur_program ||
            cg_program_can_see(cg, cg->cur_program, ut->owner_program)) {
            if (!visible) visible = ut;
        }
    }
    if (visible) return visible;
    /* No visible match: leave NULL so callers can issue an "unknown type"
     * diagnostic against the offending token. We deliberately do NOT fall
     * back to a hidden, non-visible candidate \u2014 doing so reintroduces the
     * silent cross-module aliasing bug this helper exists to prevent. */
    return NULL;
}

static const UserSpec *cg_find_user_spec(const CG *cg, const char *name, size_t len) {
    const UserSpec *visible = NULL;
    for (size_t i = 0; i < cg->user_spec_count; i++) {
        const UserSpec *us = &cg->user_specs[i];
        if (strlen(us->feng_name) != len ||
            memcmp(us->feng_name, name, len) != 0) continue;
        if (cg->cur_program && us->owner_program == cg->cur_program) {
            return us;
        }
        if (!cg->cur_program ||
            cg_program_can_see(cg, cg->cur_program, us->owner_program)) {
            if (!visible) visible = us;
        }
    }
    return visible;
}

static const UserType *cg_find_user_type_by_decl(const CG *cg, const FengDecl *decl) {
    for (size_t i = 0; i < cg->user_type_count; i++) {
        if (cg->user_types[i].decl == decl) return &cg->user_types[i];
    }
    return NULL;
}

/* Resolve the persistent nominal identity behind a local generic-owner
 * layout view. Witness tables cache their UserType key beyond the current
 * function-emission frame, so a stack-owned view must never become that key. */
static const UserType *cg_user_type_nominal_identity(const CG *cg,
                                                     const UserType *type) {
    if (type == NULL || !type->is_ephemeral_generic_owner_view) {
        return type;
    }
    return cg_find_user_type_by_decl(cg, type->decl);
}

static const UserType *cg_find_open_generic_instance(const CG *cg,
                                                     const UserType *concrete) {
    if (!concrete->is_generic_instance || !concrete->generic_origin_decl) return NULL;
    for (size_t i = 0; i < cg->user_type_count; i++) {
        const UserType *candidate = &cg->user_types[i];
        if (candidate == concrete) continue;
        if (candidate->generic_origin_decl == concrete->generic_origin_decl &&
            candidate->generic_context_type_param_count > 0U) {
            return candidate;
        }
    }
    return NULL;
}

/* 在共享体的 reified_agg_deps 映射中查找给定聚合描述符名称的索引。
 * 返回 true 并设置 *out_index 表示找到；返回 false 表示无匹配。 */
static bool cg_lookup_reified_agg_dep_index(const CG *cg,
                                             const char *agg_desc_name,
                                             size_t *out_index) {
    if (cg->generic_type_method_rad_count == 0U || agg_desc_name == NULL) {
        return false;
    }
    for (size_t i = 0; i < cg->generic_type_method_rad_count; i++) {
        if (cg->generic_type_method_rad_descs[i] != NULL &&
            strcmp(agg_desc_name, cg->generic_type_method_rad_descs[i]) == 0) {
            *out_index = i;
            return true;
        }
    }
    return false;
}

static const UserSpec *cg_find_user_spec_by_decl(const CG *cg, const FengDecl *decl) {
    for (size_t i = 0; i < cg->user_spec_count; i++) {
        if (cg->user_specs[i].decl == decl) return &cg->user_specs[i];
    }
    return NULL;
}

static bool cg_user_spec_index(const CG *cg, const UserSpec *spec, size_t *out_index) {
    if (spec == NULL) {
        *out_index = (size_t)-1;
        return true;
    }
    for (size_t i = 0U; i < cg->user_spec_count; ++i) {
        if (&cg->user_specs[i] == spec) {
            *out_index = i;
            return true;
        }
    }
    return false;
}

static const UserSpec *cg_user_spec_by_index(const CG *cg, size_t index) {
    if (index == (size_t)-1) return NULL;
    if (index >= cg->user_spec_count) return NULL;
    return &cg->user_specs[index];
}

/* Return one exact direct-parent spec instance in source declaration order. */
static const UserSpec *cg_user_spec_direct_parent(const CG *cg,
                                                  const UserSpec *spec,
                                                  size_t parent_index) {
    if (cg == NULL || spec == NULL ||
        parent_index >= spec->direct_parent_spec_count ||
        spec->direct_parent_spec_indices == NULL) {
        return NULL;
    }
    return cg_user_spec_by_index(cg,
                                 spec->direct_parent_spec_indices[parent_index]);
}

/* Parent witness fields use the parent's complete stable witness-struct name,
 * which already includes module identity and instantiated generic arguments. */
static void cg_append_spec_parent_field_name(Buf *out,
                                             const UserSpec *parent_spec) {
    if (out == NULL || parent_spec == NULL ||
        parent_spec->c_witness_struct_name == NULL) {
        return;
    }
    buf_append_fmt(out, "parent__%s", parent_spec->c_witness_struct_name);
}

static bool cg_user_spec_constraint_indices(CG *cg,
                                            const UserSpec **constraints,
                                            size_t constraint_count,
                                            FengToken blame,
                                            size_t **out_indices) {
    size_t *indices = NULL;

    *out_indices = NULL;
    if (constraint_count == 0U) return true;
    indices = calloc(constraint_count, sizeof *indices);
    if (indices == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0U; i < constraint_count; ++i) {
        if (!cg_user_spec_index(cg, constraints != NULL ? constraints[i] : NULL, &indices[i])) {
            free(indices);
            return cg_fail(cg, blame,
                           "CE0017", "codegen: internal: generic constraint spec moved before it could be indexed");
        }
    }
    *out_indices = indices;
    return true;
}

static bool cg_user_spec_constraints_from_indices(CG *cg,
                                                  const size_t *indices,
                                                  size_t constraint_count,
                                                  FengToken blame,
                                                  const UserSpec ***out_constraints) {
    const UserSpec **constraints = NULL;

    *out_constraints = NULL;
    if (constraint_count == 0U) return true;
    constraints = calloc(constraint_count, sizeof *constraints);
    if (constraints == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0U; i < constraint_count; ++i) {
        constraints[i] = cg_user_spec_by_index(cg, indices != NULL ? indices[i] : (size_t)-1);
        if (indices != NULL && indices[i] != (size_t)-1 && constraints[i] == NULL) {
            free(constraints);
            return cg_fail(cg, blame,
                           "CE0018", "codegen: internal: generic constraint spec index is out of range");
        }
    }
    *out_constraints = constraints;
    return true;
}

/* Finds a non-generic user type from the program that owns the reference. */
static const UserType *cg_find_user_type_by_ref_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program) {
    const UserType *visible = NULL;

    if (cg == NULL || ref == NULL || ref->kind != FENG_TYPE_REF_NAMED) {
        return NULL;
    }

    for (size_t i = 0; i < cg->user_type_count; ++i) {
        const UserType *ut = &cg->user_types[i];

        if (ut->is_generic_instance || ut->decl == NULL ||
            ut->decl->kind != FENG_DECL_TYPE || ut->owner_program == NULL ||
            !cg_named_type_ref_targets_owner_program_from(
                cg,
                reference_program,
                ref,
                ut->owner_program,
                ut->decl->visibility,
                ut->decl->as.type_decl.name)) {
            continue;
        }
        if (reference_program != NULL && ut->owner_program == reference_program) {
            return ut;
        }
        if (visible == NULL) {
            visible = ut;
        }
    }

    return visible;
}

/* Finds a non-generic user type from the program currently being emitted. */
static const UserType *cg_find_user_type_by_ref(const CG *cg,
                                                const FengTypeRef *ref) {
    return cg_find_user_type_by_ref_from_program(
        cg,
        ref,
        cg != NULL ? cg->cur_program : NULL);
}

/* Finds a non-generic user spec from the program that owns the reference. */
static const UserSpec *cg_find_user_spec_by_ref_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program) {
    const UserSpec *visible = NULL;

    if (cg == NULL || ref == NULL || ref->kind != FENG_TYPE_REF_NAMED) {
        return NULL;
    }

    for (size_t i = 0; i < cg->user_spec_count; ++i) {
        const UserSpec *us = &cg->user_specs[i];

        if (us->is_generic_instance || us->decl == NULL ||
            us->decl->kind != FENG_DECL_SPEC || us->owner_program == NULL ||
            !cg_named_type_ref_targets_owner_program_from(
                cg,
                reference_program,
                ref,
                us->owner_program,
                us->decl->visibility,
                us->decl->as.spec_decl.name)) {
            continue;
        }
        if (reference_program != NULL && us->owner_program == reference_program) {
            return us;
        }
        if (visible == NULL) {
            visible = us;
        }
    }

    return visible;
}

/* Finds a non-generic user spec from the program currently being emitted. */
static const UserSpec *cg_find_user_spec_by_ref(const CG *cg,
                                                const FengTypeRef *ref) {
    return cg_find_user_spec_by_ref_from_program(
        cg,
        ref,
        cg != NULL ? cg->cur_program : NULL);
}

static const FengDecl *cg_find_enum_decl_by_ref(const CG *cg,
                                                const FengTypeRef *ref) {
    const FengDecl *visible = NULL;

    if (cg == NULL || cg->analysis == NULL || ref == NULL ||
        ref->kind != FENG_TYPE_REF_NAMED) {
        return NULL;
    }

    for (size_t module_index = 0U; module_index < cg->analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &cg->analysis->modules[module_index];

        for (size_t program_index = 0U; program_index < module->program_count; ++program_index) {
            const FengProgram *program = module->programs[program_index];

            for (size_t decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl->kind != FENG_DECL_ENUM ||
                    !cg_named_type_ref_targets_owner_program(cg,
                                                             ref,
                                                             program,
                                                             decl->visibility,
                                                             decl->as.enum_decl.name)) {
                    continue;
                }
                if (cg->cur_program != NULL && program == cg->cur_program) {
                    return decl;
                }
                if (visible == NULL) {
                    visible = decl;
                }
            }
        }
    }

    return visible;
}

/* Resolve the type-fact forms that do not require a declaration-specific
 * type-parameter substitution context. TYPE_REF facts are deliberately left
 * to the caller so free functions, type methods, and fit methods can apply
 * their own owner/callable scopes through the existing resolvers. */
static bool cg_try_resolve_non_reference_type_fact(
    CG *cg,
    const FengSemanticTypeFact *fact,
    FengToken blame,
    CGType **out_type,
    bool *out_handled) {
    if (out_type == NULL || out_handled == NULL) {
        return false;
    }
    *out_type = NULL;
    *out_handled = false;
    if (fact == NULL ||
        fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF ||
        fact->kind == FENG_SEMANTIC_TYPE_FACT_UNKNOWN) {
        return true;
    }

    *out_handled = true;
    if (fact->kind == FENG_SEMANTIC_TYPE_FACT_BUILTIN) {
        for (size_t index = 0U;
             index < sizeof k_builtin_types / sizeof k_builtin_types[0];
             ++index) {
            const BuiltinTypeMap *builtin = &k_builtin_types[index];

            if (strlen(builtin->name) == fact->builtin_name.length &&
                memcmp(builtin->name,
                       fact->builtin_name.data,
                       fact->builtin_name.length) == 0) {
                *out_type = cgtype_new(builtin->kind);
                return *out_type != NULL;
            }
        }
        return cg_fail(cg, blame,
                       "CE0019", "codegen: unsupported builtin inferred callable return type");
    }

    if (fact->kind == FENG_SEMANTIC_TYPE_FACT_DECL) {
        const UserType *user_type;
        const UserSpec *user_spec;
        CGType *resolved;

        if (fact->type_decl == NULL) {
            return cg_fail(cg, blame,
                           "CE0020", "codegen: inferred callable return type is missing its declaration");
        }
        if (fact->type_decl->kind == FENG_DECL_ENUM) {
            *out_type = cgtype_new_enum(fact->type_decl);
            return *out_type != NULL;
        }
        user_type = cg_find_user_type_by_decl(cg, fact->type_decl);
        if (user_type != NULL) {
            resolved = cgtype_new(CG_TYPE_OBJECT);
            if (resolved == NULL) {
                return false;
            }
            resolved->user = user_type;
            *out_type = resolved;
            return true;
        }
        user_spec = cg_find_user_spec_by_decl(cg, fact->type_decl);
        if (user_spec != NULL) {
            resolved = cgtype_new(user_spec->form == FENG_SPEC_FORM_CALLABLE
                                      ? CG_TYPE_CALLABLE
                                      : CG_TYPE_SPEC);
            if (resolved == NULL) {
                return false;
            }
            resolved->user_spec = user_spec;
            *out_type = resolved;
            return true;
        }
        return cg_fail(cg, blame,
                       "CE0021", "codegen: unsupported declared inferred callable return type");
    }

    *out_handled = false;
    return true;
}

/* Resolve one callable's effective return type. An explicit annotation is
 * authoritative; otherwise Semantic's callable type fact supplies the same
 * inferred type used by calls and symbol export. A missing fact denotes the
 * legacy void fallback for body-less/special callables. */
static bool cg_resolve_callable_return_type(
    CG *cg,
    const FengCallableSignature *callable,
    FengToken blame,
    CGType **out_type) {
    const FengSemanticTypeFact *fact = NULL;
    bool handled = false;

    if (out_type == NULL || callable == NULL) {
        return false;
    }
    *out_type = NULL;
    if (callable->return_type != NULL) {
        return cg_resolve_type(cg,
                               callable->return_type,
                               &blame,
                               out_type);
    }
    if (cg != NULL && cg->analysis != NULL) {
        fact = feng_semantic_lookup_type_fact(cg->analysis, callable);
    }
    if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
        return cg_resolve_type(cg, fact->type_ref, &blame, out_type);
    }
    if (!cg_try_resolve_non_reference_type_fact(
            cg, fact, blame, out_type, &handled)) {
        return false;
    }
    if (handled) {
        return true;
    }

    *out_type = cgtype_new(CG_TYPE_VOID);
    return *out_type != NULL;
}

static bool cg_resolve_global_binding_type(CG *cg,
                                           const FengDecl *decl,
                                           CGType **out_type) {
    const FengBinding *binding;
    const FengSemanticTypeFact *fact = NULL;

    if (out_type == NULL) {
        return false;
    }
    *out_type = NULL;
    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_GLOBAL_BINDING) {
        return false;
    }

    binding = &decl->as.binding;
    if (binding->type != NULL) {
        return cg_resolve_type(cg, binding->type, &decl->token, out_type);
    }

    if (cg->analysis != NULL) {
        fact = feng_semantic_lookup_type_fact(cg->analysis, binding);
    }
    if (fact != NULL) {
        switch (fact->kind) {
            case FENG_SEMANTIC_TYPE_FACT_BUILTIN:
                for (size_t i = 0; i < sizeof k_builtin_types / sizeof k_builtin_types[0]; ++i) {
                    const BuiltinTypeMap *m = &k_builtin_types[i];

                    if (strlen(m->name) == fact->builtin_name.length &&
                        memcmp(m->name,
                               fact->builtin_name.data,
                               fact->builtin_name.length) == 0) {
                        *out_type = cgtype_new(m->kind);
                        return *out_type != NULL;
                    }
                }
                return cg_fail(cg,
                               decl->token,
                               "CE0019", "codegen: unsupported builtin inferred type for global binding '%.*s'",
                               (int)binding->name.length,
                               binding->name.data);

            case FENG_SEMANTIC_TYPE_FACT_TYPE_REF:
                return cg_resolve_type(cg, fact->type_ref, &decl->token, out_type);

            case FENG_SEMANTIC_TYPE_FACT_DECL:
                if (fact->type_decl == NULL) {
                    return cg_fail(cg,
                                   decl->token,
                                   "CE0020", "codegen: inferred type for global binding '%.*s' is missing its declaration",
                                   (int)binding->name.length,
                                   binding->name.data);
                }
                if (fact->type_decl->kind == FENG_DECL_ENUM) {
                    *out_type = cgtype_new_enum(fact->type_decl);
                    return *out_type != NULL;
                }
                {
                    const UserType *ut = cg_find_user_type_by_decl(cg, fact->type_decl);

                    if (ut != NULL) {
                        CGType *type = cgtype_new(CG_TYPE_OBJECT);

                        if (type == NULL) {
                            return false;
                        }
                        type->user = ut;
                        *out_type = type;
                        return true;
                    }
                }
                {
                    const UserSpec *us = cg_find_user_spec_by_decl(cg, fact->type_decl);

                    if (us != NULL) {
                        CGType *type = cgtype_new(us->form == FENG_SPEC_FORM_CALLABLE
                                                  ? CG_TYPE_CALLABLE
                                                  : CG_TYPE_SPEC);

                        if (type == NULL) {
                            return false;
                        }
                        type->user_spec = us;
                        *out_type = type;
                        return true;
                    }
                }
                return cg_fail(cg,
                               decl->token,
                               "CE0021", "codegen: unsupported declared inferred type for global binding '%.*s'",
                               (int)binding->name.length,
                               binding->name.data);

            case FENG_SEMANTIC_TYPE_FACT_UNKNOWN:
                break;
        }
    }

    if (binding->initializer == NULL) {
        return cg_fail(cg,
                       decl->token,
                       "CE0022", "codegen: module-level binding requires an explicit type or initializer");
    }

    switch (binding->initializer->kind) {
        case FENG_EXPR_BOOL:
            *out_type = cgtype_new(CG_TYPE_BOOL);
            return *out_type != NULL;
        case FENG_EXPR_INTEGER:
            *out_type = cgtype_new(CG_TYPE_I32);
            return *out_type != NULL;
        case FENG_EXPR_FLOAT:
            *out_type = cgtype_new(CG_TYPE_F64);
            return *out_type != NULL;
        case FENG_EXPR_STRING:
            *out_type = cgtype_new(CG_TYPE_STRING);
            return *out_type != NULL;
        default:
            return cg_fail(cg,
                           decl->token,
                           "CE0023", "codegen: missing semantic type fact for inferred global binding '%.*s'; add an explicit type if this persists",
                           (int)binding->name.length,
                           binding->name.data);
    }
}

static bool cg_resolve_coercion_target_user_spec(CG *cg,
                                                 const FengSpecCoercionSite *cs,
                                                 FengToken blame,
                                                 const UserSpec **out_spec) {
    CGType *target_type = NULL;

    *out_spec = NULL;
    if (cg == NULL || cs == NULL) {
        return false;
    }
    if (cs->target_spec_type_ref != NULL) {
        if (!cg_resolve_type(cg, cs->target_spec_type_ref, &blame, &target_type)) {
            return false;
        }
        if (target_type == NULL ||
            (target_type->kind != CG_TYPE_SPEC && target_type->kind != CG_TYPE_CALLABLE) ||
            target_type->user_spec == NULL) {
            cgtype_free(target_type);
            return cg_fail(cg, blame,
                "CE0024", "codegen: coercion target did not resolve to a concrete spec instance");
        }
        *out_spec = target_type->user_spec;
        cgtype_free(target_type);
        return true;
    }

    *out_spec = cg_find_user_spec_by_decl(cg, cs->target_spec_decl);
    return *out_spec != NULL;
}

static bool cg_resolve_union_target_user_spec(CG *cg,
                                              const FengUnionCoercionSite *site,
                                              FengToken blame,
                                              const UserSpec **out_spec) {
    CGType *target_type = NULL;

    *out_spec = NULL;
    if (cg == NULL || site == NULL) {
        return false;
    }
    if (site->target_union_type_ref != NULL) {
        if (!cg_resolve_type(cg, site->target_union_type_ref, &blame, &target_type)) {
            return false;
        }
        if (target_type == NULL || target_type->kind != CG_TYPE_SPEC ||
            target_type->user_spec == NULL ||
            target_type->user_spec->form != FENG_SPEC_FORM_UNION) {
            cgtype_free(target_type);
            return cg_fail(cg, blame,
                           "CE0025", "codegen: union coercion target did not resolve to a concrete union-form spec");
        }
        *out_spec = target_type->user_spec;
        cgtype_free(target_type);
        return true;
    }

    *out_spec = cg_find_user_spec_by_decl(cg, site->target_union_decl);
    return *out_spec != NULL && (*out_spec)->form == FENG_SPEC_FORM_UNION;
}

static const UserFit *cg_find_user_fit_by_decl_and_target(const CG *cg,
                                                          const FengDecl *decl,
                                                          const UserType *target) {
    for (size_t i = 0; i < cg->user_fit_count; i++) {
        if (cg->user_fits[i].decl == decl && cg->user_fits[i].target == target) {
            return &cg->user_fits[i];
        }
    }
    return NULL;
}

static bool cg_user_type_index(const CG *cg, const UserType *target, size_t *out_index) {
    if (cg == NULL || target == NULL || out_index == NULL) return false;
    for (size_t i = 0; i < cg->user_type_count; ++i) {
        if (&cg->user_types[i] == target) {
            *out_index = i;
            return true;
        }
    }
    return false;
}

static void cg_refresh_user_fit_targets(CG *cg) {
    if (cg == NULL) return;
    for (size_t i = 0; i < cg->user_fit_count; ++i) {
        UserFit *fit = &cg->user_fits[i];

        if (fit->target_index < cg->user_type_count) {
            fit->target = &cg->user_types[fit->target_index];
        }
    }
}

static void cg_refresh_user_fit_specs(CG *cg) {
    if (cg == NULL) return;
    for (size_t fit_index = 0; fit_index < cg->user_fit_count; ++fit_index) {
        UserFit *fit = &cg->user_fits[fit_index];

        for (size_t spec_index = 0; spec_index < fit->spec_count; ++spec_index) {
            if (fit->spec_indices != NULL &&
                fit->spec_indices[spec_index] < cg->user_spec_count) {
                fit->specs[spec_index] = &cg->user_specs[fit->spec_indices[spec_index]];
            }
        }
    }
}

static const UserSpec *cg_remap_user_spec_ptr(uintptr_t old_base,
                                              size_t old_count,
                                              const UserSpec *new_base,
                                              const UserSpec *ptr) {
    uintptr_t p;
    uintptr_t old_end;

    if (old_base == 0U || old_count == 0U || new_base == NULL || ptr == NULL) {
        return ptr;
    }
    p = (uintptr_t)ptr;
    old_end = old_base + old_count * sizeof(UserSpec);
    if (p < old_base || p >= old_end || ((p - old_base) % sizeof(UserSpec)) != 0U) {
        return ptr;
    }
    return &new_base[(p - old_base) / sizeof(UserSpec)];
}

static void cg_refresh_cgtype_user_specs(CGType *type,
                                         uintptr_t old_base,
                                         size_t old_count,
                                         const UserSpec *new_base) {
    if (type == NULL) return;
    if (type->kind == CG_TYPE_SPEC || type->kind == CG_TYPE_CALLABLE) {
        type->user_spec = cg_remap_user_spec_ptr(old_base,
                                                 old_count,
                                                 new_base,
                                                 type->user_spec);
    }
    cg_refresh_cgtype_user_specs(type->element, old_base, old_count, new_base);
}

static void cg_refresh_user_spec_references(CG *cg,
                                            uintptr_t old_base,
                                            size_t old_count) {
    if (cg == NULL || old_base == 0U || old_count == 0U) return;

    for (size_t i = 0; i < cg->extern_count; ++i) {
        ExternFn *fn = &cg->externs[i];
        for (size_t j = 0; j < fn->param_count; ++j) {
            cg_refresh_cgtype_user_specs(fn->param_types[j], old_base, old_count, cg->user_specs);
        }
        cg_refresh_cgtype_user_specs(fn->return_type, old_base, old_count, cg->user_specs);
    }
    for (size_t i = 0; i < cg->free_fn_count; ++i) {
        FreeFn *fn = &cg->free_fns[i];
        for (size_t j = 0; j < fn->param_count; ++j) {
            cg_refresh_cgtype_user_specs(fn->param_types[j], old_base, old_count, cg->user_specs);
        }
        cg_refresh_cgtype_user_specs(fn->return_type, old_base, old_count, cg->user_specs);
    }
    for (size_t i = 0; i < cg->user_type_count; ++i) {
        UserType *type = &cg->user_types[i];
        for (size_t j = 0; j < type->field_count; ++j) {
            cg_refresh_cgtype_user_specs(type->fields[j].type, old_base, old_count, cg->user_specs);
        }
        for (size_t j = 0; j < type->static_binding_count; ++j) {
            cg_refresh_cgtype_user_specs(type->static_bindings[j].type, old_base, old_count, cg->user_specs);
        }
        for (size_t j = 0; j < type->constructor_count; ++j) {
            UserMethod *method = &type->constructors[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_specs(method->param_types[k], old_base, old_count, cg->user_specs);
            }
            cg_refresh_cgtype_user_specs(method->return_type, old_base, old_count, cg->user_specs);
        }
        for (size_t j = 0; j < type->method_count; ++j) {
            UserMethod *method = &type->methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_specs(method->param_types[k], old_base, old_count, cg->user_specs);
            }
            cg_refresh_cgtype_user_specs(method->return_type, old_base, old_count, cg->user_specs);
        }
        for (size_t j = 0; j < type->static_method_count; ++j) {
            UserMethod *method = &type->static_methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_specs(method->param_types[k], old_base, old_count, cg->user_specs);
            }
            cg_refresh_cgtype_user_specs(method->return_type, old_base, old_count, cg->user_specs);
        }
    }
    for (size_t i = 0; i < cg->user_spec_count; ++i) {
        UserSpec *spec = &cg->user_specs[i];
        for (size_t j = 0; j < spec->member_count; ++j) {
            UserSpecMember *member = &spec->members[j];
            cg_refresh_cgtype_user_specs(member->type, old_base, old_count, cg->user_specs);
            for (size_t k = 0; k < member->param_count; ++k) {
                cg_refresh_cgtype_user_specs(member->param_types[k], old_base, old_count, cg->user_specs);
            }
        }
        cg_refresh_cgtype_user_specs(spec->callable_return_type, old_base, old_count, cg->user_specs);
        for (size_t j = 0; j < spec->callable_param_count; ++j) {
            cg_refresh_cgtype_user_specs(spec->callable_param_types[j], old_base, old_count, cg->user_specs);
        }
        for (size_t j = 0; j < spec->union_member_count; ++j) {
            cg_refresh_cgtype_user_specs(spec->union_member_types[j], old_base, old_count, cg->user_specs);
        }
    }
    for (size_t i = 0; i < cg->user_fit_count; ++i) {
        UserFit *fit = &cg->user_fits[i];
        for (size_t j = 0; j < fit->method_count; ++j) {
            UserMethod *method = &fit->methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_specs(method->param_types[k], old_base, old_count, cg->user_specs);
            }
            cg_refresh_cgtype_user_specs(method->return_type, old_base, old_count, cg->user_specs);
        }
    }
    for (size_t i = 0; i < cg->builtin_fit_count; ++i) {
        BuiltinFit *fit = &cg->builtin_fits[i];
        for (size_t j = 0; j < fit->spec_count; ++j) {
            fit->specs[j] = cg_remap_user_spec_ptr(old_base, old_count, cg->user_specs, fit->specs[j]);
        }
        for (size_t j = 0; j < fit->method_count; ++j) {
            UserMethod *method = &fit->methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_specs(method->param_types[k], old_base, old_count, cg->user_specs);
            }
            cg_refresh_cgtype_user_specs(method->return_type, old_base, old_count, cg->user_specs);
        }
    }
}

/* Mirror of cg_remap_user_spec_ptr for UserType pointers. After cg->user_types
 * is realloc'd, every borrowed UserType* that pointed into the old array becomes
 * dangling; this remaps such pointers to the same offset in the new array.
 * Pointers not within the old array range (e.g., &cg->user_types[0] captured
 * before any allocation, or NULL) are returned unchanged. */
static const UserType *cg_remap_user_type_ptr(uintptr_t old_base,
                                              size_t old_count,
                                              const UserType *new_base,
                                              const UserType *ptr) {
    uintptr_t p;
    uintptr_t old_end;

    if (old_base == 0U || old_count == 0U || new_base == NULL || ptr == NULL) {
        return ptr;
    }
    p = (uintptr_t)ptr;
    old_end = old_base + old_count * sizeof(UserType);
    if (p < old_base || p >= old_end || ((p - old_base) % sizeof(UserType)) != 0U) {
        return ptr;
    }
    return &new_base[(p - old_base) / sizeof(UserType)];
}

/* Mirror of cg_refresh_cgtype_user_specs for the CGType->user slot. Refreshes
 * type->user for CG_TYPE_OBJECT nodes (the only kind that borrows a UserType)
 * and recurses through type->element so arrays/pointers of user types are
 * remapped too. */
static void cg_refresh_cgtype_user_types(CGType *type,
                                         uintptr_t old_base,
                                         size_t old_count,
                                         const UserType *new_base) {
    if (type == NULL) return;
    if (type->kind == CG_TYPE_OBJECT) {
        type->user = cg_remap_user_type_ptr(old_base,
                                            old_count,
                                            new_base,
                                            type->user);
    }
    cg_refresh_cgtype_user_types(type->element, old_base, old_count, new_base);
}

/* Mirror of cg_refresh_user_spec_references for UserType pointers. After
 * cg->user_types is realloc'd, walks every CGType held by externs, free_fns,
 * user_types (fields, static_bindings, constructors, methods, static_methods),
 * user_specs (members, callable types, union types), user_fits (methods), and
 * builtin_fits (methods) to refresh type->user pointers. UserFit->target is
 * already refreshed by cg_refresh_user_fit_targets via target_index, so it is
 * not revisited here. */
static void cg_refresh_user_type_references(CG *cg,
                                            uintptr_t old_base,
                                            size_t old_count) {
    if (cg == NULL || old_base == 0U || old_count == 0U) return;

    for (size_t i = 0; i < cg->extern_count; ++i) {
        ExternFn *fn = &cg->externs[i];
        for (size_t j = 0; j < fn->param_count; ++j) {
            cg_refresh_cgtype_user_types(fn->param_types[j], old_base, old_count, cg->user_types);
        }
        cg_refresh_cgtype_user_types(fn->return_type, old_base, old_count, cg->user_types);
    }
    for (size_t i = 0; i < cg->free_fn_count; ++i) {
        FreeFn *fn = &cg->free_fns[i];
        for (size_t j = 0; j < fn->param_count; ++j) {
            cg_refresh_cgtype_user_types(fn->param_types[j], old_base, old_count, cg->user_types);
        }
        cg_refresh_cgtype_user_types(fn->return_type, old_base, old_count, cg->user_types);
    }
    for (size_t i = 0; i < cg->user_type_count; ++i) {
        UserType *type = &cg->user_types[i];
        for (size_t j = 0; j < type->field_count; ++j) {
            cg_refresh_cgtype_user_types(type->fields[j].type, old_base, old_count, cg->user_types);
        }
        for (size_t j = 0; j < type->static_binding_count; ++j) {
            type->static_bindings[j].owner_type = cg_remap_user_type_ptr(
                old_base,
                old_count,
                cg->user_types,
                type->static_bindings[j].owner_type);
            cg_refresh_cgtype_user_types(type->static_bindings[j].type, old_base, old_count, cg->user_types);
        }
        for (size_t j = 0; j < type->constructor_count; ++j) {
            UserMethod *method = &type->constructors[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_types(method->param_types[k], old_base, old_count, cg->user_types);
            }
            cg_refresh_cgtype_user_types(method->return_type, old_base, old_count, cg->user_types);
        }
        for (size_t j = 0; j < type->method_count; ++j) {
            UserMethod *method = &type->methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_types(method->param_types[k], old_base, old_count, cg->user_types);
            }
            cg_refresh_cgtype_user_types(method->return_type, old_base, old_count, cg->user_types);
        }
        for (size_t j = 0; j < type->static_method_count; ++j) {
            UserMethod *method = &type->static_methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_types(method->param_types[k], old_base, old_count, cg->user_types);
            }
            cg_refresh_cgtype_user_types(method->return_type, old_base, old_count, cg->user_types);
        }
    }
    for (size_t i = 0; i < cg->user_spec_count; ++i) {
        UserSpec *spec = &cg->user_specs[i];
        for (size_t j = 0; j < spec->member_count; ++j) {
            UserSpecMember *member = &spec->members[j];
            cg_refresh_cgtype_user_types(member->type, old_base, old_count, cg->user_types);
            for (size_t k = 0; k < member->param_count; ++k) {
                cg_refresh_cgtype_user_types(member->param_types[k], old_base, old_count, cg->user_types);
            }
        }
        cg_refresh_cgtype_user_types(spec->callable_return_type, old_base, old_count, cg->user_types);
        for (size_t j = 0; j < spec->callable_param_count; ++j) {
            cg_refresh_cgtype_user_types(spec->callable_param_types[j], old_base, old_count, cg->user_types);
        }
        for (size_t j = 0; j < spec->union_member_count; ++j) {
            cg_refresh_cgtype_user_types(spec->union_member_types[j], old_base, old_count, cg->user_types);
        }
    }
    for (size_t i = 0; i < cg->user_fit_count; ++i) {
        UserFit *fit = &cg->user_fits[i];
        for (size_t j = 0; j < fit->method_count; ++j) {
            UserMethod *method = &fit->methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_types(method->param_types[k], old_base, old_count, cg->user_types);
            }
            cg_refresh_cgtype_user_types(method->return_type, old_base, old_count, cg->user_types);
        }
    }
    for (size_t i = 0; i < cg->builtin_fit_count; ++i) {
        BuiltinFit *fit = &cg->builtin_fits[i];
        for (size_t j = 0; j < fit->method_count; ++j) {
            UserMethod *method = &fit->methods[j];
            for (size_t k = 0; k < method->param_count; ++k) {
                cg_refresh_cgtype_user_types(method->param_types[k], old_base, old_count, cg->user_types);
            }
            cg_refresh_cgtype_user_types(method->return_type, old_base, old_count, cg->user_types);
        }
    }
}

static const BuiltinFit *cg_find_builtin_fit_by_decl(const CG *cg,
                                                     const FengDecl *decl) {
    for (size_t i = 0; i < cg->builtin_fit_count; i++) {
        if (cg->builtin_fits[i].decl == decl) {
            return &cg->builtin_fits[i];
        }
    }
    return NULL;
}

static bool cg_ensure_callable_function_value(CG *cg, const UserSpec *spec,
                                              const FengDecl *function_decl,
                                              FengToken blame,
                                              const char **out_var) {
    const FreeFn *fn;

    if (out_var == NULL || spec == NULL || spec->form != FENG_SPEC_FORM_CALLABLE ||
        function_decl == NULL || function_decl->kind != FENG_DECL_FUNCTION) {
        return cg_fail(cg, blame,
            "CE0026", "codegen: invalid callable function-value request");
    }
    for (size_t i = 0; i < cg->callable_fn_value_count; ++i) {
        if (cg->callable_fn_values[i].spec == spec &&
            cg->callable_fn_values[i].function_decl == function_decl) {
            *out_var = cg->callable_fn_values[i].c_var;
            return true;
        }
    }

    fn = cg_find_free_fn_by_decl(cg, function_decl);
    if (fn == NULL) {
        return cg_fail(cg, blame,
            "CE0027", "codegen: callable value source function was not registered");
    }
    if (cg->callable_fn_value_count + 1 > cg->callable_fn_value_capacity) {
        size_t cap = cg->callable_fn_value_capacity ? cg->callable_fn_value_capacity * 2 : 4;
        void *grown = realloc(cg->callable_fn_values, cap * sizeof *cg->callable_fn_values);
        if (grown == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->callable_fn_values = grown;
        cg->callable_fn_value_capacity = cap;
    }

    char *fn_san = cg_sanitize(fn->c_name, strlen(fn->c_name));
    if (fn_san == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    Buf vb; buf_init(&vb);
    buf_append_fmt(&vb, "FengCallableValue__%s__%s", spec->c_closure_struct_name, fn_san);
    char *var_name = vb.data;

    Buf ab; buf_init(&ab);
    buf_append_fmt(&ab, "FengCallableInvoke__%s__%s", spec->c_closure_struct_name, fn_san);
    char *adapter_name = ab.data;
    free(fn_san);

    if (var_name == NULL || adapter_name == NULL) {
        free(var_name);
        free(adapter_name);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(&cg->headers,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->headers, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->headers,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs, " %s(void *_closure", adapter_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(&cg->witness_defs,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->witness_defs,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->witness_defs, ") {\n    (void)_closure;\n    ");
    if (spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "*(");
        cg_emit_c_type(&cg->witness_defs, spec->callable_return_type);
        buf_append_cstr(&cg->witness_defs, " *)_out = ");
    } else if (spec->callable_return_type != NULL &&
               spec->callable_return_type->kind != CG_TYPE_VOID) {
        buf_append_cstr(&cg->witness_defs, "return ");
    }
    buf_append_fmt(&cg->witness_defs, "%s(", fn->c_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        if (i > 0) buf_append_cstr(&cg->witness_defs, ", ");
        char arg_name[32];
        (void)snprintf(arg_name, sizeof arg_name, "_arg%zu", i);
        cg_append_callable_abi_argument_value(&cg->witness_defs,
                                              spec->callable_param_types[i],
                                              spec->callable_param_abi_kinds[i],
                                              arg_name);
    }
    buf_append_cstr(&cg->witness_defs, ");\n}\n\n");

    buf_append_fmt(&cg->statics,
        "static struct %s %s = {\n"
        "    ._hdr = { .desc = &%s, .tag = FENG_TYPE_TAG_CLOSURE, .refcount = FENG_REFCOUNT_IMMORTAL },\n"
        "    ._self = NULL,\n"
        "    .invoke = %s\n"
        "};\n",
        spec->c_closure_struct_name,
        var_name,
        spec->c_closure_desc_name,
        adapter_name);

    memset(&cg->callable_fn_values[cg->callable_fn_value_count],
           0,
           sizeof cg->callable_fn_values[cg->callable_fn_value_count]);
    cg->callable_fn_values[cg->callable_fn_value_count].spec = spec;
    cg->callable_fn_values[cg->callable_fn_value_count].function_decl = function_decl;
    cg->callable_fn_values[cg->callable_fn_value_count].c_var = var_name;
    cg->callable_fn_value_count += 1;

    free(adapter_name);
    *out_var = var_name;
    return true;
}

/* Emit or reuse the closed adapter and immortal callable value for one generic
 * top-level function surface. The adapter binds the same function descriptor
 * that owns its callable_value facet and invokes the provider shared body
 * directly; no runtime descriptor search or closure allocation is introduced. */
static bool cg_ensure_reified_callable_function_value(
    CG *cg,
    const UserSpec *spec,
    const GenericFn *function,
    const char *descriptor_c_name,
    FengTypeRef *const *type_args,
    size_t type_arg_count,
    FengToken blame,
    const char **out_var,
    const char **out_adapter) {
    const FengCallableSignature *signature;
    const UserSpec **constraint_specs = NULL;
    CGType **resolved_type_args = NULL;
    char **descriptor_exprs = NULL;
    bool *param_uses_address = NULL;
    char *adapter_name = NULL;
    char *var_name = NULL;
    bool ok = false;

    if (cg == NULL || spec == NULL ||
        spec->form != FENG_SPEC_FORM_CALLABLE || function == NULL ||
        function->decl == NULL || descriptor_c_name == NULL ||
        out_var == NULL || out_adapter == NULL) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: invalid reified callable function-value request");
    }
    *out_var = NULL;
    *out_adapter = NULL;
    signature = &function->decl->as.function_decl;
    if (type_arg_count != signature->type_param_count ||
        spec->callable_param_count != signature->param_count) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: reified callable function-value signature is inconsistent");
    }
    for (size_t index = 0U; index < cg->callable_fn_value_count; ++index) {
        if (cg->callable_fn_values[index].spec == spec &&
            cg->callable_fn_values[index].function_decl == function->decl &&
            cg->callable_fn_values[index].descriptor_c_name != NULL &&
            strcmp(cg->callable_fn_values[index].descriptor_c_name,
                   descriptor_c_name) == 0) {
            *out_var = cg->callable_fn_values[index].c_var;
            *out_adapter = cg->callable_fn_values[index].c_adapter_fn;
            return true;
        }
    }

    resolved_type_args = type_arg_count > 0U
        ? (CGType **)calloc(type_arg_count, sizeof(*resolved_type_args))
        : NULL;
    descriptor_exprs = type_arg_count > 0U
        ? (char **)calloc(type_arg_count, sizeof(*descriptor_exprs))
        : NULL;
    if ((type_arg_count > 0U &&
         (resolved_type_args == NULL || descriptor_exprs == NULL)) ||
        !cg_build_generic_param_constraints(cg,
                                            signature->type_params,
                                            signature->type_param_count,
                                            blame,
                                            &constraint_specs) ||
        !cg_build_shared_callable_param_address_flags(cg,
                                                      NULL,
                                                      signature,
                                                      function->owner_program,
                                                      blame,
                                                      &param_uses_address)) {
        if (!cg->failed) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        goto cleanup;
    }
    for (size_t index = 0U; index < type_arg_count; ++index) {
        if (!cg_resolve_type(cg,
                             type_args[index],
                             &blame,
                             &resolved_type_args[index]) ||
            !cg_generic_descriptor_expr(cg,
                                        resolved_type_args[index],
                                        constraint_specs[index],
                                        &blame,
                                        &descriptor_exprs[index])) {
            goto cleanup;
        }
    }

    {
        char *descriptor_san = cg_sanitize(descriptor_c_name,
                                           strlen(descriptor_c_name));
        Buf name;

        if (descriptor_san == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        buf_init(&name);
        buf_append_fmt(&name,
                       "FengCallableInvoke__%s__%s",
                       spec->c_closure_struct_name,
                       descriptor_san);
        adapter_name = name.data;
        buf_init(&name);
        buf_append_fmt(&name,
                       "FengCallableValue__%s__%s",
                       spec->c_closure_struct_name,
                       descriptor_san);
        var_name = name.data;
        free(descriptor_san);
    }
    if (adapter_name == NULL || var_name == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t index = 0U; index < spec->callable_param_count; ++index) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(&cg->headers,
                                        spec->callable_param_types[index],
                                        spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->headers, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(&cg->headers,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs, " %s(void *_closure", adapter_name);
    for (size_t index = 0U; index < spec->callable_param_count; ++index) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(&cg->witness_defs,
                                        spec->callable_param_types[index],
                                        spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(&cg->witness_defs,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->witness_defs, ") {\n    (void)_closure;\n");
    if (spec->callable_return_type != NULL &&
        spec->callable_return_type->kind != CG_TYPE_VOID &&
        spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "    ");
        cg_emit_c_type(&cg->witness_defs, spec->callable_return_type);
        buf_append_cstr(&cg->witness_defs, " _result;\n");
    }
    buf_append_fmt(&cg->witness_defs,
                   "    %s(&%s",
                   function->c_name,
                   descriptor_c_name);
    for (size_t index = 0U; index < type_arg_count; ++index) {
        buf_append_fmt(&cg->witness_defs, ", %s", descriptor_exprs[index]);
    }
    for (size_t index = 0U; index < spec->callable_param_count; ++index) {
        char arg_name[32];

        (void)snprintf(arg_name, sizeof arg_name, "_arg%zu", index);
        buf_append_cstr(&cg->witness_defs, ", ");
        if (param_uses_address[index]) {
            buf_append_fmt(&cg->witness_defs,
                           "%s%s",
                           spec->callable_param_abi_kinds[index] ==
                                   CG_CALLABLE_ABI_ADDRESS
                               ? ""
                               : "&",
                           arg_name);
        } else {
            cg_append_callable_abi_argument_value(
                &cg->witness_defs,
                spec->callable_param_types[index],
                spec->callable_param_abi_kinds[index],
                arg_name);
        }
    }
    if (spec->callable_return_type != NULL &&
        spec->callable_return_type->kind != CG_TYPE_VOID) {
        buf_append_fmt(&cg->witness_defs,
                       ", %s",
                       spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS
                           ? "_out"
                           : "&_result");
    }
    buf_append_cstr(&cg->witness_defs, ");\n");
    if (spec->callable_return_type != NULL &&
        spec->callable_return_type->kind != CG_TYPE_VOID &&
        spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "    return _result;\n");
    } else {
        buf_append_cstr(&cg->witness_defs, "    return;\n");
    }
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    buf_append_fmt(&cg->statics,
                   "static struct %s %s = {\n"
                   "    ._hdr = { .desc = &%s, .tag = FENG_TYPE_TAG_CLOSURE, "
                   ".refcount = FENG_REFCOUNT_IMMORTAL },\n"
                   "    ._self = NULL,\n"
                   "    .invoke = %s\n"
                   "};\n",
                   spec->c_closure_struct_name,
                   var_name,
                   spec->c_closure_desc_name,
                   adapter_name);

    if (cg->callable_fn_value_count == cg->callable_fn_value_capacity) {
        size_t new_capacity = cg->callable_fn_value_capacity == 0U
                                  ? 4U
                                  : cg->callable_fn_value_capacity * 2U;
        void *grown = realloc(cg->callable_fn_values,
                              new_capacity *
                                  sizeof(*cg->callable_fn_values));

        if (grown == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        cg->callable_fn_values = grown;
        cg->callable_fn_value_capacity = new_capacity;
    }
    memset(&cg->callable_fn_values[cg->callable_fn_value_count],
           0,
           sizeof cg->callable_fn_values[cg->callable_fn_value_count]);
    cg->callable_fn_values[cg->callable_fn_value_count].spec = spec;
    cg->callable_fn_values[cg->callable_fn_value_count].function_decl =
        function->decl;
    cg->callable_fn_values[cg->callable_fn_value_count].descriptor_c_name =
        strdup(descriptor_c_name);
    cg->callable_fn_values[cg->callable_fn_value_count].c_adapter_fn =
        adapter_name;
    cg->callable_fn_values[cg->callable_fn_value_count].c_var = var_name;
    if (cg->callable_fn_values[cg->callable_fn_value_count]
                .descriptor_c_name == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->callable_fn_value_count++;
    *out_var = var_name;
    *out_adapter = adapter_name;
    adapter_name = NULL;
    var_name = NULL;
    ok = true;

cleanup:
    for (size_t index = 0U; index < type_arg_count; ++index) {
        cgtype_free(resolved_type_args != NULL
                        ? resolved_type_args[index]
                        : NULL);
        free(descriptor_exprs != NULL ? descriptor_exprs[index] : NULL);
    }
    free(resolved_type_args);
    free(descriptor_exprs);
    free((void *)constraint_specs);
    free(param_uses_address);
    free(adapter_name);
    free(var_name);
    return ok;
}

/* Emit or reuse the adapter and immortal closure for one fully closed static
 * method source. The adapter calls the compile-time selected thin wrapper,
 * imported shared dispatch or builtin-fit entry and binds all descriptors as
 * constants; forming the Feng callable value performs no allocation or lookup. */
static bool cg_ensure_callable_static_method_value(
    CG *cg,
    const UserSpec *spec,
    const UserType *owner,
    const UserMethod *method,
    const BuiltinFit *builtin_fit,
    const UserFit *user_fit,
    const char *callee_c_name,
    const char *owner_descriptor_expr,
    bool uses_shared_dispatch,
    const char *descriptor_c_name,
    const char *const *method_descriptor_exprs,
    size_t method_descriptor_count,
    const bool *param_uses_address,
    FengToken blame,
    const char **out_var,
    const char **out_adapter) {
    const FengCallableSignature *signature;
    const FengDecl *fit_decl = builtin_fit != NULL
                                   ? builtin_fit->decl
                                   : (user_fit != NULL ? user_fit->decl : NULL);
    bool returns_value;
    bool passes_function_descriptor;
    bool provider_returns_via_out;
    char *adapter_name = NULL;
    char *var_name = NULL;

    if (cg == NULL || spec == NULL ||
        spec->form != FENG_SPEC_FORM_CALLABLE || method == NULL ||
        method->member == NULL || !method->member->is_static ||
        callee_c_name == NULL ||
        (uses_shared_dispatch && owner_descriptor_expr == NULL) ||
        descriptor_c_name == NULL || out_var == NULL || out_adapter == NULL ||
        (builtin_fit == NULL && owner == NULL)) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: invalid static callable method-value request");
    }
    *out_var = NULL;
    *out_adapter = NULL;
    signature = &method->member->as.callable;
    if (signature->param_count != spec->callable_param_count ||
        signature->type_param_count != method_descriptor_count ||
        (signature->param_count > 0U && param_uses_address == NULL) ||
        (method_descriptor_count > 0U &&
         method_descriptor_exprs == NULL)) {
        return cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: closed static method-value signature is inconsistent");
    }
    if (builtin_fit != NULL &&
        builtin_fit->target_type_param_count > 0U) {
        return cg_fail(
            cg,
            blame,
            "CE0144",
            "codegen: generic builtin static fit methods are not supported yet");
    }
    if (owner != NULL && owner->generic_context_type_param_count > 0U) {
        return cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: static method-value owner was not fully closed");
    }
    for (size_t index = 0U;
         index < cg->callable_static_method_value_count;
         ++index) {
        const CGCallableStaticMethodValueSupport *support =
            &cg->callable_static_method_values[index];

        if (support->spec == spec && support->member == method->member &&
            support->fit_decl == fit_decl &&
            strcmp(support->descriptor_c_name,
                   descriptor_c_name) == 0) {
            *out_var = support->c_var;
            *out_adapter = support->c_adapter_fn;
            return true;
        }
    }

    {
        char *descriptor_san = cg_sanitize(
            descriptor_c_name, strlen(descriptor_c_name));
        Buf name;

        if (descriptor_san == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_init(&name);
        buf_append_fmt(&name,
                       "FengCallableStaticInvoke__%s__%s",
                       spec->c_closure_struct_name,
                       descriptor_san);
        adapter_name = name.data;
        buf_init(&name);
        buf_append_fmt(&name,
                       "FengCallableStaticValue__%s__%s",
                       spec->c_closure_struct_name,
                       descriptor_san);
        var_name = name.data;
        free(descriptor_san);
    }
    if (adapter_name == NULL || var_name == NULL) {
        free(adapter_name);
        free(var_name);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t index = 0U;
         index < spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(&cg->headers,
                                        spec->callable_param_types[index],
                                        spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->headers, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(&cg->headers,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");

    returns_value = spec->callable_return_type != NULL &&
                    spec->callable_return_type->kind != CG_TYPE_VOID;
    passes_function_descriptor =
        uses_shared_dispatch || builtin_fit != NULL ||
        signature->type_param_count > 0U;
    provider_returns_via_out =
        returns_value &&
        (uses_shared_dispatch ||
         (builtin_fit != NULL
             ? cg_builtin_fit_return_uses_out(builtin_fit, method)
             : signature->type_param_count > 0U));

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs, " %s(void *_closure", adapter_name);
    for (size_t index = 0U;
         index < spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(&cg->witness_defs,
                                        spec->callable_param_types[index],
                                        spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(&cg->witness_defs,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->witness_defs, ") {\n    (void)_closure;\n");
    if (provider_returns_via_out &&
        spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "    ");
        cg_emit_c_type(&cg->witness_defs, spec->callable_return_type);
        buf_append_cstr(&cg->witness_defs, " _result;\n");
    }
    buf_append_cstr(&cg->witness_defs, "    ");
    if (!provider_returns_via_out && returns_value) {
        if (spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(&cg->witness_defs, "*(");
            cg_emit_c_type(&cg->witness_defs,
                           spec->callable_return_type);
            buf_append_cstr(&cg->witness_defs, " *)_out = ");
        } else {
            buf_append_cstr(&cg->witness_defs, "return ");
        }
    }
    buf_append_fmt(&cg->witness_defs, "%s(", callee_c_name);
    {
        bool has_argument = false;

        if (uses_shared_dispatch) {
            buf_append_cstr(&cg->witness_defs, owner_descriptor_expr);
            has_argument = true;
        }
        if (passes_function_descriptor) {
            if (has_argument) {
                buf_append_cstr(&cg->witness_defs, ", ");
            }
            buf_append_fmt(&cg->witness_defs,
                           "&%s",
                           descriptor_c_name);
            has_argument = true;
        }
        for (size_t index = 0U;
             index < method_descriptor_count;
             ++index) {
            if (has_argument) {
                buf_append_cstr(&cg->witness_defs, ", ");
            }
            buf_append_cstr(&cg->witness_defs,
                            method_descriptor_exprs[index]);
            has_argument = true;
        }
        for (size_t index = 0U;
             index < spec->callable_param_count;
             ++index) {
            char argument_name[32];

            if (has_argument) {
                buf_append_cstr(&cg->witness_defs, ", ");
            }
            (void)snprintf(argument_name,
                           sizeof argument_name,
                           "_arg%zu",
                           index);
            if (param_uses_address[index]) {
                buf_append_fmt(
                    &cg->witness_defs,
                    "%s%s",
                    spec->callable_param_abi_kinds[index] ==
                            CG_CALLABLE_ABI_ADDRESS
                        ? ""
                        : "&",
                    argument_name);
            } else {
                cg_append_callable_abi_argument_value(
                    &cg->witness_defs,
                    spec->callable_param_types[index],
                    spec->callable_param_abi_kinds[index],
                    argument_name);
            }
            has_argument = true;
        }
        if (provider_returns_via_out) {
            if (has_argument) {
                buf_append_cstr(&cg->witness_defs, ", ");
            }
            buf_append_cstr(
                &cg->witness_defs,
                spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS
                    ? "_out"
                    : "&_result");
        }
    }
    buf_append_cstr(&cg->witness_defs, ");\n");
    if (provider_returns_via_out &&
        spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "    return _result;\n");
    } else if (provider_returns_via_out || !returns_value) {
        buf_append_cstr(&cg->witness_defs, "    return;\n");
    }
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    buf_append_fmt(&cg->statics,
                   "static struct %s %s = {\n"
                   "    ._hdr = { .desc = &%s, .tag = FENG_TYPE_TAG_CLOSURE, "
                   ".refcount = FENG_REFCOUNT_IMMORTAL },\n"
                   "    ._self = NULL,\n"
                   "    .invoke = %s\n"
                   "};\n",
                   spec->c_closure_struct_name,
                   var_name,
                   spec->c_closure_desc_name,
                   adapter_name);

    if (cg->callable_static_method_value_count ==
        cg->callable_static_method_value_capacity) {
        size_t new_capacity =
            cg->callable_static_method_value_capacity == 0U
                ? 4U
                : cg->callable_static_method_value_capacity * 2U;
        CGCallableStaticMethodValueSupport *grown =
            (CGCallableStaticMethodValueSupport *)realloc(
                cg->callable_static_method_values,
                new_capacity * sizeof(*grown));

        if (grown == NULL) {
            free(adapter_name);
            free(var_name);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->callable_static_method_values = grown;
        cg->callable_static_method_value_capacity = new_capacity;
    }
    {
        CGCallableStaticMethodValueSupport *support =
            &cg->callable_static_method_values[
                cg->callable_static_method_value_count];

        memset(support, 0, sizeof(*support));
        support->spec = spec;
        support->member = method->member;
        support->fit_decl = fit_decl;
        support->descriptor_c_name = strdup(descriptor_c_name);
        support->c_adapter_fn = adapter_name;
        support->c_var = var_name;
        if (support->descriptor_c_name == NULL) {
            free(adapter_name);
            free(var_name);
            memset(support, 0, sizeof(*support));
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->callable_static_method_value_count++;
        *out_var = support->c_var;
        *out_adapter = support->c_adapter_fn;
    }
    return true;
}

/* Forward declaration for the shared spec-requirement ABI bridge emitted by
 * both receiver-bound and receiver-free method-value adapters. */
static void cg_emit_callable_spec_requirement_invoke(
    Buf *out,
    const UserSpec *target_spec,
    const UserSpecMember *method,
    const char *witness_expr,
    const char *subject_expr);

/* Emit or reuse the adapter and immortal closure for one closed static spec
 * requirement. The adapter binds a compile-time concrete type descriptor and
 * calls the exact witness slot selected by Semantic; formation performs no
 * allocation, member search, or runtime target selection. */
static bool cg_ensure_callable_spec_static_method_value(
    CG *cg,
    const UserSpec *target_spec,
    const UserSpec *receiver_spec,
    const UserSpecMember *method,
    const char *owner_descriptor_expr,
    const char *descriptor_c_name,
    FengToken blame,
    const char **out_var,
    const char **out_adapter) {
    char *adapter_name = NULL;
    char *var_name = NULL;

    if (cg == NULL || target_spec == NULL || receiver_spec == NULL ||
        method == NULL || method->member == NULL ||
        owner_descriptor_expr == NULL || descriptor_c_name == NULL ||
        out_var == NULL || out_adapter == NULL ||
        target_spec->form != FENG_SPEC_FORM_CALLABLE ||
        (receiver_spec->form != FENG_SPEC_FORM_OBJECT &&
         receiver_spec->form != FENG_SPEC_FORM_INTERSECTION) ||
        method->kind != USM_KIND_METHOD || !method->is_static ||
        target_spec->callable_param_count != method->param_count) {
        return cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: invalid constrained-generic static method-value request");
    }
    *out_var = NULL;
    *out_adapter = NULL;
    for (size_t index = 0U;
         index < cg->callable_static_method_value_count;
         ++index) {
        const CGCallableStaticMethodValueSupport *support =
            &cg->callable_static_method_values[index];

        if (support->spec == target_spec &&
            support->member == method->member &&
            support->fit_decl == NULL &&
            strcmp(support->descriptor_c_name,
                   descriptor_c_name) == 0) {
            *out_var = support->c_var;
            *out_adapter = support->c_adapter_fn;
            return true;
        }
    }

    {
        char *descriptor_san = cg_sanitize(
            descriptor_c_name, strlen(descriptor_c_name));
        Buf name;

        if (descriptor_san == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_init(&name);
        buf_append_fmt(&name,
                       "FengCallableSpecStaticInvoke__%s__%s",
                       target_spec->c_closure_struct_name,
                       descriptor_san);
        adapter_name = name.data;
        buf_init(&name);
        buf_append_fmt(&name,
                       "FengCallableSpecStaticValue__%s__%s",
                       target_spec->c_closure_struct_name,
                       descriptor_san);
        var_name = name.data;
        free(descriptor_san);
    }
    if (adapter_name == NULL || var_name == NULL) {
        free(adapter_name);
        free(var_name);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     target_spec->callable_return_type,
                                     target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(
            &cg->headers,
            target_spec->callable_param_types[index],
            target_spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->headers, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(
        &cg->headers, target_spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     target_spec->callable_return_type,
                                     target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs,
                   " %s(void *_closure",
                   adapter_name);
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(
            &cg->witness_defs,
            target_spec->callable_param_types[index],
            target_spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(
        &cg->witness_defs, target_spec->callable_return_abi_kind);
    buf_append_fmt(
        &cg->witness_defs,
        ") {\n"
        "    (void)_closure;\n"
        "    const struct %s *_witness = "
        "(const struct %s *)(%s)->witness;\n"
        "    ",
        receiver_spec->c_witness_struct_name,
        receiver_spec->c_witness_struct_name,
        owner_descriptor_expr);
    cg_emit_callable_spec_requirement_invoke(&cg->witness_defs,
                                             target_spec,
                                             method,
                                             "_witness",
                                             NULL);
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    buf_append_fmt(&cg->statics,
                   "static struct %s %s = {\n"
                   "    ._hdr = { .desc = &%s, .tag = FENG_TYPE_TAG_CLOSURE, "
                   ".refcount = FENG_REFCOUNT_IMMORTAL },\n"
                   "    ._self = NULL,\n"
                   "    .invoke = %s\n"
                   "};\n",
                   target_spec->c_closure_struct_name,
                   var_name,
                   target_spec->c_closure_desc_name,
                   adapter_name);

    if (cg->callable_static_method_value_count ==
        cg->callable_static_method_value_capacity) {
        size_t new_capacity =
            cg->callable_static_method_value_capacity == 0U
                ? 4U
                : cg->callable_static_method_value_capacity * 2U;
        CGCallableStaticMethodValueSupport *grown =
            (CGCallableStaticMethodValueSupport *)realloc(
                cg->callable_static_method_values,
                new_capacity * sizeof(*grown));

        if (grown == NULL) {
            free(adapter_name);
            free(var_name);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->callable_static_method_values = grown;
        cg->callable_static_method_value_capacity = new_capacity;
    }
    {
        CGCallableStaticMethodValueSupport *support =
            &cg->callable_static_method_values[
                cg->callable_static_method_value_count];

        memset(support, 0, sizeof(*support));
        support->spec = target_spec;
        support->member = method->member;
        support->descriptor_c_name = strdup(descriptor_c_name);
        support->c_adapter_fn = adapter_name;
        support->c_var = var_name;
        if (support->descriptor_c_name == NULL) {
            free(adapter_name);
            free(var_name);
            memset(support, 0, sizeof(*support));
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->callable_static_method_value_count++;
        *out_var = support->c_var;
        *out_adapter = support->c_adapter_fn;
    }
    return true;
}

/* Emit the callable adapter, one-allocation closure layout, and binder for a
 * fixed-layout value receiver. The receiver is copied into the closure's
 * inline payload; `_self` remains NULL solely to preserve the callable-form
 * common prefix used by ordinary callable invocation. */
/* Emit the invocation portion of a bound-method adapter. Ordinary methods keep
 * their existing direct call. Reified methods enter the provider shared body
 * with compile-time-bound owner/function/generic descriptors and preserve the
 * target callable-form ABI exactly. */
static void cg_emit_callable_method_target_invoke(
    Buf *out,
    const UserSpec *spec,
    const char *ordinary_target_fn,
    const CGReifiedCallableMethodTarget *reified_target) {
    bool returns_value = spec->callable_return_type != NULL &&
                         spec->callable_return_type->kind != CG_TYPE_VOID;

    if (reified_target == NULL) {
        buf_append_cstr(out, "    ");
        if (spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(out, "*(");
            cg_emit_c_type(out, spec->callable_return_type);
            buf_append_cstr(out, " *)_out = ");
        } else if (returns_value) {
            buf_append_cstr(out, "return ");
        }
        buf_append_fmt(out, "%s(_self", ordinary_target_fn);
        for (size_t index = 0U;
             index < spec->callable_param_count;
             ++index) {
            char arg_name[32];

            (void)snprintf(arg_name, sizeof arg_name, "_arg%zu", index);
            buf_append_cstr(out, ", ");
            cg_append_callable_abi_argument_value(
                out,
                spec->callable_param_types[index],
                spec->callable_param_abi_kinds[index],
                arg_name);
        }
        buf_append_cstr(out, ");\n");
        return;
    }

    if (returns_value &&
        spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "    ");
        cg_emit_c_type(out, spec->callable_return_type);
        buf_append_cstr(out, " _result;\n");
    }
    buf_append_fmt(out,
                   "    %s((void *)_self, %s, %s",
                   reified_target->shared_c_name,
                   reified_target->owner_descriptor_expr,
                   reified_target->function_descriptor_expr);
    for (size_t index = 0U;
         index < reified_target->method_descriptor_count;
         ++index) {
        buf_append_fmt(out,
                       ", %s",
                       reified_target->method_descriptor_exprs[index]);
    }
    for (size_t index = 0U; index < spec->callable_param_count; ++index) {
        char arg_name[32];

        (void)snprintf(arg_name, sizeof arg_name, "_arg%zu", index);
        buf_append_cstr(out, ", ");
        if (reified_target->param_uses_address[index]) {
            buf_append_fmt(out,
                           "%s%s",
                           spec->callable_param_abi_kinds[index] ==
                                   CG_CALLABLE_ABI_ADDRESS
                               ? ""
                               : "&",
                           arg_name);
        } else {
            cg_append_callable_abi_argument_value(
                out,
                spec->callable_param_types[index],
                spec->callable_param_abi_kinds[index],
                arg_name);
        }
    }
    if (returns_value) {
        buf_append_fmt(out,
                       ", %s",
                       spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS
                           ? "_out"
                           : "&_result");
    }
    buf_append_cstr(out, ");\n");
    if (returns_value &&
        spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "    return _result;\n");
    } else {
        buf_append_cstr(out, "    return;\n");
    }
}

static bool cg_emit_fixed_value_callable_method_support(
    CG *cg,
    const UserSpec *spec,
    const UserType *owner,
    const UserMethod *method,
    FengToken blame,
    const char *target_fn,
    const CGReifiedCallableMethodTarget *reified_target,
    const char *adapter_name,
    const char *bind_name,
    const char **out_closure_struct,
    const char **out_closure_desc) {
    char *closure_struct = NULL;
    char *closure_desc = NULL;
    CGType receiver_type;
    size_t receiver_pointer_slot_count;

    if (cg == NULL || spec == NULL || owner == NULL || method == NULL ||
        target_fn == NULL || adapter_name == NULL || bind_name == NULL ||
        out_closure_struct == NULL || out_closure_desc == NULL ||
        owner->c_struct_name == NULL || owner->c_aggregate_desc_name == NULL) {
        return cg_fail(cg, blame,
            "CE0028", "codegen: invalid fixed value callable method-value request");
    }

    memset(&receiver_type, 0, sizeof receiver_type);
    receiver_type.kind = CG_TYPE_OBJECT;
    receiver_type.user = owner;
    receiver_pointer_slot_count =
        cg_aggregate_pointer_slot_count(&receiver_type);

    {
        Buf name;

        buf_init(&name);
        buf_append_fmt(&name, "%s__ValueClosure", bind_name);
        closure_struct = name.data;
    }
    {
        Buf name;

        buf_init(&name);
        buf_append_fmt(&name, "%s__ValueClosureDesc", bind_name);
        closure_desc = name.data;
    }
    if (closure_struct == NULL || closure_desc == NULL) {
        free(closure_struct);
        free(closure_desc);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_fmt(&cg->type_defs,
                   "struct %s {\n"
                   "    FengManagedHeader _hdr;\n"
                   "    void *_self;\n    ",
                   closure_struct);
    cg_emit_callable_abi_return_type(&cg->type_defs,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_cstr(&cg->type_defs, " (*invoke)(void *_closure");
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->type_defs, ", ");
        cg_emit_callable_abi_param_type(&cg->type_defs,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
    }
    cg_append_callable_abi_out_parameter(&cg->type_defs,
                                         spec->callable_return_abi_kind);
    buf_append_fmt(&cg->type_defs,
                   ");\n    struct %s _receiver;\n};\n\n",
                   owner->c_struct_name);

    if (receiver_pointer_slot_count > 0U) {
        Buf receiver_base;

        buf_init(&receiver_base);
        buf_append_fmt(&receiver_base,
                       "offsetof(struct %s, _receiver)",
                       closure_struct);
        if (receiver_base.data == NULL) {
            free(closure_struct);
            free(closure_desc);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(&cg->type_defs,
                       "static void %s__release_children(void *_self) {\n"
                       "    struct %s *_o = (struct %s *)_self;\n"
                       "    feng_aggregate_release(&_o->_receiver, &%s);\n"
                       "}\n\n"
                       "static const FengManagedFieldDescriptor %s__managed_fields[] = {\n",
                       closure_desc,
                       closure_struct,
                       closure_struct,
                       owner->c_aggregate_desc_name,
                       closure_desc);
        cg_emit_aggregate_pointer_slot_rows(&cg->type_defs,
                                            receiver_base.data,
                                            &receiver_type);
        buf_append_cstr(&cg->type_defs, "};\n\n");
        buf_free(&receiver_base);
    }

    buf_append_fmt(&cg->type_defs,
                   "static const FengTypeDescriptor %s = {\n"
                   "    .name = \"%s\",\n"
                   "    .size = sizeof(struct %s),\n"
                   "    .default_zero_init = NULL,\n"
                   "    .finalizer = NULL,\n",
                   closure_desc,
                   closure_struct,
                   closure_struct);
    if (receiver_pointer_slot_count > 0U) {
        buf_append_fmt(&cg->type_defs,
                       "    .release_children = %s__release_children,\n"
                       "    .is_potentially_cyclic = true,\n"
                       "    .managed_field_count = %zu,\n"
                       "    .managed_fields = %s__managed_fields,\n",
                       closure_desc,
                       receiver_pointer_slot_count,
                       closure_desc);
    } else {
        buf_append_cstr(&cg->type_defs,
                        "    .release_children = NULL,\n"
                        "    .is_potentially_cyclic = false,\n"
                        "    .managed_field_count = 0,\n"
                        "    .managed_fields = NULL,\n");
    }
    buf_append_cstr(&cg->type_defs,
                    "    .equal_fn = NULL,\n"
                    "    .reified_generic_params_count = 0,\n"
                    "};\n\n");

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(&cg->headers,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->headers, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->headers,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");
    buf_append_fmt(&cg->headers,
                   "static struct %s *%s(struct %s *_self);\n",
                   spec->c_closure_struct_name,
                   bind_name,
                   owner->c_struct_name);

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs, " %s(void *_closure", adapter_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(&cg->witness_defs,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->witness_defs,
                                         spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs,
                   ") {\n    struct %s *_bound = (struct %s *)_closure;\n"
                   "    struct %s *_self = &_bound->_receiver;\n",
                   closure_struct,
                   closure_struct,
                   owner->c_struct_name);
    cg_emit_callable_method_target_invoke(&cg->witness_defs,
                                          spec,
                                          target_fn,
                                          reified_target);
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    buf_append_fmt(&cg->witness_defs,
                   "static struct %s *%s(struct %s *_self) {\n"
                   "    struct %s *_o = (struct %s *)feng_object_new(&%s);\n"
                   "    _o->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
                   "    _o->_self = NULL;\n"
                   "    _o->invoke = %s;\n",
                   spec->c_closure_struct_name,
                   bind_name,
                   owner->c_struct_name,
                   closure_struct,
                   closure_struct,
                   closure_desc,
                   adapter_name);
    if (receiver_pointer_slot_count > 0U) {
        buf_append_fmt(&cg->witness_defs,
                       "    feng_aggregate_default_init(&_o->_receiver, &%s);\n"
                       "    feng_aggregate_assign(&_o->_receiver, _self, &%s);\n",
                       owner->c_aggregate_desc_name,
                       owner->c_aggregate_desc_name);
    } else {
        buf_append_cstr(&cg->witness_defs,
                        "    _o->_receiver = *_self;\n");
    }
    buf_append_fmt(&cg->witness_defs,
                   "    return (struct %s *)_o;\n"
                   "}\n\n",
                   spec->c_closure_struct_name);

    *out_closure_struct = closure_struct;
    *out_closure_desc = closure_desc;
    return true;
}

static bool cg_ensure_callable_method_value(CG *cg, const UserSpec *spec,
                                            const UserType *owner,
                                            const UserMethod *method,
                                            FengToken blame,
                                            const char *target_fn,
                                            const CGReifiedCallableMethodTarget *reified_target,
                                            const char **out_bind_fn) {
    char *adapter_name = NULL;
    char *bind_name = NULL;
    const char *value_closure_struct = NULL;
    const char *value_closure_desc = NULL;

    if (out_bind_fn == NULL || spec == NULL || owner == NULL || method == NULL ||
        target_fn == NULL ||
        spec->form != FENG_SPEC_FORM_CALLABLE) {
        return cg_fail(cg, blame,
            "CE0028", "codegen: invalid callable method-value request");
    }
    for (size_t i = 0; i < cg->callable_method_value_count; ++i) {
        if (cg->callable_method_values[i].spec == spec &&
            cg->callable_method_values[i].owner == owner &&
            cg->callable_method_values[i].method == method &&
            strcmp(cg->callable_method_values[i].c_target_fn,
                   target_fn) == 0) {
            *out_bind_fn = cg->callable_method_values[i].c_bind_fn;
            return true;
        }
    }
    if (cg->callable_method_value_count + 1 > cg->callable_method_value_capacity) {
        size_t cap = cg->callable_method_value_capacity
                         ? cg->callable_method_value_capacity * 2
                         : 4;
        void *grown = realloc(cg->callable_method_values,
                              cap * sizeof *cg->callable_method_values);
        if (grown == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->callable_method_values = grown;
        cg->callable_method_value_capacity = cap;
    }

    {
        Buf ab; buf_init(&ab);
        buf_append_fmt(&ab, "FengCallableInvoke__%s__%s",
                       spec->c_closure_struct_name,
                       target_fn);
        adapter_name = ab.data;
    }
    {
        Buf bb; buf_init(&bb);
        buf_append_fmt(&bb, "FengCallableBind__%s__%s",
                       spec->c_closure_struct_name,
                       target_fn);
        bind_name = bb.data;
    }
    if (adapter_name == NULL || bind_name == NULL) {
        free(adapter_name);
        free(bind_name);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    if (cg_user_type_is_value_semantics(owner)) {
        if (!cg_emit_fixed_value_callable_method_support(cg,
                                                         spec,
                                                         owner,
                                                         method,
                                                         blame,
                                                         target_fn,
                                                         reified_target,
                                                         adapter_name,
                                                         bind_name,
                                                         &value_closure_struct,
                                                         &value_closure_desc)) {
            free(adapter_name);
            free(bind_name);
            return false;
        }
        goto record_callable_method_value;
    }

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(&cg->headers,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->headers, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->headers,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");
    buf_append_fmt(&cg->headers, "static struct %s *%s(struct %s *_self);\n",
                   spec->c_closure_struct_name,
                   bind_name,
                   owner->c_struct_name);

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs, " %s(void *_closure", adapter_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(&cg->witness_defs,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->witness_defs,
                                         spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs,
                   ") {\n    struct %s *_bound = (struct %s *)_closure;\n"
                   "    struct %s *_self = (struct %s *)_bound->_self;\n",
                   spec->c_closure_struct_name,
                   spec->c_closure_struct_name,
                   owner->c_struct_name,
                   owner->c_struct_name);
    cg_emit_callable_method_target_invoke(&cg->witness_defs,
                                          spec,
                                          target_fn,
                                          reified_target);
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    buf_append_fmt(&cg->witness_defs,
                   "static struct %s *%s(struct %s *_self) {\n"
                   "    struct %s *_o = (struct %s *)feng_object_new(&%s);\n"
                   "    _o->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
                   "    _o->_self = NULL;\n"
                   "    feng_assign(&_o->_self, (void *)_self);\n"
                   "    _o->invoke = %s;\n"
                   "    return _o;\n"
                   "}\n\n",
                   spec->c_closure_struct_name,
                   bind_name,
                   owner->c_struct_name,
                   spec->c_closure_struct_name,
                   spec->c_closure_struct_name,
                   spec->c_closure_desc_name,
                   adapter_name);

record_callable_method_value:
    memset(&cg->callable_method_values[cg->callable_method_value_count],
           0,
           sizeof cg->callable_method_values[cg->callable_method_value_count]);
    cg->callable_method_values[cg->callable_method_value_count].spec = spec;
    cg->callable_method_values[cg->callable_method_value_count].owner = owner;
    cg->callable_method_values[cg->callable_method_value_count].method = method;
    cg->callable_method_values[cg->callable_method_value_count].c_target_fn =
        strdup(target_fn);
    cg->callable_method_values[cg->callable_method_value_count].c_bind_fn = bind_name;
    cg->callable_method_values[cg->callable_method_value_count].c_adapter_fn =
        adapter_name;
    cg->callable_method_values[cg->callable_method_value_count].c_closure_struct =
        value_closure_struct != NULL
            ? (char *)value_closure_struct
            : strdup(spec->c_closure_struct_name);
    cg->callable_method_values[cg->callable_method_value_count].c_closure_desc =
        value_closure_desc != NULL
            ? (char *)value_closure_desc
            : strdup(spec->c_closure_desc_name);
    if (cg->callable_method_values[cg->callable_method_value_count]
                .c_target_fn == NULL ||
        cg->callable_method_values[cg->callable_method_value_count]
                .c_closure_struct == NULL ||
        cg->callable_method_values[cg->callable_method_value_count]
                .c_closure_desc == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    cg->callable_method_value_count += 1;

    *out_bind_fn = bind_name;
    return true;
}

/* Return generated method-value support after ensuring its adapter and
 * closure layout have been emitted. The returned entry is CG-owned. */
static const CGCallableMethodValueSupport *cg_callable_method_value_support(
    CG *cg,
    const UserSpec *spec,
    const UserType *owner,
    const UserMethod *method,
    FengToken blame,
    const char *target_fn,
    const CGReifiedCallableMethodTarget *reified_target) {
    const char *unused_bind_fn = NULL;

    if (!cg_ensure_callable_method_value(cg,
                                         spec,
                                         owner,
                                         method,
                                         blame,
                                         target_fn,
                                         reified_target,
                                         &unused_bind_fn)) {
        return NULL;
    }
    for (size_t index = 0U;
         index < cg->callable_method_value_count;
         ++index) {
        const CGCallableMethodValueSupport *support =
            &cg->callable_method_values[index];

        if (support->spec == spec && support->owner == owner &&
            support->method == method &&
            strcmp(support->c_target_fn, target_fn) == 0) {
            return support;
        }
    }
    (void)cg_fail(cg,
                  blame,
                  "IE0002",
                  "codegen: callable method-value support was not retained");
    return NULL;
}

/* Emit one already-selected spec requirement call while bridging the source
 * witness ABI to the target callable-form ABI. Instance requirements prepend
 * their subject; static requirements intentionally leave it absent. */
static void cg_emit_callable_spec_requirement_invoke(
    Buf *out,
    const UserSpec *target_spec,
    const UserSpecMember *method,
    const char *witness_expr,
    const char *subject_expr) {
    if (target_spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS &&
        method->value_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "*(");
        cg_emit_c_type(out, target_spec->callable_return_type);
        buf_append_cstr(out, " *)_out = ");
    } else if (target_spec->callable_return_abi_kind !=
                   CG_CALLABLE_ABI_ADDRESS &&
               method->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        cg_emit_c_type(out, target_spec->callable_return_type);
        buf_append_cstr(out, " _result;\n    ");
    } else if (target_spec->callable_return_type != NULL &&
               target_spec->callable_return_type->kind != CG_TYPE_VOID &&
               target_spec->callable_return_abi_kind !=
                   CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "return ");
    }

    bool has_argument = false;

    buf_append_fmt(out,
                   "%s->%s(",
                   witness_expr,
                   method->c_field_name);
    if (!method->is_static) {
        buf_append_cstr(out, subject_expr);
        has_argument = true;
    }
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        char argument_name[32];

        (void)snprintf(argument_name,
                       sizeof(argument_name),
                       "_arg%zu",
                       index);
        if (has_argument) {
            buf_append_cstr(out, ", ");
        }
        cg_append_callable_abi_bridge_argument(
            out,
            method->param_types[index],
            target_spec->callable_param_abi_kinds[index],
            method->param_abi_kinds[index],
            argument_name);
        has_argument = true;
    }
    if (method->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        if (has_argument) {
            buf_append_cstr(out, ", ");
        }
        buf_append_cstr(
            out,
            target_spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS
                ? "_out"
                : "&_result");
    }
    buf_append_cstr(out, ");\n");
    if (target_spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS &&
        method->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "    return _result;\n");
    }
}

/* Emit and cache the one-allocation closure support for an object-form or
 * intersection-form spec method value. The generated closure preserves the
 * canonical callable prefix, retains only the subject, and borrows the
 * immutable witness pointer selected at formation. No runtime member lookup or
 * ABI extension is needed. */
static bool cg_ensure_callable_spec_method_value(
    CG *cg,
    const UserSpec *target_spec,
    const UserSpec *receiver_spec,
    const UserSpecMember *method,
    FengToken blame,
    const char **out_bind_fn) {
    char *adapter_name = NULL;
    char *bind_name = NULL;
    char *closure_struct = NULL;
    char *closure_desc = NULL;
    size_t support_index;

    if (cg == NULL || target_spec == NULL || receiver_spec == NULL ||
        method == NULL || method->member == NULL || out_bind_fn == NULL ||
        target_spec->form != FENG_SPEC_FORM_CALLABLE ||
        (receiver_spec->form != FENG_SPEC_FORM_OBJECT &&
         receiver_spec->form != FENG_SPEC_FORM_INTERSECTION) ||
        method->kind != USM_KIND_METHOD || method->is_static ||
        target_spec->callable_param_count != method->param_count) {
        return cg_fail(cg,
                       blame,
                       "CE0111",
                       "codegen: invalid spec method-value request");
    }

    for (support_index = 0U;
         support_index < cg->callable_spec_method_value_count;
         ++support_index) {
        const CGCallableSpecMethodValueSupport *support =
            &cg->callable_spec_method_values[support_index];

        if (support->target_spec == target_spec &&
            support->receiver_spec == receiver_spec &&
            support->member == method->member) {
            *out_bind_fn = support->c_bind_fn;
            return true;
        }
    }

    if (cg->callable_spec_method_value_count + 1U >
        cg->callable_spec_method_value_capacity) {
        size_t capacity = cg->callable_spec_method_value_capacity != 0U
                              ? cg->callable_spec_method_value_capacity * 2U
                              : 4U;
        void *grown = realloc(cg->callable_spec_method_values,
                              capacity *
                                  sizeof(*cg->callable_spec_method_values));

        if (grown == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->callable_spec_method_values = grown;
        cg->callable_spec_method_value_capacity = capacity;
    }

    support_index = cg->callable_spec_method_value_count;
    {
        Buf name;

        buf_init(&name);
        buf_append_fmt(&name,
                       "FengSpecMethodValueInvoke__%s__%s__%s__%zu",
                       target_spec->c_closure_struct_name,
                       receiver_spec->c_witness_struct_name,
                       method->c_field_name,
                       support_index);
        adapter_name = name.data;

        buf_init(&name);
        buf_append_fmt(&name,
                       "FengSpecMethodValueBind__%s__%s__%s__%zu",
                       target_spec->c_closure_struct_name,
                       receiver_spec->c_witness_struct_name,
                       method->c_field_name,
                       support_index);
        bind_name = name.data;

        buf_init(&name);
        buf_append_fmt(&name, "%s__Closure", bind_name);
        closure_struct = name.data;

        buf_init(&name);
        buf_append_fmt(&name, "%s__ClosureDesc", bind_name);
        closure_desc = name.data;
    }
    if (adapter_name == NULL || bind_name == NULL || closure_struct == NULL ||
        closure_desc == NULL) {
        free(adapter_name);
        free(bind_name);
        free(closure_struct);
        free(closure_desc);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_fmt(&cg->type_defs,
                   "struct %s {\n"
                   "    FengManagedHeader _hdr;\n"
                   "    void *_self;\n    ",
                   closure_struct);
    cg_emit_callable_abi_return_type(&cg->type_defs,
                                     target_spec->callable_return_type,
                                     target_spec->callable_return_abi_kind);
    buf_append_cstr(&cg->type_defs, " (*invoke)(void *_closure");
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->type_defs, ", ");
        cg_emit_callable_abi_param_type(
            &cg->type_defs,
            target_spec->callable_param_types[index],
            target_spec->callable_param_abi_kinds[index]);
    }
    cg_append_callable_abi_out_parameter(
        &cg->type_defs, target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->type_defs,
                   ");\n"
                   "    const struct %s *_witness;\n"
                   "};\n\n"
                   "static void %s__release_children(void *_self) {\n"
                   "    struct %s *_o = (struct %s *)_self;\n"
                   "    feng_release(_o->_self);\n"
                   "    _o->_self = NULL;\n"
                   "}\n\n"
                   "static const FengManagedFieldDescriptor "
                   "%s__managed_fields[] = {\n"
                   "    { offsetof(struct %s, _self), NULL, NULL },\n"
                   "};\n\n"
                   "static const FengTypeDescriptor %s = {\n"
                   "    .name = \"%s\",\n"
                   "    .size = sizeof(struct %s),\n"
                   "    .default_zero_init = NULL,\n"
                   "    .finalizer = NULL,\n"
                   "    .release_children = %s__release_children,\n"
                   "    .is_potentially_cyclic = true,\n"
                   "    .managed_field_count = 1,\n"
                   "    .managed_fields = %s__managed_fields,\n"
                   "    .equal_fn = NULL,\n"
                   "    .reified_generic_params_count = 0,\n"
                   "};\n\n",
                   receiver_spec->c_witness_struct_name,
                   closure_desc,
                   closure_struct,
                   closure_struct,
                   closure_desc,
                   closure_struct,
                   closure_desc,
                   closure_struct,
                   closure_struct,
                   closure_desc,
                   closure_desc);

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     target_spec->callable_return_type,
                                     target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(
            &cg->headers,
            target_spec->callable_param_types[index],
            target_spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->headers, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(
        &cg->headers, target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers,
                   ");\n"
                   "static struct %s *%s(const struct %s *_receiver);\n",
                   target_spec->c_closure_struct_name,
                   bind_name,
                   receiver_spec->c_value_struct_name);

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     target_spec->callable_return_type,
                                     target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs, " %s(void *_closure", adapter_name);
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(
            &cg->witness_defs,
            target_spec->callable_param_types[index],
            target_spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(
        &cg->witness_defs, target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs,
                   ") {\n"
                   "    struct %s *_bound = (struct %s *)_closure;\n"
                   "    ",
                   closure_struct,
                   closure_struct);

    cg_emit_callable_spec_requirement_invoke(&cg->witness_defs,
                                             target_spec,
                                             method,
                                             "_bound->_witness",
                                             "_bound->_self");
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    buf_append_fmt(&cg->witness_defs,
                   "static struct %s *%s(const struct %s *_receiver) {\n"
                   "    struct %s *_o = "
                   "(struct %s *)feng_object_new(&%s);\n"
                   "    _o->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
                   "    _o->_self = NULL;\n"
                   "    feng_assign(&_o->_self, _receiver->subject);\n"
                   "    _o->invoke = %s;\n"
                   "    _o->_witness = _receiver->witness;\n"
                   "    return (struct %s *)_o;\n"
                   "}\n\n",
                   target_spec->c_closure_struct_name,
                   bind_name,
                   receiver_spec->c_value_struct_name,
                   closure_struct,
                   closure_struct,
                   closure_desc,
                   adapter_name,
                   target_spec->c_closure_struct_name);

    {
        CGCallableSpecMethodValueSupport *support =
            &cg->callable_spec_method_values[
                cg->callable_spec_method_value_count++];

        memset(support, 0, sizeof(*support));
        support->target_spec = target_spec;
        support->receiver_spec = receiver_spec;
        support->member = method->member;
        support->c_bind_fn = bind_name;
        support->c_adapter_fn = adapter_name;
        support->c_closure_struct = closure_struct;
        support->c_closure_desc = closure_desc;
    }
    *out_bind_fn = bind_name;
    return true;
}

/* Emit or reuse the closed adapter and closure layout for one method value
 * whose source receiver remains an erased object/intersection-constrained
 * generic parameter in the shared body. The concrete descriptor fixes the
 * witness and layout, so the shared body only performs the ordinary receiver
 * copy into one closure. */
static const CGCallableGenericSpecMethodValueSupport *
cg_ensure_callable_generic_spec_method_value(
    CG *cg,
    const UserSpec *target_spec,
    const UserSpec *receiver_spec,
    const UserSpecMember *method,
    const CGType *receiver_type,
    const char *receiver_descriptor_expr,
    const char *descriptor_c_name,
    FengToken blame) {
    CGValueKind receiver_kind;
    bool has_inline_receiver;
    size_t pointer_slot_count = 0U;
    char *aggregate_descriptor_expr = NULL;
    char *adapter_name = NULL;
    char *closure_struct = NULL;
    char *closure_desc = NULL;
    CGCallableGenericSpecMethodValueSupport *support;

    if (cg == NULL || target_spec == NULL || receiver_spec == NULL ||
        method == NULL || method->member == NULL || receiver_type == NULL ||
        receiver_descriptor_expr == NULL || descriptor_c_name == NULL ||
        target_spec->form != FENG_SPEC_FORM_CALLABLE ||
        (receiver_spec->form != FENG_SPEC_FORM_OBJECT &&
         receiver_spec->form != FENG_SPEC_FORM_INTERSECTION) ||
        method->kind != USM_KIND_METHOD || method->is_static ||
        target_spec->callable_param_count != method->param_count) {
        (void)cg_fail(cg,
                      blame,
                      "CE0111",
                      "codegen: invalid constrained-generic method-value request");
        return NULL;
    }

    for (size_t index = 0U;
         index < cg->callable_generic_spec_method_value_count;
         ++index) {
        support = &cg->callable_generic_spec_method_values[index];
        if (support->target_spec == target_spec &&
            support->receiver_spec == receiver_spec &&
            support->member == method->member &&
            strcmp(support->descriptor_c_name,
                   descriptor_c_name) == 0) {
            return support;
        }
    }

    receiver_kind = cgtype_value_kind(receiver_type);
    has_inline_receiver = receiver_kind != CG_VK_MANAGED_POINTER;
    if (receiver_kind == CG_VK_AGGREGATE) {
        const char *aggregate_descriptor_name =
            cg_aggregate_desc_name(receiver_type);
        Buf expression;

        if (aggregate_descriptor_name == NULL) {
            (void)cg_fail(cg,
                          blame,
                          "CE0066",
                          "codegen: constrained-generic aggregate receiver requires a closed descriptor");
            return NULL;
        }
        buf_init(&expression);
        buf_append_fmt(&expression,
                       "&%s",
                       aggregate_descriptor_name);
        aggregate_descriptor_expr = expression.data;
        pointer_slot_count =
            cg_aggregate_pointer_slot_count(receiver_type);
    }

    {
        Buf name;

        buf_init(&name);
        buf_append_fmt(&name,
                       "FengGenericSpecMethodValueInvoke__%s",
                       descriptor_c_name);
        adapter_name = name.data;
        if (has_inline_receiver) {
            buf_init(&name);
            buf_append_fmt(&name,
                           "FengGenericSpecMethodValueClosure__%s",
                           descriptor_c_name);
            closure_struct = name.data;
            buf_init(&name);
            buf_append_fmt(&name,
                           "FengGenericSpecMethodValueClosureDesc__%s",
                           descriptor_c_name);
            closure_desc = name.data;
        } else {
            closure_struct = strdup(target_spec->c_closure_struct_name);
            closure_desc = strdup(target_spec->c_closure_desc_name);
        }
    }
    if (adapter_name == NULL || closure_struct == NULL ||
        closure_desc == NULL) {
        free(aggregate_descriptor_expr);
        free(adapter_name);
        free(closure_struct);
        free(closure_desc);
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        return NULL;
    }

    if (has_inline_receiver) {
        buf_append_fmt(&cg->type_defs,
                       "struct %s {\n"
                       "    FengManagedHeader _hdr;\n"
                       "    void *_self;\n    ",
                       closure_struct);
        cg_emit_callable_abi_return_type(&cg->type_defs,
                                         target_spec->callable_return_type,
                                         target_spec->callable_return_abi_kind);
        buf_append_cstr(&cg->type_defs, " (*invoke)(void *_closure");
        for (size_t index = 0U;
             index < target_spec->callable_param_count;
             ++index) {
            buf_append_cstr(&cg->type_defs, ", ");
            cg_emit_callable_abi_param_type(
                &cg->type_defs,
                target_spec->callable_param_types[index],
                target_spec->callable_param_abi_kinds[index]);
        }
        cg_append_callable_abi_out_parameter(
            &cg->type_defs, target_spec->callable_return_abi_kind);
        buf_append_cstr(&cg->type_defs, ");\n    ");
        cg_emit_c_type(&cg->type_defs, receiver_type);
        buf_append_cstr(&cg->type_defs, " _receiver;\n};\n\n");

        if (pointer_slot_count > 0U) {
            Buf receiver_base;

            buf_init(&receiver_base);
            buf_append_fmt(&receiver_base,
                           "offsetof(struct %s, _receiver)",
                           closure_struct);
            buf_append_fmt(&cg->type_defs,
                           "static void %s__release_children(void *_self) {\n"
                           "    struct %s *_o = (struct %s *)_self;\n"
                           "    feng_aggregate_release(&_o->_receiver, %s);\n"
                           "}\n\n"
                           "static const FengManagedFieldDescriptor "
                           "%s__managed_fields[] = {\n",
                           closure_desc,
                           closure_struct,
                           closure_struct,
                           aggregate_descriptor_expr,
                           closure_desc);
            cg_emit_aggregate_pointer_slot_rows(&cg->type_defs,
                                                receiver_base.data,
                                                receiver_type);
            buf_append_cstr(&cg->type_defs, "};\n\n");
            buf_free(&receiver_base);
        }

        buf_append_fmt(&cg->type_defs,
                       "static const FengTypeDescriptor %s = {\n"
                       "    .name = \"%s\",\n"
                       "    .size = sizeof(struct %s),\n"
                       "    .default_zero_init = NULL,\n"
                       "    .finalizer = NULL,\n",
                       closure_desc,
                       closure_struct,
                       closure_struct);
        if (pointer_slot_count > 0U) {
            buf_append_fmt(&cg->type_defs,
                           "    .release_children = %s__release_children,\n"
                           "    .is_potentially_cyclic = true,\n"
                           "    .managed_field_count = %zu,\n"
                           "    .managed_fields = %s__managed_fields,\n",
                           closure_desc,
                           pointer_slot_count,
                           closure_desc);
        } else {
            buf_append_cstr(&cg->type_defs,
                            "    .release_children = NULL,\n"
                            "    .is_potentially_cyclic = false,\n"
                            "    .managed_field_count = 0,\n"
                            "    .managed_fields = NULL,\n");
        }
        buf_append_cstr(&cg->type_defs,
                        "    .equal_fn = NULL,\n"
                        "    .reified_generic_params_count = 0,\n"
                        "};\n\n");
    }

    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     target_spec->callable_return_type,
                                     target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers,
                   " %s(void *_closure",
                   adapter_name);
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(
            &cg->headers,
            target_spec->callable_param_types[index],
            target_spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->headers, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(
        &cg->headers, target_spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     target_spec->callable_return_type,
                                     target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs,
                   " %s(void *_closure",
                   adapter_name);
    for (size_t index = 0U;
         index < target_spec->callable_param_count;
         ++index) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(
            &cg->witness_defs,
            target_spec->callable_param_types[index],
            target_spec->callable_param_abi_kinds[index]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", index);
    }
    cg_append_callable_abi_out_parameter(
        &cg->witness_defs, target_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs,
                   ") {\n"
                   "    struct %s *_bound = (struct %s *)_closure;\n"
                   "    const struct %s *_witness = "
                   "(const struct %s *)(%s)->witness;\n"
                   "    ",
                   closure_struct,
                   closure_struct,
                   receiver_spec->c_witness_struct_name,
                   receiver_spec->c_witness_struct_name,
                   receiver_descriptor_expr);
    cg_emit_callable_spec_requirement_invoke(
        &cg->witness_defs,
        target_spec,
        method,
        "_witness",
        has_inline_receiver ? "&_bound->_receiver" : "_bound->_self");
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    if (cg->callable_generic_spec_method_value_count ==
        cg->callable_generic_spec_method_value_capacity) {
        size_t capacity =
            cg->callable_generic_spec_method_value_capacity == 0U
                ? 4U
                : cg->callable_generic_spec_method_value_capacity * 2U;
        void *grown = realloc(
            cg->callable_generic_spec_method_values,
            capacity * sizeof(*cg->callable_generic_spec_method_values));

        if (grown == NULL) {
            free(aggregate_descriptor_expr);
            free(adapter_name);
            free(closure_struct);
            free(closure_desc);
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            return NULL;
        }
        cg->callable_generic_spec_method_values = grown;
        cg->callable_generic_spec_method_value_capacity = capacity;
    }
    support = &cg->callable_generic_spec_method_values[
        cg->callable_generic_spec_method_value_count++];
    memset(support, 0, sizeof(*support));
    support->target_spec = target_spec;
    support->receiver_spec = receiver_spec;
    support->member = method->member;
    support->descriptor_c_name = strdup(descriptor_c_name);
    support->c_adapter_fn = adapter_name;
    support->c_closure_struct = closure_struct;
    support->c_closure_desc = closure_desc;
    support->has_inline_receiver = has_inline_receiver;
    free(aggregate_descriptor_expr);
    if (support->descriptor_c_name == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        return NULL;
    }
    return support;
}

/* ---- Generic registry helpers (G6) ---- */

static bool cg_register_generic_fn(CG *cg, const FengDecl *decl) {
    const FengCallableSignature *sig = &decl->as.function_decl;
    if (cg->generic_fn_count + 1 > cg->generic_fn_capacity) {
        size_t cap = cg->generic_fn_capacity ? cg->generic_fn_capacity * 2 : 4;
        void *p = realloc(cg->generic_fns, cap * sizeof *cg->generic_fns);
        if (!p) return false;
        cg->generic_fns = p;
        cg->generic_fn_capacity = cap;
    }
    GenericFn *gf = &cg->generic_fns[cg->generic_fn_count];
    memset(gf, 0, sizeof *gf);
    char *feng_n = malloc(sig->name.length + 1);
    if (!feng_n) return false;
    memcpy(feng_n, sig->name.data, sig->name.length);
    feng_n[sig->name.length] = '\0';
    gf->feng_name = feng_n;
    gf->c_name = cg_fn_mangle(cg->module_mangle, &sig->name);
    if (!gf->c_name) { free(feng_n); return false; }
    gf->type_param_count = sig->type_param_count;
    if (sig->type_param_count > 0) {
        gf->type_param_names = calloc(sig->type_param_count, sizeof(char *));
        if (!gf->type_param_names) { free(feng_n); free(gf->c_name); return false; }
        for (size_t i = 0; i < sig->type_param_count; i++) {
            const FengSlice tp_name = sig->type_params[i].name;
            const FengSlice *tp = &tp_name;
            char *s = malloc(tp->length + 1);
            if (!s) {
                for (size_t j = 0; j < i; j++) free(gf->type_param_names[j]);
                free(gf->type_param_names);
                free(feng_n); free(gf->c_name);
                return false;
            }
            memcpy(s, tp->data, tp->length);
            s[tp->length] = '\0';
            gf->type_param_names[i] = s;
        }
    }
    gf->decl = decl;
    gf->owner_program = cg->cur_program;
    cg->generic_fn_count++;

    /* Append overload-aware param-type suffix to c_name, matching the scheme
     * used by non-generic functions and type methods (e.g. string.format).
     * We temporarily activate generic-fn state so that cg_resolve_type maps
     * type parameters to CG_TYPE_GENERIC_PARAM correctly. */
    if (sig->param_count > 0U) {
        bool saved_in_generic_fn = cg->in_generic_fn;
        size_t saved_tp_count = cg->generic_fn_type_param_count;
        char **saved_tp_names = cg->generic_fn_type_param_names;
        const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
        const char **saved_tp_descs = cg->generic_fn_type_param_descs;

        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count = gf->type_param_count;
        cg->generic_fn_type_param_names = gf->type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = NULL;

        CGType **ptypes = calloc(sig->param_count, sizeof *ptypes);
        bool resolve_ok = (ptypes != NULL);
        if (resolve_ok) {
            for (size_t i = 0; i < sig->param_count; i++) {
                if (!cg_resolve_type(cg, sig->params[i].type,
                                     &sig->params[i].token, &ptypes[i])) {
                    resolve_ok = false;
                    break;
                }
            }
        }
        if (resolve_ok) {
            bool is_variadic = sig->params[sig->param_count - 1U].is_variadic;
            gf->c_name = cg_append_param_suffix(gf->c_name, ptypes,
                                                sig->param_count, is_variadic,
                                                true);
        }
        if (ptypes) {
            for (size_t i = 0; i < sig->param_count; i++) {
                cgtype_free(ptypes[i]);
            }
            free(ptypes);
        }

        cg->in_generic_fn = saved_in_generic_fn;
        cg->generic_fn_type_param_count = saved_tp_count;
        cg->generic_fn_type_param_names = saved_tp_names;
        cg->generic_fn_type_param_constraints = saved_tp_constraints;
        cg->generic_fn_type_param_descs = saved_tp_descs;

        if (!gf->c_name) return false;
    } else {
        /* No params — append __from__void suffix for consistency. */
        gf->c_name = cg_append_param_suffix(gf->c_name, NULL, 0U, false, true);
        if (!gf->c_name) return false;
    }

    return true;
}

static const GenericFn *cg_find_generic_fn_by_decl(const CG *cg, const FengDecl *decl) {
    for (size_t i = 0; i < cg->generic_fn_count; i++) {
        if (cg->generic_fns[i].decl == decl) return &cg->generic_fns[i];
    }
    return NULL;
}

static bool cg_register_generic_type_decl(CG *cg, const FengDecl *decl) {
    if (cg->generic_type_decl_count + 1 > cg->generic_type_decl_capacity) {
        size_t cap = cg->generic_type_decl_capacity ? cg->generic_type_decl_capacity * 2 : 4;
        void *p = realloc(cg->generic_type_decls, cap * sizeof *cg->generic_type_decls);
        if (!p) return false;
        cg->generic_type_decls = p;
        cg->generic_type_decl_capacity = cap;
    }
    cg->generic_type_decls[cg->generic_type_decl_count].decl = decl;
    cg->generic_type_decls[cg->generic_type_decl_count].owner_program = cg->cur_program;
    cg->generic_type_decl_count++;
    return true;
}

static bool cg_register_generic_spec_decl(CG *cg, const FengDecl *decl) {
    if (cg->generic_spec_decl_count + 1 > cg->generic_spec_decl_capacity) {
        size_t cap = cg->generic_spec_decl_capacity ? cg->generic_spec_decl_capacity * 2 : 4;
        void *p = realloc(cg->generic_spec_decls, cap * sizeof *cg->generic_spec_decls);
        if (!p) return false;
        cg->generic_spec_decls = p;
        cg->generic_spec_decl_capacity = cap;
    }
    cg->generic_spec_decls[cg->generic_spec_decl_count].decl = decl;
    cg->generic_spec_decls[cg->generic_spec_decl_count].owner_program = cg->cur_program;
    cg->generic_spec_decl_count++;
    return true;
}

typedef struct CGTypeParamScope {
    const FengTypeParam *first;
    size_t first_count;
    const FengTypeParam *second;
    size_t second_count;
} CGTypeParamScope;

static bool cg_type_param_scope_copy_names(const CGTypeParamScope *scope,
                                           char ***out_names,
                                           size_t *out_count) {
    size_t count = 0;
    char **names = NULL;

    *out_names = NULL;
    *out_count = 0;
    if (scope == NULL) return true;
    count = scope->first_count + scope->second_count;
    if (count == 0U) return true;
    names = calloc(count, sizeof *names);
    if (names == NULL) return false;
    for (size_t i = 0; i < scope->first_count; ++i) {
        names[i] = strndup(scope->first[i].name.data, scope->first[i].name.length);
        if (names[i] == NULL) {
            cg_free_cstr_array(names, i);
            return false;
        }
    }
    for (size_t i = 0; i < scope->second_count; ++i) {
        size_t index = scope->first_count + i;
        names[index] = strndup(scope->second[i].name.data, scope->second[i].name.length);
        if (names[index] == NULL) {
            cg_free_cstr_array(names, index);
            return false;
        }
    }
    *out_names = names;
    *out_count = count;
    return true;
}

/* Resolve both segments of a generic scope under one stable ordered context.
 * Constraints in the callable segment may therefore reference parameters from
 * the owner segment while preserving the existing descriptor slot order. */
static bool cg_type_param_scope_build_constraints(CG *cg,
                                                  const CGTypeParamScope *scope,
                                                  FengToken blame,
                                                  const UserSpec ***out_constraints) {
    FengTypeParam *combined_params = NULL;
    size_t count = 0U;
    bool ok;

    *out_constraints = NULL;
    if (scope == NULL) return true;
    count = scope->first_count + scope->second_count;
    if (count == 0U) return true;

    combined_params = calloc(count, sizeof *combined_params);
    if (combined_params == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (scope->first_count > 0U) {
        memcpy(combined_params,
               scope->first,
               scope->first_count * sizeof *combined_params);
    }
    if (scope->second_count > 0U) {
        memcpy(combined_params + scope->first_count,
               scope->second,
               scope->second_count * sizeof *combined_params);
    }
    ok = cg_build_generic_param_constraints(cg,
                                            combined_params,
                                            count,
                                            blame,
                                            out_constraints);
    free(combined_params);
    return ok;
}

static bool cg_type_param_context_equal(char *const *left,
                                        size_t left_count,
                                        char *const *right,
                                        size_t right_count) {
    if (left_count != right_count) return false;
    for (size_t i = 0; i < left_count; ++i) {
        const char *l = left ? left[i] : NULL;
        const char *r = right ? right[i] : NULL;
        if (l == NULL || r == NULL || strcmp(l, r) != 0) return false;
    }
    return true;
}

static bool cg_type_ref_contains_type_param_names(const FengTypeRef *ref,
                                                  char *const *names,
                                                  size_t name_count) {
    if (ref == NULL || names == NULL || name_count == 0U) return false;
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED:
            if (ref->as.named.segment_count == 1U &&
                ref->as.named.type_arg_count == 0U) {
                const FengSlice seg = ref->as.named.segments[0];
                for (size_t i = 0; i < name_count; ++i) {
                    if (names[i] != NULL && strlen(names[i]) == seg.length &&
                        memcmp(names[i], seg.data, seg.length) == 0) {
                        return true;
                    }
                }
            }
            for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                if (cg_type_ref_contains_type_param_names(ref->as.named.type_args[i],
                                                          names,
                                                          name_count)) {
                    return true;
                }
            }
            return false;
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return cg_type_ref_contains_type_param_names(ref->as.inner, names, name_count);
    }
    return false;
}

static bool cg_type_param_scope_contains(const CGTypeParamScope *scope,
                                         FengSlice name) {
    if (scope == NULL) return false;
    for (size_t i = 0; i < scope->first_count; ++i) {
        if (cg_module_segments_equal(&scope->first[i].name, 1U, &name, 1U)) {
            return true;
        }
    }
    for (size_t i = 0; i < scope->second_count; ++i) {
        if (cg_module_segments_equal(&scope->second[i].name, 1U, &name, 1U)) {
            return true;
        }
    }
    return false;
}

/**
 * Extend a possibly two-part generic scope with one nested declaration scope.
 *
 * CGTypeParamScope keeps the common owner/member pair without allocation. If
 * the incoming scope already uses both parts, its parameters are shallowly
 * flattened into an owned prefix so another nested scope can be appended.
 * The referenced FengTypeParam declarations remain owned by their ASTs.
 */
static bool cg_type_param_scope_extend(
    const CGTypeParamScope *base,
    const FengTypeParam *nested,
    size_t nested_count,
    CGTypeParamScope *out_scope,
    FengTypeParam **out_owned_prefix) {
    CGTypeParamScope empty = {0};
    size_t prefix_count;

    if (out_scope == NULL || out_owned_prefix == NULL) {
        return false;
    }
    *out_owned_prefix = NULL;
    *out_scope = base != NULL ? *base : empty;
    if (nested_count == 0U) {
        return true;
    }
    if (out_scope->second_count == 0U) {
        out_scope->second = nested;
        out_scope->second_count = nested_count;
        return true;
    }

    prefix_count = out_scope->first_count + out_scope->second_count;
    FengTypeParam *prefix = prefix_count > 0U
        ? calloc(prefix_count, sizeof(*prefix))
        : NULL;
    if (prefix_count > 0U && prefix == NULL) {
        return false;
    }
    if (out_scope->first_count > 0U) {
        memcpy(prefix,
               out_scope->first,
               out_scope->first_count * sizeof(*prefix));
    }
    if (out_scope->second_count > 0U) {
        memcpy(prefix + out_scope->first_count,
               out_scope->second,
               out_scope->second_count * sizeof(*prefix));
    }
    out_scope->first = prefix;
    out_scope->first_count = prefix_count;
    out_scope->second = nested;
    out_scope->second_count = nested_count;
    *out_owned_prefix = prefix;
    return true;
}

static bool cg_type_ref_contains_type_param(const FengTypeRef *ref,
                                            const CGTypeParamScope *scope) {
    if (ref == NULL || scope == NULL) return false;
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED:
            if (ref->as.named.segment_count == 1U &&
                ref->as.named.type_arg_count == 0U &&
                cg_type_param_scope_contains(scope, ref->as.named.segments[0])) {
                return true;
            }
            for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                if (cg_type_ref_contains_type_param(ref->as.named.type_args[i], scope)) {
                    return true;
                }
            }
            return false;
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return cg_type_ref_contains_type_param(ref->as.inner, scope);
    }
    return false;
}

/* Return whether a declaration slot is the generic parameter itself rather
 * than a fixed-representation wrapper such as Ref<T>, T[], or T*. */
static bool cg_callable_type_ref_is_direct_param(
    const FengTypeRef *ref,
    const CGTypeParamScope *scope) {
    return ref != NULL && scope != NULL &&
           ref->kind == FENG_TYPE_REF_NAMED &&
           ref->as.named.segment_count == 1U &&
           ref->as.named.type_arg_count == 0U &&
           cg_type_param_scope_contains(scope, ref->as.named.segments[0]);
}

/* Classify one callable declaration slot before generic substitution. A
 * direct T can close to any Feng representation and therefore uses address
 * ABI. A known managed-reference or pointer wrapper has fixed pointer
 * representation and can use erased pointer ABI. Every other generic-
 * dependent by-value family uses address ABI even when its current closed
 * instance happens to have fixed size, because its C nominal type differs
 * between open and closed instances. */
static CGCallableABIKind cg_callable_decl_slot_abi_kind(
    const FengTypeRef *declared_type,
    const CGTypeParamScope *scope,
    const CGType *resolved_type) {
    if (!cg_type_ref_contains_type_param(declared_type, scope)) {
        return CG_CALLABLE_ABI_DIRECT;
    }
    if (cg_callable_type_ref_is_direct_param(declared_type, scope)) {
        return CG_CALLABLE_ABI_ADDRESS;
    }
    if (resolved_type != NULL) {
        if (resolved_type->kind == CG_TYPE_ARRAY ||
            resolved_type->kind == CG_TYPE_CALLABLE ||
            resolved_type->kind == CG_TYPE_POINTER) {
            return CG_CALLABLE_ABI_ERASED_POINTER;
        }
        if (resolved_type->kind == CG_TYPE_OBJECT &&
            !cg_type_is_value_semantics(resolved_type)) {
            return CG_CALLABLE_ABI_ERASED_POINTER;
        }
    }
    return CG_CALLABLE_ABI_ADDRESS;
}

static FengTypeRef *cg_type_ref_clone(const FengTypeRef *ref) {
    if (ref == NULL) return NULL;
    FengTypeRef *clone = calloc(1U, sizeof *clone);
    if (!clone) return NULL;
    clone->token = ref->token;
    clone->kind = ref->kind;
    clone->array_element_writable = ref->array_element_writable;
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED:
            clone->as.named.segment_count = ref->as.named.segment_count;
            clone->as.named.type_arg_count = ref->as.named.type_arg_count;
            if (ref->as.named.segment_count > 0U) {
                clone->as.named.segments = malloc(sizeof(FengSlice) * ref->as.named.segment_count);
                if (!clone->as.named.segments) { free(clone); return NULL; }
                memcpy(clone->as.named.segments, ref->as.named.segments,
                       sizeof(FengSlice) * ref->as.named.segment_count);
            }
            if (ref->as.named.type_arg_count > 0U) {
                clone->as.named.type_args = calloc(ref->as.named.type_arg_count,
                                                   sizeof(FengTypeRef *));
                if (!clone->as.named.type_args) {
                    free(clone->as.named.segments);
                    free(clone);
                    return NULL;
                }
                for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                    clone->as.named.type_args[i] = cg_type_ref_clone(ref->as.named.type_args[i]);
                    if (!clone->as.named.type_args[i]) {
                        for (size_t j = 0; j < i; ++j) free(clone->as.named.type_args[j]);
                        free(clone->as.named.type_args);
                        free(clone->as.named.segments);
                        free(clone);
                        return NULL;
                    }
                }
            }
            return clone;
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            clone->as.inner = cg_type_ref_clone(ref->as.inner);
            if (!clone->as.inner) { free(clone); return NULL; }
            return clone;
    }
    free(clone);
    return NULL;
}

static void cg_type_ref_free(FengTypeRef *ref) {
    if (ref == NULL) return;
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED:
            for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                cg_type_ref_free(ref->as.named.type_args[i]);
            }
            free(ref->as.named.type_args);
            free(ref->as.named.segments);
            break;
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            cg_type_ref_free(ref->as.inner);
            break;
    }
    free(ref);
}

static FengTypeRef *cg_type_ref_from_cgtype(const CG *cg,
                                            const CGType *type,
                                            FengToken token) {
    FengTypeRef *ref;
    FengSlice segment;
    const char *builtin_name = NULL;

    if (type == NULL) return NULL;

    if (type->kind == CG_TYPE_GENERIC_PARAM) {
        const char *type_param_name = cg_generic_param_name(cg,
                                                            type->generic_param_index);

        if (type_param_name == NULL) {
            return NULL;
        }
        ref = calloc(1U, sizeof *ref);
        if (ref == NULL) return NULL;
        ref->token = token;
        ref->kind = FENG_TYPE_REF_NAMED;
        ref->as.named.segment_count = 1U;
        ref->as.named.segments = calloc(1U, sizeof *ref->as.named.segments);
        if (ref->as.named.segments == NULL) {
            free(ref);
            return NULL;
        }
        ref->as.named.segments[0].data = type_param_name;
        ref->as.named.segments[0].length = strlen(type_param_name);
        return ref;
    }

    /* Enum CGTypes use the i32 storage kind but retain a nominal declaration.
     * Preserve that identity before considering ordinary builtin kinds so
     * reified generic dependencies select the enum's own witness/descriptor. */
    if (type->enum_decl != NULL &&
        type->enum_decl->kind == FENG_DECL_ENUM) {
        ref = calloc(1U, sizeof *ref);
        if (ref == NULL) return NULL;
        ref->token = token;
        ref->kind = FENG_TYPE_REF_NAMED;
        ref->as.named.segment_count = 1U;
        ref->as.named.segments = calloc(1U, sizeof *ref->as.named.segments);
        if (ref->as.named.segments == NULL) {
            free(ref);
            return NULL;
        }
        ref->as.named.segments[0] = type->enum_decl->as.enum_decl.name;
        return ref;
    }

    for (size_t i = 0; i < sizeof k_builtin_types / sizeof k_builtin_types[0]; ++i) {
        if (k_builtin_types[i].kind == type->kind) {
            builtin_name = k_builtin_types[i].name;
            break;
        }
    }

    if (builtin_name != NULL) {
        ref = calloc(1U, sizeof *ref);
        if (ref == NULL) return NULL;
        ref->token = token;
        ref->kind = FENG_TYPE_REF_NAMED;
        ref->as.named.segment_count = 1U;
        ref->as.named.segments = calloc(1U, sizeof *ref->as.named.segments);
        if (ref->as.named.segments == NULL) {
            free(ref);
            return NULL;
        }
        ref->as.named.segments[0].data = builtin_name;
        ref->as.named.segments[0].length = strlen(builtin_name);
        return ref;
    }

    if (type->kind == CG_TYPE_POINTER && type->element != NULL) {
        ref = calloc(1U, sizeof *ref);
        if (ref == NULL) return NULL;
        ref->token = token;
        ref->kind = FENG_TYPE_REF_POINTER;
        ref->as.inner = cg_type_ref_from_cgtype(cg, type->element, token);
        if (ref->as.inner == NULL) {
            free(ref);
            return NULL;
        }
        return ref;
    }

    if (type->kind == CG_TYPE_ARRAY && type->element != NULL) {
        ref = calloc(1U, sizeof *ref);
        if (ref == NULL) return NULL;
        ref->token = token;
        ref->kind = FENG_TYPE_REF_ARRAY;
        ref->array_element_writable = type->array_element_writable;
        ref->as.inner = cg_type_ref_from_cgtype(cg, type->element, token);
        if (ref->as.inner == NULL) {
            free(ref);
            return NULL;
        }
        return ref;
    }

    if ((type->kind == CG_TYPE_SPEC || type->kind == CG_TYPE_CALLABLE) &&
        type->user_spec != NULL && type->user_spec->decl != NULL &&
        type->user_spec->decl->kind == FENG_DECL_SPEC) {
        ref = calloc(1U, sizeof *ref);
        if (ref == NULL) return NULL;
        ref->token = token;
        ref->kind = FENG_TYPE_REF_NAMED;
        ref->as.named.segment_count = 1U;
        ref->as.named.segments = calloc(1U, sizeof *ref->as.named.segments);
        if (ref->as.named.segments == NULL) {
            free(ref);
            return NULL;
        }
        segment = type->user_spec->decl->as.spec_decl.name;
        ref->as.named.segments[0] = segment;
        if (type->user_spec->is_generic_instance) {
            ref->as.named.type_arg_count = type->user_spec->generic_type_arg_count;
            ref->as.named.type_args = calloc(ref->as.named.type_arg_count,
                                             sizeof *ref->as.named.type_args);
            if (ref->as.named.type_arg_count > 0U && ref->as.named.type_args == NULL) {
                cg_type_ref_free(ref);
                return NULL;
            }
            for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                ref->as.named.type_args[i] =
                    cg_type_ref_clone(type->user_spec->generic_type_args[i]);
                if (ref->as.named.type_args[i] == NULL) {
                    cg_type_ref_free(ref);
                    return NULL;
                }
            }
        }
        return ref;
    }

    if (type->kind != CG_TYPE_OBJECT || type->user == NULL || type->user->decl == NULL ||
        type->user->decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }

    ref = calloc(1U, sizeof *ref);
    if (ref == NULL) return NULL;
    ref->token = token;
    ref->kind = FENG_TYPE_REF_NAMED;
    ref->as.named.segment_count = 1U;
    ref->as.named.segments = calloc(1U, sizeof *ref->as.named.segments);
    if (ref->as.named.segments == NULL) {
        free(ref);
        return NULL;
    }
    segment = type->user->decl->as.type_decl.name;
    ref->as.named.segments[0] = segment;
    if (type->user->is_generic_instance) {
        ref->as.named.type_arg_count = type->user->generic_type_arg_count;
        ref->as.named.type_args = calloc(ref->as.named.type_arg_count,
                                         sizeof *ref->as.named.type_args);
        if (ref->as.named.type_arg_count > 0U && ref->as.named.type_args == NULL) {
            cg_type_ref_free(ref);
            return NULL;
        }
        for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
            ref->as.named.type_args[i] = cg_type_ref_clone(type->user->generic_type_args[i]);
            if (ref->as.named.type_args[i] == NULL) {
                cg_type_ref_free(ref);
                return NULL;
            }
        }
    }
    return ref;
}

static FengTypeRef *cg_type_ref_substitute(const FengTypeRef *ref,
                                           const FengTypeParam *type_params,
                                           size_t type_param_count,
                                           FengTypeRef *const *type_args) {
    if (ref == NULL) return NULL;
    if (ref->kind == FENG_TYPE_REF_NAMED &&
        ref->as.named.segment_count == 1U &&
        ref->as.named.type_arg_count == 0U) {
        for (size_t i = 0; i < type_param_count; ++i) {
            if (cg_module_segments_equal(&ref->as.named.segments[0], 1U,
                                         &type_params[i].name, 1U)) {
                return cg_type_ref_clone(type_args[i]);
            }
        }
    }

    FengTypeRef *clone = cg_type_ref_clone(ref);
    if (!clone) return NULL;
    if (clone->kind == FENG_TYPE_REF_NAMED) {
        for (size_t i = 0; i < clone->as.named.type_arg_count; ++i) {
            FengTypeRef *sub = cg_type_ref_substitute(ref->as.named.type_args[i],
                                                      type_params,
                                                      type_param_count,
                                                      type_args);
            if (!sub) { cg_type_ref_free(clone); return NULL; }
            cg_type_ref_free(clone->as.named.type_args[i]);
            clone->as.named.type_args[i] = sub;
        }
    } else if (clone->kind == FENG_TYPE_REF_POINTER ||
               clone->kind == FENG_TYPE_REF_ARRAY) {
        FengTypeRef *sub = cg_type_ref_substitute(ref->as.inner,
                                                  type_params,
                                                  type_param_count,
                                                  type_args);
        if (!sub) { cg_type_ref_free(clone); return NULL; }
        cg_type_ref_free(clone->as.inner);
        clone->as.inner = sub;
    }
    return clone;
}

static bool cg_type_ref_equal(const FengTypeRef *left, const FengTypeRef *right) {
    if (left == right) return true;
    if (left == NULL || right == NULL || left->kind != right->kind) return false;
    if (left->kind == FENG_TYPE_REF_ARRAY &&
        left->array_element_writable != right->array_element_writable) {
        return false;
    }
    switch (left->kind) {
        case FENG_TYPE_REF_NAMED:
            if (left->as.named.segment_count != right->as.named.segment_count ||
                left->as.named.type_arg_count != right->as.named.type_arg_count) {
                return false;
            }
            for (size_t i = 0; i < left->as.named.segment_count; ++i) {
                if (!cg_module_segments_equal(&left->as.named.segments[i], 1U,
                                              &right->as.named.segments[i], 1U)) {
                    return false;
                }
            }
            for (size_t i = 0; i < left->as.named.type_arg_count; ++i) {
                if (!cg_type_ref_equal(left->as.named.type_args[i],
                                       right->as.named.type_args[i])) {
                    return false;
                }
            }
            return true;
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return cg_type_ref_equal(left->as.inner, right->as.inner);
    }
    return false;
}

/* Recursively qualifies declaration-backed type names from the program that
 * owns the source reference. Field templates use their declaring program so
 * imported closed generics keep the same display type in every artifact. */
static FengTypeRef *cg_debug_qualify_type_ref_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program) {
    FengTypeRef *result;

    if (ref == NULL) return NULL;

    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED: {
            FengSlice decl_name = {0};
            const FengProgram *owner =
                cg_type_ref_decl_identity_from_program(cg,
                                                       ref,
                                                       reference_program,
                                                       &decl_name);

            result = calloc(1U, sizeof *result);
            if (result == NULL) return NULL;
            result->token = ref->token;
            result->kind = FENG_TYPE_REF_NAMED;

            if (owner != NULL && owner->module_segment_count > 0U) {
                size_t mod_count = owner->module_segment_count;
                size_t total = mod_count + 1U;
                result->as.named.segment_count = total;
                result->as.named.segments =
                    calloc(total, sizeof *result->as.named.segments);
                if (result->as.named.segments == NULL) {
                    free(result);
                    return NULL;
                }
                for (size_t i = 0; i < mod_count; ++i) {
                    result->as.named.segments[i] = owner->module_segments[i];
                }
                result->as.named.segments[mod_count] = decl_name;
            } else {
                result->as.named.segment_count = ref->as.named.segment_count;
                result->as.named.segments =
                    calloc(ref->as.named.segment_count,
                           sizeof *result->as.named.segments);
                if (ref->as.named.segment_count > 0U &&
                    result->as.named.segments == NULL) {
                    free(result);
                    return NULL;
                }
                for (size_t i = 0; i < ref->as.named.segment_count; ++i) {
                    result->as.named.segments[i] = ref->as.named.segments[i];
                }
            }

            if (ref->as.named.type_arg_count > 0U) {
                result->as.named.type_arg_count = ref->as.named.type_arg_count;
                result->as.named.type_args =
                    calloc(ref->as.named.type_arg_count,
                           sizeof *result->as.named.type_args);
                if (result->as.named.type_args == NULL) {
                    cg_type_ref_free(result);
                    return NULL;
                }
                for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                    result->as.named.type_args[i] =
                        cg_debug_qualify_type_ref_from_program(
                            cg,
                            ref->as.named.type_args[i],
                            reference_program);
                    if (result->as.named.type_args[i] == NULL) {
                        cg_type_ref_free(result);
                        return NULL;
                    }
                }
            }
            return result;
        }
        case FENG_TYPE_REF_POINTER:
            result = calloc(1U, sizeof *result);
            if (result == NULL) return NULL;
            result->token = ref->token;
            result->kind = FENG_TYPE_REF_POINTER;
            result->as.inner = cg_debug_qualify_type_ref_from_program(
                cg,
                ref->as.inner,
                reference_program);
            if (result->as.inner == NULL) { free(result); return NULL; }
            return result;
        case FENG_TYPE_REF_ARRAY:
            result = calloc(1U, sizeof *result);
            if (result == NULL) return NULL;
            result->token = ref->token;
            result->kind = FENG_TYPE_REF_ARRAY;
            result->array_element_writable = ref->array_element_writable;
            result->as.inner = cg_debug_qualify_type_ref_from_program(
                cg,
                ref->as.inner,
                reference_program);
            if (result->as.inner == NULL) { free(result); return NULL; }
            return result;
    }
    return cg_type_ref_clone(ref);
}

/* Qualifies a type reference from the program currently being emitted. */
static FengTypeRef *cg_debug_qualify_type_ref(const CG *cg,
                                              const FengTypeRef *ref) {
    return cg_debug_qualify_type_ref_from_program(
        cg,
        ref,
        cg != NULL ? cg->cur_program : NULL);
}

static void cg_append_type_ref_display(Buf *out, const FengTypeRef *ref) {
    if (ref == NULL) { buf_append_cstr(out, "<unknown>"); return; }
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED:
            for (size_t i = 0; i < ref->as.named.segment_count; ++i) {
                if (i) buf_append_cstr(out, ".");
                buf_append(out, ref->as.named.segments[i].data,
                           ref->as.named.segments[i].length);
            }
            if (ref->as.named.type_arg_count > 0U) {
                buf_append_cstr(out, "<");
                for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                    if (i) buf_append_cstr(out, ", ");
                    cg_append_type_ref_display(out, ref->as.named.type_args[i]);
                }
                buf_append_cstr(out, ">");
            }
            break;
        case FENG_TYPE_REF_POINTER:
            cg_append_type_ref_display(out, ref->as.inner);
            buf_append_cstr(out, "*");
            break;
        case FENG_TYPE_REF_ARRAY:
            cg_append_type_ref_display(out, ref->as.inner);
            buf_append_cstr(out, ref->array_element_writable ? "[!]" : "[]");
            break;
    }
}

/* Find a generic type using the source program that owns the reference. */
static const GenericTypeDecl *cg_find_generic_type_decl_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program) {
    const GenericTypeDecl *visible = NULL;

    if (ref == NULL || ref->kind != FENG_TYPE_REF_NAMED) {
        return NULL;
    }

    for (size_t i = 0; i < cg->generic_type_decl_count; ++i) {
        const GenericTypeDecl *entry = &cg->generic_type_decls[i];
        const FengDecl *decl = entry->decl;

        if (decl == NULL || decl->kind != FENG_DECL_TYPE ||
            entry->owner_program == NULL ||
            !cg_named_type_ref_targets_owner_program_from(
                cg,
                reference_program,
                ref,
                entry->owner_program,
                decl->visibility,
                decl->as.type_decl.name)) {
            continue;
        }
        if (decl->as.type_decl.type_param_count != ref->as.named.type_arg_count) {
            continue;
        }
        if (reference_program != NULL &&
            entry->owner_program == reference_program) {
            return entry;
        }
        if (visible == NULL) {
            visible = entry;
        }
    }
    return visible;
}

/* Find a generic type from the program currently being emitted. */
static const GenericTypeDecl *cg_find_generic_type_decl(const CG *cg,
                                                        const FengTypeRef *ref) {
    return cg_find_generic_type_decl_from_program(
        cg, ref, cg != NULL ? cg->cur_program : NULL);
}

static const GenericTypeDecl *cg_find_generic_type_decl_by_decl(CG *cg,
                                                                const FengDecl *decl) {
    for (size_t i = 0; i < cg->generic_type_decl_count; ++i) {
        if (cg->generic_type_decls[i].decl == decl) {
            return &cg->generic_type_decls[i];
        }
    }
    return NULL;
}

/* Find a generic spec using the source program that owns the reference. */
static const GenericSpecDecl *cg_find_generic_spec_decl_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program) {
    const GenericSpecDecl *visible = NULL;

    if (ref == NULL || ref->kind != FENG_TYPE_REF_NAMED) {
        return NULL;
    }

    for (size_t i = 0; i < cg->generic_spec_decl_count; ++i) {
        const GenericSpecDecl *entry = &cg->generic_spec_decls[i];
        const FengDecl *decl = entry->decl;

        if (decl == NULL || decl->kind != FENG_DECL_SPEC ||
            entry->owner_program == NULL ||
            !cg_named_type_ref_targets_owner_program_from(
                cg,
                reference_program,
                ref,
                entry->owner_program,
                decl->visibility,
                decl->as.spec_decl.name)) {
            continue;
        }
        /* Type/spec identity includes generic arity. The semantic model
         * permits callable families such as Func<R> and Func<T, R>; selecting
         * only by name here would bind a valid reference to the wrong AST
         * declaration after semantic analysis had already disambiguated it. */
        if (decl->as.spec_decl.type_param_count !=
            ref->as.named.type_arg_count) {
            continue;
        }
        if (reference_program != NULL &&
            entry->owner_program == reference_program) {
            return entry;
        }
        if (visible == NULL) {
            visible = entry;
        }
    }
    return visible;
}

/* Find a generic spec from the program currently being emitted. */
static const GenericSpecDecl *cg_find_generic_spec_decl(const CG *cg,
                                                        const FengTypeRef *ref) {
    return cg_find_generic_spec_decl_from_program(
        cg, ref, cg != NULL ? cg->cur_program : NULL);
}

/* Find a registered generic spec by stable source declaration identity. */
static const GenericSpecDecl *cg_find_generic_spec_decl_by_decl(
    const CG *cg,
    const FengDecl *decl) {
    if (cg == NULL || decl == NULL) {
        return NULL;
    }
    for (size_t i = 0U; i < cg->generic_spec_decl_count; ++i) {
        if (cg->generic_spec_decls[i].decl == decl) {
            return &cg->generic_spec_decls[i];
        }
    }
    return NULL;
}

/* Resolve one named generic reference to a stable declaration identity. */
static CGNamedGenericTarget cg_resolve_named_generic_target_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program) {
    CGNamedGenericTarget target = {0};

    target.type =
        cg_find_generic_type_decl_from_program(cg, ref, reference_program);
    if (target.type != NULL) {
        target.kind = CG_NAMED_GENERIC_TARGET_TYPE;
        target.decl = target.type->decl;
        target.owner_program = target.type->owner_program;
        return target;
    }

    target.spec =
        cg_find_generic_spec_decl_from_program(cg, ref, reference_program);
    if (target.spec != NULL) {
        target.kind = CG_NAMED_GENERIC_TARGET_SPEC;
        target.decl = target.spec->decl;
        target.owner_program = target.spec->owner_program;
    }
    return target;
}

/* Resolves a named type reference from its source program to the declaration
 * identity used by stable symbols and fully-qualified debug display types. */
static const FengProgram *cg_type_ref_decl_identity_from_program(
    const CG *cg,
    const FengTypeRef *ref,
    const FengProgram *reference_program,
    FengSlice *out_name) {
    const UserType *user_type;
    const UserSpec *user_spec;
    const GenericTypeDecl *generic_type;
    const GenericSpecDecl *generic_spec;
    const FengProgram *visible_enum_owner = NULL;
    FengSlice visible_enum_name = {0};

    if (cg == NULL || ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        out_name == NULL) {
        return NULL;
    }

    user_type =
        cg_find_user_type_by_ref_from_program(cg, ref, reference_program);
    if (user_type != NULL && user_type->decl != NULL) {
        *out_name = user_type->decl->as.type_decl.name;
        return user_type->owner_program;
    }

    user_spec =
        cg_find_user_spec_by_ref_from_program(cg, ref, reference_program);
    if (user_spec != NULL && user_spec->decl != NULL) {
        *out_name = user_spec->decl->as.spec_decl.name;
        return user_spec->owner_program;
    }

    generic_type =
        cg_find_generic_type_decl_from_program(cg, ref, reference_program);
    if (generic_type != NULL && generic_type->decl != NULL) {
        *out_name = generic_type->decl->as.type_decl.name;
        return generic_type->owner_program;
    }
    generic_spec =
        cg_find_generic_spec_decl_from_program(cg, ref, reference_program);
    if (generic_spec != NULL && generic_spec->decl != NULL) {
        *out_name = generic_spec->decl->as.spec_decl.name;
        return generic_spec->owner_program;
    }

    if (cg->analysis == NULL) return NULL;
    for (size_t module_index = 0U;
         module_index < cg->analysis->module_count;
         ++module_index) {
        const FengSemanticModule *module = &cg->analysis->modules[module_index];

        for (size_t program_index = 0U;
             program_index < module->program_count;
             ++program_index) {
            const FengProgram *program = module->programs[program_index];

            for (size_t decl_index = 0U;
                 decl_index < program->declaration_count;
                 ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl->kind != FENG_DECL_ENUM ||
                    !cg_named_type_ref_targets_owner_program_from(
                        cg,
                        reference_program,
                        ref,
                        program,
                        decl->visibility,
                        decl->as.enum_decl.name)) {
                    continue;
                }
                if (reference_program != NULL && program == reference_program) {
                    *out_name = decl->as.enum_decl.name;
                    return program;
                }
                if (visible_enum_owner == NULL) {
                    visible_enum_owner = program;
                    visible_enum_name = decl->as.enum_decl.name;
                }
            }
        }
    }
    if (visible_enum_owner != NULL) {
        *out_name = visible_enum_name;
    }
    return visible_enum_owner;
}

/* Resolves a named reference from the program currently being emitted. Type
 * parameters and builtins have no declaration owner and remain short names. */
static const FengProgram *cg_type_ref_decl_identity(const CG *cg,
                                                    const FengTypeRef *ref,
                                                    FengSlice *out_name) {
    return cg_type_ref_decl_identity_from_program(
        cg,
        ref,
        cg != NULL ? cg->cur_program : NULL,
        out_name);
}

/* Append a canonical type-reference symbol fragment. Named declaration types
 * use their real module path so local short names, aliases, and imported
 * fully-qualified references produce the same cross-package symbol. */
static bool cg_append_type_ref_symbol(CG *cg,
                                      Buf *out,
                                      const FengTypeRef *ref) {
    if (ref == NULL) return false;
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED: {
            FengSlice decl_name = {0};
            const FengProgram *owner =
                cg_type_ref_decl_identity(cg, ref, &decl_name);

            if (owner != NULL) {
                for (size_t i = 0U; i < owner->module_segment_count; ++i) {
                    char *san = cg_sanitize(owner->module_segments[i].data,
                                            owner->module_segments[i].length);
                    if (san == NULL) return false;
                    if (i > 0U) buf_append_cstr(out, "__");
                    buf_append_cstr(out, san);
                    free(san);
                }
                if (owner->module_segment_count > 0U) {
                    buf_append_cstr(out, "__");
                }
                char *san = cg_sanitize(decl_name.data, decl_name.length);
                if (san == NULL) return false;
                buf_append_cstr(out, san);
                free(san);
            } else {
                for (size_t i = 0; i < ref->as.named.segment_count; ++i) {
                    char *san = cg_sanitize(ref->as.named.segments[i].data,
                                            ref->as.named.segments[i].length);
                    if (!san) return false;
                    if (i) buf_append_cstr(out, "__");
                    buf_append_cstr(out, san);
                    free(san);
                }
            }
            if (ref->as.named.type_arg_count > 0U) {
                buf_append_cstr(out, "__G");
                for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                    buf_append_cstr(out, "__");
                    if (!cg_append_type_ref_symbol(cg,
                                                   out,
                                                   ref->as.named.type_args[i])) {
                        return false;
                    }
                }
            }
            return true;
        }
        case FENG_TYPE_REF_POINTER:
            buf_append_cstr(out, "P__");
            return cg_append_type_ref_symbol(cg, out, ref->as.inner);
        case FENG_TYPE_REF_ARRAY:
            buf_append_cstr(out, ref->array_element_writable ? "AW__" : "A__");
            return cg_append_type_ref_symbol(cg, out, ref->as.inner);
    }
    return false;
}

/* Append the canonical symbol fragment shared by every generated artifact of
 * one generic type instance. */
static bool cg_append_generic_type_instance_symbol(
    CG *cg,
    Buf *out,
    const FengDecl *decl,
    FengTypeRef *const *type_args,
    size_t type_arg_count) {
    char *base_san;

    if (cg == NULL || out == NULL || decl == NULL ||
        decl->kind != FENG_DECL_TYPE) {
        return false;
    }

    base_san = cg_sanitize(decl->as.type_decl.name.data,
                           decl->as.type_decl.name.length);
    if (base_san == NULL) return false;
    buf_append_cstr(out, base_san);
    free(base_san);
    buf_append_cstr(out, "__G");
    for (size_t i = 0U; i < type_arg_count; ++i) {
        buf_append_cstr(out, "__");
        if (!cg_append_type_ref_symbol(cg, out, type_args[i])) {
            return false;
        }
    }
    return true;
}

/* Build the canonical C struct name of one closed generic type instance. */
static char *cg_closed_generic_type_struct_name(
    CG *cg,
    const GenericTypeDecl *generic_decl,
    FengTypeRef *const *type_args,
    size_t type_arg_count) {
    Buf symbol;
    Buf struct_name;
    char *owner_mangle;

    if (generic_decl == NULL || generic_decl->decl == NULL ||
        generic_decl->owner_program == NULL) {
        return NULL;
    }

    buf_init(&symbol);
    if (!cg_append_generic_type_instance_symbol(cg,
                                                &symbol,
                                                generic_decl->decl,
                                                type_args,
                                                type_arg_count)) {
        buf_free(&symbol);
        return NULL;
    }
    owner_mangle = cg_module_mangle(
        generic_decl->owner_program->module_segments,
        generic_decl->owner_program->module_segment_count);
    if (owner_mangle == NULL) {
        buf_free(&symbol);
        return NULL;
    }

    buf_init(&struct_name);
    buf_append_fmt(&struct_name, "Feng__%s__%s", owner_mangle, symbol.data);
    free(owner_mangle);
    buf_free(&symbol);
    return struct_name.data;
}

/* Build the canonical emitted identity of one closed generic spec instance.
 * Generic object/intersection values intentionally share one carrier tag per
 * declaration, so they cannot identify an instance. Value-form aggregate
 * descriptors and callable-form closure descriptors remain instance-specific
 * and are therefore the stable deduplication identity across FT AST copies. */
static char *cg_closed_generic_spec_identity_name(
    CG *cg,
    const GenericSpecDecl *generic_decl,
    FengTypeRef *const *type_args,
    size_t type_arg_count) {
    const FengDecl *decl;
    char *base_san;
    char *owner_mangle;
    Buf symbol;
    Buf tag;

    if (cg == NULL || generic_decl == NULL || generic_decl->decl == NULL ||
        generic_decl->owner_program == NULL) {
        return NULL;
    }
    decl = generic_decl->decl;
    if (decl->kind != FENG_DECL_SPEC) {
        return NULL;
    }
    base_san = cg_sanitize(decl->as.spec_decl.name.data,
                           decl->as.spec_decl.name.length);
    if (base_san == NULL) {
        return NULL;
    }
    buf_init(&symbol);
    buf_append_cstr(&symbol, base_san);
    buf_append_cstr(&symbol, "__G");
    free(base_san);
    for (size_t i = 0U; i < type_arg_count; ++i) {
        buf_append_cstr(&symbol, "__");
        if (!cg_append_type_ref_symbol(cg, &symbol, type_args[i])) {
            buf_free(&symbol);
            return NULL;
        }
    }
    owner_mangle = cg_module_mangle(
        generic_decl->owner_program->module_segments,
        generic_decl->owner_program->module_segment_count);
    if (owner_mangle == NULL) {
        buf_free(&symbol);
        return NULL;
    }
    buf_init(&tag);
    buf_append_fmt(&tag,
                   decl->as.spec_decl.form == FENG_SPEC_FORM_CALLABLE
                       ? "FengClosureDesc__%s__%s"
                       : "FengSpecAgg__%s__%s",
                   owner_mangle,
                   symbol.data);
    free(owner_mangle);
    buf_free(&symbol);
    return tag.data;
}

static UserSpec *cg_find_generic_instance_user_spec_with_context(CG *cg,
                                                                 const FengDecl *origin_decl,
                                                                 FengTypeRef *const *type_args,
                                                                 size_t type_arg_count,
                                                                 char *const *context_names,
                                                                 size_t context_count) {
    for (size_t i = 0; i < cg->user_spec_count; ++i) {
        UserSpec *us = &cg->user_specs[i];
        if (!us->is_generic_instance || us->generic_origin_decl != origin_decl ||
            us->generic_type_arg_count != type_arg_count) {
            continue;
        }
        if (!cg_type_param_context_equal(us->generic_context_type_param_names,
                                         us->generic_context_type_param_count,
                                         context_names,
                                         context_count)) {
            continue;
        }
        bool same = true;
        for (size_t arg_index = 0; same && arg_index < type_arg_count; ++arg_index) {
            same = cg_type_ref_equal(us->generic_type_args[arg_index],
                                     type_args[arg_index]);
        }
        if (same) return us;
    }

    /* FT imports can materialize the same closed spec through distinct AST
     * declaration/type-ref identities. The canonical emitted tag is already
     * the code-generation identity, so use it as the closed-instance fallback
     * exactly as generic UserType registration does. */
    if (context_count == 0U) {
        const GenericSpecDecl *generic_decl =
            cg_find_generic_spec_decl_by_decl(cg, origin_decl);
        char *canonical_identity = cg_closed_generic_spec_identity_name(
            cg,
            generic_decl,
            type_args,
            type_arg_count);

        if (canonical_identity == NULL) {
            return NULL;
        }
        for (size_t i = 0U; i < cg->user_spec_count; ++i) {
            UserSpec *candidate = &cg->user_specs[i];
            const char *candidate_identity;

            if (!candidate->is_generic_instance ||
                candidate->generic_context_type_param_count != 0U ||
                candidate->form != origin_decl->as.spec_decl.form) {
                continue;
            }
            candidate_identity = candidate->form == FENG_SPEC_FORM_CALLABLE
                                     ? candidate->c_closure_desc_name
                                     : candidate->c_aggregate_desc_name;
            if (candidate_identity != NULL &&
                strcmp(candidate_identity, canonical_identity) == 0) {
                free(canonical_identity);
                return candidate;
            }
        }
        free(canonical_identity);
    }
    return NULL;
}

static bool cg_type_args_contain_type_param_names(FengTypeRef *const *type_args,
                                                  size_t type_arg_count,
                                                  char *const *names,
                                                  size_t name_count);

/* Find a generic spec instance using the active generic parameter context. */
static UserSpec *cg_find_generic_instance_user_spec_with_active_context(
    CG *cg,
    const FengDecl *origin_decl,
    FengTypeRef *const *type_args,
    size_t type_arg_count) {
    char *const *context_names = NULL;
    size_t context_count = 0U;

    if (cg->in_generic_fn &&
        cg_type_args_contain_type_param_names(type_args,
                                              type_arg_count,
                                              cg->generic_fn_type_param_names,
                                              cg->generic_fn_type_param_count)) {
        context_names = cg->generic_fn_type_param_names;
        context_count = cg->generic_fn_type_param_count;
    } else if (cg->ambient_type_param_count > 0U &&
               cg_type_args_contain_type_param_names(type_args,
                                                     type_arg_count,
                                                     cg->ambient_type_param_names,
                                                     cg->ambient_type_param_count)) {
        context_names = cg->ambient_type_param_names;
        context_count = cg->ambient_type_param_count;
    }
    return cg_find_generic_instance_user_spec_with_context(cg,
                                                           origin_decl,
                                                           type_args,
                                                           type_arg_count,
                                                           context_names,
                                                           context_count);
}

static UserSpec *cg_find_generic_instance_user_spec_for_ref(CG *cg,
                                                            const FengTypeRef *ref) {
    const GenericSpecDecl *generic_decl = cg_find_generic_spec_decl(cg, ref);
    if (generic_decl == NULL) return NULL;
    return cg_find_generic_instance_user_spec_with_active_context(
        cg,
        generic_decl->decl,
        ref->as.named.type_args,
        ref->as.named.type_arg_count);
}

static UserType *cg_find_generic_instance_user_type_with_active_context(
    CG *cg,
    const FengDecl *origin_decl,
    FengTypeRef *const *type_args,
    size_t type_arg_count);

/* Resolve the open-instance aggregate descriptor symbol used as the
 * compile-time key for one reified aggregate dependency. Both generic value
 * types and generic object specs participate; the latter keep a fixed value
 * layout but still require the concrete descriptor for lifecycle/default
 * semantics in a shared body. */
static const char *cg_open_generic_aggregate_descriptor_name(
    CG *cg,
    const FengTypeRef *ref) {
    UserSpec *spec_instance;
    const GenericTypeDecl *type_decl;
    const UserType *type_instance;

    if (cg == NULL || ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.type_arg_count == 0U) {
        return NULL;
    }
    spec_instance = cg_find_generic_instance_user_spec_for_ref(cg, ref);
    if (spec_instance != NULL &&
        spec_instance->generic_context_type_param_count > 0U) {
        return spec_instance->c_aggregate_desc_name;
    }
    type_decl = cg_find_generic_type_decl(cg, ref);
    if (type_decl == NULL) {
        return NULL;
    }
    type_instance = cg_find_generic_instance_user_type_with_active_context(
        cg,
        type_decl->decl,
        ref->as.named.type_args,
        ref->as.named.type_arg_count);
    return type_instance != NULL ? type_instance->c_aggregate_desc_name : NULL;
}

/* Resolve the open-instance managed descriptor symbol used as the stable key
 * for one reified type dependency. Both ordinary reference types and
 * callable-form specs have fixed pointer representation but require their
 * concrete descriptor when a shared body creates a default instance. */
static const char *cg_open_generic_managed_descriptor_name(
    CG *cg,
    const FengTypeRef *ref) {
    UserSpec *spec_instance;
    const GenericTypeDecl *type_decl;
    const UserType *type_instance;

    if (cg == NULL || ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.type_arg_count == 0U) {
        return NULL;
    }
    spec_instance = cg_find_generic_instance_user_spec_for_ref(cg, ref);
    if (spec_instance != NULL &&
        spec_instance->form == FENG_SPEC_FORM_CALLABLE &&
        spec_instance->generic_context_type_param_count > 0U) {
        return spec_instance->c_closure_desc_name;
    }
    type_decl = cg_find_generic_type_decl(cg, ref);
    if (type_decl == NULL || type_decl->decl == NULL ||
        cg_type_decl_is_value_semantics(type_decl->decl)) {
        return NULL;
    }
    type_instance = cg_find_generic_instance_user_type_with_active_context(
        cg,
        type_decl->decl,
        ref->as.named.type_args,
        ref->as.named.type_arg_count);
    return type_instance != NULL ? type_instance->c_desc_name : NULL;
}

static UserType *cg_find_generic_instance_user_type(CG *cg,
                                                    const FengDecl *origin_decl,
                                                    FengTypeRef *const *type_args,
                                                    size_t type_arg_count) {
    const GenericTypeDecl *generic_decl;
    char *canonical_struct_name;

    for (size_t i = 0; i < cg->user_type_count; ++i) {
        UserType *ut = &cg->user_types[i];
        if (!ut->is_generic_instance || ut->generic_origin_decl != origin_decl ||
            ut->generic_type_arg_count != type_arg_count) {
            continue;
        }
        bool same = true;
        for (size_t arg_index = 0; same && arg_index < type_arg_count; ++arg_index) {
            same = cg_type_ref_equal(ut->generic_type_args[arg_index],
                                     type_args[arg_index]);
        }
        if (same) return ut;
    }

    /* FT imports may materialize the same declaration through different AST
     * identities. Closed instances still share one canonical generated type
     * symbol and must therefore reuse the already registered UserType. */
    generic_decl = cg_find_generic_type_decl_by_decl(cg, origin_decl);
    canonical_struct_name = cg_closed_generic_type_struct_name(cg,
                                                               generic_decl,
                                                               type_args,
                                                               type_arg_count);
    if (canonical_struct_name == NULL) return NULL;
    for (size_t i = 0U; i < cg->user_type_count; ++i) {
        UserType *ut = &cg->user_types[i];

        if (!ut->is_generic_instance ||
            ut->generic_context_type_param_count != 0U ||
            ut->c_struct_name == NULL) {
            continue;
        }
        if (strcmp(ut->c_struct_name, canonical_struct_name) == 0) {
            free(canonical_struct_name);
            return ut;
        }
    }
    free(canonical_struct_name);
    return NULL;
}

static UserType *cg_find_generic_instance_user_type_with_context(CG *cg,
                                                                const FengDecl *origin_decl,
                                                                FengTypeRef *const *type_args,
                                                                size_t type_arg_count,
                                                                char *const *context_names,
                                                                size_t context_count) {
    for (size_t i = 0; i < cg->user_type_count; ++i) {
        UserType *ut = &cg->user_types[i];
        if (!ut->is_generic_instance || ut->generic_origin_decl != origin_decl ||
            ut->generic_type_arg_count != type_arg_count) {
            continue;
        }
        if (!cg_type_param_context_equal(ut->generic_context_type_param_names,
                                         ut->generic_context_type_param_count,
                                         context_names,
                                         context_count)) {
            continue;
        }
        bool same = true;
        for (size_t arg_index = 0; same && arg_index < type_arg_count; ++arg_index) {
            same = cg_type_ref_equal(ut->generic_type_args[arg_index],
                                     type_args[arg_index]);
        }
        if (same) return ut;
    }
    return NULL;
}

static bool cg_type_args_contain_type_param_names(FengTypeRef *const *type_args,
                                                  size_t type_arg_count,
                                                  char *const *names,
                                                  size_t name_count) {
    if (type_args == NULL || type_arg_count == 0U) return false;
    for (size_t i = 0; i < type_arg_count; ++i) {
        if (cg_type_ref_contains_type_param_names(type_args[i], names, name_count)) {
            return true;
        }
    }
    return false;
}

static UserType *cg_find_generic_instance_user_type_with_active_context(
    CG *cg,
    const FengDecl *origin_decl,
    FengTypeRef *const *type_args,
    size_t type_arg_count) {
    char *const *context_names = NULL;
    size_t context_count = 0U;

    /* Concrete substitution scope: when emitting field initializers for a
     * concrete generic instance (e.g. Holder<i32>), type-arg references to
     * the origin's type parameters (e.g. T in Inner<T>()) must be replaced
     * with the concrete type_args (e.g. i32) so we look up the concrete
     * instance Inner<i32> rather than the open instance Inner<T>. */
    if (cg->concrete_subst_param_count > 0U && type_args != NULL) {
        bool needs_subst = false;
        for (size_t i = 0; i < type_arg_count; ++i) {
            if (type_args[i] != NULL &&
                type_args[i]->kind == FENG_TYPE_REF_NAMED &&
                type_args[i]->as.named.segment_count == 1U &&
                type_args[i]->as.named.type_arg_count == 0U) {
                FengSlice seg = type_args[i]->as.named.segments[0];
                for (size_t p = 0; p < cg->concrete_subst_param_count; ++p) {
                    if (cg->concrete_subst_params[p].name.length == seg.length &&
                        memcmp(cg->concrete_subst_params[p].name.data, seg.data, seg.length) == 0) {
                        needs_subst = true;
                        break;
                    }
                }
                if (needs_subst) break;
            }
        }
        if (needs_subst) {
            FengTypeRef **subst_args = NULL;
            bool ok = true;
            subst_args = (FengTypeRef **)calloc(type_arg_count, sizeof(*subst_args));
            if (subst_args == NULL) return NULL;
            for (size_t i = 0; i < type_arg_count; ++i) {
                subst_args[i] = cg_type_ref_substitute(
                    type_args[i],
                    cg->concrete_subst_params,
                    cg->concrete_subst_param_count,
                    cg->concrete_subst_type_args);
                if (subst_args[i] == NULL && type_args[i] != NULL) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                UserType *inst = cg_find_generic_instance_user_type(
                    cg, origin_decl, subst_args, type_arg_count);
                for (size_t i = 0; i < type_arg_count; ++i) {
                    cg_type_ref_free(subst_args[i]);
                }
                free(subst_args);
                if (inst != NULL) return inst;
            } else {
                for (size_t i = 0; i < type_arg_count; ++i) {
                    cg_type_ref_free(subst_args[i]);
                }
                free(subst_args);
            }
        }
    }

    if (cg->in_generic_fn &&
        cg_type_args_contain_type_param_names(type_args,
                                              type_arg_count,
                                              cg->generic_fn_type_param_names,
                                              cg->generic_fn_type_param_count)) {
        context_names = cg->generic_fn_type_param_names;
        context_count = cg->generic_fn_type_param_count;
    } else if (cg->ambient_type_param_count > 0U &&
               cg_type_args_contain_type_param_names(type_args,
                                                     type_arg_count,
                                                     cg->ambient_type_param_names,
                                                     cg->ambient_type_param_count)) {
        context_names = cg->ambient_type_param_names;
        context_count = cg->ambient_type_param_count;
    }

    UserType *instance = cg_find_generic_instance_user_type_with_context(cg,
                                                                        origin_decl,
                                                                        type_args,
                                                                        type_arg_count,
                                                                        context_names,
                                                                        context_count);
    if (instance != NULL) {
        return instance;
    }
    if (context_count == 0U) {
        return cg_find_generic_instance_user_type(cg,
                                                  origin_decl,
                                                  type_args,
                                                  type_arg_count);
    }
    return NULL;
}

static bool cg_collect_generic_instances_from_type_ref(CG *cg,
                                                       const FengTypeRef *ref,
                                                       CGTypeParamScope scope);
static bool cg_collect_generic_instances_from_type_ref_from_program(
    CG *cg,
    const FengTypeRef *ref,
    CGTypeParamScope scope,
    const FengProgram *reference_program);
static bool cg_collect_generic_instances_from_substituted_type_ref(
    CG *cg,
    const FengTypeRef *source_ref,
    const FengTypeRef *effective_ref,
    const FengTypeParam *substituted_params,
    size_t substituted_param_count,
    CGTypeParamScope effective_scope,
    const FengProgram *source_program);

static bool cg_annotations_contain_kind(const FengAnnotation *annotations,
                                        size_t annotation_count,
                                        FengAnnotationKind kind) {
    if (annotations == NULL) {
        return false;
    }
    for (size_t i = 0; i < annotation_count; ++i) {
        if (annotations[i].builtin_kind == kind) {
            return true;
        }
    }
    return false;
}

static bool cg_annotation_kind_is_calling_convention(FengAnnotationKind kind) {
    return kind == FENG_ANNOTATION_CDECL || kind == FENG_ANNOTATION_STDCALL ||
           kind == FENG_ANNOTATION_FASTCALL;
}

static const FengAnnotation *cg_find_calling_convention_annotation(
    const FengAnnotation *annotations,
    size_t annotation_count) {
    if (annotations == NULL) {
        return NULL;
    }
    for (size_t i = 0; i < annotation_count; ++i) {
        if (cg_annotation_kind_is_calling_convention(annotations[i].builtin_kind)) {
            return &annotations[i];
        }
    }
    return NULL;
}

static FengAnnotationKind cg_find_calling_convention_kind(const FengAnnotation *annotations,
                                                          size_t annotation_count) {
    const FengAnnotation *annotation = cg_find_calling_convention_annotation(annotations,
                                                                             annotation_count);

    return annotation != NULL ? annotation->builtin_kind : FENG_ANNOTATION_NONE;
}

static const char *cg_extern_calling_convention_macro(FengAnnotationKind kind) {
    switch (kind) {
        case FENG_ANNOTATION_STDCALL:
            return "FENG_EXTERN_CALLCONV_STDCALL";
        case FENG_ANNOTATION_FASTCALL:
            return "FENG_EXTERN_CALLCONV_FASTCALL";
        default:
            return NULL;
    }
}

static bool cg_slice_equals_cstr(FengSlice slice, const char *text) {
    size_t text_length = strlen(text);

    return slice.length == text_length && memcmp(slice.data, text, text_length) == 0;
}

static bool cg_decl_uses_runtime_contract(const FengDecl *decl) {
    return decl != NULL && decl->kind == FENG_DECL_FUNCTION && decl->is_extern &&
           cg_annotations_contain_kind(
               decl->annotations, decl->annotation_count, FENG_ANNOTATION_RUNTIME);
}

static bool cg_runtime_contract_contains_name(FengSlice name) {
#define FENG_RUNTIME_CONTRACT(ret_type, symbol, args) \
    if (cg_slice_equals_cstr(name, #symbol)) {           \
        return true;                                     \
    }
#include "runtime/feng_runtime_contract.inc"
#undef FENG_RUNTIME_CONTRACT

    return false;
}

static bool cg_init_user_type_abi_symbols(UserType *t) {
    if (t == NULL || !t->is_abi_type || !cg_decl_has_field_members(t->decl)) {
        return true;
    }

    Buf layout; buf_init(&layout);
    buf_append_fmt(&layout, "%s__AbiLayout", t->c_struct_name);
    t->c_abi_layout_name = layout.data;

    Buf ptr; buf_init(&ptr);
    buf_append_fmt(&ptr, "%s__abi_ptr", t->c_struct_name);
    t->c_abi_ptr_name = ptr.data;

    Buf offset; buf_init(&offset);
    buf_append_fmt(&offset, "%s__abi_base_offset", t->c_struct_name);
    t->c_abi_base_offset_name = offset.data;

        Buf value; buf_init(&value);
        buf_append_fmt(&value, "%s__abi_value", t->c_struct_name);
        t->c_abi_value_name = value.data;

        Buf box; buf_init(&box);
        buf_append_fmt(&box, "%s__abi_box", t->c_struct_name);
        t->c_abi_box_name = box.data;

    return t->c_abi_layout_name != NULL &&
           t->c_abi_ptr_name != NULL &&
            t->c_abi_base_offset_name != NULL &&
            t->c_abi_value_name != NULL &&
            t->c_abi_box_name != NULL;
}
static bool cg_collect_generic_instances_from_type_params(CG *cg,
                                                          const FengTypeParam *type_params,
                                                          size_t type_param_count,
                                                          CGTypeParamScope scope);
static bool cg_collect_generic_instances_from_type_params_from_program(
    CG *cg,
    const FengTypeParam *type_params,
    size_t type_param_count,
    CGTypeParamScope scope,
    const FengProgram *reference_program);
static const FengReifiableDepSet *cg_callable_dep_set(
    const CG *cg,
    const FengReifiableCallableDep *dep);
static bool cg_close_callable_dep_type_args(
    CG *cg,
    const FengReifiableCallableDep *dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    FengToken blame,
    FengTypeParam **out_params,
    FengTypeRef ***out_args,
    size_t *out_count);

/* One active node in recursive generic-instance pre-registration.  The
 * dependency-set identity and closed arguments together identify a concrete
 * callable invocation; retaining only the active path handles direct and
 * mutual recursion without suppressing independent branches. */
typedef struct CGReifiablePreRegistrationFrame {
    const FengReifiableDepSet *dep_set;
    FengTypeRef *const *type_args;
    size_t type_arg_count;
    const struct CGReifiablePreRegistrationFrame *parent;
} CGReifiablePreRegistrationFrame;

/* Return whether one closed dependency invocation is already active. */
static bool cg_reifiable_pre_registration_is_active(
    const CGReifiablePreRegistrationFrame *frame,
    const FengReifiableDepSet *dep_set,
    FengTypeRef *const *type_args,
    size_t type_arg_count) {
    for (const CGReifiablePreRegistrationFrame *current = frame;
         current != NULL;
         current = current->parent) {
        size_t index;

        if (current->dep_set != dep_set ||
            current->type_arg_count != type_arg_count) {
            continue;
        }
        for (index = 0U; index < type_arg_count; ++index) {
            if (!cg_type_ref_equal(current->type_args[index],
                                   type_args[index])) {
                break;
            }
        }
        if (index == type_arg_count) {
            return true;
        }
    }
    return false;
}

/* Register direct and transitive type/spec instances required by one closed
 * callable dependency graph. */
static bool cg_collect_closed_reifiable_dep_instances_inner(
    CG *cg,
    const FengReifiableDepSet *dep_set,
    const FengTypeParam *type_params,
    size_t type_param_count,
    FengTypeRef *const *type_args,
    CGTypeParamScope caller_scope,
    const FengProgram *reference_program,
    FengToken blame,
    const CGReifiablePreRegistrationFrame *parent) {
    CGReifiablePreRegistrationFrame frame;

    if (dep_set == NULL) {
        return true;
    }
    if (type_param_count > 0U && type_args == NULL) {
        return true;
    }
    if (cg_reifiable_pre_registration_is_active(parent,
                                                 dep_set,
                                                 type_args,
                                                 type_param_count)) {
        return true;
    }
    frame.dep_set = dep_set;
    frame.type_args = type_args;
    frame.type_arg_count = type_param_count;
    frame.parent = parent;

    for (size_t index = 0U; index < dep_set->dep_count; ++index) {
        FengTypeRef *closed_ref = cg_type_ref_substitute(
            dep_set->deps[index].type_ref,
            type_params,
            type_param_count,
            type_args);
        bool ok;

        if (closed_ref == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        ok = cg_collect_generic_instances_from_substituted_type_ref(
            cg,
            dep_set->deps[index].type_ref,
            closed_ref,
            type_params,
            type_param_count,
            caller_scope,
            reference_program);
        cg_type_ref_free(closed_ref);
        if (!ok) {
            return false;
        }
    }

    for (size_t index = 0U;
         index < dep_set->callable_dep_count;
         ++index) {
        const FengReifiableCallableDep *callable_dep =
            &dep_set->callable_deps[index];
        const FengReifiableDepSet *callee_dep_set =
            cg_callable_dep_set(cg, callable_dep);
        const FengDecl *reference_decl =
            callable_dep->function_decl != NULL
                ? callable_dep->function_decl
                : (callable_dep->fit_decl != NULL
                       ? callable_dep->fit_decl
                       : callable_dep->owner_type_decl);
        FengTypeParam *callee_params = NULL;
        FengTypeRef **callee_args = NULL;
        size_t callee_count = 0U;
        bool ok;

        if (callable_dep->purpose ==
            FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE) {
            const FengTypeRef *callable_value_refs[] = {
                callable_dep->owner_instance_type_ref,
                callable_dep->target_callable_type_ref,
            };

            for (size_t ref_index = 0U;
                 ref_index < sizeof(callable_value_refs) /
                 sizeof(callable_value_refs[0]);
                 ++ref_index) {
                const FengTypeRef *open_ref = callable_value_refs[ref_index];
                FengTypeRef *closed_ref;

                /* Top-level callable values have no receiver owner. The
                 * target callable surface is still collected below. */
                if (open_ref == NULL) {
                    continue;
                }
                closed_ref = cg_type_ref_substitute(
                    open_ref,
                    type_params,
                    type_param_count,
                    type_args);
                if (closed_ref == NULL) {
                    return cg_fail(cg,
                                   blame,
                                   "IE0001",
                                   "codegen: out of memory");
                }
                ok = cg_collect_generic_instances_from_substituted_type_ref(
                    cg,
                    open_ref,
                    closed_ref,
                    type_params,
                    type_param_count,
                    caller_scope,
                    reference_program);
                cg_type_ref_free(closed_ref);
                if (!ok) {
                    return false;
                }
            }
        }

        if (!cg_close_callable_dep_type_args(cg,
                                             callable_dep,
                                             type_params,
                                             type_param_count,
                                             type_args,
                                             blame,
                                             &callee_params,
                                             &callee_args,
                                             &callee_count)) {
            return false;
        }
        ok = true;
        {
            size_t callee_arg_index = 0U;

            if (callable_dep->owner_type_decl != NULL &&
                callable_dep->owner_type_decl->kind == FENG_DECL_TYPE &&
                callable_dep->owner_type_decl->as.type_decl.type_param_count >
                    0U) {
                const FengTypeRef *owner_ref =
                    callable_dep->owner_instance_type_ref;
                size_t owner_count =
                    callable_dep->owner_type_decl->as.type_decl
                        .type_param_count;

                for (size_t arg_index = 0U;
                     arg_index < owner_count;
                     ++arg_index, ++callee_arg_index) {
                    if (!cg_collect_generic_instances_from_substituted_type_ref(
                            cg,
                            owner_ref->as.named.type_args[arg_index],
                            callee_args[callee_arg_index],
                            type_params,
                            type_param_count,
                            caller_scope,
                            reference_program)) {
                        ok = false;
                        break;
                    }
                }
            }
            for (size_t arg_index = 0U;
                 ok && arg_index < callable_dep->callable_type_arg_count;
                 ++arg_index, ++callee_arg_index) {
                if (!cg_collect_generic_instances_from_substituted_type_ref(
                        cg,
                        callable_dep->callable_type_args[arg_index],
                        callee_args[callee_arg_index],
                        type_params,
                        type_param_count,
                        caller_scope,
                        reference_program)) {
                    ok = false;
                }
            }
        }
        if (!ok) {
            for (size_t arg_index = 0U;
                 arg_index < callee_count;
                 ++arg_index) {
                cg_type_ref_free(callee_args[arg_index]);
            }
            free(callee_args);
            free(callee_params);
            return false;
        }
        ok = cg_collect_closed_reifiable_dep_instances_inner(
            cg,
            callee_dep_set,
            callee_params,
            callee_count,
            callee_args,
            caller_scope,
            cg_find_decl_owner_program(cg, reference_decl),
            blame,
            &frame);
        for (size_t arg_index = 0U;
             arg_index < callee_count;
             ++arg_index) {
            cg_type_ref_free(callee_args[arg_index]);
        }
        free(callee_args);
        free(callee_params);
        if (!ok) {
            return false;
        }
    }
    return true;
}

/* Close one callable's direct reifiable type dependencies at a concrete call
 * site and register every direct or transitive generic type/spec instance
 * before the emission passes resolve descriptor symbols. */
static bool cg_collect_closed_reifiable_dep_instances(
    CG *cg,
    const FengReifiableDepSet *dep_set,
    const FengTypeParam *type_params,
    size_t type_param_count,
    FengTypeRef *const *type_args,
    CGTypeParamScope caller_scope,
    const FengProgram *reference_program,
    FengToken blame) {
    return cg_collect_closed_reifiable_dep_instances_inner(
        cg,
        dep_set,
        type_params,
        type_param_count,
        type_args,
        caller_scope,
        reference_program,
        blame,
        NULL);
}

/* Close one resolved type/fit member call through the common member dep set.
 * Owner type arguments precede method arguments, matching collection order. */
static bool cg_collect_resolved_member_call_reifiable_dep_instances(
    CG *cg,
    const FengExpr *call_expr,
    const FengDecl *owner_decl,
    const FengDecl *dependency_owner_decl,
    const FengTypeMember *member,
    CGTypeParamScope caller_scope) {
    const FengCallableSignature *callable;
    const FengTypeRef *owner_instance;
    const FengTypeRef *const *method_args = NULL;
    size_t owner_count;
    size_t method_count;
    size_t combined_count;
    FengTypeParam *combined_params = NULL;
    FengTypeRef **combined_args = NULL;
    const FengReifiableDepSet *dep_set;
    bool ok;

    if (owner_decl == NULL || owner_decl->kind != FENG_DECL_TYPE ||
        dependency_owner_decl == NULL || member == NULL ||
        member->kind != FENG_TYPE_MEMBER_METHOD) {
        return true;
    }
    callable = &member->as.callable;
    owner_instance =
        call_expr->as.call.resolved_callable.owner_instance_type_ref;
    owner_count = owner_decl->as.type_decl.type_param_count;
    method_count = callable->type_param_count;
    combined_count = owner_count + method_count;
    dep_set = feng_semantic_lookup_member_reifiable_dep_set(
        cg->analysis, dependency_owner_decl, member);

    if (owner_count > 0U &&
        (owner_instance == NULL ||
         owner_instance->kind != FENG_TYPE_REF_NAMED ||
         owner_instance->as.named.type_arg_count != owner_count)) {
        return true;
    }
    if (method_count > 0U) {
        const FengResolvedCallable *resolved =
            &call_expr->as.call.resolved_callable;

        if (resolved->callable_type_args != NULL &&
            resolved->callable_type_arg_count == method_count) {
            method_args = resolved->callable_type_args;
        } else if (call_expr->as.call.has_explicit_type_args &&
                   call_expr->as.call.explicit_type_arg_count ==
                       method_count) {
            method_args = (const FengTypeRef *const *)
                call_expr->as.call.explicit_type_args;
        } else {
            return true;
        }
    }
    if (combined_count == 0U) {
        return true;
    }

    combined_params = (FengTypeParam *)calloc(
        combined_count, sizeof(*combined_params));
    combined_args = (FengTypeRef **)calloc(
        combined_count, sizeof(*combined_args));
    if (combined_params == NULL || combined_args == NULL) {
        free(combined_params);
        free(combined_args);
        return cg_fail(cg, call_expr->token,
                       "IE0001", "codegen: out of memory");
    }
    for (size_t index = 0U; index < owner_count; ++index) {
        combined_params[index] = owner_decl->as.type_decl.type_params[index];
        combined_args[index] = owner_instance->as.named.type_args[index];
    }
    for (size_t index = 0U; index < method_count; ++index) {
        combined_params[owner_count + index] = callable->type_params[index];
        combined_args[owner_count + index] =
            (FengTypeRef *)method_args[index];
    }
    ok = cg_collect_closed_reifiable_dep_instances(
        cg,
        dep_set,
        combined_params,
        combined_count,
        combined_args,
        caller_scope,
        cg_find_decl_owner_program(cg, dependency_owner_decl),
        call_expr->token);
    free(combined_params);
    free(combined_args);
    return ok;
}

/* Close direct dependencies for a resolved top-level, type, or fit call. */
static bool cg_collect_resolved_call_reifiable_dep_instances(
    CG *cg,
    const FengExpr *call_expr,
    CGTypeParamScope caller_scope) {
    const FengResolvedCallable *resolved;

    if (cg == NULL || call_expr == NULL ||
        call_expr->kind != FENG_EXPR_CALL) {
        return true;
    }
    resolved = &call_expr->as.call.resolved_callable;

    if (resolved->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
        resolved->function_decl != NULL) {
        const FengDecl *function_decl = resolved->function_decl;
        const FengCallableSignature *callable =
            &function_decl->as.function_decl;
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(cg->analysis,
                                                   function_decl);

        if (callable->type_param_count == 0U ||
            !call_expr->as.call.has_explicit_type_args ||
            call_expr->as.call.explicit_type_arg_count !=
                callable->type_param_count) {
            return true;
        }
        return cg_collect_closed_reifiable_dep_instances(
            cg,
            dep_set,
            callable->type_params,
            callable->type_param_count,
            call_expr->as.call.explicit_type_args,
            caller_scope,
            cg_find_decl_owner_program(cg, function_decl),
            call_expr->token);
    }

    if ((resolved->kind == FENG_RESOLVED_CALLABLE_TYPE_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD) &&
        resolved->owner_type_decl != NULL && resolved->member != NULL) {
        const FengDecl *dependency_owner =
            resolved->fit_decl != NULL
                ? resolved->fit_decl
                : resolved->owner_type_decl;

        return cg_collect_resolved_member_call_reifiable_dep_instances(
            cg,
            call_expr,
            resolved->owner_type_decl,
            dependency_owner,
            resolved->member,
            caller_scope);
    }

    (void)caller_scope;
    return true;
}

/**
 * Collect generic instances referenced by one instantiated callable member.
 *
 * Owner type parameters are first substituted with the current instance
 * arguments. Any still-open instantiation scope is then combined with the
 * callable's own generic parameters before collecting constraints, parameter
 * types, and the return type.
 */
static bool cg_collect_instantiated_callable_member_instances(
    CG *cg,
    const FengCallableSignature *callable,
    const FengTypeParam *owner_type_params,
    size_t owner_type_param_count,
    FengTypeRef *const *owner_type_args,
    CGTypeParamScope inherited_scope,
    const FengProgram *reference_program) {
    CGTypeParamScope callable_scope;
    FengTypeParam *owned_scope_prefix = NULL;
    bool ok = true;

    if (callable == NULL) {
        return true;
    }
    if (!cg_type_param_scope_extend(&inherited_scope,
                                    callable->type_params,
                                    callable->type_param_count,
                                    &callable_scope,
                                    &owned_scope_prefix)) {
        return cg_fail(cg, callable->token, "IE0001", "codegen: out of memory");
    }
    for (size_t index = 0U; ok && index < callable->type_param_count; ++index) {
        const FengTypeRef *constraint = callable->type_params[index].constraint;
        FengTypeRef *substituted;

        if (constraint == NULL) {
            continue;
        }
        substituted = cg_type_ref_substitute(constraint,
                                              owner_type_params,
                                              owner_type_param_count,
                                              owner_type_args);
        if (substituted == NULL) {
            ok = false;
            break;
        }
        ok = cg_collect_generic_instances_from_substituted_type_ref(
            cg,
            constraint,
            substituted,
            owner_type_params,
            owner_type_param_count,
            callable_scope,
            reference_program);
        cg_type_ref_free(substituted);
    }
    for (size_t index = 0U; ok && index < callable->param_count; ++index) {
        FengTypeRef *substituted = cg_type_ref_substitute(
            callable->params[index].type,
            owner_type_params,
            owner_type_param_count,
            owner_type_args);

        if (substituted == NULL) {
            ok = false;
            break;
        }
        ok = cg_collect_generic_instances_from_substituted_type_ref(
            cg,
            callable->params[index].type,
            substituted,
            owner_type_params,
            owner_type_param_count,
            callable_scope,
            reference_program);
        cg_type_ref_free(substituted);
    }
    if (ok && callable->return_type != NULL) {
        FengTypeRef *substituted = cg_type_ref_substitute(
            callable->return_type,
            owner_type_params,
            owner_type_param_count,
            owner_type_args);

        if (substituted == NULL) {
            ok = false;
        } else {
            ok = cg_collect_generic_instances_from_substituted_type_ref(
                cg,
                callable->return_type,
                substituted,
                owner_type_params,
                owner_type_param_count,
                callable_scope,
                reference_program);
            cg_type_ref_free(substituted);
        }
    }
    free(owned_scope_prefix);
    return ok;
}

static bool cg_register_generic_type_instance_shell(CG *cg,
                                                    const GenericTypeDecl *generic_decl,
                                                    FengTypeRef *const *type_args,
                                                    size_t type_arg_count,
                                                    FengToken blame,
                                                    const CGTypeParamScope *open_scope) {
    if (generic_decl == NULL || generic_decl->decl == NULL) return true;
    const FengDecl *decl = generic_decl->decl;
    if (decl->kind != FENG_DECL_TYPE) return true;
    if (type_arg_count != decl->as.type_decl.type_param_count) {
        return cg_fail(cg, blame,
                       "CE0029", "codegen: generic type '%.*s' expects %zu type argument(s), got %zu",
                       (int)decl->as.type_decl.name.length,
                       decl->as.type_decl.name.data,
                       decl->as.type_decl.type_param_count,
                       type_arg_count);
    }
    char **context_names = NULL;
    const UserSpec **context_constraints = NULL;
    size_t *context_constraint_indices = NULL;
    size_t context_count = 0U;
    bool has_open_type_arg = false;
    if (open_scope != NULL) {
        for (size_t i = 0; i < type_arg_count; ++i) {
            if (cg_type_ref_contains_type_param(type_args[i], open_scope)) {
                has_open_type_arg = true;
                break;
            }
        }
        if (has_open_type_arg && !cg_type_param_scope_copy_names(open_scope, &context_names, &context_count)) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (has_open_type_arg &&
            !cg_type_param_scope_build_constraints(cg, open_scope, blame, &context_constraints)) {
            cg_free_cstr_array(context_names, context_count);
            return false;
        }
        if (has_open_type_arg &&
            !cg_user_spec_constraint_indices(cg,
                                             context_constraints,
                                             context_count,
                                             blame,
                                             &context_constraint_indices)) {
            cg_free_cstr_array(context_names, context_count);
            free((void *)context_constraints);
            return false;
        }
        free((void *)context_constraints);
        context_constraints = NULL;
        if (has_open_type_arg &&
            cg_find_generic_instance_user_type_with_context(cg,
                                                            decl,
                                                            type_args,
                                                            type_arg_count,
                                                            context_names,
                                                            context_count) != NULL) {
            cg_free_cstr_array(context_names, context_count);
            free(context_constraint_indices);
            return true;
        }
    }
    if (!has_open_type_arg &&
        cg_find_generic_instance_user_type(cg, decl, type_args, type_arg_count) != NULL) {
        return true;
    }
    if (cg->user_type_count + 1 > cg->user_type_capacity) {
        uintptr_t old_base = (uintptr_t)cg->user_types;
        size_t old_count = cg->user_type_count;
        size_t cap = cg->user_type_capacity ? cg->user_type_capacity * 2 : 4;
        void *p = realloc(cg->user_types, cap * sizeof *cg->user_types);
        if (!p) return false;
        cg->user_types = p;
        cg->user_type_capacity = cap;
        cg_refresh_user_fit_targets(cg);
        cg_refresh_user_type_references(cg, old_base, old_count);
    }

    UserType *t = &cg->user_types[cg->user_type_count++];
    memset(t, 0, sizeof *t);
    t->owner_program = generic_decl->owner_program;
    t->instantiation_program = cg->cur_program != NULL
        ? cg->cur_program
        : generic_decl->owner_program;
    t->decl = decl;
    t->is_generic_instance = true;
    t->generic_origin_decl = decl;
    t->generic_type_arg_count = type_arg_count;
    t->generic_type_args = type_arg_count ? calloc(type_arg_count, sizeof(FengTypeRef *)) : NULL;
    if (type_arg_count && !t->generic_type_args) return false;
    t->generic_context_type_param_names = context_names;
    t->generic_context_type_param_constraint_indices = context_constraint_indices;
    t->generic_context_type_param_count = context_count;
    context_names = NULL;
    context_constraint_indices = NULL;
    context_count = 0U;
    for (size_t i = 0; i < type_arg_count; ++i) {
        t->generic_type_args[i] = cg_type_ref_clone(type_args[i]);
        if (!t->generic_type_args[i]) return false;
    }

    Buf display; buf_init(&display);
    buf_append(&display, decl->as.type_decl.name.data, decl->as.type_decl.name.length);
    buf_append_cstr(&display, "<");
    for (size_t i = 0; i < type_arg_count; ++i) {
        if (i) buf_append_cstr(&display, ", ");
        cg_append_type_ref_display(&display, type_args[i]);
    }
    buf_append_cstr(&display, ">");
    t->feng_name = display.data;

    Buf symbol; buf_init(&symbol);
    if (!cg_append_generic_type_instance_symbol(cg,
                                                &symbol,
                                                decl,
                                                type_args,
                                                type_arg_count)) {
        buf_free(&symbol);
        return false;
    }
    /* Open instances retain their complete descriptor-slot context. Encode
     * that context in the compile-time C identity, as generic specs already
     * do, so two valid scopes such as [U] and [T,U] cannot emit colliding
     * placeholder types while still using different generic-param indices. */
    if (t->generic_context_type_param_count > 0U) {
        buf_append_cstr(&symbol, "__CTX");
        for (size_t i = 0U;
             i < t->generic_context_type_param_count;
             ++i) {
            char *context_name = cg_sanitize(
                t->generic_context_type_param_names[i],
                strlen(t->generic_context_type_param_names[i]));

            if (context_name == NULL) {
                buf_free(&symbol);
                return false;
            }
            buf_append_cstr(&symbol, "__");
            buf_append_cstr(&symbol, context_name);
            free(context_name);
        }
    }

    Buf struct_name; buf_init(&struct_name);
    char *owner_mangle = cg_module_mangle(generic_decl->owner_program->module_segments,
                                          generic_decl->owner_program->module_segment_count);
    if (!owner_mangle) { buf_free(&symbol); return false; }
    buf_append_fmt(&struct_name, "Feng__%s__%s", owner_mangle, symbol.data);
    t->c_struct_name = struct_name.data;

    Buf desc_name; buf_init(&desc_name);
    buf_append_fmt(&desc_name, "FengTypeDesc__%s__%s", owner_mangle, symbol.data);
    t->c_desc_name = desc_name.data;

    Buf zero_name; buf_init(&zero_name);
    buf_append_fmt(&zero_name, "%s__default_zero", t->c_struct_name);
    t->c_default_zero_name = zero_name.data;
    if (!cg_init_user_type_value_symbols(t)) {
        free(owner_mangle);
        buf_free(&symbol);
        return false;
    }
    t->is_abi_type = cg_annotations_contain_kind(decl->annotations,
                                                 decl->annotation_count,
                                                 FENG_ANNOTATION_ABI);
    if (!cg_init_user_type_abi_symbols(t)) {
        free(owner_mangle);
        buf_free(&symbol);
        return false;
    }

    free(owner_mangle);
    buf_free(&symbol);
    if (!t->feng_name || !t->c_struct_name || !t->c_desc_name || !t->c_default_zero_name ||
        (cg_user_type_is_value_semantics(t) &&
         (!t->c_aggregate_slots_name || !t->c_aggregate_default_name ||
          !t->c_aggregate_desc_name || !t->c_value_box_struct_name ||
          !t->c_value_box_desc_name || !t->c_value_box_release_children_name))) {
        return false;
    }

    CGTypeParamScope constraint_scope = {0};
    constraint_scope.first = decl->as.type_decl.type_params;
    constraint_scope.first_count = decl->as.type_decl.type_param_count;
    if (!cg_collect_generic_instances_from_type_params_from_program(
            cg,
            decl->as.type_decl.type_params,
            decl->as.type_decl.type_param_count,
            constraint_scope,
            generic_decl->owner_program)) {
        return false;
    }

    /* Substituted members inherit the instantiation point's still-open
     * parameters. A callable member adds its own generic scope below. */
    CGTypeParamScope member_scope = open_scope != NULL
        ? *open_scope
        : (CGTypeParamScope){0};
    for (size_t i = 0; i < decl->as.type_decl.member_count; ++i) {
        const FengTypeMember *member = decl->as.type_decl.members[i];
        if (member->kind == FENG_TYPE_MEMBER_FIELD) {
            /* Inferred fields (field.type == NULL, e.g.
             * `let items = Inner<T>()`) carry their type only as a semantic
             * type fact.  Fall back to it so the field's generic instance
             * (e.g. Inner<i32> when registering Holder<i32>) is substituted
             * and collected; otherwise substituting NULL yields NULL and
             * silently aborts instance registration with CE0353. */
            const FengTypeRef *field_type_ref = member->as.field.type;
            if (field_type_ref == NULL && cg->analysis != NULL) {
                const FengSemanticTypeFact *fact =
                    feng_semantic_lookup_type_fact(cg->analysis, member);
                if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
                    field_type_ref = fact->type_ref;
                }
            }
            FengTypeRef *sub = cg_type_ref_substitute(field_type_ref,
                                                      decl->as.type_decl.type_params,
                                                      decl->as.type_decl.type_param_count,
                                                      type_args);
            if (!sub) {
                /* field_type_ref may legitimately be NULL when neither an
                 * explicit type nor a semantic fact is available (e.g. an
                 * unbound placeholder); skip collection for that field
                 * instead of aborting the whole instance registration. */
                continue;
            }
            bool ok = cg_collect_generic_instances_from_substituted_type_ref(
                cg,
                field_type_ref,
                sub,
                decl->as.type_decl.type_params,
                decl->as.type_decl.type_param_count,
                member_scope,
                generic_decl->owner_program);
            cg_type_ref_free(sub);
            if (!ok) return false;
        } else if (member->kind == FENG_TYPE_MEMBER_METHOD ||
                   member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR ||
                   member->kind == FENG_TYPE_MEMBER_FINALIZER) {
            const FengCallableSignature *callable = &member->as.callable;
            if (!cg_collect_instantiated_callable_member_instances(
                    cg,
                    callable,
                    decl->as.type_decl.type_params,
                    decl->as.type_decl.type_param_count,
                    type_args,
                    member_scope,
                    generic_decl->owner_program)) {
                return false;
            }

            /* A fully closed generic owner emits one closed function
             * descriptor for each non-method-generic ordinary method. Close
             * that method's implementation dependencies while registering
             * the owner shell, before any wrapper attempts to resolve their
             * descriptor symbols. Direct calls also collect this set, but
             * owner registration must be complete on its own for witness and
             * other indirect wrapper consumers. */
            if (!has_open_type_arg &&
                member->kind == FENG_TYPE_MEMBER_METHOD &&
                callable->type_param_count == 0U &&
                !cg_collect_closed_reifiable_dep_instances(
                    cg,
                    feng_semantic_lookup_member_reifiable_dep_set(
                        cg->analysis, decl, member),
                    decl->as.type_decl.type_params,
                    decl->as.type_decl.type_param_count,
                    type_args,
                    member_scope,
                    generic_decl->owner_program,
                    member->token)) {
                return false;
            }
        }
    }
    if (!cg_collect_closed_reifiable_dep_instances(
            cg,
            feng_semantic_lookup_reifiable_dep_set(cg->analysis, decl),
            decl->as.type_decl.type_params,
            decl->as.type_decl.type_param_count,
            type_args,
            member_scope,
            generic_decl->owner_program,
            blame)) {
        cg_free_cstr_array(context_names, context_count);
        return false;
    }
    cg_free_cstr_array(context_names, context_count);
    return true;
}

static bool cg_type_ref_is_builtin_fit_param(const FengTypeRef *ref,
                                             const BuiltinFit *bf,
                                             size_t *out_index) {
    if (ref == NULL || bf == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.segment_count != 1U || ref->as.named.type_arg_count != 0U) {
        return false;
    }
    for (size_t i = 0; i < bf->target_type_param_count; ++i) {
        if (ref->as.named.segments[0].length == bf->target_type_params[i].name.length &&
            memcmp(ref->as.named.segments[0].data,
                   bf->target_type_params[i].name.data,
                   ref->as.named.segments[0].length) == 0) {
            if (out_index != NULL) *out_index = i;
            return true;
        }
    }
    return false;
}

static CGType *cg_instantiate_builtin_fit_return_type(CG *cg,
                                                       const BuiltinFit *bf,
                                                       const CGType *return_type,
                                                       const CGType *receiver_element,
                                                       FengToken blame) {
    CGType *result;

    if (return_type == NULL) return NULL;
    if (bf == NULL || bf->target_type_param_count == 0U || receiver_element == NULL) {
        return cgtype_clone(return_type);
    }

    if (return_type->kind == CG_TYPE_GENERIC_PARAM) {
        if (return_type->generic_param_index == 0U) {
            return cgtype_clone(receiver_element);
        }
        return NULL;
    }

    if (return_type->kind == CG_TYPE_ARRAY || return_type->kind == CG_TYPE_POINTER) {
        result = cgtype_new(return_type->kind);
        if (result == NULL) return NULL;
        result->element = cg_instantiate_builtin_fit_return_type(cg,
                                                                 bf,
                                                                 return_type->element,
                                                                 receiver_element,
                                                                 blame);
        if (result->element == NULL) {
            cgtype_free(result);
            return NULL;
        }
        return result;
    }

    if (return_type->kind == CG_TYPE_OBJECT && return_type->user != NULL &&
        return_type->user->is_generic_instance &&
        return_type->user->generic_context_type_param_count > 0U) {
        const UserType *open_user = return_type->user;
        const GenericTypeDecl *generic_decl = cg_find_generic_type_decl_by_decl(cg,
            open_user->generic_origin_decl);
        const FengDecl *origin_decl = open_user->generic_origin_decl;
        size_t open_arg_count = open_user->generic_type_arg_count;
        FengTypeRef **type_args;
        UserType *concrete_user;

        if (generic_decl == NULL) return NULL;
        type_args = open_arg_count > 0U
            ? calloc(open_arg_count, sizeof *type_args)
            : NULL;
        if (open_arg_count > 0U && type_args == NULL) {
            return NULL;
        }
        for (size_t i = 0; i < open_arg_count; ++i) {
            size_t param_index = 0U;
            if (cg_type_ref_is_builtin_fit_param(open_user->generic_type_args[i],
                                                 bf,
                                                 &param_index)) {
                if (param_index != 0U) {
                    for (size_t j = 0; j < i; ++j) cg_type_ref_free(type_args[j]);
                    free(type_args);
                    return NULL;
                }
                type_args[i] = cg_type_ref_from_cgtype(cg, receiver_element, blame);
            } else {
                type_args[i] = cg_type_ref_clone(open_user->generic_type_args[i]);
            }
            if (type_args[i] == NULL) {
                for (size_t j = 0; j < i; ++j) cg_type_ref_free(type_args[j]);
                free(type_args);
                return NULL;
            }
        }
        if (!cg_register_generic_type_instance_shell(cg,
                                                    generic_decl,
                                                    type_args,
                                                    open_arg_count,
                                                    blame,
                                                    NULL)) {
            for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
            free(type_args);
            return NULL;
        }
        concrete_user = cg_find_generic_instance_user_type(cg,
                                                           origin_decl,
                                                           type_args,
                                                           open_arg_count);
        if (concrete_user == NULL) {
            for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
            free(type_args);
            return NULL;
        }
        if (concrete_user->field_count == 0U &&
            concrete_user->constructor_count == 0U &&
            concrete_user->method_count == 0U &&
            concrete_user->static_method_count == 0U &&
            concrete_user->decl != NULL &&
            concrete_user->decl->kind == FENG_DECL_TYPE &&
            concrete_user->decl->as.type_decl.member_count > 0U) {
            const FengProgram *saved_program = cg->cur_program;
            const FengProgram *instance_program = concrete_user->instantiation_program != NULL
                ? concrete_user->instantiation_program
                : concrete_user->owner_program;
            Buf *saved_cur_body = cg->cur_body;
            CGType *saved_cur_return_type = cg->cur_return_type;
            Scope *saved_cur_scope = cg->cur_scope;
            bool saved_cur_fn_is_main = cg->cur_fn_is_main;

            cg->cur_program = instance_program;
            if (!cg_register_user_type_members(cg, concrete_user, FENG_COMPILE_TARGET_BIN)) {
                cg->cur_program = saved_program;
                for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
                free(type_args);
                return NULL;
            }
            concrete_user = cg_find_generic_instance_user_type(cg,
                                                               origin_decl,
                                                               type_args,
                                                               open_arg_count);
            if (concrete_user == NULL) {
                cg->cur_program = saved_program;
                for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
                free(type_args);
                return NULL;
            }
            cg_emit_user_type_forward(cg, concrete_user);
            cg_emit_user_type_definition(cg, (UserType *)concrete_user);
            {
                Buf saved_fn_defs = cg->fn_defs;
                cg->fn_defs = cg->witness_defs;
                cg->witness_defs = saved_fn_defs;
                cg->cur_body = &cg->fn_defs;
            }
            for (size_t ci = 0; ci < concrete_user->constructor_count; ++ci) {
                if (!cg_emit_generic_type_method_wrapper(cg, concrete_user, &concrete_user->constructors[ci], NULL, NULL, NULL)) {
                    Buf emitted_defs = cg->fn_defs;
                    cg->fn_defs = cg->witness_defs;
                    cg->witness_defs = emitted_defs;
                    cg->cur_body = saved_cur_body;
                    cg->cur_return_type = saved_cur_return_type;
                    cg->cur_scope = saved_cur_scope;
                    cg->cur_fn_is_main = saved_cur_fn_is_main;
                    cg->cur_program = saved_program;
                    for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
                    free(type_args);
                    return NULL;
                }
            }
            for (size_t mi = 0; mi < concrete_user->method_count; ++mi) {
                if (!cg_emit_generic_type_method_wrapper(cg, concrete_user, &concrete_user->methods[mi], NULL, NULL, NULL)) {
                    Buf emitted_defs = cg->fn_defs;
                    cg->fn_defs = cg->witness_defs;
                    cg->witness_defs = emitted_defs;
                    cg->cur_body = saved_cur_body;
                    cg->cur_return_type = saved_cur_return_type;
                    cg->cur_scope = saved_cur_scope;
                    cg->cur_fn_is_main = saved_cur_fn_is_main;
                    cg->cur_program = saved_program;
                    for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
                    free(type_args);
                    return NULL;
                }
            }
            for (size_t mi = 0; mi < concrete_user->static_method_count; ++mi) {
                if (!cg_emit_generic_type_method_wrapper(cg, concrete_user, &concrete_user->static_methods[mi], NULL, NULL, NULL)) {
                    Buf emitted_defs = cg->fn_defs;
                    cg->fn_defs = cg->witness_defs;
                    cg->witness_defs = emitted_defs;
                    cg->cur_body = saved_cur_body;
                    cg->cur_return_type = saved_cur_return_type;
                    cg->cur_scope = saved_cur_scope;
                    cg->cur_fn_is_main = saved_cur_fn_is_main;
                    cg->cur_program = saved_program;
                    for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
                    free(type_args);
                    return NULL;
                }
            }
            if (!cg_emit_user_finalizer(cg, concrete_user)) {
                Buf emitted_defs = cg->fn_defs;
                cg->fn_defs = cg->witness_defs;
                cg->witness_defs = emitted_defs;
                cg->cur_body = saved_cur_body;
                cg->cur_return_type = saved_cur_return_type;
                cg->cur_scope = saved_cur_scope;
                cg->cur_fn_is_main = saved_cur_fn_is_main;
                cg->cur_program = saved_program;
                for (size_t i = 0; i < open_arg_count; ++i) {
                    cg_type_ref_free(type_args[i]);
                }
                free(type_args);
                return NULL;
            }
            {
                Buf emitted_defs = cg->fn_defs;
                cg->fn_defs = cg->witness_defs;
                cg->witness_defs = emitted_defs;
                cg->cur_body = saved_cur_body;
                cg->cur_return_type = saved_cur_return_type;
                cg->cur_scope = saved_cur_scope;
                cg->cur_fn_is_main = saved_cur_fn_is_main;
            }
            cg->cur_program = saved_program;
        }
        for (size_t i = 0; i < open_arg_count; ++i) cg_type_ref_free(type_args[i]);
        free(type_args);
        result = cgtype_new(CG_TYPE_OBJECT);
        if (result == NULL) return NULL;
        result->user = concrete_user;
        return result;
    }

    return cgtype_clone(return_type);
}

static bool cg_register_generic_spec_instance_shell(CG *cg,
                                                    const GenericSpecDecl *generic_decl,
                                                    FengTypeRef *const *type_args,
                                                    size_t type_arg_count,
                                                    FengToken blame,
                                                    const CGTypeParamScope *open_scope) {
    if (generic_decl == NULL || generic_decl->decl == NULL) return true;
    const FengDecl *decl = generic_decl->decl;
    char **context_names = NULL;
    size_t context_count = 0U;
    bool has_open_type_arg = false;

    if (decl->kind != FENG_DECL_SPEC) return true;
    if (type_arg_count != decl->as.spec_decl.type_param_count) {
        return cg_fail(cg, blame,
                       "CE0030", "codegen: generic spec '%.*s' expects %zu type argument(s), got %zu",
                       (int)decl->as.spec_decl.name.length,
                       decl->as.spec_decl.name.data,
                       decl->as.spec_decl.type_param_count,
                       type_arg_count);
    }
    for (size_t i = 0; i < type_arg_count; ++i) {
        if (cg_type_ref_contains_type_param(type_args[i], open_scope)) {
            has_open_type_arg = true;
            break;
        }
    }
    if (has_open_type_arg &&
        !cg_type_param_scope_copy_names(open_scope, &context_names, &context_count)) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (cg_find_generic_instance_user_spec_with_context(cg,
                                                        decl,
                                                        type_args,
                                                        type_arg_count,
                                                        context_names,
                                                        context_count) != NULL) {
        cg_free_cstr_array(context_names, context_count);
        return true;
    }
    if (cg->user_spec_count + 1 > cg->user_spec_capacity) {
        uintptr_t old_base = (uintptr_t)cg->user_specs;
        size_t old_count = cg->user_spec_count;
        size_t cap = cg->user_spec_capacity ? cg->user_spec_capacity * 2 : 4;
        void *p = realloc(cg->user_specs, cap * sizeof *cg->user_specs);
        if (!p) {
            cg_free_cstr_array(context_names, context_count);
            return false;
        }
        cg->user_specs = p;
        cg->user_spec_capacity = cap;
        cg_refresh_user_fit_specs(cg);
        cg_refresh_user_spec_references(cg, old_base, old_count);
    }

    UserSpec *s = &cg->user_specs[cg->user_spec_count++];
    memset(s, 0, sizeof *s);
    s->owner_program = generic_decl->owner_program;
    s->instantiation_program = cg->cur_program != NULL
        ? cg->cur_program
        : generic_decl->owner_program;
    s->decl = decl;
    s->form = decl->as.spec_decl.form;
    s->is_generic_instance = true;
    s->generic_origin_decl = decl;
    s->generic_type_arg_count = type_arg_count;
    s->generic_context_type_param_names = context_names;
    s->generic_context_type_param_count = context_count;
    context_names = NULL;
    context_count = 0U;
    s->generic_type_args = type_arg_count ? calloc(type_arg_count, sizeof(FengTypeRef *)) : NULL;
    if (type_arg_count > 0U && s->generic_type_args == NULL) return false;
    for (size_t i = 0; i < type_arg_count; ++i) {
        s->generic_type_args[i] = cg_type_ref_clone(type_args[i]);
        if (s->generic_type_args[i] == NULL) return false;
    }

    Buf display; buf_init(&display);
    buf_append(&display, decl->as.spec_decl.name.data, decl->as.spec_decl.name.length);
    buf_append_cstr(&display, "<");
    for (size_t i = 0; i < type_arg_count; ++i) {
        if (i) buf_append_cstr(&display, ", ");
        cg_append_type_ref_display(&display, type_args[i]);
    }
    buf_append_cstr(&display, ">");
    s->feng_name = display.data;

    char *base_san = cg_sanitize(decl->as.spec_decl.name.data,
                                 decl->as.spec_decl.name.length);
    if (base_san == NULL) return false;

    Buf symbol; buf_init(&symbol);
    buf_append_cstr(&symbol, base_san);
    buf_append_cstr(&symbol, "__G");
    for (size_t i = 0; i < type_arg_count; ++i) {
        buf_append_cstr(&symbol, "__");
        if (!cg_append_type_ref_symbol(cg, &symbol, type_args[i])) {
            free(base_san);
            buf_free(&symbol);
            return false;
        }
    }
    if (s->generic_context_type_param_count > 0U) {
        buf_append_cstr(&symbol, "__CTX");
        for (size_t i = 0; i < s->generic_context_type_param_count; ++i) {
            char *ctx_san = cg_sanitize(s->generic_context_type_param_names[i],
                                        strlen(s->generic_context_type_param_names[i]));
            if (ctx_san == NULL) {
                free(base_san);
                buf_free(&symbol);
                return false;
            }
            buf_append_cstr(&symbol, "__");
            buf_append_cstr(&symbol, ctx_san);
            free(ctx_san);
        }
    }

    char *owner_mangle = cg_module_mangle(generic_decl->owner_program->module_segments,
                                          generic_decl->owner_program->module_segment_count);
    if (owner_mangle == NULL) {
        free(base_san);
        buf_free(&symbol);
        return false;
    }

    if (s->form == FENG_SPEC_FORM_OBJECT || s->form == FENG_SPEC_FORM_UNION ||
        s->form == FENG_SPEC_FORM_INTERSECTION) {
        Buf vb; buf_init(&vb);
        if (s->form == FENG_SPEC_FORM_OBJECT ||
            s->form == FENG_SPEC_FORM_INTERSECTION) {
            buf_append_fmt(&vb, "FengSpecValue__%s__%s__GenericABI",
                           owner_mangle, base_san);
        } else {
            buf_append_fmt(&vb, "FengSpecValue__%s__%s",
                           owner_mangle, symbol.data);
        }
        s->c_value_struct_name = vb.data;

        Buf db; buf_init(&db);
        buf_append_fmt(&db, "FengSpecAgg__%s__%s", owner_mangle, symbol.data);
        s->c_aggregate_desc_name = db.data;

        Buf sb; buf_init(&sb);
        buf_append_fmt(&sb, "FengSpecAggSlots__%s__%s", owner_mangle, symbol.data);
        s->c_aggregate_slots_name = sb.data;

        Buf db2; buf_init(&db2);
        buf_append_fmt(&db2, "FengSpecAggDefault__%s__%s", owner_mangle, symbol.data);
        s->c_aggregate_default_name = db2.data;

        Buf ib; buf_init(&ib);
        buf_append_fmt(&ib, "FengSpecAggInit__%s__%s", owner_mangle, symbol.data);
        s->c_aggregate_init_fn_name = ib.data;

        Buf wb; buf_init(&wb);
        if (s->form == FENG_SPEC_FORM_OBJECT ||
            s->form == FENG_SPEC_FORM_INTERSECTION) {
            buf_append_fmt(&wb, "FengSpecWitness__%s__%s__GenericABI",
                           owner_mangle, base_san);
        } else {
            buf_append_fmt(&wb, "FengSpecWitness__%s__%s",
                           owner_mangle, symbol.data);
        }
        s->c_witness_struct_name = wb.data;

        if (s->form == FENG_SPEC_FORM_OBJECT || s->form == FENG_SPEC_FORM_INTERSECTION) {
            Buf dssb; buf_init(&dssb);
            buf_append_fmt(&dssb, "FengSpecDefault__%s__%s__Subject",
                           owner_mangle, symbol.data);
            s->c_default_subject_struct_name = dssb.data;

            Buf ddb; buf_init(&ddb);
            buf_append_fmt(&ddb, "FengSpecDefault__%s__%s__Subject_desc",
                           owner_mangle, symbol.data);
            s->c_default_subject_desc_name = ddb.data;

            Buf dnb; buf_init(&dnb);
            buf_append_fmt(&dnb, "FengSpecDefault__%s__%s__new_subject",
                           owner_mangle, symbol.data);
            s->c_default_subject_new_name = dnb.data;

            Buf dwb; buf_init(&dwb);
            buf_append_fmt(&dwb, "FengSpecDefaultWitness__%s__%s",
                           owner_mangle, symbol.data);
            s->c_default_witness_name = dwb.data;
        }
    } else {
        Buf wb; buf_init(&wb);
        buf_append_fmt(&wb, "FengSpecWitness__%s__%s", owner_mangle, symbol.data);
        s->c_witness_struct_name = wb.data;

        Buf cb; buf_init(&cb);
        buf_append_fmt(&cb, "FengClosure__%s__%s", owner_mangle, symbol.data);
        s->c_closure_struct_name = cb.data;

        Buf db; buf_init(&db);
        buf_append_fmt(&db, "FengClosureDesc__%s__%s", owner_mangle, symbol.data);
        s->c_closure_desc_name = db.data;

        Buf pb; buf_init(&pb);
        buf_append_fmt(&pb, "FengAbiFnPtr__%s__%s", owner_mangle, symbol.data);
        s->c_abi_fn_ptr_typedef_name = pb.data;

        Buf nb; buf_init(&nb);
        buf_append_fmt(&nb, "FengCallableDefault__%s__%s__noop", owner_mangle, symbol.data);
        s->c_default_callable_noop_name = nb.data;

        Buf fb; buf_init(&fb);
        buf_append_fmt(&fb, "FengCallableDefault__%s__%s__new", owner_mangle, symbol.data);
        s->c_default_callable_new_name = fb.data;
    }

    free(owner_mangle);
    free(base_san);
    buf_free(&symbol);
    if (s->form == FENG_SPEC_FORM_OBJECT || s->form == FENG_SPEC_FORM_INTERSECTION) {
        if (!(s->feng_name && s->c_value_struct_name && s->c_witness_struct_name &&
              s->c_aggregate_desc_name && s->c_aggregate_slots_name &&
              s->c_aggregate_default_name && s->c_aggregate_init_fn_name &&
              s->c_default_subject_struct_name && s->c_default_subject_desc_name &&
              s->c_default_subject_new_name && s->c_default_witness_name)) {
            return false;
        }
    } else if (s->form == FENG_SPEC_FORM_UNION) {
        if (!(s->feng_name && s->c_value_struct_name && s->c_witness_struct_name &&
              s->c_aggregate_desc_name && s->c_aggregate_slots_name &&
              s->c_aggregate_default_name && s->c_aggregate_init_fn_name)) {
            return false;
        }
    } else if (!(s->feng_name && s->c_witness_struct_name && s->c_closure_struct_name &&
                 s->c_closure_desc_name && s->c_abi_fn_ptr_typedef_name &&
                 s->c_default_callable_noop_name && s->c_default_callable_new_name)) {
        return false;
    }

    for (size_t parent_index = 0; parent_index < decl->as.spec_decl.parent_spec_count; ++parent_index) {
        CGTypeParamScope parent_scope = open_scope != NULL ? *open_scope : (CGTypeParamScope){0};
        FengTypeRef *sub = cg_type_ref_substitute(decl->as.spec_decl.parent_specs[parent_index],
                                                  decl->as.spec_decl.type_params,
                                                  decl->as.spec_decl.type_param_count,
                                                  type_args);
        bool ok;

        if (sub == NULL) return false;
        ok = cg_collect_generic_instances_from_substituted_type_ref(
            cg,
            decl->as.spec_decl.parent_specs[parent_index],
            sub,
            decl->as.spec_decl.type_params,
            decl->as.spec_decl.type_param_count,
            parent_scope,
            generic_decl->owner_program);
        cg_type_ref_free(sub);
        if (!ok) return false;
    }
    if (s->form == FENG_SPEC_FORM_OBJECT) {
        CGTypeParamScope member_scope = open_scope != NULL
            ? *open_scope
            : (CGTypeParamScope){0};

        for (size_t member_index = 0U;
             member_index < decl->as.spec_decl.as.object.member_count;
             ++member_index) {
            const FengTypeMember *member =
                decl->as.spec_decl.as.object.members[member_index];

            if (member->kind == FENG_TYPE_MEMBER_FIELD) {
                FengTypeRef *substituted = cg_type_ref_substitute(
                    member->as.field.type,
                    decl->as.spec_decl.type_params,
                    decl->as.spec_decl.type_param_count,
                    type_args);
                bool ok;

                if (substituted == NULL) return false;
                ok = cg_collect_generic_instances_from_substituted_type_ref(
                    cg,
                    member->as.field.type,
                    substituted,
                    decl->as.spec_decl.type_params,
                    decl->as.spec_decl.type_param_count,
                    member_scope,
                    generic_decl->owner_program);
                cg_type_ref_free(substituted);
                if (!ok) return false;
            } else if (member->kind == FENG_TYPE_MEMBER_METHOD) {
                if (!cg_collect_instantiated_callable_member_instances(
                        cg,
                        &member->as.callable,
                        decl->as.spec_decl.type_params,
                        decl->as.spec_decl.type_param_count,
                        type_args,
                        member_scope,
                        generic_decl->owner_program)) {
                    return false;
                }
            }
        }
    } else if (s->form == FENG_SPEC_FORM_CALLABLE) {
        CGTypeParamScope callable_scope = open_scope != NULL
            ? *open_scope
            : (CGTypeParamScope){0};

        for (size_t parameter_index = 0U;
             parameter_index < decl->as.spec_decl.as.callable.param_count;
             ++parameter_index) {
            const FengTypeRef *parameter_type =
                decl->as.spec_decl.as.callable.params[parameter_index].type;
            FengTypeRef *substituted = cg_type_ref_substitute(
                parameter_type,
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                type_args);
            bool ok;

            if (substituted == NULL) return false;
            ok = cg_collect_generic_instances_from_substituted_type_ref(
                cg,
                parameter_type,
                substituted,
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                callable_scope,
                generic_decl->owner_program);
            cg_type_ref_free(substituted);
            if (!ok) return false;
        }
        if (decl->as.spec_decl.as.callable.return_type != NULL) {
            const FengTypeRef *return_type =
                decl->as.spec_decl.as.callable.return_type;
            FengTypeRef *substituted = cg_type_ref_substitute(
                return_type,
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                type_args);
            bool ok;

            if (substituted == NULL) return false;
            ok = cg_collect_generic_instances_from_substituted_type_ref(
                cg,
                return_type,
                substituted,
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                callable_scope,
                generic_decl->owner_program);
            cg_type_ref_free(substituted);
            if (!ok) return false;
        }
    }
    if (s->form == FENG_SPEC_FORM_UNION) {
        for (size_t member_index = 0U;
             member_index < decl->as.spec_decl.as.union_form.member_count;
             ++member_index) {
            CGTypeParamScope member_scope = open_scope != NULL ? *open_scope : (CGTypeParamScope){0};
            FengTypeRef *sub = cg_type_ref_substitute(decl->as.spec_decl.as.union_form.members[member_index],
                                                      decl->as.spec_decl.type_params,
                                                      decl->as.spec_decl.type_param_count,
                                                      type_args);
            bool ok;

            if (sub == NULL) return false;
            ok = cg_collect_generic_instances_from_substituted_type_ref(
                cg,
                decl->as.spec_decl.as.union_form.members[member_index],
                sub,
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                member_scope,
                generic_decl->owner_program);
            cg_type_ref_free(sub);
            if (!ok) return false;
        }
    }
    /* 9.9: intersection-form members also need their type-arg-substituted
     * generic instances registered (e.g. `spec Comparable<T>: Eq<T> & Ord<T>`
     * instantiated as `Comparable<IntBox>` must register `Eq<IntBox>` and
     * `Ord<IntBox>`). Without this, cg_register_user_spec_members cannot
     * locate the member-spec instances later. */
    if (s->form == FENG_SPEC_FORM_INTERSECTION) {
        for (size_t member_index = 0U;
             member_index < decl->as.spec_decl.as.intersection_form.member_count;
             ++member_index) {
            CGTypeParamScope member_scope = open_scope != NULL ? *open_scope : (CGTypeParamScope){0};
            FengTypeRef *sub = cg_type_ref_substitute(
                decl->as.spec_decl.as.intersection_form.members[member_index],
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                type_args);
            bool ok;

            if (sub == NULL) return false;
            ok = cg_collect_generic_instances_from_substituted_type_ref(
                cg,
                decl->as.spec_decl.as.intersection_form.members[member_index],
                sub,
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                member_scope,
                generic_decl->owner_program);
            cg_type_ref_free(sub);
            if (!ok) return false;
        }
    }
    return true;
}

static bool cg_resolve_type(CG *cg, const FengTypeRef *ref, const FengToken *fallback,
                            CGType **out_type) {
    *out_type = NULL;
    if (!ref) {
        *out_type = cgtype_new(CG_TYPE_VOID);
        return *out_type != NULL;
    }
    if (cg->current_user_fit != NULL &&
        cg->current_user_fit->target != NULL &&
        cg->current_user_fit->target->is_generic_instance) {
        const UserFit *active_fit = cg->current_user_fit;
        const FengDecl *target_decl = active_fit->target->generic_origin_decl;

        if (target_decl != NULL && target_decl->kind == FENG_DECL_TYPE &&
            target_decl->as.type_decl.type_param_count > 0U) {
            FengTypeRef *substituted = cg_type_ref_substitute(
                ref,
                target_decl->as.type_decl.type_params,
                target_decl->as.type_decl.type_param_count,
                active_fit->target->generic_type_args);
            bool ok;

            if (substituted == NULL) {
                return false;
            }
            cg->current_user_fit = NULL;
            ok = cg_resolve_type(cg, substituted, fallback, out_type);
            cg->current_user_fit = active_fit;
            cg_type_ref_free(substituted);
            return ok;
        }
    }
    if (ref->kind == FENG_TYPE_REF_NAMED) {
        const size_t segment_count = ref->as.named.segment_count;
        const FengSlice *seg = &ref->as.named.segments[segment_count - 1U];

        if (ref->as.named.type_arg_count > 0U) {
            const GenericTypeDecl *generic_decl = cg_find_generic_type_decl(cg, ref);
            bool uses_active_context = false;
            UserType *generic_instance = NULL;

            if (generic_decl != NULL) {
                uses_active_context =
                    (cg->in_generic_fn &&
                     cg_type_args_contain_type_param_names(ref->as.named.type_args,
                                                           ref->as.named.type_arg_count,
                                                           cg->generic_fn_type_param_names,
                                                           cg->generic_fn_type_param_count)) ||
                    (cg->ambient_type_param_count > 0U &&
                     cg_type_args_contain_type_param_names(ref->as.named.type_args,
                                                           ref->as.named.type_arg_count,
                                                           cg->ambient_type_param_names,
                                                           cg->ambient_type_param_count));
                generic_instance = cg_find_generic_instance_user_type_with_active_context(
                    cg,
                    generic_decl->decl,
                    ref->as.named.type_args,
                    ref->as.named.type_arg_count);
                (void)uses_active_context;
            }
            if (generic_instance != NULL) {
                CGType *t = cgtype_new(CG_TYPE_OBJECT);
                if (!t) return false;
                t->user = generic_instance;
                *out_type = t;
                return true;
            }
            UserSpec *generic_spec_instance = cg_find_generic_instance_user_spec_for_ref(cg, ref);
            if (generic_spec_instance != NULL) {
                CGType *t = cgtype_new(generic_spec_instance->form == FENG_SPEC_FORM_CALLABLE
                                       ? CG_TYPE_CALLABLE
                                       : CG_TYPE_SPEC);
                if (!t) return false;
                t->user_spec = generic_spec_instance;
                *out_type = t;
                return true;
            }
            return cg_fail(cg, ref->token,
                "CE0031", "codegen: generic type/spec instance '%.*s<...>' was not registered",
                (int)seg->length, seg->data);
        }
        /* G6: when inside a generic function body, check type parameter names
         * first so they shadow any same-named types in scope. */
        if (ref->as.named.type_arg_count == 0 && segment_count == 1U) {
            for (size_t i = 0; i < cg->generic_fn_type_param_count; i++) {
                const char *tp;
                if (!cg->in_generic_fn) break;
                tp = cg->generic_fn_type_param_names[i];
                if (seg->length == strlen(tp) &&
                    memcmp(seg->data, tp, seg->length) == 0) {
                    CGType *t = cgtype_new(CG_TYPE_GENERIC_PARAM);
                    if (!t) return false;
                    t->generic_param_index = i;
                    *out_type = t;
                    return true;
                }
            }
            for (size_t i = 0; i < cg->ambient_type_param_count; i++) {
                const char *tp = cg->ambient_type_param_names[i];
                if (seg->length == strlen(tp) &&
                    memcmp(seg->data, tp, seg->length) == 0) {
                    CGType *t = cgtype_new(CG_TYPE_GENERIC_PARAM);
                    if (!t) return false;
                    t->generic_param_index = i;
                    *out_type = t;
                    return true;
                }
            }
        }

        if (segment_count == 1U) {
            for (size_t i = 0; i < sizeof k_builtin_types / sizeof k_builtin_types[0]; i++) {
                const BuiltinTypeMap *m = &k_builtin_types[i];

                if (strlen(m->name) == seg->length &&
                    memcmp(m->name, seg->data, seg->length) == 0) {
                    *out_type = cgtype_new(m->kind);
                    return *out_type != NULL;
                }
            }
        }

        const UserType *ut = segment_count == 1U
            ? cg_find_user_type(cg, seg->data, seg->length)
            : cg_find_user_type_by_ref(cg, ref);
        if (ut) {
            CGType *t = cgtype_new(CG_TYPE_OBJECT);
            if (!t) return false;
            t->user = ut;
            *out_type = t;
            return true;
        }

        const UserSpec *us = segment_count == 1U
            ? cg_find_user_spec(cg, seg->data, seg->length)
            : cg_find_user_spec_by_ref(cg, ref);
        if (us) {
            CGType *t = cgtype_new(us->form == FENG_SPEC_FORM_CALLABLE
                                   ? CG_TYPE_CALLABLE
                                   : CG_TYPE_SPEC);
            if (!t) return false;
            t->user_spec = us;
            *out_type = t;
            return true;
        }

        {
            const FengDecl *enum_decl = segment_count == 1U
                ? cg_find_visible_enum_decl(cg, seg->data, seg->length)
                : cg_find_enum_decl_by_ref(cg, ref);

            if (enum_decl != NULL) {
                *out_type = cgtype_new_enum(enum_decl);
                return *out_type != NULL;
            }
        }
        FengToken tk = fallback ? *fallback : ref->token;
        (void)tk;
        return cg_fail(cg, ref->token,
            "CE0032", "codegen: unknown type '%.*s'",
            (int)seg->length, seg->data);
    }
    if (ref->kind == FENG_TYPE_REF_ARRAY) {
        CGType *elem = NULL;
        if (!cg_resolve_type(cg, ref->as.inner, fallback, &elem)) return false;
        CGType *t = cgtype_new(CG_TYPE_ARRAY);
        if (!t) { cgtype_free(elem); return false; }
        t->element = elem;
        t->array_element_writable = ref->array_element_writable;
        *out_type = t;
        return true;
    }
    if (ref->kind == FENG_TYPE_REF_POINTER) {
        CGType *inner = NULL;
        if (!cg_resolve_type(cg, ref->as.inner, fallback, &inner)) return false;
        if (!cg_pointer_inner_is_lowerable(inner)) {
            cgtype_free(inner);
            return cg_fail(cg, ref->token,
                "CE0033", "codegen: this pointee type does not support ABI pointer lowering");
        }
        CGType *t = cgtype_new(CG_TYPE_POINTER);
        if (!t) {
            cgtype_free(inner);
            return false;
        }
        t->element = inner;
        *out_type = t;
        return true;
    }
    return cg_fail(cg, ref->token,
        "CE0034", "codegen: unknown type reference kind");
}

static bool cg_register_open_generic_type_instances_in_ref(CG *cg,
                                                          const FengTypeRef *ref,
                                                          const CGTypeParamScope *scope,
                                                          FengToken blame);
static bool cg_register_open_generic_type_instances_in_ref_from_program(
    CG *cg,
    const FengTypeRef *ref,
    const CGTypeParamScope *scope,
    FengToken blame,
    const FengProgram *reference_program);

static bool cg_resolve_type_with_open_scope(CG *cg,
                                            const FengTypeRef *ref,
                                            const FengToken *fallback,
                                            const CGTypeParamScope *scope,
                                            CGType **out_type) {
    char **type_param_names = NULL;
    size_t type_param_count = 0U;
    bool saved_in_generic_fn = cg->in_generic_fn;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    FengToken blame = fallback != NULL ? *fallback : (ref != NULL ? ref->token : (FengToken){0});
    bool ok;

    if (scope == NULL || (scope->first_count == 0U && scope->second_count == 0U)) {
        return cg_resolve_type(cg, ref, fallback, out_type);
    }

    if (!cg_type_param_scope_copy_names(scope, &type_param_names, &type_param_count)) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    cg->in_generic_fn = true;
    cg->generic_fn_type_param_count = type_param_count;
    cg->generic_fn_type_param_names = type_param_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;

    if (!cg_register_open_generic_type_instances_in_ref(cg, ref, scope, blame)) {
        cg->in_generic_fn = saved_in_generic_fn;
        cg->generic_fn_type_param_count = saved_tp_count;
        cg->generic_fn_type_param_names = saved_tp_names;
        cg->generic_fn_type_param_constraints = saved_tp_constraints;
        cg->generic_fn_type_param_descs = saved_tp_descs;
        cg_free_cstr_array(type_param_names, type_param_count);
        return false;
    }

    if (ref != NULL && ref->kind == FENG_TYPE_REF_NAMED &&
        ref->as.named.type_arg_count > 0U) {
        const GenericTypeDecl *generic_decl = cg_find_generic_type_decl(cg, ref);

        if (generic_decl != NULL) {
            UserType *generic_instance = cg_find_generic_instance_user_type_with_context(
                cg,
                generic_decl->decl,
                ref->as.named.type_args,
                ref->as.named.type_arg_count,
                type_param_names,
                type_param_count);

            if (generic_instance != NULL) {
                CGType *resolved = cgtype_new(CG_TYPE_OBJECT);
                if (resolved == NULL) {
                    cg->in_generic_fn = saved_in_generic_fn;
                    cg->generic_fn_type_param_count = saved_tp_count;
                    cg->generic_fn_type_param_names = saved_tp_names;
                    cg->generic_fn_type_param_constraints = saved_tp_constraints;
                    cg->generic_fn_type_param_descs = saved_tp_descs;
                    cg_free_cstr_array(type_param_names, type_param_count);
                    return false;
                }
                resolved->user = generic_instance;
                *out_type = resolved;
                cg->in_generic_fn = saved_in_generic_fn;
                cg->generic_fn_type_param_count = saved_tp_count;
                cg->generic_fn_type_param_names = saved_tp_names;
                cg->generic_fn_type_param_constraints = saved_tp_constraints;
                cg->generic_fn_type_param_descs = saved_tp_descs;
                cg_free_cstr_array(type_param_names, type_param_count);
                return true;
            }
        }
    }

    ok = cg_resolve_type(cg, ref, fallback, out_type);
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_cstr_array(type_param_names, type_param_count);
    return ok;
}

static bool cg_type_param_names_from_decl(CG *cg,
                                          const FengTypeParam *type_params,
                                          size_t type_param_count,
                                          FengToken blame,
                                          char ***out_names);

/* Resolve a source type reference in the program that declares it. */
static bool cg_resolve_type_from_program(CG *cg,
                                         const FengTypeRef *ref,
                                         const FengProgram *reference_program,
                                         const FengToken *fallback,
                                         CGType **out_type) {
    const FengProgram *saved_program = cg->cur_program;
    bool ok;

    if (reference_program != NULL) {
        cg->cur_program = reference_program;
    }
    ok = cg_resolve_type(cg, ref, fallback, out_type);
    cg->cur_program = saved_program;
    return ok;
}

/* Compute the source shared ABI for every callable parameter. Owner and
 * callable type parameters remain open while resolving the declaration, so a
 * by-value surface whose layout depends on either domain is passed by address.
 * The helper only affects compile-time emission state and restores the caller
 * context before returning. */
static bool cg_build_shared_callable_param_address_flags(
    CG *cg,
    const FengDecl *owner_type_decl,
    const FengCallableSignature *callable,
    const FengProgram *reference_program,
    FengToken blame,
    bool **out_flags) {
    const FengTypeParam *owner_params = NULL;
    size_t owner_count = 0U;
    size_t callable_count;
    size_t combined_count;
    char **type_param_names = NULL;
    bool *flags = NULL;
    bool saved_in_generic_fn;
    size_t saved_type_param_count;
    char **saved_type_param_names;
    const UserSpec **saved_constraints;
    const char **saved_descriptors;
    bool ok = false;

    if (out_flags == NULL || callable == NULL) {
        return false;
    }
    *out_flags = NULL;
    if (owner_type_decl != NULL &&
        owner_type_decl->kind == FENG_DECL_TYPE) {
        owner_params = owner_type_decl->as.type_decl.type_params;
        owner_count = owner_type_decl->as.type_decl.type_param_count;
    }
    callable_count = callable->type_param_count;
    combined_count = owner_count + callable_count;
    if (combined_count > 0U) {
        type_param_names = (char **)calloc(combined_count,
                                           sizeof(*type_param_names));
    }
    if (callable->param_count > 0U) {
        flags = (bool *)calloc(callable->param_count, sizeof(*flags));
    }
    if ((combined_count > 0U && type_param_names == NULL) ||
        (callable->param_count > 0U && flags == NULL)) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t index = 0U; index < owner_count; ++index) {
        type_param_names[index] = strndup(owner_params[index].name.data,
                                          owner_params[index].name.length);
        if (type_param_names[index] == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }
    for (size_t index = 0U; index < callable_count; ++index) {
        type_param_names[owner_count + index] =
            strndup(callable->type_params[index].name.data,
                    callable->type_params[index].name.length);
        if (type_param_names[owner_count + index] == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }

    saved_in_generic_fn = cg->in_generic_fn;
    saved_type_param_count = cg->generic_fn_type_param_count;
    saved_type_param_names = cg->generic_fn_type_param_names;
    saved_constraints = cg->generic_fn_type_param_constraints;
    saved_descriptors = cg->generic_fn_type_param_descs;
    cg->in_generic_fn = true;
    cg->generic_fn_type_param_count = combined_count;
    cg->generic_fn_type_param_names = type_param_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;
    for (size_t index = 0U; index < callable->param_count; ++index) {
        CGType *param_type = NULL;

        if (!cg_resolve_type_from_program(cg,
                                          callable->params[index].type,
                                          reference_program,
                                          &callable->params[index].token,
                                          &param_type)) {
            cg->in_generic_fn = saved_in_generic_fn;
            cg->generic_fn_type_param_count = saved_type_param_count;
            cg->generic_fn_type_param_names = saved_type_param_names;
            cg->generic_fn_type_param_constraints = saved_constraints;
            cg->generic_fn_type_param_descs = saved_descriptors;
            goto cleanup;
        }
        flags[index] = cg_shared_generic_param_uses_address(param_type);
        cgtype_free(param_type);
    }
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_type_param_count;
    cg->generic_fn_type_param_names = saved_type_param_names;
    cg->generic_fn_type_param_constraints = saved_constraints;
    cg->generic_fn_type_param_descs = saved_descriptors;
    *out_flags = flags;
    flags = NULL;
    ok = true;

cleanup:
    cg_free_cstr_array(type_param_names, combined_count);
    free(flags);
    return ok;
}

/* Resolve a generic type node by the declaration context of the original
 * source reference while using the substituted node only for type arguments.
 * This preserves private target identity without changing user name lookup. */
static bool cg_try_resolve_declared_generic_type_ref(
    CG *cg,
    const FengTypeRef *source_ref,
    const FengTypeRef *effective_ref,
    const FengProgram *reference_program,
    const FengToken *fallback,
    CGType **out_type,
    bool *out_handled) {
    *out_type = NULL;
    *out_handled = false;
    if (source_ref == NULL || effective_ref == NULL ||
        source_ref->kind != effective_ref->kind) {
        return true;
    }

    if (source_ref->kind == FENG_TYPE_REF_NAMED) {
        CGNamedGenericTarget target;
        const FengSlice *name;

        if (source_ref->as.named.type_arg_count == 0U ||
            effective_ref->as.named.type_arg_count == 0U) {
            return true;
        }
        target = cg_resolve_named_generic_target_from_program(
            cg, source_ref, reference_program);
        if (target.kind == CG_NAMED_GENERIC_TARGET_NONE) {
            return true;
        }
        *out_handled = true;
        name = &source_ref->as.named.segments[
            source_ref->as.named.segment_count - 1U];

        if (target.kind == CG_NAMED_GENERIC_TARGET_TYPE) {
            UserType *instance =
                cg_find_generic_instance_user_type_with_active_context(
                    cg,
                    target.decl,
                    effective_ref->as.named.type_args,
                    effective_ref->as.named.type_arg_count);
            CGType *resolved;

            if (instance == NULL) {
                return cg_fail(
                    cg,
                    fallback ? *fallback : source_ref->token,
                    "CE0031",
                    "codegen: generic type/spec instance '%.*s<...>' was not registered",
                    (int)name->length,
                    name->data);
            }
            resolved = cgtype_new(CG_TYPE_OBJECT);
            if (resolved == NULL) return false;
            resolved->user = instance;
            *out_type = resolved;
            return true;
        }

        {
            UserSpec *instance =
                cg_find_generic_instance_user_spec_with_active_context(
                    cg,
                    target.decl,
                    effective_ref->as.named.type_args,
                    effective_ref->as.named.type_arg_count);
            CGType *resolved;

            if (instance == NULL) {
                return cg_fail(
                    cg,
                    fallback ? *fallback : source_ref->token,
                    "CE0031",
                    "codegen: generic type/spec instance '%.*s<...>' was not registered",
                    (int)name->length,
                    name->data);
            }
            resolved = cgtype_new(instance->form == FENG_SPEC_FORM_CALLABLE
                                      ? CG_TYPE_CALLABLE
                                      : CG_TYPE_SPEC);
            if (resolved == NULL) return false;
            resolved->user_spec = instance;
            *out_type = resolved;
            return true;
        }
    }

    if (source_ref->kind == FENG_TYPE_REF_ARRAY ||
        source_ref->kind == FENG_TYPE_REF_POINTER) {
        CGType *inner = NULL;
        bool inner_handled = false;
        CGType *resolved;

        if (!cg_try_resolve_declared_generic_type_ref(
                cg,
                source_ref->as.inner,
                effective_ref->as.inner,
                reference_program,
                fallback,
                &inner,
                &inner_handled)) {
            return false;
        }
        if (!inner_handled) {
            return true;
        }
        *out_handled = true;
        if (source_ref->kind == FENG_TYPE_REF_POINTER &&
            !cg_pointer_inner_is_lowerable(inner)) {
            cgtype_free(inner);
            return cg_fail(
                cg,
                effective_ref->token,
                "CE0033",
                "codegen: this pointee type does not support ABI pointer lowering");
        }
        resolved = cgtype_new(source_ref->kind == FENG_TYPE_REF_ARRAY
                                  ? CG_TYPE_ARRAY
                                  : CG_TYPE_POINTER);
        if (resolved == NULL) {
            cgtype_free(inner);
            return false;
        }
        resolved->element = inner;
        if (source_ref->kind == FENG_TYPE_REF_ARRAY) {
            resolved->array_element_writable =
                effective_ref->array_element_writable;
        }
        *out_type = resolved;
    }
    return true;
}

static bool cg_resolve_type_for_user_type_member(CG *cg,
                                                 const UserType *owner,
                                                 const FengTypeRef *ref,
                                                 const FengToken *fallback,
                                                 CGType **out_type) {
    if (owner == NULL) {
        return cg_resolve_type(cg, ref, fallback, out_type);
    }
    if (!owner->is_generic_instance) {
        const FengDecl *owner_decl = owner->decl;
        if (owner_decl == NULL || owner_decl->kind != FENG_DECL_TYPE ||
            owner_decl->as.type_decl.type_param_count == 0U) {
            return cg_resolve_type_from_program(cg,
                                                ref,
                                                owner->owner_program,
                                                fallback,
                                                out_type);
        }

        char **type_param_names = NULL;
        bool saved_in_generic_fn = cg->in_generic_fn;
        size_t saved_tp_count = cg->generic_fn_type_param_count;
        char **saved_tp_names = cg->generic_fn_type_param_names;
        const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
        const char **saved_tp_descs = cg->generic_fn_type_param_descs;
        bool ok;

        if (!cg_type_param_names_from_decl(cg,
                                           owner_decl->as.type_decl.type_params,
                                           owner_decl->as.type_decl.type_param_count,
                                           fallback ? *fallback : owner_decl->token,
                                           &type_param_names)) {
            return false;
        }

        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count = owner_decl->as.type_decl.type_param_count;
        cg->generic_fn_type_param_names = type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = NULL;
        if (!cg_register_open_generic_type_instances_in_ref_from_program(
                cg,
                ref,
                &(CGTypeParamScope){
                    .first = owner_decl->as.type_decl.type_params,
                    .first_count = owner_decl->as.type_decl.type_param_count,
                },
                fallback ? *fallback : owner_decl->token,
                owner->owner_program)) {
            cg->in_generic_fn = saved_in_generic_fn;
            cg->generic_fn_type_param_count = saved_tp_count;
            cg->generic_fn_type_param_names = saved_tp_names;
            cg->generic_fn_type_param_constraints = saved_tp_constraints;
            cg->generic_fn_type_param_descs = saved_tp_descs;
            cg_free_cstr_array(type_param_names, owner_decl->as.type_decl.type_param_count);
            return false;
        }
        {
            bool handled = false;

            ok = cg_try_resolve_declared_generic_type_ref(
                cg,
                ref,
                ref,
                owner->owner_program,
                fallback,
                out_type,
                &handled);
            if (ok && !handled) {
                ok = cg_resolve_type_from_program(cg,
                                                  ref,
                                                  owner->owner_program,
                                                  fallback,
                                                  out_type);
            }
        }
        cg->in_generic_fn = saved_in_generic_fn;
        cg->generic_fn_type_param_count = saved_tp_count;
        cg->generic_fn_type_param_names = saved_tp_names;
        cg->generic_fn_type_param_constraints = saved_tp_constraints;
        cg->generic_fn_type_param_descs = saved_tp_descs;
        cg_free_cstr_array(type_param_names, owner_decl->as.type_decl.type_param_count);
        return ok;
    }
    if (ref == NULL) {
        return cg_resolve_type_from_program(cg,
                                            ref,
                                            owner->owner_program,
                                            fallback,
                                            out_type);
    }
    const FengProgram *fallback_program =
        cg_type_ref_contains_type_param(
            ref,
            &(CGTypeParamScope){
                .first = owner->generic_origin_decl->as.type_decl.type_params,
                .first_count =
                    owner->generic_origin_decl->as.type_decl.type_param_count,
            })
            ? NULL
            : owner->owner_program;
    FengTypeRef *substituted = cg_type_ref_substitute(
        ref,
        owner->generic_origin_decl->as.type_decl.type_params,
        owner->generic_origin_decl->as.type_decl.type_param_count,
        owner->generic_type_args);
    if (!substituted) return false;
    bool saved_in_generic_fn = cg->in_generic_fn;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    bool ok;
    if (owner->generic_context_type_param_count > 0U) {
        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count = owner->generic_context_type_param_count;
        cg->generic_fn_type_param_names = owner->generic_context_type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = NULL;
    }
    if (!cg_register_open_generic_type_instances_in_ref_from_program(
            cg,
            ref,
            &(CGTypeParamScope){
                .first = owner->generic_origin_decl->as.type_decl.type_params,
                .first_count = owner->generic_origin_decl->as.type_decl.type_param_count,
            },
            fallback ? *fallback : owner->generic_origin_decl->token,
            owner->owner_program)) {
        cg->in_generic_fn = saved_in_generic_fn;
        cg->generic_fn_type_param_count = saved_tp_count;
        cg->generic_fn_type_param_names = saved_tp_names;
        cg->generic_fn_type_param_constraints = saved_tp_constraints;
        cg->generic_fn_type_param_descs = saved_tp_descs;
        cg_type_ref_free(substituted);
        return false;
    }
    {
        bool handled = false;

        ok = cg_try_resolve_declared_generic_type_ref(
            cg,
            ref,
            substituted,
            owner->owner_program,
            fallback,
            out_type,
            &handled);
        if (ok && !handled) {
            ok = cg_resolve_type_from_program(cg,
                                              substituted,
                                              fallback_program,
                                              fallback,
                                              out_type);
        }
    }
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_type_ref_free(substituted);
    return ok;
}

static bool cg_resolve_type_fact_for_user_type_member(CG *cg,
                                                      const UserType *owner,
                                                      const FengSemanticTypeFact *fact,
                                                      const FengToken *fallback,
                                                      CGType **out_type) {
    if (out_type == NULL) {
        return false;
    }
    *out_type = NULL;
    if (fact == NULL) {
        return false;
    }

    switch (fact->kind) {
        case FENG_SEMANTIC_TYPE_FACT_BUILTIN:
            for (size_t i = 0; i < sizeof k_builtin_types / sizeof k_builtin_types[0]; ++i) {
                const BuiltinTypeMap *m = &k_builtin_types[i];

                if (strlen(m->name) == fact->builtin_name.length &&
                    memcmp(m->name, fact->builtin_name.data, fact->builtin_name.length) == 0) {
                    *out_type = cgtype_new(m->kind);
                    return *out_type != NULL;
                }
            }
            return cg_fail(cg,
                           fallback ? *fallback : (FengToken){0},
                           "CE0035", "codegen: unsupported builtin inferred type for field");

        case FENG_SEMANTIC_TYPE_FACT_TYPE_REF:
            return cg_resolve_type_for_user_type_member(cg,
                                                        owner,
                                                        fact->type_ref,
                                                        fallback,
                                                        out_type);

        case FENG_SEMANTIC_TYPE_FACT_DECL:
            if (fact->type_decl == NULL) {
                return cg_fail(cg,
                               fallback ? *fallback : (FengToken){0},
                               "CE0036", "codegen: inferred field type is missing its declaration");
            }
            if (fact->type_decl->kind == FENG_DECL_ENUM) {
                *out_type = cgtype_new_enum(fact->type_decl);
                return *out_type != NULL;
            }
            {
                const UserType *ut = cg_find_user_type_by_decl(cg, fact->type_decl);

                if (ut != NULL) {
                    CGType *type = cgtype_new(CG_TYPE_OBJECT);

                    if (type == NULL) {
                        return false;
                    }
                    type->user = ut;
                    *out_type = type;
                    return true;
                }
            }
            {
                const UserSpec *us = cg_find_user_spec_by_decl(cg, fact->type_decl);

                if (us != NULL) {
                    CGType *type = cgtype_new(us->form == FENG_SPEC_FORM_CALLABLE
                                              ? CG_TYPE_CALLABLE
                                              : CG_TYPE_SPEC);

                    if (type == NULL) {
                        return false;
                    }
                    type->user_spec = us;
                    *out_type = type;
                    return true;
                }
            }
            return cg_fail(cg,
                           fallback ? *fallback : (FengToken){0},
                           "CE0037", "codegen: unsupported declared inferred field type");

        case FENG_SEMANTIC_TYPE_FACT_UNKNOWN:
            break;
    }

    return false;
}

/* Resolve one field type-ref in the owner context that owns its layout.
 * Ephemeral generic-owner views already run inside the active shared-body
 * generic context, so applying owner-instance substitution again would form
 * a different reified dependency identity. */
static bool cg_resolve_user_field_type_ref(CG *cg,
                                           const UserType *owner,
                                           const FengTypeRef *type_ref,
                                           const FengToken *fallback,
                                           CGType **out_type) {
    if (owner != NULL && owner->is_ephemeral_generic_owner_view) {
        return cg_resolve_type(cg, type_ref, fallback, out_type);
    }
    return cg_resolve_type_for_user_type_member(cg,
                                                owner,
                                                type_ref,
                                                fallback,
                                                out_type);
}

static bool cg_resolve_user_field_type(CG *cg,
                                       const UserType *owner,
                                       const FengTypeMember *member,
                                       CGType **out_type) {
    const FengSemanticTypeFact *fact = NULL;

    if (out_type == NULL) {
        return false;
    }
    *out_type = NULL;
    if (member == NULL || member->kind != FENG_TYPE_MEMBER_FIELD) {
        return false;
    }

    if (member->as.field.type != NULL) {
        return cg_resolve_user_field_type_ref(cg,
                                              owner,
                                              member->as.field.type,
                                              &member->token,
                                              out_type);
    }

    if (cg->analysis != NULL) {
        fact = feng_semantic_lookup_type_fact(cg->analysis, member);
    }
    if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
        return cg_resolve_user_field_type_ref(cg,
                                              owner,
                                              fact->type_ref,
                                              &member->token,
                                              out_type);
    }
    if (fact != NULL) {
        return cg_resolve_type_fact_for_user_type_member(cg,
                                                         owner,
                                                         fact,
                                                         &member->token,
                                                         out_type);
    }

    if (member->as.field.initializer != NULL) {
        switch (member->as.field.initializer->kind) {
            case FENG_EXPR_BOOL:
                *out_type = cgtype_new(CG_TYPE_BOOL);
                return *out_type != NULL;
            case FENG_EXPR_INTEGER:
                *out_type = cgtype_new(CG_TYPE_I32);
                return *out_type != NULL;
            case FENG_EXPR_FLOAT:
                *out_type = cgtype_new(CG_TYPE_F64);
                return *out_type != NULL;
            case FENG_EXPR_STRING:
                *out_type = cgtype_new(CG_TYPE_STRING);
                return *out_type != NULL;
            default:
                break;
        }
    }

    return cg_fail(cg,
                   member->token,
                   "CE0038", "codegen: field '%.*s' requires an explicit type or semantic inferred type",
                   (int)member->as.field.name.length,
                   member->as.field.name.data);
}

static bool cg_callable_type_param_names(CG *cg,
                                         const FengCallableSignature *sig,
                                         FengToken blame,
                                         char ***out_names) {
    size_t count = sig ? sig->type_param_count : 0U;
    char **names = count ? calloc(count, sizeof *names) : NULL;
    if (count > 0U && names == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0; i < count; ++i) {
        FengSlice name = sig->type_params[i].name;
        names[i] = strndup(name.data, name.length);
        if (names[i] == NULL) {
            cg_free_cstr_array(names, i);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }
    *out_names = names;
    return true;
}

static bool cg_type_has_stable_generic_extern_surface(const CGType *type) {
    if (type == NULL) return true;

    switch (type->kind) {
        case CG_TYPE_GENERIC_PARAM:
            return false;
        case CG_TYPE_ARRAY:
            return true;
        case CG_TYPE_POINTER:
            return cg_type_has_stable_generic_extern_surface(type->element);
        case CG_TYPE_OBJECT:
            return type->user == NULL || type->user->generic_context_type_param_count == 0U;
        case CG_TYPE_SPEC:
        case CG_TYPE_CALLABLE:
            return type->user_spec == NULL ||
                   type->user_spec->generic_context_type_param_count == 0U;
        default:
            return true;
    }
}

static bool cg_resolve_callable_type_template(
    CG *cg,
    const FengCallableSignature *sig,
    const FengTypeRef *ref,
    const FengToken *fallback,
    CGType **out_type) {
    char **type_param_names = NULL;
    bool saved_in_generic_fn = cg->in_generic_fn;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    bool ok;

    if (sig == NULL || sig->type_param_count == 0U) {
        return cg_resolve_type(cg, ref, fallback, out_type);
    }
    if (!cg_callable_type_param_names(cg,
                                      sig,
                                      fallback ? *fallback : sig->token,
                                      &type_param_names)) {
        return false;
    }

    cg->in_generic_fn = true;
    cg->generic_fn_type_param_count = sig->type_param_count;
    cg->generic_fn_type_param_names = type_param_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;

    ok = cg_resolve_type(cg, ref, fallback, out_type);

    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_cstr_array(type_param_names, sig->type_param_count);
    return ok;
}

/* Register open generic instances using the program that owns the reference. */
static bool cg_register_open_generic_type_instances_in_ref_from_program(
    CG *cg,
    const FengTypeRef *ref,
    const CGTypeParamScope *scope,
    FengToken blame,
    const FengProgram *reference_program) {
    if (ref == NULL || scope == NULL) return true;
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED: {
            if (ref->as.named.type_arg_count > 0U) {
                for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                    if (!cg_register_open_generic_type_instances_in_ref_from_program(
                            cg,
                            ref->as.named.type_args[i],
                            scope,
                            blame,
                            reference_program)) {
                        return false;
                    }
                }
                CGNamedGenericTarget target =
                    cg_resolve_named_generic_target_from_program(
                        cg, ref, reference_program);
                if (target.kind == CG_NAMED_GENERIC_TARGET_TYPE &&
                    cg_type_ref_contains_type_param(ref, scope)) {
                    if (!cg_register_generic_type_instance_shell(cg,
                                                                target.type,
                                                                ref->as.named.type_args,
                                                                ref->as.named.type_arg_count,
                                                                blame,
                                                                scope)) {
                        return false;
                    }
                }
            }
            return true;
        }
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return cg_register_open_generic_type_instances_in_ref_from_program(
                cg, ref->as.inner, scope, blame, reference_program);
    }
    return true;
}

/* Register open generic instances from the program currently being emitted. */
static bool cg_register_open_generic_type_instances_in_ref(
    CG *cg,
    const FengTypeRef *ref,
    const CGTypeParamScope *scope,
    FengToken blame) {
    return cg_register_open_generic_type_instances_in_ref_from_program(
        cg,
        ref,
        scope,
        blame,
        cg != NULL ? cg->cur_program : NULL);
}

static bool cg_type_param_names_from_decl(CG *cg,
                                          const FengTypeParam *type_params,
                                          size_t type_param_count,
                                          FengToken blame,
                                          char ***out_names) {
    char **names = type_param_count ? calloc(type_param_count, sizeof *names) : NULL;
    if (type_param_count > 0U && names == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0; i < type_param_count; ++i) {
        FengSlice name = type_params[i].name;
        names[i] = strndup(name.data, name.length);
        if (names[i] == NULL) {
            cg_free_cstr_array(names, i);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }
    *out_names = names;
    return true;
}

static bool cg_resolve_type_for_user_method_member(CG *cg,
                                                   const UserType *owner,
                                                   const FengCallableSignature *sig,
                                                   const FengTypeRef *ref,
                                                   const FengToken *fallback,
                                                   CGType **out_type) {
    FengTypeRef *substituted = NULL;
    const FengTypeRef *effective_ref = ref;
    const FengDecl *owner_decl = NULL;
    const FengProgram *fallback_program = NULL;
    CGTypeParamScope scope = {0};
    char **type_param_names = NULL;
    size_t type_param_count = 0U;
    bool saved_in_generic_fn = cg->in_generic_fn;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    bool ok;

    if (sig == NULL || sig->type_param_count == 0U) {
        return cg_resolve_type_for_user_type_member(cg, owner, ref, fallback, out_type);
    }
    if (owner != NULL) {
        owner_decl = owner->is_generic_instance
                         ? owner->generic_origin_decl
                         : owner->decl;
    }
    if (owner_decl != NULL && owner_decl->kind == FENG_DECL_TYPE) {
        scope.first = owner_decl->as.type_decl.type_params;
        scope.first_count = owner_decl->as.type_decl.type_param_count;
    }
    scope.second = sig->type_params;
    scope.second_count = sig->type_param_count;
    if (owner != NULL && owner->is_generic_instance && ref != NULL) {
        substituted = cg_type_ref_substitute(
            ref,
            owner->generic_origin_decl->as.type_decl.type_params,
            owner->generic_origin_decl->as.type_decl.type_param_count,
            owner->generic_type_args);
        if (substituted == NULL) {
            return false;
        }
        effective_ref = substituted;
        fallback_program = cg_type_ref_contains_type_param(
            ref,
            &(CGTypeParamScope){
                .first = owner->generic_origin_decl->as.type_decl.type_params,
                .first_count = owner->generic_origin_decl->as.type_decl
                                   .type_param_count,
            })
            ? NULL
            : owner->owner_program;
    } else if (owner != NULL) {
        fallback_program = owner->owner_program;
    }
    if (!cg_type_param_scope_copy_names(
            &scope, &type_param_names, &type_param_count)) {
        cg_type_ref_free(substituted);
        return cg_fail(cg,
                       fallback ? *fallback : sig->token,
                       "IE0001", "codegen: out of memory");
    }

    cg->in_generic_fn = true;
    cg->generic_fn_type_param_count = type_param_count;
    cg->generic_fn_type_param_names = type_param_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;

    ok = owner != NULL && owner->is_generic_instance
        ? cg_collect_generic_instances_from_substituted_type_ref(
              cg,
              ref,
              effective_ref,
              owner->generic_origin_decl->as.type_decl.type_params,
              owner->generic_origin_decl->as.type_decl.type_param_count,
              scope,
              owner->owner_program)
        : cg_collect_generic_instances_from_type_ref_from_program(
              cg,
              effective_ref,
              scope,
              owner != NULL ? owner->owner_program : NULL);
    if (ok) {
        bool handled = false;

        if (owner != NULL && owner->is_generic_instance) {
            ok = cg_try_resolve_declared_generic_type_ref(
                cg,
                ref,
                effective_ref,
                owner->owner_program,
                fallback,
                out_type,
                &handled);
        }
        if (ok && !handled) {
            ok = cg_resolve_type_from_program(cg,
                                              effective_ref,
                                              fallback_program,
                                              fallback,
                                              out_type);
        }
    }

    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_cstr_array(type_param_names, type_param_count);
    cg_type_ref_free(substituted);
    return ok;
}

/* Resolve a type-owned callable return with the same owner/method generic
 * substitution used by explicit member signatures. */
static bool cg_resolve_user_method_return_type(
    CG *cg,
    const UserType *owner,
    const FengCallableSignature *callable,
    const FengToken *fallback,
    CGType **out_type) {
    const FengSemanticTypeFact *fact = NULL;
    bool handled = false;
    FengToken blame;

    if (out_type == NULL || callable == NULL) {
        return false;
    }
    *out_type = NULL;
    blame = fallback != NULL ? *fallback : callable->token;
    if (callable->return_type != NULL) {
        return cg_resolve_type_for_user_method_member(
            cg, owner, callable, callable->return_type, fallback, out_type);
    }
    if (cg != NULL && cg->analysis != NULL) {
        fact = feng_semantic_lookup_type_fact(cg->analysis, callable);
    }
    if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
        return cg_resolve_type_for_user_method_member(
            cg, owner, callable, fact->type_ref, fallback, out_type);
    }
    if (!cg_try_resolve_non_reference_type_fact(
            cg, fact, blame, out_type, &handled)) {
        return false;
    }
    if (handled) {
        return true;
    }

    *out_type = cgtype_new(CG_TYPE_VOID);
    return *out_type != NULL;
}

/* Resolve one generic method parameter exactly as the shared body resolves
 * its original declaration slot.  The resulting physical-layout fact is the
 * ABI authority; a substituted instance type must not redefine that ABI. */
static bool cg_resolve_shared_method_declared_param_type(
    CG *cg,
    const FengTypeParam *outer_type_params,
    size_t outer_type_param_count,
    const FengProgram *owner_program,
    const FengTypeMember *member,
    size_t param_index,
    CGType **out_type) {
    const FengCallableSignature *sig;
    CGTypeParamScope scope;
    char **type_param_names = NULL;
    size_t type_param_count = 0U;
    bool saved_in_generic_fn;
    size_t saved_tp_count;
    char **saved_tp_names;
    const UserSpec **saved_tp_constraints;
    const char **saved_tp_descs;
    bool ok;

    if (cg == NULL || member == NULL ||
        (member->kind != FENG_TYPE_MEMBER_METHOD &&
         member->kind != FENG_TYPE_MEMBER_CONSTRUCTOR)) {
        return false;
    }
    sig = &member->as.callable;
    if (param_index >= sig->param_count) {
        return false;
    }
    scope = (CGTypeParamScope){
        .first = outer_type_params,
        .first_count = outer_type_param_count,
        .second = sig->type_params,
        .second_count = sig->type_param_count,
    };
    if (!cg_type_param_scope_copy_names(
            &scope, &type_param_names, &type_param_count)) {
        return cg_fail(cg, member->token,
                       "IE0001", "codegen: out of memory");
    }

    saved_in_generic_fn = cg->in_generic_fn;
    saved_tp_count = cg->generic_fn_type_param_count;
    saved_tp_names = cg->generic_fn_type_param_names;
    saved_tp_constraints = cg->generic_fn_type_param_constraints;
    saved_tp_descs = cg->generic_fn_type_param_descs;
    cg->in_generic_fn = type_param_count > 0U;
    cg->generic_fn_type_param_count = type_param_count;
    cg->generic_fn_type_param_names = type_param_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;

    ok = cg_resolve_type_from_program(cg,
                                      sig->params[param_index].type,
                                      owner_program,
                                      &sig->params[param_index].token,
                                      out_type);

    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_cstr_array(type_param_names, type_param_count);
    return ok;
}

/* Query the address/direct ABI selected by a generic method's original
 * declaration slot.  This must match cg_emit_generic_type_method_shared. */
static bool cg_shared_method_param_uses_address_abi(
    CG *cg,
    const FengDecl *owner_decl,
    const FengTypeMember *member,
    size_t param_index,
    bool *out_uses_address) {
    CGType *declared_type = NULL;
    const FengProgram *owner_program;

    if (owner_decl == NULL || owner_decl->kind != FENG_DECL_TYPE ||
        out_uses_address == NULL) {
        return false;
    }
    owner_program = cg_find_decl_owner_program(cg, owner_decl);
    if (!cg_resolve_shared_method_declared_param_type(
            cg,
            owner_decl->as.type_decl.type_params,
            owner_decl->as.type_decl.type_param_count,
            owner_program,
            member,
            param_index,
            &declared_type)) {
        return false;
    }
    *out_uses_address = cg_shared_generic_param_uses_address(declared_type);
    cgtype_free(declared_type);
    return true;
}

static bool cg_resolve_type_for_user_spec_member(CG *cg,
                                                 const UserSpec *owner,
                                                 const FengTypeRef *ref,
                                                 const FengToken *fallback,
                                                 CGType **out_type) {
    if (owner == NULL || !owner->is_generic_instance) {
        const FengDecl *owner_decl = owner != NULL ? owner->decl : NULL;
        if (owner_decl == NULL || owner_decl->kind != FENG_DECL_SPEC ||
            owner_decl->as.spec_decl.type_param_count == 0U) {
            return cg_resolve_type_from_program(
                cg,
                ref,
                owner != NULL ? owner->owner_program : NULL,
                fallback,
                out_type);
        }

        char **type_param_names = NULL;
        bool saved_in_generic_fn = cg->in_generic_fn;
        size_t saved_tp_count = cg->generic_fn_type_param_count;
        char **saved_tp_names = cg->generic_fn_type_param_names;
        const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
        const char **saved_tp_descs = cg->generic_fn_type_param_descs;
        bool ok;

        if (!cg_type_param_names_from_decl(cg,
                                           owner_decl->as.spec_decl.type_params,
                                           owner_decl->as.spec_decl.type_param_count,
                                           fallback ? *fallback : owner_decl->token,
                                           &type_param_names)) {
            return false;
        }

        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count = owner_decl->as.spec_decl.type_param_count;
        cg->generic_fn_type_param_names = type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = NULL;
        if (!cg_register_open_generic_type_instances_in_ref_from_program(
                cg,
                ref,
                &(CGTypeParamScope){
                    .first = owner_decl->as.spec_decl.type_params,
                    .first_count = owner_decl->as.spec_decl.type_param_count,
                },
                fallback ? *fallback : owner_decl->token,
                owner->owner_program)) {
            cg->in_generic_fn = saved_in_generic_fn;
            cg->generic_fn_type_param_count = saved_tp_count;
            cg->generic_fn_type_param_names = saved_tp_names;
            cg->generic_fn_type_param_constraints = saved_tp_constraints;
            cg->generic_fn_type_param_descs = saved_tp_descs;
            cg_free_cstr_array(type_param_names,
                               owner_decl->as.spec_decl.type_param_count);
            return false;
        }
        {
            bool handled = false;

            ok = cg_try_resolve_declared_generic_type_ref(
                cg,
                ref,
                ref,
                owner->owner_program,
                fallback,
                out_type,
                &handled);
            if (ok && !handled) {
                ok = cg_resolve_type_from_program(cg,
                                                  ref,
                                                  owner->owner_program,
                                                  fallback,
                                                  out_type);
            }
        }
        cg->in_generic_fn = saved_in_generic_fn;
        cg->generic_fn_type_param_count = saved_tp_count;
        cg->generic_fn_type_param_names = saved_tp_names;
        cg->generic_fn_type_param_constraints = saved_tp_constraints;
        cg->generic_fn_type_param_descs = saved_tp_descs;
        cg_free_cstr_array(type_param_names,
                           owner_decl->as.spec_decl.type_param_count);
        return ok;
    }
    if (ref == NULL) {
        return cg_resolve_type_from_program(cg,
                                            ref,
                                            owner->owner_program,
                                            fallback,
                                            out_type);
    }
    const FengProgram *fallback_program =
        cg_type_ref_contains_type_param(
            ref,
            &(CGTypeParamScope){
                .first = owner->generic_origin_decl->as.spec_decl.type_params,
                .first_count =
                    owner->generic_origin_decl->as.spec_decl.type_param_count,
            })
            ? NULL
            : owner->owner_program;
    FengTypeRef *substituted = cg_type_ref_substitute(
        ref,
        owner->generic_origin_decl->as.spec_decl.type_params,
        owner->generic_origin_decl->as.spec_decl.type_param_count,
        owner->generic_type_args);
    if (!substituted) return false;
    bool saved_in_generic_fn = cg->in_generic_fn;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    if (owner->generic_context_type_param_count > 0U) {
        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count = owner->generic_context_type_param_count;
        cg->generic_fn_type_param_names = owner->generic_context_type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = NULL;
    }
    bool ok;
    {
        bool handled = false;

        ok = cg_try_resolve_declared_generic_type_ref(
            cg,
            ref,
            substituted,
            owner->owner_program,
            fallback,
            out_type,
            &handled);
        if (ok && !handled) {
            ok = cg_resolve_type_from_program(cg,
                                              substituted,
                                              fallback_program,
                                              fallback,
                                              out_type);
        }
    }
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_type_ref_free(substituted);
    return ok;
}

/* ===================== string literal cache ===================== */

static const char *cg_string_literal_var(CG *cg, const char *content, size_t len) {
    for (size_t i = 0; i < cg->string_literal_count; i++) {
        if (cg->string_literals[i].length == len &&
            memcmp(cg->string_literals[i].content, content, len) == 0) {
            return cg->string_literals[i].c_var;
        }
    }
    if (cg->string_literal_count + 1 > cg->string_literal_capacity) {
        size_t cap = cg->string_literal_capacity ? cg->string_literal_capacity * 2 : 8;
        void *p = realloc(cg->string_literals, cap * sizeof *cg->string_literals);
        if (!p) return NULL;
        cg->string_literals = p;
        cg->string_literal_capacity = cap;
    }
    char *cv = NULL;
    {
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "_feng_str_lit_%zu", cg->string_literal_count);
        cv = b.data;
    }
    char *contents_copy = malloc(len + 1);
    if (!contents_copy || !cv) { free(cv); free(contents_copy); return NULL; }
    memcpy(contents_copy, content, len);
    contents_copy[len] = '\0';
    cg->string_literals[cg->string_literal_count].content = contents_copy;
    cg->string_literals[cg->string_literal_count].length = len;
    cg->string_literals[cg->string_literal_count].c_var = cv;
    cg->string_literal_count++;
    return cv;
}

static bool cg_ensure_user_spec_members_registered(CG *cg, UserSpec *s);

static bool cg_user_spec_member_name_equals(const UserSpecMember *sm,
                                            const char *name,
                                            size_t len) {
    return sm != NULL && sm->feng_name != NULL &&
           strlen(sm->feng_name) == len &&
           memcmp(sm->feng_name, name, len) == 0;
}

/* Compare the exact lowered identities used by intersection requirement
 * signatures. Unlike the broad assignment-oriented cg_types_equal helper,
 * this comparison preserves generic-parameter indices, nominal enum/spec/type
 * identity, pointer/array nesting, and array writability. */
static bool cg_spec_slot_type_identity_equal(const CGType *left,
                                             const CGType *right) {
    if (left == right) return true;
    if (left == NULL || right == NULL || left->kind != right->kind) {
        return false;
    }
    switch (left->kind) {
        case CG_TYPE_GENERIC_PARAM:
            return left->generic_param_index == right->generic_param_index;
        case CG_TYPE_OBJECT:
            return left->user == right->user;
        case CG_TYPE_SPEC:
        case CG_TYPE_CALLABLE:
            return left->user_spec == right->user_spec;
        case CG_TYPE_POINTER:
            return cg_spec_slot_type_identity_equal(left->element,
                                                    right->element);
        case CG_TYPE_ARRAY:
            return left->array_element_writable ==
                       right->array_element_writable &&
                   cg_spec_slot_type_identity_equal(left->element,
                                                    right->element);
        default:
            return left->enum_decl == right->enum_decl;
    }
}

/* Return whether one method parameter is the variadic tail recorded on its
 * AST-owned requirement declaration. Spec methods cannot declare callable
 * type parameters, so the cloned member signature remains index-aligned. */
static bool cg_user_spec_member_param_is_variadic(
    const UserSpecMember *member,
    size_t param_index) {
    return member != NULL && member->member != NULL &&
           member->member->kind == FENG_TYPE_MEMBER_METHOD &&
           param_index < member->member->as.callable.param_count &&
           member->member->as.callable.params[param_index].is_variadic;
}

/* Return whether two flattened requirements occupy one Semantic-equivalent
 * intersection slot. Same-name methods with a different parameter signature
 * remain legal overloads and therefore return false. ABI classifications are
 * intentionally excluded: the first merged slot owns one stable ABI and its
 * compile-time adapters bridge any equivalent declaring surface. */
static bool cg_user_spec_members_semantically_equivalent(
    const UserSpecMember *left,
    const UserSpecMember *right) {
    if (left == NULL || right == NULL || left->kind != right->kind ||
        left->is_static != right->is_static || left->feng_name == NULL ||
        right->feng_name == NULL ||
        strcmp(left->feng_name, right->feng_name) != 0) {
        return false;
    }
    if (left->kind == USM_KIND_FIELD) {
        return left->is_var == right->is_var &&
               cg_spec_slot_type_identity_equal(left->type, right->type);
    }
    if (left->param_count != right->param_count ||
        !cg_spec_slot_type_identity_equal(left->type, right->type)) {
        return false;
    }
    for (size_t index = 0U; index < left->param_count; ++index) {
        if (!cg_spec_slot_type_identity_equal(left->param_types[index],
                                              right->param_types[index]) ||
            cg_user_spec_member_param_is_variadic(left, index) !=
                cg_user_spec_member_param_is_variadic(right, index)) {
            return false;
        }
    }
    return true;
}

/* Return whether one merged slot represents the exact Semantic requirement
 * declaration, either as its first-seen source or as an equivalent alias. */
static bool cg_user_spec_member_has_decl(const UserSpecMember *slot,
                                         const FengTypeMember *member) {
    if (slot == NULL || member == NULL) return false;
    if (slot->member == member) return true;
    for (size_t index = 0U; index < slot->member_alias_count; ++index) {
        if (slot->member_aliases[index] == member) return true;
    }
    return false;
}

/* Add one AST-owned equivalent declaration identity to a merged slot. */
static bool cg_user_spec_member_append_alias(UserSpecMember *slot,
                                             const FengTypeMember *member) {
    const FengTypeMember **grown;

    if (slot == NULL || member == NULL ||
        cg_user_spec_member_has_decl(slot, member)) {
        return true;
    }
    grown = realloc(slot->member_aliases,
                    (slot->member_alias_count + 1U) * sizeof *grown);
    if (grown == NULL) return false;
    slot->member_aliases = grown;
    slot->member_aliases[slot->member_alias_count++] = member;
    return true;
}

/* Copy every declaration identity represented by `source` into `target` as
 * aliases. The target's primary declaration and witness source stay intact. */
static bool cg_user_spec_member_append_aliases(
    UserSpecMember *target,
    const UserSpecMember *source) {
    if (target == NULL || source == NULL ||
        !cg_user_spec_member_append_alias(target, source->member)) {
        return false;
    }
    for (size_t index = 0U; index < source->member_alias_count; ++index) {
        if (!cg_user_spec_member_append_alias(
                target, source->member_aliases[index])) {
            return false;
        }
    }
    return true;
}

/* Find the already-recorded slot equivalent to one flattened requirement. */
static UserSpecMember *cg_user_spec_equivalent_member(
    UserSpec *spec,
    const UserSpecMember *candidate) {
    if (spec == NULL || candidate == NULL) return NULL;
    for (size_t index = 0U; index < spec->member_count; ++index) {
        if (cg_user_spec_members_semantically_equivalent(
                &spec->members[index], candidate)) {
            return &spec->members[index];
        }
    }
    return NULL;
}

static bool cg_user_spec_append_member_slot(UserSpec *s, UserSpecMember **out_slot) {
    size_t count = s->member_count;
    UserSpecMember *grown = realloc(s->members, (count + 1U) * sizeof *s->members);
    if (grown == NULL) return false;
    s->members = grown;
    *out_slot = &s->members[count];
    memset(*out_slot, 0, sizeof **out_slot);
    s->member_count = count + 1U;
    return true;
}

/* Release all compiler-owned storage held by one registered spec member. */
static void cg_user_spec_member_free(UserSpecMember *member) {
    if (member == NULL) return;
    free(member->feng_name);
    free(member->c_field_name);
    cgtype_free(member->type);
    for (size_t index = 0U; index < member->param_count; ++index) {
        if (member->param_types != NULL) {
            cgtype_free(member->param_types[index]);
        }
        if (member->param_names != NULL) {
            free(member->param_names[index]);
        }
    }
    free(member->param_types);
    free(member->param_abi_kinds);
    free(member->param_names);
    free(member->member_aliases);
    free(member->source_c_field_name);
    cg_type_ref_free(member->source_member_type_ref);
    memset(member, 0, sizeof *member);
}

/* Release a temporary or final spec member array. */
static void cg_user_spec_members_free(UserSpec *spec) {
    if (spec == NULL) return;
    for (size_t index = 0U; index < spec->member_count; ++index) {
        cg_user_spec_member_free(&spec->members[index]);
    }
    free(spec->members);
    spec->members = NULL;
    spec->member_count = 0U;
}

static bool cg_user_spec_clone_inherited_member(UserSpec *s,
                                                const UserSpecMember *src) {
    UserSpecMember *dst = NULL;
    if (src == NULL || src->feng_name == NULL) return true;
    if (!cg_user_spec_append_member_slot(s, &dst)) return false;
    dst->kind = src->kind;
    dst->type = cgtype_clone(src->type);
    dst->value_abi_kind = src->value_abi_kind;
    dst->is_var = src->is_var;
    dst->is_static = src->is_static;
    dst->param_count = src->param_count;
    dst->member = src->member;
    dst->feng_name = strdup(src->feng_name);
    dst->c_field_name = strdup(src->c_field_name);
    if (src->type != NULL && dst->type == NULL) return false;
    if (dst->feng_name == NULL || dst->c_field_name == NULL) return false;
    if (src->param_count > 0U) {
        dst->param_types = calloc(src->param_count, sizeof *dst->param_types);
        dst->param_abi_kinds = calloc(src->param_count,
                                      sizeof *dst->param_abi_kinds);
        dst->param_names = calloc(src->param_count, sizeof *dst->param_names);
        if (dst->param_types == NULL || dst->param_abi_kinds == NULL ||
            dst->param_names == NULL) return false;
        for (size_t i = 0; i < src->param_count; ++i) {
            dst->param_types[i] = cgtype_clone(src->param_types[i]);
            dst->param_abi_kinds[i] = src->param_abi_kinds[i];
            dst->param_names[i] = strdup(src->param_names[i]);
            if ((src->param_types[i] != NULL && dst->param_types[i] == NULL) ||
                dst->param_names[i] == NULL) {
                return false;
            }
        }
    }
    return cg_user_spec_member_append_aliases(dst, src);
}

/* Clone a member slot from an intersection's flattened member spec into the
 * intersection's own members[] array. Mirrors cg_user_spec_clone_inherited_member
 * but additionally records `source_member_decl` — the AST decl of the member
 * spec this slot was cloned from — so cg_ensure_witness_instance_for_type can
 * later locate the subject's per-member-spec witness when assembling the
 * merged witness constant. `c_field_name` is the destination merged-witness
 * field: first-seen names preserve their existing ABI, while legal overloads
 * receive a deterministic appended-slot name. Dedup is the caller's
 * responsibility.
 *
 * 9.9: `source_member_type_ref` is the substituted member type ref for
 * generic intersection instances (e.g. Eq<IntBox> for Comparable<IntBox>);
 * NULL for non-generic intersections. Takes ownership of the passed ref. */
static bool cg_user_spec_clone_intersection_member(UserSpec *s,
                                                   const UserSpecMember *src,
                                                   const FengDecl *source_member_decl,
                                                   FengTypeRef *source_member_type_ref,
                                                   const char *c_field_name) {
    UserSpecMember *dst = NULL;
    if (src == NULL || src->feng_name == NULL) {
        cg_type_ref_free(source_member_type_ref);
        return true;
    }
    if (!cg_user_spec_append_member_slot(s, &dst)) {
        cg_type_ref_free(source_member_type_ref);
        return false;
    }
    dst->kind = src->kind;
    dst->type = cgtype_clone(src->type);
    dst->value_abi_kind = src->value_abi_kind;
    dst->is_var = src->is_var;
    dst->is_static = src->is_static;
    dst->param_count = src->param_count;
    dst->member = src->member;
    dst->source_member_decl = source_member_decl;
    dst->source_member_type_ref = source_member_type_ref;
    dst->feng_name = strdup(src->feng_name);
    dst->c_field_name = c_field_name != NULL ? strdup(c_field_name) : NULL;
    dst->source_c_field_name = strdup(
        src->source_c_field_name != NULL
            ? src->source_c_field_name
            : src->c_field_name);
    if (src->type != NULL && dst->type == NULL) return false;
    if (dst->feng_name == NULL || dst->c_field_name == NULL ||
        dst->source_c_field_name == NULL ||
        !cg_user_spec_member_append_aliases(dst, src)) {
        return false;
    }
    if (src->param_count > 0U) {
        dst->param_types = calloc(src->param_count, sizeof *dst->param_types);
        dst->param_abi_kinds = calloc(src->param_count,
                                      sizeof *dst->param_abi_kinds);
        dst->param_names = calloc(src->param_count, sizeof *dst->param_names);
        if (dst->param_types == NULL || dst->param_abi_kinds == NULL ||
            dst->param_names == NULL) return false;
        for (size_t i = 0; i < src->param_count; ++i) {
            dst->param_types[i] = cgtype_clone(src->param_types[i]);
            dst->param_abi_kinds[i] = src->param_abi_kinds[i];
            dst->param_names[i] = strdup(src->param_names[i]);
            if ((src->param_types[i] != NULL && dst->param_types[i] == NULL) ||
                dst->param_names[i] == NULL) {
                return false;
            }
        }
    }
    return true;
}

/* Return the first slot carrying one Feng member name in an exact
 * instance/static surface. */
static UserSpecMember *cg_user_spec_named_member_in_surface(
    UserSpec *spec,
    const char *name,
    bool is_static) {
    if (spec == NULL || name == NULL) return NULL;
    for (size_t index = 0U; index < spec->member_count; ++index) {
        if (spec->members[index].is_static == is_static &&
            cg_user_spec_member_name_equals(&spec->members[index],
                                            name,
                                            strlen(name))) {
            return &spec->members[index];
        }
    }
    return NULL;
}

/* Return the first same-name slot from either owner surface. This is used
 * only to keep generated C field names unique across one witness struct. */
static UserSpecMember *cg_user_spec_named_member_any_surface(
    UserSpec *spec,
    const char *name) {
    if (spec == NULL || name == NULL) return NULL;
    for (size_t index = 0U; index < spec->member_count; ++index) {
        if (cg_user_spec_member_name_equals(&spec->members[index],
                                            name,
                                            strlen(name))) {
            return &spec->members[index];
        }
    }
    return NULL;
}

/* Record one flattened intersection requirement. First-seen names enter the
 * historical primary member order. Equivalent declarations become aliases of
 * that slot. Additional legal slots, including another owner surface or a
 * method overload, are staged after all primary slots. Takes ownership of
 * `source_member_type_ref`. */
static bool cg_user_spec_record_intersection_member(
    CG *cg,
    UserSpec *spec,
    UserSpec *pending_overloads,
    const UserSpecMember *source,
    const FengDecl *source_member_decl,
    FengTypeRef *source_member_type_ref,
    FengToken blame) {
    UserSpecMember *equivalent;
    const UserSpecMember *named;
    const UserSpecMember *any_named;

    if (source == NULL || source->feng_name == NULL) {
        cg_type_ref_free(source_member_type_ref);
        return true;
    }
    equivalent = cg_user_spec_equivalent_member(spec, source);
    if (equivalent == NULL) {
        equivalent = cg_user_spec_equivalent_member(pending_overloads, source);
    }
    if (equivalent != NULL) {
        bool ok = cg_user_spec_member_append_aliases(equivalent, source);

        cg_type_ref_free(source_member_type_ref);
        return ok;
    }

    named = cg_user_spec_named_member_in_surface(
        spec, source->feng_name, source->is_static);
    if (named == NULL) {
        named = cg_user_spec_named_member_in_surface(
            pending_overloads, source->feng_name, source->is_static);
    }
    if (named == NULL) {
        any_named = cg_user_spec_named_member_any_surface(
            spec, source->feng_name);
        if (any_named == NULL) {
            any_named = cg_user_spec_named_member_any_surface(
                pending_overloads, source->feng_name);
        }
        if (any_named != NULL) {
            return cg_user_spec_clone_intersection_member(
                pending_overloads,
                source,
                source_member_decl,
                source_member_type_ref,
                any_named->c_field_name);
        }
        return cg_user_spec_clone_intersection_member(
            spec,
            source,
            source_member_decl,
            source_member_type_ref,
            source->c_field_name);
    }
    if (named->kind != USM_KIND_METHOD ||
        source->kind != USM_KIND_METHOD) {
        cg_type_ref_free(source_member_type_ref);
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: non-method intersection requirements with the same name were not normalized");
    }
    return cg_user_spec_clone_intersection_member(
        pending_overloads,
        source,
        source_member_decl,
        source_member_type_ref,
        named->c_field_name);
}

/* Replace one equivalent parent slot with the exact child requirement while
 * retaining the historical field name, slot position and every declaration
 * alias. The child owns the slot ABI, matching the pre-existing object-spec
 * replacement rule for a generic parent closed to a concrete child shape. */
static bool cg_user_spec_replace_equivalent_member(
    UserSpecMember *target,
    const UserSpecMember *source) {
    UserSpec temporary;
    UserSpecMember replacement;
    char *field_name;

    if (target == NULL || source == NULL || source->member == NULL ||
        target->c_field_name == NULL) {
        return false;
    }
    memset(&temporary, 0, sizeof(temporary));
    if (!cg_user_spec_clone_inherited_member(&temporary, source) ||
        temporary.member_count != 1U) {
        cg_user_spec_members_free(&temporary);
        return false;
    }
    replacement = temporary.members[0];
    free(temporary.members);
    field_name = strdup(target->c_field_name);
    if (field_name == NULL) {
        cg_user_spec_member_free(&replacement);
        return false;
    }
    free(replacement.c_field_name);
    replacement.c_field_name = field_name;
    if (!cg_user_spec_member_append_aliases(&replacement, target)) {
        cg_user_spec_member_free(&replacement);
        return false;
    }
    cg_user_spec_member_free(target);
    *target = replacement;
    return true;
}

/* Preserve the historical name-based replacement behavior for non-method
 * member collisions that are outside the method-overload surface repaired by
 * this change. The destination slot position and C field name remain stable. */
static bool cg_user_spec_replace_non_method_slot(
    UserSpecMember *target,
    const UserSpecMember *source) {
    UserSpec temporary;
    UserSpecMember replacement;
    char *field_name;

    if (target == NULL || source == NULL || target->c_field_name == NULL) {
        return false;
    }
    memset(&temporary, 0, sizeof(temporary));
    if (!cg_user_spec_clone_inherited_member(&temporary, source) ||
        temporary.member_count != 1U) {
        cg_user_spec_members_free(&temporary);
        return false;
    }
    replacement = temporary.members[0];
    free(temporary.members);
    field_name = strdup(target->c_field_name);
    if (field_name == NULL) {
        cg_user_spec_member_free(&replacement);
        return false;
    }
    free(replacement.c_field_name);
    replacement.c_field_name = field_name;
    cg_user_spec_member_free(target);
    *target = replacement;
    return true;
}

/* Stage one legal object-spec method overload from the historical primary
 * slot's base C field name. Parent slots may already carry an overload suffix;
 * that suffix is local to the parent layout and must not be nested in the
 * child layout's deterministic numbering. */
static bool cg_user_spec_clone_object_overload(
    UserSpec *pending_overloads,
    const UserSpecMember *source,
    const char *base_c_field_name) {
    UserSpecMember *cloned;
    char *field_name;

    if (pending_overloads == NULL || source == NULL ||
        base_c_field_name == NULL ||
        !cg_user_spec_clone_inherited_member(pending_overloads, source)) {
        return false;
    }
    cloned = &pending_overloads
                  ->members[pending_overloads->member_count - 1U];
    field_name = strdup(base_c_field_name);
    if (field_name == NULL) {
        return false;
    }
    free(cloned->c_field_name);
    cloned->c_field_name = field_name;
    return true;
}

/* Record one object-form requirement using exact lowered identity. Existing
 * first-name slots keep their layout; distinct method overloads and members
 * from the other owner surface are staged for deterministic append, while an
 * equivalent child declaration becomes the primary slot identity. */
static bool cg_user_spec_record_object_member(
    UserSpec *spec,
    UserSpec *pending_overloads,
    const UserSpecMember *source,
    bool prefer_source_identity) {
    UserSpecMember *equivalent;
    UserSpecMember *named;
    UserSpecMember *any_named;

    if (source == NULL || source->feng_name == NULL) {
        return true;
    }
    equivalent = cg_user_spec_equivalent_member(spec, source);
    if (equivalent == NULL) {
        equivalent = cg_user_spec_equivalent_member(
            pending_overloads, source);
    }
    if (equivalent != NULL) {
        return prefer_source_identity
                   ? cg_user_spec_replace_equivalent_member(equivalent, source)
                   : cg_user_spec_member_append_aliases(equivalent, source);
    }

    named = cg_user_spec_named_member_in_surface(
        spec, source->feng_name, source->is_static);
    if (named == NULL) {
        named = cg_user_spec_named_member_in_surface(
            pending_overloads, source->feng_name, source->is_static);
    }
    if (named == NULL) {
        any_named = cg_user_spec_named_member_any_surface(
            spec, source->feng_name);
        if (any_named == NULL) {
            any_named = cg_user_spec_named_member_any_surface(
                pending_overloads, source->feng_name);
        }
        if (any_named != NULL) {
            return cg_user_spec_clone_object_overload(
                pending_overloads, source, any_named->c_field_name);
        }
        return cg_user_spec_clone_inherited_member(spec, source);
    }
    if (named->kind == USM_KIND_METHOD &&
        source->kind == USM_KIND_METHOD) {
        return cg_user_spec_clone_object_overload(
            pending_overloads, source, named->c_field_name);
    }
    if (prefer_source_identity) {
        return cg_user_spec_replace_non_method_slot(named, source);
    }
    return true;
}

/* Return whether one generated C field name already belongs to a slot. */
static bool cg_user_spec_has_c_field_name(const UserSpec *spec,
                                          const char *name,
                                          size_t limit) {
    if (spec == NULL || name == NULL) return false;
    if (limit > spec->member_count) limit = spec->member_count;
    for (size_t index = 0U; index < limit; ++index) {
        if (spec->members[index].c_field_name != NULL &&
            strcmp(spec->members[index].c_field_name, name) == 0) {
            return true;
        }
    }
    return false;
}

/* Build the deterministic field name for one appended legal overload. The
 * search also avoids collisions with user-authored names after sanitization. */
static char *cg_spec_overload_c_field_name(
    const UserSpec *primary,
    const UserSpec *pending_overloads,
    size_t pending_index,
    const char *base_name) {
    size_t ordinal = 2U;

    if (base_name == NULL) return NULL;
    while (true) {
        Buf candidate;

        buf_init(&candidate);
        buf_append_fmt(&candidate,
                       "%s__feng_overload_%zu",
                       base_name,
                       ordinal);
        if (candidate.data == NULL) return NULL;
        if (!cg_user_spec_has_c_field_name(primary,
                                           candidate.data,
                                           primary->member_count) &&
            !cg_user_spec_has_c_field_name(pending_overloads,
                                           candidate.data,
                                           pending_index)) {
            return candidate.data;
        }
        buf_free(&candidate);
        if (ordinal == SIZE_MAX) return NULL;
        ++ordinal;
    }
}

/* Append staged overloads after every historical first-name slot. Ownership
 * of the staged elements moves into `spec`; the temporary array is cleared. */
static bool cg_user_spec_commit_overloads(
    UserSpec *spec,
    UserSpec *pending_overloads) {
    UserSpecMember *grown;
    size_t combined_count;

    if (spec == NULL || pending_overloads == NULL ||
        pending_overloads->member_count == 0U) {
        return true;
    }
    for (size_t index = 0U;
         index < pending_overloads->member_count;
         ++index) {
        char *field_name = cg_spec_overload_c_field_name(
            spec,
            pending_overloads,
            index,
            pending_overloads->members[index].c_field_name);

        if (field_name == NULL) return false;
        free(pending_overloads->members[index].c_field_name);
        pending_overloads->members[index].c_field_name = field_name;
    }
    if (pending_overloads->member_count > SIZE_MAX - spec->member_count) {
        return false;
    }
    combined_count = spec->member_count + pending_overloads->member_count;
    grown = realloc(spec->members, combined_count * sizeof *grown);
    if (grown == NULL) return false;
    spec->members = grown;
    memcpy(&spec->members[spec->member_count],
           pending_overloads->members,
           pending_overloads->member_count * sizeof *pending_overloads->members);
    spec->member_count = combined_count;
    free(pending_overloads->members);
    pending_overloads->members = NULL;
    pending_overloads->member_count = 0U;
    return true;
}

static bool cg_user_spec_append_decl_member(CG *cg,
                                            UserSpec *s,
                                            const FengTypeMember *m) {
    UserSpecMember *sm = NULL;
    CGTypeParamScope spec_scope;

    if (m == NULL) return true;
    spec_scope = (CGTypeParamScope){
        .first = s->generic_origin_decl != NULL
                     ? s->generic_origin_decl->as.spec_decl.type_params
                     : s->decl->as.spec_decl.type_params,
        .first_count = s->generic_origin_decl != NULL
                           ? s->generic_origin_decl->as.spec_decl.type_param_count
                           : s->decl->as.spec_decl.type_param_count,
    };
    if (!cg_user_spec_append_member_slot(s, &sm)) return false;
    sm->member = m;
    sm->is_static = m->is_static;
    if (m->kind == FENG_TYPE_MEMBER_FIELD) {
        sm->kind = USM_KIND_FIELD;
        sm->is_var = (m->as.field.mutability == FENG_MUTABILITY_VAR);
        sm->feng_name = strndup(m->as.field.name.data, m->as.field.name.length);
        sm->c_field_name = cg_sanitize(m->as.field.name.data, m->as.field.name.length);
        if (!cg_resolve_type_for_user_spec_member(cg, s, m->as.field.type,
                                                  &m->token, &sm->type)) return false;
        sm->value_abi_kind = cg_callable_decl_slot_abi_kind(
            m->as.field.type, &spec_scope, sm->type);
    } else if (m->kind == FENG_TYPE_MEMBER_METHOD) {
        sm->kind = USM_KIND_METHOD;
        const FengCallableSignature *sig = &m->as.callable;
        sm->feng_name = strndup(sig->name.data, sig->name.length);
        sm->c_field_name = cg_sanitize(sig->name.data, sig->name.length);
        sm->param_count = sig->param_count;
        sm->param_types = sig->param_count
            ? calloc(sig->param_count, sizeof(CGType*)) : NULL;
        sm->param_abi_kinds = sig->param_count
            ? calloc(sig->param_count, sizeof *sm->param_abi_kinds) : NULL;
        sm->param_names = sig->param_count
            ? calloc(sig->param_count, sizeof(char*)) : NULL;
        if (sig->param_count > 0U &&
            (sm->param_types == NULL || sm->param_abi_kinds == NULL ||
             sm->param_names == NULL)) {
            return false;
        }
        for (size_t pi = 0; pi < sig->param_count; pi++) {
            if (!cg_resolve_type_for_user_spec_member(cg,
                                                      s,
                                                      sig->params[pi].type,
                                                      &sig->params[pi].token,
                                                      &sm->param_types[pi])) return false;
            sm->param_abi_kinds[pi] = cg_callable_decl_slot_abi_kind(
                sig->params[pi].type, &spec_scope, sm->param_types[pi]);
            sm->param_names[pi] = strndup(sig->params[pi].name.data,
                                          sig->params[pi].name.length);
        }
        if (!cg_resolve_type_for_user_spec_member(cg, s, sig->return_type,
                                                  &sig->token, &sm->type)) return false;
        sm->value_abi_kind = cg_callable_decl_slot_abi_kind(
            sig->return_type, &spec_scope, sm->type);
    } else {
        return cg_fail(cg, m->token,
            "CE0039", "codegen: spec member kind not supported (Step 4b-α only handles fields/methods)");
    }
    return sm->feng_name != NULL && sm->c_field_name != NULL;
}

/* ===================== symbol tables ===================== */

/* Find the exact extern entry selected by semantic analysis. */
static const ExternFn *cg_find_extern_by_decl(const CG *cg,
                                              const FengDecl *decl) {
    if (decl == NULL) {
        return NULL;
    }
    for (size_t i = 0U; i < cg->extern_count; ++i) {
        if (cg->externs[i].decl == decl) {
            return &cg->externs[i];
        }
    }
    return NULL;
}

static bool cg_register_extern(CG *cg, const FengDecl *decl) {
    char **type_param_names = NULL;
    char *module_mangle = NULL;
    bool saved_in_generic_fn = cg->in_generic_fn;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    bool ok = false;

    if (cg->extern_count + 1 > cg->extern_capacity) {
        size_t cap = cg->extern_capacity ? cg->extern_capacity * 2 : 4;
        void *p = realloc(cg->externs, cap * sizeof *cg->externs);
        if (!p) return false;
        cg->externs = p;
        cg->extern_capacity = cap;
    }
    const FengCallableSignature *sig = &decl->as.function_decl;
    ExternFn *ef = &cg->externs[cg->extern_count];

    memset(ef, 0, sizeof(*ef));
    ef->decl = decl;
    ef->owner_program = cg_find_decl_owner_program(cg, decl);
    if (ef->owner_program == NULL) {
        return cg_fail(cg,
                       sig->token,
                       "CE0071", "codegen: cannot determine owner program for extern func '%.*s'",
                       (int)sig->name.length,
                       sig->name.data);
    }
    ef->uses_runtime_contract = cg_decl_uses_runtime_contract(decl);
    ef->calling_convention = cg_find_calling_convention_kind(decl->annotations,
                                                             decl->annotation_count);
    {
        const FengAnnotation *callconv = cg_find_calling_convention_annotation(
            decl->annotations, decl->annotation_count);
        if (callconv != NULL && callconv->arg_count >= 3U &&
            callconv->args[2]->kind == FENG_EXPR_INTEGER) {
            ef->fixed_param_count = (size_t)callconv->args[2]->as.integer;
        }
    }

    if (ef->uses_runtime_contract && !cg_runtime_contract_contains_name(sig->name)) {
        return cg_fail(cg,
                       sig->token,
                       "CE0040", "codegen: @runtime extern func '%.*s' is not declared by runtime contract",
                       (int)sig->name.length,
                       sig->name.data);
    }

    ef->feng_name = strndup(sig->name.data, sig->name.length);
    if (ef->feng_name == NULL) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    ef->native_symbol = cg_extern_c_symbol_name(cg, decl, sig);
    if (ef->native_symbol == NULL) {
        if (!cg->failed) {
            cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        }
        goto cleanup;
    }
    ef->param_count = sig->param_count;
    ef->param_types = sig->param_count ? calloc(sig->param_count, sizeof(CGType*)) : NULL;
    if (sig->param_count > 0U && ef->param_types == NULL) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    if (sig->type_param_count > 0U) {
        if (!cg_callable_type_param_names(cg, sig, sig->token, &type_param_names)) {
            goto cleanup;
        }
        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count = sig->type_param_count;
        cg->generic_fn_type_param_names = type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = NULL;
    }

    for (size_t i = 0; i < sig->param_count; i++) {
        bool has_stable_surface;

        if (!cg_resolve_type(cg, sig->params[i].type, &sig->params[i].token,
                             &ef->param_types[i])) {
            goto cleanup;
        }
        has_stable_surface = cg_type_has_stable_generic_extern_surface(ef->param_types[i]);
        if (!has_stable_surface && ef->uses_runtime_contract &&
            ef->param_types[i] != NULL &&
            ef->param_types[i]->kind == CG_TYPE_GENERIC_PARAM) {
            has_stable_surface = true;
        }
        if (sig->type_param_count > 0U && !has_stable_surface) {
            cg_fail(cg,
                    sig->params[i].token,
                    "CE0041", "codegen: generic extern func '%.*s' parameter '%.*s' does not lower to a single external surface",
                    (int)sig->name.length,
                    sig->name.data,
                    (int)sig->params[i].name.length,
                    sig->params[i].name.data);
            goto cleanup;
        }
    }
    if (!cg_resolve_type(cg, sig->return_type, &sig->token, &ef->return_type)) {
        goto cleanup;
    }
    if (sig->type_param_count > 0U) {
        bool has_stable_surface = cg_type_has_stable_generic_extern_surface(ef->return_type);

        if (!has_stable_surface && ef->uses_runtime_contract &&
            ef->return_type != NULL &&
            ef->return_type->kind == CG_TYPE_GENERIC_PARAM) {
            has_stable_surface = true;
        }
        if (!has_stable_surface) {
            cg_fail(cg,
                    sig->token,
                    "CE0042", "codegen: generic extern func '%.*s' return type does not lower to a single external surface",
                    (int)sig->name.length,
                    sig->name.data);
            goto cleanup;
        }
    }
    module_mangle = cg_module_mangle(ef->owner_program->module_segments,
                                     ef->owner_program->module_segment_count);
    if (module_mangle == NULL) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    ef->generated_c_name = cg_fn_mangle(module_mangle, &sig->name);
    if (ef->generated_c_name == NULL) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    ef->generated_c_name = cg_append_param_suffix(
        ef->generated_c_name,
        ef->param_types,
        ef->param_count,
        false,
        sig->type_param_count > 0U);
    if (ef->generated_c_name == NULL) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->extern_count++;
    ok = true;

cleanup:
    free(module_mangle);
    if (!ok) {
        free(ef->feng_name);
        free(ef->generated_c_name);
        free(ef->native_symbol);
        if (ef->param_types != NULL) {
            for (size_t param_index = 0U; param_index < ef->param_count; ++param_index) {
                cgtype_free(ef->param_types[param_index]);
            }
        }
        free(ef->param_types);
        cgtype_free(ef->return_type);
        memset(ef, 0, sizeof(*ef));
    }
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_cstr_array(type_param_names, sig->type_param_count);
    return ok;
}

/* Legacy fallback for call sites that do not carry a resolved declaration. */
static const ExternFn *cg_find_extern_by_name(const CG *cg,
                                              const char *name,
                                              size_t len) {
    for (size_t i = 0; i < cg->extern_count; i++) {
        if (strlen(cg->externs[i].feng_name) == len &&
            memcmp(cg->externs[i].feng_name, name, len) == 0) {
            return &cg->externs[i];
        }
    }
    return NULL;
}

/* Return the linker-visible symbol selected by the extern annotation. */
static const char *cg_extern_c_symbol(const ExternFn *ef) {
    return ef->native_symbol != NULL ? ef->native_symbol : ef->feng_name;
}

/* Return the C identifier used at a generated call site. */
static const char *cg_extern_call_target(const ExternFn *ef) {
    if (ef->uses_runtime_contract) {
        return cg_extern_c_symbol(ef);
    }
    return ef->generated_c_name;
}

static bool cg_emit_registered_extern_decl(CG *cg, const ExternFn *ef) {
    Buf *h = &cg->headers;

    if (ef == NULL) {
        return false;
    }

    /* Runtime-contract externs rely on the runtime header as the single
     * declaration authority. Emitting a second prototype here would drift on
     * qualifiers such as `const` and create C conflicts for the same symbol. */
    if (ef->uses_runtime_contract) {
        return true;
    }

    buf_append_cstr(h, "extern ");
    cg_emit_c_abi_surface_type(h, ef->return_type);
    {
        const char *callconv_macro = cg_extern_calling_convention_macro(ef->calling_convention);

        if (callconv_macro != NULL) {
            buf_append_fmt(h, " %s", callconv_macro);
        }
    }
    buf_append_fmt(h, " %s(", ef->generated_c_name);
    if (ef->param_count == 0) {
        buf_append_cstr(h, "void");
    } else if (ef->fixed_param_count > 0) {
        for (size_t i = 0; i < ef->fixed_param_count; i++) {
            if (i) buf_append_cstr(h, ", ");
            cg_emit_c_abi_surface_type(h, ef->param_types[i]);
        }
        if (ef->fixed_param_count > 0) buf_append_cstr(h, ", ");
        buf_append_cstr(h, "...");
    } else {
        for (size_t i = 0; i < ef->param_count; i++) {
            if (i) buf_append_cstr(h, ", ");
            cg_emit_c_abi_surface_type(h, ef->param_types[i]);
        }
    }
    buf_append_cstr(h, ") FENG_NATIVE_SYMBOL(");
    buf_append_c_string_literal(h, cg_extern_c_symbol(ef));
    buf_append_cstr(h, ");\n");
    return true;
}

/* Register one free function only after all owned metadata has been built.
 * Failed registrations leave no partially committed entry for cg_dispose. */
static bool cg_register_free_fn(CG *cg, const FengDecl *decl) {
    const FengCallableSignature *sig = &decl->as.function_decl;
    FreeFn *f;
    char *surface_name = NULL;
    bool ok = false;

    if (cg->free_fn_count + 1 > cg->free_fn_capacity) {
        size_t cap = cg->free_fn_capacity ? cg->free_fn_capacity * 2 : 4;
        void *p = realloc(cg->free_fns, cap * sizeof *cg->free_fns);
        if (!p) {
            return cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        }
        cg->free_fns = p;
        cg->free_fn_capacity = cap;
    }
    f = &cg->free_fns[cg->free_fn_count];
    memset(f, 0, sizeof(*f));
    f->feng_name = strndup(sig->name.data, sig->name.length);
    if (f->feng_name == NULL) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    f->is_abi = cg_annotations_contain_kind(decl->annotations,
                                            decl->annotation_count,
                                            FENG_ANNOTATION_ABI);
    f->is_variadic = sig->param_count > 0U && sig->params[sig->param_count - 1U].is_variadic;
    surface_name = cg_fn_mangle(cg->module_mangle, &sig->name);
    if (surface_name == NULL) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    f->param_count = sig->param_count;
    f->param_types = sig->param_count ? calloc(sig->param_count, sizeof(CGType*)) : NULL;
    f->param_names = sig->param_count ? calloc(sig->param_count, sizeof(char*)) : NULL;
    if (sig->param_count > 0U &&
        (f->param_types == NULL || f->param_names == NULL)) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t i = 0; i < sig->param_count; i++) {
        if (!cg_resolve_type(cg, sig->params[i].type, &sig->params[i].token,
                             &f->param_types[i])) {
            goto cleanup;
        }
        f->param_names[i] = strndup(sig->params[i].name.data, sig->params[i].name.length);
        if (f->param_names[i] == NULL) {
            cg_fail(cg, sig->params[i].token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }
    if (!cg_resolve_callable_return_type(cg, sig, sig->token, &f->return_type)) {
        goto cleanup;
    }
    /* Append param-type suffix for overload-aware mangling. Applied
     * unconditionally so the symbol shape is the same regardless of whether
     * the function is part of an overload set today. */
    surface_name = cg_append_param_suffix(surface_name, f->param_types, f->param_count, f->is_variadic, false);
    if (!surface_name) {
        cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (f->is_abi) {
        Buf impl; buf_init(&impl);
        buf_append_cstr(&impl, surface_name);
        buf_append_cstr(&impl, "__impl");
        if (impl.data == NULL) {
            cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        f->c_name = impl.data;
        f->c_abi_name = surface_name;
        surface_name = NULL;
    } else {
        f->c_name = surface_name;
        surface_name = NULL;
    }
    f->decl = decl;
    f->owner_program = cg->cur_program;
    cg->free_fn_count++;
    ok = true;

cleanup:
    free(surface_name);
    if (!ok) {
        free(f->feng_name);
        free(f->c_name);
        free(f->c_abi_name);
        for (size_t i = 0U; i < f->param_count; ++i) {
            cgtype_free(f->param_types != NULL ? f->param_types[i] : NULL);
            free(f->param_names != NULL ? f->param_names[i] : NULL);
        }
        free(f->param_types);
        free(f->param_names);
        cgtype_free(f->return_type);
        memset(f, 0, sizeof(*f));
    }
    return ok;
}

static const FreeFn *cg_find_free_fn(const CG *cg, const char *name, size_t len) {
    for (size_t i = 0; i < cg->free_fn_count; i++) {
        if (strlen(cg->free_fns[i].feng_name) == len &&
            memcmp(cg->free_fns[i].feng_name, name, len) == 0) {
            return &cg->free_fns[i];
        }
    }
    return NULL;
}

/* Overload-aware lookup. Semantic analysis attaches the resolved FengDecl to
 * every call site (FengResolvedCallable.function_decl); when present, codegen
 * uses it to select the exact registered FreeFn rather than relying on
 * by-name lookup which would silently pick the first overload. */
static const FreeFn *cg_find_free_fn_by_decl(const CG *cg, const FengDecl *decl) {
    if (!decl) return NULL;
    for (size_t i = 0; i < cg->free_fn_count; i++) {
        if (cg->free_fns[i].decl == decl) return &cg->free_fns[i];
    }
    return NULL;
}

/* ----- user types ----- */

static bool cg_register_user_type_shell(CG *cg, const FengDecl *decl) {
    if (cg->user_type_count + 1 > cg->user_type_capacity) {
        uintptr_t old_base = (uintptr_t)cg->user_types;
        size_t old_count = cg->user_type_count;
        size_t cap = cg->user_type_capacity ? cg->user_type_capacity * 2 : 4;
        void *p = realloc(cg->user_types, cap * sizeof *cg->user_types);
        if (!p) return false;
        cg->user_types = p;
        cg->user_type_capacity = cap;
        cg_refresh_user_fit_targets(cg);
        cg_refresh_user_type_references(cg, old_base, old_count);
    }
    UserType *t = &cg->user_types[cg->user_type_count++];
    memset(t, 0, sizeof *t);
    t->owner_program = cg->cur_program;
    t->feng_name = strndup(decl->as.type_decl.name.data,
                           decl->as.type_decl.name.length);
    t->decl = decl;

    Buf b; buf_init(&b);
    buf_append_fmt(&b, "Feng__%s__", cg->module_mangle);
    char *san = cg_sanitize(decl->as.type_decl.name.data,
                            decl->as.type_decl.name.length);
    if (!san) { buf_free(&b); return false; }
    buf_append_cstr(&b, san);
    t->c_struct_name = b.data;

    Buf d; buf_init(&d);
    buf_append_fmt(&d, "FengTypeDesc__%s__%s", cg->module_mangle, san);
    t->c_desc_name = d.data;

    if (!cg_init_user_type_value_symbols(t)) {
        free(san);
        return false;
    }

    /* release_children symbol is materialised lazily in
     * cg_emit_user_type_definition: types without managed fields don't get a
     * function emitted and leave the descriptor slot NULL. */
    t->c_release_children_name = NULL;
    /* default_zero symbol is computed eagerly here so cross-type recursive
     * default-zero calls can use it before the per-type body is emitted.
     * Whether it is actually emitted (and whether it is legal to reference)
     * is decided in cg_emit_user_type_definition / cg_emit_default_value. */
    {
        Buf z; buf_init(&z);
        buf_append_fmt(&z, "%s__default_zero", t->c_struct_name);
        t->c_default_zero_name = z.data;
        if (!t->c_default_zero_name) { free(san); return false; }
    }
    t->is_abi_type = cg_annotations_contain_kind(decl->annotations,
                                                 decl->annotation_count,
                                                 FENG_ANNOTATION_ABI);
    if (!cg_init_user_type_abi_symbols(t)) {
        free(san);
        return false;
    }
    free(san);
    return t->feng_name && t->c_struct_name && t->c_desc_name;
}

static bool cg_init_type_static_binding(CG *cg,
                                        UserType *t,
                                        const FengTypeMember *member,
                                        TypeStaticBinding *binding) {
    char *field_san = NULL;
    Buf slot;
    Buf ensure;
    Buf inited;

    if (member == NULL || member->kind != FENG_TYPE_MEMBER_FIELD || binding == NULL) {
        return false;
    }

    memset(binding, 0, sizeof(*binding));
    binding->member = member;
    binding->owner_type = t;
    binding->is_var = member->as.field.mutability == FENG_MUTABILITY_VAR;
    binding->feng_name = strndup(member->as.field.name.data, member->as.field.name.length);
    field_san = cg_sanitize(member->as.field.name.data, member->as.field.name.length);
    if (binding->feng_name == NULL || field_san == NULL) {
        free(field_san);
        return false;
    }

    buf_init(&slot);
    buf_init(&ensure);
    buf_init(&inited);
    buf_append_fmt(&slot, "%s__static__%s", t->c_struct_name, field_san);
    buf_append_fmt(&ensure, "%s__static__%s__ensure_init", t->c_struct_name, field_san);
    buf_append_fmt(&inited, "%s__static__%s__inited", t->c_struct_name, field_san);
    free(field_san);

    binding->c_name = slot.data;
    binding->c_ensure_init_name = ensure.data;
    binding->c_inited_name = inited.data;
    if (binding->c_name == NULL || binding->c_ensure_init_name == NULL ||
        binding->c_inited_name == NULL) {
        return false;
    }

    return cg_resolve_user_field_type(cg, t, member, &binding->type);
}

/** Emit zero-initialized C storage for a Feng static binding by value category. */
static void cg_emit_static_storage_decl(Buf *out,
                                        bool exports_public_surface,
                                        bool weak_definition,
                                        const char *cty,
                                        const char *c_name,
                                        const CGType *type) {
    const char *prefix = weak_definition
                             ? "__attribute__((weak)) "
                             : (exports_public_surface ? "" : "static ");

    if (cgtype_is_managed(type)) {
        buf_append_fmt(out, "%s%s %s = NULL;\n", prefix, cty, c_name);
    } else if (cgtype_is_aggregate(type) || cgtype_is_by_value_struct(type)) {
        buf_append_fmt(out, "%s%s %s = {0};\n", prefix, cty, c_name);
    } else {
        buf_append_fmt(out, "%s%s %s = 0;\n", prefix, cty, c_name);
    }
}

static bool cg_emit_type_static_binding_decl(CG *cg, const TypeStaticBinding *binding) {
    char *cty;

    if (binding == NULL || binding->type == NULL) {
        return false;
    }
    cty = cg_ctype_dup(binding->type);
    if (cty == NULL) {
        return cg_fail(cg,
                       binding->member != NULL ? binding->member->token : (FengToken){0},
                       "IE0001", "codegen: out of memory");
    }
    cg_emit_static_storage_decl(&cg->statics,
                                binding->exports_public_surface,
                                cg_user_type_is_generic_origin_instance(
                                    binding->owner_type) &&
                                    binding->owner_type->generic_context_type_param_count == 0U,
                                cty,
                                binding->c_name,
                                binding->type);
    if (!cg_user_type_is_generic_origin_instance(binding->owner_type)) {
        buf_append_fmt(&cg->statics,
                       "static bool %s = false;\n",
                       binding->c_inited_name);
    }
    if (!cg_user_type_is_generic_origin_instance(binding->owner_type)) {
        buf_append_fmt(&cg->fn_protos,
                       "%svoid %s(void);\n",
                       binding->exports_public_surface ? "" : "static ",
                       binding->c_ensure_init_name);
    } else if (binding->exports_public_surface &&
               cg_program_origin(cg, binding->owner_type->owner_program) ==
                   FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        char *shared_ensure =
            cg_generic_type_static_ensure_shared_cname(
                cg,
                binding->owner_type->generic_origin_decl,
                binding->member);
        const char *descriptor_type =
            cg_user_type_is_value(binding->owner_type)
                ? "FengAggregateDescriptor"
                : "FengTypeDescriptor";

        if (shared_ensure == NULL) {
            free(cty);
            return cg_fail(cg,
                           binding->member != NULL
                               ? binding->member->token
                               : (FengToken){0},
                           "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(&cg->fn_protos,
            "void %s(const %s *_type_desc, "
            "FengStaticBindingState *_state);\n",
            shared_ensure,
            descriptor_type);
        free(shared_ensure);
    }
    free(cty);
    return true;
}

static bool cg_register_user_type_members(CG *cg, UserType *t, FengCompileTarget target) {
    const FengDecl *decl = t->decl;
    /* First pass: count fields/constructors/methods to size arrays. */
    size_t fcount = 0, ccount = 0, mcount = 0, sbcount = 0, smcount = 0;
    for (size_t i = 0; i < decl->as.type_decl.member_count; i++) {
        const FengTypeMember *m = decl->as.type_decl.members[i];
        if (m->kind == FENG_TYPE_MEMBER_FIELD) {
            if (m->is_static) sbcount++;
            else fcount++;
        }
        else if (m->kind == FENG_TYPE_MEMBER_METHOD) {
            if (m->is_static) smcount++;
            else mcount++;
        }
        else if (m->kind == FENG_TYPE_MEMBER_CONSTRUCTOR) ccount++;
        else if (m->kind == FENG_TYPE_MEMBER_FINALIZER) {
            if (t->finalizer) {
                return cg_fail(cg, m->token,
                    "CE0043", "codegen: type already declares a finalizer");
            }
            t->finalizer = m;
        }
    }
    if (t->finalizer) {
        Buf fb; buf_init(&fb);
        buf_append_fmt(&fb, "%s__finalize", t->c_struct_name);
        t->c_finalizer_name = fb.data;
        if (!t->c_finalizer_name) return false;
    }
    t->fields = fcount ? calloc(fcount, sizeof *t->fields) : NULL;
    t->constructors = ccount ? calloc(ccount, sizeof *t->constructors) : NULL;
    t->methods = mcount ? calloc(mcount, sizeof *t->methods) : NULL;
    t->static_bindings = sbcount ? calloc(sbcount, sizeof *t->static_bindings) : NULL;
    t->static_methods = smcount ? calloc(smcount, sizeof *t->static_methods) : NULL;
    if ((fcount && !t->fields) || (ccount && !t->constructors) ||
        (mcount && !t->methods) || (sbcount && !t->static_bindings) ||
        (smcount && !t->static_methods)) return false;

    size_t fi = 0, ci = 0, mi = 0, sbi = 0, smi = 0;
    for (size_t i = 0; i < decl->as.type_decl.member_count; i++) {
        const FengTypeMember *m = decl->as.type_decl.members[i];
        if (m->kind == FENG_TYPE_MEMBER_FIELD) {
            if (m->is_static) {
                TypeStaticBinding *sb = &t->static_bindings[sbi++];

                if (!cg_init_type_static_binding(cg, t, m, sb)) return false;
                sb->exports_public_surface =
                    cg_member_uses_package_static_binding_codegen(
                        cg,
                        t->decl,
                        m) &&
                    (target == FENG_COMPILE_TARGET_LIB ||
                     cg_program_origin(cg, t->owner_program) ==
                         FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE);
                if (((!cg_user_type_is_generic_origin_instance(t) &&
                      cg_program_origin(cg, t->owner_program) !=
                          FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) ||
                     (cg_user_type_is_generic_origin_instance(t) &&
                      t->generic_context_type_param_count == 0U)) &&
                    !cg_emit_type_static_binding_decl(cg, sb)) {
                    return false;
                }
                continue;
            }
            UserField *uf = &t->fields[fi++];
            uf->feng_name = strndup(m->as.field.name.data, m->as.field.name.length);
            uf->c_name = cg_sanitize(m->as.field.name.data, m->as.field.name.length);
            uf->member = m;
            if (!uf->feng_name || !uf->c_name) return false;
            if (!cg_resolve_user_field_type(cg, t, m, &uf->type)) return false;
        } else if (m->kind == FENG_TYPE_MEMBER_CONSTRUCTOR ||
                   m->kind == FENG_TYPE_MEMBER_METHOD) {
            bool is_ctor = m->kind == FENG_TYPE_MEMBER_CONSTRUCTOR;
             UserMethod *um = is_ctor
                         ? &t->constructors[ci++]
                         : m->is_static ? &t->static_methods[smi++] : &t->methods[mi++];
            const FengCallableSignature *sig = &m->as.callable;
            um->member = m;
            um->feng_name = strndup(sig->name.data, sig->name.length);
            char *msan = cg_sanitize(sig->name.data, sig->name.length);
            if (!um->feng_name || !msan) { free(msan); return false; }
            Buf cb; buf_init(&cb);
            if (is_ctor) {
                buf_append_fmt(&cb, "%s__ctor__%s", t->c_struct_name, msan);
            } else if (m->is_static) {
                buf_append_fmt(&cb, "%s__static__%s", t->c_struct_name, msan);
            } else {
                buf_append_fmt(&cb, "%s__%s", t->c_struct_name, msan);
            }
            um->c_name = cb.data;
            free(msan);
            um->param_count = sig->param_count;
            um->is_variadic = sig->param_count > 0U &&
                              sig->params[sig->param_count - 1U].is_variadic;
            um->param_types = sig->param_count ? calloc(sig->param_count, sizeof(CGType*)) : NULL;
            um->param_names = sig->param_count ? calloc(sig->param_count, sizeof(char*)) : NULL;
            for (size_t pi = 0; pi < sig->param_count; pi++) {
                if (!cg_resolve_type_for_user_method_member(cg, t, sig,
                                                            sig->params[pi].type,
                                                            &sig->params[pi].token,
                                                            &um->param_types[pi])) return false;
                um->param_names[pi] = strndup(sig->params[pi].name.data,
                                              sig->params[pi].name.length);
            }
            if (!cg_resolve_user_method_return_type(cg, t, sig,
                                                    &sig->token, &um->return_type)) {
                return false;
            }
            um->c_name = cg_append_param_suffix(um->c_name,
                                                um->param_types, um->param_count,
                                                um->is_variadic,
                                                sig->type_param_count > 0U);
            if (!um->c_name) return false;
        }
    }
    t->field_count = fi;
    t->constructor_count = ci;
    t->method_count = mi;
    t->static_binding_count = sbi;
    t->static_method_count = smi;
    t->generic_layout_fact = CG_GENERIC_LAYOUT_UNKNOWN;
    if (cg_user_type_uses_static_binding_states(t) &&
        (cg_program_origin(cg, t->owner_program) !=
             FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE ||
         t->generic_context_type_param_count == 0U)) {
        char *states_name = cg_user_type_static_binding_states_name_dup(t);
        const char *linkage = "__attribute__((weak)) ";

        if (states_name == NULL) {
            return cg_fail(cg, t->decl->token,
                           "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(&cg->statics,
                       "%sFengStaticBindingState %s[] = {\n",
                       linkage,
                       states_name);
        for (size_t binding_index = 0U;
             binding_index < t->static_binding_count;
             ++binding_index) {
            buf_append_fmt(&cg->statics,
                           "    { .storage = (void *)&%s, .initialized = false },\n",
                           t->static_bindings[binding_index].c_name);
        }
        buf_append_cstr(&cg->statics, "};\n");
        free(states_name);
    }
    return cg_debug_add_user_type_field_records(cg, t, decl->token);
}

static const UserField *cg_user_type_field(const UserType *t, const char *name, size_t len) {
    for (size_t i = 0; i < t->field_count; i++) {
        if (strlen(t->fields[i].feng_name) == len &&
            memcmp(t->fields[i].feng_name, name, len) == 0) {
            return &t->fields[i];
        }
    }
    return NULL;
}

static const UserMethod *cg_user_type_method(const UserType *t, const char *name, size_t len) {
    for (size_t i = 0; i < t->method_count; i++) {
        if (strlen(t->methods[i].feng_name) == len &&
            memcmp(t->methods[i].feng_name, name, len) == 0) {
            return &t->methods[i];
        }
    }
    return NULL;
}

/* Overload-aware method lookup: matches by the FengTypeMember pointer that
 * semantic analysis stored on the call site. By-name lookup would silently
 * pick the first overload of `name`. */
static const UserMethod *cg_user_type_method_by_member(const UserType *t,
                                                       const FengTypeMember *m) {
    if (!m) return NULL;
    for (size_t i = 0; i < t->method_count; i++) {
        if (t->methods[i].member == m) return &t->methods[i];
    }
    return NULL;
}

static const TypeStaticBinding *cg_user_type_static_binding(const UserType *t,
                                                            const char *name,
                                                            size_t len) {
    if (t == NULL) return NULL;
    for (size_t i = 0; i < t->static_binding_count; i++) {
        if (strlen(t->static_bindings[i].feng_name) == len &&
            memcmp(t->static_bindings[i].feng_name, name, len) == 0) {
            return &t->static_bindings[i];
        }
    }
    return NULL;
}

static const UserMethod *cg_user_type_static_method(const UserType *t,
                                                    const char *name,
                                                    size_t len) {
    if (t == NULL) return NULL;
    for (size_t i = 0; i < t->static_method_count; i++) {
        if (strlen(t->static_methods[i].feng_name) == len &&
            memcmp(t->static_methods[i].feng_name, name, len) == 0) {
            return &t->static_methods[i];
        }
    }
    return NULL;
}

static const UserMethod *cg_user_type_static_method_by_member(const UserType *t,
                                                              const FengTypeMember *m) {
    if (t == NULL || m == NULL) return NULL;
    for (size_t i = 0; i < t->static_method_count; i++) {
        if (t->static_methods[i].member == m) return &t->static_methods[i];
    }
    return NULL;
}

static const UserMethod *cg_user_type_constructor_by_member(const UserType *t,
                                                            const FengTypeMember *m) {
    if (!m) return NULL;
    for (size_t i = 0; i < t->constructor_count; i++) {
        if (t->constructors[i].member == m) return &t->constructors[i];
    }
    return NULL;
}

