/* ------------- Spec registration (Step 4b — value model) ------------- */

static bool cg_register_user_spec_shell(CG *cg, const FengDecl *decl) {
    if (cg->user_spec_count + 1 > cg->user_spec_capacity) {
        uintptr_t old_base = (uintptr_t)cg->user_specs;
        size_t old_count = cg->user_spec_count;
        size_t cap = cg->user_spec_capacity ? cg->user_spec_capacity * 2 : 4;
        void *p = realloc(cg->user_specs, cap * sizeof *cg->user_specs);
        if (!p) return false;
        cg->user_specs = p;
        cg->user_spec_capacity = cap;
        cg_refresh_user_fit_specs(cg);
        cg_refresh_user_spec_references(cg, old_base, old_count);
    }
    UserSpec *s = &cg->user_specs[cg->user_spec_count++];
    memset(s, 0, sizeof *s);
    s->owner_program = cg->cur_program;
    s->decl = decl;
    s->form = decl->as.spec_decl.form;
    s->feng_name = strndup(decl->as.spec_decl.name.data,
                           decl->as.spec_decl.name.length);
    if (!s->feng_name) return false;

    char *san = cg_sanitize(decl->as.spec_decl.name.data,
                            decl->as.spec_decl.name.length);
    if (!san) return false;

    if (s->form == FENG_SPEC_FORM_OBJECT || s->form == FENG_SPEC_FORM_UNION ||
        s->form == FENG_SPEC_FORM_INTERSECTION) {
        Buf vb; buf_init(&vb);
        buf_append_fmt(&vb, "FengSpecValue__%s__%s", cg->module_mangle, san);
        s->c_value_struct_name = vb.data;

        Buf db; buf_init(&db);
        buf_append_fmt(&db, "FengSpecAgg__%s__%s", cg->module_mangle, san);
        s->c_aggregate_desc_name = db.data;

        Buf sb; buf_init(&sb);
        buf_append_fmt(&sb, "FengSpecAggSlots__%s__%s", cg->module_mangle, san);
        s->c_aggregate_slots_name = sb.data;

        Buf db2; buf_init(&db2);
        buf_append_fmt(&db2, "FengSpecAggDefault__%s__%s", cg->module_mangle, san);
        s->c_aggregate_default_name = db2.data;

        Buf ib; buf_init(&ib);
        buf_append_fmt(&ib, "FengSpecAggInit__%s__%s", cg->module_mangle, san);
        s->c_aggregate_init_fn_name = ib.data;

        Buf wb; buf_init(&wb);
        buf_append_fmt(&wb, "FengSpecWitness__%s__%s", cg->module_mangle, san);
        s->c_witness_struct_name = wb.data;

        if (s->form == FENG_SPEC_FORM_OBJECT || s->form == FENG_SPEC_FORM_INTERSECTION) {
            Buf dssb; buf_init(&dssb);
            buf_append_fmt(&dssb, "FengSpecDefault__%s__%s__Subject",
                           cg->module_mangle, san);
            s->c_default_subject_struct_name = dssb.data;

            Buf ddb; buf_init(&ddb);
            buf_append_fmt(&ddb, "FengSpecDefault__%s__%s__Subject_desc",
                           cg->module_mangle, san);
            s->c_default_subject_desc_name = ddb.data;

            Buf dnb; buf_init(&dnb);
            buf_append_fmt(&dnb, "FengSpecDefault__%s__%s__new_subject",
                           cg->module_mangle, san);
            s->c_default_subject_new_name = dnb.data;

            Buf dwb; buf_init(&dwb);
            buf_append_fmt(&dwb, "FengSpecDefaultWitness__%s__%s",
                           cg->module_mangle, san);
            s->c_default_witness_name = dwb.data;
        }
    } else {
        Buf wb; buf_init(&wb);
        buf_append_fmt(&wb, "FengSpecWitness__%s__%s", cg->module_mangle, san);
        s->c_witness_struct_name = wb.data;

        Buf cb; buf_init(&cb);
        buf_append_fmt(&cb, "FengClosure__%s__%s", cg->module_mangle, san);
        s->c_closure_struct_name = cb.data;

        Buf db; buf_init(&db);
        buf_append_fmt(&db, "FengClosureDesc__%s__%s", cg->module_mangle, san);
        s->c_closure_desc_name = db.data;

        Buf pb; buf_init(&pb);
        buf_append_fmt(&pb, "FengAbiFnPtr__%s__%s", cg->module_mangle, san);
        s->c_abi_fn_ptr_typedef_name = pb.data;

        Buf nb; buf_init(&nb);
        buf_append_fmt(&nb, "FengCallableDefault__%s__%s__noop", cg->module_mangle, san);
        s->c_default_callable_noop_name = nb.data;

        Buf fb; buf_init(&fb);
        buf_append_fmt(&fb, "FengCallableDefault__%s__%s__new", cg->module_mangle, san);
        s->c_default_callable_new_name = fb.data;
    }

    free(san);
    if (s->form == FENG_SPEC_FORM_OBJECT || s->form == FENG_SPEC_FORM_INTERSECTION) {
        return s->c_value_struct_name && s->c_witness_struct_name
            && s->c_aggregate_desc_name && s->c_aggregate_slots_name
            && s->c_aggregate_default_name && s->c_aggregate_init_fn_name
            && s->c_default_subject_struct_name && s->c_default_subject_desc_name
            && s->c_default_subject_new_name && s->c_default_witness_name;
    }
    if (s->form == FENG_SPEC_FORM_UNION) {
        return s->c_value_struct_name && s->c_witness_struct_name
            && s->c_aggregate_desc_name && s->c_aggregate_slots_name
            && s->c_aggregate_default_name && s->c_aggregate_init_fn_name;
    }
    return s->c_witness_struct_name && s->c_closure_struct_name &&
           s->c_closure_desc_name && s->c_abi_fn_ptr_typedef_name &&
           s->c_default_callable_noop_name && s->c_default_callable_new_name;
}

static bool cg_register_user_spec_members(CG *cg, UserSpec *s) {
    const FengDecl *decl = s->decl;
    if (s->form == FENG_SPEC_FORM_CALLABLE) {
        CGTypeParamScope callable_scope = {
            .first = decl->as.spec_decl.type_params,
            .first_count = decl->as.spec_decl.type_param_count,
        };

        s->callable_param_count = decl->as.spec_decl.as.callable.param_count;
        s->callable_is_variadic = decl->as.spec_decl.as.callable.param_count > 0U &&
                                  decl->as.spec_decl.as.callable
                                      .params[decl->as.spec_decl.as.callable.param_count - 1U]
                                      .is_variadic;
        s->callable_param_types = decl->as.spec_decl.as.callable.param_count
            ? calloc(decl->as.spec_decl.as.callable.param_count,
                     sizeof *s->callable_param_types)
            : NULL;
        s->callable_param_abi_kinds = decl->as.spec_decl.as.callable.param_count
            ? calloc(decl->as.spec_decl.as.callable.param_count,
                     sizeof *s->callable_param_abi_kinds)
            : NULL;
        if (decl->as.spec_decl.as.callable.param_count > 0U &&
            (s->callable_param_types == NULL ||
             s->callable_param_abi_kinds == NULL)) {
            return false;
        }
        for (size_t i = 0; i < decl->as.spec_decl.as.callable.param_count; ++i) {
            if (!cg_resolve_type_for_user_spec_member(
                    cg,
                    s,
                    decl->as.spec_decl.as.callable.params[i].type,
                    &decl->as.spec_decl.as.callable.params[i].token,
                    &s->callable_param_types[i])) {
                return false;
            }
            s->callable_param_abi_kinds[i] =
                cg_callable_decl_slot_abi_kind(
                    decl->as.spec_decl.as.callable.params[i].type,
                    &callable_scope,
                    s->callable_param_types[i]);
        }
        if (!cg_resolve_type_for_user_spec_member(cg,
                                                  s,
                                                  decl->as.spec_decl.as.callable.return_type,
                                                  &decl->token,
                                                  &s->callable_return_type)) {
            return false;
        }
        s->callable_return_abi_kind = cg_callable_decl_slot_abi_kind(
            decl->as.spec_decl.as.callable.return_type,
            &callable_scope,
            s->callable_return_type);
        return true;
    }
    if (s->form == FENG_SPEC_FORM_UNION) {
        const FengUnionSpecInfo *info =
            feng_semantic_lookup_union_spec_info(cg->analysis, decl);
        size_t member_count = info != NULL
                                  ? info->member_count
                                  : decl->as.spec_decl.as.union_form.member_count;

        if (member_count == 0U) {
            return cg_fail(cg, decl->token,
                           "CE0044", "codegen: union-form spec has no normalized members");
        }
        s->union_member_types = (CGType **)calloc(member_count,
                                                  sizeof(*s->union_member_types));
        if (s->union_member_types == NULL) {
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
        s->union_member_count = member_count;
        for (size_t member_index = 0U; member_index < member_count; ++member_index) {
            const FengTypeRef *member_ref = info != NULL
                ? info->members[member_index].type_ref
                : decl->as.spec_decl.as.union_form.members[member_index];

            if (!cg_resolve_type_for_user_spec_member(cg,
                                                      s,
                                                      member_ref,
                                                      member_ref != NULL ? &member_ref->token : &decl->token,
                                                      &s->union_member_types[member_index])) {
                return false;
            }
        }
        return true;
    }
    if (s->form == FENG_SPEC_FORM_INTERSECTION) {
        UserSpec pending_overloads;

        memset(&pending_overloads, 0, sizeof pending_overloads);
        /* Intersection members are derived from the flattened member spec
         * list computed by 9.3/9.4 (resolve_intersection_spec_form). Each
         * flattened member is an object-form spec decl; we clone its
         * members[] into the intersection's members[] with source_member_decl
         * set, so cg_ensure_witness_instance_for_type can later locate the
         * subject's per-member-spec witness when assembling the merged
         * witness constant. Semantic-equivalent requirements share the
         * first-seen slot; same-name methods with distinct parameter
         * signatures are staged and appended as legal overload slots after
         * every historical first-name field.
         *
         * 9.9: for generic intersection instances (e.g. `Comparable<IntBox>`
         * from `spec Comparable<T>: Eq<T> & Ord<T>`), flattened_members only
         * stores bare decls (Eq<T>, Ord<T>) — the type-arg information is
         * lost. So we re-traverse intersection_form.members[] (the original
         * type refs with type args), substitute the intersection's type
         * params with the instance's type args, resolve the substituted ref
         * to the correct member-spec generic instance (Eq<IntBox>), and
         * record that substituted ref as source_member_type_ref so
         * cg_ensure_witness_instance_for_type can later locate the right
         * UserSpec (not the generic context). Nested intersection members
         * propagate their leaf source_member_type_ref through the clone. */
        const FengIntersectionSpecInfo *info =
            feng_semantic_lookup_intersection_spec_info(cg->analysis, decl);
        if (info == NULL) {
            return cg_fail(cg, decl->token,
                "CE0355", "codegen: intersection-form spec has no flattened member info");
        }
        if (s->is_generic_instance) {
            /* 9.9: generic instance — re-traverse intersection_form.members[]
             * with type-arg substitution. */
            /* When the intersection is an open generic instance (e.g.
             * `Comparable<T>` registered as a generic context from
             * `func do_compare<T: Comparable<T>>`), resolving the substituted
             * member ref `Eq<T>` requires the active generic-fn context so
             * cg_find_generic_instance_user_spec_for_ref can match the
             * generic-context UserSpec. Temporarily install the instance's
             * own context names while resolving, mirroring
             * cg_resolve_type_for_user_spec_member. */
            bool saved_in_generic_fn = cg->in_generic_fn;
            size_t saved_tp_count = cg->generic_fn_type_param_count;
            char **saved_tp_names = cg->generic_fn_type_param_names;
            const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
            const char **saved_tp_descs = cg->generic_fn_type_param_descs;
            if (s->generic_context_type_param_count > 0U) {
                cg->in_generic_fn = true;
                cg->generic_fn_type_param_count = s->generic_context_type_param_count;
                cg->generic_fn_type_param_names = s->generic_context_type_param_names;
                cg->generic_fn_type_param_constraints = NULL;
                cg->generic_fn_type_param_descs = NULL;
            }
            for (size_t mi = 0U;
                 mi < decl->as.spec_decl.as.intersection_form.member_count;
                 ++mi) {
                const FengTypeRef *member_ref =
                    decl->as.spec_decl.as.intersection_form.members[mi];
                FengTypeRef *sub = cg_type_ref_substitute(
                    member_ref,
                    decl->as.spec_decl.type_params,
                    decl->as.spec_decl.type_param_count,
                    s->generic_type_args);
                if (sub == NULL) {
                    cg_user_spec_members_free(&pending_overloads);
                    if (s->generic_context_type_param_count > 0U) {
                        cg->in_generic_fn = saved_in_generic_fn;
                        cg->generic_fn_type_param_count = saved_tp_count;
                        cg->generic_fn_type_param_names = saved_tp_names;
                        cg->generic_fn_type_param_constraints = saved_tp_constraints;
                        cg->generic_fn_type_param_descs = saved_tp_descs;
                    }
                    return false;
                }

                CGType *member_type = NULL;
                if (!cg_resolve_type(cg, sub, &decl->token, &member_type)) {
                    cg_type_ref_free(sub);
                    cg_user_spec_members_free(&pending_overloads);
                    if (s->generic_context_type_param_count > 0U) {
                        cg->in_generic_fn = saved_in_generic_fn;
                        cg->generic_fn_type_param_count = saved_tp_count;
                        cg->generic_fn_type_param_names = saved_tp_names;
                        cg->generic_fn_type_param_constraints = saved_tp_constraints;
                        cg->generic_fn_type_param_descs = saved_tp_descs;
                    }
                    return false;
                }
                const UserSpec *member_spec =
                    (member_type != NULL &&
                     (member_type->kind == CG_TYPE_SPEC ||
                      member_type->kind == CG_TYPE_CALLABLE))
                        ? member_type->user_spec : NULL;
                if (member_spec == NULL) {
                    cgtype_free(member_type);
                    cg_type_ref_free(sub);
                    cg_user_spec_members_free(&pending_overloads);
                    if (s->generic_context_type_param_count > 0U) {
                        cg->in_generic_fn = saved_in_generic_fn;
                        cg->generic_fn_type_param_count = saved_tp_count;
                        cg->generic_fn_type_param_names = saved_tp_names;
                        cg->generic_fn_type_param_constraints = saved_tp_constraints;
                        cg->generic_fn_type_param_descs = saved_tp_descs;
                    }
                    return cg_fail(cg, decl->token,
                        "CE0356", "codegen: intersection-form spec member spec not registered");
                }
                if (!cg_ensure_user_spec_members_registered(cg, (UserSpec *)member_spec)) {
                    cgtype_free(member_type);
                    cg_type_ref_free(sub);
                    cg_user_spec_members_free(&pending_overloads);
                    if (s->generic_context_type_param_count > 0U) {
                        cg->in_generic_fn = saved_in_generic_fn;
                        cg->generic_fn_type_param_count = saved_tp_count;
                        cg->generic_fn_type_param_names = saved_tp_names;
                        cg->generic_fn_type_param_constraints = saved_tp_constraints;
                        cg->generic_fn_type_param_descs = saved_tp_descs;
                    }
                    return false;
                }
                for (size_t member_index = 0U;
                     member_index < member_spec->member_count;
                     ++member_index) {
                    const UserSpecMember *src_member =
                        &member_spec->members[member_index];
                    const FengDecl *decl_for_clone;
                    FengTypeRef *type_ref_for_clone;

                    if (src_member->source_member_type_ref != NULL) {
                        /* Nested intersection generic instance: inherit the
                         * leaf's substituted type ref and decl. */
                        decl_for_clone = src_member->source_member_decl;
                        type_ref_for_clone =
                            cg_type_ref_clone(src_member->source_member_type_ref);
                    } else {
                        /* Direct member-spec generic instance: use the outer
                         * substituted ref and the member spec's origin decl. */
                        decl_for_clone = member_spec->decl;
                        type_ref_for_clone = cg_type_ref_clone(sub);
                    }
                    if (type_ref_for_clone == NULL) {
                        cgtype_free(member_type);
                        cg_type_ref_free(sub);
                        cg_user_spec_members_free(&pending_overloads);
                        if (s->generic_context_type_param_count > 0U) {
                            cg->in_generic_fn = saved_in_generic_fn;
                            cg->generic_fn_type_param_count = saved_tp_count;
                            cg->generic_fn_type_param_names = saved_tp_names;
                            cg->generic_fn_type_param_constraints = saved_tp_constraints;
                            cg->generic_fn_type_param_descs = saved_tp_descs;
                        }
                        return cg_fail(cg, decl->token, "IE0001",
                            "codegen: out of memory");
                    }
                    if (!cg_user_spec_record_intersection_member(
                            cg,
                            s,
                            &pending_overloads,
                            src_member,
                            decl_for_clone,
                            type_ref_for_clone,
                            decl->token)) {
                        cgtype_free(member_type);
                        cg_type_ref_free(sub);
                        cg_user_spec_members_free(&pending_overloads);
                        if (s->generic_context_type_param_count > 0U) {
                            cg->in_generic_fn = saved_in_generic_fn;
                            cg->generic_fn_type_param_count = saved_tp_count;
                            cg->generic_fn_type_param_names = saved_tp_names;
                            cg->generic_fn_type_param_constraints = saved_tp_constraints;
                            cg->generic_fn_type_param_descs = saved_tp_descs;
                        }
                        return false;
                    }
                }
                cgtype_free(member_type);
                cg_type_ref_free(sub);
            }
            if (s->generic_context_type_param_count > 0U) {
                cg->in_generic_fn = saved_in_generic_fn;
                cg->generic_fn_type_param_count = saved_tp_count;
                cg->generic_fn_type_param_names = saved_tp_names;
                cg->generic_fn_type_param_constraints = saved_tp_constraints;
                cg->generic_fn_type_param_descs = saved_tp_descs;
            }
        } else {
            /* Non-generic: use flattened_members[] (bare decls suffice). */
            for (size_t mi = 0U; mi < info->flattened_member_count; ++mi) {
                const FengDecl *member_decl = info->flattened_members[mi];
                const UserSpec *member_spec = cg_find_user_spec_by_decl(cg, member_decl);
                if (member_spec == NULL) {
                    cg_user_spec_members_free(&pending_overloads);
                    return cg_fail(cg, decl->token,
                        "CE0356", "codegen: intersection-form spec member spec not registered");
                }
                if (!cg_ensure_user_spec_members_registered(cg, (UserSpec *)member_spec)) {
                    cg_user_spec_members_free(&pending_overloads);
                    return false;
                }
                for (size_t member_index = 0U; member_index < member_spec->member_count; ++member_index) {
                    const UserSpecMember *src_member = &member_spec->members[member_index];
                    if (!cg_user_spec_record_intersection_member(
                            cg,
                            s,
                            &pending_overloads,
                            src_member,
                            member_decl,
                            NULL,
                            decl->token)) {
                        cg_user_spec_members_free(&pending_overloads);
                        return false;
                    }
                }
            }
        }
        if (!cg_user_spec_commit_overloads(
                s, &pending_overloads)) {
            cg_user_spec_members_free(&pending_overloads);
            return cg_fail(cg,
                           decl->token,
                           "IE0001",
                           "codegen: out of memory while registering intersection overload slots");
        }
        return true;
    }
    UserSpec pending_overloads;
    UserSpec own_members;

    memset(&pending_overloads, 0, sizeof(pending_overloads));
    memset(&own_members, 0, sizeof(own_members));
    s->direct_parent_spec_count = decl->as.spec_decl.parent_spec_count;
    if (s->direct_parent_spec_count > 0U) {
        s->direct_parent_spec_indices = (size_t *)calloc(
            s->direct_parent_spec_count,
            sizeof(*s->direct_parent_spec_indices));
        if (s->direct_parent_spec_indices == NULL) {
            cg_user_spec_members_free(&pending_overloads);
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
    }
    for (size_t parent_index = 0; parent_index < decl->as.spec_decl.parent_spec_count; ++parent_index) {
        CGType *parent_type = NULL;
        UserSpec *parent_spec = NULL;
        size_t parent_spec_index;
        if (!cg_resolve_type_for_user_spec_member(cg,
                                                  s,
                                                  decl->as.spec_decl.parent_specs[parent_index],
                                                  &decl->token,
                                                  &parent_type)) {
            cg_user_spec_members_free(&pending_overloads);
            return false;
        }
        if (parent_type == NULL || parent_type->kind != CG_TYPE_SPEC || parent_type->user_spec == NULL) {
            cgtype_free(parent_type);
            cg_user_spec_members_free(&pending_overloads);
            return cg_fail(cg, decl->token,
                "CE0046", "codegen: spec parent did not resolve to an object-form spec");
        }
        parent_spec = (UserSpec *)parent_type->user_spec;
        if (!cg_user_spec_index(cg, parent_spec, &parent_spec_index)) {
            cgtype_free(parent_type);
            cg_user_spec_members_free(&pending_overloads);
            return cg_fail(cg, decl->token,
                "CE0046", "codegen: resolved spec parent is not registered");
        }
        s->direct_parent_spec_indices[parent_index] = parent_spec_index;
        if (!cg_ensure_user_spec_members_registered(cg, parent_spec)) {
            cgtype_free(parent_type);
            cg_user_spec_members_free(&pending_overloads);
            return false;
        }
        for (size_t member_index = 0; member_index < parent_spec->member_count; ++member_index) {
            const UserSpecMember *parent_member = &parent_spec->members[member_index];

            if (!cg_user_spec_record_object_member(
                    s,
                    &pending_overloads,
                    parent_member,
                    false)) {
                cgtype_free(parent_type);
                cg_user_spec_members_free(&pending_overloads);
                return false;
            }
        }
        cgtype_free(parent_type);
    }
    own_members = *s;
    own_members.members = NULL;
    own_members.member_count = 0U;
    for (size_t i = 0; i < decl->as.spec_decl.as.object.member_count; i++) {
        const FengTypeMember *m = decl->as.spec_decl.as.object.members[i];

        if (!cg_user_spec_append_decl_member(cg, &own_members, m)) {
            cg_user_spec_members_free(&own_members);
            cg_user_spec_members_free(&pending_overloads);
            return false;
        }
    }
    for (size_t member_index = 0U;
         member_index < own_members.member_count;
         ++member_index) {
        if (!cg_user_spec_record_object_member(
                s,
                &pending_overloads,
                &own_members.members[member_index],
                true)) {
            cg_user_spec_members_free(&own_members);
            cg_user_spec_members_free(&pending_overloads);
            return false;
        }
    }
    cg_user_spec_members_free(&own_members);
    if (!cg_user_spec_commit_overloads(s, &pending_overloads)) {
        cg_user_spec_members_free(&pending_overloads);
        return cg_fail(
            cg,
            decl->token,
            "IE0001",
            "codegen: out of memory while registering object-form spec overload slots");
    }
    return true;
}

static bool cg_ensure_user_spec_members_registered(CG *cg, UserSpec *s) {
    const FengProgram *saved_program;
    bool ok;

    if (s == NULL) return true;
    if (s->members_registered) return true;
    if (s->members_registering) {
        return cg_fail(cg, s->decl->token,
            "CE0047", "codegen: recursive spec parent registration detected");
    }
    s->members_registering = true;
    saved_program = cg->cur_program;
    cg->cur_program = s->instantiation_program != NULL
        ? s->instantiation_program
        : s->owner_program;
    ok = cg_register_user_spec_members(cg, s);
    cg->cur_program = saved_program;
    s->members_registering = false;
    if (ok) s->members_registered = true;
    return ok;
}

static const UserSpecMember *cg_user_spec_member(const UserSpec *s,
                                                 const char *name, size_t len) {
    for (size_t i = 0; i < s->member_count; i++) {
        if (strlen(s->members[i].feng_name) == len &&
            memcmp(s->members[i].feng_name, name, len) == 0) {
            return &s->members[i];
        }
    }
    return NULL;
}

/* Find a field in one exact instance/static witness member surface. */
static const UserSpecMember *cg_user_spec_field_member(
    const UserSpec *spec,
    const char *name,
    size_t length,
    bool require_static) {
    if (spec == NULL || name == NULL) return NULL;
    for (size_t index = 0U; index < spec->member_count; ++index) {
        const UserSpecMember *candidate = &spec->members[index];

        if (candidate->kind == USM_KIND_FIELD &&
            candidate->is_static == require_static &&
            cg_user_spec_member_name_equals(candidate, name, length)) {
            return candidate;
        }
    }
    return NULL;
}

/* Find the exact requirement selected by Semantic instead of repeating
 * overload selection from a source-level name. Inherited slots preserve the
 * original FengTypeMember identity when copied into a child spec surface. */
static const UserSpecMember *cg_user_spec_member_by_decl(
    const UserSpec *spec,
    const FengTypeMember *member) {
    if (spec == NULL || member == NULL) {
        return NULL;
    }
    for (size_t index = 0U; index < spec->member_count; ++index) {
        if (cg_user_spec_member_has_decl(&spec->members[index], member)) {
            return &spec->members[index];
        }
    }
    return NULL;
}

/* Find a declaration identity only when it denotes one slot in this closed
 * surface. A repeated generic AST member needs additional closed-owner or
 * callable-target information and must not silently fall back to the first
 * slot. */
static const UserSpecMember *cg_user_spec_member_by_unique_decl(
    const UserSpec *spec,
    const FengTypeMember *member) {
    const UserSpecMember *result = NULL;

    if (spec == NULL || member == NULL) {
        return NULL;
    }
    for (size_t index = 0U; index < spec->member_count; ++index) {
        if (!cg_user_spec_member_has_decl(&spec->members[index], member)) {
            continue;
        }
        if (result != NULL) {
            return NULL;
        }
        result = &spec->members[index];
    }
    return result;
}

/* Resolve the exact Semantic-selected field for a member expression. The
 * surface fallback is retained for imported or legacy sites without a
 * SpecMemberAccess sidecar. */
static const UserSpecMember *cg_user_spec_field_member_for_access(
    const CG *cg,
    const UserSpec *spec,
    const FengExpr *member_expr,
    bool fallback_static) {
    const FengSpecMemberAccess *access =
        cg != NULL && cg->analysis != NULL && member_expr != NULL
            ? feng_semantic_lookup_spec_member_access(cg->analysis,
                                                      member_expr)
            : NULL;

    if (access != NULL && access->member != NULL &&
        access->member->kind == FENG_TYPE_MEMBER_FIELD) {
        const UserSpecMember *selected =
            cg_user_spec_member_by_unique_decl(spec, access->member);

        if (selected != NULL && selected->kind == USM_KIND_FIELD) {
            return selected;
        }
        fallback_static = access->member->is_static;
    }
    return member_expr != NULL
               ? cg_user_spec_field_member(
                     spec,
                     member_expr->as.member.member.data,
                     member_expr->as.member.member.length,
                     fallback_static)
               : NULL;
}

/* Find one closed requirement slot within a larger spec surface. Generic
 * parent instances may share the same AST member declaration, so declaration
 * identity narrows the candidates while the already-lowered signature selects
 * the exact closed slot. This lookup is compiler-only and does not affect the
 * emitted witness layout. */
static const UserSpecMember *cg_user_spec_member_matching_slot(
    const UserSpec *spec,
    const UserSpecMember *required_slot) {
    if (spec == NULL || required_slot == NULL ||
        required_slot->member == NULL) {
        return NULL;
    }
    for (size_t index = 0U; index < spec->member_count; ++index) {
        const UserSpecMember *candidate = &spec->members[index];

        if (cg_user_spec_member_has_decl(candidate, required_slot->member) &&
            cg_user_spec_member_compatible(candidate, required_slot)) {
            return candidate;
        }
    }
    return NULL;
}

/* Resolve the exact slot selected for one Semantic spec call. The selected
 * declaring owner instance identifies the closed generic requirement; that
 * small declaring surface is then projected into the receiver's full surface.
 * No source-level overload resolution is repeated here. */
static const UserSpecMember *cg_user_spec_member_for_resolved_call(
    CG *cg,
    const UserSpec *receiver_spec,
    const FengResolvedCallable *resolved) {
    const UserSpec *declaring_spec = NULL;
    const UserSpecMember *declaring_slot = NULL;

    if (cg == NULL || receiver_spec == NULL || resolved == NULL ||
        resolved->member == NULL) {
        return NULL;
    }
    if (resolved->owner_instance_type_ref != NULL &&
        resolved->owner_instance_type_ref->kind == FENG_TYPE_REF_NAMED) {
        if (resolved->owner_instance_type_ref->as.named.type_arg_count > 0U) {
            declaring_spec = cg_find_generic_instance_user_spec_for_ref(
                cg, resolved->owner_instance_type_ref);
        } else {
            declaring_spec = cg_find_user_spec_by_ref(
                cg, resolved->owner_instance_type_ref);
        }
    }
    if (declaring_spec == NULL && resolved->owner_type_decl != NULL &&
        resolved->owner_type_decl->kind == FENG_DECL_SPEC) {
        declaring_spec = cg_find_user_spec_by_decl(
            cg, resolved->owner_type_decl);
    }
    if (declaring_spec != NULL &&
        cg_ensure_user_spec_members_registered(
            cg, (UserSpec *)declaring_spec)) {
        declaring_slot = cg_user_spec_member_by_decl(
            declaring_spec, resolved->member);
        if (declaring_slot != NULL) {
            const UserSpecMember *projected =
                cg_user_spec_member_matching_slot(
                    receiver_spec, declaring_slot);

            if (projected != NULL) {
                return projected;
            }
        }
    }
    return cg_user_spec_member_by_unique_decl(
        receiver_spec, resolved->member);
}

/* Return whether one closed requirement has the structural callable surface
 * selected as a method-value target. ABI classifications may differ and are
 * bridged by the existing adapter, so only language-level parameter/return
 * types and variadic shape participate. */
static bool cg_user_spec_method_matches_callable_target(
    const UserSpecMember *method,
    const UserSpec *target_spec) {
    if (method == NULL || target_spec == NULL ||
        method->kind != USM_KIND_METHOD ||
        target_spec->form != FENG_SPEC_FORM_CALLABLE ||
        method->param_count != target_spec->callable_param_count ||
        !cg_types_equal(method->type,
                        target_spec->callable_return_type)) {
        return false;
    }
    for (size_t index = 0U; index < method->param_count; ++index) {
        if (!cg_types_equal(method->param_types[index],
                            target_spec->callable_param_types[index])) {
            return false;
        }
    }
    return method->param_count == 0U ||
           cg_user_spec_member_param_is_variadic(
               method, method->param_count - 1U) ==
               target_spec->callable_is_variadic;
}

/* Select a method-value slot from Semantic's declaration identity plus the
 * explicit callable target. The target is required by the language and
 * distinguishes different closures of one generic AST member without any
 * runtime lookup. */
static const UserSpecMember *cg_user_spec_member_for_method_value(
    const UserSpec *receiver_spec,
    const FengTypeMember *member,
    const UserSpec *target_spec,
    bool require_static) {
    const UserSpecMember *result = NULL;

    if (receiver_spec == NULL || member == NULL || target_spec == NULL) {
        return NULL;
    }
    for (size_t index = 0U; index < receiver_spec->member_count; ++index) {
        const UserSpecMember *candidate = &receiver_spec->members[index];

        if (!cg_user_spec_member_has_decl(candidate, member) ||
            candidate->is_static != require_static ||
            !cg_user_spec_method_matches_callable_target(
                candidate, target_spec)) {
            continue;
        }
        if (result != NULL) {
            return NULL;
        }
        result = candidate;
    }
    return result;
}

/* Locate the Semantic witness entry represented by one Codegen slot when its
 * AST declaration identity is unique. Logical requirement order is
 * intentionally irrelevant: parent and child declarations may be aliases of
 * the same slot, while different closures of one generic declaration can
 * produce multiple matching entries. The latter is reported through
 * out_ambiguous and resolved from the closed signature by the caller. This is
 * a compiler-time lookup only. */
static const FengSpecWitnessMember *cg_spec_witness_member_for_slot(
    const FengSpecWitness *witness,
    const UserSpecMember *slot,
    bool *out_ambiguous) {
    const FengSpecWitnessMember *result = NULL;

    if (out_ambiguous != NULL) {
        *out_ambiguous = false;
    }
    if (witness == NULL || slot == NULL) {
        return NULL;
    }
    for (size_t index = 0U; index < witness->member_count; ++index) {
        const FengSpecWitnessMember *candidate = &witness->members[index];

        if (!cg_user_spec_member_has_decl(slot, candidate->spec_member)) {
            continue;
        }
        if (result != NULL) {
            if (out_ambiguous != NULL) {
                *out_ambiguous = true;
            }
            return NULL;
        }
        result = candidate;
    }
    return result;
}

/* ------------- Fit registration (Step 4b-γ) ------------- */

/* Build the stable implementation prefix for one user-type fit.  The
 * ordinal is local to the declaring module, concrete target symbol, and fit
 * visibility, so unrelated fits registered by a binary-package consumer do
 * not change the producer's method symbol. */
static char *cg_user_fit_c_prefix(CG *cg,
                                  const FengDecl *decl,
                                  const UserType *target) {
    const FengProgram *owner_program = cg != NULL ? cg->cur_program : NULL;
    char *owner_mangle;
    bool is_public;
    size_t ordinal = 0U;
    Buf prefix;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_FIT ||
        target == NULL || target->c_struct_name == NULL ||
        owner_program == NULL) {
        return NULL;
    }
    owner_mangle = cg_module_mangle(owner_program->module_segments,
                                    owner_program->module_segment_count);
    if (owner_mangle == NULL) {
        return NULL;
    }
    is_public = decl->visibility == FENG_VISIBILITY_PUBLIC;
    for (size_t index = 0U; index < cg->user_fit_count; ++index) {
        const UserFit *registered = &cg->user_fits[index];
        const FengDecl *candidate = registered->decl;
        const FengProgram *candidate_owner = registered->owner_program;

        if (candidate == NULL || candidate->kind != FENG_DECL_FIT ||
            candidate_owner == NULL || registered->target == NULL ||
            registered->target->c_struct_name == NULL ||
            !cg_module_segments_equal(
                candidate_owner->module_segments,
                candidate_owner->module_segment_count,
                owner_program->module_segments,
                owner_program->module_segment_count) ||
            strcmp(registered->target->c_struct_name,
                   target->c_struct_name) != 0 ||
            (candidate->visibility == FENG_VISIBILITY_PUBLIC) != is_public) {
            continue;
        }
        ++ordinal;
    }

    buf_init(&prefix);
    buf_append_fmt(&prefix,
                   "FengFitUser__%s__%s__%s%zu",
                   owner_mangle,
                   target->c_struct_name,
                   is_public ? "m" : "i",
                   ordinal);
    free(owner_mangle);
    return prefix.data;
}

/* Register a `fit T :: S { ... }` shell: resolve the target T to a UserType
 * and assign its stable implementation prefix. Member resolution is
 * deferred to cg_register_user_fit_members so target T's methods (used by
 * cg_resolve_type for parameter / return types) are already populated. */
static bool cg_register_user_fit_shell_for_target(CG *cg,
                                                  const FengDecl *decl,
                                                  const UserType *target,
                                                  const FengTypeParam *type_params,
                                                  size_t type_param_count,
                                                  FengTypeRef *const *type_args,
                                                  size_t type_arg_count) {
    size_t target_index = 0U;
    if (target == NULL) return false;
    if (!cg_user_type_index(cg, target, &target_index)) return false;

    /* Declaration collection already covers the open fit template. A closed
     * generic target additionally needs every fit method surface collected
     * after owner substitution, exactly like a closed generic type instance,
     * before the common member-registration pass resolves those surfaces. */
    if (type_param_count > 0U &&
        target->generic_context_type_param_count == 0U) {
        CGTypeParamScope closed_scope = {0};

        for (size_t member_index = 0U;
             member_index < decl->as.fit_decl.member_count;
             ++member_index) {
            const FengTypeMember *member =
                decl->as.fit_decl.members[member_index];

            if (member->kind == FENG_TYPE_MEMBER_METHOD) {
                const FengCallableSignature *callable =
                    &member->as.callable;

                if (!cg_collect_instantiated_callable_member_instances(
                        cg,
                        callable,
                        type_params,
                        type_param_count,
                        type_args,
                        closed_scope,
                        cg->cur_program)) {
                    return false;
                }
                /* A closed owner must register every dependency required by
                 * an ordinary fit member even when no direct call exists.
                 * Method-generic members close their combined owner/method
                 * domain at the eventual call site. */
                if (callable->type_param_count == 0U &&
                    !cg_collect_closed_reifiable_dep_instances(
                        cg,
                        feng_semantic_lookup_member_reifiable_dep_set(
                            cg->analysis, decl, member),
                        type_params,
                        type_param_count,
                        type_args,
                        closed_scope,
                        cg->cur_program,
                        member->token)) {
                    return false;
                }
            }
        }
        target = &cg->user_types[target_index];
    }
    if (cg->user_fit_count + 1 > cg->user_fit_capacity) {
        size_t cap = cg->user_fit_capacity ? cg->user_fit_capacity * 2 : 4;
        void *p = realloc(cg->user_fits, cap * sizeof *cg->user_fits);
        if (!p) return false;
        cg->user_fits = p;
        cg->user_fit_capacity = cap;
    }
    UserFit *uf = &cg->user_fits[cg->user_fit_count];
    memset(uf, 0, sizeof *uf);
    uf->decl = decl;
    uf->target = target;
    uf->target_index = target_index;
    uf->index = cg->user_fit_count;
    uf->owner_program = cg->cur_program;
    uf->c_prefix = cg_user_fit_c_prefix(cg, decl, target);
    if (uf->c_prefix == NULL) return false;
    uf->spec_count = decl->as.fit_decl.spec_count;
    uf->specs = uf->spec_count ? calloc(uf->spec_count, sizeof *uf->specs) : NULL;
    uf->spec_indices = uf->spec_count ? calloc(uf->spec_count, sizeof *uf->spec_indices) : NULL;
    if (uf->spec_count > 0U && (uf->specs == NULL || uf->spec_indices == NULL)) return false;
    for (size_t spec_index = 0; spec_index < uf->spec_count; ++spec_index) {
        const FengTypeRef *spec_ref = decl->as.fit_decl.specs[spec_index];
        const FengTypeRef *resolved_spec_ref = spec_ref;
        FengTypeRef *substituted = NULL;
        CGTypeParamScope resolve_scope = {0};
        CGType *spec_type = NULL;
        bool ok;

        if (type_param_count > 0U) {
            substituted = cg_type_ref_substitute(spec_ref,
                                                type_params,
                                                type_param_count,
                                                type_args);
            if (substituted == NULL) return false;
            resolved_spec_ref = substituted;
        }

        /* An open generic fit is the compile-time template used to emit the
         * shared body. Its substituted spec still contains the target type
         * parameters, so collect and resolve it in that declared scope. */
        if (target->generic_context_type_param_count > 0U) {
            resolve_scope.first = type_params;
            resolve_scope.first_count = type_param_count;
        }

        ok = cg_collect_generic_instances_from_type_ref(
                 cg, resolved_spec_ref, resolve_scope) &&
             cg_resolve_type_with_open_scope(
                 cg, resolved_spec_ref, &decl->token, &resolve_scope,
                 &spec_type);
        cg_type_ref_free(substituted);
        if (!ok) return false;
        if (spec_type == NULL ||
            (spec_type->kind != CG_TYPE_SPEC && spec_type->kind != CG_TYPE_CALLABLE) ||
            spec_type->user_spec == NULL) {
            cgtype_free(spec_type);
            return cg_fail(cg, decl->token,
                "CE0048", "codegen: fit spec did not resolve to a known user spec");
        }
        if (!cg_user_spec_index(cg, spec_type->user_spec, &uf->spec_indices[spec_index])) {
            cgtype_free(spec_type);
            return false;
        }
        uf->specs[spec_index] = spec_type->user_spec;
        cgtype_free(spec_type);
    }
    cg->user_fit_count++;
    (void)type_arg_count;
    return true;
}

static bool cg_builtin_fit_target_local_type_param(CG *cg,
                                                   const FengDecl *fit_decl,
                                                   FengTypeParam *out_type_param);

static bool cg_fit_target_is_builtin_form(const FengTypeRef *target_ref) {
    if (target_ref == NULL) {
        return false;
    }
    if (target_ref->kind == FENG_TYPE_REF_ARRAY) {
        return true;
    }
    return target_ref->kind == FENG_TYPE_REF_NAMED &&
           target_ref->as.named.segment_count == 1U &&
           target_ref->as.named.type_arg_count == 0U &&
           cg_is_builtin_named_fit_target(target_ref->as.named.segments[0]);
}

static char *cg_builtin_fit_c_prefix(CG *cg, const FengDecl *decl) {
    const FengProgram *owner_program = cg->cur_program;
    char *owner_mangle = NULL;
    Buf target_symbol;
    bool is_public;
    size_t ordinal = 0U;
    Buf b;

    if (decl == NULL || decl->kind != FENG_DECL_FIT || decl->as.fit_decl.target == NULL) {
        return NULL;
    }

    if (owner_program != NULL) {
        owner_mangle = cg_module_mangle(owner_program->module_segments,
                                        owner_program->module_segment_count);
    } else if (cg->module_mangle != NULL) {
        owner_mangle = strdup(cg->module_mangle);
    }
    if (owner_mangle == NULL) {
        return NULL;
    }

    buf_init(&target_symbol);
    if (!cg_append_type_ref_symbol(cg, &target_symbol, decl->as.fit_decl.target) ||
        target_symbol.data == NULL) {
        free(owner_mangle);
        buf_free(&target_symbol);
        return NULL;
    }

    is_public = decl->visibility == FENG_VISIBILITY_PUBLIC;
    /* Use already-registered builtin fits to compute a module-wide stable
     * ordinal. Scanning only the current source file causes cross-file fits in
     * the same module to all mint `m0`, which breaks linker symbol matching. */
    if (owner_program != NULL) {
        for (size_t i = 0U; i < cg->builtin_fit_count; ++i) {
            const BuiltinFit *registered = &cg->builtin_fits[i];
            const FengDecl *candidate = registered->decl;
            const FengProgram *candidate_owner = registered->owner_program;

            if (candidate == NULL || candidate->kind != FENG_DECL_FIT) {
                continue;
            }
            if (candidate_owner == NULL) {
                continue;
            }
            if (!cg_module_segments_equal(candidate_owner->module_segments,
                                          candidate_owner->module_segment_count,
                                          owner_program->module_segments,
                                          owner_program->module_segment_count)) {
                continue;
            }
            if (!cg_fit_target_is_builtin_form(candidate->as.fit_decl.target)) {
                continue;
            }
            if ((candidate->visibility == FENG_VISIBILITY_PUBLIC) != is_public) {
                continue;
            }
            if (!cg_type_ref_equal(candidate->as.fit_decl.target, decl->as.fit_decl.target)) {
                continue;
            }
            ++ordinal;
        }
    }

    buf_init(&b);
    buf_append_fmt(&b,
                   "FengFitBuiltin__%s__%s__%s%zu",
                   owner_mangle,
                   target_symbol.data,
                   is_public ? "m" : "i",
                   ordinal);
    free(owner_mangle);
    buf_free(&target_symbol);
    return b.data;
}

static bool cg_register_builtin_fit_shell(CG *cg,
                                          const FengDecl *decl,
                                          const FengTypeRef *target_ref) {
    BuiltinFit *bf;
    CGType *target_type = NULL;
    FengTypeParam local_type_param;
    CGTypeParamScope open_scope = {0};

    if (decl == NULL || target_ref == NULL) {
        return false;
    }
    if (cg->builtin_fit_count + 1 > cg->builtin_fit_capacity) {
        size_t cap = cg->builtin_fit_capacity ? cg->builtin_fit_capacity * 2 : 4;
        void *p = realloc(cg->builtin_fits, cap * sizeof *cg->builtin_fits);

        if (p == NULL) {
            return false;
        }
        cg->builtin_fits = p;
        cg->builtin_fit_capacity = cap;
    }

    if (cg_builtin_fit_target_local_type_param(cg, decl, &local_type_param)) {
        open_scope.first = &local_type_param;
        open_scope.first_count = 1U;
    }

    if (!cg_resolve_type_with_open_scope(cg, target_ref, &decl->token, &open_scope, &target_type) ||
        target_type == NULL) {
        cgtype_free(target_type);
        return cg_fail(cg, decl->token,
            "CE0049", "codegen: fit target did not resolve to a builtin/array type");
    }

    bf = &cg->builtin_fits[cg->builtin_fit_count];
    memset(bf, 0, sizeof *bf);
    bf->decl = decl;
    bf->target_type = target_type;
    if (open_scope.first_count > 0U) {
        bf->target_type_params = calloc(1, sizeof *bf->target_type_params);
        if (bf->target_type_params == NULL) {
            cgtype_free(target_type);
            memset(bf, 0, sizeof *bf);
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
        bf->target_type_params[0] = local_type_param;
        bf->target_type_param_count = 1U;
    }
    bf->spec_count = decl->as.fit_decl.spec_count;
    bf->specs = bf->spec_count ? calloc(bf->spec_count, sizeof *bf->specs) : NULL;
    if (bf->spec_count > 0U && bf->specs == NULL) {
        free(bf->target_type_params);
        cgtype_free(target_type);
        memset(bf, 0, sizeof *bf);
        return false;
    }
    for (size_t spec_index = 0; spec_index < bf->spec_count; ++spec_index) {
        const FengTypeRef *spec_ref = decl->as.fit_decl.specs[spec_index];
        CGType *spec_type = NULL;

        if (!cg_resolve_type_with_open_scope(cg, spec_ref, &decl->token, &open_scope, &spec_type)) {
            free(bf->specs);
            free(bf->target_type_params);
            cgtype_free(target_type);
            memset(bf, 0, sizeof *bf);
            return false;
        }
        if (spec_type == NULL ||
            (spec_type->kind != CG_TYPE_SPEC && spec_type->kind != CG_TYPE_CALLABLE) ||
            spec_type->user_spec == NULL) {
            cgtype_free(spec_type);
            free(bf->specs);
            free(bf->target_type_params);
            cgtype_free(target_type);
            memset(bf, 0, sizeof *bf);
            return cg_fail(cg, decl->token,
                "CE0048", "codegen: fit spec did not resolve to a known user spec");
        }
        bf->specs[spec_index] = spec_type->user_spec;
        cgtype_free(spec_type);
    }
    bf->owner_program = cg->cur_program;
    bf->c_prefix = cg_builtin_fit_c_prefix(cg, decl);
    if (bf->c_prefix == NULL) {
        free(bf->specs);
        free(bf->target_type_params);
        cgtype_free(target_type);
        memset(bf, 0, sizeof *bf);
        return false;
    }

    cg->builtin_fit_count++;
    return true;
}

static bool cg_is_builtin_named_fit_target(FengSlice name) {
    /* After AST alias normalization (docs/engineering/feng-scalar-alias-optimize.md §6),
     * only canonical width-explicit names reach codegen. */
    static const char *kBuiltinNames[] = {
        "i8", "i16", "i32", "i64",
        "u8", "u16", "u32", "u64",
        "f32", "f64",
        "bool", "string"
    };
    for (size_t i = 0; i < sizeof(kBuiltinNames) / sizeof(kBuiltinNames[0]); ++i) {
        size_t len = strlen(kBuiltinNames[i]);

        if (name.length == len && strncmp(name.data, kBuiltinNames[i], len) == 0) {
            return true;
        }
    }
    return false;
}

static bool cg_builtin_fit_target_local_type_param(CG *cg,
                                                   const FengDecl *fit_decl,
                                                   FengTypeParam *out_type_param) {
    const FengTypeRef *target_ref;
    const FengTypeRef *element_ref;
    const FengSemanticTypeFact *fact;
    FengSlice element_name;
    FengSlice probe_segments[1];
    FengTypeRef probe_ref;

    if (out_type_param == NULL || fit_decl == NULL ||
        fit_decl->kind != FENG_DECL_FIT) {
        return false;
    }
    target_ref = fit_decl->as.fit_decl.target;
    if (target_ref == NULL ||
        target_ref->kind != FENG_TYPE_REF_ARRAY) {
        return false;
    }

    element_ref = target_ref->as.inner;
    if (element_ref == NULL || element_ref->kind != FENG_TYPE_REF_NAMED ||
        element_ref->as.named.segment_count != 1U ||
        element_ref->as.named.type_arg_count != 0U) {
        return false;
    }

    element_name = element_ref->as.named.segments[0];
    fact = feng_semantic_lookup_type_fact(cg->analysis, fit_decl);
    if (fact != NULL &&
        fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF &&
        fact->type_ref == element_ref) {
        memset(out_type_param, 0, sizeof(*out_type_param));
        out_type_param->token = element_ref->token;
        out_type_param->name = element_name;
        out_type_param->constraint = NULL;
        return true;
    }
    if (cg_is_builtin_named_fit_target(element_name) ||
        cg_find_user_type(cg, element_name.data, element_name.length) != NULL ||
        cg_find_user_spec(cg, element_name.data, element_name.length) != NULL ||
        cg_find_enum_decl_by_ref(cg, element_ref) != NULL) {
        return false;
    }

    memset(&probe_ref, 0, sizeof(probe_ref));
    probe_segments[0] = element_name;
    probe_ref.kind = FENG_TYPE_REF_NAMED;
    probe_ref.as.named.segments = probe_segments;
    probe_ref.as.named.segment_count = 1U;
    if (cg_find_generic_type_decl(cg, &probe_ref) != NULL ||
        cg_find_generic_spec_decl(cg, &probe_ref) != NULL) {
        return false;
    }

    memset(out_type_param, 0, sizeof(*out_type_param));
    out_type_param->token = element_ref->token;
    out_type_param->name = element_name;
    out_type_param->constraint = NULL;
    return true;
}

static bool cg_register_user_fit_shell(CG *cg, const FengDecl *decl) {
    if (!decl->as.fit_decl.has_body) {
        /* `fit T :: S, U;` (head-only) carries no methods to emit; semantic
         * still consumes it for satisfaction relations. Codegen registers
         * an empty entry so witness lookup by decl returns a stable handle. */
    }
    const FengTypeRef *target_ref = decl->as.fit_decl.target;
    if (!target_ref) {
        return cg_fail(cg, decl->token,
            "CE0050", "codegen: fit target is missing");
    }

    if (target_ref->kind == FENG_TYPE_REF_ARRAY) {
        return cg_register_builtin_fit_shell(cg, decl, target_ref);
    }

    if (target_ref->kind != FENG_TYPE_REF_NAMED) {
        return cg_fail(cg, decl->token,
            "CE0051", "codegen: only named or array fit targets are supported");
    }
    if (target_ref->as.named.segment_count == 1U &&
        cg_is_builtin_named_fit_target(target_ref->as.named.segments[0])) {
        return cg_register_builtin_fit_shell(cg, decl, target_ref);
    }
    if (target_ref->as.named.type_arg_count > 0U) {
        const GenericTypeDecl *generic_target = cg_find_generic_type_decl(cg, target_ref);
        const FengDecl *target_decl = generic_target != NULL ? generic_target->decl : NULL;
        if (target_decl == NULL || target_decl->kind != FENG_DECL_TYPE) {
            return cg_fail(cg, decl->token,
                "CE0052", "codegen: fit target did not resolve to a known user type");
        }
        for (size_t i = 0; i < cg->user_type_count; ++i) {
            const UserType *candidate = &cg->user_types[i];

            if (!candidate->is_generic_instance ||
                candidate->generic_origin_decl != target_decl) {
                continue;
            }
            if (!cg_register_user_fit_shell_for_target(
                    cg,
                    decl,
                    candidate,
                    target_decl->as.type_decl.type_params,
                    target_decl->as.type_decl.type_param_count,
                    candidate->generic_type_args,
                    candidate->generic_type_arg_count)) {
                return false;
            }
        }
        return true;
    }

    const FengSlice *seg =
        &target_ref->as.named.segments[target_ref->as.named.segment_count - 1U];
    const UserType *target = target_ref->as.named.segment_count == 1U
        ? cg_find_user_type(cg, seg->data, seg->length)
        : cg_find_user_type_by_ref(cg, target_ref);
    if (!target) {
        CGType *resolved_target = NULL;

        if (cg_resolve_type(cg, target_ref, &decl->token, &resolved_target) &&
            resolved_target != NULL &&
            (resolved_target->kind != CG_TYPE_OBJECT || resolved_target->user == NULL)) {
            cgtype_free(resolved_target);
            return cg_register_builtin_fit_shell(cg, decl, target_ref);
        }
        cgtype_free(resolved_target);
        return cg_fail(cg, decl->token,
            "CE0053", "codegen: fit target type '%.*s' is not a known user type",
            (int)seg->length, seg->data);
    }
    return cg_register_user_fit_shell_for_target(cg, decl, target, NULL, 0U, NULL, 0U);
}

static bool cg_resolve_type_for_user_fit_member(CG *cg,
                                                const UserFit *uf,
                                                const FengCallableSignature *sig,
                                                const FengTypeRef *ref,
                                                const FengToken *fallback,
                                                CGType **out_type) {
    const FengDecl *target_decl = NULL;
    const FengTypeRef *effective_ref = ref;
    FengTypeRef *substituted = NULL;
    CGTypeParamScope open_scope = {0};
    bool ok;

    if (uf == NULL || uf->target == NULL || uf->decl == NULL || sig == NULL) {
        return false;
    }
    if (uf->target->is_generic_instance) {
        target_decl = uf->target->generic_origin_decl;
        if (target_decl != NULL && target_decl->kind == FENG_DECL_TYPE &&
            target_decl->as.type_decl.type_param_count > 0U) {
            substituted = cg_type_ref_substitute(
                ref,
                target_decl->as.type_decl.type_params,
                target_decl->as.type_decl.type_param_count,
                uf->target->generic_type_args);
            if (substituted == NULL) {
                return false;
            }
            effective_ref = substituted;
            /* Keep the declared owner domain before the method domain even
             * for a closed instance. Shared fit-method ABIs use the same
             * owner-T / method-U descriptor indices as ordinary methods. */
            open_scope.first = target_decl->as.type_decl.type_params;
            open_scope.first_count =
                target_decl->as.type_decl.type_param_count;
        }
    }
    open_scope.second = sig->type_params;
    open_scope.second_count = sig->type_param_count;

    if (open_scope.first_count > 0U || open_scope.second_count > 0U) {
        ok = cg_resolve_type_with_open_scope(
            cg, effective_ref, fallback, &open_scope, out_type);
    } else {
        ok = cg_resolve_type(cg, effective_ref, fallback, out_type);
    }
    cg_type_ref_free(substituted);
    return ok;
}

/* Resolve a user-fit callable return through the fit target and method
 * substitution context, including Semantic's inferred callable fact. */
static bool cg_resolve_user_fit_return_type(
    CG *cg,
    const UserFit *fit,
    const FengCallableSignature *callable,
    const FengToken *fallback,
    CGType **out_type) {
    const FengSemanticTypeFact *fact = NULL;
    bool handled = false;
    FengToken blame;

    if (out_type == NULL || callable == NULL) {
        return false;
    }
    *out_type = NULL;
    blame = fallback != NULL ? *fallback : callable->token;
    if (callable->return_type != NULL) {
        return cg_resolve_type_for_user_fit_member(
            cg, fit, callable, callable->return_type, fallback, out_type);
    }
    if (cg != NULL && cg->analysis != NULL) {
        fact = feng_semantic_lookup_type_fact(cg->analysis, callable);
    }
    if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
        return cg_resolve_type_for_user_fit_member(
            cg, fit, callable, fact->type_ref, fallback, out_type);
    }
    if (!cg_try_resolve_non_reference_type_fact(
            cg, fact, blame, out_type, &handled)) {
        return false;
    }
    if (handled) {
        return true;
    }

    *out_type = cgtype_new(CG_TYPE_VOID);
    return *out_type != NULL;
}

/* Resolve a builtin-fit callable return while preserving the fit-target and
 * method type-parameter scope already used for explicit signatures. */
static bool cg_resolve_builtin_fit_return_type(
    CG *cg,
    const FengCallableSignature *callable,
    const CGTypeParamScope *open_scope,
    const FengToken *fallback,
    CGType **out_type) {
    const FengSemanticTypeFact *fact = NULL;
    bool handled = false;
    FengToken blame;

    if (out_type == NULL || callable == NULL) {
        return false;
    }
    *out_type = NULL;
    blame = fallback != NULL ? *fallback : callable->token;
    if (callable->return_type != NULL) {
        return cg_resolve_type_with_open_scope(
            cg, callable->return_type, fallback, open_scope, out_type);
    }
    if (cg != NULL && cg->analysis != NULL) {
        fact = feng_semantic_lookup_type_fact(cg->analysis, callable);
    }
    if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
        return cg_resolve_type_with_open_scope(
            cg, fact->type_ref, fallback, open_scope, out_type);
    }
    if (!cg_try_resolve_non_reference_type_fact(
            cg, fact, blame, out_type, &handled)) {
        return false;
    }
    if (handled) {
        return true;
    }

    *out_type = cgtype_new(CG_TYPE_VOID);
    return *out_type != NULL;
}

/* Return whether a completed fit-method C name is already used in methods. */
static bool cg_fit_method_c_name_is_used(const UserMethod *methods,
                                         size_t method_count,
                                         const char *c_name) {
    if (methods == NULL || c_name == NULL) {
        return false;
    }
    for (size_t index = 0U; index < method_count; ++index) {
        if (methods[index].c_name != NULL &&
            strcmp(methods[index].c_name, c_name) == 0) {
            return true;
        }
    }
    return false;
}

/* Preserve every historical non-conflicting fit symbol. When the old complete
 * symbol loses the instance/static domain and therefore collides, append that
 * domain only to the later method and keep checking for a deterministic unique
 * compiler symbol. The input name is consumed on both success and failure. */
static char *cg_disambiguate_fit_method_c_name(UserMethod *methods,
                                               size_t method_count,
                                               char *c_name,
                                               bool is_static) {
    const char *domain = is_static ? "static" : "instance";
    size_t discriminator = 1U;

    if (c_name == NULL ||
        !cg_fit_method_c_name_is_used(methods, method_count, c_name)) {
        return c_name;
    }
    for (;;) {
        Buf candidate;

        buf_init(&candidate);
        if (discriminator == 1U) {
            buf_append_fmt(&candidate, "%s__%s", c_name, domain);
        } else {
            buf_append_fmt(&candidate, "%s__%s_%zu",
                           c_name, domain, discriminator);
        }
        if (candidate.data == NULL) {
            free(c_name);
            return NULL;
        }
        if (!cg_fit_method_c_name_is_used(
                methods, method_count, candidate.data)) {
            free(c_name);
            return candidate.data;
        }
        buf_free(&candidate);
        discriminator++;
    }
}

/* Populate the fit's UserMethod array. Field members are not legal in a fit
 * body (semantic enforces this; we double-check). Each method's base c_name
 * is `<fit_prefix>__<member>` so two fits for the same T cannot collide,
 * and so a fit method does not shadow a same-named method on T itself. */
static bool cg_register_user_fit_members(CG *cg, UserFit *uf) {
    const FengDecl *decl = uf->decl;
    size_t mc = 0;
    for (size_t i = 0; i < decl->as.fit_decl.member_count; i++) {
        if (decl->as.fit_decl.members[i]->kind == FENG_TYPE_MEMBER_METHOD) mc++;
    }
    uf->methods = mc ? calloc(mc, sizeof *uf->methods) : NULL;
    if (mc && !uf->methods) return false;
    size_t mi = 0;
    for (size_t i = 0; i < decl->as.fit_decl.member_count; i++) {
        const FengTypeMember *m = decl->as.fit_decl.members[i];
        if (m->kind != FENG_TYPE_MEMBER_METHOD) {
            return cg_fail(cg, m->token,
                "CE0054", "codegen: only methods are supported in fit bodies");
        }
        UserMethod *um = &uf->methods[mi++];
        const FengCallableSignature *sig = &m->as.callable;
        um->member = m;
        um->feng_name = strndup(sig->name.data, sig->name.length);
        char *msan = cg_sanitize(sig->name.data, sig->name.length);
        if (!um->feng_name || !msan) { free(msan); return false; }
        Buf cb; buf_init(&cb);
        buf_append_fmt(&cb, "%s__%s", uf->c_prefix, msan);
        um->c_name = cb.data;
        free(msan);
        um->param_count = sig->param_count;
        um->is_variadic = sig->param_count > 0U &&
                          sig->params[sig->param_count - 1U].is_variadic;
        um->param_types = sig->param_count
            ? calloc(sig->param_count, sizeof(CGType*)) : NULL;
        um->param_names = sig->param_count
            ? calloc(sig->param_count, sizeof(char*)) : NULL;
        for (size_t pi = 0; pi < sig->param_count; pi++) {
            if (!cg_resolve_type_for_user_fit_member(cg,
                                                     uf,
                                                     sig,
                                                     sig->params[pi].type,
                                                     &sig->params[pi].token,
                                                     &um->param_types[pi])) return false;
            um->param_names[pi] = strndup(sig->params[pi].name.data,
                                          sig->params[pi].name.length);
        }
        if (!cg_resolve_user_fit_return_type(cg, uf, sig, &sig->token,
                                             &um->return_type)) return false;
        um->c_name = cg_append_param_suffix(um->c_name,
                                            um->param_types, um->param_count,
                                            um->is_variadic,
                                            sig->type_param_count > 0U);
        um->c_name = cg_disambiguate_fit_method_c_name(
            uf->methods, mi - 1U, um->c_name, m->is_static);
        if (!um->c_name) return false;
    }
    uf->method_count = mi;
    return true;
}

static bool cg_register_builtin_fit_members(CG *cg, BuiltinFit *bf) {
    const FengDecl *decl = bf->decl;
    size_t mc = 0;

    for (size_t i = 0; i < decl->as.fit_decl.member_count; i++) {
        if (decl->as.fit_decl.members[i]->kind == FENG_TYPE_MEMBER_METHOD) mc++;
    }
    bf->methods = mc ? calloc(mc, sizeof *bf->methods) : NULL;
    if (mc && !bf->methods) return false;

    size_t mi = 0;
    for (size_t i = 0; i < decl->as.fit_decl.member_count; i++) {
        const FengTypeMember *m = decl->as.fit_decl.members[i];

        if (m->kind != FENG_TYPE_MEMBER_METHOD) {
            return cg_fail(cg, m->token,
                "CE0054", "codegen: only methods are supported in fit bodies");
        }
        UserMethod *um = &bf->methods[mi++];
        const FengCallableSignature *sig = &m->as.callable;

        /* Build scope with both fit-target and method-level type params. */
        CGTypeParamScope open_scope = {
            .first = bf->target_type_params,
            .first_count = bf->target_type_param_count,
            .second = sig->type_params,
            .second_count = sig->type_param_count,
        };

        um->member = m;
        um->feng_name = strndup(sig->name.data, sig->name.length);
        char *msan = cg_sanitize(sig->name.data, sig->name.length);
        if (!um->feng_name || !msan) {
            free(msan);
            return false;
        }
        Buf cb;
        buf_init(&cb);
        buf_append_fmt(&cb, "%s__%s", bf->c_prefix, msan);
        um->c_name = cb.data;
        free(msan);
        um->param_count = sig->param_count;
        um->is_variadic = sig->param_count > 0U &&
                          sig->params[sig->param_count - 1U].is_variadic;
        um->param_types = sig->param_count ? calloc(sig->param_count, sizeof(CGType *)) : NULL;
        um->param_names = sig->param_count ? calloc(sig->param_count, sizeof(char *)) : NULL;
        for (size_t pi = 0; pi < sig->param_count; pi++) {
            if (!cg_resolve_type_with_open_scope(cg,
                                                sig->params[pi].type,
                                                &sig->params[pi].token,
                                                &open_scope,
                                                &um->param_types[pi])) {
                return false;
            }
            um->param_names[pi] = strndup(sig->params[pi].name.data,
                                          sig->params[pi].name.length);
        }
        if (!cg_resolve_builtin_fit_return_type(cg,
                                                sig,
                                                &open_scope,
                                                &m->token,
                                                &um->return_type)) {
            return false;
        }
        um->c_name = cg_append_param_suffix(um->c_name,
                                            um->param_types,
                                            um->param_count,
                                            um->is_variadic,
                                            false);
        um->c_name = cg_disambiguate_fit_method_c_name(
            bf->methods, mi - 1U, um->c_name, m->is_static);
        if (um->c_name == NULL) {
            return false;
        }
    }
    bf->method_count = mi;
    return true;
}

static void cg_emit_callable_abi_function_pointer_typedef(Buf *b, const UserSpec *s) {
    buf_append_cstr(b, "typedef ");
    cg_emit_c_abi_surface_type(b, s->callable_return_type);
    buf_append_fmt(b, " (*%s)(", s->c_abi_fn_ptr_typedef_name);
    if (s->callable_param_count == 0U) {
        buf_append_cstr(b, "void");
    } else {
        for (size_t i = 0; i < s->callable_param_count; ++i) {
            if (i != 0U) {
                buf_append_cstr(b, ", ");
            }
            cg_emit_c_abi_surface_type(b, s->callable_param_types[i]);
        }
    }
    buf_append_cstr(b, ");\n");
}

static void cg_append_union_payload_field_name(Buf *b, size_t member_index) {
    buf_append_fmt(b, "m%zu", member_index);
}

static bool cg_append_union_member_slot_descriptor(CG *cg,
                                                   Buf *b,
                                                   const UserSpec *s,
                                                   size_t member_index,
                                                   FengToken blame) {
    const CGType *member_type;
    CGValueKind value_kind;

    if (s == NULL || b == NULL || member_index >= s->union_member_count) {
        return false;
    }
    member_type = s->union_member_types[member_index];
    value_kind = cgtype_value_kind(member_type);
    if (value_kind == CG_VK_TRIVIAL) {
        buf_append_cstr(b,
                        "(FengManagedSlotDescriptor){ .offset = 0, "
                        ".kind = FENG_SLOT_NONE, .nested = NULL }");
        return true;
    }
    buf_append_fmt(b,
                   "(FengManagedSlotDescriptor){ .offset = offsetof(struct %s, payload.",
                   s->c_value_struct_name);
    cg_append_union_payload_field_name(b, member_index);
    if (value_kind == CG_VK_MANAGED_POINTER) {
        buf_append_cstr(b, "), .kind = FENG_SLOT_POINTER, .nested = NULL }");
        return true;
    }
    if (value_kind == CG_VK_AGGREGATE) {
        char *aggregate_desc = cg_aggregate_descriptor_expr_dup(cg,
                                                                member_type,
                                                                blame);
        if (aggregate_desc == NULL) {
            return cg_fail(cg, blame,
                           "CE0055", "codegen: union-form aggregate member is missing a descriptor");
        }
        buf_append_fmt(b,
                       "), .kind = FENG_SLOT_NESTED_AGGREGATE, .nested = %s }",
                       aggregate_desc);
        free(aggregate_desc);
        return true;
    }
    return false;
}

static void cg_emit_witness_struct_body(CG *cg, const UserSpec *s, Buf *out);

/* Generic object/intersection spec instances share one fixed two-word value
 * and witness C representation per declaration origin. Instance descriptors
 * and witness constants remain distinct; only the nominal C carrier is
 * canonical so a binary-distributed shared body can accept every closure. */
static bool cg_user_spec_uses_canonical_generic_object_abi(
    const UserSpec *spec) {
    return spec != NULL && spec->is_generic_instance &&
           spec->generic_origin_decl != NULL &&
           spec->generic_origin_decl->kind == FENG_DECL_SPEC &&
           spec->generic_origin_decl->as.spec_decl.type_param_count > 0U &&
           (spec->form == FENG_SPEC_FORM_OBJECT ||
            spec->form == FENG_SPEC_FORM_INTERSECTION);
}

/* Return whether this instance owns emission of its origin's shared C tags. */
static bool cg_user_spec_emits_canonical_generic_object_abi(
    const CG *cg,
    const UserSpec *spec) {
    if (!cg_user_spec_uses_canonical_generic_object_abi(spec)) {
        return true;
    }
    for (size_t index = 0U; index < cg->user_spec_count; ++index) {
        const UserSpec *candidate = &cg->user_specs[index];

        if (candidate->generic_origin_decl == spec->generic_origin_decl &&
            cg_user_spec_uses_canonical_generic_object_abi(candidate)) {
            return candidate == spec;
        }
    }
    return false;
}

/* Emit every named C tag owned by one registered spec. This pass runs for all
 * specs before any witness body or callable ABI function-pointer typedef is
 * emitted, so a spec type first mentioned inside a function parameter list
 * resolves to the file-scope tag instead of creating a prototype-scope tag.
 * Repeated declarations would be legal C, but keeping tags in this dedicated
 * pass makes declaration dependencies independent of spec registration order. */
static void cg_emit_user_spec_tag_forwards(CG *cg, const UserSpec *s) {
    if (s->c_value_struct_name != NULL) {
        buf_append_fmt(&cg->headers, "struct %s;\n", s->c_value_struct_name);
    }
    if (s->c_closure_struct_name != NULL) {
        buf_append_fmt(&cg->headers, "struct %s;\n", s->c_closure_struct_name);
    }
    if (s->c_witness_struct_name != NULL) {
        buf_append_fmt(&cg->headers, "struct %s;\n", s->c_witness_struct_name);
    }
}

/* Emit the witness-struct body and the remaining declarations/definitions for
 * one spec. All spec-owned C tags have already been declared at file scope by
 * cg_emit_user_spec_tag_forwards. The witness body is emitted here (not
 * deferred to cg_emit_user_spec_definition) so it precedes witness-instance
 * tentative definitions in the headers buffer. */
static void cg_emit_user_spec_forward(CG *cg, const UserSpec *s) {
    if (s->form == FENG_SPEC_FORM_CALLABLE) {
        cg_emit_callable_abi_function_pointer_typedef(&cg->headers, s);
        cg_emit_witness_struct_body(cg, s, &cg->headers);
        /* Forward-declare the closure type descriptor so that generic
         * type instances referencing it (e.g. List<WakerFn>) can compile
         * even though the full definition is emitted later in the spec
         * definition pass. */
        if (s->c_closure_desc_name != NULL) {
            buf_append_fmt(&cg->headers,
                "static const FengCallableTypeDescriptor %s__record;\n"
                "#define %s (%s__record.base)\n",
                s->c_closure_desc_name,
                s->c_closure_desc_name,
                s->c_closure_desc_name);
        }
        return;
    }
    if (s->form == FENG_SPEC_FORM_UNION) {
        /* Union spec struct body is emitted by cg_emit_value_and_union_struct_bodies_sorted
         * (Pass 3.5a) which topologically sorts value types and union specs together.
         * Its tag was emitted by cg_emit_user_spec_tag_forwards; here we emit
         * only the witness body and descriptor declaration. An open generic
         * union is an overlay used by shared bodies; its concrete aggregate
         * descriptor is supplied by a reified dependency slot, so declaring
         * a layout-authoritative static descriptor here would be incorrect. */
        cg_emit_witness_struct_body(cg, s, &cg->headers);
        if (s->generic_context_type_param_count > 0U) {
            /* Other open generic overlays may retain this declaration as a
             * compile-time dependency identity. Keep it translation-unit
             * local and zero-only: no shared body may use it as concrete
             * layout authority. Closed wrappers replace it through the
             * existing reified dependency slot. */
            buf_append_fmt(&cg->headers,
                           "static const FengAggregateDescriptor %s;\n",
                           s->c_aggregate_desc_name);
        } else {
            bool ext_visible =
                cg_user_spec_descriptor_is_externally_visible(cg, s);
            buf_append_fmt(&cg->headers,
                ext_visible ? "extern const FengAggregateDescriptor %s;\n"
                            : "static const FengAggregateDescriptor %s;\n",
                s->c_aggregate_desc_name);
        }
        return;
    }
    /* OBJECT and INTERSECTION forms share the same value layout
     * ({ void *subject; const Witness *witness; }) and the same aggregate
     * descriptor shape, so they share the forward-emission path. The witness
     * struct body is emitted here (not just forward-declared) so it precedes
     * any witness-instance tentative definitions that appear later in
     * headers during type-descriptor generation. */
    if (cg_user_spec_emits_canonical_generic_object_abi(cg, s)) {
        cg_emit_witness_struct_body(cg, s, &cg->headers);
        buf_append_fmt(&cg->headers,
            "struct %s { void *subject; const struct %s *witness; };\n",
            s->c_value_struct_name, s->c_witness_struct_name);
    }
    bool ext_visible = cg_user_spec_descriptor_is_externally_visible(cg, s);
    buf_append_fmt(&cg->headers,
        ext_visible ? "extern const FengAggregateDescriptor %s;\n"
                    : "static const FengAggregateDescriptor %s;\n",
        s->c_aggregate_desc_name);
}

/* Emit the witness struct body to `out`. Method members get a single
 * function-pointer slot. Field members get either a value getter or a stable
 * storage borrow plus, for `var`, a setter. The declaration order of slots
 * matches the spec source so codegen iteration and debugger inspection stay
 * aligned. If a spec has no slots at all an empty struct would be invalid C —
 * emit a `_padding` byte.
 *
 * Called from cg_emit_user_spec_forward so the complete struct appears
 * in the headers buffer before any witness-instance tentative definitions
 * (which reference the struct type). */
static void cg_emit_witness_struct_body(CG *cg, const UserSpec *s, Buf *out) {
    if (s->form == FENG_SPEC_FORM_CALLABLE) {
        buf_append_fmt(out, "struct %s {\n    void (*invoke)(const void *_callee",
                       s->c_witness_struct_name);
        for (size_t i = 0; i < s->callable_param_count; ++i) {
            buf_append_cstr(out, ", const void *");
        }
        buf_append_cstr(out, ", void *_out);\n};\n\n");
        return;
    }
    buf_append_fmt(out, "struct %s {\n", s->c_witness_struct_name);
    size_t emitted = 0;
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind == USM_KIND_METHOD) {
            buf_append_cstr(out, "    ");
            cg_emit_callable_abi_return_type(out,
                                             sm->type,
                                             sm->value_abi_kind);
            if (sm->is_static) {
                buf_append_fmt(out, " (*%s)(", sm->c_field_name);
            } else {
                buf_append_fmt(out, " (*%s)(void *_subject", sm->c_field_name);
            }
            for (size_t pi = 0; pi < sm->param_count; pi++) {
                if (!sm->is_static || pi > 0U) {
                    buf_append_cstr(out, ", ");
                }
                cg_emit_callable_abi_param_type(out,
                                                sm->param_types[pi],
                                                sm->param_abi_kinds[pi]);
            }
            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                if (!sm->is_static || sm->param_count > 0U) {
                    buf_append_cstr(out, ", ");
                }
                buf_append_cstr(out, "void *_out");
            }
            buf_append_cstr(out, ");\n");
            emitted++;
        } else if (sm->kind == USM_KIND_FIELD) {
            if (cg_spec_field_uses_storage_borrow(sm)) {
                buf_append_fmt(out,
                               "    void *(*borrow_%s)(void *_subject);\n",
                               sm->c_field_name);
                emitted++;
            } else {
                buf_append_cstr(out, "    ");
                cg_emit_callable_abi_return_type(out,
                                                 sm->type,
                                                 sm->value_abi_kind);
                if (sm->is_static) {
                    if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                        buf_append_fmt(out, " (*get_%s)(void *_out);\n",
                                       sm->c_field_name);
                    } else {
                        buf_append_fmt(out, " (*get_%s)(void);\n",
                                       sm->c_field_name);
                    }
                } else {
                    buf_append_fmt(out, " (*get_%s)(void *_subject",
                                   sm->c_field_name);
                    if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                        buf_append_cstr(out, ", void *_out");
                    }
                    buf_append_cstr(out, ");\n");
                }
                emitted++;
            }
            if (sm->is_var) {
                buf_append_cstr(out, "    void (*set_");
                buf_append_cstr(out, sm->c_field_name);
                if (sm->is_static) {
                    buf_append_cstr(out, ")(");
                } else {
                    buf_append_cstr(out, ")(void *_subject, ");
                }
                cg_emit_callable_abi_param_type(out,
                                                sm->type,
                                                sm->value_abi_kind);
                buf_append_cstr(out, " value);\n");
                emitted++;
            }
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        if (parent_spec == NULL) {
            (void)cg_fail(cg, s->decl->token,
                          "CE0046", "codegen: direct parent spec is not registered");
            continue;
        }
        buf_append_fmt(out, "    const struct %s *",
                       parent_spec->c_witness_struct_name);
        cg_append_spec_parent_field_name(out, parent_spec);
        buf_append_cstr(out, ";\n");
        emitted++;
    }
    if (emitted == 0) {
        buf_append_cstr(out, "    char _padding;\n");
    }
    buf_append_cstr(out, "};\n\n");
}

/* Emit a closed default value through one stable spec-member return ABI.
 * Open generic spec definitions never emit default witnesses; every type
 * reaching this helper therefore has an exact closed representation. */
static bool cg_emit_spec_default_abi_result(CG *cg,
                                            Buf *out,
                                            const CGType *type,
                                            CGCallableABIKind abi_kind,
                                            FengToken blame) {
    char *default_expr = NULL;

    if (type == NULL || type->kind == CG_TYPE_VOID) {
        buf_append_cstr(out, "}\n");
        return true;
    }
    if (cgtype_is_aggregate(type)) {
        char *result_ctype = cg_ctype_dup(type);
        Buf init_call;

        buf_init(&init_call);
        if (result_ctype == NULL ||
            !cg_append_aggregate_default_init_call(&init_call,
                                                   type,
                                                   "_default_ret")) {
            free(result_ctype);
            buf_free(&init_call);
            return false;
        }
        buf_append_fmt(out, "    %s _default_ret;\n", result_ctype);
        buf_append_fmt(out, "    %s;\n", init_call.data);
        if (abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(out,
                "    memcpy(_out, &_default_ret, sizeof _default_ret);\n}\n");
        } else {
            buf_append_cstr(out, "    return _default_ret;\n}\n");
        }
        free(result_ctype);
        buf_free(&init_call);
        return true;
    }
    if (!cg_default_value_expr(cg, type, &blame, &default_expr)) {
        free(default_expr);
        return false;
    }
    if (abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "    ");
        cg_emit_c_type(out, type);
        buf_append_fmt(out,
                       " _default_ret = %s;\n"
                       "    memcpy(_out, &_default_ret, sizeof _default_ret);\n}\n",
                       default_expr);
    } else if (abi_kind == CG_CALLABLE_ABI_ERASED_POINTER) {
        buf_append_fmt(out, "    return (void *)(%s);\n}\n", default_expr);
    } else {
        buf_append_fmt(out, "    return %s;\n}\n", default_expr);
    }
    free(default_expr);
    return true;
}

/* Emit one default-witness field read-or-borrow/setter pair through the
 * field's stable generic-spec ABI. */
static bool cg_emit_default_spec_field_thunks(CG *cg,
                                               Buf *out,
                                               const UserSpec *spec,
                                               const UserSpecMember *member) {
    if (cg_spec_field_uses_storage_borrow(member)) {
        buf_append_fmt(out,
            "static void *%s__borrow_%s(void *_subject) {\n"
            "    return &((struct %s *)_subject)->%s;\n"
            "}\n",
            spec->c_default_witness_name,
            member->c_field_name,
            spec->c_default_subject_struct_name,
            member->c_field_name);
    } else {
        buf_append_cstr(out, "static ");
        cg_emit_callable_abi_return_type(out,
                                         member->type,
                                         member->value_abi_kind);
        buf_append_fmt(out, " %s__get_%s(",
                       spec->c_default_witness_name,
                       member->c_field_name);
        if (!member->is_static) {
            buf_append_cstr(out, "void *_subject");
        }
        if (member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            if (!member->is_static) buf_append_cstr(out, ", ");
            buf_append_cstr(out, "void *_out");
        } else if (member->is_static) {
            buf_append_cstr(out, "void");
        }
        buf_append_cstr(out, ") {\n");
        if (member->is_static) {
            if (!cg_emit_spec_default_abi_result(cg,
                                                 out,
                                                 member->type,
                                                 member->value_abi_kind,
                                                 spec->decl->token)) {
                return false;
            }
        } else if (member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_fmt(out,
                "    memcpy(_out, &((struct %s *)_subject)->%s, "
                "sizeof ((struct %s *)_subject)->%s);\n}\n",
                spec->c_default_subject_struct_name,
                member->c_field_name,
                spec->c_default_subject_struct_name,
                member->c_field_name);
        } else {
            if (member->value_abi_kind == CG_CALLABLE_ABI_ERASED_POINTER) {
                buf_append_cstr(out, "    return (void *)");
            } else {
                buf_append_cstr(out, "    return ");
            }
            buf_append_fmt(out,
                "((struct %s *)_subject)->%s;\n}\n",
                spec->c_default_subject_struct_name,
                member->c_field_name);
        }
    }
    if (!member->is_var) return true;

    buf_append_fmt(out, "static void %s__set_%s(",
                   spec->c_default_witness_name,
                   member->c_field_name);
    if (!member->is_static) {
        buf_append_cstr(out, "void *_subject, ");
    }
    cg_emit_callable_abi_param_type(out,
                                    member->type,
                                    member->value_abi_kind);
    buf_append_cstr(out, " value) {\n");
    if (member->is_static) {
        buf_append_cstr(out, "    (void)value;\n}\n");
        return true;
    }
    if (cgtype_is_managed(member->type)) {
        buf_append_fmt(out,
            "    feng_assign((void **)&((struct %s *)_subject)->%s, ",
            spec->c_default_subject_struct_name,
            member->c_field_name);
        cg_append_callable_abi_argument_value(out,
                                              member->type,
                                              member->value_abi_kind,
                                              "value");
        buf_append_cstr(out, ");\n}\n");
    } else if (cgtype_is_aggregate(member->type)) {
        const char *descriptor = cg_aggregate_desc_name(member->type);

        if (descriptor == NULL) return false;
        buf_append_fmt(out,
            "    feng_aggregate_assign(&((struct %s *)_subject)->%s, ",
            spec->c_default_subject_struct_name,
            member->c_field_name);
        if (member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(out, "value");
        } else {
            buf_append_cstr(out, "&value");
        }
        buf_append_fmt(out, ", &%s);\n}\n", descriptor);
    } else {
        buf_append_fmt(out,
            "    ((struct %s *)_subject)->%s = ",
            spec->c_default_subject_struct_name,
            member->c_field_name);
        cg_append_callable_abi_argument_value(out,
                                              member->type,
                                              member->value_abi_kind,
                                              "value");
        buf_append_cstr(out, ";\n}\n");
    }
    return true;
}

/* Emit one default-witness method that ignores its inputs and returns the
 * source type's default value through the stable generic-spec ABI. */
static bool cg_emit_default_spec_method_thunk(CG *cg,
                                               Buf *out,
                                               const UserSpec *spec,
                                               const UserSpecMember *member) {
    buf_append_cstr(out, "static ");
    cg_emit_callable_abi_return_type(out,
                                     member->type,
                                     member->value_abi_kind);
    buf_append_fmt(out, " %s__%s(",
                   spec->c_default_witness_name,
                   member->c_field_name);
    if (!member->is_static) {
        buf_append_cstr(out, "void *_subject");
    }
    for (size_t index = 0U; index < member->param_count; ++index) {
        if (!member->is_static || index > 0U) buf_append_cstr(out, ", ");
        cg_emit_callable_abi_param_type(out,
                                        member->param_types[index],
                                        member->param_abi_kinds[index]);
        buf_append_fmt(out, " _p%zu", index);
    }
    if (member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        if (!member->is_static || member->param_count > 0U) {
            buf_append_cstr(out, ", ");
        }
        buf_append_cstr(out, "void *_out");
    } else if (member->is_static && member->param_count == 0U) {
        buf_append_cstr(out, "void");
    }
    buf_append_cstr(out, ") {\n");
    if (!member->is_static) buf_append_cstr(out, "    (void)_subject;\n");
    for (size_t index = 0U; index < member->param_count; ++index) {
        buf_append_fmt(out, "    (void)_p%zu;\n", index);
    }
    return cg_emit_spec_default_abi_result(cg,
                                           out,
                                           member->type,
                                           member->value_abi_kind,
                                           spec->decl->token);
}

/* Compare the exact default-witness identity of two registered spec views.
 * Generic object specs share one canonical witness struct ABI across closed
 * instances, so the struct name alone is intentionally insufficient here. */
static bool cg_spec_default_witness_identity_equal(const UserSpec *left,
                                                   const UserSpec *right) {
    if (left == right) {
        return true;
    }
    return left != NULL && right != NULL &&
           left->c_default_witness_name != NULL &&
           right->c_default_witness_name != NULL &&
           strcmp(left->c_default_witness_name,
                  right->c_default_witness_name) == 0;
}

/* Return whether two semantically compatible method slots use the same
 * lowered function-pointer ABI. A closed child requirement may be direct
 * while its generic parent slot remains address-form. */
static bool cg_spec_method_slot_abi_equal(
    const UserSpecMember *left,
    const UserSpecMember *right) {
    if (left == NULL || right == NULL || left->kind != USM_KIND_METHOD ||
        right->kind != USM_KIND_METHOD ||
        left->is_static != right->is_static ||
        left->param_count != right->param_count ||
        left->value_abi_kind != right->value_abi_kind) {
        return false;
    }
    for (size_t index = 0U; index < left->param_count; ++index) {
        if (left->param_abi_kinds[index] !=
            right->param_abi_kinds[index]) {
            return false;
        }
    }
    return true;
}

/* Emit one allocation-free bridge from a parent projection's target slot ABI
 * to the root default witness thunk. The bridge is needed only when generic
 * erasure makes two semantically equal requirements use different lowered
 * ABIs; it preserves the existing witness layout and slot identity. */
static bool cg_emit_default_parent_method_bridge(
    CG *cg,
    Buf *out,
    const UserSpec *root,
    const UserSpecMember *root_member,
    const UserSpecMember *target_member,
    const char *bridge_prefix,
    FengToken blame) {
    bool has_signature_parameter = false;
    bool has_call_argument = false;
    bool target_returns_value;

    if (cg == NULL || out == NULL || root == NULL || root_member == NULL ||
        target_member == NULL || bridge_prefix == NULL ||
        root_member->kind != USM_KIND_METHOD ||
        target_member->kind != USM_KIND_METHOD ||
        root_member->is_static != target_member->is_static ||
        root_member->param_count != target_member->param_count) {
        return false;
    }
    target_returns_value = target_member->type != NULL &&
                           target_member->type->kind != CG_TYPE_VOID;

    buf_append_cstr(out, "static ");
    cg_emit_callable_abi_return_type(out,
                                     target_member->type,
                                     target_member->value_abi_kind);
    buf_append_fmt(out,
                   " %s__%s(",
                   bridge_prefix,
                   target_member->c_field_name);
    if (!target_member->is_static) {
        buf_append_cstr(out, "void *_subject");
        has_signature_parameter = true;
    }
    for (size_t index = 0U;
         index < target_member->param_count;
         ++index) {
        if (has_signature_parameter) {
            buf_append_cstr(out, ", ");
        }
        cg_emit_callable_abi_param_type(out,
                                        target_member->param_types[index],
                                        target_member->param_abi_kinds[index]);
        buf_append_fmt(out, " _p%zu", index);
        has_signature_parameter = true;
    }
    if (target_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        if (has_signature_parameter) {
            buf_append_cstr(out, ", ");
        }
        buf_append_cstr(out, "void *_out");
        has_signature_parameter = true;
    }
    if (!has_signature_parameter) {
        buf_append_cstr(out, "void");
    }
    buf_append_cstr(out, ") {\n");

    if (target_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS &&
        root_member->value_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "    *(");
        cg_emit_c_type(out, target_member->type);
        buf_append_cstr(out, " *)_out = ");
        if (root_member->value_abi_kind ==
            CG_CALLABLE_ABI_ERASED_POINTER) {
            buf_append_cstr(out, "(");
            cg_emit_c_type(out, target_member->type);
            buf_append_cstr(out, ")");
        }
    } else if (target_member->value_abi_kind !=
                   CG_CALLABLE_ABI_ADDRESS &&
               root_member->value_abi_kind ==
                   CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(out, "    ");
        cg_emit_c_type(out, target_member->type);
        buf_append_cstr(out, " _result;\n    ");
    } else if (target_returns_value) {
        buf_append_cstr(out, "    return ");
        if (target_member->value_abi_kind ==
                CG_CALLABLE_ABI_ERASED_POINTER &&
            root_member->value_abi_kind !=
                CG_CALLABLE_ABI_ERASED_POINTER) {
            buf_append_cstr(out, "(void *)");
        } else if (target_member->value_abi_kind !=
                       CG_CALLABLE_ABI_ERASED_POINTER &&
                   root_member->value_abi_kind ==
                       CG_CALLABLE_ABI_ERASED_POINTER) {
            buf_append_cstr(out, "(");
            cg_emit_c_type(out, target_member->type);
            buf_append_cstr(out, ")");
        }
    } else {
        buf_append_cstr(out, "    ");
    }

    buf_append_fmt(out,
                   "%s__%s(",
                   root->c_default_witness_name,
                   root_member->c_field_name);
    if (!root_member->is_static) {
        buf_append_cstr(out, "_subject");
        has_call_argument = true;
    }
    for (size_t index = 0U;
         index < root_member->param_count;
         ++index) {
        char argument_name[32];

        (void)snprintf(argument_name,
                       sizeof argument_name,
                       "_p%zu",
                       index);
        if (has_call_argument) {
            buf_append_cstr(out, ", ");
        }
        cg_append_callable_abi_bridge_argument(
            out,
            root_member->param_types[index],
            target_member->param_abi_kinds[index],
            root_member->param_abi_kinds[index],
            argument_name);
        has_call_argument = true;
    }
    if (root_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        if (has_call_argument) {
            buf_append_cstr(out, ", ");
        }
        buf_append_cstr(
            out,
            target_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS
                ? "_out"
                : "&_result");
    }
    buf_append_cstr(out, ");\n");
    if (target_member->value_abi_kind != CG_CALLABLE_ABI_ADDRESS &&
        root_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        if (target_member->value_abi_kind ==
            CG_CALLABLE_ABI_ERASED_POINTER) {
            buf_append_cstr(out, "    return (void *)_result;\n");
        } else {
            buf_append_cstr(out, "    return _result;\n");
        }
    }
    buf_append_cstr(out, "}\n\n");
    (void)blame;
    return true;
}

/* Emit W(DefaultSubject(root), target). Parent views reuse root's default
 * member thunks so every projection keeps the same hidden subject storage.
 * The (root,target) cache makes a diamond converge on one ancestor witness. */
static bool cg_ensure_default_parent_witness(CG *cg,
                                             const UserSpec *root,
                                             const UserSpec *target,
                                             FengToken blame,
                                             const char **out_var) {
    const char **parent_witness_vars = NULL;
    Buf var;

    if (cg == NULL || root == NULL || target == NULL || out_var == NULL) {
        return false;
    }
    if (root == target) {
        *out_var = root->c_default_witness_name;
        return true;
    }
    for (size_t index = 0U;
         index < cg->default_parent_witness_count;
         ++index) {
        if (cg_spec_default_witness_identity_equal(
                cg->default_parent_witnesses[index].root,
                root) &&
            cg_spec_default_witness_identity_equal(
                cg->default_parent_witnesses[index].target,
                target)) {
            *out_var = cg->default_parent_witnesses[index].c_var;
            return true;
        }
    }
    if (target->direct_parent_spec_count > 0U) {
        parent_witness_vars = (const char **)calloc(
            target->direct_parent_spec_count,
            sizeof(*parent_witness_vars));
        if (parent_witness_vars == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }
    for (size_t parent_index = 0U;
         parent_index < target->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, target, parent_index);

        if (parent_spec == NULL ||
            !cg_ensure_default_parent_witness(
                cg,
                root,
                parent_spec,
                blame,
                &parent_witness_vars[parent_index])) {
            free(parent_witness_vars);
            return false;
        }
    }

    buf_init(&var);
    buf_append_fmt(&var,
                   "FengSpecDefaultProjection__%s__as__%s",
                   root->c_default_witness_name,
                   target->c_default_witness_name);
    if (var.data == NULL) {
        free(parent_witness_vars);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t member_index = 0U;
         member_index < target->member_count;
        ++member_index) {
        const UserSpecMember *target_member = &target->members[member_index];
        const UserSpecMember *root_member = cg_user_spec_member_matching_slot(
            root, target_member);

        if (root_member == NULL &&
            target_member->kind != USM_KIND_METHOD) {
            root_member = cg_user_spec_field_member(
                root,
                target_member->feng_name,
                strlen(target_member->feng_name),
                target_member->is_static);
        }

        if (root_member == NULL ||
            !cg_user_spec_member_compatible(root_member, target_member)) {
            free(parent_witness_vars);
            buf_free(&var);
            return cg_fail(cg,
                           blame,
                           "CE0048",
                           "codegen: default subject parent witness member mismatch");
        }
        if (target_member->kind == USM_KIND_METHOD &&
            !cg_spec_method_slot_abi_equal(root_member, target_member) &&
            !cg_emit_default_parent_method_bridge(cg,
                                                  &cg->type_defs,
                                                  root,
                                                  root_member,
                                                  target_member,
                                                  var.data,
                                                  blame)) {
            free(parent_witness_vars);
            buf_free(&var);
            if (!cg->failed) {
                (void)cg_fail(cg,
                              blame,
                              "IE0002",
                              "codegen: failed to bridge default parent method witness ABI");
            }
            return false;
        }
    }
    buf_append_fmt(&cg->type_defs,
                   "static const struct %s %s = {\n",
                   target->c_witness_struct_name,
                   var.data);
    for (size_t member_index = 0U;
         member_index < target->member_count;
        ++member_index) {
        const UserSpecMember *target_member = &target->members[member_index];
        const UserSpecMember *root_member = cg_user_spec_member_matching_slot(
            root, target_member);

        if (root_member == NULL &&
            target_member->kind != USM_KIND_METHOD) {
            root_member = cg_user_spec_field_member(
                root,
                target_member->feng_name,
                strlen(target_member->feng_name),
                target_member->is_static);
        }

        if (target_member->kind == USM_KIND_FIELD) {
            if (cg_spec_field_uses_storage_borrow(target_member)) {
                buf_append_fmt(&cg->type_defs,
                               "    .borrow_%s = &%s__borrow_%s,\n",
                               target_member->c_field_name,
                               root->c_default_witness_name,
                               root_member->c_field_name);
            } else {
                buf_append_fmt(&cg->type_defs,
                               "    .get_%s = &%s__get_%s,\n",
                               target_member->c_field_name,
                               root->c_default_witness_name,
                               root_member->c_field_name);
            }
            if (target_member->is_var) {
                buf_append_fmt(&cg->type_defs,
                               "    .set_%s = &%s__set_%s,\n",
                               target_member->c_field_name,
                               root->c_default_witness_name,
                               root_member->c_field_name);
            }
        } else {
            if (cg_spec_method_slot_abi_equal(root_member,
                                              target_member)) {
                buf_append_fmt(&cg->type_defs,
                               "    .%s = &%s__%s,\n",
                               target_member->c_field_name,
                               root->c_default_witness_name,
                               root_member->c_field_name);
            } else {
                buf_append_fmt(&cg->type_defs,
                               "    .%s = &%s__%s,\n",
                               target_member->c_field_name,
                               var.data,
                               target_member->c_field_name);
            }
        }
    }
    for (size_t parent_index = 0U;
         parent_index < target->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, target, parent_index);

        buf_append_cstr(&cg->type_defs, "    .");
        cg_append_spec_parent_field_name(&cg->type_defs, parent_spec);
        buf_append_fmt(&cg->type_defs,
                       " = &%s,\n",
                       parent_witness_vars[parent_index]);
    }
    buf_append_cstr(&cg->type_defs, "};\n\n");
    free(parent_witness_vars);

    if (cg->default_parent_witness_count ==
        cg->default_parent_witness_capacity) {
        size_t new_capacity = cg->default_parent_witness_capacity == 0U
                                  ? 8U
                                  : cg->default_parent_witness_capacity * 2U;
        void *grown = realloc(cg->default_parent_witnesses,
                              new_capacity * sizeof(*cg->default_parent_witnesses));

        if (grown == NULL) {
            buf_free(&var);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->default_parent_witnesses = grown;
        cg->default_parent_witness_capacity = new_capacity;
    }
    cg->default_parent_witnesses[cg->default_parent_witness_count].root = root;
    cg->default_parent_witnesses[cg->default_parent_witness_count].target = target;
    cg->default_parent_witnesses[cg->default_parent_witness_count].c_var = var.data;
    cg->default_parent_witness_count++;
    *out_var = var.data;
    return true;
}

static void cg_emit_user_spec_definition(CG *cg, const UserSpec *s) {
    Buf *td = &cg->type_defs;
    if (s->form == FENG_SPEC_FORM_CALLABLE) {
        buf_append_fmt(td, "struct %s {\n", s->c_closure_struct_name);
        buf_append_cstr(td, "    FengManagedHeader _hdr;\n    void *_self;\n    ");
        cg_emit_callable_abi_return_type(td,
                                         s->callable_return_type,
                                         s->callable_return_abi_kind);
        buf_append_cstr(td, " (*invoke)(void *_closure");
        for (size_t i = 0; i < s->callable_param_count; ++i) {
            buf_append_cstr(td, ", ");
            cg_emit_callable_abi_param_type(td,
                                            s->callable_param_types[i],
                                            s->callable_param_abi_kinds[i]);
        }
        cg_append_callable_abi_out_parameter(td,
                                             s->callable_return_abi_kind);
        buf_append_cstr(td, ");\n};\n\n");

        /* Witness struct body already emitted in cg_emit_user_spec_forward. */

        buf_append_fmt(td,
            "static void %s__release_children(void *_self) {\n"
            "    struct %s *_o = (struct %s *)_self;\n"
            "    feng_release(_o->_self);\n"
            "    _o->_self = NULL;\n"
            "}\n\n",
            s->c_closure_desc_name,
            s->c_closure_struct_name,
            s->c_closure_struct_name);

        buf_append_fmt(td,
            "static const FengManagedFieldDescriptor %s__managed_fields[] = {\n"
            "    { offsetof(struct %s, _self), NULL, NULL },\n"
            "};\n\n",
            s->c_closure_desc_name,
            s->c_closure_struct_name);

        /* Noop invoke — used by the default-zero callable value. */
        buf_append_cstr(td, "static ");
        cg_emit_callable_abi_return_type(td,
                                         s->callable_return_type,
                                         s->callable_return_abi_kind);
        buf_append_fmt(td, " %s(void *_closure", s->c_default_callable_noop_name);
        for (size_t i = 0; i < s->callable_param_count; ++i) {
            buf_append_cstr(td, ", ");
            cg_emit_callable_abi_param_type(td,
                                            s->callable_param_types[i],
                                            s->callable_param_abi_kinds[i]);
            buf_append_fmt(td, " _p%zu", i);
        }
        cg_append_callable_abi_out_parameter(td,
                                             s->callable_return_abi_kind);
        buf_append_cstr(td, ") {\n    (void)_closure;\n");
        for (size_t i = 0; i < s->callable_param_count; ++i) {
            buf_append_fmt(td, "    (void)_p%zu;\n", i);
        }
        if (s->generic_context_type_param_count > 0U &&
            s->callable_return_type->kind != CG_TYPE_VOID) {
            /* A shared default factory installs the closed instance's noop
             * from its concrete callable descriptor. The open descriptor is
             * only a compile-time identity and must never be invoked. */
            if (s->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                buf_append_cstr(td, "    (void)_out;\n");
            }
            buf_append_cstr(td,
                "    feng_panic(\"open generic callable default invoked without a concrete descriptor\");\n");
            if (s->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
                buf_append_cstr(td, "    return NULL;\n");
            }
            buf_append_cstr(td, "}\n\n");
        } else if (s->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS &&
                   cgtype_is_aggregate(s->callable_return_type)) {
            const char *aggregate_descriptor =
                cg_aggregate_desc_name(s->callable_return_type);

            if (aggregate_descriptor == NULL) {
                (void)cg_fail(cg,
                              s->decl->token,
                              "CE0224", "codegen: missing aggregate descriptor for callable default return");
                return;
            }
            buf_append_fmt(td,
                           "    feng_aggregate_default_init(_out, &%s);\n}\n\n",
                           aggregate_descriptor);
        } else if (s->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            char *ret_expr = NULL;
            char *ret_cty = cg_ctype_dup(s->callable_return_type);
            if (ret_cty == NULL ||
                !cg_default_value_expr(cg, s->callable_return_type,
                                       &s->decl->token, &ret_expr)) {
                free(ret_cty);
                free(ret_expr);
                return;
            }
            buf_append_fmt(td,
                           "    *(%s *)_out = %s;\n}\n\n",
                           ret_cty,
                           ret_expr);
            free(ret_cty);
            free(ret_expr);
        } else if (s->callable_return_type->kind == CG_TYPE_VOID) {
            buf_append_cstr(td, "}\n\n");
        } else {
            char *ret_expr = NULL;
            if (!cg_default_value_expr(cg, s->callable_return_type,
                                       &s->decl->token, &ret_expr)) {
                free(ret_expr);
                return;
            }
            buf_append_fmt(td, "    return %s;\n}\n\n", ret_expr);
            free(ret_expr);
        }

        /* Keep the runtime descriptor as the first member so all existing
         * managed-object paths keep using &descriptor. The typed noop is
         * erased only while stored and converted back to the exact canonical
         * invoke type before it is ever called. */
        if (s->generic_context_type_param_count == 0U) {
            buf_append_fmt(
                &cg->headers,
                "static void %s__default_zero_init("
                "void *_out, const FengTypeDescriptor *_descriptor);\n",
                s->c_closure_desc_name);
        }
        buf_append_fmt(td,
            "static const FengCallableTypeDescriptor %s__record = {\n"
            "    .base = {\n"
            "        .name = \"%s\",\n"
            "        .size = sizeof(struct %s),\n",
            s->c_closure_desc_name,
            s->feng_name,
            s->c_closure_struct_name);
        if (s->generic_context_type_param_count == 0U) {
            buf_append_fmt(
                td,
                "        .default_zero_init = %s__default_zero_init,\n",
                s->c_closure_desc_name);
        } else {
            buf_append_cstr(td, "        .default_zero_init = NULL,\n");
        }
        buf_append_fmt(td,
            "        .finalizer = NULL,\n"
            "        .release_children = %s__release_children,\n"
            "        .is_potentially_cyclic = true,\n"
            "        .managed_field_count = 1,\n"
            "        .managed_fields = %s__managed_fields,\n"
            "        .equal_fn = NULL,\n"
            "        .reified_generic_params_count = 0,\n"
            "    },\n"
            "    .default_invoke = (void (*)(void))%s,\n"
            "};\n\n",
            s->c_closure_desc_name,
            s->c_closure_desc_name,
            s->c_default_callable_noop_name);

        /* Forward declare so other default-zero factories can reference it. */
        {
            bool _imported = cg_program_origin(cg, s->owner_program) ==
                             FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE;
            bool needs_concrete_descriptor =
                s->generic_context_type_param_count > 0U;
            buf_append_fmt(&cg->headers,
                "%sstruct %s *%s(",
                _imported ? "static " : "",
                s->c_closure_struct_name,
                s->c_default_callable_new_name);
            buf_append_cstr(&cg->headers,
                needs_concrete_descriptor
                    ? "const FengTypeDescriptor *_type_desc);\n"
                    : "void);\n");

            /* Default-zero factory — allocates a callable with the noop invoke.
             * For imported specs the factory uses internal linkage so each
             * consumer has its own copy and avoids duplicate-symbol errors
             * with the originating library. */
            if (needs_concrete_descriptor) {
                buf_append_fmt(td,
                    "%sstruct %s *%s(const FengTypeDescriptor *_type_desc) {\n"
                    "    const FengCallableTypeDescriptor *_callable_desc = "
                    "(const FengCallableTypeDescriptor *)_type_desc;\n"
                    "    struct %s *_o = (struct %s *)feng_object_new(_type_desc);\n"
                    "    _o->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
                    "    _o->_self = NULL;\n"
                    "    _o->invoke = (",
                    _imported ? "static " : "",
                    s->c_closure_struct_name,
                    s->c_default_callable_new_name,
                    s->c_closure_struct_name,
                    s->c_closure_struct_name);
                cg_emit_callable_invoke_pointer_type(td, s);
                buf_append_cstr(td,
                    ")_callable_desc->default_invoke;\n"
                    "    return _o;\n"
                    "}\n\n");
            } else {
                buf_append_fmt(td,
                    "%sstruct %s *%s(void) {\n"
                    "    struct %s *_o = (struct %s *)feng_object_new(&%s);\n"
                    "    _o->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
                    "    _o->_self = NULL;\n"
                    "    _o->invoke = %s;\n"
                    "    return _o;\n"
                    "}\n\n",
                    _imported ? "static " : "",
                    s->c_closure_struct_name,
                    s->c_default_callable_new_name,
                    s->c_closure_struct_name,
                    s->c_closure_struct_name,
                    s->c_closure_desc_name,
                    s->c_default_callable_noop_name);
            }

            if (s->generic_context_type_param_count == 0U) {
                buf_append_fmt(
                    td,
                    "static void %s__default_zero_init("
                    "void *_out, const FengTypeDescriptor *_descriptor) {\n"
                    "    (void)_descriptor;\n"
                    "    *(void **)_out = %s();\n"
                    "}\n\n",
                    s->c_closure_desc_name,
                    s->c_default_callable_new_name);
            }
        }

        return;
    }
    if (s->form == FENG_SPEC_FORM_UNION) {
        Buf slot_descriptor;

        /* Shared generic bodies use this instance only as a C overlay for
         * fixed metadata/payload offsets. The final call site places the
         * closed union descriptor in reified_agg_deps; do not manufacture a
         * pseudo-closed size/default authority from the open overlay. */
        if (s->generic_context_type_param_count > 0U) {
            return;
        }

        buf_init(&slot_descriptor);
        if (s->union_member_count == 0U) {
            (void)cg_fail(cg, s->decl->token,
                          "CE0056", "codegen: union-form spec has no members");
            return;
        }
        if (!cg_append_union_member_slot_descriptor(cg,
                                                    &slot_descriptor,
                                                    s,
                                                    0U,
                                                    s->decl->token)) {
            buf_free(&slot_descriptor);
            return;
        }

        buf_append_fmt(td,
            "static const FengManagedSlotDescriptor %s[] = {\n"
            "    { offsetof(struct %s, _fwd), FENG_SLOT_FORWARD, NULL },\n"
            "};\n",
            s->c_aggregate_slots_name,
            s->c_value_struct_name);

        buf_append_fmt(td,
            "static void %s(void *_value_out) {\n"
            "    struct %s *_v = (struct %s *)_value_out;\n"
            "    memset(_v, 0, sizeof *_v);\n"
            "    _v->tag = 0U;\n"
            "    _v->_fwd = %s;\n",
            s->c_aggregate_init_fn_name,
            s->c_value_struct_name,
            s->c_value_struct_name,
            slot_descriptor.data);
        buf_free(&slot_descriptor);

        if (s->union_member_types[0U] != NULL &&
            s->union_member_types[0U]->kind != CG_TYPE_VOID) {
            if (cgtype_is_aggregate(s->union_member_types[0U])) {
                const char *member_desc = cg_aggregate_desc_name(s->union_member_types[0U]);

                if (member_desc == NULL) {
                    (void)cg_fail(cg,
                                  s->decl->token,
                                  "CE0057", "codegen: union default aggregate member is missing a descriptor");
                    return;
                }
                buf_append_fmt(td,
                    "    feng_aggregate_default_init(&_v->payload.m0, &%s);\n",
                    member_desc);
            } else {
                char *default_expr = NULL;
                char *member_ctype = cg_ctype_dup(s->union_member_types[0U]);

                if (member_ctype == NULL ||
                    !cg_default_value_expr(cg,
                                           s->union_member_types[0U],
                                           &s->decl->token,
                                           &default_expr)) {
                    free(member_ctype);
                    free(default_expr);
                    return;
                }
                buf_append_fmt(td,
                    "    _v->payload.m0 = (%s)(%s);\n",
                    member_ctype,
                    default_expr);
                free(member_ctype);
                free(default_expr);
            }
        }
        buf_append_cstr(td, "}\n");

        buf_append_fmt(td,
            "static const FengAggregateDefaultInitDescriptor %s = {\n"
            "    .kind = FENG_DEFAULT_INIT_FN,\n"
            "    .init_fn = %s,\n"
            "};\n",
            s->c_aggregate_default_name,
            s->c_aggregate_init_fn_name);

        bool ext_visible = cg_user_spec_descriptor_is_externally_visible(cg, s);
        buf_append_fmt(td,
            ext_visible
                ? "const FengAggregateDescriptor %s __attribute__((weak, unused)) = {\n"
                : "static const FengAggregateDescriptor %s __attribute__((unused)) = {\n",
            s->c_aggregate_desc_name);
        buf_append_fmt(td,
            "    .name = \"%s\",\n"
            "    .size = sizeof(struct %s),\n"
            "    .default_init = &%s,\n"
            "    .managed_slot_count = 1,\n"
            "    .managed_slots = %s,\n"
            "    .equal_fn = NULL,\n"
            "    .reified_generic_params_count = 0,\n"
            "};\n\n",
            s->feng_name,
            s->c_value_struct_name,
            s->c_aggregate_default_name,
            s->c_aggregate_slots_name);
        return;
    }
    /* Witness struct body already emitted in cg_emit_user_spec_forward. */

    if (s->generic_context_type_param_count > 0U) {
        return;
    }

    /* ---- Value-model aggregate descriptor (docs/engineering/feng-value-model-delivered.md
     * §3, §7.2, §8.2). For object-form specs the value layout is
     * { void *subject; const Witness *witness; } — exactly one managed
     * pointer slot at offset 0 (subject). The witness pointer is a
     * non-managed reference into rodata. */
    buf_append_fmt(td,
        "static const FengManagedSlotDescriptor %s[] = {\n"
        "    { offsetof(struct %s, subject), FENG_SLOT_POINTER, NULL },\n"
        "};\n",
        s->c_aggregate_slots_name,
        s->c_value_struct_name);

    /* ---- Hidden default-subject type (docs/engineering/feng-spec-codegen-delivered.md §6).
     * For each object-form spec we generate a real managed object that
     * backs default-initialised spec values: the default witness reads /
     * writes its fields, and method slots return per-type defaults. The
     * struct is opaque to user code (its name carries `Default__`). */
    buf_append_fmt(td, "struct %s {\n", s->c_default_subject_struct_name);
    buf_append_cstr(td, "    FengManagedHeader _hdr;\n");
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind != USM_KIND_FIELD || sm->is_static) continue;
        buf_append_cstr(td, "    ");
        cg_emit_c_type(td, sm->type);
        buf_append_fmt(td, " %s;\n", sm->c_field_name);
    }
    buf_append_cstr(td, "};\n\n");

    /* Subject release_children — one drop per managed FIELD. Aggregate fields
     * reuse the aggregate descriptor flatten rules through cg_emit_field_release. */
    bool subject_any_managed = false;
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind == USM_KIND_FIELD &&
            !sm->is_static &&
            cgtype_value_kind(sm->type) != CG_VK_TRIVIAL) {
            subject_any_managed = true;
            break;
        }
    }
    char *subject_release_name = NULL;
    if (subject_any_managed) {
        Buf rcn; buf_init(&rcn);
        buf_append_fmt(&rcn, "%s__release_children",
                       s->c_default_subject_struct_name);
        subject_release_name = rcn.data;
        buf_append_fmt(td, "static void %s(void *_self) {\n", subject_release_name);
        buf_append_fmt(td, "    struct %s *_o = (struct %s *)_self;\n",
                       s->c_default_subject_struct_name,
                       s->c_default_subject_struct_name);
        for (size_t i = 0; i < s->member_count; i++) {
            const UserSpecMember *sm = &s->members[i];
            if (sm->kind != USM_KIND_FIELD || sm->is_static) continue;
            if (!cg_emit_field_release(cg, td, sm->c_field_name, sm->type,
                                       s->decl->token)) {
                free(subject_release_name);
                return;
            }
        }
        buf_append_cstr(td, "}\n\n");
    }

    /* Subject managed_fields metadata for the cycle collector. */
    size_t subject_managed_count = 0U;
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind != USM_KIND_FIELD || sm->is_static) continue;
        subject_managed_count += cg_field_managed_descriptor_count(
            cg, sm->type, s->decl->token);
    }
    if (subject_managed_count > 0U) {
        buf_append_fmt(td,
            "static const FengManagedFieldDescriptor %s__managed_fields[] = {\n",
            s->c_default_subject_struct_name);
        for (size_t i = 0; i < s->member_count; i++) {
            const UserSpecMember *sm = &s->members[i];
            if (sm->kind != USM_KIND_FIELD || sm->is_static) continue;
            if (!cg_emit_field_managed_descriptors(cg, td,
                    s->c_default_subject_struct_name,
                    sm->c_field_name, sm->type, s->decl->token)) {
                free(subject_release_name);
                return;
            }
        }
        buf_append_cstr(td, "};\n\n");
    }

    /* Subject FengTypeDescriptor — hidden default subjects are never user
     * finalisers and conservatively marked acyclic (default zero values
     * cannot reference back into themselves: every initialiser is a fresh
     * default of its own type). */
    buf_append_fmt(td,
        "static const FengTypeDescriptor %s = {\n"
        "    .name = \"%s.%s.<spec_default>\",\n"
        "    .size = sizeof(struct %s),\n"
        "    .finalizer = NULL,\n"
        "    .release_children = %s,\n"
        "    .is_potentially_cyclic = false,\n"
        "    .managed_field_count = %zu,\n",
        s->c_default_subject_desc_name,
        cg->module_dot_name, s->feng_name,
        s->c_default_subject_struct_name,
        subject_release_name ? subject_release_name : "NULL",
        subject_managed_count);
    if (subject_managed_count > 0U) {
        buf_append_fmt(td, "    .managed_fields = %s__managed_fields,\n",
                       s->c_default_subject_struct_name);
    } else {
        buf_append_cstr(td, "    .managed_fields = NULL,\n");
    }
    buf_append_cstr(td, "    .equal_fn = NULL,\n");
    buf_append_cstr(td, "    .reified_generic_params_count = 0,\n");
    buf_append_cstr(td, "};\n\n");
    free(subject_release_name);

    /* Subject factory: feng_object_new + per-field default-zero materialise.
     * Returns +1 owns_ref. */
    buf_append_fmt(td,
        "static struct %s *%s(void) {\n"
        "    struct %s *_o = (struct %s *)feng_object_new(&%s);\n",
        s->c_default_subject_struct_name, s->c_default_subject_new_name,
        s->c_default_subject_struct_name, s->c_default_subject_struct_name,
        s->c_default_subject_desc_name);
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind != USM_KIND_FIELD || sm->is_static) continue;
        /* Trivial: feng_object_new already zeroed. */
        if (cgtype_value_kind(sm->type) == CG_VK_TRIVIAL) continue;
        if (cgtype_is_aggregate(sm->type)) {
            Buf lvalue;
            bool ok;
            buf_init(&lvalue);
            buf_append_fmt(&lvalue, "_o->%s", sm->c_field_name);
            if (lvalue.data == NULL) {
                return;
            }
            buf_append_cstr(td, "    ");
            ok = cg_append_aggregate_default_init_call(td, sm->type, lvalue.data);
            buf_free(&lvalue);
            if (!ok) {
                return;
            }
            buf_append_cstr(td, ";\n");
            continue;
        }
        char *expr = NULL;
        if (!cg_default_value_expr(cg, sm->type, &s->decl->token, &expr)) {
            free(expr);
            return;
        }
        buf_append_fmt(td, "    _o->%s = %s;\n", sm->c_field_name, expr);
        free(expr);
    }
    buf_append_cstr(td, "    return _o;\n}\n\n");

    /* Default witness thunks. Field getters / setters route through the
     * subject's own field; methods return the default value of their
     * return type. Method thunks ignore arguments (default semantics
     * cannot inspect them). Static members omit the _subject parameter —
     * the default witness has no backing type, so static getters return
     * default-zero values and static setters are no-ops (no real storage). */
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind == USM_KIND_FIELD) {
            if (!cg_emit_default_spec_field_thunks(cg, td, s, sm)) return;
        } else if (sm->kind == USM_KIND_METHOD) {
            if (!cg_emit_default_spec_method_thunk(cg, td, s, sm)) return;
        }
    }
    buf_append_cstr(td, "\n");

    const char **default_parent_witness_vars = NULL;
    if (s->direct_parent_spec_count > 0U) {
        default_parent_witness_vars = (const char **)calloc(
            s->direct_parent_spec_count,
            sizeof(*default_parent_witness_vars));
        if (default_parent_witness_vars == NULL) {
            (void)cg_fail(cg, s->decl->token,
                          "IE0001", "codegen: out of memory");
            return;
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        if (parent_spec == NULL ||
            !cg_ensure_default_parent_witness(
                cg,
                s,
                parent_spec,
                s->decl->token,
                &default_parent_witness_vars[parent_index])) {
            free(default_parent_witness_vars);
            return;
        }
    }

    /* Default witness instance — same struct layout as a (T,S) witness; only
     * the function pointers differ. */
    buf_append_fmt(td, "static const struct %s %s = {\n",
                   s->c_witness_struct_name, s->c_default_witness_name);
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind == USM_KIND_FIELD) {
            if (cg_spec_field_uses_storage_borrow(sm)) {
                buf_append_fmt(td, "    .borrow_%s = &%s__borrow_%s,\n",
                               sm->c_field_name, s->c_default_witness_name,
                               sm->c_field_name);
            } else {
                buf_append_fmt(td, "    .get_%s = &%s__get_%s,\n",
                               sm->c_field_name, s->c_default_witness_name,
                               sm->c_field_name);
            }
            if (sm->is_var) {
                buf_append_fmt(td, "    .set_%s = &%s__set_%s,\n",
                               sm->c_field_name, s->c_default_witness_name,
                               sm->c_field_name);
            }
        } else if (sm->kind == USM_KIND_METHOD) {
            buf_append_fmt(td, "    .%s = &%s__%s,\n",
                           sm->c_field_name, s->c_default_witness_name,
                           sm->c_field_name);
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        buf_append_cstr(td, "    .");
        cg_append_spec_parent_field_name(td, parent_spec);
        buf_append_fmt(td,
                       " = &%s,\n",
                       default_parent_witness_vars[parent_index]);
    }
    buf_append_cstr(td, "};\n\n");
    free(default_parent_witness_vars);

    /* Real default-init function: allocate fresh subject (+1) and bind
     * the default witness. Per docs/engineering/feng-spec-codegen-delivered.md §6.4 the
     * factory already returned an owning reference, so no extra retain. */
    buf_append_fmt(td,
        "static void %s(void *_value_out) {\n"
        "    struct %s *_v = _value_out;\n"
        "    _v->subject = (void *)%s();\n"
        "    _v->witness = &%s;\n"
        "}\n",
        s->c_aggregate_init_fn_name,
        s->c_value_struct_name,
        s->c_default_subject_new_name,
        s->c_default_witness_name);

    buf_append_fmt(td,
        "static const FengAggregateDefaultInitDescriptor %s = {\n"
        "    .kind = FENG_DEFAULT_INIT_FN,\n"
        "    .init_fn = %s,\n"
        "};\n",
        s->c_aggregate_default_name,
        s->c_aggregate_init_fn_name);

    buf_append_fmt(td,
        "static bool %s__equal(const void *_left, const void *_right) {\n"
        "    const struct %s *_l = (const struct %s *)_left;\n"
        "    const struct %s *_r = (const struct %s *)_right;\n"
        "    return _l->subject == _r->subject;\n"
        "}\n",
        s->c_aggregate_desc_name,
        s->c_value_struct_name,
        s->c_value_struct_name,
        s->c_value_struct_name,
        s->c_value_struct_name);

    bool ext_visible = cg_user_spec_descriptor_is_externally_visible(cg, s);
    buf_append_fmt(td,
        ext_visible
            ? "const FengAggregateDescriptor %s __attribute__((weak, unused)) = {\n"
            : "static const FengAggregateDescriptor %s __attribute__((unused)) = {\n",
        s->c_aggregate_desc_name);
    buf_append_fmt(td,
        "    .name = \"%s\",\n"
        "    .size = sizeof(struct %s),\n"
        "    .default_init = &%s,\n"
        "    .managed_slot_count = 1,\n"
        "    .managed_slots = %s,\n"
        "    .equal_fn = %s__equal,\n"
        "    .reified_generic_params_count = 0,\n"
        "};\n\n",
        s->feng_name,
        s->c_value_struct_name,
        s->c_aggregate_default_name,
        s->c_aggregate_slots_name,
        s->c_aggregate_desc_name);
}

/* ----- module bindings ----- */

static bool cg_register_module_binding(CG *cg,
                                       const FengDecl *decl,
                                       FengCompileTarget target) {
    if (cg->module_binding_count + 1 > cg->module_binding_capacity) {
        size_t cap = cg->module_binding_capacity ? cg->module_binding_capacity * 2 : 4;
        void *p = realloc(cg->module_bindings, cap * sizeof *cg->module_bindings);
        if (!p) return false;
        cg->module_bindings = p;
        cg->module_binding_capacity = cap;
    }
    ModuleBinding *mb = &cg->module_bindings[cg->module_binding_count++];
    memset(mb, 0, sizeof *mb);
    mb->binding = &decl->as.binding;
    mb->is_var = (decl->as.binding.mutability == FENG_MUTABILITY_VAR);
    mb->exports_public_surface =
        target == FENG_COMPILE_TARGET_LIB && decl->visibility == FENG_VISIBILITY_PUBLIC;
    mb->owner_program = cg->cur_program;
    mb->feng_name = strndup(decl->as.binding.name.data, decl->as.binding.name.length);
    if (!mb->feng_name) return false;
    char *san = cg_sanitize(decl->as.binding.name.data, decl->as.binding.name.length);
    if (!san) return false;
    Buf b; buf_init(&b);
    Buf inited; buf_init(&inited);
    char *public_slot_name = NULL;
    char *public_ensure_init_name = NULL;
    Buf ensure_init; buf_init(&ensure_init);

    if (mb->exports_public_surface) {
        if (!cg_binding_public_surface_names(cg,
                                             decl,
                                             &public_slot_name,
                                             &public_ensure_init_name)) {
            free(san);
            buf_free(&b);
            buf_free(&inited);
            buf_free(&ensure_init);
            return false;
        }
    } else {
        buf_append_fmt(&b, "_feng_g__%s__%s", cg->module_mangle, san);
        buf_append_fmt(&ensure_init, "_feng_ensure_g__%s__%s", cg->module_mangle, san);
    }
    buf_append_fmt(&inited, "_feng_g__%s__%s__inited", cg->module_mangle, san);
    free(san);
    mb->c_name = mb->exports_public_surface ? public_slot_name : b.data;
    mb->c_ensure_init_name = mb->exports_public_surface ? public_ensure_init_name : ensure_init.data;
    mb->c_inited_name = inited.data;
    if (!mb->c_name || !mb->c_ensure_init_name || !mb->c_inited_name) {
        free(mb->c_name);
        free(mb->c_ensure_init_name);
        free(mb->c_inited_name);
        mb->c_name = NULL;
        mb->c_ensure_init_name = NULL;
        mb->c_inited_name = NULL;
        return false;
    }
    if (!cg_resolve_global_binding_type(cg, decl, &mb->type)) {
        return false;
    }
    return true;
}

static const ModuleBinding *cg_find_module_binding(const CG *cg, const char *name, size_t len) {
    for (size_t i = 0; i < cg->module_binding_count; i++) {
        if (strlen(cg->module_bindings[i].feng_name) == len &&
            memcmp(cg->module_bindings[i].feng_name, name, len) == 0) {
            return &cg->module_bindings[i];
        }
    }
    return NULL;
}

static const ModuleBinding *cg_find_module_binding_by_binding(const CG *cg,
                                                              const FengBinding *binding) {
    for (size_t i = 0; i < cg->module_binding_count; i++) {
        if (cg->module_bindings[i].binding == binding) {
            return &cg->module_bindings[i];
        }
    }
    return NULL;
}

static char *cg_module_binding_slot_expr_dup(const ModuleBinding *mb) {
    return mb != NULL && mb->c_name != NULL ? strdup(mb->c_name) : NULL;
}

static void cg_emit_module_binding_ensure_init_call(CG *cg,
                                                    const ModuleBinding *mb) {
    buf_append_fmt(cg->cur_body, "    %s();\n", mb->c_ensure_init_name);
}

/* Append one static-binding ensure call to an arbitrary generated-code
 * buffer. Generic instances reuse the declaration's shared initializer with
 * their exact descriptor/state entry; ordinary types keep the zero-argument
 * ensure function. */
static bool cg_append_type_static_binding_ensure_init_call(
    CG *cg,
    Buf *out,
    const TypeStaticBinding *binding) {
    if (cg == NULL || out == NULL || binding == NULL ||
        binding->owner_type == NULL) {
        return false;
    }
    if (cg_user_type_is_generic_origin_instance(binding->owner_type)) {
        char *state_expr = cg_type_static_binding_state_expr_dup(binding);
        char *ensure_name = cg_generic_type_static_ensure_shared_cname(
            cg,
            binding->owner_type->generic_origin_decl,
            binding->member);
        const char *descriptor_name = cg_user_type_is_value(binding->owner_type)
                                          ? binding->owner_type->c_aggregate_desc_name
                                          : binding->owner_type->c_desc_name;

        if (state_expr == NULL || ensure_name == NULL ||
            descriptor_name == NULL) {
            free(state_expr);
            free(ensure_name);
            return cg_fail(cg,
                           binding->member != NULL
                               ? binding->member->token
                               : (FengToken){0},
                           "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(out,
                       "    %s(&%s, &%s);\n",
                       ensure_name,
                       descriptor_name,
                       state_expr);
        free(state_expr);
        free(ensure_name);
        return true;
    }
    buf_append_fmt(out, "    %s();\n", binding->c_ensure_init_name);
    return true;
}

/* Emit one static-binding ensure call into the active function body. */
static bool cg_emit_type_static_binding_ensure_init_call(
    CG *cg,
    const TypeStaticBinding *binding) {
    return cg != NULL &&
           cg_append_type_static_binding_ensure_init_call(cg,
                                                          cg->cur_body,
                                                          binding);
}

/** Return whether an erased generic body must select this static via a descriptor. */
static bool cg_static_binding_uses_shared_state(
    const CG *cg,
    const UserType *target) {
    return cg != NULL &&
           cg->in_generic_fn &&
           target != NULL &&
           cg_user_type_is_generic_origin_instance(target) &&
           target->generic_context_type_param_count > 0U;
}

/** Emit one descriptor-indexed generic static state lookup and direct ensure call. */
static bool cg_emit_shared_static_binding_state(
    CG *cg,
    const UserType *target,
    const TypeStaticBinding *binding,
    FengToken blame,
    char **out_state_name) {
    const FengDecl *origin;
    const char *descriptor_type;
    char *descriptor_expr = NULL;
    char *descriptor_name = NULL;
    char *state_name = NULL;
    char *ensure_name = NULL;
    size_t binding_index;

    if (out_state_name != NULL) {
        *out_state_name = NULL;
    }
    if (!cg_static_binding_uses_shared_state(cg, target) ||
        binding == NULL || binding->member == NULL ||
        !cg_type_static_binding_index(binding, &binding_index)) {
        return false;
    }
    origin = target->generic_origin_decl;
    if (origin == cg->generic_type_method_decl) {
        descriptor_expr = strdup("_td");
    } else {
        descriptor_expr = cg_rtd_expr_for_type(cg, target, blame);
    }
    descriptor_name = cg_fresh_temp(cg, "_static_desc");
    state_name = cg_fresh_temp(cg, "_static_state");
    ensure_name = cg_generic_type_static_ensure_shared_cname(
        cg,
        origin,
        binding->member);
    if (descriptor_expr == NULL || descriptor_name == NULL ||
        state_name == NULL || ensure_name == NULL) {
        free(descriptor_expr);
        free(descriptor_name);
        free(state_name);
        free(ensure_name);
        if (!cg->failed) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        return false;
    }
    descriptor_type = cg_user_type_is_value(target)
                          ? "FengAggregateDescriptor"
                          : "FengTypeDescriptor";
    buf_append_fmt(cg->cur_body,
        "    const %s *%s = %s;\n"
        "    FengStaticBindingState *%s = &%s->static_bindings[%zu];\n"
        "    %s(%s, %s);\n",
        descriptor_type,
        descriptor_name,
        descriptor_expr,
        state_name,
        descriptor_name,
        binding_index,
        ensure_name,
        descriptor_name,
        state_name);
    free(descriptor_expr);
    free(descriptor_name);
    free(ensure_name);
    if (out_state_name != NULL) {
        *out_state_name = state_name;
    } else {
        free(state_name);
    }
    return true;
}

/* ===================== expression emission ===================== */

struct ExprResult {
    char   *c_expr;       /* malloc'd */
    CGType *type;         /* malloc'd */
    /* When true, the C expression evaluates to a fresh +1 reference that the
     * caller MUST either store in a slot (transferring ownership) or wrap in
     * a temporary and release after use. Meaningful for managed and
     * aggregate types. */
    bool    owns_ref;
    /* For a borrowed managed result, true when compile-time mutability facts
     * prove that its reference identity and owning path cannot change while
     * later subexpressions of the current statement are evaluated. */
    bool    managed_identity_is_stable;
    /* True when the result has stable storage for the current statement. */
    bool    is_addressable;
    /* True when c_expr itself is the address of the Feng value storage.
     * This is independent from whether the storage has dynamic aggregate
     * layout authority. */
    bool    is_storage_address;
    /* Direct generic parameter storage whose concrete size and lifecycle
     * are selected by a FengGenericParamDescriptor at runtime. */
    bool    uses_erased_generic_storage;
    char   *erased_generic_descriptor_c_name;
    char   *erased_generic_size_c_name;
    /* True when c_expr already evaluates to the address of descriptor-sized
     * storage. Such an expression must never be copied through the open
     * generic C placeholder struct. */
    bool    uses_reified_storage;
    /* Cached names for the descriptor and size used to declare that storage.
     * They are propagated when an owned temporary is adopted as a local. */
    char   *reified_descriptor_c_name;
    char   *reified_size_c_name;
};

/* Lower one shared-callable argument according to the declaration-selected
 * ABI. Address transport does not change Feng parameter semantics: value
 * representations receive an independent parameter copy, while managed
 * pointers continue to copy only the reference value. */
static char *cg_shared_callable_argument_expr_dup(CG *cg,
                                                  ExprResult *argument,
                                                  bool uses_address_abi,
                                                  const char *temp_prefix) {
    if (cg == NULL || argument == NULL || argument->type == NULL) {
        return NULL;
    }
    if ((cgtype_is_managed(argument->type) ||
         cgtype_is_aggregate(argument->type)) &&
        argument->owns_ref &&
        cg_materialize_to_local(cg, argument, temp_prefix) == NULL) {
        return NULL;
    }
    if (uses_address_abi) {
        if (!cg_materialize_shared_callable_value_argument(
                cg, argument, temp_prefix)) {
            return NULL;
        }
        if (!argument->is_addressable &&
            cg_materialize_to_local(cg, argument, temp_prefix) == NULL) {
            return NULL;
        }
        return cg_aggregate_result_address_dup(argument);
    }
    return strdup(argument->c_expr);
}

/* Return the generic declaration that owns one nominal managed-pointer type.
 * Ordinary reference types and callable-form specs both use a single managed
 * pointer while their open and closed instances have distinct C struct tags.
 * Other managed categories already have one common C pointer surface. */
static const FengDecl *cg_nominal_managed_pointer_generic_origin(
    const CGType *type) {
    if (type == NULL) {
        return NULL;
    }
    if (type->kind == CG_TYPE_OBJECT && type->user != NULL &&
        !cg_type_is_value_semantics(type)) {
        if (type->user->generic_origin_decl != NULL) {
            return type->user->generic_origin_decl;
        }
        if (type->user->decl != NULL &&
            type->user->decl->kind == FENG_DECL_TYPE &&
            type->user->decl->as.type_decl.type_param_count > 0U) {
            return type->user->decl;
        }
        return NULL;
    }
    if (type->kind == CG_TYPE_CALLABLE && type->user_spec != NULL) {
        if (type->user_spec->generic_origin_decl != NULL) {
            return type->user_spec->generic_origin_decl;
        }
        if (type->user_spec->decl != NULL &&
            type->user_spec->decl->kind == FENG_DECL_SPEC &&
            type->user_spec->decl->as.spec_decl.type_param_count > 0U) {
            return type->user_spec->decl;
        }
    }
    return NULL;
}

/* Bridge two nominal managed-pointer instances of the same generic
 * declaration at a shared-body call boundary. The emitted C cast preserves
 * the single-pointer representation and adds no runtime work. */
static char *cg_shared_nominal_managed_pointer_expr_dup(
    const CGType *shared_type,
    const CGType *actual_type,
    const char *actual_expr) {
    const FengDecl *shared_origin;
    const FengDecl *actual_origin;
    Buf expression;

    if (actual_expr == NULL) {
        return NULL;
    }
    if (shared_type == NULL || actual_type == NULL ||
        shared_type->kind != actual_type->kind ||
        !cgtype_is_managed(shared_type) ||
        !cgtype_is_managed(actual_type) ||
        cg_types_equal(shared_type, actual_type)) {
        return strdup(actual_expr);
    }
    shared_origin =
        cg_nominal_managed_pointer_generic_origin(shared_type);
    actual_origin =
        cg_nominal_managed_pointer_generic_origin(actual_type);
    if (shared_origin == NULL || shared_origin != actual_origin) {
        return strdup(actual_expr);
    }

    buf_init(&expression);
    buf_append_cstr(&expression, "((");
    cg_emit_c_type(&expression, shared_type);
    buf_append_fmt(&expression, ")(%s))", actual_expr);
    return expression.data;
}

/* Lower one argument and apply the zero-cost nominal pointer bridge selected
 * by the original shared declaration. Address-ABI values already use neutral
 * storage pointers and therefore need no additional C type adaptation. */
static char *cg_shared_callable_argument_for_type_expr_dup(
    CG *cg,
    ExprResult *argument,
    const CGType *shared_type,
    bool uses_address_abi,
    const char *temp_prefix) {
    char *lowered;
    char *bridged;

    lowered = cg_shared_callable_argument_expr_dup(
        cg, argument, uses_address_abi, temp_prefix);
    if (lowered == NULL || uses_address_abi) {
        return lowered;
    }
    bridged = cg_shared_nominal_managed_pointer_expr_dup(
        shared_type, argument->type, lowered);
    free(lowered);
    return bridged;
}

/** Store one erased generic-parameter value into caller-provided storage. */
static bool cg_emit_generic_value_store(
    CG *cg,
    const char *storage_expr,
    const CGType *target_type,
    ExprResult *value,
    FengToken blame,
    bool replace_existing) {
    const char *descriptor;
    char *source_name;

    if (cg == NULL || storage_expr == NULL || target_type == NULL ||
        target_type->kind != CG_TYPE_GENERIC_PARAM || value == NULL ||
        value->type == NULL || value->type->kind != CG_TYPE_GENERIC_PARAM ||
        value->type->generic_param_index != target_type->generic_param_index) {
        return cg_fail(cg, blame,
                       "CE0248", "codegen: generic assignment requires a value with the same generic type parameter");
    }
    descriptor = cg_generic_param_desc_name(
        cg,
        target_type->generic_param_index);
    source_name = cg_fresh_temp(cg, "_static_source");
    if (descriptor == NULL || source_name == NULL) {
        free(source_name);
        return cg_fail(cg,
                       blame,
                       descriptor == NULL ? "CE0237" : "IE0001",
                       descriptor == NULL
                           ? "codegen: missing generic descriptor for assignment"
                           : "codegen: out of memory");
    }
    buf_append_fmt(cg->cur_body,
        "    const void *%s = %s;\n"
        "    switch (%s->kind) {\n"
        "        case FENG_VALUE_TRIVIAL:\n"
        "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
        "            break;\n"
        "        case FENG_VALUE_MANAGED_POINTER: {\n"
        "            void *_new_value = *(void *const *)%s;\n",
        source_name,
        value->c_expr,
        descriptor,
        storage_expr,
        source_name,
        descriptor,
        source_name);
    if (!value->owns_ref) {
        buf_append_cstr(cg->cur_body,
                        "            feng_retain(_new_value);\n");
    }
    if (replace_existing) {
        buf_append_fmt(cg->cur_body,
            "            void *_old_value = *(void **)%s;\n"
            "            *(void **)%s = _new_value;\n"
            "            feng_release(_old_value);\n",
            storage_expr,
            storage_expr);
    } else {
        buf_append_fmt(cg->cur_body,
            "            *(void **)%s = _new_value;\n",
            storage_expr);
    }
    buf_append_cstr(cg->cur_body,
        "            break;\n"
        "        }\n"
        "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n");
    if (value->owns_ref) {
        buf_append_fmt(cg->cur_body,
            "            feng_aggregate_take(%s, (void *)%s, "
            "feng_generic_aggregate_descriptor(%s));\n",
            storage_expr,
            source_name,
            descriptor);
    } else {
        buf_append_fmt(cg->cur_body,
            "            feng_aggregate_assign(%s, %s, "
            "feng_generic_aggregate_descriptor(%s));\n",
            storage_expr,
            source_name,
            descriptor);
    }
    buf_append_cstr(cg->cur_body,
        "            break;\n"
        "    }\n");
    free(source_name);
    return true;
}

static void er_init(ExprResult *r) {
    r->c_expr = NULL;
    r->type = NULL;
    r->owns_ref = false;
    r->managed_identity_is_stable = false;
    r->is_addressable = false;
    r->is_storage_address = false;
    r->uses_erased_generic_storage = false;
    r->erased_generic_descriptor_c_name = NULL;
    r->erased_generic_size_c_name = NULL;
    r->uses_reified_storage = false;
    r->reified_descriptor_c_name = NULL;
    r->reified_size_c_name = NULL;
}

static bool cg_tuple_user_has_field_count(const UserType *ut, size_t count) {
    return cg_user_type_is_tuple(ut) && ut->field_count == count;
}

static bool cg_emit_tuple_field_value_store(CG *cg,
                                            const char *tuple_expr,
                                            const UserField *field,
                                            ExprResult *value,
                                            FengToken blame,
                                            const char *rad_desc_expr,
                                            size_t field_index) {
    if (cg == NULL || tuple_expr == NULL || field == NULL || value == NULL) {
        return false;
    }

    if (field->type != NULL && field->type->kind == CG_TYPE_GENERIC_PARAM) {
        size_t gp_index = field->type->generic_param_index;
        const char *desc = cg_generic_param_desc_name(cg, gp_index);
        char *slot_tmp = NULL;
        char *src_tmp = NULL;

        if (desc == NULL) {
            return cg_fail(cg,
                           blame,
                           "CE0058", "codegen: missing generic descriptor for tuple field '%s'",
                           field->feng_name);
        }
        if (value->type == NULL || value->type->kind != CG_TYPE_GENERIC_PARAM ||
            value->type->generic_param_index != gp_index) {
            return cg_fail(cg,
                           blame,
                           "CE0059", "codegen: tuple field '%s' generic initializer type mismatch",
                           field->feng_name);
        }

        slot_tmp = cg_fresh_temp(cg, "_gslot");
        src_tmp = cg_fresh_temp(cg, "_gsrc");
        if (slot_tmp == NULL || src_tmp == NULL) {
            free(slot_tmp);
            free(src_tmp);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }

        if (rad_desc_expr != NULL) {
            buf_append_fmt(cg->cur_body,
                           "    void *%s = (void *)((char *)%s + %s->reified_field_offsets[%zu]);\n"
                           "    const void *%s = %s;\n"
                           "    switch (%s->kind) {\n"
                           "        case FENG_VALUE_TRIVIAL:\n"
                           "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
                           "            break;\n"
                           "        case FENG_VALUE_MANAGED_POINTER: {\n"
                           "            void *_new_value = *(void *const *)%s;\n"
                           "            if (!%s) {\n"
                           "                feng_retain(_new_value);\n"
                           "            }\n"
                           "            *(void **)%s = _new_value;\n"
                           "            break;\n"
                           "        }\n"
                           "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                           "            feng_aggregate_assign(%s, %s, feng_generic_aggregate_descriptor(%s));\n"
                           "            break;\n"
                           "    }\n",
                           slot_tmp,
                           tuple_expr,
                           rad_desc_expr,
                           field_index,
                           src_tmp,
                           value->c_expr,
                           desc,
                           slot_tmp,
                           src_tmp,
                           desc,
                           src_tmp,
                           value->owns_ref ? "true" : "false",
                           slot_tmp,
                           slot_tmp,
                           src_tmp,
                           desc);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    void *%s = (void *)&%s.%s;\n"
                           "    const void *%s = %s;\n"
                           "    switch (%s->kind) {\n"
                           "        case FENG_VALUE_TRIVIAL:\n"
                           "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
                           "            break;\n"
                           "        case FENG_VALUE_MANAGED_POINTER: {\n"
                           "            void *_new_value = *(void *const *)%s;\n"
                           "            if (!%s) {\n"
                           "                feng_retain(_new_value);\n"
                           "            }\n"
                           "            *(void **)%s = _new_value;\n"
                           "            break;\n"
                           "        }\n"
                           "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                           "            feng_aggregate_assign(%s, %s, feng_generic_aggregate_descriptor(%s));\n"
                           "            break;\n"
                           "    }\n",
                           slot_tmp,
                           tuple_expr,
                           field->c_name,
                           src_tmp,
                           value->c_expr,
                           desc,
                           slot_tmp,
                           src_tmp,
                           desc,
                           src_tmp,
                           value->owns_ref ? "true" : "false",
                           slot_tmp,
                           slot_tmp,
                           src_tmp,
                           desc);
        }

        free(slot_tmp);
        free(src_tmp);
        return true;
    }

    if (cgtype_is_managed(field->type)) {
        if (rad_desc_expr != NULL) {
            if (value->owns_ref) {
                buf_append_fmt(cg->cur_body,
                               "    *(void **)((char *)%s + %s->reified_field_offsets[%zu]) = %s;\n",
                               tuple_expr, rad_desc_expr, field_index,
                               value->c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    *(void **)((char *)%s + %s->reified_field_offsets[%zu]) = %s;"
                               " feng_retain(*(void **)((char *)%s + %s->reified_field_offsets[%zu]));\n",
                               tuple_expr, rad_desc_expr, field_index,
                               value->c_expr,
                               tuple_expr, rad_desc_expr, field_index);
            }
        } else {
            if (value->owns_ref) {
                buf_append_fmt(cg->cur_body,
                               "    %s.%s = %s;\n",
                               tuple_expr,
                               field->c_name,
                               value->c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    %s.%s = %s; feng_retain(%s.%s);\n",
                               tuple_expr,
                               field->c_name,
                               value->c_expr,
                               tuple_expr,
                               field->c_name);
            }
        }
        return true;
    }

    if (cgtype_is_aggregate(field->type)) {
        const char *agg_desc = cg_aggregate_desc_name(field->type);
        char *field_descriptor = NULL;
        Buf lvalue;
        bool ok;

        if (agg_desc == NULL) {
            return cg_fail(cg,
                           blame,
                           "CE0060", "codegen: missing aggregate descriptor for tuple field '%s'",
                           field->feng_name);
        }
        buf_init(&lvalue);
        if (rad_desc_expr != NULL) {
            buf_append_fmt(&lvalue, "((char *)%s + %s->reified_field_offsets[%zu])",
                           tuple_expr, rad_desc_expr, field_index);
        } else {
            buf_append_fmt(&lvalue, "%s.%s", tuple_expr, field->c_name);
        }
        if (lvalue.data == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        field_descriptor = cg_aggregate_descriptor_expr_dup(cg,
                                                            field->type,
                                                            blame);
        if (field_descriptor == NULL) {
            buf_free(&lvalue);
            return false;
        }
        if (rad_desc_expr != NULL) {
            buf_append_fmt(cg->cur_body,
                           "    feng_aggregate_default_init((void *)%s, %s);\n",
                           lvalue.data, field_descriptor);
        } else {
            buf_append_cstr(cg->cur_body, "    ");
            ok = cg_append_aggregate_default_init_call(cg->cur_body, field->type, lvalue.data);
            buf_append_cstr(cg->cur_body, ";\n");
            if (!ok) {
                buf_free(&lvalue);
                free(field_descriptor);
                return cg_fail(cg,
                               blame,
                               "CE0061", "codegen: missing aggregate default-init rule for tuple field '%s'",
                               field->feng_name);
            }
        }
        if (!cg_prepare_aggregate_assign_source(cg, value, "_t")) {
            buf_free(&lvalue);
            free(field_descriptor);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (value->owns_ref) {
            buf_free(&lvalue);
            free(field_descriptor);
            return cg_fail(cg, blame, "CE0062", "codegen: internal tuple aggregate ownership state was not materialized");
        }
        if (cgtype_is_aggregate(value->type)) {
            char *source_address = cg_aggregate_result_address_dup(value);
            if (source_address == NULL) {
                buf_free(&lvalue);
                free(field_descriptor);
                return cg_fail(cg, blame, "CE0062", "codegen: tuple aggregate source has no address");
            }
            if (rad_desc_expr != NULL) {
                buf_append_fmt(cg->cur_body,
                               "    feng_aggregate_assign((void *)%s, %s, %s);\n",
                               lvalue.data,
                               source_address,
                               field_descriptor);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    feng_aggregate_assign(&%s, %s, %s);\n",
                               lvalue.data,
                               source_address,
                               field_descriptor);
            }
            free(source_address);
        } else {
            buf_free(&lvalue);
            free(field_descriptor);
            return cg_fail(cg, blame, "CE0063", "codegen: tuple aggregate field initializer type mismatch");
        }
        buf_free(&lvalue);
        free(field_descriptor);
        return true;
    }

    {
        char *cty = cg_ctype_dup(field->type);

        if (cty == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (rad_desc_expr != NULL) {
            if (cgtype_is_by_value_struct(field->type)) {
                buf_append_fmt(cg->cur_body,
                               "    memcpy((char *)%s + %s->reified_field_offsets[%zu], &%s, sizeof(%s));\n",
                               tuple_expr, rad_desc_expr, field_index,
                               value->c_expr, cty);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    *(%s *)((char *)%s + %s->reified_field_offsets[%zu]) = (%s)(%s);\n",
                               cty,
                               tuple_expr, rad_desc_expr, field_index,
                               cty,
                               value->c_expr);
            }
        } else if (cgtype_is_by_value_struct(field->type)) {
            buf_append_fmt(cg->cur_body,
                           "    %s.%s = %s;\n",
                           tuple_expr,
                           field->c_name,
                           value->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    %s.%s = (%s)(%s);\n",
                           tuple_expr,
                           field->c_name,
                           cty,
                           value->c_expr);
        }
        free(cty);
    }
    return true;
}

static bool cg_emit_tuple_literal_typed(CG *cg,
                                        const FengExpr *e,
                                        const CGType *expected_type,
                                        ExprResult *out) {
    er_init(out);
    if (e == NULL || e->kind != FENG_EXPR_TUPLE_LITERAL ||
        !cg_type_is_tuple_user(expected_type)) {
        return cg_fail(cg,
                       e != NULL ? e->token : (FengToken){0},
                       "CE0064", "codegen: tuple literal requires a named tuple target type");
    }

    const UserType *ut = expected_type->user;
    size_t item_count = e->as.tuple_literal.count;
    if (!cg_tuple_user_has_field_count(ut, item_count)) {
        return cg_fail(cg,
                       e->token,
                       "CE0065", "codegen: tuple literal arity does not match target tuple type '%s'",
                       ut->feng_name);
    }

    /* VLA path for tuples that depend on generic parameters in shared bodies. */
    if (cg_type_uses_reified_storage(cg, expected_type)) {
        char *tmp = cg_fresh_temp(cg, "_tuple");
        char *descriptor_name = NULL;
        char *size_name = NULL;
        if (tmp == NULL ||
            !cg_emit_reified_storage_declaration(cg,
                                                 expected_type,
                                                 tmp,
                                                 e->token,
                                                 &descriptor_name,
                                                 &size_name)) {
            free(tmp);
            free(descriptor_name);
            free(size_name);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
            "    feng_aggregate_default_init(%s, %s);\n",
            tmp,
            descriptor_name);

        for (size_t i = 0; i < item_count; ++i) {
            ExprResult value;
            if (!cg_emit_expr_for_expected_type(cg,
                                                e->as.tuple_literal.items[i],
                                                ut->fields[i].type,
                                                &value)) {
                free(tmp);
                free(descriptor_name);
                free(size_name);
                return false;
            }
            if (!cg_emit_tuple_field_value_store(cg, tmp, &ut->fields[i],
                                                  &value, e->token,
                                                  descriptor_name, i)) {
                er_free(&value);
                free(tmp);
                free(descriptor_name);
                free(size_name);
                return false;
            }
            er_free(&value);
        }

        out->c_expr = strdup(tmp);
        out->type = cgtype_clone(expected_type);
        out->owns_ref = true;
        out->is_addressable = true;
        out->is_storage_address = true;
        out->uses_reified_storage = true;
        out->reified_descriptor_c_name = descriptor_name;
        out->reified_size_c_name = size_name;
        free(tmp);
        return out->c_expr != NULL && out->type != NULL;
    }

    char *tmp = cg_fresh_temp(cg, "_tuple");
    char *cty = cg_ctype_dup(expected_type);
    if (tmp == NULL || cty == NULL) {
        free(tmp);
        free(cty);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, tmp);
    free(cty);
    buf_append_fmt(cg->cur_body, "    memset(&%s, 0, sizeof %s);\n", tmp, tmp);

    for (size_t i = 0; i < item_count; ++i) {
        ExprResult value;
        if (!cg_emit_expr_for_expected_type(cg,
                                            e->as.tuple_literal.items[i],
                                            ut->fields[i].type,
                                            &value)) {
            free(tmp);
            return false;
        }
        if (!cg_emit_tuple_field_value_store(cg, tmp, &ut->fields[i], &value, e->token,
                                                NULL, 0)) {
            er_free(&value);
            free(tmp);
            return false;
        }
        er_free(&value);
    }

    out->c_expr = strdup(tmp);
    out->type = cgtype_clone(expected_type);
    out->owns_ref = cgtype_is_aggregate(expected_type);
    free(tmp);
    return out->c_expr != NULL && out->type != NULL;
}

/* Box one statically known scalar, enum, tuple, or @value value. The returned
 * managed object uses the concrete ValueBox<T> descriptor and is owned by the
 * caller. Aggregate values preserve their existing retain semantics. */
static bool cg_emit_value_box_subject(CG *cg,
                                      ExprResult *source,
                                      FengToken blame,
                                      char **out_subject_expr) {
    char *box_tmp;
    CGValueBoxInfo box_info;

    if (source == NULL || source->type == NULL || out_subject_expr == NULL ||
        !cg_type_has_value_box(source->type)) {
        return cg_fail(cg, blame,
                       "CE0067", "codegen: value box emission is missing type metadata");
    }
    if (!cg_value_box_info_for_type(cg, source->type, blame, &box_info)) {
        return false;
    }

    if (cg_materialize_to_local(cg, source, "_value_subject") == NULL) {
        cg_value_box_info_dispose(&box_info);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    box_tmp = cg_fresh_temp(cg, "_value_box");
    if (box_tmp == NULL) {
        cg_value_box_info_dispose(&box_info);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    buf_append_fmt(cg->cur_body,
                   "    struct %s *%s = (struct %s *)feng_object_new(&%s);\n",
                   box_info.struct_name,
                   box_tmp,
                   box_info.struct_name,
                   box_info.descriptor_name);

    if (cgtype_is_aggregate(source->type)) {
        const char *desc = cg_aggregate_desc_name(source->type);

        if (desc == NULL) {
            free(box_tmp);
            cg_value_box_info_dispose(&box_info);
            return cg_fail(cg, blame, "CE0068", "codegen: missing value-type aggregate descriptor for spec coercion");
        }
        buf_append_fmt(cg->cur_body,
                       "    feng_aggregate_assign(&%s->value, &%s, &%s);\n",
                       box_tmp,
                       source->c_expr,
                       desc);
    } else {
        buf_append_fmt(cg->cur_body,
                       "    %s->value = %s;\n",
                       box_tmp,
                       source->c_expr);
    }

    cg_value_box_info_dispose(&box_info);
    *out_subject_expr = box_tmp;
    return true;
}

static bool cg_emit_tuple_cast_to_type(CG *cg,
                                       const FengExpr *e,
                                       const CGType *target,
                                       ExprResult *out) {
    ExprResult source;

    er_init(out);
    if (e->kind == FENG_EXPR_TUPLE_LITERAL) {
        return cg_emit_tuple_literal_typed(cg, e, target, out);
    }
    if (!cg_emit_expr(cg, e, &source)) {
        return false;
    }
    if (!cg_type_is_tuple_user(source.type)) {
        er_free(&source);
        return cg_fail(cg, e->token, "CE0069", "codegen: tuple cast source must be a tuple value");
    }
    if (source.type->user == target->user) {
        cgtype_free(source.type);
        source.type = cgtype_clone(target);
        *out = source;
        return out->type != NULL;
    }
    if (!cg_tuple_user_has_field_count(source.type->user, target->user->field_count)) {
        er_free(&source);
        return cg_fail(cg, e->token, "CE0070", "codegen: tuple cast arity mismatch");
    }

    if (cg_materialize_to_local(cg, &source, "_tuple_src") == NULL) {
        er_free(&source);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    char *tmp = cg_fresh_temp(cg, "_tuple_cast");
    char *cty = cg_ctype_dup(target);
    if (tmp == NULL || cty == NULL) {
        free(tmp);
        free(cty);
        er_free(&source);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, tmp);
    free(cty);

    if (target->user->field_count == 0U) {
        buf_append_fmt(cg->cur_body, "    memset(&%s, 0, sizeof %s);\n", tmp, tmp);
    }

    for (size_t i = 0; i < target->user->field_count; ++i) {
        ExprResult field_value;
        Buf field_expr;

        er_init(&field_value);
        buf_init(&field_expr);
        buf_append_fmt(&field_expr,
                       "%s.%s",
                       source.c_expr,
                       source.type->user->fields[i].c_name);
        field_value.c_expr = field_expr.data;
        field_value.type = cgtype_clone(target->user->fields[i].type);
        field_value.owns_ref = false;
        field_value.is_addressable = true;
        if (field_value.c_expr == NULL || field_value.type == NULL) {
            er_free(&field_value);
            free(tmp);
            er_free(&source);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        if (!cg_emit_tuple_field_value_store(cg,
                                             tmp,
                                             &target->user->fields[i],
                                             &field_value,
                                             e->token,
                                             NULL, 0)) {
            er_free(&field_value);
            free(tmp);
            er_free(&source);
            return false;
        }
        er_free(&field_value);
    }

    out->c_expr = strdup(tmp);
    out->type = cgtype_clone(target);
    out->owns_ref = cgtype_is_aggregate(target);
    free(tmp);
    er_free(&source);
    return out->c_expr != NULL && out->type != NULL;
}

static bool cg_emit_imported_binding_expr(CG *cg,
                                          const FengDecl *decl,
                                          ExprResult *out) {
    char *slot_name = NULL;
    char *ensure_init_name = NULL;

    if (cg == NULL || decl == NULL || out == NULL ||
        decl->kind != FENG_DECL_GLOBAL_BINDING) {
        return false;
    }
    if (!cg_binding_public_surface_names(cg, decl, &slot_name, &ensure_init_name)) {
        return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    }
    if (!cg_resolve_global_binding_type(cg, decl, &out->type)) {
        free(slot_name);
        free(ensure_init_name);
        return false;
    }
    buf_append_fmt(cg->cur_body, "    %s();\n", ensure_init_name);
    out->c_expr = slot_name;
    out->owns_ref = false;
    out->managed_identity_is_stable =
        decl->as.binding.mutability != FENG_MUTABILITY_VAR;
    out->is_addressable = true;
    free(ensure_init_name);
    return true;
}

static bool cg_emit_imported_binding_assign(CG *cg,
                                            const FengDecl *decl,
                                            const FengStmt *stmt,
                                            bool is_compound,
                                            FengTokenKind binary_op) {
    CGType *binding_type = NULL;
    char *slot_name = NULL;
    char *ensure_init_name = NULL;

    if (cg == NULL || decl == NULL || stmt == NULL ||
        decl->kind != FENG_DECL_GLOBAL_BINDING) {
        return false;
    }
    if (decl->as.binding.mutability != FENG_MUTABILITY_VAR) {
        return cg_fail(cg, stmt->token,
            "CE0071", "codegen: cannot assign to immutable imported binding '%.*s'",
            (int)decl->as.binding.name.length,
            decl->as.binding.name.data);
    }
    if (!cg_binding_public_surface_names(cg, decl, &slot_name, &ensure_init_name)) {
        return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    }
    if (!cg_resolve_global_binding_type(cg, decl, &binding_type)) {
        free(slot_name);
        free(ensure_init_name);
        return false;
    }

    buf_append_fmt(cg->cur_body, "    %s();\n", ensure_init_name);

    if (is_compound) {
        char *cty = cg_ctype_dup(binding_type);
        char *old_tmp = NULL;
        ExprResult v;
        Buf expr;

        if (!cty || !cgtype_is_numeric(binding_type->kind)) {
            free(cty);
            cgtype_free(binding_type);
            free(slot_name);
            free(ensure_init_name);
            return cg_fail(cg, stmt->token,
                "CE0072", "codegen: compound assignment requires a numeric binding type");
        }

        old_tmp = cg_fresh_temp(cg, "_old");
        if (!old_tmp) {
            free(cty);
            cgtype_free(binding_type);
            free(slot_name);
            free(ensure_init_name);
            return false;
        }

        buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, old_tmp, slot_name);
        if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
            free(old_tmp);
            free(cty);
            cgtype_free(binding_type);
            free(slot_name);
            free(ensure_init_name);
            return false;
        }

        buf_init(&expr);
        if (!cg_append_numeric_op_expr(&expr,
                                       binding_type->kind,
                                       old_tmp,
                                       binary_op,
                                       v.c_expr)) {
            buf_free(&expr);
            er_free(&v);
            free(old_tmp);
            free(cty);
            cgtype_free(binding_type);
            free(slot_name);
            free(ensure_init_name);
            return cg_fail(cg, stmt->token,
                "CE0073", "codegen: unsupported compound assignment operator");
        }

        buf_append_fmt(cg->cur_body, "    %s = (%s)(%s);\n",
                       slot_name, cty, expr.data);

        buf_free(&expr);
        er_free(&v);
        free(old_tmp);
        free(cty);
        cgtype_free(binding_type);
        free(slot_name);
        free(ensure_init_name);
        return true;
    }

    ExprResult v;
    if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
        cgtype_free(binding_type);
        free(slot_name);
        free(ensure_init_name);
        return false;
    }
    if (cgtype_is_managed(binding_type)) {
        if (v.owns_ref) {
            buf_append_fmt(cg->cur_body,
                "    { void *_old = %s; %s = %s; feng_release(_old); }\n",
                slot_name, slot_name, v.c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "    feng_assign((void**)&%s, %s);\n",
                slot_name, v.c_expr);
        }
    } else if (cgtype_is_aggregate(binding_type)) {
        const char *aggregate_desc = cg_aggregate_desc_name(binding_type);

        if (aggregate_desc == NULL) {
            er_free(&v);
            cgtype_free(binding_type);
            free(slot_name);
            free(ensure_init_name);
            return cg_fail(cg,
                           stmt->token,
                           "CE0074", "codegen: missing aggregate descriptor for assignment");
        }
        if (!cg_prepare_aggregate_assign_source(cg, &v, "_t")) {
            er_free(&v);
            cgtype_free(binding_type);
            free(slot_name);
            free(ensure_init_name);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
            "    feng_aggregate_assign(&%s, &%s, &%s);\n",
            slot_name,
            v.c_expr,
            aggregate_desc);
    } else {
        char *cty = cg_ctype_dup(binding_type);
        buf_append_fmt(cg->cur_body, "    %s = (%s)(%s);\n",
                       slot_name, cty, v.c_expr);
        free(cty);
    }
    er_free(&v);
    cgtype_free(binding_type);
    free(slot_name);
    free(ensure_init_name);
    return true;
}

static void er_free(ExprResult *r) {
    if (!r) return;
    free(r->c_expr);
    free(r->erased_generic_descriptor_c_name);
    free(r->erased_generic_size_c_name);
    free(r->reified_descriptor_c_name);
    free(r->reified_size_c_name);
    cgtype_free(r->type);
    r->c_expr = NULL;
    r->type = NULL;
    r->owns_ref = false;
    r->managed_identity_is_stable = false;
    r->is_addressable = false;
    r->is_storage_address = false;
    r->uses_erased_generic_storage = false;
    r->erased_generic_descriptor_c_name = NULL;
    r->erased_generic_size_c_name = NULL;
    r->uses_reified_storage = false;
    r->reified_descriptor_c_name = NULL;
    r->reified_size_c_name = NULL;
}

/* Resolve the aggregate descriptor authority for one value. Shared generic
 * bodies use their concrete dependency entry; ordinary bodies use the static
 * descriptor. The returned expression is owned. */
static char *cg_aggregate_descriptor_expr_dup(CG *cg,
                                              const CGType *type,
                                              FengToken blame) {
    const char *aggregate_name;
    const char *source;
    size_t index;
    Buf expression;

    aggregate_name = cg_aggregate_desc_name(type);
    if (aggregate_name == NULL) {
        cg_fail(cg, blame,
                "CE0066", "codegen: aggregate value requires a descriptor");
        return NULL;
    }
    buf_init(&expression);
    if (cg_value_needs_reified_layout(cg, type) &&
        cg_lookup_reified_agg_dep_index(cg, aggregate_name, &index)) {
        source = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
        buf_append_fmt(
            &expression,
            "((const FengAggregateDescriptor *)%s->reified_agg_deps[%zu])",
            source,
            index);
    } else {
        buf_append_fmt(&expression, "&%s", aggregate_name);
    }
    return expression.data;
}

/* Resolve the concrete descriptor required by descriptor-sized storage. */
static char *cg_reified_aggregate_descriptor_expr_dup(CG *cg,
                                                      const CGType *type,
                                                      FengToken blame) {
    const char *aggregate_name;
    size_t index;

    if (!cg_type_uses_reified_storage(cg, type)) {
        return NULL;
    }
    aggregate_name = cg_aggregate_desc_name(type);
    if (aggregate_name == NULL ||
        !cg_lookup_reified_agg_dep_index(cg, aggregate_name, &index)) {
        cg_fail(cg, blame,
                "CE0066", "codegen: descriptor-sized storage requires a concrete descriptor dependency");
        return NULL;
    }
    return cg_aggregate_descriptor_expr_dup(cg, type, blame);
}

/* Declare one zeroed, descriptor-sized aggregate local and cache the single
 * descriptor/size reads used by all subsequent operations on that local. */
static bool cg_emit_reified_storage_declaration(CG *cg,
                                                const CGType *type,
                                                const char *storage_c_name,
                                                FengToken blame,
                                                char **out_descriptor_c_name,
                                                char **out_size_c_name) {
    char *descriptor_expr;
    char *descriptor_name;
    char *size_name;

    if (cg == NULL || type == NULL || storage_c_name == NULL ||
        out_descriptor_c_name == NULL || out_size_c_name == NULL) {
        return false;
    }
    descriptor_expr = cg_reified_aggregate_descriptor_expr_dup(cg, type, blame);
    descriptor_name = cg_fresh_temp(cg, "_rad");
    size_name = cg_fresh_temp(cg, "_rsize");
    if (descriptor_expr == NULL || descriptor_name == NULL || size_name == NULL) {
        free(descriptor_expr);
        free(descriptor_name);
        free(size_name);
        if (!cg->failed) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        return false;
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    const FengAggregateDescriptor *%s = %s;\n"
                   "    const size_t %s = %s->size;\n"
                   "    _Alignas(max_align_t) char %s[%s];\n"
                   "    memset(%s, 0, %s);\n",
                   descriptor_name,
                   descriptor_expr,
                   size_name,
                   descriptor_name,
                   storage_c_name,
                   size_name,
                   storage_c_name,
                   size_name);
    free(descriptor_expr);
    *out_descriptor_c_name = descriptor_name;
    *out_size_c_name = size_name;
    return true;
}

/* Declare exact stack storage from one runtime generic descriptor expression.
 * Descriptor and size expressions are each evaluated once. Supplying an
 * existing size expression preserves the descriptor authority already
 * attached to captured or forwarded erased storage. */
static bool cg_emit_erased_generic_storage_declaration_from_descriptor(
    CG *cg,
    const char *descriptor_c_expr,
    const char *size_c_expr,
    const char *storage_c_name,
    FengToken blame,
    char **out_descriptor_c_name,
    char **out_size_c_name) {
    char *descriptor_name;
    char *size_name;

    if (cg == NULL || descriptor_c_expr == NULL || storage_c_name == NULL ||
        out_descriptor_c_name == NULL || out_size_c_name == NULL) {
        return false;
    }
    descriptor_name = cg_fresh_temp(cg, "_gpd");
    size_name = cg_fresh_temp(cg, "_gsize");
    if (descriptor_name == NULL || size_name == NULL) {
        free(descriptor_name);
        free(size_name);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    const FengGenericParamDescriptor *%s = %s;\n",
                   descriptor_name,
                   descriptor_c_expr);
    if (size_c_expr != NULL) {
        buf_append_fmt(cg->cur_body,
                       "    const size_t %s = %s;\n",
                       size_name,
                       size_c_expr);
    } else {
        buf_append_fmt(cg->cur_body,
                       "    const size_t %s = feng_generic_value_size(%s);\n",
                       size_name,
                       descriptor_name);
    }
    buf_append_fmt(cg->cur_body,
                   "    _Alignas(max_align_t) char %s[%s];\n"
                   "    memset(%s, 0, %s);\n",
                   storage_c_name,
                   size_name,
                   storage_c_name,
                   size_name);
    *out_descriptor_c_name = descriptor_name;
    *out_size_c_name = size_name;
    return true;
}

/* Declare exact stack storage for one direct generic parameter value. The
 * active hidden parameter descriptor supplies the representation authority. */
static bool cg_emit_erased_generic_storage_declaration(
    CG *cg,
    const CGType *type,
    const char *storage_c_name,
    FengToken blame,
    char **out_descriptor_c_name,
    char **out_size_c_name) {
    const char *descriptor_expr;

    if (cg == NULL || type == NULL ||
        type->kind != CG_TYPE_GENERIC_PARAM) {
        return false;
    }
    descriptor_expr = cg_generic_param_desc_name(
        cg, type->generic_param_index);
    if (descriptor_expr == NULL) {
        return cg_fail(cg,
                       blame,
                       "CE0237", "codegen: missing generic descriptor for erased storage");
    }
    return cg_emit_erased_generic_storage_declaration_from_descriptor(
        cg,
        descriptor_expr,
        NULL,
        storage_c_name,
        blame,
        out_descriptor_c_name,
        out_size_c_name);
}

/* Cache the descriptor for one borrowed address-form parameter. The
 * parameter already points at caller-owned exact storage, so it requires no
 * size read, local allocation or copy. */
static bool cg_emit_reified_parameter_descriptor(CG *cg,
                                                 const CGType *type,
                                                 FengToken blame,
                                                 char **out_descriptor_c_name) {
    char *descriptor_expr;
    char *descriptor_name;

    if (cg == NULL || type == NULL || out_descriptor_c_name == NULL) {
        return false;
    }
    descriptor_expr = cg_reified_aggregate_descriptor_expr_dup(cg, type, blame);
    descriptor_name = cg_fresh_temp(cg, "_prad");
    if (descriptor_expr == NULL || descriptor_name == NULL) {
        free(descriptor_expr);
        free(descriptor_name);
        if (!cg->failed) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        return false;
    }
    buf_append_fmt(cg->cur_body,
                   "    const FengAggregateDescriptor *%s = %s;\n",
                   descriptor_name,
                   descriptor_expr);
    free(descriptor_expr);
    *out_descriptor_c_name = descriptor_name;
    return true;
}

/* Record the representation of one parameter received through the shared
 * generic address ABI. A dynamic aggregate also caches its lifecycle
 * descriptor; a direct generic parameter needs only the compile-time fact
 * that its C expression is already a storage address. */
static bool cg_mark_last_shared_address_parameter(CG *cg,
                                                  Scope *scope,
                                                  const CGType *type,
                                                  FengToken blame) {
    char *descriptor_name = NULL;
    bool ok;

    if (!cg_shared_generic_param_uses_address(type)) {
        return true;
    }
    if (!cg_type_uses_reified_storage(cg, type)) {
        return scope_mark_last_storage_address(scope);
    }
    ok = cg_emit_reified_parameter_descriptor(cg,
                                               type,
                                               blame,
                                               &descriptor_name) &&
         scope_mark_last_reified_storage(scope, descriptor_name, NULL);
    free(descriptor_name);
    if (!ok && !cg->failed) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    return ok;
}

/* Return an owned C expression for the address of an aggregate result. */
static char *cg_aggregate_result_address_dup(const ExprResult *result) {
    Buf address;

    if (result == NULL || result->c_expr == NULL) {
        return NULL;
    }
    buf_init(&address);
    if (result->is_storage_address) {
        buf_append_fmt(&address, "(void *)%s", result->c_expr);
    } else if (result->is_addressable) {
        buf_append_fmt(&address, "(void *)&(%s)", result->c_expr);
    } else {
        return NULL;
    }
    return address.data;
}

/* Evaluate one fixed-layout C value exactly once without changing its Feng
 * ownership. No cleanup is registered: the caller must immediately transfer
 * an owned result or otherwise attach it to ordinary cleanup storage. */
static bool cg_materialize_ownership_alias(CG *cg,
                                           ExprResult *result,
                                           const char *prefix) {
    char *temporary;
    char *ctype;

    if (cg == NULL || result == NULL || result->type == NULL ||
        result->c_expr == NULL || result->is_storage_address ||
        result->uses_erased_generic_storage ||
        result->uses_reified_storage ||
        result->type->kind == CG_TYPE_GENERIC_PARAM) {
        return false;
    }
    temporary = cg_fresh_temp(cg, prefix);
    ctype = cg_ctype_dup(result->type);
    if (temporary == NULL || ctype == NULL) {
        free(temporary);
        free(ctype);
        return false;
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    %s %s = %s;\n",
                   ctype,
                   temporary,
                   result->c_expr);
    free(ctype);
    free(result->c_expr);
    result->c_expr = temporary;
    result->is_addressable = true;
    return true;
}

/* Materialise an ExprResult into a fresh C local so its lifetime spans the
 * current statement. For managed +1 results this also schedules a release at
 * the end of the local scope by registering the local in the scope. For
 * non-managed values, it simply binds to a temp.
 *
 * Returns the C expression (identifier of the local), via *out_cexpr (malloc'd
 * by caller's responsibility — caller must free). The type is transferred to
 * the local in scope so the caller MUST NOT use r->type afterwards. */
static char *cg_materialize_to_local(CG *cg, ExprResult *r, const char *prefix) {
    if (r != NULL && r->type != NULL &&
        r->type->kind == CG_TYPE_GENERIC_PARAM) {
        char *storage_name = cg_fresh_temp(cg, prefix);
        char *descriptor_name = NULL;
        char *size_name = NULL;

        if (storage_name == NULL ||
            !cg_emit_erased_generic_storage_declaration(
                cg,
                r->type,
                storage_name,
                (FengToken){0},
                &descriptor_name,
                &size_name)) {
            free(storage_name);
            free(descriptor_name);
            free(size_name);
            return NULL;
        }
        cg_emit_current_stmt_line_directive_force(cg);
        buf_append_fmt(cg->cur_body,
            "    switch (%s->kind) {\n"
            "        case FENG_VALUE_TRIVIAL:\n"
            "            memcpy(%s, %s, %s);\n"
            "            break;\n"
            "        case FENG_VALUE_MANAGED_POINTER: {\n"
            "            void *_generic_value = *(void *const *)%s;\n",
            descriptor_name,
            storage_name,
            r->c_expr,
            size_name,
            r->c_expr);
        if (r->owns_ref) {
            buf_append_fmt(cg->cur_body,
                "            *(void **)%s = _generic_value;\n"
                "            *(void **)%s = NULL;\n",
                storage_name,
                r->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "            feng_retain(_generic_value);\n"
                "            *(void **)%s = _generic_value;\n",
                storage_name);
        }
        buf_append_fmt(cg->cur_body,
            "            break;\n"
            "        }\n"
            "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n");
        if (r->owns_ref) {
            buf_append_fmt(cg->cur_body,
                "            memcpy(%s, %s, %s);\n"
                "            memset(%s, 0, %s);\n",
                storage_name,
                r->c_expr,
                size_name,
                r->c_expr,
                size_name);
        } else {
            buf_append_fmt(cg->cur_body,
                "            feng_aggregate_assign(%s, %s, "
                "feng_generic_aggregate_descriptor(%s));\n",
                storage_name,
                r->c_expr,
                descriptor_name);
        }
        buf_append_cstr(cg->cur_body,
            "            break;\n"
            "    }\n");
        if (!cg_register_erased_generic_storage_for_cleanup(
                cg,
                storage_name,
                r->type,
                descriptor_name,
                size_name,
                (FengToken){0})) {
            free(storage_name);
            free(descriptor_name);
            free(size_name);
            return NULL;
        }
        free(r->c_expr);
        free(r->erased_generic_descriptor_c_name);
        free(r->erased_generic_size_c_name);
        r->c_expr = strdup(storage_name);
        r->erased_generic_descriptor_c_name = strdup(descriptor_name);
        r->erased_generic_size_c_name = strdup(size_name);
        r->owns_ref = false;
        r->is_addressable = true;
        r->is_storage_address = true;
        r->uses_erased_generic_storage = true;
        free(descriptor_name);
        free(size_name);
        if (r->c_expr == NULL ||
            r->erased_generic_descriptor_c_name == NULL ||
            r->erased_generic_size_c_name == NULL) {
            free(storage_name);
            return NULL;
        }
        return storage_name;
    }
    if (cg_type_uses_reified_storage(cg, r->type)) {
        char *storage_name = NULL;
        char *descriptor_name = NULL;
        char *size_name = NULL;
        char *source_address = NULL;
        char *scope_name = cg_fresh_temp(cg, prefix);

        if (scope_name == NULL) {
            return NULL;
        }
        if (r->owns_ref && r->uses_reified_storage) {
            /* The producer already created the exact descriptor-sized slot.
             * Adopt it directly: no second descriptor load and no copy. */
            storage_name = strdup(r->c_expr);
            descriptor_name = r->reified_descriptor_c_name != NULL
                                  ? strdup(r->reified_descriptor_c_name)
                                  : NULL;
            size_name = r->reified_size_c_name != NULL
                            ? strdup(r->reified_size_c_name)
                            : NULL;
            if (storage_name == NULL || descriptor_name == NULL || size_name == NULL) {
                free(storage_name);
                free(descriptor_name);
                free(size_name);
                free(scope_name);
                return NULL;
            }
        } else {
            storage_name = cg_fresh_temp(cg, prefix);
            if (storage_name == NULL ||
                !cg_emit_reified_storage_declaration(cg,
                                                     r->type,
                                                     storage_name,
                                                     (FengToken){0},
                                                     &descriptor_name,
                                                     &size_name)) {
                free(storage_name);
                free(descriptor_name);
                free(size_name);
                free(scope_name);
                return NULL;
            }
            source_address = cg_aggregate_result_address_dup(r);
            if (source_address == NULL) {
                free(storage_name);
                free(descriptor_name);
                free(size_name);
                free(scope_name);
                return NULL;
            }
            cg_emit_current_stmt_line_directive_force(cg);
            if (r->owns_ref) {
                buf_append_fmt(cg->cur_body,
                               "    feng_aggregate_take(%s, %s, %s);\n",
                               storage_name,
                               source_address,
                               descriptor_name);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    feng_aggregate_assign(%s, %s, %s);\n",
                               storage_name,
                               source_address,
                               descriptor_name);
            }
            free(source_address);
        }

        if (!scope_add(cg->cur_scope,
                       scope_name,
                       storage_name,
                       cgtype_clone(r->type),
                       false) ||
            !scope_mark_last_reified_storage(cg->cur_scope,
                                             descriptor_name,
                                             size_name)) {
            free(storage_name);
            free(descriptor_name);
            free(size_name);
            free(scope_name);
            return NULL;
        }
        cg_emit_cleanup_push_for_reified_aggregate_storage(cg,
                                                           storage_name,
                                                           descriptor_name);
        free(r->c_expr);
        free(r->reified_descriptor_c_name);
        free(r->reified_size_c_name);
        r->c_expr = strdup(storage_name);
        r->reified_descriptor_c_name = strdup(descriptor_name);
        r->reified_size_c_name = strdup(size_name);
        r->owns_ref = false;
        r->is_addressable = true;
        r->is_storage_address = true;
        r->uses_reified_storage = true;
        free(descriptor_name);
        free(size_name);
        free(scope_name);
        if (r->c_expr == NULL || r->reified_descriptor_c_name == NULL ||
            r->reified_size_c_name == NULL) {
            free(storage_name);
            return NULL;
        }
        return storage_name;
    }

    if (cgtype_is_aggregate(r->type) && r->owns_ref &&
        r->is_addressable) {
        char *storage_name = strdup(r->c_expr);
        char *scope_name = cg_fresh_temp(cg, prefix);

        /* Owned fixed-layout aggregate producers already materialize into a
         * unique C local. Adopt that storage directly instead of copying it
         * into a second temporary solely to attach Feng cleanup metadata. */
        if (storage_name == NULL || scope_name == NULL ||
            !scope_add(cg->cur_scope,
                       scope_name,
                       storage_name,
                       cgtype_clone(r->type),
                       false)) {
            free(storage_name);
            free(scope_name);
            return NULL;
        }
        cg_emit_cleanup_push_for_aggregate_local(cg,
                                                 storage_name,
                                                 r->type);
        r->owns_ref = false;
        free(scope_name);
        return storage_name;
    }

    bool adopts_owned_managed_identity =
        cgtype_is_managed(r->type) && r->owns_ref;
    char *tmp = cg_fresh_temp(cg, prefix);
    if (!tmp) return NULL;
    char *cty = cg_ctype_dup(r->type);
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, r->c_expr);
    free(cty);
    if (cgtype_is_managed(r->type) && r->owns_ref) {
        /* Register in scope so it gets released on scope exit. The scope
         * takes ownership of a clone so r->type remains valid for callers
         * that still need to inspect (e.g., extern arg coercions). */
        scope_add(cg->cur_scope, tmp, tmp, cgtype_clone(r->type), false);
        cg_emit_cleanup_push_for_managed_local(cg, tmp);
    } else if (cgtype_is_managed(r->type)) {
        /* Borrowed: don't register for release. */
    } else if (cgtype_is_aggregate(r->type)) {
        /* Step 4b — fat spec value.  Two sub-cases:
         *
         * owns_ref=true  (inline expression, e.g. cg_emit_registered_call):
         *   The C struct copy above is the sole owner of the +1 reference;
         *   no retain needed.  Just register the copy for cleanup.
         *
         * owns_ref=false (out-param temp, e.g. cg_emit_generic_call path 1):
         *   The source variable already has its own cleanup registration
         *   that will release the subject.  The bare copy above aliases the
         *   source's subject pointer without incrementing its refcount, so
         *   retain here to give the copy an independent +1. */
        if (!r->owns_ref) {
            if (cg_value_needs_reified_layout(cg, r->type)) {
                const char *agg_desc = cg_aggregate_desc_name(r->type);
                size_t rad_idx;
                if (agg_desc &&
                    cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                    const char *src = cg->generic_type_method_rad_via_desc
                                          ? "_desc" : "_td";
                    cg_emit_current_stmt_line_directive_force(cg);
                    buf_append_fmt(cg->cur_body,
                        "    feng_aggregate_retain(&%s, "
                        "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]);\n",
                        tmp, src, rad_idx);
                }
            } else {
                const char *desc = cg_aggregate_desc_name(r->type);
                if (desc) {
                    cg_emit_current_stmt_line_directive_force(cg);
                    buf_append_fmt(cg->cur_body,
                                   "    feng_aggregate_retain(&%s, &%s);\n", tmp, desc);
                }
            }
        }
        scope_add(cg->cur_scope, tmp, tmp, cgtype_clone(r->type), false);
        cg_emit_cleanup_push_for_aggregate_local(cg, tmp, r->type);
    }
    /* Free r->c_expr; r->type is preserved so caller-side decisions that
     * branch on the source type (e.g., extern STRING wrapping) keep
     * working. */
    free(r->c_expr);
    r->c_expr = strdup(tmp);
    r->owns_ref = false;
    if (adopts_owned_managed_identity) {
        /* The scope-tracked local now owns the former +1 result, so later
         * code cannot invalidate this reference by rebinding another slot. */
        r->managed_identity_is_stable = true;
    }
    r->is_addressable = true;
    return tmp;
}

/* Prepare one explicit parameter for an address-based shared callable ABI.
 *
 * A direct open generic parameter needs runtime representation selection.
 * Trivial values are byte-copied, managed pointers copy only the borrowed
 * reference value, and managed aggregates receive an owning aggregate copy.
 * Closed value-semantics types use the ordinary aggregate materialisation
 * path, so their generated work matches a normal by-value copy. The implicit
 * self receiver never enters this helper and remains an address to the
 * original receiver storage. */
static bool cg_materialize_shared_callable_value_argument(
    CG *cg,
    ExprResult *argument,
    const char *prefix) {
    char *storage_name = NULL;
    char *descriptor_name = NULL;
    char *size_name = NULL;
    char *source_address = NULL;

    if (cg == NULL || argument == NULL || argument->type == NULL) {
        return false;
    }
    if (argument->type->kind != CG_TYPE_GENERIC_PARAM) {
        if (cg_type_is_value_semantics(argument->type) ||
            (!cgtype_is_managed(argument->type) &&
             !cgtype_is_aggregate(argument->type))) {
            return cg_materialize_to_local(cg, argument, prefix) != NULL;
        }
        return true;
    }

    /* Preserve an owned producer result before deriving the independent
     * parameter copy. This also gives a non-addressable result stable source
     * storage and transfers its cleanup responsibility to the current scope. */
    if ((argument->owns_ref || !argument->is_addressable) &&
        cg_materialize_to_local(cg, argument, prefix) == NULL) {
        return false;
    }
    source_address = cg_aggregate_result_address_dup(argument);
    storage_name = cg_fresh_temp(cg, prefix);
    const char *descriptor_expr = argument->uses_erased_generic_storage
        ? argument->erased_generic_descriptor_c_name
        : cg_generic_param_desc_name(
              cg, argument->type->generic_param_index);
    const char *size_expr = argument->uses_erased_generic_storage
        ? argument->erased_generic_size_c_name
        : NULL;
    if (source_address == NULL || storage_name == NULL ||
        descriptor_expr == NULL ||
        !cg_emit_erased_generic_storage_declaration_from_descriptor(
            cg,
            descriptor_expr,
            size_expr,
            storage_name,
            (FengToken){0},
            &descriptor_name,
            &size_name)) {
        free(source_address);
        free(storage_name);
        free(descriptor_name);
        free(size_name);
        return false;
    }

    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
        "    switch (%s->kind) {\n"
        "        case FENG_VALUE_TRIVIAL:\n"
        "            memcpy(%s, %s, %s);\n"
        "            break;\n"
        "        case FENG_VALUE_MANAGED_POINTER:\n"
        "            *(void **)%s = *(void *const *)%s;\n"
        "            break;\n"
        "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
        "            feng_aggregate_assign(%s, %s, "
        "feng_generic_aggregate_descriptor(%s));\n"
        "            break;\n"
        "    }\n",
        descriptor_name,
        storage_name,
        source_address,
        size_name,
        storage_name,
        source_address,
        storage_name,
        source_address,
        descriptor_name);
    if (!cg_register_erased_generic_argument_storage_for_cleanup(
            cg,
            storage_name,
            argument->type,
            descriptor_name,
            size_name,
            (FengToken){0})) {
        free(source_address);
        free(storage_name);
        free(descriptor_name);
        free(size_name);
        return false;
    }

    free(argument->c_expr);
    free(argument->erased_generic_descriptor_c_name);
    free(argument->erased_generic_size_c_name);
    argument->c_expr = strdup(storage_name);
    argument->erased_generic_descriptor_c_name = strdup(descriptor_name);
    argument->erased_generic_size_c_name = strdup(size_name);
    argument->owns_ref = false;
    argument->is_addressable = true;
    argument->is_storage_address = true;
    argument->uses_erased_generic_storage = true;
    free(source_address);
    free(storage_name);
    free(descriptor_name);
    free(size_name);
    return argument->c_expr != NULL &&
           argument->erased_generic_descriptor_c_name != NULL &&
           argument->erased_generic_size_c_name != NULL;
}

/* Ensure that an aggregate source can be passed to a pointer-based runtime
 * operation. Owned results use the regular managed temporary path. A borrowed
 * C rvalue needs only a statement-local shallow copy: the destination
 * operation retains its managed slots before the borrowed owner can expire. */
static bool cg_prepare_aggregate_assign_source(CG *cg,
                                               ExprResult *source,
                                               const char *prefix) {
    char *tmp;
    char *ctype;

    if (cg == NULL || source == NULL || source->type == NULL ||
        !cgtype_is_aggregate(source->type)) {
        return false;
    }
    if (source->owns_ref) {
        return cg_materialize_to_local(cg, source, prefix) != NULL;
    }
    if (cg_type_uses_reified_storage(cg, source->type)) {
        if (source->uses_reified_storage) {
            return true;
        }
        return cg_materialize_to_local(cg, source, prefix) != NULL;
    }
    if (source->is_addressable) {
        return true;
    }

    tmp = cg_fresh_temp(cg, prefix);
    ctype = cg_ctype_dup(source->type);
    if (tmp == NULL || ctype == NULL) {
        free(tmp);
        free(ctype);
        return false;
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    %s %s = %s;\n",
                   ctype,
                   tmp,
                   source->c_expr);
    free(ctype);
    free(source->c_expr);
    source->c_expr = tmp;
    source->is_addressable = true;
    return true;
}

/* Prepare an aggregate for replacement of persistent storage. An owned
 * fixed-layout result remains owned and is exposed through a shallow C alias
 * for `feng_aggregate_take`; a borrowed result follows the ordinary
 * `feng_aggregate_assign` preparation path. */
static bool cg_prepare_aggregate_store_source(CG *cg,
                                              ExprResult *source,
                                              const char *prefix,
                                              bool *out_take_source) {
    bool take_source;

    if (cg == NULL || source == NULL || source->type == NULL ||
        !cgtype_is_aggregate(source->type) || out_take_source == NULL) {
        return false;
    }
    take_source = source->owns_ref;
    *out_take_source = take_source;
    if (!take_source) {
        return cg_prepare_aggregate_assign_source(cg, source, prefix);
    }
    if (source->is_storage_address || source->is_addressable) {
        return true;
    }
    if (cg_type_uses_reified_storage(cg, source->type)) {
        /* Reified storage needs its descriptor-sized materialization. Keep
         * the pre-materialization ownership decision so the caller still
         * moves from the registered, subsequently zeroed source slot. */
        return cg_materialize_to_local(cg, source, prefix) != NULL;
    }
    return cg_materialize_ownership_alias(cg, source, prefix);
}

/* C symbol for the source package's ordinary implicit-construction entry.
 * Its reserved no-suffix spelling is distinct from explicit constructor
 * overload symbols and is used only when no constructor is declared. */
static char *cg_implicit_constructor_cname(const UserType *type) {
    Buf name;
    char *type_name;

    if (type == NULL || type->decl == NULL ||
        type->decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    type_name = cg_sanitize(type->decl->as.type_decl.name.data,
                            type->decl->as.type_decl.name.length);
    if (type_name == NULL) {
        return NULL;
    }
    buf_init(&name);
    buf_append_fmt(&name,
                   "%s__ctor__%s",
                   type->c_struct_name,
                   type_name);
    free(type_name);
    return name.data;
}

/* Build one stable provider/consumer ABI symbol for a generated generic
 * owner helper. */
static char *cg_generic_owner_helper_cname(
    CG *cg,
    const FengDecl *decl,
    const char *role) {
    const GenericTypeDecl *generic_decl;
    const FengProgram *owner_program;
    char *owner_mangle;
    char *type_name;
    Buf name;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_TYPE ||
        role == NULL) {
        return NULL;
    }
    generic_decl = cg_find_generic_type_decl_by_decl(cg, decl);
    owner_program = generic_decl != NULL
        ? generic_decl->owner_program
        : cg->cur_program;
    owner_mangle = owner_program != NULL
        ? cg_module_mangle(owner_program->module_segments,
                           owner_program->module_segment_count)
        : NULL;
    type_name = cg_sanitize(decl->as.type_decl.name.data,
                            decl->as.type_decl.name.length);
    if (owner_mangle == NULL || type_name == NULL) {
        free(owner_mangle);
        free(type_name);
        return NULL;
    }
    buf_init(&name);
    buf_append_fmt(&name,
                   "%s__%s__%s__G%zu",
                   role,
                   owner_mangle,
                   type_name,
                   decl->as.type_decl.type_param_count);
    free(owner_mangle);
    free(type_name);
    return name.data;
}

/* Stable shared symbol used by every concrete instance of a generic type
 * that relies on its implicit constructor. */
static char *cg_generic_implicit_constructor_shared_cname(
    CG *cg,
    const FengDecl *decl) {
    return cg_generic_owner_helper_cname(
        cg, decl, "FengGenericImplicitCtor");
}

/* Stable shared symbols for default-zero initialization and allocation. */
static char *cg_generic_default_zero_init_shared_cname(
    CG *cg,
    const FengDecl *decl) {
    return cg_generic_owner_helper_cname(
        cg, decl, "FengGenericDefaultZeroInit");
}

static char *cg_generic_default_zero_shared_cname(
    CG *cg,
    const FengDecl *decl) {
    return cg_generic_owner_helper_cname(
        cg, decl, "FengGenericDefaultZero");
}

/* Invoke the source package's ordinary implicit-constructor body.  This is
 * used only when the source type came from a compiled package and therefore
 * its field-initializer AST is intentionally absent from the consumer. */
static bool cg_emit_compiled_implicit_constructor_invoke(
    CG *cg,
    const UserType *type,
    const char *self_expr,
    FengToken blame) {
    char *name;
    bool imported;

    if (cg == NULL || type == NULL || self_expr == NULL) {
        return false;
    }
    if (type->field_count == 0U) {
        return true;
    }
    imported = cg_program_origin(cg, type->owner_program) ==
        FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE;
    if (type->is_generic_instance && type->generic_origin_decl != NULL) {
        const char *descriptor_type = cg_user_type_is_value(type)
            ? "FengAggregateDescriptor"
            : "FengTypeDescriptor";
        char *descriptor_expr = NULL;

        name = cg_generic_implicit_constructor_shared_cname(
            cg, type->generic_origin_decl);
        if (name == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (type->generic_context_type_param_count > 0U) {
            descriptor_expr = cg_rtd_expr_for_type(cg, type, blame);
        } else {
            Buf descriptor;

            buf_init(&descriptor);
            buf_append_fmt(&descriptor,
                           "&%s",
                           cg_user_type_is_value(type)
                               ? type->c_aggregate_desc_name
                               : type->c_desc_name);
            descriptor_expr = descriptor.data;
        }
        if (descriptor_expr == NULL) {
            free(name);
            return false;
        }
        /* Source generic declarations emit their own linkage-correct
         * prototype together with the shared body.  Imported declarations
         * need the public ABI declaration locally because their body lives
         * in the provider package. */
        if (imported) {
            buf_append_fmt(&cg->fn_protos,
                           "void %s(void *_self, const %s *_type_desc);\n",
                           name,
                           descriptor_type);
        }
        buf_append_fmt(cg->cur_body,
                       "    %s((void *)%s, %s);\n",
                       name,
                       self_expr,
                       descriptor_expr);
        free(descriptor_expr);
        free(name);
        return true;
    }

    name = cg_implicit_constructor_cname(type);
    if (name == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    buf_append_fmt(&cg->fn_protos,
                   "void %s(struct %s *self);\n",
                   name,
                   type->c_struct_name);
    buf_append_fmt(cg->cur_body,
                   "    %s(%s);\n",
                   name,
                   self_expr);
    free(name);
    return true;
}

/* Emit phase one of ordinary object construction.  Explicit constructors
 * execute this phase inside their source-defined body.  An implicit
 * constructor stays inline while its AST is present, and calls the compiled
 * source-package entry when consuming a binary package. */
static bool cg_emit_construction_member_initializers(
    CG *cg,
    const UserType *type,
    const UserMethod *constructor,
    const char *self_expr,
    FengToken blame) {
    if (constructor != NULL) {
        return true;
    }
    /* Every closed instance of a generic type executes the same owner-level
     * shared initializer body.  Besides keeping provider and consumer ABI
     * identical, this is what lets initializers containing open callable
     * expressions such as make<T>() read the closed callable dependency from
     * the type descriptor instead of trying to lower T at a concrete caller. */
    if (type->is_generic_instance && type->generic_origin_decl != NULL) {
        return cg_emit_compiled_implicit_constructor_invoke(
            cg, type, self_expr, blame);
    }
    if (cg_program_origin(cg, type->owner_program) ==
        FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return cg_emit_compiled_implicit_constructor_invoke(
            cg, type, self_expr, blame);
    }
    return cg_emit_user_type_member_initializers(
        cg, type, self_expr, blame);
}

/* Transfer one already-evaluated Feng value into the canonical callable
 * `_out` slot. The slot is uninitialised caller-owned storage; this helper
 * establishes the returned +1 ownership before releasing the invoke frame. */
static bool cg_emit_callable_out_return_expr_result(CG *cg,
                                                    FengToken blame,
                                                    ExprResult *result) {
    if (cg == NULL || result == NULL || result->type == NULL) {
        er_free(result);
        return cg_fail(cg, blame,
                       "CE0075", "codegen: callable out return has no value type");
    }

    if (result->type->kind == CG_TYPE_GENERIC_PARAM) {
        const char *descriptor = cg_generic_param_desc_name(
            cg, result->type->generic_param_index);

        if (descriptor == NULL) {
            er_free(result);
            return cg_fail(cg, blame,
                           "CE0075", "codegen: callable generic return has no descriptor");
        }
        if (result->owns_ref) {
            buf_append_fmt(cg->cur_body,
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s)); break;\n"
                "        case FENG_VALUE_MANAGED_POINTER:\n"
                "            *(void **)_out = *(void **)%s; *(void **)%s = NULL; break;\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s));\n"
                "            memset(%s, 0, feng_generic_value_size(%s)); break;\n"
                "    }\n",
                descriptor,
                result->c_expr, descriptor,
                result->c_expr, result->c_expr,
                result->c_expr, descriptor,
                result->c_expr, descriptor);
        } else {
            buf_append_fmt(cg->cur_body,
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s)); break;\n"
                "        case FENG_VALUE_MANAGED_POINTER: {\n"
                "            void *_returned = *(void *const *)%s;\n"
                "            feng_retain(_returned); *(void **)_out = _returned; break;\n"
                "        }\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s));\n"
                "            feng_aggregate_retain(_out, feng_generic_aggregate_descriptor(%s)); break;\n"
                "    }\n",
                descriptor,
                result->c_expr, descriptor,
                result->c_expr,
                result->c_expr, descriptor,
                descriptor);
        }
    } else if (cg_type_uses_reified_storage(cg, result->type)) {
        char *owned_descriptor = NULL;
        char *source_address = cg_aggregate_result_address_dup(result);
        const char *descriptor = result->reified_descriptor_c_name;
        const char *size = result->reified_size_c_name;
        Buf fallback_size;

        buf_init(&fallback_size);
        if (descriptor == NULL) {
            owned_descriptor = cg_reified_aggregate_descriptor_expr_dup(
                cg, result->type, blame);
            descriptor = owned_descriptor;
        }
        if (size == NULL && descriptor != NULL) {
            buf_append_fmt(&fallback_size, "%s->size", descriptor);
            size = fallback_size.data;
        }
        if (source_address == NULL || descriptor == NULL || size == NULL) {
            free(owned_descriptor);
            free(source_address);
            buf_free(&fallback_size);
            er_free(result);
            return cg_fail(cg, blame,
                           "CE0075", "codegen: callable reified return has no storage authority");
        }
        buf_append_fmt(cg->cur_body,
                       "    memcpy(_out, %s, %s);\n",
                       source_address,
                       size);
        if (result->owns_ref) {
            buf_append_fmt(cg->cur_body,
                           "    memset(%s, 0, %s);\n",
                           source_address,
                           size);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    feng_aggregate_retain(_out, %s);\n",
                           descriptor);
        }
        free(owned_descriptor);
        free(source_address);
        buf_free(&fallback_size);
    } else if (cgtype_is_managed(result->type)) {
        char *temporary = cg_fresh_temp(cg, "_ret");
        char *ctype = cg_ctype_dup(result->type);

        if (temporary == NULL || ctype == NULL) {
            free(temporary);
            free(ctype);
            er_free(result);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (result->owns_ref) {
            buf_append_fmt(cg->cur_body,
                           "    %s %s = %s;\n",
                           ctype, temporary, result->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    %s %s = %s; feng_retain(%s);\n",
                           ctype, temporary, result->c_expr, temporary);
        }
        buf_append_fmt(cg->cur_body,
                       "    memcpy(_out, &%s, sizeof %s);\n",
                       temporary, temporary);
        free(temporary);
        free(ctype);
    } else if (cgtype_is_aggregate(result->type)) {
        char *descriptor = cg_aggregate_descriptor_expr_dup(
            cg, result->type, blame);
        char *temporary = cg_fresh_temp(cg, "_ret");
        char *ctype = cg_ctype_dup(result->type);

        if (descriptor == NULL || temporary == NULL || ctype == NULL) {
            free(descriptor);
            free(temporary);
            free(ctype);
            er_free(result);
            if (!cg->failed) {
                cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }
            return false;
        }
        if (result->owns_ref) {
            if (cg_materialize_to_local(cg, result, "_t") == NULL) {
                free(descriptor);
                free(temporary);
                free(ctype);
                er_free(result);
                return false;
            }
            buf_append_fmt(cg->cur_body,
                "    %s %s; memset(&%s, 0, sizeof %s);"
                " feng_aggregate_take(&%s, &%s, %s);\n",
                ctype, temporary, temporary, temporary,
                temporary, result->c_expr, descriptor);
        } else {
            buf_append_fmt(cg->cur_body,
                "    %s %s = %s; feng_aggregate_retain(&%s, %s);\n",
                ctype, temporary, result->c_expr, temporary, descriptor);
        }
        buf_append_fmt(cg->cur_body,
                       "    memcpy(_out, &%s, sizeof %s);\n",
                       temporary, temporary);
        free(descriptor);
        free(temporary);
        free(ctype);
    } else {
        char *temporary = cg_fresh_temp(cg, "_ret");
        char *ctype = cg_ctype_dup(result->type);

        if (temporary == NULL || ctype == NULL) {
            free(temporary);
            free(ctype);
            er_free(result);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (cgtype_is_by_value_struct(result->type)) {
            buf_append_fmt(cg->cur_body,
                           "    %s %s = %s;\n",
                           ctype, temporary, result->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    %s %s = (%s)(%s);\n",
                           ctype, temporary, ctype, result->c_expr);
        }
        buf_append_fmt(cg->cur_body,
                       "    memcpy(_out, &%s, sizeof %s);\n",
                       temporary, temporary);
        free(temporary);
        free(ctype);
    }

    cg_release_through(cg, NULL);
    cg_emit_return_control_cleanup(cg);
    buf_append_cstr(cg->cur_body, "    return;\n");
    er_free(result);
    return true;
}

static bool cg_emit_return_expr_result(CG *cg,
                                       FengToken blame,
                                       ExprResult *r) {
    if (cg->callable_return_uses_out) {
        return cg_emit_callable_out_return_expr_result(cg, blame, r);
    }
    if (cgtype_is_managed(r->type)) {
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(r->type);
        if (tmp == NULL || cty == NULL) {
            free(tmp);
            free(cty);
            er_free(r);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (!r->owns_ref) {
            buf_append_fmt(cg->cur_body, "    %s %s = %s; feng_retain(%s);\n",
                           cty, tmp, r->c_expr, tmp);
        } else {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, r->c_expr);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body, "    return %s;\n", tmp);
        free(tmp);
    } else if (cgtype_is_aggregate(r->type)) {
        const char *desc = cg_aggregate_desc_name(r->type);
        if (!desc) {
            er_free(r);
            return cg_fail(cg, blame,
                "CE0075", "codegen: missing aggregate descriptor for spec return");
        }
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(r->type);
        if (tmp == NULL || cty == NULL) {
            free(tmp);
            free(cty);
            er_free(r);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (!r->owns_ref) {
            buf_append_fmt(cg->cur_body,
                "    %s %s = %s; feng_aggregate_retain(&%s, &%s);\n",
                cty, tmp, r->c_expr, tmp, desc);
        } else {
            cg_materialize_to_local(cg, r, "_t");
            buf_append_fmt(cg->cur_body,
                "    %s %s; memset(&%s, 0, sizeof %s);"
                " feng_aggregate_take(&%s, &%s, &%s);\n",
                cty, tmp, tmp, tmp, tmp, r->c_expr, desc);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body, "    return %s;\n", tmp);
        free(tmp);
    } else {
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(r->type);
        if (tmp == NULL || cty == NULL) {
            free(tmp);
            free(cty);
            er_free(r);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (cgtype_is_by_value_struct(r->type)) {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n",
                           cty, tmp, r->c_expr);
        } else {
            buf_append_fmt(cg->cur_body, "    %s %s = (%s)(%s);\n",
                           cty, tmp, cty, r->c_expr);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body, "    return %s;\n", tmp);
        free(tmp);
    }
    er_free(r);
    return true;
}

static bool cg_emit_constructor_invoke(CG *cg,
                                       FengExpr *const *args,
                                       size_t arg_count,
                                       const UserType *owner_type,
                                       const UserMethod *ctor,
                                       const char *self_expr,
                                       const char *owner_descriptor_expr,
                                       FengToken blame) {
    Buf args_buf;
    bool is_variadic;
    size_t fixed_count;
    bool ok = true;

    buf_init(&args_buf);
    if (ctor == NULL) {
        if (arg_count != 0U) {
            buf_free(&args_buf);
            return cg_fail(cg, blame,
                           "CE0076", "codegen: constructor arguments require a resolved user-defined constructor");
        }
        return true;
    }
    is_variadic = ctor->is_variadic;
    fixed_count = is_variadic ? ctor->param_count - 1U : ctor->param_count;
    if ((!is_variadic && arg_count != ctor->param_count) ||
        (is_variadic && arg_count < fixed_count)) {
        buf_free(&args_buf);
        return cg_fail(cg, blame,
                       "CE0077", "codegen: wrong argument count for constructor '%s' (expected%s %zu, got %zu)",
                       ctor->feng_name,
                       is_variadic ? " at least" : "",
                       fixed_count,
                       arg_count);
    }

    for (size_t i = 0; i < fixed_count; ++i) {
        ExprResult ar;
        if (!cg_emit_expr_for_expected_type(cg, args[i], ctor->param_types[i], &ar)) {
            ok = false;
            break;
        }
        if (cgtype_is_managed(ar.type) && ar.owns_ref) {
            cg_materialize_to_local(cg, &ar, "_t");
        }
        buf_append_cstr(&args_buf, ", ");
        buf_append_cstr(&args_buf, ar.c_expr);
        er_free(&ar);
    }
    if (ok && is_variadic) {
        const CGType *array_type = ctor->param_types[ctor->param_count - 1U];
        ExprResult variadic_array;

        if (!cg_emit_variadic_array_arg_from_args(
                cg,
                &blame,
                args,
                arg_count,
                fixed_count,
                array_type,
                &variadic_array)) {
            ok = false;
        } else {
            if (cgtype_is_managed(variadic_array.type) &&
                variadic_array.owns_ref) {
                cg_materialize_to_local(cg, &variadic_array, "_t");
            }
            buf_append_cstr(&args_buf, ", ");
            buf_append_cstr(&args_buf, variadic_array.c_expr);
            er_free(&variadic_array);
        }
    }
    if (!ok) {
        buf_free(&args_buf);
        return false;
    }

    if (owner_type->is_generic_instance &&
        owner_type->generic_origin_decl != NULL &&
        owner_type->generic_context_type_param_count > 0U) {
        char *shared_name = cg_generic_type_method_shared_cname(
            cg, owner_type->generic_origin_decl, ctor->member);
        char *descriptor_expr = owner_descriptor_expr != NULL
                                    ? strdup(owner_descriptor_expr)
                                    : cg_rtd_expr_for_type(
                                          cg, owner_type, blame);
        const char *descriptor_type = cg_user_type_is_value(owner_type)
            ? "FengAggregateDescriptor"
            : "FengTypeDescriptor";

        if (shared_name == NULL || descriptor_expr == NULL) {
            bool out_of_memory = shared_name == NULL;

            free(shared_name);
            free(descriptor_expr);
            buf_free(&args_buf);
            return out_of_memory
                ? cg_fail(cg, blame, "IE0001", "codegen: out of memory")
                : false;
        }
        buf_append_fmt(&cg->fn_protos,
                       "void %s(void *_self, const %s *_type_desc",
                       shared_name,
                       descriptor_type);
        for (size_t i = 0U; i < ctor->param_count; ++i) {
            buf_append_cstr(&cg->fn_protos, ", ");
            if (cg_shared_generic_param_uses_address(ctor->param_types[i])) {
                buf_append_fmt(&cg->fn_protos, "const void *_p%zu", i);
            } else {
                cg_emit_c_type(&cg->fn_protos, ctor->param_types[i]);
                buf_append_fmt(&cg->fn_protos, " _p%zu", i);
            }
        }
        buf_append_cstr(&cg->fn_protos, ");\n");
        buf_append_fmt(cg->cur_body,
                       "    %s((void *)%s, %s",
                       shared_name,
                       self_expr,
                       descriptor_expr);
        if (args_buf.data != NULL) {
            buf_append(cg->cur_body, args_buf.data, args_buf.length);
        }
        buf_append_cstr(cg->cur_body, ");\n");
        free(shared_name);
        free(descriptor_expr);
        buf_free(&args_buf);
        return true;
    }

    buf_append_fmt(cg->cur_body,
                   "    %s(%s",
                   ctor->c_name,
                   self_expr);
    if (!cg_append_user_type_context_descriptor_args(cg,
                                                     cg->cur_body,
                                                     owner_type,
                                                     blame)) {
        buf_free(&args_buf);
        return false;
    }
    if (args_buf.data != NULL) {
        buf_append(cg->cur_body, args_buf.data, args_buf.length);
    }
    buf_append_cstr(cg->cur_body, ");\n");
    buf_free(&args_buf);
    return true;
}

/* Emit @value type construction: stack-allocate, run field default-init /
 * member initialisers, then invoke the user constructor (if any).
 *
 * The pattern mirrors cg_emit_tuple_literal_typed: a fresh stack local
 * (_val) is declared and zero-initialised; field initialisers and the
 * constructor populate it through a pointer (&_val); the result is returned
 * as an owned expression (owns_ref=true).  The temporary is NOT registered
 * for scope cleanup — the consumer (binding / materialize) takes ownership
 * of managed fields via struct copy (trivial) or feng_aggregate_assign
 * (aggregate).  This matches the "owned by expression result" convention
 * used by tuple literals and spec returns. */
static bool cg_emit_value_type_construction(CG *cg,
                                            const UserType *ut,
                                            const UserMethod *ctor,
                                            FengExpr *const *args,
                                            size_t arg_count,
                                            FengToken blame,
                                            ExprResult *out) {
    char *val_name = NULL;
    char *storage_descriptor_name = NULL;
    char *storage_size_name = NULL;
    CGType *val_type = NULL;
    bool uses_reified_storage = false;

    er_init(out);
    if (cg == NULL || ut == NULL) {
        return false;
    }

    val_name = cg_fresh_temp(cg, "_val");
    if (val_name == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    val_type = cgtype_new(CG_TYPE_OBJECT);
    if (val_type == NULL) {
        free(val_name);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    val_type->user = (UserType *)ut;
    uses_reified_storage = cg_type_uses_reified_storage(cg, val_type);

    /* Step 1 — stack-allocate and zero-initialise.  An open generic value
     * instance has only a placeholder C struct layout in the shared body;
     * its concrete descriptor is the sole size authority. */
    if (!cg_emit_line_directive_force(cg, blame)) {
        free(val_name);
        free(storage_descriptor_name);
        free(storage_size_name);
        cgtype_free(val_type);
        return false;
    }
    if (uses_reified_storage) {
        if (!cg_emit_reified_storage_declaration(cg,
                                                 val_type,
                                                 val_name,
                                                 blame,
                                                 &storage_descriptor_name,
                                                 &storage_size_name)) {
            free(val_name);
            cgtype_free(val_type);
            return false;
        }
    } else {
        buf_append_fmt(cg->cur_body,
                       "    struct %s %s = {0};\n",
                       ut->c_struct_name, val_name);
    }

    /* Step 2 — run field default-init / member initialisers.
     * The reified buffer already decays to the required storage pointer. */
    {
        Buf addr;
        buf_init(&addr);
        if (uses_reified_storage) {
            buf_append_cstr(&addr, val_name);
        } else {
            buf_append_fmt(&addr, "(&%s)", val_name);
        }
        if (addr.data == NULL) {
            free(val_name);
            free(storage_descriptor_name);
            free(storage_size_name);
            cgtype_free(val_type);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        bool ok = cg_emit_construction_member_initializers(
            cg, ut, ctor, addr.data, blame);
        buf_free(&addr);
        if (!ok) {
            free(val_name);
            free(storage_descriptor_name);
            free(storage_size_name);
            cgtype_free(val_type);
            return false;
        }
    }

    /* Step 3 — invoke the user constructor (if any).
     * ctor->c_name(&_val, ...args...); */
    {
        Buf addr;
        buf_init(&addr);
        if (uses_reified_storage) {
            buf_append_cstr(&addr, val_name);
        } else {
            buf_append_fmt(&addr, "&%s", val_name);
        }
        if (addr.data == NULL) {
            free(val_name);
            free(storage_descriptor_name);
            free(storage_size_name);
            cgtype_free(val_type);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        bool ok = cg_emit_constructor_invoke(cg, args, arg_count,
                                             ut, ctor, addr.data,
                                             storage_descriptor_name,
                                             blame);
        buf_free(&addr);
        if (!ok) {
            free(val_name);
            free(storage_descriptor_name);
            free(storage_size_name);
            cgtype_free(val_type);
            return false;
        }
    }

    /* Step 4 — build the owned result.
     * type is CG_TYPE_OBJECT with the @value UserType attached;
     * cg_aggregate_facts will route it to trivial/aggregate as needed. */
    if (uses_reified_storage) {
        out->c_expr = val_name;
        out->is_storage_address = true;
        out->uses_reified_storage = true;
        out->reified_descriptor_c_name = storage_descriptor_name;
        out->reified_size_c_name = storage_size_name;
    } else {
        out->c_expr = val_name;   /* transfer ownership of val_name */
        free(storage_descriptor_name);
        free(storage_size_name);
    }
    if (out->c_expr == NULL) {
        cgtype_free(val_type);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    out->type = val_type;
    out->owns_ref = true;
    out->is_addressable = true;
    return true;
}

static bool cg_compute_capture_requirements_in_lambda_body(const FengExpr *lambda_expr,
                                                           char ***out_names,
                                                           size_t *out_count,
                                                           bool *out_captures_self) {
    size_t capacity = 0U;

    *out_names = NULL;
    *out_count = 0U;
    *out_captures_self = false;
    if (lambda_expr == NULL || lambda_expr->kind != FENG_EXPR_LAMBDA) {
        return true;
    }

    bool ok = lambda_expr->as.lambda.is_block_body
        ? cg_collect_capture_requirements_in_block_inner(lambda_expr->as.lambda.body_block,
                                                         out_names,
                                                         out_count,
                                                         &capacity,
                                                         out_captures_self)
        : cg_collect_capture_requirements_in_expr(lambda_expr->as.lambda.body,
                                                  out_names,
                                                  out_count,
                                                  &capacity,
                                                  out_captures_self);
    if (!ok) {
        if (*out_names != NULL) {
            for (size_t i = 0; i < *out_count; ++i) free((*out_names)[i]);
            free(*out_names);
        }
        *out_names = NULL;
        *out_count = 0U;
        *out_captures_self = false;
        return false;
    }
    return true;
}

/* Direct lookup from a single-segment type_ref name to a builtin scalar
 * CGTypeKind.  Avoids calling cg_resolve_type (which can report errors
 * for non-builtin names such as generic type parameters), making it safe
 * for use in literal emission where the type might not be resolvable in
 * the current codegen context. */
static bool cg_builtin_scalar_kind_from_type_ref(const FengTypeRef *ref,
                                                  CGTypeKind *out_kind) {
    static const struct { const char *name; CGTypeKind kind; } map[] = {
        {"i8", CG_TYPE_I8}, {"i16", CG_TYPE_I16},
        {"i32", CG_TYPE_I32}, {"i64", CG_TYPE_I64},
        {"u8", CG_TYPE_U8}, {"u16", CG_TYPE_U16},
        {"u32", CG_TYPE_U32}, {"u64", CG_TYPE_U64},
        {"f32", CG_TYPE_F32}, {"f64", CG_TYPE_F64},
    };
    FengSlice seg;
    size_t i;

    if (ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.segment_count != 1U) {
        return false;
    }
    seg = ref->as.named.segments[0];
    for (i = 0; i < sizeof map / sizeof map[0]; i++) {
        if (strlen(map[i].name) == seg.length &&
            memcmp(map[i].name, seg.data, seg.length) == 0) {
            *out_kind = map[i].kind;
            return true;
        }
    }
    return false;
}

static bool cg_emit_literal(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    if (e->kind == FENG_EXPR_BOOL) {
        out->c_expr = strdup(e->as.boolean ? "true" : "false");
        out->type = cgtype_new(CG_TYPE_BOOL);
        return out->c_expr && out->type;
    }
    if (e->kind == FENG_EXPR_INTEGER) {
        /* Read the semantic-resolved type (if any) to emit the correct
         * width and signedness.  Uses direct builtin-name lookup rather
         * than cg_resolve_type to avoid side effects (error reporting,
         * generic-context interaction).  Falls back to int64_t when type
         * is NULL or not a recognized builtin scalar. */
        CGTypeKind scalar_kind;
        if (cg_builtin_scalar_kind_from_type_ref(e->type, &scalar_kind) &&
            cgtype_is_integer(scalar_kind)) {
            Buf b; buf_init(&b);
            switch (scalar_kind) {
                case CG_TYPE_I8:
                    buf_append_fmt(&b, "(int8_t)INT8_C(%" PRId64 ")",
                                   (int64_t)(int8_t)e->as.integer);
                    break;
                case CG_TYPE_I16:
                    buf_append_fmt(&b, "(int16_t)INT16_C(%" PRId64 ")",
                                   (int64_t)(int16_t)e->as.integer);
                    break;
                case CG_TYPE_I32:
                    buf_append_fmt(&b, "(int32_t)INT32_C(%" PRId64 ")",
                                   (int64_t)(int32_t)e->as.integer);
                    break;
                case CG_TYPE_I64:
                    buf_append_fmt(&b, "(int64_t)INT64_C(%" PRId64 ")",
                                   e->as.integer);
                    break;
                case CG_TYPE_U8:
                    buf_append_fmt(&b, "(uint8_t)UINT8_C(%" PRIu64 ")",
                                   (uint64_t)(uint8_t)e->as.integer);
                    break;
                case CG_TYPE_U16:
                    buf_append_fmt(&b, "(uint16_t)UINT16_C(%" PRIu64 ")",
                                   (uint64_t)(uint16_t)e->as.integer);
                    break;
                case CG_TYPE_U32:
                    buf_append_fmt(&b, "(uint32_t)UINT32_C(%" PRIu64 ")",
                                   (uint64_t)(uint32_t)e->as.integer);
                    break;
                case CG_TYPE_U64:
                    buf_append_fmt(&b, "(uint64_t)UINT64_C(%" PRIu64 ")",
                                   (uint64_t)e->as.integer);
                    break;
                default: break;
            }
            out->c_expr = b.data;
            out->type = cgtype_new(scalar_kind);
            return out->c_expr && out->type;
        }
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "(int64_t)INT64_C(%" PRId64 ")", e->as.integer);
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_I64);
        return out->c_expr && out->type;
    }
    if (e->kind == FENG_EXPR_FLOAT) {
        /* Read the semantic-resolved type (if any) to emit f32 vs f64.
         * Falls back to f64 when type is NULL or not a recognized scalar. */
        CGTypeKind scalar_kind;
        if (cg_builtin_scalar_kind_from_type_ref(e->type, &scalar_kind) &&
            cgtype_is_float(scalar_kind)) {
            Buf b; buf_init(&b);
            if (scalar_kind == CG_TYPE_F32) {
                buf_append_fmt(&b, "(float)(%af)", e->as.floating);
            } else {
                buf_append_fmt(&b, "(%a)", e->as.floating);
            }
            out->c_expr = b.data;
            out->type = cgtype_new(scalar_kind);
            return out->c_expr && out->type;
        }
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "(%a)", e->as.floating);
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_F64);
        return out->c_expr && out->type;
    }
    if (e->kind == FENG_EXPR_STRING) {
        /* Check if this is a raw string (backtick-delimited) by examining the
         * first character of the lexeme. Raw strings have delimiters preserved
         * in lexeme (like double-quoted strings). Process here: remove delimiters
         * and replace `` with `. No escape decoding. */
        const char *raw = e->as.string.data;
        size_t rlen = e->as.string.length;
        if (rlen >= 2 && raw[0] == '`' && raw[rlen - 1] == '`') {
            const char *body = raw + 1;
            size_t blen = rlen - 2;

            /* First pass: count output length (`` becomes single `) */
            size_t out_len = 0;
            for (size_t i = 0; i < blen; ) {
                if (body[i] == '`' && i + 1 < blen && body[i + 1] == '`') {
                    out_len++;
                    i += 2;
                } else {
                    out_len++;
                    i++;
                }
            }

            char *processed = malloc(out_len + 1);
            if (!processed) return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            size_t di = 0;
            for (size_t i = 0; i < blen; ) {
                if (body[i] == '`' && i + 1 < blen && body[i + 1] == '`') {
                    processed[di++] = '`';
                    i += 2;
                } else {
                    processed[di++] = body[i];
                    i++;
                }
            }
            processed[di] = '\0';

            const char *cv = cg_string_literal_var(cg, processed, di);
            free(processed);
            if (!cv) return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            out->c_expr = strdup(cv);
            out->type = cgtype_new(CG_TYPE_STRING);
            out->owns_ref = false;   /* immortal */
            return out->c_expr && out->type;
        }

        /* Double-quoted string: decode escapes. The lexer guarantees the
         * literal is well-formed: starts/ends with '"' and uses only the
         * supported escape set (\\ \" \n \r \t \0 \xNN). */
        if (rlen < 2 || raw[0] != '"' || raw[rlen - 1] != '"') {
            return cg_fail(cg, e->token, "CE0078", "codegen: malformed string literal");
        }
        const char *body = raw + 1;
        size_t blen = rlen - 2;
        char *decoded = malloc(blen + 1);
        if (!decoded) return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        size_t di = 0;
        for (size_t i = 0; i < blen; i++) {
            char ch = body[i];
            if (ch == '\\' && i + 1 < blen) {
                char esc = body[++i];
                switch (esc) {
                    case '\\': decoded[di++] = '\\'; break;
                    case '"':  decoded[di++] = '"';  break;
                    case 'n':  decoded[di++] = '\n'; break;
                    case 'r':  decoded[di++] = '\r'; break;
                    case 't':  decoded[di++] = '\t'; break;
                    case '0':  decoded[di++] = '\0'; break;
                    case 'x':
                        /* \xNN: exactly 2 hex digits → one byte.
                         * Lexer already validated syntax; this is defensive. */
                        if (i + 2 >= blen) {
                            free(decoded);
                            return cg_fail(cg, e->token,
                                "CE0079", "codegen: invalid \\x escape: expected 2 hex digits");
                        }
                        {
                            char h1 = body[i + 1];
                            char h2 = body[i + 2];
                            unsigned int high, low;
                            /* Convert hex char to value 0-15 */
                            if (h1 >= '0' && h1 <= '9')      high = (unsigned int)(h1 - '0');
                            else if (h1 >= 'a' && h1 <= 'f') high = (unsigned int)(h1 - 'a' + 10);
                            else if (h1 >= 'A' && h1 <= 'F') high = (unsigned int)(h1 - 'A' + 10);
                            else {
                                free(decoded);
                                return cg_fail(cg, e->token,
                                    "CE0080", "codegen: invalid \\x escape: expected hex digit");
                            }
                            if (h2 >= '0' && h2 <= '9')      low = (unsigned int)(h2 - '0');
                            else if (h2 >= 'a' && h2 <= 'f') low = (unsigned int)(h2 - 'a' + 10);
                            else if (h2 >= 'A' && h2 <= 'F') low = (unsigned int)(h2 - 'A' + 10);
                            else {
                                free(decoded);
                                return cg_fail(cg, e->token,
                                    "CE0080", "codegen: invalid \\x escape: expected hex digit");
                            }
                            decoded[di++] = (char)((high << 4) | low);
                            i += 2; /* skip the 2 hex digits (loop will ++i) */
                        }
                        break;
                    default:
                        free(decoded);
                        return cg_fail(cg, e->token,
                            "CE0081", "codegen: unknown string escape '\\%c'", esc);
                }
            } else {
                decoded[di++] = ch;
            }
        }
        decoded[di] = '\0';
        const char *cv = cg_string_literal_var(cg, decoded, di);
        free(decoded);
        if (!cv) return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        out->c_expr = strdup(cv);
        out->type = cgtype_new(CG_TYPE_STRING);
        out->owns_ref = false;   /* immortal */
        return out->c_expr && out->type;
    }
    return cg_fail(cg, e->token, "CE0082", "codegen: unsupported literal kind");
}

static const char *cg_binop_c(FengTokenKind op) {
    switch (op) {
        case FENG_TOKEN_PLUS: return "+";
        case FENG_TOKEN_MINUS: return "-";
        case FENG_TOKEN_STAR: return "*";
        case FENG_TOKEN_SLASH: return "/";
        case FENG_TOKEN_PERCENT: return "%";
        case FENG_TOKEN_LT: return "<";
        case FENG_TOKEN_LE: return "<=";
        case FENG_TOKEN_GT: return ">";
        case FENG_TOKEN_GE: return ">=";
        case FENG_TOKEN_EQ: return "==";
        case FENG_TOKEN_NE: return "!=";
        case FENG_TOKEN_AND_AND: return "&&";
        case FENG_TOKEN_OR_OR: return "||";
        case FENG_TOKEN_AMP: return "&";
        case FENG_TOKEN_PIPE: return "|";
        case FENG_TOKEN_CARET: return "^";
        case FENG_TOKEN_SHL: return "<<";
        case FENG_TOKEN_SHR: return ">>";
        default: return NULL;
    }
}

static FengTokenKind cg_assignment_binary_op(FengTokenKind op) {
    switch (op) {
        case FENG_TOKEN_PLUS_ASSIGN:
            return FENG_TOKEN_PLUS;
        case FENG_TOKEN_MINUS_ASSIGN:
            return FENG_TOKEN_MINUS;
        case FENG_TOKEN_STAR_ASSIGN:
            return FENG_TOKEN_STAR;
        case FENG_TOKEN_SLASH_ASSIGN:
            return FENG_TOKEN_SLASH;
        case FENG_TOKEN_PERCENT_ASSIGN:
            return FENG_TOKEN_PERCENT;
        case FENG_TOKEN_AMP_ASSIGN:
            return FENG_TOKEN_AMP;
        case FENG_TOKEN_PIPE_ASSIGN:
            return FENG_TOKEN_PIPE;
        case FENG_TOKEN_CARET_ASSIGN:
            return FENG_TOKEN_CARET;
        case FENG_TOKEN_SHL_ASSIGN:
            return FENG_TOKEN_SHL;
        case FENG_TOKEN_SHR_ASSIGN:
            return FENG_TOKEN_SHR;
        default:
            return FENG_TOKEN_ERROR;
    }
}

static bool cg_assignment_is_compound(FengTokenKind op) {
    return op != FENG_TOKEN_ASSIGN;
}

/* Return the compiler intrinsic used to implement one wrapping integer
 * operation. The intrinsic writes the result directly in the requested
 * fixed-width type; its overflow flag is intentionally ignored. */
static const char *cg_integer_wrapping_builtin(FengTokenKind op) {
    switch (op) {
        case FENG_TOKEN_PLUS:
            return "__builtin_add_overflow";
        case FENG_TOKEN_MINUS:
            return "__builtin_sub_overflow";
        case FENG_TOKEN_STAR:
            return "__builtin_mul_overflow";
        default:
            return NULL;
    }
}

/* Append one numeric expression while preserving Feng's fixed-width integer
 * semantics. Wrapping arithmetic uses compiler intrinsics so signed overflow
 * and narrow-integer promotion remain defined without runtime checks. */
static bool cg_append_numeric_op_expr(Buf *b,
                                      CGTypeKind kind,
                                      const char *lhs,
                                      FengTokenKind op,
                                      const char *rhs) {
    const char *cty = cgtype_to_c(kind);
    const char *cop = cg_binop_c(op);
    const char *wrapping_builtin = cgtype_is_integer(kind)
                                       ? cg_integer_wrapping_builtin(op)
                                       : NULL;

    if (wrapping_builtin != NULL) {
        buf_append_fmt(
            b,
            "(__extension__ ({ %s _wrap_result; "
            "(void)%s((%s)(%s), (%s)(%s), &_wrap_result); "
            "_wrap_result; }))",
            cty,
            wrapping_builtin,
            cty,
            lhs,
            cty,
            rhs);
        return true;
    }

    if (op == FENG_TOKEN_PERCENT && kind == CG_TYPE_F32) {
        buf_append_fmt(b, "fmodf((float)(%s), (float)(%s))", lhs, rhs);
        return true;
    }
    if (op == FENG_TOKEN_PERCENT && kind == CG_TYPE_F64) {
        buf_append_fmt(b, "fmod((double)(%s), (double)(%s))", lhs, rhs);
        return true;
    }
    if (cop == NULL) {
        return false;
    }

    buf_append_fmt(b, "((%s)%s %s (%s)%s)", cty, lhs, cop, cty, rhs);
    return true;
}

static bool cg_unify_numeric(CG *cg, FengToken tok, ExprResult *l, ExprResult *r,
                             CGType **out_common) {
    CGTypeKind lk = l->type->kind, rk = r->type->kind;
    if (lk == CG_TYPE_F64 || rk == CG_TYPE_F64) { *out_common = cgtype_new(CG_TYPE_F64); return true; }
    if (lk == CG_TYPE_F32 || rk == CG_TYPE_F32) { *out_common = cgtype_new(CG_TYPE_F32); return true; }
    if (cgtype_is_integer(lk) && cgtype_is_integer(rk)) {
        int lr = cgtype_int_rank(lk), rr = cgtype_int_rank(rk);
        CGTypeKind chosen = (lr >= rr) ? lk : rk;
        /* Mixed-sign promotes to signed of higher rank for Phase 1A. */
        if (cgtype_is_signed(lk) != cgtype_is_signed(rk)) {
            chosen = (cgtype_int_rank(chosen) >= 4) ? CG_TYPE_I64 : CG_TYPE_I64;
        }
        *out_common = cgtype_new(chosen);
        return true;
    }
    return cg_fail(cg, tok, "CE0083", "codegen: cannot apply numeric op to non-numeric operands");
}

static bool cg_emit_binary(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    ExprResult lr; ExprResult rr;
    if (!cg_emit_expr(cg, e->as.binary.left, &lr)) return false;
    if (!cg_emit_expr(cg, e->as.binary.right, &rr)) { er_free(&lr); return false; }

    /* Spec `==` / `!=` — reference-identity per docs/engineering/feng-spec-codegen-delivered.md
     * §7. Semantic registers a SpecEquality sidecar entry for every binary
     * `==`/`!=` whose operands resolve to a spec; codegen consumes it and
     * lowers to a direct subject pointer compare. Both operands are fat
     * spec values (aggregates); when either side is an owns_ref temporary
     * we materialise it to a local first so its `subject` survives the
     * comparison and its scope cleanup runs the standard aggregate
     * release. */
    const FengSpecEquality *eq_site =
        cg->analysis ? feng_semantic_lookup_spec_equality(cg->analysis, e) : NULL;
    if (eq_site != NULL) {
        if (!cgtype_is_aggregate(lr.type) || !cgtype_is_aggregate(rr.type)) {
            er_free(&lr); er_free(&rr);
            return cg_fail(cg, e->token,
                "CE0084", "codegen: spec equality requires aggregate spec operands");
        }
        cg_materialize_to_local(cg, &lr, "_t");
        cg_materialize_to_local(cg, &rr, "_t");
        Buf b; buf_init(&b);
        if (eq_site->op == FENG_SPEC_EQUALITY_OP_EQ) {
            buf_append_fmt(&b, "feng_spec_subject_equal(%s.subject, %s.subject)",
                           lr.c_expr, rr.c_expr);
        } else {
            buf_append_fmt(&b, "!feng_spec_subject_equal(%s.subject, %s.subject)",
                           lr.c_expr, rr.c_expr);
        }
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_BOOL);
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    /* String concatenation: '+' on two strings. */
    if (e->as.binary.op == FENG_TOKEN_PLUS &&
        lr.type->kind == CG_TYPE_STRING && rr.type->kind == CG_TYPE_STRING) {
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "feng_string_concat(%s, %s)", lr.c_expr, rr.c_expr);
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_STRING);
        out->owns_ref = true;
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    /* String equality: pointer-first fast-path, then byte comparison. */
    if ((e->as.binary.op == FENG_TOKEN_EQ || e->as.binary.op == FENG_TOKEN_NE) &&
        lr.type->kind == CG_TYPE_STRING && rr.type->kind == CG_TYPE_STRING) {
        Buf b; buf_init(&b);
        if (e->as.binary.op == FENG_TOKEN_EQ) {
            buf_append_fmt(&b, "feng_string_equal(%s, %s)", lr.c_expr, rr.c_expr);
        } else {
            buf_append_fmt(&b, "!feng_string_equal(%s, %s)", lr.c_expr, rr.c_expr);
        }
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_BOOL);
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    /* Object/Array/Callable equality: reference identity (pointer
     * comparison). Excludes value-semantics types (tuple, @value), which use
     * equal_fn, and strings, which use content equality above. */
    if ((e->as.binary.op == FENG_TOKEN_EQ || e->as.binary.op == FENG_TOKEN_NE) &&
        cg_type_has_reference_identity_equality(lr.type) &&
        lr.type->kind == rr.type->kind &&
        cg_type_has_reference_identity_equality(rr.type)) {
        const char *cop2 = (e->as.binary.op == FENG_TOKEN_EQ) ? "==" : "!=";
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "(bool)((void *)%s %s (void *)%s)", lr.c_expr, cop2, rr.c_expr);
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_BOOL);
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    /* Value-type equality (tuple or @value): value semantics via generated
     * aggregate equal_fn. */
    if ((e->as.binary.op == FENG_TOKEN_EQ || e->as.binary.op == FENG_TOKEN_NE) &&
        cg_type_is_value_semantics(lr.type) && cg_type_is_value_semantics(rr.type)) {
        const char *desc_name = lr.type->user->c_aggregate_desc_name;
        if (desc_name == NULL) {
            er_free(&lr); er_free(&rr);
            return cg_fail(cg, e->token, "CE0085", "codegen: value type has no aggregate descriptor for equality");
        }
        Buf b; buf_init(&b);
        if (e->as.binary.op == FENG_TOKEN_EQ) {
            buf_append_fmt(&b, "(&%s)->equal_fn(&%s, &%s)", desc_name, lr.c_expr, rr.c_expr);
        } else {
            buf_append_fmt(&b, "!(&%s)->equal_fn(&%s, &%s)", desc_name, lr.c_expr, rr.c_expr);
        }
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_BOOL);
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    const char *cop = cg_binop_c(e->as.binary.op);
    if (!cop) {
        er_free(&lr); er_free(&rr);
        return cg_fail(cg, e->token, "CE0086", "codegen: unsupported binary operator");
    }

    /* Logical operators: bool && bool, bool || bool. */
    if (e->as.binary.op == FENG_TOKEN_AND_AND || e->as.binary.op == FENG_TOKEN_OR_OR) {
        if (lr.type->kind != CG_TYPE_BOOL || rr.type->kind != CG_TYPE_BOOL) {
            er_free(&lr); er_free(&rr);
            return cg_fail(cg, e->token, "CE0087", "codegen: && / || require bool operands");
        }
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "(%s %s %s)", lr.c_expr, cop, rr.c_expr);
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_BOOL);
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    /* Comparison: produces bool from numeric/bool operands. */
    bool is_cmp = (e->as.binary.op == FENG_TOKEN_LT || e->as.binary.op == FENG_TOKEN_LE ||
                   e->as.binary.op == FENG_TOKEN_GT || e->as.binary.op == FENG_TOKEN_GE ||
                   e->as.binary.op == FENG_TOKEN_EQ || e->as.binary.op == FENG_TOKEN_NE);
    if (is_cmp && lr.type->kind == CG_TYPE_BOOL && rr.type->kind == CG_TYPE_BOOL) {
        if (e->as.binary.op != FENG_TOKEN_EQ && e->as.binary.op != FENG_TOKEN_NE) {
            er_free(&lr); er_free(&rr);
            return cg_fail(cg, e->token, "CE0088", "codegen: ordering comparisons require numeric operands");
        }
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "(%s %s %s)", lr.c_expr, cop, rr.c_expr);
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_BOOL);
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    if (is_cmp && e->as.binary.op != FENG_TOKEN_LT && e->as.binary.op != FENG_TOKEN_LE &&
        e->as.binary.op != FENG_TOKEN_GT && e->as.binary.op != FENG_TOKEN_GE &&
        lr.type->kind == CG_TYPE_POINTER && rr.type->kind == CG_TYPE_POINTER) {
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "(bool)(%s %s %s)", lr.c_expr, cop, rr.c_expr);
        out->c_expr = b.data;
        out->type = cgtype_new(CG_TYPE_BOOL);
        er_free(&lr); er_free(&rr);
        return out->c_expr && out->type;
    }

    /* Numeric arithmetic / bitwise / comparison. */
    CGType *common = NULL;
    if (!cg_unify_numeric(cg, e->token, &lr, &rr, &common)) {
        er_free(&lr); er_free(&rr); return false;
    }
    Buf b; buf_init(&b);
    if (!cg_append_numeric_op_expr(&b,
                                   common->kind,
                                   lr.c_expr,
                                   e->as.binary.op,
                                   rr.c_expr)) {
        cgtype_free(common);
        er_free(&lr);
        er_free(&rr);
        return cg_fail(cg, e->token,
                       "CE0089", "codegen: unsupported numeric operation");
    }
    out->c_expr = b.data;
    if (is_cmp) {
        cgtype_free(common);
        out->type = cgtype_new(CG_TYPE_BOOL);
    } else {
        out->type = common;
    }
    er_free(&lr); er_free(&rr);
    return out->c_expr && out->type;
}

static bool cg_expr_is_direct_lvalue(const FengExpr *expr) {
    if (expr == NULL) {
        return false;
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
        case FENG_EXPR_MEMBER:
            return true;
        default:
            return false;
    }
}

static bool cg_array_data_pointer_element_is_lowerable(const CGType *element_type) {
    if (element_type == NULL) {
        return false;
    }
    if (cg_type_kind_is_scalar_builtin(element_type->kind) ||
        element_type->kind == CG_TYPE_POINTER ||
        element_type->kind == CG_TYPE_CALLABLE ||
        (element_type->kind == CG_TYPE_OBJECT && cg_user_type_is_abi(element_type->user))) {
        return true;
    }
    return false;
}

static bool cg_array_data_pointer_type_is_lowerable(const CGType *array_type) {
    return array_type != NULL && array_type->kind == CG_TYPE_ARRAY &&
           cg_array_data_pointer_element_is_lowerable(array_type->element);
}

static void cg_emit_array_data_pointer_c_type(Buf *b, const CGType *array_type) {
    CGType data_pointer;

    if (!cg_array_data_pointer_type_is_lowerable(array_type)) {
        buf_append_cstr(b, "void *");
        return;
    }

    memset(&data_pointer, 0, sizeof(data_pointer));
    data_pointer.kind = CG_TYPE_POINTER;
    data_pointer.element = array_type->element;
    cg_emit_c_type(b, &data_pointer);
}

static bool cg_emit_unary(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    ExprResult inner;
    if (!cg_emit_expr(cg, e->as.unary.operand, &inner)) return false;
    if (e->as.unary.op == FENG_TOKEN_AMP) {
        if (inner.type == NULL) {
            er_free(&inner);
            return cg_fail(cg, e->token,
                "CE0090", "codegen: unary '&' is missing an operand type");
        }

        if (inner.type->kind == CG_TYPE_OBJECT &&
            inner.type->user != NULL &&
            inner.type->user->is_abi_type &&
            cg_type_is_value_user(inner.type)) {
            /* @value @abi: value expression (not pointer), take address
             * before passing to c_abi_ptr_name. lvalue recv: &expr
             * directly. rvalue recv (owns_ref): materialize first so
             * the temporary has a stable address. */
            Buf b;

            if (inner.owns_ref) {
                if (cg_materialize_to_local(cg, &inner, "_addr") == NULL) {
                    er_free(&inner);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            }

            buf_init(&b);
            buf_append_fmt(&b, "%s(&%s)",
                           inner.type->user->c_abi_ptr_name,
                           inner.c_expr);
            out->c_expr = b.data;
            out->type = cgtype_new(CG_TYPE_POINTER);
            if (out->type == NULL) {
                er_free(&inner);
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            out->type->element = cgtype_clone(inner.type);
            if (out->type->element == NULL) {
                er_free(&inner);
                cgtype_free(out->type);
                out->type = NULL;
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            er_free(&inner);
            out->owns_ref = false;
            return out->c_expr != NULL;
        }

        if (inner.type->kind == CG_TYPE_OBJECT &&
            inner.type->user != NULL &&
            inner.type->user->is_abi_type) {
            Buf b;

            if (inner.owns_ref) {
                if (cg_materialize_to_local(cg, &inner, "_addr") == NULL) {
                    er_free(&inner);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            }

            buf_init(&b);
            buf_append_fmt(&b, "%s(%s)",
                           inner.type->user->c_abi_ptr_name,
                           inner.c_expr);
            out->c_expr = b.data;
            out->type = cgtype_new(CG_TYPE_POINTER);
            if (out->type == NULL) {
                er_free(&inner);
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            out->type->element = cgtype_clone(inner.type);
            if (out->type->element == NULL) {
                er_free(&inner);
                cgtype_free(out->type);
                out->type = NULL;
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            er_free(&inner);
            out->owns_ref = false;
            return out->c_expr != NULL;
        }

        if (inner.type->kind == CG_TYPE_STRING) {
            if (inner.owns_ref) {
                if (cg_materialize_to_local(cg, &inner, "_addr") == NULL) {
                    er_free(&inner);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            }
            Buf b; buf_init(&b);
            buf_append_fmt(&b, "((char *)feng_string_data(%s))", inner.c_expr);
            out->c_expr = b.data;
            out->type = cgtype_new(CG_TYPE_POINTER);
            if (out->type == NULL) {
                er_free(&inner);
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            out->type->element = cgtype_new(CG_TYPE_STRING);
            if (out->type->element == NULL) {
                er_free(&inner);
                cgtype_free(out->type);
                out->type = NULL;
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            er_free(&inner);
            out->owns_ref = false;
            return out->c_expr != NULL;
        }

        if (inner.type->kind == CG_TYPE_ARRAY) {
            char *elem_ptr_cty;
            CGType *elem_ptr_type;
            Buf b;

            if (inner.type->element == NULL ||
                !cg_array_data_pointer_element_is_lowerable(inner.type->element)) {
                er_free(&inner);
                return cg_fail(cg, e->token,
                    "CE0091", "codegen: this ABI-compatible array element type does not support data-pointer lowering");
            }
            if (inner.owns_ref && cg_materialize_to_local(cg, &inner, "_addr") == NULL) {
                er_free(&inner);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }

            elem_ptr_type = cgtype_new(CG_TYPE_POINTER);
            if (elem_ptr_type == NULL) {
                er_free(&inner);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            elem_ptr_type->element = cgtype_clone(inner.type->element);
            if (elem_ptr_type->element == NULL) {
                cgtype_free(elem_ptr_type);
                er_free(&inner);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            elem_ptr_cty = cg_ctype_dup(elem_ptr_type);
            cgtype_free(elem_ptr_type);
            if (elem_ptr_cty == NULL) {
                er_free(&inner);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }

            buf_init(&b);
            buf_append_fmt(&b, "((%s)feng_array_data(%s))", elem_ptr_cty, inner.c_expr);
            free(elem_ptr_cty);
            out->c_expr = b.data;
            out->type = cgtype_new(CG_TYPE_POINTER);
            if (out->type == NULL) {
                er_free(&inner);
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            out->type->element = cgtype_clone(inner.type->element);
            if (out->type->element == NULL) {
                er_free(&inner);
                cgtype_free(out->type);
                out->type = NULL;
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            er_free(&inner);
            out->owns_ref = false;
            return out->c_expr != NULL;
        }

        if (cg_type_kind_is_scalar_builtin(inner.type->kind)) {
            const ModuleBinding *addr_binding = NULL;
            Buf b;

            if (e->as.unary.operand->kind == FENG_EXPR_IDENTIFIER) {
                const FengSlice name = e->as.unary.operand->as.identifier;

                if (scope_lookup(cg->cur_scope, name.data, name.length) == NULL) {
                    addr_binding = cg_find_module_binding(cg, name.data, name.length);
                }
            }

            /* Scalar module bindings are lowered through getters for reads,
             * but address-of must still point at the backing storage slot. */
            if (addr_binding != NULL) {
                free(inner.c_expr);
                inner.c_expr = strdup(addr_binding->c_name);
                if (inner.c_expr == NULL) {
                    er_free(&inner);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            } else if (!cg_expr_is_direct_lvalue(e->as.unary.operand)) {
                if (cg_materialize_to_local(cg, &inner, "_addr") == NULL) {
                    er_free(&inner);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            }

            buf_init(&b);
            buf_append_fmt(&b, "(&(%s))", inner.c_expr);
            out->c_expr = b.data;
            out->type = cgtype_new(CG_TYPE_POINTER);
            if (out->type == NULL) {
                er_free(&inner);
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            out->type->element = cgtype_clone(inner.type);
            if (out->type->element == NULL) {
                er_free(&inner);
                cgtype_free(out->type);
                out->type = NULL;
                free(out->c_expr);
                out->c_expr = NULL;
                return false;
            }
            er_free(&inner);
            out->owns_ref = false;
            return out->c_expr != NULL;
        }

        er_free(&inner);
        return cg_fail(cg, e->token,
            "CE0092", "codegen: this operand type does not support ABI pointer formation; only string, ABI scalar, fielded @abi value, and ABI-compatible array operands are allowed here");
    }
    const char *op = NULL;
    bool require_bool = false;
    bool require_int = false;
    switch (e->as.unary.op) {
        case FENG_TOKEN_MINUS: op = "-"; break;
        case FENG_TOKEN_PLUS:  op = "+"; break;
        case FENG_TOKEN_NOT:   op = "!"; require_bool = true; break;
        case FENG_TOKEN_TILDE: op = "~"; require_int = true; break;
        default:
            er_free(&inner);
            return cg_fail(cg, e->token, "CE0093", "codegen: unsupported unary operator");
    }
    if (require_bool && inner.type->kind != CG_TYPE_BOOL) {
        er_free(&inner);
        return cg_fail(cg, e->token, "CE0094", "codegen: '!' requires bool operand");
    }
    if (require_int && !cgtype_is_integer(inner.type->kind)) {
        er_free(&inner);
        return cg_fail(cg, e->token, "CE0095", "codegen: '~' requires integer operand");
    }
    if (!require_bool && !require_int && !cgtype_is_numeric(inner.type->kind)) {
        er_free(&inner);
        return cg_fail(cg, e->token, "CE0096", "codegen: unary +/- requires numeric operand");
    }
    Buf b; buf_init(&b);
    /* Parenthesize the operand so composite c_expr (e.g. infix match's
     * `_mt.tag == 1U || _mt.tag == 2U`) is treated atomically under
     * C operator precedence. Without parens, `!_mt.tag == 1U` parses as
     * `(!_mt.tag) == 1U`, not `!(_mt.tag == 1U)`. */
    buf_append_fmt(&b, "(%s(%s))", op, inner.c_expr);
    out->c_expr = b.data;
    out->type = inner.type;
    inner.type = NULL;
    er_free(&inner);
    return out->c_expr && out->type;
}

/* Borrowed compile-time description of the reification context that a
 * generated lambda invoke body must recover from its closure environment.
 * Descriptor objects themselves are static read-only data and therefore do
 * not participate in ARC or the closure's managed-field metadata. */
typedef struct CGLambdaReificationContext {
    const char *function_descriptor_c_name;
    const FengDecl *owner_type_decl;
    size_t generic_param_count;
    const char *const *generic_param_descriptor_c_names;
} CGLambdaReificationContext;

/* Snapshot the active callable context before lambda emission temporarily
 * switches to the generated invoke function's local scope. */
static CGLambdaReificationContext cg_lambda_reification_context(const CG *cg) {
    CGLambdaReificationContext context;

    memset(&context, 0, sizeof(context));
    if (cg == NULL) {
        return context;
    }
    context.function_descriptor_c_name =
        cg->generic_function_descriptor_c_name;
    context.owner_type_decl = cg->generic_type_method_decl;
    if (cg->in_generic_fn) {
        context.generic_param_count = cg->generic_fn_type_param_count;
        context.generic_param_descriptor_c_names =
            cg->generic_fn_type_param_descs;
    }
    return context;
}

/* Return the C descriptor type used by a generic owner. */
static const char *cg_lambda_owner_descriptor_c_type(
    const CGLambdaReificationContext *context) {
    if (context == NULL || context->owner_type_decl == NULL ||
        context->owner_type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    return cg_type_decl_is_value_semantics(context->owner_type_decl)
               ? "FengAggregateDescriptor"
               : "FengTypeDescriptor";
}

static bool cg_emit_lambda_closure_type(CG *cg,
                                        const UserSpec *spec,
                                        const char *closure_struct_name,
                                        const char *closure_desc_name,
                                        const Local *const *captures,
                                        char *const *capture_field_names,
                                        size_t capture_count,
                                        const CGLambdaReificationContext *reification,
                                        FengToken blame) {
    Buf *td = &cg->type_defs;
    const char *owner_descriptor_type =
        cg_lambda_owner_descriptor_c_type(reification);

    buf_append_fmt(td, "struct %s {\n", closure_struct_name);
    buf_append_cstr(td, "    FengManagedHeader _hdr;\n    void *_self;\n    ");
    cg_emit_callable_abi_return_type(td,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_cstr(td, " (*invoke)(void *_closure");
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(td, ", ");
        cg_emit_callable_abi_param_type(td,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
    }
    cg_append_callable_abi_out_parameter(td,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(td, ");\n");
    for (size_t i = 0; i < capture_count; ++i) {
        if (!captures[i]->capture_cell_uses_dynamic_storage &&
            captures[i]->capture_cell_struct_name == NULL) {
            return cg_fail(cg, blame,
                "CE0097", "codegen: lambda capture was not lowered to a capture cell");
        }
        if (captures[i]->capture_cell_uses_dynamic_storage) {
            buf_append_fmt(td,
                           "    FengArray *%s;\n",
                           capture_field_names[i]);
        } else {
            buf_append_fmt(td, "    struct %s *%s;\n",
                           captures[i]->capture_cell_struct_name,
                           capture_field_names[i]);
        }
    }
    if (reification != NULL &&
        reification->function_descriptor_c_name != NULL) {
        buf_append_cstr(td,
            "    const FengFunctionDescriptor *_reified_function_desc;\n");
    }
    if (owner_descriptor_type != NULL) {
        buf_append_fmt(td,
                       "    const %s *_reified_owner_desc;\n",
                       owner_descriptor_type);
    }
    if (reification != NULL) {
        for (size_t i = 0U; i < reification->generic_param_count; ++i) {
            buf_append_fmt(td,
                "    const FengGenericParamDescriptor *_reified_param%zu;\n",
                i);
        }
    }
    buf_append_cstr(td, "};\n\n");

    buf_append_fmt(td,
        "static void %s__release_children(void *_self) {\n"
        "    struct %s *_o = (struct %s *)_self;\n"
        "    feng_release(_o->_self);\n"
        "    _o->_self = NULL;\n",
        closure_desc_name,
        closure_struct_name,
        closure_struct_name);
    for (size_t i = 0; i < capture_count; ++i) {
        buf_append_fmt(td,
            "    feng_release(_o->%s);\n"
            "    _o->%s = NULL;\n",
            capture_field_names[i],
            capture_field_names[i]);
    }
    buf_append_cstr(td, "}\n\n");

    buf_append_fmt(td,
        "static const FengManagedFieldDescriptor %s__managed_fields[] = {\n"
        "    { offsetof(struct %s, _self), NULL, NULL },\n",
        closure_desc_name,
        closure_struct_name);
    for (size_t i = 0; i < capture_count; ++i) {
        buf_append_fmt(td, "    { offsetof(struct %s, %s), NULL, NULL },\n",
                       closure_struct_name,
                       capture_field_names[i]);
    }
    buf_append_cstr(td, "};\n\n");

    buf_append_fmt(td,
        "static const FengTypeDescriptor %s = {\n"
        "    .name = \"%s\",\n"
        "    .size = sizeof(struct %s),\n"
        "    .finalizer = NULL,\n"
        "    .release_children = %s__release_children,\n"
        "    .is_potentially_cyclic = true,\n"
        "    .managed_field_count = %zu,\n"
        "    .managed_fields = %s__managed_fields,\n"
        "    .equal_fn = NULL,\n"
        "    .reified_generic_params_count = 0,\n"
        "};\n\n",
        closure_desc_name,
        closure_struct_name,
        closure_struct_name,
        closure_desc_name,
        capture_count + 1U,
        closure_desc_name);
    return true;
}

static void cg_emit_lambda_invoke_proto(CG *cg,
                                        const UserSpec *spec,
                                        const char *invoke_name) {
    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", invoke_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(&cg->headers,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->headers, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->headers,
                                         spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");
}

static bool cg_emit_lambda_invoke_function(CG *cg,
                                           const UserSpec *spec,
                                           const FengExpr *lambda_expr,
                                           const char *closure_struct_name,
                                           const char *invoke_name,
                                           const Local *const *captures,
                                           FengSlice const *capture_names,
                                           char *const *capture_field_names,
                                           size_t capture_count,
                                           const CGLambdaReificationContext *reification,
                                           FengToken blame) {
    Buf fn;
    Buf *saved_body = cg->cur_body;
    Scope *saved_scope = cg->cur_scope;
    int saved_tmp_counter = cg->tmp_counter;
    int saved_local_counter = cg->local_counter;
    int saved_loop_depth = cg->loop_depth;
    int saved_try_depth = cg->try_depth;
    int saved_active_exception_frame_count = cg->active_exception_frame_count;
    int saved_active_caught_unwind_count = cg->active_caught_unwind_count;
    CGType *saved_return_type = cg->cur_return_type;
    bool saved_is_main = cg->cur_fn_is_main;
    bool saved_callable_return_uses_out = cg->callable_return_uses_out;
    bool saved_has_frame_marker = cg->cur_function_has_frame_marker;
    char **saved_captured_names = cg->captured_binding_names;
    size_t saved_captured_name_count = cg->captured_binding_name_count;
    bool saved_captures_self = cg->current_callable_captures_self;
    const char *saved_frame_backend_symbol = cg->current_frame_backend_symbol;
    char **body_captured_names = NULL;
    size_t body_captured_name_count = 0U;
    bool body_captures_self = false;
    Scope *fn_scope = NULL;
    bool ok = false;
    const char *owner_descriptor_type =
        cg_lambda_owner_descriptor_c_type(reification);

    buf_init(&fn);
    if (!cg_compute_capture_requirements_in_lambda_body(lambda_expr,
                                                        &body_captured_names,
                                                        &body_captured_name_count,
                                                        &body_captures_self)) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    fn_scope = scope_push(NULL);
    if (fn_scope == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    cg->cur_body = &fn;
    cg->cur_scope = fn_scope;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    cg->loop_depth = 0;
    cg->try_depth = 0;
    cg->active_exception_frame_count = 0;
    cg->active_caught_unwind_count = 0;
    cg->cur_function_has_frame_marker = false;
    cg->cur_return_type = spec->callable_return_type;
    cg->callable_return_uses_out =
        spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS;
    cg->cur_fn_is_main = false;
    cg->captured_binding_names = body_captured_names;
    cg->captured_binding_name_count = body_captured_name_count;
    cg->current_callable_captures_self = body_captures_self;

    buf_append_cstr(&fn, "static ");
    cg_emit_callable_abi_return_type(&fn,
                                     spec->callable_return_type,
                                     spec->callable_return_abi_kind);
    buf_append_fmt(&fn, " %s(void *_closure", invoke_name);
    for (size_t i = 0; i < spec->callable_param_count; ++i) {
        buf_append_cstr(&fn, ", ");
        cg_emit_callable_abi_param_type(&fn,
                                        spec->callable_param_types[i],
                                        spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&fn, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&fn,
                                         spec->callable_return_abi_kind);
    buf_append_fmt(&fn,
        ") {\n"
        "    struct %s *_lambda = (struct %s *)_closure;\n"
        "    (void)_lambda;\n",
        closure_struct_name,
        closure_struct_name);
    if (reification != NULL &&
        reification->function_descriptor_c_name != NULL) {
        buf_append_fmt(&fn,
            "    const FengFunctionDescriptor *%s = "
            "_lambda->_reified_function_desc;\n"
            "    (void)%s;\n",
            reification->function_descriptor_c_name,
            reification->function_descriptor_c_name);
    }
    if (owner_descriptor_type != NULL) {
        buf_append_fmt(&fn,
            "    const %s *_type_desc = _lambda->_reified_owner_desc;\n"
            "    const %s *_td = _type_desc;\n"
            "    (void)_type_desc; (void)_td;\n",
            owner_descriptor_type,
            owner_descriptor_type);
    }
    if (reification != NULL) {
        for (size_t i = 0U; i < reification->generic_param_count; ++i) {
            const char *descriptor_name =
                reification->generic_param_descriptor_c_names != NULL
                    ? reification->generic_param_descriptor_c_names[i]
                    : NULL;

            if (descriptor_name == NULL) {
                cg_fail(cg, blame,
                    "CE0097", "codegen: lambda reification context is missing a generic parameter descriptor");
                goto cleanup;
            }
            buf_append_fmt(&fn,
                "    const FengGenericParamDescriptor *%s = "
                "_lambda->_reified_param%zu;\n"
                "    (void)%s;\n",
                descriptor_name,
                i,
                descriptor_name);
        }
    }
    if (!cg_emit_function_eh_prologue(cg, lambda_expr->token)) {
        goto cleanup;
    }
    {
        Buf frame_name;
        buf_init(&frame_name);
        if (lambda_expr->token.line > 0U) {
            buf_append_fmt(&frame_name, "lambda@%u", lambda_expr->token.line);
        } else {
            buf_append_cstr(&frame_name, "lambda");
        }
        if (frame_name.data == NULL ||
            !cg_debug_set_current_frame(cg,
                                        invoke_name,
                                        frame_name.data,
                                        FENG_CODEGEN_MAPING_FRAME_VISIBLE,
                                        blame) ||
            !cg_debug_add_current_frame_module_binding_records(cg, blame)) {
            buf_free(&frame_name);
            goto cleanup;
        }
        buf_free(&frame_name);
    }

    for (size_t i = 0; i < capture_count; ++i) {
        Buf cell_expr;
        Buf value_expr;
        char *capture_descriptor_name = NULL;
        char *capture_size_name = NULL;
        bool dynamic_capture =
            captures[i]->capture_cell_uses_dynamic_storage;
        buf_init(&cell_expr);
        buf_init(&value_expr);
        buf_append_fmt(&cell_expr, "_lambda->%s", capture_field_names[i]);
        if (dynamic_capture) {
            buf_append_fmt(&value_expr,
                           "((void *)feng_array_data(_lambda->%s))",
                           capture_field_names[i]);
            if (!cg_emit_dynamic_capture_storage_metadata(
                    cg,
                    captures[i]->type,
                    blame,
                    &capture_descriptor_name,
                    &capture_size_name)) {
                buf_free(&cell_expr);
                buf_free(&value_expr);
                goto cleanup;
            }
        } else {
            buf_append_fmt(&value_expr,
                           "(_lambda->%s->value)",
                           capture_field_names[i]);
        }
        if (cell_expr.data == NULL || value_expr.data == NULL ||
            !cg_scope_add_capture_alias(fn_scope,
                                        capture_names[i],
                                        value_expr.data,
                                        cell_expr.data,
                                        captures[i]->capture_cell_struct_name,
                                        captures[i]->capture_cell_desc_name,
                                        captures[i]->type,
                                        dynamic_capture) ||
            !scope_copy_last_binding_mutability(fn_scope, captures[i])) {
            buf_free(&cell_expr);
            buf_free(&value_expr);
            free(capture_descriptor_name);
            free(capture_size_name);
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (dynamic_capture) {
            bool marked = captures[i]->type->kind == CG_TYPE_GENERIC_PARAM
                              ? scope_mark_last_erased_generic_storage(
                                    fn_scope,
                                    capture_descriptor_name,
                                    capture_size_name)
                              : scope_mark_last_reified_storage(
                                    fn_scope,
                                    capture_descriptor_name,
                                    capture_size_name);
            if (!marked) {
                buf_free(&cell_expr);
                buf_free(&value_expr);
                free(capture_descriptor_name);
                free(capture_size_name);
                cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }
        if (!cg_debug_add_variable_record_slice_cgtype(cg,
                                                       NULL,
                                                       capture_names[i],
                                                       value_expr.data,
                                                       captures[i]->type,
                                                       cg_slice_equals(capture_names[i],
                                                                       (FengSlice){"self", 4U})
                                                           ? FENG_CODEGEN_MAPING_VARIABLE_SELF
                                                           : FENG_CODEGEN_MAPING_VARIABLE_CAPTURE,
                                                       blame)) {
            buf_free(&cell_expr);
            buf_free(&value_expr);
            free(capture_descriptor_name);
            free(capture_size_name);
            goto cleanup;
        }
        buf_free(&cell_expr);
        buf_free(&value_expr);
        free(capture_descriptor_name);
        free(capture_size_name);
    }

    for (size_t i = 0; i < lambda_expr->as.lambda.param_count; ++i) {
        const FengParameter *param = &lambda_expr->as.lambda.params[i];
        char arg_name[32];
        char *param_expr = NULL;
        CGCallableABIKind abi_kind = spec->callable_param_abi_kinds[i];
        int n = snprintf(arg_name, sizeof arg_name, "_arg%zu", i);
        if (n < 0 || (size_t)n >= sizeof arg_name) {
            cg_fail(cg, param->token, "CE0098", "codegen: lambda argument name overflow");
            goto cleanup;
        }
        buf_append_fmt(&fn, "    (void)%s;\n", arg_name);
        if (abi_kind == CG_CALLABLE_ABI_ERASED_POINTER) {
            char *ctype = cg_ctype_dup(spec->callable_param_types[i]);
            Buf cast;

            if (ctype == NULL) {
                cg_fail(cg, param->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
            buf_init(&cast);
            buf_append_fmt(&cast, "((%s)%s)", ctype, arg_name);
            free(ctype);
            param_expr = cast.data;
        } else if (abi_kind == CG_CALLABLE_ABI_ADDRESS &&
                   spec->callable_param_types[i]->kind ==
                       CG_TYPE_GENERIC_PARAM) {
            param_expr = strdup(arg_name);
        } else if (abi_kind == CG_CALLABLE_ABI_ADDRESS &&
                   !cg_type_uses_reified_storage(cg,
                                                 spec->callable_param_types[i])) {
            char *ctype = cg_ctype_dup(spec->callable_param_types[i]);
            char *value_name = cg_fresh_temp(cg, "_call_arg");

            if (ctype == NULL || value_name == NULL) {
                free(ctype);
                free(value_name);
                cg_fail(cg, param->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
            buf_append_fmt(&fn,
                           "    %s %s = *(const %s *)%s;\n",
                           ctype,
                           value_name,
                           ctype,
                           arg_name);
            free(ctype);
            param_expr = value_name;
        } else {
            param_expr = strdup(arg_name);
        }
        if (param_expr == NULL) {
            cg_fail(cg, param->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (cg_current_callable_captures_name(cg, param->name.data, param->name.length)) {
            if (!cg_scope_bind_capture_cell(cg,
                                            fn_scope,
                                            param->name,
                                            spec->callable_param_types[i],
                                            param->token,
                                            param_expr,
                                            true,
                                            false,
                                            true,
                                            FENG_CODEGEN_MAPING_VARIABLE_PARAM) ||
                !scope_mark_last_binding_mutability(fn_scope,
                                                    param->mutability)) {
                free(param_expr);
                goto cleanup;
            }
            free(param_expr);
            continue;
        }
        char *param_name = strndup(param->name.data, param->name.length);
        CGType *param_type = cgtype_clone(spec->callable_param_types[i]);
        if (param_name == NULL || param_type == NULL ||
            !scope_add(fn_scope, param_name, param_expr, param_type, true) ||
            !scope_mark_last_binding_mutability(fn_scope,
                                                param->mutability)) {
            free(param_name);
            free(param_expr);
            cgtype_free(param_type);
            cg_fail(cg, param->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (abi_kind == CG_CALLABLE_ABI_ADDRESS &&
            (spec->callable_param_types[i]->kind == CG_TYPE_GENERIC_PARAM ||
             cg_type_uses_reified_storage(cg,
                                          spec->callable_param_types[i])) &&
            !cg_mark_last_shared_address_parameter(
                cg,
                fn_scope,
                spec->callable_param_types[i],
                param->token)) {
            free(param_name);
            free(param_expr);
            goto cleanup;
        }
        if (!cg_debug_add_variable_record_slice_cgtype(cg,
                                                       arg_name,
                                                       param->name,
                                                       NULL,
                                                       spec->callable_param_types[i],
                                                       FENG_CODEGEN_MAPING_VARIABLE_PARAM,
                                                       param->token)) {
            free(param_name);
            free(param_expr);
            goto cleanup;
        }
        free(param_name);
        free(param_expr);
    }

    if (lambda_expr->as.lambda.is_block_body) {
        if (!cg_emit_block(cg, lambda_expr->as.lambda.body_block)) goto cleanup;
        cg_release_scope(cg, fn_scope);
        cg_emit_function_fallthrough_cleanup(cg);
        if (spec->callable_return_type->kind == CG_TYPE_VOID) {
            buf_append_cstr(&fn, "    return;\n");
        } else {
            buf_append_cstr(&fn,
                "    feng_panic(\"lambda reached end without return\");\n");
        }
    } else {
        ExprResult result;
        if (!cg_emit_line_directive(cg, lambda_expr->token)) {
            goto cleanup;
        }
        if (spec->callable_return_type->kind == CG_TYPE_VOID) {
            if (!cg_emit_expr(cg, lambda_expr->as.lambda.body, &result)) {
                goto cleanup;
            }
        } else if (!cg_emit_expr_for_expected_type(
                       cg,
                       lambda_expr->as.lambda.body,
                       spec->callable_return_type,
                       &result)) {
            goto cleanup;
        }
        if (spec->callable_return_type->kind == CG_TYPE_VOID) {
            buf_append_fmt(&fn, "    %s;\n", result.c_expr);
            er_free(&result);
            cg_release_scope(cg, fn_scope);
            cg_emit_function_fallthrough_cleanup(cg);
            buf_append_cstr(&fn, "    return;\n");
        } else if (!cg_emit_return_expr_result(cg, lambda_expr->token, &result)) {
            goto cleanup;
        }
    }
    buf_append_cstr(&fn, "}\n\n");
    if (fn.data == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    buf_append(&cg->witness_defs, fn.data, fn.length);
    ok = true;

cleanup:
    cg->cur_body = saved_body;
    cg->cur_scope = saved_scope;
    cg->tmp_counter = saved_tmp_counter;
    cg->local_counter = saved_local_counter;
    cg->loop_depth = saved_loop_depth;
    cg->try_depth = saved_try_depth;
    cg->active_exception_frame_count = saved_active_exception_frame_count;
    cg->active_caught_unwind_count = saved_active_caught_unwind_count;
    cg->cur_return_type = saved_return_type;
    cg->callable_return_uses_out = saved_callable_return_uses_out;
    cg->cur_fn_is_main = saved_is_main;
    cg->cur_function_has_frame_marker = saved_has_frame_marker;
    cg->captured_binding_names = saved_captured_names;
    cg->captured_binding_name_count = saved_captured_name_count;
    cg->current_callable_captures_self = saved_captures_self;
    cg->current_frame_backend_symbol = saved_frame_backend_symbol;
    if (fn_scope != NULL) scope_pop_free(fn_scope);
    for (size_t i = 0; i < body_captured_name_count; ++i) free(body_captured_names[i]);
    free(body_captured_names);
    buf_free(&fn);
    return ok;
}

static bool cg_emit_callable_lambda_coercion(CG *cg,
                                             const FengExpr *e,
                                             const FengExpr *lambda_expr,
                                             const FengSpecCoercionSite *cs,
                                             ExprResult *out) {
    const UserSpec *target_spec = NULL;
    const Local **captures = NULL;
    FengSlice *capture_names = NULL;
    char **capture_field_names = NULL;
    size_t capture_count = 0U;
    size_t capture_capacity = 0U;
    char *closure_struct_name = NULL;
    char *closure_desc_name = NULL;
    char *invoke_name = NULL;
    char *closure_var = NULL;
    bool ok = false;
    CGLambdaReificationContext reification =
        cg_lambda_reification_context(cg);
    const char *owner_descriptor_type =
        cg_lambda_owner_descriptor_c_type(&reification);
    FengToken blame = e ? e->token : (lambda_expr ? lambda_expr->token : (FengToken){0});

    er_init(out);
    if (lambda_expr == NULL || lambda_expr->kind != FENG_EXPR_LAMBDA) {
        return cg_fail(cg, blame,
            "CE0099", "codegen: callable lambda coercion is missing lambda semantic data");
    }
    if (!cg_resolve_coercion_target_user_spec(cg, cs, blame, &target_spec)) {
        return false;
    }
    if (target_spec == NULL || target_spec->form != FENG_SPEC_FORM_CALLABLE) {
        return cg_fail(cg, blame,
            "CE0100", "codegen: callable lambda coercion target was not registered as a callable-form spec");
    }
    if (target_spec->callable_param_count != lambda_expr->as.lambda.param_count) {
        return cg_fail(cg, blame,
            "CE0101", "codegen: callable lambda coercion parameter count mismatch");
    }

    capture_capacity = lambda_expr->as.lambda.capture_count +
                       (lambda_expr->as.lambda.captures_self ? 1U : 0U);
    if (capture_capacity > 0U) {
        captures = calloc(capture_capacity, sizeof *captures);
        capture_names = calloc(capture_capacity, sizeof *capture_names);
        capture_field_names = calloc(capture_capacity, sizeof *capture_field_names);
        if (captures == NULL || capture_names == NULL || capture_field_names == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }

    for (size_t i = 0; i < lambda_expr->as.lambda.capture_count; ++i) {
        const FengLambdaCapture *capture = &lambda_expr->as.lambda.captures[i];
        if (capture->kind != FENG_LAMBDA_CAPTURE_LOCAL) {
            continue;
        }
        const Local *local = scope_lookup(cg->cur_scope,
                                          capture->name.data,
                                          capture->name.length);
        if (local == NULL || local->capture_cell_c_name == NULL ||
            (!local->capture_cell_uses_dynamic_storage &&
             (local->capture_cell_struct_name == NULL ||
              local->capture_cell_desc_name == NULL))) {
            cg_fail(cg, blame,
                "CE0102", "codegen: lambda capture '%.*s' was not lowered to a capture cell",
                (int)capture->name.length,
                capture->name.data);
            goto cleanup;
        }
        captures[capture_count] = local;
        capture_names[capture_count] = capture->name;
        Buf fb;
        buf_init(&fb);
        buf_append_fmt(&fb, "_cap%zu", capture_count);
        capture_field_names[capture_count] = fb.data;
        if (capture_field_names[capture_count] == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        capture_count += 1U;
    }
    if (lambda_expr->as.lambda.captures_self) {
        FengSlice self_name = {"self", 4U};
        const Local *local = scope_lookup(cg->cur_scope, "self", 4U);
        if (local == NULL || local->capture_cell_c_name == NULL ||
            (!local->capture_cell_uses_dynamic_storage &&
             (local->capture_cell_struct_name == NULL ||
              local->capture_cell_desc_name == NULL))) {
            cg_fail(cg, blame,
                "CE0103", "codegen: lambda self capture was not lowered to a capture cell");
            goto cleanup;
        }
        captures[capture_count] = local;
        capture_names[capture_count] = self_name;
        Buf fb;
        buf_init(&fb);
        buf_append_fmt(&fb, "_cap%zu", capture_count);
        capture_field_names[capture_count] = fb.data;
        if (capture_field_names[capture_count] == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        capture_count += 1U;
    }

    size_t lambda_id = cg->lambda_counter++;
    {
        Buf sb;
        Buf db;
        Buf ib;
        buf_init(&sb);
        buf_init(&db);
        buf_init(&ib);
        buf_append_fmt(&sb, "FengLambda__%s__%zu",
                       cg->module_mangle ? cg->module_mangle : "mod",
                       lambda_id);
        buf_append_fmt(&db, "FengLambdaDesc__%s__%zu",
                       cg->module_mangle ? cg->module_mangle : "mod",
                       lambda_id);
        buf_append_fmt(&ib, "FengLambdaInvoke__%s__%zu",
                       cg->module_mangle ? cg->module_mangle : "mod",
                       lambda_id);
        closure_struct_name = sb.data;
        closure_desc_name = db.data;
        invoke_name = ib.data;
    }
    if (closure_struct_name == NULL || closure_desc_name == NULL || invoke_name == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    if (!cg_emit_lambda_closure_type(cg,
                                     target_spec,
                                     closure_struct_name,
                                     closure_desc_name,
                                     captures,
                                     capture_field_names,
                                     capture_count,
                                     &reification,
                                     blame)) {
        goto cleanup;
    }
    cg_emit_lambda_invoke_proto(cg, target_spec, invoke_name);
    if (!cg_emit_lambda_invoke_function(cg,
                                        target_spec,
                                        lambda_expr,
                                        closure_struct_name,
                                        invoke_name,
                                        captures,
                                        capture_names,
                                        capture_field_names,
                                        capture_count,
                                        &reification,
                                        blame)) {
        goto cleanup;
    }

    closure_var = cg_fresh_temp(cg, "_lambda");
    if (closure_var == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    buf_append_fmt(cg->cur_body,
        "    struct %s *%s = (struct %s *)feng_object_new(&%s);\n"
        "    %s->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
        "    %s->_self = NULL;\n"
        "    %s->invoke = %s;\n",
        closure_struct_name,
        closure_var,
        closure_struct_name,
        closure_desc_name,
        closure_var,
        closure_var,
        closure_var,
        invoke_name);
    if (reification.function_descriptor_c_name != NULL) {
        buf_append_fmt(cg->cur_body,
            "    %s->_reified_function_desc = %s;\n",
            closure_var,
            reification.function_descriptor_c_name);
    }
    if (owner_descriptor_type != NULL) {
        buf_append_fmt(cg->cur_body,
            "    %s->_reified_owner_desc = _type_desc;\n",
            closure_var);
    }
    for (size_t i = 0U; i < reification.generic_param_count; ++i) {
        const char *descriptor_name =
            reification.generic_param_descriptor_c_names != NULL
                ? reification.generic_param_descriptor_c_names[i]
                : NULL;

        if (descriptor_name == NULL) {
            cg_fail(cg, blame,
                "CE0097", "codegen: lambda reification context is missing a generic parameter descriptor");
            goto cleanup;
        }
        buf_append_fmt(cg->cur_body,
            "    %s->_reified_param%zu = %s;\n",
            closure_var,
            i,
            descriptor_name);
    }
    for (size_t i = 0; i < capture_count; ++i) {
        buf_append_fmt(cg->cur_body,
            "    %s->%s = NULL;\n"
            "    feng_assign((void **)&%s->%s, (void *)%s);\n",
            closure_var,
            capture_field_names[i],
            closure_var,
            capture_field_names[i],
            captures[i]->capture_cell_c_name);
    }

    {
        Buf expr;
        buf_init(&expr);
        buf_append_fmt(&expr, "(struct %s *)%s",
                       target_spec->c_closure_struct_name,
                       closure_var);
        out->c_expr = expr.data;
    }
    out->type = cgtype_new(CG_TYPE_CALLABLE);
    if (out->c_expr == NULL || out->type == NULL) {
        er_free(out);
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    out->type->user_spec = target_spec;
    out->owns_ref = true;
    ok = true;

cleanup:
    if (!ok) er_free(out);
    if (capture_field_names != NULL) {
        for (size_t i = 0; i < capture_capacity; ++i) free(capture_field_names[i]);
    }
    free(capture_field_names);
    free(capture_names);
    free(captures);
    free(closure_struct_name);
    free(closure_desc_name);
    free(invoke_name);
    free(closure_var);
    return ok;
}

static bool cg_emit_identifier(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    const Local *l = scope_lookup(cg->cur_scope, e->as.identifier.data,
                                  e->as.identifier.length);
    if (l) {
        out->c_expr = strdup(l->c_name);
        out->type = cgtype_clone(l->type);
        out->owns_ref = false;  /* borrow from local slot */
        out->managed_identity_is_stable =
            l->binding_mutability_known && !l->binding_is_rebindable;
        out->is_addressable = true;
        out->is_storage_address = l->is_storage_address;
        out->uses_erased_generic_storage =
            l->uses_erased_generic_storage;
        if (l->uses_erased_generic_storage) {
            out->erased_generic_descriptor_c_name =
                strdup(l->erased_generic_descriptor_c_name);
            out->erased_generic_size_c_name =
                strdup(l->erased_generic_size_c_name);
        }
        out->uses_reified_storage = l->uses_reified_storage;
        if (l->uses_reified_storage) {
            out->reified_descriptor_c_name =
                strdup(l->reified_descriptor_c_name);
            out->reified_size_c_name = l->reified_size_c_name != NULL
                                           ? strdup(l->reified_size_c_name)
                                           : NULL;
        }
        return out->c_expr && out->type;
    }
    const ModuleBinding *mb = cg_find_module_binding(cg,
        e->as.identifier.data, e->as.identifier.length);
    if (mb) {
        cg_emit_module_binding_ensure_init_call(cg, mb);
        out->c_expr = cg_module_binding_slot_expr_dup(mb);
        out->type = cgtype_clone(mb->type);
        out->owns_ref = false;  /* borrow from static slot */
        out->managed_identity_is_stable = !mb->is_var;
        out->is_addressable = true;
        return out->c_expr && out->type;
    }
    {
        const FengDecl *imported_binding_decl =
            cg_resolve_imported_module_binding_decl(cg, e);

        if (imported_binding_decl != NULL) {
            return cg_emit_imported_binding_expr(cg, imported_binding_decl, out);
        }
    }
    /* G4: generic type parameter used as a value-level identifier (e.g.,
     * `T` in `func f<T: Factory<T>>() { T.make(); T.tag }`). Resolve to
     * a synthetic CG_TYPE_GENERIC_PARAM ExprResult whose c_expr is the
     * C descriptor name. Downstream member/call dispatch recognises the
     * type and routes through the constraint spec's witness table. */
    if (cg->generic_fn_type_param_names != NULL) {
        for (size_t i = 0U; i < cg->generic_fn_type_param_count; ++i) {
            const char *name = cg->generic_fn_type_param_names[i];
            if (name == NULL ||
                strncmp(name, e->as.identifier.data,
                        e->as.identifier.length) != 0 ||
                strlen(name) != e->as.identifier.length) {
                continue;
            }
            const char *desc_name =
                (cg->generic_fn_type_param_descs != NULL &&
                 i < cg->generic_fn_type_param_count)
                    ? cg->generic_fn_type_param_descs[i]
                    : NULL;
            if (desc_name == NULL) {
                continue;
            }
            CGType *t = cgtype_new(CG_TYPE_GENERIC_PARAM);
            if (t == NULL) {
                return cg_fail(cg, e->token,
                               "IE0001", "codegen: out of memory");
            }
            t->generic_param_index = i;
            t->user_spec = cg_generic_param_constraint_spec(cg, i);
            out->c_expr = strdup(desc_name);
            out->type = t;
            out->owns_ref = false;
            return out->c_expr != NULL;
        }
    }
    return cg_fail(cg, e->token,
        "CE0104", "codegen: identifier '%.*s' not found",
        (int)e->as.identifier.length, e->as.identifier.data);
}

static bool cg_emit_callable_function_coercion(CG *cg,
                                               const FengExpr *e,
                                               const FengSpecCoercionSite *cs,
                                               ExprResult *out) {
    const UserSpec *target_spec = NULL;
    const char *callable_var = NULL;
    const GenericFn *generic_function = NULL;

    er_init(out);
    if (!cg_resolve_coercion_target_user_spec(cg, cs, e->token, &target_spec)) {
        return false;
    }
    if (target_spec == NULL || target_spec->form != FENG_SPEC_FORM_CALLABLE) {
        return cg_fail(cg, e->token,
            "CE0105", "codegen: callable coercion target was not registered as a callable-form spec");
    }
    if (cs->callable_decl == NULL || cs->callable_decl->kind != FENG_DECL_FUNCTION) {
        return cg_fail(cg, e->token,
            "CE0106", "codegen: only top-level function callable coercions are supported in this step");
    }
    generic_function = cg_find_generic_fn_by_decl(cg, cs->callable_decl);
    if (generic_function != NULL) {
        FengReifiableCallableDep dependency;
        char *descriptor_expr;
        Buf expression;

        memset(&dependency, 0, sizeof dependency);
        dependency.purpose = FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE;
        dependency.kind = FENG_RESOLVED_CALLABLE_FUNCTION;
        dependency.function_decl = cs->callable_decl;
        dependency.callable_type_args = cs->callable_type_args;
        dependency.callable_type_arg_count = cs->callable_type_arg_count;
        dependency.target_callable_type_ref = cs->target_spec_type_ref;
        descriptor_expr = cg_try_callable_descriptor_expr_for_dep(
            cg, &dependency);
        if (descriptor_expr == NULL &&
            !cg_emit_closed_callable_dep_expr(cg,
                                              &dependency,
                                              NULL,
                                              0U,
                                              NULL,
                                              cg->cur_program,
                                              e->token,
                                              &descriptor_expr)) {
            return false;
        }
        buf_init(&expression);
        buf_append_fmt(&expression,
                       "(struct %s *)((%s)->callable_value.static_value)",
                       target_spec->c_closure_struct_name,
                       descriptor_expr);
        free(descriptor_expr);
        out->c_expr = expression.data;
        out->type = cgtype_new(CG_TYPE_CALLABLE);
        if (out->c_expr == NULL || out->type == NULL) {
            er_free(out);
            return cg_fail(cg,
                           e->token,
                           "IE0001",
                           "codegen: out of memory");
        }
        out->type->user_spec = target_spec;
        out->owns_ref = false;
        return true;
    }
    if (!cg_ensure_callable_function_value(cg, target_spec, cs->callable_decl,
                                           e->token, &callable_var)) {
        return false;
    }
    {
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "&%s", callable_var);
        out->c_expr = b.data;
    }
    out->type = cgtype_new(CG_TYPE_CALLABLE);
    if (!out->c_expr || !out->type) {
        er_free(out);
        return false;
    }
    out->type->user_spec = target_spec;
    out->owns_ref = false;
    return true;
}

static bool cg_emit_abi_function_pointer_site(CG *cg,
                                              const FengExpr *e,
                                              const FengSpecCoercionSite *cs,
                                              ExprResult *out) {
    const UserSpec *target_spec = NULL;
    const FreeFn *fn = NULL;

    er_init(out);
    if (!cg_resolve_coercion_target_user_spec(cg, cs, e->token, &target_spec)) {
        return false;
    }
    if (target_spec == NULL || target_spec->form != FENG_SPEC_FORM_CALLABLE) {
        return cg_fail(cg, e->token,
            "CE0107", "codegen: ABI function pointer target was not registered as a callable-form spec");
    }
    if (cs->callable_source != FENG_SPEC_COERCION_CALLABLE_SOURCE_TOP_LEVEL_FN ||
        cs->callable_decl == NULL || cs->callable_decl->kind != FENG_DECL_FUNCTION) {
        return cg_fail(cg, e->token,
            "CE0108", "codegen: ABI function pointers currently support only top-level @abi functions");
    }
    fn = cg_find_free_fn_by_decl(cg, cs->callable_decl);
    if (fn == NULL || (fn->c_name == NULL && fn->c_abi_name == NULL)) {
        return cg_fail(cg, e->token,
            "CE0109", "codegen: ABI function pointer source function was not registered");
    }

    {
        Buf b;
        buf_init(&b);
        buf_append_fmt(&b, "&%s", cg_free_fn_has_abi_wrapper(fn) ? fn->c_abi_name : fn->c_name);
        out->c_expr = b.data;
    }
    out->type = cgtype_new(CG_TYPE_POINTER);
    if (out->c_expr == NULL || out->type == NULL) {
        er_free(out);
        return false;
    }
    out->type->element = cgtype_new(CG_TYPE_CALLABLE);
    if (out->type->element == NULL) {
        er_free(out);
        return false;
    }
    out->type->element->user_spec = target_spec;
    out->owns_ref = false;
    return true;
}

static bool cg_emit_callable_method_coercion(CG *cg,
                                             const FengExpr *e,
                                             const FengSpecCoercionSite *cs,
                                             ExprResult *out) {
    const FengExpr *source_expr = e;
    const UserSpec *target_spec = NULL;
    const UserMethod *method = NULL;
    const UserFit *selected_fit = NULL;
    const FengDecl *receiver_owner_decl = NULL;
    const char *bind_fn = NULL;
    char *callable_descriptor_expr = NULL;
    char *receiver_argument = NULL;
    ExprResult recv;

    er_init(out);
    if (source_expr != NULL &&
        source_expr->kind == FENG_EXPR_GENERIC_TARGET) {
        source_expr = source_expr->as.generic_target.target;
    }
    if (source_expr == NULL || source_expr->kind != FENG_EXPR_MEMBER ||
        source_expr->as.member.object == NULL) {
        return cg_fail(cg, e ? e->token : (FengToken){0},
            "CE0110", "codegen: callable method coercion requires a member expression");
    }
    if (!cg_resolve_coercion_target_user_spec(cg, cs, e->token, &target_spec)) {
        return false;
    }
    if (target_spec == NULL || target_spec->form != FENG_SPEC_FORM_CALLABLE) {
        return cg_fail(cg, e->token,
            "CE0105", "codegen: callable coercion target was not registered as a callable-form spec");
    }
    if (cs->callable_member != NULL &&
        cs->callable_member->is_static) {
        FengReifiableCallableDep dependency;
        Buf expression;

        if (cs->callable_receiver_type_ref == NULL) {
            return cg_fail(
                cg,
                e->token,
                "CE0111",
                "codegen: callable static method coercion is missing its owner type");
        }
        memset(&dependency, 0, sizeof(dependency));
        dependency.purpose = FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE;
        dependency.kind = cs->callable_owner_type_decl != NULL &&
                                  cs->callable_owner_type_decl->kind ==
                                      FENG_DECL_SPEC
                              ? FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD
                              : (cs->callable_fit_decl != NULL
                                     ? FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD
                                     : FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD);
        dependency.owner_type_decl = cs->callable_owner_type_decl;
        dependency.member = cs->callable_member;
        dependency.fit_decl = cs->callable_fit_decl;
        dependency.owner_instance_type_ref =
            cs->callable_receiver_type_ref;
        dependency.callable_type_args = cs->callable_type_args;
        dependency.callable_type_arg_count =
            cs->callable_type_arg_count;
        dependency.target_callable_type_ref = cs->target_spec_type_ref;
        callable_descriptor_expr =
            cg_try_callable_descriptor_expr_for_dep(cg, &dependency);
        if (callable_descriptor_expr == NULL &&
            !cg_emit_closed_callable_dep_expr(cg,
                                              &dependency,
                                              NULL,
                                              0U,
                                              NULL,
                                              cg->cur_program,
                                              e->token,
                                              &callable_descriptor_expr)) {
            return false;
        }
        if (callable_descriptor_expr == NULL) {
            return cg_fail(
                cg,
                e->token,
                "IE0002",
                "codegen: static method-value descriptor was not materialized");
        }
        buf_init(&expression);
        buf_append_fmt(&expression,
                       "((struct %s *)((%s)->callable_value.static_value))",
                       target_spec->c_closure_struct_name,
                       callable_descriptor_expr);
        free(callable_descriptor_expr);
        out->c_expr = expression.data;
        out->type = cgtype_new(CG_TYPE_CALLABLE);
        if (out->c_expr == NULL || out->type == NULL) {
            er_free(out);
            return cg_fail(cg,
                           e->token,
                           "IE0001",
                           "codegen: out of memory");
        }
        out->type->user_spec = target_spec;
        out->owns_ref = false;
        return true;
    }
    if (cs->callable_member == NULL || cs->callable_owner_type_decl == NULL) {
        return cg_fail(cg, e->token,
            "CE0111", "codegen: callable method coercion is missing semantic resolution data");
    }
    if (!cg_emit_expr(cg, source_expr->as.member.object, &recv)) {
        return false;
    }
    if (recv.type != NULL &&
        recv.type->kind == CG_TYPE_GENERIC_PARAM) {
        size_t generic_index = recv.type->generic_param_index;
        const UserSpec *receiver_spec =
            cg_generic_param_constraint_spec(cg, generic_index);
        const char *receiver_descriptor =
            cg_generic_param_desc_name(cg, generic_index);
        FengReifiableCallableDep dependency;
        char *receiver_address = NULL;
        char *descriptor_name = NULL;
        char *value_descriptor_name = NULL;
        char *closure_name = NULL;

        if (receiver_spec == NULL ||
            (receiver_spec->form != FENG_SPEC_FORM_OBJECT &&
             receiver_spec->form != FENG_SPEC_FORM_INTERSECTION) ||
            receiver_descriptor == NULL ||
            cg_user_spec_member_for_method_value(
                receiver_spec,
                cs->callable_member,
                target_spec,
                false) == NULL) {
            er_free(&recv);
            return cg_fail(
                cg,
                e->token,
                "CE0114",
                "codegen: constrained-generic method-value requirement was not registered");
        }
        if (!recv.is_addressable &&
            cg_materialize_to_local(cg,
                                    &recv,
                                    "_generic_method_receiver") == NULL) {
            er_free(&recv);
            return cg_fail(cg,
                           e->token,
                           "IE0001",
                           "codegen: failed to materialize constrained-generic method receiver");
        }
        receiver_address = cg_aggregate_result_address_dup(&recv);
        memset(&dependency, 0, sizeof(dependency));
        dependency.purpose = FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE;
        dependency.kind = FENG_RESOLVED_CALLABLE_SPEC_METHOD;
        dependency.owner_type_decl = cs->callable_owner_type_decl;
        dependency.member = cs->callable_member;
        dependency.owner_instance_type_ref =
            cs->callable_receiver_type_ref;
        dependency.target_callable_type_ref =
            cs->target_spec_type_ref;
        callable_descriptor_expr =
            cg_callable_descriptor_expr_for_dep(cg,
                                                &dependency,
                                                e->token);
        descriptor_name = cg_fresh_temp(cg, "_method_value_desc");
        value_descriptor_name =
            cg_fresh_temp(cg, "_callable_value_desc");
        closure_name = cg_fresh_temp(cg, "_method_value_closure");
        if (receiver_address == NULL ||
            callable_descriptor_expr == NULL ||
            descriptor_name == NULL || value_descriptor_name == NULL ||
            closure_name == NULL) {
            free(receiver_address);
            free(descriptor_name);
            free(value_descriptor_name);
            free(closure_name);
            free(callable_descriptor_expr);
            er_free(&recv);
            if (!cg->failed) {
                (void)cg_fail(cg,
                              e->token,
                              "IE0001",
                              "codegen: failed to lower a constrained-generic method receiver");
            }
            return false;
        }
        buf_append_fmt(
            cg->cur_body,
            "    const FengFunctionDescriptor *%s = %s;\n"
            "    const FengCallableValueDescriptor *%s = &%s->callable_value;\n"
            "    struct %s *%s = "
            "(struct %s *)feng_object_new(%s->closure_desc);\n"
            "    %s->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
            "    %s->_self = NULL;\n"
            "    %s->invoke = (",
            descriptor_name,
            callable_descriptor_expr,
            value_descriptor_name,
            descriptor_name,
            target_spec->c_closure_struct_name,
            closure_name,
            target_spec->c_closure_struct_name,
            value_descriptor_name,
            closure_name,
            closure_name,
            closure_name);
        cg_emit_callable_invoke_pointer_type(cg->cur_body, target_spec);
        buf_append_fmt(
            cg->cur_body,
            ")%s->invoke;\n"
            "    switch (%s->kind) {\n"
            "        case FENG_VALUE_TRIVIAL:\n"
            "            memcpy((char *)%s + "
            "%s->aggregate_capture_offset, %s, "
            "feng_generic_value_size(%s));\n"
            "            break;\n"
            "        case FENG_VALUE_MANAGED_POINTER:\n",
            value_descriptor_name,
            receiver_descriptor,
            closure_name,
            value_descriptor_name,
            receiver_address,
            receiver_descriptor);
        if (recv.owns_ref) {
            buf_append_fmt(
                cg->cur_body,
                "            %s->_self = *(void **)%s;\n"
                "            *(void **)%s = NULL;\n",
                closure_name,
                receiver_address,
                receiver_address);
        } else {
            buf_append_fmt(cg->cur_body,
                           "            feng_assign(&%s->_self, "
                           "*(void *const *)%s);\n",
                           closure_name,
                           receiver_address);
        }
        buf_append_cstr(
            cg->cur_body,
            "            break;\n"
            "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n");
        if (recv.owns_ref) {
            buf_append_fmt(
                cg->cur_body,
                "            feng_aggregate_take((char *)%s + "
                "%s->aggregate_capture_offset, %s, "
                "feng_generic_aggregate_descriptor(%s));\n",
                closure_name,
                value_descriptor_name,
                receiver_address,
                receiver_descriptor);
        } else {
            buf_append_fmt(
                cg->cur_body,
                "            feng_aggregate_assign((char *)%s + "
                "%s->aggregate_capture_offset, %s, "
                "feng_generic_aggregate_descriptor(%s));\n",
                closure_name,
                value_descriptor_name,
                receiver_address,
                receiver_descriptor);
        }
        buf_append_cstr(cg->cur_body,
                        "            break;\n"
                        "    }\n");
        {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(&expression,
                           "(struct %s *)%s",
                           target_spec->c_closure_struct_name,
                           closure_name);
            out->c_expr = expression.data;
        }
        out->type = cgtype_new(CG_TYPE_CALLABLE);
        if (out->c_expr == NULL || out->type == NULL) {
            er_free(out);
            free(receiver_address);
            free(descriptor_name);
            free(value_descriptor_name);
            free(closure_name);
            free(callable_descriptor_expr);
            er_free(&recv);
            return cg_fail(cg,
                           e->token,
                           "IE0001",
                           "codegen: out of memory");
        }
        out->type->user_spec = target_spec;
        out->owns_ref = true;
        free(receiver_address);
        free(descriptor_name);
        free(value_descriptor_name);
        free(closure_name);
        free(callable_descriptor_expr);
        er_free(&recv);
        return true;
    }
    if (recv.type != NULL && recv.type->kind == CG_TYPE_SPEC &&
        recv.type->user_spec != NULL) {
        const UserSpec *receiver_spec = recv.type->user_spec;
        const UserSpecMember *spec_method;

        if ((receiver_spec->form != FENG_SPEC_FORM_OBJECT &&
             receiver_spec->form != FENG_SPEC_FORM_INTERSECTION) ||
            !cg_ensure_user_spec_members_registered(
                cg, (UserSpec *)receiver_spec)) {
            er_free(&recv);
            return cg_fail(cg,
                           e->token,
                           "CE0112",
                           "codegen: callable method coercion source must be an object-form or intersection-form spec value");
        }
        spec_method = cg_user_spec_member_for_method_value(
            receiver_spec,
            cs->callable_member,
            target_spec,
            false);
        if (spec_method == NULL || spec_method->kind != USM_KIND_METHOD ||
            spec_method->is_static || cs->callable_type_arg_count != 0U) {
            er_free(&recv);
            return cg_fail(cg,
                           e->token,
                           "CE0114",
                           "codegen: resolved spec method-value requirement was not registered");
        }
        if (cg_materialize_to_local(cg,
                                    &recv,
                                    "_spec_method_receiver") == NULL) {
            er_free(&recv);
            return cg_fail(cg,
                           e->token,
                           "IE0001",
                           "codegen: failed to materialize object-spec method receiver");
        }
        receiver_argument = cg_aggregate_result_address_dup(&recv);
        if (receiver_argument == NULL ||
            !cg_ensure_callable_spec_method_value(cg,
                                                  target_spec,
                                                  receiver_spec,
                                                  spec_method,
                                                  e->token,
                                                  &bind_fn)) {
            free(receiver_argument);
            er_free(&recv);
            return false;
        }
        {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(&expression,
                           "%s(%s)",
                           bind_fn,
                           receiver_argument);
            out->c_expr = expression.data;
        }
        out->type = cgtype_new(CG_TYPE_CALLABLE);
        if (out->c_expr == NULL || out->type == NULL) {
            free(receiver_argument);
            er_free(&recv);
            er_free(out);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        out->type->user_spec = target_spec;
        out->owns_ref = true;
        free(receiver_argument);
        er_free(&recv);
        return true;
    }
    if (recv.type == NULL || recv.type->kind != CG_TYPE_OBJECT) {
        er_free(&recv);
        return cg_fail(cg, e->token,
            "CE0112", "codegen: callable method coercion source must be an object value");
    }
    if (recv.type->user == NULL ||
        recv.type->user->generic_context_type_param_count > 0U ||
        cs->callable_type_arg_count > 0U) {
        FengReifiableCallableDep dependency;
        char *descriptor_name;
        char *value_descriptor_name;
        char *closure_name;
        bool value_receiver =
            cg_type_decl_is_value_semantics(cs->callable_owner_type_decl);

        memset(&dependency, 0, sizeof(dependency));
        dependency.purpose = FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE;
        dependency.kind = cs->callable_fit_decl != NULL
                              ? FENG_RESOLVED_CALLABLE_FIT_METHOD
                              : FENG_RESOLVED_CALLABLE_TYPE_METHOD;
        dependency.owner_type_decl = cs->callable_owner_type_decl;
        dependency.member = cs->callable_member;
        dependency.fit_decl = cs->callable_fit_decl;
        dependency.owner_instance_type_ref =
            cs->callable_receiver_type_ref;
        dependency.callable_type_args = cs->callable_type_args;
        dependency.callable_type_arg_count = cs->callable_type_arg_count;
        dependency.target_callable_type_ref =
            cs->target_spec_type_ref;
        callable_descriptor_expr =
            cg_try_callable_descriptor_expr_for_dep(cg, &dependency);
        if (callable_descriptor_expr == NULL &&
            !cg_emit_closed_callable_dep_expr(cg,
                                              &dependency,
                                              NULL,
                                              0U,
                                              NULL,
                                              cg->cur_program,
                                              e->token,
                                              &callable_descriptor_expr)) {
            er_free(&recv);
            return false;
        }
        if (value_receiver) {
            receiver_argument =
                source_expr->as.member.object->kind == FENG_EXPR_SELF
                    ? strdup(recv.c_expr)
                    : cg_aggregate_result_address_dup(&recv);
        } else {
            if (cgtype_is_managed(recv.type) && recv.owns_ref) {
                (void)cg_materialize_to_local(cg, &recv, "_method_receiver");
            }
            receiver_argument = strdup(recv.c_expr);
        }
        descriptor_name = cg_fresh_temp(cg, "_method_value_desc");
        value_descriptor_name = cg_fresh_temp(cg, "_callable_value_desc");
        closure_name = cg_fresh_temp(cg, "_method_value_closure");
        if (callable_descriptor_expr == NULL ||
            receiver_argument == NULL || descriptor_name == NULL ||
            value_descriptor_name == NULL || closure_name == NULL) {
            free(descriptor_name);
            free(value_descriptor_name);
            free(closure_name);
            free(receiver_argument);
            free(callable_descriptor_expr);
            er_free(&recv);
            return cg_fail(cg,
                           e->token,
                           "IE0001",
                           "codegen: failed to lower a reified value method receiver");
        }
        buf_append_fmt(
            cg->cur_body,
            "    const FengFunctionDescriptor *%s = %s;\n"
            "    const FengCallableValueDescriptor *%s = &%s->callable_value;\n"
            "    struct %s *%s = "
            "(struct %s *)feng_object_new(%s->closure_desc);\n"
            "    %s->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
            "    %s->_self = NULL;\n"
            "    %s->invoke = (",
            descriptor_name,
            callable_descriptor_expr,
            value_descriptor_name,
            descriptor_name,
            target_spec->c_closure_struct_name,
            closure_name,
            target_spec->c_closure_struct_name,
            value_descriptor_name,
            closure_name,
            closure_name,
            closure_name);
        cg_emit_callable_invoke_pointer_type(cg->cur_body, target_spec);
        buf_append_fmt(cg->cur_body,
                       ")%s->invoke;\n",
                       value_descriptor_name);
        if (value_receiver) {
            buf_append_fmt(
                cg->cur_body,
                "    feng_aggregate_assign((char *)%s + "
                "%s->aggregate_capture_offset, %s, "
                "%s->aggregate_capture_desc);\n",
                closure_name,
                value_descriptor_name,
                receiver_argument,
                value_descriptor_name);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    feng_assign(&%s->_self, (void *)%s);\n",
                           closure_name,
                           receiver_argument);
        }
        {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(&expression,
                           "(struct %s *)%s",
                           target_spec->c_closure_struct_name,
                           closure_name);
            out->c_expr = expression.data;
        }
        out->type = cgtype_new(CG_TYPE_CALLABLE);
        if (out->c_expr == NULL || out->type == NULL) {
            er_free(out);
            free(descriptor_name);
            free(value_descriptor_name);
            free(closure_name);
            free(receiver_argument);
            free(callable_descriptor_expr);
            er_free(&recv);
            return cg_fail(cg,
                           e->token,
                           "IE0001",
                           "codegen: out of memory");
        }
        out->type->user_spec = target_spec;
        out->owns_ref = true;
        free(descriptor_name);
        free(value_descriptor_name);
        free(closure_name);
        free(receiver_argument);
        free(callable_descriptor_expr);
        er_free(&recv);
        return true;
    }
    receiver_owner_decl = recv.type->user->is_generic_instance
                              ? recv.type->user->generic_origin_decl
                              : recv.type->user->decl;
    if (receiver_owner_decl != cs->callable_owner_type_decl) {
        er_free(&recv);
        return cg_fail(cg, e->token,
            "CE0113", "codegen: callable method coercion receiver type does not match resolved owner type");
    }
    if (cs->callable_fit_decl != NULL) {
        selected_fit = cg_find_user_fit_by_decl_and_target(cg,
                                                           cs->callable_fit_decl,
                                                           recv.type->user);
        method = cg_user_fit_method_by_member(selected_fit,
                                              cs->callable_member);
    } else {
        method = cg_user_type_method_by_member(recv.type->user,
                                               cs->callable_member);
    }
    if (method == NULL) {
        er_free(&recv);
        return cg_fail(cg, e->token,
            "CE0114", "codegen: callable method coercion source method was not registered");
    }
    if (cg_type_is_value_semantics(recv.type)) {
        if ((!recv.is_addressable || recv.owns_ref) &&
            cg_materialize_to_local(cg, &recv, "_value_method_receiver") == NULL) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                           "IE0001", "codegen: failed to materialize value method receiver");
        }
        receiver_argument = cg_aggregate_result_address_dup(&recv);
        if (receiver_argument == NULL) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                           "IE0001", "codegen: value method receiver has no stable storage");
        }
    } else if (cgtype_is_managed(recv.type) && recv.owns_ref) {
        cg_materialize_to_local(cg, &recv, "_t");
    }
    if (!cg_ensure_callable_method_value(cg, target_spec, recv.type->user,
                                         method, e->token, method->c_name,
                                         NULL,
                                         &bind_fn)) {
        free(receiver_argument);
        free(callable_descriptor_expr);
        er_free(&recv);
        return false;
    }
    {
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "%s(%s)", bind_fn,
                       receiver_argument != NULL
                           ? receiver_argument
                           : recv.c_expr);
        out->c_expr = b.data;
    }
    out->type = cgtype_new(CG_TYPE_CALLABLE);
    if (!out->c_expr || !out->type) {
        er_free(&recv);
        er_free(out);
        free(receiver_argument);
        return false;
    }
    out->type->user_spec = target_spec;
    out->owns_ref = true;
    free(receiver_argument);
    free(callable_descriptor_expr);
    er_free(&recv);
    return true;
}

static bool cg_callable_specs_signature_compatible(const UserSpec *src,
                                                   const UserSpec *dst) {
    if (src == NULL || dst == NULL ||
        src->form != FENG_SPEC_FORM_CALLABLE ||
        dst->form != FENG_SPEC_FORM_CALLABLE) {
        return false;
    }
    if (src->callable_param_count != dst->callable_param_count) {
        return false;
    }
    if (src->callable_is_variadic != dst->callable_is_variadic) {
        return false;
    }
    for (size_t i = 0U; i < src->callable_param_count; ++i) {
        if (!cg_types_equal(src->callable_param_types[i],
                            dst->callable_param_types[i])) {
            return false;
        }
    }
    return cg_types_equal(src->callable_return_type, dst->callable_return_type);
}

/* Return true when two signature-compatible callable specs use exactly the
 * same generated C calling convention. Such values need only a static closure
 * view change; no runtime adapter object or invocation layer is required. */
static bool cg_callable_specs_abi_compatible(const UserSpec *src,
                                             const UserSpec *dst) {
    if (!cg_callable_specs_signature_compatible(src, dst) ||
        src->callable_return_abi_kind != dst->callable_return_abi_kind) {
        return false;
    }
    for (size_t i = 0U; i < src->callable_param_count; ++i) {
        if (src->callable_param_abi_kinds[i] !=
            dst->callable_param_abi_kinds[i]) {
            return false;
        }
    }
    return true;
}

static bool cg_emit_callable_other_rewrap(CG *cg,
                                          const FengExpr *e,
                                          ExprResult *source,
                                          const UserSpec *src_spec,
                                          const UserSpec *dst_spec,
                                          ExprResult *out) {
    FengToken blame = e ? e->token : (FengToken){0};
    char *adapter_name = NULL;
    char *closure_var = NULL;

    if (!cg_callable_specs_signature_compatible(src_spec, dst_spec)) {
        return cg_fail(cg, blame,
            "CE0115", "codegen: callable-form coercion requires source/target callable signatures to match");
    }
    if (cg_callable_specs_abi_compatible(src_spec, dst_spec)) {
        Buf cast;

        er_init(out);
        buf_init(&cast);
        buf_append_fmt(&cast,
                       "((struct %s *)%s)",
                       dst_spec->c_closure_struct_name,
                       source->c_expr);
        out->c_expr = cast.data;
        out->type = cgtype_new(CG_TYPE_CALLABLE);
        if (out->c_expr == NULL || out->type == NULL) {
            er_free(out);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        out->type->user_spec = dst_spec;
        out->owns_ref = source->owns_ref;
        out->is_addressable = source->is_addressable;
        return true;
    }
    if (cgtype_is_managed(source->type) && source->owns_ref) {
        cg_materialize_to_local(cg, source, "_t");
    }

    {
        size_t rewrap_id = cg->lambda_counter++;
        Buf ab;
        buf_init(&ab);
        buf_append_fmt(&ab, "FengCallableRewrap__%s__to__%s__%zu",
                       src_spec->c_closure_struct_name,
                       dst_spec->c_closure_struct_name,
                       rewrap_id);
        adapter_name = ab.data;
    }
    closure_var = cg_fresh_temp(cg, "_callable");
    if (adapter_name == NULL || closure_var == NULL) {
        free(adapter_name);
        free(closure_var);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    /* Prototype emitted early because fn_defs are emitted before witness_defs. */
    buf_append_cstr(&cg->headers, "static ");
    cg_emit_callable_abi_return_type(&cg->headers,
                                     dst_spec->callable_return_type,
                                     dst_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->headers, " %s(void *_closure", adapter_name);
    for (size_t i = 0U; i < dst_spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->headers, ", ");
        cg_emit_callable_abi_param_type(&cg->headers,
                                        dst_spec->callable_param_types[i],
                                        dst_spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->headers, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->headers,
                                         dst_spec->callable_return_abi_kind);
    buf_append_cstr(&cg->headers, ");\n");

    buf_append_cstr(&cg->witness_defs, "static ");
    cg_emit_callable_abi_return_type(&cg->witness_defs,
                                     dst_spec->callable_return_type,
                                     dst_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs, " %s(void *_closure", adapter_name);
    for (size_t i = 0U; i < dst_spec->callable_param_count; ++i) {
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_emit_callable_abi_param_type(&cg->witness_defs,
                                        dst_spec->callable_param_types[i],
                                        dst_spec->callable_param_abi_kinds[i]);
        buf_append_fmt(&cg->witness_defs, " _arg%zu", i);
    }
    cg_append_callable_abi_out_parameter(&cg->witness_defs,
                                         dst_spec->callable_return_abi_kind);
    buf_append_fmt(&cg->witness_defs,
        ") {\n"
        "    struct %s *_dst = (struct %s *)_closure;\n"
        "    struct %s *_src = (struct %s *)_dst->_self;\n"
        "    ",
        dst_spec->c_closure_struct_name,
        dst_spec->c_closure_struct_name,
        src_spec->c_closure_struct_name,
        src_spec->c_closure_struct_name);

    if (dst_spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS &&
        src_spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "*(");
        cg_emit_c_type(&cg->witness_defs, dst_spec->callable_return_type);
        buf_append_cstr(&cg->witness_defs, " *)_out = ");
    } else if (dst_spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS &&
               src_spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "");
        cg_emit_c_type(&cg->witness_defs, dst_spec->callable_return_type);
        buf_append_cstr(&cg->witness_defs, " _result;\n    ");
    } else if (dst_spec->callable_return_type != NULL &&
               dst_spec->callable_return_type->kind != CG_TYPE_VOID &&
               dst_spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "return ");
    }
    buf_append_cstr(&cg->witness_defs, "_src->invoke((void *)_src");
    for (size_t i = 0U; i < dst_spec->callable_param_count; ++i) {
        char argument_name[32];

        (void)snprintf(argument_name, sizeof argument_name, "_arg%zu", i);
        buf_append_cstr(&cg->witness_defs, ", ");
        cg_append_callable_abi_bridge_argument(
            &cg->witness_defs,
            src_spec->callable_param_types[i],
            dst_spec->callable_param_abi_kinds[i],
            src_spec->callable_param_abi_kinds[i],
            argument_name);
    }
    if (src_spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs,
                        dst_spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS
                            ? ", _out"
                            : ", &_result");
    }
    buf_append_cstr(&cg->witness_defs, ");\n");
    if (dst_spec->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS &&
        src_spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        buf_append_cstr(&cg->witness_defs, "    return _result;\n");
    }
    buf_append_cstr(&cg->witness_defs, "}\n\n");

    buf_append_fmt(cg->cur_body,
        "    struct %s *%s = (struct %s *)feng_object_new(&%s);\n"
        "    %s->_hdr.tag = FENG_TYPE_TAG_CLOSURE;\n"
        "    %s->_self = NULL;\n"
        "    feng_assign((void **)&%s->_self, (void *)%s);\n"
        "    %s->invoke = %s;\n",
        dst_spec->c_closure_struct_name,
        closure_var,
        dst_spec->c_closure_struct_name,
        dst_spec->c_closure_desc_name,
        closure_var,
        closure_var,
        closure_var,
        source->c_expr,
        closure_var,
        adapter_name);

    er_init(out);
    {
        Buf b;
        buf_init(&b);
        buf_append_fmt(&b, "(struct %s *)%s",
                       dst_spec->c_closure_struct_name,
                       closure_var);
        out->c_expr = b.data;
    }
    out->type = cgtype_new(CG_TYPE_CALLABLE);
    if (out->c_expr == NULL || out->type == NULL) {
        free(adapter_name);
        free(closure_var);
        er_free(out);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    out->type->user_spec = dst_spec;
    out->owns_ref = true;

    free(adapter_name);
    free(closure_var);
    return true;
}

static bool cg_emit_callable_spec_coercion(CG *cg,
                                           const FengExpr *e,
                                           const FengSpecCoercionSite *cs,
                                           ExprResult *out) {
    if (cs->callable_source == FENG_SPEC_COERCION_CALLABLE_SOURCE_TOP_LEVEL_FN) {
        return cg_emit_callable_function_coercion(cg, e, cs, out);
    }
    if (cs->callable_source == FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE) {
        return cg_emit_callable_method_coercion(cg, e, cs, out);
    }
    if (cs->callable_source == FENG_SPEC_COERCION_CALLABLE_SOURCE_LAMBDA) {
        return cg_emit_callable_lambda_coercion(cg, e, cs->callable_lambda_expr, cs, out);
    }
    if (cs->callable_source == FENG_SPEC_COERCION_CALLABLE_SOURCE_OTHER) {
        const UserSpec *target_spec = NULL;
        ExprResult src;
        if (cs->callable_lambda_expr != NULL) {
            return cg_emit_callable_lambda_coercion(cg, e, cs->callable_lambda_expr, cs, out);
        }
        if (!cg_resolve_coercion_target_user_spec(cg, cs, e->token, &target_spec)) {
            return false;
        }
        if (!cg_emit_expr_raw(cg, e, &src)) {
            return false;
        }
        if (target_spec != NULL && src.type != NULL && src.type->kind == CG_TYPE_CALLABLE &&
            src.type->user_spec == target_spec) {
            *out = src;
            return true;
        }
        if (target_spec != NULL && src.type != NULL && src.type->kind == CG_TYPE_CALLABLE &&
            src.type->user_spec != NULL) {
            bool ok = cg_emit_callable_other_rewrap(cg, e, &src,
                                                    src.type->user_spec,
                                                    target_spec,
                                                    out);
            er_free(&src);
            return ok;
        }
        er_free(&src);
        return cg_fail(cg, e->token,
            "CE0116", "codegen: callable-form coercion source must be a callable value");
    }
    return cg_fail(cg, e->token,
        "CE0117", "codegen: callable-form lambda/method coercion not yet supported in this step");
}

/* Emit the active tag and forwarding slot for one union value held in
 * address-form storage. The payload offset is part of the generated union
 * carrier ABI and remains fixed even when the payload's concrete size is
 * supplied by a descriptor. */
static bool cg_emit_reified_union_header(CG *cg,
                                         const UserSpec *spec,
                                         size_t member_index,
                                         const char *storage_expr,
                                         FengToken blame) {
    const CGType *member_type;
    Buf slot_descriptor;

    if (cg == NULL || spec == NULL ||
        spec->form != FENG_SPEC_FORM_UNION ||
        member_index >= spec->union_member_count || storage_expr == NULL) {
        return false;
    }
    member_type = spec->union_member_types[member_index];
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    ((struct %s *)(void *)%s)->tag = %zuU;\n",
                   spec->c_value_struct_name,
                   storage_expr,
                   member_index);

    if (member_type != NULL &&
        member_type->kind == CG_TYPE_GENERIC_PARAM) {
        const char *descriptor = cg_generic_param_desc_name(
            cg, member_type->generic_param_index);

        if (descriptor == NULL) {
            return cg_fail(cg,
                           blame,
                           "CE0237", "codegen: union member is missing its generic descriptor");
        }
        buf_append_fmt(cg->cur_body,
            "    switch (%s->kind) {\n"
            "        case FENG_VALUE_TRIVIAL:\n"
            "            ((struct %s *)(void *)%s)->_fwd = "
            "(FengManagedSlotDescriptor){ .offset = 0, .kind = FENG_SLOT_NONE, .nested = NULL };\n"
            "            break;\n"
            "        case FENG_VALUE_MANAGED_POINTER:\n"
            "            ((struct %s *)(void *)%s)->_fwd = "
            "(FengManagedSlotDescriptor){ .offset = offsetof(struct %s, payload.m%zu), "
            ".kind = FENG_SLOT_POINTER, .nested = NULL };\n"
            "            break;\n"
            "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
            "            ((struct %s *)(void *)%s)->_fwd = "
            "(FengManagedSlotDescriptor){ .offset = offsetof(struct %s, payload.m%zu), "
            ".kind = FENG_SLOT_NESTED_AGGREGATE, "
            ".nested = feng_generic_aggregate_descriptor(%s) };\n"
            "            break;\n"
            "    }\n",
            descriptor,
            spec->c_value_struct_name,
            storage_expr,
            spec->c_value_struct_name,
            storage_expr,
            spec->c_value_struct_name,
            member_index,
            spec->c_value_struct_name,
            storage_expr,
            spec->c_value_struct_name,
            member_index,
            descriptor);
        return true;
    }

    buf_init(&slot_descriptor);
    if (!cg_append_union_member_slot_descriptor(cg,
                                                &slot_descriptor,
                                                spec,
                                                member_index,
                                                blame)) {
        buf_free(&slot_descriptor);
        return false;
    }
    buf_append_fmt(cg->cur_body,
                   "    ((struct %s *)(void *)%s)->_fwd = %s;\n",
                   spec->c_value_struct_name,
                   storage_expr,
                   slot_descriptor.data);
    buf_free(&slot_descriptor);
    return true;
}

/* Construct one selected union path directly in descriptor-sized storage.
 * Each nesting level owns only its own tag/forward metadata; the selected
 * leaf is copied or moved according to its own value representation. */
static bool cg_emit_reified_union_path_store(CG *cg,
                                             const UserSpec *spec,
                                             const FengUnionCoercionSite *site,
                                             size_t path_level,
                                             const char *storage_expr,
                                             ExprResult *source,
                                             FengToken blame) {
    const CGType *member_type;
    size_t member_index;
    Buf payload_address;

    if (cg == NULL || spec == NULL || site == NULL || source == NULL ||
        path_level >= site->path_length ||
        site->path_indices[path_level] >= spec->union_member_count) {
        return cg_fail(cg,
                       blame,
                       "CE0118", "codegen: union coercion path is invalid");
    }
    member_index = site->path_indices[path_level];
    member_type = spec->union_member_types[member_index];
    if (!cg_emit_reified_union_header(cg,
                                      spec,
                                      member_index,
                                      storage_expr,
                                      blame)) {
        return false;
    }

    buf_init(&payload_address);
    buf_append_fmt(&payload_address,
                   "((void *)((char *)%s + offsetof(struct %s, payload.m%zu)))",
                   storage_expr,
                   spec->c_value_struct_name,
                   member_index);
    if (payload_address.data == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    if (path_level + 1U < site->path_length) {
        const UserSpec *nested_spec =
            member_type != NULL && member_type->kind == CG_TYPE_SPEC
                ? member_type->user_spec
                : NULL;
        bool ok;

        if (nested_spec == NULL ||
            nested_spec->form != FENG_SPEC_FORM_UNION) {
            buf_free(&payload_address);
            return cg_fail(cg,
                           blame,
                           "CE0119", "codegen: nested union path traverses non-union member");
        }
        ok = cg_emit_reified_union_path_store(cg,
                                              nested_spec,
                                              site,
                                              path_level + 1U,
                                              payload_address.data,
                                              source,
                                              blame);
        buf_free(&payload_address);
        return ok;
    }

    if (member_type == NULL || member_type->kind == CG_TYPE_VOID) {
        buf_free(&payload_address);
        return true;
    }
    if (member_type->kind == CG_TYPE_GENERIC_PARAM) {
        bool ok = cg_emit_generic_value_store(cg,
                                              payload_address.data,
                                              member_type,
                                              source,
                                              blame,
                                              false);
        buf_free(&payload_address);
        return ok;
    }
    if (cgtype_is_managed(member_type)) {
        char *ctype = cg_ctype_dup(member_type);

        if (ctype == NULL) {
            buf_free(&payload_address);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "    *(%s *)%s = (%s)(%s);\n",
                       ctype,
                       payload_address.data,
                       ctype,
                       source->c_expr);
        if (!source->owns_ref) {
            buf_append_fmt(cg->cur_body,
                           "    feng_retain(*(void **)%s);\n",
                           payload_address.data);
        }
        free(ctype);
        buf_free(&payload_address);
        return true;
    }
    if (cgtype_is_aggregate(member_type)) {
        bool take_source = source->owns_ref;
        char *descriptor;
        char *source_address;

        if (!cg_prepare_aggregate_assign_source(cg, source, "_union_source")) {
            buf_free(&payload_address);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        descriptor = cg_aggregate_descriptor_expr_dup(cg,
                                                      member_type,
                                                      blame);
        source_address = cg_aggregate_result_address_dup(source);
        if (descriptor == NULL || source_address == NULL) {
            free(descriptor);
            free(source_address);
            buf_free(&payload_address);
            return cg_fail(cg,
                           blame,
                           "CE0055", "codegen: union-form aggregate member is missing storage authority");
        }
        buf_append_fmt(cg->cur_body,
                       "    %s(%s, %s, %s);\n",
                       take_source ? "feng_aggregate_take"
                                   : "feng_aggregate_assign",
                       payload_address.data,
                       source_address,
                       descriptor);
        free(descriptor);
        free(source_address);
        buf_free(&payload_address);
        return true;
    }

    {
        char *ctype = cg_ctype_dup(member_type);

        if (ctype == NULL) {
            buf_free(&payload_address);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (cgtype_is_by_value_struct(member_type)) {
            buf_append_fmt(cg->cur_body,
                           "    *(%s *)%s = %s;\n",
                           ctype,
                           payload_address.data,
                           source->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    *(%s *)%s = (%s)(%s);\n",
                           ctype,
                           payload_address.data,
                           ctype,
                           source->c_expr);
        }
        free(ctype);
    }
    buf_free(&payload_address);
    return true;
}

static bool cg_append_nested_union_coercion(CG *cg,
                                             Buf *expr,
                                             const UserSpec *spec,
                                             const FengUnionCoercionSite *site,
                                             size_t path_level,
                                             const char *source_c_expr,
                                             bool *out_payload_owns_ref,
                                             FengToken blame) {
    Buf slot_descriptor;
    size_t member_index;
    const CGType *member_type;

    if (spec == NULL || spec->form != FENG_SPEC_FORM_UNION ||
        path_level >= site->path_length ||
        site->path_indices[path_level] >= spec->union_member_count) {
        return cg_fail(cg, blame,
                       "CE0118", "codegen: union coercion path is invalid");
    }
    member_index = site->path_indices[path_level];
    buf_init(&slot_descriptor);
    if (!cg_append_union_member_slot_descriptor(cg, &slot_descriptor, spec, member_index, blame)) {
        buf_free(&slot_descriptor);
        return false;
    }

    buf_append_fmt(expr,
                   "((struct %s){ .tag = %zuU, ._fwd = %s",
                   spec->c_value_struct_name,
                   member_index,
                   slot_descriptor.data);
    buf_free(&slot_descriptor);

    member_type = spec->union_member_types[member_index];
    if (member_type != NULL && member_type->kind != CG_TYPE_VOID) {
        buf_append_cstr(expr, ", .payload.");
        cg_append_union_payload_field_name(expr, member_index);
        buf_append_cstr(expr, " = ");

        if (path_level + 1U < site->path_length) {
            /* Intermediate level: recurse into nested union. */
            const UserSpec *nested_spec = (member_type->kind == CG_TYPE_SPEC)
                                              ? member_type->user_spec
                                              : NULL;
            if (nested_spec == NULL || nested_spec->form != FENG_SPEC_FORM_UNION) {
                buf_free(expr);
                return cg_fail(cg, blame,
                               "CE0119", "codegen: nested union path traverses non-union member");
            }
            if (!cg_append_nested_union_coercion(cg, expr, nested_spec, site,
                                                  path_level + 1U, source_c_expr,
                                                  out_payload_owns_ref, blame)) {
                buf_free(expr);
                return false;
            }
        } else {
            /* Leaf level: assign source expression. */
            if (cgtype_is_by_value_struct(member_type) || cgtype_is_aggregate(member_type)) {
                buf_append_cstr(expr, source_c_expr);
            } else {
                char *member_ctype = cg_ctype_dup(member_type);
                if (member_ctype == NULL) {
                    buf_free(expr);
                    return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(expr, "(%s)(%s)", member_ctype, source_c_expr);
                free(member_ctype);
            }
        }
    }
    buf_append_cstr(expr, " })");
    return true;
}

static bool cg_emit_union_spec_coercion(CG *cg,
                                        const FengExpr *e,
                                        const FengUnionCoercionSite *site,
                                        ExprResult *out) {
    const UserSpec *target_spec = NULL;
    const FengSpecCoercionSite *leaf_spec_site =
        feng_semantic_lookup_spec_coercion_site(cg->analysis, e);
    ExprResult source;
    Buf expr;
    bool payload_owns_ref = false;
    FengUnionCoercionSite patched_site;

    er_init(out);
    er_init(&source);
    buf_init(&expr);

    if (!cg_resolve_union_target_user_spec(cg, site, e->token, &target_spec)) {
        return false;
    }
    if (target_spec == NULL || target_spec->form != FENG_SPEC_FORM_UNION) {
        return cg_fail(cg, e->token,
                       "CE0118", "codegen: union coercion target member is invalid");
    }

    /* Backward compatibility: if path was not set, synthesize single-level path. */
    if (site->path_length == 0U) {
        patched_site = *site;
        patched_site.path_indices[0] = site->member_index;
        patched_site.path_length = 1U;
        site = &patched_site;
    }

    /* Member selection and member conversion are separate semantic steps.
     * Emit any conversion required by the selected leaf before wrapping the
     * resulting value in the union path. */
    if (!cg_emit_expr_with_spec_coercion(cg, e, leaf_spec_site, &source)) {
        return false;
    }

    out->type = cgtype_new(CG_TYPE_SPEC);
    if (out->type == NULL) {
        er_free(&source);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    out->type->user_spec = target_spec;

    if (cg_type_uses_reified_storage(cg, out->type)) {
        char *storage_name = cg_fresh_temp(cg, "_union");

        if (storage_name == NULL ||
            !cg_emit_reified_storage_declaration(
                cg,
                out->type,
                storage_name,
                e->token,
                &out->reified_descriptor_c_name,
                &out->reified_size_c_name) ||
            !cg_emit_reified_union_path_store(cg,
                                              target_spec,
                                              site,
                                              0U,
                                              storage_name,
                                              &source,
                                              e->token)) {
            free(storage_name);
            er_free(&source);
            er_free(out);
            return false;
        }
        out->c_expr = strdup(storage_name);
        out->owns_ref = true;
        out->is_addressable = true;
        out->is_storage_address = true;
        out->uses_reified_storage = true;
        free(storage_name);
        er_free(&source);
        if (out->c_expr == NULL) {
            er_free(out);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        return true;
    }

    if (!cg_append_nested_union_coercion(cg, &expr, target_spec, site,
                                          0U, source.c_expr,
                                          &payload_owns_ref, e->token)) {
        er_free(&source);
        buf_free(&expr);
        return false;
    }

    payload_owns_ref = (cgtype_is_managed(source.type) || cgtype_is_aggregate(source.type)) &&
                       source.owns_ref;

    out->c_expr = expr.data;
    if (out->c_expr == NULL) {
        er_free(&source);
        er_free(out);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    out->owns_ref = payload_owns_ref;
    er_free(&source);
    return true;
}

static bool cg_exprs_structurally_equal(const FengExpr *a, const FengExpr *b) {
    if (a == b) return true;
    if (a == NULL || b == NULL || a->kind != b->kind) return false;
    switch (a->kind) {
        case FENG_EXPR_SELF:
            return true;
        case FENG_EXPR_IDENTIFIER:
            return cg_slice_equals(a->as.identifier, b->as.identifier);
        case FENG_EXPR_MEMBER:
            return cg_slice_equals(a->as.member.member, b->as.member.member) &&
                   cg_exprs_structurally_equal(a->as.member.object, b->as.member.object);
        default:
            return false;
    }
}

static bool cg_emit_expr_raw(CG *cg, const FengExpr *e, ExprResult *out) {
    bool ok;

    if (cg->failed) return false;

    if (cg->expr_narrowing_count > 0U) {
        size_t i;

        for (i = cg->expr_narrowing_count; i > 0U; --i) {
            struct CGExprNarrowing *n = &cg->expr_narrowings[i - 1U];

            if (cg_exprs_structurally_equal(e, n->target_expr)) {
                er_init(out);
                out->c_expr = strdup(n->c_expr);
                out->type = cgtype_clone(n->type);
                out->owns_ref = false;
                out->is_addressable = true;
                return out->c_expr != NULL && out->type != NULL;
            }
        }
    }

    switch (e->kind) {
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
            ok = cg_emit_literal(cg, e, out); break;
        case FENG_EXPR_IDENTIFIER:
            ok = cg_emit_identifier(cg, e, out); break;
        case FENG_EXPR_SELF: {
            const Local *l = scope_lookup(cg->cur_scope, "self", 4);
            if (!l) {
                return cg_fail(cg, e->token,
                    "CE0119", "codegen: 'self' used outside of method body");
            }
            er_init(out);
            out->c_expr = strdup(l->c_name);
            out->type = cgtype_clone(l->type);
            out->owns_ref = false;
            out->managed_identity_is_stable = true;
            out->is_addressable = true;
            /* `self` is a dedicated AST node, but its lowered storage form is
             * still owned by the scope binding. In particular, a shared
             * generic @value method receives `_self` as an address already;
             * preserving this bit prevents nested self calls from taking the
             * address of that pointer a second time. */
            out->is_storage_address = l->is_storage_address;
            out->uses_erased_generic_storage =
                l->uses_erased_generic_storage;
            if (l->uses_erased_generic_storage) {
                out->erased_generic_descriptor_c_name =
                    strdup(l->erased_generic_descriptor_c_name);
                out->erased_generic_size_c_name =
                    strdup(l->erased_generic_size_c_name);
            }
            out->uses_reified_storage = l->uses_reified_storage;
            if (l->uses_reified_storage) {
                out->reified_descriptor_c_name =
                    strdup(l->reified_descriptor_c_name);
                out->reified_size_c_name =
                    l->reified_size_c_name != NULL
                        ? strdup(l->reified_size_c_name)
                        : NULL;
            }
            ok = out->c_expr && out->type;
            break;
        }
        case FENG_EXPR_BINARY:        ok = cg_emit_binary(cg, e, out); break;
        case FENG_EXPR_UNARY:         ok = cg_emit_unary(cg, e, out); break;
        case FENG_EXPR_CALL:          ok = cg_emit_call(cg, e, out); break;
        case FENG_EXPR_MEMBER:        ok = cg_emit_member(cg, e, out); break;
        case FENG_EXPR_OBJECT_LITERAL:ok = cg_emit_object_literal(cg, e, out); break;
        case FENG_EXPR_GENERIC_TARGET:
            return cg_fail(cg,
                           e->token,
                           "CE0120", "codegen: explicit generic target must be consumed before emission");
        case FENG_EXPR_ARRAY_LITERAL: ok = cg_emit_array_literal(cg, e, out); break;
        case FENG_EXPR_TUPLE_LITERAL:
            return cg_fail(cg, e->token,
                "CE0121", "codegen: tuple literal requires an explicit named tuple target type");
        case FENG_EXPR_ARRAY_NEW:     ok = cg_emit_array_new(cg, e, out); break;
        case FENG_EXPR_INDEX:         ok = cg_emit_index(cg, e, out); break;
        case FENG_EXPR_CAST:          ok = cg_emit_cast(cg, e, out); break;
        case FENG_EXPR_IF:            ok = cg_emit_if_expr(cg, e, out); break;
        case FENG_EXPR_MATCH:         ok = cg_emit_match_expr(cg, e, out); break;
        case FENG_EXPR_MATCH_OP:      ok = cg_emit_match_op(cg, e, out); break;
        case FENG_EXPR_TRY:           ok = cg_emit_try_expr(cg, e, out, true); break;
        default:
            return cg_fail(cg, e->token,
                "CE0122", "codegen: expression kind not yet supported in this iteration");
    }
    return ok;
}

static bool cg_emit_registered_call(CG *cg,
                                    const FengExpr *e,
                                    const FreeFn *fn,
                                    const ExternFn *ext,
                                    ExprResult *out);
static char *cg_array_element_descriptor(const CGType *elem);

/* Pack already evaluated variadic values into one newly allocated FengArray.
 * Values are prepared in place so callers can release their ExprResult
 * metadata normally after this helper has retained/copied every array slot. */
static bool cg_pack_variadic_expr_results(CG *cg,
                                          const FengToken *tok,
                                          ExprResult *items,
                                          size_t n,
                                          const CGType *elem_type,
                                          ExprResult *out) {
    CGType *elem = cgtype_clone(elem_type);
    char *arr_tmp = cg_fresh_temp(cg, "_varr");
    char *elem_cty = cg_ctype_dup(elem);
    char *desc_expr = cg_array_element_descriptor(elem);

    er_init(out);

    if (!elem || !arr_tmp || !elem_cty || !desc_expr) {
        cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
        return cg_fail(cg, *tok, "IE0001", "codegen: out of memory packing variadic arguments");
    }

    bool elem_managed = cgtype_is_managed(elem);
    bool elem_aggregate = cgtype_is_aggregate(elem);
    bool elem_is_generic_param = elem->kind == CG_TYPE_GENERIC_PARAM;
    const char *generic_elem_desc = elem_is_generic_param
                                        ? cg_generic_param_desc_name(
                                              cg, elem->generic_param_index)
                                        : NULL;
    const char *agg_desc = elem_aggregate ? cg_aggregate_desc_name(elem) : NULL;
    char *generic_elem_meta = NULL;

    if (elem_is_generic_param && generic_elem_desc == NULL) {
        cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
        return cg_fail(cg, *tok,
                       "CE0184", "codegen: generic variadic packing requires an active generic descriptor");
    }
    if (elem_aggregate && agg_desc == NULL) {
        cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
        return cg_fail(cg, *tok,
            "CE0123", "codegen: missing aggregate descriptor for variadic element type");
    }
    if (elem_is_generic_param) {
        generic_elem_meta = cg_fresh_temp(cg, "_vmeta");
        if (generic_elem_meta == NULL) {
            cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
            return cg_fail(cg, *tok,
                           "IE0001", "codegen: out of memory packing variadic arguments");
        }
        buf_append_fmt(cg->cur_body,
            "    const FengValueKind %s_kind = %s->kind;\n"
            "    const size_t %s_size = feng_generic_value_size(%s);\n"
            "    const FengAggregateDescriptor *%s_agg = "
            "%s_kind == FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS ? feng_generic_aggregate_descriptor(%s) : NULL;\n",
            generic_elem_meta, generic_elem_desc,
            generic_elem_meta, generic_elem_desc,
            generic_elem_meta,
            generic_elem_meta, generic_elem_desc);
    }

    if (n == 0) {
        /* Empty variadic: produce a zero-length array. */
        cg_emit_current_stmt_line_directive_force(cg);
        if (elem_aggregate) {
            size_t rad_idx;
            if (cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
                buf_append_fmt(cg->cur_body,
                    "    FengArray *%s = feng_array_new_kinded("
                    "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, %s->reified_agg_deps[%zu], "
                    "NULL, %s->reified_agg_deps[%zu]->size, (size_t)0);\n",
                    arr_tmp, rad_src, rad_idx, rad_src, rad_idx);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    FengArray *%s = feng_array_new_kinded("
                    "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, &%s, NULL, sizeof(%s), (size_t)0);\n",
                    arr_tmp, agg_desc, elem_cty);
            }
        } else if (elem_is_generic_param) {
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "%s_kind, %s_agg, NULL, %s_size, (size_t)0);\n",
                arr_tmp,
                generic_elem_meta,
                generic_elem_meta,
                generic_elem_meta);
        } else {
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new(%s, sizeof(%s), %s, (size_t)0);\n",
                arr_tmp, desc_expr, elem_cty, elem_managed ? "true" : "false");
        }
        free(elem_cty); free(desc_expr); free(generic_elem_meta);
        out->c_expr = strdup(arr_tmp);
        free(arr_tmp);
        out->type = cgtype_new(CG_TYPE_ARRAY);
        if (!out->c_expr || !out->type) { cgtype_free(elem); return false; }
        out->type->element = elem;
        out->owns_ref = true;
        return true;
    }

    /* Stabilize each already evaluated value before filling array storage. */
    for (size_t i = 0; i < n; i++) {
        if (elem_is_generic_param && !items[i].is_storage_address) {
            if (cg_materialize_to_local(cg, &items[i], "_t") == NULL) {
                cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
                free(generic_elem_meta);
                return false;
            }
        } else if (cgtype_is_managed(items[i].type) && items[i].owns_ref) {
            if (cg_materialize_to_local(cg, &items[i], "_t") == NULL) {
                cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
                free(generic_elem_meta);
                return false;
            }
        } else if (cgtype_is_aggregate(items[i].type) &&
                   !cg_prepare_aggregate_assign_source(cg, &items[i], "_t")) {
            cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
            free(generic_elem_meta);
            return cg_fail(cg, *tok, "IE0001", "codegen: out of memory packing variadic arguments");
        }
    }

    /* Allocate the array and fill slots. */
    cg_emit_current_stmt_line_directive_force(cg);
    if (elem_aggregate) {
        size_t rad_idx;
        if (cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
            const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, %s->reified_agg_deps[%zu], "
                "NULL, %s->reified_agg_deps[%zu]->size, (size_t)%zu);\n",
                arr_tmp, rad_src, rad_idx, rad_src, rad_idx, n);
        } else {
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, &%s, NULL, sizeof(%s), (size_t)%zu);\n",
                arr_tmp, agg_desc, elem_cty, n);
        }
    } else if (elem_is_generic_param) {
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new_kinded("
            "%s_kind, %s_agg, NULL, %s_size, (size_t)%zu);\n",
            arr_tmp,
            generic_elem_meta,
            generic_elem_meta,
            generic_elem_meta,
            n);
    } else {
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new(%s, sizeof(%s), %s, (size_t)%zu);\n",
            arr_tmp, desc_expr, elem_cty, elem_managed ? "true" : "false", n);
    }

    char *slots_tmp = cg_fresh_temp(cg, "_vslots");
    if (!slots_tmp) {
        cgtype_free(elem); free(arr_tmp); free(elem_cty); free(desc_expr);
        free(generic_elem_meta);
        return cg_fail(cg, *tok, "IE0001", "codegen: out of memory");
    }
    cg_emit_current_stmt_line_directive_force(cg);
    size_t variadic_rad_idx;
    bool variadic_has_rad = elem_aggregate &&
        cg_lookup_reified_agg_dep_index(cg, agg_desc, &variadic_rad_idx);
    if (variadic_has_rad || elem_is_generic_param) {
        buf_append_fmt(cg->cur_body,
            "    char *%s = (char *)feng_array_data(%s);\n",
            slots_tmp, arr_tmp);
    } else {
        buf_append_fmt(cg->cur_body,
            "    %s *%s = (%s *)feng_array_data(%s);\n",
            elem_cty, slots_tmp, elem_cty, arr_tmp);
    }

    for (size_t i = 0; i < n; i++) {
        cg_emit_current_stmt_line_directive_force(cg);
        if (elem_is_generic_param) {
            buf_append_fmt(cg->cur_body,
                "    switch (%s_kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(%s + %zu * %s_size, %s, %s_size);\n"
                "            break;\n"
                "        case FENG_VALUE_MANAGED_POINTER: {\n"
                "            void *_value = *(void *const *)%s;\n"
                "            *(void **)(%s + %zu * %s_size) = _value;\n"
                "            feng_retain(_value);\n"
                "            break;\n"
                "        }\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            feng_aggregate_assign(%s + %zu * %s_size, %s, %s_agg);\n"
                "            break;\n"
                "    }\n",
                generic_elem_meta,
                slots_tmp, i, generic_elem_meta,
                items[i].c_expr, generic_elem_meta,
                items[i].c_expr,
                slots_tmp, i, generic_elem_meta,
                slots_tmp, i, generic_elem_meta,
                items[i].c_expr, generic_elem_meta);
        } else if (elem_aggregate) {
            const char *source_address_prefix =
                items[i].is_storage_address ? "" : "&";
            if (variadic_has_rad) {
                const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
                buf_append_fmt(cg->cur_body,
                    "    feng_aggregate_assign("
                    "(void *)(%s + %zu * %s->reified_agg_deps[%zu]->size), "
                    "%s%s, %s->reified_agg_deps[%zu]);\n",
                    slots_tmp, i, rad_src, variadic_rad_idx,
                    source_address_prefix, items[i].c_expr,
                    rad_src, variadic_rad_idx);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_aggregate_assign(&%s[%zu], %s%s, &%s);\n",
                    slots_tmp, i,
                    source_address_prefix, items[i].c_expr, agg_desc);
            }
        } else if (elem_managed) {
            buf_append_fmt(cg->cur_body,
                "    %s[%zu] = %s; feng_retain(%s[%zu]);\n",
                slots_tmp, i, items[i].c_expr, slots_tmp, i);
        } else {
            if (cgtype_is_by_value_struct(elem)) {
                buf_append_fmt(cg->cur_body,
                    "    %s[%zu] = %s;\n",
                    slots_tmp, i, items[i].c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    %s[%zu] = (%s)(%s);\n",
                    slots_tmp, i, elem_cty, items[i].c_expr);
            }
        }
    }

    free(slots_tmp); free(elem_cty); free(desc_expr); free(generic_elem_meta);

    out->c_expr = strdup(arr_tmp);
    free(arr_tmp);
    out->type = cgtype_new(CG_TYPE_ARRAY);
    if (!out->c_expr || !out->type) { cgtype_free(elem); return false; }
    out->type->element = elem;
    out->owns_ref = true;
    return true;
}

/* Evaluate ordinary variadic suffix expressions exactly once, then normalize
 * the resulting values through the shared array-packing implementation. */
static bool cg_pack_variadic_args(CG *cg,
                                  const FengToken *tok,
                                  FengExpr *const *args,
                                  size_t n,
                                  const CGType *elem_type,
                                  ExprResult *out) {
    ExprResult *items = n > 0U ? calloc(n, sizeof *items) : NULL;
    bool ok = n == 0U || items != NULL;

    if (!ok) {
        return cg_fail(cg, *tok,
                       "IE0001", "codegen: out of memory packing variadic arguments");
    }
    for (size_t index = 0U; index < n && ok; ++index) {
        ok = cg_emit_expr_for_expected_type(
            cg, args[index], elem_type, &items[index]);
    }
    if (ok) {
        ok = cg_pack_variadic_expr_results(
            cg, tok, items, n, elem_type, out);
    }
    for (size_t index = 0U; index < n; ++index) {
        er_free(&items[index]);
    }
    free(items);
    return ok;
}

/* Produce the normalized array argument for a variadic call.  Ordinary calls
 * allocate and pack their variadic suffix; an explicit final `...expr` is
 * evaluated once as the already packed array and passed through unchanged. */
static bool cg_emit_variadic_array_arg(CG *cg,
                                       const FengExpr *call,
                                       size_t fixed_count,
                                       const CGType *array_type,
                                       ExprResult *out) {
    if (call == NULL || call->kind != FENG_EXPR_CALL) {
        return false;
    }
    return cg_emit_variadic_array_arg_from_args(
        cg,
        &call->token,
        call->as.call.args,
        call->as.call.arg_count,
        fixed_count,
        array_type,
        out);
}

/* Produce the normalized array argument from any resolved variadic call
 * shape, including ordinary functions, methods, callable values and
 * constructors. */
static bool cg_emit_variadic_array_arg_from_args(
    CG *cg,
    const FengToken *token,
    FengExpr *const *args,
    size_t arg_count,
    size_t fixed_count,
    const CGType *array_type,
    ExprResult *out) {
    const FengExpr *last_arg;

    if (token == NULL || array_type == NULL ||
        array_type->kind != CG_TYPE_ARRAY || arg_count < fixed_count) {
        return false;
    }
    last_arg = arg_count > 0U
                   ? args[arg_count - 1U]
                   : NULL;
    if (last_arg != NULL && last_arg->is_prepacked_variadic_arg) {
        if (arg_count != fixed_count + 1U) {
            return cg_fail(
                cg,
                *token,
                "CE0123", "codegen: prepacked variadic argument is not at the first variadic position");
        }
        return cg_emit_expr_for_expected_type(cg, last_arg, array_type, out);
    }

    return cg_pack_variadic_args(
        cg,
        token,
        args != NULL ? args + fixed_count : NULL,
        arg_count - fixed_count,
        array_type->element,
        out);
}

static bool cg_emit_registered_call(CG *cg,
                                    const FengExpr *e,
                                    const FreeFn *fn,
                                    const ExternFn *ext,
                                    ExprResult *out) {
    const FengExpr *callee = e->as.call.callee;
    FengSlice name;
    Buf args_buf;
    bool ok = true;
    bool fn_is_variadic = fn != NULL && fn->is_variadic;
    size_t fixed_count = fn_is_variadic ? fn->param_count - 1U : 0U;

    if (callee->kind == FENG_EXPR_IDENTIFIER) {
        name = callee->as.identifier;
    } else {
        name = callee->as.member.member;
    }

    if (!ext && !fn) {
        return cg_fail(cg, e->token,
            "CE0124", "codegen: undefined function '%.*s'", (int)name.length, name.data);
    }

    /* Argument-count validation. */
    if (fn_is_variadic) {
        if (e->as.call.arg_count < fixed_count) {
            return cg_fail(cg, e->token,
                "CE0125", "codegen: too few arguments for variadic function '%.*s' (need at least %zu, got %zu)",
                (int)name.length, name.data, fixed_count, e->as.call.arg_count);
        }
    } else {
        size_t expected = ext ? ext->param_count : fn->param_count;

        if (e->as.call.arg_count != expected) {
            return cg_fail(cg, e->token,
                "CE0126", "codegen: wrong argument count for '%.*s' (expected %zu, got %zu)",
                (int)name.length, name.data, expected, e->as.call.arg_count);
        }
    }

    buf_init(&args_buf);

    /* Emit fixed-position arguments (same for variadic and non-variadic). */
    size_t fixed_arg_limit = fn_is_variadic ? fixed_count : e->as.call.arg_count;

    for (size_t i = 0; i < fixed_arg_limit; i++) {
        ExprResult ar;
        CGType *expected_ty = ext ? ext->param_types[i] : fn->param_types[i];

        if (!cg_emit_expr_for_expected_type(cg, e->as.call.args[i], expected_ty, &ar)) {
            ok = false;
            break;
        }
        const UserType *expected_abi_user =
            (ext != NULL && !ext->uses_runtime_contract) ? cg_abi_value_user_type(expected_ty)
                                                         : NULL;
        if (cgtype_is_managed(ar.type) && ar.owns_ref) {
            cg_materialize_to_local(cg, &ar, "_t");
        } else if (cgtype_is_aggregate(ar.type)) {
            cg_materialize_to_local(cg, &ar, "_t");
        } else if (expected_abi_user != NULL &&
                   cg_user_type_is_value(expected_abi_user)) {
            /* §9.12: @value @abi type is a value expression (rvalue).
             * Materialize to an lvalue so we can pass &local to
             * c_abi_value_name (which expects a const pointer). */
            cg_materialize_to_local(cg, &ar, "_t");
        }
        if (i) buf_append_cstr(&args_buf, ", ");
        if (expected_abi_user != NULL && expected_abi_user->c_abi_value_name != NULL) {
            if (cg_user_type_is_value(expected_abi_user)) {
                /* §9.12: @value @abi — pass address of the materialized
                 * local (c_abi_value_name expects const struct X *). */
                buf_append_fmt(&args_buf, "%s(&%s)",
                               expected_abi_user->c_abi_value_name, ar.c_expr);
            } else {
                buf_append_fmt(&args_buf, "%s(%s)",
                               expected_abi_user->c_abi_value_name, ar.c_expr);
            }
        } else {
            buf_append_cstr(&args_buf, ar.c_expr);
        }
        er_free(&ar);
    }

    /* Pack variadic arguments into a FengArray* and append as the last argument. */
    if (ok && fn_is_variadic) {
        const CGType *array_type = fn->param_types[fn->param_count - 1U];
        ExprResult varr;

        if (!cg_emit_variadic_array_arg(cg, e, fixed_count, array_type, &varr)) {
            ok = false;
        } else {
            if (cgtype_is_managed(varr.type) && varr.owns_ref) {
                cg_materialize_to_local(cg, &varr, "_t");
            }
            if (fixed_count > 0U) buf_append_cstr(&args_buf, ", ");
            buf_append_cstr(&args_buf, varr.c_expr);
            er_free(&varr);
        }
    }

    if (!ok) {
        buf_free(&args_buf);
        return false;
    }

    Buf b;
    buf_init(&b);
    if (ext) {
        const char *extern_c_name = cg_extern_call_target(ext);
        const UserType *return_abi_user =
            ext->uses_runtime_contract ? NULL : cg_abi_value_user_type(ext->return_type);

        if (return_abi_user != NULL && return_abi_user->c_abi_box_name != NULL) {
            char *abi_tmp = cg_fresh_temp(cg, "_abi_ret");
            char *ret_tmp = cg_fresh_temp(cg, "_ret");

            if (abi_tmp == NULL || ret_tmp == NULL) {
                free(abi_tmp);
                free(ret_tmp);
                buf_free(&args_buf);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }

            buf_append_fmt(cg->cur_body,
                "    struct %s %s = %s(%s);\n"
                "    struct %s *%s = %s(%s);\n",
                return_abi_user->c_abi_layout_name,
                abi_tmp,
                extern_c_name,
                args_buf.data ? args_buf.data : "",
                return_abi_user->c_struct_name,
                ret_tmp,
                return_abi_user->c_abi_box_name,
                abi_tmp);
            out->c_expr = ret_tmp;
            out->type = cgtype_clone(ext->return_type);
            out->owns_ref = true;
            free(abi_tmp);
            buf_free(&args_buf);
            return out->c_expr && out->type;
        }

        buf_append_fmt(&b, "%s(%s)", extern_c_name, args_buf.data ? args_buf.data : "");
        out->type = cgtype_clone(ext->return_type);
    } else {
        buf_append_fmt(&b, "%s(%s)", fn->c_name, args_buf.data ? args_buf.data : "");
        out->type = cgtype_clone(fn->return_type);
    }
    buf_free(&args_buf);
    out->c_expr = b.data;
    out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
    return out->c_expr && out->type;
}

static bool cg_emit_free_fn_abi_wrapper(CG *cg,
                                        const FreeFn *fn,
                                        bool needs_static) {
    char **call_args = NULL;
    char **boxed_params = NULL;
    bool ok = true;

    if (!cg_free_fn_has_abi_wrapper(fn)) {
        return true;
    }

    call_args = fn->param_count ? calloc(fn->param_count, sizeof *call_args) : NULL;
    boxed_params = fn->param_count ? calloc(fn->param_count, sizeof *boxed_params) : NULL;
    if (fn->param_count > 0U && (call_args == NULL || boxed_params == NULL)) {
        free(call_args);
        free(boxed_params);
        return cg_fail(cg, fn->decl->token, "IE0001", "codegen: out of memory");
    }

    Buf *body = &cg->fn_defs;
    if (needs_static) {
        buf_append_cstr(body, "static ");
    }
    cg_emit_c_abi_surface_type(body, fn->return_type);
    buf_append_fmt(body, " %s(", fn->c_abi_name);
    if (fn->param_count == 0U) {
        buf_append_cstr(body, "void");
    }
    for (size_t i = 0; i < fn->param_count; ++i) {
        const char *param_name = fn->param_names[i] ? fn->param_names[i] : "_p";
        if (i != 0U) {
            buf_append_cstr(body, ", ");
        }
        cg_emit_c_abi_surface_type(body, fn->param_types[i]);
        buf_append_fmt(body, " %s", param_name);
    }
    buf_append_cstr(body, ") {\n");

    for (size_t i = 0; i < fn->param_count; ++i) {
        const UserType *abi_user = cg_abi_value_user_type(fn->param_types[i]);
        const char *param_name = fn->param_names[i] ? fn->param_names[i] : "_p";

        if (abi_user != NULL && cg_user_type_is_value(abi_user)) {
            /* §9.12: @value @abi — wrapper param is struct <abi_layout>
             * by value; _impl function expects struct <feng_struct> by
             * value (not a pointer).  Reinterpret via type-punning cast:
             * *(struct Feng__mod__T *)&param.  Layout guaranteed
             * identical by _Static_assert in
             * cg_emit_value_type_abi_surface.  @value @abi types are
             * always trivial (no managed fields), so no cleanup is
             * needed for the wrapper parameter. */
            Buf addr_buf;
            buf_init(&addr_buf);
            buf_append_fmt(&addr_buf, "*(struct %s *)&%s",
                           abi_user->c_struct_name, param_name);
            call_args[i] = addr_buf.data;
        } else if (abi_user != NULL && abi_user->c_abi_box_name != NULL) {
            boxed_params[i] = cg_fresh_temp(cg, "_abi_arg");
            if (boxed_params[i] == NULL) {
                ok = false;
                break;
            }
            buf_append_fmt(body,
                "    struct %s *%s = %s(%s);\n",
                abi_user->c_struct_name,
                boxed_params[i],
                abi_user->c_abi_box_name,
                param_name);
            call_args[i] = strdup(boxed_params[i]);
        } else {
            call_args[i] = strdup(param_name);
        }

        if (call_args[i] == NULL) {
            ok = false;
            break;
        }
    }

    if (!ok) {
        for (size_t i = 0; i < fn->param_count; ++i) {
            free(call_args[i]);
            free(boxed_params[i]);
        }
        free(call_args);
        free(boxed_params);
        return cg_fail(cg, fn->decl->token, "IE0001", "codegen: out of memory");
    }

    const UserType *return_abi_user = cg_abi_value_user_type(fn->return_type);
    if (return_abi_user != NULL && cg_user_type_is_value(return_abi_user)) {
        /* §9.12: @value @abi return — Feng function returns struct by
         * value (not a heap pointer).  The C ABI wrapper returns the
         * same struct layout directly, no c_abi_value_name conversion
         * or feng_release needed.  @value @abi types are always trivial
         * (no managed fields), so no aggregate cleanup is needed.
         * Cast to ABI layout type (different C name, identical layout,
         * guaranteed by _Static_assert). */
        if (fn->return_type != NULL && fn->return_type->kind != CG_TYPE_VOID) {
            char *ret_tmp = cg_fresh_temp(cg, "_abi_ret");
            if (ret_tmp == NULL) {
                ok = false;
            } else {
                buf_append_cstr(body, "    ");
                cg_emit_c_type(body, fn->return_type);
                buf_append_fmt(body, " %s = %s(", ret_tmp, fn->c_name);
                for (size_t i = 0; i < fn->param_count; ++i) {
                    if (i != 0U) {
                        buf_append_cstr(body, ", ");
                    }
                    buf_append_cstr(body, call_args[i]);
                }
                buf_append_fmt(body, ");\n");
                buf_append_fmt(body,
                    "    return *(struct %s *)&%s;\n",
                    return_abi_user->c_abi_layout_name, ret_tmp);
                free(ret_tmp);
            }
        } else {
            buf_append_fmt(body, "    %s(", fn->c_name);
            for (size_t i = 0; i < fn->param_count; ++i) {
                if (i != 0U) {
                    buf_append_cstr(body, ", ");
                }
                buf_append_cstr(body, call_args[i]);
            }
            buf_append_cstr(body, ");\n");
        }
    } else if (return_abi_user != NULL && return_abi_user->c_abi_value_name != NULL) {
        char *ret_obj = cg_fresh_temp(cg, "_abi_ret_obj");
        char *ret_value = cg_fresh_temp(cg, "_abi_ret");
        if (ret_obj == NULL || ret_value == NULL) {
            free(ret_obj);
            free(ret_value);
            ok = false;
        } else {
            buf_append_fmt(body,
                "    struct %s *%s = %s(",
                return_abi_user->c_struct_name,
                ret_obj,
                fn->c_name);
            for (size_t i = 0; i < fn->param_count; ++i) {
                if (i != 0U) {
                    buf_append_cstr(body, ", ");
                }
                buf_append_cstr(body, call_args[i]);
            }
            buf_append_cstr(body, ");\n");
            buf_append_fmt(body,
                "    struct %s %s = %s(%s);\n"
                "    feng_release(%s);\n",
                return_abi_user->c_abi_layout_name,
                ret_value,
                return_abi_user->c_abi_value_name,
                ret_obj,
                ret_obj);
            for (size_t i = 0; i < fn->param_count; ++i) {
                if (boxed_params[i] != NULL) {
                    buf_append_fmt(body, "    feng_release(%s);\n", boxed_params[i]);
                }
            }
            buf_append_fmt(body, "    return %s;\n", ret_value);
            free(ret_obj);
            free(ret_value);
        }
    } else if (fn->return_type != NULL && fn->return_type->kind != CG_TYPE_VOID) {
        buf_append_cstr(body, "    ");
        cg_emit_c_abi_surface_type(body, fn->return_type);
        buf_append_fmt(body, " _ret = %s(", fn->c_name);
        for (size_t i = 0; i < fn->param_count; ++i) {
            if (i != 0U) {
                buf_append_cstr(body, ", ");
            }
            buf_append_cstr(body, call_args[i]);
        }
        buf_append_cstr(body, ");\n");
        for (size_t i = 0; i < fn->param_count; ++i) {
            if (boxed_params[i] != NULL) {
                buf_append_fmt(body, "    feng_release(%s);\n", boxed_params[i]);
            }
        }
        buf_append_cstr(body, "    return _ret;\n");
    } else {
        buf_append_fmt(body, "    %s(", fn->c_name);
        for (size_t i = 0; i < fn->param_count; ++i) {
            if (i != 0U) {
                buf_append_cstr(body, ", ");
            }
            buf_append_cstr(body, call_args[i]);
        }
        buf_append_cstr(body, ");\n");
        for (size_t i = 0; i < fn->param_count; ++i) {
            if (boxed_params[i] != NULL) {
                buf_append_fmt(body, "    feng_release(%s);\n", boxed_params[i]);
            }
        }
        buf_append_cstr(body, "    return;\n");
    }
    buf_append_cstr(body, "}\n\n");

    for (size_t i = 0; i < fn->param_count; ++i) {
        free(call_args[i]);
        free(boxed_params[i]);
    }
    free(call_args);
    free(boxed_params);
    return ok;
}

static bool cg_emit_callable_value_call(CG *cg,
                                        const FengExpr *e,
                                        ExprResult *callee,
                                        const UserSpec *spec,
                                        ExprResult *out) {
    Buf args_buf;
    bool is_variadic;
    size_t fixed_count;

    er_init(out);
    if (spec == NULL || spec->form != FENG_SPEC_FORM_CALLABLE) {
        return cg_fail(cg, e->token,
            "CE0127", "codegen: callable value call requires a callable-form spec type");
    }
    is_variadic = spec->callable_is_variadic;
    fixed_count = is_variadic ? spec->callable_param_count - 1U : spec->callable_param_count;
    if (is_variadic) {
        if (e->as.call.arg_count < fixed_count) {
            return cg_fail(cg, e->token,
                "CE0128", "codegen: too few arguments for variadic callable '%s' (need at least %zu, got %zu)",
                spec->feng_name,
                fixed_count,
                e->as.call.arg_count);
        }
    } else if (e->as.call.arg_count != spec->callable_param_count) {
        return cg_fail(cg, e->token,
            "CE0129", "codegen: wrong argument count for callable '%s' (expected %zu, got %zu)",
            spec->feng_name,
            spec->callable_param_count,
            e->as.call.arg_count);
    }
    if (cgtype_is_managed(callee->type) && callee->owns_ref) {
        cg_materialize_to_local(cg, callee, "_t");
    }

    buf_init(&args_buf);
    for (size_t i = 0; i < (is_variadic ? fixed_count : e->as.call.arg_count); ++i) {
        ExprResult ar;
        char *argument_expr;
        if (!cg_emit_expr_for_expected_type(cg,
                                            e->as.call.args[i],
                                            spec->callable_param_types[i],
                                            &ar)) {
            buf_free(&args_buf);
            return false;
        }
        if ((cgtype_is_managed(ar.type) || cgtype_is_aggregate(ar.type)) && ar.owns_ref) {
            cg_materialize_to_local(cg, &ar, "_t");
        }
        argument_expr = cg_shared_callable_argument_expr_dup(
            cg,
            &ar,
            spec->callable_param_abi_kinds[i] == CG_CALLABLE_ABI_ADDRESS,
            "_call_arg");
        if (argument_expr == NULL) {
            er_free(&ar);
            buf_free(&args_buf);
            return cg_fail(cg, e->token,
                           "IE0001", "codegen: callable argument lowering failed");
        }
        buf_append_cstr(&args_buf, ", ");
        buf_append_cstr(&args_buf, argument_expr);
        free(argument_expr);
        er_free(&ar);
    }

    if (is_variadic) {
        ExprResult varr;

        if (!cg_emit_variadic_array_arg(
                cg,
                e,
                fixed_count,
                spec->callable_param_types[spec->callable_param_count - 1U],
                &varr)) {
            buf_free(&args_buf);
            return false;
        }
        if (cgtype_is_managed(varr.type) && varr.owns_ref) {
            cg_materialize_to_local(cg, &varr, "_t");
        }
        buf_append_cstr(&args_buf, ", ");
        buf_append_cstr(&args_buf, varr.c_expr);
        er_free(&varr);
    }

    if (spec->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        char *result_name = cg_fresh_temp(cg, "_call_result");
        char *erased_descriptor_name = NULL;
        char *erased_size_name = NULL;

        if (result_name == NULL) {
            buf_free(&args_buf);
            er_free(callee);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        if (spec->callable_return_type->kind == CG_TYPE_GENERIC_PARAM) {
            if (!cg_emit_erased_generic_storage_declaration(
                    cg,
                    spec->callable_return_type,
                    result_name,
                    e->token,
                    &erased_descriptor_name,
                    &erased_size_name)) {
                free(result_name);
                buf_free(&args_buf);
                er_free(callee);
                return false;
            }
            out->c_expr = strdup(result_name);
            out->is_addressable = true;
            out->is_storage_address = true;
        } else if (cg_type_uses_reified_storage(
                       cg, spec->callable_return_type)) {
            if (!cg_emit_reified_storage_declaration(
                    cg,
                    spec->callable_return_type,
                    result_name,
                    e->token,
                    &out->reified_descriptor_c_name,
                    &out->reified_size_c_name)) {
                free(result_name);
                buf_free(&args_buf);
                er_free(callee);
                return false;
            }
            out->c_expr = strdup(result_name);
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_reified_storage = true;
        } else {
            char *result_ctype = cg_ctype_dup(spec->callable_return_type);

            if (result_ctype == NULL) {
                free(result_name);
                buf_free(&args_buf);
                er_free(callee);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            buf_append_fmt(cg->cur_body,
                           "    %s %s;\n",
                           result_ctype,
                           result_name);
            free(result_ctype);
            out->c_expr = strdup(result_name);
            out->is_addressable = true;
        }
        if (out->c_expr == NULL) {
            free(erased_descriptor_name);
            free(erased_size_name);
            free(result_name);
            buf_free(&args_buf);
            er_free(callee);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "    ((struct %s *)%s)->invoke(%s%s, %s%s);\n",
                       spec->c_closure_struct_name,
                       callee->c_expr,
                       callee->c_expr,
                       args_buf.data ? args_buf.data : "",
                       (spec->callable_return_type->kind == CG_TYPE_GENERIC_PARAM ||
                        out->uses_reified_storage) ? "" : "&",
                       result_name);
        if (spec->callable_return_type->kind == CG_TYPE_GENERIC_PARAM) {
            out->type = cgtype_clone(spec->callable_return_type);
            if (out->type == NULL ||
                !cg_register_erased_generic_storage_for_cleanup(
                    cg,
                    result_name,
                    out->type,
                    erased_descriptor_name,
                    erased_size_name,
                    e->token)) {
                free(erased_descriptor_name);
                free(erased_size_name);
                free(result_name);
                buf_free(&args_buf);
                er_free(callee);
                er_free(out);
                return false;
            }
            out->owns_ref = false;
            out->uses_erased_generic_storage = true;
            out->erased_generic_descriptor_c_name = erased_descriptor_name;
            out->erased_generic_size_c_name = erased_size_name;
            erased_descriptor_name = NULL;
            erased_size_name = NULL;
        }
        free(erased_descriptor_name);
        free(erased_size_name);
        free(result_name);
    } else {
        Buf invocation;

        buf_init(&invocation);
        buf_append_fmt(&invocation, "((struct %s *)%s)->invoke(%s%s)",
                       spec->c_closure_struct_name,
                       callee->c_expr,
                       callee->c_expr,
                       args_buf.data ? args_buf.data : "");
        out->c_expr = invocation.data;
    }
    buf_free(&args_buf);
    if (out->type == NULL) {
        out->type = cgtype_clone(spec->callable_return_type);
        out->owns_ref = cgtype_is_managed(out->type) ||
                        cgtype_is_aggregate(out->type);
    }
    bool ok = out->c_expr && out->type;
    er_free(callee);
    return ok;
}

static bool cg_emit_generic_callable_value_call(CG *cg,
                                                const FengExpr *e,
                                                ExprResult *callee,
                                                size_t generic_param_index,
                                                ExprResult *out) {
    const UserSpec *constraint = cg_generic_param_constraint_spec(cg, generic_param_index);
    const char *desc_name = cg_generic_param_desc_name(cg, generic_param_index);
    char **arg_addr_exprs = NULL;
    bool ok = true;
    bool is_variadic;
    size_t fixed_count;
    size_t emitted_arg_count;
    char *callee_subject = NULL;

    er_init(out);
    if (constraint == NULL || constraint->form != FENG_SPEC_FORM_CALLABLE ||
        desc_name == NULL) {
        er_free(callee);
        return cg_fail(cg, e->token,
            "CE0130", "codegen: generic direct call requires a callable-form spec constraint");
    }
    is_variadic = constraint->callable_is_variadic;
    fixed_count = is_variadic ? constraint->callable_param_count - 1U
                              : constraint->callable_param_count;
    emitted_arg_count = is_variadic ? constraint->callable_param_count : e->as.call.arg_count;
    if (is_variadic) {
        if (e->as.call.arg_count < fixed_count) {
            er_free(callee);
            return cg_fail(cg, e->token,
                "CE0131", "codegen: too few arguments for variadic callable constraint '%s' (need at least %zu, got %zu)",
                constraint->feng_name,
                fixed_count,
                e->as.call.arg_count);
        }
    } else if (e->as.call.arg_count != constraint->callable_param_count) {
        er_free(callee);
        return cg_fail(cg, e->token,
            "CE0132", "codegen: wrong argument count for callable constraint '%s' (expected %zu, got %zu)",
            constraint->feng_name,
            constraint->callable_param_count,
            e->as.call.arg_count);
    }
    if (callee->is_storage_address) {
        Buf subject;

        buf_init(&subject);
        buf_append_fmt(&subject,
                       "(*(void *const *)%s)",
                       callee->c_expr);
        callee_subject = subject.data;
    } else {
        callee_subject = strdup(callee->c_expr);
    }
    if (callee_subject == NULL) {
        er_free(callee);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    arg_addr_exprs = calloc(emitted_arg_count, sizeof *arg_addr_exprs);
    if (arg_addr_exprs == NULL) {
        free(callee_subject);
        er_free(callee);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    for (size_t i = 0; i < fixed_count; ++i) {
        ExprResult ar;

        if (!cg_emit_expr_for_expected_type(cg,
                                            e->as.call.args[i],
                                            constraint->callable_param_types[i],
                                            &ar)) {
            ok = false;
            break;
        }
        arg_addr_exprs[i] = cg_shared_callable_argument_expr_dup(
            cg, &ar, true, "_ca");
        er_free(&ar);
        if (arg_addr_exprs[i] == NULL) {
            ok = false;
            break;
        }
    }

    if (ok && is_variadic) {
        ExprResult varr;

        if (!cg_emit_variadic_array_arg(
                cg,
                e,
                fixed_count,
                constraint->callable_param_types[constraint->callable_param_count - 1U],
                &varr)) {
            ok = false;
        } else {
            if ((cgtype_is_managed(varr.type) || cgtype_is_aggregate(varr.type)) && varr.owns_ref) {
                if (cg_materialize_to_local(cg, &varr, "_ca") == NULL) {
                    er_free(&varr);
                    ok = false;
                }
            }
            if (ok) {
                arg_addr_exprs[emitted_arg_count - 1U] =
                    cg_aggregate_result_address_dup(&varr);
                if (arg_addr_exprs[emitted_arg_count - 1U] == NULL) {
                    ok = false;
                }
            }
            er_free(&varr);
        }
    }

    if (!ok) {
        for (size_t i = 0; i < emitted_arg_count; ++i) free(arg_addr_exprs[i]);
        free(arg_addr_exprs);
        free(callee_subject);
        er_free(callee);
        return false;
    }

    if (constraint->callable_return_type != NULL &&
        constraint->callable_return_type->kind != CG_TYPE_VOID) {
        char *ret_tmp = cg_fresh_temp(cg, "_cr");
        bool return_is_storage_address = false;
        bool return_uses_erased_generic_storage = false;
        char *erased_descriptor_name = NULL;
        char *erased_size_name = NULL;

        if (ret_tmp == NULL) {
            free(ret_tmp);
            ok = false;
        } else {
            if (constraint->callable_return_type->kind == CG_TYPE_GENERIC_PARAM) {
                if (!cg_emit_erased_generic_storage_declaration(
                        cg,
                        constraint->callable_return_type,
                        ret_tmp,
                        e->token,
                        &erased_descriptor_name,
                        &erased_size_name)) {
                    ok = false;
                } else {
                    return_is_storage_address = true;
                    return_uses_erased_generic_storage = true;
                }
            } else if (cg_type_uses_reified_storage(
                           cg, constraint->callable_return_type)) {
                if (!cg_emit_reified_storage_declaration(
                        cg,
                        constraint->callable_return_type,
                        ret_tmp,
                        e->token,
                        &out->reified_descriptor_c_name,
                        &out->reified_size_c_name)) {
                    ok = false;
                } else {
                    return_is_storage_address = true;
                    out->uses_reified_storage = true;
                }
            } else {
                char *ret_cty = cg_ctype_dup(constraint->callable_return_type);

                if (ret_cty == NULL) {
                    ok = false;
                } else {
                    buf_append_fmt(cg->cur_body, "    %s %s;\n", ret_cty, ret_tmp);
                }
                free(ret_cty);
            }
        }
        if (ok) {
            buf_append_fmt(cg->cur_body, "    ((const struct %s *)%s->witness)->invoke(%s",
                           constraint->c_witness_struct_name,
                           desc_name,
                           callee_subject);
            for (size_t i = 0; i < emitted_arg_count; ++i) {
                buf_append_fmt(cg->cur_body, ", %s", arg_addr_exprs[i]);
            }
            buf_append_fmt(cg->cur_body,
                           ", %s%s);\n",
                           return_is_storage_address ? "" : "&",
                           ret_tmp);
            out->c_expr = strdup(ret_tmp);
            out->type = cgtype_clone(constraint->callable_return_type);
            out->owns_ref = out->type != NULL &&
                (cgtype_is_managed(out->type) ||
                 cgtype_is_aggregate(out->type));
            out->is_addressable = true;
            out->is_storage_address = return_is_storage_address;
            if (return_uses_erased_generic_storage) {
                if (out->c_expr == NULL || out->type == NULL ||
                    !cg_register_erased_generic_storage_for_cleanup(
                        cg,
                        ret_tmp,
                        out->type,
                        erased_descriptor_name,
                        erased_size_name,
                        e->token)) {
                    ok = false;
                } else {
                    out->owns_ref = false;
                    out->uses_erased_generic_storage = true;
                    out->erased_generic_descriptor_c_name =
                        erased_descriptor_name;
                    out->erased_generic_size_c_name = erased_size_name;
                    erased_descriptor_name = NULL;
                    erased_size_name = NULL;
                }
            }
            ok = ok && out->c_expr && out->type;
        }
        free(erased_descriptor_name);
        free(erased_size_name);
        free(ret_tmp);
    } else {
        buf_append_fmt(cg->cur_body, "    ((const struct %s *)%s->witness)->invoke(%s",
                       constraint->c_witness_struct_name,
                       desc_name,
                       callee_subject);
        for (size_t i = 0; i < emitted_arg_count; ++i) {
            buf_append_fmt(cg->cur_body, ", %s", arg_addr_exprs[i]);
        }
        buf_append_cstr(cg->cur_body, ", NULL);\n");
        out->c_expr = strdup("((void)0)");
        out->type = cgtype_new(CG_TYPE_VOID);
        out->owns_ref = false;
        ok = out->c_expr && out->type;
    }

    for (size_t i = 0; i < emitted_arg_count; ++i) free(arg_addr_exprs[i]);
    free(arg_addr_exprs);
    free(callee_subject);
    er_free(callee);
    return ok;
}

/* Fix one computed callable value before its enclosing call evaluates any
 * arguments. Owned results are adopted by the ordinary local materializer;
 * borrowed concrete callables receive the same retain and scoped cleanup as
 * an explicit Feng local binding. Generic values reuse descriptor-selected
 * materialization so the concrete runtime representation remains unchanged. */
static bool cg_stabilize_computed_callable_callee(CG *cg,
                                                  ExprResult *callee,
                                                  FengToken blame) {
    if (callee == NULL || callee->type == NULL || callee->c_expr == NULL) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: computed callable has no emitted value");
    }
    if (callee->type->kind == CG_TYPE_GENERIC_PARAM || callee->owns_ref) {
        if (cg_materialize_to_local(cg, callee, "_callee") == NULL) {
            if (!cg->failed) {
                cg_fail(cg,
                        blame,
                        "IE0001",
                        "codegen: failed to materialize computed callable");
            }
            return false;
        }
        return true;
    }
    if (callee->type->kind != CG_TYPE_CALLABLE ||
        !cgtype_is_managed(callee->type)) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: computed call target is not a callable value");
    }

    char *temporary = cg_fresh_temp(cg, "_callee");
    char *ctype = cg_ctype_dup(callee->type);

    if (temporary == NULL || ctype == NULL) {
        free(temporary);
        free(ctype);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    %s %s = %s; feng_retain(%s);\n",
                   ctype,
                   temporary,
                   callee->c_expr,
                   temporary);
    free(ctype);
    if (!cg_register_local_for_cleanup(cg,
                                       temporary,
                                       callee->type,
                                       blame)) {
        free(temporary);
        return false;
    }

    free(callee->c_expr);
    callee->c_expr = strdup(temporary);
    callee->owns_ref = false;
    callee->is_addressable = true;
    callee->is_storage_address = false;
    free(temporary);
    if (callee->c_expr == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    return true;
}

/* Emit a call whose target is an arbitrary computed expression already
 * accepted as callable by Semantic. This path only bridges the emitted value
 * into the existing concrete or constrained-generic callable invoke helpers. */
static bool cg_emit_computed_callable_call(CG *cg,
                                           const FengExpr *call,
                                           ExprResult *out) {
    ExprResult callee;

    er_init(&callee);
    if (!cg_emit_expr(cg, call->as.call.callee, &callee)) {
        return false;
    }
    if (callee.type != NULL && callee.type->kind == CG_TYPE_CALLABLE &&
        callee.type->user_spec != NULL &&
        callee.type->user_spec->form == FENG_SPEC_FORM_CALLABLE) {
        const UserSpec *spec = callee.type->user_spec;

        if (!cg_stabilize_computed_callable_callee(cg,
                                                   &callee,
                                                   call->token)) {
            er_free(&callee);
            return false;
        }
        return cg_emit_callable_value_call(cg, call, &callee, spec, out);
    }
    if (callee.type != NULL &&
        callee.type->kind == CG_TYPE_GENERIC_PARAM) {
        size_t generic_param_index = callee.type->generic_param_index;
        const UserSpec *constraint =
            cg_generic_param_constraint_spec(cg, generic_param_index);

        if (constraint != NULL &&
            constraint->form == FENG_SPEC_FORM_CALLABLE) {
            if (!cg_stabilize_computed_callable_callee(cg,
                                                       &callee,
                                                       call->token)) {
                er_free(&callee);
                return false;
            }
            return cg_emit_generic_callable_value_call(cg,
                                                       call,
                                                       &callee,
                                                       generic_param_index,
                                                       out);
        }
    }

    er_free(&callee);
    return cg_fail(cg,
                   call->token,
                   "IE0002",
                   "codegen: Semantic accepted a non-callable computed call target");
}

static bool cg_build_method_type_param_constraints(CG *cg,
                                                   const UserType *owner,
                                                   const FengCallableSignature *sig,
                                                   FengToken blame,
                                                   const UserSpec ***out_constraints) {
    size_t count = sig ? sig->type_param_count : 0U;
    const UserSpec **constraints = count ? calloc(count, sizeof *constraints) : NULL;
    size_t *constraint_indices = count ? calloc(count, sizeof *constraint_indices) : NULL;
    CGTypeParamScope scope = {0};
    char **context_names = NULL;
    size_t context_count = 0U;
    bool saved_in_generic_fn;
    size_t saved_tp_count;
    char **saved_tp_names;
    const UserSpec **saved_tp_constraints;
    const char **saved_tp_descs;
    bool ok = false;

    *out_constraints = NULL;
    if (count > 0U && (constraints == NULL || constraint_indices == NULL)) {
        free((void *)constraints);
        free(constraint_indices);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0U; i < count; ++i) {
        constraint_indices[i] = (size_t)-1;
    }

    /* An open owner retains its declared descriptor domain before the method
     * domain. A closed owner has already substituted that domain away. */
    if (owner != NULL && owner->is_generic_instance &&
        owner->generic_context_type_param_count > 0U &&
        owner->generic_origin_decl != NULL &&
        owner->generic_origin_decl->kind == FENG_DECL_TYPE) {
        scope.first = owner->generic_origin_decl->as.type_decl.type_params;
        scope.first_count =
            owner->generic_origin_decl->as.type_decl.type_param_count;
    }
    scope.second = sig != NULL ? sig->type_params : NULL;
    scope.second_count = count;
    if (!cg_type_param_scope_copy_names(&scope,
                                        &context_names,
                                        &context_count)) {
        free((void *)constraints);
        free(constraint_indices);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    saved_in_generic_fn = cg->in_generic_fn;
    saved_tp_count = cg->generic_fn_type_param_count;
    saved_tp_names = cg->generic_fn_type_param_names;
    saved_tp_constraints = cg->generic_fn_type_param_constraints;
    saved_tp_descs = cg->generic_fn_type_param_descs;
    cg->in_generic_fn = context_count > 0U;
    cg->generic_fn_type_param_count = context_count;
    cg->generic_fn_type_param_names = context_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;

    for (size_t i = 0; i < count; ++i) {
        const FengTypeRef *constraint_ref = sig->type_params[i].constraint;
        FengTypeRef *substituted = NULL;
        CGType *constraint_type = NULL;
        bool resolved;

        if (constraint_ref == NULL) {
            continue;
        }
        if (owner != NULL && owner->is_generic_instance) {
            substituted = cg_type_ref_substitute(
                constraint_ref,
                owner->generic_origin_decl->as.type_decl.type_params,
                owner->generic_origin_decl->as.type_decl.type_param_count,
                owner->generic_type_args);
            if (substituted == NULL) {
                goto cleanup;
            }
            constraint_ref = substituted;
        }

        resolved = cg_collect_generic_instances_from_type_ref(cg,
                                                              constraint_ref,
                                                              scope) &&
                   cg_resolve_type(cg,
                                   constraint_ref,
                                   &sig->type_params[i].token,
                                   &constraint_type);

        cg_type_ref_free(substituted);
        if (!resolved) {
            goto cleanup;
        }
        if (constraint_type == NULL ||
            (constraint_type->kind != CG_TYPE_SPEC &&
             constraint_type->kind != CG_TYPE_CALLABLE) ||
             constraint_type->user_spec == NULL) {
            cgtype_free(constraint_type);
            cg_fail(cg, sig->type_params[i].token,
                    "CE0133", "codegen: generic method constraint for '%.*s' must be a spec supported by codegen",
                    (int)sig->type_params[i].name.length,
                    sig->type_params[i].name.data);
            goto cleanup;
        }
        if (!cg_user_spec_index(cg,
                                constraint_type->user_spec,
                                &constraint_indices[i])) {
            cgtype_free(constraint_type);
            goto cleanup;
        }
        cgtype_free(constraint_type);
    }

    for (size_t i = 0U; i < count; ++i) {
        constraints[i] = cg_user_spec_by_index(cg, constraint_indices[i]);
    }
    ok = true;

cleanup:
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_cstr_array(context_names, context_count);
    free(constraint_indices);
    if (!ok) {
        free((void *)constraints);
        return false;
    }
    *out_constraints = constraints;
    return true;
}

/* Return whether calls to this concrete generic-fit method enter a thin
 * wrapper that owns the member's closed function descriptor. Method-generic
 * members remain call-site-parametric and receive their descriptor exactly as
 * generic methods declared directly on a type do. */
static bool cg_closed_generic_fit_wrapper_binds_function_descriptor(
    const UserFit *fit,
    const UserType *owner,
    const FengTypeMember *member) {
    return fit != NULL && owner != NULL && fit->target == owner &&
           member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
           member->as.callable.type_param_count == 0U &&
           owner->is_generic_instance &&
           owner->generic_origin_decl != NULL &&
           owner->generic_context_type_param_count == 0U;
}

static CGType *cg_infer_method_type_arg(const FengCallableSignature *sig,
                                        size_t tp_idx,
                                        ExprResult *args,
                                        size_t arg_count) {
    size_t param_count = sig ? sig->param_count : 0U;
    size_t n = arg_count < param_count ? arg_count : param_count;
    if (sig == NULL || tp_idx >= sig->type_param_count) return NULL;
    for (size_t i = 0; i < n; ++i) {
        const FengTypeRef *param_type = sig->params[i].type;
        FengSlice type_param_name = sig->type_params[tp_idx].name;
        if (param_type == NULL) continue;
        /* Direct match: param is T (named type ref matching type param name). */
        if (param_type->kind == FENG_TYPE_REF_NAMED &&
            param_type->as.named.segment_count == 1U &&
            param_type->as.named.type_arg_count == 0U) {
            const FengSlice *segment = &param_type->as.named.segments[0];
            if (segment->length == type_param_name.length &&
                memcmp(segment->data, type_param_name.data, segment->length) == 0) {
                return cgtype_clone(args[i].type);
            }
        }
        /* Variadic match: param is T[] (array whose element is the type param).
         * For variadic parameters, the actual argument is already an array,
         * so infer T from the array element type. For non-variadic array params
         * where the caller passed a plain value at position i, infer T directly
         * from the argument type (this covers variadic call expansion). */
        if (param_type->kind == FENG_TYPE_REF_ARRAY &&
            param_type->as.inner != NULL &&
            param_type->as.inner->kind == FENG_TYPE_REF_NAMED &&
            param_type->as.inner->as.named.segment_count == 1U &&
            param_type->as.inner->as.named.type_arg_count == 0U) {
            const FengSlice *segment = &param_type->as.inner->as.named.segments[0];
            if (segment->length == type_param_name.length &&
                memcmp(segment->data, type_param_name.data, segment->length) == 0) {
                /* If the arg is an array, infer T from its element type. */
                if (args[i].type != NULL && args[i].type->kind == CG_TYPE_ARRAY &&
                    args[i].type->element != NULL) {
                    return cgtype_clone(args[i].type->element);
                }
                /* Otherwise infer T directly from the arg type
                 * (variadic expansion: individual args not yet packed). */
                return cgtype_clone(args[i].type);
            }
        }
    }
    /* Fallback for variadic: if arg_count > param_count, the extra args
     * correspond to the variadic parameter. Try to infer from the first
     * extra arg using the last (variadic) parameter's element type. */
    if (param_count > 0U && arg_count > param_count) {
        const FengTypeRef *last_param = sig->params[param_count - 1U].type;
        if (last_param != NULL &&
            last_param->kind == FENG_TYPE_REF_ARRAY &&
            last_param->as.inner != NULL &&
            last_param->as.inner->kind == FENG_TYPE_REF_NAMED &&
            last_param->as.inner->as.named.segment_count == 1U &&
            last_param->as.inner->as.named.type_arg_count == 0U) {
            const FengSlice *segment = &last_param->as.inner->as.named.segments[0];
            FengSlice type_param_name = sig->type_params[tp_idx].name;
            if (segment->length == type_param_name.length &&
                memcmp(segment->data, type_param_name.data, segment->length) == 0) {
                /* Infer from the first variadic argument. */
                return cgtype_clone(args[param_count].type);
            }
        }
    }
    return NULL;
}

/* Return whether semantic analysis recorded the complete callable-local type
 * arguments for this selected call.  These caller-view refs are authoritative
 * after overload resolution, including arguments inferred from the target
 * type rather than from value arguments. */
static bool cg_call_has_resolved_callable_type_args(const FengExpr *call,
                                                    size_t expected_count) {
    const FengResolvedCallable *resolved;

    if (call == NULL || call->kind != FENG_EXPR_CALL) {
        return false;
    }
    resolved = &call->as.call.resolved_callable;
    return resolved->callable_type_arg_count == expected_count &&
           (expected_count == 0U || resolved->callable_type_args != NULL);
}

/* Resolve the callable-local type arguments persisted by semantic analysis
 * into codegen types.  This is a compile-time conversion only; it does not
 * alter the generated generic-call ABI or add runtime work. */
static bool cg_resolve_recorded_callable_type_args(CG *cg,
                                                   const FengExpr *call,
                                                   size_t type_arg_count,
                                                   CGType **out_type_args) {
    const FengResolvedCallable *resolved = &call->as.call.resolved_callable;

    for (size_t i = 0U; i < type_arg_count; ++i) {
        if (!cg_resolve_type(cg,
                             resolved->callable_type_args[i],
                             &call->token,
                             &out_type_args[i])) {
            return false;
        }
    }
    return true;
}

/* Resolve any selected callable type surface after applying both generic
 * layers recorded by semantic analysis. Owner parameters are substituted
 * first, followed by callable-local parameters; the resulting closed (or
 * caller-relative open) type is then resolved in the declaring program. */
static bool cg_resolve_selected_callable_type_ref(
    CG *cg,
    const FengExpr *call_expr,
    const FengCallableSignature *callable,
    const FengTypeRef *declared_type_ref,
    FengToken blame,
    CGType **out_type) {
    const FengResolvedCallable *resolved;
    const FengTypeRef *effective_ref;
    FengTypeRef *owner_substituted = NULL;
    FengTypeRef *callable_substituted = NULL;
    const FengProgram *reference_program = NULL;
    CGTypeParamScope substituted_scope = {0};
    bool ok;

    if (out_type == NULL) {
        return false;
    }
    *out_type = NULL;
    if (cg == NULL || call_expr == NULL ||
        call_expr->kind != FENG_EXPR_CALL || callable == NULL ||
        declared_type_ref == NULL) {
        return false;
    }

    resolved = &call_expr->as.call.resolved_callable;
    effective_ref = declared_type_ref;
    if (resolved->owner_type_decl != NULL &&
        (resolved->owner_type_decl->kind == FENG_DECL_TYPE ||
         resolved->owner_type_decl->kind == FENG_DECL_SPEC)) {
        const FengDecl *owner_decl = resolved->owner_type_decl;
        const FengTypeParam *owner_params =
            owner_decl->kind == FENG_DECL_TYPE
                ? owner_decl->as.type_decl.type_params
                : owner_decl->as.spec_decl.type_params;
        size_t owner_count =
            owner_decl->kind == FENG_DECL_TYPE
                ? owner_decl->as.type_decl.type_param_count
                : owner_decl->as.spec_decl.type_param_count;

        reference_program = cg_find_decl_owner_program(cg, owner_decl);
        substituted_scope.first = owner_params;
        substituted_scope.first_count = owner_count;
        if (owner_count > 0U) {
            if (resolved->owner_instance_type_ref == NULL ||
                resolved->owner_instance_type_ref->kind != FENG_TYPE_REF_NAMED ||
                resolved->owner_instance_type_ref->as.named.type_arg_count !=
                    owner_count) {
                return cg_fail(
                    cg, blame, "CE0297",
                    "codegen: selected generic method return type is missing owner arguments");
            }
            owner_substituted = cg_type_ref_substitute(
                effective_ref,
                owner_params,
                owner_count,
                resolved->owner_instance_type_ref->as.named.type_args);
            if (owner_substituted == NULL) {
                return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }
            effective_ref = owner_substituted;
        }
    } else if (resolved->fit_decl != NULL) {
        reference_program =
            cg_find_decl_owner_program(cg, resolved->fit_decl);
    } else if (resolved->function_decl != NULL) {
        reference_program =
            cg_find_decl_owner_program(cg, resolved->function_decl);
    }

    if (callable->type_param_count > 0U) {
        substituted_scope.second = callable->type_params;
        substituted_scope.second_count = callable->type_param_count;
        if (resolved->callable_type_arg_count != callable->type_param_count) {
            cg_type_ref_free(owner_substituted);
            return cg_fail(
                cg, blame, "CE0298",
                "codegen: selected generic callable return type is missing callable arguments");
        }
        callable_substituted = cg_type_ref_substitute(
            effective_ref,
            callable->type_params,
            callable->type_param_count,
            (FengTypeRef *const *)resolved->callable_type_args);
        if (callable_substituted == NULL) {
            cg_type_ref_free(owner_substituted);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        effective_ref = callable_substituted;
    }

    {
        const FengProgram *fallback_program =
            cg_type_ref_contains_type_param(declared_type_ref,
                                            &substituted_scope)
                ? NULL
                : reference_program;
        bool handled = false;

        ok = cg_try_resolve_declared_generic_type_ref(
            cg,
            declared_type_ref,
            effective_ref,
            reference_program,
            &blame,
            out_type,
            &handled);
        if (ok && !handled) {
            ok = cg_resolve_type_from_program(cg,
                                              effective_ref,
                                              fallback_program,
                                              &blame,
                                              out_type);
        }
    }
    cg_type_ref_free(callable_substituted);
    cg_type_ref_free(owner_substituted);
    return ok;
}

/* Resolve the selected callable return through the common type-surface
 * substitution helper; a missing return type denotes void. */
static bool cg_resolve_selected_callable_return_type(
    CG *cg,
    const FengExpr *call_expr,
    const FengCallableSignature *callable,
    FengToken blame,
    CGType **out_type) {
    if (out_type == NULL) {
        return false;
    }
    if (callable == NULL || callable->return_type == NULL) {
        *out_type = cgtype_new(CG_TYPE_VOID);
        return *out_type != NULL;
    }
    return cg_resolve_selected_callable_type_ref(
        cg,
        call_expr,
        callable,
        callable->return_type,
        blame,
        out_type);
}

static bool cg_emit_generic_type_method_call(CG *cg,
                                             const FengExpr *e,
                                             ExprResult *recv,
                                             const UserType *ut,
                                             const UserMethod *um,
                                             const UserFit *user_fit,
                                             ExprResult *out) {
    const FengCallableSignature *sig = um ? &um->member->as.callable : NULL;
    size_t method_tp_count = sig ? sig->type_param_count : 0U;
    size_t arg_count = e->as.call.arg_count;
    bool method_is_variadic = um != NULL && um->is_variadic;
    size_t fixed_param_count = method_is_variadic
                                   ? um->param_count - 1U
                                   : um->param_count;
    size_t emitted_arg_count = method_is_variadic
                                   ? um->param_count
                                   : arg_count;
    bool has_prepacked_variadic_arg =
        method_is_variadic && arg_count > 0U &&
        e->as.call.args[arg_count - 1U]->is_prepacked_variadic_arg;
    ExprResult *args = NULL;
    CGType **type_args = NULL;
    const UserSpec **constraint_specs = NULL;
    char **desc_exprs = NULL;
    char **arg_exprs = NULL;
    char *func_desc_expr = NULL;
    char *dispatch_name = NULL;
    char *shared_type_desc_expr = NULL;
    CGType *variadic_array_type = NULL;
    CGType *concrete_return = NULL;
    char *ret_cname = NULL;
    char *ret_erased_descriptor_name = NULL;
    char *ret_erased_size_name = NULL;
    char *ret_reified_descriptor_name = NULL;
    char *ret_reified_size_name = NULL;
    bool return_uses_erased_generic_storage = false;
    bool return_uses_reified_storage = false;
    bool wrapper_binds_func_desc =
        cg_closed_generic_fit_wrapper_binds_function_descriptor(
            user_fit, ut, um != NULL ? um->member : NULL);
    bool ok = true;

    er_init(out);
    if (sig == NULL || method_tp_count == 0U) {
        er_free(recv);
        return cg_fail(cg, e->token,
            "CE0134", "codegen: internal: generic type method call missing method type parameters");
    }
    if (e->as.call.has_explicit_type_args &&
        e->as.call.explicit_type_arg_count != method_tp_count) {
        er_free(recv);
        return cg_fail(cg, e->token,
            "CE0135", "codegen: method expects %zu type argument(s), got %zu",
            method_tp_count,
            e->as.call.explicit_type_arg_count);
    }
    if ((method_is_variadic && arg_count < fixed_param_count) ||
        (!method_is_variadic && arg_count != um->param_count)) {
        er_free(recv);
        return cg_fail(cg, e->token,
            "CE0136", "codegen: semantic argument-count invariant failed for generic method '%s' "
            "(expected %s%zu, got %zu)",
            um->feng_name,
            method_is_variadic ? "at least " : "",
            fixed_param_count,
            arg_count);
    }
    if (cgtype_is_managed(recv->type) && recv->owns_ref) {
        cg_materialize_to_local(cg, recv, "_t");
    }
    /* §9.15: value-semantics (tuple/@value) method takes struct X *self; pass
     * &recv directly for lvalues, materialize for rvalues. */
    if (cg_type_is_value_semantics(recv->type)) {
        const FengExpr *recv_obj = (e != NULL && e->kind == FENG_EXPR_CALL &&
                                    e->as.call.callee != NULL &&
                                    e->as.call.callee->kind == FENG_EXPR_MEMBER)
                                       ? e->as.call.callee->as.member.object
                                       : NULL;
        bool recv_is_lvalue =
            recv_obj != NULL &&
            (recv_obj->kind == FENG_EXPR_IDENTIFIER ||
             recv_obj->kind == FENG_EXPR_SELF ||
             recv_obj->kind == FENG_EXPR_MEMBER ||
             recv_obj->kind == FENG_EXPR_INDEX);
        if (!recv_is_lvalue) {
            cg_materialize_to_local(cg, recv, "_vrecv");
        }
    }

    args = arg_count ? calloc(arg_count, sizeof *args) : NULL;
    type_args = method_tp_count ? calloc(method_tp_count, sizeof *type_args) : NULL;
    desc_exprs = method_tp_count ? calloc(method_tp_count, sizeof *desc_exprs) : NULL;
    arg_exprs = emitted_arg_count
                    ? calloc(emitted_arg_count, sizeof *arg_exprs)
                    : NULL;
    if ((arg_count > 0U && args == NULL) ||
        (emitted_arg_count > 0U && arg_exprs == NULL) ||
        (method_tp_count && (type_args == NULL || desc_exprs == NULL))) {
        cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        ok = false;
        goto cleanup;
    }

    if (method_is_variadic) {
        if (!cg_resolve_selected_callable_type_ref(
                cg,
                e,
                sig,
                sig->params[sig->param_count - 1U].type,
                sig->params[sig->param_count - 1U].token,
                &variadic_array_type)) {
            ok = false;
            goto cleanup;
        }
        if (variadic_array_type == NULL ||
            variadic_array_type->kind != CG_TYPE_ARRAY ||
            variadic_array_type->element == NULL) {
            cg_fail(cg,
                    e->token,
                    "CE0136", "codegen: cannot determine concrete variadic parameter type for generic method '%s'",
                    um->feng_name);
            ok = false;
            goto cleanup;
        }
    }

    for (size_t i = 0; i < arg_count; ++i) {
        const CGType *expected_type = NULL;

        if (i < fixed_param_count) {
            expected_type = um->param_types[i];
        } else if (method_is_variadic) {
            expected_type = has_prepacked_variadic_arg
                                ? variadic_array_type
                                : variadic_array_type->element;
        } else {
            expected_type = um->param_types[i];
        }
        if (!cg_emit_expr_for_expected_type(cg,
                                            e->as.call.args[i],
                                            expected_type,
                                            &args[i])) {
            ok = false;
            goto cleanup;
        }
    }

    if (e->as.call.has_explicit_type_args) {
        for (size_t i = 0; i < method_tp_count; ++i) {
            if (!cg_resolve_type(cg, e->as.call.explicit_type_args[i],
                                 &e->token, &type_args[i])) {
                ok = false;
                goto cleanup;
            }
        }
    } else if (cg_call_has_resolved_callable_type_args(e, method_tp_count)) {
        if (!cg_resolve_recorded_callable_type_args(cg,
                                                    e,
                                                    method_tp_count,
                                                    type_args)) {
            ok = false;
            goto cleanup;
        }
    } else {
        for (size_t i = 0; i < method_tp_count; ++i) {
            type_args[i] = cg_infer_method_type_arg(sig, i, args, arg_count);
            if (type_args[i] == NULL) {
                cg_fail(cg, e->token,
                    "CE0137", "codegen: cannot infer type argument %zu for generic method '%s'",
                    i,
                    um->feng_name);
                ok = false;
                goto cleanup;
            }
        }
    }

    if (!cg_build_method_type_param_constraints(cg, ut, sig, e->token,
                                                &constraint_specs)) {
        ok = false;
        goto cleanup;
    }
    for (size_t i = 0; i < method_tp_count; ++i) {
        if (!cg_generic_descriptor_expr(cg, type_args[i], constraint_specs[i],
                                        &e->token, &desc_exprs[i])) {
            ok = false;
            goto cleanup;
        }
    }

    if (wrapper_binds_func_desc) {
        func_desc_expr = NULL;
    } else if (cg->in_generic_fn) {
        func_desc_expr =
            cg_callable_descriptor_expr_for_call(cg, e, e->token);
        if (func_desc_expr == NULL) {
            ok = false;
            goto cleanup;
        }
    } else {
        const FengDecl *owner_decl = ut->generic_origin_decl != NULL
                                         ? ut->generic_origin_decl
                                         : ut->decl;
        const size_t owner_tp_count = owner_decl != NULL
                                          ? owner_decl->as.type_decl.type_param_count
                                          : 0U;
        const size_t combined_count = owner_tp_count + method_tp_count;
        FengTypeParam *combined_params = combined_count > 0U
                                             ? (FengTypeParam *)calloc(
                                                   combined_count,
                                                   sizeof(*combined_params))
                                             : NULL;
        FengTypeRef **combined_args = combined_count > 0U
                                          ? (FengTypeRef **)calloc(
                                                combined_count,
                                                sizeof(*combined_args))
                                          : NULL;
        FengTypeRef **owned_method_refs = method_tp_count > 0U
                                               ? (FengTypeRef **)calloc(
                                                     method_tp_count,
                                                     sizeof(*owned_method_refs))
                                               : NULL;
        const FengDecl *dependency_owner = user_fit != NULL
            ? user_fit->decl
            : owner_decl;
        const FengReifiableDepSet *dep_set = user_fit != NULL
            ? feng_semantic_lookup_member_reifiable_dep_set(
                  cg->analysis, user_fit->decl, um->member)
            : owner_decl != NULL
                  ? feng_semantic_lookup_member_reifiable_dep_set(
                        cg->analysis, owner_decl, um->member)
                  : NULL;

        if ((combined_count > 0U &&
             (combined_params == NULL || combined_args == NULL)) ||
            (method_tp_count > 0U && owned_method_refs == NULL)) {
            free(combined_params);
            free(combined_args);
            free(owned_method_refs);
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
            goto cleanup;
        }
        for (size_t index = 0U; index < owner_tp_count; ++index) {
            combined_params[index] = owner_decl->as.type_decl.type_params[index];
            combined_args[index] = ut->generic_type_args[index];
        }
        for (size_t index = 0U; index < method_tp_count; ++index) {
            combined_params[owner_tp_count + index] = sig->type_params[index];
            owned_method_refs[index] = cg_type_ref_from_cgtype(
                cg, type_args[index], e->token);
            if (owned_method_refs[index] == NULL) {
                ok = false;
                break;
            }
            combined_args[owner_tp_count + index] = owned_method_refs[index];
        }
        if (ok &&
            !cg_emit_closed_callable_fdesc(
                cg,
                dep_set,
                combined_params,
                combined_count,
                combined_args,
                cg_find_decl_owner_program(cg, dependency_owner),
                e->token,
                um->c_name,
                um->feng_name,
                NULL,
                &func_desc_expr)) {
            ok = false;
        }
        for (size_t index = 0U; index < method_tp_count; ++index) {
            cg_type_ref_free(owned_method_refs[index]);
        }
        free(owned_method_refs);
        free(combined_args);
        free(combined_params);
        if (!ok) {
            goto cleanup;
        }
    }

    for (size_t i = 0; i < fixed_param_count; ++i) {
        bool uses_address_abi =
            cg_shared_generic_param_uses_address(um->param_types[i]);

        arg_exprs[i] = cg_shared_callable_argument_for_type_expr_dup(
            cg,
            &args[i],
            um->param_types[i],
            uses_address_abi,
            "_gma");
        if (arg_exprs[i] == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
            goto cleanup;
        }
    }
    if (method_is_variadic) {
        ExprResult variadic_array;
        bool uses_address_abi = cg_shared_generic_param_uses_address(
            um->param_types[fixed_param_count]);

        er_init(&variadic_array);
        if (has_prepacked_variadic_arg) {
            if (arg_count != fixed_param_count + 1U) {
                cg_fail(cg,
                        e->token,
                        "CE0123", "codegen: prepacked variadic argument is not at the first variadic position");
                ok = false;
            } else {
                variadic_array = args[fixed_param_count];
                er_init(&args[fixed_param_count]);
            }
        } else if (!cg_pack_variadic_expr_results(
                       cg,
                       &e->token,
                       args != NULL ? args + fixed_param_count : NULL,
                       arg_count - fixed_param_count,
                       variadic_array_type->element,
                       &variadic_array)) {
            ok = false;
        }
        if (ok) {
            arg_exprs[fixed_param_count] =
                cg_shared_callable_argument_for_type_expr_dup(
                    cg,
                    &variadic_array,
                    um->param_types[fixed_param_count],
                    uses_address_abi,
                    "_gma");
            if (arg_exprs[fixed_param_count] == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
            }
        }
        er_free(&variadic_array);
        if (!ok) {
            goto cleanup;
        }
    } else {
        for (size_t i = fixed_param_count; i < arg_count; ++i) {
            bool uses_address_abi =
                cg_shared_generic_param_uses_address(um->param_types[i]);

            arg_exprs[i] = cg_shared_callable_argument_for_type_expr_dup(
                cg,
                &args[i],
                um->param_types[i],
                uses_address_abi,
                "_gma");
            if (arg_exprs[i] == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
                goto cleanup;
            }
        }
    }

    if (!cg_resolve_selected_callable_return_type(
            cg, e, sig, e->token, &concrete_return)) {
        ok = false;
        goto cleanup;
    }

    if (concrete_return->kind != CG_TYPE_VOID) {
        ret_cname = cg_fresh_temp(cg, "_gmr");
        return_uses_erased_generic_storage =
            concrete_return->kind == CG_TYPE_GENERIC_PARAM;
        return_uses_reified_storage =
            cg_type_uses_reified_storage(cg, concrete_return);
        if (ret_cname == NULL) {
            ok = false;
            goto cleanup;
        }
        if (return_uses_erased_generic_storage) {
            if (!cg_emit_erased_generic_storage_declaration(
                    cg,
                    concrete_return,
                    ret_cname,
                    e->token,
                    &ret_erased_descriptor_name,
                    &ret_erased_size_name)) {
                ok = false;
                goto cleanup;
            }
        } else if (return_uses_reified_storage) {
            if (!cg_emit_reified_storage_declaration(
                    cg,
                    concrete_return,
                    ret_cname,
                    e->token,
                    &ret_reified_descriptor_name,
                    &ret_reified_size_name)) {
                ok = false;
                goto cleanup;
            }
        } else {
            char *cty = cg_ctype_dup(concrete_return);

            if (cty == NULL) {
                ok = false;
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, ret_cname);
            free(cty);
        }
    }

    /* Imported non-generic owners do not have a consumer-local wrapper for a
     * method-generic member. Call their exported shared entry directly. */
    const char *call_name = um->c_name;
    bool calls_open_shared =
        ut->is_generic_instance &&
        ut->generic_context_type_param_count > 0U;
    bool calls_imported_shared =
        cg_program_origin(cg, ut->owner_program) ==
        FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE &&
        !ut->is_generic_instance;
    bool calls_shared = calls_open_shared || calls_imported_shared;
    if (calls_shared) {
        dispatch_name = user_fit != NULL
            ? cg_fit_method_shared_cname(cg, user_fit, um->member)
            : cg_generic_type_method_shared_cname(
                  cg,
                  calls_open_shared ? ut->generic_origin_decl : ut->decl,
                  um->member);
        if (dispatch_name == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
            goto cleanup;
        }
        call_name = dispatch_name;
        if (calls_open_shared) {
            shared_type_desc_expr = cg_rtd_expr_for_type(cg, ut, e->token);
            if (shared_type_desc_expr == NULL) {
                ok = false;
                goto cleanup;
            }
        }
    }

    /* §9.15: ordinary value storage needs its address; address-form storage
     * already denotes the exact receiver and must not be addressed again. */
    buf_append_fmt(cg->cur_body, "    %s(%s%s", call_name,
                   cg_type_is_value_semantics(recv->type) &&
                           !recv->is_storage_address
                       ? "&"
                       : "",
                   recv->c_expr);
    if (calls_shared) {
        const char *type_descriptor = calls_open_shared
            ? shared_type_desc_expr
            : (cg_user_type_is_value_semantics(ut)
                   ? ut->c_aggregate_desc_name
                   : ut->c_desc_name);
        if (type_descriptor == NULL) {
            cg_fail(cg, e->token,
                    "CE0142", "codegen: generic method call is missing its owner descriptor");
            ok = false;
            goto cleanup;
        }
        buf_append_fmt(cg->cur_body,
                       calls_open_shared ? ", %s" : ", &%s",
                       type_descriptor);
    }
    if (func_desc_expr != NULL) {
        buf_append_fmt(cg->cur_body, ", %s", func_desc_expr);
    }
    for (size_t i = 0; i < method_tp_count; ++i) {
        buf_append_fmt(cg->cur_body, ", %s", desc_exprs[i]);
    }
    for (size_t i = 0; i < emitted_arg_count; ++i) {
        buf_append_fmt(cg->cur_body, ", %s", arg_exprs[i]);
    }
    if (ret_cname != NULL) {
        buf_append_fmt(cg->cur_body,
                       (return_uses_erased_generic_storage ||
                        return_uses_reified_storage) ? ", %s" : ", &%s",
                       ret_cname);
    }
    buf_append_cstr(cg->cur_body, ");\n");

    if (ret_cname != NULL) {
        out->c_expr = strdup(ret_cname);
        out->type = concrete_return;
        concrete_return = NULL;
        if (return_uses_erased_generic_storage) {
            if (out->c_expr == NULL ||
                !cg_register_erased_generic_storage_for_cleanup(
                    cg,
                    ret_cname,
                    out->type,
                    ret_erased_descriptor_name,
                    ret_erased_size_name,
                    e->token)) {
                ok = false;
                goto cleanup;
            }
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_erased_generic_storage = true;
            out->erased_generic_descriptor_c_name =
                ret_erased_descriptor_name;
            out->erased_generic_size_c_name = ret_erased_size_name;
            ret_erased_descriptor_name = NULL;
            ret_erased_size_name = NULL;
        } else if (return_uses_reified_storage) {
            if (out->c_expr == NULL ||
                !scope_add(cg->cur_scope,
                           ret_cname,
                           ret_cname,
                           cgtype_clone(out->type),
                           false) ||
                !scope_mark_last_reified_storage(
                    cg->cur_scope,
                    ret_reified_descriptor_name,
                    ret_reified_size_name)) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
                goto cleanup;
            }
            cg_emit_cleanup_push_for_reified_aggregate_storage(
                cg, ret_cname, ret_reified_descriptor_name);
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_reified_storage = true;
            out->reified_descriptor_c_name =
                ret_reified_descriptor_name;
            out->reified_size_c_name = ret_reified_size_name;
            ret_reified_descriptor_name = NULL;
            ret_reified_size_name = NULL;
        } else {
            out->owns_ref = cgtype_is_managed(out->type) ||
                            cgtype_is_aggregate(out->type);
        }
    } else {
        out->c_expr = strdup("((void)0)");
        out->type = concrete_return;
        out->owns_ref = false;
        concrete_return = NULL;
    }
    if (out->c_expr == NULL || out->type == NULL) {
        cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        ok = false;
        goto cleanup;
    }

cleanup:
    if (!ok) er_free(out);
    if (args != NULL) {
        for (size_t i = 0; i < arg_count; ++i) er_free(&args[i]);
    }
    free(args);
    if (type_args != NULL) {
        for (size_t i = 0; i < method_tp_count; ++i) cgtype_free(type_args[i]);
    }
    free(type_args);
    if (desc_exprs != NULL) {
        for (size_t i = 0; i < method_tp_count; ++i) free(desc_exprs[i]);
    }
    free(desc_exprs);
    if (arg_exprs != NULL) {
        for (size_t i = 0; i < emitted_arg_count; ++i) free(arg_exprs[i]);
    }
    free(arg_exprs);
    free(func_desc_expr);
    free(dispatch_name);
    free(shared_type_desc_expr);
    free((void *)constraint_specs);
    cgtype_free(variadic_array_type);
    cgtype_free(concrete_return);
    free(ret_erased_descriptor_name);
    free(ret_erased_size_name);
    free(ret_reified_descriptor_name);
    free(ret_reified_size_name);
    free(ret_cname);
    er_free(recv);
    return ok;
}

static const FengTypeMember *cg_type_decl_method_member_by_name(const FengDecl *decl,
                                                                const char *name,
                                                                size_t len) {
    if (decl == NULL || decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    for (size_t i = 0; i < decl->as.type_decl.member_count; ++i) {
        const FengTypeMember *member = decl->as.type_decl.members[i];
        if (member == NULL || member->kind != FENG_TYPE_MEMBER_METHOD) {
            continue;
        }
        if (member->as.callable.name.length == len &&
            memcmp(member->as.callable.name.data, name, len) == 0) {
            return member;
        }
    }
    return NULL;
}

static bool cg_type_ref_is_direct_type_param(const FengTypeRef *ref,
                                             const FengTypeParam *params,
                                             size_t param_count,
                                             size_t *out_index) {
    if (ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.segment_count != 1U ||
        ref->as.named.type_arg_count != 0U) {
        return false;
    }
    const FengSlice *segment = &ref->as.named.segments[0];
    for (size_t i = 0; i < param_count; ++i) {
        FengSlice name = params[i].name;
        if (segment->length == name.length &&
            memcmp(segment->data, name.data, segment->length) == 0) {
            if (out_index != NULL) *out_index = i;
            return true;
        }
    }
    return false;
}

static bool cg_emit_generic_type_self_method_call(CG *cg,
                                                  const FengExpr *e,
                                                  const FengExpr *member_expr,
                                                  ExprResult *recv,
                                                  ExprResult *out) {
    const FengDecl *owner = cg->generic_type_method_decl;
    const FengResolvedCallable *rc = &e->as.call.resolved_callable;
    const FengTypeMember *member = NULL;
    const FengCallableSignature *sig;
    size_t method_tp_count;
    size_t arg_count;
    bool method_is_variadic;
    size_t fixed_param_count;
    size_t emitted_arg_count;
    bool has_prepacked_variadic_arg;
    char *shared_name = NULL;
    CGType **param_types = NULL;
    ExprResult *args = NULL;
    CGType **type_args = NULL;
    const UserSpec **constraint_specs = NULL;
    char **desc_exprs = NULL;
    char **arg_exprs = NULL;
    CGType *variadic_array_type = NULL;
    CGType *return_type = NULL;
    char *ret_cname = NULL;
    char *ret_erased_descriptor_name = NULL;
    char *ret_erased_size_name = NULL;
    char *ret_reified_descriptor_name = NULL;
    char *ret_reified_size_name = NULL;
    char *func_desc_expr = NULL;
    bool ret_is_erased = false;
    bool ret_uses_reified_storage = false;
    bool ok = true;

    er_init(out);
    if (rc->kind == FENG_RESOLVED_CALLABLE_TYPE_METHOD && rc->member != NULL) {
        member = rc->member;
    } else {
        member = cg_type_decl_method_member_by_name(owner,
                                                   member_expr->as.member.member.data,
                                                   member_expr->as.member.member.length);
    }
    if (member == NULL || member->kind != FENG_TYPE_MEMBER_METHOD) {
        er_free(recv);
        return cg_fail(cg, e->token,
            "CE0139", "codegen: generic type '%.*s' has no method '%.*s'",
            (int)owner->as.type_decl.name.length,
            owner->as.type_decl.name.data,
            (int)member_expr->as.member.member.length,
            member_expr->as.member.member.data);
    }

    sig = &member->as.callable;
    method_tp_count = sig->type_param_count;
    arg_count = e->as.call.arg_count;
    method_is_variadic = sig->param_count > 0U &&
                         sig->params[sig->param_count - 1U].is_variadic;
    fixed_param_count = method_is_variadic
                            ? sig->param_count - 1U
                            : sig->param_count;
    emitted_arg_count = method_is_variadic
                            ? sig->param_count
                            : arg_count;
    has_prepacked_variadic_arg =
        method_is_variadic && arg_count > 0U &&
        e->as.call.args[arg_count - 1U]->is_prepacked_variadic_arg;
    if (e->as.call.has_explicit_type_args &&
        e->as.call.explicit_type_arg_count != method_tp_count) {
        er_free(recv);
        return cg_fail(cg, e->token,
            "CE0135", "codegen: method expects %zu type argument(s), got %zu",
            method_tp_count,
            e->as.call.explicit_type_arg_count);
    }
    if ((method_is_variadic && arg_count < fixed_param_count) ||
        (!method_is_variadic && arg_count != sig->param_count)) {
        er_free(recv);
        return cg_fail(cg, e->token,
            "CE0140", "codegen: semantic argument-count invariant failed for method '%.*s' "
            "(expected %s%zu, got %zu)",
            (int)sig->name.length,
            sig->name.data,
            method_is_variadic ? "at least " : "",
            fixed_param_count,
            arg_count);
    }

    shared_name = cg_generic_type_method_shared_cname(cg, owner, member);
    param_types = sig->param_count ? calloc(sig->param_count, sizeof *param_types) : NULL;
    args = arg_count ? calloc(arg_count, sizeof *args) : NULL;
    type_args = method_tp_count ? calloc(method_tp_count, sizeof *type_args) : NULL;
    desc_exprs = method_tp_count ? calloc(method_tp_count, sizeof *desc_exprs) : NULL;
    arg_exprs = emitted_arg_count
                    ? calloc(emitted_arg_count, sizeof *arg_exprs)
                    : NULL;
    if (shared_name == NULL ||
        (sig->param_count > 0U && param_types == NULL) ||
        (arg_count > 0U && args == NULL) ||
        (emitted_arg_count > 0U && arg_exprs == NULL) ||
        (method_tp_count > 0U && (type_args == NULL || desc_exprs == NULL))) {
        cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        ok = false;
        goto cleanup;
    }

    if (method_is_variadic) {
        if (!cg_resolve_selected_callable_type_ref(
                cg,
                e,
                sig,
                sig->params[sig->param_count - 1U].type,
                sig->params[sig->param_count - 1U].token,
                &variadic_array_type)) {
            ok = false;
            goto cleanup;
        }
        if (variadic_array_type == NULL ||
            variadic_array_type->kind != CG_TYPE_ARRAY ||
            variadic_array_type->element == NULL) {
            cg_fail(cg,
                    e->token,
                    "CE0140", "codegen: cannot determine concrete variadic parameter type for method '%.*s'",
                    (int)sig->name.length,
                    sig->name.data);
            ok = false;
            goto cleanup;
        }
    }

    for (size_t i = 0; i < arg_count; ++i) {
        if (!cg_emit_expr(cg, e->as.call.args[i], &args[i])) {
            ok = false;
            goto cleanup;
        }
    }

    if (e->as.call.has_explicit_type_args) {
        for (size_t i = 0; i < method_tp_count; ++i) {
            if (!cg_resolve_type(cg, e->as.call.explicit_type_args[i],
                                 &e->token, &type_args[i])) {
                ok = false;
                goto cleanup;
            }
        }
    } else if (cg_call_has_resolved_callable_type_args(e, method_tp_count)) {
        if (!cg_resolve_recorded_callable_type_args(cg,
                                                    e,
                                                    method_tp_count,
                                                    type_args)) {
            ok = false;
            goto cleanup;
        }
    } else {
        for (size_t i = 0; i < method_tp_count; ++i) {
            type_args[i] = cg_infer_method_type_arg(sig, i, args, arg_count);
            if (type_args[i] == NULL) {
                cg_fail(cg, e->token,
                    "CE0141", "codegen: cannot infer type argument %zu for generic method '%.*s'",
                    i,
                    (int)sig->name.length,
                    sig->name.data);
                ok = false;
                goto cleanup;
            }
        }
    }

    if (!cg_build_method_type_param_constraints(cg, NULL, sig, e->token,
                                                &constraint_specs)) {
        ok = false;
        goto cleanup;
    }
    for (size_t i = 0; i < method_tp_count; ++i) {
        if (!cg_generic_descriptor_expr(cg, type_args[i], constraint_specs[i],
                                        &e->token, &desc_exprs[i])) {
            ok = false;
            goto cleanup;
        }
    }

    for (size_t i = 0; i < sig->param_count; ++i) {
        size_t method_tp_index = 0U;
        if (cg_type_ref_is_direct_type_param(sig->params[i].type,
                                            sig->type_params,
                                            method_tp_count,
                                            &method_tp_index)) {
            param_types[i] = cgtype_new(CG_TYPE_GENERIC_PARAM);
            if (param_types[i] != NULL) {
                param_types[i]->generic_param_index = owner->as.type_decl.type_param_count + method_tp_index;
            }
        } else if (!cg_resolve_type(cg, sig->params[i].type, &sig->params[i].token,
                                    &param_types[i])) {
            ok = false;
            goto cleanup;
        }
        if (param_types[i] == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
            goto cleanup;
        }
        if (i < fixed_param_count || !method_is_variadic) {
            bool uses_address_abi = false;

            if (!cg_shared_method_param_uses_address_abi(
                    cg, owner, member, i, &uses_address_abi)) {
                ok = false;
                goto cleanup;
            }
            arg_exprs[i] = cg_shared_callable_argument_for_type_expr_dup(
                cg,
                &args[i],
                param_types[i],
                uses_address_abi,
                "_gsm");
            if (arg_exprs[i] == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
                goto cleanup;
            }
        }
    }

    if (method_is_variadic) {
        ExprResult variadic_array;
        bool uses_address_abi = false;

        er_init(&variadic_array);
        if (has_prepacked_variadic_arg) {
            if (arg_count != fixed_param_count + 1U) {
                cg_fail(cg,
                        e->token,
                        "CE0123", "codegen: prepacked variadic argument is not at the first variadic position");
                ok = false;
            } else {
                variadic_array = args[fixed_param_count];
                er_init(&args[fixed_param_count]);
            }
        } else if (!cg_pack_variadic_expr_results(
                       cg,
                       &e->token,
                       args != NULL ? args + fixed_param_count : NULL,
                       arg_count - fixed_param_count,
                       variadic_array_type->element,
                       &variadic_array)) {
            ok = false;
        }
        if (ok && !cg_shared_method_param_uses_address_abi(
                      cg,
                      owner,
                      member,
                      fixed_param_count,
                      &uses_address_abi)) {
            ok = false;
        }
        if (ok) {
            arg_exprs[fixed_param_count] =
                cg_shared_callable_argument_for_type_expr_dup(
                    cg,
                    &variadic_array,
                    param_types[fixed_param_count],
                    uses_address_abi,
                    "_gsm");
            if (arg_exprs[fixed_param_count] == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
            }
        }
        er_free(&variadic_array);
        if (!ok) {
            goto cleanup;
        }
    }

    if (!cg_resolve_selected_callable_return_type(
            cg, e, sig, member->token, &return_type)) {
        ok = false;
        goto cleanup;
    }
    if (return_type->kind != CG_TYPE_VOID) {
        ret_cname = cg_fresh_temp(cg, "_gsm_ret");
        if (ret_cname == NULL) {
            ok = false;
            goto cleanup;
        }
        if (return_type->kind == CG_TYPE_GENERIC_PARAM) {
            if (!cg_emit_erased_generic_storage_declaration(
                    cg,
                    return_type,
                    ret_cname,
                    e->token,
                    &ret_erased_descriptor_name,
                    &ret_erased_size_name)) {
                ok = false;
                goto cleanup;
            }
            ret_is_erased = true;
        } else if (cg_type_uses_reified_storage(cg, return_type)) {
            if (!cg_emit_reified_storage_declaration(
                    cg,
                    return_type,
                    ret_cname,
                    e->token,
                    &ret_reified_descriptor_name,
                    &ret_reified_size_name)) {
                ok = false;
                goto cleanup;
            }
            ret_uses_reified_storage = true;
        } else {
            char *cty = cg_ctype_dup(return_type);
            if (cty == NULL) {
                ok = false;
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, ret_cname);
            free(cty);
        }
    }

    func_desc_expr =
        cg_callable_descriptor_expr_for_call(cg, e, e->token);
    if (func_desc_expr == NULL) {
        ok = false;
        goto cleanup;
    }

    /* §6.7: shared body self-call — recv + _td + callable descriptor +
     * method-level descs;
     * type-level params are obtained from _type_desc inside shared body. */
    /* §9.15: pass the address of ordinary value storage; address-form
     * receiver expressions already denote their exact storage. */
    buf_append_fmt(cg->cur_body, "    %s(%s%s, _td, %s",
                   shared_name,
                   cg_type_is_value_semantics(recv->type) &&
                           !recv->is_storage_address
                       ? "&"
                       : "",
                   recv->c_expr,
                   func_desc_expr);
    for (size_t i = 0; i < method_tp_count; ++i) {
        buf_append_fmt(cg->cur_body, ", %s", desc_exprs[i]);
    }
    for (size_t i = 0; i < emitted_arg_count; ++i) {
        buf_append_fmt(cg->cur_body, ", %s", arg_exprs[i]);
    }
    if (ret_cname != NULL) {
        buf_append_fmt(cg->cur_body,
                       ret_is_erased || ret_uses_reified_storage
                           ? ", %s"
                           : ", &%s",
                       ret_cname);
    }
    buf_append_cstr(cg->cur_body, ");\n");

    if (ret_cname != NULL) {
        out->c_expr = strdup(ret_cname);
        out->type = return_type;
        return_type = NULL;
        if (ret_is_erased) {
            if (out->c_expr == NULL ||
                !cg_register_erased_generic_storage_for_cleanup(
                    cg,
                    ret_cname,
                    out->type,
                    ret_erased_descriptor_name,
                    ret_erased_size_name,
                    e->token)) {
                ok = false;
                goto cleanup;
            }
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_erased_generic_storage = true;
            out->erased_generic_descriptor_c_name =
                ret_erased_descriptor_name;
            out->erased_generic_size_c_name = ret_erased_size_name;
            ret_erased_descriptor_name = NULL;
            ret_erased_size_name = NULL;
        } else if (ret_uses_reified_storage) {
            if (out->c_expr == NULL ||
                !scope_add(cg->cur_scope,
                           ret_cname,
                           ret_cname,
                           cgtype_clone(out->type),
                           false) ||
                !scope_mark_last_reified_storage(
                    cg->cur_scope,
                    ret_reified_descriptor_name,
                    ret_reified_size_name)) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
                goto cleanup;
            }
            cg_emit_cleanup_push_for_reified_aggregate_storage(
                cg, ret_cname, ret_reified_descriptor_name);
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_reified_storage = true;
            out->reified_descriptor_c_name =
                ret_reified_descriptor_name;
            out->reified_size_c_name = ret_reified_size_name;
            ret_reified_descriptor_name = NULL;
            ret_reified_size_name = NULL;
        } else {
            out->owns_ref = ret_is_erased || cgtype_is_managed(out->type) ||
                            cgtype_is_aggregate(out->type);
        }
    } else {
        out->c_expr = strdup("((void)0)");
        out->type = return_type;
        out->owns_ref = false;
        return_type = NULL;
    }
    if (out->c_expr == NULL || out->type == NULL) {
        cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        ok = false;
        goto cleanup;
    }

cleanup:
    if (!ok) {
        er_free(out);
    }
    if (args != NULL) {
        for (size_t i = 0; i < arg_count; ++i) {
            er_free(&args[i]);
        }
    }
    if (type_args != NULL) {
        for (size_t i = 0; i < method_tp_count; ++i) {
            cgtype_free(type_args[i]);
        }
    }
    if (desc_exprs != NULL) {
        for (size_t i = 0; i < method_tp_count; ++i) {
            free(desc_exprs[i]);
        }
    }
    if (param_types != NULL) {
        for (size_t i = 0; i < sig->param_count; ++i) {
            cgtype_free(param_types[i]);
        }
    }
    if (arg_exprs != NULL) {
        for (size_t i = 0; i < emitted_arg_count; ++i) {
            free(arg_exprs[i]);
        }
    }
    free(param_types);
    free(args);
    free(type_args);
    free((void *)constraint_specs);
    free(desc_exprs);
    free(arg_exprs);
    cgtype_free(variadic_array_type);
    cgtype_free(return_type);
    free(ret_erased_descriptor_name);
    free(ret_erased_size_name);
    free(ret_reified_descriptor_name);
    free(ret_reified_size_name);
    free(ret_cname);
    free(func_desc_expr);
    free(shared_name);
    er_free(recv);
    return ok;
}

static void cg_append_call_arg_separator(Buf *buf, bool *has_arg) {
    if (*has_arg) {
        buf_append_cstr(buf, ", ");
    }
    *has_arg = true;
}

static bool cg_append_static_owner_context_args(CG *cg,
                                                Buf *buf,
                                                const UserType *owner_type,
                                                bool *has_arg,
                                                FengToken blame) {
    if (owner_type == NULL || owner_type->generic_context_type_param_count == 0U) {
        return true;
    }
    for (size_t i = 0U; i < owner_type->generic_context_type_param_count; ++i) {
        const char *name = owner_type->generic_context_type_param_names[i];
        const char *desc = cg_generic_param_desc_name_for_name(cg, name);

        if (desc == NULL) {
            return cg_fail(cg, blame,
                           "CE0142", "codegen: generic static method call requires an active generic descriptor context");
        }
        cg_append_call_arg_separator(buf, has_arg);
        buf_append_cstr(buf, desc);
    }
    return true;
}

/* Resolve the parameter surface selected by one static method call. Local
 * concrete methods retain their instantiated surface. Shared type methods
 * recover imported members by declaration ordinal; shared fit methods retain
 * their own member and use the target's owner-parameter domain. */
static bool cg_generic_static_method_param_uses_address_abi(
    CG *cg,
    const UserType *owner_type,
    const UserMethod *method,
    const BuiltinFit *builtin_fit,
    const UserFit *user_fit,
    size_t param_index,
    bool *out_uses_address) {
    const FengDecl *origin = NULL;
    const FengTypeMember *origin_member;
    size_t method_ordinal = (size_t)-1;
    size_t current_ordinal = 0U;

    if (cg == NULL || method == NULL || param_index >= method->param_count ||
        out_uses_address == NULL) {
        return false;
    }
    (void)builtin_fit;
    if (owner_type == NULL ||
        (owner_type->generic_context_type_param_count == 0U &&
         cg_program_origin(cg, owner_type->owner_program) !=
             FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE)) {
        *out_uses_address = cg_shared_generic_param_uses_address(
            method->param_types[param_index]);
        return true;
    }
    if (user_fit != NULL) {
        const FengDecl *target_decl = user_fit->target != NULL
            ? (user_fit->target->generic_origin_decl != NULL
                   ? user_fit->target->generic_origin_decl
                   : user_fit->target->decl)
            : NULL;
        const FengTypeParam *outer_params = NULL;
        size_t outer_param_count = 0U;
        const FengProgram *fit_program =
            cg_find_decl_owner_program(cg, user_fit->decl);
        CGType *declared_type = NULL;

        if (target_decl != NULL && target_decl->kind == FENG_DECL_TYPE) {
            outer_params = target_decl->as.type_decl.type_params;
            outer_param_count = target_decl->as.type_decl.type_param_count;
        }
        if (!cg_resolve_shared_method_declared_param_type(
                cg,
                outer_params,
                outer_param_count,
                fit_program,
                method->member,
                param_index,
                &declared_type)) {
            return false;
        }
        *out_uses_address =
            cg_shared_generic_param_uses_address(declared_type);
        cgtype_free(declared_type);
        return true;
    }
    origin_member = method->member;
    origin = owner_type->generic_origin_decl != NULL
                 ? owner_type->generic_origin_decl
                 : owner_type->decl;
    if (origin == NULL || origin->kind != FENG_DECL_TYPE) {
        return false;
    }
    if (!owner_type->is_generic_instance) {
        return cg_shared_method_param_uses_address_abi(
            cg, origin, origin_member, param_index, out_uses_address);
    }
    for (size_t i = 0U; i < owner_type->static_method_count; ++i) {
        if (&owner_type->static_methods[i] == method) {
            method_ordinal = i;
            break;
        }
    }
    if (method_ordinal == (size_t)-1) {
        return false;
    }

    origin_member = NULL;
    for (size_t i = 0U; i < origin->as.type_decl.member_count; ++i) {
        const FengTypeMember *candidate = origin->as.type_decl.members[i];

        if (candidate == NULL || candidate->kind != FENG_TYPE_MEMBER_METHOD ||
            !candidate->is_static) {
            continue;
        }
        if (current_ordinal == method_ordinal) {
            origin_member = candidate;
            break;
        }
        current_ordinal++;
    }
    if (origin_member == NULL ||
        param_index >= origin_member->as.callable.param_count) {
        return false;
    }

    return cg_shared_method_param_uses_address_abi(
        cg, origin, origin_member, param_index, out_uses_address);
}

/* Return whether a static method call must enter the exported shared body
 * instead of a local thin wrapper. This is the same choice used by direct
 * generic static calls: imported generic methods and imported generic owner
 * instances expose only the shared package symbol, while a local closed
 * instance keeps its existing thin wrapper. */
static bool cg_static_method_uses_shared_dispatch(
    const CG *cg,
    const UserType *owner_type,
    const UserMethod *method) {
    const FengCallableSignature *signature =
        method != NULL && method->member != NULL
            ? &method->member->as.callable
            : NULL;
    bool owner_is_imported;

    if (cg == NULL || owner_type == NULL || signature == NULL) {
        return false;
    }
    owner_is_imported =
        cg_program_origin(cg, owner_type->owner_program) ==
        FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE;
    return owner_type->generic_context_type_param_count > 0U ||
           (owner_is_imported &&
            (owner_type->is_generic_instance ||
             signature->type_param_count > 0U));
}

static bool cg_emit_generic_static_method_call(CG *cg,
                                               const FengExpr *e,
                                               const UserType *owner_type,
                                               const UserMethod *um,
                                               const BuiltinFit *builtin_fit,
                                               const UserFit *user_fit,
                                               ExprResult *out) {
    const FengCallableSignature *sig = um != NULL && um->member != NULL
                                           ? &um->member->as.callable
                                           : NULL;
    size_t method_tp_count = sig != NULL ? sig->type_param_count : 0U;
    size_t arg_count = e->as.call.arg_count;
    bool method_is_variadic = um != NULL && um->is_variadic;
    size_t fixed_param_count = method_is_variadic ? um->param_count - 1U : um->param_count;
    ExprResult *args = NULL;
    CGType **type_args = NULL;
    const UserSpec **constraint_specs = NULL;
    char **desc_exprs = NULL;
    char **arg_exprs = NULL;
    size_t emitted_arg_count = 0U;
    CGType *concrete_return = NULL;
    char *ret_cname = NULL;
    char *ret_erased_descriptor_name = NULL;
    char *ret_erased_size_name = NULL;
    char *ret_reified_descriptor_name = NULL;
    char *ret_reified_size_name = NULL;
    char *dispatch_name = NULL;
    char *func_desc_expr = NULL;
    bool ret_is_erased = false;
    bool ret_uses_reified_storage = false;
    bool returns_directly = false;
    bool method_is_imported = owner_type != NULL &&
        cg_program_origin(cg, owner_type->owner_program) ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE;
    bool wrapper_binds_func_desc =
        !method_is_imported &&
        cg_closed_generic_fit_wrapper_binds_function_descriptor(user_fit,
                                                                owner_type,
                                                                um != NULL
                                                                    ? um->member
                                                                    : NULL);
    bool ok = true;

    er_init(out);
    if (sig == NULL ||
        (method_tp_count == 0U &&
         (owner_type == NULL || !owner_type->is_generic_instance))) {
        return cg_fail(cg, e->token,
                       "CE0143", "codegen: internal: generic static method call is missing a generic owner or method type parameters");
    }
    if (builtin_fit != NULL && builtin_fit->target_type_param_count > 0U) {
        return cg_fail(cg,
                       e->token,
                       "CE0144", "codegen: generic builtin static fit methods are not supported yet");
    }
    returns_directly = builtin_fit != NULL &&
        !cg_builtin_fit_return_uses_out(builtin_fit, um);
    if (e->as.call.has_explicit_type_args &&
        e->as.call.explicit_type_arg_count != method_tp_count) {
        return cg_fail(cg, e->token,
                       "CE0145", "codegen: static method expects %zu type argument(s), got %zu",
                       method_tp_count,
                       e->as.call.explicit_type_arg_count);
    }
    /* Argument-count validation: variadic methods accept >= fixed_param_count args. */
    if (method_is_variadic) {
        if (arg_count < fixed_param_count) {
            return cg_fail(cg, e->token,
                           "CE0146", "codegen: too few arguments for variadic generic static method '%s' "
                           "(need at least %zu, got %zu)",
                           um->feng_name, fixed_param_count, arg_count);
        }
    } else {
        if (arg_count != um->param_count) {
            return cg_fail(cg, e->token,
                           "CE0147", "codegen: wrong argument count for generic static method '%s' "
                           "(expected %zu, got %zu)",
                           um->feng_name, um->param_count, arg_count);
        }
    }

    /* For variadic methods, we emit fixed_param_count args + 1 packed array arg. */
    emitted_arg_count = method_is_variadic ? um->param_count : arg_count;
    args = arg_count ? calloc(arg_count, sizeof(*args)) : NULL;
    type_args = method_tp_count ? calloc(method_tp_count, sizeof(*type_args)) : NULL;
    desc_exprs = method_tp_count ? calloc(method_tp_count, sizeof(*desc_exprs)) : NULL;
    arg_exprs = emitted_arg_count ? calloc(emitted_arg_count, sizeof(*arg_exprs)) : NULL;
    if ((arg_count > 0U && args == NULL) ||
        (emitted_arg_count > 0U && arg_exprs == NULL) ||
        (method_tp_count > 0U && (type_args == NULL || desc_exprs == NULL))) {
        cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        ok = false;
        goto cleanup;
    }

    /* Emit fixed-position arguments. */
    for (size_t i = 0U; i < fixed_param_count; ++i) {
        if (!cg_emit_expr_for_expected_type(cg,
                                            e->as.call.args[i],
                                            um->param_types[i],
                                            &args[i])) {
            ok = false;
            goto cleanup;
        }
    }

    /* For variadic methods, also emit the variadic arguments (untyped, for inference). */
    if (method_is_variadic) {
        const CGType *variadic_elem_type = um->param_types[um->param_count - 1U] != NULL
            ? um->param_types[um->param_count - 1U]->element
            : NULL;
        bool has_prepacked_variadic_arg =
            arg_count > 0U &&
            e->as.call.args[arg_count - 1U]->is_prepacked_variadic_arg;
        for (size_t i = fixed_param_count; i < arg_count; ++i) {
            if (!cg_emit_expr_for_expected_type(cg,
                                                e->as.call.args[i],
                                                has_prepacked_variadic_arg
                                                    ? um->param_types[um->param_count - 1U]
                                                    : variadic_elem_type,
                                                &args[i])) {
                ok = false;
                goto cleanup;
            }
        }
    } else {
        for (size_t i = fixed_param_count; i < arg_count; ++i) {
            if (!cg_emit_expr_for_expected_type(cg,
                                                e->as.call.args[i],
                                                um->param_types[i],
                                                &args[i])) {
                ok = false;
                goto cleanup;
            }
        }
    }

    /* Infer or resolve type arguments. */
    if (e->as.call.has_explicit_type_args) {
        for (size_t i = 0U; i < method_tp_count; ++i) {
            if (!cg_resolve_type(cg, e->as.call.explicit_type_args[i],
                                 &e->token, &type_args[i])) {
                ok = false;
                goto cleanup;
            }
        }
    } else if (cg_call_has_resolved_callable_type_args(e, method_tp_count)) {
        if (!cg_resolve_recorded_callable_type_args(cg,
                                                    e,
                                                    method_tp_count,
                                                    type_args)) {
            ok = false;
            goto cleanup;
        }
    } else {
        for (size_t i = 0U; i < method_tp_count; ++i) {
            type_args[i] = cg_infer_method_type_arg(sig, i, args, arg_count);
            if (type_args[i] == NULL) {
                cg_fail(cg, e->token,
                        "CE0148", "codegen: cannot infer type argument %zu for generic static method '%s'",
                        i,
                        um->feng_name);
                ok = false;
                goto cleanup;
            }
        }
    }

    if (!cg_build_method_type_param_constraints(cg, owner_type, sig, e->token,
                                                &constraint_specs)) {
        ok = false;
        goto cleanup;
    }
    for (size_t i = 0U; i < method_tp_count; ++i) {
        if (!cg_generic_descriptor_expr(cg, type_args[i], constraint_specs[i],
                                        &e->token, &desc_exprs[i])) {
            ok = false;
            goto cleanup;
        }
    }

    if (wrapper_binds_func_desc) {
        func_desc_expr = NULL;
    } else if (cg->in_generic_fn) {
        func_desc_expr =
            cg_callable_descriptor_expr_for_call(cg, e, e->token);
        if (func_desc_expr == NULL) {
            ok = false;
            goto cleanup;
        }
    } else {
        const FengDecl *owner_decl = owner_type != NULL
            ? (owner_type->generic_origin_decl != NULL
                   ? owner_type->generic_origin_decl
                   : owner_type->decl)
            : NULL;
        const size_t owner_tp_count = owner_decl != NULL
                                          ? owner_decl->as.type_decl.type_param_count
                                          : 0U;
        const size_t combined_count = owner_tp_count + method_tp_count;
        FengTypeParam *combined_params = combined_count > 0U
                                             ? (FengTypeParam *)calloc(
                                                   combined_count,
                                                   sizeof(*combined_params))
                                             : NULL;
        FengTypeRef **combined_args = combined_count > 0U
                                          ? (FengTypeRef **)calloc(
                                                combined_count,
                                                sizeof(*combined_args))
                                          : NULL;
        FengTypeRef **owned_method_refs = method_tp_count > 0U
                                               ? (FengTypeRef **)calloc(
                                                     method_tp_count,
                                                     sizeof(*owned_method_refs))
                                               : NULL;
        const FengDecl *dependency_owner = user_fit != NULL
            ? user_fit->decl
            : owner_decl;
        const FengReifiableDepSet *dep_set = user_fit != NULL
            ? feng_semantic_lookup_member_reifiable_dep_set(
                  cg->analysis, user_fit->decl, um->member)
            : owner_decl != NULL
                  ? feng_semantic_lookup_member_reifiable_dep_set(
                        cg->analysis, owner_decl, um->member)
                  : NULL;

        if ((combined_count > 0U &&
             (combined_params == NULL || combined_args == NULL)) ||
            (method_tp_count > 0U && owned_method_refs == NULL)) {
            free(combined_params);
            free(combined_args);
            free(owned_method_refs);
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
            goto cleanup;
        }
        for (size_t index = 0U; index < owner_tp_count; ++index) {
            combined_params[index] = owner_decl->as.type_decl.type_params[index];
            combined_args[index] = owner_type->generic_type_args[index];
        }
        for (size_t index = 0U; index < method_tp_count; ++index) {
            combined_params[owner_tp_count + index] = sig->type_params[index];
            owned_method_refs[index] = cg_type_ref_from_cgtype(
                cg, type_args[index], e->token);
            if (owned_method_refs[index] == NULL) {
                ok = false;
                break;
            }
            combined_args[owner_tp_count + index] = owned_method_refs[index];
        }
        if (ok &&
            !cg_emit_closed_callable_fdesc(
                cg,
                dep_set,
                combined_params,
                combined_count,
                combined_args,
                cg_find_decl_owner_program(cg, dependency_owner),
                e->token,
                um->c_name,
                um->feng_name,
                NULL,
                &func_desc_expr)) {
            ok = false;
        }
        for (size_t index = 0U; index < method_tp_count; ++index) {
            cg_type_ref_free(owned_method_refs[index]);
        }
        free(owned_method_refs);
        free(combined_args);
        free(combined_params);
        if (!ok) {
            goto cleanup;
        }
    }

    /* Build arg_exprs for fixed arguments. */
    for (size_t i = 0U; i < fixed_param_count; ++i) {
        bool uses_address_abi = false;

        if (!cg_generic_static_method_param_uses_address_abi(
                cg,
                owner_type,
                um,
                builtin_fit,
                user_fit,
                i,
                &uses_address_abi)) {
            if (!cg->failed) {
                cg_fail(cg,
                        e->token,
                        "IE0002",
                        "codegen: generic static method parameter ABI could not be resolved");
            }
            ok = false;
            goto cleanup;
        }
        arg_exprs[i] = cg_shared_callable_argument_for_type_expr_dup(
            cg,
            &args[i],
            um->param_types[i],
            uses_address_abi,
            "_gsma");
        if (arg_exprs[i] == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
            goto cleanup;
        }
    }

    /* Pack variadic arguments into an array for the last parameter slot. */
    if (method_is_variadic) {
        ExprResult varr;
        bool has_prepacked_variadic_arg =
            arg_count > 0U &&
            e->as.call.args[arg_count - 1U]->is_prepacked_variadic_arg;

        if (has_prepacked_variadic_arg) {
            if (arg_count != fixed_param_count + 1U) {
                cg_fail(cg,
                        e->token,
                        "CE0123", "codegen: prepacked variadic argument is not at the first variadic position");
                ok = false;
                goto cleanup;
            }
            varr = args[fixed_param_count];
            er_init(&args[fixed_param_count]);
        } else if (!cg_pack_variadic_args(
                       cg,
                       &e->token,
                       e->as.call.args != NULL
                           ? e->as.call.args + fixed_param_count
                           : NULL,
                       arg_count - fixed_param_count,
                       um->param_types[um->param_count - 1U]->element,
                       &varr)) {
            ok = false;
            goto cleanup;
        }
        if (cgtype_is_managed(varr.type) && varr.owns_ref) {
            cg_materialize_to_local(cg, &varr, "_gsma");
        }
        arg_exprs[fixed_param_count] = strdup(varr.c_expr);
        er_free(&varr);
        if (arg_exprs[fixed_param_count] == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
            goto cleanup;
        }
    } else {
        /* Non-variadic: build remaining arg_exprs (generic param handling). */
        for (size_t i = fixed_param_count; i < arg_count; ++i) {
            bool uses_address_abi = false;

            if (!cg_generic_static_method_param_uses_address_abi(
                    cg,
                    owner_type,
                    um,
                    builtin_fit,
                    user_fit,
                    i,
                    &uses_address_abi)) {
                if (!cg->failed) {
                    cg_fail(cg,
                            e->token,
                            "IE0002",
                            "codegen: generic static method parameter ABI could not be resolved");
                }
                ok = false;
                goto cleanup;
            }
            arg_exprs[i] = cg_shared_callable_argument_for_type_expr_dup(
                cg,
                &args[i],
                um->param_types[i],
                uses_address_abi,
                "_gsma");
            if (arg_exprs[i] == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
                goto cleanup;
            }
        }
    }

    if (builtin_fit != NULL) {
        concrete_return = um->return_type == NULL
                              ? cgtype_new(CG_TYPE_VOID)
                              : cg_instantiate_builtin_fit_return_type(cg,
                                                                       builtin_fit,
                                                                       um->return_type,
                                                                       NULL,
                                                                       e->token);
    } else if (!cg_resolve_selected_callable_return_type(
                   cg, e, sig, e->token, &concrete_return)) {
        ok = false;
        goto cleanup;
    }
    if (concrete_return == NULL) {
        cg_fail(cg, e->token, "CE0149", "codegen: cannot determine generic static method return type");
        ok = false;
        goto cleanup;
    }

    if (concrete_return->kind != CG_TYPE_VOID) {
        ret_cname = cg_fresh_temp(cg, "_gsmr");
        if (ret_cname == NULL) {
            ok = false;
            goto cleanup;
        }
        if (concrete_return->kind == CG_TYPE_GENERIC_PARAM) {
            if (!cg_emit_erased_generic_storage_declaration(
                    cg,
                    concrete_return,
                    ret_cname,
                    e->token,
                    &ret_erased_descriptor_name,
                    &ret_erased_size_name)) {
                ok = false;
                goto cleanup;
            }
            ret_is_erased = true;
        } else if (cg_type_uses_reified_storage(cg, concrete_return)) {
            if (!cg_emit_reified_storage_declaration(
                    cg,
                    concrete_return,
                    ret_cname,
                    e->token,
                    &ret_reified_descriptor_name,
                    &ret_reified_size_name)) {
                ok = false;
                goto cleanup;
            }
            ret_uses_reified_storage = true;
        } else {
            char *cty = cg_ctype_dup(concrete_return);

            if (cty == NULL) {
                ok = false;
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, ret_cname);
            free(cty);
        }
    }

    {
        /* For imported generic static methods, call the exported dispatch
         * function (FengGenericMethod__...) instead of the file-local
         * static function.  This applies uniformly to both generic type
         * instances and non-generic types with method-level type params. */
        bool uses_shared_dispatch =
            cg_static_method_uses_shared_dispatch(cg, owner_type, um);
        const FengDecl *method_origin_decl = owner_type != NULL
            ? (owner_type->generic_origin_decl != NULL
                   ? owner_type->generic_origin_decl
                   : owner_type->decl)
            : NULL;
        const char *call_name = um->c_name;
        if (uses_shared_dispatch && method_origin_decl != NULL) {
            dispatch_name = user_fit != NULL
                ? cg_fit_method_shared_cname(cg, user_fit, um->member)
                : cg_generic_type_method_shared_cname(
                      cg, method_origin_decl, um->member);
            if (dispatch_name == NULL) {
                ok = false;
                goto cleanup;
            }
            call_name = dispatch_name;
        }

        bool has_arg = false;
        char *owner_descriptor_expr = NULL;

        if (returns_directly && ret_cname != NULL) {
            buf_append_fmt(cg->cur_body,
                           "    %s = %s(",
                           ret_cname,
                           call_name);
        } else {
            buf_append_fmt(cg->cur_body, "    %s(", call_name);
        }
        if (owner_type != NULL &&
            owner_type->generic_context_type_param_count > 0U) {
            owner_descriptor_expr = cg_rtd_expr_for_type(
                cg, owner_type, e->token);
            if (owner_descriptor_expr == NULL) {
                ok = false;
                goto cleanup;
            }
            buf_append_cstr(cg->cur_body, owner_descriptor_expr);
            has_arg = true;
        } else if (method_is_imported && owner_type != NULL) {
            const char *owner_descriptor = cg_user_type_is_value(owner_type)
                                               ? owner_type->c_aggregate_desc_name
                                               : owner_type->c_desc_name;

            if (owner_descriptor == NULL) {
                cg_fail(cg,
                        e->token,
                        "CE0142", "codegen: generic static method call is missing its owner descriptor");
                ok = false;
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body, "&%s", owner_descriptor);
            has_arg = true;
        }
        free(owner_descriptor_expr);
        if (func_desc_expr != NULL) {
            cg_append_call_arg_separator(cg->cur_body, &has_arg);
            buf_append_cstr(cg->cur_body, func_desc_expr);
        }
        for (size_t i = 0U; i < method_tp_count; ++i) {
            cg_append_call_arg_separator(cg->cur_body, &has_arg);
            buf_append_cstr(cg->cur_body, desc_exprs[i]);
        }
        for (size_t i = 0U; i < emitted_arg_count; ++i) {
            cg_append_call_arg_separator(cg->cur_body, &has_arg);
            buf_append_cstr(cg->cur_body, arg_exprs[i]);
        }
        if (ret_cname != NULL && !returns_directly) {
            cg_append_call_arg_separator(cg->cur_body, &has_arg);
            buf_append_fmt(cg->cur_body,
                           ret_is_erased || ret_uses_reified_storage
                               ? "%s"
                               : "&%s",
                           ret_cname);
        }
        buf_append_cstr(cg->cur_body, ");\n");
    }

    if (ret_cname != NULL) {
        out->c_expr = strdup(ret_cname);
        out->type = concrete_return;
        concrete_return = NULL;
        if (ret_is_erased) {
            if (out->c_expr == NULL ||
                !cg_register_erased_generic_storage_for_cleanup(
                    cg,
                    ret_cname,
                    out->type,
                    ret_erased_descriptor_name,
                    ret_erased_size_name,
                    e->token)) {
                ok = false;
                goto cleanup;
            }
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_erased_generic_storage = true;
            out->erased_generic_descriptor_c_name =
                ret_erased_descriptor_name;
            out->erased_generic_size_c_name = ret_erased_size_name;
            ret_erased_descriptor_name = NULL;
            ret_erased_size_name = NULL;
        } else if (ret_uses_reified_storage) {
            if (out->c_expr == NULL ||
                !scope_add(cg->cur_scope,
                           ret_cname,
                           ret_cname,
                           cgtype_clone(out->type),
                           false) ||
                !scope_mark_last_reified_storage(
                    cg->cur_scope,
                    ret_reified_descriptor_name,
                    ret_reified_size_name)) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
                goto cleanup;
            }
            cg_emit_cleanup_push_for_reified_aggregate_storage(
                cg, ret_cname, ret_reified_descriptor_name);
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_reified_storage = true;
            out->reified_descriptor_c_name =
                ret_reified_descriptor_name;
            out->reified_size_c_name = ret_reified_size_name;
            ret_reified_descriptor_name = NULL;
            ret_reified_size_name = NULL;
        } else {
            out->owns_ref = ret_is_erased ||
                            cgtype_is_managed(out->type) ||
                            cgtype_is_aggregate(out->type);
        }
    } else {
        out->c_expr = strdup("((void)0)");
        out->type = concrete_return;
        out->owns_ref = false;
        concrete_return = NULL;
    }
    if (out->c_expr == NULL || out->type == NULL) {
        cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        ok = false;
        goto cleanup;
    }

cleanup:
    if (!ok) er_free(out);
    if (args != NULL) {
        for (size_t i = 0U; i < arg_count; ++i) er_free(&args[i]);
    }
    free(args);
    if (type_args != NULL) {
        for (size_t i = 0U; i < method_tp_count; ++i) cgtype_free(type_args[i]);
    }
    free(type_args);
    if (desc_exprs != NULL) {
        for (size_t i = 0U; i < method_tp_count; ++i) free(desc_exprs[i]);
    }
    free(desc_exprs);
    if (arg_exprs != NULL) {
        for (size_t i = 0U; i < emitted_arg_count; ++i) free(arg_exprs[i]);
    }
    free(arg_exprs);
    free((void *)constraint_specs);
    cgtype_free(concrete_return);
    free(ret_erased_descriptor_name);
    free(ret_erased_size_name);
    free(ret_reified_descriptor_name);
    free(ret_reified_size_name);
    free(ret_cname);
    free(dispatch_name);
    free(func_desc_expr);
    return ok;
}

static bool cg_emit_static_method_call_with_user_method(CG *cg,
                                                        const FengExpr *e,
                                                        const UserType *owner_type,
                                                        const UserMethod *um,
                                                        const BuiltinFit *builtin_fit,
                                                        const UserFit *user_fit,
                                                        ExprResult *out) {
    Buf args_buf;
    bool has_arg = false;

    er_init(out);
    if (um == NULL) {
        return cg_fail(cg, e->token, "CE0150", "codegen: resolved static method was not registered");
    }
    if (um->member != NULL &&
        (um->member->as.callable.type_param_count > 0U ||
         (owner_type != NULL && owner_type->is_generic_instance &&
          (owner_type->generic_context_type_param_count > 0U ||
           cg_program_origin(cg, owner_type->owner_program) ==
               FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE)))) {
        return cg_emit_generic_static_method_call(cg,
                                                  e,
                                                  owner_type,
                                                  um,
                                                  builtin_fit,
                                                  user_fit,
                                                  out);
    }
    if (builtin_fit != NULL && builtin_fit->target_type_param_count > 0U) {
        return cg_fail(cg,
                       e->token,
                       "CE0144", "codegen: generic builtin static fit methods are not supported yet");
    }
    if (e->as.call.arg_count != um->param_count) {
        if (!um->is_variadic) {
            return cg_fail(cg,
                           e->token,
                           "CE0151", "codegen: wrong argument count for static method '%s' (expected %zu, got %zu)",
                           um->feng_name,
                           um->param_count,
                           e->as.call.arg_count);
        }
        size_t fixed_count = um->param_count - 1U;
        if (e->as.call.arg_count < fixed_count) {
            return cg_fail(cg,
                           e->token,
                           "CE0152", "codegen: too few arguments for variadic static method '%s' (need at least %zu, got %zu)",
                           um->feng_name,
                           fixed_count,
                           e->as.call.arg_count);
        }
    }

    buf_init(&args_buf);
    if (!cg_append_static_owner_context_args(cg,
                                             &args_buf,
                                             owner_type,
                                             &has_arg,
                                             e->token)) {
        buf_free(&args_buf);
        return false;
    }
    size_t fixed_arg_limit = um->is_variadic ? um->param_count - 1U : e->as.call.arg_count;
    for (size_t i = 0; i < fixed_arg_limit; i++) {
        ExprResult arg;
        char *arg_expr = NULL;

        if (!cg_emit_expr_for_expected_type(cg,
                                            e->as.call.args[i],
                                            um->param_types[i],
                                            &arg)) {
            buf_free(&args_buf);
            return false;
        }
        if (um->param_types[i] != NULL &&
            um->param_types[i]->kind == CG_TYPE_GENERIC_PARAM) {
            char *tmp = cg_fresh_temp(cg, "_sma");

            if (tmp == NULL) {
                er_free(&arg);
                buf_free(&args_buf);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            if (arg.type != NULL && arg.type->kind == CG_TYPE_GENERIC_PARAM) {
                buf_append_fmt(cg->cur_body, "    const void *%s = %s;\n", tmp, arg.c_expr);
                arg_expr = strdup(tmp);
            } else {
                char *cty = cg_ctype_dup(arg.type);

                if (cty == NULL) {
                    free(tmp);
                    er_free(&arg);
                    buf_free(&args_buf);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, arg.c_expr);
                if ((cgtype_is_managed(arg.type) || cgtype_is_aggregate(arg.type)) &&
                    arg.owns_ref) {
                    if (!cg_register_local_for_cleanup(cg, tmp, arg.type, e->token)) {
                        free(cty);
                        free(tmp);
                        er_free(&arg);
                        buf_free(&args_buf);
                        return false;
                    }
                    arg.owns_ref = false;
                }
                Buf addr;
                buf_init(&addr);
                buf_append_fmt(&addr, "&%s", tmp);
                arg_expr = addr.data;
                free(cty);
            }
            free(tmp);
        } else {
            if (cgtype_is_managed(arg.type) && arg.owns_ref) {
                cg_materialize_to_local(cg, &arg, "_t");
            } else if (cgtype_is_aggregate(arg.type) && arg.owns_ref) {
                cg_materialize_to_local(cg, &arg, "_t");
            }
            arg_expr = strdup(arg.c_expr);
        }
        if (arg_expr == NULL) {
            er_free(&arg);
            buf_free(&args_buf);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        cg_append_call_arg_separator(&args_buf, &has_arg);
        buf_append_cstr(&args_buf, arg_expr);
        free(arg_expr);
        er_free(&arg);
    }
    if (um->is_variadic) {
        const CGType *array_type = um->param_types[um->param_count - 1U];
        ExprResult varr;

        if (!cg_emit_variadic_array_arg(
                cg, e, fixed_arg_limit, array_type, &varr)) {
            buf_free(&args_buf);
            return false;
        }
        if (cgtype_is_managed(varr.type) && varr.owns_ref) {
            cg_materialize_to_local(cg, &varr, "_t");
        }
        cg_append_call_arg_separator(&args_buf, &has_arg);
        buf_append_cstr(&args_buf, varr.c_expr);
        er_free(&varr);
    }

    {
        Buf call;

        buf_init(&call);
        if (builtin_fit != NULL) {
            buf_append_fmt(&call,
                "%s(&(const FengFunctionDescriptor){.name = \"%s\"}",
                um->c_name, um->feng_name);
            if (args_buf.data != NULL && args_buf.length > 0U) {
                buf_append_cstr(&call, ", ");
                buf_append_cstr(&call, args_buf.data);
            }
            buf_append_cstr(&call, ")");
        } else {
            buf_append_fmt(&call, "%s(%s)",
                           um->c_name,
                           args_buf.data != NULL ? args_buf.data : "");
        }
        buf_free(&args_buf);
        out->c_expr = call.data;
    }
    out->type = builtin_fit != NULL
                    ? cg_instantiate_builtin_fit_return_type(cg,
                                                             builtin_fit,
                                                             um->return_type,
                                                             NULL,
                                                             e->token)
                    : cgtype_clone(um->return_type);
    if (out->type == NULL) {
        er_free(out);
        return cg_fail(cg, e->token, "CE0153", "codegen: failed to determine static method return type");
    }
    out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
    return out->c_expr != NULL && out->type != NULL;
}

static bool cg_emit_call(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    const FengResolvedCallable *rc = &e->as.call.resolved_callable;
    /* Method call: callee is a member access. */
    if (e->as.call.callee->kind == FENG_EXPR_MEMBER) {
        const FengExpr *ma = e->as.call.callee;
        const FengDecl *imported_binding_decl =
            cg_resolve_imported_module_binding_decl(cg, ma);

        if (rc->kind == FENG_RESOLVED_CALLABLE_FUNCTION && rc->function_decl != NULL) {
            return cg_emit_registered_call(cg,
                                           e,
                                           cg_find_free_fn_by_decl(cg, rc->function_decl),
                                           NULL,
                                           out);
        }

        if (imported_binding_decl != NULL) {
            ExprResult callee;

            er_init(&callee);
            if (!cg_emit_imported_binding_expr(cg, imported_binding_decl, &callee)) {
                return false;
            }
            if (callee.type == NULL || callee.type->kind != CG_TYPE_CALLABLE ||
                callee.type->user_spec == NULL) {
                er_free(&callee);
                return cg_fail(cg, e->token,
                    "CE0154", "codegen: imported binding '%.*s' is not callable",
                    (int)ma->as.member.member.length,
                    ma->as.member.member.data);
            }
            return cg_emit_callable_value_call(cg, e, &callee,
                                               callee.type->user_spec, out);
        }

        if (rc->kind == FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD) {
            const UserType *ut = cg_find_user_type_by_expr_path(cg, ma->as.member.object);
            const UserMethod *um = NULL;

            if (ut == NULL && rc->owner_type_decl != NULL) {
                ut = cg_find_user_type_by_decl(cg, rc->owner_type_decl);
            }

            if (ut != NULL && rc->member != NULL) {
                um = cg_user_type_static_method_by_member(ut, rc->member);
            }
            if (um == NULL && ut != NULL) {
                um = cg_user_type_static_method(ut,
                                                ma->as.member.member.data,
                                                ma->as.member.member.length);
            }
            return cg_emit_static_method_call_with_user_method(
                cg, e, ut, um, NULL, NULL, out);
        }

        if (rc->kind == FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD) {
            const BuiltinFit *bf = rc->fit_decl != NULL
                                       ? cg_find_builtin_fit_by_decl(cg, rc->fit_decl)
                                       : NULL;
            const UserMethod *um = NULL;

            if (bf != NULL) {
                if (rc->member != NULL) {
                    um = cg_builtin_fit_method_by_member(bf, rc->member);
                }
                if (um == NULL) {
                    um = cg_builtin_fit_method(bf,
                                               ma->as.member.member.data,
                                               ma->as.member.member.length);
                }
                return cg_emit_static_method_call_with_user_method(
                    cg, e, NULL, um, bf, NULL, out);
            }
            {
                const UserType *ut = cg_find_user_type_by_expr_path(cg, ma->as.member.object);
                const UserFit *uf = ut != NULL && rc->fit_decl != NULL
                                        ? cg_find_user_fit_by_decl_and_target(cg, rc->fit_decl, ut)
                                        : NULL;

                if (ut == NULL && rc->owner_type_decl != NULL) {
                    ut = cg_find_user_type_by_decl(cg, rc->owner_type_decl);
                    uf = ut != NULL && rc->fit_decl != NULL
                             ? cg_find_user_fit_by_decl_and_target(cg, rc->fit_decl, ut)
                             : NULL;
                }

                if (uf != NULL && rc->member != NULL) {
                    um = cg_user_fit_method_by_member(uf, rc->member);
                }
                if (um == NULL && uf != NULL) {
                    um = cg_user_fit_method(uf,
                                            ma->as.member.member.data,
                                            ma->as.member.member.length);
                }
                return cg_emit_static_method_call_with_user_method(
                    cg, e, ut, um, NULL, uf, out);
            }
        }

        ExprResult recv;
        if (!cg_emit_expr(cg, ma->as.member.object, &recv)) return false;
        if (rc->kind == FENG_RESOLVED_CALLABLE_NONE &&
            (recv.type->kind == CG_TYPE_GENERIC_PARAM ||
             (recv.type->kind == CG_TYPE_SPEC &&
              recv.type->user_spec != NULL))) {
            const UserSpec *field_spec = NULL;
            const UserSpecMember *field = NULL;
            const char *generic_descriptor = NULL;

            if (recv.type->kind == CG_TYPE_GENERIC_PARAM) {
                size_t generic_index = recv.type->generic_param_index;

                field_spec = cg_generic_param_constraint_spec(
                    cg, generic_index);
                generic_descriptor = cg_generic_param_desc_name(
                    cg, generic_index);
            } else {
                field_spec = recv.type->user_spec;
            }
            if (field_spec != NULL) {
                field = cg_user_spec_field_member_for_access(
                    cg,
                    field_spec,
                    ma,
                    /*fallback_static=*/false);
            }
            if (field != NULL && field->kind == USM_KIND_FIELD &&
                field->type != NULL &&
                field->type->kind == CG_TYPE_CALLABLE &&
                field->type->user_spec != NULL) {
                ExprResult callee;
                const UserSpec *callable_spec = field->type->user_spec;

                if (!cg_emit_spec_field_borrow(cg,
                                               &recv,
                                               field_spec,
                                               field,
                                               generic_descriptor,
                                               e->token,
                                               &callee)) {
                    return false;
                }
                return cg_emit_callable_value_call(cg,
                                                   e,
                                                   &callee,
                                                   callable_spec,
                                                   out);
            }
        }
        if (recv.type->kind == CG_TYPE_GENERIC_PARAM) {
            size_t gp_idx = recv.type->generic_param_index;
            const UserSpec *us = cg_generic_param_constraint_spec(cg, gp_idx);
            const char *desc_name = cg_generic_param_desc_name(cg, gp_idx);
            if (!us || !desc_name) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0155", "codegen: generic method call requires an object-form spec constraint");
            }
            const UserSpecMember *sm = rc->member != NULL
                ? cg_user_spec_member_for_resolved_call(cg, us, rc)
                : NULL;
            if (sm == NULL && rc->member == NULL) {
                sm = cg_user_spec_member(us,
                    ma->as.member.member.data, ma->as.member.member.length);
            }
            if (!sm || sm->kind != USM_KIND_METHOD) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0156", "codegen: spec '%s' has no method '%.*s'",
                    us->feng_name,
                    (int)ma->as.member.member.length, ma->as.member.member.data);
            }
            if (e->as.call.arg_count != sm->param_count) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0157", "codegen: wrong argument count for spec method '%s' (expected %zu, got %zu)",
                    sm->feng_name, sm->param_count, e->as.call.arg_count);
            }
            /* G4: static method dispatch has no _subject parameter and the
             * args buffer starts without a leading ", " separator. */
            const bool is_static_dispatch = sm->is_static;
            char *subject_expr = NULL;
            if (!is_static_dispatch) {
                subject_expr = cg_generic_witness_subject_expr(desc_name, recv.c_expr);
                if (!subject_expr) {
                    er_free(&recv);
                    return false;
                }
            }
            Buf args_buf; buf_init(&args_buf);
            bool ok = true;
            for (size_t i = 0; i < e->as.call.arg_count; i++) {
                ExprResult ar;
                char *argument_expr = NULL;
                if (!cg_emit_expr_for_expected_type(cg,
                                                    e->as.call.args[i],
                                                    sm->param_types[i],
                                                    &ar)) { ok = false; break; }
                argument_expr = cg_shared_callable_argument_expr_dup(
                    cg,
                    &ar,
                    sm->param_abi_kinds[i] == CG_CALLABLE_ABI_ADDRESS,
                    "_spec_arg");
                if (argument_expr == NULL) {
                    er_free(&ar);
                    ok = false;
                    break;
                }
                if (!is_static_dispatch || i > 0U) {
                    buf_append_cstr(&args_buf, ", ");
                }
                buf_append_cstr(&args_buf, argument_expr);
                free(argument_expr);
                er_free(&ar);
            }
            if (!ok) {
                free(subject_expr);
                buf_free(&args_buf);
                er_free(&recv);
                return false;
            }
            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                char *ret_slot = cg_fresh_temp(cg, "_spec_ret");
                char *erased_descriptor_name = NULL;
                char *erased_size_name = NULL;
                const char *ret_argument_prefix = "&";

                if (ret_slot == NULL) {
                    free(ret_slot);
                    free(subject_expr);
                    buf_free(&args_buf);
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                                   "IE0001", "codegen: out of memory");
                }
                if (sm->type->kind == CG_TYPE_GENERIC_PARAM) {
                    if (!cg_emit_erased_generic_storage_declaration(
                            cg,
                            sm->type,
                            ret_slot,
                            e->token,
                            &erased_descriptor_name,
                            &erased_size_name)) {
                        free(ret_slot);
                        free(subject_expr);
                        buf_free(&args_buf);
                        er_free(&recv);
                        return false;
                    }
                    out->c_expr = strdup(ret_slot);
                    out->is_addressable = true;
                    out->is_storage_address = true;
                    ret_argument_prefix = "";
                } else if (cg_type_uses_reified_storage(cg, sm->type)) {
                    if (!cg_emit_reified_storage_declaration(
                            cg,
                            sm->type,
                            ret_slot,
                            e->token,
                            &out->reified_descriptor_c_name,
                            &out->reified_size_c_name)) {
                        free(ret_slot);
                        free(subject_expr);
                        buf_free(&args_buf);
                        er_free(&recv);
                        return false;
                    }
                    out->c_expr = strdup(ret_slot);
                    out->is_addressable = true;
                    out->is_storage_address = true;
                    out->uses_reified_storage = true;
                    ret_argument_prefix = "";
                } else {
                    char *ret_ctype = cg_ctype_dup(sm->type);

                    if (ret_ctype == NULL) {
                        free(ret_slot);
                        free(subject_expr);
                        buf_free(&args_buf);
                        er_free(&recv);
                        return cg_fail(cg, e->token,
                                       "IE0001", "codegen: out of memory");
                    }
                    buf_append_fmt(cg->cur_body,
                                   "    %s %s;\n",
                                   ret_ctype,
                                   ret_slot);
                    free(ret_ctype);
                    out->c_expr = strdup(ret_slot);
                    out->is_addressable = true;
                }
                if (out->c_expr == NULL) {
                    free(erased_descriptor_name);
                    free(erased_size_name);
                    free(ret_slot);
                    free(subject_expr);
                    buf_free(&args_buf);
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                                   "IE0001", "codegen: out of memory");
                }
                if (is_static_dispatch) {
                    /* Static spec method: args_buf has no leading ", ";
                     * insert a ", " between args and the out-param slot.
                     * If there are no args (args_buf empty / NULL), emit
                     * only the out-param to avoid a dangling leading comma. */
                    if (args_buf.data && args_buf.data[0] != '\0') {
                        buf_append_fmt(cg->cur_body,
                            "    ((const struct %s *)%s->witness)->%s(%s, %s%s);\n",
                            us->c_witness_struct_name,
                            desc_name,
                            sm->c_field_name,
                            args_buf.data,
                            ret_argument_prefix,
                            ret_slot);
                    } else {
                        buf_append_fmt(cg->cur_body,
                            "    ((const struct %s *)%s->witness)->%s(%s%s);\n",
                            us->c_witness_struct_name,
                            desc_name,
                            sm->c_field_name,
                            ret_argument_prefix,
                            ret_slot);
                    }
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    ((const struct %s *)%s->witness)->%s(%s%s, %s%s);\n",
                        us->c_witness_struct_name,
                        desc_name,
                        sm->c_field_name,
                        subject_expr,
                        args_buf.data ? args_buf.data : "",
                        ret_argument_prefix,
                        ret_slot);
                }
                out->type = cgtype_clone(sm->type);
                if (out->type == NULL) {
                    free(ret_slot);
                    free(erased_descriptor_name);
                    free(erased_size_name);
                    free(subject_expr);
                    buf_free(&args_buf);
                    er_free(&recv);
                    er_free(out);
                    return cg_fail(cg, e->token,
                                   "IE0001", "codegen: out of memory");
                }
                if (sm->type->kind == CG_TYPE_GENERIC_PARAM) {
                    if (!cg_register_erased_generic_storage_for_cleanup(
                            cg,
                            ret_slot,
                            out->type,
                            erased_descriptor_name,
                            erased_size_name,
                            e->token)) {
                        free(ret_slot);
                        free(erased_descriptor_name);
                        free(erased_size_name);
                        free(subject_expr);
                        buf_free(&args_buf);
                        er_free(&recv);
                        er_free(out);
                        return false;
                    }
                    out->owns_ref = false;
                    out->uses_erased_generic_storage = true;
                    out->erased_generic_descriptor_c_name =
                        erased_descriptor_name;
                    out->erased_generic_size_c_name = erased_size_name;
                    erased_descriptor_name = NULL;
                    erased_size_name = NULL;
                } else {
                    out->owns_ref = true;
                }
                free(ret_slot);
                free(erased_descriptor_name);
                free(erased_size_name);
                free(subject_expr);
                buf_free(&args_buf);
                er_free(&recv);
                return out->c_expr != NULL && out->type != NULL;
            }
            Buf b; buf_init(&b);
            if (is_static_dispatch) {
                buf_append_fmt(&b, "((const struct %s *)%s->witness)->%s(%s)",
                               us->c_witness_struct_name, desc_name,
                               sm->c_field_name,
                               args_buf.data ? args_buf.data : "");
            } else {
                buf_append_fmt(&b, "((const struct %s *)%s->witness)->%s(%s%s)",
                               us->c_witness_struct_name, desc_name,
                               sm->c_field_name, subject_expr,
                               args_buf.data ? args_buf.data : "");
            }
            free(subject_expr);
            buf_free(&args_buf);
            out->c_expr = b.data;
            out->type = cgtype_clone(sm->type);
            out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
            er_free(&recv);
            return out->c_expr && out->type;
        }
        if (recv.type->kind == CG_TYPE_SPEC && recv.type->user_spec) {
            /* Step 4b — spec method dispatch via witness table. */
            const UserSpec *us = recv.type->user_spec;
            const UserSpecMember *sm = rc->member != NULL
                ? cg_user_spec_member_for_resolved_call(cg, us, rc)
                : NULL;
            if (sm == NULL && rc->member == NULL) {
                sm = cg_user_spec_member(us,
                    ma->as.member.member.data, ma->as.member.member.length);
            }
            if (!sm || sm->kind != USM_KIND_METHOD) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0156", "codegen: spec '%s' has no method '%.*s'",
                    us->feng_name,
                    (int)ma->as.member.member.length, ma->as.member.member.data);
            }
            if (e->as.call.arg_count != sm->param_count) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0157", "codegen: wrong argument count for spec method '%s' (expected %zu, got %zu)",
                    sm->feng_name, sm->param_count, e->as.call.arg_count);
            }
            /* Materialize the receiver so .subject / .witness load exactly
             * once. Spec values are aggregates — owns_ref==true means the
             * value carries a +1 the materialised local should adopt. */
            cg_materialize_to_local(cg, &recv, "_t");
            Buf args_buf; buf_init(&args_buf);
            bool ok = true;
            for (size_t i = 0; i < e->as.call.arg_count; i++) {
                ExprResult ar;
                char *argument_expr = NULL;
                if (!cg_emit_expr_for_expected_type(cg,
                                                    e->as.call.args[i],
                                                    sm->param_types[i],
                                                    &ar)) { ok = false; break; }
                argument_expr = cg_shared_callable_argument_expr_dup(
                    cg,
                    &ar,
                    sm->param_abi_kinds[i] == CG_CALLABLE_ABI_ADDRESS,
                    "_spec_arg");
                if (argument_expr == NULL) {
                    er_free(&ar);
                    ok = false;
                    break;
                }
                buf_append_cstr(&args_buf, ", ");
                buf_append_cstr(&args_buf, argument_expr);
                free(argument_expr);
                er_free(&ar);
            }
            if (!ok) { buf_free(&args_buf); er_free(&recv); return false; }
            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                char *result_name = cg_fresh_temp(cg, "_spec_result");
                char *erased_descriptor_name = NULL;
                char *erased_size_name = NULL;
                const char *result_argument_prefix = "&";

                if (result_name == NULL) {
                    buf_free(&args_buf);
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                                   "IE0001", "codegen: out of memory");
                }
                if (sm->type->kind == CG_TYPE_GENERIC_PARAM) {
                    if (!cg_emit_erased_generic_storage_declaration(
                            cg,
                            sm->type,
                            result_name,
                            e->token,
                            &erased_descriptor_name,
                            &erased_size_name)) {
                        free(result_name);
                        buf_free(&args_buf);
                        er_free(&recv);
                        return false;
                    }
                    out->c_expr = strdup(result_name);
                    out->is_addressable = true;
                    out->is_storage_address = true;
                    result_argument_prefix = "";
                } else if (cg_type_uses_reified_storage(cg, sm->type)) {
                    if (!cg_emit_reified_storage_declaration(
                            cg,
                            sm->type,
                            result_name,
                            e->token,
                            &out->reified_descriptor_c_name,
                            &out->reified_size_c_name)) {
                        free(result_name);
                        buf_free(&args_buf);
                        er_free(&recv);
                        return false;
                    }
                    out->c_expr = strdup(result_name);
                    out->is_addressable = true;
                    out->is_storage_address = true;
                    out->uses_reified_storage = true;
                    result_argument_prefix = "";
                } else {
                    char *result_ctype = cg_ctype_dup(sm->type);

                    if (result_ctype == NULL) {
                        free(result_name);
                        buf_free(&args_buf);
                        er_free(&recv);
                        return cg_fail(cg, e->token,
                                       "IE0001", "codegen: out of memory");
                    }
                    buf_append_fmt(cg->cur_body,
                                   "    %s %s;\n",
                                   result_ctype,
                                   result_name);
                    free(result_ctype);
                    out->c_expr = strdup(result_name);
                    out->is_addressable = true;
                }
                if (out->c_expr == NULL) {
                    free(erased_descriptor_name);
                    free(erased_size_name);
                    free(result_name);
                    buf_free(&args_buf);
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                                   "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(cg->cur_body,
                    "    %s.witness->%s(%s.subject%s, %s%s);\n",
                    recv.c_expr,
                    sm->c_field_name,
                    recv.c_expr,
                    args_buf.data ? args_buf.data : "",
                    result_argument_prefix,
                    result_name);
                out->type = cgtype_clone(sm->type);
                if (sm->type->kind == CG_TYPE_GENERIC_PARAM) {
                    if (out->type == NULL ||
                        !cg_register_erased_generic_storage_for_cleanup(
                            cg,
                            result_name,
                            out->type,
                            erased_descriptor_name,
                            erased_size_name,
                            e->token)) {
                        free(erased_descriptor_name);
                        free(erased_size_name);
                        free(result_name);
                        buf_free(&args_buf);
                        er_free(&recv);
                        er_free(out);
                        return false;
                    }
                    out->owns_ref = false;
                    out->uses_erased_generic_storage = true;
                    out->erased_generic_descriptor_c_name =
                        erased_descriptor_name;
                    out->erased_generic_size_c_name = erased_size_name;
                    erased_descriptor_name = NULL;
                    erased_size_name = NULL;
                } else {
                    out->owns_ref = true;
                }
                free(erased_descriptor_name);
                free(erased_size_name);
                free(result_name);
                buf_free(&args_buf);
                er_free(&recv);
                return out->c_expr != NULL && out->type != NULL;
            }
            Buf b; buf_init(&b);
            buf_append_fmt(&b, "%s.witness->%s(%s.subject%s)",
                           recv.c_expr, sm->c_field_name, recv.c_expr,
                           args_buf.data ? args_buf.data : "");
            buf_free(&args_buf);
            out->c_expr = b.data;
            out->type = cgtype_clone(sm->type);
            out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
            er_free(&recv);
            return out->c_expr && out->type;
        }
        /* A callable field access has no resolved method target.  Handle it
         * before generic-self method dispatch, which intentionally searches
         * only method declarations on the open generic owner. */
        if (e->as.call.resolved_callable.kind == FENG_RESOLVED_CALLABLE_NONE &&
            cg->in_generic_type_method &&
            cg_type_is_current_generic_owner(cg, recv.type) &&
            cg->generic_type_method_decl != NULL &&
            cg->generic_type_method_decl->kind == FENG_DECL_TYPE &&
            ma->as.member.object->kind == FENG_EXPR_SELF) {
            ExprResult callee;

            er_free(&recv);
            er_init(&callee);
            if (!cg_emit_expr(cg, ma, &callee)) {
                return false;
            }
            if (callee.type == NULL ||
                callee.type->kind != CG_TYPE_CALLABLE ||
                callee.type->user_spec == NULL) {
                er_free(&callee);
                return cg_fail(cg, e->token,
                    "CE0163", "codegen: member call on non-callable value");
            }
            return cg_emit_callable_value_call(cg,
                                               e,
                                               &callee,
                                               callee.type->user_spec,
                                               out);
        }
        if (cg->in_generic_type_method &&
            cg_type_is_current_generic_owner(cg, recv.type) &&
            cg->generic_type_method_decl != NULL &&
            cg->generic_type_method_decl->kind == FENG_DECL_TYPE &&
            ma->as.member.object->kind == FENG_EXPR_SELF) {
            return cg_emit_generic_type_self_method_call(cg, e, ma, &recv, out);
        }
        const UserMethod *um = NULL;
        const UserFit *selected_user_fit = NULL;
        if (rc->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD &&
            (recv.type->kind != CG_TYPE_OBJECT || !recv.type->user)) {
            const BuiltinFit *bf = NULL;

            if (rc->fit_decl != NULL) {
                bf = cg_find_builtin_fit_by_decl(cg, rc->fit_decl);
            }
            if (bf != NULL && rc->member != NULL) {
                um = cg_builtin_fit_method_by_member(bf, rc->member);
            }
            if (um == NULL && bf != NULL) {
                um = cg_builtin_fit_method(bf,
                    ma->as.member.member.data, ma->as.member.member.length);
            }
            if (um == NULL) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0159", "codegen: builtin/array fit has no method '%.*s'",
                    (int)ma->as.member.member.length, ma->as.member.member.data);
            }
            if (e->as.call.arg_count != um->param_count) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0160", "codegen: wrong argument count for method '%s' (expected %zu, got %zu)",
                    um->feng_name, um->param_count, e->as.call.arg_count);
            }
            if (cgtype_is_managed(recv.type) && recv.owns_ref) {
                cg_materialize_to_local(cg, &recv, "_t");
            }
            Buf args_buf; buf_init(&args_buf);
            for (size_t i = 0; i < e->as.call.arg_count; i++) {
                ExprResult ar;
                char *arg_expr = NULL;
                if (!cg_emit_expr_for_expected_type(cg,
                                                    e->as.call.args[i],
                                                    um->param_types[i],
                                                    &ar)) {
                    buf_free(&args_buf); er_free(&recv); return false;
                }
                if (um->param_types[i] != NULL && um->param_types[i]->kind == CG_TYPE_GENERIC_PARAM) {
                    char *tmp = cg_fresh_temp(cg, "_bfa");

                    if (tmp == NULL) {
                        buf_free(&args_buf);
                        er_free(&ar);
                        er_free(&recv);
                        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                    }
                    if (ar.type != NULL && ar.type->kind == CG_TYPE_GENERIC_PARAM) {
                        buf_append_fmt(cg->cur_body, "    const void *%s = %s;\n", tmp, ar.c_expr);
                        arg_expr = strdup(tmp);
                    } else {
                        char *cty = cg_ctype_dup(ar.type);

                        if (cty == NULL) {
                            free(tmp);
                            buf_free(&args_buf);
                            er_free(&ar);
                            er_free(&recv);
                            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                        }
                        buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, ar.c_expr);
                        if (cgtype_is_managed(ar.type) && ar.owns_ref) {
                            cg_emit_cleanup_push_for_managed_local(cg, tmp);
                            ar.owns_ref = false;
                        }
                        Buf addr; buf_init(&addr);
                        buf_append_fmt(&addr, "&%s", tmp);
                        arg_expr = addr.data;
                        free(cty);
                    }
                    free(tmp);
                } else {
                    if (cgtype_is_managed(ar.type) && ar.owns_ref) {
                        cg_materialize_to_local(cg, &ar, "_t");
                    }
                    arg_expr = strdup(ar.c_expr);
                }
                if (arg_expr == NULL) {
                    buf_free(&args_buf);
                    er_free(&ar);
                    er_free(&recv);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
                buf_append_cstr(&args_buf, ", ");
                buf_append_cstr(&args_buf, arg_expr);
                free(arg_expr);
                er_free(&ar);
            }
            /* 先确保返回类型的泛型实例已注册（副作用：注册
             * Span<i32> 等 dep 实例）。 */
            CGType *bf_ret = cg_instantiate_builtin_fit_return_type(cg,
                bf, um->return_type,
                recv.type != NULL && recv.type->kind == CG_TYPE_ARRAY
                    ? recv.type->element : NULL,
                e->token);

            Buf b; buf_init(&b);
            if (cg->generic_type_method_rtd_via_desc ||
                cg->generic_type_method_rad_via_desc) {
                /* 在 BuiltinFit 共享体内部调用同一 fit 的另一个方法
                 * 时，直接传递 _desc（已含正确的 reified deps）。 */
                buf_append_fmt(&b, "%s(%s, _desc",
                               um->c_name, recv.c_expr);
            } else {
                const CGType *elem = (recv.type != NULL &&
                                      recv.type->kind == CG_TYPE_ARRAY)
                                         ? recv.type->element : NULL;
                char *fdesc = cg_builtin_fit_fdesc_expr(cg, bf,
                                                         um,
                                                         elem,
                                                         &e->token);
                if (fdesc == NULL) {
                    cgtype_free(bf_ret);
                    buf_free(&args_buf);
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                        "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(&b, "%s(%s, %s",
                               um->c_name, recv.c_expr, fdesc);
                free(fdesc);
            }
            if (bf->target_type_param_count > 0U) {
                if (bf->target_type_param_count != 1U ||
                    recv.type == NULL || recv.type->kind != CG_TYPE_ARRAY ||
                    recv.type->element == NULL) {
                    buf_free(&args_buf);
                    buf_free(&b);
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                        "CE0161", "codegen: builtin fit generic descriptor emission only supports array targets in this phase");
                }
                char *desc_expr = NULL;
                if (!cg_generic_descriptor_expr(cg,
                                                recv.type->element,
                                                NULL,
                                                &e->token,
                                                &desc_expr)) {
                    buf_free(&args_buf);
                    buf_free(&b);
                    er_free(&recv);
                    return false;
                }
                buf_append_fmt(&b, ", %s", desc_expr);
                free(desc_expr);
            }
            if (args_buf.data != NULL) {
                buf_append(&b, args_buf.data, args_buf.length);
            }
            buf_free(&args_buf);
            out->type = bf_ret;
            if (out->type == NULL) {
                buf_free(&b);
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0162", "codegen: failed to instantiate builtin fit return type");
            }
            if (cg_builtin_fit_return_uses_out(bf, um)) {
                char *return_temp = cg_fresh_temp(cg, "_bfr");
                if (return_temp == NULL) {
                    free(return_temp);
                    buf_free(&b);
                    er_free(&recv);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
                if (cg_type_uses_reified_storage(cg, out->type)) {
                    char *descriptor_name = NULL;
                    char *size_name = NULL;

                    if (!cg_emit_reified_storage_declaration(cg,
                                                             out->type,
                                                             return_temp,
                                                             e->token,
                                                             &descriptor_name,
                                                             &size_name)) {
                        free(return_temp);
                        buf_free(&b);
                        er_free(&recv);
                        return false;
                    }
                    buf_append_fmt(&b, ", %s)", return_temp);
                    buf_append_fmt(cg->cur_body, "    %s;\n", b.data);
                    out->c_expr = strdup(return_temp);
                    out->is_storage_address = true;
                    out->uses_reified_storage = true;
                    out->is_addressable = true;
                    out->reified_descriptor_c_name = descriptor_name;
                    out->reified_size_c_name = size_name;
                } else {
                    char *return_ctype = cg_ctype_dup(out->type);
                    if (return_ctype == NULL) {
                        free(return_temp);
                        buf_free(&b);
                        er_free(&recv);
                        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                    }
                    buf_append_fmt(&b, ", &%s)", return_temp);
                    buf_append_fmt(cg->cur_body,
                                   "    %s %s;\n"
                                   "    %s;\n",
                                   return_ctype,
                                   return_temp,
                                   b.data);
                    out->c_expr = strdup(return_temp);
                    free(return_ctype);
                }
                free(return_temp);
                buf_free(&b);
                if (out->c_expr == NULL) {
                    er_free(&recv);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            } else {
                buf_append_cstr(&b, ")");
                out->c_expr = b.data;
            }
            if (!cg_builtin_fit_return_uses_out(bf, um) &&
                bf->target_type_param_count > 0U &&
                out->type->kind == CG_TYPE_OBJECT &&
                um->return_type != NULL &&
                um->return_type->kind == CG_TYPE_OBJECT &&
                um->return_type->user != out->type->user) {
                char *target_ctype = cg_ctype_dup(out->type);
                char *raw_expr = out->c_expr;
                if (target_ctype == NULL) {
                    free(raw_expr);
                    er_free(&recv);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
                Buf cast_expr;
                buf_init(&cast_expr);
                buf_append_fmt(&cast_expr, "((%s)(%s))", target_ctype, raw_expr);
                free(target_ctype);
                free(raw_expr);
                out->c_expr = cast_expr.data;
                if (out->c_expr == NULL) {
                    er_free(&recv);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            }
            out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
            er_free(&recv);
            return out->c_expr && out->type;
        }

        if (recv.type->kind != CG_TYPE_OBJECT || !recv.type->user) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0163", "codegen: method call on non-object value");
        }
        const UserType *ut = recv.type->user;
        if (rc->kind == FENG_RESOLVED_CALLABLE_NONE) {
            const UserField *callable_field = cg_user_type_field(
                ut,
                ma->as.member.member.data,
                ma->as.member.member.length);

            if (callable_field != NULL &&
                callable_field->type != NULL &&
                callable_field->type->kind == CG_TYPE_CALLABLE &&
                callable_field->type->user_spec != NULL) {
                ExprResult callee;
                const UserSpec *callable_spec = callable_field->type->user_spec;

                if (!cg_emit_user_field_borrow(cg,
                                               &recv,
                                               callable_field,
                                               e->token,
                                               &callee)) {
                    return false;
                }
                return cg_emit_callable_value_call(cg,
                                                   e,
                                                   &callee,
                                                   callable_spec,
                                                   out);
            }
        }
        if (rc->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD) {
            if (rc->fit_decl != NULL) {
                selected_user_fit = cg_find_user_fit_by_decl_and_target(
                    cg, rc->fit_decl, ut);
            }
            if (selected_user_fit != NULL && rc->member != NULL) {
                um = cg_user_fit_method_by_member(
                    selected_user_fit, rc->member);
            }
            if (um == NULL && selected_user_fit != NULL) {
                um = cg_user_fit_method(selected_user_fit,
                    ma->as.member.member.data, ma->as.member.member.length);
            }
            if (um == NULL) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0164", "codegen: type '%s' has no method '%.*s'",
                    ut->feng_name,
                    (int)ma->as.member.member.length, ma->as.member.member.data);
            }
        } else {
            if (rc->kind == FENG_RESOLVED_CALLABLE_TYPE_METHOD && rc->member) {
                um = cg_user_type_method_by_member(ut, rc->member);
            }
            if (!um) {
                um = cg_user_type_method(ut,
                    ma->as.member.member.data, ma->as.member.member.length);
            }
        }
        if (!um) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0164", "codegen: type '%s' has no method '%.*s'",
                ut->feng_name,
                (int)ma->as.member.member.length, ma->as.member.member.data);
        }
        if (um->member != NULL &&
            um->member->as.callable.type_param_count > 0U) {
            return cg_emit_generic_type_method_call(
                cg, e, &recv, ut, um, selected_user_fit, out);
        }
        /* Open generic instance: call shared body directly instead of the
         * per-instance static forwarder (which only exists for concrete
         * instances like List<int>, not open ones like List<T>). */
        if (ut->is_generic_instance &&
            ut->generic_context_type_param_count > 0U &&
            um->member != NULL) {
            if (e->as.call.arg_count != um->param_count) {
                if (!um->is_variadic) {
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                        "CE0160", "codegen: wrong argument count for method '%s' (expected %zu, got %zu)",
                        um->feng_name, um->param_count, e->as.call.arg_count);
                }
                size_t fixed_count = um->param_count - 1U;
                if (e->as.call.arg_count < fixed_count) {
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                        "CE0165", "codegen: too few arguments for variadic method '%s' (need at least %zu, got %zu)",
                        um->feng_name, fixed_count, e->as.call.arg_count);
                }
            }
            if (cgtype_is_managed(recv.type) && recv.owns_ref) {
                cg_materialize_to_local(cg, &recv, "_t");
            }
            /* §9.15: value-semantics (tuple/@value) shared body takes void *self
             * (pointer to value); pass &recv directly for lvalues, materialize
             * for rvalues. */
            if (cg_type_is_value_semantics(recv.type)) {
                bool recv_is_lvalue =
                    ma->as.member.object->kind == FENG_EXPR_IDENTIFIER ||
                    ma->as.member.object->kind == FENG_EXPR_SELF ||
                    ma->as.member.object->kind == FENG_EXPR_MEMBER ||
                    ma->as.member.object->kind == FENG_EXPR_INDEX;
                if (!recv_is_lvalue) {
                    cg_materialize_to_local(cg, &recv, "_vrecv");
                }
            }
            char *shared_name = selected_user_fit != NULL
                ? cg_fit_method_shared_cname(
                      cg, selected_user_fit, um->member)
                : cg_generic_type_method_shared_cname(
                      cg, ut->generic_origin_decl, um->member);
            char *rtd_expr = cg_rtd_expr_for_type(cg, ut, e->token);
            char *func_desc_expr =
                cg_callable_descriptor_expr_for_call(cg, e, e->token);
            if (shared_name == NULL || rtd_expr == NULL ||
                func_desc_expr == NULL) {
                free(shared_name);
                free(rtd_expr);
                free(func_desc_expr);
                er_free(&recv);
                return false;
            }
            /* Emit argument expressions. */
            size_t arg_count = e->as.call.arg_count;
            ExprResult *args = arg_count
                ? calloc(arg_count, sizeof *args) : NULL;
            char **arg_exprs = arg_count
                ? calloc(arg_count, sizeof *arg_exprs) : NULL;
            if (arg_count && (args == NULL || arg_exprs == NULL)) {
                free(args);
                free(arg_exprs);
                free(shared_name);
                free(rtd_expr);
                free(func_desc_expr);
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "IE0001", "codegen: out of memory");
            }
            bool call_ok = true;
            for (size_t i = 0; i < arg_count; i++) {
                bool uses_address_abi = false;

                if (!cg_emit_expr_for_expected_type(cg,
                                                    e->as.call.args[i],
                                                    um->param_types[i],
                                                    &args[i])) {
                    call_ok = false;
                    break;
                }
                if (!cg_shared_method_param_uses_address_abi(
                        cg,
                        ut->generic_origin_decl,
                        um->member,
                        i,
                        &uses_address_abi)) {
                    call_ok = false;
                    break;
                }
                {
                    CGType *shared_param_type = NULL;

                    if (!cg_resolve_shared_method_declared_param_type(
                            cg,
                            ut->generic_origin_decl->as.type_decl.type_params,
                            ut->generic_origin_decl->as.type_decl.type_param_count,
                            cg_find_decl_owner_program(
                                cg, ut->generic_origin_decl),
                            um->member,
                            i,
                            &shared_param_type)) {
                        call_ok = false;
                        break;
                    }
                    arg_exprs[i] =
                        cg_shared_callable_argument_for_type_expr_dup(
                            cg,
                            &args[i],
                            shared_param_type,
                            uses_address_abi,
                            "_t");
                    cgtype_free(shared_param_type);
                }
                if (arg_exprs[i] == NULL) {
                    call_ok = false;
                    break;
                }
            }
            if (!call_ok) {
                for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
                for (size_t i = 0; i < arg_count; i++) free(arg_exprs[i]);
                free(args);
                free(arg_exprs);
                free(shared_name);
                free(rtd_expr);
                free(func_desc_expr);
                er_free(&recv);
                return false;
            }
            /* Determine return handling. */
            bool has_return = um->return_type != NULL &&
                              um->return_type->kind != CG_TYPE_VOID;
            bool ret_is_storage_address = false;
            bool ret_uses_erased_generic_storage = false;
            bool ret_uses_reified_storage = false;
            CGType *concrete_return = NULL;
            char *ret_tmp = NULL;
            char *ret_descriptor_name = NULL;
            char *ret_size_name = NULL;
            if (!cg_resolve_selected_callable_return_type(
                    cg,
                    e,
                    &um->member->as.callable,
                    e->token,
                    &concrete_return)) {
                for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
                for (size_t i = 0; i < arg_count; i++) free(arg_exprs[i]);
                free(args);
                free(arg_exprs);
                free(shared_name);
                free(rtd_expr);
                free(func_desc_expr);
                er_free(&recv);
                return false;
            }
            if (has_return) {
                ret_tmp = cg_fresh_temp(cg, "_osr");
                if (ret_tmp == NULL) {
                    for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
                    for (size_t i = 0; i < arg_count; i++) free(arg_exprs[i]);
                    free(args);
                    free(arg_exprs);
                    free(shared_name);
                    free(rtd_expr);
                    free(func_desc_expr);
                    cgtype_free(concrete_return);
                    er_free(&recv);
                    return cg_fail(cg, e->token,
                        "IE0001", "codegen: out of memory");
                }
                if (concrete_return->kind == CG_TYPE_GENERIC_PARAM) {
                    if (!cg_emit_erased_generic_storage_declaration(
                            cg,
                            concrete_return,
                            ret_tmp,
                            e->token,
                            &ret_descriptor_name,
                            &ret_size_name)) {
                        free(ret_tmp);
                        for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
                        for (size_t i = 0; i < arg_count; i++) free(arg_exprs[i]);
                        free(args);
                        free(arg_exprs);
                        free(shared_name);
                        free(rtd_expr);
                        free(func_desc_expr);
                        cgtype_free(concrete_return);
                        er_free(&recv);
                        return false;
                    }
                    ret_is_storage_address = true;
                    ret_uses_erased_generic_storage = true;
                } else if (cg_type_uses_reified_storage(
                               cg, concrete_return)) {
                    if (!cg_emit_reified_storage_declaration(
                            cg,
                            concrete_return,
                            ret_tmp,
                            e->token,
                            &ret_descriptor_name,
                            &ret_size_name)) {
                        free(ret_tmp);
                        for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
                        for (size_t i = 0; i < arg_count; i++) free(arg_exprs[i]);
                        free(args);
                        free(arg_exprs);
                        free(shared_name);
                        free(rtd_expr);
                        free(func_desc_expr);
                        cgtype_free(concrete_return);
                        er_free(&recv);
                        return false;
                    }
                    ret_is_storage_address = true;
                    ret_uses_reified_storage = true;
                } else {
                    char *cty = cg_ctype_dup(concrete_return);
                    if (cty == NULL) {
                        free(ret_tmp);
                        for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
                        for (size_t i = 0; i < arg_count; i++) free(arg_exprs[i]);
                        free(args);
                        free(arg_exprs);
                        free(shared_name);
                        free(rtd_expr);
                        free(func_desc_expr);
                        cgtype_free(concrete_return);
                        er_free(&recv);
                        return cg_fail(cg, e->token,
                            "IE0001", "codegen: out of memory");
                    }
                    buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, ret_tmp);
                    free(cty);
                }
            }
            /* Build: shared_name((void *)recv, rtd_expr, func_desc,
             * args..., [_out]). */
            Buf b; buf_init(&b);
            /* §9.15: ordinary value storage needs an address; address-form
             * receiver expressions already denote their exact storage. */
            if (cg_type_is_value_semantics(recv.type) &&
                !recv.is_storage_address) {
                buf_append_fmt(&b, "%s((void *)&%s, %s, %s",
                               shared_name, recv.c_expr, rtd_expr,
                               func_desc_expr);
            } else {
                buf_append_fmt(&b, "%s((void *)%s, %s, %s",
                               shared_name, recv.c_expr, rtd_expr,
                               func_desc_expr);
            }
            for (size_t i = 0; i < arg_count; i++) {
                buf_append_fmt(&b, ", %s", arg_exprs[i]);
            }
            if (has_return) {
                buf_append_fmt(&b,
                               ret_is_storage_address ? ", %s" : ", &%s",
                               ret_tmp);
            }
            buf_append_cstr(&b, ");\n");
            buf_append(cg->cur_body, b.data, b.length);
            buf_free(&b);
            for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
            for (size_t i = 0; i < arg_count; i++) free(arg_exprs[i]);
            free(args);
            free(arg_exprs);
            free(shared_name);
            free(rtd_expr);
            free(func_desc_expr);
            if (has_return) {
                out->c_expr = strdup(ret_tmp);
                out->type = concrete_return;
                concrete_return = NULL;
                out->owns_ref = cgtype_is_managed(out->type) ||
                                cgtype_is_aggregate(out->type);
                out->is_addressable = true;
                out->is_storage_address = ret_is_storage_address;
                if (ret_uses_erased_generic_storage) {
                    if (out->c_expr == NULL ||
                        !cg_register_erased_generic_storage_for_cleanup(
                            cg,
                            ret_tmp,
                            out->type,
                            ret_descriptor_name,
                            ret_size_name,
                            e->token)) {
                        er_free(out);
                        free(ret_tmp);
                        free(ret_descriptor_name);
                        free(ret_size_name);
                        er_free(&recv);
                        return false;
                    }
                    out->owns_ref = false;
                    out->uses_erased_generic_storage = true;
                    out->erased_generic_descriptor_c_name =
                        ret_descriptor_name;
                    out->erased_generic_size_c_name = ret_size_name;
                    ret_descriptor_name = NULL;
                    ret_size_name = NULL;
                }
                out->uses_reified_storage = ret_uses_reified_storage;
                if (ret_uses_reified_storage) {
                    out->reified_descriptor_c_name = ret_descriptor_name;
                    out->reified_size_c_name = ret_size_name;
                    ret_descriptor_name = NULL;
                    ret_size_name = NULL;
                }
                free(ret_tmp);
            } else {
                out->c_expr = strdup("((void)0)");
                out->type = concrete_return;
                concrete_return = NULL;
                out->owns_ref = false;
            }
            cgtype_free(concrete_return);
            free(ret_descriptor_name);
            free(ret_size_name);
            er_free(&recv);
            return out->c_expr && out->type;
        }
        if (e->as.call.arg_count != um->param_count) {
            if (!um->is_variadic) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0160", "codegen: wrong argument count for method '%s' (expected %zu, got %zu)",
                    um->feng_name, um->param_count, e->as.call.arg_count);
            }
            size_t fixed_count = um->param_count - 1U;
            if (e->as.call.arg_count < fixed_count) {
                er_free(&recv);
                return cg_fail(cg, e->token,
                    "CE0165", "codegen: too few arguments for variadic method '%s' (need at least %zu, got %zu)",
                    um->feng_name, fixed_count, e->as.call.arg_count);
            }
        }
        /* Materialize receiver if it's a +1 owns_ref (so it lives across args). */
        if (cgtype_is_managed(recv.type) && recv.owns_ref) {
            cg_materialize_to_local(cg, &recv, "_t");
        }
        /* §9.15: value-semantics (tuple/@value) method signature takes
         * struct X *self (pointer), but recv is a value expression.  For
         * lvalue recv (local var, field access, self), pass &recv directly
         * so method mutations propagate back.  For rvalue recv (function
         * return, literal), materialize to local first. */
        if (cg_type_is_value_semantics(recv.type)) {
            bool recv_is_lvalue =
                ma->as.member.object->kind == FENG_EXPR_IDENTIFIER ||
                ma->as.member.object->kind == FENG_EXPR_SELF ||
                ma->as.member.object->kind == FENG_EXPR_MEMBER ||
                ma->as.member.object->kind == FENG_EXPR_INDEX;
            if (!recv_is_lvalue) {
                cg_materialize_to_local(cg, &recv, "_vrecv");
            }
        }
        Buf args_buf; buf_init(&args_buf);
        size_t fixed_arg_limit = um->is_variadic ? um->param_count - 1U : e->as.call.arg_count;
        for (size_t i = 0; i < fixed_arg_limit; i++) {
            ExprResult ar;
            if (!cg_emit_expr_for_expected_type(cg,
                                                e->as.call.args[i],
                                                um->param_types[i],
                                                &ar)) {
                buf_free(&args_buf); er_free(&recv); return false;
            }
            if (cgtype_is_managed(ar.type) && ar.owns_ref) {
                cg_materialize_to_local(cg, &ar, "_t");
            }
            buf_append_cstr(&args_buf, ", ");
            buf_append_cstr(&args_buf, ar.c_expr);
            er_free(&ar);
        }
        /* Pack variadic arguments into a FengArray* and append as the last argument. */
        if (um->is_variadic) {
            const CGType *array_type = um->param_types[um->param_count - 1U];
            ExprResult varr;
            if (!cg_emit_variadic_array_arg(
                    cg, e, fixed_arg_limit, array_type, &varr)) {
                buf_free(&args_buf); er_free(&recv); return false;
            }
            if (cgtype_is_managed(varr.type) && varr.owns_ref) {
                cg_materialize_to_local(cg, &varr, "_t");
            }
            buf_append_cstr(&args_buf, ", ");
            buf_append_cstr(&args_buf, varr.c_expr);
            er_free(&varr);
        }
        Buf b; buf_init(&b);
        /* §9.15: value receiver methods take storage addresses. Reuse an
         * existing address-form receiver instead of taking its address. */
        if (cg_type_is_value_semantics(recv.type) &&
            !recv.is_storage_address) {
            buf_append_fmt(&b, "%s(&%s", um->c_name, recv.c_expr);
        } else {
            buf_append_fmt(&b, "%s(%s", um->c_name, recv.c_expr);
        }
        if (!cg_append_user_type_context_descriptor_args(cg, &b, ut, e->token)) {
            buf_free(&args_buf);
            buf_free(&b);
            er_free(&recv);
            return false;
        }
        if (args_buf.data != NULL) {
            buf_append(&b, args_buf.data, args_buf.length);
        }
        buf_append_cstr(&b, ")");
        buf_free(&args_buf);
        out->c_expr = b.data;
        out->type = cgtype_clone(um->return_type);
        out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
        er_free(&recv);
        return out->c_expr && out->type;
    }

    if (e->as.call.callee->kind != FENG_EXPR_IDENTIFIER) {
        return cg_emit_computed_callable_call(cg, e, out);
    }
    const FengSlice name = e->as.call.callee->as.identifier;

    {
        const Local *callee_local = scope_lookup(cg->cur_scope, name.data, name.length);
        if (callee_local != NULL && callee_local->type != NULL &&
            callee_local->type->kind == CG_TYPE_GENERIC_PARAM) {
            const UserSpec *constraint =
                cg_generic_param_constraint_spec(cg, callee_local->type->generic_param_index);
            if (constraint != NULL && constraint->form == FENG_SPEC_FORM_CALLABLE) {
                ExprResult callee;
                er_init(&callee);
                callee.c_expr = strdup(callee_local->c_name);
                callee.type = cgtype_clone(callee_local->type);
                callee.owns_ref = false;
                callee.is_addressable = true;
                callee.is_storage_address = callee_local->is_storage_address;
                if (callee.c_expr == NULL || callee.type == NULL) {
                    er_free(&callee);
                    return false;
                }
                return cg_emit_generic_callable_value_call(
                    cg, e, &callee, callee_local->type->generic_param_index, out);
            }
        }
        if (callee_local != NULL && callee_local->type != NULL &&
            callee_local->type->kind == CG_TYPE_CALLABLE &&
            callee_local->type->user_spec != NULL) {
            ExprResult callee;
            er_init(&callee);
            callee.c_expr = strdup(callee_local->c_name);
            callee.type = cgtype_clone(callee_local->type);
            callee.owns_ref = false;
            if (callee.c_expr == NULL || callee.type == NULL) {
                er_free(&callee);
                return false;
            }
            return cg_emit_callable_value_call(cg, e, &callee,
                                               callee.type->user_spec, out);
        }

        const ModuleBinding *callee_binding = cg_find_module_binding(cg, name.data, name.length);
        if (callee_binding != NULL && callee_binding->type != NULL &&
            callee_binding->type->kind == CG_TYPE_CALLABLE &&
            callee_binding->type->user_spec != NULL) {
            ExprResult callee;
            er_init(&callee);
            cg_emit_module_binding_ensure_init_call(cg, callee_binding);
            callee.c_expr = cg_module_binding_slot_expr_dup(callee_binding);
            callee.type = cgtype_clone(callee_binding->type);
            callee.owns_ref = false;
            if (callee.c_expr == NULL || callee.type == NULL) {
                er_free(&callee);
                return false;
            }
            return cg_emit_callable_value_call(cg, e, &callee,
                                               callee.type->user_spec, out);
        }

        {
            const FengDecl *imported_binding_decl =
                cg_resolve_imported_module_binding_decl(cg, e->as.call.callee);

            if (imported_binding_decl != NULL) {
                ExprResult callee;

                er_init(&callee);
                if (!cg_emit_imported_binding_expr(cg, imported_binding_decl, &callee)) {
                    return false;
                }
                if (callee.type == NULL || callee.type->kind != CG_TYPE_CALLABLE ||
                    callee.type->user_spec == NULL) {
                    er_free(&callee);
                    return cg_fail(cg, e->token,
                        "CE0154", "codegen: imported binding '%.*s' is not callable",
                        (int)name.length,
                        name.data);
                }
                return cg_emit_callable_value_call(cg, e, &callee,
                                                   callee.type->user_spec, out);
            }
        }
    }

    if (rc->kind == FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR) {
        const UserType *ut = NULL;
        const UserMethod *ctor = NULL;
        char *obj_name = NULL;
        char *obj_init = NULL;

        if (rc->owner_type_decl != NULL &&
            rc->owner_type_decl->kind == FENG_DECL_TYPE &&
            rc->owner_type_decl->as.type_decl.type_param_count > 0U) {
            ut = cg_find_generic_instance_user_type_with_active_context(
                cg,
                rc->owner_type_decl,
                e->as.call.explicit_type_args,
                e->as.call.explicit_type_arg_count);
            if (ut == NULL) {
                return cg_fail(cg, e->token,
                    "CE0167", "codegen: generic type constructor instance for '%.*s' was not registered",
                    (int)name.length, name.data);
            }
        } else {
            ut = cg_find_user_type(cg, name.data, name.length);
            if (ut == NULL) {
                return cg_fail(cg, e->token,
                    "CE0168", "codegen: unknown type '%.*s' in constructor call",
                    (int)name.length, name.data);
            }
        }

        if (rc->member != NULL) {
            ctor = cg_user_type_constructor_by_member(ut, rc->member);
            if (ctor == NULL) {
                return cg_fail(cg, e->token,
                    "CE0169", "codegen: resolved constructor for type '%s' was not registered",
                    ut->feng_name);
            }
        }

        /* @value type: stack-allocate, member-init, constructor-invoke. */
        if (cg_user_type_is_value(ut)) {
            return cg_emit_value_type_construction(cg, ut, ctor,
                                                   e->as.call.args,
                                                   e->as.call.arg_count,
                                                   e->token, out);
        }

        obj_name = cg_fresh_temp(cg, "_obj");

        /* 共享体内创建依赖泛型的托管对象时，直接用具体描述符
         * （reified_type_deps[i]）分配，避免先用擦除描述符分配
         * 再覆写 desc 的脆弱模式。 */
        {
            const char *desc_expr = NULL;
            if (cg->generic_type_method_rtd_count > 0U &&
                ut->is_generic_instance && ut->generic_origin_decl != NULL) {
                for (size_t ri = 0; ri < cg->generic_type_method_rtd_count; ri++) {
                    if (cg->generic_type_method_rtd_descs[ri] != NULL &&
                        strcmp(ut->c_desc_name,
                               cg->generic_type_method_rtd_descs[ri]) == 0) {
                        const char *src = cg->generic_type_method_rtd_via_desc
                                              ? "_desc" : "_td";
                        buf_append_fmt(cg->cur_body,
                            "    struct %s *%s = (struct %s *)feng_object_new("
                            "%s->reified_type_deps[%zu]);\n",
                            ut->c_struct_name, obj_name,
                            ut->c_struct_name, src, ri);
                        desc_expr = src;
                        break;
                    }
                }
            }
            if (desc_expr == NULL) {
                obj_init = cg_user_type_raw_object_new_expr(ut);
                if (obj_init == NULL) {
                    free(obj_name);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(cg->cur_body,
                               "    struct %s *%s = %s;\n",
                               ut->c_struct_name, obj_name, obj_init);
                free(obj_init);
            }
        }

        if (!cg_emit_construction_member_initializers(
                cg, ut, ctor, obj_name, e->token)) {
            free(obj_name);
            return false;
        }

        if (!cg_emit_constructor_invoke(cg,
                                        e->as.call.args,
                                        e->as.call.arg_count,
                                        ut,
                                        ctor,
                                        obj_name,
                                        NULL,
                                        e->token)) {
            free(obj_name);
            return false;
        }

        out->c_expr = obj_name;
        out->type = cgtype_new(CG_TYPE_OBJECT);
        if (!out->c_expr || !out->type) {
            free(obj_name);
            return false;
        }
        out->type->user = (UserType *)ut;
        out->owns_ref = true;
        return true;
    }

    const ExternFn *ext = NULL;
    const FreeFn *fn = NULL;
    bool has_resolved_extern_decl = false;
    if (rc->kind == FENG_RESOLVED_CALLABLE_FUNCTION && rc->function_decl) {
        if (rc->function_decl->is_extern) {
            has_resolved_extern_decl = true;
            ext = cg_find_extern_by_decl(cg, rc->function_decl);
            /* Generic extern calls are specialized through the ordinary extern
             * ABI path after resolving/inferencing concrete type arguments.
             * Non-generic externs continue through cg_emit_registered_call. */
            if (ext != NULL && rc->function_decl->as.function_decl.type_param_count > 0U) {
                return cg_emit_generic_extern_call(cg, e, rc->function_decl, ext, out);
            }
        } else {
            fn = cg_find_free_fn_by_decl(cg, rc->function_decl);
            /* G6: check if this is a call to a registered generic function. */
            if (!fn) {
                const GenericFn *gfn = cg_find_generic_fn_by_decl(cg, rc->function_decl);
                if (gfn) return cg_emit_generic_call(cg, e, gfn, out);
            }
        }
    }
    if (ext == NULL && !has_resolved_extern_decl) {
        ext = cg_find_extern_by_name(cg, name.data, name.length);
    }
    if (!fn && !ext) {
        fn = cg_find_free_fn(cg, name.data, name.length);
    }
    return cg_emit_registered_call(cg, e, fn, ext, out);
}

/* Read one static spec field whose open generic declaration selected the
 * address-return ABI. The closed member type may be a scalar, a direct
 * generic parameter, or a descriptor-sized aggregate; in every case the
 * witness getter writes into exact caller-owned storage. The result remains
 * a borrow of the static binding, so this helper deliberately registers no
 * cleanup for the shallow copy written by the getter. */
static bool cg_emit_spec_static_field_address_read(
    CG *cg,
    const UserSpec *spec,
    const UserSpecMember *field,
    const char *generic_descriptor,
    FengToken blame,
    ExprResult *out) {
    char *storage_name;
    const char *out_prefix = "&";

    er_init(out);
    if (cg == NULL || spec == NULL || field == NULL ||
        field->kind != USM_KIND_FIELD || !field->is_static ||
        field->value_abi_kind != CG_CALLABLE_ABI_ADDRESS ||
        generic_descriptor == NULL) {
        return cg_fail(cg,
                       blame,
                       "IE0001", "codegen: invalid static spec field address read");
    }

    storage_name = cg_fresh_temp(cg, "_spec_field");
    if (storage_name == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (field->type->kind == CG_TYPE_GENERIC_PARAM) {
        if (!cg_emit_erased_generic_storage_declaration(
                cg,
                field->type,
                storage_name,
                blame,
                &out->erased_generic_descriptor_c_name,
                &out->erased_generic_size_c_name)) {
            free(storage_name);
            er_free(out);
            return false;
        }
        out->uses_erased_generic_storage = true;
        out->is_storage_address = true;
        out_prefix = "";
    } else if (cg_type_uses_reified_storage(cg, field->type)) {
        if (!cg_emit_reified_storage_declaration(
                cg,
                field->type,
                storage_name,
                blame,
                &out->reified_descriptor_c_name,
                &out->reified_size_c_name)) {
            free(storage_name);
            er_free(out);
            return false;
        }
        out->uses_reified_storage = true;
        out->is_storage_address = true;
        out_prefix = "";
    } else {
        char *storage_type = cg_ctype_dup(field->type);

        if (storage_type == NULL) {
            free(storage_name);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg_emit_current_stmt_line_directive_force(cg);
        buf_append_fmt(cg->cur_body,
                       "    %s %s;\n",
                       storage_type,
                       storage_name);
        free(storage_type);
    }

    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(
        cg->cur_body,
        "    ((const struct %s *)%s->witness)->get_%s(%s%s);\n",
        spec->c_witness_struct_name,
        generic_descriptor,
        field->c_field_name,
        out_prefix,
        storage_name);
    out->c_expr = strdup(storage_name);
    out->type = cgtype_clone(field->type);
    out->owns_ref = false;
    out->is_addressable = true;
    free(storage_name);
    if (out->c_expr == NULL || out->type == NULL) {
        er_free(out);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    return true;
}

/* Borrow one field through an already-evaluated object-form spec receiver.
 * A direct generic parameter obtains the witness from its active descriptor;
 * an ordinary spec value carries the subject and witness together. */
static bool cg_emit_spec_field_borrow(CG *cg,
                                      ExprResult *receiver,
                                      const UserSpec *spec,
                                      const UserSpecMember *field,
                                      const char *generic_descriptor,
                                      FengToken blame,
                                      ExprResult *out) {
    Buf value;
    bool uses_storage_borrow;

    er_init(out);
    if (cg == NULL || receiver == NULL || receiver->type == NULL ||
        spec == NULL || field == NULL || field->kind != USM_KIND_FIELD) {
        return cg_fail(cg,
                       blame,
                       "IE0001", "codegen: invalid spec field receiver");
    }
    if (receiver->type->kind == CG_TYPE_GENERIC_PARAM &&
        field->is_static &&
        field->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        bool ok = cg_emit_spec_static_field_address_read(cg,
                                                         spec,
                                                         field,
                                                         generic_descriptor,
                                                         blame,
                                                         out);

        er_free(receiver);
        return ok;
    }
    uses_storage_borrow = cg_spec_field_uses_storage_borrow(field);

    buf_init(&value);
    if (receiver->type->kind == CG_TYPE_GENERIC_PARAM) {
        char *subject = NULL;

        if (generic_descriptor == NULL) {
            er_free(receiver);
            return cg_fail(
                cg,
                blame,
                "CE0172", "codegen: generic member access requires an object-form spec constraint");
        }
        if (field->is_static) {
            buf_append_fmt(
                &value,
                "((const struct %s *)%s->witness)->get_%s()",
                spec->c_witness_struct_name,
                generic_descriptor,
                field->c_field_name);
        } else {
            subject = cg_generic_witness_subject_expr(
                generic_descriptor, receiver->c_expr);
            if (subject == NULL) {
                buf_free(&value);
                er_free(receiver);
                return false;
            }
            if (uses_storage_borrow) {
                buf_append_fmt(
                    &value,
                    "((const struct %s *)%s->witness)->borrow_%s(%s)",
                    spec->c_witness_struct_name,
                    generic_descriptor,
                    field->c_field_name,
                    subject);
            } else {
                buf_append_fmt(
                    &value,
                    "((const struct %s *)%s->witness)->get_%s(%s)",
                    spec->c_witness_struct_name,
                    generic_descriptor,
                    field->c_field_name,
                    subject);
            }
            free(subject);
        }
    } else if (receiver->type->kind == CG_TYPE_SPEC &&
               receiver->type->user_spec != NULL) {
        if (cg_materialize_to_local(cg, receiver, "_t") == NULL) {
            buf_free(&value);
            er_free(receiver);
            if (!cg->failed) {
                return cg_fail(cg,
                               blame,
                               "IE0001", "codegen: out of memory");
            }
            return false;
        }
        if (uses_storage_borrow) {
            buf_append_fmt(&value,
                           "%s.witness->borrow_%s(%s.subject)",
                           receiver->c_expr,
                           field->c_field_name,
                           receiver->c_expr);
        } else {
            buf_append_fmt(&value,
                           "%s.witness->get_%s(%s.subject)",
                           receiver->c_expr,
                           field->c_field_name,
                           receiver->c_expr);
        }
    } else {
        buf_free(&value);
        er_free(receiver);
        return cg_fail(cg,
                       blame,
                       "IE0001", "codegen: invalid spec field receiver");
    }

    if (uses_storage_borrow &&
        field->type->kind != CG_TYPE_GENERIC_PARAM &&
        !cg_type_uses_reified_storage(cg, field->type)) {
        char *ctype = cg_ctype_dup(field->type);
        Buf dereference;

        if (ctype == NULL) {
            buf_free(&value);
            er_free(receiver);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_init(&dereference);
        buf_append_fmt(&dereference,
                       "(*(%s *)(%s))",
                       ctype,
                       value.data);
        free(ctype);
        buf_free(&value);
        out->c_expr = dereference.data;
    } else {
        out->c_expr = value.data;
    }
    out->type = cgtype_clone(field->type);
    out->owns_ref = false;
    out->is_addressable = uses_storage_borrow;
    out->is_storage_address =
        uses_storage_borrow &&
        (field->type->kind == CG_TYPE_GENERIC_PARAM ||
         cg_type_uses_reified_storage(cg, field->type));
    out->uses_reified_storage =
        uses_storage_borrow &&
        cg_type_uses_reified_storage(cg, field->type);
    if (out->uses_reified_storage) {
        out->reified_descriptor_c_name =
            cg_reified_aggregate_descriptor_expr_dup(cg,
                                                      field->type,
                                                      blame);
    }
    er_free(receiver);
    return out->c_expr != NULL && out->type != NULL &&
           (!out->uses_reified_storage ||
            out->reified_descriptor_c_name != NULL);
}

/* Return whether an immutable field reached through a stable receiver keeps
 * the same managed identity while later subexpressions are evaluated. */
static bool cg_user_field_managed_identity_is_stable(
    const ExprResult *receiver,
    const UserField *field) {
    return receiver != NULL && receiver->managed_identity_is_stable &&
           field != NULL && field->member != NULL &&
           field->member->kind == FENG_TYPE_MEMBER_FIELD &&
           field->member->as.field.mutability == FENG_MUTABILITY_LET;
}

/* Borrow one already-evaluated user field while preserving the receiver's
 * concrete storage authority. Shared generic bodies must use descriptor
 * offsets for every field of a reified layout, including fixed-size fields
 * that happen to follow a descriptor-sized field. */
static bool cg_emit_user_field_borrow(CG *cg,
                                      ExprResult *receiver,
                                      const UserField *field,
                                      FengToken blame,
                                      ExprResult *out) {
    const UserType *owner;

    er_init(out);
    if (cg == NULL || receiver == NULL || receiver->type == NULL ||
        receiver->type->kind != CG_TYPE_OBJECT ||
        receiver->type->user == NULL || field == NULL) {
        return cg_fail(cg,
                       blame,
                       "IE0001", "codegen: invalid user field receiver");
    }
    owner = receiver->type->user;

    if (cg_type_is_value_semantics(receiver->type)) {
        if (cgtype_is_aggregate(receiver->type) && receiver->owns_ref &&
            cg_materialize_to_local(cg, receiver, "_value") == NULL) {
            er_free(receiver);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }

        if (receiver->uses_reified_storage) {
            char *owned_descriptor = NULL;
            const char *descriptor = receiver->reified_descriptor_c_name;
            char *receiver_address;
            char *field_descriptor = NULL;
            size_t field_index = 0U;
            Buf field_address;
            Buf value;

            while (field_index < owner->field_count &&
                   &owner->fields[field_index] != field) {
                ++field_index;
            }
            if (field_index == owner->field_count) {
                er_free(receiver);
                return cg_fail(cg,
                               blame,
                               "IE0001", "codegen: user field is not owned by receiver type");
            }
            if (descriptor == NULL) {
                owned_descriptor = cg_reified_aggregate_descriptor_expr_dup(
                    cg, receiver->type, blame);
                descriptor = owned_descriptor;
            }
            receiver_address = cg_aggregate_result_address_dup(receiver);
            if (receiver_address == NULL || descriptor == NULL) {
                free(owned_descriptor);
                free(receiver_address);
                er_free(receiver);
                return cg_fail(cg,
                               blame,
                               "CE0066", "codegen: reified value receiver has no address storage");
            }

            buf_init(&field_address);
            buf_append_fmt(&field_address,
                           "((char *)%s + %s->reified_field_offsets[%zu])",
                           receiver_address,
                           descriptor,
                           field_index);
            free(receiver_address);
            buf_init(&value);
            if (field->type != NULL &&
                field->type->kind == CG_TYPE_GENERIC_PARAM) {
                buf_append_fmt(&value, "(void *)%s", field_address.data);
            } else if (cg_type_uses_reified_storage(cg, field->type)) {
                buf_append_fmt(&value, "(void *)%s", field_address.data);
                field_descriptor =
                    cg_reified_aggregate_descriptor_expr_dup(cg,
                                                              field->type,
                                                              blame);
            } else {
                char *ctype = cg_ctype_dup(field->type);

                if (ctype == NULL) {
                    buf_free(&value);
                    buf_free(&field_address);
                    free(owned_descriptor);
                    er_free(receiver);
                    return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(&value,
                               "(*(%s *)%s)",
                               ctype,
                               field_address.data);
                free(ctype);
            }
            buf_free(&field_address);

            out->c_expr = value.data;
            out->type = cgtype_clone(field->type);
            out->owns_ref = false;
            out->managed_identity_is_stable =
                cg_user_field_managed_identity_is_stable(receiver, field);
            out->is_addressable = receiver->is_addressable;
            out->is_storage_address =
                field->type != NULL &&
                (field->type->kind == CG_TYPE_GENERIC_PARAM ||
                 cg_type_uses_reified_storage(cg, field->type));
            out->uses_reified_storage =
                cg_type_uses_reified_storage(cg, field->type);
            out->reified_descriptor_c_name = field_descriptor;
            free(owned_descriptor);
            er_free(receiver);
            return out->c_expr != NULL && out->type != NULL &&
                   (!out->uses_reified_storage ||
                    out->reified_descriptor_c_name != NULL);
        }

        {
            Buf value;

            buf_init(&value);
            buf_append_fmt(&value,
                           "(%s).%s",
                           receiver->c_expr,
                           field->c_name);
            out->c_expr = value.data;
        }
        out->type = cgtype_clone(field->type);
        out->owns_ref = false;
        out->managed_identity_is_stable =
            cg_user_field_managed_identity_is_stable(receiver, field);
        out->is_addressable = receiver->is_addressable;
        er_free(receiver);
        return out->c_expr != NULL && out->type != NULL;
    }

    if (cgtype_is_managed(receiver->type) && receiver->owns_ref &&
        cg_materialize_to_local(cg, receiver, "_t") == NULL) {
        er_free(receiver);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (cg_reference_needs_reified_field_layout(cg, receiver->type)) {
        char *descriptor = cg_rtd_expr_for_type(cg, owner, blame);
        char *field_descriptor = NULL;
        size_t field_index = 0U;
        Buf field_address;
        Buf value;

        while (field_index < owner->field_count &&
               &owner->fields[field_index] != field) {
            ++field_index;
        }
        if (descriptor == NULL || field_index == owner->field_count) {
            free(descriptor);
            er_free(receiver);
            if (!cg->failed) {
                return cg_fail(cg,
                               blame,
                               "CE0176", "codegen: reified field index is missing for type '%s'",
                               owner->feng_name);
            }
            return false;
        }

        buf_init(&field_address);
        buf_append_fmt(&field_address,
                       "((char *)%s + %s->reified_field_offsets[%zu])",
                       receiver->c_expr,
                       descriptor,
                       field_index);
        buf_init(&value);
        if (field->type != NULL &&
            field->type->kind == CG_TYPE_GENERIC_PARAM) {
            buf_append_fmt(&value, "(void *)%s", field_address.data);
        } else if (cg_type_uses_reified_storage(cg, field->type)) {
            buf_append_fmt(&value, "(void *)%s", field_address.data);
            field_descriptor =
                cg_reified_aggregate_descriptor_expr_dup(cg,
                                                          field->type,
                                                          blame);
        } else {
            char *ctype = cg_ctype_dup(field->type);

            if (ctype == NULL) {
                buf_free(&value);
                buf_free(&field_address);
                free(descriptor);
                er_free(receiver);
                return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }
            buf_append_fmt(&value,
                           "(*(%s *)%s)",
                           ctype,
                           field_address.data);
            free(ctype);
        }
        buf_free(&field_address);
        free(descriptor);

        out->c_expr = value.data;
        out->type = cgtype_clone(field->type);
        out->owns_ref = false;
        out->managed_identity_is_stable =
            cg_user_field_managed_identity_is_stable(receiver, field);
        out->is_addressable = true;
        out->is_storage_address =
            field->type != NULL &&
            (field->type->kind == CG_TYPE_GENERIC_PARAM ||
             cg_type_uses_reified_storage(cg, field->type));
        out->uses_reified_storage =
            cg_type_uses_reified_storage(cg, field->type);
        out->reified_descriptor_c_name = field_descriptor;
        er_free(receiver);
        return out->c_expr != NULL && out->type != NULL &&
               (!out->uses_reified_storage ||
                out->reified_descriptor_c_name != NULL);
    }

    {
        Buf value;

        buf_init(&value);
        if (field->type != NULL &&
            field->type->kind == CG_TYPE_GENERIC_PARAM) {
            /* Erased generic values are represented by the address of their
             * storage; reads and writes must use the same convention. */
            buf_append_fmt(&value,
                           "(void *)&((%s)->%s)",
                           receiver->c_expr,
                           field->c_name);
        } else {
            buf_append_fmt(&value,
                           "(%s)->%s",
                           receiver->c_expr,
                           field->c_name);
        }
        out->c_expr = value.data;
    }
    out->type = cgtype_clone(field->type);
    out->owns_ref = false;
    out->managed_identity_is_stable =
        cg_user_field_managed_identity_is_stable(receiver, field);
    out->is_addressable = true;
    out->is_storage_address =
        field->type != NULL && field->type->kind == CG_TYPE_GENERIC_PARAM;
    er_free(receiver);
    return out->c_expr != NULL && out->type != NULL;
}

static bool cg_emit_member(CG *cg, const FengExpr *e, ExprResult *out) {
    const FengDecl *enum_decl;
    const FengDecl *imported_binding_decl;

    er_init(out);

    enum_decl = cg_resolve_type_target_enum_decl(cg, e->as.member.object);
    if (enum_decl != NULL) {
        bool found = false;
        size_t ei;
        char *item_c_name;
        Buf b;

        if (!cg_ensure_enum_emitted(cg, enum_decl)) return false;

        for (ei = 0U; ei < enum_decl->as.enum_decl.item_count; ++ei) {
            if (cg_slice_equals(enum_decl->as.enum_decl.items[ei].name,
                                e->as.member.member)) {
                found = true;
                break;
            }
        }
        if (!found) {
            return cg_fail(cg,
                           e->token,
                           "CE0170", "codegen: enum '%.*s' has no item '%.*s'",
                           (int)enum_decl->as.enum_decl.name.length,
                           enum_decl->as.enum_decl.name.data,
                           (int)e->as.member.member.length,
                           e->as.member.member.data);
        }

        item_c_name = cg_enum_item_c_name(cg, enum_decl, e->as.member.member);
        if (item_c_name == NULL) {
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory referencing enum item constant");
        }

        buf_init(&b);
        buf_append_cstr(&b, item_c_name);
        out->c_expr = b.data;
        out->type = cgtype_new_enum(enum_decl);
        out->owns_ref = false;
        free(item_c_name);
        return out->c_expr != NULL && out->type != NULL;
    }

    imported_binding_decl = cg_resolve_imported_module_binding_decl(cg, e);
    if (imported_binding_decl != NULL) {
        return cg_emit_imported_binding_expr(cg, imported_binding_decl, out);
    }

    {
        const UserType *static_target = cg_find_user_type_by_expr_path(cg, e->as.member.object);
        const TypeStaticBinding *binding = static_target != NULL
                                               ? cg_user_type_static_binding(static_target,
                                                                             e->as.member.member.data,
                                                                             e->as.member.member.length)
                                               : NULL;

        if (binding != NULL) {
            if (cg_static_binding_uses_shared_state(cg, static_target)) {
                char *state_name = NULL;

                if (!cg_emit_shared_static_binding_state(cg,
                                                         static_target,
                                                         binding,
                                                         e->token,
                                                         &state_name)) {
                    free(state_name);
                    return false;
                }
                if (binding->type->kind == CG_TYPE_GENERIC_PARAM) {
                    Buf storage;

                    buf_init(&storage);
                    buf_append_fmt(&storage, "%s->storage", state_name);
                    out->c_expr = storage.data;
                } else {
                    char *cty = cg_ctype_dup(binding->type);
                    Buf storage;

                    if (cty == NULL) {
                        free(state_name);
                        return cg_fail(cg, e->token,
                                       "IE0001", "codegen: out of memory");
                    }
                    buf_init(&storage);
                    buf_append_fmt(&storage,
                                   "(*(%s *)%s->storage)",
                                   cty,
                                   state_name);
                    free(cty);
                    out->c_expr = storage.data;
                }
                free(state_name);
                out->type = cgtype_clone(binding->type);
                out->owns_ref = false;
                out->managed_identity_is_stable = !binding->is_var;
                out->is_addressable = true;
                return out->c_expr != NULL && out->type != NULL;
            }
            if (!cg_emit_type_static_binding_ensure_init_call(cg, binding)) {
                return false;
            }
            out->c_expr = strdup(binding->c_name);
            out->type = cgtype_clone(binding->type);
            out->owns_ref = false;
            out->managed_identity_is_stable = !binding->is_var;
            out->is_addressable = true;
            return out->c_expr != NULL && out->type != NULL;
        }
    }

    ExprResult recv;
    if (!cg_emit_expr(cg, e->as.member.object, &recv)) return false;
    if (cg->in_generic_type_method &&
        cg_type_is_current_generic_owner(cg, recv.type) &&
        cg->generic_type_method_decl != NULL &&
        cg->generic_type_method_decl->kind == FENG_DECL_TYPE) {
        const FengDecl *owner = cg->generic_type_method_decl;
        const FengTypeMember *field_member = NULL;
        size_t field_index = 0;

        for (size_t i = 0; i < owner->as.type_decl.member_count; ++i) {
            const FengTypeMember *member = owner->as.type_decl.members[i];
            if (member->kind != FENG_TYPE_MEMBER_FIELD) continue;
            if (member->as.field.name.length == e->as.member.member.length &&
                memcmp(member->as.field.name.data,
                       e->as.member.member.data,
                       e->as.member.member.length) == 0) {
                field_member = member;
                break;
            }
            field_index++;
        }
        if (field_member == NULL) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0171", "codegen: generic type '%.*s' has no field '%.*s'",
                (int)owner->as.type_decl.name.length,
                owner->as.type_decl.name.data,
                (int)e->as.member.member.length,
                e->as.member.member.data);
        }

        CGType *field_type = NULL;
        if (!cg_resolve_user_field_type(cg,
                                        recv.type->user,
                                        field_member,
                                        &field_type)) {
            er_free(&recv);
            return false;
        }

        Buf addr; buf_init(&addr);
        buf_append_fmt(&addr, "((char *)%s + %s[%zu])",
                       recv.c_expr,
                       cg->generic_type_method_field_offsets_name,
                       field_index);
        if (field_type->kind == CG_TYPE_GENERIC_PARAM ||
            cg_type_uses_reified_storage(cg, field_type)) {
            out->c_expr = addr.data;
        } else {
            char *cty = cg_ctype_dup(field_type);
            Buf value; buf_init(&value);
            buf_append_fmt(&value, "(*(%s *)(%s))", cty, addr.data);
            free(cty);
            buf_free(&addr);
            out->c_expr = value.data;
        }
        out->type = field_type;
        out->owns_ref = false;
        out->managed_identity_is_stable =
            recv.managed_identity_is_stable &&
            field_member->as.field.mutability == FENG_MUTABILITY_LET;
        out->is_addressable = true;
        out->is_storage_address =
            field_type->kind == CG_TYPE_GENERIC_PARAM ||
            cg_type_uses_reified_storage(cg, field_type);
        out->uses_reified_storage =
            cg_type_uses_reified_storage(cg, field_type);
        if (out->uses_reified_storage) {
            out->reified_descriptor_c_name =
                cg_reified_aggregate_descriptor_expr_dup(cg,
                                                          field_type,
                                                          e->token);
        }
        er_free(&recv);
        return out->c_expr && out->type &&
               (!out->uses_reified_storage ||
                out->reified_descriptor_c_name != NULL);
    }
    if (recv.type->kind == CG_TYPE_GENERIC_PARAM) {
        size_t gp_idx = recv.type->generic_param_index;
        const UserSpec *us = cg_generic_param_constraint_spec(cg, gp_idx);
        const char *desc_name = cg_generic_param_desc_name(cg, gp_idx);
        if (!us || !desc_name) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0172", "codegen: generic member access requires an object-form spec constraint");
        }
        const UserSpecMember *sm = cg_user_spec_field_member_for_access(
            cg, us, e, /*fallback_static=*/false);
        if (!sm || sm->kind != USM_KIND_FIELD) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0173", "codegen: spec '%s' has no field '%.*s'",
                us->feng_name,
                (int)e->as.member.member.length, e->as.member.member.data);
        }
        return cg_emit_spec_field_borrow(cg,
                                         &recv,
                                         us,
                                         sm,
                                         desc_name,
                                         e->token,
                                         out);
    }
    if (recv.type->kind == CG_TYPE_SPEC && recv.type->user_spec) {
        /* Step 4b-β — spec field access via witness getter. */
        const UserSpec *us = recv.type->user_spec;
        const UserSpecMember *sm = cg_user_spec_field_member_for_access(
            cg, us, e, /*fallback_static=*/false);
        if (!sm || sm->kind != USM_KIND_FIELD) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0173", "codegen: spec '%s' has no field '%.*s'",
                us->feng_name,
                (int)e->as.member.member.length, e->as.member.member.data);
        }
        return cg_emit_spec_field_borrow(cg,
                                         &recv,
                                         us,
                                         sm,
                                         NULL,
                                         e->token,
                                         out);
    }
    if (cg_type_is_value_semantics(recv.type)) {
        const UserType *ut = recv.type->user;
        const UserField *uf = cg_user_type_field(ut,
            e->as.member.member.data, e->as.member.member.length);
        if (!uf) {
            er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0174", "codegen: value type '%s' has no field '%.*s'",
                ut->feng_name,
                (int)e->as.member.member.length,
                e->as.member.member.data);
        }
        return cg_emit_user_field_borrow(cg, &recv, uf, e->token, out);
    }
    if (recv.type->kind != CG_TYPE_OBJECT || !recv.type->user) {
        er_free(&recv);
        return cg_fail(cg, e->token,
            "CE0175", "codegen: member access on non-object value");
    }
    const UserType *ut = recv.type->user;
    const UserField *uf = cg_user_type_field(ut,
        e->as.member.member.data, e->as.member.member.length);
    if (!uf) {
        er_free(&recv);
        return cg_fail(cg, e->token,
            "CE0176", "codegen: type '%s' has no field '%.*s'",
            ut->feng_name,
            (int)e->as.member.member.length, e->as.member.member.data);
    }
    return cg_emit_user_field_borrow(cg, &recv, uf, e->token, out);
}

static size_t cg_expr_path_segment_count(const FengExpr *expr) {
    if (expr == NULL) {
        return 0U;
    }
    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
            return 1U;
        case FENG_EXPR_MEMBER: {
            size_t object_count = cg_expr_path_segment_count(expr->as.member.object);

            return object_count == 0U ? 0U : object_count + 1U;
        }
        default:
            return 0U;
    }
}

static bool cg_expr_collect_path_segments(const FengExpr *expr,
                                          FengSlice *segments,
                                          size_t segment_count,
                                          size_t *next_index) {
    if (expr == NULL || segments == NULL || next_index == NULL ||
        *next_index >= segment_count) {
        return false;
    }
    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
            segments[(*next_index)++] = expr->as.identifier;
            return true;
        case FENG_EXPR_MEMBER:
            if (!cg_expr_collect_path_segments(expr->as.member.object,
                                               segments,
                                               segment_count,
                                               next_index) ||
                *next_index >= segment_count) {
                return false;
            }
            segments[(*next_index)++] = expr->as.member.member;
            return true;
        default:
            return false;
    }
}

static FengSlice *cg_expr_path_segments_alloc(const FengExpr *expr, size_t *out_count) {
    size_t count = cg_expr_path_segment_count(expr);
    FengSlice *segments;
    size_t next_index = 0U;

    if (out_count != NULL) {
        *out_count = 0U;
    }
    if (count == 0U) {
        return NULL;
    }

    segments = (FengSlice *)calloc(count, sizeof(*segments));
    if (segments == NULL) {
        return NULL;
    }
    if (!cg_expr_collect_path_segments(expr, segments, count, &next_index) ||
        next_index != count) {
        free(segments);
        return NULL;
    }

    if (out_count != NULL) {
        *out_count = count;
    }
    return segments;
}

static const UserType *cg_find_user_type_by_expr_path(CG *cg, const FengExpr *expr) {
    size_t segment_count = 0U;
    const FengExpr *path_expr = expr;
    FengSlice *segments;
    const UserType *user_type = NULL;

    if (expr != NULL && expr->kind == FENG_EXPR_GENERIC_TARGET) {
        path_expr = expr->as.generic_target.target;
    }

    segments = cg_expr_path_segments_alloc(path_expr, &segment_count);

    if (segments == NULL || segment_count == 0U) {
        free(segments);
        return NULL;
    }

    if (expr != NULL && expr->kind == FENG_EXPR_GENERIC_TARGET) {
        FengTypeRef ref;
        CGType *resolved = NULL;

        memset(&ref, 0, sizeof(ref));
        ref.token = expr->token;
        ref.kind = FENG_TYPE_REF_NAMED;
        ref.as.named.segments = segments;
        ref.as.named.segment_count = segment_count;
        ref.as.named.type_args = expr->as.generic_target.type_args;
        ref.as.named.type_arg_count = expr->as.generic_target.type_arg_count;
        if (cg_resolve_type(cg, &ref, &expr->token, &resolved) &&
            resolved != NULL && resolved->kind == CG_TYPE_OBJECT) {
            user_type = resolved->user;
        }
        cgtype_free(resolved);
    } else if (segment_count == 1U) {
        user_type = cg_find_user_type(cg, segments[0].data, segments[0].length);
    } else {
        FengTypeRef ref;

        memset(&ref, 0, sizeof(ref));
        ref.token = expr->token;
        ref.kind = FENG_TYPE_REF_NAMED;
        ref.as.named.segments = segments;
        ref.as.named.segment_count = segment_count;
        user_type = cg_find_user_type_by_ref(cg, &ref);
    }

    free(segments);
    return user_type;
}

static bool cg_resolve_object_literal_target_user_type(CG *cg,
                                                       const FengExpr *target,
                                                       const UserType **out) {
    if (out != NULL) *out = NULL;
    if (target == NULL) {
        return cg_fail(cg, (FengToken){0},
            "CE0177", "codegen: missing object literal target");
    }

    if (target->kind == FENG_EXPR_IDENTIFIER || target->kind == FENG_EXPR_MEMBER) {
        size_t segment_count = 0U;
        FengSlice *segments = cg_expr_path_segments_alloc(target, &segment_count);
        FengSlice tn = segment_count > 0U
            ? segments[segment_count - 1U]
            : (FengSlice){target->token.lexeme, target->token.length};
        const UserType *ut = cg_find_user_type_by_expr_path(cg, target);

        if (!ut) {
            free(segments);
            return cg_fail(cg, target->token,
                "CE0178", "codegen: unknown type '%.*s' in object literal",
                (int)tn.length, tn.data);
        }
        free(segments);
        if (out != NULL) *out = ut;
        return true;
    }

    if (target->kind == FENG_EXPR_CALL && target->as.call.callee != NULL &&
        (target->as.call.callee->kind == FENG_EXPR_IDENTIFIER ||
         target->as.call.callee->kind == FENG_EXPR_MEMBER)) {
        const FengExpr *callee = target->as.call.callee;
        size_t segment_count = 0U;
        FengSlice *segments = cg_expr_path_segments_alloc(callee, &segment_count);
        FengSlice tn = segment_count > 0U
            ? segments[segment_count - 1U]
            : (FengSlice){callee->token.lexeme, callee->token.length};
        const FengResolvedCallable *rc = &target->as.call.resolved_callable;

        if (rc->kind == FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR &&
            rc->owner_type_decl != NULL &&
            rc->owner_type_decl->kind == FENG_DECL_TYPE &&
            rc->owner_type_decl->as.type_decl.type_param_count > 0U) {
            FengTypeRef **lookup_type_args = target->as.call.explicit_type_args;
            FengTypeRef **owned_type_args = NULL;
            if (cg->current_user_fit != NULL &&
                cg->current_user_fit->target != NULL &&
                cg->current_user_fit->target->is_generic_instance &&
                target->as.call.explicit_type_arg_count > 0U) {
                const FengDecl *fit_origin = cg->current_user_fit->target->generic_origin_decl;

                if (fit_origin != NULL && fit_origin->kind == FENG_DECL_TYPE &&
                    fit_origin->as.type_decl.type_param_count > 0U) {
                    owned_type_args = calloc(target->as.call.explicit_type_arg_count,
                                             sizeof(*owned_type_args));
                    if (owned_type_args == NULL) {
                        free(segments);
                        return cg_fail(cg, target->token, "IE0001", "codegen: out of memory");
                    }
                    for (size_t i = 0U; i < target->as.call.explicit_type_arg_count; ++i) {
                        owned_type_args[i] = cg_type_ref_substitute(
                            target->as.call.explicit_type_args[i],
                            fit_origin->as.type_decl.type_params,
                            fit_origin->as.type_decl.type_param_count,
                            cg->current_user_fit->target->generic_type_args);
                        if (owned_type_args[i] == NULL) {
                            for (size_t j = 0U; j < i; ++j) cg_type_ref_free(owned_type_args[j]);
                            free(owned_type_args);
                            free(segments);
                            return false;
                        }
                    }
                    lookup_type_args = owned_type_args;
                }
            }
            UserType *ut = cg_find_generic_instance_user_type_with_active_context(
                cg,
                rc->owner_type_decl,
                lookup_type_args,
                target->as.call.explicit_type_arg_count);
            if (ut == NULL) {
                ut = cg_find_generic_instance_user_type(cg,
                                                        rc->owner_type_decl,
                                                        lookup_type_args,
                                                        target->as.call.explicit_type_arg_count);
            }
            if (owned_type_args != NULL) {
                for (size_t i = 0U; i < target->as.call.explicit_type_arg_count; ++i) {
                    cg_type_ref_free(owned_type_args[i]);
                }
                free(owned_type_args);
            }
            if (ut == NULL) {
                free(segments);
                return cg_fail(cg, target->token,
                    "CE0179", "codegen: generic type object literal instance for '%.*s' was not registered",
                    (int)tn.length, tn.data);
            }
            free(segments);
            if (out != NULL) *out = ut;
            return true;
        }

        {
            const UserType *ut = cg_find_user_type_by_expr_path(cg, callee);
            if (!ut) {
                free(segments);
                return cg_fail(cg, target->token,
                    "CE0178", "codegen: unknown type '%.*s' in object literal",
                    (int)tn.length, tn.data);
            }
            free(segments);
            if (out != NULL) *out = ut;
            return true;
        }
    }

    return cg_fail(cg, target->token,
        "CE0180", "codegen: only direct type constructor targets are supported for object literals");
}

static bool cg_emit_object_literal(CG *cg, const FengExpr *e, ExprResult *out) {
    const UserType *ut = NULL;
    const UserMethod *ctor = NULL;
    const FengExpr *target_call = NULL;

    er_init(out);
    if (!cg_resolve_object_literal_target_user_type(cg,
                                                   e->as.object_literal.target,
                                                   &ut)) {
        return false;
    }

    if (e->as.object_literal.resolved_constructor != NULL) {
        ctor = cg_user_type_constructor_by_member(
            ut, e->as.object_literal.resolved_constructor);
        if (ctor == NULL) {
            return cg_fail(cg, e->token,
                "CE0169", "codegen: resolved constructor for type '%s' was not registered",
                ut->feng_name);
        }
    }

    if (e->as.object_literal.target != NULL &&
        e->as.object_literal.target->kind == FENG_EXPR_CALL) {
        target_call = e->as.object_literal.target;
        if (target_call->as.call.arg_count != 0U && ctor == NULL) {
            return cg_fail(cg, target_call->token,
                "CE0076", "codegen: constructor arguments require a resolved user-defined constructor");
        }
    }
    /* @value type: stack-allocate + member init + constructor invoke. */
    if (cg_user_type_is_value(ut)) {
        char *obj_ptr_expr = NULL;
        ExprResult ctor_result;

        if (!cg_emit_value_type_construction(cg, ut, ctor,
                                             target_call != NULL
                                                 ? target_call->as.call.args : NULL,
                                             target_call != NULL
                                                 ? target_call->as.call.arg_count : 0U,
                                             e->token,
                                             &ctor_result)) {
            return false;
        }
        /* Preserve the construction result's actual address form.  A
         * descriptor-sized value is already represented by a storage
         * address, while a fixed-layout value needs the address of its C
         * local. */
        if (ctor_result.is_storage_address) {
            obj_ptr_expr = strdup(ctor_result.c_expr);
        } else {
            Buf pe;

            buf_init(&pe);
            buf_append_fmt(&pe, "(&%s)", ctor_result.c_expr);
            obj_ptr_expr = pe.data;
        }
        if (obj_ptr_expr == NULL) {
            er_free(&ctor_result);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }

        /* Track which fields are assigned so we can detect missing initialisers. */
        bool *assigned = ut->field_count
                             ? calloc(ut->field_count, sizeof *assigned)
                             : NULL;
        if (ut->field_count && !assigned) {
            free(obj_ptr_expr);
            er_free(&ctor_result);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        for (size_t i = 0; i < e->as.object_literal.field_count; i++) {
            const FengObjectFieldInit *fi = &e->as.object_literal.fields[i];
            size_t idx = (size_t)-1;
            char *field_offsets_expr = NULL;
            for (size_t k = 0; k < ut->field_count; k++) {
                if (strlen(ut->fields[k].feng_name) == fi->name.length &&
                    memcmp(ut->fields[k].feng_name, fi->name.data, fi->name.length) == 0) {
                    idx = k; break;
                }
            }
            if (idx == (size_t)-1) {
                free(assigned); free(obj_ptr_expr); er_free(&ctor_result);
                return cg_fail(cg, fi->token,
                    "CE0176", "codegen: type '%s' has no field '%.*s'",
                    ut->feng_name, (int)fi->name.length, fi->name.data);
            }
            if (assigned[idx]) {
                free(assigned); free(obj_ptr_expr); er_free(&ctor_result);
                return cg_fail(cg, fi->token,
                    "CE0181", "codegen: duplicate field '%s' in object literal",
                    ut->fields[idx].feng_name);
            }
            assigned[idx] = true;
            ExprResult v;
            const UserField *uf = &ut->fields[idx];
            if (!cg_emit_expr_for_expected_type(cg, fi->value, uf->type, &v)) {
                free(assigned); free(obj_ptr_expr); er_free(&ctor_result);
                return false;
            }
            if (ctor_result.uses_reified_storage &&
                ctor_result.reified_descriptor_c_name != NULL) {
                Buf offsets;

                buf_init(&offsets);
                buf_append_fmt(&offsets,
                               "%s->reified_field_offsets",
                               ctor_result.reified_descriptor_c_name);
                field_offsets_expr = offsets.data;
            }
            if (!cg_emit_user_field_value_store_with_offsets(
                    cg,
                    obj_ptr_expr,
                    uf,
                    field_offsets_expr,
                    idx,
                    &v,
                    fi->token,
                    true)) {
                free(field_offsets_expr);
                er_free(&v);
                free(assigned); free(obj_ptr_expr); er_free(&ctor_result);
                return false;
            }
            free(field_offsets_expr);
            er_free(&v);
        }
        free(assigned);
        free(obj_ptr_expr);

        /* Transfer the complete representation contract, including dynamic
         * aggregate descriptor/size authority. */
        *out = ctor_result;
        return true;
    }

    /* Allocate, then assign each field. We open an inline statement block in
     * the body to compute argument expressions and then reference the result.
     * Since we need a single C expression for ExprResult, we hoist the alloc
     * + assignments into a fresh temp via cg->cur_body and return the temp
     * as the c_expr. */
    char *tmp = cg_fresh_temp(cg, "_obj");
    if (!tmp) return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    {
        const char *used_rtd = NULL;
        if (cg->generic_type_method_rtd_count > 0U &&
            ut->is_generic_instance && ut->generic_origin_decl != NULL) {
            for (size_t ri = 0; ri < cg->generic_type_method_rtd_count; ri++) {
                if (cg->generic_type_method_rtd_descs[ri] != NULL &&
                    strcmp(ut->c_desc_name,
                           cg->generic_type_method_rtd_descs[ri]) == 0) {
                    const char *src = cg->generic_type_method_rtd_via_desc
                                          ? "_desc" : "_td";
                    buf_append_fmt(cg->cur_body,
                        "    struct %s *%s = (struct %s *)feng_object_new("
                        "%s->reified_type_deps[%zu]);\n",
                        ut->c_struct_name, tmp,
                        ut->c_struct_name, src, ri);
                    used_rtd = src;
                    break;
                }
            }
        }
        if (used_rtd == NULL) {
            char *obj_init = cg_user_type_raw_object_new_expr(ut);
            if (obj_init == NULL) {
                free(tmp);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            buf_append_fmt(cg->cur_body,
                "    struct %s *%s = %s;\n",
                ut->c_struct_name, tmp, obj_init);
            free(obj_init);
        }
    }

    if (!cg_emit_construction_member_initializers(
            cg, ut, ctor, tmp, e->token)) {
        free(tmp);
        return false;
    }

    if (ctor != NULL) {
        if (!cg_emit_constructor_invoke(cg,
                                        target_call != NULL
                                            ? target_call->as.call.args : NULL,
                                        target_call != NULL
                                            ? target_call->as.call.arg_count : 0U,
                                        ut,
                                        ctor,
                                        tmp,
                                        NULL,
                                        target_call != NULL
                                            ? target_call->token : e->token)) {
            free(tmp);
            return false;
        }
    }

    /* Track which fields are assigned so we can detect missing initialisers. */
    bool *assigned = ut->field_count ? calloc(ut->field_count, sizeof *assigned) : NULL;
    if (ut->field_count && !assigned) {
        free(tmp);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0; i < e->as.object_literal.field_count; i++) {
        const FengObjectFieldInit *fi = &e->as.object_literal.fields[i];
        size_t idx = (size_t)-1;
        for (size_t k = 0; k < ut->field_count; k++) {
            if (strlen(ut->fields[k].feng_name) == fi->name.length &&
                memcmp(ut->fields[k].feng_name, fi->name.data, fi->name.length) == 0) {
                idx = k; break;
            }
        }
        if (idx == (size_t)-1) {
            free(assigned); free(tmp);
            return cg_fail(cg, fi->token,
                "CE0176", "codegen: type '%s' has no field '%.*s'",
                ut->feng_name, (int)fi->name.length, fi->name.data);
        }
        if (assigned[idx]) {
            free(assigned); free(tmp);
            return cg_fail(cg, fi->token,
                "CE0181", "codegen: duplicate field '%s' in object literal",
                ut->fields[idx].feng_name);
        }
        assigned[idx] = true;
        ExprResult v;
        const UserField *uf = &ut->fields[idx];
        if (!cg_emit_expr_for_expected_type(cg, fi->value, uf->type, &v)) {
            free(assigned); free(tmp); return false;
        }
        if (!cg_emit_user_field_value_store(cg, tmp, uf, &v, fi->token, true)) {
            er_free(&v);
            free(assigned); free(tmp);
            return false;
        }
        er_free(&v);
    }
    free(assigned);

    out->c_expr = strdup(tmp);
    out->type = cgtype_new(CG_TYPE_OBJECT);
    if (!out->c_expr || !out->type) { free(tmp); return false; }
    out->type->user = ut;
    out->owns_ref = true;
    free(tmp);
    return true;
}

/* Returns the FengTypeDescriptor C expression for an array element type, or
 * the literal "NULL" if no descriptor is meaningful (descriptor is purely
 * diagnostic in the runtime). Caller-frees via free(). */
static char *cg_array_element_descriptor(const CGType *elem) {
    Buf b; buf_init(&b);
    if (!elem) { buf_append_cstr(&b, "NULL"); return b.data; }
    switch (elem->kind) {
        case CG_TYPE_STRING: buf_append_cstr(&b, "&feng_string_descriptor"); break;
        case CG_TYPE_ARRAY:  buf_append_cstr(&b, "&feng_array_descriptor"); break;
        case CG_TYPE_OBJECT:
            if (cg_type_is_value_semantics(elem)) {
                buf_append_cstr(&b, "NULL");
            } else if (elem->user && elem->user->c_desc_name != NULL) {
                buf_append_fmt(&b, "&%s", elem->user->c_desc_name);
            } else {
                buf_append_cstr(&b, "NULL");
            }
            break;
        case CG_TYPE_CALLABLE:
            if (elem->user_spec && elem->user_spec->c_closure_desc_name) {
                buf_append_fmt(&b, "&%s", elem->user_spec->c_closure_desc_name);
            } else {
                buf_append_cstr(&b, "NULL");
            }
            break;
        default: buf_append_cstr(&b, "NULL"); break;
    }
    return b.data;
}

static bool cg_types_equal(const CGType *a, const CGType *b) {
    if (!a || !b) return false;
    if (a->kind != b->kind) return false;
    if (a->kind == CG_TYPE_OBJECT) return a->user == b->user;
    if (a->kind == CG_TYPE_CALLABLE) return a->user_spec == b->user_spec;
    if (a->kind == CG_TYPE_POINTER) return cg_types_equal(a->element, b->element);
    if (a->kind == CG_TYPE_ARRAY) return cg_types_equal(a->element, b->element);
    return true;
}

static bool cg_emit_array_literal_typed(CG *cg, const FengExpr *e,
                                        const CGType *expected_elem,
                                        ExprResult *out) {
    er_init(out);
    if (e->as.array_literal.count == 0) {
        if (expected_elem == NULL) {
            return cg_fail(cg, e->token,
                "CE0182", "codegen: empty array literal needs an explicit element type");
        }

        CGType *elem = cgtype_clone(expected_elem);
        char *arr_tmp = cg_fresh_temp(cg, "_arr");
        char *elem_cty = cg_ctype_dup(elem);
        char *desc_expr = cg_array_element_descriptor(elem);
        if (elem == NULL || arr_tmp == NULL || elem_cty == NULL || desc_expr == NULL) {
            cgtype_free(elem);
            free(arr_tmp); free(elem_cty); free(desc_expr);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }

        bool elem_managed = cgtype_is_managed(elem);
        bool elem_aggregate = cgtype_is_aggregate(elem);
        const char *agg_desc = elem_aggregate ? cg_aggregate_desc_name(elem) : NULL;
        if (elem_aggregate && agg_desc == NULL) {
            cgtype_free(elem);
            free(arr_tmp); free(elem_cty); free(desc_expr);
            return cg_fail(cg, e->token,
                "CE0183", "codegen: missing aggregate descriptor for spec array element");
        }

        if (elem_aggregate) {
            size_t rad_idx;
            if (cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
                buf_append_fmt(cg->cur_body,
                    "    FengArray *%s = feng_array_new_kinded("
                    "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, %s->reified_agg_deps[%zu], "
                    "NULL, %s->reified_agg_deps[%zu]->size, (size_t)0);\n",
                    arr_tmp, rad_src, rad_idx, rad_src, rad_idx);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    FengArray *%s = feng_array_new_kinded("
                    "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, &%s, NULL, sizeof(%s), (size_t)0);\n",
                    arr_tmp, agg_desc, elem_cty);
            }
        } else if (elem->kind == CG_TYPE_GENERIC_PARAM) {
            const char *desc = cg_generic_param_desc_name(cg, elem->generic_param_index);
            if (desc == NULL) {
                cgtype_free(elem);
                free(arr_tmp); free(elem_cty); free(desc_expr);
                return cg_fail(cg, e->token,
                    "CE0184", "codegen: generic empty array literal requires an active generic descriptor");
            }
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "%s->kind, (%s->kind == FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS ? feng_generic_aggregate_descriptor(%s) : NULL), NULL, feng_generic_value_size(%s), (size_t)0);\n",
                arr_tmp, desc, desc, desc, desc);
        } else {
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new(%s, sizeof(%s), %s, (size_t)0);\n",
                arr_tmp, desc_expr, elem_cty, elem_managed ? "true" : "false");
        }
        free(elem_cty); free(desc_expr);

        out->c_expr = strdup(arr_tmp);
        free(arr_tmp);
        out->type = cgtype_new(CG_TYPE_ARRAY);
        if (!out->c_expr || !out->type) { cgtype_free(elem); return false; }
        out->type->element = elem;
        out->owns_ref = true;
        return true;
    }
    /* Evaluate every element and ensure the inferred element type is
     * uniform. We materialize +1 owners up-front so they are released
     * exactly once after the slot writes complete. */
    size_t n = e->as.array_literal.count;
    ExprResult *items = calloc(n, sizeof *items);
    if (!items) return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    /* When narrowing into a nested array element, recurse with the inner
     * element type. Otherwise emit each item with the default rules. */
    bool nested_narrow = (expected_elem != NULL &&
                          expected_elem->kind == CG_TYPE_ARRAY &&
                          expected_elem->element != NULL);
    for (size_t i = 0; i < n; i++) {
        const FengExpr *item_expr = e->as.array_literal.items[i];
        bool ok;
        if (nested_narrow && item_expr->kind == FENG_EXPR_ARRAY_LITERAL) {
            ok = cg_emit_array_literal_typed(cg, item_expr,
                                             expected_elem->element, &items[i]);
        } else {
            ok = cg_emit_expr(cg, item_expr, &items[i]);
        }
        if (!ok) {
            for (size_t k = 0; k < i; k++) er_free(&items[k]);
            free(items); return false;
        }
        if (i > 0 && !cg_types_equal(items[0].type, items[i].type)) {
            for (size_t k = 0; k <= i; k++) er_free(&items[k]);
            free(items);
            return cg_fail(cg, e->as.array_literal.items[i]->token,
                "CE0185", "codegen: heterogeneous array literal (all elements must share a type)");
        }
        if (cgtype_is_managed(items[i].type) && items[i].owns_ref) {
            cg_materialize_to_local(cg, &items[i], "_t");
        } else if (cgtype_is_aggregate(items[i].type)) {
            /* Aggregate sources must be addressable for the pointer-based
             * slot write; owned results additionally need scope cleanup. */
            if (!cg_prepare_aggregate_assign_source(cg, &items[i], "_t")) {
                for (size_t k = 0; k <= i; ++k) er_free(&items[k]);
                free(items);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
        }
    }
    /* Choose the slot type. If a non-array narrowing target was supplied
     * (e.g. expected i32 but items are i64 numeric literals), the slot
     * uses expected_elem so that allocation size and read access agree. */
    CGType *elem;
    if (expected_elem != NULL && !nested_narrow &&
        cgtype_is_integer(expected_elem->kind) &&
        cgtype_is_integer(items[0].type->kind)) {
        elem = cgtype_clone(expected_elem);
    } else if (nested_narrow) {
        /* Items already match expected_elem after recursive emit. */
        elem = cgtype_clone(items[0].type);
    } else {
        elem = cgtype_clone(items[0].type);
    }
    if (!elem) {
        for (size_t k = 0; k < n; k++) er_free(&items[k]);
        free(items);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    char *arr_tmp = cg_fresh_temp(cg, "_arr");
    char *slots_tmp = cg_fresh_temp(cg, "_slots");
    char *elem_cty = cg_ctype_dup(elem);
    char *desc_expr = cg_array_element_descriptor(elem);
    if (!arr_tmp || !slots_tmp || !elem_cty || !desc_expr) {
        free(arr_tmp); free(slots_tmp); free(elem_cty); free(desc_expr);
        cgtype_free(elem);
        for (size_t k = 0; k < n; k++) er_free(&items[k]);
        free(items);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    bool elem_managed = cgtype_is_managed(elem);
    bool elem_aggregate = cgtype_is_aggregate(elem);
    const char *agg_desc = elem_aggregate ? cg_aggregate_desc_name(elem) : NULL;
    if (elem_aggregate && agg_desc == NULL) {
        free(arr_tmp); free(slots_tmp); free(elem_cty); free(desc_expr);
        cgtype_free(elem);
        for (size_t k = 0; k < n; k++) er_free(&items[k]);
        free(items);
        return cg_fail(cg, e->token,
            "CE0183", "codegen: missing aggregate descriptor for spec array element");
    }
    if (elem_aggregate) {
        /* Step 4b-γ §9.6 — aggregate-element arrays must use the kinded
         * factory so the cycle collector walks each element's managed
         * slots and so default_init seeds every slot before assignment. */
        size_t rad_idx;
        if (cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
            const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, %s->reified_agg_deps[%zu], "
                "NULL, %s->reified_agg_deps[%zu]->size, (size_t)%zu);\n",
                arr_tmp, rad_src, rad_idx, rad_src, rad_idx, n);
        } else {
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, &%s, NULL, sizeof(%s), (size_t)%zu);\n",
                arr_tmp, agg_desc, elem_cty, n);
        }
    } else {
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new(%s, sizeof(%s), %s, (size_t)%zu);\n",
            arr_tmp, desc_expr, elem_cty, elem_managed ? "true" : "false", n);
    }
    bool literal_has_rad = false;
    size_t literal_rad_idx = 0;
    if (elem_aggregate) {
        literal_has_rad = cg_lookup_reified_agg_dep_index(cg, agg_desc, &literal_rad_idx);
    }
    if (literal_has_rad) {
        buf_append_fmt(cg->cur_body,
            "    char *%s = (char *)feng_array_data(%s);\n",
            slots_tmp, arr_tmp);
    } else {
        buf_append_fmt(cg->cur_body,
            "    %s *%s = (%s *)feng_array_data(%s);\n",
            elem_cty, slots_tmp, elem_cty, arr_tmp);
    }
    for (size_t i = 0; i < n; i++) {
        if (elem_aggregate) {
            char *source_address =
                cg_aggregate_result_address_dup(&items[i]);

            if (source_address == NULL) {
                free(slots_tmp); free(elem_cty); free(desc_expr);
                cgtype_free(elem);
                for (size_t k = 0; k < n; k++) er_free(&items[k]);
                free(items); free(arr_tmp);
                return cg_fail(cg, e->token,
                    "CE0183", "codegen: array aggregate source has no address");
            }
            /* feng_aggregate_assign releases the default-init'd slot (which
             * carries +1 from feng_array_new_kinded) and retains the new
             * value's managed slots — so both owns_ref temps and borrowed
             * sources arrive in the slot with the correct refcount. The
             * source temp's eventual cleanup balances the local +1. */
            if (literal_has_rad) {
                const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
                buf_append_fmt(cg->cur_body,
                    "    feng_aggregate_assign("
                    "(void *)(%s + %zu * %s->reified_agg_deps[%zu]->size), "
                    "%s, %s->reified_agg_deps[%zu]);\n",
                    slots_tmp, i, rad_src, literal_rad_idx,
                    source_address, rad_src, literal_rad_idx);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_aggregate_assign(&%s[%zu], %s, &%s);\n",
                    slots_tmp, i, source_address, agg_desc);
            }
            free(source_address);
        } else if (elem_managed) {
            /* Slots own +1 each: retain (items already materialised). */
            buf_append_fmt(cg->cur_body,
                "    %s[%zu] = %s; feng_retain(%s[%zu]);\n",
                slots_tmp, i, items[i].c_expr, slots_tmp, i);
        } else {
            if (cgtype_is_by_value_struct(elem)) {
                buf_append_fmt(cg->cur_body,
                    "    %s[%zu] = %s;\n",
                    slots_tmp, i, items[i].c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    %s[%zu] = (%s)(%s);\n",
                    slots_tmp, i, elem_cty, items[i].c_expr);
            }
        }
    }
    free(slots_tmp); free(elem_cty); free(desc_expr);
    for (size_t k = 0; k < n; k++) er_free(&items[k]);
    free(items);

    out->c_expr = strdup(arr_tmp);
    free(arr_tmp);
    out->type = cgtype_new(CG_TYPE_ARRAY);
    if (!out->c_expr || !out->type) { cgtype_free(elem); return false; }
    out->type->element = elem;
    out->owns_ref = true;
    return true;
}

static bool cg_emit_array_literal(CG *cg, const FengExpr *e, ExprResult *out) {
    return cg_emit_array_literal_typed(cg, e, NULL, out);
}

static bool cg_emit_array_new(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    /* Resolve element type. */
    CGType *elem = NULL;
    if (!cg_resolve_type(cg, e->as.array_new.element_type, &e->token, &elem)) return false;

    /* Emit size expression. */
    ExprResult size_res;
    if (!cg_emit_expr(cg, e->as.array_new.size, &size_res)) {
        cgtype_free(elem);
        return false;
    }
    /* Materialise size into a size_t local so it is evaluated once. */
    char *size_tmp = cg_fresh_temp(cg, "_n");
    if (!size_tmp) {
        er_free(&size_res); cgtype_free(elem);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    buf_append_fmt(cg->cur_body,
        "    size_t %s = (size_t)(%s);\n", size_tmp, size_res.c_expr);
    er_free(&size_res);

    char *arr_tmp  = cg_fresh_temp(cg, "_arr");
    char *elem_cty = cg_ctype_dup(elem);
    char *desc_expr = cg_array_element_descriptor(elem);
    if (!arr_tmp || !elem_cty || !desc_expr) {
        free(size_tmp); free(arr_tmp); free(elem_cty); free(desc_expr);
        cgtype_free(elem);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    bool elem_managed   = cgtype_is_managed(elem);
    bool elem_aggregate = cgtype_is_aggregate(elem);
    if (!elem_aggregate && cg_value_needs_reified_layout(cg, elem)) {
        elem_aggregate = true;
    }
    const char *agg_desc = elem_aggregate ? cg_aggregate_desc_name(elem) : NULL;
    if (elem_aggregate && agg_desc == NULL) {
        free(size_tmp); free(arr_tmp); free(elem_cty); free(desc_expr);
        cgtype_free(elem);
        return cg_fail(cg, e->token,
            "CE0186", "codegen: missing aggregate descriptor for array-new element type");
    }

    if (elem_aggregate) {
        size_t rad_idx;
        if (cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
            const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, %s->reified_agg_deps[%zu], "
                "NULL, %s->reified_agg_deps[%zu]->size, %s);\n",
                arr_tmp, rad_src, rad_idx, rad_src, rad_idx, size_tmp);
        } else {
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = feng_array_new_kinded("
                "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, &%s, NULL, sizeof(%s), %s);\n",
                arr_tmp, agg_desc, elem_cty, size_tmp);
        }
    } else if (elem->kind == CG_TYPE_GENERIC_PARAM) {
        size_t gp_index = elem->generic_param_index;
        const char *desc = cg_generic_param_desc_name(cg, gp_index);
        if (desc == NULL) {
            free(size_tmp); free(arr_tmp); free(elem_cty); free(desc_expr);
            cgtype_free(elem);
            return cg_fail(cg, e->token,
                "CE0187", "codegen: generic array-new requires an active generic descriptor");
        }
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new_kinded("
            "%s->kind, (%s->kind == FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS ? feng_generic_aggregate_descriptor(%s) : NULL), NULL, feng_generic_value_size(%s), %s);\n",
            arr_tmp, desc, desc, desc, desc, size_tmp);
    } else if (elem_managed && elem->kind == CG_TYPE_OBJECT && elem->user &&
               elem->user->c_default_zero_name) {
        /* Managed object element: allocate the array of pointers, then
         * fill each slot with a freshly default-zero'd object so that
         * out-of-bounds / uninitialized access fails visibly rather than
         * silently dereferencing NULL. */
        char *slots_tmp = cg_fresh_temp(cg, "_slots");
        char *idx_tmp   = cg_fresh_temp(cg, "_i");
        if (!slots_tmp || !idx_tmp) {
            free(slots_tmp); free(idx_tmp);
            free(size_tmp); free(arr_tmp); free(elem_cty); free(desc_expr);
            cgtype_free(elem);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new(%s, sizeof(%s), %s, %s);\n",
            arr_tmp, desc_expr, elem_cty,
            elem_managed ? "true" : "false", size_tmp);
        buf_append_fmt(cg->cur_body,
            "    %s *%s = (%s *)feng_array_data(%s);\n",
            elem_cty, slots_tmp, elem_cty, arr_tmp);
        buf_append_fmt(cg->cur_body,
            "    for (size_t %s = 0; %s < %s; ++%s) "
            "%s[%s] = %s();\n",
            idx_tmp, idx_tmp, size_tmp, idx_tmp,
            slots_tmp, idx_tmp, elem->user->c_default_zero_name);
        free(slots_tmp); free(idx_tmp);
    } else {
        buf_append_fmt(cg->cur_body,
            "    FengArray *%s = feng_array_new(%s, sizeof(%s), %s, %s);\n",
            arr_tmp, desc_expr, elem_cty,
            elem_managed ? "true" : "false", size_tmp);
    }

    free(size_tmp); free(elem_cty); free(desc_expr);

    out->c_expr = strdup(arr_tmp);
    free(arr_tmp);
    out->type = cgtype_new(CG_TYPE_ARRAY);
    if (!out->c_expr || !out->type) { cgtype_free(elem); return false; }
    out->type->element = elem;
    out->owns_ref = true;
    return true;
}

static bool cg_emit_index(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    ExprResult recv;
    if (!cg_emit_expr(cg, e->as.index.object, &recv)) return false;
    if (recv.type->kind != CG_TYPE_ARRAY || !recv.type->element) {
        er_free(&recv);
        return cg_fail(cg, e->token,
            "CE0188", "codegen: indexing requires an array value");
    }
    if (cgtype_is_managed(recv.type) && recv.owns_ref) {
        cg_materialize_to_local(cg, &recv, "_t");
    }
    ExprResult idx;
    if (!cg_emit_expr(cg, e->as.index.index, &idx)) {
        er_free(&recv); return false;
    }
    if (!cgtype_is_integer(idx.type->kind)) {
        er_free(&idx); er_free(&recv);
        return cg_fail(cg, e->token, "CE0189", "codegen: array index must be an integer");
    }
    /* Materialize index into a `size_t` local so we can both bounds-check
     * and slot-load using the same value. */
    char *idx_tmp = cg_fresh_temp(cg, "_idx");
    if (!idx_tmp) { er_free(&idx); er_free(&recv); return false; }
    buf_append_fmt(cg->cur_body, "    size_t %s = (size_t)(%s);\n",
                   idx_tmp, idx.c_expr);
    buf_append_fmt(cg->cur_body, "    feng_array_check_index(%s, %s);\n",
                   recv.c_expr, idx_tmp);

    char *elem_cty = cg_ctype_dup(recv.type->element);
    if (!elem_cty) {
        free(idx_tmp); er_free(&idx); er_free(&recv); return false;
    }
    Buf b; buf_init(&b);
    if (recv.type->element->kind == CG_TYPE_GENERIC_PARAM) {
        size_t gp_index = recv.type->element->generic_param_index;
        const char *desc = cg_generic_param_desc_name(cg, gp_index);
        if (desc == NULL) {
            free(elem_cty); free(idx_tmp);
            er_free(&idx); er_free(&recv);
            return cg_fail(cg, e->token,
                "CE0190", "codegen: generic array index requires an active generic descriptor");
        }
        buf_append_fmt(&b,
            "((%s->kind == FENG_VALUE_MANAGED_POINTER) ? "
            "(void *)&((void **)feng_array_data(%s))[%s] : "
            "(void *)((char *)feng_array_data(%s) + (%s) * feng_generic_value_size(%s)))",
            desc,
            recv.c_expr, idx_tmp,
            recv.c_expr, idx_tmp, desc);
    } else {
        buf_append_fmt(&b, "(((%s *)feng_array_data(%s))[%s])",
                       elem_cty, recv.c_expr, idx_tmp);
    }
    free(elem_cty); free(idx_tmp);
    out->c_expr = b.data;
    out->type = cgtype_clone(recv.type->element);
    out->owns_ref = false;   /* borrowed */
    out->is_addressable = true;
    out->is_storage_address =
        recv.type->element->kind == CG_TYPE_GENERIC_PARAM;
    er_free(&idx); er_free(&recv);
    return out->c_expr && out->type;
}

static bool cg_emit_cast(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);
    CGType *target = NULL;
    if (!cg_resolve_type(cg, e->as.cast.type, &e->token, &target)) return false;
    if (cg_type_is_tuple_user(target)) {
        bool ok = cg_emit_tuple_cast_to_type(cg, e->as.cast.value, target, out);
        cgtype_free(target);
        return ok;
    }
    if (target->kind == CG_TYPE_CALLABLE) {
        ExprResult inner;
        const UserSpec *target_spec = target->user_spec;
        const UserSpec *source_spec = NULL;

        if (!cg_emit_expr(cg, e->as.cast.value, &inner)) {
            cgtype_free(target);
            return false;
        }
        if (target_spec != NULL && inner.type != NULL && inner.type->kind == CG_TYPE_CALLABLE) {
            source_spec = inner.type->user_spec;
            if (source_spec != NULL &&
                (source_spec == target_spec ||
                 cg_callable_specs_signature_compatible(source_spec, target_spec))) {
                if (source_spec != target_spec) {
                    bool ok = cg_emit_callable_other_rewrap(cg,
                                                            e,
                                                            &inner,
                                                            source_spec,
                                                            target_spec,
                                                            out);
                    er_free(&inner);
                    cgtype_free(target);
                    return ok;
                }
                cgtype_free(inner.type);
                inner.type = target;
                *out = inner;
                return true;
            }
        }
        er_free(&inner);
        cgtype_free(target);
        return cg_fail(cg,
                       e->token,
                       "CE0191", "codegen: callable-form cast operand must be a callable-form spec value");
    }
    if (target->kind == CG_TYPE_SPEC) {
        ExprResult inner;

        if (!cg_emit_expr(cg, e->as.cast.value, &inner)) {
            cgtype_free(target);
            return false;
        }
        if (inner.type == NULL || inner.type->kind != CG_TYPE_SPEC ||
            inner.type->user_spec != target->user_spec) {
            er_free(&inner);
            cgtype_free(target);
            return cg_fail(cg,
                           e->token,
                           "CE0195", "codegen: object-form spec cast operand did not project to the target spec");
        }
        cgtype_free(inner.type);
        inner.type = target;
        *out = inner;
        return true;
    }
    if (target->kind == CG_TYPE_ARRAY) {
        ExprResult inner;

        if (!cg_emit_expr(cg, e->as.cast.value, &inner)) {
            cgtype_free(target);
            return false;
        }
        if (inner.type->kind != CG_TYPE_ARRAY || !cg_types_equal(target, inner.type)) {
            er_free(&inner);
            cgtype_free(target);
            return cg_fail(cg,
                           e->token,
                           "CE0192", "codegen: array cast requires the same lowered array type");
        }
        out->c_expr = strdup(inner.c_expr);
        out->type = target;
        out->owns_ref = inner.owns_ref;
        er_free(&inner);
        return out->c_expr != NULL && out->type != NULL;
    }
    if (!cgtype_is_numeric(target->kind) && target->kind != CG_TYPE_BOOL) {
        cgtype_free(target);
        return cg_fail(cg, e->token, "CE0193", "codegen: only numeric/bool casts supported in 1A iter 1");
    }
    ExprResult inner;
    if (!cg_emit_expr(cg, e->as.cast.value, &inner)) { cgtype_free(target); return false; }
    if (!cgtype_is_numeric(inner.type->kind) && inner.type->kind != CG_TYPE_BOOL) {
        er_free(&inner); cgtype_free(target);
        return cg_fail(cg, e->token, "CE0194", "codegen: cast operand must be numeric/bool");
    }
    Buf b; buf_init(&b);
    buf_append_fmt(&b, "((%s)%s)", cgtype_to_c(target->kind), inner.c_expr);
    out->c_expr = b.data;
    out->type = target;
    er_free(&inner);
    return out->c_expr && out->type;
}

/* ===================== if / match expression emission =====================
 *
 * Per docs/specifications/feng-flow.md §4 the `if` expression form requires every branch
 * (then, every `else if`, and a mandatory `else`) to be a block whose final
 * statement is an expression statement. The block's value is that
 * expression's value; semantic analysis has already verified all branch
 * yield types unify, so codegen is purely a lowering exercise:
 *
 *   1. Discover the result type by emitting the then-branch yield expression
 *      into a throwaway buffer/scope (probe). This is safe because the only
 *      side-effects cg_emit_expr mutates outside the buffer (string-literal
 *      cache, witness-instance table, tmp_counter) are either idempotent or
 *      monotonic.
 *   2. Allocate a slot `_ifv_N` of the result type in the OUTER scope and
 *      register it on the Feng cleanup chain (managed kinds only). Any
 *      `return`/`throw` raised inside a branch body therefore traverses
 *      `_ifv_N` exactly once via cg_release_through, keeping the runtime
 *      cleanup chain consistent.
 *   3. For each branch: push a Feng scope, emit all leading statements via
 *      cg_emit_stmt, then evaluate the yield expression and assign into
 *      `_ifv_N` with the standard +1 transfer (steal on owns_ref, retain on
 *      borrow); release the branch scope before joining.
 *
 * Aggregate (fat-spec) results reuse the value-model aggregate slot protocol:
 * the outer slot is default-initialised once, each branch writes through
 * feng_aggregate_assign / feng_aggregate_take, and scope cleanup releases the
 * slot exactly once on exit.
 */

static const FengExpr *cg_branch_yield_expr(const FengBlock *block) {
    if (!block || block->statement_count == 0) return NULL;
    const FengStmt *last = block->statements[block->statement_count - 1];
    if (last->kind != FENG_STMT_EXPR) return NULL;
    return last->as.expr;
}

/* A branch block "terminates with throw" when its last statement is a
 * FENG_STMT_THROW. Such branches never write into the result slot; they
 * are emitted as plain blocks whose control flow exits via the unwinder. */
static bool cg_branch_terminates_with_throw(const FengBlock *block) {
    if (!block || block->statement_count == 0) return false;
    const FengStmt *last = block->statements[block->statement_count - 1];
    return last->kind == FENG_STMT_THROW;
}

/* Representation metadata for one outer result slot shared by expression
 * branches. Direct generic parameters and descriptor-sized aggregates use
 * address storage plus cached descriptor/size locals; fixed-layout results
 * keep their existing C slot. */
typedef struct CGExpressionJoinSlot {
    bool uses_erased_generic_storage;
    char *erased_generic_descriptor_c_name;
    char *erased_generic_size_c_name;
    bool uses_reified_storage;
    char *reified_descriptor_c_name;
    char *reified_size_c_name;
} CGExpressionJoinSlot;

/* Release compile-time strings owned by one expression join slot. */
static void cg_expression_join_slot_free(CGExpressionJoinSlot *slot) {
    if (slot == NULL) {
        return;
    }
    free(slot->erased_generic_descriptor_c_name);
    free(slot->erased_generic_size_c_name);
    free(slot->reified_descriptor_c_name);
    free(slot->reified_size_c_name);
    memset(slot, 0, sizeof(*slot));
}

/* Copy dynamic join-slot representation metadata into the expression result
 * consumed by later assignment, call, or return lowering. */
static bool cg_expression_join_slot_apply_to_result(
    const CGExpressionJoinSlot *slot,
    ExprResult *result) {
    if (slot == NULL || result == NULL) {
        return true;
    }
    if (slot->uses_erased_generic_storage) {
        result->is_storage_address = true;
        result->uses_erased_generic_storage = true;
        result->erased_generic_descriptor_c_name =
            strdup(slot->erased_generic_descriptor_c_name);
        result->erased_generic_size_c_name =
            strdup(slot->erased_generic_size_c_name);
        return result->erased_generic_descriptor_c_name != NULL &&
               result->erased_generic_size_c_name != NULL;
    }
    if (!slot->uses_reified_storage) {
        return true;
    }
    result->is_storage_address = true;
    result->uses_reified_storage = true;
    result->reified_descriptor_c_name =
        strdup(slot->reified_descriptor_c_name);
    result->reified_size_c_name = strdup(slot->reified_size_c_name);
    return result->reified_descriptor_c_name != NULL &&
           result->reified_size_c_name != NULL;
}

/* Declare and register one expression result slot in the current Feng scope.
 * The helper is shared by if, match, and try joins so every control-flow form
 * preserves the same reified storage and cleanup contract. */
static bool cg_emit_expression_join_slot(CG *cg,
                                         const char *slot_name,
                                         const CGType *result_type,
                                         bool managed,
                                         bool aggregate,
                                         FengToken blame,
                                         CGExpressionJoinSlot *out_slot) {
    char *ctype = NULL;

    if (cg == NULL || slot_name == NULL || result_type == NULL ||
        out_slot == NULL) {
        return false;
    }
    memset(out_slot, 0, sizeof(*out_slot));

    if (result_type->kind == CG_TYPE_GENERIC_PARAM) {
        if (!cg_emit_erased_generic_storage_declaration(
                cg,
                result_type,
                slot_name,
                blame,
                &out_slot->erased_generic_descriptor_c_name,
                &out_slot->erased_generic_size_c_name) ||
            !cg_register_erased_generic_storage_for_cleanup(
                cg,
                slot_name,
                result_type,
                out_slot->erased_generic_descriptor_c_name,
                out_slot->erased_generic_size_c_name,
                blame)) {
            return false;
        }
        out_slot->uses_erased_generic_storage = true;
        return true;
    }

    if (aggregate && cg_type_uses_reified_storage(cg, result_type)) {
        if (!cg_emit_reified_storage_declaration(
                cg,
                result_type,
                slot_name,
                blame,
                &out_slot->reified_descriptor_c_name,
                &out_slot->reified_size_c_name)) {
            return false;
        }
        out_slot->uses_reified_storage = true;
        buf_append_fmt(cg->cur_body,
            "    feng_aggregate_default_init(%s, %s);\n",
            slot_name,
            out_slot->reified_descriptor_c_name);
        if (!scope_add(cg->cur_scope,
                       slot_name,
                       slot_name,
                       cgtype_clone(result_type),
                       false) ||
            !scope_mark_last_reified_storage(
                cg->cur_scope,
                out_slot->reified_descriptor_c_name,
                out_slot->reified_size_c_name)) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg_emit_cleanup_push_for_reified_aggregate_storage(
            cg,
            slot_name,
            out_slot->reified_descriptor_c_name);
        return true;
    }

    ctype = cg_ctype_dup(result_type);
    if (ctype == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (managed) {
        buf_append_fmt(cg->cur_body, "    %s %s = NULL;\n", ctype, slot_name);
        cg_emit_cleanup_push_for_managed_local(cg, slot_name);
        if (!scope_add(cg->cur_scope,
                       slot_name,
                       slot_name,
                       cgtype_clone(result_type),
                       false)) {
            free(ctype);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    } else if (aggregate) {
        buf_append_fmt(cg->cur_body, "    %s %s; ", ctype, slot_name);
        if (!cg_append_aggregate_default_init_call(
                cg->cur_body, result_type, slot_name)) {
            free(ctype);
            return cg_fail(cg, blame,
                "CE0202", "codegen: missing aggregate default-init rule for expression result");
        }
        buf_append_cstr(cg->cur_body, ";\n");
        cg_emit_cleanup_push_for_aggregate_local(cg, slot_name, result_type);
        if (!scope_add(cg->cur_scope,
                       slot_name,
                       slot_name,
                       cgtype_clone(result_type),
                       false)) {
            free(ctype);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    } else if (cgtype_is_by_value_struct(result_type)) {
        buf_append_fmt(cg->cur_body, "    %s %s = {0};\n", ctype, slot_name);
    } else {
        buf_append_fmt(cg->cur_body,
                       "    %s %s = (%s)0;\n",
                       ctype,
                       slot_name,
                       ctype);
    }
    free(ctype);
    return true;
}

/* Assign one branch value into an already-declared join slot while preserving
 * ownership and the slot's physical representation. */
static bool cg_assign_expr_result_to_join_slot(
    CG *cg,
    const char *slot_name,
    const CGType *result_type,
    bool managed,
    bool aggregate,
    const CGExpressionJoinSlot *slot,
    ExprResult *result,
    FengToken blame,
    const char *mismatch_code,
    const char *mismatch_message) {
    if (!cg_types_equal(result_type, result->type) &&
        !(cgtype_is_numeric(result_type->kind) &&
          cgtype_is_numeric(result->type->kind))) {
        return cg_fail(cg, blame, mismatch_code, "%s", mismatch_message);
    }
    if (result_type->kind == CG_TYPE_VOID) {
        buf_append_fmt(cg->cur_body,
                       "        (void)(%s);\n",
                       result->c_expr);
        return true;
    }
    if (slot != NULL && slot->uses_erased_generic_storage) {
        return cg_emit_generic_value_store(cg,
                                           slot_name,
                                           result_type,
                                           result,
                                           blame,
                                           false);
    }
    if (managed) {
        if (result->owns_ref) {
            buf_append_fmt(cg->cur_body,
                           "        %s = %s;\n",
                           slot_name,
                           result->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "        %s = %s; if (%s) feng_retain(%s);\n",
                           slot_name,
                           result->c_expr,
                           slot_name,
                           slot_name);
        }
        return true;
    }
    if (aggregate) {
        if (slot != NULL && slot->uses_reified_storage) {
            if (result->owns_ref && result->uses_reified_storage) {
                buf_append_fmt(cg->cur_body,
                    "        feng_aggregate_take(%s, %s, %s);\n",
                    slot_name,
                    result->c_expr,
                    slot->reified_descriptor_c_name);
                return true;
            }
            if (!cg_prepare_aggregate_assign_source(cg, result, "_t")) {
                return cg_fail(cg, blame,
                               "IE0001", "codegen: out of memory");
            }
            {
                char *source_address =
                    cg_aggregate_result_address_dup(result);

                if (source_address == NULL) {
                    return cg_fail(cg, blame,
                        "CE0196", "codegen: reified expression result has no address storage");
                }
                buf_append_fmt(cg->cur_body,
                    "        feng_aggregate_assign(%s, %s, %s);\n",
                    slot_name,
                    source_address,
                    slot->reified_descriptor_c_name);
                free(source_address);
            }
            return true;
        }
        {
            const char *aggregate_descriptor =
                cg_aggregate_desc_name(result_type);

            if (aggregate_descriptor == NULL) {
                return cg_fail(cg, blame,
                    "CE0196", "codegen: missing aggregate descriptor for expression result slot");
            }
            if (result->owns_ref) {
                cg_materialize_to_local(cg, result, "_t");
                buf_append_fmt(cg->cur_body,
                    "        feng_aggregate_take(&%s, &%s, &%s);\n",
                    slot_name,
                    result->c_expr,
                    aggregate_descriptor);
            } else {
                if (!cg_prepare_aggregate_assign_source(cg, result, "_t")) {
                    return cg_fail(cg, blame,
                                   "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(cg->cur_body,
                    "        feng_aggregate_assign(&%s, &%s, &%s);\n",
                    slot_name,
                    result->c_expr,
                    aggregate_descriptor);
            }
        }
        return true;
    }
    {
        char *ctype = cg_ctype_dup(result_type);

        if (ctype == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "        %s = (%s)(%s);\n",
                       slot_name,
                       ctype,
                       result->c_expr);
        free(ctype);
    }
    return true;
}

static bool cg_emit_branch_into_slot(CG *cg,
                                     const FengBlock *block,
                                     const char *ifv_name,
                                     const CGType *result_type,
                                     bool managed,
                                     bool aggregate,
                                     const CGExpressionJoinSlot *slot,
                                     FengToken err_token) {
    Scope *bsc = scope_push(cg->cur_scope);
    if (!bsc) return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
    cg->cur_scope = bsc;

    bool ok = true;
    /* Leading statements (everything except the trailing yield expression). */
    for (size_t i = 0; i + 1 < block->statement_count; i++) {
        if (!cg_emit_stmt(cg, block->statements[i])) { ok = false; break; }
    }

    if (ok) {
        const FengExpr *yield =
            block->statements[block->statement_count - 1]->as.expr;
        ExprResult r;
        if (!cg_emit_expr(cg, yield, &r)) {
            ok = false;
        } else {
            ok = cg_assign_expr_result_to_join_slot(
                cg,
                ifv_name,
                result_type,
                managed,
                aggregate,
                slot,
                &r,
                err_token,
                "CE0195",
                "codegen: if-expression branches yield mismatched types");
            er_free(&r);
        }
    }

    if (ok) {
        cg_release_scope(cg, bsc);
    }
    cg->cur_scope = bsc->parent;
    scope_pop_free(bsc);
    return ok;
}

/* Emit a branch that is statically known to terminate with throw in its own
 * compile-time scope. Managed locals still push runtime cleanup nodes, but no
 * normal-exit cleanup is emitted because control can only leave through the
 * unwinder. The landing pad or an outer frame releases those nodes. */
static bool cg_emit_throwing_branch(CG *cg,
                                    const FengBlock *block,
                                    FengToken err_token) {
    Scope *branch_scope = scope_push(cg->cur_scope);
    bool ok;

    if (branch_scope == NULL) {
        return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
    }
    cg->cur_scope = branch_scope;
    ok = cg_emit_block(cg, block);
    cg->cur_scope = branch_scope->parent;
    scope_pop_free(branch_scope);
    return ok;
}

/* Probe an expression type by emitting it into a throwaway buffer and scope.
 * This may advance monotonic counters or populate shared caches, but it does
 * not splice code into the real output stream. Returns a heap-owned CGType
 * clone on success or NULL on failure. Caller owns the returned CGType. */
static CGType *cg_probe_expr_type(CG *cg, const FengExpr *expr) {
    Buf throwaway; buf_init(&throwaway);
    Buf *saved_body = cg->cur_body;
    cg->cur_body = &throwaway;
    Scope *probe = scope_push(cg->cur_scope);
    if (!probe) {
        cg->cur_body = saved_body;
        buf_free(&throwaway);
        return NULL;
    }
    cg->cur_scope = probe;
    ExprResult r;
    bool ok = cg_emit_expr(cg, expr, &r);
    CGType *result = ok ? cgtype_clone(r.type) : NULL;
    er_free(&r);
    cg->cur_scope = probe->parent;
    scope_pop_free(probe);
    cg->cur_body = saved_body;
    buf_free(&throwaway);
    return result;
}

static CGType *cg_probe_branch_yield_type(CG *cg, const FengExpr *yield) {
    return cg_probe_expr_type(cg, yield);
}

static bool cg_assign_expr_result_to_slot(CG *cg,
                                          const char *slot_name,
                                          const CGType *result_type,
                                          bool managed,
                                          bool aggregate,
                                          const CGExpressionJoinSlot *slot,
                                          ExprResult *r,
                                          FengToken err_token) {
    return cg_assign_expr_result_to_join_slot(
        cg,
        slot_name,
        result_type,
        managed,
        aggregate,
        slot,
        r,
        err_token,
        "CE0197",
        "codegen: try/catch branches yield mismatched types");
}

static bool cg_emit_if_expr(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);

    const FengBlock *then_b = e->as.if_expr.then_block;
    const FengBlock *else_b = e->as.if_expr.else_block;
    bool then_throws = cg_branch_terminates_with_throw(then_b);
    bool else_throws = cg_branch_terminates_with_throw(else_b);
    const FengExpr *then_yield = then_throws ? NULL : cg_branch_yield_expr(then_b);
    const FengExpr *else_yield = else_throws ? NULL : cg_branch_yield_expr(else_b);

    if (!then_yield && !else_yield) {
        return cg_fail(cg, e->token,
            "CE0199", "codegen: if-expression branches must end with an expression statement or throw");
    }

    /* When both branches terminate with throw the expression has no usable
     * result value. Emit a plain if/else that propagates the exception; the
     * result slot is unnecessary, so we surface a void-typed ExprResult. */
    if (then_throws && else_throws) {
        char *cond_tmp = cg_fresh_temp(cg, "_cond");
        ExprResult cond;
        bool ok;

        if (!cond_tmp) {
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        if (!cg_emit_expr(cg, e->as.if_expr.condition, &cond)) {
            free(cond_tmp);
            return false;
        }
        if (cond.type->kind != CG_TYPE_BOOL) {
            er_free(&cond);
            free(cond_tmp);
            return cg_fail(cg, e->token,
                "CE0201", "codegen: if-expression condition must be bool");
        }
        buf_append_fmt(cg->cur_body, "    bool %s = %s;\n", cond_tmp, cond.c_expr);
        er_free(&cond);

        buf_append_fmt(cg->cur_body, "    if (%s) {\n", cond_tmp);
        ok = cg_emit_throwing_branch(cg, then_b, e->token);
        buf_append_cstr(cg->cur_body, "    } else {\n");
        if (ok) {
            ok = cg_emit_throwing_branch(cg, else_b, e->token);
        }
        buf_append_cstr(cg->cur_body, "    }\n");
        free(cond_tmp);
        if (!ok) {
            return false;
        }

        out->type = cgtype_new(CG_TYPE_VOID);
        out->c_expr = strdup("(void)0");
        out->owns_ref = false;
        return out->type != NULL && out->c_expr != NULL;
    }

    /* Exactly one branch throws. Derive the result type from the yielding
     * branch; the throwing branch is emitted as a plain block (its throw
     * leaves control flow before the slot would ever be read). */
    const FengExpr *yield_for_type = then_yield != NULL ? then_yield : else_yield;
    CGType *result_type = cg_probe_branch_yield_type(cg, yield_for_type);
    if (!result_type) return false;

    bool managed = cgtype_is_managed(result_type);
    bool aggregate = cgtype_is_aggregate(result_type);
    CGExpressionJoinSlot join_slot = {0};

    char *cond_tmp = cg_fresh_temp(cg, "_cond");
    char *ifv = cg_fresh_temp(cg, "_ifv");
    if (!cond_tmp || !ifv) {
        free(cond_tmp); free(ifv); cgtype_free(result_type);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    /* Emit the condition first; the slot decl follows so a panic raised by
     * the condition expression itself never observes a dangling cleanup
     * node for `_ifv` on the runtime chain. */
    ExprResult cond;
    if (!cg_emit_expr(cg, e->as.if_expr.condition, &cond)) {
        free(cond_tmp); free(ifv); cgtype_free(result_type);
        return false;
    }
    if (cond.type->kind != CG_TYPE_BOOL) {
        er_free(&cond);
        free(cond_tmp); free(ifv); cgtype_free(result_type);
        return cg_fail(cg, e->token,
            "CE0201", "codegen: if-expression condition must be bool");
    }
    buf_append_fmt(cg->cur_body, "    bool %s = %s;\n", cond_tmp, cond.c_expr);
    er_free(&cond);

    if (!cg_emit_expression_join_slot(cg,
                                      ifv,
                                      result_type,
                                      managed,
                                      aggregate,
                                      e->token,
                                      &join_slot)) {
        free(cond_tmp);
        free(ifv);
        cgtype_free(result_type);
        cg_expression_join_slot_free(&join_slot);
        return false;
    }

    buf_append_fmt(cg->cur_body, "    if (%s) {\n", cond_tmp);
    bool ok = true;
    if (then_throws) {
        ok = cg_emit_throwing_branch(cg, then_b, e->token);
    } else {
        ok = cg_emit_branch_into_slot(cg, then_b, ifv, result_type,
                                      managed, aggregate, &join_slot, e->token);
    }
    buf_append_cstr(cg->cur_body, "    } else {\n");
    if (ok) {
        if (else_throws) {
            ok = cg_emit_throwing_branch(cg, else_b, e->token);
        } else {
            ok = cg_emit_branch_into_slot(cg, else_b, ifv, result_type,
                                          managed, aggregate, &join_slot, e->token);
        }
    }
    buf_append_cstr(cg->cur_body, "    }\n");
    if (!ok) {
        free(cond_tmp); free(ifv); cgtype_free(result_type);
        cg_expression_join_slot_free(&join_slot);
        return false;
    }

    out->c_expr = strdup(ifv);
    out->type = result_type;
    /* For managed values the OUTER Feng scope owns the +1 (the slot was
     * registered above). For non-managed values it's a plain rvalue copy.
     * In both cases the surface contract is "borrowed-from-slot": owns_ref
     * is false, callers that need to retain do so themselves. */
    out->owns_ref = false;
    out->is_addressable = true;
    if (!cg_expression_join_slot_apply_to_result(&join_slot, out)) {
        er_free(out);
        free(cond_tmp);
        free(ifv);
        cg_expression_join_slot_free(&join_slot);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    free(cond_tmp);
    free(ifv);
    cg_expression_join_slot_free(&join_slot);
    return out->c_expr != NULL;
}

/* Build a C boolean expression matching `target_tmp` against a single match
 * label. Label literal expressions are emitted via cg_emit_expr; per
 * docs/specifications/feng-flow.md §3 they must be compile-time constants/let-literal
 * bindings, so the emitted C is a pure value with no scope side-effects.
 * String comparison uses inline length+memcmp lowering against the runtime's
 * FengString accessors so the runtime surface stays the value-model API set.
 */
static bool cg_emit_match_label_cond(CG *cg, const char *target_tmp,
                                     CGTypeKind target_kind,
                                     const FengMatchLabel *lab, Buf *out) {
    if (lab->kind == FENG_MATCH_LABEL_VALUE) {
        ExprResult lv;
        if (!cg_emit_expr(cg, lab->value, &lv)) return false;
        if (target_kind == CG_TYPE_STRING) {
            buf_append_fmt(out,
                "(bool)(feng_string_length(%s) == feng_string_length(%s) && "
                "memcmp(feng_string_data(%s), feng_string_data(%s), "
                "feng_string_length(%s)) == 0)",
                target_tmp, lv.c_expr,
                target_tmp, lv.c_expr,
                lv.c_expr);
        } else {
            buf_append_fmt(out, "(bool)(%s == %s)", target_tmp, lv.c_expr);
        }
        er_free(&lv);
        return true;
    }
    if (lab->kind == FENG_MATCH_LABEL_RANGE) {
        if (target_kind == CG_TYPE_STRING || target_kind == CG_TYPE_BOOL) {
            return cg_fail(cg, lab->token,
                "CE0203", "codegen: range labels apply to integer match targets only");
        }
        ExprResult lo, hi;
        if (!cg_emit_expr(cg, lab->range_low, &lo)) return false;
        if (!cg_emit_expr(cg, lab->range_high, &hi)) {
            er_free(&lo);
            return false;
        }
        buf_append_fmt(out, "(%s >= %s && %s <= %s)",
                       target_tmp, lo.c_expr, target_tmp, hi.c_expr);
        er_free(&lo);
        er_free(&hi);
        return true;
    }
    if (lab->kind == FENG_MATCH_LABEL_TYPE) {
        /* Enum item reference label of the form `EnumName.ItemName` (a
         * 2-segment named type ref). Semantic validation guarantees the
         * first segment resolves to an enum decl visible from the current
         * program, and the second segment is a valid item name in that
         * enum. We emit the canonical C constant `EnumTypedef__ItemName`
         * and lower the comparison to `(bool)(_mt == EnumTypedef__ItemName)`,
         * matching the existing integer-label lowering path. */
        const FengTypeRef *ref = lab->type;
        const FengDecl *enum_decl;
        char *item_c_name;
        bool found = false;
        size_t ei;

        if (ref == NULL ||
            ref->kind != FENG_TYPE_REF_NAMED ||
            ref->as.named.segment_count != 2U) {
            return cg_fail(cg, lab->token,
                "CE0204", "codegen: enum item reference label must be 'EnumName.ItemName'");
        }
        enum_decl = cg_find_visible_enum_decl(cg,
            ref->as.named.segments[0].data,
            ref->as.named.segments[0].length);
        if (enum_decl == NULL) {
            return cg_fail(cg, lab->token,
                "CE0171", "codegen: enum '%.*s' is not visible from this program",
                (int)ref->as.named.segments[0].length,
                ref->as.named.segments[0].data);
        }
        if (!cg_ensure_enum_emitted(cg, enum_decl)) return false;

        for (ei = 0U; ei < enum_decl->as.enum_decl.item_count; ++ei) {
            if (cg_slice_equals(enum_decl->as.enum_decl.items[ei].name,
                                ref->as.named.segments[1])) {
                found = true;
                break;
            }
        }
        if (!found) {
            return cg_fail(cg,
                lab->token,
                "CE0170", "codegen: enum '%.*s' has no item '%.*s'",
                (int)enum_decl->as.enum_decl.name.length,
                enum_decl->as.enum_decl.name.data,
                (int)ref->as.named.segments[1].length,
                ref->as.named.segments[1].data);
        }
        item_c_name = cg_enum_item_c_name(cg, enum_decl, ref->as.named.segments[1]);
        if (item_c_name == NULL) {
            return cg_fail(cg, lab->token, "IE0001", "codegen: out of memory referencing enum item constant");
        }
        buf_append_fmt(out, "(bool)(%s == %s)", target_tmp, item_c_name);
        free(item_c_name);
        return true;
    }
    return cg_fail(cg, lab->token, "CE0204", "codegen: unknown match label kind");
}

/* Emit a match expression where every branch (including else) terminates
 * with throw. No result slot is needed; each branch is emitted as a plain
 * block whose throw propagates up through the unwinder. `tgt_tmp` is the
 * already-materialised target variable name. */
static bool cg_emit_match_expr_all_throw(CG *cg, const FengExpr *e,
                                         const char *tgt_tmp, ExprResult *out) {
    er_init(out);

    /* Check if target is a union spec for the union-match code path. */
    const FengExpr *target = e->as.match_expr.target;
    CGType *target_type = cg_probe_expr_type(cg, target);
    bool is_union = target_type != NULL && target_type->kind == CG_TYPE_SPEC &&
                    target_type->user_spec != NULL &&
                    target_type->user_spec->form == FENG_SPEC_FORM_UNION;

    if (is_union) {
        const UserSpec *union_spec = target_type->user_spec;
        bool first_branch = true;
        bool ok = true;

        for (size_t branch_index = 0U;
             branch_index < e->as.match_expr.branch_count;
             ++branch_index) {
            const FengMatchBranch *branch = &e->as.match_expr.branches[branch_index];
            Buf condition;
            size_t first_member_index = 0U;
            size_t matched_member_count = 0U;

            if (branch->label_count == 0U) {
                ok = cg_fail(cg, branch->token,
                             "CE0210", "codegen: match branch has no labels");
                break;
            }

            buf_init(&condition);
            for (size_t label_index = 0U;
                 label_index < branch->label_count;
                 ++label_index) {
                size_t member_index = 0U;
                char *label_cond = NULL;

                if (!cg_union_member_index_for_label(cg,
                                                     union_spec,
                                                     &branch->labels[label_index],
                                                     &member_index)) {
                    ok = false;
                    break;
                }
                label_cond = cg_build_label_condition(cg, tgt_tmp, union_spec,
                                                       &branch->labels[label_index]);
                if (label_cond == NULL) {
                    ok = false;
                    break;
                }
                if (label_index != 0U) {
                    buf_append_cstr(&condition, " || ");
                }
                buf_append_cstr(&condition, label_cond);
                free(label_cond);
                if (matched_member_count == 0U) {
                    first_member_index = member_index;
                }
                matched_member_count++;
            }

            if (!ok) {
                buf_free(&condition);
                break;
            }

            if (first_branch) {
                buf_append_fmt(cg->cur_body, "    if (%s) {\n", condition.data);
                first_branch = false;
            } else {
                buf_append_fmt(cg->cur_body, "    } else if (%s) {\n", condition.data);
            }
            buf_free(&condition);

            {
                Scope *branch_scope = scope_push(cg->cur_scope);

                if (branch_scope == NULL) {
                    ok = cg_fail(cg, branch->token, "IE0001", "codegen: out of memory");
                    break;
                }
                cg->cur_scope = branch_scope;
                if (branch->has_binding &&
                    branch->binding_name.data != NULL &&
                    branch->binding_name.length > 0U &&
                    matched_member_count == 1U) {
                    Buf payload_expr;
                    CGType *alias_type;

                    buf_init(&payload_expr);
                    buf_append_fmt(&payload_expr, "%s.payload.", tgt_tmp);
                    cg_append_union_payload_field_name(&payload_expr, first_member_index);
                    alias_type = cgtype_clone(union_spec->union_member_types[first_member_index]);

                    char *alias_cstr = strndup(branch->binding_name.data,
                                               branch->binding_name.length);

                    if (payload_expr.data == NULL || alias_type == NULL || alias_cstr == NULL ||
                        !scope_add(branch_scope,
                                   alias_cstr,
                                   payload_expr.data,
                                   alias_type,
                                   true)) {
                        cgtype_free(alias_type);
                        free(alias_cstr);
                        buf_free(&payload_expr);
                        cg->cur_scope = branch_scope->parent;
                        scope_pop_free(branch_scope);
                        ok = cg_fail(cg, branch->token, "IE0001", "codegen: out of memory");
                        break;
                    }
                    free(alias_cstr);
                    cgtype_free(alias_type);
                    buf_free(&payload_expr);
                }

                ok = cg_emit_throwing_branch(cg,
                                              branch->body,
                                              branch->token);
                cg->cur_scope = branch_scope->parent;
                scope_pop_free(branch_scope);
                if (!ok) {
                    break;
                }
            }
        }

        if (ok) {
            if (first_branch) {
                buf_append_cstr(cg->cur_body, "    {\n");
            } else {
                buf_append_cstr(cg->cur_body, "    } else {\n");
            }
            ok = cg_emit_throwing_branch(cg,
                                          e->as.match_expr.else_block,
                                          e->token);
            buf_append_cstr(cg->cur_body, "    }\n");
        }

        cgtype_free(target_type);
        if (!ok) {
            return false;
        }
        out->type = cgtype_new(CG_TYPE_VOID);
        out->c_expr = strdup("(void)0");
        out->owns_ref = false;
        return out->type != NULL && out->c_expr != NULL;
    }

    /* General match path (integer/string/bool target). */
    CGTypeKind tk;
    {
        tk = target_type != NULL ? target_type->kind : CG_TYPE_VOID;

        cgtype_free(target_type);

        if (tk != CG_TYPE_BOOL && tk != CG_TYPE_STRING && !cgtype_is_integer(tk)) {
            return cg_fail(cg, e->token,
                "CE0211", "codegen: match target must be integer, bool, string, or enum");
        }
    }

    bool first_branch = true;
    for (size_t i = 0; i < e->as.match_expr.branch_count; i++) {
        const FengMatchBranch *br = &e->as.match_expr.branches[i];
        if (br->label_count == 0) {
            return cg_fail(cg, br->token,
                "CE0210", "codegen: match branch has no labels");
        }
        Buf cond; buf_init(&cond);
        bool cond_ok = true;
        for (size_t li = 0; li < br->label_count; li++) {
            if (li) buf_append_cstr(&cond, " || ");
            if (!cg_emit_match_label_cond(cg, tgt_tmp, tk, &br->labels[li], &cond)) {
                cond_ok = false;
                break;
            }
        }
        if (!cond_ok) {
            buf_free(&cond);
            return false;
        }
        if (first_branch) {
            buf_append_fmt(cg->cur_body, "    if (%s) {\n", cond.data);
            first_branch = false;
        } else {
            buf_append_fmt(cg->cur_body, "    } else if (%s) {\n", cond.data);
        }
        buf_free(&cond);
        if (!cg_emit_throwing_branch(cg, br->body, br->token)) {
            return false;
        }
    }
    if (first_branch) {
        buf_append_cstr(cg->cur_body, "    {\n");
    } else {
        buf_append_cstr(cg->cur_body, "    } else {\n");
    }
    if (!cg_emit_throwing_branch(cg,
                                 e->as.match_expr.else_block,
                                 e->token)) {
        return false;
    }
    buf_append_cstr(cg->cur_body, "    }\n");

    out->type = cgtype_new(CG_TYPE_VOID);
    out->c_expr = strdup("(void)0");
    out->owns_ref = false;
    return out->type != NULL && out->c_expr != NULL;
}

static bool cg_emit_match_expr(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);

    if (!e->as.match_expr.else_block) {
        return cg_fail(cg, e->token,
            "CE0205", "codegen: match expression requires an else branch");
    }
    /* Allow each branch (including else) to end with either an expression
     * statement or a throw. Branches that terminate with throw never
     * produce a result value; they are emitted via cg_emit_block. */
    bool else_throws = cg_branch_terminates_with_throw(e->as.match_expr.else_block);
    const FengExpr *else_yield = else_throws ? NULL : cg_branch_yield_expr(e->as.match_expr.else_block);
    if (!else_yield && !else_throws) {
        return cg_fail(cg, e->token,
            "CE0206", "codegen: match expression else branch must end with an expression statement or throw");
    }
    for (size_t i = 0; i < e->as.match_expr.branch_count; i++) {
        if (!cg_branch_yield_expr(e->as.match_expr.branches[i].body) &&
            !cg_branch_terminates_with_throw(e->as.match_expr.branches[i].body)) {
            return cg_fail(cg, e->token,
                "CE0207", "codegen: match branch must end with an expression statement or throw");
        }
    }

    /* Derive the result type from the first branch that does not throw.
     * When every branch (including else) terminates with throw, no result
     * slot is required and the expression type is void. */
    const FengExpr *yield_for_type = else_yield;
    if (yield_for_type == NULL) {
        for (size_t i = 0; i < e->as.match_expr.branch_count; i++) {
            if (!cg_branch_terminates_with_throw(e->as.match_expr.branches[i].body)) {
                yield_for_type = cg_branch_yield_expr(e->as.match_expr.branches[i].body);
                break;
            }
        }
    }

    /* Materialise the target so it is evaluated exactly once and (for managed
     * targets like `string`) stays alive across every label comparison. */
    ExprResult tgt;
    if (!cg_emit_expr(cg, e->as.match_expr.target, &tgt)) {
        return false;
    }

    if (yield_for_type == NULL) {
        /* All branches throw — emit without a result slot. */
        char *tgt_tmp = cg_materialize_to_local(cg, &tgt, "_mt");
        er_free(&tgt);
        if (!tgt_tmp) {
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        /* Delegate to a helper that emits all branches as plain blocks. */
        bool ok = cg_emit_match_expr_all_throw(cg, e, tgt_tmp, out);
        free(tgt_tmp);
        return ok;
    }

    CGType *result_type = cg_probe_branch_yield_type(cg, yield_for_type);
    if (!result_type) {
        er_free(&tgt);
        return false;
    }
    bool managed = cgtype_is_managed(result_type);
    bool aggregate = cgtype_is_aggregate(result_type);
    CGExpressionJoinSlot join_slot = {0};

    char *ifv = cg_fresh_temp(cg, "_ifv");
    if (!ifv) {
        er_free(&tgt);
        cgtype_free(result_type);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    if (!cg_emit_expression_join_slot(cg,
                                      ifv,
                                      result_type,
                                      managed,
                                      aggregate,
                                      e->token,
                                      &join_slot)) {
        free(ifv);
        er_free(&tgt);
        cgtype_free(result_type);
        cg_expression_join_slot_free(&join_slot);
        return false;
    }

    if (tgt.type != NULL && tgt.type->kind == CG_TYPE_SPEC &&
        tgt.type->user_spec != NULL &&
        tgt.type->user_spec->form == FENG_SPEC_FORM_UNION) {
        const UserSpec *union_spec = tgt.type->user_spec;
        bool first_branch = true;
        bool ok = true;
        char *tgt_tmp = cg_materialize_to_local(cg, &tgt, "_umt");

        if (tgt_tmp == NULL) {
            free(ifv);
            er_free(&tgt);
            cgtype_free(result_type);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        er_free(&tgt);

        for (size_t branch_index = 0U;
             branch_index < e->as.match_expr.branch_count;
             ++branch_index) {
            const FengMatchBranch *branch = &e->as.match_expr.branches[branch_index];
            Buf condition;
            size_t first_member_index = 0U;
            size_t matched_member_count = 0U;

            if (branch->label_count == 0U) {
                ok = cg_fail(cg, branch->token,
                             "CE0210", "codegen: match branch has no labels");
                break;
            }

            buf_init(&condition);
            for (size_t label_index = 0U;
                 label_index < branch->label_count;
                 ++label_index) {
                size_t member_index = 0U;
                char *label_cond = NULL;

                if (!cg_union_member_index_for_label(cg,
                                                     union_spec,
                                                     &branch->labels[label_index],
                                                     &member_index)) {
                    ok = false;
                    break;
                }
                label_cond = cg_build_label_condition(cg, tgt_tmp, union_spec,
                                                       &branch->labels[label_index]);
                if (label_cond == NULL) {
                    ok = false;
                    break;
                }
                if (label_index != 0U) {
                    buf_append_cstr(&condition, " || ");
                }
                buf_append_cstr(&condition, label_cond);
                free(label_cond);
                if (matched_member_count == 0U) {
                    first_member_index = member_index;
                }
                matched_member_count++;
            }

            if (!ok) {
                buf_free(&condition);
                break;
            }

            if (first_branch) {
                buf_append_fmt(cg->cur_body, "    if (%s) {\n", condition.data);
                first_branch = false;
            } else {
                buf_append_fmt(cg->cur_body, "    } else if (%s) {\n", condition.data);
            }
            buf_free(&condition);

            {
                Scope *branch_scope = scope_push(cg->cur_scope);
                FengSlice alias_name = {NULL, 0U};

                if (branch_scope == NULL) {
                    ok = cg_fail(cg, branch->token, "IE0001", "codegen: out of memory");
                    break;
                }
                cg->cur_scope = branch_scope;
                if (branch->has_binding &&
                    branch->binding_name.data != NULL &&
                    branch->binding_name.length > 0U) {
                    alias_name = branch->binding_name;
                }
                if (matched_member_count == 1U) {
                    /* Check if any label has a chain for deepest-type narrowing */
                    const FengMatchLabel *chain_label = NULL;
                    for (size_t label_idx = 0U; label_idx < branch->label_count; ++label_idx) {
                        if (branch->labels[label_idx].type_chain_count > 0U) {
                            chain_label = &branch->labels[label_idx];
                            break;
                        }
                    }

                    if (chain_label != NULL) {
                        /* Chain label: build nested payload path to deepest type */
                        CGType *deepest_type = NULL;
                        char *payload_path = cg_build_chain_payload_path(cg,
                                                                          tgt_tmp,
                                                                          union_spec,
                                                                          chain_label,
                                                                          &deepest_type);
                        if (payload_path != NULL && deepest_type != NULL) {
                            if (alias_name.data != NULL && alias_name.length > 0U) {
                                char *alias_cstr = strndup(alias_name.data, alias_name.length);
                                bool add_ok = alias_cstr != NULL &&
                                              scope_add(branch_scope,
                                                        alias_cstr,
                                                        payload_path,
                                                        deepest_type,
                                                        true);
                                free(payload_path);
                                free(alias_cstr);
                                if (!add_ok) {
                                    cgtype_free(deepest_type);
                                    cg->cur_scope = branch_scope->parent;
                                    scope_pop_free(branch_scope);
                                    ok = cg_fail(cg, branch->token, "IE0001", "codegen: out of memory");
                                    break;
                                }
                            } else {
                                free(payload_path);
                                cgtype_free(deepest_type);
                            }
                        } else {
                            /* Fallback to first-level member if chain path building fails */
                            cgtype_free(deepest_type);
                            free(payload_path);
                            Buf payload_expr;
                            CGType *alias_type;

                            buf_init(&payload_expr);
                            buf_append_fmt(&payload_expr, "%s.payload.", tgt_tmp);
                            cg_append_union_payload_field_name(&payload_expr, first_member_index);
                            alias_type = cgtype_clone(union_spec->union_member_types[first_member_index]);

                            if (alias_name.data != NULL && alias_name.length > 0U) {
                                char *alias_cstr = strndup(alias_name.data, alias_name.length);

                                if (payload_expr.data == NULL || alias_type == NULL || alias_cstr == NULL ||
                                    !scope_add(branch_scope,
                                               alias_cstr,
                                               payload_expr.data,
                                               alias_type,
                                               true)) {
                                    cgtype_free(alias_type);
                                    free(alias_cstr);
                                    buf_free(&payload_expr);
                                    cg->cur_scope = branch_scope->parent;
                                    scope_pop_free(branch_scope);
                                    ok = cg_fail(cg, branch->token, "IE0001", "codegen: out of memory");
                                    break;
                                }
                                free(alias_cstr);
                            } else {
                                cgtype_free(alias_type);
                            }
                            buf_free(&payload_expr);
                        }
                    } else {
                        /* Non-chain label: use first-level member */
                        Buf payload_expr;
                        CGType *alias_type;

                        buf_init(&payload_expr);
                        buf_append_fmt(&payload_expr, "%s.payload.", tgt_tmp);
                        cg_append_union_payload_field_name(&payload_expr, first_member_index);
                        alias_type = cgtype_clone(union_spec->union_member_types[first_member_index]);

                        if (alias_name.data != NULL && alias_name.length > 0U) {
                            char *alias_cstr = strndup(alias_name.data, alias_name.length);

                            if (payload_expr.data == NULL || alias_type == NULL || alias_cstr == NULL ||
                                !scope_add(branch_scope,
                                           alias_cstr,
                                           payload_expr.data,
                                           alias_type,
                                           true)) {
                                cgtype_free(alias_type);
                                free(alias_cstr);
                                buf_free(&payload_expr);
                                cg->cur_scope = branch_scope->parent;
                                scope_pop_free(branch_scope);
                                ok = cg_fail(cg, branch->token, "IE0001", "codegen: out of memory");
                                break;
                            }
                            free(alias_cstr);
                        } else {
                            cgtype_free(alias_type);
                        }
                        buf_free(&payload_expr);
                    }
                }

                bool branch_throws =
                    cg_branch_terminates_with_throw(branch->body);
                if (branch_throws) {
                    if (!cg_emit_throwing_branch(cg,
                                                 branch->body,
                                                 branch->token)) {
                        ok = false;
                    }
                } else if (!cg_emit_branch_into_slot(cg,
                                              branch->body,
                                              ifv,
                                              result_type,
                                              managed,
                                              aggregate,
                                              &join_slot,
                                              e->token)) {
                    ok = false;
                }
                if (ok && !branch_throws) {
                    cg_release_scope(cg, branch_scope);
                }
                cg->cur_scope = branch_scope->parent;
                scope_pop_free(branch_scope);
                if (!ok) {
                    break;
                }
            }
        }

        if (ok) {
            if (first_branch) {
                buf_append_cstr(cg->cur_body, "    {\n");
            } else {
                buf_append_cstr(cg->cur_body, "    } else {\n");
            }

            {
                Scope *else_scope = scope_push(cg->cur_scope);

                if (else_scope == NULL) {
                    ok = cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                } else {
                    cg->cur_scope = else_scope;

                    if (ok) {
                        if (else_throws) {
                            if (!cg_emit_throwing_branch(cg,
                                                        e->as.match_expr.else_block,
                                                        e->token)) {
                                ok = false;
                            }
                        } else if (!cg_emit_branch_into_slot(cg,
                                                            e->as.match_expr.else_block,
                                                            ifv,
                                                            result_type,
                                                            managed,
                                                            aggregate,
                                                            &join_slot,
                                                            e->token)) {
                            ok = false;
                        }
                    }
                    if (ok && !else_throws) {
                        cg_release_scope(cg, else_scope);
                    }
                    cg->cur_scope = else_scope->parent;
                    scope_pop_free(else_scope);
                }
            }

            first_branch = false;
        }

        if (ok && !first_branch) {
            buf_append_cstr(cg->cur_body, "    }\n");
        }

        free(tgt_tmp);
        if (!ok) {
            free(ifv);
            cgtype_free(result_type);
            cg_expression_join_slot_free(&join_slot);
            return false;
        }

        out->c_expr = strdup(ifv);
        out->type = result_type;
        out->owns_ref = false;
        out->is_addressable = true;
        if (out->c_expr == NULL ||
            !cg_expression_join_slot_apply_to_result(&join_slot, out)) {
            er_free(out);
            free(ifv);
            cg_expression_join_slot_free(&join_slot);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }
        free(ifv);
        cg_expression_join_slot_free(&join_slot);
        return true;
    }

    {
        CGTypeKind tk = tgt.type->kind;

        if (tk != CG_TYPE_BOOL && tk != CG_TYPE_STRING && !cgtype_is_integer(tk)) {
            er_free(&tgt);
            free(ifv);
            cgtype_free(result_type);
            return cg_fail(cg, e->token,
                "CE0211", "codegen: match target must be integer, bool, or string");
        }
    }
    /* materialize_to_local registers managed +1 results into the current
     * scope and emits the cleanup_push, so the target survives every
     * comparison and is released at scope exit alongside other locals. */
    char *tgt_tmp = cg_materialize_to_local(cg, &tgt, "_mt");
    if (!tgt_tmp) {
        er_free(&tgt);
        free(ifv);
        cgtype_free(result_type);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    {
        CGTypeKind tk = tgt.type->kind;

        er_free(&tgt);

        bool first_branch = true;
        for (size_t i = 0; i < e->as.match_expr.branch_count; i++) {
            const FengMatchBranch *br = &e->as.match_expr.branches[i];
            if (br->label_count == 0) {
                free(ifv); free(tgt_tmp); cgtype_free(result_type);
                return cg_fail(cg, br->token,
                    "CE0210", "codegen: match branch has no labels");
            }
            Buf cond; buf_init(&cond);
            bool cond_ok = true;
            for (size_t li = 0; li < br->label_count; li++) {
                if (li) buf_append_cstr(&cond, " || ");
                if (!cg_emit_match_label_cond(cg, tgt_tmp, tk, &br->labels[li], &cond)) {
                    cond_ok = false;
                    break;
                }
            }
            if (!cond_ok) {
                buf_free(&cond);
                free(ifv); free(tgt_tmp); cgtype_free(result_type);
                return false;
            }
            if (first_branch) {
                buf_append_fmt(cg->cur_body, "    if (%s) {\n", cond.data);
                first_branch = false;
            } else {
                buf_append_fmt(cg->cur_body, "    } else if (%s) {\n", cond.data);
            }
            buf_free(&cond);
            if (cg_branch_terminates_with_throw(br->body)) {
                if (!cg_emit_throwing_branch(cg, br->body, br->token)) {
                    free(ifv); free(tgt_tmp); cgtype_free(result_type);
                    return false;
                }
            } else if (!cg_emit_branch_into_slot(cg, br->body, ifv, result_type,
                                                 managed, aggregate, &join_slot,
                                                 e->token)) {
                free(ifv); free(tgt_tmp); cgtype_free(result_type);
                return false;
            }
        }
        if (first_branch) {
            /* No value branches — degenerate to a plain block running else only.
             * Wrap in a C block so the assignment-driven slot setup is consistent. */
            buf_append_cstr(cg->cur_body, "    {\n");
        } else {
            buf_append_cstr(cg->cur_body, "    } else {\n");
        }
        if (cg_branch_terminates_with_throw(e->as.match_expr.else_block)) {
            if (!cg_emit_throwing_branch(cg,
                                         e->as.match_expr.else_block,
                                         e->token)) {
                free(ifv); free(tgt_tmp); cgtype_free(result_type);
                return false;
            }
        } else if (!cg_emit_branch_into_slot(cg, e->as.match_expr.else_block, ifv,
                                      result_type, managed, aggregate, &join_slot,
                                      e->token)) {
            free(ifv); free(tgt_tmp); cgtype_free(result_type);
            return false;
        }
        buf_append_cstr(cg->cur_body, "    }\n");
    }

    out->c_expr = strdup(ifv);
    out->type = result_type;
    out->owns_ref = false;
    out->is_addressable = true;

    if (out->c_expr == NULL ||
        !cg_expression_join_slot_apply_to_result(&join_slot, out)) {
        er_free(out);
        free(tgt_tmp);
        free(ifv);
        cg_expression_join_slot_free(&join_slot);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    free(tgt_tmp);
    free(ifv);
    cg_expression_join_slot_free(&join_slot);
    return true;
}

/* Emit codegen for infix match operator `target match pattern`.
 *
 * Materialises the target into a local `_mt`, then emits the OR of each
 * label's match condition. The result is always bool. When `has_binding`
 * is true (union-form target with binding), the binding variable is
 * registered in the current scope as an alias to either `_mt.payload.mX`
 * (single-member subset) or `_mt` (multi-member subset), so it is visible
 * to subsequent `&&` right operands and to if/while body scopes. The
 * alias is only safe to dereference when the match condition is true;
 * `&&` short-circuit and if/while control flow guarantee that. */
static bool cg_emit_match_op(CG *cg, const FengExpr *e, ExprResult *out) {
    er_init(out);

    ExprResult tgt;
    if (!cg_emit_expr(cg, e->as.match_op.target, &tgt)) {
        return false;
    }
    if (tgt.type == NULL) {
        er_free(&tgt);
        return cg_fail(cg, e->token,
            "CE0272", "codegen: infix match target has no resolved type");
    }

    /* Capture target type info before cg_materialize_to_local transfers
     * ownership of tgt.type into the scope. */
    bool is_union = tgt.type->kind == CG_TYPE_SPEC &&
                    tgt.type->user_spec != NULL &&
                    tgt.type->user_spec->form == FENG_SPEC_FORM_UNION;
    const UserSpec *union_spec = is_union ? tgt.type->user_spec : NULL;
    CGTypeKind target_kind = tgt.type->kind;

    char *tgt_tmp = cg_materialize_to_local(cg, &tgt, "_mt");
    if (tgt_tmp == NULL) {
        er_free(&tgt);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    er_free(&tgt);

    Buf cond;
    buf_init(&cond);
    bool ok = true;
    size_t first_member_index = 0U;
    size_t matched_member_count = 0U;

    if (is_union) {
        for (size_t i = 0U; i < e->as.match_op.label_count; ++i) {
            size_t member_index = 0U;
            char *label_cond = NULL;
            if (!cg_union_member_index_for_label(cg,
                                                  union_spec,
                                                  &e->as.match_op.labels[i],
                                                  &member_index)) {
                ok = false;
                break;
            }
            label_cond = cg_build_label_condition(cg, tgt_tmp, union_spec,
                                                   &e->as.match_op.labels[i]);
            if (label_cond == NULL) {
                ok = false;
                break;
            }
            if (i != 0U) {
                buf_append_cstr(&cond, " || ");
            }
            buf_append_cstr(&cond, label_cond);
            free(label_cond);
            if (matched_member_count == 0U) {
                first_member_index = member_index;
            }
            ++matched_member_count;
        }
    } else {
        if (target_kind != CG_TYPE_BOOL &&
            target_kind != CG_TYPE_STRING &&
            !cgtype_is_integer(target_kind)) {
            buf_free(&cond);
            free(tgt_tmp);
            return cg_fail(cg, e->token,
                "CE0270", "codegen: match target must be integer, bool, string, or enum");
        }
        for (size_t i = 0U; i < e->as.match_op.label_count; ++i) {
            if (i != 0U) {
                buf_append_cstr(&cond, " || ");
            }
            if (!cg_emit_match_label_cond(cg,
                                           tgt_tmp,
                                           target_kind,
                                           &e->as.match_op.labels[i],
                                           &cond)) {
                ok = false;
                break;
            }
        }
    }

    if (!ok) {
        buf_free(&cond);
        free(tgt_tmp);
        return false;
    }

    /* If has_binding (guaranteed union-form by semantic), register the
     * binding variable as an alias in the current scope. Single-member
     * subsets alias to the member payload; multi-member subsets alias
     * to the target tmp itself (the union value). The alias is read
     * only when the match condition is true (enforced by `&&` short-
     * circuit and if/while control flow), so the alias access is safe. */
    if (e->as.match_op.has_binding &&
        e->as.match_op.binding_name.data != NULL &&
        e->as.match_op.binding_name.length > 0U) {
        FengSlice alias_name = e->as.match_op.binding_name;
        char *alias_cstr = strndup(alias_name.data, alias_name.length);

        if (alias_cstr == NULL) {
            buf_free(&cond);
            free(tgt_tmp);
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }

        /* Check if any label has a chain for deepest-type narrowing */
        const FengMatchLabel *chain_label = NULL;
        for (size_t i = 0U; i < e->as.match_op.label_count; ++i) {
            if (e->as.match_op.labels[i].type_chain_count > 0U) {
                chain_label = &e->as.match_op.labels[i];
                break;
            }
        }

        if (chain_label != NULL && matched_member_count == 1U) {
            /* Chain label: build nested payload path to deepest type */
            CGType *deepest_type = NULL;
            char *payload_path = cg_build_chain_payload_path(cg,
                                                              tgt_tmp,
                                                              union_spec,
                                                              chain_label,
                                                              &deepest_type);
            if (payload_path != NULL && deepest_type != NULL) {
                bool add_ok = scope_add(cg->cur_scope,
                                       alias_cstr,
                                       payload_path,
                                       deepest_type,
                                       true);
                free(payload_path);
                free(alias_cstr);
                if (!add_ok) {
                    cgtype_free(deepest_type);
                    buf_free(&cond);
                    free(tgt_tmp);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
            } else {
                /* Fallback to first-level member if chain path building fails */
                cgtype_free(deepest_type);
                free(payload_path);
                Buf payload_expr;
                CGType *alias_type;

                buf_init(&payload_expr);
                buf_append_fmt(&payload_expr, "%s.payload.", tgt_tmp);
                cg_append_union_payload_field_name(&payload_expr, first_member_index);
                alias_type = cgtype_clone(union_spec->union_member_types[first_member_index]);
                if (payload_expr.data == NULL || alias_type == NULL ||
                    !scope_add(cg->cur_scope,
                               alias_cstr,
                               payload_expr.data,
                               alias_type,
                               true)) {
                    cgtype_free(alias_type);
                    free(alias_cstr);
                    buf_free(&payload_expr);
                    buf_free(&cond);
                    free(tgt_tmp);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
                buf_free(&payload_expr);
                free(alias_cstr);
            }
        } else if (matched_member_count == 1U) {
            Buf payload_expr;
            CGType *alias_type;

            buf_init(&payload_expr);
            buf_append_fmt(&payload_expr, "%s.payload.", tgt_tmp);
            cg_append_union_payload_field_name(&payload_expr, first_member_index);
            alias_type = cgtype_clone(union_spec->union_member_types[first_member_index]);
            if (payload_expr.data == NULL || alias_type == NULL ||
                !scope_add(cg->cur_scope,
                           alias_cstr,
                           payload_expr.data,
                           alias_type,
                           true)) {
                cgtype_free(alias_type);
                free(alias_cstr);
                buf_free(&payload_expr);
                buf_free(&cond);
                free(tgt_tmp);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            buf_free(&payload_expr);
            free(alias_cstr);
        } else {
            /* Multi-member subset: alias to the target tmp (the union
             * value). Semantic narrowing guarantees type safety at the
             * source level; at codegen the binding just refers to the
             * whole union value. */
            const Local *tgt_local = scope_lookup(cg->cur_scope,
                                                    tgt_tmp,
                                                    strlen(tgt_tmp));
            CGType *alias_type;
            if (tgt_local == NULL) {
                free(alias_cstr);
                buf_free(&cond);
                free(tgt_tmp);
                return cg_fail(cg, e->token,
                    "CE0273", "codegen: infix match target tmp not in scope");
            }
            alias_type = cgtype_clone(tgt_local->type);
            if (alias_type == NULL ||
                !scope_add(cg->cur_scope,
                           alias_cstr,
                           tgt_tmp,
                           alias_type,
                           true)) {
                cgtype_free(alias_type);
                free(alias_cstr);
                buf_free(&cond);
                free(tgt_tmp);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            free(alias_cstr);
        }
    }

    out->c_expr = strndup(cond.data, cond.length);
    out->type = cgtype_new(CG_TYPE_BOOL);
    out->owns_ref = false;

    buf_free(&cond);
    free(tgt_tmp);
    return out->c_expr != NULL && out->type != NULL;
}

static bool cg_type_ref_is_unknown_catch_type(const FengTypeRef *ref) {
    if (ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.segment_count != 1U) {
        return false;
    }
    FengSlice name = ref->as.named.segments[0];
    return name.length == strlen("unknown") &&
           memcmp(name.data, "unknown", name.length) == 0;
}

static bool cg_emit_try_expr_catch_binding(CG *cg,
                                           const FengTryCatchClause *clause,
                                           const CGType *catch_type,
                                           bool is_unknown,
                                           FengToken err_token) {
    char *feng_name = strndup(clause->name.data, clause->name.length);
    char *c_name = NULL;

    if (feng_name == NULL) {
        return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
    }
    c_name = cg_local_cname(cg, clause->name.data, clause->name.length);
    if (c_name == NULL) {
        free(feng_name);
        return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
    }

    if (is_unknown) {
        CGType *local_type = cgtype_new(CG_TYPE_OBJECT);

        if (local_type == NULL) {
            free(c_name);
            free(feng_name);
            return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "        void *%s = feng_caught_value();\n",
                       c_name);
        if (!scope_add(cg->cur_scope,
                       feng_name,
                       c_name,
                       local_type,
                       true)) {
            free(c_name);
            free(feng_name);
            return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
        }
        if (!scope_mark_unknown_exception(cg->cur_scope,
                                          feng_name,
                                          strlen(feng_name))) {
            free(c_name);
            free(feng_name);
            return cg_fail(cg, err_token,
                           "CE0212", "codegen: failed to register unknown catch binding");
        }
        free(c_name);
        free(feng_name);
        return true;
    }

    if (catch_type == NULL) {
        free(c_name);
        free(feng_name);
        return cg_fail(cg, err_token, "CE0213", "codegen: missing catch binding type");
    }
    /* Scalars, enums, tuples, and @value types all extract from their
     * statically known ValueBox<T>. Aggregate values retain managed fields
     * through the existing aggregate assignment path. */
    if (cg_type_has_value_box(catch_type)) {
        CGValueBoxInfo box_info;
        char *cty = cg_ctype_dup(catch_type);
        bool is_user_value = cg_type_is_value_semantics(catch_type);

        if (cty == NULL ||
            !cg_value_box_info_for_type(cg,
                                        catch_type,
                                        err_token,
                                        &box_info)) {
            free(cty);
            free(c_name);
            free(feng_name);
            return false;
        }

        if (cgtype_is_aggregate(catch_type)) {
            buf_append_fmt(cg->cur_body,
                           "        %s %s;\n"
                           "        memset(&%s, 0, sizeof %s);\n",
                           cty,
                           c_name,
                           c_name,
                           c_name);

            const char *agg_desc = cg_aggregate_desc_name(catch_type);
            if (agg_desc == NULL) {
                free(cty);
                cg_value_box_info_dispose(&box_info);
                free(c_name);
                free(feng_name);
                return cg_fail(cg, err_token,
                               "CE0214", "codegen: missing aggregate descriptor for value-type catch binding");
            }
            buf_append_fmt(cg->cur_body,
                           "        feng_aggregate_assign(&%s, "
                           "&((struct %s *)feng_caught_value())->value, &%s);\n",
                           c_name,
                           box_info.struct_name,
                           agg_desc);
        } else {
            buf_append_fmt(cg->cur_body,
                           "        %s %s = ((struct %s *)feng_caught_value())->value;\n",
                           cty,
                           c_name,
                           box_info.struct_name);
        }
        free(cty);
        cg_value_box_info_dispose(&box_info);

        if (!scope_add(cg->cur_scope,
                       feng_name,
                       c_name,
                       cgtype_clone(catch_type),
                       !is_user_value)) {
            free(c_name);
            free(feng_name);
            return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
        }
        if (cgtype_is_aggregate(catch_type)) {
            cg_emit_cleanup_push_for_aggregate_local(cg, c_name, catch_type);
        }
        free(c_name);
        free(feng_name);
        return true;
    }
    {
        char *cty = cg_ctype_dup(catch_type);

        if (cty == NULL) {
            free(c_name);
            free(feng_name);
            return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "        %s %s = (%s)feng_caught_value();\n",
                       cty,
                       c_name,
                       cty);
        free(cty);
    }
    if (!scope_add(cg->cur_scope,
                   feng_name,
                   c_name,
                   cgtype_clone(catch_type),
                   true)) {
        free(c_name);
        free(feng_name);
        return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
    }
    free(c_name);
    free(feng_name);
    return true;
}

static bool cg_emit_try_expr_body_to_slot(CG *cg,
                                          const FengExpr *body,
                                          const char *slot_name,
                                          const CGType *result_type,
                                          bool managed,
                                          bool aggregate,
                                          const CGExpressionJoinSlot *slot,
                                          FengToken err_token) {
    Scope *body_scope = scope_push(cg->cur_scope);
    if (body_scope == NULL) {
        return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
    }
    cg->cur_scope = body_scope;

    ExprResult r;
    bool ok;

    if (!cg_emit_expr(cg, body, &r)) {
        cg->cur_scope = body_scope->parent;
        scope_pop_free(body_scope);
        return false;
    }
    ok = cg_assign_expr_result_to_slot(cg,
                                       slot_name,
                                       result_type,
                                       managed,
                                       aggregate,
                                       slot,
                                       &r,
                                       err_token);
    er_free(&r);
    if (ok) {
        cg_release_scope(cg, body_scope);
    }
    cg->cur_scope = body_scope->parent;
    scope_pop_free(body_scope);
    return ok;
}

static bool cg_discard_expr_result(CG *cg, ExprResult *result) {
    if ((cgtype_is_managed(result->type) || cgtype_is_aggregate(result->type)) &&
        result->owns_ref) {
        return cg_materialize_to_local(cg, result, "_t") != NULL;
    }
    buf_append_fmt(cg->cur_body, "        (void)(%s);\n", result->c_expr);
    return true;
}

static bool cg_emit_try_expr_body_discard(CG *cg,
                                          const FengExpr *body,
                                          FengToken err_token) {
    Scope *body_scope = scope_push(cg->cur_scope);
    if (body_scope == NULL) {
        return cg_fail(cg, err_token, "IE0001", "codegen: out of memory");
    }
    cg->cur_scope = body_scope;

    ExprResult r;
    bool ok;

    if (!cg_emit_expr(cg, body, &r)) {
        cg->cur_scope = body_scope->parent;
        scope_pop_free(body_scope);
        return false;
    }
    ok = cg_discard_expr_result(cg, &r);
    er_free(&r);
    if (ok) {
        cg_release_scope(cg, body_scope);
    }
    cg->cur_scope = body_scope->parent;
    scope_pop_free(body_scope);
    return ok;
}

static bool cg_emit_try_catch_block_to_slot(CG *cg,
                                            const FengBlock *block,
                                            const char *slot_name,
                                            const CGType *result_type,
                                            bool managed,
                                            bool aggregate,
                                            const CGExpressionJoinSlot *slot,
                                            FengToken err_token) {
    if (result_type->kind == CG_TYPE_VOID) {
        return block == NULL || cg_emit_block(cg, block);
    }
    if (block == NULL || block->statement_count == 0U) {
        return cg_fail(cg, err_token,
                       "CE0215", "codegen: catch block must produce a try-expression value");
    }

    const FengExpr *yield = cg_branch_yield_expr(block);
    if (yield == NULL) {
        return cg_emit_block(cg, block);
    }

    bool ok = true;
    for (size_t i = 0; i + 1U < block->statement_count; i++) {
        if (!cg_emit_stmt(cg, block->statements[i])) {
            ok = false;
            break;
        }
    }
    if (ok) {
        ok = cg_emit_try_expr_body_to_slot(cg,
                                           yield,
                                           slot_name,
                                           result_type,
                                           managed,
                                           aggregate,
                                           slot,
                                           err_token);
    }
    return ok;
}

static bool cg_emit_try_expr(CG *cg,
                             const FengExpr *e,
                             ExprResult *out,
                             bool result_required) {
    er_init(out);

    CGType *result_type = result_required
                              ? cg_probe_expr_type(cg, e->as.try_expr.body)
                              : cgtype_new(CG_TYPE_VOID);
    if (result_type == NULL) {
        return false;
    }

    bool managed = result_required && cgtype_is_managed(result_type);
    bool aggregate = result_required && cgtype_is_aggregate(result_type);
    bool is_void = result_type->kind == CG_TYPE_VOID;
    CGExpressionJoinSlot join_slot = {0};

    int try_id = cg->label_counter++;
    char begin_label[64];
    char end_label[64];
    char landing_label[64];
    char done_label[64];
    char catch_done_label[64];
    char clauses_name[64];
    char region_name[64];
    char registered_name[64];
    char keep_landing_name[64];
    char caught_clause_name[64];
    snprintf(begin_label, sizeof begin_label, "_try_begin_%d", try_id);
    snprintf(end_label, sizeof end_label, "_try_end_%d", try_id);
    snprintf(landing_label, sizeof landing_label, "_try_lpad_%d", try_id);
    snprintf(done_label, sizeof done_label, "_try_done_%d", try_id);
    snprintf(catch_done_label, sizeof catch_done_label, "_try_after_catch_%d", try_id);
    snprintf(clauses_name, sizeof clauses_name, "_try_clauses_%d", try_id);
    snprintf(region_name, sizeof region_name, "_try_region_%d", try_id);
    snprintf(registered_name, sizeof registered_name, "_try_registered_%d", try_id);
    snprintf(keep_landing_name, sizeof keep_landing_name, "_try_keep_lpad_%d", try_id);
    snprintf(caught_clause_name, sizeof caught_clause_name, "_try_clause_%d", try_id);

    char *slot_name = cg_fresh_temp(cg, "_tryv");
    char *marker_name = cg_fresh_temp(cg, "_try_marker");
    if (slot_name == NULL || marker_name == NULL) {
        free(slot_name);
        free(marker_name);
        cgtype_free(result_type);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    if (!is_void) {
        if (!cg_emit_expression_join_slot(cg,
                                          slot_name,
                                          result_type,
                                          managed,
                                          aggregate,
                                          e->token,
                                          &join_slot)) {
            free(slot_name);
            free(marker_name);
            cgtype_free(result_type);
            cg_expression_join_slot_free(&join_slot);
            return false;
        }
    }

    buf_append_fmt(cg->cur_body,
                   "    static const FengCatchClause %s[%zu] = {\n",
                   clauses_name,
                   e->as.try_expr.clause_count);
    for (size_t i = 0U; i < e->as.try_expr.clause_count; i++) {
        const FengTryCatchClause *clause = &e->as.try_expr.clauses[i];
        bool is_unknown = cg_type_ref_is_unknown_catch_type(clause->type);
        bool is_anonymous = clause->type == NULL && clause->name.length == 0U;
        CGType *catch_type = NULL;
        char *desc_expr = NULL;

        if (!is_unknown && !is_anonymous) {
            if (!cg_resolve_type(cg, clause->type, &clause->token, &catch_type)) {
                free(slot_name);
                free(marker_name);
                cgtype_free(result_type);
                return false;
            }
            if (!cg_exception_descriptor_expr_for_type(cg,
                                                       catch_type,
                                                       clause->token,
                                                       &desc_expr)) {
                cgtype_free(catch_type);
                free(slot_name);
                free(marker_name);
                cgtype_free(result_type);
                return false;
            }
        }
        buf_append_fmt(cg->cur_body,
                       "        { %s },\n",
                       (is_unknown || is_anonymous) ? "NULL" : desc_expr);
        cgtype_free(catch_type);
        free(desc_expr);
    }
    buf_append_fmt(cg->cur_body,
                   "    };\n"
                   "    static FengLSDA %s;\n"
                   "    static bool %s = false;\n"
                   "    static volatile int %s = 0;\n"
                   "    if (!%s) {\n"
                   "        %s = (FengLSDA){ &&%s, &&%s, &&%s, %s, %zu };\n"
                   "        feng_register_lsda(&%s, 1);\n"
                   "        %s = true;\n"
                   "    }\n"
                   "    if (%s) goto %s;\n"
                   "    FengFrameMarker %s;\n"
                   "    feng_try_frame_push(&%s);\n"
                   "    {\n"
                   "    %s: ;\n",
                   region_name,
                   registered_name,
                   keep_landing_name,
                   registered_name,
                   region_name,
                   begin_label,
                   end_label,
                   landing_label,
                   clauses_name,
                   e->as.try_expr.clause_count,
                   region_name,
                   registered_name,
                   keep_landing_name,
                   landing_label,
                   marker_name,
                   marker_name,
                   begin_label);
    cg->try_depth++;
    cg->active_exception_frame_count++;
    bool ok = result_required
                  ? cg_emit_try_expr_body_to_slot(cg,
                                                  e->as.try_expr.body,
                                                  slot_name,
                                                  result_type,
                                                  managed,
                                                  aggregate,
                                                  &join_slot,
                                                  e->token)
                  : cg_emit_try_expr_body_discard(cg,
                                                  e->as.try_expr.body,
                                                  e->token);
    cg->active_exception_frame_count--;
    cg->try_depth--;
    if (!ok) {
        free(slot_name);
        free(marker_name);
        cgtype_free(result_type);
        return false;
    }
    buf_append_fmt(cg->cur_body,
                   "    %s: ;\n"
                   "    }\n"
                   "    feng_frame_pop();\n"
                   "    goto %s;\n"
                   "    %s: ;\n"
                   "    feng_frame_release_to(&%s);\n"
                   "    int %s = feng_caught_clause();\n",
                   end_label,
                   done_label,
                   landing_label,
                   marker_name,
                   caught_clause_name);

    for (size_t i = 0U; i < e->as.try_expr.clause_count; i++) {
        const FengTryCatchClause *clause = &e->as.try_expr.clauses[i];
        bool is_unknown = cg_type_ref_is_unknown_catch_type(clause->type);
        bool is_anonymous = clause->type == NULL && clause->name.length == 0U;
        CGType *catch_type = NULL;

        if (!is_unknown && !is_anonymous) {
            if (!cg_resolve_type(cg, clause->type, &clause->token, &catch_type)) {
                free(slot_name);
                free(marker_name);
                cgtype_free(result_type);
                return false;
            }
        }

        buf_append_fmt(cg->cur_body,
                   "    %s (%s == %zu) {\n",
                   i == 0U ? "if" : "else if",
                   caught_clause_name,
                   i);

        Scope *catch_scope = scope_push(cg->cur_scope);
        if (catch_scope == NULL) {
            cgtype_free(catch_type);
            free(slot_name);
            free(marker_name);
            cgtype_free(result_type);
            return cg_fail(cg, clause->token, "IE0001", "codegen: out of memory");
        }
        cg->cur_scope = catch_scope;
        if (!is_anonymous &&
            !cg_emit_try_expr_catch_binding(cg,
                                            clause,
                                            catch_type,
                                            is_unknown,
                                            clause->token)) {
            cg->cur_scope = catch_scope->parent;
            scope_pop_free(catch_scope);
            cgtype_free(catch_type);
            free(slot_name);
            free(marker_name);
            cgtype_free(result_type);
            return false;
        }
        cg->try_depth++;
        cg->active_caught_unwind_count++;
        ok = result_required
             ? cg_emit_try_catch_block_to_slot(cg,
                               clause->body,
                               slot_name,
                               result_type,
                               managed,
                               aggregate,
                               &join_slot,
                               clause->token)
             : cg_emit_block(cg, clause->body);
        cg->active_caught_unwind_count--;
        cg->try_depth--;
        if (ok) {
            cg_release_scope(cg, catch_scope);
        }
        cg->cur_scope = catch_scope->parent;
        scope_pop_free(catch_scope);
        if (!ok) {
            cgtype_free(catch_type);
            free(slot_name);
            free(marker_name);
            cgtype_free(result_type);
            return false;
        }
        buf_append_cstr(cg->cur_body,
                        "        feng_release_unwind_exception();\n"
                        "        goto ");
        buf_append_cstr(cg->cur_body, catch_done_label);
        buf_append_cstr(cg->cur_body,
                        ";\n"
                        "    }\n");
        cgtype_free(catch_type);
    }

    if (e->as.try_expr.clause_count > 0U) {
        buf_append_cstr(cg->cur_body,
                        "    else {\n"
                        "        feng_rethrow();\n"
                        "    }\n");
    } else {
        buf_append_cstr(cg->cur_body,
                        "    feng_rethrow();\n");
    }
    buf_append_fmt(cg->cur_body,
                   "    %s: ;\n"
                   "    %s: ;\n",
                   catch_done_label,
                   done_label);

    out->c_expr = strdup(is_void ? "((void)0)" : slot_name);
    out->type = result_type;
    out->owns_ref = false;
    out->is_addressable = !is_void;
    if (!cg_expression_join_slot_apply_to_result(&join_slot, out)) {
        er_free(out);
        free(slot_name);
        free(marker_name);
        cg_expression_join_slot_free(&join_slot);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }

    free(slot_name);
    free(marker_name);
    cg_expression_join_slot_free(&join_slot);
    return out->c_expr != NULL;
}

/* Lower one semantic-selected nominal spec path. The raw source is evaluated
 * into an unowned C alias exactly once; ownership remains attached to the
 * projected ExprResult, so the projection itself emits no retain/release. */
static bool cg_emit_object_spec_upcast(CG *cg,
                                       const FengExpr *e,
                                       const FengSpecCoercionSite *site,
                                       ExprResult *out) {
    ExprResult source;
    const UserSpec *current_spec;
    CGType *target_type = NULL;
    const char *source_tmp;
    Buf witness_expr;
    Buf result_expr;
    bool source_owns_ref;

    er_init(out);
    if (cg == NULL || e == NULL || site == NULL ||
        site->form != FENG_SPEC_COERCION_FORM_OBJECT_UPCAST ||
        site->object_upcast_parent_indices == NULL ||
        site->object_upcast_parent_index_count == 0U) {
        return false;
    }
    if (!cg_emit_expr_raw(cg, e, &source)) {
        return false;
    }
    if (source.type == NULL || source.type->kind != CG_TYPE_SPEC ||
        source.type->user_spec == NULL) {
        er_free(&source);
        return cg_fail(cg, e->token,
                       "CE0196", "codegen: object-spec upcast source is not an object-form spec value");
    }
    current_spec = source.type->user_spec;
    source_owns_ref = source.owns_ref;
    if (!cg_materialize_ownership_alias(cg, &source, "_spec_view")) {
        er_free(&source);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    source_tmp = source.c_expr;

    buf_init(&witness_expr);
    buf_append_fmt(&witness_expr, "%s.witness", source_tmp);
    for (size_t path_index = 0U;
         path_index < site->object_upcast_parent_index_count;
         ++path_index) {
        size_t parent_index =
            site->object_upcast_parent_indices[path_index];
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, current_spec, parent_index);

        if (parent_spec == NULL) {
            buf_free(&witness_expr);
            er_free(&source);
            return cg_fail(cg, e->token,
                           "CE0198", "codegen: semantic object-spec upcast path contains an invalid direct-parent index");
        }
        buf_append_cstr(&witness_expr, "->");
        cg_append_spec_parent_field_name(&witness_expr, parent_spec);
        current_spec = parent_spec;
    }
    if (!cg_resolve_type(cg,
                         site->target_spec_type_ref,
                         &e->token,
                         &target_type)) {
        buf_free(&witness_expr);
        er_free(&source);
        return false;
    }
    if (target_type == NULL || target_type->kind != CG_TYPE_SPEC ||
        target_type->user_spec == NULL || target_type->user_spec != current_spec) {
        cgtype_free(target_type);
        buf_free(&witness_expr);
        er_free(&source);
        return cg_fail(cg, e->token,
                       "CE0199", "codegen: object-spec upcast path does not end at its semantic target");
    }

    buf_init(&result_expr);
    buf_append_fmt(&result_expr,
                   "((struct %s){ .subject = %s.subject, .witness = %s })",
                   target_type->user_spec->c_value_struct_name,
                   source_tmp,
                   witness_expr.data);
    buf_free(&witness_expr);
    er_free(&source);
    if (result_expr.data == NULL) {
        cgtype_free(target_type);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    out->c_expr = result_expr.data;
    out->type = target_type;
    out->owns_ref = source_owns_ref;
    return true;
}

/* Emits an expression and applies one already-resolved spec conversion, but
 * deliberately does not consult the union sidecar. Union emission uses this
 * helper for its selected leaf, then wraps the converted value in union tags. */
static bool cg_emit_expr_with_spec_coercion(
        CG *cg,
        const FengExpr *e,
        const FengSpecCoercionSite *cs,
        ExprResult *out) {
    if (cg->failed) return false;
    bool ok;

    if (cs && cs->form == FENG_SPEC_COERCION_FORM_OBJECT_UPCAST) {
        return cg_emit_object_spec_upcast(cg, e, cs, out);
    }
    if (cs && cs->form == FENG_SPEC_COERCION_FORM_ABI_FUNCTION_POINTER) {
        return cg_emit_abi_function_pointer_site(cg, e, cs, out);
    }
    if (cs && cs->form == FENG_SPEC_COERCION_FORM_CALLABLE) {
        return cg_emit_callable_spec_coercion(cg, e, cs, out);
    }
    ok = cg_emit_expr_raw(cg, e, out);
    if (!ok) return false;

    /* Step 4b — apply spec coercion if the analyzer marked this expression as
     * a coercion site. For object-form, we wrap the produced object reference
     * into a fat-spec value `{ .subject = expr, .witness = &Witness }`. */
    if (cs && (cs->form == FENG_SPEC_COERCION_FORM_OBJECT ||
               cs->form == FENG_SPEC_COERCION_FORM_INTERSECTION)) {
        if (out->type == NULL) {
            return cg_fail(cg, e->token,
                "CE0217", "codegen: spec coercion source type is missing");
        }
        const UserSpec *tgt_s = NULL;
        if (!cg_resolve_coercion_target_user_spec(cg, cs, e->token, &tgt_s)) {
            return false;
        }
        if (tgt_s == NULL) {
            return cg_fail(cg, e->token,
                "CE0024", "codegen: coercion target did not resolve to a concrete spec instance");
        }
        const char *witness_var = NULL;
        bool subject_owned = false;
        char *subject_expr = NULL;

        if (cs->src_subject_key.kind == FENG_SEMANTIC_SUBJECT_KEY_TYPE_DECL &&
            (cs->src_subject_key.as.type_decl == NULL ||
             cs->src_subject_key.as.type_decl->kind != FENG_DECL_ENUM)) {
            const UserType *src_t = cg_find_user_type_by_decl(cg, cs->src_subject_key.as.type_decl);

            if (!src_t) {
                return cg_fail(cg, e->token,
                    "CE0218", "codegen: spec coercion references type outside current codegen scope");
            }
            if (out->type->kind == CG_TYPE_OBJECT && out->type->user != NULL) {
                src_t = cg_user_type_nominal_identity(
                    cg, out->type->user);
                if (src_t == NULL) {
                    return cg_fail(
                        cg,
                        e->token,
                        "CE0218", "codegen: generic owner nominal type is not registered in current codegen scope");
                }
                if (cg_user_type_is_value_semantics(src_t)) {
                    if (!cg_ensure_value_box_witness_instance(cg,
                                                              src_t,
                                                              tgt_s,
                                                              e->token,
                                                              &witness_var)) {
                        return false;
                    }
                    if (!cg_emit_value_box_subject(cg,
                                                   out,
                                                   e->token,
                                                   &subject_expr)) {
                        return false;
                    }
                    subject_owned = true;
                } else {
                    if (!cg_ensure_witness_instance_for_type(cg,
                                                             src_t,
                                                             tgt_s,
                                                             e->token,
                                                             &witness_var)) {
                        return false;
                    }
                    /* Evaluate exactly once while preserving a constructor
                     * result's +1 for the resulting fat value. */
                    subject_owned = out->owns_ref;
                    if (!cg_materialize_ownership_alias(cg, out, "_t")) {
                        return cg_fail(cg, e->token,
                                       "IE0001", "codegen: out of memory");
                    }
                    subject_expr = strdup(out->c_expr);
                }
            } else {
                if (!cg_ensure_witness_instance(cg,
                                                &cs->src_subject_key,
                                                tgt_s,
                                                FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER,
                                                e->token,
                                                &witness_var)) {
                    return false;
                }
                /* Evaluate exactly once while preserving a managed source's
                 * ownership for the resulting fat value. */
                subject_owned = out->owns_ref;
                if (!cg_materialize_ownership_alias(cg, out, "_t")) {
                    return cg_fail(cg, e->token,
                                   "IE0001", "codegen: out of memory");
                }
                subject_expr = strdup(out->c_expr);
            }
        } else {
            if (!cg_ensure_witness_instance_for_subject_key(cg,
                                                            &cs->src_subject_key,
                                                            tgt_s,
                                                            cs->object_subject_storage,
                                                            e->token,
                                                            &witness_var)) {
                return false;
            }

            if (out->type->kind == CG_TYPE_BOOL ||
                out->type->kind == CG_TYPE_I8 || out->type->kind == CG_TYPE_I16 ||
                out->type->kind == CG_TYPE_I32 || out->type->kind == CG_TYPE_I64 ||
                out->type->kind == CG_TYPE_U8 || out->type->kind == CG_TYPE_U16 ||
                out->type->kind == CG_TYPE_U32 || out->type->kind == CG_TYPE_U64 ||
                out->type->kind == CG_TYPE_F32 || out->type->kind == CG_TYPE_F64) {
                if (!cg_emit_value_box_subject(cg,
                                               out,
                                               e->token,
                                               &subject_expr)) {
                    return false;
                }
                subject_owned = true;
            } else if (out->type->kind == CG_TYPE_STRING || out->type->kind == CG_TYPE_ARRAY) {
                subject_owned = out->owns_ref;
                if (!cg_materialize_ownership_alias(cg, out, "_t")) {
                    return cg_fail(cg, e->token,
                                   "IE0001", "codegen: out of memory");
                }
                subject_expr = strdup(out->c_expr);
            } else {
                return cg_fail(cg, e->token,
                    "CE0220", "codegen: object-form spec coercion source kind is invalid");
            }
        }
        if (subject_expr == NULL) {
            return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        }

        Buf b; buf_init(&b);
        buf_append_fmt(&b,
            "((struct %s){ .subject = (void *)%s, .witness = &%s })",
            tgt_s->c_value_struct_name, subject_expr, witness_var);
        free(subject_expr);
        free(out->c_expr); out->c_expr = b.data;
        cgtype_free(out->type);
        out->type = cgtype_new(CG_TYPE_SPEC);
        if (!out->type) return false;
        out->type->user_spec = tgt_s;
        /* Managed constructor results transfer their +1 into the fat value;
         * borrowed subjects remain borrowed. Boxed subjects are always +1. */
        out->owns_ref = subject_owned;
        out->is_addressable = false;
    }
    return true;
}

/* Emits the complete conversion pipeline for one expression. A union entry
 * first converts to its selected leaf member and only then constructs the
 * outer tagged-union representation. */
static bool cg_emit_expr(CG *cg, const FengExpr *e, ExprResult *out) {
    const FengSpecCoercionSite *spec_site;
    const FengUnionCoercionSite *union_site;

    if (cg->failed) {
        return false;
    }
    spec_site = feng_semantic_lookup_spec_coercion_site(cg->analysis, e);
    union_site = feng_semantic_lookup_union_coercion_site(cg->analysis, e);
    if (union_site != NULL) {
        return cg_emit_union_spec_coercion(cg, e, union_site, out);
    }
    return cg_emit_expr_with_spec_coercion(cg, e, spec_site, out);
}

/* ===================== statement emission ===================== */

static void cg_release_scope(CG *cg, const Scope *scope) {
    /* Walk in reverse insertion order to mirror C destruction. Each managed
     * non-param local was paired with a feng_cleanup_push at declaration; we
     * must pop the chain in strict LIFO order, then release+NULL the slot so
     * any later throw-driven walk skips it. */
    for (size_t i = scope->count; i > 0; i--) {
        const Local *l = &scope->items[i - 1];
        if (l->is_param) continue;
        if (cgtype_is_defer(l->type)) {
            /* docs/engineering/feng-defer-dev.md §5.6.3: defer nodes mix with managed
             * locals in LIFO order on the cleanup chain. Pop the chain node
             * pushed at registration time, then invoke the generated defer
             * function with its closure (NULL when the defer body captures
             * nothing — see §5.5). The `name` field stores the defer function
             * name and `c_name` stores the closure variable name. */
            cg_emit_current_stmt_line_directive_force(cg);
            if (l->c_name != NULL && l->c_name[0] != '\0') {
                buf_append_fmt(cg->cur_body,
                               "    feng_cleanup_pop(); %s(&%s);\n",
                               l->name, l->c_name);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    feng_cleanup_pop(); %s(NULL);\n",
                               l->name);
            }
            continue;
        }
        if (l->uses_erased_generic_storage) {
            cg_emit_current_stmt_line_directive_force(cg);
            if (l->erased_generic_cleanup_aggregate_only) {
                buf_append_fmt(cg->cur_body,
                    "    if (%s->kind == "
                    "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS) {\n"
                    "        feng_cleanup_pop();\n"
                    "        feng_aggregate_release(%s, "
                    "feng_generic_aggregate_descriptor(%s));\n"
                    "        memset(%s, 0, %s);\n"
                    "    }\n",
                    l->erased_generic_descriptor_c_name,
                    l->c_name,
                    l->erased_generic_descriptor_c_name,
                    l->c_name,
                    l->erased_generic_size_c_name);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    switch (%s->kind) {\n"
                    "        case FENG_VALUE_TRIVIAL:\n"
                    "            break;\n"
                    "        case FENG_VALUE_MANAGED_POINTER:\n"
                    "            feng_cleanup_pop();\n"
                    "            feng_release(*(void **)%s);\n"
                    "            *(void **)%s = NULL;\n"
                    "            break;\n"
                    "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                    "            feng_cleanup_pop();\n"
                    "            feng_aggregate_release(%s, "
                    "feng_generic_aggregate_descriptor(%s));\n"
                    "            memset(%s, 0, %s);\n"
                    "            break;\n"
                    "    }\n",
                    l->erased_generic_descriptor_c_name,
                    l->c_name,
                    l->c_name,
                    l->c_name,
                    l->erased_generic_descriptor_c_name,
                    l->c_name,
                    l->erased_generic_size_c_name);
            }
        } else if (cgtype_is_managed(l->type)) {
            cg_emit_current_stmt_line_directive_force(cg);
            buf_append_fmt(cg->cur_body,
                           "    feng_cleanup_pop(); feng_release(%s); %s = NULL;\n",
                           l->c_name, l->c_name);
        } else if (cgtype_is_aggregate(l->type)) {
            if (l->uses_reified_storage) {
                cg_emit_current_stmt_line_directive_force(cg);
                buf_append_fmt(cg->cur_body,
                    "    feng_cleanup_pop(); "
                    "feng_aggregate_release(%s, %s); "
                    "memset(%s, 0, %s);\n",
                    l->c_name,
                    l->reified_descriptor_c_name,
                    l->c_name,
                    l->reified_size_c_name);
            } else if (cg_value_needs_reified_layout(cg, l->type)) {
                /* Reified tuple: single cleanup node (pushed by RAD path in
                 * cg_emit_cleanup_push_for_aggregate_local), pop 1, release
                 * via RAD, zero entire struct. */
                const char *agg_desc = cg_aggregate_desc_name(l->type);
                size_t rad_idx;
                if (agg_desc &&
                    cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                    const char *src = cg->generic_type_method_rad_via_desc
                                          ? "_desc" : "_td";
                    cg_emit_current_stmt_line_directive_force(cg);
                    buf_append_fmt(cg->cur_body,
                        "    feng_cleanup_pop(); "
                        "feng_aggregate_release(&%s, "
                        "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]); "
                        "memset(&%s, 0, sizeof %s);\n",
                        l->c_name, src, rad_idx, l->c_name, l->c_name);
                }
            } else {
                /* Pop every cleanup node registered for the aggregate's managed
                 * slots before releasing through the descriptor. If release
                 * panics, the throwing cleanup walk must not re-enter the same
                 * slots. */
                const char *desc = cg_aggregate_desc_name(l->type);
                if (!desc) {
                    cg_emit_current_stmt_line_directive_force(cg);
                    buf_append_fmt(cg->cur_body,
                        "    feng_panic(\"codegen: missing aggregate descriptor for %s\");\n",
                        l->c_name);
                    continue;
                }
                cg_emit_current_stmt_line_directive_force(cg);
                buf_append_cstr(cg->cur_body, "    ");
                cg_emit_cleanup_pops_for_aggregate_local(cg->cur_body, l->type);
                buf_append_fmt(cg->cur_body,
                    "feng_aggregate_release(&%s, &%s); ",
                    l->c_name, desc);
                cg_emit_cleanup_zero_for_aggregate_local(cg->cur_body, l->c_name, l->type);
                buf_append_cstr(cg->cur_body, "\n");
            }
        }
    }
}

/* Release all scopes from cg->cur_scope down to (but not including) `stop`.
 * Used by return / break / continue. */
static void cg_release_through(CG *cg, const Scope *stop) {
    for (const Scope *s = cg->cur_scope; s && s != stop; s = s->parent) {
        cg_release_scope(cg, s);
    }
}

static void cg_emit_control_cleanup_to_try_depth(CG *cg, int keep_exception_frame_count) {
    int pop_count;

    if (cg->active_caught_unwind_count > 0) {
        buf_append_cstr(cg->cur_body, "    feng_release_unwind_exception();\n");
    }
    pop_count = cg->active_exception_frame_count - keep_exception_frame_count;
    if (pop_count < 0) {
        pop_count = 0;
    }
    for (int i = 0; i < pop_count; ++i) {
        buf_append_cstr(cg->cur_body, "    feng_frame_pop();\n");
    }
}

static void cg_emit_return_control_cleanup(CG *cg) {
    cg_emit_control_cleanup_to_try_depth(cg, 0);
    if (cg->cur_function_has_frame_marker) {
        buf_append_cstr(cg->cur_body, "    feng_frame_pop();\n");
    }
}

/* Register a managed local on the per-thread cleanup chain so a throw passing
 * through the current scope releases it. The companion feng_cleanup_pop is
 * emitted by cg_release_scope. The companion node lives on the C stack right
 * next to the local so its lifetime matches. */
static void cg_emit_cleanup_push_for_managed_local(CG *cg, const char *cname) {
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    FengCleanupNode _cu_%s; feng_cleanup_push(&_cu_%s, (void **)&%s);\n",
                   cname, cname, cname);
}

static bool cg_register_local_for_cleanup(CG *cg,
                                const char *cname,
                                const CGType *type,
                                FengToken token) {
    CGType *owned_type = cgtype_clone(type);

    if (owned_type == NULL) {
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    if (!scope_add(cg->cur_scope, cname, cname, owned_type, false)) {
        cgtype_free(owned_type);
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    if (cgtype_is_managed(type)) {
        cg_emit_cleanup_push_for_managed_local(cg, cname);
    } else if (cgtype_is_aggregate(type)) {
        cg_emit_cleanup_push_for_aggregate_local(cg, cname, type);
    }
    return true;
}

/* Register one owning direct-generic value.  Shared code cannot classify T
 * statically, so the descriptor selects the existing pointer or aggregate
 * cleanup node; trivial values register no node. */
static bool cg_register_erased_generic_storage_for_cleanup(
    CG *cg,
    const char *cname,
    const CGType *type,
    const char *descriptor_c_name,
    const char *size_c_name,
    FengToken token) {
    CGType *owned_type;

    if (cg == NULL || cname == NULL || type == NULL ||
        type->kind != CG_TYPE_GENERIC_PARAM || descriptor_c_name == NULL ||
        size_c_name == NULL) {
        return false;
    }
    owned_type = cgtype_clone(type);
    if (owned_type == NULL ||
        !scope_add(cg->cur_scope, cname, cname, owned_type, false)) {
        cgtype_free(owned_type);
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    if (!scope_mark_last_erased_generic_storage(cg->cur_scope,
                                                descriptor_c_name,
                                                size_c_name)) {
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    cg_emit_cleanup_push_for_erased_generic_storage(
        cg, cname, descriptor_c_name);
    return true;
}

/* Register a generic by-value argument copy. Managed-pointer values remain
 * borrowed for the duration of the call, while aggregate copies own their
 * retained slots and therefore participate in exception-safe cleanup. */
static bool cg_register_erased_generic_argument_storage_for_cleanup(
    CG *cg,
    const char *cname,
    const CGType *type,
    const char *descriptor_c_name,
    const char *size_c_name,
    FengToken token) {
    CGType *owned_type;

    if (cg == NULL || cname == NULL || type == NULL ||
        type->kind != CG_TYPE_GENERIC_PARAM || descriptor_c_name == NULL ||
        size_c_name == NULL) {
        return false;
    }
    owned_type = cgtype_clone(type);
    if (owned_type == NULL ||
        !scope_add(cg->cur_scope, cname, cname, owned_type, false)) {
        cgtype_free(owned_type);
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    if (!scope_mark_last_erased_generic_argument_storage(
            cg->cur_scope, descriptor_c_name, size_c_name)) {
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    cg_emit_cleanup_push_for_erased_generic_argument_storage(
        cg, cname, descriptor_c_name);
    return true;
}

/* Register every managed pointer slot of an aggregate local on the cleanup
 * chain. The exact slot addresses are owned by the aggregate facts provider. */
static void cg_emit_cleanup_push_for_aggregate_local(CG *cg,
                                                     const char *cname,
                                                     const CGType *type) {
    /* Reified tuple: use RAD to push a single aggregate cleanup node that
     * covers the entire struct, rather than per-field nodes (which would skip
     * CG_TYPE_GENERIC_PARAM fields classified as CG_VK_TRIVIAL). */
    if (cg_value_needs_reified_layout(cg, type)) {
        const char *agg_desc = cg_aggregate_desc_name(type);
        size_t rad_idx;
        if (agg_desc &&
            cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
            const char *src = cg->generic_type_method_rad_via_desc
                                  ? "_desc" : "_td";
            cg_emit_current_stmt_line_directive_force(cg);
            buf_append_fmt(cg->cur_body,
                "    FengCleanupNode _cu_%s; "
                "feng_cleanup_push_aggregate(&_cu_%s, &%s, "
                "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]);\n",
                cname, cname, cname, src, rad_idx);
        }
        return;
    }
    CGAggregateFacts facts;
    if (cg_aggregate_facts(type, &facts) && facts.emit_cleanup_push != NULL) {
        cg_emit_current_stmt_line_directive_force(cg);
        facts.emit_cleanup_push(cg->cur_body, cname, type);
    }
}

/* Register one descriptor-sized address local as a single aggregate cleanup
 * node. Both arguments are cached C local names, so this adds no descriptor
 * table lookup to the generated cleanup path. */
static void cg_emit_cleanup_push_for_reified_aggregate_storage(
    CG *cg,
    const char *cname,
    const char *descriptor_c_name) {
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    FengCleanupNode _cu_%s; "
                   "feng_cleanup_push_aggregate(&_cu_%s, %s, %s);\n",
                   cname,
                   cname,
                   cname,
                   descriptor_c_name);
}

/* Pair one erased generic storage slot with the existing cleanup-chain node
 * matching its closed value kind.  No runtime descriptor lookup or heap
 * allocation is introduced. */
static void cg_emit_cleanup_push_for_erased_generic_storage(
    CG *cg,
    const char *cname,
    const char *descriptor_c_name) {
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
        "    FengCleanupNode _cu_%s;\n"
        "    switch (%s->kind) {\n"
        "        case FENG_VALUE_TRIVIAL:\n"
        "            break;\n"
        "        case FENG_VALUE_MANAGED_POINTER:\n"
        "            feng_cleanup_push(&_cu_%s, (void **)%s);\n"
        "            break;\n"
        "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
        "            feng_cleanup_push_aggregate(&_cu_%s, %s, "
        "feng_generic_aggregate_descriptor(%s));\n"
        "            break;\n"
        "    }\n",
        cname,
        descriptor_c_name,
        cname,
        cname,
        cname,
        cname,
        descriptor_c_name);
}

/* Push cleanup only for the aggregate branch of a generic argument copy.
 * The managed-pointer branch is a borrowed reference value, matching normal
 * reference-typed parameter lowering. */
static void cg_emit_cleanup_push_for_erased_generic_argument_storage(
    CG *cg,
    const char *cname,
    const char *descriptor_c_name) {
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
        "    FengCleanupNode _cu_%s;\n"
        "    if (%s->kind == "
        "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS) {\n"
        "        feng_cleanup_push_aggregate(&_cu_%s, %s, "
        "feng_generic_aggregate_descriptor(%s));\n"
        "    }\n",
        cname,
        descriptor_c_name,
        cname,
        cname,
        descriptor_c_name);
}

/* Emit one feng_cleanup_pop per cleanup node previously registered for the
 * aggregate local. */
static void cg_emit_cleanup_pops_for_aggregate_local(Buf *out, const CGType *type) {
    CGAggregateFacts facts;
    size_t count = cg_aggregate_facts(type, &facts) ? facts.pointer_slot_count : 0U;
    for (size_t i = 0; i < count; ++i) {
        buf_append_cstr(out, "feng_cleanup_pop(); ");
    }
}

/* Emit post-release zeroing for aggregate cleanup slots. */
static void cg_emit_cleanup_zero_for_aggregate_local(Buf *out,
                                                     const char *cname,
                                                     const CGType *type) {
    CGAggregateFacts facts;
    if (cg_aggregate_facts(type, &facts) && facts.emit_cleanup_zero != NULL) {
        facts.emit_cleanup_zero(out, cname, type);
    }
}

/* ---------- default-zero emission ----------
 *
 * Feng has no `null`. Every binding without an explicit initializer (and
 * every object-literal field omitted by the user) takes the type's default
 * zero value, see docs/specifications/feng-builtin-type.md and docs/specifications/feng-type.md §5/§7.
 *
 * The string default is the process-wide IMMORTAL singleton produced by
 * feng_string_default(); the array default is a freshly allocated empty
 * FengArray with the right element descriptor; the object default is a
 * recursive zero instance produced by the per-type Feng__M__T__default_zero()
 * factory emitted alongside the type. Cyclic object types (self- or
 * mutually-referential) cannot have a finite default zero and must be
 * rejected at compile time. */

/* Recursive predicate: T is default-zero-safe iff T itself is acyclic AND
 * every managed object field of T is itself default-zero-safe. The recursion
 * terminates on the acyclic-types DAG. `visited` tracks the current DFS path
 * to keep the algorithm robust even if the cyclicity marker is somehow
 * inconsistent (defensive — feng_semantic_type_is_potentially_cyclic should
 * already catch true cycles). */
static bool cg_user_type_dz_safe_dfs(CG *cg, const UserType *t,
                                     const UserType **stack, size_t depth,
                                     size_t cap) {
    if (feng_semantic_type_is_potentially_cyclic(cg->analysis, t->decl)) return false;
    for (size_t i = 0; i < depth; i++) if (stack[i] == t) return false;
    if (depth + 1 > cap) return false;  /* defensive */
    stack[depth] = t;
    for (size_t i = 0; i < t->field_count; i++) {
        const CGType *ft = t->fields[i].type;
        if (ft->kind != CG_TYPE_OBJECT || !ft->user) continue;
        if (!cg_user_type_dz_safe_dfs(cg, ft->user, stack, depth + 1, cap)) {
            return false;
        }
    }
    return true;
}

static bool cg_user_type_is_default_zero_safe(CG *cg, const UserType *t) {
    /* Cap at user_type_count: any deeper path must contain a repeat, which
     * the cycle marker would already have flagged. */
    size_t cap = cg->user_type_count + 1;
    const UserType **stack = calloc(cap, sizeof *stack);
    if (!stack) return false;
    bool ok = cg_user_type_dz_safe_dfs(cg, t, stack, 0, cap);
    free(stack);
    return ok;
}

/* Emit a C expression that produces the default-zero value of `type` and
 * write it to *out_expr (caller-frees). For managed types the expression
 * always carries a freshly-owned reference (+1 owns_ref semantics), with the
 * exception of the IMMORTAL string singleton — it is also safe to treat as
 * "owns_ref" because feng_release/feng_retain are no-ops on IMMORTAL refs.
 *
 * Returns false (and reports through cg_fail) when `type` is not eligible
 * for default-zero (cyclic object type, or a type containing one). */
static bool cg_default_value_expr(CG *cg, const CGType *type,
                                  const FengToken *blame,
                                  char **out_expr) {
    Buf b; buf_init(&b);
    switch (type->kind) {
        case CG_TYPE_BOOL:
            buf_append_cstr(&b, "false"); break;
        case CG_TYPE_I8: case CG_TYPE_I16: case CG_TYPE_I32: case CG_TYPE_I64:
        case CG_TYPE_U8: case CG_TYPE_U16: case CG_TYPE_U32: case CG_TYPE_U64:
            if (type->enum_decl != NULL) {
                char *item_c_name;

                if (!cg_ensure_enum_emitted(cg, type->enum_decl)) {
                    buf_free(&b);
                    return false;
                }
                if (type->enum_decl->as.enum_decl.item_count == 0U) {
                    buf_free(&b);
                    return cg_fail(cg,
                                   blame ? *blame : (FengToken){0},
                                   "CE0221", "codegen: enum has no items for default value");
                }
                item_c_name = cg_enum_item_c_name(cg, type->enum_decl,
                                                   type->enum_decl->as.enum_decl.items[0].name);
                if (item_c_name == NULL) {
                    buf_free(&b);
                    return cg_fail(cg,
                                   blame ? *blame : (FengToken){0},
                                   "CE0222", "codegen: out of memory emitting enum default value");
                }
                buf_append_cstr(&b, item_c_name);
                free(item_c_name);
            } else {
                buf_append_cstr(&b, "0");
            }
            break;
        case CG_TYPE_F32: case CG_TYPE_F64:
            buf_append_cstr(&b, "0.0"); break;
        case CG_TYPE_POINTER:
            buf_append_cstr(&b, "NULL"); break;
        case CG_TYPE_CALLABLE:
            if (type->user_spec != NULL &&
                type->user_spec->c_default_callable_new_name != NULL &&
                type->user_spec->c_closure_struct_name != NULL) {
                if (type->user_spec->generic_context_type_param_count > 0U) {
                    char *descriptor_expr =
                        cg_rtd_expr_for_managed_descriptor(
                            cg,
                            type->user_spec->c_closure_desc_name,
                            blame ? *blame : (FengToken){0});

                    if (descriptor_expr == NULL) {
                        buf_free(&b);
                        return false;
                    }
                    buf_append_fmt(&b, "(struct %s *)%s(%s)",
                                   type->user_spec->c_closure_struct_name,
                                   type->user_spec->c_default_callable_new_name,
                                   descriptor_expr);
                    free(descriptor_expr);
                } else {
                    buf_append_fmt(&b, "(struct %s *)%s()",
                                   type->user_spec->c_closure_struct_name,
                                   type->user_spec->c_default_callable_new_name);
                }
            } else {
                buf_free(&b);
                return cg_fail(cg, blame ? *blame : (FengToken){0},
                    "CE0223", "codegen: cannot produce default value for unresolved callable type");
            }
            break;
        case CG_TYPE_GENERIC_PARAM:
            buf_append_cstr(&b, "NULL"); break;
        case CG_TYPE_STRING:
            buf_append_cstr(&b, "feng_string_default()"); break;
        case CG_TYPE_ARRAY: {
            char *desc = cg_array_element_descriptor(type->element);
            /* Use full C type (including pointer star for managed elements)
             * so sizeof matches the per-slot storage actually allocated by
             * feng_array_new — see cg_emit_array_literal_typed for the
             * canonical pattern. */
            char *elem_cty = cg_ctype_dup(type->element);
            bool em = type->element ? cgtype_is_managed(type->element) : false;
            bool ea = type->element ? cgtype_is_aggregate(type->element) : false;
            if (type->element != NULL &&
                type->element->kind == CG_TYPE_GENERIC_PARAM) {
                const char *generic_desc = cg_generic_param_desc_name(
                    cg, type->element->generic_param_index);

                if (generic_desc == NULL) {
                    free(desc); free(elem_cty); buf_free(&b);
                    return cg_fail(
                        cg,
                        blame ? *blame : (FengToken){0},
                        "CE0184", "codegen: generic array default value requires an active generic descriptor");
                }
                buf_append_fmt(&b,
                    "feng_array_new_kinded("
                    "%s->kind, (%s->kind == FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS ? feng_generic_aggregate_descriptor(%s) : NULL), "
                    "NULL, feng_generic_value_size(%s), (size_t)0)",
                    generic_desc, generic_desc, generic_desc, generic_desc);
            } else if (ea) {
                /* Step 4b-γ §9.6 — aggregate-element arrays must encode the
                 * AGGREGATE element kind even at length 0 so the cycle
                 * collector tags the array correctly when later resized. */
                const char *agg_desc = cg_aggregate_desc_name(type->element);
                size_t rad_idx;

                if (agg_desc == NULL) {
                    free(desc); free(elem_cty); buf_free(&b);
                    return cg_fail(cg, blame ? *blame : (FengToken){0},
                        "CE0224", "codegen: missing aggregate descriptor for spec array default-zero");
                }
                if (cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                    const char *rad_src =
                        cg->generic_type_method_rad_via_desc ? "_desc" : "_td";

                    buf_append_fmt(&b,
                        "feng_array_new_kinded("
                        "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, %s->reified_agg_deps[%zu], "
                        "NULL, %s->reified_agg_deps[%zu]->size, (size_t)0)",
                        rad_src, rad_idx, rad_src, rad_idx);
                } else {
                    buf_append_fmt(&b,
                        "feng_array_new_kinded("
                        "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, &%s, NULL, sizeof(%s), (size_t)0)",
                        agg_desc, elem_cty ? elem_cty : "void *");
                }
            } else {
                buf_append_fmt(&b, "feng_array_new(%s, sizeof(%s), %s, (size_t)0)",
                               desc ? desc : "NULL",
                               elem_cty ? elem_cty : "void *",
                               em ? "true" : "false");
            }
            free(desc);
            free(elem_cty);
            break;
        }
        case CG_TYPE_OBJECT: {
            if (!type->user || type->user->c_struct_name == NULL) {
                buf_free(&b);
                return cg_fail(cg, blame ? *blame : (FengToken){0},
                    "CE0225", "codegen: cannot default-zero an unresolved object type");
            }
            if (cg_user_type_is_value_semantics(type->user)) {
                buf_append_fmt(&b, "(struct %s){0}", type->user->c_struct_name);
                break;
            }
            if (!cg_user_type_is_default_zero_safe(cg, type->user)) {
                buf_free(&b);
                return cg_fail(cg, blame ? *blame : (FengToken){0},
                    "CE0226", "codegen: type '%s' contains reference cycles and has no default zero value; provide an explicit initializer",
                    type->user->feng_name != NULL ? type->user->feng_name : "<unknown>");
            }
            if (cg_reference_needs_reified_field_layout(cg, type)) {
                char *descriptor = cg_rtd_expr_for_type(
                    cg,
                    type->user,
                    blame ? *blame : (FengToken){0});
                char *factory = cg_generic_default_zero_shared_cname(
                    cg, type->user->generic_origin_decl);

                if (descriptor == NULL || factory == NULL) {
                    free(descriptor);
                    free(factory);
                    buf_free(&b);
                    if (!cg->failed) {
                        return cg_fail(cg,
                                       blame ? *blame : (FengToken){0},
                                       "IE0001", "codegen: out of memory");
                    }
                    return false;
                }
                if (cg_program_origin(cg, type->user->owner_program) ==
                    FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                    buf_append_fmt(&cg->fn_protos,
                                   "void *%s(const FengTypeDescriptor *_type_desc);\n",
                                   factory);
                }
                buf_append_fmt(&b,
                               "(struct %s *)%s(%s)",
                               type->user->c_struct_name,
                               factory,
                               descriptor);
                free(descriptor);
                free(factory);
                break;
            }
            if (type->user->c_default_zero_name == NULL) {
                buf_free(&b);
                return cg_fail(cg, blame ? *blame : (FengToken){0},
                    "CE0225", "codegen: cannot default-zero an unresolved object type");
            }
            buf_append_fmt(&b, "%s()", type->user->c_default_zero_name);
            break;
        }
        default:
            buf_free(&b);
            return cg_fail(cg, blame ? *blame : (FengToken){0},
                "CE0227", "codegen: cannot produce default value for this type");
    }
    *out_expr = b.data ? b.data : strdup("0");
    return *out_expr != NULL;
}

static bool cg_emit_expr_for_expected_type(CG *cg,
                                           const FengExpr *expr,
                                           const CGType *expected_type,
                                           ExprResult *out) {
    if (expected_type != NULL && expected_type->kind == CG_TYPE_ARRAY &&
        expected_type->element != NULL && expr != NULL &&
        expr->kind == FENG_EXPR_ARRAY_LITERAL) {
        return cg_emit_array_literal_typed(cg, expr, expected_type->element, out);
    }
    if (expected_type != NULL && cg_type_is_tuple_user(expected_type) &&
        expr != NULL && expr->kind == FENG_EXPR_TUPLE_LITERAL) {
        return cg_emit_tuple_literal_typed(cg, expr, expected_type, out);
    }
    return cg_emit_expr(cg, expr, out);
}

static bool cg_emit_initializer_for_declared_type(CG *cg,
                                                  const FengExpr *initializer,
                                                  const CGType *decl_type,
                                                  ExprResult *out) {
    return cg_emit_expr_for_expected_type(cg, initializer, decl_type, out);
}

static bool cg_emit_initialized_local_binding(CG *cg,
                                              FengSlice name,
                                              const CGType *decl_type,
                                              ExprResult *init,
                                              FengToken token,
                                              FengMutability mutability) {
    if (name.data == NULL || name.length == 0U || decl_type == NULL || init == NULL) {
        return false;
    }
    if (cg_current_callable_captures_name(cg, name.data, name.length)) {
        bool bound = cg_scope_bind_capture_cell(
            cg,
            cg->cur_scope,
            name,
            decl_type,
            token,
            init->c_expr,
            true,
            init->owns_ref,
            true,
            FENG_CODEGEN_MAPING_VARIABLE_BINDING);

        return bound &&
               scope_mark_last_binding_mutability(cg->cur_scope,
                                                  mutability);
    }

    char *cname = cg_local_cname(cg, name.data, name.length);
    char *cty = cg_ctype_dup(decl_type);
    if (cname == NULL || cty == NULL) {
        free(cname);
        free(cty);
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }

    if (!cg_emit_line_directive_force(cg, token)) {
        free(cname);
        free(cty);
        return false;
    }
    if (cgtype_is_managed(decl_type)) {
        if (init->owns_ref) {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, cname, init->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    %s %s = %s; feng_retain(%s);\n",
                           cty,
                           cname,
                           init->c_expr,
                           cname);
        }
    } else if (cgtype_is_aggregate(decl_type)) {
        if (init->owns_ref) {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, cname, init->c_expr);
        } else {
            const char *desc = cg_aggregate_desc_name(decl_type);
            if (desc == NULL) {
                free(cname);
                free(cty);
                return cg_fail(cg, token, "CE0228", "codegen: missing aggregate descriptor for local binding");
            }
            buf_append_fmt(cg->cur_body,
                           "    %s %s = %s; feng_aggregate_retain(&%s, &%s);\n",
                           cty,
                           cname,
                           init->c_expr,
                           cname,
                           desc);
        }
    } else {
        if (cgtype_is_by_value_struct(decl_type)) {
            buf_append_fmt(cg->cur_body,
                           "    %s %s = %s;\n",
                           cty,
                           cname,
                           init->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    %s %s = (%s)(%s);\n",
                           cty,
                           cname,
                           cty,
                           init->c_expr);
        }
    }
    free(cty);

    CGType *local_type = cgtype_clone(decl_type);
    if (local_type == NULL ||
        !scope_add(cg->cur_scope, "_unused_internal_name__", cname, local_type, false) ||
        !scope_mark_last_binding_mutability(cg->cur_scope, mutability)) {
        cgtype_free(local_type);
        free(cname);
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    Local *added = &cg->cur_scope->items[cg->cur_scope->count - 1];
    free(added->name);
    added->name = strndup(name.data, name.length);
    if (added->name == NULL) {
        free(cname);
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    if (!cg_debug_add_variable_record_slice_cgtype(cg,
                                                   cname,
                                                   name,
                                                   NULL,
                                                   decl_type,
                                                   FENG_CODEGEN_MAPING_VARIABLE_BINDING,
                                                   token)) {
        free(cname);
        return false;
    }
    if (cgtype_is_managed(decl_type)) {
        cg_emit_cleanup_push_for_managed_local(cg, cname);
    } else if (cgtype_is_aggregate(decl_type)) {
        cg_emit_cleanup_push_for_aggregate_local(cg, cname, decl_type);
    }
    free(cname);
    return true;
}

static bool cg_emit_destructure_binding(CG *cg, const FengStmt *stmt) {
    const FengBinding *binding = &stmt->as.binding;

    if (binding->initializer == NULL) {
        return cg_fail(cg, binding->token,
                       "CE0229", "codegen: destructuring binding requires an initializer");
    }
    if (binding->initializer->kind == FENG_EXPR_TUPLE_LITERAL) {
        const FengExpr *tuple = binding->initializer;
        if (tuple->as.tuple_literal.count != binding->destructure_count) {
            return cg_fail(cg, binding->token,
                           "CE0230", "codegen: destructuring arity mismatch");
        }
        for (size_t i = 0; i < binding->destructure_count; ++i) {
            FengSlice name = binding->destructure_names[i];
            if (name.length == 0U) {
                continue;
            }
            ExprResult item;
            if (!cg_emit_expr(cg, tuple->as.tuple_literal.items[i], &item)) {
                return false;
            }
            if (!cg_emit_initialized_local_binding(cg,
                                                   name,
                                                   item.type,
                                                   &item,
                                                   binding->token,
                                                   binding->mutability)) {
                er_free(&item);
                return false;
            }
            er_free(&item);
        }
        return true;
    }

    ExprResult source;
    if (!cg_emit_expr(cg, binding->initializer, &source)) {
        return false;
    }
    if (!cg_type_is_tuple_user(source.type)) {
        er_free(&source);
        return cg_fail(cg, binding->token,
                       "CE0231", "codegen: destructuring source must be a tuple value");
    }
    if (source.type->user->field_count != binding->destructure_count) {
        er_free(&source);
        return cg_fail(cg, binding->token,
                       "CE0230", "codegen: destructuring arity mismatch");
    }
    if (binding->destructure_count == 0U) {
        cg_emit_current_stmt_line_directive_force(cg);
        buf_append_fmt(cg->cur_body, "    (void)(%s);\n", source.c_expr);
        er_free(&source);
        return true;
    }
    if (cg_materialize_to_local(cg, &source, "_tuple") == NULL) {
        er_free(&source);
        return cg_fail(cg, binding->token, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0; i < binding->destructure_count; ++i) {
        FengSlice name = binding->destructure_names[i];
        if (name.length == 0U) {
            continue;
        }
        const UserField *field = &source.type->user->fields[i];
        ExprResult field_value;
        Buf field_expr;

        er_init(&field_value);
        buf_init(&field_expr);
        buf_append_fmt(&field_expr, "%s.%s", source.c_expr, field->c_name);
        field_value.c_expr = field_expr.data;
        field_value.type = cgtype_clone(field->type);
        field_value.owns_ref = false;
        if (field_value.c_expr == NULL || field_value.type == NULL) {
            er_free(&field_value);
            er_free(&source);
            return cg_fail(cg, binding->token, "IE0001", "codegen: out of memory");
        }
        if (!cg_emit_initialized_local_binding(cg,
                                               name,
                                               field->type,
                                               &field_value,
                                               binding->token,
                                               binding->mutability)) {
            er_free(&field_value);
            er_free(&source);
            return false;
        }
        er_free(&field_value);
    }
    er_free(&source);
    return true;
}

/* Return one field's descriptor-provided offset index while emitting an open
 * generic shared body; ordinary concrete layouts do not use this path. */
static bool cg_user_field_reified_index(const CG *cg,
                                        const UserField *field,
                                        size_t *out_index) {
    size_t field_index = 0U;

    if (cg == NULL || field == NULL || field->member == NULL ||
        cg->generic_type_method_field_offsets_name == NULL ||
        cg->generic_type_method_decl == NULL ||
        cg->generic_type_method_decl->kind != FENG_DECL_TYPE) {
        return false;
    }
    for (size_t i = 0U;
         i < cg->generic_type_method_decl->as.type_decl.member_count;
         ++i) {
        const FengTypeMember *member =
            cg->generic_type_method_decl->as.type_decl.members[i];

        if (member == NULL || member->kind != FENG_TYPE_MEMBER_FIELD ||
            member->is_static) {
            continue;
        }
        if (member == field->member) {
            if (out_index != NULL) {
                *out_index = field_index;
            }
            return true;
        }
        field_index++;
    }
    return false;
}

/* Store a field value with an optional explicit dynamic-layout authority.
 * Reified values constructed outside their own owner method supply their
 * aggregate descriptor's offset table; owner shared bodies keep using the
 * active type descriptor selected by the existing context. */
static bool cg_emit_user_field_value_store_with_offsets(
    CG *cg,
    const char *object_expr,
    const UserField *uf,
    const char *reified_field_offsets_expr,
    size_t explicit_reified_index,
    ExprResult *value,
    FengToken blame,
    bool replace_existing) {
    size_t reified_index = explicit_reified_index;
    bool uses_reified_offset;
    const char *field_offsets_expr = reified_field_offsets_expr;
    Buf field_expr;

    if (cg == NULL || object_expr == NULL || uf == NULL || value == NULL) {
        return false;
    }
    uses_reified_offset = field_offsets_expr != NULL;
    if (!uses_reified_offset) {
        uses_reified_offset = cg_user_field_reified_index(
            cg, uf, &reified_index);
        if (uses_reified_offset) {
            field_offsets_expr =
                cg->generic_type_method_field_offsets_name;
        }
    }
    if (uses_reified_offset && uf->type != NULL &&
        uf->type->kind == CG_TYPE_GENERIC_PARAM) {
        const char *descriptor = cg_generic_param_desc_name(
            cg, uf->type->generic_param_index);
        char *destination = cg_fresh_temp(cg, "_ginit_dst");
        char *source = cg_fresh_temp(cg, "_ginit_src");

        if (descriptor == NULL || destination == NULL || source == NULL) {
            free(destination);
            free(source);
            return cg_fail(cg,
                           blame,
                           descriptor == NULL ? "CE0237" : "IE0001",
                           descriptor == NULL
                               ? "codegen: missing generic descriptor for field initialization"
                               : "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
            "    void *%s = ((char *)%s + %s[%zu]);\n"
            "    const void *%s = %s;\n"
            "    switch (%s->kind) {\n"
            "        case FENG_VALUE_TRIVIAL:\n"
            "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
            "            break;\n"
            "        case FENG_VALUE_MANAGED_POINTER: {\n"
            "            void *_new_value = *(void *const *)%s;\n",
            destination, object_expr,
            field_offsets_expr, reified_index,
            source, value->c_expr,
            descriptor,
            destination, source, descriptor,
            source);
        if (!value->owns_ref) {
            buf_append_cstr(cg->cur_body,
                "            feng_retain(_new_value);\n");
        }
        if (replace_existing) {
            buf_append_fmt(cg->cur_body,
                "            void *_old_value = *(void **)%s;\n"
                "            *(void **)%s = _new_value;\n"
                "            feng_release(_old_value);\n",
                destination, destination);
        } else {
            buf_append_fmt(cg->cur_body,
                "            *(void **)%s = _new_value;\n",
                destination);
        }
        buf_append_fmt(cg->cur_body,
            "            break;\n"
            "        }\n"
            "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
            "            feng_aggregate_assign(%s, %s, "
            "feng_generic_aggregate_descriptor(%s));\n"
            "            break;\n"
            "    }\n",
            destination, source, descriptor);
        free(destination);
        free(source);
        return true;
    }

    buf_init(&field_expr);
    if (uses_reified_offset) {
        char *ctype = cg_ctype_dup(uf->type);

        if (ctype == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(&field_expr,
                       "(*(%s *)((char *)%s + %s[%zu]))",
                       ctype,
                       object_expr,
                       field_offsets_expr,
                       reified_index);
        free(ctype);
    } else {
        buf_append_fmt(&field_expr,
                       "%s->%s",
                       object_expr,
                       uf->c_name);
    }
    if (field_expr.data == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    if (cgtype_is_managed(uf->type)) {
        if (replace_existing) {
            if (value->owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { void *_old = %s; %s = %s; feng_release(_old); }\n",
                    field_expr.data, field_expr.data, value->c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_assign((void **)&%s, %s);\n",
                    field_expr.data, value->c_expr);
            }
        } else if (value->owns_ref) {
            buf_append_fmt(cg->cur_body,
                "    %s = %s;\n",
                field_expr.data, value->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "    %s = %s; feng_retain(%s);\n",
                field_expr.data, value->c_expr, field_expr.data);
        }
        buf_free(&field_expr);
        return true;
    }

    if (cgtype_is_aggregate(uf->type)) {
        const char *agg_desc = cg_aggregate_desc_name(uf->type);
        size_t rad_index;
        char *source_address;
        bool take_source;

        if (agg_desc == NULL) {
            buf_free(&field_expr);
            return cg_fail(cg,
                           blame,
                           "CE0232", "codegen: missing aggregate descriptor for field '%s'",
                           uf->feng_name);
        }
        if (!cg_prepare_aggregate_store_source(
                cg, value, "_t", &take_source)) {
            buf_free(&field_expr);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        source_address = cg_aggregate_result_address_dup(value);
        if (source_address == NULL) {
            buf_free(&field_expr);
            return cg_fail(cg, blame,
                           "CE0232", "codegen: aggregate field source has no address");
        }
        if (uses_reified_offset &&
            cg_value_needs_reified_layout(cg, uf->type) &&
            cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_index)) {
            const char *rad_source = cg->generic_type_method_rad_via_desc
                                         ? "_desc"
                                         : "_td";

            buf_append_fmt(cg->cur_body,
                "    %s(&%s, %s, "
                "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]);\n",
                take_source ? "feng_aggregate_take" : "feng_aggregate_assign",
                field_expr.data, source_address, rad_source, rad_index);
        } else {
            buf_append_fmt(cg->cur_body,
                "    %s(&%s, %s, &%s);\n",
                take_source ? "feng_aggregate_take" : "feng_aggregate_assign",
                field_expr.data, source_address, agg_desc);
        }
        free(source_address);
        buf_free(&field_expr);
        return true;
    }

    {
        char *cty = cg_ctype_dup(uf->type);

        if (cty == NULL) {
            buf_free(&field_expr);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (cgtype_is_by_value_struct(uf->type)) {
            buf_append_fmt(cg->cur_body,
                "    %s = %s;\n",
                field_expr.data, value->c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "    %s = (%s)(%s);\n",
                field_expr.data, cty, value->c_expr);
        }
        free(cty);
    }
    buf_free(&field_expr);
    return true;
}

/* Store one field using the current owner context when no explicit dynamic
 * aggregate offset table is required. */
static bool cg_emit_user_field_value_store(CG *cg,
                                           const char *object_expr,
                                           const UserField *uf,
                                           ExprResult *value,
                                           FengToken blame,
                                           bool replace_existing) {
    return cg_emit_user_field_value_store_with_offsets(cg,
                                                       object_expr,
                                                       uf,
                                                       NULL,
                                                       0U,
                                                       value,
                                                       blame,
                                                       replace_existing);
}

static bool cg_emit_generic_param_default_init(CG *cg,
                                               const char *lvalue_expr,
                                               const CGType *type,
                                               FengToken blame) {
    char *managed_descriptor;

    if (cg == NULL || lvalue_expr == NULL || type == NULL ||
        type->kind != CG_TYPE_GENERIC_PARAM) {
        return false;
    }

    const char *desc = cg_generic_param_desc_name(cg, type->generic_param_index);
    if (desc == NULL) {
        return cg_fail(cg,
                       blame,
                       "CE0237", "codegen: missing generic descriptor for default value");
    }
    managed_descriptor = cg_fresh_temp(cg, "_default_type_desc");
    if (managed_descriptor == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_fmt(cg->cur_body,
        "    switch (%s->kind) {\n"
        "        case FENG_VALUE_TRIVIAL:\n"
        "            memset(&%s, 0, feng_generic_value_size(%s));\n"
        "            break;\n"
        "        case FENG_VALUE_MANAGED_POINTER: {\n"
        "            const FengTypeDescriptor *%s = "
        "feng_generic_type_descriptor(%s);\n"
        "            %s->default_zero_init(&%s, %s);\n"
        "            break;\n"
        "        }\n"
        "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
        "            feng_aggregate_default_init(&%s, feng_generic_aggregate_descriptor(%s));\n"
        "            break;\n"
        "    }\n",
        desc,
        lvalue_expr, desc,
        managed_descriptor, desc,
        managed_descriptor, lvalue_expr, managed_descriptor,
        lvalue_expr, desc);
    free(managed_descriptor);
    return true;
}

/* Address-form counterpart used by shared generic constructor bodies, where
 * a reified field is located through the concrete descriptor rather than a C
 * struct member expression. */
static bool cg_emit_generic_param_default_init_at_address(
    CG *cg,
    const char *address_expr,
    const CGType *type,
    FengToken blame) {
    const char *descriptor;
    char *managed_descriptor;

    if (cg == NULL || address_expr == NULL || type == NULL ||
        type->kind != CG_TYPE_GENERIC_PARAM) {
        return false;
    }
    descriptor = cg_generic_param_desc_name(
        cg, type->generic_param_index);
    if (descriptor == NULL) {
        return cg_fail(cg,
                       blame,
                       "CE0237", "codegen: missing generic descriptor for default value");
    }
    managed_descriptor = cg_fresh_temp(cg, "_default_type_desc");
    if (managed_descriptor == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    buf_append_fmt(cg->cur_body,
        "    switch (%s->kind) {\n"
        "        case FENG_VALUE_TRIVIAL:\n"
        "            memset(%s, 0, feng_generic_value_size(%s));\n"
        "            break;\n"
        "        case FENG_VALUE_MANAGED_POINTER: {\n"
        "            const FengTypeDescriptor *%s = "
        "feng_generic_type_descriptor(%s);\n"
        "            %s->default_zero_init(%s, %s);\n"
        "            break;\n"
        "        }\n"
        "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
        "            feng_aggregate_default_init(%s, "
        "feng_generic_aggregate_descriptor(%s));\n"
        "            break;\n"
        "    }\n",
        descriptor,
        address_expr, descriptor,
        managed_descriptor, descriptor,
        managed_descriptor, address_expr, managed_descriptor,
        address_expr, descriptor);
    free(managed_descriptor);
    return true;
}

/* Emit the no-initializer member default for one field during object construction. */
static bool cg_emit_user_field_default_value(CG *cg,
                                             const char *object_expr,
                                             const UserField *uf,
                                             FengToken blame) {
    size_t reified_index = 0U;
    bool uses_reified_offset;
    Buf field_expr;

    if (cg == NULL || object_expr == NULL || uf == NULL) {
        return false;
    }
    uses_reified_offset = cg_user_field_reified_index(
        cg, uf, &reified_index);

    if (uf->type != NULL && uf->type->kind == CG_TYPE_GENERIC_PARAM) {
        Buf lvalue;

        if (cg_generic_param_desc_name(cg, uf->type->generic_param_index) == NULL) {
            return true;
        }

        buf_init(&lvalue);
        if (uses_reified_offset) {
            buf_append_fmt(&lvalue,
                           "((char *)%s + %s[%zu])",
                           object_expr,
                           cg->generic_type_method_field_offsets_name,
                           reified_index);
        } else {
            buf_append_fmt(&lvalue, "%s->%s", object_expr, uf->c_name);
        }
        if (lvalue.data == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        bool ok = uses_reified_offset
            ? cg_emit_generic_param_default_init_at_address(
                  cg, lvalue.data, uf->type, blame)
            : cg_emit_generic_param_default_init(
                  cg, lvalue.data, uf->type, blame);
        buf_free(&lvalue);
        return ok;
    }

    buf_init(&field_expr);
    if (uses_reified_offset) {
        char *ctype = cg_ctype_dup(uf->type);

        if (ctype == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(&field_expr,
                       "(*(%s *)((char *)%s + %s[%zu]))",
                       ctype,
                       object_expr,
                       cg->generic_type_method_field_offsets_name,
                       reified_index);
        free(ctype);
    } else {
        buf_append_fmt(&field_expr,
                       "%s->%s",
                       object_expr,
                       uf->c_name);
    }
    if (field_expr.data == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    if (cgtype_is_aggregate(uf->type)) {
        bool ok;
        const char *aggregate_desc = cg_aggregate_desc_name(uf->type);
        size_t rad_index;

        buf_append_cstr(cg->cur_body, "    ");
        if (uses_reified_offset && aggregate_desc != NULL &&
            cg_value_needs_reified_layout(cg, uf->type) &&
            cg_lookup_reified_agg_dep_index(
                cg, aggregate_desc, &rad_index)) {
            const char *rad_source = cg->generic_type_method_rad_via_desc
                                         ? "_desc"
                                         : "_td";

            buf_append_fmt(cg->cur_body,
                "feng_aggregate_default_init(&%s, "
                "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu])",
                field_expr.data, rad_source, rad_index);
            ok = true;
        } else {
            ok = cg_append_aggregate_default_init_call(
                cg->cur_body, uf->type, field_expr.data);
        }
        if (!ok) {
            buf_free(&field_expr);
            return cg_fail(cg,
                           blame,
                           "CE0233", "codegen: missing aggregate default-init rule for field '%s'",
                           uf->feng_name);
        }
        buf_append_cstr(cg->cur_body, ";\n");
        buf_free(&field_expr);
        return true;
    }

    {
        char *def_expr = NULL;
        char *cty = NULL;

        if (!cg_default_value_expr(cg, uf->type, &blame, &def_expr)) {
            buf_free(&field_expr);
            return false;
        }
        cty = cg_ctype_dup(uf->type);
        if (cty == NULL) {
            free(def_expr);
            buf_free(&field_expr);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        if (cgtype_is_by_value_struct(uf->type)) {
            buf_append_fmt(cg->cur_body,
                "    %s = %s;\n",
                field_expr.data, def_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "    %s = (%s)(%s);\n",
                field_expr.data, cty, def_expr);
        }
        free(cty);
        free(def_expr);
    }
    buf_free(&field_expr);
    return true;
}

/* Initialize every instance field to its type-level default zero.  This is
 * intentionally distinct from declaration initialization: field initializer
 * expressions and user constructors are not part of an object's default-zero
 * value. */
static bool cg_emit_user_type_default_field_values(CG *cg,
                                                   const UserType *type,
                                                   const char *object_expr,
                                                   FengToken blame) {
    if (cg == NULL || type == NULL || object_expr == NULL) {
        return false;
    }
    for (size_t index = 0U; index < type->field_count; ++index) {
        const UserField *field = &type->fields[index];

        if (!cg_emit_user_field_default_value(
                cg,
                object_expr,
                field,
                field->member != NULL ? field->member->token : blame)) {
            return false;
        }
    }
    return true;
}

static bool cg_user_type_member_initializers_capture_self(const UserType *ut,
                                                          bool *out_captures_self) {
    if (out_captures_self == NULL) {
        return false;
    }
    *out_captures_self = false;
    if (ut == NULL) {
        return true;
    }

    for (size_t i = 0; i < ut->field_count; ++i) {
        const UserField *uf = &ut->fields[i];
        const FengTypeMember *member = uf->member;
        char **captured_names = NULL;
        size_t captured_name_count = 0U;
        size_t captured_name_capacity = 0U;
        bool captures_self = false;

        if (member == NULL || member->as.field.initializer == NULL) {
            continue;
        }
        if (!cg_collect_capture_requirements_in_expr(member->as.field.initializer,
                                                     &captured_names,
                                                     &captured_name_count,
                                                     &captured_name_capacity,
                                                     &captures_self)) {
            for (size_t j = 0U; j < captured_name_count; ++j) free(captured_names[j]);
            free(captured_names);
            return false;
        }
        for (size_t j = 0U; j < captured_name_count; ++j) free(captured_names[j]);
        free(captured_names);
        if (captures_self) {
            *out_captures_self = true;
            return true;
        }
    }
    return true;
}

/* Borrow one already-materialized source field without re-evaluating the
 * source construction expression.  This mirrors ordinary member access but
 * starts from an ExprResult shared by every field in one mixin group. */
static bool cg_emit_mixin_source_field_borrow(CG *cg,
                                              const ExprResult *source,
                                              const UserField *source_field,
                                              ExprResult *out,
                                              FengToken blame) {
    Buf expression;

    if (cg == NULL || source == NULL || source->type == NULL ||
        source->type->kind != CG_TYPE_OBJECT || source->type->user == NULL ||
        source_field == NULL || out == NULL) {
        return cg_fail(cg,
                       blame,
                       "CE0377", "codegen: member mix source field is not lowerable");
    }
    er_init(out);
    buf_init(&expression);

    if (cg_type_is_value_semantics(source->type)) {
        if (cg_value_needs_reified_layout(cg, source->type)) {
            const char *aggregate_desc = cg_aggregate_desc_name(source->type);
            const char *rad_source = cg->generic_type_method_rad_via_desc
                                         ? "_desc"
                                         : "_td";
            size_t rad_index;
            size_t field_index = 0U;

            if (aggregate_desc == NULL ||
                !cg_lookup_reified_agg_dep_index(cg, aggregate_desc, &rad_index)) {
                return cg_fail(
                    cg,
                    blame,
                    "CE0378", "codegen: member mix source requires missing reified layout");
            }
            while (field_index < source->type->user->field_count &&
                   &source->type->user->fields[field_index] != source_field) {
                ++field_index;
            }
            if (field_index == source->type->user->field_count) {
                return cg_fail(cg,
                               blame,
                               "CE0379", "codegen: member mix source field index is missing");
            }
            if (source_field->type != NULL &&
                source_field->type->kind == CG_TYPE_GENERIC_PARAM) {
                buf_append_fmt(
                    &expression,
                    "(void *)((char *)&(%s) + ((const FengAggregateDescriptor *)%s->reified_agg_deps[%zu])->reified_field_offsets[%zu])",
                    source->c_expr,
                    rad_source,
                    rad_index,
                    field_index);
            } else {
                char *ctype = cg_ctype_dup(source_field->type);

                if (ctype == NULL) {
                    return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                }
                buf_append_fmt(
                    &expression,
                    "(*(%s *)((char *)&(%s) + ((const FengAggregateDescriptor *)%s->reified_agg_deps[%zu])->reified_field_offsets[%zu]))",
                    ctype,
                    source->c_expr,
                    rad_source,
                    rad_index,
                    field_index);
                free(ctype);
            }
        } else {
            buf_append_fmt(&expression,
                           "(%s).%s",
                           source->c_expr,
                           source_field->c_name);
        }
    } else if (cg_reference_needs_reified_field_layout(cg, source->type)) {
        char *descriptor = cg_rtd_expr_for_type(
            cg, source->type->user, blame);
        size_t field_index = 0U;

        while (field_index < source->type->user->field_count &&
               &source->type->user->fields[field_index] != source_field) {
            ++field_index;
        }
        if (descriptor == NULL ||
            field_index == source->type->user->field_count) {
            free(descriptor);
            return cg_fail(cg,
                           blame,
                           "CE0379", "codegen: member mix source field index is missing");
        }
        if (source_field->type != NULL &&
            source_field->type->kind == CG_TYPE_GENERIC_PARAM) {
            buf_append_fmt(
                &expression,
                "(void *)((char *)%s + %s->reified_field_offsets[%zu])",
                source->c_expr,
                descriptor,
                field_index);
        } else {
            char *ctype = cg_ctype_dup(source_field->type);

            if (ctype == NULL) {
                free(descriptor);
                return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }
            buf_append_fmt(
                &expression,
                "(*(%s *)((char *)%s + %s->reified_field_offsets[%zu]))",
                ctype,
                source->c_expr,
                descriptor,
                field_index);
            free(ctype);
        }
        free(descriptor);
    } else if (source_field->type != NULL &&
               source_field->type->kind == CG_TYPE_GENERIC_PARAM) {
        buf_append_fmt(&expression,
                       "(void *)&((%s)->%s)",
                       source->c_expr,
                       source_field->c_name);
    } else {
        buf_append_fmt(&expression,
                       "(%s)->%s",
                       source->c_expr,
                       source_field->c_name);
    }

    out->c_expr = expression.data;
    out->type = cgtype_clone(source_field->type);
    out->owns_ref = false;
    if (out->c_expr == NULL || out->type == NULL) {
        er_free(out);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    return true;
}

/* Emit one explicit-source mixin group.  A nested scope owns the temporary
 * source, so it is released immediately after all generated target fields
 * have copied their final values. */
static bool cg_emit_user_type_mixin_initializer(CG *cg,
                                                const UserType *target_type,
                                                const FengTypeMixinDecl *mixin,
                                                const char *object_expr,
                                                FengToken blame) {
    Scope *saved_scope;
    Scope *source_scope;
    ExprResult source;
    bool ok = false;

    if (cg == NULL || target_type == NULL || mixin == NULL ||
        mixin->source_constructor == NULL || object_expr == NULL) {
        return false;
    }
    saved_scope = cg->cur_scope;
    source_scope = scope_push(saved_scope);
    if (source_scope == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    cg->cur_scope = source_scope;
    er_init(&source);

    if (!cg_emit_expr(cg, mixin->source_constructor, &source)) {
        goto cleanup;
    }
    if (cg_materialize_to_local(cg, &source, "_mixin_source") == NULL ||
        source.type == NULL || source.type->kind != CG_TYPE_OBJECT ||
        source.type->user == NULL) {
        cg_fail(cg,
                blame,
                "CE0377", "codegen: member mix source construction is not an object value");
        goto cleanup;
    }

    for (size_t field_index = 0U;
         field_index < target_type->field_count;
         ++field_index) {
        const UserField *target_field = &target_type->fields[field_index];
        const FengTypeMember *member = target_field->member;
        const UserField *source_field;
        ExprResult field_value;

        if (member == NULL || member->mixin_origin != mixin) {
            continue;
        }
        if (!member->as.field.declaration_bound) {
            if (!cg_emit_user_field_default_value(cg,
                                                  object_expr,
                                                  target_field,
                                                  member->token)) {
                goto cleanup;
            }
            continue;
        }
        source_field = cg_user_type_field(
            source.type->user,
            member->as.field.name.data,
            member->as.field.name.length);
        if (source_field == NULL) {
            cg_fail(cg,
                    member->token,
                    "CE0379", "codegen: member mix source field is missing");
            goto cleanup;
        }
        if (!cg_emit_mixin_source_field_borrow(cg,
                                               &source,
                                               source_field,
                                               &field_value,
                                               member->token)) {
            goto cleanup;
        }
        if (!cg_emit_user_field_value_store(cg,
                                            object_expr,
                                            target_field,
                                            &field_value,
                                            member->token,
                                            false)) {
            er_free(&field_value);
            goto cleanup;
        }
        er_free(&field_value);
    }
    ok = true;

cleanup:
    er_free(&source);
    if (ok) {
        cg_release_scope(cg, source_scope);
    }
    cg->cur_scope = saved_scope;
    scope_pop_free(source_scope);
    return ok;
}

/* Emit the member declaration-initialization phase for a freshly allocated object. */
static bool cg_emit_user_type_member_initializers(CG *cg,
                                                  const UserType *ut,
                                                  const char *object_expr,
                                                  FengToken blame) {
    Scope *saved_scope = NULL;
    Scope *initializer_scope = NULL;
    bool captures_self = false;
    bool ok = false;

    /* Save concrete-subst scope so we can restore it even on early exit. */
    size_t saved_subst_count = cg->concrete_subst_param_count;
    const FengTypeParam *saved_subst_params = cg->concrete_subst_params;
    FengTypeRef *const *saved_subst_args = cg->concrete_subst_type_args;
    size_t saved_subst_arg_count = cg->concrete_subst_type_arg_count;

    if (cg == NULL || ut == NULL || object_expr == NULL) {
        return false;
    }

    /* For a concrete generic instance (e.g. Holder<i32>), field initializers
     * may reference the origin's type parameters (e.g. `Inner<T>()`).  Set
     * up a concrete substitution scope so nested constructor calls resolve
     * T → i32 and find the concrete instance Inner<i32> rather than the
     * open instance Inner<T> (which would fail outside a generic method
     * context with CE0005).  Only activate when the instance is concrete
     * (no open context type params) and has a known origin decl. */
    if (ut->is_generic_instance && ut->generic_origin_decl != NULL &&
        ut->generic_context_type_param_count == 0U &&
        ut->generic_origin_decl->kind == FENG_DECL_TYPE &&
        ut->generic_origin_decl->as.type_decl.type_param_count > 0U &&
        ut->generic_origin_decl->as.type_decl.type_param_count == ut->generic_type_arg_count) {
        cg->concrete_subst_param_count = ut->generic_origin_decl->as.type_decl.type_param_count;
        cg->concrete_subst_params = ut->generic_origin_decl->as.type_decl.type_params;
        cg->concrete_subst_type_args = ut->generic_type_args;
        cg->concrete_subst_type_arg_count = ut->generic_type_arg_count;
    }

    if (!cg_user_type_member_initializers_capture_self(ut, &captures_self)) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (captures_self) {
        FengSlice self_name = {"self", 4U};
        CGType *self_t = cgtype_new(CG_TYPE_OBJECT);

        saved_scope = cg->cur_scope;
        initializer_scope = scope_push(saved_scope);
        if (initializer_scope == NULL || self_t == NULL) {
            cgtype_free(self_t);
            if (initializer_scope != NULL) scope_pop_free(initializer_scope);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        self_t->user = (UserType *)ut;
        cg->cur_scope = initializer_scope;
        /* For @value types the object_expr is a pointer (e.g. "(&_val)");
         * dereference so the capture cell stores the value itself. */
        const char *self_source = object_expr;
        Buf self_deref;
        buf_init(&self_deref);
        if (cg_user_type_is_value(ut)) {
            buf_append_fmt(&self_deref, "(*%s)", object_expr);
            if (self_deref.data == NULL) {
                cgtype_free(self_t);
                scope_pop_free(initializer_scope);
                cg->cur_scope = saved_scope;
                return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }
            self_source = self_deref.data;
        }
        if (!cg_scope_bind_capture_cell(cg,
                                        initializer_scope,
                                        self_name,
                                        self_t,
                                        blame,
                                        self_source,
                                        true,
                                        false,
                                        false,
                                        FENG_CODEGEN_MAPING_VARIABLE_SELF)) {
            cgtype_free(self_t);
            buf_free(&self_deref);
            goto cleanup;
        }
        cgtype_free(self_t);
        buf_free(&self_deref);
    }

    for (size_t i = 0; i <= ut->field_count; ++i) {
        if (ut->decl != NULL && ut->decl->kind == FENG_DECL_TYPE) {
            for (size_t mixin_index = 0U;
                 mixin_index < ut->decl->as.type_decl.mixin_count;
                 ++mixin_index) {
                const FengTypeMixinDecl *mixin =
                    &ut->decl->as.type_decl.mixins[mixin_index];

                if (mixin->source_constructor != NULL &&
                    mixin->expanded_field_index == i &&
                    !cg_emit_user_type_mixin_initializer(cg,
                                                         ut,
                                                         mixin,
                                                         object_expr,
                                                         mixin->token)) {
                    goto cleanup;
                }
            }
        }
        if (i == ut->field_count) {
            break;
        }
        const UserField *uf = &ut->fields[i];
        const FengTypeMember *member = uf->member;

        if (member != NULL && member->mixin_origin != NULL &&
            member->mixin_origin->source_constructor != NULL) {
            /* The containing explicit-source group initialized this field. */
            continue;
        }
        if (member != NULL && member->as.field.initializer != NULL) {
            ExprResult init;
            bool ok;

            er_init(&init);
            ok = cg_emit_initializer_for_declared_type(cg,
                                                       member->as.field.initializer,
                                                       uf->type,
                                                       &init);
            if (!ok) {
                goto cleanup;
            }
            ok = cg_emit_user_field_value_store(cg,
                                                object_expr,
                                                uf,
                                                &init,
                                                member->token,
                                                false);
            er_free(&init);
            if (!ok) {
                goto cleanup;
            }
        } else if (!cg_emit_user_field_default_value(cg,
                                                     object_expr,
                                                     uf,
                                                     member != NULL ? member->token : blame)) {
            goto cleanup;
        }
    }
    ok = true;

cleanup:
    if (initializer_scope != NULL) {
        if (ok) cg_release_scope(cg, initializer_scope);
        cg->cur_scope = saved_scope;
        scope_pop_free(initializer_scope);
    }
    /* Restore concrete-subst scope. */
    cg->concrete_subst_param_count = saved_subst_count;
    cg->concrete_subst_params = saved_subst_params;
    cg->concrete_subst_type_args = saved_subst_args;
    cg->concrete_subst_type_arg_count = saved_subst_arg_count;
    return ok;
}

static bool cg_emit_binding(CG *cg, const FengStmt *stmt) {
    const FengBinding *b = &stmt->as.binding;
    if (b->is_destructure) {
        return cg_emit_destructure_binding(cg, stmt);
    }
    /* Determine type: explicit annotation else inferred from initializer. */
    CGType *decl_type = NULL;
    if (b->type) {
        if (!cg_resolve_type(cg, b->type, &b->token, &decl_type)) return false;
    }
    ExprResult init;
    bool has_init = b->initializer != NULL;
    if (has_init) {
        bool ok = cg_emit_initializer_for_declared_type(cg,
                                                        b->initializer,
                                                        decl_type,
                                                        &init);
        if (!ok) {
            cgtype_free(decl_type); return false;
        }
        if (!decl_type) {
            decl_type = cgtype_clone(init.type);
        }
    } else {
        if (!decl_type) {
            return cg_fail(cg, b->token,
                "CE0234", "codegen: binding without type or initializer not supported");
        }
    }
    if (cg_current_callable_captures_name(cg, b->name.data, b->name.length)) {
        bool ok;
        if (has_init) {
            ok = cg_scope_bind_capture_cell(cg,
                                            cg->cur_scope,
                                            b->name,
                                            decl_type,
                                            b->token,
                                            init.c_expr,
                                            true,
                                            init.owns_ref,
                                            true,
                                            FENG_CODEGEN_MAPING_VARIABLE_BINDING);
            er_free(&init);
        } else {
            ok = cg_scope_bind_capture_cell(cg,
                                            cg->cur_scope,
                                            b->name,
                                            decl_type,
                                            b->token,
                                            NULL,
                                            false,
                                            false,
                                            true,
                                            FENG_CODEGEN_MAPING_VARIABLE_BINDING);
        }
        if (ok) {
            ok = scope_mark_last_binding_mutability(cg->cur_scope,
                                                    b->mutability);
        }
        cgtype_free(decl_type);
        return ok;
    }
    char *cname = cg_local_cname(cg, b->name.data, b->name.length);
    if (!cname) { if (has_init) er_free(&init); cgtype_free(decl_type); return false; }

    if (decl_type->kind == CG_TYPE_GENERIC_PARAM) {
        char *descriptor_name = NULL;
        char *size_name = NULL;

        if (has_init && !init.is_storage_address &&
            cg_materialize_to_local(cg, &init, "_bind_generic_source") == NULL) {
            er_free(&init);
            free(cname);
            cgtype_free(decl_type);
            return cg_fail(cg, b->token,
                           "CE0235", "codegen: generic binding source has no stable storage");
        }
        if (!cg_emit_erased_generic_storage_declaration(
                cg,
                decl_type,
                cname,
                b->token,
                &descriptor_name,
                &size_name)) {
            if (has_init) er_free(&init);
            free(cname);
            cgtype_free(decl_type);
            return false;
        }
        if (has_init) {
            buf_append_fmt(cg->cur_body,
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(%s, %s, %s);\n"
                "            break;\n"
                "        case FENG_VALUE_MANAGED_POINTER: {\n"
                "            void *_generic_value = *(void *const *)%s;\n",
                descriptor_name,
                cname,
                init.c_expr,
                size_name,
                init.c_expr);
            if (init.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "            *(void **)%s = _generic_value;\n"
                    "            *(void **)%s = NULL;\n",
                    cname,
                    init.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "            feng_retain(_generic_value);\n"
                    "            *(void **)%s = _generic_value;\n",
                    cname);
            }
            buf_append_cstr(cg->cur_body,
                "            break;\n"
                "        }\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n");
            if (init.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "            memcpy(%s, %s, %s);\n"
                    "            memset(%s, 0, %s);\n",
                    cname,
                    init.c_expr,
                    size_name,
                    init.c_expr,
                    size_name);
            } else {
                buf_append_fmt(cg->cur_body,
                    "            feng_aggregate_assign(%s, %s, "
                    "feng_generic_aggregate_descriptor(%s));\n",
                    cname,
                    init.c_expr,
                    descriptor_name);
            }
            buf_append_cstr(cg->cur_body,
                "            break;\n"
                "    }\n");
            er_free(&init);
        } else {
            buf_append_fmt(cg->cur_body,
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            break;\n"
                "        case FENG_VALUE_MANAGED_POINTER:\n"
                "            *(void **)%s = NULL;\n"
                "            break;\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            feng_aggregate_default_init(%s, "
                "feng_generic_aggregate_descriptor(%s));\n"
                "            break;\n"
                "    }\n",
                descriptor_name,
                cname,
                cname,
                descriptor_name);
        }
        if (!scope_add(cg->cur_scope,
                       "_unused_internal_name__",
                       cname,
                       decl_type,
                       false) ||
            !scope_mark_last_erased_generic_storage(cg->cur_scope,
                                                    descriptor_name,
                                                    size_name) ||
            !scope_mark_last_binding_mutability(cg->cur_scope,
                                                b->mutability)) {
            free(cname);
            free(descriptor_name);
            free(size_name);
            return cg_fail(cg, b->token, "IE0001", "codegen: out of memory");
        }
        Local *added = &cg->cur_scope->items[cg->cur_scope->count - 1U];
        free(added->name);
        added->name = strndup(b->name.data, b->name.length);
        if (added->name == NULL ||
            !cg_debug_add_variable_record_slice_cgtype(
                cg,
                cname,
                b->name,
                NULL,
                decl_type,
                FENG_CODEGEN_MAPING_VARIABLE_BINDING,
                b->token)) {
            free(cname);
            free(descriptor_name);
            free(size_name);
            return false;
        }
        cg_emit_cleanup_push_for_erased_generic_storage(
            cg, cname, descriptor_name);
        free(cname);
        free(descriptor_name);
        free(size_name);
        return true;
    }

    char *cty = cg_ctype_dup(decl_type);
    if (!cg_emit_line_directive_force(cg, b->token)) {
        free(cname);
        cgtype_free(decl_type);
        return false;
    }
    if (cg_type_uses_reified_storage(cg, decl_type)) {
        char *descriptor_name = NULL;
        char *size_name = NULL;

        if (has_init && init.owns_ref && init.uses_reified_storage) {
            /* Adopt the constructor/call result slot as the binding itself. */
            free(cname);
            cname = strdup(init.c_expr);
            descriptor_name = init.reified_descriptor_c_name != NULL
                                  ? strdup(init.reified_descriptor_c_name)
                                  : NULL;
            size_name = init.reified_size_c_name != NULL
                            ? strdup(init.reified_size_c_name)
                            : NULL;
            if (cname == NULL || descriptor_name == NULL || size_name == NULL) {
                er_free(&init);
                free(cname);
                free(descriptor_name);
                free(size_name);
                cgtype_free(decl_type);
                return cg_fail(cg, b->token, "IE0001", "codegen: out of memory");
            }
        } else {
            char *source_address = NULL;

            if (has_init &&
                !cg_prepare_aggregate_assign_source(cg, &init, "_bind_source")) {
                er_free(&init);
                free(cname);
                cgtype_free(decl_type);
                return cg_fail(cg, b->token,
                               "IE0001", "codegen: failed to materialize reified binding source");
            }
            if (!cg_emit_reified_storage_declaration(cg,
                                                     decl_type,
                                                     cname,
                                                     b->token,
                                                     &descriptor_name,
                                                     &size_name)) {
                if (has_init) er_free(&init);
                free(cname);
                cgtype_free(decl_type);
                return false;
            }
            if (has_init) {
                source_address = cg_aggregate_result_address_dup(&init);
                if (source_address == NULL) {
                    er_free(&init);
                    free(cname);
                    free(descriptor_name);
                    free(size_name);
                    cgtype_free(decl_type);
                    return cg_fail(cg, b->token,
                                   "CE0235", "codegen: reified binding source has no address storage");
                }
                buf_append_fmt(cg->cur_body,
                               "    feng_aggregate_assign(%s, %s, %s);\n",
                               cname,
                               source_address,
                               descriptor_name);
                free(source_address);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    feng_aggregate_default_init(%s, %s);\n",
                               cname,
                               descriptor_name);
            }
        }
        if (has_init) {
            er_free(&init);
        }
        if (!scope_add(cg->cur_scope,
                       "_unused_internal_name__",
                       cname,
                       decl_type,
                       false) ||
            !scope_mark_last_reified_storage(cg->cur_scope,
                                             descriptor_name,
                                             size_name) ||
            !scope_mark_last_binding_mutability(cg->cur_scope,
                                                b->mutability)) {
            free(cname);
            free(descriptor_name);
            free(size_name);
            return cg_fail(cg, b->token, "IE0001", "codegen: out of memory");
        }
        Local *added = &cg->cur_scope->items[cg->cur_scope->count - 1U];
        free(added->name);
        added->name = strndup(b->name.data, b->name.length);
        if (added->name == NULL ||
            !cg_debug_add_variable_record_slice_cgtype(
                cg,
                cname,
                b->name,
                NULL,
                decl_type,
                FENG_CODEGEN_MAPING_VARIABLE_BINDING,
                b->token)) {
            free(cname);
            free(descriptor_name);
            free(size_name);
            return false;
        }
        cg_emit_cleanup_push_for_reified_aggregate_storage(cg,
                                                           cname,
                                                           descriptor_name);
        free(cname);
        free(descriptor_name);
        free(size_name);
        return true;
    }

    if (has_init) {
        if (cgtype_is_managed(decl_type)) {
            if (init.owns_ref) {
                /* Take the +1 directly. */
                buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, cname, init.c_expr);
            } else {
                /* Borrowed; retain into our slot. */
                buf_append_fmt(cg->cur_body, "    %s %s = %s; feng_retain(%s);\n",
                               cty, cname, init.c_expr, cname);
            }
        } else if (cgtype_is_aggregate(decl_type)) {
            if (init.owns_ref) {
                buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, cname, init.c_expr);
            } else if (cg_value_needs_reified_layout(cg, decl_type)) {
                /* Reified tuple: retain via RAD. */
                const char *agg_desc = cg_aggregate_desc_name(decl_type);
                size_t rad_idx;
                if (agg_desc &&
                    cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                    const char *src = cg->generic_type_method_rad_via_desc
                                          ? "_desc" : "_td";
                    buf_append_fmt(cg->cur_body,
                        "    %s %s = %s; feng_aggregate_retain(&%s, "
                        "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]);\n",
                        cty, cname, init.c_expr, cname, src, rad_idx);
                } else {
                    buf_append_fmt(cg->cur_body, "    %s %s = %s;\n",
                                   cty, cname, init.c_expr);
                }
            } else {
                const char *desc = cg_aggregate_desc_name(decl_type);
                if (!desc) {
                    er_free(&init);
                    free(cty); free(cname); cgtype_free(decl_type);
                    return cg_fail(cg, b->token,
                        "CE0235", "codegen: missing aggregate descriptor for spec local");
                }
                buf_append_fmt(cg->cur_body,
                               "    %s %s = %s; feng_aggregate_retain(&%s, &%s);\n",
                               cty, cname, init.c_expr, cname, desc);
            }
        } else {
            if (cgtype_is_by_value_struct(decl_type)) {
                buf_append_fmt(cg->cur_body, "    %s %s = %s;\n",
                               cty, cname, init.c_expr);
            } else {
                buf_append_fmt(cg->cur_body, "    %s %s = (%s)(%s);\n",
                               cty, cname, cty, init.c_expr);
            }
        }
        er_free(&init);
    } else {
        /* No initializer: emit the type's default zero value. Per
         * docs/specifications/feng-builtin-type.md & docs/specifications/feng-type.md §5/§7 every Feng
         * type has a finite default zero (Feng has no `null`). For managed
         * types the resulting reference is owned by this slot and joins the
         * cleanup chain just like an explicit initializer. */
        if (cgtype_is_aggregate(decl_type)) {
            /* Aggregate default-zero is owned by the aggregate facts provider.
             * For object-form specs this routes through the descriptor's
             * default_init function and produces an owned subject slot. */
            if (cg_value_needs_reified_layout(cg, decl_type)) {
                const char *agg_desc = cg_aggregate_desc_name(decl_type);
                size_t rad_idx;

                if (agg_desc == NULL ||
                    !cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                    free(cname); free(cty); cgtype_free(decl_type);
                    return cg_fail(cg, b->token,
                        "CE0236", "codegen: missing reified aggregate default-init rule");
                }
                const char *src = cg->generic_type_method_rad_via_desc
                                      ? "_desc" : "_td";
                buf_append_fmt(cg->cur_body,
                    "    %s %s; feng_aggregate_default_init(&%s, "
                    "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]);\n",
                    cty,
                    cname,
                    cname,
                    src,
                    rad_idx);
            } else {
                Buf init_call;
                buf_init(&init_call);
                if (!cg_append_aggregate_default_init_call(&init_call, decl_type, cname)) {
                    buf_free(&init_call);
                    free(cname); free(cty); cgtype_free(decl_type);
                    return cg_fail(cg, b->token,
                        "CE0236", "codegen: missing aggregate default-init rule");
                }
                buf_append_fmt(cg->cur_body, "    %s %s; ", cty, cname);
                buf_append_cstr(cg->cur_body, init_call.data);
                buf_append_cstr(cg->cur_body, ";\n");
                buf_free(&init_call);
            }
        } else {
            char *def_expr = NULL;
            if (!cg_default_value_expr(cg, decl_type, &b->token, &def_expr)) {
                free(cname); free(cty); cgtype_free(decl_type); return false;
            }
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, cname, def_expr);
            free(def_expr);
        }
    }
    free(cty);

    if (!scope_add(cg->cur_scope, /*feng*/ "_unused_internal_name__", cname,
                   decl_type, false) ||
        !scope_mark_last_binding_mutability(cg->cur_scope,
                                            b->mutability)) {
        free(cname); return false;
    }
    /* Replace the placeholder with the real Feng name. */
    Local *added = &cg->cur_scope->items[cg->cur_scope->count - 1];
    free(added->name);
    added->name = strndup(b->name.data, b->name.length);
    if (!cg_debug_add_variable_record_slice_cgtype(cg,
                                                   cname,
                                                   b->name,
                                                   NULL,
                                                   decl_type,
                                                   FENG_CODEGEN_MAPING_VARIABLE_BINDING,
                                                   b->token)) {
        free(cname);
        return false;
    }
    if (cgtype_is_managed(decl_type)) {
        if (!cg_emit_line_directive_force(cg, b->token)) {
            free(cname);
            return false;
        }
        cg_emit_cleanup_push_for_managed_local(cg, cname);
    } else if (cgtype_is_aggregate(decl_type)) {
        if (!cg_emit_line_directive_force(cg, b->token)) {
            free(cname);
            return false;
        }
        cg_emit_cleanup_push_for_aggregate_local(cg, cname, decl_type);
    }
    free(cname);
    return true;
}

/** Emit assignment to a static binding selected through a generic descriptor. */
static bool cg_emit_shared_static_binding_assign(
    CG *cg,
    const FengStmt *stmt,
    const UserType *target,
    const TypeStaticBinding *binding,
    bool is_compound,
    FengTokenKind binary_op) {
    char *state_name = NULL;
    char *destination = NULL;
    char *cty = NULL;
    bool ok = false;

    if (!cg_emit_shared_static_binding_state(cg,
                                             target,
                                             binding,
                                             stmt->token,
                                             &state_name)) {
        goto cleanup;
    }
    if (binding->type->kind == CG_TYPE_GENERIC_PARAM) {
        ExprResult value;
        Buf storage;

        if (is_compound) {
            cg_fail(cg,
                    stmt->token,
                    "CE0245", "codegen: compound assignment requires a numeric static binding type");
            goto cleanup;
        }
        if (!cg_emit_expr_for_expected_type(cg,
                                            stmt->as.assign.value,
                                            binding->type,
                                            &value)) {
            goto cleanup;
        }
        buf_init(&storage);
        buf_append_fmt(&storage, "%s->storage", state_name);
        ok = storage.data != NULL &&
             cg_emit_generic_value_store(cg,
                                                  storage.data,
                                                  binding->type,
                                                  &value,
                                                  stmt->token,
                                                  true);
        buf_free(&storage);
        er_free(&value);
        goto cleanup;
    }

    cty = cg_ctype_dup(binding->type);
    if (cty == NULL) {
        cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    {
        Buf lvalue;

        buf_init(&lvalue);
        buf_append_fmt(&lvalue,
                       "(*(%s *)%s->storage)",
                       cty,
                       state_name);
        destination = lvalue.data;
    }
    if (destination == NULL) {
        cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    if (is_compound) {
        char *old_name;
        ExprResult value;
        Buf expression;

        if (!cgtype_is_numeric(binding->type->kind)) {
            cg_fail(cg,
                    stmt->token,
                    "CE0245", "codegen: compound assignment requires a numeric static binding type");
            goto cleanup;
        }
        old_name = cg_fresh_temp(cg, "_old");
        if (old_name == NULL) {
            cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        buf_append_fmt(cg->cur_body,
                       "    %s %s = %s;\n",
                       cty,
                       old_name,
                       destination);
        if (!cg_emit_expr(cg, stmt->as.assign.value, &value)) {
            free(old_name);
            goto cleanup;
        }
        buf_init(&expression);
        if (!cg_append_numeric_op_expr(&expression,
                                       binding->type->kind,
                                       old_name,
                                       binary_op,
                                       value.c_expr)) {
            buf_free(&expression);
            er_free(&value);
            free(old_name);
            cg_fail(cg,
                    stmt->token,
                    "CE0073", "codegen: unsupported compound assignment operator");
            goto cleanup;
        }
        buf_append_fmt(cg->cur_body,
                       "    %s = (%s)(%s);\n",
                       destination,
                       cty,
                       expression.data);
        buf_free(&expression);
        er_free(&value);
        free(old_name);
        ok = true;
        goto cleanup;
    }

    {
        ExprResult value;

        if (!cg_emit_expr_for_expected_type(cg,
                                            stmt->as.assign.value,
                                            binding->type,
                                            &value)) {
            goto cleanup;
        }
        if (cgtype_is_managed(binding->type)) {
            if (value.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { void *_old = %s; %s = %s; feng_release(_old); }\n",
                    destination,
                    destination,
                    value.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_assign((void **)&%s, %s);\n",
                    destination,
                    value.c_expr);
            }
        } else if (cgtype_is_aggregate(binding->type)) {
            const char *aggregate_descriptor =
                cg_aggregate_desc_name(binding->type);

            if (aggregate_descriptor == NULL) {
                er_free(&value);
                cg_fail(cg,
                        stmt->token,
                        "CE0246", "codegen: missing aggregate descriptor for static binding write");
                goto cleanup;
            }
            if (!cg_prepare_aggregate_assign_source(cg, &value, "_t")) {
                er_free(&value);
                cg_fail(cg, stmt->token,
                        "IE0001", "codegen: out of memory");
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body,
                "    feng_aggregate_assign(%s->storage, &%s, &%s);\n",
                state_name,
                value.c_expr,
                aggregate_descriptor);
        } else if (cgtype_is_by_value_struct(binding->type)) {
            buf_append_fmt(cg->cur_body,
                           "    %s = %s;\n",
                           destination,
                           value.c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    %s = (%s)(%s);\n",
                           destination,
                           cty,
                           value.c_expr);
        }
        er_free(&value);
        ok = true;
    }

cleanup:
    free(cty);
    free(destination);
    free(state_name);
    return ok;
}

/* Assign a field whose address is provided by a closed descriptor. Aggregate
 * receivers already use address-form storage; reference receivers use their
 * object pointer and obtain the FengTypeDescriptor from the active slot. */
static bool cg_emit_reified_user_field_assign(CG *cg,
                                              const FengStmt *stmt,
                                              ExprResult *receiver,
                                              const UserField *field,
                                              bool is_compound,
                                              FengTokenKind binary_op) {
    const char *descriptor_expr = receiver->reified_descriptor_c_name;
    char *owned_descriptor_expr = NULL;
    char *field_address = NULL;
    size_t field_index = 0U;
    bool ok = false;

    if (descriptor_expr == NULL) {
        if (cg_reference_needs_reified_field_layout(cg, receiver->type)) {
            owned_descriptor_expr =
                cg_rtd_expr_for_type(cg, receiver->type->user, stmt->token);
        } else {
            owned_descriptor_expr =
                cg_reified_aggregate_descriptor_expr_dup(cg,
                                                          receiver->type,
                                                          stmt->token);
        }
        descriptor_expr = owned_descriptor_expr;
    }
    while (field_index < receiver->type->user->field_count &&
           &receiver->type->user->fields[field_index] != field) {
        ++field_index;
    }
    field_address = cg_fresh_temp(cg, "_value_field");
    if (descriptor_expr == NULL || field_address == NULL ||
        field_index == receiver->type->user->field_count) {
        goto cleanup;
    }
    buf_append_fmt(cg->cur_body,
                   "    void *%s = (void *)((char *)%s + %s->reified_field_offsets[%zu]);\n",
                   field_address,
                   receiver->c_expr,
                   descriptor_expr,
                   field_index);

    if (is_compound) {
        ExprResult value;
        char *ctype = NULL;
        char *old_name = NULL;
        Buf expression;

        if (!cgtype_is_numeric(field->type->kind)) {
            cg_fail(cg, stmt->token,
                    "CE0249", "codegen: compound member assignment requires a numeric field type");
            goto cleanup;
        }
        ctype = cg_ctype_dup(field->type);
        old_name = cg_fresh_temp(cg, "_old");
        if (ctype == NULL || old_name == NULL) {
            free(ctype);
            free(old_name);
            goto cleanup;
        }
        buf_append_fmt(cg->cur_body,
                       "    %s %s = *(%s *)%s;\n",
                       ctype, old_name, ctype, field_address);
        if (!cg_emit_expr(cg, stmt->as.assign.value, &value)) {
            free(ctype);
            free(old_name);
            goto cleanup;
        }
        buf_init(&expression);
        if (!cg_append_numeric_op_expr(&expression,
                                       field->type->kind,
                                       old_name,
                                       binary_op,
                                       value.c_expr)) {
            er_free(&value);
            buf_free(&expression);
            free(ctype);
            free(old_name);
            cg_fail(cg, stmt->token,
                    "CE0250", "codegen: unsupported compound member assignment operator");
            goto cleanup;
        }
        buf_append_fmt(cg->cur_body,
                       "    *(%s *)%s = (%s)(%s);\n",
                       ctype, field_address, ctype, expression.data);
        er_free(&value);
        buf_free(&expression);
        free(ctype);
        free(old_name);
        ok = true;
        goto cleanup;
    }

    {
        ExprResult value;

        if (!cg_emit_expr_for_expected_type(cg,
                                            stmt->as.assign.value,
                                            field->type,
                                            &value)) {
            goto cleanup;
        }
        if (field->type->kind == CG_TYPE_GENERIC_PARAM) {
            const char *generic_desc =
                cg_generic_param_desc_name(cg,
                                           field->type->generic_param_index);
            char *source = cg_fresh_temp(cg, "_generic_source");

            if (generic_desc == NULL || source == NULL || value.type == NULL ||
                value.type->kind != CG_TYPE_GENERIC_PARAM ||
                value.type->generic_param_index !=
                    field->type->generic_param_index) {
                free(source);
                er_free(&value);
                cg_fail(cg, stmt->token,
                        "CE0257", "codegen: generic member assignment requires a matching descriptor");
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body,
                "    const void *%s = %s;\n"
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
                "            break;\n"
                "        case FENG_VALUE_MANAGED_POINTER: {\n"
                "            void *_new_value = *(void *const *)%s;\n"
                "            feng_retain(_new_value);\n"
                "            void *_old_value = *(void **)%s;\n"
                "            *(void **)%s = _new_value;\n"
                "            feng_release(_old_value);\n"
                "            break;\n"
                "        }\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            feng_aggregate_assign(%s, %s, feng_generic_aggregate_descriptor(%s));\n"
                "            break;\n"
                "    }\n",
                source, value.c_expr,
                generic_desc,
                field_address, source, generic_desc,
                source,
                field_address,
                field_address,
                field_address, source, generic_desc);
            free(source);
        } else if (cgtype_is_managed(field->type)) {
            if (value.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { void *_old = *(void **)%s; *(void **)%s = %s; feng_release(_old); }\n",
                    field_address, field_address, value.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_assign((void **)%s, %s);\n",
                    field_address, value.c_expr);
            }
        } else if (cgtype_is_aggregate(field->type)) {
            char *source_address;
            char *descriptor;

            if (!cg_prepare_aggregate_assign_source(cg, &value, "_field_source")) {
                er_free(&value);
                goto cleanup;
            }
            source_address = cg_aggregate_result_address_dup(&value);
            descriptor = cg_aggregate_descriptor_expr_dup(cg,
                                                           field->type,
                                                           stmt->token);
            if (source_address == NULL || descriptor == NULL) {
                free(source_address);
                free(descriptor);
                er_free(&value);
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body,
                           "    feng_aggregate_assign(%s, %s, %s);\n",
                           field_address,
                           source_address,
                           descriptor);
            free(source_address);
            free(descriptor);
        } else {
            char *ctype = cg_ctype_dup(field->type);

            if (ctype == NULL) {
                er_free(&value);
                goto cleanup;
            }
            buf_append_fmt(cg->cur_body,
                           "    *(%s *)%s = (%s)(%s);\n",
                           ctype, field_address, ctype, value.c_expr);
            free(ctype);
        }
        er_free(&value);
    }
    ok = true;

cleanup:
    free(owned_descriptor_expr);
    free(field_address);
    return ok;
}

/* Statement-scoped ownership state for one assignment receiver. An active
 * guard pairs a generated strong-reference temporary with a cleanup-chain
 * node until the final target write has completed. */
typedef struct CGAssignmentOwnerGuard {
    bool active;
    Scope *scope;
    size_t first_local_index;
} CGAssignmentOwnerGuard;

/* Conservatively prove that evaluating an expression cannot execute user
 * code or rebind any assignment target. Only intrinsic scalar computation
 * and reads from already-resolved local slots participate in this proof. */
static bool cg_assignment_expr_cannot_mutate_state(CG *cg,
                                                   const FengExpr *expr) {
    if (cg == NULL || expr == NULL) {
        return false;
    }
    switch (expr->kind) {
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
        case FENG_EXPR_SELF:
            return true;
        case FENG_EXPR_IDENTIFIER:
            /* Non-local identifiers can trigger module/static lazy
             * initialization, so only a lexical local read is proven safe. */
            return scope_lookup(cg->cur_scope,
                                expr->as.identifier.data,
                                expr->as.identifier.length) != NULL;
        case FENG_EXPR_UNARY:
            return cg_assignment_expr_cannot_mutate_state(
                cg, expr->as.unary.operand);
        case FENG_EXPR_BINARY:
            return cg_assignment_expr_cannot_mutate_state(
                       cg, expr->as.binary.left) &&
                   cg_assignment_expr_cannot_mutate_state(
                       cg, expr->as.binary.right);
        default:
            return false;
    }
}

/* Return whether final storage replacement finishes locating and writing the
 * target before it can invoke a user finalizer. Trivial stores execute no
 * user code, while managed-pointer stores publish the new pointer before
 * releasing the old one. Aggregate helpers release old managed slots before
 * their final byte copy, and erased generic writes can select that aggregate
 * path at runtime, so both require the receiver guard. */
static bool cg_assignment_writeback_cannot_invalidate_receiver(
    const CGType *target_type) {
    return target_type != NULL &&
           target_type->kind != CG_TYPE_GENERIC_PARAM &&
           !cgtype_is_aggregate(target_type);
}

/* Snapshot and retain an unstable borrowed managed receiver when a later
 * operation may invalidate it. The existing cleanup chain releases the
 * snapshot if evaluation unwinds before the final assignment write. */
static bool cg_assignment_owner_guard_begin(
    CG *cg,
    ExprResult *receiver,
    bool later_work_cannot_invalidate_receiver,
    FengToken blame,
    CGAssignmentOwnerGuard *guard) {
    char *temporary;
    char *ctype;

    if (cg == NULL || receiver == NULL || receiver->type == NULL ||
        guard == NULL) {
        return false;
    }
    guard->active = false;
    guard->scope = NULL;
    guard->first_local_index = 0U;
    if (later_work_cannot_invalidate_receiver ||
        !cgtype_is_managed(receiver->type) || receiver->owns_ref ||
        receiver->managed_identity_is_stable) {
        return true;
    }

    temporary = cg_fresh_temp(cg, "_assign_owner");
    ctype = cg_ctype_dup(receiver->type);
    if (temporary == NULL || ctype == NULL) {
        free(temporary);
        free(ctype);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    %s %s = %s; feng_retain(%s);\n",
                   ctype,
                   temporary,
                   receiver->c_expr,
                   temporary);
    free(ctype);
    guard->scope = cg->cur_scope;
    guard->first_local_index = cg->cur_scope->count;
    if (!cg_register_local_for_cleanup(cg,
                                       temporary,
                                       receiver->type,
                                       blame)) {
        free(temporary);
        guard->scope = NULL;
        return false;
    }

    free(receiver->c_expr);
    receiver->c_expr = temporary;
    receiver->managed_identity_is_stable = true;
    guard->active = true;
    return true;
}

/* End one active assignment receiver guard after the final target write.
 * Every cleanup local registered by later RHS lowering is released first;
 * the guarded receiver is the oldest item in this suffix and releases last. */
static void cg_assignment_owner_guard_end(
    CG *cg,
    ExprResult *receiver,
    CGAssignmentOwnerGuard *guard) {
    Scope suffix;

    if (cg == NULL || receiver == NULL || receiver->c_expr == NULL ||
        guard == NULL || !guard->active || guard->scope == NULL ||
        guard->first_local_index >= guard->scope->count) {
        return;
    }
    memset(&suffix, 0, sizeof(suffix));
    suffix.items = guard->scope->items + guard->first_local_index;
    suffix.count = guard->scope->count - guard->first_local_index;
    cg_release_scope(cg, &suffix);
    scope_discard_suffix(guard->scope, guard->first_local_index);
    guard->active = false;
    guard->scope = NULL;
}

static bool cg_emit_assign(CG *cg, const FengStmt *stmt) {
    const FengExpr *target = stmt->as.assign.target;
    const bool is_compound = cg_assignment_is_compound(stmt->as.assign.op);
    const FengTokenKind binary_op = cg_assignment_binary_op(stmt->as.assign.op);
    if (target->kind == FENG_EXPR_INDEX) {
        CGAssignmentOwnerGuard owner_guard = {0};
        ExprResult recv;
        if (!cg_emit_expr(cg, target->as.index.object, &recv)) return false;
        if (recv.type->kind != CG_TYPE_ARRAY || !recv.type->element) {
            er_free(&recv);
            return cg_fail(cg, stmt->token,
                "CE0237", "codegen: indexed assignment requires an array value");
        }
        if (cgtype_is_managed(recv.type) && recv.owns_ref) {
            if (cg_materialize_to_local(cg, &recv, "_t") == NULL) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                               "IE0001", "codegen: out of memory");
            }
        }
        if (!cg_assignment_owner_guard_begin(
                cg,
                &recv,
                cg_assignment_expr_cannot_mutate_state(
                    cg, target->as.index.index) &&
                    cg_assignment_expr_cannot_mutate_state(
                        cg, stmt->as.assign.value) &&
                    cg_assignment_writeback_cannot_invalidate_receiver(
                        recv.type->element),
                stmt->token,
                &owner_guard)) {
            er_free(&recv);
            return false;
        }
        ExprResult ix;
        if (!cg_emit_expr(cg, target->as.index.index, &ix)) {
            er_free(&recv); return false;
        }
        if (!cgtype_is_integer(ix.type->kind)) {
            er_free(&ix); er_free(&recv);
            return cg_fail(cg, stmt->token,
                "CE0189", "codegen: array index must be an integer");
        }
        char *idx_tmp = cg_fresh_temp(cg, "_idx");
        if (!idx_tmp) { er_free(&ix); er_free(&recv); return false; }
        buf_append_fmt(cg->cur_body, "    size_t %s = (size_t)(%s);\n",
                       idx_tmp, ix.c_expr);
        buf_append_fmt(cg->cur_body, "    feng_array_check_index(%s, %s);\n",
                       recv.c_expr, idx_tmp);
        if (is_compound) {
            char *elem_cty = cg_ctype_dup(recv.type->element);
            char *old_tmp = NULL;
            ExprResult v;
            Buf expr;

            if (!elem_cty || !cgtype_is_numeric(recv.type->element->kind)) {
                free(elem_cty);
                free(idx_tmp);
                er_free(&ix);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0238", "codegen: compound indexed assignment requires a numeric element type");
            }

            old_tmp = cg_fresh_temp(cg, "_old");
            if (!old_tmp) {
                free(elem_cty);
                free(idx_tmp);
                er_free(&ix);
                er_free(&recv);
                return false;
            }

            buf_append_fmt(cg->cur_body,
                "    %s %s = ((%s *)feng_array_data(%s))[%s];\n",
                elem_cty, old_tmp, elem_cty, recv.c_expr, idx_tmp);

            if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                free(old_tmp);
                free(elem_cty);
                free(idx_tmp);
                er_free(&ix);
                er_free(&recv);
                return false;
            }

            buf_init(&expr);
            if (!cg_append_numeric_op_expr(&expr,
                                           recv.type->element->kind,
                                           old_tmp,
                                           binary_op,
                                           v.c_expr)) {
                buf_free(&expr);
                er_free(&v);
                free(old_tmp);
                free(elem_cty);
                free(idx_tmp);
                er_free(&ix);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0239", "codegen: unsupported compound indexed assignment operator");
            }

            buf_append_fmt(cg->cur_body,
                "    ((%s *)feng_array_data(%s))[%s] = (%s)(%s);\n",
                elem_cty, recv.c_expr, idx_tmp, elem_cty, expr.data);

            cg_assignment_owner_guard_end(cg, &recv, &owner_guard);

            buf_free(&expr);
            er_free(&v);
            free(old_tmp);
            free(elem_cty);
            free(idx_tmp);
            er_free(&ix);
            er_free(&recv);
            return true;
        }
        ExprResult v;
        if (!cg_emit_expr_for_expected_type(cg,
                                            stmt->as.assign.value,
                                            recv.type->element,
                                            &v)) {
            free(idx_tmp); er_free(&ix); er_free(&recv); return false;
        }
        char *elem_cty = cg_ctype_dup(recv.type->element);
        if (!elem_cty) {
            free(idx_tmp); er_free(&v); er_free(&ix); er_free(&recv); return false;
        }
        if (recv.type->element->kind == CG_TYPE_GENERIC_PARAM) {
            size_t gp_index = recv.type->element->generic_param_index;
            const char *desc = cg_generic_param_desc_name(cg, gp_index);
            if (desc == NULL) {
                free(elem_cty);
                free(idx_tmp);
                er_free(&v);
                er_free(&ix);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0240", "codegen: missing generic descriptor for array element assignment");
            }
            if (v.type->kind != CG_TYPE_GENERIC_PARAM ||
                v.type->generic_param_index != gp_index) {
                free(elem_cty);
                free(idx_tmp);
                er_free(&v);
                er_free(&ix);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0241", "codegen: generic array element assignment requires a value with the same generic type parameter");
            }
            char *slot_tmp = cg_fresh_temp(cg, "_gslot");
            char *src_tmp = cg_fresh_temp(cg, "_gsrc");
            if (!slot_tmp || !src_tmp) {
                free(slot_tmp);
                free(src_tmp);
                free(elem_cty);
                free(idx_tmp);
                er_free(&v);
                er_free(&ix);
                er_free(&recv);
                return false;
            }
            buf_append_fmt(cg->cur_body,
                "    void *%s = ((%s->kind == FENG_VALUE_MANAGED_POINTER) ? "
                "(void *)&((void **)feng_array_data(%s))[%s] : "
                "(void *)((char *)feng_array_data(%s) + (%s) * feng_generic_value_size(%s)));\n"
                "    const void *%s = %s;\n"
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
                "            break;\n"
                "        case FENG_VALUE_MANAGED_POINTER: {\n"
                "            void *_new_value = *(void *const *)%s;\n"
                "            feng_retain(_new_value);\n"
                "            void *_old_value = *(void **)%s;\n"
                "            *(void **)%s = _new_value;\n"
                "            feng_release(_old_value);\n"
                "            break;\n"
                "        }\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            feng_aggregate_assign(%s, %s, feng_generic_aggregate_descriptor(%s));\n"
                "            break;\n"
                "    }\n",
                slot_tmp, desc,
                recv.c_expr, idx_tmp,
                recv.c_expr, idx_tmp, desc,
                src_tmp, v.c_expr,
                desc,
                slot_tmp, src_tmp, desc,
                src_tmp,
                slot_tmp,
                slot_tmp,
                slot_tmp, src_tmp, desc);
            cg_assignment_owner_guard_end(cg, &recv, &owner_guard);
            free(slot_tmp);
            free(src_tmp);
            free(elem_cty);
            free(idx_tmp);
            er_free(&v);
            er_free(&ix);
            er_free(&recv);
            return true;
        }
        if (cg_value_needs_reified_layout(cg, recv.type->element)) {
            const char *agg_desc = cg_aggregate_desc_name(recv.type->element);
            size_t rad_idx;
            bool has_rad = agg_desc != NULL &&
                           cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx);
            if (!has_rad) {
                free(elem_cty); free(idx_tmp);
                er_free(&v); er_free(&ix); er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0242", "codegen: tuple array element requires reified layout "
                    "but no reified_agg_dep found");
            }
            const char *rad_src = cg->generic_type_method_rad_via_desc
                                      ? "_desc" : "_td";
            if (v.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    feng_aggregate_take("
                    "(void *)((char *)feng_array_data(%s) + (%s) * %s->reified_agg_deps[%zu]->size), "
                    "(void *)%s, %s->reified_agg_deps[%zu]);\n",
                    recv.c_expr, idx_tmp, rad_src, rad_idx,
                    v.c_expr, rad_src, rad_idx);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_aggregate_assign("
                    "(void *)((char *)feng_array_data(%s) + (%s) * %s->reified_agg_deps[%zu]->size), "
                    "(const void *)%s, %s->reified_agg_deps[%zu]);\n",
                    recv.c_expr, idx_tmp, rad_src, rad_idx,
                    v.c_expr, rad_src, rad_idx);
            }
        } else if (cgtype_is_managed(recv.type->element)) {
            if (v.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { %s *_slots = (%s *)feng_array_data(%s);"
                    " void *_old = _slots[%s]; _slots[%s] = %s;"
                    " feng_release(_old); }\n",
                    elem_cty, elem_cty, recv.c_expr, idx_tmp, idx_tmp, v.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_assign((void**)&((%s *)feng_array_data(%s))[%s], %s);\n",
                    elem_cty, recv.c_expr, idx_tmp, v.c_expr);
            }
        } else if (cgtype_is_aggregate(recv.type->element)) {
            /* Persistent aggregate slots copy borrowed values and move owned
             * expression results. Both helpers release the old slot first. */
            const char *agg_desc = cg_aggregate_desc_name(recv.type->element);
            char *source_address;
            bool take_source;
            if (agg_desc == NULL) {
                free(elem_cty); free(idx_tmp);
                er_free(&v); er_free(&ix); er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0243", "codegen: missing aggregate descriptor for spec array element write");
            }
            if (!cg_prepare_aggregate_store_source(
                    cg, &v, "_t", &take_source)) {
                free(elem_cty); free(idx_tmp);
                er_free(&v); er_free(&ix); er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "IE0001", "codegen: out of memory");
            }
            source_address = cg_aggregate_result_address_dup(&v);
            if (source_address == NULL) {
                free(elem_cty); free(idx_tmp);
                er_free(&v); er_free(&ix); er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0243", "codegen: aggregate array source has no address");
            }
            size_t rad_idx;
            if (cg_lookup_reified_agg_dep_index(cg, agg_desc, &rad_idx)) {
                const char *rad_src = cg->generic_type_method_rad_via_desc ? "_desc" : "_td";
                buf_append_fmt(cg->cur_body,
                    "    %s("
                    "(void *)((char *)feng_array_data(%s) + (%s) * %s->reified_agg_deps[%zu]->size), "
                    "%s, %s->reified_agg_deps[%zu]);\n",
                    take_source ? "feng_aggregate_take" : "feng_aggregate_assign",
                    recv.c_expr, idx_tmp, rad_src, rad_idx,
                    source_address, rad_src, rad_idx);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    %s(&((%s *)feng_array_data(%s))[%s], %s, &%s);\n",
                    take_source ? "feng_aggregate_take" : "feng_aggregate_assign",
                    elem_cty, recv.c_expr, idx_tmp, source_address, agg_desc);
            }
            free(source_address);
        } else {
            buf_append_fmt(cg->cur_body,
                "    ((%s *)feng_array_data(%s))[%s] = (%s)(%s);\n",
                elem_cty, recv.c_expr, idx_tmp, elem_cty, v.c_expr);
        }
        cg_assignment_owner_guard_end(cg, &recv, &owner_guard);
        free(elem_cty); free(idx_tmp);
        er_free(&v); er_free(&ix); er_free(&recv);
        return true;
    }
    if (target->kind == FENG_EXPR_MEMBER) {
        const FengDecl *imported_binding_decl =
            cg_resolve_imported_module_binding_decl(cg, target);

        if (imported_binding_decl != NULL) {
            return cg_emit_imported_binding_assign(cg,
                                                   imported_binding_decl,
                                                   stmt,
                                                   is_compound,
                                                   binary_op);
        }

        {
            const UserType *static_target = cg_find_user_type_by_expr_path(cg, target->as.member.object);
            const TypeStaticBinding *binding = static_target != NULL
                                                   ? cg_user_type_static_binding(static_target,
                                                                                 target->as.member.member.data,
                                                                                 target->as.member.member.length)
                                                   : NULL;

            if (binding != NULL) {
                if (!binding->is_var) {
                    return cg_fail(cg,
                                   stmt->token,
                                   "CE0244", "codegen: cannot assign to immutable static binding '%s.%s'",
                                   static_target->feng_name,
                                   binding->feng_name);
                }
                if (cg_static_binding_uses_shared_state(cg, static_target)) {
                    return cg_emit_shared_static_binding_assign(cg,
                                                                stmt,
                                                                static_target,
                                                                binding,
                                                                is_compound,
                                                                binary_op);
                }
                if (!cg_emit_type_static_binding_ensure_init_call(cg, binding)) {
                    return false;
                }
                if (is_compound) {
                    char *cty = cg_ctype_dup(binding->type);
                    char *old_tmp = NULL;
                    ExprResult v;
                    Buf expr;

                    if (cty == NULL || !cgtype_is_numeric(binding->type->kind)) {
                        free(cty);
                        return cg_fail(cg,
                                       stmt->token,
                                       "CE0245", "codegen: compound assignment requires a numeric static binding type");
                    }
                    old_tmp = cg_fresh_temp(cg, "_old");
                    if (old_tmp == NULL) {
                        free(cty);
                        return false;
                    }
                    buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, old_tmp, binding->c_name);
                    if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                        free(old_tmp);
                        free(cty);
                        return false;
                    }
                    buf_init(&expr);
                    if (!cg_append_numeric_op_expr(&expr,
                                                   binding->type->kind,
                                                   old_tmp,
                                                   binary_op,
                                                   v.c_expr)) {
                        buf_free(&expr);
                        er_free(&v);
                        free(old_tmp);
                        free(cty);
                        return cg_fail(cg,
                                       stmt->token,
                                       "CE0073", "codegen: unsupported compound assignment operator");
                    }
                    buf_append_fmt(cg->cur_body,
                                   "    %s = (%s)(%s);\n",
                                   binding->c_name,
                                   cty,
                                   expr.data);
                    buf_free(&expr);
                    er_free(&v);
                    free(old_tmp);
                    free(cty);
                    return true;
                }
                {
                    ExprResult v;

                    if (!cg_emit_expr_for_expected_type(cg,
                                                        stmt->as.assign.value,
                                                        binding->type,
                                                        &v)) {
                        return false;
                    }
                    if (cgtype_is_managed(binding->type)) {
                        if (v.owns_ref) {
                            buf_append_fmt(cg->cur_body,
                                           "    { void *_old = %s; %s = %s; feng_release(_old); }\n",
                                           binding->c_name,
                                           binding->c_name,
                                           v.c_expr);
                        } else {
                            buf_append_fmt(cg->cur_body,
                                           "    feng_assign((void **)&%s, %s);\n",
                                           binding->c_name,
                                           v.c_expr);
                        }
                    } else if (cgtype_is_aggregate(binding->type)) {
                        const char *agg_desc = cg_aggregate_desc_name(binding->type);

                        if (agg_desc == NULL) {
                            er_free(&v);
                            return cg_fail(cg,
                                           stmt->token,
                                           "CE0246", "codegen: missing aggregate descriptor for static binding write");
                        }
                        if (!cg_prepare_aggregate_assign_source(cg, &v, "_t")) {
                            er_free(&v);
                            return cg_fail(cg, stmt->token,
                                           "IE0001", "codegen: out of memory");
                        }
                        buf_append_fmt(cg->cur_body,
                                       "    feng_aggregate_assign(&%s, &%s, &%s);\n",
                                       binding->c_name,
                                       v.c_expr,
                                       agg_desc);
                    } else {
                        char *cty = cg_ctype_dup(binding->type);

                        if (cty == NULL) {
                            er_free(&v);
                            return false;
                        }
                        if (cgtype_is_by_value_struct(binding->type)) {
                            buf_append_fmt(cg->cur_body,
                                           "    %s = %s;\n",
                                           binding->c_name,
                                           v.c_expr);
                        } else {
                            buf_append_fmt(cg->cur_body,
                                           "    %s = (%s)(%s);\n",
                                           binding->c_name,
                                           cty,
                                           v.c_expr);
                        }
                        free(cty);
                    }
                    er_free(&v);
                    return true;
                }
            }
        }

        ExprResult recv;
        if (!cg_emit_expr(cg, target->as.member.object, &recv)) return false;
        if (cg->in_generic_type_method &&
            cg_type_is_current_generic_owner(cg, recv.type) &&
            cg->generic_type_method_decl != NULL &&
            cg->generic_type_method_decl->kind == FENG_DECL_TYPE) {
            const FengDecl *owner = cg->generic_type_method_decl;
            const FengTypeMember *field_member = NULL;
            size_t field_index = 0;
            for (size_t i = 0; i < owner->as.type_decl.member_count; ++i) {
                const FengTypeMember *member = owner->as.type_decl.members[i];
                if (member->kind != FENG_TYPE_MEMBER_FIELD) continue;
                if (member->as.field.name.length == target->as.member.member.length &&
                    memcmp(member->as.field.name.data,
                           target->as.member.member.data,
                           target->as.member.member.length) == 0) {
                    field_member = member;
                    break;
                }
                field_index++;
            }
            if (field_member == NULL) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0171", "codegen: generic type '%.*s' has no field '%.*s'",
                    (int)owner->as.type_decl.name.length,
                    owner->as.type_decl.name.data,
                    (int)target->as.member.member.length,
                    target->as.member.member.data);
            }
            CGType *field_type = NULL;
            if (!cg_resolve_user_field_type(cg,
                                            recv.type->user,
                                            field_member,
                                            &field_type)) {
                er_free(&recv);
                return false;
            }
            if (field_type->kind == CG_TYPE_GENERIC_PARAM) {
                if (is_compound) {
                    cgtype_free(field_type);
                    er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0247", "codegen: compound assignment to generic field requires a concrete numeric field type");
                }
                ExprResult v;
                if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                    cgtype_free(field_type); er_free(&recv); return false;
                }
                if (v.type->kind != CG_TYPE_GENERIC_PARAM ||
                    v.type->generic_param_index != field_type->generic_param_index) {
                    er_free(&v); cgtype_free(field_type); er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0248", "codegen: generic field assignment requires a value with the same generic type parameter");
                }
                const char *desc = cg->generic_fn_type_param_descs[field_type->generic_param_index];
                char *dst_tmp = cg_fresh_temp(cg, "_gdst");
                char *src_tmp = cg_fresh_temp(cg, "_gsrc");
                if (!dst_tmp || !src_tmp) {
                    free(dst_tmp); free(src_tmp);
                    er_free(&v); cgtype_free(field_type); er_free(&recv);
                    return false;
                }
                buf_append_fmt(cg->cur_body,
                    "    void *%s = ((char *)%s + %s[%zu]);\n"
                    "    const void *%s = %s;\n"
                    "    switch (%s->kind) {\n"
                    "        case FENG_VALUE_TRIVIAL:\n"
                    "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
                    "            break;\n"
                    "        case FENG_VALUE_MANAGED_POINTER: {\n"
                    "            void *_new_value = *(void *const *)%s;\n"
                    "            feng_retain(_new_value);\n"
                    "            void *_old_value = *(void **)%s;\n"
                    "            *(void **)%s = _new_value;\n"
                    "            feng_release(_old_value);\n"
                    "            break;\n"
                    "        }\n"
                    "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                    "            feng_aggregate_assign(%s, %s, feng_generic_aggregate_descriptor(%s));\n"
                    "            break;\n"
                    "    }\n",
                    dst_tmp, recv.c_expr,
                    cg->generic_type_method_field_offsets_name, field_index,
                    src_tmp, v.c_expr,
                    desc,
                    dst_tmp, src_tmp, desc,
                    src_tmp,
                    dst_tmp,
                    dst_tmp,
                    dst_tmp, src_tmp, desc);
                free(dst_tmp); free(src_tmp);
                er_free(&v); cgtype_free(field_type); er_free(&recv);
                return true;
            }
            char *field_addr = cg_fresh_temp(cg, "_gfield");
            char *field_cty = cg_ctype_dup(field_type);
            if (!field_addr || !field_cty) {
                free(field_addr); free(field_cty);
                cgtype_free(field_type); er_free(&recv);
                return false;
            }
            buf_append_fmt(cg->cur_body,
                "    char *%s = ((char *)%s + %s[%zu]);\n",
                field_addr, recv.c_expr,
                cg->generic_type_method_field_offsets_name, field_index);
            if (is_compound) {
                if (!cgtype_is_numeric(field_type->kind)) {
                    free(field_addr); free(field_cty);
                    cgtype_free(field_type); er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0249", "codegen: compound member assignment requires a numeric field type");
                }
                char *old_tmp = cg_fresh_temp(cg, "_old");
                if (!old_tmp) {
                    free(field_addr); free(field_cty);
                    cgtype_free(field_type); er_free(&recv);
                    return false;
                }
                buf_append_fmt(cg->cur_body,
                    "    %s %s = *(%s *)%s;\n",
                    field_cty, old_tmp, field_cty, field_addr);
                ExprResult v;
                if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                    free(old_tmp); free(field_addr); free(field_cty);
                    cgtype_free(field_type); er_free(&recv);
                    return false;
                }
                Buf expr; buf_init(&expr);
                if (!cg_append_numeric_op_expr(&expr, field_type->kind,
                                               old_tmp, binary_op, v.c_expr)) {
                    buf_free(&expr); er_free(&v);
                    free(old_tmp); free(field_addr); free(field_cty);
                    cgtype_free(field_type); er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0250", "codegen: unsupported compound member assignment operator");
                }
                buf_append_fmt(cg->cur_body,
                    "    *(%s *)%s = (%s)(%s);\n",
                    field_cty, field_addr, field_cty, expr.data);
                buf_free(&expr); er_free(&v);
                free(old_tmp); free(field_addr); free(field_cty);
                cgtype_free(field_type); er_free(&recv);
                return true;
            }
            ExprResult v;
            if (!cg_emit_expr_for_expected_type(cg,
                                                stmt->as.assign.value,
                                                field_type,
                                                &v)) {
                free(field_addr); free(field_cty);
                cgtype_free(field_type); er_free(&recv);
                return false;
            }
            if (cgtype_is_managed(field_type)) {
                if (v.owns_ref) {
                    buf_append_fmt(cg->cur_body,
                        "    { void *_old = *(void **)%s; *(void **)%s = %s; feng_release(_old); }\n",
                        field_addr, field_addr, v.c_expr);
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    feng_assign((void **)%s, %s);\n",
                        field_addr, v.c_expr);
                }
            } else if (cgtype_is_aggregate(field_type)) {
                char *descriptor = cg_aggregate_descriptor_expr_dup(
                    cg, field_type, stmt->token);
                if (descriptor == NULL) {
                    er_free(&v); free(field_addr); free(field_cty);
                    cgtype_free(field_type); er_free(&recv);
                    return false;
                }
                if (!cg_prepare_aggregate_assign_source(cg, &v, "_t")) {
                    free(descriptor);
                    er_free(&v); free(field_addr); free(field_cty);
                    cgtype_free(field_type); er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "IE0001", "codegen: out of memory");
                }
                char *source_address = cg_aggregate_result_address_dup(&v);
                if (source_address == NULL) {
                    free(descriptor);
                    er_free(&v); free(field_addr); free(field_cty);
                    cgtype_free(field_type); er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0251", "codegen: aggregate field source has no address");
                }
                buf_append_fmt(cg->cur_body,
                    "    feng_aggregate_assign(%s, %s, %s);\n",
                    field_addr, source_address, descriptor);
                free(source_address);
                free(descriptor);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    *(%s *)%s = (%s)(%s);\n",
                    field_cty, field_addr, field_cty, v.c_expr);
            }
            er_free(&v);
            free(field_addr); free(field_cty);
            cgtype_free(field_type); er_free(&recv);
            return true;
        }
        if (recv.type->kind == CG_TYPE_GENERIC_PARAM) {
            size_t gp_idx = recv.type->generic_param_index;
            const UserSpec *us = cg_generic_param_constraint_spec(cg, gp_idx);
            const char *desc_name = cg_generic_param_desc_name(cg, gp_idx);
            if (!us || !desc_name) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0252", "codegen: generic member assignment requires an object-form spec constraint");
            }
            const UserSpecMember *sm = cg_user_spec_field_member_for_access(
                cg, us, target, /*fallback_static=*/false);
            if (!sm || sm->kind != USM_KIND_FIELD) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0173", "codegen: spec '%s' has no field '%.*s'",
                    us->feng_name,
                    (int)target->as.member.member.length,
                    target->as.member.member.data);
            }
            if (!sm->is_var) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0253", "codegen: spec field '%s' is not declared `var`",
                    sm->feng_name);
            }
            char *subject_expr = NULL;
            if (!sm->is_static) {
                subject_expr = cg_generic_witness_subject_expr(desc_name, recv.c_expr);
                if (!subject_expr) {
                    er_free(&recv);
                    return false;
                }
            }
            if (is_compound) {
                char *field_cty = cg_ctype_dup(sm->type);
                char *old_tmp = NULL;
                ExprResult v;
                Buf expr;

                if (!field_cty || !cgtype_is_numeric(sm->type->kind)) {
                    free(field_cty);
                    free(subject_expr);
                    er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0254", "codegen: compound spec field assignment requires a numeric field type");
                }

                old_tmp = cg_fresh_temp(cg, "_old");
                if (!old_tmp) {
                    free(field_cty);
                    free(subject_expr);
                    er_free(&recv);
                    return false;
                }

                if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                    if (sm->is_static) {
                        buf_append_fmt(cg->cur_body,
                            "    %s %s;\n"
                            "    ((const struct %s *)%s->witness)->get_%s(&%s);\n",
                            field_cty, old_tmp, us->c_witness_struct_name,
                            desc_name, sm->c_field_name, old_tmp);
                    } else {
                        buf_append_fmt(cg->cur_body,
                            "    %s %s = *(const %s *)((const struct %s *)%s->witness)->borrow_%s(%s);\n",
                            field_cty, old_tmp, field_cty,
                            us->c_witness_struct_name, desc_name,
                            sm->c_field_name, subject_expr);
                    }
                } else if (sm->is_static) {
                    buf_append_fmt(cg->cur_body,
                        "    %s %s = ((const struct %s *)%s->witness)->get_%s();\n",
                        field_cty, old_tmp, us->c_witness_struct_name,
                        desc_name, sm->c_field_name);
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    %s %s = ((const struct %s *)%s->witness)->get_%s(%s);\n",
                        field_cty, old_tmp, us->c_witness_struct_name,
                        desc_name, sm->c_field_name, subject_expr);
                }

                if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                    free(old_tmp);
                    free(field_cty);
                    free(subject_expr);
                    er_free(&recv);
                    return false;
                }

                buf_init(&expr);
                if (!cg_append_numeric_op_expr(&expr,
                                               sm->type->kind,
                                               old_tmp,
                                               binary_op,
                                               v.c_expr)) {
                    buf_free(&expr);
                    er_free(&v);
                    free(old_tmp);
                    free(field_cty);
                    free(subject_expr);
                    er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0255", "codegen: unsupported compound spec field assignment operator");
                }

                if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                    char *new_tmp = cg_fresh_temp(cg, "_new");

                    if (new_tmp == NULL) {
                        buf_free(&expr);
                        er_free(&v);
                        free(old_tmp);
                        free(field_cty);
                        free(subject_expr);
                        er_free(&recv);
                        return cg_fail(cg, stmt->token,
                                       "IE0001", "codegen: out of memory");
                    }
                    buf_append_fmt(cg->cur_body,
                                   "    %s %s = (%s)(%s);\n",
                                   field_cty, new_tmp, field_cty, expr.data);
                    if (sm->is_static) {
                        buf_append_fmt(cg->cur_body,
                            "    ((const struct %s *)%s->witness)->set_%s(&%s);\n",
                            us->c_witness_struct_name, desc_name,
                            sm->c_field_name, new_tmp);
                    } else {
                        buf_append_fmt(cg->cur_body,
                            "    ((const struct %s *)%s->witness)->set_%s(%s, &%s);\n",
                            us->c_witness_struct_name, desc_name,
                            sm->c_field_name, subject_expr, new_tmp);
                    }
                    free(new_tmp);
                } else if (sm->is_static) {
                    buf_append_fmt(cg->cur_body,
                        "    ((const struct %s *)%s->witness)->set_%s((%s)(%s));\n",
                        us->c_witness_struct_name, desc_name,
                        sm->c_field_name, field_cty, expr.data);
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    ((const struct %s *)%s->witness)->set_%s(%s, (%s)(%s));\n",
                        us->c_witness_struct_name, desc_name,
                        sm->c_field_name, subject_expr, field_cty, expr.data);
                }

                buf_free(&expr);
                er_free(&v);
                free(old_tmp);
                free(field_cty);
                free(subject_expr);
                er_free(&recv);
                return true;
            }
            ExprResult v;
            if (!cg_emit_expr_for_expected_type(cg,
                                                stmt->as.assign.value,
                                                sm->type,
                                                &v)) {
                free(subject_expr);
                er_free(&recv);
                return false;
            }
            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                char *argument_expr = cg_shared_callable_argument_expr_dup(
                    cg, &v, true, "_spec_field_arg");

                if (argument_expr == NULL) {
                    er_free(&v);
                    free(subject_expr);
                    er_free(&recv);
                    return false;
                }
                if (sm->is_static) {
                    buf_append_fmt(cg->cur_body,
                        "    ((const struct %s *)%s->witness)->set_%s(%s);\n",
                        us->c_witness_struct_name, desc_name,
                        sm->c_field_name, argument_expr);
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    ((const struct %s *)%s->witness)->set_%s(%s, %s);\n",
                        us->c_witness_struct_name, desc_name,
                        sm->c_field_name, subject_expr, argument_expr);
                }
                free(argument_expr);
                er_free(&v);
                free(subject_expr);
                er_free(&recv);
                return true;
            }
            if (cgtype_is_managed(sm->type) && v.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { ");
                cg_emit_c_type(cg->cur_body, sm->type);
                if (sm->is_static) {
                    buf_append_fmt(cg->cur_body,
                        " _v = %s; ((const struct %s *)%s->witness)->set_%s(_v); feng_release(_v); }\n",
                        v.c_expr, us->c_witness_struct_name, desc_name,
                        sm->c_field_name);
                } else {
                    buf_append_fmt(cg->cur_body,
                        " _v = %s; ((const struct %s *)%s->witness)->set_%s(%s, _v); feng_release(_v); }\n",
                        v.c_expr, us->c_witness_struct_name, desc_name,
                        sm->c_field_name, subject_expr);
                }
            } else {
                if (sm->is_static) {
                    buf_append_fmt(cg->cur_body,
                        "    ((const struct %s *)%s->witness)->set_%s(%s);\n",
                        us->c_witness_struct_name, desc_name,
                        sm->c_field_name, v.c_expr);
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    ((const struct %s *)%s->witness)->set_%s(%s, %s);\n",
                        us->c_witness_struct_name, desc_name,
                        sm->c_field_name, subject_expr, v.c_expr);
                }
            }
            er_free(&v);
            free(subject_expr);
            er_free(&recv);
            return true;
        }
        if (recv.type->kind == CG_TYPE_SPEC && recv.type->user_spec) {
            /* Step 4b-β — spec field write via witness setter. */
            const UserSpec *us = recv.type->user_spec;
            const UserSpecMember *sm = cg_user_spec_field_member_for_access(
                cg, us, target, /*fallback_static=*/false);
            if (!sm || sm->kind != USM_KIND_FIELD) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0173", "codegen: spec '%s' has no field '%.*s'",
                    us->feng_name,
                    (int)target->as.member.member.length,
                    target->as.member.member.data);
            }
            if (!sm->is_var) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0253", "codegen: spec field '%s' is not declared `var`",
                    sm->feng_name);
            }
            cg_materialize_to_local(cg, &recv, "_t");
            if (is_compound) {
                char *field_cty = cg_ctype_dup(sm->type);
                char *old_tmp = NULL;
                ExprResult v;
                Buf expr;

                if (!field_cty || !cgtype_is_numeric(sm->type->kind)) {
                    free(field_cty);
                    er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0254", "codegen: compound spec field assignment requires a numeric field type");
                }

                old_tmp = cg_fresh_temp(cg, "_old");
                if (!old_tmp) {
                    free(field_cty);
                    er_free(&recv);
                    return false;
                }

                if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                    buf_append_fmt(cg->cur_body,
                        "    %s %s = *(const %s *)%s.witness->borrow_%s(%s.subject);\n",
                        field_cty, old_tmp, field_cty,
                        recv.c_expr, sm->c_field_name, recv.c_expr);
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    %s %s = %s.witness->get_%s(%s.subject);\n",
                        field_cty, old_tmp, recv.c_expr,
                        sm->c_field_name, recv.c_expr);
                }

                if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                    free(old_tmp);
                    free(field_cty);
                    er_free(&recv);
                    return false;
                }

                buf_init(&expr);
                if (!cg_append_numeric_op_expr(&expr,
                                               sm->type->kind,
                                               old_tmp,
                                               binary_op,
                                               v.c_expr)) {
                    buf_free(&expr);
                    er_free(&v);
                    free(old_tmp);
                    free(field_cty);
                    er_free(&recv);
                    return cg_fail(cg, stmt->token,
                        "CE0255", "codegen: unsupported compound spec field assignment operator");
                }

                if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                    char *new_tmp = cg_fresh_temp(cg, "_new");

                    if (new_tmp == NULL) {
                        buf_free(&expr);
                        er_free(&v);
                        free(old_tmp);
                        free(field_cty);
                        er_free(&recv);
                        return cg_fail(cg, stmt->token,
                                       "IE0001", "codegen: out of memory");
                    }
                    buf_append_fmt(cg->cur_body,
                                   "    %s %s = (%s)(%s);\n"
                                   "    %s.witness->set_%s(%s.subject, &%s);\n",
                                   field_cty, new_tmp, field_cty, expr.data,
                                   recv.c_expr, sm->c_field_name,
                                   recv.c_expr, new_tmp);
                    free(new_tmp);
                } else {
                    buf_append_fmt(cg->cur_body,
                        "    %s.witness->set_%s(%s.subject, (%s)(%s));\n",
                        recv.c_expr, sm->c_field_name,
                        recv.c_expr, field_cty, expr.data);
                }

                buf_free(&expr);
                er_free(&v);
                free(old_tmp);
                free(field_cty);
                er_free(&recv);
                return true;
            }
            ExprResult v;
            if (!cg_emit_expr_for_expected_type(cg,
                                                stmt->as.assign.value,
                                                sm->type,
                                                &v)) {
                er_free(&recv); return false;
            }
            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                char *argument_expr = cg_shared_callable_argument_expr_dup(
                    cg, &v, true, "_spec_field_arg");

                if (argument_expr == NULL) {
                    er_free(&v);
                    er_free(&recv);
                    return false;
                }
                buf_append_fmt(cg->cur_body,
                    "    %s.witness->set_%s(%s.subject, %s);\n",
                    recv.c_expr, sm->c_field_name,
                    recv.c_expr, argument_expr);
                free(argument_expr);
                er_free(&v);
                er_free(&recv);
                return true;
            }
            /* Setter takes ownership semantics inside the thunk (managed →
             * feng_assign). For an owns_ref RHS we must pass it as +1 and
             * the setter's feng_assign will retain+release; therefore we
             * release the +1 ourselves after the call to balance to a net
             * +0 store. For a borrow RHS we just pass through. */
            if (cgtype_is_managed(sm->type) && v.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { ");
                cg_emit_c_type(cg->cur_body, sm->type);
                buf_append_fmt(cg->cur_body,
                    " _v = %s; %s.witness->set_%s(%s.subject, _v); feng_release(_v); }\n",
                    v.c_expr, recv.c_expr, sm->c_field_name, recv.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    %s.witness->set_%s(%s.subject, %s);\n",
                    recv.c_expr, sm->c_field_name, recv.c_expr, v.c_expr);
            }
            er_free(&v);
            er_free(&recv);
            return true;
        }
        if (recv.type->kind != CG_TYPE_OBJECT || !recv.type->user) {
            er_free(&recv);
            return cg_fail(cg, stmt->token,
                "CE0256", "codegen: member assignment on non-object value");
        }
        const UserType *ut = recv.type->user;
        const UserField *uf = cg_user_type_field(ut,
            target->as.member.member.data, target->as.member.member.length);
        if (!uf) {
            er_free(&recv);
            return cg_fail(cg, stmt->token,
                "CE0176", "codegen: type '%s' has no field '%.*s'",
                ut->feng_name,
                (int)target->as.member.member.length,
                target->as.member.member.data);
        }
        /* @value types use `.` (value), regular objects use `->` (pointer). */
        const char *acc = cg_type_is_value_user(recv.type) ? "." : "->";
        CGAssignmentOwnerGuard owner_guard = {0};
        if (cgtype_is_managed(recv.type) && recv.owns_ref) {
            if (cg_materialize_to_local(cg, &recv, "_t") == NULL) {
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                               "IE0001", "codegen: out of memory");
            }
        }
        if (!cg_assignment_owner_guard_begin(
                cg,
                &recv,
                cg_assignment_expr_cannot_mutate_state(
                    cg, stmt->as.assign.value) &&
                    cg_assignment_writeback_cannot_invalidate_receiver(
                        uf->type),
                stmt->token,
                &owner_guard)) {
            er_free(&recv);
            return false;
        }
        if (recv.uses_reified_storage ||
            cg_reference_needs_reified_field_layout(cg, recv.type)) {
            bool assigned = cg_emit_reified_user_field_assign(cg,
                                                              stmt,
                                                              &recv,
                                                              uf,
                                                              is_compound,
                                                              binary_op);
            if (assigned) {
                cg_assignment_owner_guard_end(cg, &recv, &owner_guard);
            }
            er_free(&recv);
            return assigned;
        }
        if (is_compound) {
            char *field_cty = cg_ctype_dup(uf->type);
            char *old_tmp = NULL;
            ExprResult v;
            Buf expr;

            if (!field_cty || !cgtype_is_numeric(uf->type->kind)) {
                free(field_cty);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0249", "codegen: compound member assignment requires a numeric field type");
            }

            old_tmp = cg_fresh_temp(cg, "_old");
            if (!old_tmp) {
                free(field_cty);
                er_free(&recv);
                return false;
            }

            buf_append_fmt(cg->cur_body,
                "    %s %s = (%s)%s%s;\n",
                field_cty, old_tmp, recv.c_expr, acc, uf->c_name);

            if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                free(old_tmp);
                free(field_cty);
                er_free(&recv);
                return false;
            }

            buf_init(&expr);
            if (!cg_append_numeric_op_expr(&expr,
                                           uf->type->kind,
                                           old_tmp,
                                           binary_op,
                                           v.c_expr)) {
                buf_free(&expr);
                er_free(&v);
                free(old_tmp);
                free(field_cty);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                    "CE0250", "codegen: unsupported compound member assignment operator");
            }

            buf_append_fmt(cg->cur_body,
                "    (%s)%s%s = (%s)(%s);\n",
                recv.c_expr, acc, uf->c_name, field_cty, expr.data);

            cg_assignment_owner_guard_end(cg, &recv, &owner_guard);

            buf_free(&expr);
            er_free(&v);
            free(old_tmp);
            free(field_cty);
            er_free(&recv);
            return true;
        }
        ExprResult v;
        if (!cg_emit_expr_for_expected_type(cg,
                                            stmt->as.assign.value,
                                            uf->type,
                                            &v)) {
            er_free(&recv); return false;
        }
        if (uf->type->kind == CG_TYPE_GENERIC_PARAM) {
            const char *desc = cg_generic_param_desc_name(cg, uf->type->generic_param_index);
            char *dst_tmp = cg_fresh_temp(cg, "_gdst");
            char *src_tmp = cg_fresh_temp(cg, "_gsrc");

            if (desc == NULL || dst_tmp == NULL || src_tmp == NULL) {
                free(dst_tmp);
                free(src_tmp);
                er_free(&v);
                er_free(&recv);
                return cg_fail(cg,
                               stmt->token,
                               "CE0257", "codegen: generic member assignment requires a matching descriptor");
            }
            if (v.type == NULL || v.type->kind != CG_TYPE_GENERIC_PARAM ||
                v.type->generic_param_index != uf->type->generic_param_index) {
                free(dst_tmp);
                free(src_tmp);
                er_free(&v);
                er_free(&recv);
                return cg_fail(cg,
                               stmt->token,
                               "CE0257", "codegen: generic member assignment requires a value with the same generic type parameter");
            }
            buf_append_fmt(cg->cur_body,
                "    void *%s = (void *)&(%s)%s%s;\n"
                "    const void *%s = %s;\n"
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(%s, %s, feng_generic_value_size(%s));\n"
                "            break;\n"
                "        case FENG_VALUE_MANAGED_POINTER: {\n"
                "            void *_new_value = *(void *const *)%s;\n"
                "            feng_retain(_new_value);\n"
                "            void *_old_value = *(void **)%s;\n"
                "            *(void **)%s = _new_value;\n"
                "            feng_release(_old_value);\n"
                "            break;\n"
                "        }\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            feng_aggregate_assign(%s, %s, feng_generic_aggregate_descriptor(%s));\n"
                "            break;\n"
                "    }\n",
                dst_tmp,
                recv.c_expr, acc, uf->c_name,
                src_tmp, v.c_expr,
                desc,
                dst_tmp, src_tmp, desc,
                src_tmp,
                dst_tmp,
                dst_tmp,
                dst_tmp, src_tmp, desc);
            free(dst_tmp);
            free(src_tmp);
        } else if (cgtype_is_managed(uf->type)) {
            if (v.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { void *_old = (%s)%s%s; (%s)%s%s = %s; feng_release(_old); }\n",
                    recv.c_expr, acc, uf->c_name, recv.c_expr, acc, uf->c_name, v.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_assign((void**)&(%s)%s%s, %s);\n",
                    recv.c_expr, acc, uf->c_name, v.c_expr);
            }
        } else if (cgtype_is_aggregate(uf->type)) {
            const char *desc = cg_aggregate_desc_name(uf->type);
            char *source_address;
            bool take_source;
            if (desc == NULL) {
                er_free(&v);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                               "CE0257", "codegen: missing aggregate descriptor for member assignment");
            }
            if (!cg_prepare_aggregate_store_source(
                    cg, &v, "_t", &take_source)) {
                er_free(&v);
                er_free(&recv);
                return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
            }
            source_address = cg_aggregate_result_address_dup(&v);
            if (source_address == NULL) {
                er_free(&v);
                er_free(&recv);
                return cg_fail(cg, stmt->token,
                               "CE0257", "codegen: aggregate member source has no address");
            }
            buf_append_fmt(cg->cur_body,
                "    %s(&(%s)%s%s, %s, &%s);\n",
                take_source ? "feng_aggregate_take" : "feng_aggregate_assign",
                recv.c_expr, acc, uf->c_name, source_address, desc);
            free(source_address);
        } else {
            char *cty = cg_ctype_dup(uf->type);
            if (cgtype_is_by_value_struct(uf->type)) {
                buf_append_fmt(cg->cur_body, "    (%s)%s%s = %s;\n",
                               recv.c_expr, acc, uf->c_name, v.c_expr);
            } else {
                buf_append_fmt(cg->cur_body, "    (%s)%s%s = (%s)(%s);\n",
                               recv.c_expr, acc, uf->c_name, cty, v.c_expr);
            }
            free(cty);
        }
        cg_assignment_owner_guard_end(cg, &recv, &owner_guard);
        er_free(&v);
        er_free(&recv);
        return true;
    }
    if (target->kind != FENG_EXPR_IDENTIFIER) {
        return cg_fail(cg, stmt->token,
            "CE0258", "codegen: only identifier or member assignments supported in this iteration");
    }
    const FengSlice n = target->as.identifier;
    const Local *l = scope_lookup(cg->cur_scope, n.data, n.length);
    if (!l) {
        const ModuleBinding *mb = cg_find_module_binding(cg, n.data, n.length);
        if (!mb) {
            const FengDecl *imported_binding_decl =
                cg_resolve_imported_module_binding_decl(cg, target);

            if (imported_binding_decl != NULL) {
                return cg_emit_imported_binding_assign(cg,
                                                       imported_binding_decl,
                                                       stmt,
                                                       is_compound,
                                                       binary_op);
            }
            return cg_fail(cg, stmt->token,
                "CE0259", "codegen: assignment to undefined identifier '%.*s'",
                (int)n.length, n.data);
        }
        if (!mb->is_var) {
            return cg_fail(cg, stmt->token,
                "CE0260", "codegen: cannot assign to immutable module binding '%s'",
                mb->feng_name);
        }
        cg_emit_module_binding_ensure_init_call(cg, mb);
        if (is_compound) {
            char *cty = cg_ctype_dup(mb->type);
            char *old_tmp = NULL;
            ExprResult v;
            Buf expr;

            if (!cty || !cgtype_is_numeric(mb->type->kind)) {
                free(cty);
                return cg_fail(cg, stmt->token,
                    "CE0072", "codegen: compound assignment requires a numeric binding type");
            }

            old_tmp = cg_fresh_temp(cg, "_old");
            if (!old_tmp) {
                free(cty);
                return false;
            }

            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, old_tmp, mb->c_name);
            if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
                free(old_tmp);
                free(cty);
                return false;
            }

            buf_init(&expr);
            if (!cg_append_numeric_op_expr(&expr,
                                           mb->type->kind,
                                           old_tmp,
                                           binary_op,
                                           v.c_expr)) {
                buf_free(&expr);
                er_free(&v);
                free(old_tmp);
                free(cty);
                return cg_fail(cg, stmt->token,
                    "CE0073", "codegen: unsupported compound assignment operator");
            }

            buf_append_fmt(cg->cur_body, "    %s = (%s)(%s);\n",
                           mb->c_name, cty, expr.data);

            buf_free(&expr);
            er_free(&v);
            free(old_tmp);
            free(cty);
            return true;
        }
        ExprResult v;
        if (!cg_emit_expr_for_expected_type(cg,
                            stmt->as.assign.value,
                            mb->type,
                            &v)) return false;
        if (cgtype_is_managed(mb->type)) {
            if (v.owns_ref) {
                buf_append_fmt(cg->cur_body,
                    "    { void *_old = %s; %s = %s; feng_release(_old); }\n",
                    mb->c_name, mb->c_name, v.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    feng_assign((void**)&%s, %s);\n", mb->c_name, v.c_expr);
            }
        } else if (cgtype_is_aggregate(mb->type)) {
            const char *desc = cg_aggregate_desc_name(mb->type);
            if (desc == NULL) {
                er_free(&v);
                return cg_fail(cg, stmt->token,
                               "CE0261", "codegen: missing aggregate descriptor for module assignment");
            }
            if (!cg_prepare_aggregate_assign_source(cg, &v, "_t")) {
                er_free(&v);
                return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
            }
            buf_append_fmt(cg->cur_body,
                "    feng_aggregate_assign(&%s, &%s, &%s);\n",
                mb->c_name, v.c_expr, desc);
        } else {
            char *cty = cg_ctype_dup(mb->type);
            if (cgtype_is_by_value_struct(mb->type)) {
                buf_append_fmt(cg->cur_body, "    %s = %s;\n",
                               mb->c_name, v.c_expr);
            } else {
                buf_append_fmt(cg->cur_body, "    %s = (%s)(%s);\n",
                               mb->c_name, cty, v.c_expr);
            }
            free(cty);
        }
        er_free(&v);
        return true;
    }
    if (is_compound) {
        char *cty = cg_ctype_dup(l->type);
        char *old_tmp = NULL;
        ExprResult v;
        Buf expr;

        if (!cty || !cgtype_is_numeric(l->type->kind)) {
            free(cty);
            return cg_fail(cg, stmt->token,
                "CE0262", "codegen: compound assignment requires a numeric local type");
        }

        old_tmp = cg_fresh_temp(cg, "_old");
        if (!old_tmp) {
            free(cty);
            return false;
        }

        buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, old_tmp, l->c_name);
        if (!cg_emit_expr(cg, stmt->as.assign.value, &v)) {
            free(old_tmp);
            free(cty);
            return false;
        }

        buf_init(&expr);
        if (!cg_append_numeric_op_expr(&expr,
                                       l->type->kind,
                                       old_tmp,
                                       binary_op,
                                       v.c_expr)) {
            buf_free(&expr);
            er_free(&v);
            free(old_tmp);
            free(cty);
            return cg_fail(cg, stmt->token,
                "CE0073", "codegen: unsupported compound assignment operator");
        }

        buf_append_fmt(cg->cur_body, "    %s = (%s)(%s);\n",
                       l->c_name, cty, expr.data);

        buf_free(&expr);
        er_free(&v);
        free(old_tmp);
        free(cty);
        return true;
    }
    ExprResult v;
    if (!cg_emit_expr_for_expected_type(cg,
                                        stmt->as.assign.value,
                                        l->type,
                                        &v)) return false;
    if (l->uses_erased_generic_storage) {
        if (!v.is_storage_address &&
            cg_materialize_to_local(cg, &v, "_assign_generic_source") == NULL) {
            er_free(&v);
            return cg_fail(cg, stmt->token,
                           "CE0263", "codegen: generic local assignment source has no stable storage");
        }
        buf_append_fmt(cg->cur_body,
            "    switch (%s->kind) {\n"
            "        case FENG_VALUE_TRIVIAL:\n"
            "            memcpy(%s, %s, %s);\n"
            "            break;\n"
            "        case FENG_VALUE_MANAGED_POINTER:\n",
            l->erased_generic_descriptor_c_name,
            l->c_name,
            v.c_expr,
            l->erased_generic_size_c_name);
        if (v.owns_ref) {
            buf_append_fmt(cg->cur_body,
                "            feng_release(*(void **)%s);\n"
                "            *(void **)%s = *(void **)%s;\n"
                "            *(void **)%s = NULL;\n",
                l->c_name,
                l->c_name,
                v.c_expr,
                v.c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "            feng_assign((void **)%s, *(void *const *)%s);\n",
                l->c_name,
                v.c_expr);
        }
        buf_append_cstr(cg->cur_body,
            "            break;\n"
            "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n");
        if (v.owns_ref) {
            buf_append_fmt(cg->cur_body,
                "            feng_aggregate_release(%s, "
                "feng_generic_aggregate_descriptor(%s));\n"
                "            memcpy(%s, %s, %s);\n"
                "            memset(%s, 0, %s);\n",
                l->c_name,
                l->erased_generic_descriptor_c_name,
                l->c_name,
                v.c_expr,
                l->erased_generic_size_c_name,
                v.c_expr,
                l->erased_generic_size_c_name);
        } else {
            buf_append_fmt(cg->cur_body,
                "            feng_aggregate_assign(%s, %s, "
                "feng_generic_aggregate_descriptor(%s));\n",
                l->c_name,
                v.c_expr,
                l->erased_generic_descriptor_c_name);
        }
        buf_append_cstr(cg->cur_body,
            "            break;\n"
            "    }\n");
    } else if (cgtype_is_managed(l->type)) {
        if (v.owns_ref) {
            /* Release old, take +1. */
            buf_append_fmt(cg->cur_body,
                "    { void *_old = %s; %s = %s; feng_release(_old); }\n",
                l->c_name, l->c_name, v.c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "    feng_assign((void**)&%s, %s);\n", l->c_name, v.c_expr);
        }
    } else if (cgtype_is_aggregate(l->type)) {
        const char *desc = cg_aggregate_desc_name(l->type);
        bool take_source;
        if (desc == NULL) {
            er_free(&v);
            return cg_fail(cg, stmt->token,
                           "CE0263", "codegen: missing aggregate descriptor for local assignment");
        }
        if (l->uses_reified_storage && v.owns_ref &&
            v.uses_reified_storage) {
            buf_append_fmt(cg->cur_body,
                           "    feng_aggregate_take(%s, %s, %s);\n",
                           l->c_name,
                           v.c_expr,
                           l->reified_descriptor_c_name);
            er_free(&v);
            return true;
        }
        if (!cg_prepare_aggregate_store_source(
                cg, &v, "_t", &take_source)) {
            er_free(&v);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        {
            char *source_address = cg_aggregate_result_address_dup(&v);
            if (source_address == NULL) {
                er_free(&v);
                return cg_fail(cg, stmt->token,
                               "CE0263", "codegen: aggregate local source has no address");
            }
            if (l->uses_reified_storage) {
                buf_append_fmt(cg->cur_body,
                               "    %s(%s, %s, %s);\n",
                               take_source
                                   ? "feng_aggregate_take"
                                   : "feng_aggregate_assign",
                               l->c_name,
                               source_address,
                               l->reified_descriptor_c_name);
            } else {
                buf_append_fmt(cg->cur_body,
                               "    %s(&%s, %s, &%s);\n",
                               take_source
                                   ? "feng_aggregate_take"
                                   : "feng_aggregate_assign",
                               l->c_name,
                               source_address,
                               desc);
            }
            free(source_address);
        }
    } else {
        char *cty = cg_ctype_dup(l->type);
        if (cgtype_is_by_value_struct(l->type)) {
            buf_append_fmt(cg->cur_body, "    %s = %s;\n",
                           l->c_name, v.c_expr);
        } else {
            buf_append_fmt(cg->cur_body, "    %s = (%s)(%s);\n",
                           l->c_name, cty, v.c_expr);
        }
        free(cty);
    }
    er_free(&v);
    return true;
}

static bool cg_emit_return(CG *cg, const FengStmt *stmt) {
    if (cg->callable_return_uses_out) {
        ExprResult result;

        if (cg->cur_return_type == NULL ||
            cg->cur_return_type->kind == CG_TYPE_VOID ||
            stmt->as.return_value == NULL) {
            return cg_fail(cg, stmt->token,
                           "CE0265", "codegen: callable out return requires a value");
        }
        if (!cg_emit_expr_for_expected_type(cg,
                                            stmt->as.return_value,
                                            cg->cur_return_type,
                                            &result)) {
            return false;
        }
        return cg_emit_callable_out_return_expr_result(cg,
                                                       stmt->token,
                                                       &result);
    }
    /* G6: inside a generic function, all returns use the _out out-parameter. */
    if (cg->in_generic_fn && cg->generic_return_uses_out) {
        return cg_emit_generic_return(cg, stmt);
    }
    if (!cg->cur_return_type ||
        cg->cur_return_type->kind == CG_TYPE_VOID) {
        if (stmt->as.return_value != NULL &&
            stmt->is_mixin_wrapper_forward_return) {
            FengStmt expr_stmt = *stmt;

            expr_stmt.kind = FENG_STMT_EXPR;
            expr_stmt.as.expr = stmt->as.return_value;
            if (!cg_emit_expr_stmt(cg, &expr_stmt)) {
                return false;
            }
            cg_release_through(cg, NULL);
            cg_emit_return_control_cleanup(cg);
            buf_append_cstr(cg->cur_body, "    return;\n");
            return true;
        }
        if (stmt->as.return_value) {
            return cg_fail(cg, stmt->token,
                "CE0264", "codegen: void function cannot return a value");
        }
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        if (cg->cur_fn_is_main) {
            buf_append_cstr(cg->cur_body, "    return;\n");
        } else {
            buf_append_cstr(cg->cur_body, "    return;\n");
        }
        return true;
    }
    if (!stmt->as.return_value) {
        return cg_fail(cg, stmt->token,
            "CE0265", "codegen: non-void function must return a value");
    }
    ExprResult r;
    if (!cg_emit_expr_for_expected_type(cg,
                                        stmt->as.return_value,
                                        cg->cur_return_type,
                                        &r)) return false;
    /* Non-managed: emit cleanup then return. Managed: must transfer +1 out:
     * - if r.owns_ref, store in temp, release scopes, return temp.
     * - else (borrowed), retain, release scopes, return retained. */
    if (cgtype_is_managed(r.type)) {
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(r.type);
        if (!r.owns_ref) {
            buf_append_fmt(cg->cur_body, "    %s %s = %s; feng_retain(%s);\n",
                           cty, tmp, r.c_expr, tmp);
        } else {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, r.c_expr);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body, "    return %s;\n", tmp);
        free(tmp);
    } else if (cgtype_is_aggregate(r.type)) {
        /* Step 4b-γ-2 — fat spec value: transfer +1 on every managed slot
         * out of the function. Two source flavours:
         *   • borrowed (owns_ref=false): bump every managed slot via
         *     feng_aggregate_retain so the caller's _ret carries +1
         *     independent of the source's lifetime.
         *   • +1 rvalue (owns_ref=true, e.g. another spec-returning call,
         *     a coerced object, a default-init binding): hoist into a
         *     scope-tracked temp via cg_materialize_to_local (so its
         *     subject lifetime is anchored, including across panics) and
         *     then move the bytes through feng_aggregate_take. take()
         *     nulls the source's managed slots so the cleanup-chain
         *     release at scope exit is a well-defined no-op (per
         *     feng_aggregate.c §take), which is exactly the documented
         *     spec-return move semantics (docs/engineering/feng-spec-codegen-delivered
         *     §13.3.γ-2). _ret itself is null-initialised before take so
         *     take's "release dst slots first" precondition holds.
         */
        const char *desc = cg_aggregate_desc_name(r.type);
        if (!desc) {
            er_free(&r);
            return cg_fail(cg, stmt->token,
                "CE0075", "codegen: missing aggregate descriptor for spec return");
        }
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(r.type);
        if (!r.owns_ref) {
            buf_append_fmt(cg->cur_body,
                "    %s %s = %s; feng_aggregate_retain(&%s, &%s);\n",
                cty, tmp, r.c_expr, tmp, desc);
        } else {
            cg_materialize_to_local(cg, &r, "_t");
            buf_append_fmt(cg->cur_body,
                "    %s %s; memset(&%s, 0, sizeof %s);"
                " feng_aggregate_take(&%s, &%s, &%s);\n",
                cty, tmp, tmp, tmp, tmp, r.c_expr, desc);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body, "    return %s;\n", tmp);
        free(tmp);
    } else {
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(r.type);
        if (cgtype_is_by_value_struct(r.type)) {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n",
                           cty, tmp, r.c_expr);
        } else {
            buf_append_fmt(cg->cur_body, "    %s %s = (%s)(%s);\n",
                           cty, tmp, cty, r.c_expr);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body, "    return %s;\n", tmp);
        free(tmp);
    }
    er_free(&r);
    return true;
}

static bool cg_emit_if(CG *cg, const FengStmt *stmt) {
    /*
     * In C, nothing may appear between `}` and `else`.  When the condition of
     * an `else if` clause requires preamble code (function calls producing
     * temporaries, cleanup pushes, etc.), we rewrite:
     *
     *   } else if (<complex>) { body }
     *
     * into:
     *
     *   } else {                        // wrapper block
     *       <preamble>                  // temporaries live in wrapper_scope
     *       if (<result>) { body }
     *       ...remaining else-if/else...
     *       <cleanup preamble temps>    // wrapper_scope released
     *   }
     *
     * Wrapper scopes nest: each one wraps all remaining clauses and the
     * optional else block, so they are closed in reverse order at the end.
     */
    #define MAX_IF_WRAPPER_SCOPES 64
    Scope  *wrapper_scopes[MAX_IF_WRAPPER_SCOPES];
    size_t  wrapper_count = 0;

    for (size_t i = 0; i < stmt->as.if_stmt.clause_count; i++) {
        const FengIfClause *c = &stmt->as.if_stmt.clauses[i];
        ExprResult cond;
        Scope *branch_scope;

        if (i > 0) {
            /*
             * Push a wrapper scope *before* evaluating the condition so that
             * any temporaries produced by cg_emit_expr are registered in this
             * scope (and cleaned up when we close the wrapper).
             */
            Scope *ws = scope_push(cg->cur_scope);
            if (!ws) return cg_fail(cg, c->token, "IE0001", "codegen: out of memory");
            cg->cur_scope = ws;

            /* Record buffer position to detect preamble. */
            size_t body_len_before = cg->cur_body->length;

            if (!cg_emit_expr(cg, c->condition, &cond)) {
                cg->cur_scope = ws->parent;
                scope_pop_free(ws);
                return false;
            }
            if (cond.type->kind != CG_TYPE_BOOL) {
                er_free(&cond);
                cg->cur_scope = ws->parent;
                scope_pop_free(ws);
                return cg_fail(cg, c->token, "CE0266", "codegen: if condition must be bool");
            }

            bool has_preamble = (cg->cur_body->length != body_len_before);

            if (has_preamble) {
                /*
                 * Preamble was emitted after the previous clause's `}`.
                 * Insert `else {\n` before it and use a plain `if`.
                 */
                const char *else_open = "    else {\n";
                size_t eo_len = strlen(else_open);
                size_t pr_len = cg->cur_body->length - body_len_before;

                if (!buf_reserve(cg->cur_body, eo_len)) {
                    er_free(&cond);
                    cg->cur_scope = ws->parent;
                    scope_pop_free(ws);
                    return cg_fail(cg, c->token, "IE0001", "codegen: out of memory");
                }
                memmove(cg->cur_body->data + body_len_before + eo_len,
                        cg->cur_body->data + body_len_before,
                        pr_len);
                memcpy(cg->cur_body->data + body_len_before, else_open, eo_len);
                cg->cur_body->length += eo_len;
                cg->cur_body->data[cg->cur_body->length] = '\0';

                buf_append_fmt(cg->cur_body, "    if (%s) {\n", cond.c_expr);

                if (wrapper_count >= MAX_IF_WRAPPER_SCOPES) {
                    er_free(&cond);
                    cg->cur_scope = ws->parent;
                    scope_pop_free(ws);
                    return cg_fail(cg, c->token, "CE0267", "codegen: too many nested else-if wrappers");
                }
                wrapper_scopes[wrapper_count++] = ws;
            } else {
                /*
                 * No preamble — the wrapper scope is empty.  Pop it and emit
                 * a normal `else if`.
                 */
                cg->cur_scope = ws->parent;
                scope_pop_free(ws);

                buf_append_fmt(cg->cur_body, "    else if (%s) {\n", cond.c_expr);
            }
        } else {
            /* First clause (i == 0): plain `if`. */
            if (!cg_emit_expr(cg, c->condition, &cond)) return false;
            if (cond.type->kind != CG_TYPE_BOOL) {
                er_free(&cond);
                return cg_fail(cg, c->token, "CE0266", "codegen: if condition must be bool");
            }
            buf_append_fmt(cg->cur_body, "    if (%s) {\n", cond.c_expr);
        }

        er_free(&cond);

        branch_scope = scope_push(cg->cur_scope);
        if (!branch_scope) return cg_fail(cg, c->token, "IE0001", "codegen: out of memory");
        cg->cur_scope = branch_scope;
        if (!cg_emit_block(cg, c->block)) {
            cg->cur_scope = branch_scope->parent;
            scope_pop_free(branch_scope);
            return false;
        }
        cg_release_scope(cg, branch_scope);
        cg->cur_scope = branch_scope->parent;
        scope_pop_free(branch_scope);
        buf_append_cstr(cg->cur_body, "    }\n");
    }

    if (stmt->as.if_stmt.else_block) {
        Scope *else_scope = scope_push(cg->cur_scope);
        if (!else_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        cg->cur_scope = else_scope;
        buf_append_cstr(cg->cur_body, "    else {\n");
        if (!cg_emit_block(cg, stmt->as.if_stmt.else_block)) {
            cg->cur_scope = else_scope->parent;
            scope_pop_free(else_scope);
            return false;
        }
        cg_release_scope(cg, else_scope);
        cg->cur_scope = else_scope->parent;
        scope_pop_free(else_scope);
        buf_append_cstr(cg->cur_body, "    }\n");
    }

    /* Close wrapper scopes in reverse order: release temporaries, then `}`. */
    for (size_t d = wrapper_count; d > 0; d--) {
        Scope *ws = wrapper_scopes[d - 1];
        cg_release_scope(cg, ws);
        cg->cur_scope = ws->parent;
        scope_pop_free(ws);
        buf_append_cstr(cg->cur_body, "    }\n");
    }
    return true;
}

static bool cg_emit_match_stmt_branch(CG *cg, const FengBlock *block, FengToken token) {
    Scope *branch_scope = scope_push(cg->cur_scope);
    if (!branch_scope) return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    cg->cur_scope = branch_scope;

    bool ok = cg_emit_block(cg, block);
    if (ok) cg_release_scope(cg, branch_scope);
    cg->cur_scope = branch_scope->parent;
    scope_pop_free(branch_scope);
    return ok;
}

static bool cg_union_member_index_for_label(CG *cg,
                                            const UserSpec *spec,
                                            const FengMatchLabel *label,
                                            size_t *out_index) {
    CGType *label_type = NULL;

    if (spec == NULL || label == NULL || label->kind != FENG_MATCH_LABEL_TYPE ||
        label->type == NULL || out_index == NULL) {
        return false;
    }
    if (!cg_resolve_type(cg, label->type, &label->token, &label_type)) {
        return false;
    }
    for (size_t index = 0U; index < spec->union_member_count; ++index) {
        if (cg_types_equal(label_type, spec->union_member_types[index])) {
            *out_index = index;
            cgtype_free(label_type);
            return true;
        }
    }
    cgtype_free(label_type);
    return cg_fail(cg, label->token,
                   "CE0268", "codegen: union-form match label is not a normalized member");
}

/* Build full match condition for a label, including nested tag checks for chain labels.
 * For a simple label `A`, generates "tmp.tag == 0U".
 * For a chain label `A -> B -> C`, generates "tmp.tag == 0U && tmp.payload.m0.tag == 1U && tmp.payload.m0.payload.m1.tag == 2U".
 * Caller must free the returned string. */
static char *cg_build_label_condition(CG *cg,
                                       const char *target_tmp,
                                       const UserSpec *root_spec,
                                       const FengMatchLabel *label) {
    Buf cond;
    CGType *label_type = NULL;
    size_t first_index = 0U;
    bool found = false;

    if (label == NULL || label->kind != FENG_MATCH_LABEL_TYPE ||
        label->type == NULL || target_tmp == NULL || root_spec == NULL) {
        return NULL;
    }

    if (!cg_resolve_type(cg, label->type, &label->token, &label_type)) {
        return NULL;
    }

    for (size_t i = 0U; i < root_spec->union_member_count; ++i) {
        if (cg_types_equal(label_type, root_spec->union_member_types[i])) {
            first_index = i;
            found = true;
            break;
        }
    }
    cgtype_free(label_type);

    if (!found) {
        return NULL;
    }

    buf_init(&cond);
    buf_append_fmt(&cond, "%s.tag == %zuU", target_tmp, first_index);

    if (label->type_chain_count > 0U) {
        /* Chain label: add nested tag checks */
        Buf path;
        CGType *current_type = root_spec->union_member_types[first_index];
        const UserSpec *current_spec = root_spec;

        buf_init(&path);
        buf_append_fmt(&path, "%s.payload.", target_tmp);
        cg_append_union_payload_field_name(&path, first_index);

        for (size_t chain_idx = 0U; chain_idx < label->type_chain_count; ++chain_idx) {
            const FengTypeRef *chain_type_ref = label->type_chain[chain_idx];
            CGType *chain_type = NULL;
            size_t chain_index = 0U;

            if (chain_type_ref == NULL ||
                !cg_resolve_type(cg, chain_type_ref, &label->token, &chain_type)) {
                buf_free(&path);
                buf_free(&cond);
                return NULL;
            }

            if (current_type == NULL || current_type->kind != CG_TYPE_SPEC ||
                current_type->user_spec == NULL ||
                current_type->user_spec->form != FENG_SPEC_FORM_UNION) {
                cgtype_free(chain_type);
                buf_free(&path);
                buf_free(&cond);
                return NULL;
            }

            current_spec = current_type->user_spec;
            found = false;
            for (size_t i = 0U; i < current_spec->union_member_count; ++i) {
                if (cg_types_equal(chain_type, current_spec->union_member_types[i])) {
                    chain_index = i;
                    found = true;
                    break;
                }
            }
            cgtype_free(chain_type);

            if (!found) {
                buf_free(&path);
                buf_free(&cond);
                return NULL;
            }

            buf_append_fmt(&cond, " && %s.tag == %zuU", path.data, chain_index);
            buf_append_fmt(&path, ".payload.");
            cg_append_union_payload_field_name(&path, chain_index);

            current_type = current_spec->union_member_types[chain_index];
        }

        buf_free(&path);
    }

    return cond.data;
}

/* Build nested payload access path for chain labels.
 * For a chain like `Inner -> A`, generates path like "mt.payload.m0.payload.m1"
 * where m0 is Inner's index in Outer, and m1 is A's index in Inner.
 * Returns the deepest type in out_deepest_type.
 * Caller must free the returned string. */
static char *cg_build_chain_payload_path(CG *cg,
                                         const char *target_tmp,
                                         const UserSpec *root_spec,
                                         const FengMatchLabel *label,
                                         CGType **out_deepest_type) {
    Buf path;
    CGType *current_type = NULL;
    const UserSpec *current_spec = root_spec;

    if (label == NULL || label->type_chain_count == 0U || target_tmp == NULL ||
        root_spec == NULL || out_deepest_type == NULL || label->type == NULL) {
        return NULL;
    }

    *out_deepest_type = NULL;

    buf_init(&path);
    buf_append_cstr(&path, target_tmp);
    if (path.data == NULL) {
        buf_free(&path);
        return NULL;
    }

    /* Start with the first-level member (label->type) */
    CGType *first_type = NULL;
    if (!cg_resolve_type(cg, label->type, &label->token, &first_type)) {
        buf_free(&path);
        return NULL;
    }

    size_t first_index = 0U;
    bool found = false;
    for (size_t i = 0U; i < current_spec->union_member_count; ++i) {
        if (cg_types_equal(first_type, current_spec->union_member_types[i])) {
            first_index = i;
            found = true;
            break;
        }
    }
    cgtype_free(first_type);

    if (!found) {
        buf_free(&path);
        return NULL;
    }

    buf_append_fmt(&path, ".payload.");
    cg_append_union_payload_field_name(&path, first_index);
    if (path.data == NULL) {
        buf_free(&path);
        return NULL;
    }

    current_type = current_spec->union_member_types[first_index];

    /* Traverse the chain */
    for (size_t chain_idx = 0U; chain_idx < label->type_chain_count; ++chain_idx) {
        const FengTypeRef *chain_type_ref = label->type_chain[chain_idx];
        CGType *chain_type = NULL;

        if (chain_type_ref == NULL) {
            buf_free(&path);
            return NULL;
        }

        if (!cg_resolve_type(cg, chain_type_ref, &label->token, &chain_type)) {
            buf_free(&path);
            return NULL;
        }

        /* Current type must be a union spec */
        if (current_type == NULL || current_type->kind != CG_TYPE_SPEC ||
            current_type->user_spec == NULL ||
            current_type->user_spec->form != FENG_SPEC_FORM_UNION) {
            cgtype_free(chain_type);
            buf_free(&path);
            return NULL;
        }

        current_spec = current_type->user_spec;

        size_t chain_index = 0U;
        found = false;
        for (size_t i = 0U; i < current_spec->union_member_count; ++i) {
            if (cg_types_equal(chain_type, current_spec->union_member_types[i])) {
                chain_index = i;
                found = true;
                break;
            }
        }
        cgtype_free(chain_type);

        if (!found) {
            buf_free(&path);
            return NULL;
        }

        buf_append_fmt(&path, ".payload.");
        cg_append_union_payload_field_name(&path, chain_index);
        if (path.data == NULL) {
            buf_free(&path);
            return NULL;
        }

        current_type = current_spec->union_member_types[chain_index];
    }

    if (path.data == NULL) {
        return NULL;
    }

    *out_deepest_type = cgtype_clone(current_type);
    if (*out_deepest_type == NULL) {
        buf_free(&path);
        return NULL;
    }
    return path.data;
}


static bool cg_emit_union_match_stmt_branch(CG *cg,
                                            const FengBlock *block,
                                            FengToken token,
                                            bool has_binding,
                                            FengSlice binding_name,
                                            bool has_single_member,
                                            const char *target_tmp,
                                            const UserSpec *spec,
                                            size_t member_index,
                                            const FengMatchBranch *branch) {
    Scope *branch_scope = scope_push(cg->cur_scope);
    FengSlice alias_name = {NULL, 0U};
    bool ok;

    if (branch_scope == NULL) {
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    cg->cur_scope = branch_scope;
    /* Use binding name when present; otherwise no alias (auto-narrowing removed). */
    if (has_binding && binding_name.data != NULL && binding_name.length > 0U) {
        alias_name = binding_name;
    }
    if (alias_name.data != NULL && alias_name.length > 0U && has_single_member) {
        /* Check if any label has a chain for deepest-type narrowing */
        const FengMatchLabel *chain_label = NULL;
        if (branch != NULL) {
            for (size_t label_idx = 0U; label_idx < branch->label_count; ++label_idx) {
                if (branch->labels[label_idx].type_chain_count > 0U) {
                    chain_label = &branch->labels[label_idx];
                    break;
                }
            }
        }

        if (chain_label != NULL) {
            /* Chain label: build nested payload path to deepest type */
            CGType *deepest_type = NULL;
            char *payload_path = cg_build_chain_payload_path(cg,
                                                              target_tmp,
                                                              spec,
                                                              chain_label,
                                                              &deepest_type);
            if (payload_path != NULL && deepest_type != NULL) {
                char *alias_cstr = strndup(alias_name.data, alias_name.length);
                bool add_ok = alias_cstr != NULL &&
                              scope_add(branch_scope,
                                        alias_cstr,
                                        payload_path,
                                        deepest_type,
                                        true);
                free(payload_path);
                free(alias_cstr);
                if (!add_ok) {
                    cgtype_free(deepest_type);
                    cg->cur_scope = branch_scope->parent;
                    scope_pop_free(branch_scope);
                    return cg_fail(cg, token, "IE0001", "codegen: out of memory");
                }
            } else {
                /* Fallback to first-level member if chain path building fails */
                cgtype_free(deepest_type);
                free(payload_path);
                Buf payload_expr;
                CGType *alias_type;
                char *alias_cstr;

                buf_init(&payload_expr);
                buf_append_fmt(&payload_expr, "%s.payload.", target_tmp);
                cg_append_union_payload_field_name(&payload_expr, member_index);
                alias_type = cgtype_clone(spec->union_member_types[member_index]);
                alias_cstr = strndup(alias_name.data, alias_name.length);
                if (payload_expr.data == NULL || alias_type == NULL || alias_cstr == NULL ||
                    !scope_add(branch_scope,
                               alias_cstr,
                               payload_expr.data,
                               alias_type,
                               true)) {
                    cgtype_free(alias_type);
                    free(alias_cstr);
                    buf_free(&payload_expr);
                    cg->cur_scope = branch_scope->parent;
                    scope_pop_free(branch_scope);
                    return cg_fail(cg, token, "IE0001", "codegen: out of memory");
                }
                free(alias_cstr);
                buf_free(&payload_expr);
            }
        } else {
            /* Non-chain label: use first-level member */
            Buf payload_expr;
            CGType *alias_type;
            char *alias_cstr;

            buf_init(&payload_expr);
            buf_append_fmt(&payload_expr, "%s.payload.", target_tmp);
            cg_append_union_payload_field_name(&payload_expr, member_index);
            alias_type = cgtype_clone(spec->union_member_types[member_index]);
            alias_cstr = strndup(alias_name.data, alias_name.length);
            if (payload_expr.data == NULL || alias_type == NULL || alias_cstr == NULL ||
                !scope_add(branch_scope,
                           alias_cstr,
                           payload_expr.data,
                           alias_type,
                           true)) {
                cgtype_free(alias_type);
                free(alias_cstr);
                buf_free(&payload_expr);
                cg->cur_scope = branch_scope->parent;
                scope_pop_free(branch_scope);
                return cg_fail(cg, token, "IE0001", "codegen: out of memory");
            }
            free(alias_cstr);
            buf_free(&payload_expr);
        }
    }

    ok = cg_emit_block(cg, block);
    if (ok) {
        cg_release_scope(cg, branch_scope);
    }
    cg->cur_scope = branch_scope->parent;
    scope_pop_free(branch_scope);
    return ok;
}

static bool cg_emit_match_stmt(CG *cg, const FengStmt *stmt) {
    buf_append_cstr(cg->cur_body, "    {\n");
    Scope *match_scope = scope_push(cg->cur_scope);
    if (!match_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    cg->cur_scope = match_scope;

    ExprResult target;
    if (!cg_emit_expr(cg, stmt->as.match_stmt.target, &target)) {
        cg->cur_scope = match_scope->parent;
        scope_pop_free(match_scope);
        return false;
    }

    if (target.type != NULL && target.type->kind == CG_TYPE_SPEC &&
        target.type->user_spec != NULL &&
        target.type->user_spec->form == FENG_SPEC_FORM_UNION) {
        const UserSpec *union_spec = target.type->user_spec;
        char *target_tmp = cg_materialize_to_local(cg, &target, "_umt");
        bool first_branch = true;
        bool ok = true;
        bool *covered_members = NULL;

        if (target_tmp == NULL) {
            er_free(&target);
            cg->cur_scope = match_scope->parent;
            scope_pop_free(match_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        er_free(&target);
        covered_members = union_spec->union_member_count > 0U
                              ? (bool *)calloc(union_spec->union_member_count,
                                               sizeof(*covered_members))
                              : NULL;
        if (union_spec->union_member_count > 0U && covered_members == NULL) {
            free(target_tmp);
            cg->cur_scope = match_scope->parent;
            scope_pop_free(match_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }

        for (size_t branch_index = 0U;
             branch_index < stmt->as.match_stmt.branch_count;
             ++branch_index) {
            const FengMatchBranch *branch = &stmt->as.match_stmt.branches[branch_index];
            Buf condition;
            size_t first_member_index = 0U;
            size_t matched_member_count = 0U;

            if (branch->label_count == 0U) {
                ok = cg_fail(cg, branch->token,
                             "CE0269", "codegen: match branch has no labels");
                break;
            }
            buf_init(&condition);
            for (size_t label_index = 0U; label_index < branch->label_count; ++label_index) {
                size_t member_index = 0U;
                char *label_cond = NULL;

                if (!cg_union_member_index_for_label(cg,
                                                     union_spec,
                                                     &branch->labels[label_index],
                                                     &member_index)) {
                    ok = false;
                    break;
                }
                label_cond = cg_build_label_condition(cg, target_tmp, union_spec,
                                                       &branch->labels[label_index]);
                if (label_cond == NULL) {
                    ok = false;
                    break;
                }
                if (label_index != 0U) {
                    buf_append_cstr(&condition, " || ");
                }
                buf_append_cstr(&condition, label_cond);
                free(label_cond);
                if (covered_members != NULL) {
                    covered_members[member_index] = true;
                }
                if (matched_member_count == 0U) {
                    first_member_index = member_index;
                }
                matched_member_count++;
            }
            if (!ok) {
                buf_free(&condition);
                break;
            }

            if (first_branch) {
                buf_append_fmt(cg->cur_body, "    if (%s) {\n", condition.data);
                first_branch = false;
            } else {
                buf_append_fmt(cg->cur_body, "    } else if (%s) {\n", condition.data);
            }
            buf_free(&condition);

            if (!cg_emit_union_match_stmt_branch(cg,
                                                 branch->body,
                                                 branch->token,
                                                 branch->has_binding,
                                                 branch->binding_name,
                                                 matched_member_count == 1U,
                                                 target_tmp,
                                                 union_spec,
                                                 first_member_index,
                                                 branch)) {
                ok = false;
                break;
            }
        }

        if (ok && stmt->as.match_stmt.else_block != NULL) {
            bool else_has_single_member = false;
            size_t else_member_index = 0U;

            if (covered_members != NULL) {
                size_t remaining_count = 0U;

                for (size_t member_index = 0U;
                     member_index < union_spec->union_member_count;
                     ++member_index) {
                    if (!covered_members[member_index]) {
                        else_member_index = member_index;
                        remaining_count++;
                    }
                }
                else_has_single_member = remaining_count == 1U;
            }
            if (first_branch) {
                buf_append_cstr(cg->cur_body, "    {\n");
            } else {
                buf_append_cstr(cg->cur_body, "    } else {\n");
            }
            if (!cg_emit_union_match_stmt_branch(cg,
                                                 stmt->as.match_stmt.else_block,
                                                 stmt->token,
                                                 false,
                                                 (FengSlice){NULL, 0U},
                                                 else_has_single_member,
                                                 target_tmp,
                                                 union_spec,
                                                 else_member_index,
                                                 NULL)) {
                ok = false;
            }
            first_branch = false;
        }

        if (ok) {
            if (!first_branch) {
                buf_append_cstr(cg->cur_body, "    }\n");
            }
            cg_release_scope(cg, match_scope);
            buf_append_cstr(cg->cur_body, "    }\n");
        }
        free(covered_members);
        free(target_tmp);
        cg->cur_scope = match_scope->parent;
        scope_pop_free(match_scope);
        return ok;
    }

    CGTypeKind target_kind = target.type->kind;
    if (target_kind != CG_TYPE_BOOL &&
        target_kind != CG_TYPE_STRING &&
        !cgtype_is_integer(target_kind)) {
        er_free(&target);
        cg->cur_scope = match_scope->parent;
        scope_pop_free(match_scope);
        return cg_fail(cg, stmt->token,
            "CE0270", "codegen: match target must be integer, bool, string, or enum");
    }

    char *target_tmp = cg_materialize_to_local(cg, &target, "_mt");
    if (!target_tmp) {
        er_free(&target);
        cg->cur_scope = match_scope->parent;
        scope_pop_free(match_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }
    er_free(&target);

    bool first_branch = true;
    bool ok = true;
    for (size_t branch_index = 0;
         branch_index < stmt->as.match_stmt.branch_count;
         ++branch_index) {
        const FengMatchBranch *branch = &stmt->as.match_stmt.branches[branch_index];

        if (branch->label_count == 0) {
            ok = cg_fail(cg, branch->token,
                "CE0269", "codegen: match branch has no labels");
            break;
        }

        Buf condition;
        buf_init(&condition);
        for (size_t label_index = 0; label_index < branch->label_count; ++label_index) {
            if (label_index != 0) buf_append_cstr(&condition, " || ");
            if (!cg_emit_match_label_cond(cg,
                                          target_tmp,
                                          target_kind,
                                          &branch->labels[label_index],
                                          &condition)) {
                ok = false;
                break;
            }
        }

        if (!ok) {
            buf_free(&condition);
            break;
        }

        if (first_branch) {
            buf_append_fmt(cg->cur_body, "    if (%s) {\n", condition.data);
            first_branch = false;
        } else {
            buf_append_fmt(cg->cur_body, "    } else if (%s) {\n", condition.data);
        }
        buf_free(&condition);

        if (!cg_emit_match_stmt_branch(cg, branch->body, branch->token)) {
            ok = false;
            break;
        }
    }

    if (ok && stmt->as.match_stmt.else_block != NULL) {
        if (first_branch) {
            buf_append_cstr(cg->cur_body, "    {\n");
        } else {
            buf_append_cstr(cg->cur_body, "    } else {\n");
        }
        if (!cg_emit_match_stmt_branch(cg,
                                       stmt->as.match_stmt.else_block,
                                       stmt->token)) {
            ok = false;
        }
        first_branch = false;
    }

    if (ok) {
        if (!first_branch) {
            buf_append_cstr(cg->cur_body, "    }\n");
        }
        cg_release_scope(cg, match_scope);
        buf_append_cstr(cg->cur_body, "    }\n");
    }

    free(target_tmp);
    cg->cur_scope = match_scope->parent;
    scope_pop_free(match_scope);
    return ok;
}

/* Returns true if `expr` is or contains a match_op node with a binding.
 * Used by if/while codegen to decide whether to keep condition temporaries
 * alive across the body (the binding alias references the materialized
 * target tmp). Only `&&` chains propagate bindings (per docs/specifications/feng-flow.md
 * §3.3); `||` / `!` subtrees do not. */
static bool cg_expr_has_visible_match_binding(const FengExpr *expr) {
    if (expr == NULL) return false;
    switch (expr->kind) {
        case FENG_EXPR_BINARY:
            if (expr->as.binary.op == FENG_TOKEN_AND_AND) {
                return cg_expr_has_visible_match_binding(expr->as.binary.left) ||
                       cg_expr_has_visible_match_binding(expr->as.binary.right);
            }
            return false;
        case FENG_EXPR_UNARY:
            return false;
        case FENG_EXPR_MATCH_OP:
            return expr->as.match_op.has_binding;
        default:
            return false;
    }
}

static bool cg_emit_while(CG *cg, const FengStmt *stmt) {
    /* Emit as `for (;;)` so we can re-evaluate the condition each iter
     * inside a scope that releases temporaries from condition eval. */
    bool has_match_binding = cg_expr_has_visible_match_binding(stmt->as.while_stmt.condition);
    buf_append_cstr(cg->cur_body, "    for (;;) {\n");
    /* Condition scope: any temporaries from cond eval get released here.
     * When the condition contains a match_op with binding, the materialized
     * target tmp must survive across the body (the binding alias references
     * it), so we keep the condition scope alive until after the body and
     * mark it as the loop scope so break/continue release it on exit. */
    Scope *cond_scope = scope_push(cg->cur_scope);
    if (!cond_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    if (has_match_binding) {
        cond_scope->is_loop = true;
        cond_scope->try_depth_at_entry = cg->try_depth;
        cg->loop_depth++;
    }
    cg->cur_scope = cond_scope;
    ExprResult cond;
    if (!cg_emit_expr(cg, stmt->as.while_stmt.condition, &cond)) {
        cg->cur_scope = cond_scope->parent;
        if (has_match_binding) cg->loop_depth--;
        scope_pop_free(cond_scope);
        return false;
    }
    if (cond.type->kind != CG_TYPE_BOOL) {
        er_free(&cond);
        cg->cur_scope = cond_scope->parent;
        if (has_match_binding) cg->loop_depth--;
        scope_pop_free(cond_scope);
        return cg_fail(cg, stmt->token, "CE0271", "codegen: while condition must be bool");
    }
    char *cond_tmp = cg_fresh_temp(cg, "_cond");
    buf_append_fmt(cg->cur_body, "        bool %s = %s;\n", cond_tmp, cond.c_expr);
    er_free(&cond);

    if (has_match_binding) {
        /* Restructured control flow: body is inside `if (_cond)`, and the
         * condition scope (holding the materialized target tmp and the
         * binding alias) is released after the body on every path. The
         * trailing `if (!_cond) break;` only runs when the body was skipped,
         * after the cleanup, so the tmp is released exactly once. */
        buf_append_fmt(cg->cur_body, "        if (%s) {\n", cond_tmp);
        Scope *body_scope = scope_push(cg->cur_scope);
        if (!body_scope) {
            free(cond_tmp);
            cg->cur_scope = cond_scope->parent;
            cg->loop_depth--;
            scope_pop_free(cond_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        body_scope->is_loop = false;
        cg->cur_scope = body_scope;
        if (!cg_emit_block(cg, stmt->as.while_stmt.body)) {
            cg->cur_scope = body_scope->parent;
            scope_pop_free(body_scope);
            free(cond_tmp);
            cg->cur_scope = cond_scope->parent;
            cg->loop_depth--;
            scope_pop_free(cond_scope);
            return false;
        }
        cg_release_scope(cg, body_scope);
        cg->cur_scope = body_scope->parent;
        scope_pop_free(body_scope);
        buf_append_cstr(cg->cur_body, "        }\n");
        cg_release_scope(cg, cond_scope);
        buf_append_fmt(cg->cur_body, "        if (!%s) break;\n", cond_tmp);
        free(cond_tmp);
        cg->cur_scope = cond_scope->parent;
        cg->loop_depth--;
        scope_pop_free(cond_scope);
        buf_append_cstr(cg->cur_body, "    }\n");
        return true;
    }

    cg_release_scope(cg, cond_scope);
    cg->cur_scope = cond_scope->parent;
    scope_pop_free(cond_scope);
    buf_append_fmt(cg->cur_body, "        if (!%s) break;\n", cond_tmp);
    free(cond_tmp);

    cg->loop_depth++;
    Scope *body_scope = scope_push(cg->cur_scope);
    if (!body_scope) { cg->loop_depth--; return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory"); }
    body_scope->is_loop = true;
    body_scope->try_depth_at_entry = cg->try_depth;
    cg->cur_scope = body_scope;
    if (!cg_emit_block(cg, stmt->as.while_stmt.body)) {
        cg->cur_scope = body_scope->parent;
        scope_pop_free(body_scope);
        cg->loop_depth--;
        return false;
    }
    cg_release_scope(cg, body_scope);
    cg->cur_scope = body_scope->parent;
    scope_pop_free(body_scope);
    cg->loop_depth--;
    buf_append_cstr(cg->cur_body, "    }\n");
    return true;
}

/* `for` statement — supports both forms documented in docs/specifications/feng-flow.md §6:
 *
 *   1. Three-clause:  for [init]; [cond]; [update] { body }
 *   2. for/in       :  for let|var IT in SEQ { body }
 *
 * Compilation strategy (production-grade, mirroring `while` for ARC and
 * cleanup-chain bookkeeping; jumps are routed through goto-labels so a
 * `continue` runs the update step before re-entering the loop):
 *
 *   {                              // outer scope
 *       <init or seq materialise>  // lives until loop exits
 *       for (;;) {
 *           bool _cond_N;
 *           { <cond eval>; _cond_N = ...; }   // condition scope (release temps)
 *           if (!_cond_N) break;
 *           { <body> }             // lexical body scope; continue jumps out
 *           _cont_N: ;             // continue lands outside body declarations
 *           { <update> }           // update scope (release temps)
 *       }
 *   }
 *
 * For `for/in`, the iteration sequence is materialised once into the outer
 * scope so its +1 reference is held for the whole loop. Each iteration the
 * body scope re-declares the iter binding, retaining the array slot value
 * if it is managed; the per-iter release happens through the body scope's
 * normal release path (and through the break/continue path via the
 * inclusive release added in cg_emit_break_continue).
 *
 * Invariants honoured here:
 *   - The semantic analyzer (analyzer.c) restricts the for/in sequence to
 *     `T[]` / `T[!]` and ensures the iter binding's mutability matches use.
 *   - break / continue paths emit the same active try/catch cleanup used by
 *     return before jumping out of generated try/catch blocks.
 */

/* Register one already-initialized, non-captured loop binding in the current
 * per-iteration scope. Dynamic storage metadata is optional: direct generic
 * array elements keep their existing borrowed-address representation, while
 * descriptor-sized aggregate copies own storage and cleanup in this scope. */
static bool cg_register_loop_binding_local(
    CG *cg,
    const FengBinding *binding,
    const char *c_name,
    const CGType *binding_type,
    const char *erased_descriptor_name,
    const char *erased_size_name,
    const char *reified_descriptor_name,
    const char *reified_size_name) {
    CGType *local_type;
    Local *added;
    size_t prior_count;

    if (cg == NULL || binding == NULL || c_name == NULL ||
        binding_type == NULL) {
        return false;
    }
    local_type = cgtype_clone(binding_type);
    if (local_type == NULL) {
        return cg_fail(cg, binding->token,
                       "IE0001", "codegen: out of memory");
    }
    prior_count = cg->cur_scope->count;
    if (!scope_add(cg->cur_scope,
                   "_unused_internal_name__",
                   c_name,
                   local_type,
                   false)) {
        if (cg->cur_scope->count > prior_count) {
            scope_discard_suffix(cg->cur_scope, prior_count);
        } else {
            cgtype_free(local_type);
        }
        return cg_fail(cg, binding->token,
                       "IE0001", "codegen: out of memory");
    }
    if (erased_descriptor_name != NULL &&
        !scope_mark_last_erased_generic_storage(cg->cur_scope,
                                                erased_descriptor_name,
                                                erased_size_name)) {
        return cg_fail(cg, binding->token,
                       "IE0001", "codegen: out of memory");
    }
    if (reified_descriptor_name != NULL &&
        !scope_mark_last_reified_storage(cg->cur_scope,
                                         reified_descriptor_name,
                                         reified_size_name)) {
        return cg_fail(cg, binding->token,
                       "IE0001", "codegen: out of memory");
    }
    if (!scope_mark_last_binding_mutability(cg->cur_scope,
                                            binding->mutability)) {
        return cg_fail(cg, binding->token,
                       "IE0001", "codegen: out of memory");
    }

    added = &cg->cur_scope->items[cg->cur_scope->count - 1U];
    free(added->name);
    added->name = strndup(binding->name.data, binding->name.length);
    if (added->name == NULL ||
        !cg_debug_add_variable_record_slice_cgtype(
            cg,
            c_name,
            binding->name,
            NULL,
            binding_type,
            FENG_CODEGEN_MAPING_VARIABLE_BINDING,
            binding->token)) {
        return false;
    }

    if (erased_descriptor_name != NULL) {
        cg_emit_cleanup_push_for_erased_generic_storage(
            cg, c_name, erased_descriptor_name);
    } else if (reified_descriptor_name != NULL) {
        cg_emit_cleanup_push_for_reified_aggregate_storage(
            cg, c_name, reified_descriptor_name);
    } else if (cgtype_is_managed(binding_type)) {
        cg_emit_cleanup_push_for_managed_local(cg, c_name);
    } else if (cgtype_is_aggregate(binding_type)) {
        cg_emit_cleanup_push_for_aggregate_local(cg, c_name, binding_type);
    }
    return true;
}

/* Initialize fresh descriptor-sized loop storage directly from a borrowed
 * element. Fresh storage has no old managed slots to release, so copy then
 * retain preserves ownership without the zero-fill and destination traversal
 * required by assignment into an already initialized value. */
static bool cg_emit_fresh_reified_loop_binding_storage(
    CG *cg,
    const CGType *type,
    const char *storage_c_name,
    const char *source_expr,
    FengToken blame,
    char **out_descriptor_c_name,
    char **out_size_c_name) {
    char *descriptor_expr;
    char *descriptor_name;
    char *size_name;

    if (cg == NULL || type == NULL || storage_c_name == NULL ||
        source_expr == NULL || out_descriptor_c_name == NULL ||
        out_size_c_name == NULL) {
        return false;
    }
    descriptor_expr =
        cg_reified_aggregate_descriptor_expr_dup(cg, type, blame);
    descriptor_name = cg_fresh_temp(cg, "_rad");
    size_name = cg_fresh_temp(cg, "_rsize");
    if (descriptor_expr == NULL || descriptor_name == NULL ||
        size_name == NULL) {
        free(descriptor_expr);
        free(descriptor_name);
        free(size_name);
        if (!cg->failed) {
            cg_fail(cg, blame,
                    "IE0001", "codegen: out of memory");
        }
        return false;
    }

    cg_emit_current_stmt_line_directive_force(cg);
    buf_append_fmt(cg->cur_body,
                   "    const FengAggregateDescriptor *%s = %s;\n"
                   "    const size_t %s = %s->size;\n"
                   "    _Alignas(max_align_t) char %s[%s];\n"
                   "    memcpy(%s, %s, %s);\n"
                   "    feng_aggregate_retain(%s, %s);\n",
                   descriptor_name,
                   descriptor_expr,
                   size_name,
                   descriptor_name,
                   storage_c_name,
                   size_name,
                   storage_c_name,
                   source_expr,
                   size_name,
                   storage_c_name,
                   descriptor_name);
    free(descriptor_expr);
    *out_descriptor_c_name = descriptor_name;
    *out_size_c_name = size_name;
    return true;
}

/* Create one source-level `for/in` binding from a borrowed element value.
 * Both array and iterator-protocol lowering call this function, so capture
 * selection, per-iteration identity, mutability metadata and cleanup cannot
 * diverge between the two paths. An address-form source is dereferenced for
 * fixed-layout values and passed directly to descriptor-sized storage code. */
static bool cg_emit_loop_binding_from_borrowed_source(
    CG *cg,
    const FengBinding *binding,
    const CGType *binding_type,
    const char *source_expr,
    bool source_is_address) {
    Buf value_expr;
    const char *fixed_value_expr = source_expr;
    char *c_name = NULL;
    char *c_type = NULL;
    char *descriptor_name = NULL;
    char *size_name = NULL;
    bool ok = false;

    if (cg == NULL || binding == NULL || binding_type == NULL ||
        source_expr == NULL) {
        return false;
    }
    buf_init(&value_expr);

    if (source_is_address &&
        !cg_capture_cell_uses_dynamic_storage(cg, binding_type)) {
        c_type = cg_ctype_dup(binding_type);
        if (c_type == NULL) {
            goto cleanup;
        }
        buf_append_fmt(&value_expr, "(*(%s *)%s)", c_type, source_expr);
        if (value_expr.data == NULL) {
            goto cleanup;
        }
        fixed_value_expr = value_expr.data;
    }

    if (cg_current_callable_captures_name(
            cg, binding->name.data, binding->name.length)) {
        const char *capture_source =
            cg_capture_cell_uses_dynamic_storage(cg, binding_type)
                ? source_expr
                : fixed_value_expr;

        ok = cg_scope_bind_capture_cell(
                 cg,
                 cg->cur_scope,
                 binding->name,
                 binding_type,
                 binding->token,
                 capture_source,
                 true,
                 false,
                 true,
                 FENG_CODEGEN_MAPING_VARIABLE_BINDING) &&
             scope_mark_last_binding_mutability(cg->cur_scope,
                                                binding->mutability);
        goto cleanup;
    }

    c_name = cg_local_cname(
        cg, binding->name.data, binding->name.length);
    if (c_name == NULL) {
        cg_fail(cg, binding->token,
                "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (!cg_emit_line_directive_force(cg, binding->token)) {
        goto cleanup;
    }

    if (binding_type->kind == CG_TYPE_GENERIC_PARAM) {
        if (c_type == NULL) {
            c_type = cg_ctype_dup(binding_type);
        }
        if (c_type == NULL) {
            cg_fail(cg, binding->token,
                    "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        /* Preserve the existing zero-copy borrowed address for an uncaptured
         * direct generic element. Captured generic bindings take an owned
         * per-iteration copy in the capture cell above. */
        buf_append_fmt(cg->cur_body,
                       "    %s %s = %s;\n",
                       c_type,
                       c_name,
                       source_expr);
        ok = cg_register_loop_binding_local(cg,
                                            binding,
                                            c_name,
                                            binding_type,
                                            NULL,
                                            NULL,
                                            NULL,
                                            NULL);
        goto cleanup;
    }

    if (source_is_address &&
        cg_type_uses_reified_storage(cg, binding_type)) {
        if (!cg_emit_fresh_reified_loop_binding_storage(
                cg,
                binding_type,
                c_name,
                source_expr,
                binding->token,
                &descriptor_name,
                &size_name)) {
            goto cleanup;
        }
        ok = cg_register_loop_binding_local(cg,
                                            binding,
                                            c_name,
                                            binding_type,
                                            NULL,
                                            NULL,
                                            descriptor_name,
                                            size_name);
        goto cleanup;
    }

    if (c_type == NULL) {
        c_type = cg_ctype_dup(binding_type);
    }
    if (c_type == NULL) {
        cg_fail(cg, binding->token,
                "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (cgtype_is_managed(binding_type)) {
        buf_append_fmt(cg->cur_body,
                       "    %s %s = %s; feng_retain(%s);\n",
                       c_type,
                       c_name,
                       fixed_value_expr,
                       c_name);
    } else if (cgtype_is_aggregate(binding_type)) {
        const char *aggregate_name = cg_aggregate_desc_name(binding_type);
        size_t aggregate_index;

        if (aggregate_name == NULL) {
            cg_fail(cg, binding->token,
                    "CE0278",
                    "codegen: missing aggregate descriptor for spec for/in element");
            goto cleanup;
        }
        buf_append_fmt(cg->cur_body,
                       "    %s %s = %s;",
                       c_type,
                       c_name,
                       fixed_value_expr);
        if (cg_value_needs_reified_layout(cg, binding_type) &&
            cg_lookup_reified_agg_dep_index(
                cg, aggregate_name, &aggregate_index)) {
            const char *source = cg->generic_type_method_rad_via_desc
                                     ? "_desc"
                                     : "_td";
            buf_append_fmt(
                cg->cur_body,
                " feng_aggregate_retain(&%s, "
                "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]);",
                c_name,
                source,
                aggregate_index);
        } else {
            buf_append_fmt(cg->cur_body,
                           " feng_aggregate_retain(&%s, &%s);",
                           c_name,
                           aggregate_name);
        }
        buf_append_cstr(cg->cur_body, "\n");
    } else if (cgtype_is_by_value_struct(binding_type)) {
        buf_append_fmt(cg->cur_body,
                       "    %s %s = %s;\n",
                       c_type,
                       c_name,
                       fixed_value_expr);
    } else {
        buf_append_fmt(cg->cur_body,
                       "    %s %s = (%s)(%s);\n",
                       c_type,
                       c_name,
                       c_type,
                       fixed_value_expr);
    }
    ok = cg_register_loop_binding_local(cg,
                                        binding,
                                        c_name,
                                        binding_type,
                                        NULL,
                                        NULL,
                                        NULL,
                                        NULL);

cleanup:
    free(c_name);
    free(c_type);
    free(descriptor_name);
    free(size_name);
    buf_free(&value_expr);
    if (!ok && !cg->failed) {
        return cg_fail(cg, binding->token,
                       "IE0001", "codegen: out of memory");
    }
    return ok;
}

/* Lower one source-level for/in binding pattern from a borrowed element.
 * Tuple patterns borrow each selected field directly and delegate every
 * component to the ordinary loop-binding path; they never materialize or
 * retain the complete tuple. Dynamic tuple layouts use their descriptor
 * offsets, while fixed layouts keep direct C field access. */
static bool cg_emit_loop_binding_pattern_from_borrowed_source(
    CG *cg,
    const FengBinding *binding,
    const CGType *element_type,
    const char *source_expr,
    bool source_is_address) {
    char *tuple_c_type = NULL;
    char *descriptor_expr = NULL;
    char *descriptor_name = NULL;
    bool uses_reified_layout;
    bool has_named_position = false;
    bool ok = false;

    if (cg == NULL || binding == NULL || element_type == NULL ||
        source_expr == NULL) {
        return false;
    }
    if (!binding->is_destructure) {
        return cg_emit_loop_binding_from_borrowed_source(cg,
                                                         binding,
                                                         element_type,
                                                         source_expr,
                                                         source_is_address);
    }
    if (!cg_type_is_tuple_user(element_type)) {
        return cg_fail(cg,
                       binding->token,
                       "CE0231", "codegen: destructuring source must be a tuple value");
    }
    if (element_type->user->field_count != binding->destructure_count) {
        return cg_fail(cg,
                       binding->token,
                       "CE0230", "codegen: destructuring arity mismatch");
    }

    for (size_t i = 0U; i < binding->destructure_count; ++i) {
        if (binding->destructure_names[i].length > 0U) {
            has_named_position = true;
            break;
        }
    }
    if (!has_named_position) {
        return true;
    }

    uses_reified_layout = cg_type_uses_reified_storage(cg, element_type);
    if (uses_reified_layout) {
        if (!source_is_address) {
            return cg_fail(cg,
                           binding->token,
                           "IE0001", "codegen: reified tuple loop element requires address storage");
        }
        descriptor_expr =
            cg_reified_aggregate_descriptor_expr_dup(cg,
                                                      element_type,
                                                      binding->token);
        descriptor_name = cg_fresh_temp(cg, "_loop_tuple_desc");
        if (descriptor_expr == NULL || descriptor_name == NULL) {
            goto cleanup;
        }
        cg_emit_current_stmt_line_directive_force(cg);
        buf_append_fmt(cg->cur_body,
                       "    const FengAggregateDescriptor *%s = %s;\n",
                       descriptor_name,
                       descriptor_expr);
    } else if (source_is_address) {
        tuple_c_type = cg_ctype_dup(element_type);
        if (tuple_c_type == NULL) {
            goto cleanup;
        }
    }

    for (size_t i = 0U; i < binding->destructure_count; ++i) {
        const UserField *field;
        FengBinding component;
        Buf field_source;
        bool field_source_is_address = false;

        if (binding->destructure_names[i].length == 0U) {
            continue;
        }
        field = &element_type->user->fields[i];
        if (field->type == NULL) {
            cg_fail(cg,
                    binding->token,
                    "IE0001", "codegen: tuple loop element field type is missing");
            goto cleanup;
        }

        component = *binding;
        component.name = binding->destructure_names[i];
        if (binding->destructure_tokens != NULL) {
            component.token = binding->destructure_tokens[i];
        }
        component.type = NULL;
        component.initializer = NULL;
        component.is_destructure = false;
        component.destructure_names = NULL;
        component.destructure_tokens = NULL;
        component.destructure_count = 0U;

        buf_init(&field_source);
        if (uses_reified_layout) {
            field_source_is_address = true;
            buf_append_fmt(
                &field_source,
                "(void *)((char *)%s + %s->reified_field_offsets[%zu])",
                source_expr,
                descriptor_name,
                i);
        } else if (source_is_address) {
            buf_append_fmt(&field_source,
                           "((%s *)%s)->%s",
                           tuple_c_type,
                           source_expr,
                           field->c_name);
        } else {
            buf_append_fmt(&field_source,
                           "(%s).%s",
                           source_expr,
                           field->c_name);
        }
        if (field_source.data == NULL ||
            !cg_emit_loop_binding_from_borrowed_source(
                cg,
                &component,
                field->type,
                field_source.data,
                field_source_is_address)) {
            buf_free(&field_source);
            goto cleanup;
        }
        buf_free(&field_source);
    }
    ok = true;

cleanup:
    free(tuple_c_type);
    free(descriptor_expr);
    free(descriptor_name);
    if (!ok && !cg->failed) {
        return cg_fail(cg,
                       binding->token,
                       "IE0001", "codegen: out of memory");
    }
    return ok;
}

static bool cg_emit_for_three(CG *cg, const FengStmt *stmt) {
    int id = cg->label_counter++;
    char cont_label[64];
    snprintf(cont_label, sizeof cont_label, "_cont_%d", id);

    if (!cg_emit_line_directive_force(cg, stmt->token)) return false;
    buf_append_cstr(cg->cur_body, "    {\n");

    /* Outer scope: holds the optional `for (init; ...)` binding. The init
     * may be a binding or an assignment / expression statement. We push a
     * scope so binding-form inits are released when the loop exits, and so
     * a binding declared here is invisible outside the for. */
    Scope *outer_scope = scope_push(cg->cur_scope);
    if (!outer_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    cg->cur_scope = outer_scope;

    if (stmt->as.for_stmt.init != NULL) {
        if (!cg_emit_line_directive_force(cg, stmt->token)) {
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        if (!cg_emit_stmt(cg, stmt->as.for_stmt.init)) {
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
    }

    if (!cg_emit_line_directive_force(cg, stmt->token)) {
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }
    buf_append_cstr(cg->cur_body, "    for (;;) {\n");

    /* Condition: optional. Empty condition means "always true" per spec. */
    if (stmt->as.for_stmt.condition != NULL) {
        Scope *cond_scope = scope_push(cg->cur_scope);
        if (!cond_scope) {
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        cg->cur_scope = cond_scope;
        if (!cg_emit_line_directive_force(cg, stmt->token)) {
            cg->cur_scope = cond_scope->parent;
            scope_pop_free(cond_scope);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        ExprResult cond;
        if (!cg_emit_expr(cg, stmt->as.for_stmt.condition, &cond)) {
            cg->cur_scope = cond_scope->parent;
            scope_pop_free(cond_scope);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        if (cond.type->kind != CG_TYPE_BOOL) {
            er_free(&cond);
            cg->cur_scope = cond_scope->parent;
            scope_pop_free(cond_scope);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "CE0272", "codegen: for condition must be bool");
        }
        char *cond_tmp = cg_fresh_temp(cg, "_fcond");
        buf_append_fmt(cg->cur_body, "        bool %s = %s;\n",
                       cond_tmp, cond.c_expr);
        er_free(&cond);
        cg_release_scope(cg, cond_scope);
        cg->cur_scope = cond_scope->parent;
        scope_pop_free(cond_scope);
        buf_append_fmt(cg->cur_body, "        if (!%s) break;\n", cond_tmp);
        free(cond_tmp);
    }

    /* Keep body declarations in a nested C block. A goto-based continue must
     * land outside this block so it never jumps into the scope of a VLA
     * emitted for descriptor-sized generic storage. */
    buf_append_cstr(cg->cur_body, "        {\n");

    /* Body: loop scope, with continue_label so `continue` jumps to update. */
    cg->loop_depth++;
    Scope *body_scope = scope_push(cg->cur_scope);
    if (!body_scope) {
        cg->loop_depth--;
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }
    body_scope->is_loop = true;
    body_scope->try_depth_at_entry = cg->try_depth;
    /* Stash label in a stable buffer associated with cur_body — we use the
     * outer scope as the lifetime anchor by allocating on the heap and
     * tracking via the items list: simpler to embed the literal in body_scope
     * via a strdup that we free after the loop closes. */
    char *cont_label_owned = strdup(cont_label);
    body_scope->continue_label = cont_label_owned;
    cg->cur_scope = body_scope;
    if (!cg_emit_block(cg, stmt->as.for_stmt.body)) {
        cg->cur_scope = body_scope->parent;
        body_scope->continue_label = NULL;
        scope_pop_free(body_scope);
        free(cont_label_owned);
        cg->loop_depth--;
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }
    cg_release_scope(cg, body_scope);
    buf_append_cstr(cg->cur_body, "        }\n");
    cg->cur_scope = body_scope->parent;
    body_scope->continue_label = NULL;
    scope_pop_free(body_scope);
    free(cont_label_owned);
    cg->loop_depth--;

    /* Continue label: lands here after body, before update. */
    if (!cg_emit_line_directive_force(cg, stmt->token)) {
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }
    buf_append_fmt(cg->cur_body, "        %s: ;\n", cont_label);

    /* Update: optional. Wrapped in its own scope so any temporaries from
     * the update statement are released before the next iteration. */
    if (stmt->as.for_stmt.update != NULL) {
        Scope *upd_scope = scope_push(cg->cur_scope);
        if (!upd_scope) {
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        cg->cur_scope = upd_scope;
        if (!cg_emit_line_directive_force(cg, stmt->token)) {
            cg->cur_scope = upd_scope->parent;
            scope_pop_free(upd_scope);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        if (!cg_emit_stmt(cg, stmt->as.for_stmt.update)) {
            cg->cur_scope = upd_scope->parent;
            scope_pop_free(upd_scope);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        cg_release_scope(cg, upd_scope);
        cg->cur_scope = upd_scope->parent;
        scope_pop_free(upd_scope);
    }

    if (!cg_emit_line_directive_force(cg, stmt->token)) {
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }
    buf_append_cstr(cg->cur_body, "    }\n");

    /* Outer scope cleanup (init binding release). */
    cg_release_scope(cg, outer_scope);
    cg->cur_scope = outer_scope->parent;
    scope_pop_free(outer_scope);
    buf_append_cstr(cg->cur_body, "    }\n");
    return true;
}

/* Resolve the callable descriptor for an iterator-protocol method synthesized
 * by for/in lowering. The semantic pass records the same owner/member/fit and
 * owner-instance identity, so this uses the ordinary fixed callable slot. */
static char *cg_for_in_method_descriptor_expr(
    CG *cg,
    const UserType *owner_type,
    const UserFit *owner_fit,
    const FengTypeMember *member,
    const FengTypeRef *owner_instance_type_ref,
    FengToken blame) {
    FengReifiableCallableDep dep;
    const FengDecl *owner_decl;

    if (owner_type == NULL || member == NULL) {
        return NULL;
    }
    owner_decl = owner_type->generic_origin_decl != NULL
        ? owner_type->generic_origin_decl
        : owner_type->decl;
    if (owner_decl == NULL) {
        return NULL;
    }
    memset(&dep, 0, sizeof(dep));
    dep.kind = owner_fit != NULL
        ? FENG_RESOLVED_CALLABLE_FIT_METHOD
        : FENG_RESOLVED_CALLABLE_TYPE_METHOD;
    dep.owner_type_decl = owner_decl;
    dep.member = member;
    dep.fit_decl = owner_fit != NULL ? owner_fit->decl : NULL;
    dep.owner_instance_type_ref = owner_instance_type_ref;
    return cg_callable_descriptor_expr_for_dep(cg, &dep, blame);
}

/* Emit for/in loop using the iterator protocol (@iterable/@iterator). */
static bool cg_emit_for_in_iterator(CG *cg, const FengStmt *stmt) {
    int id = cg->label_counter++;
    char cont_label[64];
    snprintf(cont_label, sizeof cont_label, "_cont_%d", id);

    const FengTypeMember *iterable_method = stmt->as.for_stmt.iter_iterable_method;
    const FengTypeMember *iterator_method = stmt->as.for_stmt.iter_iterator_method;
    const FengDecl *cursor_type_decl = stmt->as.for_stmt.iter_cursor_type_decl;

    buf_append_cstr(cg->cur_body, "    {\n");

    Scope *outer_scope = scope_push(cg->cur_scope);
    if (!outer_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    cg->cur_scope = outer_scope;

    /* Emit the iteration source expression. */
    ExprResult src;
    if (!cg_emit_expr(cg, stmt->as.for_stmt.iter_expr, &src)) {
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }

    /* Determine the cursor UserType, its @iterator UserMethod, and cursor var.
     * For generic types, cursor_ut must come from the resolved return type of
     * @iterable (not a decl lookup which finds the wrong instance). */
    const UserType *cursor_ut = NULL;
    const UserMethod *iter_um = NULL;
    const UserFit *iterator_user_fit = NULL;
    char *cursor_var = NULL;
    bool cursor_uses_reified_storage = false;

    if (iterable_method != NULL) {
        /* Find @iterable method on the source type (UserType or BuiltinFit). */
        const UserMethod *iterable_um = NULL;
        const UserFit *iterable_user_fit = NULL;
        bool iterable_is_builtin_fit = false;
        const UserType *src_ut = src.type != NULL && src.type->user != NULL
            ? src.type->user : NULL;
        if (src_ut != NULL) {
            iterable_um = cg_user_type_method_by_member(src_ut, iterable_method);
        }
        if (!iterable_um) {
            /* Search builtin fits (e.g. fit string { @iterable ... }). */
            for (size_t fi = 0; fi < cg->builtin_fit_count; fi++) {
                iterable_um = cg_builtin_fit_method_by_member(
                    &cg->builtin_fits[fi], iterable_method);
                if (iterable_um) { iterable_is_builtin_fit = true; break; }
            }
        }
        if (!iterable_um) {
            /* Search user fits (e.g. fit SomeType { @iterable ... }). */
            for (size_t fi = 0; fi < cg->user_fit_count; fi++) {
                iterable_um = cg_user_fit_method_by_member(
                    &cg->user_fits[fi], iterable_method);
                if (iterable_um) {
                    iterable_user_fit = &cg->user_fits[fi];
                    break;
                }
            }
        }
        if (!iterable_um) {
            er_free(&src);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "CE0273", "codegen: @iterable method not found on source type");
        }
        /* Get cursor_ut from the resolved return type of @iterable. */
        cursor_ut = iterable_um->return_type != NULL
            ? iterable_um->return_type->user : NULL;
        if (!cursor_ut) {
            cursor_ut = cg_find_user_type_by_decl(cg, cursor_type_decl);
        }
        if (!cursor_ut) {
            er_free(&src);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "CE0274", "codegen: iterator cursor type not found");
        }
        iter_um = cg_user_type_method_by_member(cursor_ut, iterator_method);
        if (!iter_um) {
            for (size_t fit_index = 0U;
                 fit_index < cg->user_fit_count;
                 ++fit_index) {
                iter_um = cg_user_fit_method_by_member(
                    &cg->user_fits[fit_index], iterator_method);
                if (iter_um != NULL) {
                    iterator_user_fit = &cg->user_fits[fit_index];
                    break;
                }
            }
        }
        if (!iter_um) {
            er_free(&src);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "CE0275", "codegen: @iterator method not found on cursor type");
        }

        /* Materialize receiver if it owns a ref. */
        if (cgtype_is_managed(src.type) && src.owns_ref) {
            cg_materialize_to_local(cg, &src, "_isrc");
        }

        /* When the source expression has a value-semantics type (tuple or
         * @value), the @iterable method expects a pointer self parameter,
         * but the expression is a struct value (rvalue).  Materialize to
         * a local so we can take its address. */
        bool src_is_value = src.type != NULL &&
            src.type->kind == CG_TYPE_OBJECT &&
            src.type->user != NULL &&
            cg_user_type_is_value_semantics(src.type->user);
        const char *src_addr = "";
        if (src_is_value) {
            cg_materialize_to_local(cg, &src, "_isrc");
            src_addr = "&";
        }

        /* Call @iterable: cursor = src.iterable_method() */
        cursor_var = cg_fresh_temp(cg, "_cursor");
        if (!cursor_var) {
            er_free(&src);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        char *cursor_cty = cg_ctype_dup(iterable_um->return_type);
        if (!cursor_cty) {
            free(cursor_var);
            er_free(&src);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }

        /* Preserve the resolved cursor type so synthetic return storage uses
         * the same fixed/reified representation rules as ordinary calls. */
        CGType *cursor_cgtype = cgtype_clone(iterable_um->return_type);
        cursor_uses_reified_storage =
            cg_type_uses_reified_storage(cg, cursor_cgtype);
        if (iterable_is_builtin_fit) {
            if (cursor_uses_reified_storage) {
                free(cursor_cty); free(cursor_var);
                cgtype_free(cursor_cgtype);
                er_free(&src);
                cg_release_scope(cg, outer_scope);
                cg->cur_scope = outer_scope->parent;
                scope_pop_free(outer_scope);
                return cg_fail(cg, stmt->token,
                    "IE0001", "codegen: reified iterable cursor requires an out-parameter call");
            }
            buf_append_fmt(cg->cur_body,
                "    %s %s = %s(%s%s, "
                "&(const FengFunctionDescriptor){.name = \"%s\"});\n",
                cursor_cty, cursor_var, iterable_um->c_name, src_addr, src.c_expr,
                iterable_um->feng_name);
        } else if (cg->in_generic_fn && src_ut != NULL &&
                   src_ut->generic_context_type_param_count > 0U) {
            /* Shared body cross-type call: iter() on another generic type.
             * Use the target's shared body name and calling convention. */
            char *shared_iter = iterable_user_fit != NULL
                ? cg_fit_method_shared_cname(
                      cg, iterable_user_fit, iterable_method)
                : cg_generic_type_method_shared_cname(
                      cg, src_ut->generic_origin_decl, iterable_method);
            char *rtd_expr = cg_rtd_expr_for_type(cg, src_ut, stmt->token);
            const FengSemanticTypeFact *source_fact =
                feng_semantic_lookup_type_fact(
                    cg->analysis, stmt->as.for_stmt.iter_expr);
            char *func_desc_expr = cg_for_in_method_descriptor_expr(
                cg,
                src_ut,
                iterable_user_fit,
                iterable_method,
                source_fact != NULL &&
                        source_fact->kind ==
                            FENG_SEMANTIC_TYPE_FACT_TYPE_REF
                    ? source_fact->type_ref
                    : NULL,
                stmt->token);
            if (!shared_iter || !rtd_expr || !func_desc_expr) {
                free(shared_iter);
                free(rtd_expr);
                free(func_desc_expr);
                free(cursor_cty); free(cursor_var);
                er_free(&src);
                cg_release_scope(cg, outer_scope);
                cg->cur_scope = outer_scope->parent;
                scope_pop_free(outer_scope);
                return false;
            }
            if (cursor_uses_reified_storage) {
                char *cursor_descriptor_name = NULL;
                char *cursor_size_name = NULL;

                if (!cg_emit_reified_storage_declaration(
                        cg,
                        cursor_cgtype,
                        cursor_var,
                        stmt->token,
                        &cursor_descriptor_name,
                        &cursor_size_name)) {
                    free(shared_iter);
                    free(rtd_expr);
                    free(func_desc_expr);
                    free(cursor_cty); free(cursor_var);
                    cgtype_free(cursor_cgtype);
                    er_free(&src);
                    cg_release_scope(cg, outer_scope);
                    cg->cur_scope = outer_scope->parent;
                    scope_pop_free(outer_scope);
                    return false;
                }
                buf_append_fmt(cg->cur_body,
                    "    %s((void *)%s%s, %s, %s, %s);\n",
                    shared_iter, src_addr, src.c_expr, rtd_expr,
                    func_desc_expr, cursor_var);
                if (!scope_add(cg->cur_scope,
                               cursor_var,
                               cursor_var,
                               cursor_cgtype,
                               false) ||
                    !scope_mark_last_reified_storage(
                        cg->cur_scope,
                        cursor_descriptor_name,
                        cursor_size_name)) {
                    free(cursor_descriptor_name);
                    free(cursor_size_name);
                    free(shared_iter);
                    free(rtd_expr);
                    free(func_desc_expr);
                    free(cursor_cty); free(cursor_var);
                    er_free(&src);
                    cg_release_scope(cg, outer_scope);
                    cg->cur_scope = outer_scope->parent;
                    scope_pop_free(outer_scope);
                    return cg_fail(cg, stmt->token,
                        "IE0001", "codegen: out of memory");
                }
                cg_emit_cleanup_push_for_reified_aggregate_storage(
                    cg,
                    cursor_var,
                    cursor_descriptor_name);
                free(cursor_descriptor_name);
                free(cursor_size_name);
                cursor_cgtype = NULL;
            } else {
                buf_append_fmt(cg->cur_body,
                    "    %s %s; %s((void *)%s%s, %s, %s, &%s);\n",
                    cursor_cty, cursor_var,
                    shared_iter, src_addr, src.c_expr, rtd_expr,
                    func_desc_expr, cursor_var);
            }
            free(shared_iter);
            free(rtd_expr);
            free(func_desc_expr);
        } else {
            if (cursor_uses_reified_storage) {
                free(cursor_cty); free(cursor_var);
                cgtype_free(cursor_cgtype);
                er_free(&src);
                cg_release_scope(cg, outer_scope);
                cg->cur_scope = outer_scope->parent;
                scope_pop_free(outer_scope);
                return cg_fail(cg, stmt->token,
                    "IE0001", "codegen: reified iterable cursor requires a shared out-parameter call");
            }
            Buf iter_call; buf_init(&iter_call);
            buf_append_fmt(&iter_call, "%s(%s%s", iterable_um->c_name, src_addr, src.c_expr);
            if (!cg_append_user_type_context_descriptor_args(
                    cg, &iter_call, src_ut, stmt->token)) {
                buf_free(&iter_call);
                free(cursor_cty); free(cursor_var);
                er_free(&src);
                cg_release_scope(cg, outer_scope);
                cg->cur_scope = outer_scope->parent;
                scope_pop_free(outer_scope);
                return false;
            }
            buf_append_cstr(&iter_call, ")");
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n",
                           cursor_cty, cursor_var, iter_call.data);
            buf_free(&iter_call);
        }
        free(cursor_cty);
        er_free(&src);

        /* Register cursor in scope for cleanup. */
        if (cursor_cgtype == NULL) {
            /* Descriptor-sized cursor storage was registered at declaration. */
        } else if (cgtype_is_managed(cursor_cgtype)) {
            scope_add(cg->cur_scope, cursor_var, cursor_var, cursor_cgtype, false);
            cg_emit_cleanup_push_for_managed_local(cg, cursor_var);
        } else if (cgtype_is_aggregate(cursor_cgtype)) {
            scope_add(cg->cur_scope, cursor_var, cursor_var, cursor_cgtype, false);
            cg_emit_cleanup_push_for_aggregate_local(cg, cursor_var, cursor_cgtype);
        } else {
            cgtype_free(cursor_cgtype);
        }
    } else {
        /* Self-cursor: the source expression itself is the cursor. */
        cursor_ut = src.type != NULL ? src.type->user : NULL;
        if (!cursor_ut) {
            cursor_ut = cg_find_user_type_by_decl(cg, cursor_type_decl);
        }
        if (!cursor_ut) {
            er_free(&src);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "CE0274", "codegen: iterator cursor type not found");
        }
        iter_um = cg_user_type_method_by_member(cursor_ut, iterator_method);
        if (!iter_um) {
            for (size_t fit_index = 0U;
                 fit_index < cg->user_fit_count;
                 ++fit_index) {
                iter_um = cg_user_fit_method_by_member(
                    &cg->user_fits[fit_index], iterator_method);
                if (iter_um != NULL) {
                    iterator_user_fit = &cg->user_fits[fit_index];
                    break;
                }
            }
        }
        if (!iter_um) {
            er_free(&src);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "CE0275", "codegen: @iterator method not found on cursor type");
        }
        if (cgtype_is_managed(src.type) && src.owns_ref) {
            cursor_var = cg_materialize_to_local(cg, &src, "_cursor");
        } else if (cgtype_is_managed(src.type)) {
            cursor_var = cg_fresh_temp(cg, "_cursor");
            if (cursor_var) {
                buf_append_fmt(cg->cur_body,
                    "    struct %s *%s = %s; feng_retain(%s);\n",
                    cursor_ut->c_struct_name, cursor_var, src.c_expr, cursor_var);
                scope_add(cg->cur_scope, cursor_var, cursor_var,
                          cgtype_clone(src.type), false);
                cg_emit_cleanup_push_for_managed_local(cg, cursor_var);
            }
            er_free(&src);
        } else {
            cursor_var = cg_materialize_to_local(cg, &src, "_cursor");
        }
        if (!cursor_var) {
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
    }

    /* Get the result type from iter_um's resolved return type. The type may
     * still reference the active shared-body parameters; storage below must
     * therefore distinguish fixed layout from descriptor-sized layout. */
    CGType *result_type = cgtype_clone(iter_um->return_type);
    if (!result_type) {
        free(cursor_var);
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }

    /* Get the tuple UserType for the result to access field names. */
    const UserType *result_ut = result_type->user;
    if (!result_ut || result_ut->field_count < 2U) {
        cgtype_free(result_type);
        free(cursor_var);
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token,
            "CE0276", "codegen: @iterator return type must be a 2-field tuple");
    }

    const UserField *bool_field = &result_ut->fields[0];
    const UserField *elem_field = &result_ut->fields[1];
    CGType *element_type = cgtype_clone(elem_field->type);
    char *result_cty = cg_ctype_dup(result_type);

    if (!element_type || !result_cty) {
        free(result_cty);
        cgtype_free(element_type);
        cgtype_free(result_type);
        free(cursor_var);
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }

    bool result_needs_reified_layout =
        cg_value_needs_reified_layout(cg, result_type);
    bool result_uses_reified_storage =
        cg_type_uses_reified_storage(cg, result_type);
    char *result_descriptor_name = NULL;
    char *result_size_name = NULL;
    if (result_uses_reified_storage) {
        char *result_descriptor_expr =
            cg_reified_aggregate_descriptor_expr_dup(
                cg, result_type, stmt->token);
        result_descriptor_name = cg_fresh_temp(cg, "_rad");
        result_size_name = cg_fresh_temp(cg, "_rsize");
        if (result_descriptor_expr == NULL ||
            result_descriptor_name == NULL || result_size_name == NULL) {
            free(result_descriptor_expr);
            free(result_descriptor_name);
            free(result_size_name);
            free(result_cty);
            cgtype_free(element_type);
            cgtype_free(result_type);
            free(cursor_var);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            if (!cg->failed) {
                return cg_fail(cg, stmt->token,
                    "IE0001", "codegen: out of memory");
            }
            return false;
        }
        cg_emit_current_stmt_line_directive_force(cg);
        buf_append_fmt(cg->cur_body,
            "    const FengAggregateDescriptor *%s = %s;\n"
            "    const size_t %s = %s->size;\n",
            result_descriptor_name,
            result_descriptor_expr,
            result_size_name,
            result_descriptor_name);
        free(result_descriptor_expr);
    }

    /* Begin the loop. */
    buf_append_cstr(cg->cur_body, "    for (;;) {\n");

    /* Keep the result tuple, loop binding, and user body in one nested C
     * block. The continue label below must remain outside the block because
     * generic body expressions can declare descriptor-sized VLAs. */
    buf_append_cstr(cg->cur_body, "        {\n");

    /* Body scope: loop scope, hosts per-iteration bindings. */
    cg->loop_depth++;
    Scope *body_scope = scope_push(cg->cur_scope);
    if (!body_scope) {
        free(result_cty); cgtype_free(element_type); cgtype_free(result_type);
        free(result_descriptor_name); free(result_size_name);
        free(cursor_var);
        cg->loop_depth--;
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }
    body_scope->is_loop = true;
    body_scope->try_depth_at_entry = cg->try_depth;
    char *cont_label_owned = strdup(cont_label);
    body_scope->continue_label = cont_label_owned;
    cg->cur_scope = body_scope;

    /* Call @iterator: result = cursor.next(). Fixed @value cursors need an
     * address-of self; descriptor-sized cursor storage already is an address. */
    char *result_var = cg_fresh_temp(cg, "_ir");
    const char *cursor_addr = (cursor_ut != NULL &&
                               cg_user_type_is_value_semantics(cursor_ut) &&
                               !cursor_uses_reified_storage)
                                  ? "&" : "";
    if (result_var == NULL) {
        free(result_cty);
        free(result_descriptor_name); free(result_size_name);
        cgtype_free(element_type); cgtype_free(result_type);
        free(cont_label_owned);
        body_scope->continue_label = NULL;
        cg->cur_scope = body_scope->parent;
        scope_pop_free(body_scope);
        free(cursor_var);
        cg->loop_depth--;
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token,
            "IE0001", "codegen: out of memory");
    }
    if (cg->in_generic_fn && cursor_ut != NULL &&
        cursor_ut->generic_context_type_param_count > 0U) {
        /* Shared body cross-type call for next(). */
        char *shared_next = iterator_user_fit != NULL
            ? cg_fit_method_shared_cname(
                  cg, iterator_user_fit, iterator_method)
            : cg_generic_type_method_shared_cname(
                  cg, cursor_ut->generic_origin_decl, iterator_method);
        char *rtd_expr = cg_rtd_expr_for_type(cg, cursor_ut, stmt->token);
        char *func_desc_expr = cg_for_in_method_descriptor_expr(
            cg,
            cursor_ut,
            iterator_user_fit,
            iterator_method,
            stmt->as.for_stmt.iter_cursor_type_ref,
            stmt->token);
        if (!shared_next || !rtd_expr || !func_desc_expr) {
            free(shared_next);
            free(rtd_expr);
            free(func_desc_expr);
            free(result_var); free(result_cty);
            free(result_descriptor_name); free(result_size_name);
            cgtype_free(element_type); cgtype_free(result_type);
            free(cont_label_owned);
            body_scope->continue_label = NULL;
            cg->cur_scope = body_scope->parent;
            scope_pop_free(body_scope);
            free(cursor_var);
            cg->loop_depth--;
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        if (result_uses_reified_storage) {
            buf_append_fmt(cg->cur_body,
                "        _Alignas(max_align_t) char %s[%s];\n"
                "        memset(%s, 0, %s);\n"
                "        %s((void *)%s%s, %s, %s, %s);\n",
                result_var, result_size_name,
                result_var, result_size_name,
                shared_next, cursor_addr, cursor_var, rtd_expr,
                func_desc_expr, result_var);
        } else {
            buf_append_fmt(cg->cur_body,
                "        %s %s; %s((void *)%s%s, %s, %s, &%s);\n",
                result_cty, result_var,
                shared_next, cursor_addr, cursor_var, rtd_expr,
                func_desc_expr, result_var);
        }
        free(shared_next);
        free(rtd_expr);
        free(func_desc_expr);
    } else {
        if (result_uses_reified_storage) {
            free(result_var); free(result_cty);
            free(result_descriptor_name); free(result_size_name);
            cgtype_free(element_type); cgtype_free(result_type);
            free(cont_label_owned);
            body_scope->continue_label = NULL;
            cg->cur_scope = body_scope->parent;
            scope_pop_free(body_scope);
            free(cursor_var);
            cg->loop_depth--;
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "IE0001", "codegen: reified iterator result requires a shared out-parameter call");
        }
        Buf next_call; buf_init(&next_call);
        buf_append_fmt(&next_call, "%s(%s%s", iter_um->c_name, cursor_addr, cursor_var);
        if (!cg_append_user_type_context_descriptor_args(
                cg, &next_call, cursor_ut, stmt->token)) {
            buf_free(&next_call);
            free(result_var); free(result_cty);
            free(result_descriptor_name); free(result_size_name);
            cgtype_free(element_type); cgtype_free(result_type);
            free(cont_label_owned);
            body_scope->continue_label = NULL;
            cg->cur_scope = body_scope->parent;
            scope_pop_free(body_scope);
            free(cursor_var);
            cg->loop_depth--;
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        buf_append_cstr(&next_call, ")");
        buf_append_fmt(cg->cur_body, "        %s %s = %s;\n",
                       result_cty, result_var, next_call.data);
        buf_free(&next_call);
    }

    /* Register result tuple for aggregate cleanup if needed. */
    if (result_uses_reified_storage) {
        if (!scope_add(cg->cur_scope, result_var, result_var,
                       cgtype_clone(result_type), false) ||
            !scope_mark_last_reified_storage(cg->cur_scope,
                                             result_descriptor_name,
                                             result_size_name)) {
            free(result_var); free(result_cty);
            free(result_descriptor_name); free(result_size_name);
            cgtype_free(element_type); cgtype_free(result_type);
            free(cont_label_owned);
            body_scope->continue_label = NULL;
            cg->cur_scope = body_scope->parent;
            scope_pop_free(body_scope);
            free(cursor_var);
            cg->loop_depth--;
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(cg, stmt->token,
                "IE0001", "codegen: out of memory");
        }
        cg_emit_cleanup_push_for_reified_aggregate_storage(
            cg, result_var, result_descriptor_name);
    } else if (cgtype_is_aggregate(result_type)) {
        scope_add(cg->cur_scope, result_var, result_var,
                  cgtype_clone(result_type), false);
        cg_emit_cleanup_push_for_aggregate_local(cg, result_var, result_type);
    }

    /* Check termination: if (!result.item1) { release + pop + break; } */
    if (result_uses_reified_storage) {
        buf_append_fmt(cg->cur_body,
            "        if (!(*(bool *)((char *)%s + "
            "%s->reified_field_offsets[0]))) { ",
            result_var, result_descriptor_name);
    } else {
        buf_append_fmt(cg->cur_body, "        if (!%s.%s) { ",
                       result_var, bool_field->c_name);
    }
    if (result_uses_reified_storage) {
        buf_append_fmt(cg->cur_body,
            "feng_cleanup_pop(); feng_aggregate_release(%s, %s); "
            "memset(%s, 0, %s); ",
            result_var, result_descriptor_name,
            result_var, result_size_name);
    } else if (result_needs_reified_layout) {
        /* Fixed-size aggregate whose managed-slot authority still depends on
         * the closed generic instance. Its C storage is static, but cleanup
         * must use the reified aggregate descriptor. */
        const char *aggregate_name = cg_aggregate_desc_name(result_type);
        size_t aggregate_index;

        if (aggregate_name != NULL &&
            cg_lookup_reified_agg_dep_index(
                cg, aggregate_name, &aggregate_index)) {
            const char *source = cg->generic_type_method_rad_via_desc
                                     ? "_desc"
                                     : "_td";
            buf_append_fmt(cg->cur_body,
                "feng_cleanup_pop(); feng_aggregate_release(&%s, "
                "(const FengAggregateDescriptor *)%s->reified_agg_deps[%zu]); "
                "memset(&%s, 0, sizeof %s); ",
                result_var, source, aggregate_index,
                result_var, result_var);
        }
    } else if (cgtype_is_aggregate(result_type)) {
        /* Static aggregate: pop correct number of cleanup nodes, release
         * via static descriptor, zero managed slots. */
        const char *desc = cg_aggregate_desc_name(result_type);
        if (desc) {
            buf_append_fmt(cg->cur_body,
                "feng_aggregate_release(&%s, &%s); ", result_var, desc);
        }
        cg_emit_cleanup_pops_for_aggregate_local(cg->cur_body, result_type);
        cg_emit_cleanup_zero_for_aggregate_local(cg->cur_body, result_var,
                                                 result_type);
    }
    buf_append_cstr(cg->cur_body, "break; }\n");

    /* Bind the current element through the same per-iteration lowering used
     * by the array path. Fixed-layout fields are value expressions; erased
     * or descriptor-sized fields remain address expressions. */
    {
        const FengBinding *binding = &stmt->as.for_stmt.iter_binding;
        Buf element_source;
        bool source_is_address =
            result_uses_reified_storage ||
            element_type->kind == CG_TYPE_GENERIC_PARAM ||
            cg_type_uses_reified_storage(cg, element_type);

        buf_init(&element_source);
        if (result_uses_reified_storage) {
            buf_append_fmt(&element_source,
                "(void *)((char *)%s + %s->reified_field_offsets[1])",
                result_var, result_descriptor_name);
        } else if (source_is_address) {
            buf_append_fmt(&element_source,
                           "(void *)&%s.%s",
                           result_var,
                           elem_field->c_name);
        } else {
            buf_append_fmt(&element_source,
                           "%s.%s",
                           result_var,
                           elem_field->c_name);
        }
        if (element_source.data == NULL ||
            !cg_emit_loop_binding_pattern_from_borrowed_source(
                cg,
                binding,
                element_type,
                element_source.data,
                source_is_address)) {
            buf_free(&element_source);
            free(result_var); free(result_cty);
            free(result_descriptor_name); free(result_size_name);
            cgtype_free(element_type); cgtype_free(result_type);
            free(cont_label_owned);
            body_scope->continue_label = NULL;
            cg->cur_scope = body_scope->parent;
            scope_pop_free(body_scope);
            free(cursor_var);
            cg->loop_depth--;
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        buf_free(&element_source);
    }

    /* Emit loop body. */
    if (!cg_emit_block(cg, stmt->as.for_stmt.body)) {
        body_scope->continue_label = NULL;
        cg->cur_scope = body_scope->parent;
        scope_pop_free(body_scope);
        free(cont_label_owned);
        free(result_var); free(result_cty);
        free(result_descriptor_name); free(result_size_name);
        cgtype_free(element_type); cgtype_free(result_type);
        free(cursor_var);
        cg->loop_depth--;
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }

    cg_release_scope(cg, body_scope);
    buf_append_cstr(cg->cur_body, "        }\n");
    body_scope->continue_label = NULL;
    cg->cur_scope = body_scope->parent;
    scope_pop_free(body_scope);
    free(cont_label_owned);
    cg->loop_depth--;

    /* Continue label and loop end. */
    buf_append_fmt(cg->cur_body, "        %s: ;\n", cont_label);
    buf_append_cstr(cg->cur_body, "    }\n");

    free(result_var); free(result_cty);
    free(result_descriptor_name); free(result_size_name);
    cgtype_free(element_type); cgtype_free(result_type);
    free(cursor_var);

    cg_release_scope(cg, outer_scope);
    cg->cur_scope = outer_scope->parent;
    scope_pop_free(outer_scope);
    buf_append_cstr(cg->cur_body, "    }\n");
    return true;
}

static bool cg_emit_for_in(CG *cg, const FengStmt *stmt) {
    /* Dispatch to iterator protocol path if semantic resolved @iterator. */
    if (stmt->as.for_stmt.iter_iterator_method != NULL) {
        return cg_emit_for_in_iterator(cg, stmt);
    }

    int id = cg->label_counter++;
    char cont_label[64];
    snprintf(cont_label, sizeof cont_label, "_cont_%d", id);

    buf_append_cstr(cg->cur_body, "    {\n");

    /* Outer scope: holds the materialised iteration sequence (so its +1
     * reference outlives the loop) and the loop index. */
    Scope *outer_scope = scope_push(cg->cur_scope);
    if (!outer_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    cg->cur_scope = outer_scope;

    ExprResult seq;
    if (!cg_emit_expr(cg, stmt->as.for_stmt.iter_expr, &seq)) {
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }
    if (seq.type->kind != CG_TYPE_ARRAY || seq.type->element == NULL) {
        er_free(&seq);
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token,
            "CE0277", "codegen: for/in sequence must be an array");
    }
    /* Stash the element type before materialise possibly invalidates seq.type's
     * lifetime via cgtype clone semantics. cg_materialize_to_local hands
     * ownership of the type to the scope's Local. */
    CGType *element_type = cgtype_clone(seq.type->element);
    if (!element_type) {
        er_free(&seq);
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }
    /* Materialise the sequence into a local that owns +1 if it's an owning
     * temp; if it was borrowed (e.g. a bound var read), we still hold the
     * borrow for the loop's lifetime — but to be safe across mutation we
     * retain into a fresh slot. */
    char *seq_tmp;
    if (seq.owns_ref) {
        seq_tmp = cg_materialize_to_local(cg, &seq, "_fseq");
    } else {
        /* Borrowed: retain into a managed local so a subsequent re-assignment
         * to the source variable does not drop the array we are iterating. */
        seq_tmp = cg_fresh_temp(cg, "_fseq");
        if (seq_tmp) {
            buf_append_fmt(cg->cur_body,
                "    FengArray *%s = %s; feng_retain(%s);\n",
                seq_tmp, seq.c_expr, seq_tmp);
            scope_add(cg->cur_scope, seq_tmp, seq_tmp,
                      cgtype_clone(seq.type), false);
            cg_emit_cleanup_push_for_managed_local(cg, seq_tmp);
        }
        er_free(&seq);
    }
    if (!seq_tmp) {
        cgtype_free(element_type);
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }

    char *idx_var = cg_fresh_temp(cg, "_fidx");
    buf_append_fmt(cg->cur_body, "    size_t %s = 0;\n", idx_var);

    /* A shared T[] body cannot form a C element lvalue because T has no
     * fixed C size. Cache the descriptor-selected element size once per
     * traversal, then bind each iteration to the corresponding storage
     * address. The binding remains a borrowed generic-value address. */
    const char *generic_element_desc = NULL;
    char generic_element_size[64] = {0};
    if (element_type->kind == CG_TYPE_GENERIC_PARAM) {
        generic_element_desc = cg_generic_param_desc_name(
            cg, element_type->generic_param_index);
        if (generic_element_desc == NULL) {
            free(idx_var); free(seq_tmp); cgtype_free(element_type);
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return cg_fail(
                cg,
                stmt->token,
                "IE0001",
                "codegen: generic for-in array element requires an active descriptor");
        }
        snprintf(generic_element_size,
                 sizeof generic_element_size,
                 "_felem_size_%d",
                 id);
        buf_append_fmt(cg->cur_body,
                       "    const size_t %s = feng_generic_value_size(%s);\n",
                       generic_element_size,
                       generic_element_desc);
    }

    buf_append_cstr(cg->cur_body, "    for (;;) {\n");
    buf_append_fmt(cg->cur_body,
                   "        if (%s >= feng_array_length(%s)) break;\n",
                   idx_var, seq_tmp);

    /* The loop binding and body may contain descriptor-sized VLAs. Keep
     * them in a nested block so goto-based continue exits their scope before
     * reaching the index-update label. */
    buf_append_cstr(cg->cur_body, "        {\n");

    /* Body scope: loop scope, hosts the per-iteration iter binding. */
    cg->loop_depth++;
    Scope *body_scope = scope_push(cg->cur_scope);
    if (!body_scope) {
        free(idx_var); free(seq_tmp); cgtype_free(element_type);
        cg->loop_depth--;
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }
    body_scope->is_loop = true;
    body_scope->try_depth_at_entry = cg->try_depth;
    char *cont_label_owned = strdup(cont_label);
    body_scope->continue_label = cont_label_owned;
    cg->cur_scope = body_scope;

    /* Build the current array element source, then use the same binding
     * lowering as iterator-protocol loops. Descriptor-sized array elements
     * use byte addressing; ordinary fixed-layout elements remain lvalues. */
    {
        const FengBinding *binding = &stmt->as.for_stmt.iter_binding;
        Buf element_source;
        char *element_c_type = cg_ctype_dup(element_type);
        bool source_is_address = false;

        buf_init(&element_source);
        if (element_type->kind == CG_TYPE_GENERIC_PARAM) {
            source_is_address = true;
            buf_append_fmt(
                &element_source,
                "(void *)((char *)feng_array_data(%s) + (%s) * %s)",
                seq_tmp,
                idx_var,
                generic_element_size);
        } else if (cgtype_is_aggregate(element_type)) {
            const char *aggregate_name =
                cg_aggregate_desc_name(element_type);
            size_t aggregate_index;

            if (aggregate_name != NULL &&
                cg_lookup_reified_agg_dep_index(
                    cg, aggregate_name, &aggregate_index)) {
                const char *source = cg->generic_type_method_rad_via_desc
                                         ? "_desc"
                                         : "_td";
                source_is_address = true;
                buf_append_fmt(
                    &element_source,
                    "(void *)((char *)feng_array_data(%s) + (%s) * "
                    "%s->reified_agg_deps[%zu]->size)",
                    seq_tmp,
                    idx_var,
                    source,
                    aggregate_index);
            } else if (element_c_type != NULL) {
                buf_append_fmt(&element_source,
                               "((%s *)feng_array_data(%s))[%s]",
                               element_c_type,
                               seq_tmp,
                               idx_var);
            }
        } else if (element_c_type != NULL) {
            buf_append_fmt(&element_source,
                           "((%s *)feng_array_data(%s))[%s]",
                           element_c_type,
                           seq_tmp,
                           idx_var);
        }
        if (element_c_type == NULL || element_source.data == NULL ||
            !cg_emit_loop_binding_pattern_from_borrowed_source(
                cg,
                binding,
                element_type,
                element_source.data,
                source_is_address)) {
            free(element_c_type);
            buf_free(&element_source);
            free(cont_label_owned);
            body_scope->continue_label = NULL;
            cg->cur_scope = body_scope->parent;
            scope_pop_free(body_scope);
            free(idx_var); free(seq_tmp); cgtype_free(element_type);
            cg->loop_depth--;
            cg_release_scope(cg, outer_scope);
            cg->cur_scope = outer_scope->parent;
            scope_pop_free(outer_scope);
            return false;
        }
        free(element_c_type);
        buf_free(&element_source);
    }

    if (!cg_emit_block(cg, stmt->as.for_stmt.body)) {
        body_scope->continue_label = NULL;
        cg->cur_scope = body_scope->parent;
        scope_pop_free(body_scope);
        free(cont_label_owned);
        free(idx_var); free(seq_tmp); cgtype_free(element_type);
        cg->loop_depth--;
        cg_release_scope(cg, outer_scope);
        cg->cur_scope = outer_scope->parent;
        scope_pop_free(outer_scope);
        return false;
    }
    cg_release_scope(cg, body_scope);
    buf_append_cstr(cg->cur_body, "        }\n");
    body_scope->continue_label = NULL;
    cg->cur_scope = body_scope->parent;
    scope_pop_free(body_scope);
    free(cont_label_owned);
    cg->loop_depth--;

    /* Continue label: lands here after body, before index advance. */
    buf_append_fmt(cg->cur_body, "        %s: ;\n", cont_label);
    buf_append_fmt(cg->cur_body, "        %s++;\n", idx_var);
    buf_append_cstr(cg->cur_body, "    }\n");

    free(idx_var); free(seq_tmp); cgtype_free(element_type);

    cg_release_scope(cg, outer_scope);
    cg->cur_scope = outer_scope->parent;
    scope_pop_free(outer_scope);
    buf_append_cstr(cg->cur_body, "    }\n");
    return true;
}

static bool cg_emit_for(CG *cg, const FengStmt *stmt) {
    if (stmt->as.for_stmt.is_for_in) {
        return cg_emit_for_in(cg, stmt);
    }
    return cg_emit_for_three(cg, stmt);
}

static bool cg_emit_break_continue(CG *cg, const FengStmt *stmt, bool is_break) {
    if (cg->loop_depth == 0) {
        return cg_fail(cg, stmt->token,
            "CE0279", "codegen: '%s' outside of loop", is_break ? "break" : "continue");
    }
    /* Release scopes up to (but not including) the nearest loop scope. */
    const Scope *stop = NULL;
    for (const Scope *s = cg->cur_scope; s; s = s->parent) {
        if (s->is_loop) { stop = s; break; }
    }
    cg_release_through(cg, stop);
    /* Also release the loop scope itself: the C `break;` / `continue;` (or
     * the `goto _cont_N;` for three-clause `for`) jumps past the body's
     * closing brace, which is where the body-scope releases would otherwise
     * be emitted. Without this, any managed local declared at body-level
     * would leak (and unbalance the per-thread cleanup chain) on the
     * break / continue path. The normal end-of-iteration release path is
     * mutually exclusive with these jumps, so the slot is released exactly
     * once on every control-flow path. */
    if (stop != NULL) {
        cg_release_scope(cg, stop);
    }
    cg_emit_control_cleanup_to_try_depth(cg,
                                         stop != NULL ? stop->try_depth_at_entry : 0);
    if (!is_break && stop != NULL && stop->continue_label != NULL) {
        buf_append_fmt(cg->cur_body, "    goto %s;\n", stop->continue_label);
    } else {
        buf_append_fmt(cg->cur_body, "    %s;\n", is_break ? "break" : "continue");
    }
    return true;
}

static bool cg_emit_try_stmt(CG *cg, const FengStmt *stmt) {
    /* Open a fresh inner scope so any +1 temporaries are released at the
     * statement boundary (mirrors cg_emit_expr_stmt). */
    Scope *st_scope = scope_push(cg->cur_scope);
    if (!st_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    cg->cur_scope = st_scope;
    buf_append_cstr(cg->cur_body, "    {\n");
    ExprResult r;
    if (!cg_emit_try_expr(cg, stmt->as.expr, &r, false)) {
        cg->cur_scope = st_scope->parent;
        scope_pop_free(st_scope);
        return false;
    }
    if (cgtype_is_managed(r.type) && r.owns_ref) {
        cg_materialize_to_local(cg, &r, "_t");
    } else {
        buf_append_fmt(cg->cur_body, "    (void)(%s);\n", r.c_expr);
    }
    er_free(&r);
    cg_release_scope(cg, st_scope);
    cg->cur_scope = st_scope->parent;
    scope_pop_free(st_scope);
    buf_append_cstr(cg->cur_body, "    }\n");
    return true;
}

static bool cg_emit_expr_stmt(CG *cg, const FengStmt *stmt) {
    /* Open a fresh inner scope so any +1 temporaries from the expression
     * are released at the statement boundary. */
    Scope *st_scope = scope_push(cg->cur_scope);
    if (!st_scope) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    cg->cur_scope = st_scope;
    buf_append_cstr(cg->cur_body, "    {\n");
    ExprResult r;
    if (!cg_emit_expr(cg, stmt->as.expr, &r)) {
        cg->cur_scope = st_scope->parent;
        scope_pop_free(st_scope);
        return false;
    }
    /* Materialise managed +1 results into a temp so they're released. */
    if (cgtype_is_managed(r.type) && r.owns_ref) {
        cg_materialize_to_local(cg, &r, "_t");
    } else if (cgtype_is_aggregate(r.type) && r.owns_ref) {
        cg_materialize_to_local(cg, &r, "_t");
    } else {
        buf_append_fmt(cg->cur_body, "    (void)(%s);\n", r.c_expr);
    }
    er_free(&r);
    cg_release_scope(cg, st_scope);
    cg->cur_scope = st_scope->parent;
    scope_pop_free(st_scope);
    buf_append_cstr(cg->cur_body, "    }\n");
    return true;
}

static bool cg_exception_descriptor_expr_for_type(CG *cg,
                                                  const CGType *type,
                                                  FengToken token,
                                                  char **out_expr) {
    Buf b;

    if (out_expr == NULL) {
        return false;
    }
    *out_expr = NULL;
    if (type == NULL) {
        return cg_fail(cg, token, "CE0280", "codegen: missing exception payload type");
    }

    if (cg_type_has_value_box(type)) {
        CGValueBoxInfo box_info;

        if (!cg_value_box_info_for_type(cg, type, token, &box_info)) {
            return false;
        }
        buf_init(&b);
        buf_append_fmt(&b, "&%s", box_info.descriptor_name);
        cg_value_box_info_dispose(&box_info);
        *out_expr = b.data;
        return *out_expr != NULL;
    }

    switch (type->kind) {
        case CG_TYPE_STRING:
            *out_expr = strdup("&feng_string_descriptor");
            return *out_expr != NULL;
        case CG_TYPE_ARRAY:
            return cg_fail(cg, token,
                           "CE0282", "codegen: array is not a supported exception payload type");
        case CG_TYPE_OBJECT:
            if (type->user == NULL || type->user->c_desc_name == NULL) {
                return cg_fail(cg, token,
                               "CE0281", "codegen: object exception payload is missing a descriptor");
            }
            buf_init(&b);
            buf_append_fmt(&b, "&%s", type->user->c_desc_name);
            *out_expr = b.data;
            return *out_expr != NULL;
        default:
            return cg_fail(cg, token,
                           "CE0282", "codegen: unsupported exception payload type");
    }
}

static bool cg_expr_is_unknown_exception_identifier(CG *cg, const FengExpr *expr) {
    const Local *local;

    if (expr == NULL || expr->kind != FENG_EXPR_IDENTIFIER) {
        return false;
    }
    local = scope_lookup(cg->cur_scope, expr->as.identifier.data, expr->as.identifier.length);
    return local != NULL && local->is_unknown_exception;
}

/* Emit a throw whose managed value and descriptor describe the same object.
 * Concrete value types use ValueBox<T>; string and reference-object payloads
 * retain and transfer their existing managed pointer. */
static bool cg_emit_throw(CG *cg, const FengStmt *stmt) {
    if (stmt->as.throw_value == NULL) {
        return cg_fail(cg, stmt->token,
            "CE0283", "codegen: 'throw' requires a value");
    }
    if (cg_expr_is_unknown_exception_identifier(cg, stmt->as.throw_value)) {
        buf_append_cstr(cg->cur_body, "    feng_rethrow();\n");
        return true;
    }
    ExprResult r;
    if (!cg_emit_expr(cg, stmt->as.throw_value, &r)) return false;

    /* Semantic rejects every spec form. Keep this guard so malformed analysis
     * input cannot reach representation-specific subject extraction. */
    if (r.type->kind == CG_TYPE_SPEC) {
        er_free(&r);
        return cg_fail(cg, stmt->token,
                       "CE0284", "codegen: spec is not a supported exception payload type");
    }

    if (cg_type_has_value_box(r.type)) {
        char *box_tmp = NULL;
        char *desc_expr = NULL;

        if (!cg_exception_descriptor_expr_for_type(cg,
                                                   r.type,
                                                   stmt->token,
                                                   &desc_expr) ||
            !cg_emit_value_box_subject(cg,
                                       &r,
                                       stmt->token,
                                       &box_tmp)) {
            free(box_tmp);
            free(desc_expr);
            er_free(&r);
            return false;
        }
        buf_append_fmt(cg->cur_body,
                       "    feng_throw((void *)%s, %s);\n",
                       box_tmp,
                       desc_expr);
        free(box_tmp);
        free(desc_expr);
        er_free(&r);
        return true;
    }

    char *desc_expr = NULL;
    if (!cg_exception_descriptor_expr_for_type(cg, r.type, stmt->token, &desc_expr)) {
        er_free(&r);
        return false;
    }
    char *tmp = cg_fresh_temp(cg, "_thr");
    if (tmp == NULL) {
        free(desc_expr);
        er_free(&r);
        return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
    }
    {
        char *cty = cg_ctype_dup(r.type);
        if (cty == NULL) {
            free(tmp);
            free(desc_expr);
            er_free(&r);
            return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
        }
        if (r.owns_ref) {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, r.c_expr);
        } else {
            buf_append_fmt(cg->cur_body, "    %s %s = %s; feng_retain(%s);\n",
                           cty, tmp, r.c_expr, tmp);
        }
        free(cty);
    }
    er_free(&r);
    buf_append_fmt(cg->cur_body,
                   "    feng_throw((void *)%s, %s);\n", tmp, desc_expr);
    free(tmp);
    free(desc_expr);
    return true;
}

static bool cg_emit_stmt(CG *cg, const FengStmt *stmt) {
    FengToken saved_stmt_anchor_token = cg->current_stmt_anchor_token;
    bool saved_stmt_anchor_active = cg->current_stmt_anchor_active;
    bool ok = false;

    if (cg->failed) return false;
    if (!cg_emit_line_directive(cg, stmt->token)) return false;
    cg->current_stmt_anchor_token = stmt->token;
    cg->current_stmt_anchor_active = true;
    switch (stmt->kind) {
        case FENG_STMT_BLOCK: {
            buf_append_cstr(cg->cur_body, "    {\n");
            Scope *s = scope_push(cg->cur_scope);
            if (!s) return cg_fail(cg, stmt->token, "IE0001", "codegen: out of memory");
            cg->cur_scope = s;
            ok = cg_emit_block(cg, stmt->as.block);
            cg_release_scope(cg, s);
            cg->cur_scope = s->parent;
            scope_pop_free(s);
            buf_append_cstr(cg->cur_body, "    }\n");
            break;
        }
        case FENG_STMT_BINDING:  ok = cg_emit_binding(cg, stmt); break;
        case FENG_STMT_ASSIGN:   ok = cg_emit_assign(cg, stmt); break;
        case FENG_STMT_EXPR:     ok = cg_emit_expr_stmt(cg, stmt); break;
        case FENG_STMT_TRY:      ok = cg_emit_try_stmt(cg, stmt); break;
        case FENG_STMT_RETURN:   ok = cg_emit_return(cg, stmt); break;
        case FENG_STMT_IF:       ok = cg_emit_if(cg, stmt); break;
        case FENG_STMT_MATCH:    ok = cg_emit_match_stmt(cg, stmt); break;
        case FENG_STMT_WHILE:    ok = cg_emit_while(cg, stmt); break;
        case FENG_STMT_FOR:      ok = cg_emit_for(cg, stmt); break;
        case FENG_STMT_BREAK:    ok = cg_emit_break_continue(cg, stmt, true); break;
        case FENG_STMT_CONTINUE: ok = cg_emit_break_continue(cg, stmt, false); break;
        case FENG_STMT_THROW:    ok = cg_emit_throw(cg, stmt); break;
        case FENG_STMT_DEFER:    ok = cg_emit_defer(cg, stmt); break;
        default:
            ok = cg_fail(cg,
                         stmt->token,
                         "CE0286", "codegen: statement kind not yet supported in this iteration");
            break;
    }
    cg->current_stmt_anchor_token = saved_stmt_anchor_token;
    cg->current_stmt_anchor_active = saved_stmt_anchor_active;
    return ok;
}

static bool cg_emit_block(CG *cg, const FengBlock *block) {
    for (size_t i = 0; i < block->statement_count; i++) {
        if (!cg_emit_stmt(cg, block->statements[i])) return false;
    }
    return true;
}

/* ---- defer capture analysis ------------------------------------------------
 *
 * docs/engineering/feng-defer-dev.md §5.4: scan the defer body AST, collect every
 * outer-scope binding name referenced inside it. We use the same approach
 * as cg_collect_capture_requirements_in_block_inner but operate on the
 * defer block; the captured names list is filtered by a shadow set built
 * from local bindings declared inside the defer body so the same-named
 * local does not pull in an outer binding.
 *
 * Feng semantic rejects use-before-declaration, so a flat two-pass scan
 * (collect all local-binding names; collect all identifier references;
 * subtract) is sufficient. */

static bool cg_defer_add_local_binding_name(const FengStmt *stmt,
                                            char ***out_names,
                                            size_t *out_count,
                                            size_t *out_capacity) {
    FengSlice name;

    if (stmt == NULL) return true;
    switch (stmt->kind) {
        case FENG_STMT_BINDING:
            name = stmt->as.binding.name;
            if (name.length > 0U) {
                return cg_capture_name_list_add(out_names, out_count, out_capacity, name);
            }
            if (stmt->as.binding.is_destructure) {
                for (size_t i = 0U; i < stmt->as.binding.destructure_count; ++i) {
                    if (!cg_capture_name_list_add(out_names, out_count, out_capacity,
                                                  stmt->as.binding.destructure_names[i])) {
                        return false;
                    }
                }
            }
            return true;
        case FENG_STMT_FOR:
            if (stmt->as.for_stmt.is_for_in) {
                const FengBinding *binding =
                    &stmt->as.for_stmt.iter_binding;

                if (binding->is_destructure) {
                    for (size_t i = 0U;
                         i < binding->destructure_count;
                         ++i) {
                        if (!cg_capture_name_list_add(
                                out_names,
                                out_count,
                                out_capacity,
                                binding->destructure_names[i])) {
                            return false;
                        }
                    }
                } else {
                    name = binding->name;
                    if (name.length > 0U &&
                        !cg_capture_name_list_add(
                            out_names, out_count, out_capacity, name)) {
                        return false;
                    }
                }
            }
            return true;
        default:
            return true;
    }
}

static bool cg_defer_collect_local_binding_names_in_stmt(const FengStmt *stmt,
                                                         char ***out_names,
                                                         size_t *out_count,
                                                         size_t *out_capacity);
static bool cg_defer_collect_local_binding_names_in_block(const FengBlock *block,
                                                           char ***out_names,
                                                           size_t *out_count,
                                                           size_t *out_capacity) {
    if (block == NULL) return true;
    for (size_t i = 0U; i < block->statement_count; ++i) {
        if (!cg_defer_collect_local_binding_names_in_stmt(block->statements[i],
                                                          out_names,
                                                          out_count,
                                                          out_capacity)) {
            return false;
        }
    }
    return true;
}

static bool cg_defer_collect_local_binding_names_in_stmt(const FengStmt *stmt,
                                                         char ***out_names,
                                                         size_t *out_count,
                                                         size_t *out_capacity) {
    if (stmt == NULL) return true;
    if (!cg_defer_add_local_binding_name(stmt, out_names, out_count, out_capacity)) {
        return false;
    }
    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return cg_defer_collect_local_binding_names_in_block(stmt->as.block,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity);
        case FENG_STMT_IF:
            for (size_t i = 0U; i < stmt->as.if_stmt.clause_count; ++i) {
                if (!cg_defer_collect_local_binding_names_in_block(stmt->as.if_stmt.clauses[i].block,
                                                                  out_names,
                                                                  out_count,
                                                                  out_capacity)) {
                    return false;
                }
            }
            return cg_defer_collect_local_binding_names_in_block(stmt->as.if_stmt.else_block,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity);
        case FENG_STMT_MATCH:
            for (size_t i = 0U; i < stmt->as.match_stmt.branch_count; ++i) {
                if (!cg_defer_collect_local_binding_names_in_block(stmt->as.match_stmt.branches[i].body,
                                                                   out_names,
                                                                   out_count,
                                                                   out_capacity)) {
                    return false;
                }
            }
            return cg_defer_collect_local_binding_names_in_block(stmt->as.match_stmt.else_block,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity);
        case FENG_STMT_WHILE:
            return cg_defer_collect_local_binding_names_in_block(stmt->as.while_stmt.body,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity);
        case FENG_STMT_FOR:
            return cg_defer_collect_local_binding_names_in_block(stmt->as.for_stmt.body,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity);
        case FENG_STMT_DEFER:
            /* Nested defer is rejected by semantic (AE1503), but defensively
             * recurse so any local binding it introduces is still accounted
             * for in the outer shadow set. */
            return cg_defer_collect_local_binding_names_in_block(stmt->as.defer_block,
                                                                 out_names,
                                                                 out_count,
                                                                 out_capacity);
        default:
            return true;
    }
}

/* Determine whether `name` (length `len`) appears in the captured-names list. */
static bool cg_defer_name_in_list(char *const *names, size_t count,
                                  const char *name, size_t len) {
    for (size_t i = 0U; i < count; ++i) {
        if (strlen(names[i]) == len && memcmp(names[i], name, len) == 0) {
            return true;
        }
    }
    return false;
}

/* Collect every identifier reference inside the defer body, minus the
 * shadow set built from local bindings declared inside the defer body. */
static bool cg_defer_collect_capture_refs_in_expr(const FengExpr *expr,
                                                  char ***out_names,
                                                  size_t *out_count,
                                                  size_t *out_capacity,
                                                  char *const *shadow_names,
                                                  size_t shadow_count,
                                                  bool *out_captures_self);

static bool cg_defer_collect_capture_refs_in_stmt(const FengStmt *stmt,
                                                 char ***out_names,
                                                 size_t *out_count,
                                                 size_t *out_capacity,
                                                 char *const *shadow_names,
                                                 size_t shadow_count,
                                                 bool *out_captures_self);

static bool cg_defer_collect_capture_refs_in_block(const FengBlock *block,
                                                  char ***out_names,
                                                  size_t *out_count,
                                                  size_t *out_capacity,
                                                  char *const *shadow_names,
                                                  size_t shadow_count,
                                                  bool *out_captures_self) {
    if (block == NULL) return true;
    for (size_t i = 0U; i < block->statement_count; ++i) {
        if (!cg_defer_collect_capture_refs_in_stmt(block->statements[i],
                                                   out_names,
                                                   out_count,
                                                   out_capacity,
                                                   shadow_names,
                                                   shadow_count,
                                                   out_captures_self)) {
            return false;
        }
    }
    return true;
}

static bool cg_defer_collect_capture_refs_in_stmt(const FengStmt *stmt,
                                                 char ***out_names,
                                                 size_t *out_count,
                                                 size_t *out_capacity,
                                                 char *const *shadow_names,
                                                 size_t shadow_count,
                                                 bool *out_captures_self) {
    if (stmt == NULL) return true;
    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return cg_defer_collect_capture_refs_in_block(stmt->as.block,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
        case FENG_STMT_BINDING:
            return cg_defer_collect_capture_refs_in_expr(stmt->as.binding.initializer,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_STMT_ASSIGN:
            return cg_defer_collect_capture_refs_in_expr(stmt->as.assign.target,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self) &&
                   cg_defer_collect_capture_refs_in_expr(stmt->as.assign.value,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_STMT_EXPR:
        case FENG_STMT_TRY:
            return cg_defer_collect_capture_refs_in_expr(stmt->as.expr,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_STMT_IF:
            for (size_t i = 0U; i < stmt->as.if_stmt.clause_count; ++i) {
                if (!cg_defer_collect_capture_refs_in_expr(stmt->as.if_stmt.clauses[i].condition,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self) ||
                    !cg_defer_collect_capture_refs_in_block(stmt->as.if_stmt.clauses[i].block,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           shadow_names,
                                                           shadow_count,
                                                           out_captures_self)) {
                    return false;
                }
            }
            return cg_defer_collect_capture_refs_in_block(stmt->as.if_stmt.else_block,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
        case FENG_STMT_MATCH:
            if (!cg_defer_collect_capture_refs_in_expr(stmt->as.match_stmt.target,
                                                       out_names,
                                                       out_count,
                                                       out_capacity,
                                                       shadow_names,
                                                       shadow_count,
                                                       out_captures_self)) {
                return false;
            }
            for (size_t i = 0U; i < stmt->as.match_stmt.branch_count; ++i) {
                const FengMatchBranch *branch = &stmt->as.match_stmt.branches[i];
                for (size_t j = 0U; j < branch->label_count; ++j) {
                    const FengMatchLabel *label = &branch->labels[j];
                    if (!cg_defer_collect_capture_refs_in_expr(label->value,
                                                              out_names,
                                                              out_count,
                                                              out_capacity,
                                                              shadow_names,
                                                              shadow_count,
                                                              out_captures_self) ||
                        !cg_defer_collect_capture_refs_in_expr(label->range_low,
                                                              out_names,
                                                              out_count,
                                                              out_capacity,
                                                              shadow_names,
                                                              shadow_count,
                                                              out_captures_self) ||
                        !cg_defer_collect_capture_refs_in_expr(label->range_high,
                                                              out_names,
                                                              out_count,
                                                              out_capacity,
                                                              shadow_names,
                                                              shadow_count,
                                                              out_captures_self)) {
                        return false;
                    }
                }
                if (!cg_defer_collect_capture_refs_in_block(branch->body,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             shadow_names,
                                                             shadow_count,
                                                             out_captures_self)) {
                    return false;
                }
            }
            return cg_defer_collect_capture_refs_in_block(stmt->as.match_stmt.else_block,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
        case FENG_STMT_WHILE:
            return cg_defer_collect_capture_refs_in_expr(stmt->as.while_stmt.condition,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self) &&
                   cg_defer_collect_capture_refs_in_block(stmt->as.while_stmt.body,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
        case FENG_STMT_FOR:
            if (stmt->as.for_stmt.is_for_in) {
                return cg_defer_collect_capture_refs_in_expr(stmt->as.for_stmt.iter_expr,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             shadow_names,
                                                             shadow_count,
                                                             out_captures_self) &&
                       cg_defer_collect_capture_refs_in_expr(stmt->as.for_stmt.iter_binding.initializer,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             shadow_names,
                                                             shadow_count,
                                                             out_captures_self) &&
                       cg_defer_collect_capture_refs_in_block(stmt->as.for_stmt.body,
                                                              out_names,
                                                              out_count,
                                                              out_capacity,
                                                              shadow_names,
                                                              shadow_count,
                                                              out_captures_self);
            }
            return cg_defer_collect_capture_refs_in_stmt(stmt->as.for_stmt.init,
                                                        out_names,
                                                        out_count,
                                                        out_capacity,
                                                        shadow_names,
                                                        shadow_count,
                                                        out_captures_self) &&
                   cg_defer_collect_capture_refs_in_expr(stmt->as.for_stmt.condition,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self) &&
                   cg_defer_collect_capture_refs_in_stmt(stmt->as.for_stmt.update,
                                                        out_names,
                                                        out_count,
                                                        out_capacity,
                                                        shadow_names,
                                                        shadow_count,
                                                        out_captures_self) &&
                   cg_defer_collect_capture_refs_in_block(stmt->as.for_stmt.body,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
        case FENG_STMT_RETURN:
        case FENG_STMT_THROW:
            /* Semantic rejects return/throw inside defer (AE1501/AE1502). */
            return true;
        case FENG_STMT_BREAK:
        case FENG_STMT_CONTINUE:
            return true;
        case FENG_STMT_DEFER:
            return cg_defer_collect_capture_refs_in_block(stmt->as.defer_block,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
    }
    return true;
}

static bool cg_defer_collect_capture_refs_in_expr(const FengExpr *expr,
                                                  char ***out_names,
                                                  size_t *out_count,
                                                  size_t *out_capacity,
                                                  char *const *shadow_names,
                                                  size_t shadow_count,
                                                  bool *out_captures_self) {
    if (expr == NULL) return true;
    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER: {
            FengSlice id = expr->as.identifier;
            if (id.length == 0U) return true;
            if (cg_defer_name_in_list(shadow_names, shadow_count, id.data, id.length)) {
                return true;
            }
            if (cg_defer_name_in_list(*out_names, *out_count, id.data, id.length)) {
                return true;
            }
            return cg_capture_name_list_add(out_names, out_count, out_capacity, id);
        }
        case FENG_EXPR_SELF:
            *out_captures_self = true;
            return true;
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
            return true;
        case FENG_EXPR_ARRAY_LITERAL:
            for (size_t i = 0U; i < expr->as.array_literal.count; ++i) {
                if (!cg_defer_collect_capture_refs_in_expr(expr->as.array_literal.items[i],
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           shadow_names,
                                                           shadow_count,
                                                           out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_TUPLE_LITERAL:
            for (size_t i = 0U; i < expr->as.tuple_literal.count; ++i) {
                if (!cg_defer_collect_capture_refs_in_expr(expr->as.tuple_literal.items[i],
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           shadow_names,
                                                           shadow_count,
                                                           out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_OBJECT_LITERAL:
            if (!cg_defer_collect_capture_refs_in_expr(expr->as.object_literal.target,
                                                       out_names,
                                                       out_count,
                                                       out_capacity,
                                                       shadow_names,
                                                       shadow_count,
                                                       out_captures_self)) {
                return false;
            }
            for (size_t i = 0U; i < expr->as.object_literal.field_count; ++i) {
                if (!cg_defer_collect_capture_refs_in_expr(expr->as.object_literal.fields[i].value,
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           shadow_names,
                                                           shadow_count,
                                                           out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_GENERIC_TARGET:
            return cg_defer_collect_capture_refs_in_expr(expr->as.generic_target.target,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_EXPR_CALL:
            if (!cg_defer_collect_capture_refs_in_expr(expr->as.call.callee,
                                                       out_names,
                                                       out_count,
                                                       out_capacity,
                                                       shadow_names,
                                                       shadow_count,
                                                       out_captures_self)) {
                return false;
            }
            for (size_t i = 0U; i < expr->as.call.arg_count; ++i) {
                if (!cg_defer_collect_capture_refs_in_expr(expr->as.call.args[i],
                                                           out_names,
                                                           out_count,
                                                           out_capacity,
                                                           shadow_names,
                                                           shadow_count,
                                                           out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_MEMBER:
            return cg_defer_collect_capture_refs_in_expr(expr->as.member.object,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_EXPR_INDEX:
            return cg_defer_collect_capture_refs_in_expr(expr->as.index.object,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self) &&
                   cg_defer_collect_capture_refs_in_expr(expr->as.index.index,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_EXPR_UNARY:
            return cg_defer_collect_capture_refs_in_expr(expr->as.unary.operand,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_EXPR_BINARY:
            return cg_defer_collect_capture_refs_in_expr(expr->as.binary.left,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self) &&
                   cg_defer_collect_capture_refs_in_expr(expr->as.binary.right,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_EXPR_LAMBDA:
            /* Nested lambda's own captures do not affect this defer; their
             * body references are resolved through the lambda's capture cell
             * mechanism (semantic-analyzed separately). */
            return true;
        case FENG_EXPR_CAST:
            return cg_defer_collect_capture_refs_in_expr(expr->as.cast.value,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_EXPR_IF:
            return cg_defer_collect_capture_refs_in_expr(expr->as.if_expr.condition,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self) &&
                   cg_defer_collect_capture_refs_in_block(expr->as.if_expr.then_block,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self) &&
                   cg_defer_collect_capture_refs_in_block(expr->as.if_expr.else_block,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
        case FENG_EXPR_MATCH:
            if (!cg_defer_collect_capture_refs_in_expr(expr->as.match_expr.target,
                                                       out_names,
                                                       out_count,
                                                       out_capacity,
                                                       shadow_names,
                                                       shadow_count,
                                                       out_captures_self)) {
                return false;
            }
            for (size_t i = 0U; i < expr->as.match_expr.branch_count; ++i) {
                const FengMatchBranch *branch = &expr->as.match_expr.branches[i];
                for (size_t j = 0U; j < branch->label_count; ++j) {
                    const FengMatchLabel *label = &branch->labels[j];
                    if (!cg_defer_collect_capture_refs_in_expr(label->value,
                                                              out_names,
                                                              out_count,
                                                              out_capacity,
                                                              shadow_names,
                                                              shadow_count,
                                                              out_captures_self) ||
                        !cg_defer_collect_capture_refs_in_expr(label->range_low,
                                                              out_names,
                                                              out_count,
                                                              out_capacity,
                                                              shadow_names,
                                                              shadow_count,
                                                              out_captures_self) ||
                        !cg_defer_collect_capture_refs_in_expr(label->range_high,
                                                              out_names,
                                                              out_count,
                                                              out_capacity,
                                                              shadow_names,
                                                              shadow_count,
                                                              out_captures_self)) {
                        return false;
                    }
                }
                if (!cg_defer_collect_capture_refs_in_block(branch->body,
                                                             out_names,
                                                             out_count,
                                                             out_capacity,
                                                             shadow_names,
                                                             shadow_count,
                                                             out_captures_self)) {
                    return false;
                }
            }
            return cg_defer_collect_capture_refs_in_block(expr->as.match_expr.else_block,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self);
        case FENG_EXPR_TRY:
            if (!cg_defer_collect_capture_refs_in_expr(expr->as.try_expr.body,
                                                       out_names,
                                                       out_count,
                                                       out_capacity,
                                                       shadow_names,
                                                       shadow_count,
                                                       out_captures_self)) {
                return false;
            }
            for (size_t i = 0U; i < expr->as.try_expr.clause_count; ++i) {
                if (!cg_defer_collect_capture_refs_in_block(expr->as.try_expr.clauses[i].body,
                                                            out_names,
                                                            out_count,
                                                            out_capacity,
                                                            shadow_names,
                                                            shadow_count,
                                                            out_captures_self)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_ARRAY_NEW:
            return cg_defer_collect_capture_refs_in_expr(expr->as.array_new.size,
                                                         out_names,
                                                         out_count,
                                                         out_capacity,
                                                         shadow_names,
                                                         shadow_count,
                                                         out_captures_self);
        case FENG_EXPR_MATCH_OP:
            if (!cg_defer_collect_capture_refs_in_expr(expr->as.match_op.target,
                                                       out_names,
                                                       out_count,
                                                       out_capacity,
                                                       shadow_names,
                                                       shadow_count,
                                                       out_captures_self)) {
                return false;
            }
            for (size_t i = 0U; i < expr->as.match_op.label_count; ++i) {
                const FengMatchLabel *label = &expr->as.match_op.labels[i];
                if (!cg_defer_collect_capture_refs_in_expr(label->value,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self) ||
                    !cg_defer_collect_capture_refs_in_expr(label->range_low,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self) ||
                    !cg_defer_collect_capture_refs_in_expr(label->range_high,
                                                          out_names,
                                                          out_count,
                                                          out_capacity,
                                                          shadow_names,
                                                          shadow_count,
                                                          out_captures_self)) {
                    return false;
                }
            }
            return true;
    }
    return true;
}

/* Compute capture requirements for a defer body. Returns a heap-allocated
 * list of unique outer-scope names referenced inside the defer block,
 * excluding any local bindings declared inside it. *out_captures_self is
 * set when the defer body references `self`. */
static bool cg_defer_compute_captures(const FengBlock *defer_block,
                                      char ***out_names,
                                      size_t *out_count,
                                      bool *out_captures_self) {
    char **shadow_names = NULL;
    size_t shadow_count = 0U;
    size_t shadow_capacity = 0U;
    char **captured = NULL;
    size_t captured_count = 0U;
    size_t captured_capacity = 0U;

    *out_names = NULL;
    *out_count = 0U;
    *out_captures_self = false;
    if (!cg_defer_collect_local_binding_names_in_block(defer_block,
                                                       &shadow_names,
                                                       &shadow_count,
                                                       &shadow_capacity)) {
        goto fail;
    }
    if (!cg_defer_collect_capture_refs_in_block(defer_block,
                                                &captured,
                                                &captured_count,
                                                &captured_capacity,
                                                shadow_names,
                                                shadow_count,
                                                out_captures_self)) {
        goto fail;
    }
    for (size_t i = 0U; i < shadow_count; ++i) free(shadow_names[i]);
    free(shadow_names);
    *out_names = captured;
    *out_count = captured_count;
    return true;
fail:
    for (size_t i = 0U; i < shadow_count; ++i) free(shadow_names[i]);
    free(shadow_names);
    for (size_t i = 0U; i < captured_count; ++i) free(captured[i]);
    free(captured);
    return false;
}

typedef struct DeferCaptureInfo {
    const Local *local;   /* borrowed from outer scope; lifetime tied to Scope */
    char *field_name;     /* heap-allocated closure field name */
} DeferCaptureInfo;

/* Resolve every captured name against the current outer scope chain and
 * produce a DeferCaptureInfo[] array. Returns false on allocation failure
 * or unresolved capture (which is a codegen bug — semantic guarantees the
 * identifier resolves). */
static bool cg_defer_resolve_captures(CG *cg,
                                       char *const *names,
                                       size_t count,
                                       bool captures_self,
                                       DeferCaptureInfo **out_infos,
                                       size_t *out_count,
                                       FengToken blame) {
    DeferCaptureInfo *infos = NULL;
    size_t info_count = 0U;
    size_t total = count + (captures_self ? 1U : 0U);

    if (total == 0U) {
        *out_infos = NULL;
        *out_count = 0U;
        return true;
    }
    infos = calloc(total, sizeof *infos);
    if (infos == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0U; i < count; ++i) {
        const Local *local = scope_lookup(cg->cur_scope, names[i], strlen(names[i]));
        if (local == NULL) {
            /* Unresolved capture means the identifier resolves to something
             * codegen already lowers via capture cells (lambda) or a
             * different surface. The simplest safe behavior is to skip it
             * rather than emit a broken closure field — defer bodies that
             * reference such bindings are rare and will be revisited when
             * their owning construct is re-examined. */
            continue;
        }
        infos[info_count].local = local;
        Buf fb;
        buf_init(&fb);
        buf_append_fmt(&fb, "_dc%zu", info_count);
        infos[info_count].field_name = fb.data;
        if (infos[info_count].field_name == NULL) {
            for (size_t j = 0U; j < info_count; ++j) free(infos[j].field_name);
            free(infos);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        info_count++;
    }
    if (captures_self) {
        const Local *self_local = scope_lookup(cg->cur_scope, "self", 4U);
        if (self_local == NULL) {
            for (size_t j = 0U; j < info_count; ++j) free(infos[j].field_name);
            free(infos);
            return cg_fail(cg, blame,
                           "CE0287", "codegen: defer body references 'self' but no 'self' binding is in scope");
        }
        infos[info_count].local = self_local;
        Buf fb;
        buf_init(&fb);
        buf_append_fmt(&fb, "_dc%zu", info_count);
        infos[info_count].field_name = fb.data;
        if (infos[info_count].field_name == NULL) {
            for (size_t j = 0U; j < info_count; ++j) free(infos[j].field_name);
            free(infos);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        info_count++;
    }
    *out_infos = infos;
    *out_count = info_count;
    return true;
}

static void cg_defer_capture_infos_free(DeferCaptureInfo *infos, size_t count) {
    if (infos == NULL) return;
    for (size_t i = 0U; i < count; ++i) free(infos[i].field_name);
    free(infos);
}

/* docs/engineering/feng-defer-dev.md §5.1–§5.6: emit a defer statement.
 *
 * Steps:
 *   1. Analyze capture requirements on the defer body (§5.4).
 *   2. Resolve each captured name against the outer scope chain.
 *   3. Emit a stack-allocated closure struct type into type_defs (§5.3);
 *      skip when there are no captures.
 *   4. Emit a static `void __defer_<module>_<seq>(void *_closure)` into
 *      witness_defs (§5.2). Inside it, register every captured binding as
 *      a Local whose c_name dereferences the closure field so the body can
 *      read/modify the outer variable by address.
 *   5. At the registration site emit the closure initialiser (when any) and
 *      `feng_defer_push(&node, fn, closure_or_NULL)` (§5.5).
 *   6. Register the defer entry in the current scope's locals list via
 *      scope_add_defer (§5.6.2) so cg_release_scope emits the matching
 *      `feng_cleanup_pop(); fn(closure_or_NULL);` at scope exit.
 */
static bool cg_emit_defer(CG *cg, const FengStmt *stmt) {
    char **captured_names = NULL;
    size_t captured_count = 0U;
    bool captures_self = false;
    DeferCaptureInfo *infos = NULL;
    size_t info_count = 0U;
    char *closure_struct_name = NULL;
    char *defer_fn_name = NULL;
    char *closure_var_name = NULL;
    char *node_var_name = NULL;
    bool ok = false;
    FengToken blame = stmt->token;

    if (!cg_defer_compute_captures(stmt->as.defer_block,
                                   &captured_names,
                                   &captured_count,
                                   &captures_self)) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (!cg_defer_resolve_captures(cg,
                                   captured_names,
                                   captured_count,
                                   captures_self,
                                   &infos,
                                   &info_count,
                                   blame)) {
        for (size_t i = 0U; i < captured_count; ++i) free(captured_names[i]);
        free(captured_names);
        return false;
    }
    /* captured_names consumed (copied into infos or skipped); free shells. */
    for (size_t i = 0U; i < captured_count; ++i) free(captured_names[i]);
    free(captured_names);

    size_t defer_id = cg->defer_counter++;
    {
        Buf sb, fb;
        buf_init(&sb);
        buf_init(&fb);
        buf_append_fmt(&sb, "__defer_closure_%s_%zu",
                       cg->module_mangle ? cg->module_mangle : "mod",
                       defer_id);
        buf_append_fmt(&fb, "__defer_%s_%zu",
                       cg->module_mangle ? cg->module_mangle : "mod",
                       defer_id);
        closure_struct_name = sb.data;
        defer_fn_name = fb.data;
    }
    if (closure_struct_name == NULL || defer_fn_name == NULL) {
        cg_defer_capture_infos_free(infos, info_count);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    /* §5.3: closure struct type. Ordinary fields point to the outer local.
     * Descriptor-sized locals already denote their value storage, so the
     * closure stores that address directly together with the descriptor
     * authority required to operate on the captured value in the generated
     * defer helper. */
    if (info_count > 0U) {
        Buf *td = &cg->type_defs;
        buf_append_fmt(td, "struct %s {\n", closure_struct_name);
        for (size_t i = 0U; i < info_count; ++i) {
            if (infos[i].local->is_storage_address) {
                buf_append_fmt(td,
                               "    void *%s;\n",
                               infos[i].field_name);
            } else {
                buf_append_cstr(td, "    ");
                cg_emit_c_type(td, infos[i].local->type);
                buf_append_fmt(td, " *%s;\n", infos[i].field_name);
            }
            if (infos[i].local->uses_erased_generic_storage) {
                buf_append_fmt(td,
                    "    const FengGenericParamDescriptor *%s_descriptor;\n"
                    "    size_t %s_size;\n",
                    infos[i].field_name,
                    infos[i].field_name);
            } else if (infos[i].local->uses_reified_storage) {
                buf_append_fmt(td,
                    "    const FengAggregateDescriptor *%s_descriptor;\n",
                    infos[i].field_name);
                if (infos[i].local->reified_size_c_name != NULL) {
                    buf_append_fmt(td,
                                   "    size_t %s_size;\n",
                                   infos[i].field_name);
                }
            }
        }
        buf_append_cstr(td, "};\n\n");
    }

    /* Forward-declare the defer static function. witness_defs is emitted
     * after fn_defs in cg_finalize, but the registration site (inside the
     * caller's body, which lives in fn_defs) references this symbol — so
     * the prototype must land in fn_protos, which precedes fn_defs. */
    buf_append_fmt(&cg->fn_protos,
                   "static void %s(void *_closure);\n",
                   defer_fn_name);

    /* §5.2: defer static function. Save / restore per-function state so the
     * generated body is independent of the registration site. */
    {
        Buf fn;
        Buf *saved_body = cg->cur_body;
        Scope *saved_scope = cg->cur_scope;
        int saved_tmp_counter = cg->tmp_counter;
        int saved_local_counter = cg->local_counter;
        int saved_loop_depth = cg->loop_depth;
        int saved_try_depth = cg->try_depth;
        int saved_active_exception_frame_count = cg->active_exception_frame_count;
        int saved_active_caught_unwind_count = cg->active_caught_unwind_count;
        CGType *saved_return_type = cg->cur_return_type;
        bool saved_is_main = cg->cur_fn_is_main;
        bool saved_has_frame_marker = cg->cur_function_has_frame_marker;
        const char *saved_frame_backend_symbol = cg->current_frame_backend_symbol;
        Scope *fn_scope = NULL;
        bool fn_ok = false;

        buf_init(&fn);
        fn_scope = scope_push(NULL);
        if (fn_scope == NULL) {
            cg_defer_capture_infos_free(infos, info_count);
            free(closure_struct_name);
            free(defer_fn_name);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        cg->cur_body = &fn;
        cg->cur_scope = fn_scope;
        cg->tmp_counter = 0;
        cg->local_counter = 0;
        cg->loop_depth = 0;
        cg->try_depth = 0;
        cg->active_exception_frame_count = 0;
        cg->active_caught_unwind_count = 0;
        cg->cur_function_has_frame_marker = false;
        cg->cur_return_type = cgtype_new(CG_TYPE_VOID);
        cg->cur_fn_is_main = false;
        cg->current_frame_backend_symbol = NULL;

        buf_append_fmt(&fn, "static void %s(void *_closure) {\n", defer_fn_name);
        if (info_count > 0U) {
            buf_append_fmt(&fn,
                "    struct %s *_c = (struct %s *)_closure;\n"
                "    (void)_c;\n",
                closure_struct_name,
                closure_struct_name);
        } else {
            buf_append_cstr(&fn, "    (void)_closure;\n");
        }
        /* Register the defer function's frame record so the DAP proxy can
         * rewrite the stack trace and map captured variables. HIDDEN policy:
         * defer is scope cleanup (like Swift/Zig), not a user-visible call
         * frame. The frame record is still needed for variable mapping. */
        {
            Buf frame_name;
            buf_init(&frame_name);
            if (stmt->token.line > 0U) {
                buf_append_fmt(&frame_name, "defer@%u", stmt->token.line);
            } else {
                buf_append_cstr(&frame_name, "defer");
            }
            if (frame_name.data == NULL ||
                !cg_debug_set_current_frame(cg,
                                            defer_fn_name,
                                            frame_name.data,
                                            FENG_CODEGEN_MAPING_FRAME_HIDDEN,
                                            blame) ||
                !cg_debug_add_current_frame_module_binding_records(cg, blame)) {
                buf_free(&frame_name);
                cg_fail(cg, blame, "IE0001",
                        "codegen: out of memory recording defer debug frame");
                buf_free(&fn);
                goto fn_cleanup;
            }
            buf_free(&frame_name);
        }
        for (size_t i = 0U; i < info_count; ++i) {
            /* Register the captured binding in the defer function's scope.
             * The c_name dereferences the closure field so every read/write
             * in the body touches the outer variable's storage directly. */
            char *alias_c_name = NULL;
            Buf cb;
            buf_init(&cb);
            if (infos[i].local->is_storage_address) {
                buf_append_fmt(&cb, "_c->%s", infos[i].field_name);
            } else {
                buf_append_fmt(&cb, "(*_c->%s)", infos[i].field_name);
            }
            alias_c_name = cb.data;
            if (alias_c_name == NULL) {
                cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                buf_free(&fn);
                goto fn_cleanup;
            }
            CGType *alias_type = cgtype_clone(infos[i].local->type);
            if (alias_type == NULL ||
                !scope_add(fn_scope,
                           infos[i].local->name,
                           alias_c_name,
                           alias_type,
                           true) ||
                !scope_copy_last_binding_mutability(fn_scope,
                                                    infos[i].local)) {
                /* is_param = true: the captured binding is owned by the
                 * outer scope. cg_release_scope skips is_param locals, so
                 * the defer function does not emit a stray release for it. */
                free(alias_c_name);
                cgtype_free(alias_type);
                cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                buf_free(&fn);
                goto fn_cleanup;
            }
            if (infos[i].local->uses_erased_generic_storage) {
                Buf descriptor_expr;
                Buf size_expr;

                buf_init(&descriptor_expr);
                buf_init(&size_expr);
                buf_append_fmt(&descriptor_expr,
                               "_c->%s_descriptor",
                               infos[i].field_name);
                buf_append_fmt(&size_expr,
                               "_c->%s_size",
                               infos[i].field_name);
                if (descriptor_expr.data == NULL || size_expr.data == NULL ||
                    !scope_mark_last_erased_generic_storage(
                        fn_scope,
                        descriptor_expr.data,
                        size_expr.data)) {
                    buf_free(&descriptor_expr);
                    buf_free(&size_expr);
                    free(alias_c_name);
                    cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                    buf_free(&fn);
                    goto fn_cleanup;
                }
                buf_free(&descriptor_expr);
                buf_free(&size_expr);
            } else if (infos[i].local->uses_reified_storage) {
                Buf descriptor_expr;
                Buf size_expr;
                const char *size_c_expr = NULL;

                buf_init(&descriptor_expr);
                buf_init(&size_expr);
                buf_append_fmt(&descriptor_expr,
                               "_c->%s_descriptor",
                               infos[i].field_name);
                if (infos[i].local->reified_size_c_name != NULL) {
                    buf_append_fmt(&size_expr,
                                   "_c->%s_size",
                                   infos[i].field_name);
                    size_c_expr = size_expr.data;
                }
                if (descriptor_expr.data == NULL ||
                    (infos[i].local->reified_size_c_name != NULL &&
                     size_expr.data == NULL) ||
                    !scope_mark_last_reified_storage(
                        fn_scope,
                        descriptor_expr.data,
                        size_c_expr)) {
                    buf_free(&descriptor_expr);
                    buf_free(&size_expr);
                    free(alias_c_name);
                    cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                    buf_free(&fn);
                    goto fn_cleanup;
                }
                buf_free(&descriptor_expr);
                buf_free(&size_expr);
            }
            /* scope_add strdups name and c_name; free our copies. */
            free(alias_c_name);
            /* Register a variable record so the DAP proxy can display the
             * captured binding's original name and value when stopped inside
             * the defer body. The read expression dereferences the closure
             * field pointer to reach the outer variable's live storage. */
            {
                Buf read_expr;
                buf_init(&read_expr);
                if (infos[i].local->is_storage_address) {
                    buf_append_fmt(&read_expr,
                                   "_c->%s",
                                   infos[i].field_name);
                } else {
                    buf_append_fmt(&read_expr,
                                   "(*_c->%s)",
                                   infos[i].field_name);
                }
                if (read_expr.data == NULL ||
                    !cg_debug_add_variable_record_cstr_cgtype(
                        cg,
                        NULL,
                        infos[i].local->name,
                        read_expr.data,
                        infos[i].local->type,
                        strcmp(infos[i].local->name, "self") == 0
                            ? FENG_CODEGEN_MAPING_VARIABLE_SELF
                            : FENG_CODEGEN_MAPING_VARIABLE_CAPTURE,
                        blame)) {
                    buf_free(&read_expr);
                    cg_fail(cg, blame, "IE0001",
                            "codegen: out of memory recording defer capture");
                    buf_free(&fn);
                    goto fn_cleanup;
                }
                buf_free(&read_expr);
            }
        }
        if (!cg_emit_block(cg, stmt->as.defer_block)) {
            buf_free(&fn);
            goto fn_cleanup;
        }
        cg_release_scope(cg, fn_scope);
        buf_append_cstr(&fn, "}\n\n");
        if (fn.data == NULL) {
            cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            buf_free(&fn);
            goto fn_cleanup;
        }
        buf_append(&cg->witness_defs, fn.data, fn.length);
        fn_ok = true;

    fn_cleanup:
        cg->cur_body = saved_body;
        cg->cur_scope = saved_scope;
        cg->tmp_counter = saved_tmp_counter;
        cg->local_counter = saved_local_counter;
        cg->loop_depth = saved_loop_depth;
        cg->try_depth = saved_try_depth;
        cg->active_exception_frame_count = saved_active_exception_frame_count;
        cg->active_caught_unwind_count = saved_active_caught_unwind_count;
        cg->cur_return_type = saved_return_type;
        cg->cur_fn_is_main = saved_is_main;
        cg->cur_function_has_frame_marker = saved_has_frame_marker;
        cg->current_frame_backend_symbol = saved_frame_backend_symbol;
        if (fn_scope != NULL) scope_pop_free(fn_scope);
        buf_free(&fn);
        if (!fn_ok) {
            cg_defer_capture_infos_free(infos, info_count);
            free(closure_struct_name);
            free(defer_fn_name);
            return false;
        }
    }

    /* §5.5: emit closure initialiser + registration at the defer site. */
    if (!cg_emit_line_directive(cg, blame)) {
        cg_defer_capture_infos_free(infos, info_count);
        free(closure_struct_name);
        free(defer_fn_name);
        return false;
    }
    if (info_count > 0U) {
        Buf vb;
        buf_init(&vb);
        buf_append_fmt(&vb, "__defer_closure_%s_%zu",
                       cg->module_mangle ? cg->module_mangle : "mod",
                       defer_id);
        closure_var_name = vb.data;
        if (closure_var_name == NULL) {
            cg_defer_capture_infos_free(infos, info_count);
            free(closure_struct_name);
            free(defer_fn_name);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
                       "    struct %s %s = {",
                       closure_struct_name,
                       closure_var_name);
        for (size_t i = 0U; i < info_count; ++i) {
            if (i > 0U) buf_append_cstr(cg->cur_body, ", ");
            buf_append_fmt(cg->cur_body,
                           infos[i].local->is_storage_address ? "%s" : "&%s",
                           infos[i].local->c_name);
            if (infos[i].local->uses_erased_generic_storage) {
                buf_append_fmt(cg->cur_body,
                               ", %s, %s",
                               infos[i].local->erased_generic_descriptor_c_name,
                               infos[i].local->erased_generic_size_c_name);
            } else if (infos[i].local->uses_reified_storage) {
                buf_append_fmt(cg->cur_body,
                               ", %s",
                               infos[i].local->reified_descriptor_c_name);
                if (infos[i].local->reified_size_c_name != NULL) {
                    buf_append_fmt(cg->cur_body,
                                   ", %s",
                                   infos[i].local->reified_size_c_name);
                }
            }
        }
        buf_append_cstr(cg->cur_body, "};\n");
    }
    {
        Buf nb;
        buf_init(&nb);
        buf_append_fmt(&nb, "_defer_%s_%zu",
                       cg->module_mangle ? cg->module_mangle : "mod",
                       defer_id);
        node_var_name = nb.data;
        if (node_var_name == NULL) {
            free(closure_var_name);
            cg_defer_capture_infos_free(infos, info_count);
            free(closure_struct_name);
            free(defer_fn_name);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }
    /* feng_defer_push takes the closure by void *. The closure is a stack
     * struct; pass its address so the defer function can down-cast. */
    if (closure_var_name != NULL) {
        buf_append_fmt(cg->cur_body,
                       "    FengCleanupNode %s; feng_defer_push(&%s, %s, &%s);\n",
                       node_var_name,
                       node_var_name,
                       defer_fn_name,
                       closure_var_name);
    } else {
        buf_append_fmt(cg->cur_body,
                       "    FengCleanupNode %s; feng_defer_push(&%s, %s, NULL);\n",
                       node_var_name,
                       node_var_name,
                       defer_fn_name);
    }

    /* §5.6.2: register the defer entry in the current scope so cg_release_scope
     * emits the matching pop+invoke at scope exit. */
    {
        CGType *defer_type = cgtype_new(CG_TYPE_DEFER);
        if (defer_type == NULL ||
            !scope_add_defer(cg->cur_scope,
                             defer_fn_name,
                             closure_var_name,
                             defer_type)) {
            cgtype_free(defer_type);
            free(closure_var_name);
            free(node_var_name);
            cg_defer_capture_infos_free(infos, info_count);
            free(closure_struct_name);
            free(defer_fn_name);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }

    /* closure_var_name ownership transferred into the Local via scope_add_defer
     * (it strdup's). node_var_name is owned by this function (used only here
     * for emit); we leak it because the generated code refers to it only at
     * emit time and never after. To avoid leaking, free it now. */
    free(node_var_name);
    free(closure_struct_name);
    free(defer_fn_name);
    cg_defer_capture_infos_free(infos, info_count);
    ok = true;

    /* `ok = true` is the only path; suppress unused-warning otherwise. */
    (void)ok;
    return true;
}

/* ===================== top-level emission ===================== */

static bool cg_emit_function_eh_prologue(CG *cg, FengToken token) {
    char *frame_name = cg_fresh_temp(cg, "_fn_frame");

    if (frame_name == NULL) {
        return cg_fail(cg, token, "IE0001", "codegen: out of memory");
    }
    buf_append_cstr(cg->cur_body,
                    "#if !defined(_WIN32)\n"
                    "#if defined(__APPLE__)\n"
                    "    __asm__ volatile(\".cfi_personality 155, ___feng_personality_v0\\n\"\n"
                    "                     \".cfi_lsda 16, _feng_empty_function_lsda\\n\");\n"
                    "#else\n"
                    "    __asm__ volatile(\".cfi_personality 27, __feng_personality_v0\\n\"\n"
                    "                     \".cfi_lsda 16, feng_empty_function_lsda\\n\");\n"
                    "#endif\n"
                    "#endif\n");
    buf_append_fmt(cg->cur_body,
                   "    FengFrameMarker %s; feng_frame_push(&%s);\n",
                   frame_name,
                   frame_name);
    free(frame_name);
    cg->cur_function_has_frame_marker = true;
    return true;
}

static void cg_emit_function_fallthrough_cleanup(CG *cg) {
    if (cg->cur_function_has_frame_marker) {
        buf_append_cstr(cg->cur_body, "    feng_frame_pop();\n");
    }
}

static bool cg_emit_extern_decl(CG *cg, const FengDecl *decl) {
    const ExternFn *ef = cg_find_extern_by_decl(cg, decl);

    if (ef == NULL) {
        if (!cg_register_extern(cg, decl)) return false;
        ef = &cg->externs[cg->extern_count - 1U];
    }
    return cg_emit_registered_extern_decl(cg, ef);
}

static void cg_emit_free_fn_proto(Buf *out, const FreeFn *fn, bool needs_static) {
    if (needs_static) {
        buf_append_cstr(out, "static ");
    }
    cg_emit_c_type(out, fn->return_type);
    buf_append_fmt(out, " %s(", fn->c_name);
    if (fn->param_count == 0) {
        buf_append_cstr(out, "void");
    }
    for (size_t i = 0; i < fn->param_count; i++) {
        if (i) buf_append_cstr(out, ", ");
        cg_emit_c_type(out, fn->param_types[i]);
        buf_append_fmt(out, " %s",
            fn->param_names[i] ? fn->param_names[i] : "_p");
    }
    buf_append_cstr(out, ");\n");
}

static void cg_emit_free_fn_abi_proto(Buf *out, const FreeFn *fn, bool needs_static) {
    if (!cg_free_fn_has_abi_wrapper(fn)) {
        return;
    }
    if (needs_static) {
        buf_append_cstr(out, "static ");
    }
    cg_emit_c_abi_surface_type(out, fn->return_type);
    buf_append_fmt(out, " %s(", fn->c_abi_name);
    if (fn->param_count == 0) {
        buf_append_cstr(out, "void");
    }
    for (size_t i = 0; i < fn->param_count; i++) {
        if (i) buf_append_cstr(out, ", ");
        cg_emit_c_abi_surface_type(out, fn->param_types[i]);
        buf_append_fmt(out, " %s",
            fn->param_names[i] ? fn->param_names[i] : "_p");
    }
    buf_append_cstr(out, ");\n");
}

static void cg_emit_user_method_proto_ex(Buf *out,
                                         const UserType *t,
                                         const UserMethod *m,
                                         bool needs_static,
                                         bool has_func_desc) {
    bool is_static_method = m != NULL && m->member != NULL && m->member->is_static;
    bool has_param = false;

    if (needs_static) {
        buf_append_cstr(out, "static ");
    }
    cg_emit_c_type(out, m->return_type);
    buf_append_fmt(out, " %s(", m->c_name);
    if (!is_static_method) {
        /* §9.15: all types (heap objects, @value, and tuple) pass struct X *self
         * (pointer).  Self-binding c_name differs: value-semantics types bind
         * "(*self)" so field access emits (*self).field ≡ self->field; heap
         * objects bind "self" directly. */
        buf_append_fmt(out, "struct %s *self", t->c_struct_name);
        has_param = true;
    }
    if (t->generic_context_type_param_count > 0U) {
        if (has_param) buf_append_cstr(out, ", ");
        const char *td_type = cg_user_type_is_value(t)
            ? "FengAggregateDescriptor" : "FengTypeDescriptor";
        buf_append_fmt(out, "const %s *_type_desc", td_type);
        has_param = true;
    }
    if (has_func_desc) {
        if (has_param) buf_append_cstr(out, ", ");
        buf_append_cstr(out, "const FengFunctionDescriptor *_func_desc");
        has_param = true;
    }
    for (size_t i = 0; i < m->param_count; i++) {
        if (has_param) {
            buf_append_cstr(out, ", ");
        }
        if (cg_shared_generic_param_uses_address(m->param_types[i])) {
            buf_append_fmt(out, "const void *%s",
                           m->param_names[i] ? m->param_names[i] : "_p");
        } else {
            cg_emit_c_type(out, m->param_types[i]);
            buf_append_fmt(out, " %s", m->param_names[i] ? m->param_names[i] : "_p");
        }
        has_param = true;
    }
    if (!has_param) {
        buf_append_cstr(out, "void");
    }
    buf_append_cstr(out, ");\n");
}

/* Emit the ordinary method ABI, which has no callable descriptor. */
static void cg_emit_user_method_proto(Buf *out,
                                      const UserType *t,
                                      const UserMethod *m,
                                      bool needs_static) {
    cg_emit_user_method_proto_ex(out, t, m, needs_static, false);
}

/* Emit one exported shared-body ABI prototype for an imported generic-owner
 * or method-generic member. Instance/static methods use the provider's owner
 * descriptor, optional callable descriptor, method descriptors, ordinary
 * parameters and output slot ordering. A fit supplies its stable shared-name
 * override. Final C symbols are deduplicated across imported instances. */
static bool cg_emit_imported_generic_method_shared_proto(CG *cg,
                                                         const UserType *type,
                                                         const UserMethod *method,
                                                         bool has_func_desc,
                                                         const char *shared_name_override) {
    const FengCallableSignature *signature;
    char *shared_name;
    const char *type_descriptor_name;

    if (cg == NULL || type == NULL || method == NULL ||
        type->decl == NULL || method->member == NULL) {
        return false;
    }
    signature = &method->member->as.callable;
    shared_name = shared_name_override != NULL
        ? strdup(shared_name_override)
        : cg_generic_type_method_shared_cname(
              cg, type->decl, method->member);
    if (shared_name == NULL) {
        return cg_fail(cg, method->member->token,
                       "IE0001", "codegen: out of memory");
    }
    for (size_t index = 0U;
         index < cg->imported_generic_shared_proto_count;
         ++index) {
        if (strcmp(cg->imported_generic_shared_proto_names[index],
                   shared_name) == 0) {
            free(shared_name);
            return true;
        }
    }
    if (cg->imported_generic_shared_proto_count + 1U >
        cg->imported_generic_shared_proto_capacity) {
        size_t capacity = cg->imported_generic_shared_proto_capacity != 0U
            ? cg->imported_generic_shared_proto_capacity * 2U
            : 16U;
        char **grown = (char **)realloc(
            cg->imported_generic_shared_proto_names,
            capacity * sizeof(*grown));

        if (grown == NULL) {
            free(shared_name);
            return cg_fail(cg, method->member->token,
                           "IE0001", "codegen: out of memory");
        }
        cg->imported_generic_shared_proto_names = grown;
        cg->imported_generic_shared_proto_capacity = capacity;
    }
    cg->imported_generic_shared_proto_names[
        cg->imported_generic_shared_proto_count] = strdup(shared_name);
    if (cg->imported_generic_shared_proto_names[
            cg->imported_generic_shared_proto_count] == NULL) {
        free(shared_name);
        return cg_fail(cg, method->member->token,
                       "IE0001", "codegen: out of memory");
    }
    cg->imported_generic_shared_proto_count++;
    type_descriptor_name = cg_user_type_is_value_semantics(type)
                               ? "FengAggregateDescriptor"
                               : "FengTypeDescriptor";

    buf_append_fmt(&cg->fn_protos, "void %s(", shared_name);
    if (!method->member->is_static) {
        buf_append_cstr(&cg->fn_protos, "void *_self, ");
    }
    buf_append_fmt(&cg->fn_protos,
                   "const %s *_type_desc",
                   type_descriptor_name);
    if (has_func_desc) {
        buf_append_cstr(&cg->fn_protos,
                        ", const FengFunctionDescriptor *_desc");
    }
    for (size_t index = 0U; index < signature->type_param_count; ++index) {
        buf_append_fmt(&cg->fn_protos,
                       ", const FengGenericParamDescriptor *_%.*s",
                       (int)signature->type_params[index].name.length,
                       signature->type_params[index].name.data);
    }
    for (size_t index = 0U; index < method->param_count; ++index) {
        const FengDecl *origin_decl = type->generic_origin_decl != NULL
                                          ? type->generic_origin_decl
                                          : type->decl;
        bool uses_address_abi = false;

        if (!cg_shared_method_param_uses_address_abi(
                cg,
                origin_decl,
                method->member,
                index,
                &uses_address_abi)) {
            free(shared_name);
            return false;
        }
        buf_append_cstr(&cg->fn_protos, ", ");
        if (uses_address_abi) {
            buf_append_fmt(&cg->fn_protos, "const void *_p%zu", index);
        } else {
            cg_emit_c_type(&cg->fn_protos, method->param_types[index]);
            buf_append_fmt(&cg->fn_protos, " _p%zu", index);
        }
    }
    if (method->return_type != NULL &&
        method->return_type->kind != CG_TYPE_VOID) {
        buf_append_cstr(&cg->fn_protos, ", void *_out");
    }
    buf_append_cstr(&cg->fn_protos, ");\n");
    free(shared_name);
    return true;
}

/* Builtin array fits share one body across all element types.  A value-
 * semantics return whose concrete type depends on the fit target parameter
 * cannot use a C return value: the open and concrete generic structs are
 * distinct C types and the concrete layout is described at the call site.
 * Use the same caller-provided output-slot ABI as other generic shared bodies. */
static bool cg_builtin_fit_return_uses_out(const BuiltinFit *bf,
                                           const UserMethod *m) {
    return bf != NULL && bf->target_type_param_count > 0U &&
           m != NULL && m->return_type != NULL &&
           m->return_type->kind != CG_TYPE_VOID &&
           cg_type_is_value_semantics(m->return_type) &&
           m->return_type->user != NULL &&
           m->return_type->user->generic_context_type_param_count > 0U;
}

static void cg_emit_builtin_fit_method_proto(Buf *out,
                                             const BuiltinFit *bf,
                                             const UserMethod *m,
                                             bool needs_static) {
    bool is_static_method = m != NULL && m->member != NULL && m->member->is_static;
    bool has_param = false;

    if (needs_static) {
        buf_append_cstr(out, "static ");
    }
    const bool return_uses_out = cg_builtin_fit_return_uses_out(bf, m);
    if (return_uses_out) {
        buf_append_cstr(out, "void");
    } else {
        cg_emit_c_type(out, m->return_type);
    }
    buf_append_fmt(out, " %s(", m->c_name);
    if (!is_static_method) {
        cg_emit_c_type(out, bf->target_type);
        buf_append_cstr(out, " self");
        has_param = true;
    }
    /* §6.7: _desc parameter for reified deps */
    if (has_param) buf_append_cstr(out, ", ");
    buf_append_cstr(out, "const FengFunctionDescriptor *_desc");
    has_param = true;
    for (size_t i = 0; i < bf->target_type_param_count; ++i) {
        if (has_param) {
            buf_append_cstr(out, ", ");
        }
        buf_append_fmt(out,
                       "const FengGenericParamDescriptor *_%.*s",
                       (int)bf->target_type_params[i].name.length,
                       bf->target_type_params[i].name.data);
        has_param = true;
    }
    /* method-level generic type parameter descriptors */
    {
        const FengCallableSignature *sig = &m->member->as.callable;
        for (size_t i = 0; i < sig->type_param_count; ++i) {
            if (has_param) {
                buf_append_cstr(out, ", ");
            }
            buf_append_fmt(out,
                           "const FengGenericParamDescriptor *_%.*s",
                           (int)sig->type_params[i].name.length,
                           sig->type_params[i].name.data);
            has_param = true;
        }
    }
    for (size_t i = 0; i < m->param_count; i++) {
        if (has_param) {
            buf_append_cstr(out, ", ");
        }
        if (m->param_types[i] != NULL && m->param_types[i]->kind == CG_TYPE_GENERIC_PARAM) {
            buf_append_fmt(out, "const void *%s",
                           m->param_names[i] ? m->param_names[i] : "_p");
        } else {
            cg_emit_c_type(out, m->param_types[i]);
            buf_append_fmt(out, " %s", m->param_names[i] ? m->param_names[i] : "_p");
        }
        has_param = true;
    }
    if (return_uses_out) {
        if (has_param) {
            buf_append_cstr(out, ", ");
        }
        buf_append_cstr(out, "void *_out");
        has_param = true;
    }
    if (!has_param) {
        buf_append_cstr(out, "void");
    }
    buf_append_cstr(out, ");\n");
}

static bool cg_emit_imported_binding_decl(CG *cg, const FengDecl *decl) {
    CGType *binding_type = NULL;
    char *slot_name = NULL;
    char *ensure_init_name = NULL;

    if (decl == NULL || decl->kind != FENG_DECL_GLOBAL_BINDING) {
        return cg_fail(cg,
                       decl != NULL ? decl->token : (FengToken){0},
                       "CE0287", "codegen: imported public binding surface is missing a type");
    }
    if (!cg_binding_public_surface_names(cg, decl, &slot_name, &ensure_init_name)) {
        return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    }
    if (!cg_resolve_global_binding_type(cg, decl, &binding_type)) {
        free(slot_name);
        free(ensure_init_name);
        return false;
    }

    buf_append_cstr(&cg->fn_protos, "extern ");
    cg_emit_c_type(&cg->fn_protos, binding_type);
    buf_append_fmt(&cg->fn_protos, " %s;\n", slot_name);
    buf_append_fmt(&cg->fn_protos, "extern void %s(void);\n", ensure_init_name);

    cgtype_free(binding_type);
    free(slot_name);
    free(ensure_init_name);
    return true;
}

static bool cg_emit_imported_type_static_binding_decl(CG *cg,
                                                      const TypeStaticBinding *binding) {
    if (binding == NULL || binding->type == NULL || !binding->exports_public_surface) {
        return true;
    }
    {
        char *cty = cg_ctype_dup(binding->type);

        if (cty == NULL) {
            return cg_fail(cg,
                           binding->member != NULL ? binding->member->token : (FengToken){0},
                           "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(&cg->fn_protos, "extern %s %s;\n", cty, binding->c_name);
        buf_append_fmt(&cg->fn_protos, "extern void %s(void);\n", binding->c_ensure_init_name);
        free(cty);
    }
    return true;
}

static bool cg_emit_imported_function_decl(CG *cg, const FengDecl *decl) {
    if (decl->is_extern) {
        return cg_emit_extern_decl(cg, decl);
    }

    if (decl->as.function_decl.type_param_count > 0U) {
        const FengCallableSignature *sig = &decl->as.function_decl;
        const GenericFn *gfn;
        size_t tp_count = sig->type_param_count;
        const char **desc_names = NULL;
        CGType *return_type = NULL;
        CGType **param_types = NULL;
        bool ok = false;
        bool saved_in_generic_fn = cg->in_generic_fn;
        size_t saved_tp_count = cg->generic_fn_type_param_count;
        char **saved_tp_names = cg->generic_fn_type_param_names;
        const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
        const char **saved_tp_descs = cg->generic_fn_type_param_descs;

        if (!cg_find_generic_fn_by_decl(cg, decl) && !cg_register_generic_fn(cg, decl)) {
            return false;
        }
        gfn = cg_find_generic_fn_by_decl(cg, decl);
        if (gfn == NULL) {
            return false;
        }

        desc_names = tp_count ? calloc(tp_count, sizeof *desc_names) : NULL;
        if (tp_count > 0U && desc_names == NULL) {
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
        for (size_t i = 0U; i < tp_count; ++i) {
            Buf b;
            buf_init(&b);
            buf_append_fmt(&b, "_%s", gfn->type_param_names[i]);
            desc_names[i] = b.data;
            if (desc_names[i] == NULL) {
                cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }

        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count = tp_count;
        cg->generic_fn_type_param_names = gfn->type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = desc_names;

        if (!cg_resolve_callable_return_type(
                cg, sig, decl->token, &return_type)) {
            goto cleanup;
        }

        param_types = sig->param_count ? calloc(sig->param_count, sizeof *param_types) : NULL;
        if (sig->param_count > 0U && param_types == NULL) {
            cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        for (size_t i = 0U; i < sig->param_count; ++i) {
            if (!cg_resolve_type(cg, sig->params[i].type, &sig->params[i].token,
                                 &param_types[i])) {
                goto cleanup;
            }
        }

        buf_append_fmt(&cg->fn_protos, "void %s(", gfn->c_name);
        {
            bool has_out_param = return_type->kind != CG_TYPE_VOID;
            /* §6.7: _desc is always the first parameter */
            buf_append_cstr(&cg->fn_protos,
                            "const FengFunctionDescriptor *_desc");
            for (size_t i = 0U; i < tp_count; ++i) {
                buf_append_cstr(&cg->fn_protos, ", ");
                buf_append_fmt(&cg->fn_protos,
                               "const FengGenericParamDescriptor *%s",
                               desc_names[i]);
            }
            for (size_t i = 0U; i < sig->param_count; ++i) {
                buf_append_cstr(&cg->fn_protos, ", ");
                if (cg_shared_generic_param_uses_address(param_types[i])) {
                    buf_append_fmt(&cg->fn_protos, "const void *_p_%.*s",
                                   (int)sig->params[i].name.length,
                                   sig->params[i].name.data);
                } else {
                    cg_emit_c_type(&cg->fn_protos, param_types[i]);
                    buf_append_fmt(&cg->fn_protos, " _p_%.*s",
                                   (int)sig->params[i].name.length,
                                   sig->params[i].name.data);
                }
            }
            if (has_out_param) {
                buf_append_cstr(&cg->fn_protos, ", ");
                buf_append_cstr(&cg->fn_protos, "void *_out");
            }
        }
        buf_append_cstr(&cg->fn_protos, ");\n");
        ok = true;

cleanup:
        cg->in_generic_fn = saved_in_generic_fn;
        cg->generic_fn_type_param_count = saved_tp_count;
        cg->generic_fn_type_param_names = saved_tp_names;
        cg->generic_fn_type_param_constraints = saved_tp_constraints;
        cg->generic_fn_type_param_descs = saved_tp_descs;
        if (param_types != NULL) {
            for (size_t i = 0U; i < sig->param_count; ++i) {
                cgtype_free(param_types[i]);
            }
        }
        free(param_types);
        cgtype_free(return_type);
        cg_free_const_cstr_array(desc_names, tp_count);
        return ok;
    }
    if (!cg_register_free_fn(cg, decl)) {
        return false;
    }
    cg_emit_free_fn_proto(&cg->fn_protos, &cg->free_fns[cg->free_fn_count - 1], false);
    return true;
}

static bool cg_check_main_signature(CG *cg, const FreeFn *fn) {
    if (fn->return_type->kind != CG_TYPE_VOID &&
        fn->return_type->kind != CG_TYPE_I32) {
        return cg_fail(cg, fn->decl->token,
            "CE0288", "codegen: main must return void or i32");
    }
    if (fn->param_count != 1 ||
        fn->param_types[0]->kind != CG_TYPE_ARRAY ||
        !fn->param_types[0]->element ||
        fn->param_types[0]->element->kind != CG_TYPE_STRING) {
        return cg_fail(cg, fn->decl->token,
            "CE0289", "codegen: main must have signature (args: string[])");
    }
    return true;
}

/* ===================== G6 — generic codegen ===================== */

/* Generate the sort key for a reifiable dep (§2.3 recursive naming).
 * Root mode uses "__" separator between params; param mode uses "_".
 * Owner type params are represented as T0, T1, etc. by 0-based index.
 * Returns a heap-allocated string; caller frees. */
static char *cg_reifiable_sort_key(const FengTypeRef *type_ref,
                                   const FengSlice *owner_type_param_names,
                                   size_t owner_type_param_count,
                                   bool is_root) {
    Buf key;
    const char *sep;
    size_t i;

    buf_init(&key);
    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_NAMED) {
        buf_append_cstr(&key, "?");
        return key.data;
    }

    if (type_ref->as.named.type_arg_count == 0U &&
        type_ref->as.named.segment_count == 1U) {
        const FengSlice *seg = &type_ref->as.named.segments[0];

        for (i = 0U; i < owner_type_param_count; ++i) {
            if (seg->length == owner_type_param_names[i].length &&
                memcmp(seg->data, owner_type_param_names[i].data,
                       seg->length) == 0) {
                buf_append_fmt(&key, "T%zu", i);
                return key.data;
            }
        }
        buf_append_fmt(&key, "%.*s", (int)seg->length, seg->data);
        return key.data;
    }

    sep = is_root ? "__" : "_";
    {
        const FengSlice *last_seg =
            &type_ref->as.named.segments[type_ref->as.named.segment_count - 1U];
        buf_append_fmt(&key, "%.*s", (int)last_seg->length, last_seg->data);
    }
    for (i = 0U; i < type_ref->as.named.type_arg_count; ++i) {
        char *arg_key = cg_reifiable_sort_key(type_ref->as.named.type_args[i],
                                              owner_type_param_names,
                                              owner_type_param_count,
                                              false);
        if (arg_key != NULL) {
            buf_append_fmt(&key, "%s%s", sep, arg_key);
            free(arg_key);
        }
    }
    return key.data;
}

/* Build a minimal synthetic FengTypeRef from a concrete CGType so it can be
 * used in cg_type_ref_substitute for reifiable dep resolution.
 * Returns a heap-allocated FengTypeRef; caller frees via cg_type_ref_free. */
static FengTypeRef *cg_synthetic_type_ref_from_cgtype(const CGType *t) {
    FengTypeRef *ref;
    const char *name = NULL;

    if (t == NULL) {
        return NULL;
    }
    switch (t->kind) {
        case CG_TYPE_BOOL:    name = "bool";   break;
        case CG_TYPE_I8:      name = "i8";     break;
        case CG_TYPE_I16:     name = "i16";    break;
        case CG_TYPE_I32:     name = "i32";    break;
        case CG_TYPE_I64:     name = "i64";    break;
        case CG_TYPE_U8:      name = "u8";     break;
        case CG_TYPE_U16:     name = "u16";    break;
        case CG_TYPE_U32:     name = "u32";    break;
        case CG_TYPE_U64:     name = "u64";    break;
        case CG_TYPE_F32:     name = "f32";    break;
        case CG_TYPE_F64:     name = "f64";    break;
        case CG_TYPE_STRING:  name = "string"; break;
        case CG_TYPE_VOID:    name = "void";   break;
        case CG_TYPE_OBJECT:
            if (t->user != NULL) {
                name = t->user->feng_name;
            }
            break;
        default:
            break;
    }
    if (name == NULL) {
        return NULL;
    }

    ref = (FengTypeRef *)calloc(1U, sizeof(*ref));
    if (ref == NULL) {
        return NULL;
    }
    ref->kind = FENG_TYPE_REF_NAMED;
    ref->as.named.segment_count = 1U;
    ref->as.named.segments = (FengSlice *)calloc(1U, sizeof(FengSlice));
    if (ref->as.named.segments == NULL) {
        free(ref);
        return NULL;
    }
    ref->as.named.segments[0].data = strdup(name);
    ref->as.named.segments[0].length = strlen(name);
    if (ref->as.named.segments[0].data == NULL) {
        free(ref->as.named.segments);
        free(ref);
        return NULL;
    }
    return ref;
}

/* Resolve a reifiable dep's type_ref to its concrete C descriptor symbol name.
 * Substitutes owner type params with concrete type_args, resolves the type,
 * and extracts the descriptor name. Returns a heap-allocated string on
 * success, NULL on failure (error already set on CG). */
static char *cg_resolve_dep_descriptor_name(CG *cg,
                                            const FengTypeRef *dep_type_ref,
                                            const FengTypeParam *owner_type_params,
                                            size_t owner_type_param_count,
                                            FengTypeRef *const *concrete_type_args,
                                            const FengProgram *reference_program,
                                            FengReifiableDepKind expected_kind,
                                            const FengToken *blame) {
    FengTypeRef *substituted;
    CGType *resolved = NULL;
    const char *name = NULL;
    char *result = NULL;
    bool handled = false;
    const FengProgram *fallback_program = reference_program;

    if (owner_type_param_count > 0U &&
        cg_type_ref_contains_type_param(
            dep_type_ref,
            &(CGTypeParamScope){
                .first = owner_type_params,
                .first_count = owner_type_param_count,
            })) {
        fallback_program = NULL;
    }

    substituted = cg_type_ref_substitute(dep_type_ref,
                                         owner_type_params,
                                         owner_type_param_count,
                                         concrete_type_args);
    if (substituted == NULL) {
        (void)cg_fail(cg, *blame,
            "CE0290", "codegen: failed to substitute type params in reifiable dep");
        return NULL;
    }
    if (!cg_try_resolve_declared_generic_type_ref(cg,
                                                  dep_type_ref,
                                                  substituted,
                                                  reference_program,
                                                  blame,
                                                  &resolved,
                                                  &handled) ||
        (!handled &&
         !cg_resolve_type_from_program(cg,
                                       substituted,
                                       fallback_program,
                                       blame,
                                       &resolved))) {
        cg_type_ref_free(substituted);
        return NULL;
    }
    if (expected_kind == FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
        name = cg_aggregate_desc_name(resolved);
    } else {
        if (resolved != NULL && resolved->kind == CG_TYPE_CALLABLE &&
            resolved->user_spec != NULL) {
            name = resolved->user_spec->c_closure_desc_name;
        } else if (resolved != NULL && resolved->user != NULL) {
            name = resolved->user->c_desc_name;
        }
    }
    if (name != NULL) {
        result = strdup(name);
    } else {
        (void)cg_fail(cg, *blame,
            "CE0291", "codegen: failed to resolve descriptor name for reifiable dep");
    }
    cgtype_free(resolved);
    cg_type_ref_free(substituted);
    return result;
}

/* Locate the declaration and stable member ordinal of one spec requirement. */
static bool cg_find_spec_requirement_owner(
    const CG *cg,
    const FengTypeMember *member,
    const FengDecl **out_owner,
    size_t *out_ordinal) {
    if (cg == NULL || cg->analysis == NULL || member == NULL ||
        out_owner == NULL || out_ordinal == NULL) {
        return false;
    }
    *out_owner = NULL;
    *out_ordinal = 0U;
    for (size_t module_index = 0U;
         module_index < cg->analysis->module_count;
         ++module_index) {
        const FengSemanticModule *module =
            &cg->analysis->modules[module_index];

        for (size_t program_index = 0U;
             program_index < module->program_count;
             ++program_index) {
            const FengProgram *program = module->programs[program_index];

            for (size_t decl_index = 0U;
                 decl_index < program->declaration_count;
                 ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl == NULL || decl->kind != FENG_DECL_SPEC ||
                    decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
                    continue;
                }
                for (size_t member_index = 0U;
                     member_index <
                         decl->as.spec_decl.as.object.member_count;
                     ++member_index) {
                    if (decl->as.spec_decl.as.object.members[member_index] ==
                        member) {
                        *out_owner = decl;
                        *out_ordinal = member_index;
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

/* Return the stable shared-body or requirement identity for one callable
 * dependency independently of its closed type arguments. Caller frees. */
static char *cg_callable_dep_identity_name(
    CG *cg,
    const FengReifiableCallableDep *dep) {
    if (cg == NULL || dep == NULL) {
        return NULL;
    }
    if (dep->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
        dep->function_decl != NULL) {
        const GenericFn *generic_fn =
            cg_find_generic_fn_by_decl(cg, dep->function_decl);

        return generic_fn != NULL ? strdup(generic_fn->c_name) : NULL;
    }
    if ((dep->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD ||
         dep->kind == FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD) &&
        dep->fit_decl != NULL && dep->member != NULL) {
        for (size_t index = 0U; index < cg->user_fit_count; ++index) {
            const UserFit *fit = &cg->user_fits[index];

            if (fit->decl == dep->fit_decl) {
                return cg_fit_method_shared_cname(cg, fit, dep->member);
            }
        }
        {
            const BuiltinFit *fit =
                cg_find_builtin_fit_by_decl(cg, dep->fit_decl);
            const UserMethod *method =
                cg_builtin_fit_method_by_member(fit, dep->member);

            if (method != NULL && method->c_name != NULL) {
                return strdup(method->c_name);
            }
        }
    }
    if ((dep->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD ||
         dep->kind == FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD) &&
        dep->member != NULL) {
        const FengDecl *declaring_spec = NULL;
        const FengProgram *owner_program;
        size_t member_ordinal = 0U;
        char *owner_mangle;
        char *spec_name;
        char *member_name;
        Buf identity;

        if (!cg_find_spec_requirement_owner(cg,
                                            dep->member,
                                            &declaring_spec,
                                            &member_ordinal)) {
            return NULL;
        }
        owner_program = cg_find_decl_owner_program(cg, declaring_spec);
        owner_mangle = owner_program != NULL
                           ? cg_module_mangle(
                                 owner_program->module_segments,
                                 owner_program->module_segment_count)
                           : NULL;
        spec_name = cg_sanitize(
            declaring_spec->as.spec_decl.name.data,
            declaring_spec->as.spec_decl.name.length);
        member_name = cg_sanitize(
            dep->member->as.callable.name.data,
            dep->member->as.callable.name.length);
        if (owner_mangle == NULL || spec_name == NULL ||
            member_name == NULL) {
            free(owner_mangle);
            free(spec_name);
            free(member_name);
            return NULL;
        }
        buf_init(&identity);
        buf_append_fmt(&identity,
                       "FengSpecRequirement__%s__%s__m%zu__%s",
                       owner_mangle,
                       spec_name,
                       member_ordinal,
                       member_name);
        free(owner_mangle);
        free(spec_name);
        free(member_name);
        return identity.data;
    }
    if (dep->owner_type_decl != NULL && dep->member != NULL) {
        return cg_generic_type_method_shared_cname(
            cg, dep->owner_type_decl, dep->member);
    }
    return NULL;
}

/* Resolve the semantic dependency set owned by a direct callee. */
static const FengReifiableDepSet *cg_callable_dep_set(
    const CG *cg,
    const FengReifiableCallableDep *dep) {
    if (cg == NULL || dep == NULL) {
        return NULL;
    }
    if (dep->kind == FENG_RESOLVED_CALLABLE_FUNCTION) {
        return feng_semantic_lookup_reifiable_dep_set(
            cg->analysis, dep->function_decl);
    }
    if (dep->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD ||
        dep->kind == FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD) {
        return feng_semantic_lookup_member_reifiable_dep_set(
            cg->analysis, dep->fit_decl, dep->member);
    }
    if (dep->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD ||
        dep->kind == FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD) {
        return NULL;
    }
    return feng_semantic_lookup_member_reifiable_dep_set(
        cg->analysis, dep->owner_type_decl, dep->member);
}

/* A dependency-free shared callable receives a static empty descriptor
 * directly and therefore does not consume a caller callable-dependency slot.
 * Cycles containing no aggregate/type dependency also collapse to empty. */
static bool cg_callable_dep_set_has_descriptor_data_inner(
    const CG *cg,
    const FengReifiableDepSet *dep_set,
    const FengReifiableDepSet *const *stack,
    size_t stack_count) {
    const FengReifiableDepSet **next_stack;
    bool has_data = false;

    if (dep_set == NULL) {
        return false;
    }
    if (dep_set->dep_count > 0U) {
        return true;
    }
    for (size_t index = 0U; index < stack_count; ++index) {
        if (stack[index] == dep_set) {
            return false;
        }
    }
    next_stack = (const FengReifiableDepSet **)calloc(
        stack_count + 1U, sizeof(*next_stack));
    if (next_stack == NULL) {
        return false;
    }
    if (stack_count > 0U) {
        memcpy(next_stack, stack, stack_count * sizeof(*next_stack));
    }
    next_stack[stack_count] = dep_set;
    for (size_t index = 0U;
         index < dep_set->callable_dep_count;
         ++index) {
        if (cg_callable_dep_set_has_descriptor_data_inner(
                cg,
                cg_callable_dep_set(cg,
                                    &dep_set->callable_deps[index]),
                next_stack,
                stack_count + 1U)) {
            has_data = true;
            break;
        }
    }
    free(next_stack);
    return has_data;
}

static bool cg_callable_dep_set_has_descriptor_data(
    const CG *cg,
    const FengReifiableDepSet *dep_set) {
    return cg_callable_dep_set_has_descriptor_data_inner(
        cg, dep_set, NULL, 0U);
}

/* Method-value dependencies carry their own closed receiver/callable
 * metadata and therefore always consume one descriptor slot. Direct calls
 * keep the existing dependency-set emptiness optimisation. */
static bool cg_callable_dep_requires_slot(
    const CG *cg,
    const FengReifiableCallableDep *dep) {
    return dep != NULL &&
           (dep->purpose == FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE ||
            cg_callable_dep_set_has_descriptor_data(
                cg, cg_callable_dep_set(cg, dep)));
}

/* Canonical open callable dependency key used by both shared-body slot
 * assignment and closed wrapper materialization. */
static char *cg_callable_dep_sort_key(
    CG *cg,
    const FengReifiableCallableDep *dep,
    const FengSlice *caller_type_param_names,
    size_t caller_type_param_count) {
    char *identity = cg_callable_dep_identity_name(cg, dep);
    Buf key;

    if (identity == NULL) {
        return NULL;
    }
    buf_init(&key);
    buf_append_fmt(&key, "purpose=%u|", (unsigned)dep->purpose);
    buf_append_cstr(&key, identity);
    free(identity);
    if (dep->owner_instance_type_ref != NULL) {
        char *owner_key = cg_reifiable_sort_key(
            dep->owner_instance_type_ref,
            caller_type_param_names,
            caller_type_param_count,
            true);

        if (owner_key == NULL) {
            buf_free(&key);
            return NULL;
        }
        buf_append_cstr(&key, "|owner=");
        buf_append_cstr(&key, owner_key);
        free(owner_key);
    }
    for (size_t index = 0U;
         index < dep->callable_type_arg_count;
         ++index) {
        char *arg_key = cg_reifiable_sort_key(
            dep->callable_type_args[index],
            caller_type_param_names,
            caller_type_param_count,
            true);

        if (arg_key == NULL) {
            buf_free(&key);
            return NULL;
        }
        buf_append_cstr(&key, "|arg=");
        buf_append_cstr(&key, arg_key);
        free(arg_key);
    }
    if (dep->target_callable_type_ref != NULL) {
        char *target_key = cg_reifiable_sort_key(
            dep->target_callable_type_ref,
            caller_type_param_names,
            caller_type_param_count,
            true);

        if (target_key == NULL) {
            buf_free(&key);
            return NULL;
        }
        buf_append_cstr(&key, "|target=");
        buf_append_cstr(&key, target_key);
        free(target_key);
    }
    return key.data;
}

/* Build the canonical callable slot map for the active shared body. */
static bool cg_activate_callable_dep_mapping(
    CG *cg,
    const FengReifiableDepSet *dep_set,
    const FengSlice *caller_type_param_names,
    size_t caller_type_param_count,
    CGReifiedDependencySource source) {
    char **keys;
    size_t count = 0U;

    for (size_t index = 0U; index < cg->generic_callable_dep_count; ++index) {
        free(cg->generic_callable_dep_keys[index]);
    }
    free(cg->generic_callable_dep_keys);
    cg->generic_callable_dep_keys = NULL;
    cg->generic_callable_dep_count = 0U;
    cg->generic_callable_dep_via_desc =
        source == CG_REIFIED_DEP_SOURCE_FUNCTION;
    if (dep_set == NULL) {
        return true;
    }
    for (size_t index = 0U;
         index < dep_set->callable_dep_count;
         ++index) {
        if (cg_callable_dep_requires_slot(
                cg, &dep_set->callable_deps[index])) {
            ++count;
        }
    }
    if (count == 0U) {
        return true;
    }
    keys = (char **)calloc(count, sizeof(*keys));
    if (keys == NULL) {
        return cg_fail(cg, dep_set->owner_decl->token,
                       "IE0001", "codegen: out of memory");
    }
    {
        size_t next = 0U;

        for (size_t index = 0U;
             index < dep_set->callable_dep_count;
             ++index) {
            if (!cg_callable_dep_requires_slot(
                    cg, &dep_set->callable_deps[index])) {
                continue;
            }
            keys[next] = cg_callable_dep_sort_key(
                cg,
                &dep_set->callable_deps[index],
                caller_type_param_names,
                caller_type_param_count);
            if (keys[next] == NULL) {
                for (size_t free_index = 0U;
                     free_index < next;
                     ++free_index) {
                    free(keys[free_index]);
                }
                free(keys);
                return cg_fail(cg, dep_set->owner_decl->token,
                               "IE0001", "codegen: out of memory");
            }
            ++next;
        }
    }
    for (size_t index = 1U; index < count; ++index) {
        char *current = keys[index];
        size_t previous = index;

        while (previous > 0U &&
               strcmp(keys[previous - 1U], current) > 0) {
            keys[previous] = keys[previous - 1U];
            --previous;
        }
        keys[previous] = current;
    }
    cg->generic_callable_dep_keys = keys;
    cg->generic_callable_dep_count = count;
    return true;
}

/* Build the canonical aggregate, managed, and callable slot maps for one
 * shared body. All three categories use the same dependency source so fields,
 * constructors, and finalizers cannot accidentally mix `_td` and `_desc`. */
static bool cg_activate_reified_dependency_mapping(
    CG *cg,
    const FengReifiableDepSet *dep_set,
    const FengSlice *caller_type_param_names,
    size_t caller_type_param_count,
    CGReifiedDependencySource source,
    FengToken blame) {
    typedef struct CGReifiedDepSortEntry {
        size_t dep_index;
        char *key;
    } CGReifiedDepSortEntry;
    const FengReifiableDepKind kinds[] = {
        FENG_REIFIABLE_DEP_KIND_MANAGED,
        FENG_REIFIABLE_DEP_KIND_AGGREGATE,
    };
    bool via_function_descriptor =
        source == CG_REIFIED_DEP_SOURCE_FUNCTION;

    for (size_t index = 0U;
         index < cg->generic_type_method_rtd_count;
         ++index) {
        free(cg->generic_type_method_rtd_descs[index]);
    }
    free(cg->generic_type_method_rtd_descs);
    cg->generic_type_method_rtd_descs = NULL;
    cg->generic_type_method_rtd_count = 0U;
    cg->generic_type_method_rtd_via_desc = via_function_descriptor;
    for (size_t index = 0U;
         index < cg->generic_type_method_rad_count;
         ++index) {
        free(cg->generic_type_method_rad_descs[index]);
    }
    free(cg->generic_type_method_rad_descs);
    cg->generic_type_method_rad_descs = NULL;
    cg->generic_type_method_rad_count = 0U;
    cg->generic_type_method_rad_via_desc = via_function_descriptor;

    for (size_t kind_index = 0U;
         kind_index < sizeof(kinds) / sizeof(kinds[0]);
         ++kind_index) {
        FengReifiableDepKind kind = kinds[kind_index];
        CGReifiedDepSortEntry *entries = NULL;
        char ***descriptor_names =
            kind == FENG_REIFIABLE_DEP_KIND_MANAGED
                ? &cg->generic_type_method_rtd_descs
                : &cg->generic_type_method_rad_descs;
        size_t *descriptor_count =
            kind == FENG_REIFIABLE_DEP_KIND_MANAGED
                ? &cg->generic_type_method_rtd_count
                : &cg->generic_type_method_rad_count;
        size_t count = 0U;
        size_t next = 0U;

        if (dep_set == NULL) {
            continue;
        }
        for (size_t index = 0U; index < dep_set->dep_count; ++index) {
            if (dep_set->deps[index].kind == kind) {
                ++count;
            }
        }
        if (count == 0U) {
            continue;
        }
        entries = (CGReifiedDepSortEntry *)calloc(
            count, sizeof(*entries));
        if (entries == NULL) {
            return cg_fail(cg, blame,
                           "IE0001", "codegen: out of memory");
        }
        for (size_t index = 0U; index < dep_set->dep_count; ++index) {
            if (dep_set->deps[index].kind != kind) {
                continue;
            }
            entries[next].dep_index = index;
            entries[next].key = cg_reifiable_sort_key(
                dep_set->deps[index].type_ref,
                caller_type_param_names,
                caller_type_param_count,
                true);
            if (entries[next].key == NULL) {
                for (size_t free_index = 0U;
                     free_index < next;
                     ++free_index) {
                    free(entries[free_index].key);
                }
                free(entries);
                return cg_fail(cg, blame,
                               "IE0001", "codegen: out of memory");
            }
            ++next;
        }
        for (size_t index = 1U; index < count; ++index) {
            CGReifiedDepSortEntry current = entries[index];
            size_t previous = index;

            while (previous > 0U &&
                   strcmp(entries[previous - 1U].key,
                          current.key) > 0) {
                entries[previous] = entries[previous - 1U];
                --previous;
            }
            entries[previous] = current;
        }
        *descriptor_names = (char **)calloc(
            count, sizeof(**descriptor_names));
        if (*descriptor_names == NULL) {
            for (size_t index = 0U; index < count; ++index) {
                free(entries[index].key);
            }
            free(entries);
            return cg_fail(cg, blame,
                           "IE0001", "codegen: out of memory");
        }
        *descriptor_count = count;
        for (size_t index = 0U; index < count; ++index) {
            const FengReifiableDep *dep =
                &dep_set->deps[entries[index].dep_index];
            const char *descriptor_name =
                kind == FENG_REIFIABLE_DEP_KIND_MANAGED
                    ? cg_open_generic_managed_descriptor_name(
                          cg, dep->type_ref)
                    : cg_open_generic_aggregate_descriptor_name(
                          cg, dep->type_ref);

            if (descriptor_name != NULL) {
                (*descriptor_names)[index] = strdup(descriptor_name);
                if ((*descriptor_names)[index] == NULL) {
                    for (size_t free_index = 0U;
                         free_index < count;
                         ++free_index) {
                        free(entries[free_index].key);
                    }
                    free(entries);
                    return cg_fail(cg, blame,
                                   "IE0001", "codegen: out of memory");
                }
            }
            free(entries[index].key);
        }
        free(entries);
    }

    return cg_activate_callable_dep_mapping(
        cg,
        dep_set,
        caller_type_param_names,
        caller_type_param_count,
        source);
}

/* Look up one callable dependency in the active shared-body slot map. A NULL
 * result only means the current expression is fully closed or not part of the
 * active dependency domain; no diagnostic is emitted here. */
static char *cg_try_callable_descriptor_expr_for_dep(
    CG *cg,
    const FengReifiableCallableDep *dep) {
    FengSlice *param_names = NULL;
    char *key = NULL;
    char *result = NULL;

    if (cg == NULL || dep == NULL) {
        return NULL;
    }
    if (cg->generic_fn_type_param_count > 0U) {
        param_names = (FengSlice *)calloc(
            cg->generic_fn_type_param_count, sizeof(*param_names));
        if (param_names == NULL) {
            return NULL;
        }
        for (size_t index = 0U;
             index < cg->generic_fn_type_param_count;
             ++index) {
            param_names[index].data =
                cg->generic_fn_type_param_names[index];
            param_names[index].length = strlen(
                cg->generic_fn_type_param_names[index]);
        }
    }
    key = cg_callable_dep_sort_key(
        cg,
        dep,
        param_names,
        cg->generic_fn_type_param_count);
    free(param_names);
    if (key == NULL) {
        return NULL;
    }
    for (size_t index = 0U;
         index < cg->generic_callable_dep_count;
         ++index) {
        if (strcmp(key, cg->generic_callable_dep_keys[index]) == 0) {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(
                &expression,
                "%s->reified_callable_deps[%zu]",
                cg->generic_callable_dep_via_desc ? "_desc" : "_td",
                index);
            result = expression.data;
            break;
        }
    }
    free(key);
    return result;
}

/* Resolve the function descriptor argument for one generic shared callee in
 * an active shared body. Dependency-free callees use an empty descriptor and
 * therefore add no caller slot/read. */
static char *cg_callable_descriptor_expr_for_dep(
    CG *cg,
    const FengReifiableCallableDep *dep,
    FengToken blame) {
    char *result;

    if (cg == NULL || dep == NULL) {
        return NULL;
    }
    if (!cg_callable_dep_requires_slot(cg, dep)) {
        char *identity = cg_callable_dep_identity_name(cg, dep);
        Buf empty;

        buf_init(&empty);
        buf_append_fmt(
            &empty,
            "&(const FengFunctionDescriptor){.name = \"%s\"}",
            identity != NULL ? identity : "generic callable");
        free(identity);
        return empty.data;
    }
    result = cg_try_callable_descriptor_expr_for_dep(cg, dep);
    if (result == NULL) {
        cg_fail(cg, blame, "CE0296",
                "codegen: no reified callable dependency found for generic call");
    }
    return result;
}

/* Resolve one explicit call through the same canonical dependency identity
 * used by synthesized callable sites. */
static char *cg_callable_descriptor_expr_for_call(
    CG *cg,
    const FengExpr *call_expr,
    FengToken blame) {
    FengReifiableCallableDep dep;
    const FengResolvedCallable *resolved;

    if (cg == NULL || call_expr == NULL ||
        call_expr->kind != FENG_EXPR_CALL) {
        return NULL;
    }
    resolved = &call_expr->as.call.resolved_callable;
    memset(&dep, 0, sizeof(dep));
    dep.kind = resolved->kind;
    dep.function_decl = resolved->function_decl;
    dep.owner_type_decl = resolved->owner_type_decl;
    dep.member = resolved->member;
    dep.fit_decl = resolved->fit_decl;
    dep.owner_instance_type_ref = resolved->owner_instance_type_ref;
    dep.callable_type_args = resolved->callable_type_args;
    dep.callable_type_arg_count = resolved->callable_type_arg_count;
    return cg_callable_descriptor_expr_for_dep(cg, &dep, blame);
}

/* Materialize one callee's declaration-ordered parameter list and its closed
 * caller-substituted type arguments. Caller frees both arrays and every
 * returned type argument. */
static bool cg_close_callable_dep_type_args(
    CG *cg,
    const FengReifiableCallableDep *dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    FengToken blame,
    FengTypeParam **out_params,
    FengTypeRef ***out_args,
    size_t *out_count) {
    const FengTypeParam *owner_params = NULL;
    const FengTypeParam *callable_params = NULL;
    size_t owner_count = 0U;
    size_t callable_count = 0U;
    FengTypeParam *params = NULL;
    FengTypeRef **args = NULL;

    *out_params = NULL;
    *out_args = NULL;
    *out_count = 0U;
    if (dep == NULL) {
        return false;
    }
    if (dep->owner_type_decl != NULL &&
        dep->owner_type_decl->kind == FENG_DECL_TYPE) {
        owner_params = dep->owner_type_decl->as.type_decl.type_params;
        owner_count = dep->owner_type_decl->as.type_decl.type_param_count;
    }
    if (dep->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
        dep->function_decl != NULL) {
        callable_params =
            dep->function_decl->as.function_decl.type_params;
        callable_count =
            dep->function_decl->as.function_decl.type_param_count;
    } else if (dep->member != NULL) {
        callable_params = dep->member->as.callable.type_params;
        callable_count = dep->member->as.callable.type_param_count;
    }
    if (owner_count > 0U &&
        (dep->owner_instance_type_ref == NULL ||
         dep->owner_instance_type_ref->kind != FENG_TYPE_REF_NAMED ||
         dep->owner_instance_type_ref->as.named.type_arg_count !=
             owner_count)) {
        return cg_fail(cg, blame,
                       "CE0292", "codegen: generic callable dependency is missing owner type arguments");
    }
    if (dep->callable_type_arg_count != callable_count) {
        return cg_fail(cg, blame,
                       "CE0293", "codegen: generic callable dependency has inconsistent callable type arguments");
    }
    if (owner_count + callable_count == 0U) {
        return true;
    }
    params = (FengTypeParam *)calloc(
        owner_count + callable_count, sizeof(*params));
    args = (FengTypeRef **)calloc(
        owner_count + callable_count, sizeof(*args));
    if (params == NULL || args == NULL) {
        free(params);
        free(args);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    for (size_t index = 0U; index < owner_count; ++index) {
        params[index] = owner_params[index];
        args[index] = cg_type_ref_substitute(
            dep->owner_instance_type_ref->as.named.type_args[index],
            caller_type_params,
            caller_type_param_count,
            caller_type_args);
        if (args[index] == NULL) {
            goto failure;
        }
    }
    for (size_t index = 0U; index < callable_count; ++index) {
        params[owner_count + index] = callable_params[index];
        args[owner_count + index] = cg_type_ref_substitute(
            dep->callable_type_args[index],
            caller_type_params,
            caller_type_param_count,
            caller_type_args);
        if (args[owner_count + index] == NULL) {
            goto failure;
        }
    }
    *out_params = params;
    *out_args = args;
    *out_count = owner_count + callable_count;
    return true;

failure:
    for (size_t index = 0U;
         index < owner_count + callable_count;
         ++index) {
        cg_type_ref_free(args[index]);
    }
    free(args);
    free(params);
    return cg_fail(cg, blame,
                   "CE0294", "codegen: failed to close callable dependency type arguments");
}

/* Emit one static function descriptor for a fully closed callable invocation.
 * The dependency order is the same canonical sort used by the shared body. */
static bool cg_emit_closed_callable_fdesc(CG *cg,
                                          const FengReifiableDepSet *dep_set,
                                          const FengTypeParam *type_params,
                                          size_t type_param_count,
                                          FengTypeRef *const *type_args,
                                          const FengProgram *reference_program,
                                          FengToken blame,
                                          const char *identity_name,
                                          const char *display_name,
                                          const CGClosedCallableValueInit *callable_value,
                                          char **out_expr) {
    typedef struct ClosedDep {
        size_t dep_index;
        char *sort_key;
        char *descriptor_name;
    } ClosedDep;
    typedef struct ClosedCallableDep {
        size_t dep_index;
        char *sort_key;
        char *descriptor_expr;
    } ClosedCallableDep;

    FengSlice *param_names = NULL;
    ClosedDep *aggregate_deps = NULL;
    ClosedDep *managed_deps = NULL;
    ClosedCallableDep *callable_deps = NULL;
    size_t aggregate_count = 0U;
    size_t managed_count = 0U;
    size_t callable_count = 0U;
    char *descriptor_var = NULL;
    char *aggregate_var = NULL;
    char *managed_var = NULL;
    char *callable_var = NULL;
    char *node_key = NULL;
    CGClosedCallableDescriptorNode *node = NULL;
    size_t node_index = (size_t)-1;
    bool ok = false;

    if (out_expr == NULL) {
        return false;
    }
    *out_expr = NULL;

    {
        Buf key;

        buf_init(&key);
        buf_append_cstr(&key,
                        identity_name != NULL
                            ? identity_name
                            : (display_name != NULL
                                   ? display_name
                                   : "generic callable"));
        if (callable_value != NULL && callable_value->surface_key != NULL) {
            buf_append_cstr(&key, "|surface=");
            buf_append_cstr(&key, callable_value->surface_key);
        }
        for (size_t index = 0U; index < type_param_count; ++index) {
            char *type_key = cg_reifiable_sort_key(
                type_args[index], NULL, 0U, true);

            if (type_key == NULL) {
                buf_free(&key);
                goto cleanup;
            }
            buf_append_cstr(&key, "|");
            buf_append_cstr(&key, type_key);
            free(type_key);
        }
        node_key = key.data;
    }
    for (size_t index = 0U;
         index < cg->closed_callable_descriptor_node_count;
         ++index) {
        if (strcmp(cg->closed_callable_descriptor_nodes[index].key,
                   node_key) == 0) {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(
                &expression,
                "&%s",
                cg->closed_callable_descriptor_nodes[index].c_name);
            *out_expr = expression.data;
            ok = *out_expr != NULL;
            goto cleanup;
        }
    }
    if (cg->closed_callable_descriptor_node_count ==
        cg->closed_callable_descriptor_node_capacity) {
        size_t new_capacity =
            cg->closed_callable_descriptor_node_capacity == 0U
                ? 16U
                : cg->closed_callable_descriptor_node_capacity * 2U;
        CGClosedCallableDescriptorNode *grown =
            (CGClosedCallableDescriptorNode *)realloc(
                cg->closed_callable_descriptor_nodes,
                new_capacity * sizeof(*grown));

        if (grown == NULL) {
            goto cleanup;
        }
        cg->closed_callable_descriptor_nodes = grown;
        cg->closed_callable_descriptor_node_capacity = new_capacity;
    }
    node = &cg->closed_callable_descriptor_nodes[
        cg->closed_callable_descriptor_node_count];
    node_index = cg->closed_callable_descriptor_node_count;
    memset(node, 0, sizeof(*node));
    node->key = strdup(node_key);
    {
        Buf name;

        buf_init(&name);
        buf_append_fmt(
            &name,
            "_feng_closed_callable_desc_%zu",
            cg->closed_callable_descriptor_node_count);
        node->c_name = name.data;
    }
    if (node->key == NULL || node->c_name == NULL) {
        free(node->key);
        free(node->c_name);
        memset(node, 0, sizeof(*node));
        goto cleanup;
    }
    node->emitting = true;
    cg->closed_callable_descriptor_node_count++;
    buf_append_fmt(&cg->headers,
                   "static const FengFunctionDescriptor %s;\n",
                   node->c_name);

    if (dep_set != NULL) {
        for (size_t index = 0U; index < dep_set->dep_count; ++index) {
            if (dep_set->deps[index].kind ==
                FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                ++aggregate_count;
            } else {
                ++managed_count;
            }
        }
        for (size_t index = 0U;
             index < dep_set->callable_dep_count;
             ++index) {
            if (cg_callable_dep_requires_slot(
                    cg, &dep_set->callable_deps[index])) {
                ++callable_count;
            }
        }
    }
    if (type_param_count > 0U) {
        param_names = (FengSlice *)calloc(type_param_count,
                                          sizeof(*param_names));
        if (param_names == NULL) {
            goto cleanup;
        }
        for (size_t index = 0U; index < type_param_count; ++index) {
            param_names[index] = type_params[index].name;
        }
    }
    aggregate_deps = aggregate_count > 0U
                         ? (ClosedDep *)calloc(aggregate_count,
                                               sizeof(*aggregate_deps))
                         : NULL;
    managed_deps = managed_count > 0U
                       ? (ClosedDep *)calloc(managed_count,
                                             sizeof(*managed_deps))
                       : NULL;
    callable_deps = callable_count > 0U
                        ? (ClosedCallableDep *)calloc(
                              callable_count, sizeof(*callable_deps))
                        : NULL;
    if ((aggregate_count > 0U && aggregate_deps == NULL) ||
        (managed_count > 0U && managed_deps == NULL) ||
        (callable_count > 0U && callable_deps == NULL)) {
        goto cleanup;
    }

    if (dep_set != NULL && callable_count > 0U) {
        size_t callable_index = 0U;

        for (size_t index = 0U;
             index < dep_set->callable_dep_count;
             ++index) {
            const FengReifiableCallableDep *callable_dep =
                &dep_set->callable_deps[index];

            if (!cg_callable_dep_requires_slot(cg, callable_dep)) {
                continue;
            }
            callable_deps[callable_index].dep_index = index;
            callable_deps[callable_index].sort_key =
                cg_callable_dep_sort_key(
                    cg,
                    callable_dep,
                    param_names,
                    type_param_count);
            if (callable_deps[callable_index].sort_key == NULL) {
                goto cleanup;
            }
            ++callable_index;
        }
    }

    if (dep_set != NULL) {
        size_t aggregate_index = 0U;
        size_t managed_index = 0U;

        for (size_t index = 0U; index < dep_set->dep_count; ++index) {
            ClosedDep *slot;

            if (dep_set->deps[index].kind ==
                FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                slot = &aggregate_deps[aggregate_index++];
            } else {
                slot = &managed_deps[managed_index++];
            }
            slot->dep_index = index;
            slot->sort_key = cg_reifiable_sort_key(
                dep_set->deps[index].type_ref,
                param_names,
                type_param_count,
                true);
            if (slot->sort_key == NULL) {
                goto cleanup;
            }
        }
    }

#define SORT_CLOSED_DEPS(items, count)                                           \
    do {                                                                         \
        for (size_t _i = 1U; _i < (count); ++_i) {                              \
            ClosedDep _current = (items)[_i];                                    \
            size_t _j = _i;                                                      \
            while (_j > 0U &&                                                    \
                   strcmp((items)[_j - 1U].sort_key,                             \
                          _current.sort_key) > 0) {                              \
                (items)[_j] = (items)[_j - 1U];                                  \
                --_j;                                                            \
            }                                                                    \
            (items)[_j] = _current;                                              \
        }                                                                        \
    } while (0)

    SORT_CLOSED_DEPS(aggregate_deps, aggregate_count);
    SORT_CLOSED_DEPS(managed_deps, managed_count);
#undef SORT_CLOSED_DEPS
    for (size_t index = 1U; index < callable_count; ++index) {
        ClosedCallableDep current = callable_deps[index];
        size_t previous = index;

        while (previous > 0U &&
               strcmp(callable_deps[previous - 1U].sort_key,
                      current.sort_key) > 0) {
            callable_deps[previous] = callable_deps[previous - 1U];
            --previous;
        }
        callable_deps[previous] = current;
    }

    for (size_t index = 0U; index < aggregate_count; ++index) {
        aggregate_deps[index].descriptor_name =
            cg_resolve_dep_descriptor_name(
                cg,
                dep_set->deps[aggregate_deps[index].dep_index].type_ref,
                type_params,
                type_param_count,
                type_args,
                reference_program,
                FENG_REIFIABLE_DEP_KIND_AGGREGATE,
                &blame);
        if (aggregate_deps[index].descriptor_name == NULL) {
            goto cleanup;
        }
    }
    for (size_t index = 0U; index < managed_count; ++index) {
        managed_deps[index].descriptor_name =
            cg_resolve_dep_descriptor_name(
                cg,
                dep_set->deps[managed_deps[index].dep_index].type_ref,
                type_params,
                type_param_count,
                type_args,
                reference_program,
                FENG_REIFIABLE_DEP_KIND_MANAGED,
                &blame);
        if (managed_deps[index].descriptor_name == NULL) {
            goto cleanup;
        }
    }
    for (size_t index = 0U; index < callable_count; ++index) {
        const FengReifiableCallableDep *callable_dep =
            &dep_set->callable_deps[callable_deps[index].dep_index];

        if (callable_dep->purpose ==
            FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE) {
                if (!cg_emit_closed_callable_dep_expr(
                    cg,
                    callable_dep,
                    type_params,
                    type_param_count,
                    type_args,
                    reference_program,
                    blame,
                    &callable_deps[index].descriptor_expr)) {
                goto cleanup;
            }
            continue;
        }
        const FengReifiableDepSet *callee_dep_set =
            cg_callable_dep_set(cg, callable_dep);
        const FengDecl *reference_decl =
            callable_dep->function_decl != NULL
                ? callable_dep->function_decl
                : (callable_dep->fit_decl != NULL
                       ? callable_dep->fit_decl
                       : callable_dep->owner_type_decl);
        FengTypeParam *callee_params = NULL;
        FengTypeRef **callee_args = NULL;
        size_t callee_count = 0U;
        char *callee_identity = NULL;
        char *callee_display = NULL;

        if (!cg_close_callable_dep_type_args(
                cg,
                callable_dep,
                type_params,
                type_param_count,
                type_args,
                blame,
                &callee_params,
                &callee_args,
                &callee_count)) {
            goto cleanup;
        }
        callee_identity =
            cg_callable_dep_identity_name(cg, callable_dep);
        if (callable_dep->function_decl != NULL) {
            FengSlice name =
                callable_dep->function_decl->as.function_decl.name;
            callee_display = strndup(name.data, name.length);
        } else if (callable_dep->member != NULL) {
            FengSlice name = callable_dep->member->as.callable.name;
            callee_display = strndup(name.data, name.length);
        }
        if (callee_identity == NULL || callee_display == NULL ||
            !cg_emit_closed_callable_fdesc(
                cg,
                callee_dep_set,
                callee_params,
                callee_count,
                callee_args,
                cg_find_decl_owner_program(cg, reference_decl),
                blame,
                callee_identity,
                callee_display,
                NULL,
                &callable_deps[index].descriptor_expr)) {
            free(callee_identity);
            free(callee_display);
            for (size_t arg_index = 0U;
                 arg_index < callee_count;
                 ++arg_index) {
                cg_type_ref_free(callee_args[arg_index]);
            }
            free(callee_args);
            free(callee_params);
            goto cleanup;
        }
        free(callee_identity);
        free(callee_display);
        for (size_t arg_index = 0U;
             arg_index < callee_count;
             ++arg_index) {
            cg_type_ref_free(callee_args[arg_index]);
        }
        free(callee_args);
        free(callee_params);
    }

    node = node_index < cg->closed_callable_descriptor_node_count
               ? &cg->closed_callable_descriptor_nodes[node_index]
               : NULL;
    descriptor_var = node != NULL ? strdup(node->c_name) : NULL;
    if (descriptor_var == NULL) {
        goto cleanup;
    }
    if (aggregate_count > 0U) {
        Buf name;
        buf_init(&name);
        buf_append_fmt(&name, "%s__agg", descriptor_var);
        aggregate_var = name.data;
        if (aggregate_var == NULL) {
            goto cleanup;
        }
        buf_append_fmt(&cg->statics,
            "static const FengAggregateDescriptor *const %s[] = {",
            aggregate_var);
        for (size_t index = 0U; index < aggregate_count; ++index) {
            buf_append_fmt(&cg->statics,
                           "%s&%s",
                           index == 0U ? "" : ", ",
                           aggregate_deps[index].descriptor_name);
        }
        buf_append_cstr(&cg->statics, "};\n");
    }
    if (managed_count > 0U) {
        Buf name;
        buf_init(&name);
        buf_append_fmt(&name, "%s__type", descriptor_var);
        managed_var = name.data;
        if (managed_var == NULL) {
            goto cleanup;
        }
        buf_append_fmt(&cg->statics,
            "static const FengTypeDescriptor *const %s[] = {",
            managed_var);
        for (size_t index = 0U; index < managed_count; ++index) {
            buf_append_fmt(&cg->statics,
                           "%s&%s",
                           index == 0U ? "" : ", ",
                           managed_deps[index].descriptor_name);
        }
        buf_append_cstr(&cg->statics, "};\n");
    }
    if (callable_count > 0U) {
        Buf name;
        buf_init(&name);
        buf_append_fmt(&name, "%s__callable", descriptor_var);
        callable_var = name.data;
        if (callable_var == NULL) {
            goto cleanup;
        }
        buf_append_fmt(&cg->statics,
                       "static const FengFunctionDescriptor *const %s[] = {",
                       callable_var);
        for (size_t index = 0U; index < callable_count; ++index) {
            buf_append_fmt(&cg->statics,
                           "%s%s",
                           index == 0U ? "" : ", ",
                           callable_deps[index].descriptor_expr);
        }
        buf_append_cstr(&cg->statics, "};\n");
    }
    buf_append_fmt(&cg->statics,
                   "static const FengFunctionDescriptor %s = {"
                   ".name = \"%s\"",
                   descriptor_var,
                   display_name != NULL ? display_name : "generic callable");
    if (aggregate_count > 0U) {
        buf_append_fmt(&cg->statics,
                       ", .reified_agg_deps_count = %zu, "
                       ".reified_agg_deps = %s",
                       aggregate_count,
                       aggregate_var);
    }
    if (managed_count > 0U) {
        buf_append_fmt(&cg->statics,
                       ", .reified_type_deps_count = %zu, "
                       ".reified_type_deps = %s",
                       managed_count,
                       managed_var);
    }
    if (callable_count > 0U) {
        buf_append_fmt(&cg->statics,
                       ", .reified_callable_deps_count = %zu, "
                       ".reified_callable_deps = %s",
                       callable_count,
                       callable_var);
    }
    if (callable_value != NULL) {
        buf_append_cstr(&cg->statics, ", .callable_value = {");
        if (callable_value->static_value_expr != NULL) {
            buf_append_fmt(&cg->statics,
                           ".static_value = %s",
                           callable_value->static_value_expr);
        }
        if (callable_value->closure_desc_expr != NULL) {
            buf_append_fmt(&cg->statics,
                           "%s.closure_desc = %s",
                           callable_value->static_value_expr != NULL ? ", " : "",
                           callable_value->closure_desc_expr);
        }
        if (callable_value->invoke_expr != NULL) {
            buf_append_fmt(&cg->statics,
                           "%s.invoke = (void (*)(void))%s",
                           callable_value->static_value_expr != NULL ||
                                   callable_value->closure_desc_expr != NULL
                               ? ", "
                               : "",
                           callable_value->invoke_expr);
        }
        if (callable_value->aggregate_capture_desc_expr != NULL) {
            buf_append_fmt(&cg->statics,
                           ", .aggregate_capture_desc = %s",
                           callable_value->aggregate_capture_desc_expr);
        }
        if (callable_value->aggregate_capture_offset_expr != NULL) {
            buf_append_fmt(&cg->statics,
                           ", .aggregate_capture_offset = %s",
                           callable_value->aggregate_capture_offset_expr);
        }
        buf_append_cstr(&cg->statics, "}");
    }
    buf_append_cstr(&cg->statics, "};\n");
    node->emitting = false;
    node->emitted = true;

    {
        Buf expression;
        buf_init(&expression);
        buf_append_fmt(&expression, "&%s", descriptor_var);
        *out_expr = expression.data;
    }
    ok = *out_expr != NULL;

cleanup:
    if (!ok && !cg->failed) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    if (aggregate_deps != NULL) {
        for (size_t index = 0U; index < aggregate_count; ++index) {
            free(aggregate_deps[index].sort_key);
            free(aggregate_deps[index].descriptor_name);
        }
    }
    if (managed_deps != NULL) {
        for (size_t index = 0U; index < managed_count; ++index) {
            free(managed_deps[index].sort_key);
            free(managed_deps[index].descriptor_name);
        }
    }
    if (callable_deps != NULL) {
        for (size_t index = 0U; index < callable_count; ++index) {
            free(callable_deps[index].sort_key);
            free(callable_deps[index].descriptor_expr);
        }
    }
    free(aggregate_deps);
    free(managed_deps);
    free(callable_deps);
    free(param_names);
    free(node_key);
    free(descriptor_var);
    free(aggregate_var);
    free(managed_var);
    free(callable_var);
    return ok;
}

/* Reserve or locate the stable static descriptor symbol for a closed callable
 * before its definition is emitted. Callable adapters use this symbol to bind
 * the same descriptor that their shared target body receives. */
static char *cg_closed_callable_descriptor_c_name_for(
    CG *cg,
    size_t type_param_count,
    FengTypeRef *const *type_args,
    const char *identity_name,
    const char *display_name,
    const CGClosedCallableValueInit *callable_value) {
    Buf key;
    char *result = NULL;

    if (cg == NULL) {
        return NULL;
    }
    buf_init(&key);
    buf_append_cstr(&key,
                    identity_name != NULL
                        ? identity_name
                        : (display_name != NULL
                               ? display_name
                               : "generic callable"));
    if (callable_value != NULL && callable_value->surface_key != NULL) {
        buf_append_cstr(&key, "|surface=");
        buf_append_cstr(&key, callable_value->surface_key);
    }
    for (size_t index = 0U; index < type_param_count; ++index) {
        char *type_key = cg_reifiable_sort_key(
            type_args[index], NULL, 0U, true);

        if (type_key == NULL) {
            buf_free(&key);
            return NULL;
        }
        buf_append_cstr(&key, "|");
        buf_append_cstr(&key, type_key);
        free(type_key);
    }
    for (size_t index = 0U;
         index < cg->closed_callable_descriptor_node_count;
         ++index) {
        if (strcmp(cg->closed_callable_descriptor_nodes[index].key,
                   key.data) == 0) {
            result = strdup(
                cg->closed_callable_descriptor_nodes[index].c_name);
            buf_free(&key);
            return result;
        }
    }
    {
        Buf name;

        buf_init(&name);
        buf_append_fmt(&name,
                       "_feng_closed_callable_desc_%zu",
                       cg->closed_callable_descriptor_node_count);
        result = name.data;
    }
    buf_free(&key);
    return result;
}

/* Close one generic top-level function value against a target callable
 * surface. The resulting descriptor owns both the shared-body dependency
 * graph and an immortal callable value whose adapter binds that descriptor. */
static bool cg_emit_closed_callable_function_value_dep_expr(
    CG *cg,
    const FengReifiableCallableDep *callable_dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    FengToken blame,
    char **out_expr) {
    const GenericFn *function;
    const FengReifiableDepSet *callee_dep_set;
    const FengProgram *reference_program;
    FengTypeParam *callee_params = NULL;
    FengTypeRef **callee_args = NULL;
    size_t callee_count = 0U;
    FengTypeRef *closed_target_ref = NULL;
    CGType *target_type = NULL;
    bool target_handled = false;
    CGClosedCallableValueInit value_init;
    char *surface_key = NULL;
    char *identity = NULL;
    char *display = NULL;
    char *descriptor_c_name = NULL;
    char *static_value_expr = NULL;
    const char *static_value = NULL;
    const char *adapter = NULL;
    bool ok = false;

    if (callable_dep == NULL ||
        callable_dep->kind != FENG_RESOLVED_CALLABLE_FUNCTION ||
        callable_dep->function_decl == NULL ||
        callable_dep->target_callable_type_ref == NULL) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: invalid top-level callable-value dependency");
    }
    function = cg_find_generic_fn_by_decl(cg, callable_dep->function_decl);
    if (function == NULL) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: generic callable value source was not registered");
    }
    reference_program = function->owner_program;
    closed_target_ref = cg_type_ref_substitute(
        callable_dep->target_callable_type_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    if (closed_target_ref == NULL ||
        !cg_try_resolve_declared_generic_type_ref(
            cg,
            callable_dep->target_callable_type_ref,
            closed_target_ref,
            reference_program,
            &blame,
            &target_type,
            &target_handled) ||
        (!target_handled &&
         !cg_resolve_type(cg, closed_target_ref, &blame, &target_type))) {
        goto cleanup;
    }
    if (target_type == NULL || target_type->kind != CG_TYPE_CALLABLE ||
        target_type->user_spec == NULL) {
        cg_fail(cg,
                blame,
                "IE0002",
                "codegen: closed top-level callable-value target is not callable");
        goto cleanup;
    }
    if (!cg_close_callable_dep_type_args(cg,
                                         callable_dep,
                                         caller_type_params,
                                         caller_type_param_count,
                                         caller_type_args,
                                         blame,
                                         &callee_params,
                                         &callee_args,
                                         &callee_count)) {
        goto cleanup;
    }
    callee_dep_set = cg_callable_dep_set(cg, callable_dep);
    identity = cg_callable_dep_identity_name(cg, callable_dep);
    {
        FengSlice name = callable_dep->function_decl->as.function_decl.name;

        display = strndup(name.data, name.length);
    }
    surface_key = cg_reifiable_sort_key(closed_target_ref, NULL, 0U, true);
    memset(&value_init, 0, sizeof value_init);
    value_init.surface_key = surface_key;
    descriptor_c_name = cg_closed_callable_descriptor_c_name_for(
        cg,
        callee_count,
        callee_args,
        identity,
        display,
        &value_init);
    if (identity == NULL || display == NULL || surface_key == NULL ||
        descriptor_c_name == NULL ||
        !cg_ensure_reified_callable_function_value(
            cg,
            target_type->user_spec,
            function,
            descriptor_c_name,
            callee_args,
            callee_count,
            blame,
            &static_value,
            &adapter)) {
        goto cleanup;
    }
    (void)adapter;
    {
        Buf expression;

        buf_init(&expression);
        buf_append_fmt(&expression, "&%s", static_value);
        static_value_expr = expression.data;
    }
    if (static_value_expr == NULL) {
        cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    value_init.static_value_expr = static_value_expr;
    ok = cg_emit_closed_callable_fdesc(
        cg,
        callee_dep_set,
        callee_params,
        callee_count,
        callee_args,
        reference_program,
        blame,
        identity,
        display,
        &value_init,
        out_expr);

cleanup:
    free(surface_key);
    free(identity);
    free(display);
    free(descriptor_c_name);
    free(static_value_expr);
    for (size_t index = 0U; index < callee_count; ++index) {
        cg_type_ref_free(callee_args[index]);
    }
    free(callee_args);
    free(callee_params);
    cg_type_ref_free(closed_target_ref);
    cgtype_free(target_type);
    return ok;
}

/* Resolve the exact object-form or intersection-form constraint carried by
 * an instance or static callable dependency whose owner is one direct caller
 * type parameter. */
static const UserSpec *cg_closed_spec_method_constraint(
    CG *cg,
    const FengReifiableCallableDep *callable_dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    const FengProgram *caller_reference_program,
    FengToken blame) {
    size_t param_index = 0U;
    const FengTypeRef *constraint_ref;
    FengTypeRef *closed_constraint_ref = NULL;
    CGType *constraint_type = NULL;
    bool constraint_handled = false;
    UserSpec *constraint_spec = NULL;

    if (callable_dep == NULL ||
        (callable_dep->kind != FENG_RESOLVED_CALLABLE_SPEC_METHOD &&
         callable_dep->kind !=
             FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD) ||
        callable_dep->owner_type_decl == NULL ||
        callable_dep->owner_type_decl->kind != FENG_DECL_SPEC ||
        !cg_type_ref_is_direct_type_param(
            callable_dep->owner_instance_type_ref,
            caller_type_params,
            caller_type_param_count,
            &param_index) ||
        param_index >= caller_type_param_count) {
        (void)cg_fail(cg,
                      blame,
                      "IE0002",
                      "codegen: constrained-generic method-value owner is not a direct caller type parameter");
        return NULL;
    }
    constraint_ref = caller_type_params[param_index].constraint;
    if (constraint_ref == NULL) {
        (void)cg_fail(cg,
                      blame,
                      "IE0002",
                      "codegen: constrained-generic method-value owner has no spec constraint");
        return NULL;
    }
    closed_constraint_ref = cg_type_ref_substitute(
        constraint_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    if (closed_constraint_ref == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        return NULL;
    }

    if (!cg_try_resolve_declared_generic_type_ref(
            cg,
            constraint_ref,
            closed_constraint_ref,
            caller_reference_program,
            &blame,
            &constraint_type,
            &constraint_handled) ||
        (!constraint_handled &&
         !cg_resolve_type_from_program(cg,
                                       closed_constraint_ref,
                                       caller_reference_program,
                                       &blame,
                                       &constraint_type))) {
        cg_type_ref_free(closed_constraint_ref);
        return NULL;
    }
    if (constraint_type != NULL &&
        constraint_type->kind == CG_TYPE_SPEC &&
        constraint_type->user_spec != NULL) {
        constraint_spec = (UserSpec *)constraint_type->user_spec;
    }
    cg_type_ref_free(closed_constraint_ref);
    if (constraint_spec == NULL ||
        (constraint_spec->form != FENG_SPEC_FORM_OBJECT &&
         constraint_spec->form != FENG_SPEC_FORM_INTERSECTION) ||
        !cg_ensure_user_spec_members_registered(cg, constraint_spec)) {
        cgtype_free(constraint_type);
        if (!cg->failed) {
            (void)cg_fail(cg,
                          blame,
                          "IE0002",
                          "codegen: closed constrained-generic method-value spec was not registered");
        }
        return NULL;
    }
    cgtype_free(constraint_type);
    return constraint_spec;
}

/* Materialize the closed callable descriptor for one object/intersection-
 * constrained generic instance method value. The adapter's witness and
 * receiver layout are fixed here; the provider shared body later performs
 * only one descriptor-slot read and one receiver copy into the callable
 * closure. */
static bool cg_emit_closed_callable_spec_method_value_dep_expr(
    CG *cg,
    const FengReifiableCallableDep *callable_dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    const FengProgram *caller_reference_program,
    FengToken blame,
    char **out_expr) {
    FengTypeRef *closed_receiver_ref = NULL;
    FengTypeRef *closed_target_ref = NULL;
    CGType *receiver_type = NULL;
    CGType *target_type = NULL;
    bool receiver_handled = false;
    bool target_handled = false;
    const UserSpec *receiver_spec = NULL;
    const UserSpecMember *method = NULL;
    char *receiver_descriptor_expr = NULL;
    char *surface_key = NULL;
    char *identity = NULL;
    char *display = NULL;
    char *descriptor_c_name = NULL;
    char *closure_desc_expr = NULL;
    char *aggregate_desc_expr = NULL;
    char *capture_offset_expr = NULL;
    const CGCallableGenericSpecMethodValueSupport *support = NULL;
    CGClosedCallableValueInit value_init;
    bool ok = false;

    if (cg == NULL || callable_dep == NULL || out_expr == NULL ||
        callable_dep->kind != FENG_RESOLVED_CALLABLE_SPEC_METHOD ||
        callable_dep->member == NULL ||
        callable_dep->target_callable_type_ref == NULL) {
        return cg_fail(cg,
                       blame,
                       "IE0002",
                       "codegen: invalid constrained-generic method-value dependency");
    }
    *out_expr = NULL;
    closed_receiver_ref = cg_type_ref_substitute(
        callable_dep->owner_instance_type_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    closed_target_ref = cg_type_ref_substitute(
        callable_dep->target_callable_type_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    if (closed_receiver_ref == NULL || closed_target_ref == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (!cg_try_resolve_declared_generic_type_ref(
            cg,
            callable_dep->owner_instance_type_ref,
            closed_receiver_ref,
            caller_reference_program,
            &blame,
            &receiver_type,
            &receiver_handled) ||
        (!receiver_handled &&
         !cg_resolve_type_from_program(cg,
                                       closed_receiver_ref,
                                       caller_reference_program,
                                       &blame,
                                       &receiver_type)) ||
        !cg_try_resolve_declared_generic_type_ref(
            cg,
            callable_dep->target_callable_type_ref,
            closed_target_ref,
            caller_reference_program,
            &blame,
            &target_type,
            &target_handled) ||
        (!target_handled &&
         !cg_resolve_type_from_program(cg,
                                       closed_target_ref,
                                       caller_reference_program,
                                       &blame,
                                       &target_type))) {
        goto cleanup;
    }
    if (receiver_type == NULL ||
        receiver_type->kind == CG_TYPE_GENERIC_PARAM ||
        target_type == NULL || target_type->kind != CG_TYPE_CALLABLE ||
        target_type->user_spec == NULL) {
        (void)cg_fail(cg,
                      blame,
                      "IE0002",
                      "codegen: closed constrained-generic method-value dependency has an invalid receiver or target");
        goto cleanup;
    }
    receiver_spec = cg_closed_spec_method_constraint(
        cg,
        callable_dep,
        caller_type_params,
        caller_type_param_count,
        caller_type_args,
        caller_reference_program,
        blame);
    if (receiver_spec == NULL) {
        goto cleanup;
    }
    method = cg_user_spec_member_for_method_value(
        receiver_spec,
        callable_dep->member,
        target_type->user_spec,
        false);
    if (method == NULL || method->kind != USM_KIND_METHOD ||
        method->is_static) {
        (void)cg_fail(cg,
                      blame,
                      "IE0002",
                      "codegen: constrained-generic method-value requirement was not registered");
        goto cleanup;
    }
    if (!cg_generic_descriptor_expr(cg,
                                    receiver_type,
                                    receiver_spec,
                                    &blame,
                                    &receiver_descriptor_expr)) {
        goto cleanup;
    }

    {
        char *target_key = cg_reifiable_sort_key(
            closed_target_ref, NULL, 0U, true);
        char *receiver_key = cg_reifiable_sort_key(
            closed_receiver_ref, NULL, 0U, true);
        Buf key;

        if (target_key == NULL || receiver_key == NULL) {
            free(target_key);
            free(receiver_key);
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        buf_init(&key);
        buf_append_fmt(&key,
                       "%s|receiver=%s|witness=%s",
                       target_key,
                       receiver_key,
                       receiver_spec->c_witness_struct_name);
        surface_key = key.data;
        free(target_key);
        free(receiver_key);
    }
    identity = cg_callable_dep_identity_name(cg, callable_dep);
    display = strndup(callable_dep->member->as.callable.name.data,
                      callable_dep->member->as.callable.name.length);
    memset(&value_init, 0, sizeof(value_init));
    value_init.surface_key = surface_key;
    descriptor_c_name = cg_closed_callable_descriptor_c_name_for(
        cg,
        0U,
        NULL,
        identity,
        display,
        &value_init);
    if (surface_key == NULL || identity == NULL || display == NULL ||
        descriptor_c_name == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    support = cg_ensure_callable_generic_spec_method_value(
        cg,
        target_type->user_spec,
        receiver_spec,
        method,
        receiver_type,
        receiver_descriptor_expr,
        descriptor_c_name,
        blame);
    if (support == NULL) {
        goto cleanup;
    }
    {
        Buf expression;

        buf_init(&expression);
        buf_append_fmt(&expression, "&%s", support->c_closure_desc);
        closure_desc_expr = expression.data;
    }
    if (support->has_inline_receiver) {
        Buf expression;

        buf_init(&expression);
        buf_append_fmt(&expression,
                       "offsetof(struct %s, _receiver)",
                       support->c_closure_struct);
        capture_offset_expr = expression.data;
        if (cgtype_value_kind(receiver_type) == CG_VK_AGGREGATE) {
            const char *aggregate_name =
                cg_aggregate_desc_name(receiver_type);

            buf_init(&expression);
            if (aggregate_name != NULL) {
                buf_append_fmt(&expression, "&%s", aggregate_name);
            }
            aggregate_desc_expr = expression.data;
        }
    }
    if (closure_desc_expr == NULL ||
        (support->has_inline_receiver && capture_offset_expr == NULL) ||
        (cgtype_value_kind(receiver_type) == CG_VK_AGGREGATE &&
         aggregate_desc_expr == NULL)) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    value_init.closure_desc_expr = closure_desc_expr;
    value_init.invoke_expr = support->c_adapter_fn;
    value_init.aggregate_capture_desc_expr = aggregate_desc_expr;
    value_init.aggregate_capture_offset_expr = capture_offset_expr;
    ok = cg_emit_closed_callable_fdesc(cg,
                                       NULL,
                                       NULL,
                                       0U,
                                       NULL,
                                       caller_reference_program,
                                       blame,
                                       identity,
                                       display,
                                       &value_init,
                                       out_expr);

cleanup:
    cg_type_ref_free(closed_receiver_ref);
    cg_type_ref_free(closed_target_ref);
    cgtype_free(receiver_type);
    cgtype_free(target_type);
    free(receiver_descriptor_expr);
    free(surface_key);
    free(identity);
    free(display);
    free(descriptor_c_name);
    free(closure_desc_expr);
    free(aggregate_desc_expr);
    free(capture_offset_expr);
    return ok;
}

/* Close one T:ObjectSpec static method value. The closed owner descriptor and
 * exact requirement slot are embedded in an immortal callable singleton;
 * the provider shared body later obtains it through one existing callable-
 * dependency slot read and never allocates a receiver closure. */
static bool cg_emit_closed_callable_spec_static_method_value_dep_expr(
    CG *cg,
    const FengReifiableCallableDep *callable_dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    const FengProgram *caller_reference_program,
    FengToken blame,
    char **out_expr) {
    FengTypeRef *closed_owner_ref = NULL;
    FengTypeRef *closed_target_ref = NULL;
    CGType *owner_type = NULL;
    CGType *target_type = NULL;
    bool owner_handled = false;
    bool target_handled = false;
    const UserSpec *receiver_spec = NULL;
    const UserSpecMember *method = NULL;
    char *owner_descriptor_expr = NULL;
    char *surface_key = NULL;
    char *identity = NULL;
    char *display = NULL;
    char *descriptor_c_name = NULL;
    char *static_value_expr = NULL;
    const char *static_value = NULL;
    const char *adapter = NULL;
    CGClosedCallableValueInit value_init;
    bool ok = false;

    if (cg == NULL || callable_dep == NULL || out_expr == NULL ||
        callable_dep->kind !=
            FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD ||
        callable_dep->member == NULL ||
        !callable_dep->member->is_static ||
        callable_dep->owner_instance_type_ref == NULL ||
        callable_dep->target_callable_type_ref == NULL) {
        return cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: invalid constrained-generic static method-value dependency");
    }
    *out_expr = NULL;
    closed_owner_ref = cg_type_ref_substitute(
        callable_dep->owner_instance_type_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    closed_target_ref = cg_type_ref_substitute(
        callable_dep->target_callable_type_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    if (closed_owner_ref == NULL || closed_target_ref == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (!cg_try_resolve_declared_generic_type_ref(
            cg,
            callable_dep->owner_instance_type_ref,
            closed_owner_ref,
            caller_reference_program,
            &blame,
            &owner_type,
            &owner_handled) ||
        (!owner_handled &&
         !cg_resolve_type_from_program(cg,
                                       closed_owner_ref,
                                       caller_reference_program,
                                       &blame,
                                       &owner_type)) ||
        !cg_try_resolve_declared_generic_type_ref(
            cg,
            callable_dep->target_callable_type_ref,
            closed_target_ref,
            caller_reference_program,
            &blame,
            &target_type,
            &target_handled) ||
        (!target_handled &&
         !cg_resolve_type_from_program(cg,
                                       closed_target_ref,
                                       caller_reference_program,
                                       &blame,
                                       &target_type))) {
        goto cleanup;
    }
    if (owner_type == NULL ||
        owner_type->kind == CG_TYPE_GENERIC_PARAM ||
        target_type == NULL || target_type->kind != CG_TYPE_CALLABLE ||
        target_type->user_spec == NULL) {
        (void)cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: closed constrained-generic static method-value dependency has an invalid owner or target");
        goto cleanup;
    }
    receiver_spec = cg_closed_spec_method_constraint(
        cg,
        callable_dep,
        caller_type_params,
        caller_type_param_count,
        caller_type_args,
        caller_reference_program,
        blame);
    if (receiver_spec == NULL) {
        goto cleanup;
    }
    method = cg_user_spec_member_for_method_value(
        receiver_spec,
        callable_dep->member,
        target_type->user_spec,
        true);
    if (method == NULL || method->kind != USM_KIND_METHOD ||
        !method->is_static) {
        (void)cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: constrained-generic static method-value requirement was not registered");
        goto cleanup;
    }
    if (!cg_generic_descriptor_expr(cg,
                                    owner_type,
                                    receiver_spec,
                                    &blame,
                                    &owner_descriptor_expr)) {
        goto cleanup;
    }

    {
        char *target_key = cg_reifiable_sort_key(
            closed_target_ref, NULL, 0U, true);
        char *owner_key = cg_reifiable_sort_key(
            closed_owner_ref, NULL, 0U, true);
        Buf key;

        if (target_key == NULL || owner_key == NULL) {
            free(target_key);
            free(owner_key);
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        buf_init(&key);
        buf_append_fmt(&key,
                       "%s|owner=%s|witness=%s",
                       target_key,
                       owner_key,
                       receiver_spec->c_witness_struct_name);
        surface_key = key.data;
        free(target_key);
        free(owner_key);
    }
    identity = cg_callable_dep_identity_name(cg, callable_dep);
    display = strndup(callable_dep->member->as.callable.name.data,
                      callable_dep->member->as.callable.name.length);
    memset(&value_init, 0, sizeof(value_init));
    value_init.surface_key = surface_key;
    descriptor_c_name = cg_closed_callable_descriptor_c_name_for(
        cg,
        0U,
        NULL,
        identity,
        display,
        &value_init);
    if (surface_key == NULL || identity == NULL || display == NULL ||
        descriptor_c_name == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (!cg_ensure_callable_spec_static_method_value(
            cg,
            target_type->user_spec,
            receiver_spec,
            method,
            owner_descriptor_expr,
            descriptor_c_name,
            blame,
            &static_value,
            &adapter)) {
        goto cleanup;
    }
    (void)adapter;
    {
        Buf expression;

        buf_init(&expression);
        buf_append_fmt(&expression, "&%s", static_value);
        static_value_expr = expression.data;
    }
    if (static_value_expr == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    value_init.static_value_expr = static_value_expr;
    ok = cg_emit_closed_callable_fdesc(cg,
                                       NULL,
                                       NULL,
                                       0U,
                                       NULL,
                                       caller_reference_program,
                                       blame,
                                       identity,
                                       display,
                                       &value_init,
                                       out_expr);

cleanup:
    cg_type_ref_free(closed_owner_ref);
    cg_type_ref_free(closed_target_ref);
    cgtype_free(owner_type);
    cgtype_free(target_type);
    free(owner_descriptor_expr);
    free(surface_key);
    free(identity);
    free(display);
    free(descriptor_c_name);
    free(static_value_expr);
    return ok;
}

/* Close one concrete type/fit static method value. The emitted descriptor
 * owns an immortal receiver-free closure whose adapter binds the exact method
 * wrapper and all generic descriptor arguments at compile time. */
static bool cg_emit_closed_callable_static_method_value_dep_expr(
    CG *cg,
    const FengReifiableCallableDep *callable_dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    const FengProgram *caller_reference_program,
    FengToken blame,
    char **out_expr) {
    const FengReifiableDepSet *callee_dep_set = NULL;
    const FengDecl *reference_decl;
    const FengProgram *callee_reference_program;
    FengTypeRef *closed_owner_ref = NULL;
    FengTypeRef *closed_target_ref = NULL;
    CGType *owner_type = NULL;
    CGType *target_type = NULL;
    bool owner_handled = false;
    bool target_handled = false;
    const UserType *owner = NULL;
    const UserFit *user_fit = NULL;
    const BuiltinFit *builtin_fit = NULL;
    const UserMethod *method = NULL;
    FengTypeParam *callee_params = NULL;
    FengTypeRef **callee_args = NULL;
    size_t callee_count = 0U;
    const UserSpec **method_constraint_specs = NULL;
    CGType **method_type_args = NULL;
    char **method_descriptor_exprs = NULL;
    size_t method_type_param_count = 0U;
    bool *param_uses_address = NULL;
    char *identity = NULL;
    char *display = NULL;
    char *surface_key = NULL;
    char *descriptor_c_name = NULL;
    char *shared_callee_name = NULL;
    char *owner_descriptor_expr = NULL;
    char *static_value_expr = NULL;
    const char *callee_c_name = NULL;
    const char *static_value = NULL;
    const char *adapter = NULL;
    bool uses_shared_dispatch = false;
    CGClosedCallableValueInit value_init;
    bool ok = false;

    if (cg == NULL || callable_dep == NULL || out_expr == NULL ||
        (callable_dep->kind !=
             FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD &&
         callable_dep->kind !=
             FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD) ||
        callable_dep->member == NULL ||
        !callable_dep->member->is_static ||
        callable_dep->owner_instance_type_ref == NULL ||
        callable_dep->target_callable_type_ref == NULL) {
        return cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: invalid static method-value dependency");
    }
    *out_expr = NULL;
    reference_decl = callable_dep->fit_decl != NULL
                         ? callable_dep->fit_decl
                         : callable_dep->owner_type_decl;
    callee_reference_program =
        cg_find_decl_owner_program(cg, reference_decl);
    if (caller_reference_program == NULL) {
        caller_reference_program = callee_reference_program;
    }

    closed_owner_ref = cg_type_ref_substitute(
        callable_dep->owner_instance_type_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    closed_target_ref = cg_type_ref_substitute(
        callable_dep->target_callable_type_ref,
        caller_type_params,
        caller_type_param_count,
        caller_type_args);
    if (closed_owner_ref == NULL || closed_target_ref == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    if (!cg_try_resolve_declared_generic_type_ref(
            cg,
            callable_dep->owner_instance_type_ref,
            closed_owner_ref,
            caller_reference_program,
            &blame,
            &owner_type,
            &owner_handled) ||
        (!owner_handled &&
         !cg_resolve_type_from_program(cg,
                                       closed_owner_ref,
                                       caller_reference_program,
                                       &blame,
                                       &owner_type)) ||
        !cg_try_resolve_declared_generic_type_ref(
            cg,
            callable_dep->target_callable_type_ref,
            closed_target_ref,
            caller_reference_program,
            &blame,
            &target_type,
            &target_handled) ||
        (!target_handled &&
         !cg_resolve_type_from_program(cg,
                                       closed_target_ref,
                                       caller_reference_program,
                                       &blame,
                                       &target_type))) {
        goto cleanup;
    }
    if (target_type == NULL || target_type->kind != CG_TYPE_CALLABLE ||
        target_type->user_spec == NULL) {
        (void)cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: closed static method-value target is not callable");
        goto cleanup;
    }

    if (callable_dep->kind ==
        FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD) {
        if (owner_type == NULL || owner_type->kind != CG_TYPE_OBJECT ||
            owner_type->user == NULL) {
            (void)cg_fail(
                cg,
                blame,
                "IE0002",
                "codegen: closed type static method-value owner is invalid");
            goto cleanup;
        }
        owner = owner_type->user;
        method = cg_user_type_static_method_by_member(
            owner, callable_dep->member);
    } else {
        builtin_fit =
            cg_find_builtin_fit_by_decl(cg, callable_dep->fit_decl);
        if (builtin_fit != NULL) {
            method = cg_builtin_fit_method_by_member(
                builtin_fit, callable_dep->member);
        } else if (owner_type != NULL &&
                   owner_type->kind == CG_TYPE_OBJECT &&
                   owner_type->user != NULL) {
            owner = owner_type->user;
            user_fit = cg_find_user_fit_by_decl_and_target(
                cg, callable_dep->fit_decl, owner);
            method = cg_user_fit_method_by_member(
                user_fit, callable_dep->member);
        }
    }
    if (method == NULL) {
        (void)cg_fail(
            cg,
            blame,
            "IE0002",
            "codegen: closed static method-value source was not registered");
        goto cleanup;
    }
    if (builtin_fit != NULL &&
        builtin_fit->target_type_param_count > 0U) {
        (void)cg_fail(
            cg,
            blame,
            "CE0144",
            "codegen: generic builtin static fit methods are not supported yet");
        goto cleanup;
    }

    uses_shared_dispatch =
        cg_static_method_uses_shared_dispatch(cg, owner, method);
    callee_c_name = method->c_name;
    if (uses_shared_dispatch) {
        const FengDecl *origin_decl = owner->generic_origin_decl != NULL
                                          ? owner->generic_origin_decl
                                          : owner->decl;
        const char *owner_descriptor = cg_user_type_is_value(owner)
                                           ? owner->c_aggregate_desc_name
                                           : owner->c_desc_name;
        Buf expression;

        shared_callee_name = user_fit != NULL
                                 ? cg_fit_method_shared_cname(
                                       cg, user_fit, method->member)
                                 : cg_generic_type_method_shared_cname(
                                       cg, origin_decl, method->member);
        if (shared_callee_name == NULL || owner_descriptor == NULL) {
            (void)cg_fail(
                cg,
                blame,
                "IE0002",
                "codegen: imported static method-value shared dispatch is incomplete");
            goto cleanup;
        }
        buf_init(&expression);
        buf_append_fmt(&expression, "&%s", owner_descriptor);
        owner_descriptor_expr = expression.data;
        if (owner_descriptor_expr == NULL) {
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        callee_c_name = shared_callee_name;
    }

    if (!cg_close_callable_dep_type_args(
            cg,
            callable_dep,
            caller_type_params,
            caller_type_param_count,
            caller_type_args,
            blame,
            &callee_params,
            &callee_args,
            &callee_count)) {
        goto cleanup;
    }
    callee_dep_set = cg_callable_dep_set(cg, callable_dep);
    identity = cg_callable_dep_identity_name(cg, callable_dep);
    display = strdup(method->feng_name);
    surface_key = cg_reifiable_sort_key(
        closed_target_ref, NULL, 0U, true);
    memset(&value_init, 0, sizeof(value_init));
    value_init.surface_key = surface_key;
    descriptor_c_name = cg_closed_callable_descriptor_c_name_for(
        cg,
        callee_count,
        callee_args,
        identity,
        display,
        &value_init);
    if (identity == NULL || display == NULL || surface_key == NULL ||
        descriptor_c_name == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    {
        const FengCallableSignature *signature =
            &callable_dep->member->as.callable;
        size_t owner_type_param_count =
            callable_dep->owner_type_decl != NULL &&
                    callable_dep->owner_type_decl->kind == FENG_DECL_TYPE
                ? callable_dep->owner_type_decl->as.type_decl.type_param_count
                : 0U;

        method_type_param_count = signature->type_param_count;
        method_type_args = method_type_param_count > 0U
                               ? (CGType **)calloc(
                                     method_type_param_count,
                                     sizeof(*method_type_args))
                               : NULL;
        method_descriptor_exprs = method_type_param_count > 0U
                                      ? (char **)calloc(
                                            method_type_param_count,
                                            sizeof(*method_descriptor_exprs))
                                      : NULL;
        param_uses_address = signature->param_count > 0U
                                 ? (bool *)calloc(
                                       signature->param_count,
                                       sizeof(*param_uses_address))
                                 : NULL;
        if ((method_type_param_count > 0U &&
             (method_type_args == NULL ||
              method_descriptor_exprs == NULL)) ||
            (signature->param_count > 0U &&
             param_uses_address == NULL) ||
            !cg_build_method_type_param_constraints(
                cg,
                owner,
                signature,
                blame,
                &method_constraint_specs)) {
            if (!cg->failed) {
                (void)cg_fail(cg,
                              blame,
                              "IE0001",
                              "codegen: out of memory");
            }
            goto cleanup;
        }
        /* The adapter follows the same call surface as direct static calls.
         * Local closed sources use their thin-wrapper ABI; imported generic
         * sources use the provider's declared shared-body ABI. */
        for (size_t index = 0U;
             index < signature->param_count;
             ++index) {
            if (uses_shared_dispatch) {
                if (!cg_generic_static_method_param_uses_address_abi(
                        cg,
                        owner,
                        method,
                        builtin_fit,
                        user_fit,
                        index,
                        &param_uses_address[index])) {
                    if (!cg->failed) {
                        (void)cg_fail(
                            cg,
                            blame,
                            "IE0002",
                            "codegen: static method-value shared parameter ABI could not be resolved");
                    }
                    goto cleanup;
                }
            } else {
                param_uses_address[index] = builtin_fit != NULL
                    ? method->param_types[index] != NULL &&
                          method->param_types[index]->kind ==
                              CG_TYPE_GENERIC_PARAM
                    : cg_shared_generic_param_uses_address(
                          method->param_types[index]);
            }
        }
        for (size_t index = 0U;
             index < method_type_param_count;
             ++index) {
            size_t closed_index = owner_type_param_count + index;

            if (closed_index >= callee_count ||
                !cg_resolve_type_from_program(
                    cg,
                    callee_args[closed_index],
                    caller_reference_program,
                    &blame,
                    &method_type_args[index]) ||
                !cg_generic_descriptor_expr(
                    cg,
                    method_type_args[index],
                    method_constraint_specs[index],
                    &blame,
                    &method_descriptor_exprs[index])) {
                goto cleanup;
            }
        }
    }

    if (!cg_ensure_callable_static_method_value(
            cg,
            target_type->user_spec,
            owner,
            method,
            builtin_fit,
            user_fit,
            callee_c_name,
            owner_descriptor_expr,
            uses_shared_dispatch,
            descriptor_c_name,
            (const char *const *)method_descriptor_exprs,
            method_type_param_count,
            param_uses_address,
            blame,
            &static_value,
            &adapter)) {
        goto cleanup;
    }
    (void)adapter;
    {
        Buf expression;

        buf_init(&expression);
        buf_append_fmt(&expression, "&%s", static_value);
        static_value_expr = expression.data;
    }
    if (static_value_expr == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    value_init.static_value_expr = static_value_expr;
    ok = cg_emit_closed_callable_fdesc(
        cg,
        callee_dep_set,
        callee_params,
        callee_count,
        callee_args,
        callee_reference_program,
        blame,
        identity,
        display,
        &value_init,
        out_expr);

cleanup:
    for (size_t index = 0U;
         index < method_type_param_count;
         ++index) {
        cgtype_free(method_type_args != NULL
                        ? method_type_args[index]
                        : NULL);
        free(method_descriptor_exprs != NULL
                 ? method_descriptor_exprs[index]
                 : NULL);
    }
    free(method_type_args);
    free(method_descriptor_exprs);
    free((void *)method_constraint_specs);
    free(param_uses_address);
    free(identity);
    free(display);
    free(surface_key);
    free(descriptor_c_name);
    free(shared_callee_name);
    free(owner_descriptor_expr);
    free(static_value_expr);
    for (size_t index = 0U; index < callee_count; ++index) {
        cg_type_ref_free(callee_args[index]);
    }
    free(callee_args);
    free(callee_params);
    cgtype_free(owner_type);
    cgtype_free(target_type);
    cg_type_ref_free(closed_owner_ref);
    cg_type_ref_free(closed_target_ref);
    return ok;
}

/* Close one direct generic callable dependency against the current owner or
 * function type arguments and emit/reuse its function descriptor graph. */
static bool cg_emit_closed_callable_dep_expr(
    CG *cg,
    const FengReifiableCallableDep *callable_dep,
    const FengTypeParam *caller_type_params,
    size_t caller_type_param_count,
    FengTypeRef *const *caller_type_args,
    const FengProgram *caller_reference_program,
    FengToken blame,
    char **out_expr) {
    const FengReifiableDepSet *callee_dep_set;
    const FengDecl *reference_decl;
    FengTypeParam *callee_params = NULL;
    FengTypeRef **callee_args = NULL;
    size_t callee_count = 0U;
    char *callee_identity = NULL;
    char *callee_display = NULL;
    bool ok = false;

    if (cg == NULL || callable_dep == NULL || out_expr == NULL) {
        return false;
    }
    *out_expr = NULL;

    if (callable_dep->purpose ==
        FENG_REIFIABLE_CALLABLE_DEP_CALLABLE_VALUE) {
        if (callable_dep->kind == FENG_RESOLVED_CALLABLE_FUNCTION) {
            return cg_emit_closed_callable_function_value_dep_expr(
                cg,
                callable_dep,
                caller_type_params,
                caller_type_param_count,
                caller_type_args,
                blame,
                out_expr);
        }
        if (callable_dep->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD) {
            return cg_emit_closed_callable_spec_method_value_dep_expr(
                cg,
                callable_dep,
                caller_type_params,
                caller_type_param_count,
                caller_type_args,
                caller_reference_program,
                blame,
                out_expr);
        }
        if (callable_dep->kind ==
            FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD) {
            return cg_emit_closed_callable_spec_static_method_value_dep_expr(
                cg,
                callable_dep,
                caller_type_params,
                caller_type_param_count,
                caller_type_args,
                caller_reference_program,
                blame,
                out_expr);
        }
        if (callable_dep->kind ==
                FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD ||
            callable_dep->kind ==
                FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD) {
            return cg_emit_closed_callable_static_method_value_dep_expr(
                cg,
                callable_dep,
                caller_type_params,
                caller_type_param_count,
                caller_type_args,
                caller_reference_program,
                blame,
                out_expr);
        }
        const FengProgram *reference_program = caller_reference_program;

        if (reference_program == NULL) {
            reference_program = cg_find_decl_owner_program(
                cg,
                callable_dep->fit_decl != NULL
                    ? callable_dep->fit_decl
                    : callable_dep->owner_type_decl);
        }
        FengTypeRef *closed_owner_ref = NULL;
        FengTypeRef *closed_target_ref = NULL;
        CGType *owner_type = NULL;
        CGType *target_type = NULL;
        bool owner_handled = false;
        bool target_handled = false;
        const UserFit *fit = NULL;
        const UserMethod *method = NULL;
        const CGCallableMethodValueSupport *support;
        CGClosedCallableValueInit value_init;
        char *surface_key = NULL;
        char *closure_desc_expr = NULL;
        char *aggregate_desc_expr = NULL;
        char *aggregate_offset_expr = NULL;
        char *descriptor_c_name = NULL;
        char *descriptor_expr = NULL;
        char *target_fn_name = NULL;
        const UserSpec **method_constraint_specs = NULL;
        CGType **method_type_args = NULL;
        char **method_descriptor_exprs = NULL;
        size_t method_type_param_count = 0U;
        bool *param_uses_address = NULL;
        char *owner_descriptor_expr = NULL;
        CGReifiedCallableMethodTarget reified_target;

        closed_owner_ref = cg_type_ref_substitute(
            callable_dep->owner_instance_type_ref,
            caller_type_params,
            caller_type_param_count,
            caller_type_args);
        closed_target_ref = cg_type_ref_substitute(
            callable_dep->target_callable_type_ref,
            caller_type_params,
            caller_type_param_count,
            caller_type_args);
        if (closed_owner_ref == NULL || closed_target_ref == NULL) {
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto method_value_cleanup;
        }
        if (!cg_try_resolve_declared_generic_type_ref(
                cg,
                callable_dep->owner_instance_type_ref,
                closed_owner_ref,
                reference_program,
                &blame,
                &owner_type,
                &owner_handled) ||
            (!owner_handled &&
             !cg_resolve_type_from_program(cg,
                                           closed_owner_ref,
                                           reference_program,
                                           &blame,
                                           &owner_type))) {
            goto method_value_cleanup;
        }
        if (!cg_try_resolve_declared_generic_type_ref(
                cg,
                callable_dep->target_callable_type_ref,
                closed_target_ref,
                reference_program,
                &blame,
                &target_type,
                &target_handled) ||
            (!target_handled &&
             !cg_resolve_type_from_program(cg,
                                           closed_target_ref,
                                           reference_program,
                                           &blame,
                                           &target_type))) {
            goto method_value_cleanup;
        }
        if (owner_type == NULL || owner_type->kind != CG_TYPE_OBJECT ||
            owner_type->user == NULL ||
            target_type == NULL || target_type->kind != CG_TYPE_CALLABLE ||
            target_type->user_spec == NULL) {
            (void)cg_fail(
                cg,
                blame,
                "IE0002",
                "codegen: closed method-value dependency has an invalid receiver or callable type");
            goto method_value_cleanup;
        }
        if (callable_dep->fit_decl != NULL) {
            fit = cg_find_user_fit_by_decl_and_target(
                cg, callable_dep->fit_decl, owner_type->user);
            method = cg_user_fit_method_by_member(
                fit, callable_dep->member);
        } else {
            method = cg_user_type_method_by_member(
                owner_type->user, callable_dep->member);
        }
        if (method == NULL) {
            (void)cg_fail(cg,
                          blame,
                          "IE0002",
                          "codegen: closed method-value target method was not registered");
            goto method_value_cleanup;
        }
        surface_key = cg_reifiable_sort_key(
            closed_target_ref, NULL, 0U, true);
        memset(&value_init, 0, sizeof value_init);
        value_init.surface_key = surface_key;

        callee_dep_set = cg_callable_dep_set(cg, callable_dep);
        reference_decl = callable_dep->fit_decl != NULL
                             ? callable_dep->fit_decl
                             : callable_dep->owner_type_decl;
        if (!cg_close_callable_dep_type_args(
                cg,
                callable_dep,
                caller_type_params,
                caller_type_param_count,
                caller_type_args,
                blame,
                &callee_params,
                &callee_args,
                &callee_count)) {
            goto method_value_cleanup;
        }
        callee_identity = cg_callable_dep_identity_name(cg, callable_dep);
        callee_display = strdup(method->feng_name);
        if (callee_identity == NULL || callee_display == NULL) {
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto method_value_cleanup;
        }
        descriptor_c_name = cg_closed_callable_descriptor_c_name_for(
            cg,
            callee_count,
            callee_args,
            callee_identity,
            callee_display,
            &value_init);
        if (descriptor_c_name != NULL) {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(&expression, "&%s", descriptor_c_name);
            descriptor_expr = expression.data;
            buf_init(&expression);
            buf_append_fmt(&expression,
                           "FengCallableTarget__%s",
                           descriptor_c_name);
            target_fn_name = expression.data;
        }
        if (descriptor_c_name == NULL || descriptor_expr == NULL ||
            target_fn_name == NULL) {
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto method_value_cleanup;
        }
        {
            const FengCallableSignature *signature =
                &callable_dep->member->as.callable;
            size_t owner_type_param_count =
                callable_dep->owner_type_decl->as.type_decl.type_param_count;
            method_type_param_count = signature->type_param_count;

            method_type_args = method_type_param_count > 0U
                ? (CGType **)calloc(method_type_param_count,
                                    sizeof(*method_type_args))
                : NULL;
            method_descriptor_exprs = method_type_param_count > 0U
                ? (char **)calloc(method_type_param_count,
                                  sizeof(*method_descriptor_exprs))
                : NULL;
            if ((method_type_param_count > 0U &&
                 (method_type_args == NULL ||
                  method_descriptor_exprs == NULL)) ||
                !cg_build_method_type_param_constraints(
                    cg,
                    owner_type->user,
                    signature,
                    blame,
                    &method_constraint_specs) ||
                !cg_build_shared_callable_param_address_flags(
                    cg,
                    callable_dep->owner_type_decl,
                    signature,
                    reference_program,
                    blame,
                    &param_uses_address)) {
                if (!cg->failed) {
                    (void)cg_fail(cg,
                                  blame,
                                  "IE0001",
                                  "codegen: out of memory");
                }
                goto method_value_cleanup;
            }
            for (size_t index = 0U;
                 index < method_type_param_count;
                 ++index) {
                size_t closed_index = owner_type_param_count + index;

                if (closed_index >= callee_count ||
                    !cg_resolve_type(cg,
                                     callee_args[closed_index],
                                     &blame,
                                     &method_type_args[index]) ||
                    !cg_generic_descriptor_expr(
                        cg,
                        method_type_args[index],
                        method_constraint_specs[index],
                        &blame,
                        &method_descriptor_exprs[index])) {
                    goto method_value_cleanup;
                }
            }
            {
                Buf expression;

                buf_init(&expression);
                buf_append_fmt(
                    &expression,
                    "&%s",
                    cg_user_type_is_value_semantics(owner_type->user)
                        ? owner_type->user->c_aggregate_desc_name
                        : owner_type->user->c_desc_name);
                owner_descriptor_expr = expression.data;
            }
            if (owner_descriptor_expr == NULL) {
                (void)cg_fail(cg,
                              blame,
                              "IE0001",
                              "codegen: out of memory");
                goto method_value_cleanup;
            }
            memset(&reified_target, 0, sizeof reified_target);
            reified_target.shared_c_name = callee_identity;
            reified_target.owner_descriptor_expr = owner_descriptor_expr;
            reified_target.function_descriptor_expr = descriptor_expr;
            reified_target.method_descriptor_exprs =
                (const char *const *)method_descriptor_exprs;
            reified_target.method_descriptor_count = method_type_param_count;
            reified_target.param_uses_address = param_uses_address;
        }
        support = cg_callable_method_value_support(
            cg,
            target_type->user_spec,
            owner_type->user,
            method,
            blame,
            target_fn_name,
            &reified_target);
        if (support == NULL || support->c_closure_struct == NULL ||
            support->c_closure_desc == NULL ||
            support->c_adapter_fn == NULL) {
            if (!cg->failed) {
                (void)cg_fail(
                    cg,
                    blame,
                    "IE0002",
                    "codegen: method-value support is missing reified closure metadata");
            }
            goto method_value_cleanup;
        }
        {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(&expression, "&%s", support->c_closure_desc);
            closure_desc_expr = expression.data;
        }
        if (cg_user_type_is_value_semantics(owner_type->user)) {
            Buf expression;

            buf_init(&expression);
            buf_append_fmt(&expression,
                           "&%s",
                           owner_type->user->c_aggregate_desc_name);
            aggregate_desc_expr = expression.data;
            buf_init(&expression);
            buf_append_fmt(&expression,
                           "offsetof(struct %s, _receiver)",
                           support->c_closure_struct);
            aggregate_offset_expr = expression.data;
        }
        if (closure_desc_expr == NULL ||
            (cg_user_type_is_value_semantics(owner_type->user) &&
             (aggregate_desc_expr == NULL || aggregate_offset_expr == NULL))) {
            (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            goto method_value_cleanup;
        }
        value_init.closure_desc_expr = closure_desc_expr;
        value_init.invoke_expr = support->c_adapter_fn;
        value_init.aggregate_capture_desc_expr = aggregate_desc_expr;
        value_init.aggregate_capture_offset_expr = aggregate_offset_expr;
        ok = cg_emit_closed_callable_fdesc(
            cg,
            callee_dep_set,
            callee_params,
            callee_count,
            callee_args,
            cg_find_decl_owner_program(cg, reference_decl),
            blame,
            callee_identity,
            callee_display,
            &value_init,
            out_expr);

method_value_cleanup:
        free(surface_key);
        free(closure_desc_expr);
        free(aggregate_desc_expr);
        free(aggregate_offset_expr);
        free(descriptor_c_name);
        free(descriptor_expr);
        free(target_fn_name);
        free((void *)method_constraint_specs);
        if (method_type_args != NULL) {
            for (size_t index = 0U;
                 index < method_type_param_count;
                 ++index) {
                cgtype_free(method_type_args[index]);
            }
        }
        if (method_descriptor_exprs != NULL) {
            for (size_t index = 0U;
                 index < method_type_param_count;
                 ++index) {
                free(method_descriptor_exprs[index]);
            }
        }
        free(method_type_args);
        free(method_descriptor_exprs);
        free(param_uses_address);
        free(owner_descriptor_expr);
        free(callee_identity);
        free(callee_display);
        for (size_t index = 0U; index < callee_count; ++index) {
            cg_type_ref_free(callee_args[index]);
        }
        free(callee_args);
        free(callee_params);
        cgtype_free(owner_type);
        cgtype_free(target_type);
        cg_type_ref_free(closed_owner_ref);
        cg_type_ref_free(closed_target_ref);
        return ok;
    }

    callee_dep_set = cg_callable_dep_set(cg, callable_dep);
    reference_decl = callable_dep->function_decl != NULL
        ? callable_dep->function_decl
        : (callable_dep->fit_decl != NULL
               ? callable_dep->fit_decl
               : callable_dep->owner_type_decl);

    if (!cg_close_callable_dep_type_args(
            cg,
            callable_dep,
            caller_type_params,
            caller_type_param_count,
            caller_type_args,
            blame,
            &callee_params,
            &callee_args,
            &callee_count)) {
        goto cleanup;
    }
    callee_identity = cg_callable_dep_identity_name(cg, callable_dep);
    if (callable_dep->function_decl != NULL) {
        FengSlice name = callable_dep->function_decl->as.function_decl.name;
        callee_display = strndup(name.data, name.length);
    } else if (callable_dep->member != NULL) {
        FengSlice name = callable_dep->member->as.callable.name;
        callee_display = strndup(name.data, name.length);
    }
    if (callee_identity == NULL || callee_display == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    ok = cg_emit_closed_callable_fdesc(
        cg,
        callee_dep_set,
        callee_params,
        callee_count,
        callee_args,
        cg_find_decl_owner_program(cg, reference_decl),
        blame,
        callee_identity,
        callee_display,
        NULL,
        out_expr);

cleanup:
    free(callee_identity);
    free(callee_display);
    for (size_t index = 0U; index < callee_count; ++index) {
        cg_type_ref_free(callee_args[index]);
    }
    free(callee_args);
    free(callee_params);
    return ok;
}

/* Emit the owner-wide direct-callable descriptor array. Its canonical order
 * is identical to the slot map activated while emitting fields,
 * constructors, and the finalizer shared body. */
static bool cg_emit_owner_callable_dep_array(
    CG *cg,
    Buf *out,
    const char *owner_descriptor_name,
    const FengReifiableDepSet *dep_set,
    const FengTypeParam *owner_type_params,
    size_t owner_type_param_count,
    FengTypeRef *const *owner_type_args,
    FengToken blame,
    size_t *out_count) {
    typedef struct OwnerCallableDep {
        size_t dep_index;
        char *sort_key;
        char *descriptor_expr;
    } OwnerCallableDep;

    FengSlice *param_names = NULL;
    OwnerCallableDep *deps = NULL;
    size_t count = 0U;
    size_t failed_dep_index = SIZE_MAX;
    bool ok = false;

    if (cg == NULL || out == NULL || owner_descriptor_name == NULL ||
        out_count == NULL) {
        return false;
    }
    *out_count = 0U;
    if (dep_set == NULL) {
        return true;
    }
    for (size_t index = 0U;
         index < dep_set->callable_dep_count;
         ++index) {
        if (cg_callable_dep_requires_slot(
                cg, &dep_set->callable_deps[index])) {
            ++count;
        }
    }
    if (count == 0U) {
        return true;
    }
    if (owner_type_param_count > 0U) {
        param_names = (FengSlice *)calloc(
            owner_type_param_count, sizeof(*param_names));
    }
    deps = (OwnerCallableDep *)calloc(count, sizeof(*deps));
    if ((owner_type_param_count > 0U && param_names == NULL) || deps == NULL) {
        (void)cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t index = 0U; index < owner_type_param_count; ++index) {
        param_names[index] = owner_type_params[index].name;
    }
    {
        size_t next = 0U;

        for (size_t index = 0U;
             index < dep_set->callable_dep_count;
             ++index) {
            const FengReifiableCallableDep *dep =
                &dep_set->callable_deps[index];

            if (!cg_callable_dep_requires_slot(cg, dep)) {
                continue;
            }
            deps[next].dep_index = index;
            deps[next].sort_key = cg_callable_dep_sort_key(
                cg, dep, param_names, owner_type_param_count);
            if (deps[next].sort_key == NULL) {
                char *identity =
                    cg_callable_dep_identity_name(cg, dep);
                (void)cg_fail(
                    cg,
                    blame,
                    "IE0002",
                    "codegen: cannot build owner callable dependency key "
                    "for '%s' in '%s'",
                    identity != NULL ? identity : "<unknown>",
                    owner_descriptor_name);
                free(identity);
                goto cleanup;
            }
            ++next;
        }
    }
    for (size_t index = 1U; index < count; ++index) {
        OwnerCallableDep current = deps[index];
        size_t previous = index;

        while (previous > 0U &&
               strcmp(deps[previous - 1U].sort_key,
                      current.sort_key) > 0) {
            deps[previous] = deps[previous - 1U];
            --previous;
        }
        deps[previous] = current;
    }
    for (size_t index = 0U; index < count; ++index) {
        if (!cg_emit_closed_callable_dep_expr(
                cg,
                &dep_set->callable_deps[deps[index].dep_index],
                owner_type_params,
                owner_type_param_count,
                owner_type_args,
                cg_find_decl_owner_program(cg, dep_set->owner_decl),
                blame,
                &deps[index].descriptor_expr)) {
            failed_dep_index = index;
            goto cleanup;
        }
    }

    buf_append_fmt(
        out,
        "static const FengFunctionDescriptor *const %s__rcd[] = {\n",
        owner_descriptor_name);
    for (size_t index = 0U; index < count; ++index) {
        buf_append_fmt(out, "    %s,\n", deps[index].descriptor_expr);
    }
    buf_append_cstr(out, "};\n\n");
    *out_count = count;
    ok = true;

cleanup:
    if (!ok && !cg->failed) {
        (void)cg_fail(cg, blame,
                      "IE0002",
                      "codegen: failed to close owner callable dependency "
                      "'%s' for '%s'",
                      failed_dep_index < count &&
                              deps[failed_dep_index].sort_key != NULL
                          ? deps[failed_dep_index].sort_key
                          : "<unknown>",
                      owner_descriptor_name);
    }
    if (deps != NULL) {
        for (size_t index = 0U; index < count; ++index) {
            free(deps[index].sort_key);
            free(deps[index].descriptor_expr);
        }
    }
    free(deps);
    free(param_names);
    return ok;
}

/* Resolve one descriptor family for a concrete builtin-array fit call.  The
 * result order must match the shared body's independently sorted dependency
 * map so both sides address the same descriptor index. */
static bool cg_resolve_builtin_fit_dep_descriptor_names(
    CG *cg,
    const BuiltinFit *bf,
    const FengReifiableDepSet *dep_set,
    FengReifiableDepKind kind,
    const CGType *element_type,
    const FengToken *blame,
    char ***out_names,
    size_t *out_count) {
    typedef struct {
        size_t index;
        char *key;
    } SortedDep;

    size_t count = 0U;
    FengSlice *type_param_names = NULL;
    SortedDep *sorted = NULL;
    FengTypeRef *concrete_ref = NULL;
    char **names = NULL;
    bool ok = false;

    *out_names = NULL;
    *out_count = 0U;
    for (size_t i = 0U; i < dep_set->dep_count; ++i) {
        if (dep_set->deps[i].kind == kind) {
            count++;
        }
    }
    if (count == 0U) {
        return true;
    }
    if (element_type == NULL || bf->target_type_param_count != 1U) {
        return cg_fail(cg, *blame,
            "CE0292", "codegen: builtin array fit dependency resolution requires one concrete element type");
    }

    type_param_names = calloc(bf->target_type_param_count,
                              sizeof *type_param_names);
    sorted = calloc(count, sizeof *sorted);
    names = calloc(count, sizeof *names);
    if (type_param_names == NULL || sorted == NULL || names == NULL) {
        cg_fail(cg, *blame, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t i = 0U; i < bf->target_type_param_count; ++i) {
        type_param_names[i] = bf->target_type_params[i].name;
    }

    size_t sorted_index = 0U;
    for (size_t i = 0U; i < dep_set->dep_count; ++i) {
        if (dep_set->deps[i].kind != kind) {
            continue;
        }
        sorted[sorted_index].index = i;
        sorted[sorted_index].key = cg_reifiable_sort_key(
            dep_set->deps[i].type_ref,
            type_param_names,
            bf->target_type_param_count,
            true);
        if (sorted[sorted_index].key == NULL) {
            cg_fail(cg, *blame, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        sorted_index++;
    }
    for (size_t i = 1U; i < count; ++i) {
        SortedDep current = sorted[i];
        size_t j = i;
        while (j > 0U && strcmp(sorted[j - 1U].key, current.key) > 0) {
            sorted[j] = sorted[j - 1U];
            j--;
        }
        sorted[j] = current;
    }

    concrete_ref = cg_type_ref_from_cgtype(cg, element_type, *blame);
    if (concrete_ref == NULL) {
        goto cleanup;
    }
    FengTypeRef *concrete_args[1] = { concrete_ref };
    for (size_t i = 0U; i < count; ++i) {
        names[i] = cg_resolve_dep_descriptor_name(
            cg,
            dep_set->deps[sorted[i].index].type_ref,
            bf->target_type_params,
            bf->target_type_param_count,
            concrete_args,
            bf->owner_program,
            kind,
            blame);
        if (names[i] == NULL) {
            goto cleanup;
        }
    }

    *out_names = names;
    *out_count = count;
    names = NULL;
    ok = true;

cleanup:
    if (names != NULL) {
        for (size_t i = 0U; i < count; ++i) {
            free(names[i]);
        }
    }
    free(names);
    if (sorted != NULL) {
        for (size_t i = 0U; i < count; ++i) {
            free(sorted[i].key);
        }
    }
    free(sorted);
    free(type_param_names);
    cg_type_ref_free(concrete_ref);
    return ok;
}

/* Build the function descriptor passed to a builtin-array fit shared body.
 * Managed and aggregate dependencies are both concrete at the call site. */
static char *cg_builtin_fit_fdesc_expr(CG *cg,
                                       const BuiltinFit *bf,
                                       const UserMethod *method,
                                       const CGType *element_type,
                                       const FengToken *blame) {
    const FengReifiableDepSet *dep_set;
    Buf result;
    char **managed_names = NULL;
    char **aggregate_names = NULL;
    size_t managed_count = 0U;
    size_t aggregate_count = 0U;

    if (bf == NULL || bf->decl == NULL || method == NULL ||
        method->member == NULL) {
        goto simple;
    }

    dep_set = feng_semantic_lookup_member_reifiable_dep_set(
        cg->analysis, bf->decl, method->member);
    if (dep_set == NULL || dep_set->dep_count == 0U) {
        goto simple;
    }

    if (!cg_resolve_builtin_fit_dep_descriptor_names(
            cg, bf, dep_set, FENG_REIFIABLE_DEP_KIND_MANAGED,
            element_type, blame, &managed_names, &managed_count) ||
        !cg_resolve_builtin_fit_dep_descriptor_names(
            cg, bf, dep_set, FENG_REIFIABLE_DEP_KIND_AGGREGATE,
            element_type, blame, &aggregate_names, &aggregate_count)) {
        goto fail;
    }
    if (managed_count == 0U && aggregate_count == 0U) {
        goto simple;
    }

    buf_init(&result);
    buf_append_fmt(&result,
                   "&(const FengFunctionDescriptor){.name = \"%s\"",
                   method->feng_name);
    if (managed_count > 0U) {
        buf_append_fmt(&result,
            ", .reified_type_deps_count = %zu, "
            ".reified_type_deps = (const FengTypeDescriptor *[]){",
            managed_count);
        for (size_t i = 0U; i < managed_count; ++i) {
            if (i > 0U) buf_append_cstr(&result, ", ");
            buf_append_fmt(&result, "&%s", managed_names[i]);
        }
        buf_append_cstr(&result, "}");
    }
    if (aggregate_count > 0U) {
        buf_append_fmt(&result,
            ", .reified_agg_deps_count = %zu, "
            ".reified_agg_deps = (const FengAggregateDescriptor *[]){",
            aggregate_count);
        for (size_t i = 0U; i < aggregate_count; ++i) {
            if (i > 0U) buf_append_cstr(&result, ", ");
            buf_append_fmt(&result, "&%s", aggregate_names[i]);
        }
        buf_append_cstr(&result, "}");
    }
    buf_append_cstr(&result, "}");
    for (size_t i = 0U; i < managed_count; ++i) free(managed_names[i]);
    for (size_t i = 0U; i < aggregate_count; ++i) free(aggregate_names[i]);
    free(managed_names);
    free(aggregate_names);
    return result.data;

simple:
    for (size_t i = 0U; i < managed_count; ++i) free(managed_names[i]);
    for (size_t i = 0U; i < aggregate_count; ++i) free(aggregate_names[i]);
    free(managed_names);
    free(aggregate_names);
    buf_init(&result);
    buf_append_fmt(&result,
        "&(const FengFunctionDescriptor){.name = \"%s\"}",
        method != NULL && method->feng_name != NULL
            ? method->feng_name
            : "builtin fit method");
    return result.data;

fail:
    for (size_t i = 0U; i < managed_count; ++i) free(managed_names[i]);
    for (size_t i = 0U; i < aggregate_count; ++i) free(aggregate_names[i]);
    free(managed_names);
    free(aggregate_names);
    return NULL;
}

/* Return whether a generic constraint contributes a runtime witness surface.
 * Union-form constraints are compile-time membership restrictions only; all
 * other currently supported constraint forms retain their existing witness
 * ABI. */
static bool cg_generic_constraint_requires_witness(
    const UserSpec *constraint_spec) {
    return constraint_spec != NULL &&
           constraint_spec->form != FENG_SPEC_FORM_UNION;
}

/* Return whether a type expression is fully closed at code-generation time.
 * Only closed expressions may contribute file-scope generic-parameter
 * descriptor nodes; expressions that still contain a callable/owner generic
 * parameter remain wrapper data and use incoming descriptor authority. */
static bool cg_type_descriptor_is_statically_closed(const CGType *type) {
    if (type == NULL) {
        return false;
    }
    switch (type->kind) {
        case CG_TYPE_GENERIC_PARAM:
            return false;
        case CG_TYPE_ARRAY:
        case CG_TYPE_POINTER:
            return type->element != NULL &&
                   cg_type_descriptor_is_statically_closed(type->element);
        case CG_TYPE_OBJECT:
            return type->user != NULL &&
                   type->user->generic_context_type_param_count == 0U;
        case CG_TYPE_CALLABLE:
        case CG_TYPE_SPEC:
            return type->user_spec != NULL &&
                   type->user_spec->generic_context_type_param_count == 0U;
        default:
            return true;
    }
}

/* Build the FengTypeDescriptor expression for an array used as a generic
 * argument. A statically closed array is deduplicated into file-scope const
 * data, so passing it has exactly the same runtime cost as passing the former
 * builtin descriptor address. Only an array that still contains an active
 * generic parameter uses a wrapper-scoped compound descriptor. */
static bool cg_closed_array_descriptor_expr(CG *cg,
                                            const CGType *array_type,
                                            const FengToken *tok,
                                            char **out) {
    char *element_descriptor = NULL;
    Buf expression;

    if (cg == NULL || array_type == NULL ||
        array_type->kind != CG_TYPE_ARRAY || array_type->element == NULL ||
        tok == NULL || out == NULL) {
        return false;
    }
    if (!cg_generic_descriptor_expr(cg,
                                    array_type->element,
                                    NULL,
                                    tok,
                                    &element_descriptor)) {
        return false;
    }

    if (cg_type_descriptor_is_statically_closed(array_type)) {
        Buf key;
        CGClosedArrayDescriptorNode *node;

        buf_init(&key);
        buf_append_fmt(&key,
                       "%c|%s",
                       array_type->array_element_writable ? 'W' : 'R',
                       element_descriptor);
        if (key.data == NULL) {
            free(element_descriptor);
            return cg_fail(cg, *tok,
                           "IE0001", "codegen: out of memory");
        }
        for (size_t index = 0U;
             index < cg->closed_array_descriptor_node_count;
             ++index) {
            node = &cg->closed_array_descriptor_nodes[index];
            if (strcmp(node->key, key.data) == 0) {
                buf_init(&expression);
                buf_append_fmt(&expression, "&%s", node->c_name);
                buf_free(&key);
                free(element_descriptor);
                *out = expression.data;
                return *out != NULL;
            }
        }
        if (cg->closed_array_descriptor_node_count ==
            cg->closed_array_descriptor_node_capacity) {
            size_t new_capacity =
                cg->closed_array_descriptor_node_capacity == 0U
                    ? 16U
                    : cg->closed_array_descriptor_node_capacity * 2U;
            CGClosedArrayDescriptorNode *grown =
                (CGClosedArrayDescriptorNode *)realloc(
                    cg->closed_array_descriptor_nodes,
                    new_capacity * sizeof(*grown));

            if (grown == NULL) {
                buf_free(&key);
                free(element_descriptor);
                return cg_fail(cg, *tok,
                               "IE0001", "codegen: out of memory");
            }
            cg->closed_array_descriptor_nodes = grown;
            cg->closed_array_descriptor_node_capacity = new_capacity;
        }
        node = &cg->closed_array_descriptor_nodes[
            cg->closed_array_descriptor_node_count];
        memset(node, 0, sizeof(*node));
        node->key = key.data;
        {
            Buf name;

            buf_init(&name);
            buf_append_fmt(&name,
                           "_feng_closed_array_desc_%zu",
                           cg->closed_array_descriptor_node_count);
            node->c_name = name.data;
        }
        if (node->c_name == NULL) {
            free(node->key);
            memset(node, 0, sizeof(*node));
            free(element_descriptor);
            return cg_fail(cg, *tok,
                           "IE0001", "codegen: out of memory");
        }
        cg->closed_array_descriptor_node_count++;
        buf_append_fmt(&cg->headers,
                       "static const FengTypeDescriptor %s;\n",
                       node->c_name);
        buf_append_fmt(
            &cg->statics,
            "static const FengGenericParamDescriptor *const %s__rgp[] = {"
            "%s};\n"
            "static const FengTypeDescriptor %s = {"
            ".name = \"feng.builtin.array\", "
            ".size = 0U, "
            ".default_zero_init = feng_array_default_zero_init, "
            ".reified_generic_params_count = 1U, "
            ".reified_generic_params = %s__rgp};\n",
            node->c_name,
            element_descriptor,
            node->c_name,
            node->c_name);
        buf_init(&expression);
        buf_append_fmt(&expression, "&%s", node->c_name);
        free(element_descriptor);
        *out = expression.data;
        return *out != NULL;
    }

    buf_init(&expression);
    buf_append_fmt(
        &expression,
        "&(const FengTypeDescriptor){"
        ".name = \"feng.builtin.array\", "
        ".size = 0U, "
        ".default_zero_init = feng_array_default_zero_init, "
        ".reified_generic_params_count = 1U, "
        ".reified_generic_params = "
        "(const FengGenericParamDescriptor *const[]){%s}}",
        element_descriptor);
    free(element_descriptor);
    *out = expression.data;
    return *out != NULL;
}

/* Return a file-scope read-only generic-parameter descriptor for one fully
 * closed initializer. Nodes are interned within the generated C translation
 * unit so repeated calls only pass an existing static address. */
static bool cg_closed_generic_param_descriptor_expr(
    CG *cg,
    const char *kind_expr,
    const char *descriptor_expr,
    const char *witness_expr,
    const FengToken *tok,
    char **out) {
    Buf key;
    Buf expression;
    CGClosedGenericParamDescriptorNode *node;

    if (cg == NULL || kind_expr == NULL || descriptor_expr == NULL ||
        witness_expr == NULL || tok == NULL || out == NULL) {
        return false;
    }

    buf_init(&key);
    buf_append_fmt(&key,
                   "%s|%s|%s",
                   kind_expr,
                   descriptor_expr,
                   witness_expr);
    if (key.data == NULL) {
        return cg_fail(cg, *tok, "IE0001", "codegen: out of memory");
    }
    for (size_t index = 0U;
         index < cg->closed_generic_param_descriptor_node_count;
         ++index) {
        node = &cg->closed_generic_param_descriptor_nodes[index];
        if (strcmp(node->key, key.data) == 0) {
            buf_init(&expression);
            buf_append_fmt(&expression, "&%s", node->c_name);
            buf_free(&key);
            *out = expression.data;
            return *out != NULL;
        }
    }

    if (cg->closed_generic_param_descriptor_node_count ==
        cg->closed_generic_param_descriptor_node_capacity) {
        size_t new_capacity =
            cg->closed_generic_param_descriptor_node_capacity == 0U
                ? 16U
                : cg->closed_generic_param_descriptor_node_capacity * 2U;
        CGClosedGenericParamDescriptorNode *grown =
            (CGClosedGenericParamDescriptorNode *)realloc(
                cg->closed_generic_param_descriptor_nodes,
                new_capacity * sizeof(*grown));

        if (grown == NULL) {
            buf_free(&key);
            return cg_fail(cg, *tok, "IE0001", "codegen: out of memory");
        }
        cg->closed_generic_param_descriptor_nodes = grown;
        cg->closed_generic_param_descriptor_node_capacity = new_capacity;
    }

    node = &cg->closed_generic_param_descriptor_nodes[
        cg->closed_generic_param_descriptor_node_count];
    memset(node, 0, sizeof(*node));
    node->key = key.data;
    {
        Buf name;

        buf_init(&name);
        buf_append_fmt(&name,
                       "_feng_closed_generic_param_desc_%zu",
                       cg->closed_generic_param_descriptor_node_count);
        node->c_name = name.data;
    }
    if (node->c_name == NULL) {
        free(node->key);
        memset(node, 0, sizeof(*node));
        return cg_fail(cg, *tok, "IE0001", "codegen: out of memory");
    }
    cg->closed_generic_param_descriptor_node_count++;

    buf_append_fmt(&cg->headers,
                   "static const FengGenericParamDescriptor %s;\n",
                   node->c_name);
    buf_append_fmt(
        &cg->statics,
        "static const FengGenericParamDescriptor %s = {"
        ".kind = %s, .descriptor = %s, .witness = %s};\n",
        node->c_name,
        kind_expr,
        descriptor_expr,
        witness_expr);
    buf_init(&expression);
    buf_append_fmt(&expression, "&%s", node->c_name);
    *out = expression.data;
    return *out != NULL;
}

static bool cg_generic_descriptor_expr(CG *cg, const CGType *t,
                                       const UserSpec *constraint_spec,
                                       const FengToken *tok, char **out) {
    if (t && t->kind == CG_TYPE_GENERIC_PARAM) {
        const char *desc = cg_generic_param_desc_name(cg, t->generic_param_index);
        const UserSpec *current_constraint =
            cg_generic_param_constraint_spec(cg, t->generic_param_index);
        if (!desc) {
            return cg_fail(cg, *tok,
                "CE0292", "codegen: generic type argument forwarding requires an active generic descriptor context");
        }
        if (cg_generic_constraint_requires_witness(constraint_spec) &&
            current_constraint != constraint_spec) {
            if (current_constraint == NULL ||
                !cg_user_spec_witness_prefix_compatible(current_constraint, constraint_spec)) {
                return cg_fail(cg, *tok,
                    "CE0293", "codegen: forwarding a generic type argument across a different constraint surface requires a parent-compatible witness surface (G6)");
            }
        }
        *out = strdup(desc);
        return *out != NULL;
    }

    Buf b; buf_init(&b);
    const bool type_is_statically_closed =
        cg_type_descriptor_is_statically_closed(t);
    const char *witness_expr = "NULL";
    char *owned_witness_expr = NULL;

    if (cg_generic_constraint_requires_witness(constraint_spec)) {
        if (t && t->kind == CG_TYPE_OBJECT && t->user) {
            const char *witness_var = NULL;
            if (!cg_ensure_witness_instance_for_type(cg,
                                                     t->user,
                                                     constraint_spec,
                                                     *tok,
                                                     &witness_var)) {
                buf_free(&b);
                return false;
            }
            Buf wb; buf_init(&wb);
            buf_append_fmt(&wb, "&%s", witness_var);
            owned_witness_expr = wb.data;
            witness_expr = owned_witness_expr;
        } else if (t && t->enum_decl != NULL) {
            const char *witness_var = NULL;
            FengSemanticSubjectKey subject_key =
                feng_semantic_subject_key_for_type_decl(t->enum_decl);
            if (!cg_ensure_witness_instance(cg,
                                            &subject_key,
                                            constraint_spec,
                                            FENG_SPEC_OBJECT_SUBJECT_STORAGE_BORROW_LOCAL,
                                            *tok,
                                            &witness_var)) {
                buf_free(&b);
                return false;
            }
            Buf wb; buf_init(&wb);
            buf_append_fmt(&wb, "&%s", witness_var);
            owned_witness_expr = wb.data;
            witness_expr = owned_witness_expr;
        } else if (t && (t->kind == CG_TYPE_SPEC || t->kind == CG_TYPE_CALLABLE) &&
                   t->user_spec) {
            const char *witness_var = NULL;
            if (!cg_ensure_spec_slot_witness(cg, t->user_spec, constraint_spec,
                                             *tok, &witness_var)) {
                buf_free(&b);
                return false;
            }
            Buf wb; buf_init(&wb);
            buf_append_fmt(&wb, "&%s", witness_var);
            owned_witness_expr = wb.data;
            witness_expr = owned_witness_expr;
        } else if (t && t->kind == CG_TYPE_ARRAY) {
            FengTypeRef *array_type_ref =
                cg_type_ref_from_cgtype(cg, t, *tok);
            FengSemanticSubjectKey lookup_key;
            const FengSpecWitness *semantic_witness;
            const FengSemanticSubjectKey *witness_subject_key;
            const char *witness_var = NULL;

            if (array_type_ref == NULL ||
                !feng_semantic_subject_key_init_array_from_type_ref(
                    &lookup_key, array_type_ref)) {
                cg_type_ref_free(array_type_ref);
                buf_free(&b);
                return cg_fail(cg, *tok,
                    "IE0002", "codegen: failed to reconstruct constrained array subject identity");
            }
            semantic_witness = feng_semantic_lookup_spec_witness(
                cg->analysis, &lookup_key, constraint_spec->decl);
            if (semantic_witness == NULL &&
                constraint_spec->form != FENG_SPEC_FORM_INTERSECTION) {
                cg_type_ref_free(array_type_ref);
                buf_free(&b);
                return cg_fail(cg, *tok,
                    "CE0329", "codegen: missing semantic witness for constrained array type argument");
            }
            witness_subject_key = semantic_witness != NULL
                ? &semantic_witness->subject_key
                : &lookup_key;
            if (!cg_ensure_witness_instance(
                    cg,
                    witness_subject_key,
                    constraint_spec,
                    FENG_SPEC_OBJECT_SUBJECT_STORAGE_BORROW_LOCAL,
                    *tok,
                    &witness_var)) {
                cg_type_ref_free(array_type_ref);
                buf_free(&b);
                return false;
            }
            cg_type_ref_free(array_type_ref);
            Buf wb; buf_init(&wb);
            buf_append_fmt(&wb, "&%s", witness_var);
            owned_witness_expr = wb.data;
            witness_expr = owned_witness_expr;
        } else if (t) {
            const char *builtin_name =
                cg_builtin_canonical_name_for_kind(t->kind);
            if (builtin_name == NULL) {
                buf_free(&b);
                return cg_fail(cg, *tok,
                    "CE0294", "codegen: constrained generic type argument currently requires a concrete user type, concrete spec value, matching outer generic parameter, or concrete builtin type");
            }

            const char *witness_var = NULL;
            FengSemanticSubjectKey subject_key =
                feng_semantic_subject_key_for_builtin(builtin_name);
            if (!cg_ensure_witness_instance(cg,
                                            &subject_key,
                                            constraint_spec,
                                            FENG_SPEC_OBJECT_SUBJECT_STORAGE_BORROW_LOCAL,
                                            *tok,
                                            &witness_var)) {
                buf_free(&b);
                return false;
            }
            Buf wb; buf_init(&wb);
            buf_append_fmt(&wb, "&%s", witness_var);
            owned_witness_expr = wb.data;
            witness_expr = owned_witness_expr;
        } else {
            buf_free(&b);
            return cg_fail(cg, *tok,
                "CE0295", "codegen: constrained generic type argument currently requires a concrete user type, concrete spec value, or matching outer generic parameter (G6)");
        }
    }

    switch (cgtype_value_kind(t)) {
        case CG_VK_TRIVIAL: {
            char *descriptor_expr = cg_trivial_descriptor_expr(cg, t);
            if (!descriptor_expr) {
                free(owned_witness_expr);
                buf_free(&b);
                return cg_fail(cg, *tok,
                    "CE0296", "codegen: trivial generic type argument requires a trivial descriptor");
            }
            if (type_is_statically_closed) {
                if (!cg_closed_generic_param_descriptor_expr(
                        cg,
                        "FENG_VALUE_TRIVIAL",
                        descriptor_expr,
                        witness_expr,
                        tok,
                        out)) {
                    free(descriptor_expr);
                    free(owned_witness_expr);
                    buf_free(&b);
                    return false;
                }
                free(descriptor_expr);
                free(owned_witness_expr);
                buf_free(&b);
                return true;
            }
            buf_append_fmt(
                &b,
                "&(const FengGenericParamDescriptor){"
                ".kind = FENG_VALUE_TRIVIAL, "
                ".descriptor = %s, .witness = %s}",
                descriptor_expr,
                witness_expr);
            free(descriptor_expr);
            break;
        }
        case CG_VK_MANAGED_POINTER: {
            char *descriptor_expr = NULL;
            bool descriptor_is_static = type_is_statically_closed;

            if (t != NULL && t->kind == CG_TYPE_ARRAY) {
                if (!cg_closed_array_descriptor_expr(cg,
                                                     t,
                                                     tok,
                                                     &descriptor_expr)) {
                    free(owned_witness_expr);
                    buf_free(&b);
                    return false;
                }
            } else {
                descriptor_expr = cg_managed_pointer_descriptor_expr(t);
            }
            if (!descriptor_expr) {
                free(owned_witness_expr);
                buf_free(&b);
                return cg_fail(cg, *tok,
                    "CE0297", "codegen: managed generic type argument requires a type descriptor");
            }
            if (descriptor_is_static) {
                if (!cg_closed_generic_param_descriptor_expr(
                        cg,
                        "FENG_VALUE_MANAGED_POINTER",
                        descriptor_expr,
                        witness_expr,
                        tok,
                        out)) {
                    free(descriptor_expr);
                    free(owned_witness_expr);
                    buf_free(&b);
                    return false;
                }
                free(descriptor_expr);
                free(owned_witness_expr);
                buf_free(&b);
                return true;
            }
            buf_append_fmt(
                &b,
                "&(const FengGenericParamDescriptor){"
                ".kind = FENG_VALUE_MANAGED_POINTER, "
                ".descriptor = %s, .witness = %s}",
                descriptor_expr,
                witness_expr);
            free(descriptor_expr);
            break;
        }
        case CG_VK_AGGREGATE: {
            CGAggregateFacts facts;
            if (!cg_aggregate_facts(t, &facts) ||
                facts.value_kind != CG_VK_AGGREGATE ||
                facts.descriptor_name == NULL) {
                free(owned_witness_expr);
                buf_free(&b);
                return cg_fail(cg, *tok,
                    "CE0298", "codegen: aggregate type as generic type argument not yet supported (missing flatten rule) (G6)");
            }
            if (type_is_statically_closed) {
                Buf descriptor;

                buf_init(&descriptor);
                buf_append_fmt(&descriptor, "&%s", facts.descriptor_name);
                if (descriptor.data == NULL ||
                    !cg_closed_generic_param_descriptor_expr(
                        cg,
                        "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS",
                        descriptor.data,
                        witness_expr,
                        tok,
                        out)) {
                    buf_free(&descriptor);
                    free(owned_witness_expr);
                    buf_free(&b);
                    return false;
                }
                buf_free(&descriptor);
                free(owned_witness_expr);
                buf_free(&b);
                return true;
            }
            buf_append_fmt(
                &b,
                "&(const FengGenericParamDescriptor){"
                ".kind = FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, "
                ".descriptor = &%s, .witness = %s}",
                facts.descriptor_name,
                witness_expr);
            break;
        }
    }
    free(owned_witness_expr);
    *out = b.data;
    return *out != NULL;
}

/* Emit the return statement body when inside a generic function.
 * All generic-function returns go through the void *_out out-parameter
 * so the C function's return type is always `void`. */
static bool cg_emit_generic_return(CG *cg, const FengStmt *stmt) {
    /* Void-return: just release and return. */
    if (!cg->cur_return_type || cg->cur_return_type->kind == CG_TYPE_VOID) {
        if (stmt->as.return_value != NULL &&
            stmt->is_mixin_wrapper_forward_return) {
            FengStmt expr_stmt = *stmt;

            expr_stmt.kind = FENG_STMT_EXPR;
            expr_stmt.as.expr = stmt->as.return_value;
            if (!cg_emit_expr_stmt(cg, &expr_stmt)) {
                return false;
            }
            cg_release_through(cg, NULL);
            cg_emit_return_control_cleanup(cg);
            buf_append_cstr(cg->cur_body, "    return;\n");
            return true;
        }
        if (stmt->as.return_value) {
            return cg_fail(cg, stmt->token,
                "CE0264", "codegen: void function cannot return a value");
        }
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_cstr(cg->cur_body, "    return;\n");
        return true;
    }
    if (!stmt->as.return_value) {
        return cg_fail(cg, stmt->token,
            "CE0265", "codegen: non-void function must return a value");
    }
    ExprResult r;
    if (!cg_emit_expr_for_expected_type(cg,
                                        stmt->as.return_value,
                                        cg->cur_return_type,
                                        &r)) return false;

    if (cg->cur_return_type->kind == CG_TYPE_GENERIC_PARAM) {
        /* Erased return type T: dispatch via the descriptor for T. */
        size_t idx = cg->cur_return_type->generic_param_index;
        const char *desc = cg->generic_fn_type_param_descs[idx];
        /* Establish the caller-owned +1 result before releasing local
         * storage.  A borrowed local may be the final owner in this frame;
         * releasing first would read freed bytes. */
        if (r.owns_ref) {
            buf_append_fmt(cg->cur_body,
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s)); break;\n"
                "        case FENG_VALUE_MANAGED_POINTER:\n"
                "            *(void **)_out = *(void *const *)%s;\n"
                "            *(void **)%s = NULL; break;\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s));\n"
                "            memset(%s, 0, feng_generic_value_size(%s)); break;\n"
                "    }\n",
                desc,
                r.c_expr, desc,
                r.c_expr, r.c_expr,
                r.c_expr, desc,
                r.c_expr, desc);
        } else {
            buf_append_fmt(cg->cur_body,
                "    switch (%s->kind) {\n"
                "        case FENG_VALUE_TRIVIAL:\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s)); break;\n"
                "        case FENG_VALUE_MANAGED_POINTER: {\n"
                "            void *_mptr_ = *(void *const *)%s;\n"
                "            feng_retain(_mptr_);\n"
                "            *(void **)_out = _mptr_; break;\n"
                "        }\n"
                "        case FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS:\n"
                "            feng_aggregate_retain((void *)%s, feng_generic_aggregate_descriptor(%s));\n"
                "            memcpy(_out, %s, feng_generic_value_size(%s)); break;\n"
                "    }\n",
                desc,
                r.c_expr, desc,
                r.c_expr,
                r.c_expr, desc,
                r.c_expr, desc);
        }
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_cstr(cg->cur_body, "    return;\n");
        er_free(&r);
        return true;
    }
    /* Concrete return type inside a generic function: compute result and
     * memcpy into _out. */
    if (cg_type_uses_reified_storage(cg, r.type)) {
        char *owned_descriptor = NULL;
        char *source_address = NULL;
        const char *descriptor = r.reified_descriptor_c_name;
        const char *size = r.reified_size_c_name;
        Buf fallback_size;

        buf_init(&fallback_size);
        if (descriptor == NULL) {
            owned_descriptor =
                cg_reified_aggregate_descriptor_expr_dup(cg,
                                                          r.type,
                                                          stmt->token);
            descriptor = owned_descriptor;
        }
        if (size == NULL && descriptor != NULL) {
            buf_append_fmt(&fallback_size, "%s->size", descriptor);
            size = fallback_size.data;
        }
        source_address = cg_aggregate_result_address_dup(&r);
        if (descriptor == NULL || size == NULL || source_address == NULL) {
            free(owned_descriptor);
            free(source_address);
            buf_free(&fallback_size);
            er_free(&r);
            return cg_fail(cg, stmt->token,
                           "CE0299", "codegen: reified aggregate return has no address storage");
        }
        buf_append_fmt(cg->cur_body,
                       "    memcpy(_out, %s, %s);\n",
                       source_address,
                       size);
        if (r.owns_ref) {
            buf_append_fmt(cg->cur_body,
                           "    memset(%s, 0, %s);\n",
                           source_address,
                           size);
        } else {
            buf_append_fmt(cg->cur_body,
                           "    feng_aggregate_retain(_out, %s);\n",
                           descriptor);
        }
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_cstr(cg->cur_body, "    return;\n");
        free(owned_descriptor);
        free(source_address);
        buf_free(&fallback_size);
    } else if (cgtype_is_managed(r.type)) {
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(r.type);
        if (!r.owns_ref) {
            buf_append_fmt(cg->cur_body,
                "    %s %s = %s; feng_retain(%s);\n", cty, tmp, r.c_expr, tmp);
        } else {
            buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, r.c_expr);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body,
            "    memcpy(_out, &%s, sizeof %s);\n    return;\n", tmp, tmp);
        free(tmp);
    } else if (cgtype_is_aggregate(r.type)) {
        char *descriptor = cg_aggregate_descriptor_expr_dup(cg,
                                                             r.type,
                                                             stmt->token);
        char *tmp;
        char *cty;

        if (descriptor == NULL) {
            er_free(&r);
            return false;
        }

        tmp = cg_fresh_temp(cg, "_ret");
        cty = cg_ctype_dup(r.type);
        if (!tmp || !cty) {
            free(descriptor);
            free(tmp);
            free(cty);
            er_free(&r);
            return cg_fail(cg, stmt->token,
                "CE0300", "codegen: out of memory while emitting generic aggregate return");
        }

        if (!r.owns_ref) {
            if (r.is_storage_address) {
                buf_append_fmt(cg->cur_body,
                    "    %s %s = *(const %s *)(%s);"
                    " feng_aggregate_retain(&%s, %s);\n",
                    cty, tmp, cty, r.c_expr, tmp, descriptor);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    %s %s = %s; feng_aggregate_retain(&%s, %s);\n",
                    cty, tmp, r.c_expr, tmp, descriptor);
            }
        } else {
            cg_materialize_to_local(cg, &r, "_t");
            buf_append_fmt(cg->cur_body,
                "    %s %s; memset(&%s, 0, sizeof %s);"
                " feng_aggregate_take(&%s, &%s, %s);\n",
                cty, tmp, tmp, tmp, tmp, r.c_expr, descriptor);
        }

        free(descriptor);
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body,
            "    memcpy(_out, &%s, sizeof %s);\n    return;\n", tmp, tmp);
        free(tmp);
    } else {
        char *tmp = cg_fresh_temp(cg, "_ret");
        char *cty = cg_ctype_dup(cg->cur_return_type);
        if (r.is_storage_address) {
            buf_append_fmt(cg->cur_body,
                "    %s %s = *(const %s *)(%s);\n",
                cty, tmp, cty, r.c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "    %s %s = (%s)(%s);\n", cty, tmp, cty, r.c_expr);
        }
        free(cty);
        cg_release_through(cg, NULL);
        cg_emit_return_control_cleanup(cg);
        buf_append_fmt(cg->cur_body,
            "    memcpy(_out, &%s, sizeof %s);\n    return;\n", tmp, tmp);
        free(tmp);
    }
    er_free(&r);
    return true;
}

/* Emit a generic function (type_param_count > 0).
 *
 * ABI:
 *   void c_name(
 *       const FengGenericParamDescriptor *_T [, *_U, ...],
 *       <params — T-typed as const void *, non-generic as normal C type>,
 *       [void *_out]       ← present iff return type is non-void
 *   );
 *
 * The caller is responsible for setting up concrete FengGenericParamDescriptor
 * compound-literal arguments and passing T-typed values by pointer. */
static bool cg_emit_generic_function(CG *cg, const FengDecl *decl,
                                      FengCompileTarget target) {
    const FengCallableSignature *sig = &decl->as.function_decl;
    char **captured_names = NULL;
    size_t captured_name_count = 0U;
    char **saved_captured_names = cg->captured_binding_names;
    size_t saved_captured_name_count = cg->captured_binding_name_count;
    bool saved_captures_self = cg->current_callable_captures_self;
    const char *saved_function_descriptor_c_name =
        cg->generic_function_descriptor_c_name;
    bool ok = false;

    /* Register in the GenericFn table.  May already be registered if we
     * processed a forward prototype earlier; guard with a lookup. */
    if (!cg_find_generic_fn_by_decl(cg, decl)) {
        if (!cg_register_generic_fn(cg, decl)) return false;
    }
    const GenericFn *gfn = cg_find_generic_fn_by_decl(cg, decl);

    /* Allocate descriptor arg names: "_T", "_U", ... */
    size_t tp_count = sig->type_param_count;
    const char **desc_names = calloc(tp_count, sizeof *desc_names);
    const UserSpec **constraint_specs = NULL;
    if (!desc_names) return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    for (size_t i = 0; i < tp_count; i++) {
        Buf b; buf_init(&b);
        buf_append_fmt(&b, "_%s", gfn->type_param_names[i]);
        desc_names[i] = b.data;
        if (!desc_names[i]) {
            for (size_t j = 0; j < i; j++) free((void *)desc_names[j]);
            free(desc_names);
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
    }

    if (!cg_build_generic_param_constraints(cg, sig->type_params, tp_count,
                                            decl->token, &constraint_specs)) {
        for (size_t i = 0; i < tp_count; i++) free((void *)desc_names[i]);
        free(desc_names);
        return false;
    }

    /* Activate generic-function emission state. */
    cg->in_generic_fn = true;
    cg->generic_return_uses_out = true;
    cg->generic_fn_type_param_count = tp_count;
    cg->generic_fn_type_param_names = gfn->type_param_names; /* borrowed */
    cg->generic_fn_type_param_constraints = constraint_specs;  /* owned by frame */
    cg->generic_fn_type_param_descs = desc_names;             /* owned */
    cg->generic_function_descriptor_c_name = "_desc";

    /* Resolve return type (CG_TYPE_GENERIC_PARAM when it's T/U/…). */
    CGType *return_type = NULL;
    if (!cg_resolve_callable_return_type(
            cg, sig, decl->token, &return_type)) {
        goto cleanup;
    }
    cg->cur_return_type = return_type;
    bool has_out_param = (return_type->kind != CG_TYPE_VOID);

    /* Resolve parameter types. */
    size_t param_count = sig->param_count;
    CGType **param_types = calloc(param_count + 1, sizeof *param_types);
    char  **param_cnames = calloc(param_count + 1, sizeof *param_cnames);
    char  **param_fnames = calloc(param_count + 1, sizeof *param_fnames); /* Feng names */
    if (!param_types || !param_cnames || !param_fnames) {
        free(param_types); free(param_cnames); free(param_fnames);
        cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t i = 0; i < param_count; i++) {
        const FengParameter *p = &sig->params[i];
        if (!cg_resolve_type(cg, p->type, &p->token, &param_types[i])) {
            for (size_t j = 0; j < i; j++) {
                cgtype_free(param_types[j]);
                free(param_cnames[j]);
                free(param_fnames[j]);
            }
            free(param_types); free(param_cnames); free(param_fnames);
            goto cleanup;
        }
        /* Feng name: used for scope_add so the body can look up the param. */
        param_fnames[i] = strndup(p->name.data, p->name.length);
        /* C name: _p_<feng_name> to avoid C keyword conflicts. */
        Buf cb; buf_init(&cb);
        buf_append_fmt(&cb, "_p_%.*s", (int)p->name.length, p->name.data);
        param_cnames[i] = cb.data;
        if (!param_fnames[i] || !param_cnames[i]) {
            for (size_t j = 0; j <= i; j++) {
                cgtype_free(param_types[j]);
                free(param_cnames[j]);
                free(param_fnames[j]);
            }
            free(param_types); free(param_cnames); free(param_fnames);
            cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }

    bool needs_static = !(target == FENG_COMPILE_TARGET_LIB &&
                          decl->visibility == FENG_VISIBILITY_PUBLIC);

    /* Helper: emit the parameter list (shared for proto + definition).
     * §6.7: _desc is always the first parameter. */
    #define EMIT_GENERIC_PARAMS(buf_ptr)                                       \
    do {                                                                        \
        buf_append_cstr((buf_ptr),                                             \
                        "const FengFunctionDescriptor *_desc");                \
        for (size_t _i = 0; _i < tp_count; _i++) {                             \
            buf_append_cstr((buf_ptr), ", ");                                   \
            buf_append_fmt((buf_ptr), "const FengGenericParamDescriptor *%s",  \
                           desc_names[_i]);                                     \
        }                                                                       \
        for (size_t _i = 0; _i < param_count; _i++) {                          \
            buf_append_cstr((buf_ptr), ", ");                                   \
            if (cg_shared_generic_param_uses_address(param_types[_i])) {       \
                buf_append_fmt((buf_ptr), "const void *%s", param_cnames[_i]); \
            } else {                                                            \
                cg_emit_c_type((buf_ptr), param_types[_i]);                    \
                buf_append_fmt((buf_ptr), " %s", param_cnames[_i]);            \
            }                                                                   \
        }                                                                       \
        if (has_out_param) {                                                    \
            buf_append_cstr((buf_ptr), ", ");                                   \
            buf_append_cstr((buf_ptr), "void *_out");                           \
        }                                                                       \
    } while (0)

    /* Forward prototype. */
    {
        Buf *p = &cg->fn_protos;
        if (needs_static) buf_append_cstr(p, "static ");
        buf_append_fmt(p, "void %s(", gfn->c_name);
        EMIT_GENERIC_PARAMS(p);
        buf_append_cstr(p, ");\n");
    }

    /* Function body. */
    {
        Buf *body = &cg->fn_defs;
        cg->cur_body = body;

        if (needs_static) buf_append_cstr(body, "static ");
        buf_append_fmt(body, "void %s(", gfn->c_name);
        EMIT_GENERIC_PARAMS(body);
        buf_append_cstr(body, ") {\n");

        /* Suppress unused-parameter warnings. */
        buf_append_cstr(body, "    (void)_desc;\n");
        for (size_t i = 0; i < tp_count; i++) {
            buf_append_fmt(body, "    (void)%s;\n", desc_names[i]);
        }
        for (size_t i = 0; i < param_count; i++) {
            buf_append_fmt(body, "    (void)%s;\n", param_cnames[i]);
        }
        if (has_out_param) {
            buf_append_cstr(body, "    (void)_out;\n");
        }

        Scope *fn_scope = scope_push(NULL);
        if (!fn_scope) {
            cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
            goto cleanup_params;
        }
        cg->cur_scope = fn_scope;
        cg->tmp_counter = 0;
        cg->local_counter = 0;
        cg->loop_depth = 0;
        cg->try_depth = 0;
        cg->cur_fn_is_main = false;
        cg->active_exception_frame_count = 0;
        cg->active_caught_unwind_count = 0;
        cg->cur_function_has_frame_marker = false;

        /* One canonical mapping keeps aggregate, managed, and callable slots
         * on the same function-descriptor authority. */
        {
            const FengReifiableDepSet *fn_dep_set =
                feng_semantic_lookup_reifiable_dep_set(cg->analysis, decl);
            FengSlice *active_param_names = tp_count > 0U
                ? (FengSlice *)calloc(
                      tp_count, sizeof(*active_param_names))
                : NULL;

            if (tp_count > 0U && active_param_names == NULL) {
                cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                goto cleanup_params;
            }
            for (size_t index = 0U; index < tp_count; ++index) {
                active_param_names[index] = sig->type_params[index].name;
            }
            if (!cg_activate_reified_dependency_mapping(
                    cg,
                    fn_dep_set,
                    active_param_names,
                    tp_count,
                    CG_REIFIED_DEP_SOURCE_FUNCTION,
                    decl->token)) {
                free(active_param_names);
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                goto cleanup_params;
            }
            free(active_param_names);
        }

        if (!cg_emit_function_eh_prologue(cg, decl->token)) {
            cg->cur_scope = NULL;
            scope_pop_free(fn_scope);
            goto cleanup_params;
        }
        if (!cg_debug_set_current_frame(cg,
                                        gfn->c_name,
                                        gfn->feng_name,
                                        FENG_CODEGEN_MAPING_FRAME_VISIBLE,
                                        decl->token) ||
            !cg_debug_add_current_frame_module_binding_records(cg, decl->token)) {
            cg->cur_scope = NULL;
            scope_pop_free(fn_scope);
            goto cleanup_params;
        }

        if (!cg_compute_capture_requirements_in_block(
                sig->body,
                &captured_names,
                &captured_name_count,
                &cg->current_callable_captures_self)) {
            cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
            cg->cur_scope = NULL;
            scope_pop_free(fn_scope);
            goto cleanup_params;
        }
        cg->captured_binding_names = captured_names;
        cg->captured_binding_name_count = captured_name_count;

        /* Add parameters to scope. */
        for (size_t i = 0; i < param_count; i++) {
            if (cg_current_callable_captures_name(
                    cg, param_fnames[i], strlen(param_fnames[i]))) {
                if (!cg_scope_bind_capture_cell(
                        cg,
                        fn_scope,
                        sig->params[i].name,
                        param_types[i],
                        sig->params[i].token,
                        param_cnames[i],
                        true,
                        false,
                        true,
                        FENG_CODEGEN_MAPING_VARIABLE_PARAM) ||
                    !scope_mark_last_binding_mutability(
                        fn_scope, sig->params[i].mutability)) {
                    cg->cur_scope = NULL;
                    scope_pop_free(fn_scope);
                    goto cleanup_params;
                }
                continue;
            }
            CGType *pt = cgtype_clone(param_types[i]);
            if (!scope_add(fn_scope, param_fnames[i], param_cnames[i], pt,
                           /*is_param=*/true) ||
                !scope_mark_last_binding_mutability(
                    fn_scope, sig->params[i].mutability)) {
                cgtype_free(pt);
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                goto cleanup_params;
            }
            if (!cg_mark_last_shared_address_parameter(cg,
                                                       fn_scope,
                                                       param_types[i],
                                                       sig->params[i].token)) {
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                goto cleanup_params;
            }
            if (!cg_debug_add_variable_record_cstr_type_ref(cg,
                                                            param_cnames[i],
                                                            param_fnames[i],
                                                            NULL,
                                                            sig->params[i].type,
                                                            FENG_CODEGEN_MAPING_VARIABLE_PARAM,
                                                            sig->params[i].token)) {
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                goto cleanup_params;
            }
        }

        if (!cg_emit_block(cg, sig->body)) {
            cg->cur_scope = NULL;
            scope_pop_free(fn_scope);
            goto cleanup_params;
        }

        /* Implicit fall-off. */
        cg_release_scope(cg, fn_scope);
        cg_emit_function_fallthrough_cleanup(cg);
        if (return_type->kind == CG_TYPE_VOID) {
            buf_append_cstr(body, "    return;\n");
        } else {
            buf_append_cstr(body,
                "    feng_panic(\"generic function reached end without return\");\n");
        }
        buf_append_cstr(body, "}\n\n");

        cg->cur_scope = NULL;
        scope_pop_free(fn_scope);
        cg->cur_body = NULL;
        cg->current_frame_backend_symbol = NULL;
        cg->cur_function_has_frame_marker = false;
    }

    #undef EMIT_GENERIC_PARAMS

    ok = true;
    goto cleanup_params;   /* intentional — cleanup_params frees arrays then cleanup clears state */

cleanup_params:
    for (size_t i = 0; i < param_count; i++) {
        cgtype_free(param_types[i]);
        free(param_cnames[i]);
        free(param_fnames[i]);
    }
    free(param_types); free(param_cnames); free(param_fnames);
    cgtype_free(return_type);
    cg->cur_return_type = NULL;
cleanup:
    cg->captured_binding_names = saved_captured_names;
    cg->captured_binding_name_count = saved_captured_name_count;
    cg->current_callable_captures_self = saved_captures_self;
    cg->generic_function_descriptor_c_name =
        saved_function_descriptor_c_name;
    for (size_t i = 0; i < captured_name_count; ++i) {
        free(captured_names[i]);
    }
    free(captured_names);
    for (size_t i = 0; i < tp_count; i++) free((void *)desc_names[i]);
    free(desc_names);
    free((void *)constraint_specs);
    cg->in_generic_fn = false;
    cg->generic_return_uses_out = false;
    cg->generic_fn_type_param_count = 0;
    cg->generic_fn_type_param_names = NULL;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;
    cg->cur_function_has_frame_marker = false;
    for (size_t i = 0; i < cg->generic_type_method_rtd_count; i++) {
        free(cg->generic_type_method_rtd_descs[i]);
    }
    free(cg->generic_type_method_rtd_descs);
    cg->generic_type_method_rtd_descs = NULL;
    cg->generic_type_method_rtd_count = 0;
    cg->generic_type_method_rtd_via_desc = false;
    for (size_t i = 0; i < cg->generic_type_method_rad_count; i++) {
        free(cg->generic_type_method_rad_descs[i]);
    }
    free(cg->generic_type_method_rad_descs);
    cg->generic_type_method_rad_descs = NULL;
    cg->generic_type_method_rad_count = 0;
    cg->generic_type_method_rad_via_desc = false;
    return ok;
}

/* Helper: infer the concrete CGType for type parameter `tp_idx` from
 * the actual call arguments.  Returns a cloned (heap-owned) CGType or NULL
 * if inference failed. */
static CGType *cg_infer_type_arg(const GenericFn *gfn,
                                 size_t tp_idx,
                                 const FengExpr *call,
                                 ExprResult *args,
                                 size_t arg_count) {
    const FengCallableSignature *sig = &gfn->decl->as.function_decl;
    size_t param_count = sig->param_count;
    size_t n = arg_count < param_count ? arg_count : param_count;
    for (size_t i = 0; i < n; i++) {
        const FengParameter *p = &sig->params[i];
        const char *tpname = gfn->type_param_names[tp_idx];

        if (p->type == NULL) continue;
        /* A type param ref is: single-segment NAMED with 0 type_args whose
         * name matches the type param. */
        if (p->type->kind == FENG_TYPE_REF_NAMED &&
            p->type->as.named.segment_count == 1U &&
            p->type->as.named.type_arg_count == 0U) {
            const FengSlice *segment = &p->type->as.named.segments[0];

            if (segment->length == strlen(tpname) &&
                memcmp(segment->data, tpname, segment->length) == 0) {
                return cgtype_clone(args[i].type);
            }
        }

        /* A variadic T... parameter is normalized to T[].  An explicit
         * `...expr` actual already has that complete array shape, so infer T
         * from its element type.  Ordinary generic variadic inference keeps
         * its pre-existing codegen behavior. */
        if (p->is_variadic &&
            p->type->kind == FENG_TYPE_REF_ARRAY &&
            p->type->as.inner != NULL &&
            p->type->as.inner->kind == FENG_TYPE_REF_NAMED &&
            p->type->as.inner->as.named.segment_count == 1U &&
            p->type->as.inner->as.named.type_arg_count == 0U) {
            const FengSlice *inner = &p->type->as.inner->as.named.segments[0];

            if (inner->length != strlen(tpname) ||
                memcmp(inner->data, tpname, inner->length) != 0) {
                continue;
            }
            if (call == NULL || call->kind != FENG_EXPR_CALL ||
                i >= call->as.call.arg_count ||
                !call->as.call.args[i]->is_prepacked_variadic_arg) {
                continue;
            }
            if (args[i].type == NULL ||
                args[i].type->kind != CG_TYPE_ARRAY ||
                args[i].type->element == NULL) {
                return NULL;
            }
            return cgtype_clone(args[i].type->element);
        }
    }
    return NULL;
}

static bool cg_inferred_callable_types_equal(const CGType *a, const CGType *b) {
    if (!a || !b) return false;
    if (a->kind != b->kind) return false;
    switch (a->kind) {
        case CG_TYPE_GENERIC_PARAM:
            return a->generic_param_index == b->generic_param_index;
        case CG_TYPE_OBJECT:
            return a->user == b->user;
        case CG_TYPE_SPEC:
        case CG_TYPE_CALLABLE:
            return a->user_spec == b->user_spec;
        case CG_TYPE_POINTER:
        case CG_TYPE_ARRAY:
            return cg_inferred_callable_types_equal(a->element, b->element);
        default:
            return true;
    }
}

static bool cg_collect_inferred_callable_type_args(CG *cg,
                                                   FengToken blame,
                                                   const CGType *pattern,
                                                   const CGType *actual,
                                                   CGType **type_args,
                                                   size_t type_arg_count) {
    if (pattern == NULL || actual == NULL) return false;

    switch (pattern->kind) {
        case CG_TYPE_GENERIC_PARAM: {
            size_t index = pattern->generic_param_index;

            if (index >= type_arg_count) return false;
            if (type_args[index] == NULL) {
                type_args[index] = cgtype_clone(actual);
                if (type_args[index] == NULL) {
                    return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                }
                return true;
            }
            return cg_inferred_callable_types_equal(type_args[index], actual);
        }

        case CG_TYPE_POINTER:
        case CG_TYPE_ARRAY:
            return actual->kind == pattern->kind &&
                   cg_collect_inferred_callable_type_args(cg,
                                                          blame,
                                                          pattern->element,
                                                          actual->element,
                                                          type_args,
                                                          type_arg_count);

        case CG_TYPE_OBJECT:
            return actual->kind == CG_TYPE_OBJECT && pattern->user == actual->user;

        case CG_TYPE_SPEC:
        case CG_TYPE_CALLABLE:
            return actual->kind == pattern->kind && pattern->user_spec == actual->user_spec;

        default:
            return actual->kind == pattern->kind;
    }
}

static CGType *cg_instantiate_callable_type_from_args(const CGType *pattern,
                                                      CGType *const *type_args,
                                                      size_t type_arg_count) {
    if (pattern == NULL) return NULL;
    if (pattern->kind == CG_TYPE_GENERIC_PARAM) {
        if (pattern->generic_param_index >= type_arg_count ||
            type_args[pattern->generic_param_index] == NULL) {
            return NULL;
        }
        return cgtype_clone(type_args[pattern->generic_param_index]);
    }

    CGType *result = cgtype_new(pattern->kind);
    if (result == NULL) return NULL;
    result->user = pattern->user;
    result->user_spec = pattern->user_spec;
    result->generic_param_index = pattern->generic_param_index;

    if (pattern->element != NULL) {
        result->element = cg_instantiate_callable_type_from_args(pattern->element,
                                                                 type_args,
                                                                 type_arg_count);
        if (result->element == NULL) {
            cgtype_free(result);
            return NULL;
        }
    }

    return result;
}

static bool cg_emit_generic_extern_call(CG *cg, const FengExpr *e,
                                        const FengDecl *decl,
                                        const ExternFn *ext,
                                        ExprResult *out) {
    const FengCallableSignature *sig = &decl->as.function_decl;
    /* Generic externs are specialized to a concrete erased surface after
     * resolving/inferencing type arguments. Runtime-contract generic externs
     * still prepend one hidden FengGenericParamDescriptor argument per type
     * parameter before the concrete surface arguments. */
    CGType **param_types = sig->param_count ? calloc(sig->param_count, sizeof *param_types) : NULL;
    bool *param_is_direct_type_param = sig->param_count ? calloc(sig->param_count, sizeof *param_is_direct_type_param) : NULL;
    CGType **type_args = sig->type_param_count ? calloc(sig->type_param_count, sizeof *type_args) : NULL;
    CGType *return_type = NULL;
    const UserSpec **constraint_specs = NULL;
    char **desc_exprs = NULL;
    ExternFn concrete = {
        .feng_name = ext != NULL ? ext->feng_name : NULL,
        .generated_c_name = ext != NULL ? ext->generated_c_name : NULL,
        .native_symbol = ext != NULL ? ext->native_symbol : NULL,
        .param_types = param_types,
        .param_count = sig->param_count,
        .return_type = NULL,
        .calling_convention = ext != NULL ? ext->calling_convention : FENG_ANNOTATION_NONE,
        .uses_runtime_contract = ext != NULL && ext->uses_runtime_contract,
        .fixed_param_count = ext != NULL ? ext->fixed_param_count : 0U,
        .decl = ext != NULL ? ext->decl : NULL,
        .owner_program = ext != NULL ? ext->owner_program : NULL,
    };
    bool return_is_direct_type_param = false;
    bool ok = false;

    if (ext == NULL) {
        return cg_fail(cg, e->token, "CE0302", "codegen: generic extern call is missing extern metadata");
    }
    if ((sig->param_count > 0U && param_types == NULL) ||
        (sig->param_count > 0U && param_is_direct_type_param == NULL) ||
        (sig->type_param_count > 0U && type_args == NULL)) {
        free(param_types);
        free(param_is_direct_type_param);
        free(type_args);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    if (e->as.call.arg_count != sig->param_count) {
        free(param_types);
        free(param_is_direct_type_param);
        free(type_args);
        return cg_fail(cg,
                       e->token,
                       "CE0126", "codegen: wrong argument count for '%.*s' (expected %zu, got %zu)",
                       (int)sig->name.length,
                       sig->name.data,
                       sig->param_count,
                       e->as.call.arg_count);
    }

    if (e->as.call.has_explicit_type_args) {
        if (e->as.call.explicit_type_arg_count != sig->type_param_count) {
            free(param_types);
            free(param_is_direct_type_param);
            free(type_args);
            return cg_fail(cg,
                           e->token,
                           "CE0303", "codegen: generic extern type argument count mismatch");
        }
        for (size_t i = 0; i < sig->type_param_count; ++i) {
            if (!cg_resolve_type(cg,
                                 e->as.call.explicit_type_args[i],
                                 &e->token,
                                 &type_args[i])) {
                goto cleanup;
            }
        }
    } else if (cg_call_has_resolved_callable_type_args(
                   e, sig->type_param_count)) {
        if (!cg_resolve_recorded_callable_type_args(cg,
                                                    e,
                                                    sig->type_param_count,
                                                    type_args)) {
            goto cleanup;
        }
    } else {
        for (size_t i = 0; i < sig->param_count; ++i) {
            CGType *pattern = NULL;
            CGType *actual = cg_probe_expr_type(cg, e->as.call.args[i]);

            if (actual == NULL) {
                goto cleanup;
            }
            if (!cg_resolve_callable_type_template(cg,
                                                   sig,
                                                   sig->params[i].type,
                                                   &sig->params[i].token,
                                                   &pattern)) {
                cgtype_free(actual);
                goto cleanup;
            }
            if (!cg_collect_inferred_callable_type_args(cg,
                                                        sig->params[i].token,
                                                        pattern,
                                                        actual,
                                                        type_args,
                                                        sig->type_param_count)) {
                cgtype_free(pattern);
                cgtype_free(actual);
                if (cg->failed) {
                    goto cleanup;
                }
                cg_fail(cg,
                        e->token,
                        "CE0304", "codegen: cannot infer generic extern type arguments for '%.*s' from argument %zu",
                        (int)sig->name.length,
                        sig->name.data,
                        i);
                goto cleanup;
            }
            cgtype_free(pattern);
            cgtype_free(actual);
        }
        for (size_t i = 0; i < sig->type_param_count; ++i) {
            if (type_args[i] == NULL) {
                cg_fail(cg,
                        e->token,
                        "CE0305", "codegen: cannot infer type argument %zu for generic extern '%.*s'",
                        i,
                        (int)sig->name.length,
                        sig->name.data);
                goto cleanup;
            }
        }
    }

    for (size_t i = 0; i < sig->param_count; ++i) {
        CGType *pattern = NULL;

        if (!cg_resolve_callable_type_template(cg,
                                               sig,
                                               sig->params[i].type,
                                               &sig->params[i].token,
                                               &pattern)) {
            goto cleanup;
        }
        param_is_direct_type_param[i] = pattern->kind == CG_TYPE_GENERIC_PARAM;
        param_types[i] = cg_instantiate_callable_type_from_args(pattern,
                                                                type_args,
                                                                sig->type_param_count);
        cgtype_free(pattern);
        if (param_types[i] == NULL) {
            cg_fail(cg, sig->params[i].token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }

    if (sig->return_type != NULL) {
        CGType *pattern = NULL;

        if (!cg_resolve_callable_type_template(cg,
                                               sig,
                                               sig->return_type,
                                               &sig->token,
                                               &pattern)) {
            goto cleanup;
        }
        return_is_direct_type_param = pattern->kind == CG_TYPE_GENERIC_PARAM;
        return_type = cg_instantiate_callable_type_from_args(pattern,
                                                             type_args,
                                                             sig->type_param_count);
        cgtype_free(pattern);
        if (return_type == NULL) {
            cg_fail(cg, sig->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    } else {
        return_type = cgtype_new(CG_TYPE_VOID);
        if (return_type == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }

    concrete.return_type = return_type;
    if (concrete.uses_runtime_contract && sig->type_param_count > 0U) {
        Buf args_buf;
        char *ret_cname = NULL;

        if (!cg_build_generic_param_constraints(cg,
                                                sig->type_params,
                                                sig->type_param_count,
                                                e->token,
                                                &constraint_specs)) {
            goto cleanup;
        }
        desc_exprs = calloc(sig->type_param_count, sizeof *desc_exprs);
        if (desc_exprs == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        for (size_t i = 0; i < sig->type_param_count; ++i) {
            if (!cg_generic_descriptor_expr(cg,
                                            type_args[i],
                                            constraint_specs ? constraint_specs[i] : NULL,
                                            &e->token,
                                            &desc_exprs[i])) {
                goto cleanup;
            }
        }

        buf_init(&args_buf);
        for (size_t i = 0; i < sig->type_param_count; ++i) {
            if (i != 0U) {
                buf_append_cstr(&args_buf, ", ");
            }
            buf_append_cstr(&args_buf, desc_exprs[i]);
        }
        for (size_t i = 0; i < sig->param_count; ++i) {
            ExprResult ar;
            char *arg_expr = NULL;

            er_init(&ar);
            if (!cg_emit_expr_for_expected_type(cg,
                                                e->as.call.args[i],
                                                param_types[i],
                                                &ar)) {
                buf_free(&args_buf);
                goto cleanup;
            }
            if (param_is_direct_type_param[i]) {
                char *tmp = cg_fresh_temp(cg, "_rga");

                if (tmp == NULL) {
                    er_free(&ar);
                    buf_free(&args_buf);
                    return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                }
                if (ar.type != NULL && ar.type->kind == CG_TYPE_GENERIC_PARAM) {
                    buf_append_fmt(cg->cur_body, "    const void *%s = %s;\n", tmp, ar.c_expr);
                    arg_expr = strdup(tmp);
                } else {
                    char *cty = cg_ctype_dup(ar.type);

                    if (cty == NULL) {
                        free(tmp);
                        er_free(&ar);
                        buf_free(&args_buf);
                        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                    }
                    buf_append_fmt(cg->cur_body, "    %s %s = %s;\n", cty, tmp, ar.c_expr);
                    if (cgtype_is_managed(ar.type) && ar.owns_ref) {
                        if (!cg_register_local_for_cleanup(cg, tmp, ar.type, e->token)) {
                            free(cty);
                            free(tmp);
                            er_free(&ar);
                            buf_free(&args_buf);
                            return false;
                        }
                        ar.owns_ref = false;
                    }
                    Buf addr; buf_init(&addr);
                    buf_append_fmt(&addr, "&%s", tmp);
                    arg_expr = addr.data;
                    free(cty);
                }
                free(tmp);
            } else {
                if (cgtype_is_managed(ar.type) && ar.owns_ref) {
                    cg_materialize_to_local(cg, &ar, "_t");
                } else if (cgtype_is_aggregate(ar.type)) {
                    cg_materialize_to_local(cg, &ar, "_t");
                }
                arg_expr = strdup(ar.c_expr);
            }
            if (arg_expr == NULL) {
                er_free(&ar);
                buf_free(&args_buf);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            if (sig->type_param_count != 0U || i != 0U) {
                buf_append_cstr(&args_buf, ", ");
            }
            buf_append_cstr(&args_buf, arg_expr);
            free(arg_expr);
            er_free(&ar);
        }

        if (return_is_direct_type_param) {
            char *cty = cg_ctype_dup(concrete.return_type);

            ret_cname = cg_fresh_temp(cg, "_rgr");
            if (cty == NULL || ret_cname == NULL) {
                free(cty);
                free(ret_cname);
                buf_free(&args_buf);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, ret_cname);
            free(cty);

            buf_append_cstr(&args_buf, ", ");
            buf_append_fmt(&args_buf, "&%s", ret_cname);
            buf_append_fmt(cg->cur_body,
                           "    %s(%s);\n",
                           cg_extern_call_target(&concrete),
                           args_buf.data ? args_buf.data : "");

            out->c_expr = strdup(ret_cname);
            out->type = cgtype_clone(concrete.return_type);
            if (out->c_expr == NULL || out->type == NULL) {
                free(out->c_expr);
                out->c_expr = NULL;
                cgtype_free(out->type);
                out->type = NULL;
                free(ret_cname);
                buf_free(&args_buf);
                return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
            out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
            if (out->owns_ref) {
                if (!cg_register_local_for_cleanup(cg, ret_cname, out->type, e->token)) {
                    free(out->c_expr);
                    out->c_expr = NULL;
                    cgtype_free(out->type);
                    out->type = NULL;
                    free(ret_cname);
                    buf_free(&args_buf);
                    return false;
                }
                /* For aggregate (spec fat value) returns: the cleanup chain
                 * now owns the +1 reference.  Callers that create an alias
                 * (let binding, materialize-to-local) must retain before
                 * aliasing, so signal the value as borrowed (owns_ref=false). */
                if (cgtype_is_aggregate(out->type)) {
                    out->owns_ref = false;
                }
            }
            ok = true;
            free(ret_cname);
        } else {
            Buf b;

            buf_init(&b);
            buf_append_fmt(&b,
                           "%s(%s)",
                           cg_extern_call_target(&concrete),
                           args_buf.data ? args_buf.data : "");
            out->c_expr = b.data;
            out->type = cgtype_clone(concrete.return_type);
            out->owns_ref = cgtype_is_managed(out->type) || cgtype_is_aggregate(out->type);
            ok = out->c_expr != NULL && out->type != NULL;
        }
        buf_free(&args_buf);
    } else {
        ok = cg_emit_registered_call(cg, e, NULL, &concrete, out);
    }

cleanup:
    if (desc_exprs != NULL) {
        for (size_t i = 0; i < sig->type_param_count; ++i) {
            free(desc_exprs[i]);
        }
    }
    free(desc_exprs);
    free((void *)constraint_specs);
    free(param_is_direct_type_param);
    for (size_t i = 0; i < sig->param_count; ++i) {
        cgtype_free(param_types[i]);
    }
    free(param_types);
    for (size_t i = 0; i < sig->type_param_count; ++i) {
        cgtype_free(type_args[i]);
    }
    free(type_args);
    cgtype_free(return_type);
    return ok;
}

/* Emit a call to a generic function.
 *
 * Protocol at the call site:
 *   1. For each closed type parameter: reuse one file-scope static
 *      FengGenericParamDescriptor. Forwarded open parameters reuse their
 *      incoming descriptor pointer without copying its fields.
 *   2. For each parameter whose by-value representation depends on a type
 *      parameter: reuse an existing stable value address or materialise once,
 *      then pass that address.
 *   3. If the function has a non-void return type: allocate a local of the
 *      concrete return C type, pass &local, use local as the result expr. */
static bool cg_emit_generic_call(CG *cg, const FengExpr *e,
                                  const GenericFn *gfn, ExprResult *out) {
    er_init(out);
    const FengCallableSignature *sig = &gfn->decl->as.function_decl;
    size_t tp_count  = gfn->type_param_count;
    size_t arg_count = e->as.call.arg_count;
    bool is_variadic = sig->param_count > 0U &&
                       sig->params[sig->param_count - 1U].is_variadic;
    size_t fixed_count = is_variadic ? sig->param_count - 1U : sig->param_count;
    size_t emitted_arg_count = is_variadic ? sig->param_count : arg_count;
    bool has_prepacked_variadic_arg =
        is_variadic && arg_count > 0U &&
        e->as.call.args[arg_count - 1U]->is_prepacked_variadic_arg;
    CGType *variadic_array_type = NULL;

    if ((is_variadic && arg_count < fixed_count) ||
        (!is_variadic && arg_count != sig->param_count)) {
        return cg_fail(cg,
                       e->token,
                       "IE0001", "codegen: semantic call arity invariant was not satisfied");
    }

    /* ---- Step 1: prepare explicit type arguments, then emit arguments. ---- */
    ExprResult *args = calloc(arg_count + 1, sizeof *args);
    if (!args) return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    CGType **type_args = calloc(tp_count + 1, sizeof *type_args);
    if (!type_args) {
        for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
        free(args);
        return cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
    }
    bool ok = true;
    bool has_resolved_type_args = false;

    if (e->as.call.has_explicit_type_args) {
        if (e->as.call.explicit_type_arg_count != tp_count) {
            cg_fail(cg, e->token,
                "CE0306", "codegen: generic function '%s' expects %zu type argument(s), got %zu",
                gfn->feng_name,
                tp_count,
                e->as.call.explicit_type_arg_count);
            ok = false;
        }
        for (size_t i = 0; ok && i < tp_count; i++) {
            if (!cg_resolve_type(cg, e->as.call.explicit_type_args[i],
                                 &e->token, &type_args[i])) {
                ok = false; break;
            }
        }
        has_resolved_type_args = ok;
    } else if (cg_call_has_resolved_callable_type_args(e, tp_count)) {
        has_resolved_type_args =
            cg_resolve_recorded_callable_type_args(cg,
                                                   e,
                                                   tp_count,
                                                   type_args);
        ok = has_resolved_type_args;
    }
    if (!ok) goto bail;

    if (is_variadic) {
        if (!cg_resolve_selected_callable_type_ref(
                cg,
                e,
                sig,
                sig->params[sig->param_count - 1U].type,
                sig->params[sig->param_count - 1U].token,
                &variadic_array_type)) {
            ok = false;
        } else if (variadic_array_type == NULL ||
                   variadic_array_type->kind != CG_TYPE_ARRAY ||
                   variadic_array_type->element == NULL) {
            cg_fail(cg,
                    e->token,
                    "CE0307", "codegen: cannot determine concrete variadic parameter type for generic function '%s'",
                    gfn->feng_name);
            ok = false;
        }
    }
    if (!ok) goto bail;

    for (size_t i = 0; i < arg_count; i++) {
        CGType *expected_arg_type = NULL;
        const FengTypeRef *expected_arg_ref = NULL;

        if (i < fixed_count) {
            expected_arg_ref = sig->params[i].type;
        } else if (is_variadic) {
            const FengTypeRef *array_ref =
                sig->params[sig->param_count - 1U].type;

            expected_arg_ref = has_prepacked_variadic_arg
                ? array_ref
                : array_ref != NULL ? array_ref->as.inner : NULL;
        } else if (i < sig->param_count) {
            expected_arg_ref = sig->params[i].type;
        }
        if (has_resolved_type_args && expected_arg_ref != NULL) {
            if (!cg_resolve_selected_callable_type_ref(
                    cg,
                    e,
                    sig,
                    expected_arg_ref,
                    e->as.call.args[i]->token,
                    &expected_arg_type)) {
                ok = false;
            }
        }
        if (ok && !cg_emit_expr_for_expected_type(cg,
                                                  e->as.call.args[i],
                                                  expected_arg_type,
                                                  &args[i])) {
            ok = false;
        }
        cgtype_free(expected_arg_type);
        if (!ok) goto bail;
    }

    /* ---- Step 2: determine inferred type arguments when not explicit. ---- */
    if (!e->as.call.has_explicit_type_args && !has_resolved_type_args) {
        /* Infer type arguments from actual argument types. */
        for (size_t i = 0; i < tp_count && ok; i++) {
            type_args[i] = cg_infer_type_arg(gfn, i, e, args, arg_count);
            if (!type_args[i]) {
                cg_fail(cg, e->token,
                    "CE0308", "codegen: cannot infer type argument %zu for generic function '%s'",
                    i, gfn->feng_name);
                ok = false;
            }
        }
    }
    if (!ok) goto bail;

    /* ---- Step 3: build descriptor expressions for each type param ---- */
    char **desc_exprs = calloc(tp_count + 1, sizeof *desc_exprs);
    if (!desc_exprs) { cg_fail(cg, e->token, "IE0001", "codegen: out of memory"); ok = false; goto bail; }
    bool saved_constraint_in_generic_fn = cg->in_generic_fn;
    size_t saved_constraint_tp_count = cg->generic_fn_type_param_count;
    char **saved_constraint_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_constraint_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_constraint_tp_descs = cg->generic_fn_type_param_descs;
    for (size_t i = 0; i < tp_count && ok; i++) {
        FengToken _etok = e->token;
        const UserSpec *constraint_spec = NULL;
        if (i < sig->type_param_count && sig->type_params[i].constraint) {
            CGType *constraint_type = NULL;
            cg->in_generic_fn = true;
            cg->generic_fn_type_param_count = tp_count;
            cg->generic_fn_type_param_names = gfn->type_param_names;
            cg->generic_fn_type_param_constraints = NULL;
            cg->generic_fn_type_param_descs = NULL;
            if (!cg_resolve_type(cg, sig->type_params[i].constraint,
                                 &sig->type_params[i].token, &constraint_type)) {
                ok = false;
            } else {
                constraint_spec = constraint_type ? constraint_type->user_spec : NULL;
                cgtype_free(constraint_type);
            }
            cg->in_generic_fn = saved_constraint_in_generic_fn;
            cg->generic_fn_type_param_count = saved_constraint_tp_count;
            cg->generic_fn_type_param_names = saved_constraint_tp_names;
            cg->generic_fn_type_param_constraints = saved_constraint_tp_constraints;
            cg->generic_fn_type_param_descs = saved_constraint_tp_descs;
        }
        if (ok && !cg_generic_descriptor_expr(cg, type_args[i], constraint_spec,
                                              &_etok, &desc_exprs[i])) {
            ok = false;
        }
    }
    if (!ok) {
        for (size_t i = 0; i < tp_count; i++) free(desc_exprs[i]);
        free(desc_exprs);
        goto bail;
    }

    /* ---- Step 4: apply the shared generic parameter ABI. ---- */
    /* Temporarily activate generic-fn type param state so cg_resolve_type
     * recognises the param type refs (T, U, …) as generic params. */
    bool saved_in_generic_fn = cg->in_generic_fn;
    bool saved_generic_return_uses_out = cg->generic_return_uses_out;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;

    cg->in_generic_fn = true;
    cg->generic_fn_type_param_count = tp_count;
    cg->generic_fn_type_param_names = gfn->type_param_names;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;

    char **arg_addr_exprs = calloc(
        emitted_arg_count + 1U, sizeof *arg_addr_exprs);
    bool *arg_uses_address_abi = calloc(
        emitted_arg_count + 1U, sizeof *arg_uses_address_abi);
    CGType **shared_param_types = calloc(
        emitted_arg_count + 1U, sizeof *shared_param_types);
    if (!arg_addr_exprs || !arg_uses_address_abi || !shared_param_types) {
        cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
        ok = false;
    }

    for (size_t i = 0; i < emitted_arg_count && ok; i++) {
        if (i < sig->param_count && sig->params[i].type != NULL) {
            if (cg_resolve_type(cg,
                                sig->params[i].type,
                                &e->token,
                                &shared_param_types[i])) {
                arg_uses_address_abi[i] =
                    cg_shared_generic_param_uses_address(
                        shared_param_types[i]);
            } else {
                ok = false;
            }
        }
    }

    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_return_uses_out = saved_generic_return_uses_out;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;

    /* Argument expressions belong to the caller context. Restore it before
     * preparing by-value copies so an open actual T uses the caller's
     * descriptor rather than the callee declaration's type-parameter frame. */
    for (size_t i = 0; i < fixed_count && ok; i++) {
        arg_addr_exprs[i] = cg_shared_callable_argument_for_type_expr_dup(
            cg,
            &args[i],
            shared_param_types[i],
            arg_uses_address_abi[i],
            "_ga");
        if (!arg_addr_exprs[i]) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            ok = false;
        }
    }
    if (is_variadic && ok) {
        ExprResult variadic_array;

        er_init(&variadic_array);
        if (has_prepacked_variadic_arg) {
            if (arg_count != fixed_count + 1U) {
                cg_fail(cg,
                        e->token,
                        "CE0123", "codegen: prepacked variadic argument is not at the first variadic position");
                ok = false;
            } else {
                variadic_array = args[fixed_count];
                er_init(&args[fixed_count]);
            }
        } else if (!cg_pack_variadic_expr_results(
                       cg,
                       &e->token,
                       args + fixed_count,
                       arg_count - fixed_count,
                       variadic_array_type->element,
                       &variadic_array)) {
            ok = false;
        }
        if (ok) {
            arg_addr_exprs[fixed_count] =
                cg_shared_callable_argument_for_type_expr_dup(
                    cg,
                    &variadic_array,
                    shared_param_types[fixed_count],
                    arg_uses_address_abi[fixed_count],
                    "_ga");
            if (arg_addr_exprs[fixed_count] == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
            }
        }
        er_free(&variadic_array);
    } else {
        for (size_t i = fixed_count; i < arg_count && ok; ++i) {
            arg_addr_exprs[i] = cg_shared_callable_argument_for_type_expr_dup(
                cg,
                &args[i],
                shared_param_types[i],
                arg_uses_address_abi[i],
                "_ga");
            if (arg_addr_exprs[i] == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                ok = false;
            }
        }
    }
    free(arg_uses_address_abi);
    if (shared_param_types != NULL) {
        for (size_t i = 0; i < emitted_arg_count; ++i) {
            cgtype_free(shared_param_types[i]);
        }
    }
    free(shared_param_types);

    if (!ok) {
        for (size_t i = 0; i < emitted_arg_count; i++) free(arg_addr_exprs[i]);
        free(arg_addr_exprs);
        for (size_t i = 0; i < tp_count; i++) free(desc_exprs[i]);
        free(desc_exprs);
        goto bail;
    }

    /* ---- Step 5: determine concrete return type ---- */
    CGType *concrete_return = NULL;
    if (!cg_resolve_selected_callable_return_type(
            cg, e, sig, e->token, &concrete_return)) {
        for (size_t i = 0; i < emitted_arg_count; i++) free(arg_addr_exprs[i]);
        free(arg_addr_exprs);
        for (size_t i = 0; i < tp_count; i++) free(desc_exprs[i]);
        free(desc_exprs);
        goto bail;
    }
    bool has_out_param = (concrete_return->kind != CG_TYPE_VOID);

    /* ---- Step 5½: generate FengFunctionDescriptor (§2.4) ---- */
    char *call_func_desc_expr = NULL;
    {
        const FengReifiableDepSet *fn_dep_set =
            feng_semantic_lookup_reifiable_dep_set(cg->analysis, gfn->decl);

        if (saved_in_generic_fn) {
            call_func_desc_expr =
                cg_callable_descriptor_expr_for_call(cg, e, e->token);
        } else {
            FengTypeRef **concrete_type_refs = tp_count > 0U
                ? (FengTypeRef **)calloc(
                      tp_count, sizeof(*concrete_type_refs))
                : NULL;
            bool refs_ok = tp_count == 0U || concrete_type_refs != NULL;

            for (size_t index = 0U; index < tp_count && refs_ok; ++index) {
                concrete_type_refs[index] =
                    cg_type_ref_from_cgtype(cg, type_args[index], e->token);
                refs_ok = concrete_type_refs[index] != NULL;
            }
            if (refs_ok) {
                refs_ok = cg_emit_closed_callable_fdesc(
                    cg,
                    fn_dep_set,
                    sig->type_params,
                    tp_count,
                    concrete_type_refs,
                    gfn->owner_program,
                    e->token,
                    gfn->c_name,
                    gfn->feng_name,
                    NULL,
                    &call_func_desc_expr);
            }
            for (size_t index = 0U; index < tp_count; ++index) {
                cg_type_ref_free(
                    concrete_type_refs != NULL
                        ? concrete_type_refs[index]
                        : NULL);
            }
            free(concrete_type_refs);
            if (!refs_ok && !cg->failed) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            }
        }
        if (call_func_desc_expr == NULL) {
            for (size_t i = 0; i < emitted_arg_count; i++) free(arg_addr_exprs[i]);
            free(arg_addr_exprs);
            for (size_t i = 0; i < tp_count; i++) free(desc_exprs[i]);
            free(desc_exprs);
            cgtype_free(concrete_return);
            goto bail;
        }
    }
    bool has_fn_desc = false;
    {
        const FengReifiableDepSet *fn_dep_set =
            feng_semantic_lookup_reifiable_dep_set(cg->analysis, gfn->decl);

        if (call_func_desc_expr == NULL &&
            fn_dep_set != NULL && fn_dep_set->dep_count > 0U) {
            const FengCallableSignature *fn_sig = &gfn->decl->as.function_decl;

            /* Build FengTypeRef* array for concrete type args. */
            FengTypeRef **concrete_type_refs = (FengTypeRef **)calloc(
                tp_count + 1U, sizeof(FengTypeRef *));
            bool refs_ok = (concrete_type_refs != NULL);

            for (size_t i = 0; i < tp_count && refs_ok; ++i) {
                if (e->as.call.has_explicit_type_args) {
                    concrete_type_refs[i] =
                        cg_type_ref_clone(e->as.call.explicit_type_args[i]);
                } else {
                    concrete_type_refs[i] =
                        cg_synthetic_type_ref_from_cgtype(type_args[i]);
                }
                if (concrete_type_refs[i] == NULL) {
                    refs_ok = false;
                }
            }

            if (refs_ok) {
                /* Build owner type param name slices for sort key. */
                FengSlice *fn_tparam_names = (FengSlice *)calloc(
                    fn_sig->type_param_count, sizeof(FengSlice));
                if (fn_tparam_names != NULL) {
                    for (size_t i = 0; i < fn_sig->type_param_count; ++i) {
                        fn_tparam_names[i] = fn_sig->type_params[i].name;
                    }

                    typedef struct {
                        size_t dep_index;
                        char *sort_key;
                    } SortedDep;

                    size_t fn_agg_count = 0U;
                    size_t fn_type_count = 0U;
                    for (size_t i = 0; i < fn_dep_set->dep_count; ++i) {
                        if (fn_dep_set->deps[i].kind ==
                            FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                            fn_agg_count++;
                        } else {
                            fn_type_count++;
                        }
                    }

                    SortedDep *fn_agg_sorted = fn_agg_count > 0U
                        ? (SortedDep *)calloc(fn_agg_count, sizeof(SortedDep))
                        : NULL;
                    SortedDep *fn_type_sorted = fn_type_count > 0U
                        ? (SortedDep *)calloc(fn_type_count, sizeof(SortedDep))
                        : NULL;

                    size_t fai = 0U;
                    size_t fti = 0U;
                    for (size_t i = 0; i < fn_dep_set->dep_count; ++i) {
                        char *key = cg_reifiable_sort_key(
                            fn_dep_set->deps[i].type_ref,
                            fn_tparam_names,
                            fn_sig->type_param_count, true);
                        if (fn_dep_set->deps[i].kind ==
                            FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                            if (fn_agg_sorted != NULL) {
                                fn_agg_sorted[fai].dep_index = i;
                                fn_agg_sorted[fai].sort_key = key;
                                fai++;
                            } else {
                                free(key);
                            }
                        } else {
                            if (fn_type_sorted != NULL) {
                                fn_type_sorted[fti].dep_index = i;
                                fn_type_sorted[fti].sort_key = key;
                                fti++;
                            } else {
                                free(key);
                            }
                        }
                    }

                    /* Insertion sort by key. */
                    for (size_t i = 1; i < fn_agg_count; ++i) {
                        SortedDep tmp = fn_agg_sorted[i];
                        size_t j = i;
                        while (j > 0 &&
                               strcmp(fn_agg_sorted[j - 1].sort_key,
                                      tmp.sort_key) > 0) {
                            fn_agg_sorted[j] = fn_agg_sorted[j - 1];
                            j--;
                        }
                        fn_agg_sorted[j] = tmp;
                    }
                    for (size_t i = 1; i < fn_type_count; ++i) {
                        SortedDep tmp = fn_type_sorted[i];
                        size_t j = i;
                        while (j > 0 &&
                               strcmp(fn_type_sorted[j - 1].sort_key,
                                      tmp.sort_key) > 0) {
                            fn_type_sorted[j] = fn_type_sorted[j - 1];
                            j--;
                        }
                        fn_type_sorted[j] = tmp;
                    }

                    /* Emit agg deps array. */
                    if (fn_agg_count > 0U && fn_agg_sorted != NULL) {
                        buf_append_fmt(cg->cur_body,
                            "    static const FengAggregateDescriptor *%s__rad[] = {\n",
                            gfn->c_name);
                        for (size_t i = 0; i < fn_agg_count; ++i) {
                            const FengReifiableDep *dep =
                                &fn_dep_set->deps[fn_agg_sorted[i].dep_index];
                            char *dn = cg_resolve_dep_descriptor_name(
                                cg, dep->type_ref,
                                fn_sig->type_params,
                                fn_sig->type_param_count,
                                concrete_type_refs,
                                gfn->owner_program,
                                FENG_REIFIABLE_DEP_KIND_AGGREGATE,
                                &e->token);
                            if (dn != NULL) {
                                buf_append_fmt(cg->cur_body,
                                    "        &%s,\n", dn);
                                free(dn);
                            }
                        }
                        buf_append_cstr(cg->cur_body, "    };\n");
                    }

                    /* Emit type deps array. */
                    if (fn_type_count > 0U && fn_type_sorted != NULL) {
                        buf_append_fmt(cg->cur_body,
                            "    static const FengTypeDescriptor *%s__rtd[] = {\n",
                            gfn->c_name);
                        for (size_t i = 0; i < fn_type_count; ++i) {
                            const FengReifiableDep *dep =
                                &fn_dep_set->deps[fn_type_sorted[i].dep_index];
                            char *dn = cg_resolve_dep_descriptor_name(
                                cg, dep->type_ref,
                                fn_sig->type_params,
                                fn_sig->type_param_count,
                                concrete_type_refs,
                                gfn->owner_program,
                                FENG_REIFIABLE_DEP_KIND_MANAGED,
                                &e->token);
                            if (dn != NULL) {
                                buf_append_fmt(cg->cur_body,
                                    "        &%s,\n", dn);
                                free(dn);
                            }
                        }
                        buf_append_cstr(cg->cur_body, "    };\n");
                    }

                    /* Emit the FengFunctionDescriptor. */
                    buf_append_fmt(cg->cur_body,
                        "    static const FengFunctionDescriptor %s__desc = {\n"
                        "        .name = \"%s\",\n",
                        gfn->c_name, gfn->feng_name);
                    if (fn_agg_count > 0U && fn_agg_sorted != NULL) {
                        buf_append_fmt(cg->cur_body,
                            "        .reified_agg_deps_count = %zu,\n"
                            "        .reified_agg_deps = %s__rad,\n",
                            fn_agg_count, gfn->c_name);
                    }
                    if (fn_type_count > 0U && fn_type_sorted != NULL) {
                        buf_append_fmt(cg->cur_body,
                            "        .reified_type_deps_count = %zu,\n"
                            "        .reified_type_deps = %s__rtd,\n",
                            fn_type_count, gfn->c_name);
                    }
                    buf_append_cstr(cg->cur_body, "    };\n");
                    has_fn_desc = true;

                    for (size_t i = 0; i < fn_agg_count; ++i) {
                        free(fn_agg_sorted[i].sort_key);
                    }
                    for (size_t i = 0; i < fn_type_count; ++i) {
                        free(fn_type_sorted[i].sort_key);
                    }
                    free(fn_agg_sorted);
                    free(fn_type_sorted);
                    free(fn_tparam_names);
                }
            }

            for (size_t i = 0; i < tp_count; ++i) {
                cg_type_ref_free(concrete_type_refs[i]);
            }
            free(concrete_type_refs);
        }
    }

    /* ---- Step 6: allocate result local and emit the call ---- */
    char *ret_cname = NULL;
    char *ret_erased_descriptor_name = NULL;
    char *ret_erased_size_name = NULL;
    char *ret_reified_descriptor_name = NULL;
    char *ret_reified_size_name = NULL;
    bool return_uses_erased_generic_storage =
        has_out_param && concrete_return->kind == CG_TYPE_GENERIC_PARAM;
    bool return_uses_reified_storage =
        has_out_param &&
        cg_type_uses_reified_storage(cg, concrete_return);
    if (has_out_param) {
        ret_cname = cg_fresh_temp(cg, "_gr");
        if (ret_cname == NULL) {
            cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
            goto generic_call_result_failure;
        }
        if (return_uses_erased_generic_storage) {
            if (!cg_emit_erased_generic_storage_declaration(
                    cg,
                    concrete_return,
                    ret_cname,
                    e->token,
                    &ret_erased_descriptor_name,
                    &ret_erased_size_name)) {
                goto generic_call_result_failure;
            }
        } else if (return_uses_reified_storage) {
            if (!cg_emit_reified_storage_declaration(
                    cg,
                    concrete_return,
                    ret_cname,
                    e->token,
                    &ret_reified_descriptor_name,
                    &ret_reified_size_name)) {
                goto generic_call_result_failure;
            }
        } else {
            char *cty = cg_ctype_dup(concrete_return);

            if (cty == NULL) {
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                goto generic_call_result_failure;
            }
            /* The callee establishes every returned slot through `_out`. */
            buf_append_fmt(cg->cur_body, "    %s %s;\n", cty, ret_cname);
            free(cty);
        }
    }

    /* Emit the call expression. §6.7: pass &desc as first arg. */
    if (call_func_desc_expr != NULL) {
        buf_append_fmt(cg->cur_body, "    %s(%s",
                       gfn->c_name, call_func_desc_expr);
    } else if (has_fn_desc) {
        buf_append_fmt(cg->cur_body, "    %s(&%s__desc",
                       gfn->c_name, gfn->c_name);
    } else {
        buf_append_fmt(cg->cur_body,
            "    %s(&(const FengFunctionDescriptor){.name = \"%s\"}",
            gfn->c_name, gfn->feng_name);
    }
    for (size_t i = 0; i < tp_count; i++) {
        buf_append_cstr(cg->cur_body, ", ");
        buf_append_cstr(cg->cur_body, desc_exprs[i]);
    }
    for (size_t i = 0; i < emitted_arg_count; i++) {
        buf_append_cstr(cg->cur_body, ", ");
        buf_append_cstr(cg->cur_body, arg_addr_exprs[i]);
    }
    if (has_out_param) {
        buf_append_cstr(cg->cur_body, ", ");
        buf_append_fmt(cg->cur_body,
                       (return_uses_erased_generic_storage ||
                        return_uses_reified_storage) ? "%s" : "&%s",
                       ret_cname);
    }
    buf_append_cstr(cg->cur_body, ");\n");

    /* ---- Step 7: set out result ---- */
    if (has_out_param) {
        out->c_expr = strdup(ret_cname);
        out->type = concrete_return;
        if (return_uses_erased_generic_storage) {
            if (out->c_expr == NULL ||
                !cg_register_erased_generic_storage_for_cleanup(
                    cg,
                    ret_cname,
                    concrete_return,
                    ret_erased_descriptor_name,
                    ret_erased_size_name,
                    e->token)) {
                free(out->c_expr);
                out->c_expr = NULL;
                out->type = NULL;
                cgtype_free(concrete_return);
                goto generic_call_result_failure_without_return_type;
            }
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_erased_generic_storage = true;
            out->erased_generic_descriptor_c_name =
                ret_erased_descriptor_name;
            out->erased_generic_size_c_name = ret_erased_size_name;
            ret_erased_descriptor_name = NULL;
            ret_erased_size_name = NULL;
        } else if (return_uses_reified_storage) {
            if (out->c_expr == NULL ||
                !scope_add(cg->cur_scope,
                           ret_cname,
                           ret_cname,
                           cgtype_clone(concrete_return),
                           false) ||
                !scope_mark_last_reified_storage(
                    cg->cur_scope,
                    ret_reified_descriptor_name,
                    ret_reified_size_name)) {
                free(out->c_expr);
                out->c_expr = NULL;
                out->type = NULL;
                cgtype_free(concrete_return);
                cg_fail(cg, e->token, "IE0001", "codegen: out of memory");
                goto generic_call_result_failure_without_return_type;
            }
            cg_emit_cleanup_push_for_reified_aggregate_storage(
                cg, ret_cname, ret_reified_descriptor_name);
            out->owns_ref = false;
            out->is_addressable = true;
            out->is_storage_address = true;
            out->uses_reified_storage = true;
            out->reified_descriptor_c_name =
                ret_reified_descriptor_name;
            out->reified_size_c_name = ret_reified_size_name;
            ret_reified_descriptor_name = NULL;
            ret_reified_size_name = NULL;
        } else {
            out->owns_ref = cgtype_is_managed(concrete_return) ||
                            cgtype_is_aggregate(concrete_return);
            if (out->owns_ref) {
                if (!cg_register_local_for_cleanup(
                        cg, ret_cname, concrete_return, e->token)) {
                    free(out->c_expr);
                    out->c_expr = NULL;
                    out->type = NULL;
                    cgtype_free(concrete_return);
                    for (size_t i = 0; i < emitted_arg_count; i++) {
                        free(arg_addr_exprs[i]);
                    }
                    free(arg_addr_exprs);
                    for (size_t i = 0; i < tp_count; i++) {
                        free(desc_exprs[i]);
                    }
                    free(desc_exprs);
                    for (size_t i = 0; i < arg_count; i++) {
                        er_free(&args[i]);
                    }
                    free(args);
                    for (size_t i = 0; i < tp_count; i++) {
                        cgtype_free(type_args[i]);
                    }
                    free(type_args);
                    free(ret_cname);
                    return false;
                }
                /* For aggregate (spec fat value) and managed (refcounted
                 * heap object) returns: the cleanup chain now owns the +1
                 * reference. Callers that create an alias (let binding,
                 * materialize-to-local, return) must retain before aliasing,
                 * so signal the value as borrowed (owns_ref=false). Without
                 * this, a `let w = make<T>();` would copy the borrowed pointer
                 * into a new cleanup-registered local, and both cleanups would
                 * release the same +1 — double-free at scope exit. */
                out->owns_ref = false;
            }
        }
    } else {
        out->c_expr = strdup("((void)0)");
        out->type = cgtype_new(CG_TYPE_VOID);
        out->owns_ref = false;
        cgtype_free(concrete_return);
    }

    for (size_t i = 0; i < emitted_arg_count; i++) free(arg_addr_exprs[i]);
    free(arg_addr_exprs);
    for (size_t i = 0; i < tp_count; i++) free(desc_exprs[i]);
    free(desc_exprs);
    for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
    free(args);
    for (size_t i = 0; i < tp_count; i++) cgtype_free(type_args[i]);
    free(type_args);
    free(ret_cname);
    free(ret_erased_descriptor_name);
    free(ret_erased_size_name);
    free(ret_reified_descriptor_name);
    free(ret_reified_size_name);
    free(call_func_desc_expr);
    cgtype_free(variadic_array_type);
    return out->c_expr && out->type;

generic_call_result_failure:
    cgtype_free(concrete_return);
generic_call_result_failure_without_return_type:
    for (size_t i = 0; i < emitted_arg_count; i++) free(arg_addr_exprs[i]);
    free(arg_addr_exprs);
    for (size_t i = 0; i < tp_count; i++) free(desc_exprs[i]);
    free(desc_exprs);
    for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
    free(args);
    for (size_t i = 0; i < tp_count; i++) cgtype_free(type_args[i]);
    free(type_args);
    free(ret_cname);
    free(ret_erased_descriptor_name);
    free(ret_erased_size_name);
    free(ret_reified_descriptor_name);
    free(ret_reified_size_name);
    free(call_func_desc_expr);
    cgtype_free(variadic_array_type);
    return false;

bail:
    for (size_t i = 0; i < arg_count; i++) er_free(&args[i]);
    free(args);
    for (size_t i = 0; i < tp_count; i++) cgtype_free(type_args[i]);
    free(type_args);
    cgtype_free(variadic_array_type);
    return false;
}

static bool cg_emit_function(CG *cg,
                             const FengDecl *decl,
                             bool is_main,
                             FengCompileTarget target) {
    char **captured_names = NULL;
    size_t captured_name_count = 0U;
    char **saved_captured_names = cg->captured_binding_names;
    size_t saved_captured_name_count = cg->captured_binding_name_count;
    bool saved_captures_self = cg->current_callable_captures_self;
    Scope *fn_scope = NULL;
    bool ok = false;

    const FreeFn *pre_registered = cg_find_free_fn_by_decl(cg, decl);
    FreeFn *fn;
    if (pre_registered != NULL) {
        fn = (FreeFn *)pre_registered;
    } else {
        if (!cg_register_free_fn(cg, decl)) return false;
        fn = &cg->free_fns[cg->free_fn_count - 1];
    }
    bool exports_public_symbol = target == FENG_COMPILE_TARGET_LIB &&
                                 decl->visibility == FENG_VISIBILITY_PUBLIC;
    bool needs_static = cg_free_fn_has_abi_wrapper(fn) ? true : !exports_public_symbol;
    bool abi_wrapper_needs_static = !exports_public_symbol;
    cg->cur_fn_is_main = is_main;
    cg->cur_return_type = fn->return_type;

    if (is_main && !cg_check_main_signature(cg, fn)) return false;

    if (pre_registered == NULL) {
        cg_emit_free_fn_proto(&cg->fn_protos, fn, needs_static);
        cg_emit_free_fn_abi_proto(&cg->fn_protos, fn, abi_wrapper_needs_static);
    }

    Buf *body = &cg->fn_defs;
    cg->cur_body = body;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    if (needs_static) {
        buf_append_cstr(body, "static ");
    }
    cg_emit_c_type(body, fn->return_type);
    buf_append_fmt(body, " %s(", fn->c_name);
    if (fn->param_count == 0) buf_append_cstr(body, "void");
    fn_scope = scope_push(NULL);
    if (!fn_scope) {
        cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->cur_scope = fn_scope;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    cg->loop_depth = 0;
    cg->try_depth = 0;

    for (size_t i = 0; i < fn->param_count; i++) {
        if (i) buf_append_cstr(body, ", ");
        cg_emit_c_type(body, fn->param_types[i]);
        buf_append_fmt(body, " %s",
            fn->param_names[i] ? fn->param_names[i] : "_p");
    }
    buf_append_cstr(body, ") {\n");
    if (!cg_emit_function_eh_prologue(cg, decl->token)) {
        goto cleanup;
    }
    if (!cg_debug_set_current_frame(cg,
                                    fn->c_name,
                                    fn->feng_name,
                                    FENG_CODEGEN_MAPING_FRAME_VISIBLE,
                                    decl->token) ||
        !cg_debug_add_current_frame_module_binding_records(cg, decl->token)) {
        goto cleanup;
    }

    if (!cg_compute_capture_requirements_in_block(decl->as.function_decl.body,
                                                  &captured_names,
                                                  &captured_name_count,
                                                  &cg->current_callable_captures_self)) {
        cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->captured_binding_names = captured_names;
    cg->captured_binding_name_count = captured_name_count;

    for (size_t i = 0; i < fn->param_count; i++) {
        const char *pn = fn->param_names[i] ? fn->param_names[i] : "_p";
        buf_append_fmt(body, "    (void)%s;\n", pn);
    }

    for (size_t i = 0; i < fn->param_count; i++) {
        const char *pn = fn->param_names[i] ? fn->param_names[i] : "_p";
        if (cg_current_callable_captures_name(cg, pn, strlen(pn))) {
            if (!cg_scope_bind_capture_cell(cg,
                                            fn_scope,
                                            decl->as.function_decl.params[i].name,
                                            fn->param_types[i],
                                            decl->as.function_decl.params[i].token,
                                            pn,
                                            true,
                                            false,
                                            true,
                                            FENG_CODEGEN_MAPING_VARIABLE_PARAM) ||
                !scope_mark_last_binding_mutability(
                    fn_scope,
                    decl->as.function_decl.params[i].mutability)) {
                goto cleanup;
            }
            continue;
        }
        CGType *pt = cgtype_clone(fn->param_types[i]);
        if (!scope_add(fn_scope, pn, pn, pt, true) ||
            !scope_mark_last_binding_mutability(
                fn_scope,
                decl->as.function_decl.params[i].mutability)) {
            cgtype_free(pt);
            cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (!cg_debug_add_variable_record_cstr_type_ref(
            cg,
            pn,
            pn,
            NULL,
            decl->as.function_decl.params[i].type,
            FENG_CODEGEN_MAPING_VARIABLE_PARAM,
            decl->as.function_decl.params[i].token)) {
            goto cleanup;
        }
    }

    if (!cg_emit_block(cg, decl->as.function_decl.body)) goto cleanup;

    cg_release_scope(cg, fn_scope);
    cg_emit_function_fallthrough_cleanup(cg);
    if (fn->return_type->kind == CG_TYPE_VOID) {
        buf_append_cstr(body, "    return;\n");
    } else if (is_main && fn->return_type->kind == CG_TYPE_I32) {
        buf_append_cstr(body, "    return 0;\n");
    } else {
        buf_append_cstr(body, "    feng_panic(\"function reached end without return\");\n");
    }
    buf_append_cstr(body, "}\n\n");
    ok = true;
    if (ok && !cg_emit_free_fn_abi_wrapper(cg, fn, abi_wrapper_needs_static)) {
        ok = false;
    }

cleanup:
    cg->captured_binding_names = saved_captured_names;
    cg->captured_binding_name_count = saved_captured_name_count;
    cg->current_callable_captures_self = saved_captures_self;
    for (size_t i = 0; i < captured_name_count; ++i) free(captured_names[i]);
    free(captured_names);
    if (fn_scope != NULL) {
        cg->cur_scope = NULL;
        scope_pop_free(fn_scope);
    }
    cg->cur_body = NULL;
    cg->cur_return_type = NULL;
    cg->cur_fn_is_main = false;
    cg->current_frame_backend_symbol = NULL;
    cg->cur_function_has_frame_marker = false;
    return ok;
}

/* ===================== driver ===================== */

static bool slice_eq(FengSlice s, const char *cstr) {
    size_t n = strlen(cstr);
    return s.length == n && memcmp(s.data, cstr, n) == 0;
}

static bool cg_emit_module_header(CG *cg, const FengProgram *prog) {
    free(cg->module_mangle);
    free(cg->module_dot_name);
    cg->module_mangle = cg_module_mangle(prog->module_segments,
                                         prog->module_segment_count);
    cg->module_dot_name = cg_module_dot(prog->module_segments,
                                        prog->module_segment_count);
    if (!cg->module_mangle || !cg->module_dot_name) {
        return cg_fail(cg, prog->module_token, "IE0001", "codegen: out of memory");
    }
    return true;
}

/* ----- Spec witness instance emission (Step 4b — value model §6.5/§8.2) ----- */

/* Look up an already-emitted (T, S) witness table; returns NULL on miss. */
static const char *cg_witness_table_lookup(const CG *cg, const UserType *t,
                                           const UserSpec *s) {
    for (size_t i = 0; i < cg->witness_table_count; i++) {
        if (cg->witness_tables[i].t == t && cg->witness_tables[i].s == s) {
            return cg->witness_tables[i].c_var;
        }
    }
    return NULL;
}

static const char *cg_spec_slot_witness_lookup(const CG *cg,
                                               const UserSpec *src,
                                               const UserSpec *dst) {
    for (size_t i = 0; i < cg->spec_slot_witness_table_count; ++i) {
        if (cg->spec_slot_witness_tables[i].src == src &&
            cg->spec_slot_witness_tables[i].dst == dst) {
            return cg->spec_slot_witness_tables[i].c_var;
        }
    }
    return NULL;
}

/* Compare semantic subject keys for codegen witness-cache identity. */
static bool cg_subject_keys_equal(const FengSemanticSubjectKey *left,
                                  const FengSemanticSubjectKey *right) {
    if (left == NULL || right == NULL || left->kind != right->kind) {
        return false;
    }
    switch (left->kind) {
        case FENG_SEMANTIC_SUBJECT_KEY_TYPE_DECL:
            return left->as.type_decl == right->as.type_decl;
        case FENG_SEMANTIC_SUBJECT_KEY_BUILTIN:
            return left->as.builtin_canonical_name != NULL &&
                   right->as.builtin_canonical_name != NULL &&
                   strcmp(left->as.builtin_canonical_name,
                          right->as.builtin_canonical_name) == 0;
        case FENG_SEMANTIC_SUBJECT_KEY_ARRAY:
            return left->as.array.rank == right->as.array.rank &&
                   left->as.array.writable_mask == right->as.array.writable_mask &&
                   cg_type_ref_equal(left->as.array.element_type_ref,
                                     right->as.array.element_type_ref);
        case FENG_SEMANTIC_SUBJECT_KEY_INVALID:
            return false;
    }
    return false;
}

/* Find a cached non-user-type witness for one subject storage and spec. */
static const char *cg_subject_witness_table_lookup(
    const CG *cg,
    const FengSemanticSubjectKey *subject_key,
    FengSpecObjectSubjectStorageKind storage,
    const UserSpec *spec) {
    for (size_t index = 0U;
         index < cg->subject_witness_table_count;
         ++index) {
        if (cg->subject_witness_tables[index].storage == storage &&
            cg->subject_witness_tables[index].spec == spec &&
            cg_subject_keys_equal(&cg->subject_witness_tables[index].subject_key,
                                  subject_key)) {
            return cg->subject_witness_tables[index].c_var;
        }
    }
    return NULL;
}

/* Cache a newly emitted non-user-type witness variable. */
static bool cg_subject_witness_table_add(
    CG *cg,
    const FengSemanticSubjectKey *subject_key,
    FengSpecObjectSubjectStorageKind storage,
    const UserSpec *spec,
    char *c_var) {
    if (cg->subject_witness_table_count == cg->subject_witness_table_capacity) {
        size_t new_capacity = cg->subject_witness_table_capacity == 0U
                                  ? 8U
                                  : cg->subject_witness_table_capacity * 2U;
        void *grown = realloc(cg->subject_witness_tables,
                              new_capacity * sizeof(*cg->subject_witness_tables));

        if (grown == NULL) {
            return false;
        }
        cg->subject_witness_tables = grown;
        cg->subject_witness_table_capacity = new_capacity;
    }
    cg->subject_witness_tables[cg->subject_witness_table_count].subject_key =
        *subject_key;
    cg->subject_witness_tables[cg->subject_witness_table_count].storage = storage;
    cg->subject_witness_tables[cg->subject_witness_table_count].spec = spec;
    cg->subject_witness_tables[cg->subject_witness_table_count].c_var = c_var;
    cg->subject_witness_table_count++;
    return true;
}

typedef struct CGWitnessBinding {
    FengSpecWitnessSourceKind source_kind;
    const UserField *field;
    const UserMethod *method;
    const UserFit *fit;
    /* For static fields (source_kind == FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_FIELD
     * with sm->is_static), `static_binding` carries the type-level storage
     * descriptor instead of an instance UserField. */
    const TypeStaticBinding *static_binding;
} CGWitnessBinding;

/* Emit the receiver-free thunk shared by every supported static method
 * implementation source. Builtin fits keep their existing leading function
 * descriptor; type and user-fit wrappers use their ordinary static ABI. */
static bool cg_emit_static_spec_method_thunk(
    CG *cg,
    const UserSpec *spec,
    const UserSpecMember *spec_member,
    const UserMethod *method,
    const BuiltinFit *builtin_fit,
    const char *prefix,
    FengToken blame);

static bool cg_type_ref_matches_open_context_parameter(
    const FengTypeRef *actual,
    const FengTypeRef *pattern,
    char *const *context_names,
    size_t context_count,
    const char *parameter_name,
    const FengTypeRef **binding);

/* Match one lowered implementation type against an open generic spec-member
 * type for a single spec context parameter. Repeating this traversal for each
 * context parameter preserves one consistent binding across the method's
 * return and all parameter positions without constructing a substitution map. */
static bool cg_type_matches_open_spec_context_parameter(
    const CG *cg,
    const CGType *actual,
    const CGType *pattern,
    const UserSpec *spec,
    const char *parameter_name,
    const FengTypeRef **binding,
    FengTypeRef **owned_binding) {
    if (cg == NULL || actual == NULL || pattern == NULL || spec == NULL ||
        parameter_name == NULL || binding == NULL || owned_binding == NULL) {
        return false;
    }
    if (pattern->kind == CG_TYPE_GENERIC_PARAM) {
        size_t index = pattern->generic_param_index;

        if (index >= spec->generic_context_type_param_count) {
            return actual->kind == CG_TYPE_GENERIC_PARAM &&
                   actual->generic_param_index == index;
        }
        if (strcmp(spec->generic_context_type_param_names[index],
                   parameter_name) != 0) {
            return true;
        }
        FengTypeRef *actual_ref = cg_type_ref_from_cgtype(cg,
                                                          actual,
                                                          (FengToken){0});
        if (actual_ref == NULL) {
            return false;
        }
        if (*binding == NULL) {
            *binding = actual_ref;
            *owned_binding = actual_ref;
            return true;
        }
        bool matches = cg_type_ref_equal(*binding, actual_ref);
        cg_type_ref_free(actual_ref);
        return matches;
    }
    if (actual->kind != pattern->kind) {
        return false;
    }
    if (pattern->kind == CG_TYPE_POINTER || pattern->kind == CG_TYPE_ARRAY) {
        return cg_type_matches_open_spec_context_parameter(cg,
                                                           actual->element,
                                                           pattern->element,
                                                           spec,
                                                           parameter_name,
                                                           binding,
                                                           owned_binding);
    }
    if (pattern->kind == CG_TYPE_OBJECT) {
        if (actual->user == pattern->user) {
            return true;
        }
        if (actual->user == NULL || pattern->user == NULL ||
            !actual->user->is_generic_instance ||
            !pattern->user->is_generic_instance ||
            actual->user->generic_origin_decl !=
                pattern->user->generic_origin_decl ||
            actual->user->generic_type_arg_count !=
                pattern->user->generic_type_arg_count) {
            return false;
        }
        for (size_t index = 0U;
             index < pattern->user->generic_type_arg_count;
             ++index) {
            if (!cg_type_ref_matches_open_context_parameter(
                    actual->user->generic_type_args[index],
                    pattern->user->generic_type_args[index],
                    spec->generic_context_type_param_names,
                    spec->generic_context_type_param_count,
                    parameter_name,
                    binding)) {
                return false;
            }
        }
        return true;
    }
    if (pattern->kind == CG_TYPE_SPEC || pattern->kind == CG_TYPE_CALLABLE) {
        if (actual->user_spec == pattern->user_spec) {
            return true;
        }
        if (actual->user_spec == NULL || pattern->user_spec == NULL ||
            !actual->user_spec->is_generic_instance ||
            !pattern->user_spec->is_generic_instance ||
            actual->user_spec->generic_origin_decl !=
                pattern->user_spec->generic_origin_decl ||
            actual->user_spec->generic_type_arg_count !=
                pattern->user_spec->generic_type_arg_count) {
            return false;
        }
        for (size_t index = 0U;
             index < pattern->user_spec->generic_type_arg_count;
             ++index) {
            if (!cg_type_ref_matches_open_context_parameter(
                    actual->user_spec->generic_type_args[index],
                    pattern->user_spec->generic_type_args[index],
                    spec->generic_context_type_param_names,
                    spec->generic_context_type_param_count,
                    parameter_name,
                    binding)) {
                return false;
            }
        }
        return true;
    }
    return true;
}

/* Match one implementation field type against an open or closed generic spec
 * field pattern. Method matching already performs the same binding walk over
 * the complete signature; fields have one type position but must preserve the
 * identical open-context substitution rule. */
static bool cg_field_type_matches_spec_member(const CG *cg,
                                              const CGType *field_type,
                                              const UserSpec *spec,
                                              const UserSpecMember *member) {
    if (cg == NULL || field_type == NULL || spec == NULL || member == NULL ||
        member->kind != USM_KIND_FIELD || member->type == NULL) {
        return false;
    }
    if (spec->generic_context_type_param_count == 0U) {
        return cg_types_equal(field_type, member->type);
    }
    for (size_t index = 0U;
         index < spec->generic_context_type_param_count;
         ++index) {
        const FengTypeRef *binding = NULL;
        FengTypeRef *owned_binding = NULL;
        bool matches = cg_type_matches_open_spec_context_parameter(
            cg,
            field_type,
            member->type,
            spec,
            spec->generic_context_type_param_names[index],
            &binding,
            &owned_binding);

        cg_type_ref_free(owned_binding);
        if (!matches) {
            return false;
        }
    }
    return true;
}

/* Match one concrete method against an open or closed spec slot. Open spec
 * parameters are bound consistently across the entire callable signature. */
static bool cg_user_method_matches_spec_member(const CG *cg,
                                               const UserMethod *method,
                                               const UserSpec *spec,
                                               const UserSpecMember *spec_member) {
    if (cg == NULL || method == NULL || spec == NULL || spec_member == NULL ||
        spec_member->kind != USM_KIND_METHOD ||
        method->param_count != spec_member->param_count) {
        return false;
    }
    if (spec->generic_context_type_param_count == 0U) {
        if (!cg_types_equal(spec_member->type, method->return_type)) {
            return false;
        }
        for (size_t index = 0U; index < method->param_count; ++index) {
            if (!cg_types_equal(spec_member->param_types[index],
                                method->param_types[index])) {
                return false;
            }
        }
        return true;
    }
    for (size_t parameter_index = 0U;
         parameter_index < spec->generic_context_type_param_count;
         ++parameter_index) {
        const char *parameter_name =
            spec->generic_context_type_param_names[parameter_index];
        const FengTypeRef *binding = NULL;
        FengTypeRef *owned_binding = NULL;
        bool matches = cg_type_matches_open_spec_context_parameter(
            cg,
            method->return_type,
            spec_member->type,
            spec,
            parameter_name,
            &binding,
            &owned_binding);

        for (size_t param_index = 0U;
             matches && param_index < method->param_count;
             ++param_index) {
            matches = cg_type_matches_open_spec_context_parameter(
                cg,
                method->param_types[param_index],
                spec_member->param_types[param_index],
                spec,
                parameter_name,
                &binding,
                &owned_binding);
        }
        cg_type_ref_free(owned_binding);
        if (!matches) {
            return false;
        }
    }
    return true;
}

/* Match the complete callable shape of one implementation against one exact
 * closed requirement slot. Staticness and variadic shape are part of the
 * method identity even though the shared type-substitution helper above only
 * compares parameter and return types. */
static bool cg_user_method_matches_exact_spec_slot(
    const CG *cg,
    const UserMethod *method,
    const UserSpec *spec,
    const UserSpecMember *slot) {
    bool slot_is_variadic;

    if (method == NULL || method->member == NULL || slot == NULL ||
        slot->kind != USM_KIND_METHOD ||
        method->member->is_static != slot->is_static) {
        return false;
    }
    slot_is_variadic = slot->param_count > 0U &&
        cg_user_spec_member_param_is_variadic(
            slot, slot->param_count - 1U);
    return method->is_variadic == slot_is_variadic &&
           cg_user_method_matches_spec_member(cg, method, spec, slot);
}

/* Verify that a Semantic witness implementation still denotes the current
 * closed Codegen slot. Semantic witness caching is declaration-based, so a
 * generic spec declaration can be observed through multiple closed instances;
 * this compiler-time guard prevents a cached implementation for one closure
 * from being emitted into another closure's witness. */
static bool cg_witness_binding_matches_exact_spec_slot(
    const CG *cg,
    const CGWitnessBinding *binding,
    const UserSpec *spec,
    const UserSpecMember *slot) {
    const CGType *field_type;

    if (binding == NULL || spec == NULL || slot == NULL) {
        return false;
    }
    if (slot->kind == USM_KIND_METHOD) {
        return cg_user_method_matches_exact_spec_slot(
            cg, binding->method, spec, slot);
    }
    field_type = slot->is_static
        ? (binding->static_binding != NULL
               ? binding->static_binding->type
               : NULL)
        : (binding->field != NULL ? binding->field->type : NULL);
    return field_type != NULL &&
           cg_field_type_matches_spec_member(cg,
                                             field_type,
                                             spec,
                                             slot);
}

static bool cg_append_witness_forward_arg(CG *cg,
                                          Buf *out,
                                          const CGType *spec_type,
                                          const CGType *impl_type,
                                          CGCallableABIKind spec_abi_kind,
                                          const char *param_name,
                                          FengToken blame) {
    if (spec_abi_kind == CG_CALLABLE_ABI_ADDRESS && impl_type != NULL) {
        char *cty = cg_ctype_dup(impl_type);
        if (cty == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(out, "*((%s const *)%s)", cty, param_name);
        free(cty);
        return true;
    }
    if (spec_abi_kind == CG_CALLABLE_ABI_ERASED_POINTER && impl_type != NULL) {
        buf_append_cstr(out, "((");
        cg_emit_c_type(out, impl_type);
        buf_append_fmt(out, ")%s)", param_name);
        return true;
    }
    if (spec_type != NULL && spec_type->kind == CG_TYPE_GENERIC_PARAM &&
        impl_type != NULL && impl_type->kind != CG_TYPE_GENERIC_PARAM) {
        char *cty = cg_ctype_dup(impl_type);
        if (cty == NULL) {
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(out, "*((%s const *)%s)", cty, param_name);
        free(cty);
        return true;
    }
    buf_append_cstr(out, param_name);
    return true;
}

/* Open generic managed methods receive their concrete owner descriptor after
 * `self`.  A spec witness already owns the managed subject pointer, so the
 * ordinary object header is the authoritative source of that descriptor. */
static void cg_append_managed_witness_owner_descriptor(Buf *out,
                                                       const UserType *type) {
    if (out != NULL && type != NULL &&
        type->generic_context_type_param_count > 0U) {
        buf_append_cstr(
            out,
            ", ((const FengManagedHeader *)_subject)->desc");
    }
}

/* Match one type-ref against an open generic pattern for a single context
 * parameter. Other context parameters are wildcards during this pass; the
 * caller repeats the walk for every parameter so repeated occurrences must
 * bind consistently without allocating a temporary substitution table. */
static bool cg_type_ref_matches_open_context_parameter(
    const FengTypeRef *actual,
    const FengTypeRef *pattern,
    char *const *context_names,
    size_t context_count,
    const char *parameter_name,
    const FengTypeRef **binding) {
    if (actual == NULL || pattern == NULL || parameter_name == NULL ||
        binding == NULL) {
        return false;
    }
    if (pattern->kind == FENG_TYPE_REF_NAMED &&
        pattern->as.named.segment_count == 1U &&
        pattern->as.named.type_arg_count == 0U) {
        FengSlice name = pattern->as.named.segments[0];

        for (size_t index = 0U; index < context_count; ++index) {
            const char *context_name = context_names[index];

            if (context_name == NULL || strlen(context_name) != name.length ||
                memcmp(context_name, name.data, name.length) != 0) {
                continue;
            }
            if (strcmp(context_name, parameter_name) != 0) {
                return true;
            }
            if (*binding == NULL) {
                *binding = actual;
                return true;
            }
            return cg_type_ref_equal(*binding, actual);
        }
    }
    if (actual->kind != pattern->kind) {
        return false;
    }
    if (pattern->kind == FENG_TYPE_REF_ARRAY &&
        pattern->array_element_writable != actual->array_element_writable) {
        return false;
    }
    if (pattern->kind == FENG_TYPE_REF_POINTER ||
        pattern->kind == FENG_TYPE_REF_ARRAY) {
        return cg_type_ref_matches_open_context_parameter(
            actual->as.inner,
            pattern->as.inner,
            context_names,
            context_count,
            parameter_name,
            binding);
    }
    if (pattern->as.named.segment_count != actual->as.named.segment_count ||
        pattern->as.named.type_arg_count != actual->as.named.type_arg_count) {
        return false;
    }
    for (size_t index = 0U;
         index < pattern->as.named.segment_count;
         ++index) {
        if (!cg_module_segments_equal(&pattern->as.named.segments[index],
                                      1U,
                                      &actual->as.named.segments[index],
                                      1U)) {
            return false;
        }
    }
    for (size_t index = 0U;
         index < pattern->as.named.type_arg_count;
         ++index) {
        if (!cg_type_ref_matches_open_context_parameter(
                actual->as.named.type_args[index],
                pattern->as.named.type_args[index],
                context_names,
                context_count,
                parameter_name,
                binding)) {
            return false;
        }
    }
    return true;
}

/* Return true when a concrete or differently-open instance satisfies the
 * exact structural pattern of an open generic witness target. This is the
 * compile-time substitution performed for generic constraints, not nominal
 * covariance between two concrete generic instances. */
static bool cg_user_spec_matches_open_witness_target(
    const UserSpec *candidate,
    const UserSpec *target) {
    if (candidate == NULL || target == NULL || !candidate->is_generic_instance ||
        !target->is_generic_instance ||
        candidate->generic_origin_decl != target->generic_origin_decl ||
        candidate->generic_type_arg_count != target->generic_type_arg_count ||
        target->generic_context_type_param_count == 0U) {
        return false;
    }
    for (size_t parameter_index = 0U;
         parameter_index < target->generic_context_type_param_count;
         ++parameter_index) {
        const char *parameter_name =
            target->generic_context_type_param_names[parameter_index];
        const FengTypeRef *binding = NULL;

        for (size_t arg_index = 0U;
             arg_index < target->generic_type_arg_count;
             ++arg_index) {
            if (!cg_type_ref_matches_open_context_parameter(
                    candidate->generic_type_args[arg_index],
                    target->generic_type_args[arg_index],
                    target->generic_context_type_param_names,
                    target->generic_context_type_param_count,
                    parameter_name,
                    &binding)) {
                return false;
            }
        }
    }
    return true;
}

/* Return true when `candidate` exactly matches `target`, structurally
 * instantiates its open generic pattern, or names a nominal child whose
 * direct-parent graph reaches it. Concrete generic identities remain exact,
 * so this does not infer variance. */
static bool cg_user_spec_reaches_ancestor(const CG *cg,
                                          const UserSpec *candidate,
                                          const UserSpec *target) {
    if (cg == NULL || candidate == NULL || target == NULL) {
        return false;
    }
    if (candidate == target ||
        cg_user_spec_matches_open_witness_target(candidate, target)) {
        return true;
    }
    for (size_t parent_index = 0U;
         parent_index < candidate->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent =
            cg_user_spec_direct_parent(cg, candidate, parent_index);

        if (cg_user_spec_reaches_ancestor(cg, parent, target)) {
            return true;
        }
    }
    return false;
}

/* Check whether a user fit's declared specs reach one witness target. */
static bool cg_user_fit_targets_spec(const CG *cg,
                                     const UserFit *fit,
                                     const UserSpec *spec) {
    if (cg == NULL || fit == NULL || spec == NULL) return false;
    for (size_t i = 0; i < fit->spec_count; ++i) {
        if (cg_user_spec_reaches_ancestor(cg, fit->specs[i], spec)) {
            return true;
        }
    }
    return false;
}

/* Check whether a builtin fit's declared specs reach one witness target. */
static bool cg_builtin_fit_targets_spec(const CG *cg,
                                        const BuiltinFit *fit,
                                        const UserSpec *spec) {
    if (cg == NULL || fit == NULL || spec == NULL) return false;
    for (size_t i = 0; i < fit->spec_count; ++i) {
        if (cg_user_spec_reaches_ancestor(cg, fit->specs[i], spec)) {
            return true;
        }
    }
    return false;
}

static bool cg_builtin_fit_matches_subject(const BuiltinFit *fit,
                                          CGTypeKind subject_kind,
                                          const FengDecl *enum_decl) {
    if (fit == NULL || fit->target_type == NULL || fit->target_type->kind != subject_kind) {
        return false;
    }
    if (enum_decl != NULL) {
        return fit->target_type->enum_decl == enum_decl;
    }
    return fit->target_type->enum_decl == NULL;
}

/* Resolve one non-user subject implementation from the exact closed spec
 * slot. This is used when multiple closed requirements share one generic AST
 * declaration and Semantic's declaration identity alone is therefore not a
 * unique key. The scan is compiler-only; emitted witnesses retain direct
 * function pointers and perform no runtime lookup. */
static size_t cg_find_builtin_fit_method_for_spec_slot(
    const CG *cg,
    CGTypeKind subject_kind,
    const FengDecl *enum_decl,
    const UserSpec *spec,
    const UserSpecMember *slot,
    const BuiltinFit **out_fit,
    const UserMethod **out_method) {
    size_t match_count = 0U;

    if (out_fit != NULL) {
        *out_fit = NULL;
    }
    if (out_method != NULL) {
        *out_method = NULL;
    }
    if (cg == NULL || spec == NULL || slot == NULL) {
        return 0U;
    }
    for (size_t fit_index = 0U;
         fit_index < cg->builtin_fit_count;
         ++fit_index) {
        const BuiltinFit *candidate_fit = &cg->builtin_fits[fit_index];

        if (!cg_builtin_fit_matches_subject(candidate_fit,
                                            subject_kind,
                                            enum_decl) ||
            !cg_builtin_fit_targets_spec(cg, candidate_fit, spec)) {
            continue;
        }
        for (size_t method_index = 0U;
             method_index < candidate_fit->method_count;
             ++method_index) {
            const UserMethod *candidate_method =
                &candidate_fit->methods[method_index];

            if (candidate_method->member == NULL ||
                strcmp(candidate_method->feng_name, slot->feng_name) != 0 ||
                !cg_user_method_matches_exact_spec_slot(cg,
                                                        candidate_method,
                                                        spec,
                                                        slot)) {
                continue;
            }
            if (out_fit != NULL) {
                *out_fit = candidate_fit;
            }
            if (out_method != NULL) {
                *out_method = candidate_method;
            }
            ++match_count;
        }
    }
    return match_count;
}

static bool cg_subject_key_to_target_kind(const FengSemanticSubjectKey *subject_key,
                                          CGTypeKind *out_kind) {
    if (subject_key == NULL || out_kind == NULL) {
        return false;
    }
    if (subject_key->kind == FENG_SEMANTIC_SUBJECT_KEY_ARRAY) {
        *out_kind = CG_TYPE_ARRAY;
        return true;
    }
    if (subject_key->kind != FENG_SEMANTIC_SUBJECT_KEY_BUILTIN ||
        subject_key->as.builtin_canonical_name == NULL) {
        return false;
    }

    const char *name = subject_key->as.builtin_canonical_name;
    if (strcmp(name, "bool") == 0) { *out_kind = CG_TYPE_BOOL; return true; }
    if (strcmp(name, "i8") == 0) { *out_kind = CG_TYPE_I8; return true; }
    if (strcmp(name, "i16") == 0) { *out_kind = CG_TYPE_I16; return true; }
    if (strcmp(name, "i32") == 0) { *out_kind = CG_TYPE_I32; return true; }
    if (strcmp(name, "i64") == 0) { *out_kind = CG_TYPE_I64; return true; }
    if (strcmp(name, "u8") == 0) { *out_kind = CG_TYPE_U8; return true; }
    if (strcmp(name, "u16") == 0) { *out_kind = CG_TYPE_U16; return true; }
    if (strcmp(name, "u32") == 0) { *out_kind = CG_TYPE_U32; return true; }
    if (strcmp(name, "u64") == 0) { *out_kind = CG_TYPE_U64; return true; }
    if (strcmp(name, "f32") == 0) { *out_kind = CG_TYPE_F32; return true; }
    if (strcmp(name, "f64") == 0) { *out_kind = CG_TYPE_F64; return true; }
    if (strcmp(name, "string") == 0) { *out_kind = CG_TYPE_STRING; return true; }
    return false;
}

static bool cg_emit_scalar_subject_load(CG *cg,
                                        Buf *out,
                                        CGTypeKind subject_kind,
                                        const FengDecl *enum_decl,
                                        FengSpecObjectSubjectStorageKind storage,
                                        FengToken blame,
                                        const char *value_name) {
    if (cg == NULL || out == NULL || value_name == NULL) {
        return false;
    }
    const char *self_cty = cgtype_to_c(subject_kind);
    if (self_cty == NULL) {
        return cg_fail(cg, blame, "CE0310", "codegen: invalid scalar subject key");
    }
    if (storage == FENG_SPEC_OBJECT_SUBJECT_STORAGE_BORROW_LOCAL) {
        buf_append_fmt(out,
            "    %s %s = *(const %s *)_subject;\n",
            self_cty,
            value_name,
            self_cty);
        return true;
    }
    if (storage == FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER) {
        CGType subject_type;
        CGValueBoxInfo box_info;

        memset(&subject_type, 0, sizeof(subject_type));
        subject_type.kind = subject_kind;
        subject_type.enum_decl = enum_decl;
        if (!cg_value_box_info_for_type(cg,
                                        &subject_type,
                                        blame,
                                        &box_info)) {
            return false;
        }
        buf_append_fmt(out,
            "    %s %s = ((const struct %s *)_subject)->value;\n",
            self_cty,
            value_name,
            box_info.struct_name);
        cg_value_box_info_dispose(&box_info);
        return true;
    }
    return cg_fail(cg, blame, "CE0311", "codegen: invalid scalar subject storage kind");
}

static bool cg_emit_ref_subject_load(CG *cg,
                                     Buf *out,
                                     const CGType *target_type,
                                     FengToken blame,
                                     const char *value_name) {
    if (cg == NULL || out == NULL || target_type == NULL || value_name == NULL) {
        return false;
    }
    char *self_cty = cg_ctype_dup(target_type);
    if (self_cty == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    buf_append_fmt(out,
                   "    %s %s = (%s)_subject;\n",
                   self_cty,
                   value_name,
                   self_cty);
    free(self_cty);
    return true;
}

static bool cg_user_spec_member_compatible(const UserSpecMember *src,
                                           const UserSpecMember *dst) {
    if (src == NULL || dst == NULL || src->kind != dst->kind ||
        src->is_static != dst->is_static) {
        return false;
    }
    if (src->kind == USM_KIND_FIELD) {
        return cg_types_equal(src->type, dst->type) &&
               cg_spec_field_uses_storage_borrow(src) ==
                   cg_spec_field_uses_storage_borrow(dst) &&
               (!dst->is_var || src->is_var);
    }
    if (src->param_count != dst->param_count ||
        !cg_types_equal(src->type, dst->type)) {
        return false;
    }
    for (size_t i = 0; i < src->param_count; ++i) {
        if (!cg_types_equal(src->param_types[i], dst->param_types[i])) {
            return false;
        }
    }
    return true;
}

static bool cg_user_spec_witness_prefix_compatible(const UserSpec *src,
                                                   const UserSpec *dst) {
    if (src == NULL || dst == NULL || src->form != dst->form) {
        return false;
    }
    if (src == dst) {
        return true;
    }
    if (src->decl != NULL && src->decl == dst->decl) {
        return true;
    }
    if (src->form == FENG_SPEC_FORM_CALLABLE) {
        if (src->callable_param_count != dst->callable_param_count ||
            src->callable_is_variadic != dst->callable_is_variadic ||
            !cg_types_equal(src->callable_return_type, dst->callable_return_type)) {
            return false;
        }
        for (size_t i = 0; i < src->callable_param_count; ++i) {
            if (!cg_types_equal(src->callable_param_types[i], dst->callable_param_types[i])) {
                return false;
            }
        }
        return true;
    }
    if (src->member_count < dst->member_count) {
        return false;
    }
    for (size_t i = 0; i < dst->member_count; ++i) {
        if (!cg_user_spec_member_compatible(&src->members[i], &dst->members[i])) {
            return false;
        }
    }
    return true;
}

static bool cg_ensure_spec_slot_witness(CG *cg, const UserSpec *src,
                                        const UserSpec *dst, FengToken blame,
                                        const char **out_var) {
    const char *cached = cg_spec_slot_witness_lookup(cg, src, dst);

    if (cached != NULL) {
        *out_var = cached;
        return true;
    }
    if (cg == NULL || src == NULL || dst == NULL) {
        return false;
    }

    Buf var; buf_init(&var);
    buf_append_fmt(&var, "FengSpecSlotWitness__%zu", cg->spec_slot_witness_counter++);
    if (var.data == NULL) {
        return false;
    }
    if (src->form != dst->form) {
        buf_free(&var);
        return cg_fail(cg, blame,
            "CE0312", "codegen: spec value '%s' cannot satisfy generic constraint spec '%s' through mismatched spec forms",
            src->feng_name, dst->feng_name);
    }

    Buf *wd = &cg->witness_defs;
    buf_append_fmt(&cg->headers, "static const struct %s %s;\n",
                   dst->c_witness_struct_name, var.data);
    if (src->form == FENG_SPEC_FORM_CALLABLE) {
        if (src->callable_param_count != dst->callable_param_count ||
            src->callable_is_variadic != dst->callable_is_variadic ||
            !cg_types_equal(src->callable_return_type, dst->callable_return_type)) {
            buf_free(&var);
            return cg_fail(cg, blame,
                "CE0313", "codegen: spec value '%s' cannot satisfy generic constraint spec '%s' through callable slot witness adaptation",
                src->feng_name, dst->feng_name);
        }
        for (size_t i = 0; i < dst->callable_param_count; ++i) {
            if (!cg_types_equal(src->callable_param_types[i], dst->callable_param_types[i])) {
                buf_free(&var);
                return cg_fail(cg, blame,
                    "CE0313", "codegen: spec value '%s' cannot satisfy generic constraint spec '%s' through callable slot witness adaptation",
                    src->feng_name, dst->feng_name);
            }
        }

        buf_append_cstr(wd, "static void ");
        buf_append_fmt(wd, "%s__invoke(const void *_callee", var.data);
        for (size_t i = 0; i < dst->callable_param_count; ++i) {
            buf_append_fmt(wd, ", const void *_arg%zu", i);
        }
        buf_append_cstr(wd, ", void *_out) {\n");
        buf_append_fmt(wd,
            "    const struct %s *_value = (const struct %s *)_callee;\n"
            "    ",
            src->c_closure_struct_name,
            src->c_closure_struct_name);
        if (dst->callable_return_type->kind != CG_TYPE_VOID &&
            src->callable_return_abi_kind != CG_CALLABLE_ABI_ADDRESS) {
            char *ret_cty = cg_ctype_dup(dst->callable_return_type);

            if (ret_cty == NULL) {
                buf_free(&var);
                return false;
            }
            buf_append_fmt(wd, "*((%s *)_out) = ", ret_cty);
            free(ret_cty);
        } else if (dst->callable_return_type->kind == CG_TYPE_VOID) {
            buf_append_cstr(wd, "(void)_out;\n    ");
        }
        buf_append_fmt(wd, "_value->invoke((void *)_value");
        for (size_t i = 0; i < dst->callable_param_count; ++i) {
            char argument_name[32];

            (void)snprintf(argument_name, sizeof argument_name, "_arg%zu", i);
            buf_append_cstr(wd, ", ");
            cg_append_callable_abi_bridge_argument(
                wd,
                src->callable_param_types[i],
                CG_CALLABLE_ABI_ADDRESS,
                src->callable_param_abi_kinds[i],
                argument_name);
        }
        if (src->callable_return_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(wd, ", _out");
        }
        buf_append_cstr(wd, ");\n}\n");
        buf_append_fmt(wd, "static const struct %s %s = {\n",
                       dst->c_witness_struct_name, var.data);
        buf_append_fmt(wd, "    .invoke = &%s__invoke,\n", var.data);
        buf_append_cstr(wd, "};\n\n");
    } else {
        for (size_t i = 0; i < dst->member_count; ++i) {
            const UserSpecMember *dst_member = &dst->members[i];
            const UserSpecMember *src_member = cg_user_spec_member_matching_slot(
                src, dst_member);

            if (src_member == NULL &&
                dst_member->kind != USM_KIND_METHOD) {
                src_member = cg_user_spec_field_member(
                    src,
                    dst_member->feng_name,
                    strlen(dst_member->feng_name),
                    dst_member->is_static);
            }

            if (src_member == NULL ||
                !cg_user_spec_member_compatible(src_member, dst_member)) {
                buf_free(&var);
                return cg_fail(cg, blame,
                    "CE0314", "codegen: spec value '%s' cannot satisfy generic constraint spec '%s' through slot witness adaptation",
                    src->feng_name, dst->feng_name);
            }

            if (dst_member->kind == USM_KIND_FIELD) {
                if (cg_spec_field_uses_storage_borrow(dst_member)) {
                    buf_append_fmt(wd,
                        "static void *%s__borrow_%s(void *_subject) {\n"
                        "    const struct %s *_value = "
                        "(const struct %s *)_subject;\n"
                        "    return _value->witness->borrow_%s"
                        "(_value->subject);\n"
                        "}\n",
                        var.data,
                        dst_member->c_field_name,
                        src->c_value_struct_name,
                        src->c_value_struct_name,
                        src_member->c_field_name);
                } else {
                    buf_append_cstr(wd, "static ");
                    cg_emit_c_type(wd, dst_member->type);
                    buf_append_fmt(wd, " %s__get_%s(void *_subject) {\n",
                                   var.data, dst_member->c_field_name);
                    buf_append_fmt(wd,
                        "    const struct %s *_value = "
                        "(const struct %s *)_subject;\n"
                        "    return _value->witness->get_%s"
                        "(_value->subject);\n"
                        "}\n",
                        src->c_value_struct_name,
                        src->c_value_struct_name,
                        src_member->c_field_name);
                }
                if (dst_member->is_var) {
                    buf_append_fmt(wd, "static void %s__set_%s(void *_subject, ",
                                   var.data, dst_member->c_field_name);
                    cg_emit_c_type(wd, dst_member->type);
                    buf_append_cstr(wd, " value) {\n");
                    buf_append_fmt(wd,
                        "    struct %s *_value = (struct %s *)_subject;\n"
                        "    _value->witness->set_%s(_value->subject, value);\n"
                        "}\n",
                        src->c_value_struct_name,
                        src->c_value_struct_name,
                        src_member->c_field_name);
                }
            } else {
                buf_append_cstr(wd, "static ");
                cg_emit_c_type(wd, dst_member->type);
                buf_append_fmt(wd, " %s__%s(void *_subject",
                               var.data, dst_member->c_field_name);
                for (size_t pi = 0; pi < dst_member->param_count; ++pi) {
                    buf_append_cstr(wd, ", ");
                    cg_emit_c_type(wd, dst_member->param_types[pi]);
                    buf_append_fmt(wd, " _p%zu", pi);
                }
                buf_append_cstr(wd, ") {\n");
                buf_append_fmt(wd,
                    "    const struct %s *_value = (const struct %s *)_subject;\n",
                    src->c_value_struct_name,
                    src->c_value_struct_name);
                buf_append_cstr(wd, "    ");
                if (dst_member->type->kind != CG_TYPE_VOID) {
                    buf_append_cstr(wd, "return ");
                }
                buf_append_fmt(wd, "_value->witness->%s(_value->subject",
                               src_member->c_field_name);
                for (size_t pi = 0; pi < dst_member->param_count; ++pi) {
                    buf_append_fmt(wd, ", _p%zu", pi);
                }
                buf_append_cstr(wd, ");\n}\n");
            }
        }

        const char **parent_witness_vars = NULL;
        if (dst->direct_parent_spec_count > 0U) {
            parent_witness_vars = (const char **)calloc(
                dst->direct_parent_spec_count,
                sizeof(*parent_witness_vars));
            if (parent_witness_vars == NULL) {
                buf_free(&var);
                return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }
        }
        for (size_t parent_index = 0U;
             parent_index < dst->direct_parent_spec_count;
             ++parent_index) {
            const UserSpec *parent_spec =
                cg_user_spec_direct_parent(cg, dst, parent_index);

            if (parent_spec == NULL ||
                !cg_ensure_spec_slot_witness(cg,
                                             src,
                                             parent_spec,
                                             blame,
                                             &parent_witness_vars[parent_index])) {
                free(parent_witness_vars);
                buf_free(&var);
                return false;
            }
        }

        buf_append_fmt(wd, "static const struct %s %s = {\n",
                       dst->c_witness_struct_name, var.data);
        for (size_t i = 0; i < dst->member_count; ++i) {
            const UserSpecMember *dst_member = &dst->members[i];

            if (dst_member->kind == USM_KIND_FIELD) {
                if (cg_spec_field_uses_storage_borrow(dst_member)) {
                    buf_append_fmt(wd,
                                   "    .borrow_%s = &%s__borrow_%s,\n",
                                   dst_member->c_field_name, var.data,
                                   dst_member->c_field_name);
                } else {
                    buf_append_fmt(wd, "    .get_%s = &%s__get_%s,\n",
                                   dst_member->c_field_name, var.data,
                                   dst_member->c_field_name);
                }
                if (dst_member->is_var) {
                    buf_append_fmt(wd, "    .set_%s = &%s__set_%s,\n",
                                   dst_member->c_field_name, var.data,
                                   dst_member->c_field_name);
                }
            } else {
                buf_append_fmt(wd, "    .%s = &%s__%s,\n",
                               dst_member->c_field_name, var.data,
                               dst_member->c_field_name);
            }
        }
        for (size_t parent_index = 0U;
             parent_index < dst->direct_parent_spec_count;
             ++parent_index) {
            const UserSpec *parent_spec =
                cg_user_spec_direct_parent(cg, dst, parent_index);

            buf_append_cstr(wd, "    .");
            cg_append_spec_parent_field_name(wd, parent_spec);
            buf_append_fmt(wd, " = &%s,\n", parent_witness_vars[parent_index]);
        }
        buf_append_cstr(wd, "};\n\n");
        free(parent_witness_vars);
    }

    if (cg->spec_slot_witness_table_count + 1 > cg->spec_slot_witness_table_capacity) {
        size_t cap = cg->spec_slot_witness_table_capacity
                         ? cg->spec_slot_witness_table_capacity * 2
                         : 4;
        void *p = realloc(cg->spec_slot_witness_tables,
                          cap * sizeof *cg->spec_slot_witness_tables);

        if (p == NULL) {
            buf_free(&var);
            return false;
        }
        cg->spec_slot_witness_tables = p;
        cg->spec_slot_witness_table_capacity = cap;
    }

    cg->spec_slot_witness_tables[cg->spec_slot_witness_table_count].src = src;
    cg->spec_slot_witness_tables[cg->spec_slot_witness_table_count].dst = dst;
    cg->spec_slot_witness_tables[cg->spec_slot_witness_table_count].c_var = var.data;
    *out_var = var.data;
    cg->spec_slot_witness_table_count++;
    return true;
}

static bool cg_resolve_witness_binding_fallback(CG *cg,
                                                const UserType *t,
                                                const UserSpec *s,
                                                const UserSpecMember *sm,
                                                FengToken blame,
                                                CGWitnessBinding *out) {
    size_t fit_match_count = 0U;
    size_t type_match_count = 0U;

    memset(out, 0, sizeof *out);
    if (sm->kind == USM_KIND_FIELD) {
        if (sm->is_static) {
            /* Static fields are stored as type-level bindings and can only
             * come from the type itself (fit cannot declare static let/var). */
            const TypeStaticBinding *sb = cg_user_type_static_binding(
                t, sm->feng_name, strlen(sm->feng_name));
            if (sb == NULL) {
                return cg_fail(cg, blame,
                    "CE0315", "codegen: type '%s' is missing an implementation for spec '%s' member '%s'",
                    t->feng_name, s->feng_name, sm->feng_name);
            }
            if (!cg_field_type_matches_spec_member(cg, sb->type, s, sm)) {
                return cg_fail(cg, blame,
                    "CE0316", "codegen: field '%s' on type '%s' does not match spec '%s' field type",
                    sm->feng_name, t->feng_name, s->feng_name);
            }
            out->source_kind = FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_FIELD;
            out->static_binding = sb;
            return true;
        }
        const UserField *field = cg_user_type_field(t, sm->feng_name,
                                                    strlen(sm->feng_name));

        if (field == NULL) {
            return cg_fail(cg, blame,
                "CE0315", "codegen: type '%s' is missing an implementation for spec '%s' member '%s'",
                t->feng_name, s->feng_name, sm->feng_name);
        }
        if (!cg_field_type_matches_spec_member(cg, field->type, s, sm)) {
            return cg_fail(cg, blame,
                "CE0316", "codegen: field '%s' on type '%s' does not match spec '%s' field type",
                sm->feng_name, t->feng_name, s->feng_name);
        }
        out->source_kind = FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_FIELD;
        out->field = field;
        return true;
    }

    if (sm->is_static) {
        /* Static methods: scan the type's static method table and any
         * visible fits targeting T. */
        for (size_t i = 0; i < t->static_method_count; ++i) {
            const UserMethod *candidate = &t->static_methods[i];

            if (strcmp(candidate->feng_name, sm->feng_name) != 0 ||
                !cg_user_method_matches_spec_member(cg, candidate, s, sm)) {
                continue;
            }
            out->method = candidate;
            ++type_match_count;
        }

        for (size_t fit_index = 0; fit_index < cg->user_fit_count; ++fit_index) {
            const UserFit *fit = &cg->user_fits[fit_index];

            if (fit->target != t || !cg_user_fit_targets_spec(cg, fit, s)) {
                continue;
            }
            if (cg->cur_program != NULL && fit->owner_program != NULL &&
                !cg_program_can_see(cg, cg->cur_program, fit->owner_program)) {
                continue;
            }
            for (size_t method_index = 0; method_index < fit->method_count; ++method_index) {
                const UserMethod *candidate = &fit->methods[method_index];

                /* fit bodies may mix instance and static methods; only static
                 * methods can satisfy spec static method slots. */
                if (candidate->member == NULL || !candidate->member->is_static) {
                    continue;
                }
                if (strcmp(candidate->feng_name, sm->feng_name) != 0 ||
                    !cg_user_method_matches_spec_member(cg, candidate, s, sm)) {
                    continue;
                }
                out->fit = fit;
                out->method = candidate;
                ++fit_match_count;
            }
        }

        if (type_match_count + fit_match_count == 0U) {
            return cg_fail(cg, blame,
                "CE0315", "codegen: type '%s' is missing an implementation for spec '%s' member '%s'",
                t->feng_name, s->feng_name, sm->feng_name);
        }
        if (type_match_count + fit_match_count > 1U) {
            return cg_fail(cg, blame,
                "CE0317", "codegen: type '%s' has multiple visible implementations of method '%s' required by spec '%s' (one or more fits and/or the type itself)",
                t->feng_name, sm->feng_name, s->feng_name);
        }
        if (type_match_count == 1U) {
            out->source_kind = FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD;
            out->fit = NULL;
            return true;
        }
        out->source_kind = FENG_SPEC_WITNESS_SOURCE_FIT_METHOD;
        return true;
    }

    for (size_t i = 0; i < t->method_count; ++i) {
        const UserMethod *candidate = &t->methods[i];

        if (strcmp(candidate->feng_name, sm->feng_name) != 0 ||
            !cg_user_method_matches_spec_member(cg, candidate, s, sm)) {
            continue;
        }
        out->method = candidate;
        ++type_match_count;
    }

    for (size_t fit_index = 0; fit_index < cg->user_fit_count; ++fit_index) {
        const UserFit *fit = &cg->user_fits[fit_index];

        if (fit->target != t || !cg_user_fit_targets_spec(cg, fit, s)) {
            continue;
        }
        if (cg->cur_program != NULL && fit->owner_program != NULL &&
            !cg_program_can_see(cg, cg->cur_program, fit->owner_program)) {
            continue;
        }
        for (size_t method_index = 0; method_index < fit->method_count; ++method_index) {
            const UserMethod *candidate = &fit->methods[method_index];

            if (strcmp(candidate->feng_name, sm->feng_name) != 0 ||
                !cg_user_method_matches_spec_member(cg, candidate, s, sm)) {
                continue;
            }
            out->fit = fit;
            out->method = candidate;
            ++fit_match_count;
        }
    }

    if (type_match_count + fit_match_count == 0U) {
        return cg_fail(cg, blame,
            "CE0315", "codegen: type '%s' is missing an implementation for spec '%s' member '%s'",
            t->feng_name, s->feng_name, sm->feng_name);
    }
    if (type_match_count + fit_match_count > 1U) {
        return cg_fail(cg, blame,
            "CE0317", "codegen: type '%s' has multiple visible implementations of method '%s' required by spec '%s' (one or more fits and/or the type itself)",
            t->feng_name, sm->feng_name, s->feng_name);
    }
    if (type_match_count == 1U) {
        out->source_kind = FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD;
        out->fit = NULL;
        return true;
    }

    out->source_kind = FENG_SPEC_WITNESS_SOURCE_FIT_METHOD;
    return true;
}

/* Materialize one intersection-form witness by aliasing every merged slot to
 * the corresponding leaf object-form witness slot. Exactly one subject
 * representation is supplied: user_type for registered user types, otherwise
 * subject_key for enum/builtin/array subjects. The emitted witness is a static
 * compiler artifact; it adds no runtime lookup, thunk, or descriptor field. */
static bool cg_ensure_intersection_witness_instance(
    CG *cg,
    const UserType *user_type,
    const FengSemanticSubjectKey *subject_key,
    const UserSpec *intersection_spec,
    FengSpecObjectSubjectStorageKind scalar_subject_storage,
    FengToken blame,
    const char **out_var) {
    const char *spec_unique_name;
    char *spec_sanitized = NULL;
    Buf var;
    const char **member_witness_vars = NULL;
    bool saved_in_generic_fn;
    size_t saved_type_param_count;
    char **saved_type_param_names;
    const UserSpec **saved_type_param_constraints;
    const char **saved_type_param_descriptors;
    const FengSemanticSubjectKey *effective_subject_key = subject_key;
    bool ok = true;

    if (cg == NULL || intersection_spec == NULL || out_var == NULL ||
        intersection_spec->form != FENG_SPEC_FORM_INTERSECTION ||
        ((user_type == NULL) == (subject_key == NULL))) {
        return false;
    }

    spec_unique_name =
        intersection_spec->generic_context_type_param_count > 0U &&
                intersection_spec->c_aggregate_desc_name != NULL
            ? intersection_spec->c_aggregate_desc_name
            : intersection_spec->feng_name;
    spec_sanitized = cg_sanitize(spec_unique_name, strlen(spec_unique_name));
    if (spec_sanitized == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_init(&var);
    if (user_type != NULL) {
        char *type_sanitized =
            cg_sanitize(user_type->feng_name, strlen(user_type->feng_name));

        if (type_sanitized == NULL) {
            free(spec_sanitized);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(&var,
                       "FengSpecWitness__%s__%s__as__%s__%s",
                       cg->module_mangle,
                       type_sanitized,
                       cg->module_mangle,
                       spec_sanitized);
        free(type_sanitized);
    } else {
        const size_t witness_id = cg->subject_witness_counter++;

        buf_append_fmt(&var,
                       "FengWitness__%s__subject_%zu__as__%s__%s",
                       cg->module_mangle,
                       witness_id,
                       cg->module_mangle,
                       spec_sanitized);
    }
    free(spec_sanitized);
    if (var.data == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    /* Declare the merged constant before recursively materializing leaves so
     * descriptors may refer to it independent of emission order. */
    buf_append_fmt(&cg->headers,
                   "static const struct %s %s;\n",
                   intersection_spec->c_witness_struct_name,
                   var.data);

    if (intersection_spec->member_count > 0U) {
        member_witness_vars = (const char **)calloc(
            intersection_spec->member_count,
            sizeof(*member_witness_vars));
        if (member_witness_vars == NULL) {
            buf_free(&var);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }

    /* Open generic intersection instances carry substituted leaf refs. Make
     * their own type-parameter names active while resolving those refs, then
     * restore the caller context before emitting or returning. */
    saved_in_generic_fn = cg->in_generic_fn;
    saved_type_param_count = cg->generic_fn_type_param_count;
    saved_type_param_names = cg->generic_fn_type_param_names;
    saved_type_param_constraints = cg->generic_fn_type_param_constraints;
    saved_type_param_descriptors = cg->generic_fn_type_param_descs;
    if (intersection_spec->generic_context_type_param_count > 0U) {
        cg->in_generic_fn = true;
        cg->generic_fn_type_param_count =
            intersection_spec->generic_context_type_param_count;
        cg->generic_fn_type_param_names =
            intersection_spec->generic_context_type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = NULL;
    }

    for (size_t index = 0U;
         index < intersection_spec->member_count;
         ++index) {
        const UserSpecMember *member = &intersection_spec->members[index];
        const UserSpec *leaf_spec = NULL;
        const char *leaf_witness_var = NULL;

        if ((member->source_member_decl == NULL &&
             member->source_member_type_ref == NULL) ||
            member->source_c_field_name == NULL) {
            ok = cg_fail(
                cg,
                blame,
                "CE0357",
                "codegen: intersection-form spec member '%s' is missing source witness metadata",
                member->feng_name);
            break;
        }

        if (member->source_member_type_ref != NULL) {
            CGType *leaf_type = NULL;

            if (!cg_resolve_type(cg,
                                 member->source_member_type_ref,
                                 NULL,
                                 &leaf_type)) {
                ok = false;
                break;
            }
            if (leaf_type != NULL &&
                (leaf_type->kind == CG_TYPE_SPEC ||
                 leaf_type->kind == CG_TYPE_CALLABLE)) {
                leaf_spec = leaf_type->user_spec;
            }
            cgtype_free(leaf_type);
        } else {
            leaf_spec =
                cg_find_user_spec_by_decl(cg, member->source_member_decl);
        }
        if (leaf_spec == NULL) {
            ok = cg_fail(
                cg,
                blame,
                "CE0358",
                "codegen: intersection-form spec member source spec not registered");
            break;
        }

        /* Reconstructed array keys own a temporary element type ref. Replace
         * that key with the analysis-owned identity from any leaf witness
         * before recursive emission or cache insertion. */
        if (user_type == NULL &&
            effective_subject_key == subject_key &&
            subject_key->kind == FENG_SEMANTIC_SUBJECT_KEY_ARRAY) {
            const FengSpecWitness *leaf_witness =
                feng_semantic_lookup_spec_witness(cg->analysis,
                                                  subject_key,
                                                  leaf_spec->decl);

            if (leaf_witness == NULL) {
                ok = cg_fail(
                    cg,
                    blame,
                    "CE0329",
                    "codegen: missing semantic leaf witness for intersection-constrained array type argument");
                break;
            }
            effective_subject_key = &leaf_witness->subject_key;
        }

        if (user_type != NULL) {
            ok = cg_ensure_witness_instance_for_type(cg,
                                                     user_type,
                                                     leaf_spec,
                                                     blame,
                                                     &leaf_witness_var);
        } else {
            ok = cg_ensure_witness_instance(cg,
                                            effective_subject_key,
                                            leaf_spec,
                                            scalar_subject_storage,
                                            blame,
                                            &leaf_witness_var);
        }
        if (!ok) {
            break;
        }
        member_witness_vars[index] = leaf_witness_var;
    }

    if (intersection_spec->generic_context_type_param_count > 0U) {
        cg->in_generic_fn = saved_in_generic_fn;
        cg->generic_fn_type_param_count = saved_type_param_count;
        cg->generic_fn_type_param_names = saved_type_param_names;
        cg->generic_fn_type_param_constraints = saved_type_param_constraints;
        cg->generic_fn_type_param_descs = saved_type_param_descriptors;
    }
    if (!ok) {
        free((void *)member_witness_vars);
        buf_free(&var);
        return false;
    }

    /* All source witness variables are cache-owned and stable. The merged
     * initializer therefore aliases their existing slots without new thunks. */
    buf_append_fmt(&cg->witness_defs,
                   "static const struct %s %s = {\n",
                   intersection_spec->c_witness_struct_name,
                   var.data);
    for (size_t index = 0U;
         index < intersection_spec->member_count;
         ++index) {
        const UserSpecMember *member = &intersection_spec->members[index];
        const char *leaf_witness_var = member_witness_vars[index];

        if (member->kind == USM_KIND_FIELD) {
            if (cg_spec_field_uses_storage_borrow(member)) {
                buf_append_fmt(&cg->witness_defs,
                               "    .borrow_%s = %s.borrow_%s,\n",
                               member->c_field_name,
                               leaf_witness_var,
                               member->source_c_field_name);
            } else {
                buf_append_fmt(&cg->witness_defs,
                               "    .get_%s = %s.get_%s,\n",
                               member->c_field_name,
                               leaf_witness_var,
                               member->source_c_field_name);
            }
            if (member->is_var) {
                buf_append_fmt(&cg->witness_defs,
                               "    .set_%s = %s.set_%s,\n",
                               member->c_field_name,
                               leaf_witness_var,
                               member->source_c_field_name);
            }
        } else {
            buf_append_fmt(&cg->witness_defs,
                           "    .%s = %s.%s,\n",
                           member->c_field_name,
                           leaf_witness_var,
                           member->source_c_field_name);
        }
    }
    buf_append_cstr(&cg->witness_defs, "};\n\n");
    free((void *)member_witness_vars);

    if (user_type != NULL) {
        if (cg->witness_table_count == cg->witness_table_capacity) {
            const size_t new_capacity =
                cg->witness_table_capacity == 0U
                    ? 4U
                    : cg->witness_table_capacity * 2U;
            void *grown = realloc(cg->witness_tables,
                                  new_capacity * sizeof(*cg->witness_tables));

            if (grown == NULL) {
                buf_free(&var);
                return cg_fail(cg,
                               blame,
                               "IE0001",
                               "codegen: out of memory");
            }
            cg->witness_tables = grown;
            cg->witness_table_capacity = new_capacity;
        }
        cg->witness_tables[cg->witness_table_count].t = user_type;
        cg->witness_tables[cg->witness_table_count].s = intersection_spec;
        cg->witness_tables[cg->witness_table_count].c_var = var.data;
        cg->witness_table_count++;
    } else if (!cg_subject_witness_table_add(cg,
                                              effective_subject_key,
                                              scalar_subject_storage,
                                              intersection_spec,
                                              var.data)) {
        buf_free(&var);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    *out_var = var.data;
    return true;
}

static bool cg_ensure_witness_instance(
    CG *cg,
    const FengSemanticSubjectKey *subject_key,
    const UserSpec *s,
    FengSpecObjectSubjectStorageKind scalar_subject_storage,
    FengToken blame,
    const char **out_var) {
    if (cg == NULL || subject_key == NULL || s == NULL || out_var == NULL) {
        return false;
    }
    if (subject_key->kind != FENG_SEMANTIC_SUBJECT_KEY_TYPE_DECL ||
        subject_key->as.type_decl == NULL ||
        subject_key->as.type_decl->kind == FENG_DECL_ENUM) {
        const char *cached = cg_subject_witness_table_lookup(
            cg, subject_key, scalar_subject_storage, s);

        if (cached != NULL) {
            *out_var = cached;
            return true;
        }
    }
    if (s->form == FENG_SPEC_FORM_INTERSECTION &&
        (subject_key->kind != FENG_SEMANTIC_SUBJECT_KEY_TYPE_DECL ||
         subject_key->as.type_decl == NULL ||
         subject_key->as.type_decl->kind == FENG_DECL_ENUM)) {
        return cg_ensure_intersection_witness_instance(cg,
                                                       NULL,
                                                       subject_key,
                                                       s,
                                                       scalar_subject_storage,
                                                       blame,
                                                       out_var);
    }
    if (subject_key->kind == FENG_SEMANTIC_SUBJECT_KEY_TYPE_DECL) {
        if (subject_key->as.type_decl != NULL &&
            subject_key->as.type_decl->kind == FENG_DECL_ENUM) {
            const FengDecl *enum_decl = subject_key->as.type_decl;
            const FengSpecWitness *witness = NULL;
            const size_t witness_id = cg->subject_witness_counter++;
            const char *spec_unique_name =
                (s->generic_context_type_param_count > 0U && s->c_aggregate_desc_name)
                    ? s->c_aggregate_desc_name
                    : s->feng_name;
            char *s_san = NULL;
            Buf prefix;

            witness = feng_semantic_lookup_spec_witness(cg->analysis, subject_key, s->decl);

            s_san = cg_sanitize(spec_unique_name, strlen(spec_unique_name));
            if (s_san == NULL) {
                return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }

            buf_init(&prefix);
            buf_append_fmt(&prefix, "FengSpecThunk__%s__subject_%zu__as__%s__%s",
                           cg->module_mangle, witness_id, cg->module_mangle, s_san);
            if (prefix.data == NULL) {
                free(s_san);
                return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
            }

            for (size_t i = 0U; i < s->member_count; ++i) {
                const UserSpecMember *sm = &s->members[i];
                const FengSpecWitnessMember *wm = NULL;
                const BuiltinFit *bf = NULL;
                const UserMethod *fm = NULL;
                size_t fallback_match_count = 0U;
                bool witness_mapping_ambiguous = false;
                bool use_semantic_witness = witness != NULL;

                if (witness != NULL) {
                    wm = cg_spec_witness_member_for_slot(
                        witness, sm, &witness_mapping_ambiguous);
                    if (witness_mapping_ambiguous) {
                        use_semantic_witness = false;
                    } else if (wm == NULL) {
                        buf_free(&prefix);
                        free(s_san);
                        return cg_fail(cg, blame,
                            "CE0318", "codegen: internal: witness requirement mapping is missing for non-type subject '%.*s' as spec '%s' member '%s'",
                            (int)subject_key->as.type_decl->as.enum_decl.name.length,
                            subject_key->as.type_decl->as.enum_decl.name.data,
                            s->feng_name,
                            sm->feng_name);
                    }
                }
                if (use_semantic_witness) {
                    if (wm->impl_member == NULL) {
                        buf_free(&prefix);
                        free(s_san);
                        return cg_fail(cg, blame,
                            "CE0319", "codegen: missing implementation for spec member '%s'", sm->feng_name);
                    }
                    if (sm->kind != USM_KIND_METHOD ||
                        wm->source_kind != FENG_SPEC_WITNESS_SOURCE_FIT_METHOD ||
                        wm->via_fit_decl == NULL) {
                        buf_free(&prefix);
                        free(s_san);
                        return cg_fail(cg, blame,
                            "CE0320", "codegen: non-type subject key currently supports fit-method spec members only");
                    }

                    bf = cg_find_builtin_fit_by_decl(cg, wm->via_fit_decl);
                    if (bf != NULL &&
                        !cg_builtin_fit_matches_subject(bf, CG_TYPE_I32, enum_decl)) {
                        bf = NULL;
                    }
                    if (bf != NULL) {
                        fm = cg_builtin_fit_method_by_member(bf, wm->impl_member);
                        if (fm == NULL) {
                            fm = cg_builtin_fit_method(bf, sm->feng_name,
                                                       strlen(sm->feng_name));
                        }
                    }
                }
                if (bf == NULL && use_semantic_witness) {
                    for (size_t bi = 0U; bi < cg->builtin_fit_count; ++bi) {
                        const BuiltinFit *candidate = &cg->builtin_fits[bi];
                        const UserMethod *candidate_method = NULL;

                        if (!cg_builtin_fit_matches_subject(candidate, CG_TYPE_I32, enum_decl) ||
                            !cg_builtin_fit_targets_spec(cg, candidate, s)) {
                            continue;
                        }
                        candidate_method =
                            cg_builtin_fit_method_by_member(candidate, wm->impl_member);
                        if (candidate_method == NULL) {
                            candidate_method = cg_builtin_fit_method(candidate,
                                                                     sm->feng_name,
                                                                     strlen(sm->feng_name));
                        }
                        if (candidate_method != NULL) {
                            bf = candidate;
                            fm = candidate_method;
                            break;
                        }
                    }
                }
                if (!use_semantic_witness ||
                    !cg_user_method_matches_exact_spec_slot(
                        cg, fm, s, sm)) {
                    if (sm->kind != USM_KIND_METHOD) {
                        buf_free(&prefix);
                        free(s_san);
                        return cg_fail(cg, blame,
                            "CE0321", "codegen: enum '%.*s' cannot satisfy spec field '%s' without field support",
                            (int)enum_decl->as.enum_decl.name.length,
                            enum_decl->as.enum_decl.name.data,
                            sm->feng_name);
                    }

                    fallback_match_count =
                        cg_find_builtin_fit_method_for_spec_slot(
                            cg,
                            CG_TYPE_I32,
                            enum_decl,
                            s,
                            sm,
                            &bf,
                            &fm);

                    if (fallback_match_count == 0U) {
                        buf_free(&prefix);
                        free(s_san);
                        return cg_fail(cg, blame,
                            "CE0322", "codegen: enum '%.*s' is missing an implementation for spec '%s' member '%s'",
                            (int)enum_decl->as.enum_decl.name.length,
                            enum_decl->as.enum_decl.name.data,
                            s->feng_name,
                            sm->feng_name);
                    }
                    if (fallback_match_count > 1U) {
                        buf_free(&prefix);
                        free(s_san);
                        return cg_fail(cg, blame,
                            "CE0323", "codegen: enum '%.*s' has multiple visible implementations of method '%s' required by spec '%s'",
                            (int)enum_decl->as.enum_decl.name.length,
                            enum_decl->as.enum_decl.name.data,
                            sm->feng_name,
                            s->feng_name);
                    }
                }
                if (bf == NULL || !cg_builtin_fit_targets_spec(cg, bf, s) ||
                    !cg_builtin_fit_matches_subject(bf, CG_TYPE_I32, enum_decl)) {
                    buf_free(&prefix);
                    free(s_san);
                    return cg_fail(cg, blame,
                        "CE0324", "codegen: fit implementation does not match object-form spec coercion source");
                }
                if (fm == NULL) {
                    buf_free(&prefix);
                    free(s_san);
                    return cg_fail(cg, blame,
                        "CE0325", "codegen: fit method '%s' was not registered", sm->feng_name);
                }

                if (sm->is_static) {
                    if (!cg_emit_static_spec_method_thunk(cg,
                                                          s,
                                                          sm,
                                                          fm,
                                                          bf,
                                                          prefix.data,
                                                          blame)) {
                        buf_free(&prefix);
                        free(s_san);
                        return false;
                    }
                    continue;
                }

            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                    Buf *fp = &cg->fn_protos;
                    Buf *fd = &cg->witness_defs;

                    buf_append_fmt(fp, "static void %s__%s(void *_subject",
                                   prefix.data, sm->c_field_name);
                    for (size_t pi = 0; pi < sm->param_count; ++pi) {
                        buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                        buf_append_fmt(fp, " p%zu", pi);
                    }
                    buf_append_cstr(fp, ", void *_out);\n");

                    buf_append_fmt(fd, "static void %s__%s(void *_subject",
                                   prefix.data, sm->c_field_name);
                    for (size_t pi = 0; pi < sm->param_count; ++pi) {
                        buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                        buf_append_fmt(fd, " p%zu", pi);
                    }
                    buf_append_cstr(fd, ", void *_out) {\n    ");
                    cg_emit_c_type(fd, fm->return_type);
                    buf_append_cstr(fd, " _ret;\n");
                    if (!cg_emit_scalar_subject_load(cg,
                                                    fd,
                                                    CG_TYPE_I32,
                                                    enum_decl,
                                                    scalar_subject_storage,
                                                    blame,
                                                    "_self_value")) {
                        buf_free(&prefix);
                        free(s_san);
                        return false;
                    }
                    buf_append_fmt(fd,
                        "    _ret = %s(_self_value, "
                        "&(const FengFunctionDescriptor){.name = \"%s\"}",
                        fm->c_name, fm->feng_name);
                    for (size_t pi = 0; pi < sm->param_count; ++pi) {
                        char pname[32];

                        snprintf(pname, sizeof pname, "p%zu", pi);
                        buf_append_cstr(fd, ", ");
                        if (!cg_append_witness_forward_arg(cg,
                                                           fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                           blame)) {
                            buf_free(&prefix);
                            free(s_san);
                            return false;
                        }
                    }
                    buf_append_cstr(fd, ");\n    memcpy(_out, &_ret, sizeof _ret);\n}\n\n");
                    continue;
                }

                {
                    Buf *fp = &cg->fn_protos;
                    Buf *fd = &cg->witness_defs;

                    buf_append_cstr(fp, "static ");
                    cg_emit_c_type(fp, sm->type);
                    buf_append_fmt(fp, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
                    for (size_t pi = 0; pi < sm->param_count; ++pi) {
                        buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                        buf_append_fmt(fp, " p%zu", pi);
                    }
                    buf_append_cstr(fp, ");\n");

                    buf_append_cstr(fd, "static ");
                    cg_emit_c_type(fd, sm->type);
                    buf_append_fmt(fd, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
                    for (size_t pi = 0; pi < sm->param_count; ++pi) {
                        buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                        buf_append_fmt(fd, " p%zu", pi);
                    }
                    buf_append_cstr(fd, ") {\n");
                    if (!cg_emit_scalar_subject_load(cg,
                                                    fd,
                                                    CG_TYPE_I32,
                                                    enum_decl,
                                                    scalar_subject_storage,
                                                    blame,
                                                    "_self_value")) {
                        buf_free(&prefix);
                        free(s_san);
                        return false;
                    }
                    if (sm->type->kind == CG_TYPE_VOID) {
                        buf_append_fmt(fd,
                            "    %s(_self_value, "
                            "&(const FengFunctionDescriptor){.name = \"%s\"}",
                            fm->c_name, fm->feng_name);
                    } else {
                        buf_append_fmt(fd,
                            "    return %s(_self_value, "
                            "&(const FengFunctionDescriptor){.name = \"%s\"}",
                            fm->c_name, fm->feng_name);
                    }
                    for (size_t pi = 0; pi < sm->param_count; ++pi) {
                        char pname[32];

                        snprintf(pname, sizeof pname, "p%zu", pi);
                        buf_append_cstr(fd, ", ");
                        if (!cg_append_witness_forward_arg(cg,
                                                           fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                           blame)) {
                            buf_free(&prefix);
                            free(s_san);
                            return false;
                        }
                    }
                    buf_append_cstr(fd, ");\n}\n\n");
                }
            }

            {
                Buf var;
                Buf *fd = &cg->witness_defs;
                const char **parent_witness_vars = NULL;

                if (s->direct_parent_spec_count > 0U) {
                    parent_witness_vars = (const char **)calloc(
                        s->direct_parent_spec_count,
                        sizeof(*parent_witness_vars));
                    if (parent_witness_vars == NULL) {
                        buf_free(&prefix);
                        free(s_san);
                        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                    }
                }
                for (size_t parent_index = 0U;
                     parent_index < s->direct_parent_spec_count;
                     ++parent_index) {
                    const UserSpec *parent_spec =
                        cg_user_spec_direct_parent(cg, s, parent_index);

                    if (parent_spec == NULL ||
                        !cg_ensure_witness_instance(
                            cg,
                            subject_key,
                            parent_spec,
                            scalar_subject_storage,
                            blame,
                            &parent_witness_vars[parent_index])) {
                        free(parent_witness_vars);
                        buf_free(&prefix);
                        free(s_san);
                        return false;
                    }
                }

                buf_init(&var);
                buf_append_fmt(&var, "FengWitness__%s__subject_%zu__as__%s__%s",
                               cg->module_mangle, witness_id, cg->module_mangle, s_san);
                if (var.data == NULL) {
                    buf_free(&prefix);
                    free(s_san);
                    return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                }

                buf_append_fmt(&cg->headers, "static const struct %s %s;\n",
                               s->c_witness_struct_name, var.data);
                buf_append_fmt(fd, "static const struct %s %s = {\n",
                               s->c_witness_struct_name, var.data);
                for (size_t i = 0U; i < s->member_count; ++i) {
                    const UserSpecMember *sm = &s->members[i];

                    buf_append_fmt(fd, "    .%s = &%s__%s,\n",
                                   sm->c_field_name, prefix.data, sm->c_field_name);
                }
                for (size_t parent_index = 0U;
                     parent_index < s->direct_parent_spec_count;
                     ++parent_index) {
                    const UserSpec *parent_spec =
                        cg_user_spec_direct_parent(cg, s, parent_index);

                    buf_append_cstr(fd, "    .");
                    cg_append_spec_parent_field_name(fd, parent_spec);
                    buf_append_fmt(fd, " = &%s,\n",
                                   parent_witness_vars[parent_index]);
                }
                buf_append_cstr(fd, "};\n\n");

                free(parent_witness_vars);
                if (!cg_subject_witness_table_add(cg,
                                                  subject_key,
                                                  scalar_subject_storage,
                                                  s,
                                                  var.data)) {
                    buf_free(&var);
                    buf_free(&prefix);
                    free(s_san);
                    return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
                }
                *out_var = var.data;
            }
            buf_free(&prefix);
            free(s_san);
            return true;
        }

        const UserType *t = cg_find_user_type_by_decl(cg, subject_key->as.type_decl);

        if (t == NULL) {
            return cg_fail(cg, blame,
                "CE0326", "codegen: witness source type is not registered in current module");
        }
        return cg_ensure_witness_instance_for_type(cg, t, s, blame, out_var);
    }
    if (subject_key->kind != FENG_SEMANTIC_SUBJECT_KEY_BUILTIN &&
        subject_key->kind != FENG_SEMANTIC_SUBJECT_KEY_ARRAY) {
        return cg_fail(cg, blame,
            "CE0327", "codegen: invalid subject key for object-form spec coercion");
    }

    CGTypeKind subject_kind;
    if (!cg_subject_key_to_target_kind(subject_key, &subject_kind)) {
        return cg_fail(cg, blame,
            "CE0328", "codegen: object-form spec coercion has unknown subject key");
    }
    const FengSpecWitness *witness = feng_semantic_lookup_spec_witness(
        cg->analysis, subject_key, s->decl);
    if (witness == NULL) {
        return cg_fail(cg, blame,
            "CE0329", "codegen: missing semantic witness for object-form spec coercion");
    }

    const size_t witness_id = cg->subject_witness_counter++;
    const char *spec_unique_name =
        (s->generic_context_type_param_count > 0U && s->c_aggregate_desc_name)
            ? s->c_aggregate_desc_name
            : s->feng_name;
    char *s_san = cg_sanitize(spec_unique_name, strlen(spec_unique_name));
    if (s_san == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    Buf prefix;
    buf_init(&prefix);
    buf_append_fmt(&prefix, "FengSpecThunk__%s__subject_%zu__as__%s__%s",
                   cg->module_mangle, witness_id, cg->module_mangle, s_san);
    if (prefix.data == NULL) {
        free(s_san);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    for (size_t i = 0U; i < s->member_count; ++i) {
        const UserSpecMember *sm = &s->members[i];
        bool witness_mapping_ambiguous = false;
        const FengSpecWitnessMember *wm =
            cg_spec_witness_member_for_slot(
                witness, sm, &witness_mapping_ambiguous);
        const BuiltinFit *bf = NULL;
        const UserMethod *fm = NULL;

        if (wm == NULL && !witness_mapping_ambiguous) {
            buf_free(&prefix);
            free(s_san);
            return cg_fail(cg, blame,
                "CE0318", "codegen: internal: witness requirement mapping is missing for non-type subject as spec '%s' member '%s'",
                s->feng_name,
                sm->feng_name);
        }
        if (!witness_mapping_ambiguous && wm->impl_member == NULL) {
            buf_free(&prefix);
            free(s_san);
            return cg_fail(cg, blame,
                "CE0319", "codegen: missing implementation for spec member '%s'",
                sm->feng_name);
        }
        if (sm->kind != USM_KIND_METHOD ||
            (!witness_mapping_ambiguous &&
             (wm->source_kind != FENG_SPEC_WITNESS_SOURCE_FIT_METHOD ||
              wm->via_fit_decl == NULL))) {
            buf_free(&prefix);
            free(s_san);
            return cg_fail(cg, blame,
                "CE0320", "codegen: non-type subject key currently supports fit-method spec members only");
        }

        if (witness_mapping_ambiguous) {
            size_t match_count =
                cg_find_builtin_fit_method_for_spec_slot(
                    cg,
                    subject_kind,
                    NULL,
                    s,
                    sm,
                    &bf,
                    &fm);

            if (match_count == 0U) {
                buf_free(&prefix);
                free(s_san);
                return cg_fail(cg, blame,
                    "CE0318", "codegen: internal: closed witness requirement mapping is missing for non-type subject as spec '%s' member '%s'",
                    s->feng_name,
                    sm->feng_name);
            }
            if (match_count > 1U) {
                buf_free(&prefix);
                free(s_san);
                return cg_fail(cg, blame,
                    "CE0323", "codegen: non-type subject has multiple visible implementations of method '%s' required by spec '%s'",
                    sm->feng_name,
                    s->feng_name);
            }
        } else {
            bf = cg_find_builtin_fit_by_decl(cg, wm->via_fit_decl);
            if (bf != NULL &&
                !cg_builtin_fit_matches_subject(bf, subject_kind, NULL)) {
                bf = NULL;
            }
            if (bf != NULL) {
                fm = cg_builtin_fit_method_by_member(bf, wm->impl_member);
                if (fm == NULL) {
                    fm = cg_builtin_fit_method(bf, sm->feng_name,
                                               strlen(sm->feng_name));
                }
            }
            if (bf == NULL) {
                for (size_t bi = 0U; bi < cg->builtin_fit_count; ++bi) {
                    const BuiltinFit *candidate = &cg->builtin_fits[bi];
                    if (!cg_builtin_fit_matches_subject(candidate,
                                                        subject_kind,
                                                        NULL) ||
                        !cg_builtin_fit_targets_spec(cg, candidate, s)) {
                        continue;
                    }
                    const UserMethod *candidate_method =
                        cg_builtin_fit_method_by_member(candidate,
                                                        wm->impl_member);
                    if (candidate_method == NULL) {
                        candidate_method = cg_builtin_fit_method(
                            candidate,
                            sm->feng_name,
                            strlen(sm->feng_name));
                    }
                    if (candidate_method != NULL) {
                        bf = candidate;
                        fm = candidate_method;
                        break;
                    }
                }
            }
        }
        if (!witness_mapping_ambiguous &&
            !cg_user_method_matches_exact_spec_slot(cg, fm, s, sm)) {
            size_t match_count =
                cg_find_builtin_fit_method_for_spec_slot(
                    cg,
                    subject_kind,
                    NULL,
                    s,
                    sm,
                    &bf,
                    &fm);

            if (match_count == 0U) {
                buf_free(&prefix);
                free(s_san);
                return cg_fail(cg, blame,
                    "CE0318", "codegen: internal: closed witness requirement mapping is missing for non-type subject as spec '%s' member '%s'",
                    s->feng_name,
                    sm->feng_name);
            }
            if (match_count > 1U) {
                buf_free(&prefix);
                free(s_san);
                return cg_fail(cg, blame,
                    "CE0323", "codegen: non-type subject has multiple visible implementations of method '%s' required by spec '%s'",
                    sm->feng_name,
                    s->feng_name);
            }
        }
        if (bf == NULL || !cg_builtin_fit_targets_spec(cg, bf, s) ||
            !cg_builtin_fit_matches_subject(bf, subject_kind, NULL)) {
            buf_free(&prefix);
            free(s_san);
            return cg_fail(cg, blame,
                "CE0324", "codegen: fit implementation does not match object-form spec coercion source");
        }

        if (fm == NULL) {
            buf_free(&prefix);
            free(s_san);
            return cg_fail(cg, blame,
                "CE0325", "codegen: fit method '%s' was not registered", sm->feng_name);
        }
        /* D4 contract: witness thunk must forward into the same emitted fit
         * method symbol used by direct-call (fm->c_name). Do not synthesize
         * a separate box-only method implementation symbol. */

        if (sm->is_static) {
            if (!cg_emit_static_spec_method_thunk(cg,
                                                  s,
                                                  sm,
                                                  fm,
                                                  bf,
                                                  prefix.data,
                                                  blame)) {
                buf_free(&prefix);
                free(s_san);
                return false;
            }
            continue;
        }

            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            Buf *fp = &cg->fn_protos;
            buf_append_fmt(fp, "static void %s__%s(void *_subject",
                           prefix.data, sm->c_field_name);
            for (size_t pi = 0; pi < sm->param_count; ++pi) {
                buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fp, " p%zu", pi);
            }
            buf_append_cstr(fp, ", void *_out);\n");

            Buf *fd = &cg->witness_defs;
            buf_append_fmt(fd, "static void %s__%s(void *_subject",
                           prefix.data, sm->c_field_name);
            for (size_t pi = 0; pi < sm->param_count; ++pi) {
                buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fd, " p%zu", pi);
            }
            buf_append_cstr(fd, ", void *_out) {\n    ");
            cg_emit_c_type(fd, fm->return_type);
            buf_append_cstr(fd, " _ret;\n");
            if (cg_type_kind_is_scalar_builtin(subject_kind)) {
                if (!cg_emit_scalar_subject_load(cg,
                                                fd,
                                                subject_kind,
                                                NULL,
                                                scalar_subject_storage,
                                                blame,
                                                "_self_value")) {
                    buf_free(&prefix);
                    free(s_san);
                    return false;
                }
                buf_append_fmt(fd,
                    "    _ret = %s(_self_value, "
                    "&(const FengFunctionDescriptor){.name = \"%s\"}",
                    fm->c_name, fm->feng_name);
            } else {
                if (!cg_emit_ref_subject_load(cg,
                                              fd,
                                              bf->target_type,
                                              blame,
                                              "_self_ref")) {
                    buf_free(&prefix);
                    free(s_san);
                    return false;
                }
                buf_append_fmt(fd,
                    "    _ret = %s(_self_ref, "
                    "&(const FengFunctionDescriptor){.name = \"%s\"}",
                    fm->c_name, fm->feng_name);
            }
            for (size_t pi = 0; pi < sm->param_count; ++pi) {
                char pname[32];
                snprintf(pname, sizeof pname, "p%zu", pi);
                buf_append_cstr(fd, ", ");
                if (!cg_append_witness_forward_arg(cg,
                                                   fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                   blame)) {
                    buf_free(&prefix);
                    free(s_san);
                    return false;
                }
            }
            buf_append_cstr(fd, ");\n    memcpy(_out, &_ret, sizeof _ret);\n}\n\n");
            continue;
        }

        Buf *fp = &cg->fn_protos;
        buf_append_cstr(fp, "static ");
        cg_emit_c_type(fp, sm->type);
        buf_append_fmt(fp, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
        for (size_t pi = 0; pi < sm->param_count; ++pi) {
            buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
            buf_append_fmt(fp, " p%zu", pi);
        }
        buf_append_cstr(fp, ");\n");

        Buf *fd = &cg->witness_defs;
        buf_append_cstr(fd, "static ");
        cg_emit_c_type(fd, sm->type);
        buf_append_fmt(fd, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
        for (size_t pi = 0; pi < sm->param_count; ++pi) {
            buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
            buf_append_fmt(fd, " p%zu", pi);
        }
        buf_append_cstr(fd, ") {\n");
        if (sm->type->kind == CG_TYPE_VOID) {
            if (cg_type_kind_is_scalar_builtin(subject_kind)) {
                if (!cg_emit_scalar_subject_load(cg,
                                                fd,
                                                subject_kind,
                                                NULL,
                                                scalar_subject_storage,
                                                blame,
                                                "_self_value")) {
                    buf_free(&prefix);
                    free(s_san);
                    return false;
                }
                buf_append_fmt(fd,
                    "    %s(_self_value, "
                    "&(const FengFunctionDescriptor){.name = \"%s\"}",
                    fm->c_name, fm->feng_name);
            } else {
                if (!cg_emit_ref_subject_load(cg,
                                              fd,
                                              bf->target_type,
                                              blame,
                                              "_self_ref")) {
                    buf_free(&prefix);
                    free(s_san);
                    return false;
                }
                buf_append_fmt(fd,
                    "    %s(_self_ref, "
                    "&(const FengFunctionDescriptor){.name = \"%s\"}",
                    fm->c_name, fm->feng_name);
            }
        } else {
            if (cg_type_kind_is_scalar_builtin(subject_kind)) {
                if (!cg_emit_scalar_subject_load(cg,
                                                fd,
                                                subject_kind,
                                                NULL,
                                                scalar_subject_storage,
                                                blame,
                                                "_self_value")) {
                    buf_free(&prefix);
                    free(s_san);
                    return false;
                }
                buf_append_fmt(fd,
                    "    return %s(_self_value, "
                    "&(const FengFunctionDescriptor){.name = \"%s\"}",
                    fm->c_name, fm->feng_name);
            } else {
                if (!cg_emit_ref_subject_load(cg,
                                              fd,
                                              bf->target_type,
                                              blame,
                                              "_self_ref")) {
                    buf_free(&prefix);
                    free(s_san);
                    return false;
                }
                buf_append_fmt(fd,
                    "    return %s(_self_ref, "
                    "&(const FengFunctionDescriptor){.name = \"%s\"}",
                    fm->c_name, fm->feng_name);
            }
        }
        for (size_t pi = 0; pi < sm->param_count; ++pi) {
            char pname[32];
            snprintf(pname, sizeof pname, "p%zu", pi);
            buf_append_cstr(fd, ", ");
            if (!cg_append_witness_forward_arg(cg,
                                               fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                               blame)) {
                buf_free(&prefix);
                free(s_san);
                return false;
            }
        }
        buf_append_cstr(fd, ");\n}\n\n");
    }

    const char **parent_witness_vars = NULL;
    if (s->direct_parent_spec_count > 0U) {
        parent_witness_vars = (const char **)calloc(
            s->direct_parent_spec_count,
            sizeof(*parent_witness_vars));
        if (parent_witness_vars == NULL) {
            buf_free(&prefix);
            free(s_san);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        if (parent_spec == NULL ||
            !cg_ensure_witness_instance(cg,
                                        subject_key,
                                        parent_spec,
                                        scalar_subject_storage,
                                        blame,
                                        &parent_witness_vars[parent_index])) {
            free(parent_witness_vars);
            buf_free(&prefix);
            free(s_san);
            return false;
        }
    }

    Buf var;
    buf_init(&var);
    buf_append_fmt(&var, "FengWitness__%s__subject_%zu__as__%s__%s",
                   cg->module_mangle, witness_id, cg->module_mangle, s_san);
    if (var.data == NULL) {
        buf_free(&prefix);
        free(s_san);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_fmt(&cg->headers, "static const struct %s %s;\n",
                   s->c_witness_struct_name, var.data);

    Buf *fd = &cg->witness_defs;
    buf_append_fmt(fd, "static const struct %s %s = {\n",
                   s->c_witness_struct_name, var.data);
    for (size_t i = 0U; i < s->member_count; ++i) {
        const UserSpecMember *sm = &s->members[i];
        buf_append_fmt(fd, "    .%s = &%s__%s,\n",
                       sm->c_field_name, prefix.data, sm->c_field_name);
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        buf_append_cstr(fd, "    .");
        cg_append_spec_parent_field_name(fd, parent_spec);
        buf_append_fmt(fd, " = &%s,\n", parent_witness_vars[parent_index]);
    }
    buf_append_cstr(fd, "};\n\n");

    free(parent_witness_vars);
    if (!cg_subject_witness_table_add(cg,
                                      subject_key,
                                      scalar_subject_storage,
                                      s,
                                      var.data)) {
        buf_free(&var);
        buf_free(&prefix);
        free(s_san);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    *out_var = var.data;
    buf_free(&prefix);
    free(s_san);
    return true;
}

static bool cg_ensure_witness_instance_for_subject_key(
    CG *cg,
    const FengSemanticSubjectKey *subject_key,
    const UserSpec *s,
    FengSpecObjectSubjectStorageKind scalar_subject_storage,
    FengToken blame,
    const char **out_var) {
    return cg_ensure_witness_instance(cg,
                                      subject_key,
                                      s,
                                      scalar_subject_storage,
                                      blame,
                                      out_var);
}

/* Append a call to one already-selected static implementation. Builtin-fit
 * entries retain their existing descriptor-first ABI; all other static
 * wrappers receive only their declared parameters. */
static bool cg_append_static_spec_method_invoke(
    CG *cg,
    Buf *out,
    const UserSpecMember *spec_member,
    const UserMethod *method,
    const BuiltinFit *builtin_fit,
    FengToken blame) {
    bool has_argument = false;

    if (cg == NULL || out == NULL || spec_member == NULL || method == NULL ||
        method->member == NULL || !method->member->is_static ||
        method->param_count != spec_member->param_count) {
        return false;
    }
    buf_append_fmt(out, "%s(", method->c_name);
    if (builtin_fit != NULL) {
        buf_append_fmt(
            out,
            "&(const FengFunctionDescriptor){.name = \"%s\"}",
            method->feng_name);
        has_argument = true;
    }
    for (size_t index = 0U; index < spec_member->param_count; ++index) {
        char parameter_name[32];

        snprintf(parameter_name, sizeof parameter_name, "p%zu", index);
        if (has_argument) {
            buf_append_cstr(out, ", ");
        }
        if (!cg_append_witness_forward_arg(
                cg,
                out,
                spec_member->param_types[index],
                method->param_types[index],
                spec_member->param_abi_kinds[index],
                parameter_name,
                blame)) {
            return false;
        }
        has_argument = true;
    }
    buf_append_cstr(out, ")");
    return true;
}

/* Emit one receiver-free static-method witness thunk. Type methods, user-fit
 * methods and non-generic builtin-fit methods share the same stable spec slot
 * ABI; only the compile-time-selected callee ABI differs. */
static bool cg_emit_static_spec_method_thunk(
    CG *cg,
    const UserSpec *spec,
    const UserSpecMember *spec_member,
    const UserMethod *method,
    const BuiltinFit *builtin_fit,
    const char *prefix,
    FengToken blame) {
    if (cg == NULL || spec == NULL || spec_member == NULL || method == NULL ||
        method->member == NULL || !method->member->is_static ||
        prefix == NULL || spec_member->kind != USM_KIND_METHOD ||
        !spec_member->is_static ||
        method->param_count != spec_member->param_count) {
        return false;
    }
    if (builtin_fit != NULL && builtin_fit->target_type_param_count > 0U) {
        return cg_fail(
            cg,
            blame,
            "CE0144",
            "codegen: generic builtin static fit methods are not supported yet");
    }

    if (spec_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
        Buf *prototype = &cg->fn_protos;
        Buf *definition = &cg->witness_defs;

        buf_append_fmt(prototype, "static void %s__%s(",
                       prefix, spec_member->c_field_name);
        for (size_t index = 0U;
             index < spec_member->param_count;
             ++index) {
            if (index > 0U) buf_append_cstr(prototype, ", ");
            cg_emit_callable_abi_param_type(
                prototype,
                spec_member->param_types[index],
                spec_member->param_abi_kinds[index]);
            buf_append_fmt(prototype, " p%zu", index);
        }
        if (spec_member->param_count > 0U) {
            buf_append_cstr(prototype, ", ");
        }
        buf_append_cstr(prototype, "void *_out);\n");

        buf_append_fmt(definition, "static void %s__%s(",
                       prefix, spec_member->c_field_name);
        for (size_t index = 0U;
             index < spec_member->param_count;
             ++index) {
            if (index > 0U) buf_append_cstr(definition, ", ");
            cg_emit_callable_abi_param_type(
                definition,
                spec_member->param_types[index],
                spec_member->param_abi_kinds[index]);
            buf_append_fmt(definition, " p%zu", index);
        }
        if (spec_member->param_count > 0U) {
            buf_append_cstr(definition, ", ");
        }
        buf_append_cstr(definition, "void *_out) {\n    ");
        cg_emit_c_type(definition, method->return_type);
        buf_append_cstr(definition, " _ret = ");
        if (!cg_append_static_spec_method_invoke(cg,
                                                 definition,
                                                 spec_member,
                                                 method,
                                                 builtin_fit,
                                                 blame)) {
            return false;
        }
        buf_append_cstr(
            definition,
            ";\n    memcpy(_out, &_ret, sizeof _ret);\n}\n\n");
        return true;
    }

    {
        Buf *prototype = &cg->fn_protos;
        Buf *definition = &cg->witness_defs;

        buf_append_cstr(prototype, "static ");
        cg_emit_c_type(prototype, spec_member->type);
        buf_append_fmt(prototype, " %s__%s(",
                       prefix, spec_member->c_field_name);
        for (size_t index = 0U;
             index < spec_member->param_count;
             ++index) {
            if (index > 0U) buf_append_cstr(prototype, ", ");
            cg_emit_callable_abi_param_type(
                prototype,
                spec_member->param_types[index],
                spec_member->param_abi_kinds[index]);
            buf_append_fmt(prototype, " p%zu", index);
        }
        if (spec_member->param_count == 0U) {
            buf_append_cstr(prototype, "void");
        }
        buf_append_cstr(prototype, ");\n");

        buf_append_cstr(definition, "static ");
        cg_emit_c_type(definition, spec_member->type);
        buf_append_fmt(definition, " %s__%s(",
                       prefix, spec_member->c_field_name);
        for (size_t index = 0U;
             index < spec_member->param_count;
             ++index) {
            if (index > 0U) buf_append_cstr(definition, ", ");
            cg_emit_callable_abi_param_type(
                definition,
                spec_member->param_types[index],
                spec_member->param_abi_kinds[index]);
            buf_append_fmt(definition, " p%zu", index);
        }
        if (spec_member->param_count == 0U) {
            buf_append_cstr(definition, "void");
        }
        buf_append_cstr(definition, ") {\n    ");
        if (spec_member->type->kind != CG_TYPE_VOID) {
            buf_append_cstr(definition, "return ");
        }
        if (!cg_append_static_spec_method_invoke(cg,
                                                 definition,
                                                 spec_member,
                                                 method,
                                                 builtin_fit,
                                                 blame)) {
            return false;
        }
        buf_append_cstr(definition, ";\n}\n\n");
        return true;
    }
}

/* Emit one subject-independent witness thunk for a static spec member.
 * Reference types and boxed value types share this path because static slots
 * neither consume nor inspect the object-form spec subject. */
static bool cg_emit_static_user_spec_member_thunk(
    CG *cg,
    const UserType *type,
    const UserSpec *spec,
    const UserSpecMember *spec_member,
    const CGWitnessBinding *binding,
    const char *prefix,
    FengToken blame) {
    if (cg == NULL || type == NULL || spec == NULL || spec_member == NULL ||
        binding == NULL || prefix == NULL || !spec_member->is_static) {
        return false;
    }

    if (spec_member->kind == USM_KIND_METHOD) {
        const UserMethod *method = binding->method;

        if (method == NULL) {
            return cg_fail(cg, blame,
                "CE0342", "codegen: internal: type '%s' has no static method '%s' to satisfy spec '%s'",
                type->feng_name, spec_member->feng_name, spec->feng_name);
        }
        return cg_emit_static_spec_method_thunk(cg,
                                                spec,
                                                spec_member,
                                                method,
                                                NULL,
                                                prefix,
                                                blame);
    }

    if (spec_member->kind == USM_KIND_FIELD) {
        const TypeStaticBinding *static_binding = binding->static_binding;
        Buf *prototype = &cg->fn_protos;
        Buf *definition = &cg->witness_defs;

        if (static_binding == NULL) {
            return cg_fail(cg, blame,
                "CE0343", "codegen: internal: type '%s' has no static field '%s' to satisfy spec '%s'",
                type->feng_name, spec_member->feng_name, spec->feng_name);
        }

        /* A generic spec selects this slot's ABI from the open declaration.
         * Keep that ABI after the member type is closed: in particular,
         * `static let/var value: T` uses an out pointer even when T later
         * becomes a direct C scalar. */
        buf_append_cstr(definition, "static ");
        cg_emit_callable_abi_return_type(definition,
                                         spec_member->type,
                                         spec_member->value_abi_kind);
        buf_append_fmt(definition, " %s__get_%s(",
                       prefix, spec_member->c_field_name);
        if (spec_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(definition, "void *_out");
        } else {
            buf_append_cstr(definition, "void");
        }
        buf_append_cstr(definition, ") {\n");
        if (!cg_append_type_static_binding_ensure_init_call(cg,
                                                            definition,
                                                            static_binding)) {
            return false;
        }
        if (spec_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_fmt(definition,
                           "    memcpy(_out, &%s, sizeof %s);\n}\n\n",
                           static_binding->c_name,
                           static_binding->c_name);
        } else {
            buf_append_cstr(definition, "    return ");
            if (spec_member->value_abi_kind ==
                CG_CALLABLE_ABI_ERASED_POINTER) {
                buf_append_cstr(definition, "(void *)");
            }
            buf_append_fmt(definition, "%s;\n}\n\n",
                           static_binding->c_name);
        }

        buf_append_cstr(prototype, "static ");
        cg_emit_callable_abi_return_type(prototype,
                                         spec_member->type,
                                         spec_member->value_abi_kind);
        buf_append_fmt(prototype, " %s__get_%s(",
                       prefix, spec_member->c_field_name);
        if (spec_member->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
            buf_append_cstr(prototype, "void *_out");
        } else {
            buf_append_cstr(prototype, "void");
        }
        buf_append_cstr(prototype, ");\n");

        if (spec_member->is_var) {
            buf_append_fmt(definition, "static void %s__set_%s(",
                           prefix, spec_member->c_field_name);
            cg_emit_callable_abi_param_type(definition,
                                            spec_member->type,
                                            spec_member->value_abi_kind);
            buf_append_cstr(definition, " value) {\n");
            if (!cg_append_type_static_binding_ensure_init_call(
                    cg,
                    definition,
                    static_binding)) {
                return false;
            }
            if (cgtype_is_managed(static_binding->type)) {
                buf_append_fmt(definition, "    feng_assign((void **)&%s, ",
                               static_binding->c_name);
                cg_append_callable_abi_argument_value(
                    definition,
                    static_binding->type,
                    spec_member->value_abi_kind,
                    "value");
                buf_append_cstr(definition, ");\n");
            } else if (cgtype_is_aggregate(static_binding->type)) {
                const char *aggregate_descriptor =
                    cg_aggregate_desc_name(static_binding->type);

                if (aggregate_descriptor == NULL) {
                    return cg_fail(cg, blame,
                        "CE0348", "codegen: missing aggregate descriptor for spec static field write");
                }
                buf_append_fmt(definition, "    feng_aggregate_assign(&%s, ",
                               static_binding->c_name);
                if (spec_member->value_abi_kind ==
                    CG_CALLABLE_ABI_ADDRESS) {
                    buf_append_cstr(definition, "value");
                } else {
                    buf_append_cstr(definition, "&value");
                }
                buf_append_fmt(definition, ", &%s);\n",
                               aggregate_descriptor);
            } else {
                buf_append_fmt(definition, "    %s = ",
                               static_binding->c_name);
                cg_append_callable_abi_argument_value(
                    definition,
                    static_binding->type,
                    spec_member->value_abi_kind,
                    "value");
                buf_append_cstr(definition, ";\n");
            }
            buf_append_cstr(definition, "}\n\n");
            buf_append_fmt(prototype, "static void %s__set_%s(",
                           prefix, spec_member->c_field_name);
            cg_emit_callable_abi_param_type(prototype,
                                            spec_member->type,
                                            spec_member->value_abi_kind);
            buf_append_cstr(prototype, " value);\n");
        }
        return true;
    }

    return cg_fail(cg, blame,
                   "CE0342", "codegen: unsupported static spec member");
}

/* Value-semantics (tuple or @value) spec coercion stores the subject in a
 * managed box, while generic constraint dispatch still passes an address of
 * the by-value struct. This separate witness table reads `box->value` before
 * forwarding to the normal fit method body. Serves both tuple and @value. */
static bool cg_ensure_value_box_witness_instance(CG *cg,
                                                 const UserType *t,
                                                 const UserSpec *s,
                                                 FengToken blame,
                                                 const char **out_var) {
    if (cg == NULL || t == NULL || s == NULL || out_var == NULL ||
        !cg_user_type_is_value_semantics(t) || t->c_value_box_struct_name == NULL) {
        return false;
    }
    for (size_t cached_index = 0U;
         cached_index < cg->value_box_witness_table_count;
         ++cached_index) {
        if (cg->value_box_witness_tables[cached_index].type == t &&
            cg->value_box_witness_tables[cached_index].spec == s) {
            *out_var = cg->value_box_witness_tables[cached_index].c_var;
            return true;
        }
    }

    FengSemanticSubjectKey subject_key =
        feng_semantic_subject_key_for_type_decl(t->decl);
    const FengSpecWitness *witness = t->is_generic_instance
        ? NULL
        : feng_semantic_lookup_spec_witness(cg->analysis, &subject_key, s->decl);
    char *t_san = cg_sanitize(t->feng_name, strlen(t->feng_name));
    const char *spec_unique_name = s->generic_context_type_param_count > 0U && s->c_aggregate_desc_name
        ? s->c_aggregate_desc_name
        : s->feng_name;
    char *s_san = cg_sanitize(spec_unique_name, strlen(spec_unique_name));
    if (t_san == NULL || s_san == NULL) {
        free(t_san);
        free(s_san);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    const char *box_kind = cg_user_type_is_tuple(t) ? "tuple_box" : "value_box";

    Buf prefix;
    buf_init(&prefix);
    buf_append_fmt(&prefix, "FengSpecThunk__%s__%s__%s__as__%s__%s",
                   cg->module_mangle, t_san, box_kind, cg->module_mangle, s_san);
    if (prefix.data == NULL) {
        free(t_san);
        free(s_san);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    for (size_t i = 0U; i < s->member_count; ++i) {
        const UserSpecMember *sm = &s->members[i];
        CGWitnessBinding binding;
        bool witness_mapping_ambiguous = false;
        const FengSpecWitnessMember *wm = witness != NULL
            ? cg_spec_witness_member_for_slot(
                  witness, sm, &witness_mapping_ambiguous)
            : NULL;

        memset(&binding, 0, sizeof binding);
        if (witness != NULL && !witness_mapping_ambiguous) {
            if (wm == NULL) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0330", "codegen: internal: witness requirement mapping is missing for value box (%s, %s) member '%s'",
                    t->feng_name, s->feng_name, sm->feng_name);
            }
            if (wm->impl_member == NULL) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0331", "codegen: value type '%s' is missing an implementation for spec '%s' member '%s'",
                    t->feng_name, s->feng_name, sm->feng_name);
            }
            binding.source_kind = wm->source_kind;
            if (wm->source_kind == FENG_SPEC_WITNESS_SOURCE_FIT_METHOD) {
                const UserFit *uf = cg_find_user_fit_by_decl_and_target(cg,
                                                                        wm->via_fit_decl,
                                                                        t);

                if (uf == NULL || uf->target != t) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return cg_fail(cg, blame,
                        "CE0332", "codegen: internal: value type fit decl for spec '%s' member '%s' not registered for type '%s'",
                        s->feng_name, sm->feng_name, t->feng_name);
                }
                binding.fit = uf;
                for (size_t method_index = 0U; method_index < uf->method_count; ++method_index) {
                    if (uf->methods[method_index].member == wm->impl_member) {
                        binding.method = &uf->methods[method_index];
                        break;
                    }
                }
                if (binding.method == NULL) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return cg_fail(cg, blame,
                        "CE0333", "codegen: internal: value type fit method '%s' not found in fit body for type '%s'",
                        sm->feng_name, t->feng_name);
                }
            } else if (sm->kind == USM_KIND_METHOD) {
                /* TYPE_OWN_METHOD: @value type's own method satisfies the spec.
                 * Tuples have no methods of their own, so reject them here. */
                if (!cg_user_type_is_value(t)) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return cg_fail(cg, blame,
                        "CE0335", "codegen: tuple type '%s' cannot satisfy spec method '%s' without a fit method",
                        t->feng_name, sm->feng_name);
                }
                binding.method = sm->is_static
                    ? cg_user_type_static_method_by_member(t, wm->impl_member)
                    : cg_user_type_method_by_member(t, wm->impl_member);
                if (binding.method == NULL) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return cg_fail(cg, blame,
                        "CE0342", "codegen: internal: type '%s' has no method '%s' to satisfy spec '%s'",
                        t->feng_name, sm->feng_name, s->feng_name);
                }
            } else if (sm->kind == USM_KIND_FIELD) {
                if (sm->is_static) {
                    binding.static_binding = cg_user_type_static_binding(
                        t,
                        wm->impl_member->as.field.name.data,
                        wm->impl_member->as.field.name.length);
                    if (binding.static_binding == NULL) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return cg_fail(cg, blame,
                            "CE0343", "codegen: internal: type '%s' has no static field '%s' to satisfy spec '%s'",
                            t->feng_name, sm->feng_name, s->feng_name);
                    }
                } else {
                    binding.field = cg_user_type_field(
                        t,
                        wm->impl_member->as.field.name.data,
                        wm->impl_member->as.field.name.length);
                    if (binding.field == NULL) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return cg_fail(cg, blame,
                            "CE0334", "codegen: internal: value type '%s' has no field '%s' to satisfy spec '%s'",
                            t->feng_name, sm->feng_name, s->feng_name);
                    }
                }
            } else {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0335", "codegen: value type '%s' cannot satisfy spec member '%s' (unsupported source kind)",
                    t->feng_name, sm->feng_name);
            }
        } else if (!cg_resolve_witness_binding_fallback(cg, t, s, sm, blame, &binding)) {
            buf_free(&prefix); free(t_san); free(s_san);
            return false;
        }
        if (witness != NULL && !witness_mapping_ambiguous &&
            !cg_witness_binding_matches_exact_spec_slot(
                cg, &binding, s, sm) &&
            !cg_resolve_witness_binding_fallback(
                cg, t, s, sm, blame, &binding)) {
            buf_free(&prefix); free(t_san); free(s_san);
            return false;
        }

        if (sm->is_static) {
            if (!cg_emit_static_user_spec_member_thunk(
                    cg, t, s, sm, &binding, prefix.data, blame)) {
                buf_free(&prefix); free(t_san); free(s_san);
                return false;
            }
            continue;
        }

        if (binding.source_kind == FENG_SPEC_WITNESS_SOURCE_FIT_METHOD) {
            const UserMethod *fm = binding.method;

            if (sm->kind != USM_KIND_METHOD || fm == NULL) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0336", "codegen: value type spec member '%s' must be implemented by a fit method",
                    sm->feng_name);
            }

            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                Buf *fp = &cg->fn_protos;
                Buf *fd = &cg->witness_defs;

                buf_append_fmt(fp, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                    buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fp, " p%zu", pi);
                }
                buf_append_cstr(fp, ", void *_out);\n");

                buf_append_fmt(fd, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                    buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fd, " p%zu", pi);
                }
                buf_append_cstr(fd, ", void *_out) {\n    ");
                cg_emit_c_type(fd, fm->return_type);
                buf_append_fmt(fd,
                               " _ret = %s(%s((struct %s *)_subject)->value",
                               fm->c_name,
                               cg_user_type_is_value_semantics(t) ? "&" : "",
                               t->c_value_box_struct_name);
                for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                    char pname[32];

                    snprintf(pname, sizeof pname, "p%zu", pi);
                    buf_append_cstr(fd, ", ");
                    if (!cg_append_witness_forward_arg(cg,
                                                       fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                       blame)) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return false;
                    }
                }
                buf_append_cstr(fd, ");\n    memcpy(_out, &_ret, sizeof _ret);\n}\n\n");
                continue;
            }

            Buf *fp = &cg->fn_protos;
            buf_append_cstr(fp, "static ");
            cg_emit_c_type(fp, sm->type);
            buf_append_fmt(fp, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fp, " p%zu", pi);
            }
            buf_append_cstr(fp, ");\n");

            Buf *fd = &cg->witness_defs;
            buf_append_cstr(fd, "static ");
            cg_emit_c_type(fd, sm->type);
            buf_append_fmt(fd, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fd, " p%zu", pi);
            }
            buf_append_cstr(fd, ") {\n");
            if (sm->type->kind == CG_TYPE_VOID) {
                buf_append_fmt(fd,
                               "    %s(%s((struct %s *)_subject)->value",
                               fm->c_name,
                               cg_user_type_is_value_semantics(t) ? "&" : "",
                               t->c_value_box_struct_name);
            } else {
                buf_append_fmt(fd,
                               "    return %s(%s((struct %s *)_subject)->value",
                               fm->c_name,
                               cg_user_type_is_value_semantics(t) ? "&" : "",
                               t->c_value_box_struct_name);
            }
            for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                char pname[32];

                snprintf(pname, sizeof pname, "p%zu", pi);
                buf_append_cstr(fd, ", ");
                if (!cg_append_witness_forward_arg(cg,
                                                   fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                   blame)) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return false;
                }
            }
            buf_append_cstr(fd, ");\n}\n\n");
            continue;
        }

        /* TYPE_OWN_METHOD: @value type's own method satisfies the spec.
         * Thunk passes &box->value (pointer) since @value methods take
         * struct T *self. */
        if (binding.source_kind == FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD) {
            const UserMethod *um = binding.method;

            if (sm->kind != USM_KIND_METHOD || um == NULL) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0346", "codegen: spec method '%s' must be implemented by a method on '%s'",
                    sm->feng_name, t->feng_name);
            }

            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                Buf *fp = &cg->fn_protos;
                Buf *fd = &cg->witness_defs;

                buf_append_fmt(fp, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                    buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fp, " p%zu", pi);
                }
                buf_append_cstr(fp, ", void *_out);\n");

                buf_append_fmt(fd, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                    buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fd, " p%zu", pi);
                }
                buf_append_cstr(fd, ", void *_out) {\n    ");
                cg_emit_c_type(fd, um->return_type);
                buf_append_fmt(fd,
                               " _ret = %s(&((struct %s *)_subject)->value",
                               um->c_name,
                               t->c_value_box_struct_name);
                for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                    char pname[32];

                    snprintf(pname, sizeof pname, "p%zu", pi);
                    buf_append_cstr(fd, ", ");
                    if (!cg_append_witness_forward_arg(cg,
                                                       fd,
                                                           sm->param_types[pi],
                                                           um->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                       blame)) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return false;
                    }
                }
                buf_append_cstr(fd, ");\n    memcpy(_out, &_ret, sizeof _ret);\n}\n\n");
                continue;
            }

            Buf *fp = &cg->fn_protos;
            buf_append_cstr(fp, "static ");
            cg_emit_c_type(fp, sm->type);
            buf_append_fmt(fp, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fp, " p%zu", pi);
            }
            buf_append_cstr(fp, ");\n");

            Buf *fd = &cg->witness_defs;
            buf_append_cstr(fd, "static ");
            cg_emit_c_type(fd, sm->type);
            buf_append_fmt(fd, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fd, " p%zu", pi);
            }
            buf_append_cstr(fd, ") {\n");
            if (sm->type->kind == CG_TYPE_VOID) {
                buf_append_fmt(fd,
                               "    %s(&((struct %s *)_subject)->value",
                               um->c_name,
                               t->c_value_box_struct_name);
            } else {
                buf_append_fmt(fd,
                               "    return %s(&((struct %s *)_subject)->value",
                               um->c_name,
                               t->c_value_box_struct_name);
            }
            for (size_t pi = 0U; pi < sm->param_count; ++pi) {
                char pname[32];

                snprintf(pname, sizeof pname, "p%zu", pi);
                buf_append_cstr(fd, ", ");
                if (!cg_append_witness_forward_arg(cg,
                                                   fd,
                                                           sm->param_types[pi],
                                                           um->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                   blame)) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return false;
                }
            }
            buf_append_cstr(fd, ");\n}\n\n");
            continue;
        }

        if (sm->kind != USM_KIND_FIELD ||
            binding.source_kind != FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_FIELD ||
            binding.field == NULL) {
            buf_free(&prefix); free(t_san); free(s_san);
            return cg_fail(cg, blame,
                "CE0337", "codegen: value type spec field '%s' must be satisfied by a value type field",
                sm->feng_name);
        }

        const UserField *field = binding.field;
        Buf *fd = &cg->witness_defs;
        Buf *fp = &cg->fn_protos;
        if (cg_spec_field_uses_storage_borrow(sm)) {
            buf_append_fmt(fd,
                           "static void *%s__borrow_%s(void *_subject) {\n"
                           "    return &((struct %s *)_subject)->value.%s;\n"
                           "}\n\n",
                           prefix.data,
                           sm->c_field_name,
                           t->c_value_box_struct_name,
                           field->c_name);
            buf_append_fmt(fp,
                           "static void *%s__borrow_%s(void *_subject);\n",
                           prefix.data,
                           sm->c_field_name);
        } else {
            buf_append_cstr(fd, "static ");
            cg_emit_c_type(fd, sm->type);
            buf_append_fmt(fd, " %s__get_%s(void *_subject) {\n",
                           prefix.data, sm->c_field_name);
            buf_append_fmt(fd,
                           "    return ((struct %s *)_subject)->value.%s;\n",
                           t->c_value_box_struct_name,
                           field->c_name);
            buf_append_cstr(fd, "}\n\n");

            buf_append_cstr(fp, "static ");
            cg_emit_c_type(fp, sm->type);
            buf_append_fmt(fp, " %s__get_%s(void *_subject);\n",
                           prefix.data, sm->c_field_name);
        }

        if (sm->is_var) {
            buf_free(&prefix); free(t_san); free(s_san);
            return cg_fail(cg, blame,
                "CE0338", "codegen: value type field is immutable and cannot satisfy var spec field '%s'",
                sm->feng_name);
        }
    }

    const char **parent_witness_vars = NULL;
    if (s->direct_parent_spec_count > 0U) {
        parent_witness_vars = (const char **)calloc(
            s->direct_parent_spec_count,
            sizeof(*parent_witness_vars));
        if (parent_witness_vars == NULL) {
            buf_free(&prefix); free(t_san); free(s_san);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        if (parent_spec == NULL ||
            !cg_ensure_value_box_witness_instance(
                cg,
                t,
                parent_spec,
                blame,
                &parent_witness_vars[parent_index])) {
            free(parent_witness_vars);
            buf_free(&prefix); free(t_san); free(s_san);
            return false;
        }
    }

    Buf var;
    buf_init(&var);
    buf_append_fmt(&var, "FengWitness__%s__%s__%s__as__%s__%s",
                   cg->module_mangle, t_san, box_kind, cg->module_mangle, s_san);
    if (var.data == NULL) {
        buf_free(&prefix); free(t_san); free(s_san);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }

    buf_append_fmt(&cg->headers, "static const struct %s %s;\n",
                   s->c_witness_struct_name, var.data);

    Buf *fd = &cg->witness_defs;
    buf_append_fmt(fd, "static const struct %s %s = {\n",
                   s->c_witness_struct_name, var.data);
    for (size_t i = 0U; i < s->member_count; ++i) {
        const UserSpecMember *sm = &s->members[i];

        if (sm->kind == USM_KIND_METHOD) {
            buf_append_fmt(fd, "    .%s = &%s__%s,\n",
                           sm->c_field_name, prefix.data, sm->c_field_name);
        } else if (sm->kind == USM_KIND_FIELD) {
            if (cg_spec_field_uses_storage_borrow(sm)) {
                buf_append_fmt(fd, "    .borrow_%s = &%s__borrow_%s,\n",
                               sm->c_field_name, prefix.data,
                               sm->c_field_name);
            } else {
                buf_append_fmt(fd, "    .get_%s = &%s__get_%s,\n",
                               sm->c_field_name, prefix.data,
                               sm->c_field_name);
            }
            if (sm->is_var) {
                buf_append_fmt(fd, "    .set_%s = &%s__set_%s,\n",
                               sm->c_field_name, prefix.data,
                               sm->c_field_name);
            }
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        buf_append_cstr(fd, "    .");
        cg_append_spec_parent_field_name(fd, parent_spec);
        buf_append_fmt(fd, " = &%s,\n", parent_witness_vars[parent_index]);
    }
    buf_append_cstr(fd, "};\n\n");
    free(parent_witness_vars);

    if (cg->value_box_witness_table_count + 1U > cg->value_box_witness_table_capacity) {
        size_t cap = cg->value_box_witness_table_capacity
                         ? cg->value_box_witness_table_capacity * 2U
                         : 4U;
        void *p = realloc(cg->value_box_witness_tables,
                          cap * sizeof *cg->value_box_witness_tables);

        if (p == NULL) {
            buf_free(&prefix); buf_free(&var); free(t_san); free(s_san);
            return false;
        }
        cg->value_box_witness_tables = p;
        cg->value_box_witness_table_capacity = cap;
    }
    cg->value_box_witness_tables[cg->value_box_witness_table_count].type = t;
    cg->value_box_witness_tables[cg->value_box_witness_table_count].spec = s;
    cg->value_box_witness_tables[cg->value_box_witness_table_count].c_var = var.data;
    *out_var = var.data;
    cg->value_box_witness_table_count++;

    buf_free(&prefix);
    free(t_san);
    free(s_san);
    return true;
}

/* Ensure a witness table for (T, S) has been materialised in fn_protos /
 * fn_defs and write its C variable name to *out_var (borrowed pointer into
 * the cache). The preferred source is the semantic witness sidecar. When the
 * analyzer has not demanded `(T, S)` yet, codegen falls back to the already
 * registered type/spec/fit metadata and synthesizes the same static witness. */
static bool cg_ensure_witness_instance_for_type(CG *cg, const UserType *t,
                                                const UserSpec *s, FengToken blame,
                                                const char **out_var) {
    const char *cached = cg_witness_table_lookup(cg, t, s);
    if (cached) { *out_var = cached; return true; }

    if (s->form == FENG_SPEC_FORM_INTERSECTION) {
        return cg_ensure_intersection_witness_instance(
            cg,
            t,
            NULL,
            s,
            FENG_SPEC_OBJECT_SUBJECT_STORAGE_BORROW_LOCAL,
            blame,
            out_var);
    }

    FengSemanticSubjectKey subject_key =
        feng_semantic_subject_key_for_type_decl(t->decl);
    const FengSpecWitness *witness = t->is_generic_instance
        ? NULL
        : feng_semantic_lookup_spec_witness(cg->analysis, &subject_key, s->decl);

    /* Emit one thunk per spec method member (in spec member order). Field
     * accessor thunks are deferred to 4b-β. */
    char *t_san = cg_sanitize(t->feng_name, strlen(t->feng_name));
    const char *spec_unique_name = s->generic_context_type_param_count > 0U && s->c_aggregate_desc_name
        ? s->c_aggregate_desc_name
        : s->feng_name;
    char *s_san = cg_sanitize(spec_unique_name, strlen(spec_unique_name));
    if (!t_san || !s_san) { free(t_san); free(s_san); return false; }

    /* Per-thunk symbol prefix scoped by both the implementing type and the
     * target spec to keep multiple (T, S) pairings non-colliding. */
    Buf prefix; buf_init(&prefix);
    buf_append_fmt(&prefix, "FengSpecThunk__%s__%s__as__%s__%s",
                   cg->module_mangle, t_san, cg->module_mangle, s_san);

    /* Iterate stable Codegen slots and recover each logical Semantic
     * requirement by exact declaration identity. Methods get one thunk;
     * fields get a getter and (for `var`) a setter. */
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        CGWitnessBinding binding;
        bool witness_mapping_ambiguous = false;
        const FengSpecWitnessMember *wm = witness != NULL
            ? cg_spec_witness_member_for_slot(
                  witness, sm, &witness_mapping_ambiguous)
            : NULL;

        memset(&binding, 0, sizeof binding);
        if (witness != NULL && !witness_mapping_ambiguous) {
            if (wm == NULL) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0339", "codegen: internal: witness requirement mapping is missing for (%s, %s) member '%s'",
                    t->feng_name, s->feng_name, sm->feng_name);
            }
            if (!wm->impl_member) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0315", "codegen: type '%s' is missing an implementation for spec '%s' member '%s'",
                    t->feng_name, s->feng_name, sm->feng_name);
            }
            binding.source_kind = wm->source_kind;
            if (wm->source_kind == FENG_SPEC_WITNESS_SOURCE_FIT_METHOD) {
                const UserFit *uf = cg_find_user_fit_by_decl_and_target(cg,
                                                                        wm->via_fit_decl,
                                                                        t);

                if (uf == NULL || uf->target != t) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return cg_fail(cg, blame,
                        "CE0340", "codegen: internal: fit decl for spec '%s' member '%s' not registered for type '%s'",
                        s->feng_name, sm->feng_name, t->feng_name);
                }
                binding.fit = uf;
                for (size_t k = 0; k < uf->method_count; ++k) {
                    if (uf->methods[k].member == wm->impl_member) {
                        binding.method = &uf->methods[k];
                        break;
                    }
                }
                if (binding.method == NULL) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return cg_fail(cg, blame,
                        "CE0341", "codegen: internal: fit method '%s' not found in fit body for type '%s'",
                        sm->feng_name, t->feng_name);
                }
            } else if (sm->kind == USM_KIND_METHOD) {
                if (sm->is_static) {
                    binding.method = cg_user_type_static_method_by_member(t, wm->impl_member);
                } else {
                    binding.method = cg_user_type_method_by_member(t, wm->impl_member);
                }
                if (binding.method == NULL) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return cg_fail(cg, blame,
                        "CE0342", "codegen: internal: type '%s' has no method '%s' to satisfy spec '%s'",
                        t->feng_name, sm->feng_name, s->feng_name);
                }
            } else if (sm->kind == USM_KIND_FIELD) {
                if (sm->is_static) {
                    /* Static fields are stored as type-level bindings, not as
                     * instance UserFields. fit cannot declare static let/var,
                     * so TYPE_OWN_FIELD is the only source kind encountered. */
                    binding.static_binding = cg_user_type_static_binding(t,
                        wm->impl_member->as.field.name.data,
                        wm->impl_member->as.field.name.length);
                    if (binding.static_binding == NULL) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return cg_fail(cg, blame,
                            "CE0343", "codegen: internal: type '%s' has no static field '%s' to satisfy spec '%s'",
                            t->feng_name, sm->feng_name, s->feng_name);
                    }
                } else {
                    binding.field = cg_user_type_field(t,
                                                       wm->impl_member->as.field.name.data,
                                                       wm->impl_member->as.field.name.length);
                    if (binding.field == NULL) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return cg_fail(cg, blame,
                            "CE0343", "codegen: internal: type '%s' has no field '%s' to satisfy spec '%s'",
                            t->feng_name, sm->feng_name, s->feng_name);
                    }
                }
            }
        } else if (!cg_resolve_witness_binding_fallback(cg, t, s, sm, blame, &binding)) {
            buf_free(&prefix); free(t_san); free(s_san);
            return false;
        }
        if (witness != NULL && !witness_mapping_ambiguous &&
            !cg_witness_binding_matches_exact_spec_slot(
                cg, &binding, s, sm) &&
            !cg_resolve_witness_binding_fallback(
                cg, t, s, sm, blame, &binding)) {
            buf_free(&prefix); free(t_san); free(s_san);
            return false;
        }

        if (sm->is_static) {
            if (!cg_emit_static_user_spec_member_thunk(
                    cg, t, s, sm, &binding, prefix.data, blame)) {
                buf_free(&prefix); free(t_san); free(s_san);
                return false;
            }
            continue;
        }

        if (binding.source_kind == FENG_SPEC_WITNESS_SOURCE_FIT_METHOD) {
            /* Step 4b-γ — fit-provided method. The fit body emits the
             * implementation as `<fit_prefix>__<member>(struct T *self, ...)`
             * (see cg_register_user_fit_members / cg_emit_user_fit_methods);
             * the witness thunk just adapts the void* subject and forwards. */
            if (sm->kind != USM_KIND_METHOD) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0344", "codegen: spec field '%s' cannot be satisfied by a fit method",
                    sm->feng_name);
            }
            const UserFit *uf = binding.fit;
            const UserMethod *fm = binding.method;

            if (!uf || uf->target != t) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0345", "codegen: internal: fit binding for spec '%s' member '%s' not registered for type '%s'",
                    s->feng_name, sm->feng_name, t->feng_name);
            }
            if (!fm) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0341", "codegen: internal: fit method '%s' not found in fit body for type '%s'",
                    sm->feng_name, t->feng_name);
            }
            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                Buf *fp = &cg->fn_protos;
                buf_append_fmt(fp, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0; pi < sm->param_count; pi++) {
                    buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fp, " p%zu", pi);
                }
                buf_append_cstr(fp, ", void *_out);\n");

                Buf *fd = &cg->witness_defs;
                buf_append_fmt(fd, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0; pi < sm->param_count; pi++) {
                    buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fd, " p%zu", pi);
                }
                buf_append_cstr(fd, ", void *_out) {\n    ");
                cg_emit_c_type(fd, fm->return_type);
                buf_append_fmt(fd, " _ret = %s((struct %s *)_subject",
                               fm->c_name, t->c_struct_name);
                cg_append_managed_witness_owner_descriptor(fd, t);
                for (size_t pi = 0; pi < sm->param_count; pi++) {
                    char pname[32];
                    snprintf(pname, sizeof pname, "p%zu", pi);
                    buf_append_cstr(fd, ", ");
                    if (!cg_append_witness_forward_arg(cg,
                                                       fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                       blame)) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return false;
                    }
                }
                buf_append_cstr(fd, ");\n    memcpy(_out, &_ret, sizeof _ret);\n}\n\n");
                continue;
            }
            Buf *fp = &cg->fn_protos;
            buf_append_cstr(fp, "static ");
            cg_emit_c_type(fp, sm->type);
            buf_append_fmt(fp, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0; pi < sm->param_count; pi++) {
                buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fp, " p%zu", pi);
            }
            buf_append_cstr(fp, ");\n");

            Buf *fd = &cg->witness_defs;
            buf_append_cstr(fd, "static ");
            cg_emit_c_type(fd, sm->type);
            buf_append_fmt(fd, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0; pi < sm->param_count; pi++) {
                buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fd, " p%zu", pi);
            }
            buf_append_cstr(fd, ") {\n");
            if (sm->type->kind == CG_TYPE_VOID) {
                /* D6 contract: object subjects are restored by exactly one
                 * `(struct T *)_subject` cast before forwarding. */
                buf_append_fmt(fd, "    %s((struct %s *)_subject", fm->c_name, t->c_struct_name);
            } else {
                buf_append_fmt(fd, "    return %s((struct %s *)_subject",
                               fm->c_name, t->c_struct_name);
            }
            cg_append_managed_witness_owner_descriptor(fd, t);
            for (size_t pi = 0; pi < sm->param_count; pi++) {
                char pname[32];
                snprintf(pname, sizeof pname, "p%zu", pi);
                buf_append_cstr(fd, ", ");
                if (!cg_append_witness_forward_arg(cg,
                                                   fd,
                                                           sm->param_types[pi],
                                                           fm->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                   blame)) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return false;
                }
            }
            buf_append_cstr(fd, ");\n}\n\n");
            continue;
        }
        if (sm->kind == USM_KIND_METHOD) {
            if (binding.source_kind != FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0346", "codegen: spec method '%s' must be implemented by a method on '%s' (Step 4b-α)",
                    sm->feng_name, t->feng_name);
            }
            const UserMethod *um = binding.method;
            if (!um) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0342", "codegen: internal: type '%s' has no method '%s' to satisfy spec '%s'",
                    t->feng_name, sm->feng_name, s->feng_name);
            }
            if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                Buf *fp = &cg->fn_protos;
                buf_append_fmt(fp, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0; pi < sm->param_count; pi++) {
                    buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fp, " p%zu", pi);
                }
                buf_append_cstr(fp, ", void *_out);\n");

                Buf *fd = &cg->witness_defs;
                buf_append_fmt(fd, "static void %s__%s(void *_subject",
                               prefix.data, sm->c_field_name);
                for (size_t pi = 0; pi < sm->param_count; pi++) {
                    buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                    buf_append_fmt(fd, " p%zu", pi);
                }
                buf_append_cstr(fd, ", void *_out) {\n    ");
                cg_emit_c_type(fd, um->return_type);
                buf_append_fmt(fd, " _ret = %s((struct %s *)_subject",
                               um->c_name, t->c_struct_name);
                cg_append_managed_witness_owner_descriptor(fd, t);
                for (size_t pi = 0; pi < sm->param_count; pi++) {
                    char pname[32];
                    snprintf(pname, sizeof pname, "p%zu", pi);
                    buf_append_cstr(fd, ", ");
                    if (!cg_append_witness_forward_arg(cg,
                                                       fd,
                                                           sm->param_types[pi],
                                                           um->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                       blame)) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return false;
                    }
                }
                buf_append_cstr(fd, ");\n    memcpy(_out, &_ret, sizeof _ret);\n}\n\n");
                continue;
            }
            /* Forward declaration — body is emitted in cg_emit_user_method. */
            Buf *fp = &cg->fn_protos;
            buf_append_cstr(fp, "static ");
            cg_emit_c_type(fp, sm->type);
            buf_append_fmt(fp, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0; pi < sm->param_count; pi++) {
                buf_append_cstr(fp, ", ");
                        cg_emit_callable_abi_param_type(fp,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fp, " p%zu", pi);
            }
            buf_append_cstr(fp, ");\n");

            /* Body — emitted into witness_defs to avoid splicing into whatever
             * function body cur_body currently points at. */
            Buf *fd = &cg->witness_defs;
            buf_append_cstr(fd, "static ");
            cg_emit_c_type(fd, sm->type);
            buf_append_fmt(fd, " %s__%s(void *_subject", prefix.data, sm->c_field_name);
            for (size_t pi = 0; pi < sm->param_count; pi++) {
                buf_append_cstr(fd, ", ");
                        cg_emit_callable_abi_param_type(fd,
                                                        sm->param_types[pi],
                                                        sm->param_abi_kinds[pi]);
                buf_append_fmt(fd, " p%zu", pi);
            }
            buf_append_cstr(fd, ") {\n");
            if (sm->type->kind == CG_TYPE_VOID) {
                buf_append_fmt(fd, "    %s((struct %s *)_subject", um->c_name, t->c_struct_name);
            } else {
                buf_append_fmt(fd, "    return %s((struct %s *)_subject",
                               um->c_name, t->c_struct_name);
            }
            cg_append_managed_witness_owner_descriptor(fd, t);
            for (size_t pi = 0; pi < sm->param_count; pi++) {
                char pname[32];
                snprintf(pname, sizeof pname, "p%zu", pi);
                buf_append_cstr(fd, ", ");
                if (!cg_append_witness_forward_arg(cg,
                                                   fd,
                                                           sm->param_types[pi],
                                                           um->param_types[pi],
                                                           sm->param_abi_kinds[pi],
                                                           pname,
                                                   blame)) {
                    buf_free(&prefix); free(t_san); free(s_san);
                    return false;
                }
            }
            buf_append_cstr(fd, ");\n}\n\n");
        } else if (sm->kind == USM_KIND_FIELD) {
            /* Step 4b-β — TYPE_OWN_FIELD witness. The implementing field
             * lives directly on T; locate it by Feng name to recover the
             * sanitised C field identifier. */
            if (binding.source_kind != FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_FIELD) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0347", "codegen: spec field '%s' must be satisfied by a field on '%s'",
                    sm->feng_name, t->feng_name);
            }
            const UserField *uf = binding.field;
            if (!uf) {
                buf_free(&prefix); free(t_san); free(s_san);
                return cg_fail(cg, blame,
                    "CE0343", "codegen: internal: type '%s' has no field '%s' to satisfy spec '%s'",
                    t->feng_name, sm->feng_name, s->feng_name);
            }

            /* Storage-borrow fields return their implementing field address;
             * ordinary reference fields retain the existing getter ABI. */
            Buf *fd = &cg->witness_defs;
            Buf *fp = &cg->fn_protos;
            if (cg_spec_field_uses_storage_borrow(sm)) {
                buf_append_fmt(fd,
                               "static void *%s__borrow_%s"
                               "(void *_subject) {\n"
                               "    return &((struct %s *)_subject)->%s;\n"
                               "}\n\n",
                               prefix.data,
                               sm->c_field_name,
                               t->c_struct_name,
                               uf->c_name);
                buf_append_fmt(fp,
                               "static void *%s__borrow_%s"
                               "(void *_subject);\n",
                               prefix.data,
                               sm->c_field_name);
            } else {
                buf_append_cstr(fd, "static ");
                cg_emit_c_type(fd, sm->type);
                buf_append_fmt(fd, " %s__get_%s(void *_subject) {\n",
                               prefix.data, sm->c_field_name);
                buf_append_fmt(fd,
                               "    return ((struct %s *)_subject)->%s;\n",
                               t->c_struct_name, uf->c_name);
                buf_append_cstr(fd, "}\n\n");

                buf_append_cstr(fp, "static ");
                cg_emit_c_type(fp, sm->type);
                buf_append_fmt(fp, " %s__get_%s(void *_subject);\n",
                               prefix.data, sm->c_field_name);
            }

            if (sm->is_var) {
                /* Setter: managed slots route through feng_assign so the
                 * old reference is released and the new one retained
                 * atomically; trivial slots use a direct store. Its C
                 * signature follows the spec's stable declaration ABI,
                 * while storage operations use the closed implementation
                 * field type. */
                buf_append_fmt(fd, "static void %s__set_%s(void *_subject, ",
                               prefix.data, sm->c_field_name);
                cg_emit_callable_abi_param_type(fd,
                                                sm->type,
                                                sm->value_abi_kind);
                buf_append_cstr(fd, " value) {\n");
                if (cgtype_is_managed(uf->type)) {
                    buf_append_fmt(fd,
                        "    feng_assign((void **)&((struct %s *)_subject)->%s, ",
                        t->c_struct_name, uf->c_name);
                    cg_append_callable_abi_argument_value(fd,
                                                          uf->type,
                                                          sm->value_abi_kind,
                                                          "value");
                    buf_append_cstr(fd, ");\n");
                } else if (cgtype_is_aggregate(uf->type)) {
                    const char *agg_desc = cg_aggregate_desc_name(uf->type);
                    if (agg_desc == NULL) {
                        buf_free(&prefix); free(t_san); free(s_san);
                        return cg_fail(cg, blame,
                            "CE0348", "codegen: missing aggregate descriptor for spec field write");
                    }
                    buf_append_fmt(fd,
                        "    feng_aggregate_assign(&((struct %s *)_subject)->%s, ",
                        t->c_struct_name, uf->c_name);
                    if (sm->value_abi_kind == CG_CALLABLE_ABI_ADDRESS) {
                        buf_append_cstr(fd, "value");
                    } else {
                        buf_append_cstr(fd, "&value");
                    }
                    buf_append_fmt(fd, ", &%s);\n", agg_desc);
                } else {
                    buf_append_fmt(fd, "    ((struct %s *)_subject)->%s = ",
                                   t->c_struct_name, uf->c_name);
                    cg_append_callable_abi_argument_value(fd,
                                                          uf->type,
                                                          sm->value_abi_kind,
                                                          "value");
                    buf_append_cstr(fd, ";\n");
                }
                buf_append_cstr(fd, "}\n\n");

                buf_append_fmt(fp, "static void %s__set_%s(void *_subject, ",
                               prefix.data, sm->c_field_name);
                cg_emit_callable_abi_param_type(fp,
                                                sm->type,
                                                sm->value_abi_kind);
                buf_append_cstr(fp, " value);\n");
            }
        }
    }

    /* Ensure the direct-parent witness closure for the same subject before
     * initializing this table. Existing (T,S) caching deduplicates diamonds. */
    const char **parent_witness_vars = NULL;
    if (s->direct_parent_spec_count > 0U) {
        parent_witness_vars = (const char **)calloc(
            s->direct_parent_spec_count,
            sizeof(*parent_witness_vars));
        if (parent_witness_vars == NULL) {
            buf_free(&prefix); free(t_san); free(s_san);
            return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        if (parent_spec == NULL ||
            !cg_ensure_witness_instance_for_type(
                cg,
                t,
                parent_spec,
                blame,
                &parent_witness_vars[parent_index])) {
            free(parent_witness_vars);
            buf_free(&prefix); free(t_san); free(s_san);
            return false;
        }
    }

    /* Witness table instance. */
    Buf var; buf_init(&var);
    buf_append_fmt(&var, "FengWitness__%s__%s__as__%s__%s",
                   cg->module_mangle, t_san, cg->module_mangle, s_san);

    Buf *fd = &cg->witness_defs;
    buf_append_fmt(fd, "static const struct %s %s = {\n",
                   s->c_witness_struct_name, var.data);
    /* Forward-declare the table in headers so type descriptors and
     * function bodies can reference it (both precede witness_defs
     * in cg_finalize output order). */
    buf_append_fmt(&cg->headers, "static const struct %s %s;\n",
                   s->c_witness_struct_name, var.data);
    for (size_t i = 0; i < s->member_count; i++) {
        const UserSpecMember *sm = &s->members[i];
        if (sm->kind == USM_KIND_METHOD) {
            buf_append_fmt(fd, "    .%s = &%s__%s,\n",
                           sm->c_field_name, prefix.data, sm->c_field_name);
        } else if (sm->kind == USM_KIND_FIELD) {
            if (cg_spec_field_uses_storage_borrow(sm)) {
                buf_append_fmt(fd, "    .borrow_%s = &%s__borrow_%s,\n",
                               sm->c_field_name, prefix.data,
                               sm->c_field_name);
            } else {
                buf_append_fmt(fd, "    .get_%s = &%s__get_%s,\n",
                               sm->c_field_name, prefix.data,
                               sm->c_field_name);
            }
            if (sm->is_var) {
                buf_append_fmt(fd, "    .set_%s = &%s__set_%s,\n",
                               sm->c_field_name, prefix.data, sm->c_field_name);
            }
        }
    }
    for (size_t parent_index = 0U;
         parent_index < s->direct_parent_spec_count;
         ++parent_index) {
        const UserSpec *parent_spec =
            cg_user_spec_direct_parent(cg, s, parent_index);

        buf_append_cstr(fd, "    .");
        cg_append_spec_parent_field_name(fd, parent_spec);
        buf_append_fmt(fd, " = &%s,\n", parent_witness_vars[parent_index]);
    }
    buf_append_cstr(fd, "};\n\n");
    free(parent_witness_vars);

    /* Cache. */
    if (cg->witness_table_count + 1 > cg->witness_table_capacity) {
        size_t cap = cg->witness_table_capacity ? cg->witness_table_capacity * 2 : 4;
        void *p = realloc(cg->witness_tables, cap * sizeof *cg->witness_tables);
        if (!p) { buf_free(&prefix); buf_free(&var); free(t_san); free(s_san); return false; }
        cg->witness_tables = p;
        cg->witness_table_capacity = cap;
    }
    cg->witness_tables[cg->witness_table_count].t = t;
    cg->witness_tables[cg->witness_table_count].s = s;
    cg->witness_tables[cg->witness_table_count].c_var = var.data;
    *out_var = var.data;
    cg->witness_table_count++;

    buf_free(&prefix); free(t_san); free(s_san);
    return true;
}

/* --- Multi-program emission helpers (P3) ---------------------------------
 *
 * The pipeline below is structured so that every name minted by Pass 1/1.5/
 * 2.7/2b/4 uses the OWNING program's module mangle (set via
 * `cg_emit_module_header`), while passes that operate on already-registered
 * shells (member registration and emission) are program-agnostic and run
 * once across the global cg arrays.
 */

static bool cg_pass_register_type_shells(CG *cg, const FengProgram *prog) {
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];
        if (d->kind == FENG_DECL_TYPE) {
            /* G6: generic types are stored separately and not monomorphized
             * during registration — they are emitted on demand at call sites. */
            if (d->as.type_decl.type_param_count > 0) {
                if (!cg_register_generic_type_decl(cg, d)) return false;
            } else {
                if (!cg_register_user_type_shell(cg, d)) return false;
            }
        }
    }
    /* Pass 1.5: register every spec SHELL (Step 4b). Specs may appear before
     * or after the types that implement them; registering shells first lets
     * cg_resolve_type see both kinds during member-pass type resolution. */
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];
        if (d->kind == FENG_DECL_SPEC) {
            if (d->as.spec_decl.type_param_count > 0) {
                if (!cg_register_generic_spec_decl(cg, d)) return false;
                continue;
            }
            if (!cg_register_user_spec_shell(cg, d)) return false;
        }
    }
    cg->cur_program = NULL;
    return true;
}

static bool cg_collect_generic_instances_from_expr(CG *cg, const FengExpr *expr,
                                                   CGTypeParamScope scope);
static bool cg_collect_generic_instances_from_stmt(CG *cg, const FengStmt *stmt,
                                                   CGTypeParamScope scope);
static bool cg_collect_generic_instances_from_block(CG *cg, const FengBlock *block,
                                                    CGTypeParamScope scope);

/* Collect generic instances using the source program that owns each named
 * reference, rather than the program that later requests an instantiation. */
static bool cg_collect_generic_instances_from_type_ref_from_program(
    CG *cg,
    const FengTypeRef *ref,
    CGTypeParamScope scope,
    const FengProgram *reference_program) {
    if (ref == NULL) return true;
    switch (ref->kind) {
        case FENG_TYPE_REF_NAMED:
            for (size_t i = 0; i < ref->as.named.type_arg_count; ++i) {
                if (!cg_collect_generic_instances_from_type_ref_from_program(
                        cg,
                        ref->as.named.type_args[i],
                        scope,
                        reference_program)) {
                    return false;
                }
            }
            if (ref->as.named.type_arg_count > 0U) {
                bool contains_type_param = cg_type_ref_contains_type_param(ref, &scope);
                CGNamedGenericTarget target =
                    cg_resolve_named_generic_target_from_program(
                        cg, ref, reference_program);

                if (target.kind == CG_NAMED_GENERIC_TARGET_TYPE) {
                    return cg_register_generic_type_instance_shell(cg,
                                                                  target.type,
                                                                  ref->as.named.type_args,
                                                                  ref->as.named.type_arg_count,
                                                                  ref->token,
                                                                  contains_type_param ? &scope : NULL);
                }
                if (target.kind == CG_NAMED_GENERIC_TARGET_SPEC) {
                    return cg_register_generic_spec_instance_shell(
                        cg,
                        target.spec,
                        ref->as.named.type_args,
                        ref->as.named.type_arg_count,
                        ref->token,
                        contains_type_param ? &scope : NULL);
                }
            }
            return true;
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return cg_collect_generic_instances_from_type_ref_from_program(
                cg, ref->as.inner, scope, reference_program);
    }
    return true;
}

/**
 * Collect generic instances from a declaration-owned type expression after
 * replacing one generic-parameter domain with arguments from an instantiation
 * site.
 *
 * Non-parameter nodes keep the declaration program of source_ref, while a
 * direct substituted parameter is an opaque argument that was already
 * collected in the instantiation program before the enclosing instance was
 * registered. Walking source_ref and effective_ref together therefore keeps
 * provider declarations and consumer-supplied arguments in their respective
 * name-resolution domains without attaching package-specific exceptions.
 */
static bool cg_collect_generic_instances_from_substituted_type_ref(
    CG *cg,
    const FengTypeRef *source_ref,
    const FengTypeRef *effective_ref,
    const FengTypeParam *substituted_params,
    size_t substituted_param_count,
    CGTypeParamScope effective_scope,
    const FengProgram *source_program) {
    if (source_ref == NULL || effective_ref == NULL) {
        return source_ref == effective_ref;
    }
    if (cg_type_ref_is_direct_type_param(source_ref,
                                         substituted_params,
                                         substituted_param_count,
                                         NULL)) {
        return true;
    }
    if (source_ref->kind != effective_ref->kind) {
        return cg_fail(cg,
                       source_ref->token,
                       "IE0001",
                       "codegen: substituted type reference shape is inconsistent");
    }

    switch (source_ref->kind) {
        case FENG_TYPE_REF_NAMED: {
            CGNamedGenericTarget target;
            bool contains_type_param;

            if (source_ref->as.named.type_arg_count !=
                effective_ref->as.named.type_arg_count) {
                return cg_fail(cg,
                               source_ref->token,
                               "IE0001",
                               "codegen: substituted generic type argument count is inconsistent");
            }
            for (size_t index = 0U;
                 index < source_ref->as.named.type_arg_count;
                 ++index) {
                if (!cg_collect_generic_instances_from_substituted_type_ref(
                        cg,
                        source_ref->as.named.type_args[index],
                        effective_ref->as.named.type_args[index],
                        substituted_params,
                        substituted_param_count,
                        effective_scope,
                        source_program)) {
                    return false;
                }
            }
            if (source_ref->as.named.type_arg_count == 0U) {
                return true;
            }

            target = cg_resolve_named_generic_target_from_program(
                cg, source_ref, source_program);
            contains_type_param = cg_type_ref_contains_type_param(
                effective_ref, &effective_scope);
            if (target.kind == CG_NAMED_GENERIC_TARGET_TYPE) {
                return cg_register_generic_type_instance_shell(
                    cg,
                    target.type,
                    effective_ref->as.named.type_args,
                    effective_ref->as.named.type_arg_count,
                    source_ref->token,
                    contains_type_param ? &effective_scope : NULL);
            }
            if (target.kind == CG_NAMED_GENERIC_TARGET_SPEC) {
                return cg_register_generic_spec_instance_shell(
                    cg,
                    target.spec,
                    effective_ref->as.named.type_args,
                    effective_ref->as.named.type_arg_count,
                    source_ref->token,
                    contains_type_param ? &effective_scope : NULL);
            }
            return true;
        }
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return cg_collect_generic_instances_from_substituted_type_ref(
                cg,
                source_ref->as.inner,
                effective_ref->as.inner,
                substituted_params,
                substituted_param_count,
                effective_scope,
                source_program);
    }
    return true;
}

/* Collect generic instances from the program currently being emitted. */
static bool cg_collect_generic_instances_from_type_ref(CG *cg,
                                                       const FengTypeRef *ref,
                                                       CGTypeParamScope scope) {
    return cg_collect_generic_instances_from_type_ref_from_program(
        cg, ref, scope, cg != NULL ? cg->cur_program : NULL);
}

/* Register the generic root of one type-parameter constraint before walking
 * its nested type arguments. A nested open type may need to resolve the same
 * surrounding constraint while its shell is being created, so the constraint
 * shell must already be discoverable through the ordinary registry. */
static bool cg_register_generic_constraint_root_from_program(
    CG *cg,
    const FengTypeRef *constraint,
    CGTypeParamScope scope,
    const FengProgram *reference_program) {
    CGNamedGenericTarget target;
    bool contains_type_param;

    if (constraint == NULL || constraint->kind != FENG_TYPE_REF_NAMED ||
        constraint->as.named.type_arg_count == 0U) {
        return true;
    }
    target = cg_resolve_named_generic_target_from_program(
        cg, constraint, reference_program);
    contains_type_param = cg_type_ref_contains_type_param(constraint, &scope);
    if (target.kind == CG_NAMED_GENERIC_TARGET_TYPE) {
        return cg_register_generic_type_instance_shell(
            cg,
            target.type,
            constraint->as.named.type_args,
            constraint->as.named.type_arg_count,
            constraint->token,
            contains_type_param ? &scope : NULL);
    }
    if (target.kind == CG_NAMED_GENERIC_TARGET_SPEC) {
        return cg_register_generic_spec_instance_shell(
            cg,
            target.spec,
            constraint->as.named.type_args,
            constraint->as.named.type_arg_count,
            constraint->token,
            contains_type_param ? &scope : NULL);
    }
    return true;
}

/* Collect type-parameter constraints in their declaration program. */
static bool cg_collect_generic_instances_from_type_params_from_program(
    CG *cg,
    const FengTypeParam *type_params,
    size_t type_param_count,
    CGTypeParamScope scope,
    const FengProgram *reference_program) {
    for (size_t i = 0; i < type_param_count; ++i) {
        if (!cg_register_generic_constraint_root_from_program(
                cg,
                type_params[i].constraint,
                scope,
                reference_program)) {
            return false;
        }
    }
    for (size_t i = 0; i < type_param_count; ++i) {
        if (!cg_collect_generic_instances_from_type_ref_from_program(
                cg,
                type_params[i].constraint,
                scope,
                reference_program)) {
            return false;
        }
    }
    return true;
}

/* Collect type-parameter constraints in the current program. */
static bool cg_collect_generic_instances_from_type_params(
    CG *cg,
    const FengTypeParam *type_params,
    size_t type_param_count,
    CGTypeParamScope scope) {
    return cg_collect_generic_instances_from_type_params_from_program(
        cg,
        type_params,
        type_param_count,
        scope,
        cg != NULL ? cg->cur_program : NULL);
}

/* Type facts for inferred bindings can preserve an unsubstituted callee type
 * parameter (for example an imported method return `T`) even outside that
 * callee's scope.  Only facts whose complete type tree resolves to concrete
 * builtin or declared types are safe inputs to the pre-emission instance
 * collector. */
static bool cg_type_ref_is_concrete_for_instance_collection(
    CG *cg,
    const FengTypeRef *ref) {
    if (ref == NULL) {
        return false;
    }
    if (ref->kind == FENG_TYPE_REF_ARRAY ||
        ref->kind == FENG_TYPE_REF_POINTER) {
        return cg_type_ref_is_concrete_for_instance_collection(cg,
                                                               ref->as.inner);
    }
    if (ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.segment_count == 0U) {
        return false;
    }
    for (size_t i = 0U; i < ref->as.named.type_arg_count; ++i) {
        if (!cg_type_ref_is_concrete_for_instance_collection(
                cg, ref->as.named.type_args[i])) {
            return false;
        }
    }
    if (ref->as.named.type_arg_count > 0U) {
        return cg_find_generic_type_decl(cg, ref) != NULL ||
               cg_find_generic_spec_decl(cg, ref) != NULL;
    }
    if (ref->as.named.segment_count == 1U) {
        const FengSlice name = ref->as.named.segments[0];

        for (size_t i = 0U;
             i < sizeof k_builtin_types / sizeof k_builtin_types[0];
             ++i) {
            if (strlen(k_builtin_types[i].name) == name.length &&
                memcmp(k_builtin_types[i].name, name.data, name.length) == 0) {
                return true;
            }
        }
    }
    return cg_find_user_type_by_ref(cg, ref) != NULL ||
           cg_find_user_spec_by_ref(cg, ref) != NULL ||
           cg_find_enum_decl_by_ref(cg, ref) != NULL;
}

static bool cg_collect_generic_instances_from_binding(CG *cg,
                                                      const FengBinding *binding,
                                                      CGTypeParamScope scope) {
    const FengTypeRef *inferred_type = binding->type;

    if (inferred_type == NULL && cg->analysis != NULL) {
        const FengSemanticTypeFact *fact =
            feng_semantic_lookup_type_fact(cg->analysis, binding);

        if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF &&
            cg_type_ref_is_concrete_for_instance_collection(cg,
                                                            fact->type_ref)) {
            inferred_type = fact->type_ref;
        }
    }
    return cg_collect_generic_instances_from_type_ref(cg, inferred_type, scope) &&
           cg_collect_generic_instances_from_expr(cg, binding->initializer, scope);
}

static bool cg_collect_generic_instances_from_callable(CG *cg,
                                                       const FengCallableSignature *callable,
                                                       CGTypeParamScope outer_scope) {
    CGTypeParamScope scope = outer_scope;
    scope.second = callable->type_params;
    scope.second_count = callable->type_param_count;
    if (!cg_collect_generic_instances_from_type_params(cg,
                                                       callable->type_params,
                                                       callable->type_param_count,
                                                       scope)) {
        return false;
    }
    for (size_t i = 0; i < callable->param_count; ++i) {
        if (!cg_collect_generic_instances_from_type_ref(cg, callable->params[i].type, scope)) {
            return false;
        }
    }
    if (!cg_collect_generic_instances_from_type_ref(cg, callable->return_type, scope) ||
        !cg_collect_generic_instances_from_block(cg, callable->body, scope)) {
        return false;
    }
    if (!cg_register_open_generic_type_instances_in_ref(cg,
                                                        callable->return_type,
                                                        &scope,
                                                        callable->token)) {
        return false;
    }
    for (size_t i = 0; i < callable->param_count; ++i) {
        if (!cg_register_open_generic_type_instances_in_ref(cg,
                                                            callable->params[i].type,
                                                            &scope,
                                                            callable->params[i].token)) {
            return false;
        }
    }
    return true;
}

static bool cg_collect_generic_instances_from_expr(CG *cg, const FengExpr *expr,
                                                   CGTypeParamScope scope) {
    if (expr == NULL) return true;
    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
        case FENG_EXPR_SELF:
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
            return true;
        case FENG_EXPR_ARRAY_LITERAL:
            for (size_t i = 0; i < expr->as.array_literal.count; ++i) {
                if (!cg_collect_generic_instances_from_expr(cg,
                                                           expr->as.array_literal.items[i],
                                                           scope)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_TUPLE_LITERAL:
            for (size_t i = 0; i < expr->as.tuple_literal.count; ++i) {
                if (!cg_collect_generic_instances_from_expr(cg,
                                                           expr->as.tuple_literal.items[i],
                                                           scope)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_OBJECT_LITERAL:
            if (!cg_collect_generic_instances_from_expr(cg, expr->as.object_literal.target, scope)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.object_literal.field_count; ++i) {
                if (!cg_collect_generic_instances_from_expr(cg,
                                                           expr->as.object_literal.fields[i].value,
                                                           scope)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_GENERIC_TARGET:
            {
                size_t segment_count = 0U;
                FengSlice *segments = cg_expr_path_segments_alloc(expr->as.generic_target.target,
                                                                  &segment_count);
                bool ok = true;

                if (segments != NULL && segment_count > 0U) {
                    FengTypeRef target_ref;

                    memset(&target_ref, 0, sizeof(target_ref));
                    target_ref.token = expr->token;
                    target_ref.kind = FENG_TYPE_REF_NAMED;
                    target_ref.as.named.segments = segments;
                    target_ref.as.named.segment_count = segment_count;
                    target_ref.as.named.type_args = expr->as.generic_target.type_args;
                    target_ref.as.named.type_arg_count = expr->as.generic_target.type_arg_count;
                    ok = cg_collect_generic_instances_from_type_ref(cg, &target_ref, scope);
                }
                free(segments);
                if (!ok) {
                    return false;
                }
            }
            for (size_t i = 0; i < expr->as.generic_target.type_arg_count; ++i) {
                if (!cg_collect_generic_instances_from_type_ref(cg,
                                                               expr->as.generic_target.type_args[i],
                                                               scope)) {
                    return false;
                }
            }
            return cg_collect_generic_instances_from_expr(cg,
                                                          expr->as.generic_target.target,
                                                          scope);
        case FENG_EXPR_CALL:
            if (!cg_collect_generic_instances_from_type_ref(
                    cg,
                    expr->as.call.resolved_callable.owner_instance_type_ref,
                    scope)) {
                return false;
            }
            for (size_t i = 0U;
                 i < expr->as.call.resolved_callable.callable_type_arg_count;
                 ++i) {
                if (!cg_collect_generic_instances_from_type_ref(
                        cg,
                        expr->as.call.resolved_callable.callable_type_args[i],
                        scope)) {
                    return false;
                }
            }
            if (expr->as.call.has_explicit_type_args) {
                for (size_t i = 0; i < expr->as.call.explicit_type_arg_count; ++i) {
                    if (!cg_collect_generic_instances_from_type_ref(cg,
                                                                   expr->as.call.explicit_type_args[i],
                                                                   scope)) {
                        return false;
                    }
                }
            }
            if (!cg_collect_resolved_call_reifiable_dep_instances(
                    cg, expr, scope)) {
                return false;
            }
            if (expr->as.call.resolved_callable.kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
                expr->as.call.resolved_callable.function_decl != NULL &&
                expr->as.call.resolved_callable.function_decl->kind == FENG_DECL_FUNCTION) {
                const FengCallableSignature *sig =
                    &expr->as.call.resolved_callable.function_decl->as.function_decl;
                if (sig->type_param_count > 0U) {
                    CGTypeParamScope call_scope = scope;
                    call_scope.second = sig->type_params;
                    call_scope.second_count = sig->type_param_count;
                    if (!cg_collect_generic_instances_from_type_params(cg,
                                                                       sig->type_params,
                                                                       sig->type_param_count,
                                                                       call_scope)) {
                        return false;
                    }
                }
            }
            if (expr->as.call.resolved_callable.kind == FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR &&
                expr->as.call.resolved_callable.owner_type_decl != NULL &&
                expr->as.call.resolved_callable.owner_type_decl->kind == FENG_DECL_TYPE &&
                expr->as.call.resolved_callable.owner_type_decl->as.type_decl.type_param_count > 0U &&
                expr->as.call.has_explicit_type_args) {
                const GenericTypeDecl *generic_decl =
                    cg_find_generic_type_decl_by_decl(cg,
                        expr->as.call.resolved_callable.owner_type_decl);
                bool contains_type_param;
                FengTypeRef temp_ref;
                FengSlice temp_segment;
                memset(&temp_ref, 0, sizeof temp_ref);
                if (expr->as.call.callee != NULL &&
                    expr->as.call.callee->kind == FENG_EXPR_IDENTIFIER) {
                    temp_segment = expr->as.call.callee->as.identifier;
                } else {
                    temp_segment = expr->as.call.resolved_callable.owner_type_decl->as.type_decl.name;
                }
                temp_ref.token = expr->token;
                temp_ref.kind = FENG_TYPE_REF_NAMED;
                temp_ref.as.named.segments = &temp_segment;
                temp_ref.as.named.segment_count = 1U;
                temp_ref.as.named.type_args = expr->as.call.explicit_type_args;
                temp_ref.as.named.type_arg_count = expr->as.call.explicit_type_arg_count;
                contains_type_param = cg_type_ref_contains_type_param(&temp_ref, &scope);
                if (generic_decl != NULL) {
                    if (!cg_register_generic_type_instance_shell(cg,
                                                                generic_decl,
                                                                expr->as.call.explicit_type_args,
                                                                expr->as.call.explicit_type_arg_count,
                                                                expr->token,
                                                                contains_type_param ? &scope : NULL)) {
                        return false;
                    }
                }
            }
            if (!cg_collect_generic_instances_from_expr(cg, expr->as.call.callee, scope)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.call.arg_count; ++i) {
                if (!cg_collect_generic_instances_from_expr(cg, expr->as.call.args[i], scope)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_MEMBER:
            return cg_collect_generic_instances_from_expr(cg, expr->as.member.object, scope);
        case FENG_EXPR_INDEX:
            return cg_collect_generic_instances_from_expr(cg, expr->as.index.object, scope) &&
                   cg_collect_generic_instances_from_expr(cg, expr->as.index.index, scope);
        case FENG_EXPR_UNARY:
            return cg_collect_generic_instances_from_expr(cg, expr->as.unary.operand, scope);
        case FENG_EXPR_BINARY:
            return cg_collect_generic_instances_from_expr(cg, expr->as.binary.left, scope) &&
                   cg_collect_generic_instances_from_expr(cg, expr->as.binary.right, scope);
        case FENG_EXPR_LAMBDA:
            for (size_t i = 0; i < expr->as.lambda.param_count; ++i) {
                if (!cg_collect_generic_instances_from_type_ref(cg,
                                                               expr->as.lambda.params[i].type,
                                                               scope)) {
                    return false;
                }
            }
            return expr->as.lambda.is_block_body
                       ? cg_collect_generic_instances_from_block(cg, expr->as.lambda.body_block, scope)
                       : cg_collect_generic_instances_from_expr(cg, expr->as.lambda.body, scope);
        case FENG_EXPR_CAST:
            return cg_collect_generic_instances_from_type_ref(cg, expr->as.cast.type, scope) &&
                   cg_collect_generic_instances_from_expr(cg, expr->as.cast.value, scope);
        case FENG_EXPR_IF:
            return cg_collect_generic_instances_from_expr(cg, expr->as.if_expr.condition, scope) &&
                   cg_collect_generic_instances_from_block(cg, expr->as.if_expr.then_block, scope) &&
                   cg_collect_generic_instances_from_block(cg, expr->as.if_expr.else_block, scope);
        case FENG_EXPR_MATCH:
            if (!cg_collect_generic_instances_from_expr(cg, expr->as.match_expr.target, scope)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.match_expr.branch_count; ++i) {
                const FengMatchBranch *branch = &expr->as.match_expr.branches[i];
                for (size_t j = 0; j < branch->label_count; ++j) {
                    const FengMatchLabel *label = &branch->labels[j];
                    if (!cg_collect_generic_instances_from_expr(cg, label->value, scope) ||
                        !cg_collect_generic_instances_from_expr(cg, label->range_low, scope) ||
                        !cg_collect_generic_instances_from_expr(cg, label->range_high, scope)) {
                        return false;
                    }
                }
                if (!cg_collect_generic_instances_from_block(cg, branch->body, scope)) {
                    return false;
                }
            }
            return cg_collect_generic_instances_from_block(cg, expr->as.match_expr.else_block, scope);
        case FENG_EXPR_TRY:
            if (!cg_collect_generic_instances_from_expr(cg, expr->as.try_expr.body, scope)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.try_expr.clause_count; ++i) {
                const FengTryCatchClause *clause = &expr->as.try_expr.clauses[i];

                if (!cg_collect_generic_instances_from_type_ref(cg, clause->type, scope) ||
                    !cg_collect_generic_instances_from_block(cg, clause->body, scope)) {
                    return false;
                }
            }
            return true;
        case FENG_EXPR_ARRAY_NEW:
            return cg_collect_generic_instances_from_type_ref(cg,
                                                             expr->as.array_new.element_type,
                                                             scope) &&
                   cg_collect_generic_instances_from_expr(cg, expr->as.array_new.size, scope);
        case FENG_EXPR_MATCH_OP:
            if (!cg_collect_generic_instances_from_expr(cg, expr->as.match_op.target, scope)) {
                return false;
            }
            for (size_t i = 0; i < expr->as.match_op.label_count; ++i) {
                const FengMatchLabel *label = &expr->as.match_op.labels[i];
                if (!cg_collect_generic_instances_from_expr(cg, label->value, scope) ||
                    !cg_collect_generic_instances_from_expr(cg, label->range_low, scope) ||
                    !cg_collect_generic_instances_from_expr(cg, label->range_high, scope)) {
                    return false;
                }
                if (label->type != NULL &&
                    !cg_collect_generic_instances_from_type_ref(cg, label->type, scope)) {
                    return false;
                }
            }
            return true;
    }
    return true;
}

static bool cg_collect_generic_instances_from_stmt(CG *cg, const FengStmt *stmt,
                                                   CGTypeParamScope scope) {
    if (stmt == NULL) return true;
    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return cg_collect_generic_instances_from_block(cg, stmt->as.block, scope);
        case FENG_STMT_BINDING:
            return cg_collect_generic_instances_from_binding(cg, &stmt->as.binding, scope);
        case FENG_STMT_ASSIGN:
            return cg_collect_generic_instances_from_expr(cg, stmt->as.assign.target, scope) &&
                   cg_collect_generic_instances_from_expr(cg, stmt->as.assign.value, scope);
        case FENG_STMT_EXPR:
        case FENG_STMT_TRY:
            return cg_collect_generic_instances_from_expr(cg, stmt->as.expr, scope);
        case FENG_STMT_IF:
            for (size_t i = 0; i < stmt->as.if_stmt.clause_count; ++i) {
                if (!cg_collect_generic_instances_from_expr(cg,
                                                           stmt->as.if_stmt.clauses[i].condition,
                                                           scope) ||
                    !cg_collect_generic_instances_from_block(cg,
                                                            stmt->as.if_stmt.clauses[i].block,
                                                            scope)) {
                    return false;
                }
            }
            return cg_collect_generic_instances_from_block(cg, stmt->as.if_stmt.else_block, scope);
        case FENG_STMT_MATCH:
            if (!cg_collect_generic_instances_from_expr(cg, stmt->as.match_stmt.target, scope)) {
                return false;
            }
            for (size_t i = 0; i < stmt->as.match_stmt.branch_count; ++i) {
                const FengMatchBranch *branch = &stmt->as.match_stmt.branches[i];
                for (size_t j = 0; j < branch->label_count; ++j) {
                    const FengMatchLabel *label = &branch->labels[j];
                    if (!cg_collect_generic_instances_from_expr(cg, label->value, scope) ||
                        !cg_collect_generic_instances_from_expr(cg, label->range_low, scope) ||
                        !cg_collect_generic_instances_from_expr(cg, label->range_high, scope)) {
                        return false;
                    }
                }
                if (!cg_collect_generic_instances_from_block(cg, branch->body, scope)) return false;
            }
            return cg_collect_generic_instances_from_block(cg, stmt->as.match_stmt.else_block, scope);
        case FENG_STMT_WHILE:
            return cg_collect_generic_instances_from_expr(cg, stmt->as.while_stmt.condition, scope) &&
                   cg_collect_generic_instances_from_block(cg, stmt->as.while_stmt.body, scope);
        case FENG_STMT_FOR:
            return cg_collect_generic_instances_from_stmt(cg, stmt->as.for_stmt.init, scope) &&
                   cg_collect_generic_instances_from_expr(cg, stmt->as.for_stmt.condition, scope) &&
                   cg_collect_generic_instances_from_stmt(cg, stmt->as.for_stmt.update, scope) &&
                   cg_collect_generic_instances_from_binding(cg, &stmt->as.for_stmt.iter_binding, scope) &&
                   cg_collect_generic_instances_from_expr(cg, stmt->as.for_stmt.iter_expr, scope) &&
                   cg_collect_generic_instances_from_block(cg, stmt->as.for_stmt.body, scope);
        case FENG_STMT_RETURN:
            return cg_collect_generic_instances_from_expr(cg, stmt->as.return_value, scope);
        case FENG_STMT_THROW:
            return cg_collect_generic_instances_from_expr(cg, stmt->as.throw_value, scope);
        case FENG_STMT_BREAK:
        case FENG_STMT_CONTINUE:
            return true;
        case FENG_STMT_DEFER:
            return cg_collect_generic_instances_from_block(cg, stmt->as.defer_block, scope);
    }
    return true;
}

static bool cg_collect_generic_instances_from_block(CG *cg, const FengBlock *block,
                                                    CGTypeParamScope scope) {
    if (block == NULL) return true;
    for (size_t i = 0; i < block->statement_count; ++i) {
        if (!cg_collect_generic_instances_from_stmt(cg, block->statements[i], scope)) {
            return false;
        }
    }
    return true;
}

static bool cg_pass_collect_generic_type_instances(CG *cg, const FengProgram *prog) {
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; ++i) {
        const FengDecl *decl = prog->declarations[i];
        CGTypeParamScope scope = {0};
        switch (decl->kind) {
            case FENG_DECL_GLOBAL_BINDING:
                if (!cg_collect_generic_instances_from_binding(cg, &decl->as.binding, scope)) {
                    cg->cur_program = NULL;
                    return false;
                }
                break;
            case FENG_DECL_ENUM:
                break;
            case FENG_DECL_TYPE:
                scope.first = decl->as.type_decl.type_params;
                scope.first_count = decl->as.type_decl.type_param_count;
                if (!cg_collect_generic_instances_from_type_params(cg,
                                                                   decl->as.type_decl.type_params,
                                                                   decl->as.type_decl.type_param_count,
                                                                   scope)) {
                    cg->cur_program = NULL;
                    return false;
                }
                for (size_t spec_index = 0; spec_index < decl->as.type_decl.declared_spec_count; ++spec_index) {
                    if (!cg_collect_generic_instances_from_type_ref(cg,
                                                                   decl->as.type_decl.declared_specs[spec_index],
                                                                   scope)) {
                        cg->cur_program = NULL;
                        return false;
                    }
                }
                for (size_t member_index = 0; member_index < decl->as.type_decl.member_count; ++member_index) {
                    const FengTypeMember *member = decl->as.type_decl.members[member_index];
                    if (member->kind == FENG_TYPE_MEMBER_FIELD) {
                        if (!cg_collect_generic_instances_from_type_ref(cg, member->as.field.type, scope) ||
                            !cg_collect_generic_instances_from_expr(cg, member->as.field.initializer, scope)) {
                            cg->cur_program = NULL;
                            return false;
                        }
                    } else if (member->kind == FENG_TYPE_MEMBER_METHOD ||
                               member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR ||
                               member->kind == FENG_TYPE_MEMBER_FINALIZER) {
                        if (!cg_collect_generic_instances_from_callable(cg, &member->as.callable, scope)) {
                            cg->cur_program = NULL;
                            return false;
                        }
                    }
                }
                break;
            case FENG_DECL_SPEC:
                scope.first = decl->as.spec_decl.type_params;
                scope.first_count = decl->as.spec_decl.type_param_count;
                if (!cg_collect_generic_instances_from_type_params(cg,
                                                                   decl->as.spec_decl.type_params,
                                                                   decl->as.spec_decl.type_param_count,
                                                                   scope)) {
                    cg->cur_program = NULL;
                    return false;
                }
                for (size_t parent_index = 0; parent_index < decl->as.spec_decl.parent_spec_count; ++parent_index) {
                    if (!cg_collect_generic_instances_from_type_ref(cg,
                                                                   decl->as.spec_decl.parent_specs[parent_index],
                                                                   scope)) {
                        cg->cur_program = NULL;
                        return false;
                    }
                }
                if (decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
                    for (size_t member_index = 0; member_index < decl->as.spec_decl.as.object.member_count; ++member_index) {
                        const FengTypeMember *member = decl->as.spec_decl.as.object.members[member_index];
                        if (member->kind == FENG_TYPE_MEMBER_FIELD) {
                            if (!cg_collect_generic_instances_from_type_ref(cg, member->as.field.type, scope)) {
                                cg->cur_program = NULL;
                                return false;
                            }
                        } else if (member->kind == FENG_TYPE_MEMBER_METHOD) {
                            if (!cg_collect_generic_instances_from_callable(cg, &member->as.callable, scope)) {
                                cg->cur_program = NULL;
                                return false;
                            }
                        }
                    }
                } else if (decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
                    for (size_t member_index = 0U;
                         member_index < decl->as.spec_decl.as.union_form.member_count;
                         ++member_index) {
                        if (!cg_collect_generic_instances_from_type_ref(cg,
                            decl->as.spec_decl.as.union_form.members[member_index],
                            scope)) {
                            cg->cur_program = NULL;
                            return false;
                        }
                    }
                } else if (decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                    for (size_t member_index = 0U;
                         member_index < decl->as.spec_decl.as.intersection_form.member_count;
                         ++member_index) {
                        if (!cg_collect_generic_instances_from_type_ref(cg,
                            decl->as.spec_decl.as.intersection_form.members[member_index],
                            scope)) {
                            cg->cur_program = NULL;
                            return false;
                        }
                    }
                } else {
                    for (size_t param_index = 0; param_index < decl->as.spec_decl.as.callable.param_count; ++param_index) {
                        if (!cg_collect_generic_instances_from_type_ref(cg,
                            decl->as.spec_decl.as.callable.params[param_index].type,
                            scope)) {
                            cg->cur_program = NULL;
                            return false;
                        }
                    }
                    if (!cg_collect_generic_instances_from_type_ref(cg,
                        decl->as.spec_decl.as.callable.return_type,
                        scope)) {
                        cg->cur_program = NULL;
                        return false;
                    }
                }
                break;
            case FENG_DECL_FIT:
                {
                    /* When the fit target is a builtin array (e.g. `fit T[]`),
                     * cg_builtin_fit_target_local_type_param writes a synthetic
                     * FengTypeParam into local_type_param and stores its
                     * address into scope.first. The subsequent calls to
                     * cg_collect_generic_instances_from_type_ref / _callable
                     * read through scope.first, so they must run while
                     * local_type_param is still alive — keeping every use of
                     * `scope` inside this same block guarantees that. */
                    const GenericTypeDecl *generic_target = cg_find_generic_type_decl(cg,
                                                                                     decl->as.fit_decl.target);
                    const FengDecl *target_decl = generic_target != NULL ? generic_target->decl : NULL;
                    FengTypeParam local_type_param;
                    if (target_decl != NULL && target_decl->kind == FENG_DECL_TYPE) {
                        scope.first = target_decl->as.type_decl.type_params;
                        scope.first_count = target_decl->as.type_decl.type_param_count;
                    } else if (cg_builtin_fit_target_local_type_param(
                                   cg, decl, &local_type_param)) {
                        scope.first = &local_type_param;
                        scope.first_count = 1U;
                    }
                    if (!cg_collect_generic_instances_from_type_ref(cg, decl->as.fit_decl.target, scope)) {
                        cg->cur_program = NULL;
                        return false;
                    }
                    for (size_t spec_index = 0; spec_index < decl->as.fit_decl.spec_count; ++spec_index) {
                        if (!cg_collect_generic_instances_from_type_ref(cg, decl->as.fit_decl.specs[spec_index], scope)) {
                            cg->cur_program = NULL;
                            return false;
                        }
                    }
                    for (size_t member_index = 0; member_index < decl->as.fit_decl.member_count; ++member_index) {
                        const FengTypeMember *member = decl->as.fit_decl.members[member_index];
                        if (member->kind == FENG_TYPE_MEMBER_METHOD &&
                            !cg_collect_generic_instances_from_callable(cg, &member->as.callable, scope)) {
                            cg->cur_program = NULL;
                            return false;
                        }
                    }
                }
                break;
            case FENG_DECL_FUNCTION:
                if (!cg_collect_generic_instances_from_callable(cg, &decl->as.function_decl, scope)) {
                    cg->cur_program = NULL;
                    return false;
                }
                break;
        }
    }
    cg->cur_program = NULL;
    return true;
}

static bool cg_pass_register_fit_shells(CG *cg, const FengProgram *prog) {
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];
        if (d->kind == FENG_DECL_FIT) {
            if (!cg_register_user_fit_shell(cg, d)) return false;
        }
    }
    cg->cur_program = NULL;
    return true;
}

static bool cg_pass_register_module_bindings(CG *cg,
                                             const FengProgram *prog,
                                             FengCompileTarget target) {
    if (cg_program_origin(cg, prog) == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];
        if (d->kind != FENG_DECL_GLOBAL_BINDING) continue;
        if (d->is_extern) {
            return cg_fail(cg, d->token,
                "CE0349", "codegen: extern module-level bindings not supported in Phase 1A");
        }
        if (!cg_register_module_binding(cg, d, target)) return false;
        const ModuleBinding *mb = &cg->module_bindings[cg->module_binding_count - 1];
        char *cty = cg_ctype_dup(mb->type);
        if (!cty) return cg_fail(cg, d->token, "IE0001", "codegen: out of memory");
        cg_emit_static_storage_decl(&cg->statics,
                                    mb->exports_public_surface,
                                    false,
                                    cty,
                                    mb->c_name,
                                    mb->type);
        buf_append_fmt(&cg->statics, "static bool %s = false;\n", mb->c_inited_name);
        buf_append_fmt(&cg->fn_protos,
                       "%svoid %s(void);\n",
                       mb->exports_public_surface ? "" : "static ",
                       mb->c_ensure_init_name);
        free(cty);
    }
    cg->cur_program = NULL;
    return true;
}

static bool cg_pass_emit_imported_function_decls(CG *cg, const FengProgram *prog) {
    if (cg_program_origin(cg, prog) != FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];

        if (d->kind == FENG_DECL_FUNCTION) {
            if (!cg_emit_imported_function_decl(cg, d)) {
                return false;
            }
        } else if (d->kind == FENG_DECL_GLOBAL_BINDING) {
            if (!cg_emit_imported_binding_decl(cg, d)) {
                return false;
            }
        } else if (d->kind == FENG_DECL_TYPE) {
            const UserType *type = cg_find_user_type_by_decl(cg, d);

            if (type != NULL) {
                for (size_t binding_index = 0U;
                     binding_index < type->static_binding_count;
                     ++binding_index) {
                    if (!cg_emit_imported_type_static_binding_decl(
                            cg,
                            &type->static_bindings[binding_index])) {
                        return false;
                    }
                }
            }
        }
    }
    cg->cur_program = NULL;
    return true;
}

static bool cg_pass_emit_module_binding_ensure_inits(CG *cg, const FengProgram *prog);

static bool cg_pass_emit_enum_decls(CG *cg, const FengProgram *prog) {
    if (cg_program_origin(cg, prog) == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];

        if (d->kind == FENG_DECL_ENUM && !cg_emit_enum_decl(cg, d)) {
            cg->cur_program = NULL;
            return false;
        }
    }
    cg->cur_program = NULL;
    return true;
}

/* Pass 3.9: pre-register all free functions, externs, and generic functions
 * so that cross-file references within the same module are resolved
 * before any function body is emitted in Pass 4. */
static bool cg_pass_pre_register_functions(CG *cg,
                                           const FengProgram *prog,
                                           FengCompileTarget target) {
    if (cg_program_origin(cg, prog) == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];
        if (d->kind != FENG_DECL_FUNCTION) continue;

        if (d->is_extern) {
            if (cg_find_extern_by_decl(cg, d) != NULL) continue;
            if (!cg_emit_extern_decl(cg, d)) { cg->cur_program = NULL; return false; }
        } else if (d->as.function_decl.type_param_count > 0) {
            if (!cg_find_generic_fn_by_decl(cg, d)) {
                if (!cg_register_generic_fn(cg, d)) { cg->cur_program = NULL; return false; }
            }
        } else {
            if (!cg_register_free_fn(cg, d)) { cg->cur_program = NULL; return false; }
            FreeFn *fn = &cg->free_fns[cg->free_fn_count - 1];
            bool exports_public = target == FENG_COMPILE_TARGET_LIB &&
                                  d->visibility == FENG_VISIBILITY_PUBLIC;
            bool needs_static = cg_free_fn_has_abi_wrapper(fn) ? true : !exports_public;
            cg_emit_free_fn_proto(&cg->fn_protos, fn, needs_static);
            cg_emit_free_fn_abi_proto(&cg->fn_protos, fn, !exports_public);
        }
    }
    cg->cur_program = NULL;
    return true;
}

/* Register every top-level generic callable before closed owner descriptors
 * are emitted. Descriptor graphs identify callable nodes by their final C
 * symbols, so both source and imported generic functions must already have
 * their stable overload-aware names at that point. */
static bool cg_pass_register_generic_functions_for_descriptors(
    CG *cg,
    const FengProgram *prog) {
    if (!cg_emit_module_header(cg, prog)) {
        return false;
    }
    cg->cur_program = prog;
    for (size_t index = 0U;
         index < prog->declaration_count;
         ++index) {
        const FengDecl *decl = prog->declarations[index];

        if (decl->kind != FENG_DECL_FUNCTION || decl->is_extern ||
            decl->as.function_decl.type_param_count == 0U ||
            cg_find_generic_fn_by_decl(cg, decl) != NULL) {
            continue;
        }
        if (!cg_register_generic_fn(cg, decl)) {
            cg->cur_program = NULL;
            return cg_fail(cg, decl->token,
                           "IE0001", "codegen: out of memory");
        }
    }
    cg->cur_program = NULL;
    return true;
}

/* Emit the source-package implementation of an implicit constructor for a
 * non-generic public type.  The ordinary construction call site allocates the
 * object; this entry performs exactly the member declaration-initialization
 * phase that precedes every user constructor body. */
static bool cg_emit_implicit_constructor_entry(CG *cg,
                                               const UserType *type,
                                               FengCompileTarget target) {
    FengTypeMember member;
    FengBlock body;
    UserMethod method;
    bool ok;

    if (cg == NULL || type == NULL || type->decl == NULL ||
        type->constructor_count != 0U || type->field_count == 0U ||
        target != FENG_COMPILE_TARGET_LIB ||
        type->decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return true;
    }
    memset(&member, 0, sizeof(member));
    memset(&body, 0, sizeof(body));
    memset(&method, 0, sizeof(method));
    member.token = type->decl->token;
    member.kind = FENG_TYPE_MEMBER_CONSTRUCTOR;
    member.visibility = FENG_VISIBILITY_PUBLIC;
    member.as.callable.token = type->decl->token;
    member.as.callable.name = type->decl->as.type_decl.name;
    member.as.callable.body = &body;
    body.token = type->decl->token;

    method.feng_name = strndup(member.as.callable.name.data,
                               member.as.callable.name.length);
    method.c_name = cg_implicit_constructor_cname(type);
    method.return_type = cgtype_new(CG_TYPE_VOID);
    method.member = &member;
    if (method.feng_name == NULL || method.c_name == NULL ||
        method.return_type == NULL) {
        free(method.feng_name);
        free(method.c_name);
        cgtype_free(method.return_type);
        return cg_fail(cg, member.token, "IE0001", "codegen: out of memory");
    }
    ok = cg_emit_user_method(cg, type, &method, false);
    free(method.feng_name);
    free(method.c_name);
    cgtype_free(method.return_type);
    return ok;
}

/* Emit the single shared implicit-constructor body consumed by every
 * concrete instance of an external generic type. */
static bool cg_emit_generic_implicit_constructor_entry(
    CG *cg,
    const FengDecl *decl,
    FengCompileTarget target) {
    FengTypeMember member;
    FengBlock body;
    char *shared_name;
    bool has_instance_field = false;
    bool has_constructor = false;
    bool ok;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_TYPE ||
        decl->as.type_decl.type_param_count == 0U) {
        return true;
    }
    for (size_t i = 0U; i < decl->as.type_decl.member_count; ++i) {
        const FengTypeMember *candidate = decl->as.type_decl.members[i];

        if (candidate == NULL) {
            continue;
        }
        if (candidate->kind == FENG_TYPE_MEMBER_CONSTRUCTOR) {
            has_constructor = true;
        } else if (candidate->kind == FENG_TYPE_MEMBER_FIELD &&
                   !candidate->is_static) {
            has_instance_field = true;
        }
    }
    if (has_constructor || !has_instance_field) {
        return true;
    }

    memset(&member, 0, sizeof(member));
    memset(&body, 0, sizeof(body));
    member.token = decl->token;
    member.kind = FENG_TYPE_MEMBER_CONSTRUCTOR;
    member.visibility = FENG_VISIBILITY_PUBLIC;
    member.as.callable.token = decl->token;
    member.as.callable.name = decl->as.type_decl.name;
    member.as.callable.body = &body;
    body.token = decl->token;

    shared_name = cg_generic_implicit_constructor_shared_cname(cg, decl);
    if (shared_name == NULL) {
        return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    }
    ok = cg_emit_generic_type_method_shared(
        cg, decl, &member, target, false, shared_name, NULL,
        CG_GENERIC_CONSTRUCTOR_INIT_DECLARED);
    free(shared_name);
    return ok;
}

/* Emit one shared default-zero initializer plus its allocation factory for a
 * generic managed type.  The factory is selected statically by the generic
 * origin; the closed descriptor is supplied from the caller's fixed owner
 * type-dependency slot. */
static bool cg_emit_generic_default_zero_entry(CG *cg,
                                               const FengDecl *decl,
                                               FengCompileTarget target) {
    FengTypeMember member;
    FengBlock body;
    char *init_name = NULL;
    char *factory_name = NULL;
    bool exported;
    bool ok;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_TYPE ||
        decl->as.type_decl.type_param_count == 0U ||
        cg_type_decl_is_value_semantics(decl)) {
        return true;
    }
    memset(&member, 0, sizeof(member));
    memset(&body, 0, sizeof(body));
    member.token = decl->token;
    member.kind = FENG_TYPE_MEMBER_CONSTRUCTOR;
    member.visibility = FENG_VISIBILITY_PUBLIC;
    member.as.callable.token = decl->token;
    member.as.callable.name = decl->as.type_decl.name;
    member.as.callable.body = &body;
    body.token = decl->token;

    init_name = cg_generic_default_zero_init_shared_cname(cg, decl);
    factory_name = cg_generic_default_zero_shared_cname(cg, decl);
    if (init_name == NULL || factory_name == NULL) {
        free(init_name);
        free(factory_name);
        return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    }
    ok = cg_emit_generic_type_method_shared(
        cg,
        decl,
        &member,
        target,
        false,
        init_name,
        NULL,
        CG_GENERIC_CONSTRUCTOR_INIT_DEFAULT_ZERO);
    if (!ok) {
        free(init_name);
        free(factory_name);
        return false;
    }

    exported = target == FENG_COMPILE_TARGET_LIB &&
        decl->visibility == FENG_VISIBILITY_PUBLIC;
    if (!exported) {
        buf_append_cstr(&cg->fn_protos, "static ");
    }
    buf_append_fmt(&cg->fn_protos,
                   "void *%s(const FengTypeDescriptor *_type_desc);\n",
                   factory_name);
    if (!exported) {
        buf_append_cstr(&cg->fn_defs, "static ");
    }
    buf_append_fmt(&cg->fn_defs,
                   "void *%s(const FengTypeDescriptor *_type_desc) {\n"
                   "    void *_self = feng_object_new(_type_desc);\n"
                   "    %s(_self, _type_desc);\n"
                   "    return _self;\n"
                   "}\n\n",
                   factory_name,
                   init_name);
    free(init_name);
    free(factory_name);
    return true;
}

static bool cg_pass_emit_decls(CG *cg, const FengProgram *prog,
                               FengCompileTarget target) {
    if (cg_program_origin(cg, prog) == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    /* Pass 4: walk top-level decls in source order for externs / functions /
     * methods. Type decls themselves emit only their methods here. */
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];
        switch (d->kind) {
            case FENG_DECL_GLOBAL_BINDING:
                /* Already registered + storage emitted in Pass 2b; getter
                 * bodies are emitted in a dedicated pass after free
                 * functions are registered. */
                continue;
            case FENG_DECL_ENUM:
                continue;
            case FENG_DECL_TYPE: {
                if (d->as.type_decl.type_param_count > 0) {
                    for (size_t member_index = 0U;
                         member_index < d->as.type_decl.member_count;
                         ++member_index) {
                        const FengTypeMember *member =
                            d->as.type_decl.members[member_index];

                        if (member->kind == FENG_TYPE_MEMBER_FIELD &&
                            member->is_static &&
                            !cg_emit_generic_type_static_binding_ensure_shared(
                                cg, d, member, target)) {
                            return false;
                        }
                    }
                    if (!cg_emit_generic_default_zero_entry(
                            cg, d, target)) {
                        return false;
                    }
                    if (!cg_emit_generic_implicit_constructor_entry(
                            cg, d, target)) {
                        return false;
                    }
                    for (size_t member_index = 0;
                         member_index < d->as.type_decl.member_count;
                         ++member_index) {
                        const FengTypeMember *member = d->as.type_decl.members[member_index];
                        if (member->kind != FENG_TYPE_MEMBER_METHOD &&
                            member->kind != FENG_TYPE_MEMBER_CONSTRUCTOR &&
                            member->kind != FENG_TYPE_MEMBER_FINALIZER) {
                            continue;
                        }
                        if (!cg_emit_generic_type_method_shared(
                                cg, d, member, target,
                                member->kind == FENG_TYPE_MEMBER_METHOD,
                                NULL,
                                NULL,
                                CG_GENERIC_CONSTRUCTOR_INIT_DECLARED)) return false;
                    }
                    for (size_t k = 0; k < cg->user_type_count; ++k) {
                        const UserType *ut = &cg->user_types[k];
                        if (!ut->is_generic_instance || ut->generic_origin_decl != d) continue;
                        if (cg_program_origin(cg, ut->owner_program) ==
                            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                            continue;
                        }
                        const FengProgram *saved_prog = cg->cur_program;
                        cg->cur_program = ut->instantiation_program != NULL
                            ? ut->instantiation_program
                            : ut->owner_program;
                        for (size_t ci = 0; ci < ut->constructor_count; ++ci) {
                            if (!cg_emit_generic_type_method_wrapper(cg, ut, &ut->constructors[ci], NULL, NULL, NULL)) { cg->cur_program = saved_prog; return false; }
                        }
                        for (size_t mi = 0; mi < ut->method_count; ++mi) {
                            if (!cg_emit_generic_type_method_wrapper(cg, ut, &ut->methods[mi], NULL, NULL, NULL)) { cg->cur_program = saved_prog; return false; }
                        }
                        for (size_t mi = 0; mi < ut->static_method_count; ++mi) {
                            if (!cg_emit_generic_type_method_wrapper(cg, ut, &ut->static_methods[mi], NULL, NULL, NULL)) { cg->cur_program = saved_prog; return false; }
                        }
                        if (!cg_emit_user_finalizer(cg, ut)) {
                            cg->cur_program = saved_prog;
                            return false;
                        }
                        cg->cur_program = saved_prog;
                    }
                    break;
                }
                /* Find the registered UserType by AST identity. */
                const UserType *ut = NULL;
                for (size_t k = 0; k < cg->user_type_count; k++) {
                    if (cg->user_types[k].decl == d) { ut = &cg->user_types[k]; break; }
                }
                if (!ut) return cg_fail(cg, d->token, "CE0350", "codegen: internal: type not registered");
                if (!cg_emit_implicit_constructor_entry(cg, ut, target)) {
                    return false;
                }
                for (size_t ci = 0; ci < ut->constructor_count; ci++) {
                    bool needs_static = !(target == FENG_COMPILE_TARGET_LIB &&
                                          d->visibility == FENG_VISIBILITY_PUBLIC &&
                                          ut->constructors[ci].member->visibility !=
                                              FENG_VISIBILITY_PRIVATE);
                    if (!cg_emit_user_method(cg,
                                             ut,
                                             &ut->constructors[ci],
                                             needs_static)) {
                        return false;
                    }
                }
                for (size_t mi = 0; mi < ut->method_count; mi++) {
                    bool needs_static =
                        !(target == FENG_COMPILE_TARGET_LIB &&
                          cg_member_uses_package_callable_surface(
                              cg, d, ut->methods[mi].member));
                    if (ut->methods[mi].member->as.callable.type_param_count > 0U) {
                        if (!cg_emit_generic_type_method_shared(cg,
                                                               d,
                                                               ut->methods[mi].member,
                                                               target, true, NULL, NULL,
                                                               CG_GENERIC_CONSTRUCTOR_INIT_DECLARED) ||
                            !cg_emit_generic_type_method_wrapper(cg,
                                                                 ut,
                                                                 &ut->methods[mi],
                                                                 NULL, NULL, NULL)) {
                            return false;
                        }
                    } else {
                        if (!cg_emit_user_method(cg,
                                                 ut,
                                                 &ut->methods[mi],
                                                 needs_static)) {
                            return false;
                        }
                    }
                }
                for (size_t mi = 0; mi < ut->static_method_count; mi++) {
                    bool needs_static =
                        !(target == FENG_COMPILE_TARGET_LIB &&
                          cg_member_uses_package_callable_surface(
                              cg, d, ut->static_methods[mi].member));
                    if (ut->static_methods[mi].member->as.callable.type_param_count > 0U) {
                        if (!cg_emit_generic_type_method_shared(cg,
                                                               d,
                                                               ut->static_methods[mi].member,
                                                               target, true, NULL, NULL,
                                                               CG_GENERIC_CONSTRUCTOR_INIT_DECLARED) ||
                            !cg_emit_generic_type_method_wrapper(cg,
                                                                 ut,
                                                                 &ut->static_methods[mi],
                                                                 NULL, NULL, NULL)) {
                            return false;
                        }
                    } else {
                        if (!cg_emit_user_method(cg,
                                                 ut,
                                                 &ut->static_methods[mi],
                                                 needs_static)) {
                            return false;
                        }
                    }
                }
                if (!cg_emit_user_finalizer(cg, ut)) return false;
                break;
            }
            case FENG_DECL_SPEC:
                continue;
            case FENG_DECL_FIT: {
                /* Step 4b-γ — emit each fit-body method.
                 *
                 * When the fit targets a generic type, all concrete instances
                 * share a single compiled body (shared) + per-instance thin
                 * wrappers, mirroring cg_emit_generic_type_method_shared /
                 * _wrapper for the type's own methods.  Shared bodies are
                 * emitted once (on the first UserFit entry for this decl),
                 * then each subsequent instance gets only a wrapper.
                 *
                 * Non-generic targets keep the monomorphised path via
                 * cg_emit_user_method.  Witness thunks generated by
                 * cg_ensure_witness_instance call the wrapper c_name. */
                bool emitted_fit = false;
                bool fit_shared_emitted = false;
                for (size_t fit_index = 0; fit_index < cg->user_fit_count; ++fit_index) {
                    const UserFit *uf = &cg->user_fits[fit_index];

                    if (uf->decl != d) continue;
                    emitted_fit = true;

                    if (uf->target->is_generic_instance &&
                        uf->target->generic_origin_decl != NULL) {
                        /* Generic fit: shared body + wrapper path. */
                        if (!fit_shared_emitted) {
                            /* Emit shared bodies once for all methods in this
                             * fit decl, using the origin type decl for type
                             * parameters and the fit member for the body. */
                            const FengDecl *origin = uf->target->generic_origin_decl;
                            for (size_t mi = 0; mi < uf->method_count; mi++) {
                                char *sname = cg_fit_method_shared_cname(
                                    cg, uf, uf->methods[mi].member);
                                if (!sname) return false;
                                if (!cg_emit_generic_type_method_shared(
                                        cg, origin, uf->methods[mi].member,
                                        target, true, sname, d,
                                        CG_GENERIC_CONSTRUCTOR_INIT_DECLARED)) {
                                    free(sname);
                                    return false;
                                }
                                free(sname);
                            }
                            fit_shared_emitted = true;
                        }
                        /* The open instance is the compile-time fit template:
                         * it owns the shared body but has no concrete wrapper,
                         * descriptor or witness. */
                        if (uf->target->generic_context_type_param_count > 0U) {
                            continue;
                        }

                        /* Emit per-instance wrappers. */
                        const FengProgram *saved_prog = cg->cur_program;
                        cg->cur_program = uf->target->instantiation_program != NULL
                            ? uf->target->instantiation_program
                            : uf->target->owner_program;
                        /* Every fit method owns its dependency set. A closed,
                         * non-method-generic wrapper binds the member's static
                         * descriptor; a method-generic wrapper receives the
                         * call-site descriptor through the existing ABI. */
                        for (size_t mi = 0; mi < uf->method_count; mi++) {
                            char *sname = cg_fit_method_shared_cname(
                                cg, uf, uf->methods[mi].member);
                            if (!sname) { cg->cur_program = saved_prog; return false; }
                            if (!cg_emit_generic_type_method_wrapper(
                                    cg, uf->target, &uf->methods[mi],
                                    NULL, sname, d)) {
                                free(sname);
                                cg->cur_program = saved_prog;
                                return false;
                            }
                            free(sname);
                        }
                        cg->cur_program = saved_prog;
                    } else {
                        /* A fit method with its own generic parameters uses
                         * the same shared-body + thin-wrapper pipeline as a
                         * generic method declared directly on a non-generic
                         * type. Only a fully non-generic fit method remains
                         * on the monomorphised path. */
                        for (size_t mi = 0; mi < uf->method_count; mi++) {
                            const FengCallableSignature *signature =
                                &uf->methods[mi].member->as.callable;
                            bool needs_static =
                                !(target == FENG_COMPILE_TARGET_LIB &&
                                  cg_member_uses_package_callable_surface(
                                      cg, d, uf->methods[mi].member));
                            const UserFit *saved_user_fit = cg->current_user_fit;

                            cg->current_user_fit = uf;
                            if (signature->type_param_count > 0U) {
                                char *shared_name = cg_fit_method_shared_cname(
                                    cg, uf, uf->methods[mi].member);

                                if (shared_name == NULL ||
                                    !cg_emit_generic_type_method_shared(
                                        cg,
                                        uf->target->decl,
                                        uf->methods[mi].member,
                                        target,
                                        true,
                                        shared_name,
                                        d,
                                        CG_GENERIC_CONSTRUCTOR_INIT_DECLARED) ||
                                    !cg_emit_generic_type_method_wrapper(
                                        cg,
                                        uf->target,
                                        &uf->methods[mi],
                                        NULL,
                                        shared_name,
                                        d)) {
                                    free(shared_name);
                                    cg->current_user_fit = saved_user_fit;
                                    return false;
                                }
                                free(shared_name);
                            } else if (!cg_emit_user_method(cg,
                                                            uf->target,
                                                            &uf->methods[mi],
                                                            needs_static)) {
                                cg->current_user_fit = saved_user_fit;
                                return false;
                            }
                            cg->current_user_fit = saved_user_fit;
                        }
                    }
                }
                for (size_t fit_index = 0; fit_index < cg->builtin_fit_count; ++fit_index) {
                    const BuiltinFit *bf = &cg->builtin_fits[fit_index];

                    if (bf->decl != d) continue;
                    emitted_fit = true;
                    for (size_t mi = 0; mi < bf->method_count; mi++) {
                        bool needs_static =
                            !(target == FENG_COMPILE_TARGET_LIB &&
                              cg_member_uses_package_callable_surface(
                                  cg, d, bf->methods[mi].member));
                        if (!cg_emit_builtin_fit_method(cg,
                                                        bf,
                                                        &bf->methods[mi],
                                                        needs_static)) {
                            return false;
                        }
                    }
                }
                if (!emitted_fit) return cg_fail(cg, d->token,
                    "CE0351", "codegen: internal: fit not registered");
                break;
            }
            case FENG_DECL_FUNCTION:
                if (d->is_extern) {
                    /* Fully handled by cg_pass_pre_register_functions. */
                    break;
                } else if (d->as.function_decl.type_param_count > 0) {
                    /* G6: generic function — emit with the generic ABI. */
                    if (!cg_emit_generic_function(cg, d, target)) return false;
                } else {
                    bool is_main = (target == FENG_COMPILE_TARGET_BIN) &&
                                   slice_eq(d->as.function_decl.name, "main");
                    if (!cg_emit_function(cg, d, is_main, target)) return false;
                }
                break;
        }
    }
    cg->cur_program = NULL;
    return true;
}

/* Emit one value-type struct body into cg->headers.  Shared by the
 * topologically-sorted Pass 3.5a emitter so the field layout logic is
 * written once. */
static void cg_emit_value_type_struct_body(CG *cg, const UserType *t) {
    const UserType *open_inst = t->is_generic_instance
        ? cg_find_open_generic_instance(cg, t) : NULL;
    buf_append_fmt(&cg->headers, "struct %s {\n", t->c_struct_name);
    for (size_t fi = 0; fi < t->field_count; fi++) {
        bool needs_pad = false;
        if (open_inst != NULL && fi < open_inst->field_count &&
            open_inst->fields[fi].type != NULL &&
            open_inst->fields[fi].type->kind == CG_TYPE_GENERIC_PARAM) {
            switch (t->fields[fi].type->kind) {
                case CG_TYPE_BOOL:
                case CG_TYPE_I8:  case CG_TYPE_U8:
                case CG_TYPE_I16: case CG_TYPE_U16:
                case CG_TYPE_I32: case CG_TYPE_U32:
                case CG_TYPE_F32:
                    needs_pad = true;
                    break;
                default:
                    break;
            }
        }
        if (needs_pad) {
            buf_append_cstr(&cg->headers, "    _Alignas(sizeof(void *)) ");
        } else {
            buf_append_cstr(&cg->headers, "    ");
        }
        cg_emit_c_type(&cg->headers, t->fields[fi].type);
        buf_append_fmt(&cg->headers, " %s;\n", t->fields[fi].c_name);
        if (needs_pad) {
            buf_append_fmt(&cg->headers,
                "    char _pad_%s[sizeof(void *) - sizeof(",
                t->fields[fi].c_name);
            cg_emit_c_type(&cg->headers, t->fields[fi].type);
            buf_append_cstr(&cg->headers, ")];\n");
        }
    }
    buf_append_cstr(&cg->headers, "};\n");
}

/* Emit the struct body for a union-form spec value type into headers.
 * Called from the combined topological sort (Pass 3.5a) so that value
 * types embedded by value in the union payload are already defined. */
static void cg_emit_union_spec_struct_body(CG *cg, const UserSpec *s) {
    if (s->c_value_struct_name == NULL) {
        return;
    }
    buf_append_fmt(&cg->headers, "struct %s {\n", s->c_value_struct_name);
    buf_append_cstr(&cg->headers, "    uint32_t tag;\n");
    buf_append_cstr(&cg->headers, "    FengManagedSlotDescriptor _fwd;\n");
    buf_append_cstr(&cg->headers, "    union {\n");
    if (s->union_member_count == 0U) {
        buf_append_cstr(&cg->headers, "        char _empty;\n");
    }
    for (size_t member_index = 0U;
         member_index < s->union_member_count;
         ++member_index) {
        buf_append_cstr(&cg->headers, "        ");
        if (s->union_member_types[member_index] != NULL &&
            s->union_member_types[member_index]->kind == CG_TYPE_VOID) {
            buf_append_cstr(&cg->headers, "char ");
        } else {
            cg_emit_c_type(&cg->headers, s->union_member_types[member_index]);
            buf_append_cstr(&cg->headers, " ");
        }
        cg_append_union_payload_field_name(&cg->headers, member_index);
        buf_append_cstr(&cg->headers, ";\n");
    }
    buf_append_cstr(&cg->headers, "    } payload;\n};\n");
}

/* Pass 3.5a: emit full struct bodies for non-empty value-semantics types
 * (tuple / @value) AND union-form spec value structs into cg->headers,
 * topologically sorted so that any type embedded by value in another is
 * emitted first.  Zero-field value types are already emitted in
 * cg_emit_user_type_forward (Pass 3).
 *
 * Both value types and union specs may embed each other by value:
 * - Value type field of union spec type (e.g. IteratorResult<JsonValue>)
 * - Union spec member of value type (e.g. Option<StringSpan>)
 * A combined dependency graph handles both directions via Kahn's algorithm.
 *
 * Without topological ordering, a struct A that embeds struct B by value
 * may be emitted before B, producing an incomplete-type error in C. */
static bool cg_emit_value_and_union_struct_bodies_sorted(CG *cg) {
    size_t n_types = cg->user_type_count;
    size_t n_specs = cg->user_spec_count;

    /* Phase 1: count eligible nodes. */
    size_t vt_count = 0;
    for (size_t i = 0; i < n_types; i++) {
        const UserType *t = &cg->user_types[i];
        if (cg_user_type_is_value_semantics(t) && t->field_count > 0U) {
            vt_count++;
        }
    }
    size_t us_count = 0;
    for (size_t i = 0; i < n_specs; i++) {
        if (cg->user_specs[i].form == FENG_SPEC_FORM_UNION) {
            us_count++;
        }
    }
    size_t count = vt_count + us_count;
    if (count == 0U) return true;

    /* Phase 2: allocate mapping arrays.
     * node_is_spec[k]: false for value type, true for union spec.
     * node_type_idx[k]: index into user_types[] or user_specs[].
     * vt_local[i]: local node index for user_types[i] (SIZE_MAX if not eligible).
     * us_local[i]: local node index for user_specs[i] (SIZE_MAX if not union). */
    bool    *node_is_spec = calloc(count, sizeof(*node_is_spec));
    size_t  *node_type_idx = calloc(count, sizeof(*node_type_idx));
    size_t  *vt_local = n_types > 0 ? calloc(n_types, sizeof(*vt_local)) : NULL;
    size_t  *us_local = n_specs > 0 ? calloc(n_specs, sizeof(*us_local)) : NULL;
    if (!node_is_spec || !node_type_idx ||
        (n_types > 0 && !vt_local) || (n_specs > 0 && !us_local)) {
        free(node_is_spec); free(node_type_idx);
        free(vt_local); free(us_local);
        return cg_fail(cg, (FengToken){0}, "IE0001", "codegen: out of memory");
    }
    if (n_types > 0) memset(vt_local, 0xFF, n_types * sizeof(*vt_local));
    if (n_specs > 0) memset(us_local, 0xFF, n_specs * sizeof(*us_local));

    size_t k = 0;
    for (size_t i = 0; i < n_types; i++) {
        const UserType *t = &cg->user_types[i];
        if (!cg_user_type_is_value_semantics(t) || t->field_count == 0U) continue;
        vt_local[i] = k;
        node_is_spec[k] = false;
        node_type_idx[k] = i;
        k++;
    }
    for (size_t i = 0; i < n_specs; i++) {
        if (cg->user_specs[i].form != FENG_SPEC_FORM_UNION) continue;
        us_local[i] = k;
        node_is_spec[k] = true;
        node_type_idx[k] = i;
        k++;
    }

    if (count == 1U) {
        /* Single node — no ordering needed. */
        if (!node_is_spec[0]) {
            cg_emit_value_type_struct_body(cg, &cg->user_types[node_type_idx[0]]);
        } else {
            cg_emit_union_spec_struct_body(cg, &cg->user_specs[node_type_idx[0]]);
        }
        free(node_is_spec); free(node_type_idx);
        free(vt_local); free(us_local);
        return true;
    }

    /* Phase 3: build adjacency + in-degree for Kahn's algorithm.
     * Edge from B → A (dep[B * count + A]) means "A depends on B":
     * A embeds B by value, so B's struct body must come first. */
    bool *dep     = calloc(count * count, sizeof(*dep));
    size_t *indeg = calloc(count, sizeof(*indeg));
    bool *emitted = calloc(count, sizeof(*emitted));
    size_t *order = calloc(count, sizeof(*order));
    if (!dep || !indeg || !emitted || !order) {
        free(dep); free(indeg); free(emitted); free(order);
        free(node_is_spec); free(node_type_idx);
        free(vt_local); free(us_local);
        return cg_fail(cg, (FengToken){0}, "IE0001", "codegen: out of memory");
    }

    /* Add dependency edges for value type fields. */
    for (size_t vi = 0; vi < vt_count; vi++) {
        const UserType *t = &cg->user_types[node_type_idx[vi]];
        for (size_t fi = 0; fi < t->field_count; fi++) {
            const CGType *ft = t->fields[fi].type;
            size_t dep_target = SIZE_MAX;
            if (ft && ft->kind == CG_TYPE_OBJECT && ft->user &&
                cg_user_type_is_value_semantics(ft->user) &&
                ft->user->field_count > 0U) {
                for (size_t j = 0; j < n_types; j++) {
                    if (&cg->user_types[j] == ft->user) {
                        dep_target = vt_local[j];
                        break;
                    }
                }
            } else if (ft && ft->kind == CG_TYPE_SPEC && ft->user_spec &&
                       ft->user_spec->form == FENG_SPEC_FORM_UNION) {
                for (size_t j = 0; j < n_specs; j++) {
                    if (&cg->user_specs[j] == ft->user_spec) {
                        dep_target = us_local[j];
                        break;
                    }
                }
            }
            if (dep_target == SIZE_MAX || dep_target == vi) continue;
            if (!dep[dep_target * count + vi]) {
                dep[dep_target * count + vi] = true;
                indeg[vi]++;
            }
        }
    }

    /* Add dependency edges for union spec members. */
    for (size_t si = 0; si < us_count; si++) {
        size_t node_idx = vt_count + si;
        const UserSpec *s = &cg->user_specs[node_type_idx[node_idx]];
        for (size_t mi = 0; mi < s->union_member_count; mi++) {
            const CGType *mt = s->union_member_types[mi];
            size_t dep_target = SIZE_MAX;
            if (mt && mt->kind == CG_TYPE_OBJECT && mt->user &&
                cg_user_type_is_value_semantics(mt->user) &&
                mt->user->field_count > 0U) {
                for (size_t j = 0; j < n_types; j++) {
                    if (&cg->user_types[j] == mt->user) {
                        dep_target = vt_local[j];
                        break;
                    }
                }
            } else if (mt && mt->kind == CG_TYPE_SPEC && mt->user_spec &&
                       mt->user_spec->form == FENG_SPEC_FORM_UNION) {
                for (size_t j = 0; j < n_specs; j++) {
                    if (&cg->user_specs[j] == mt->user_spec) {
                        dep_target = us_local[j];
                        break;
                    }
                }
            }
            if (dep_target == SIZE_MAX || dep_target == node_idx) continue;
            if (!dep[dep_target * count + node_idx]) {
                dep[dep_target * count + node_idx] = true;
                indeg[node_idx]++;
            }
        }
    }

    /* Phase 4: Kahn's algorithm — emit nodes with no remaining deps first. */
    size_t cursor = 0;
    while (cursor < count) {
        bool found = false;
        for (size_t ni = 0; ni < count; ni++) {
            if (emitted[ni] || indeg[ni] != 0U) continue;
            emitted[ni] = true;
            order[cursor++] = ni;
            for (size_t w = 0; w < count; w++) {
                if (dep[ni * count + w]) indeg[w]--;
            }
            found = true;
            break;
        }
        if (!found) break;   /* remaining nodes form a cycle */
    }

    /* Phase 5: emit in topological order. */
    for (size_t ci = 0; ci < cursor; ci++) {
        size_t ni = order[ci];
        if (!node_is_spec[ni]) {
            cg_emit_value_type_struct_body(cg, &cg->user_types[node_type_idx[ni]]);
        } else {
            cg_emit_union_spec_struct_body(cg, &cg->user_specs[node_type_idx[ni]]);
        }
    }
    /* Fallback: emit any remaining (cycle — should not happen because
     * value_type_cycles.c rejects cycles during semantic analysis). */
    for (size_t ni = 0; ni < count; ni++) {
        if (!emitted[ni]) {
            if (!node_is_spec[ni]) {
                cg_emit_value_type_struct_body(cg, &cg->user_types[node_type_idx[ni]]);
            } else {
                cg_emit_union_spec_struct_body(cg, &cg->user_specs[node_type_idx[ni]]);
            }
        }
    }

    free(dep);
    free(indeg);
    free(emitted);
    free(order);
    free(node_is_spec);
    free(node_type_idx);
    free(vt_local);
    free(us_local);
    return !cg->failed;
}

/* Drive every pass across the full program set in deterministic
 * (module, program) order. Passes that mint cross-module-mangled symbols
 * (shells, fits, module bindings, decl emission) re-anchor `cg->module_mangle`
 * via cg_emit_module_header before processing each program; passes that walk
 * already-registered shells (member registration, type/spec body emission)
 * are program-agnostic and pin `cg->cur_program` per element so visibility
 * filtering and diagnostic paths report the right module / source file. */
static bool cg_emit_all_programs(CG *cg,
                                 const FengProgram *const *programs,
                                 size_t program_count,
                                 FengCompileTarget target) {
    /* Pass 1 + 1.5: register type and spec shells per program. */
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_register_type_shells(cg, programs[p])) {
            if (!cg->failed) cg_fail(cg, programs[p]->module_token,
                "CE0352", "codegen: internal: type shell registration failed without diagnostic");
            return false;
        }
    }
    /* Pass 1.7: collect concrete generic type instances referenced by source
     * types and expressions, then register them as normal UserType shells. */
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_collect_generic_type_instances(cg, programs[p])) {
            if (!cg->failed) cg_fail(cg, programs[p]->module_token,
                "CE0353", "codegen: internal: generic instance collection failed without diagnostic");
            return false;
        }
    }
    /* Pass 1.8: register fit shells before closing any type/spec members.
     * Substituting a generic fit for each concrete target can discover more
     * closed type/spec instances. Keeping that discovery in the shell phase
     * lets the existing member-registration passes close every instance,
     * including inherited parent specs, through one common path. */
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_register_fit_shells(cg, programs[p])) return false;
    }
    /* Pass 2: register fields/methods (uses cg_resolve_type which now sees
     * every shell, regardless of owning program). cur_program is pinned to
     * each type's owning program so cg_resolve_type's visibility filter
     * picks the right same-simple-named candidate.
     * Open (context-aware) generic instances carry unresolved type params;
     * set ambient_type_param context so cg_resolve_type finds the matching
     * open instances during member registration. */
    for (size_t i = 0; i < cg->user_type_count; i++) {
        cg->cur_program = cg->user_types[i].instantiation_program != NULL
            ? cg->user_types[i].instantiation_program
            : cg->user_types[i].owner_program;
        size_t saved_ambient_count = cg->ambient_type_param_count;
        char **saved_ambient_names = cg->ambient_type_param_names;
        if (cg->user_types[i].generic_context_type_param_count > 0U) {
            cg->ambient_type_param_count = cg->user_types[i].generic_context_type_param_count;
            cg->ambient_type_param_names = cg->user_types[i].generic_context_type_param_names;
        }
        bool ok = cg_register_user_type_members(cg, &cg->user_types[i], target);
        cg->ambient_type_param_count = saved_ambient_count;
        cg->ambient_type_param_names = saved_ambient_names;
        cg->cur_program = NULL;
        if (!ok) {
            if (!cg->failed) cg_fail(cg, cg->user_types[i].decl->token,
                "CE0354", "codegen: internal: user type member registration failed without diagnostic");
            return false;
        }
    }
    /* Pass 2.5: register spec members. */
    for (size_t i = 0; i < cg->user_spec_count; i++) {
        cg->cur_program = cg->user_specs[i].instantiation_program != NULL
            ? cg->user_specs[i].instantiation_program
            : cg->user_specs[i].owner_program;
        bool ok = cg_ensure_user_spec_members_registered(cg, &cg->user_specs[i]);
        cg->cur_program = NULL;
        if (!ok) return false;
    }
    /* Pass 2.7: register fit members. The fit-body's name lookups must see
     * the fit's own program (not the target type's), so cur_program is set
     * from the fit declaration's owning program. */
    for (size_t i = 0; i < cg->user_fit_count; i++) {
        /* Locate the owning program by scanning programs for the fit decl. */
        const FengProgram *owner = NULL;
        for (size_t p = 0; p < program_count && !owner; p++) {
            for (size_t k = 0; k < programs[p]->declaration_count; k++) {
                if (programs[p]->declarations[k] == cg->user_fits[i].decl) {
                    owner = programs[p];
                    break;
                }
            }
        }
        cg->cur_program = owner;
        bool ok = cg_register_user_fit_members(cg, &cg->user_fits[i]);
        cg->cur_program = NULL;
        if (!ok) return false;
    }
    for (size_t i = 0; i < cg->builtin_fit_count; i++) {
        const FengProgram *owner = NULL;
        for (size_t p = 0; p < program_count && !owner; p++) {
            for (size_t k = 0; k < programs[p]->declaration_count; k++) {
                if (programs[p]->declarations[k] == cg->builtin_fits[i].decl) {
                    owner = programs[p];
                    break;
                }
            }
        }
        cg->cur_program = owner;
        bool ok = cg_register_builtin_fit_members(cg, &cg->builtin_fits[i]);
        cg->cur_program = NULL;
        if (!ok) return false;
    }
    /* Pass 2b: register module-level let/var bindings + emit static storage. */
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_register_module_bindings(cg, programs[p], target)) return false;
    }
    /* Pass 2c (§9.16): update value-type descriptor symbol names based on
     * the computed value_kind. Must run after Pass 2 (field registration)
     * so field types are resolved, and before Pass 3 (type forward emit)
     * which references c_aggregate_desc_name in forward declarations. */
    if (!cg_update_value_type_descriptor_names(cg)) return false;
    /* Pass 2d: close callable graph identities before type descriptors.
     * Owner descriptors may contain function-descriptor nodes for generic
     * field initializers, constructors, and finalizers. */
    for (size_t p = 0U; p < program_count; ++p) {
        if (!cg_pass_register_generic_functions_for_descriptors(
                cg, programs[p])) {
            return false;
        }
    }
    /* Pass 3 + 3.5a/3.5b: emit type forwards/defs and spec forwards/defs.
     * These walk the global cg shell arrays. cur_program is pinned per
     * element so any diagnostic raised mid-emission reports the correct
     * source file. */
    for (size_t i = 0; i < cg->user_type_count; i++) {
        cg_emit_user_type_forward(cg, &cg->user_types[i]);
    }
    /* Declare every spec-owned C tag before emitting any witness signature.
     * A tag first introduced inside a function parameter list has prototype
     * scope in C and would be incompatible with the later file-scope body. */
    for (size_t i = 0; i < cg->user_spec_count; i++) {
        cg_emit_user_spec_tag_forwards(cg, &cg->user_specs[i]);
    }
    for (size_t i = 0; i < cg->user_spec_count; i++) {
        cg_emit_user_spec_forward(cg, &cg->user_specs[i]);
    }
    /* Pass 3.5a: emit full struct bodies for non-empty value-semantics types
     * (tuple / @value) AND union-form spec value structs into headers,
     * topologically sorted so that any type embedded by value in another
     * is emitted first. Handles cross-dependencies between value types
     * and union specs (e.g. Option<StringSpan> and IteratorResult<JsonValue>).
     * Must follow spec forward emission so object-form spec value structs
     * (e.g. Named) are complete when union specs (e.g. Display) embed them
     * by value. */
    if (!cg_emit_value_and_union_struct_bodies_sorted(cg)) return false;
    /* Pass 3.4: emit enum typedefs + descriptors before user type
     * definitions so that @value type equal functions referencing enum
     * descriptors find them already declared. */
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_emit_enum_decls(cg, programs[p])) return false;
    }
    for (size_t i = 0; i < cg->user_type_count; i++) {
        bool imported_owner = cg_program_origin(cg, cg->user_types[i].owner_program) ==
                              FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE;
        if (imported_owner && !cg->user_types[i].is_generic_instance) {
            /* Emit only the struct layout into type_defs.  The descriptor
             * and __default_zero already reside in the imported package's
             * compiled library and must NOT be re-emitted here.
             * All type forward declarations have been appended to headers
             * before this loop runs, so field type references are safe. */
            UserType *t = &cg->user_types[i];
            if (!cg_user_type_is_value_semantics(t)) {
                Buf *td = &cg->type_defs;
                const UserType *imp_open = t->is_generic_instance
                    ? cg_find_open_generic_instance(cg, t) : NULL;
                buf_append_fmt(td, "struct %s {\n", t->c_struct_name);
                buf_append_cstr(td, "    FengManagedHeader _hdr;\n");
                for (size_t fi = 0; fi < t->field_count; fi++) {
                    bool needs_pad = false;
                    if (imp_open != NULL && fi < imp_open->field_count &&
                        imp_open->fields[fi].type != NULL &&
                        imp_open->fields[fi].type->kind == CG_TYPE_GENERIC_PARAM) {
                        switch (t->fields[fi].type->kind) {
                            case CG_TYPE_BOOL:
                            case CG_TYPE_I8:  case CG_TYPE_U8:
                            case CG_TYPE_I16: case CG_TYPE_U16:
                            case CG_TYPE_I32: case CG_TYPE_U32:
                            case CG_TYPE_F32:
                                needs_pad = true;
                                break;
                            default:
                                break;
                        }
                    }
                    if (needs_pad) {
                        buf_append_cstr(td, "    _Alignas(sizeof(void *)) ");
                    } else {
                        buf_append_cstr(td, "    ");
                    }
                    cg_emit_c_type(td, t->fields[fi].type);
                    buf_append_fmt(td, " %s;\n", t->fields[fi].c_name);
                    if (needs_pad) {
                        buf_append_fmt(td,
                            "    char _pad_%s[sizeof(void *) - sizeof(",
                            t->fields[fi].c_name);
                        cg_emit_c_type(td, t->fields[fi].type);
                        buf_append_cstr(td, ")];\n");
                    }
                }
                buf_append_cstr(td, "};\n\n");
            }
            /* Forward-declare __default_zero so consumer-side generic
             * instances (e.g. Map<K, V>) can call it.  The body lives in
             * the imported package's compiled library. */
            if (t->c_default_zero_name != NULL &&
                cg_user_type_is_default_zero_safe(cg, t)) {
                buf_append_fmt(&cg->headers,
                    "struct %s *%s(void);\n",
                    t->c_struct_name, t->c_default_zero_name);
            }
            continue;
        }
        if (imported_owner && cg->user_types[i].generic_context_type_param_count > 0U) {
            continue;
        }
        if (!cg_emit_module_header(cg, cg->user_types[i].owner_program)) {
            return false;
        }
        cg->cur_program = cg->user_types[i].owner_program;
        cg_emit_user_type_definition(cg, &cg->user_types[i]);
        cg->cur_program = NULL;
        if (cg->failed) return false;
    }
    for (size_t i = 0; i < cg->user_spec_count; i++) {
        if (cg_program_origin(cg, cg->user_specs[i].owner_program) ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            /* Imported specs need their definition emitted here when the
             * consumer module references them:
             * - Generic-context specs: witness struct body is needed so
             *   consumer-side witness instances can be properly typed.
             *   cg_emit_user_spec_definition returns early for these
             *   (no aggregate descriptor emitted).
             * - Union-form specs: the aggregate descriptor (with init fn,
             *   slots, etc.) uses internal linkage in the originating
             *   library and cannot be referenced from the consumer, so we
             *   must emit our own copy here.
             * - Callable-form specs: the closure struct definition and
             *   FengClosureDesc type descriptor both use internal linkage,
             *   and the consumer needs them to create closure values
             *   inline, so we must emit our own copy here.
             * - Concrete generic specs are instantiated on demand and may
             *   not have been materialized by the provider. Public aggregate
             *   descriptors use weak definitions, so emitting a consumer
             *   copy also remains valid when the provider has one.
             * - Private object-form representation specs have no externally
             *   visible aggregate descriptor in the provider library, so the
             *   consumer must emit its own default witness and descriptor. */
            if (cg->user_specs[i].generic_context_type_param_count > 0U ||
                cg->user_specs[i].is_generic_instance ||
                cg->user_specs[i].form == FENG_SPEC_FORM_UNION ||
                cg->user_specs[i].form == FENG_SPEC_FORM_CALLABLE ||
                cg->user_specs[i].form == FENG_SPEC_FORM_INTERSECTION ||
                !cg_user_spec_descriptor_is_externally_visible(
                    cg, &cg->user_specs[i])) {
                cg->cur_program = cg->user_specs[i].instantiation_program != NULL
                    ? cg->user_specs[i].instantiation_program
                    : cg->user_specs[i].owner_program;
                cg_emit_user_spec_definition(cg, &cg->user_specs[i]);
                cg->cur_program = NULL;
                if (cg->failed) return false;
            }
            continue;
        }
        if (!cg_emit_module_header(cg, cg->user_specs[i].owner_program)) {
            return false;
        }
        cg->cur_program = cg->user_specs[i].instantiation_program != NULL
            ? cg->user_specs[i].instantiation_program
            : cg->user_specs[i].owner_program;
        cg_emit_user_spec_definition(cg, &cg->user_specs[i]);
        cg->cur_program = NULL;
        if (cg->failed) return false;
    }
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_emit_imported_function_decls(cg, programs[p])) return false;
    }
    for (size_t i = 0; i < cg->user_type_count; i++) {
        const UserType *t = &cg->user_types[i];

        if (cg_program_origin(cg, t->owner_program) !=
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        if (t->is_generic_instance) {
            /* An imported instance whose arguments still reference the
             * caller's generic context may be the only registered view of
             * its origin (for example Map<K, Composite<T>>). Its calls target
             * the provider's exported shared bodies directly, so emit those
             * declarations even when no separate open-origin shell exists. */
            if (t->generic_context_type_param_count > 0U) {
                for (size_t ci = 0U; ci < t->constructor_count; ++ci) {
                    if (!cg_emit_imported_generic_method_shared_proto(
                            cg, t, &t->constructors[ci], false, NULL)) {
                        return false;
                    }
                }
                for (size_t mi = 0U; mi < t->method_count; ++mi) {
                    if (!cg_emit_imported_generic_method_shared_proto(
                            cg, t, &t->methods[mi], true, NULL)) {
                        return false;
                    }
                }
                for (size_t mi = 0U; mi < t->static_method_count; ++mi) {
                    if (!cg_emit_imported_generic_method_shared_proto(
                            cg, t, &t->static_methods[mi], true, NULL)) {
                        return false;
                    }
                }
            }
            continue;
        }
        for (size_t mi = 0; mi < t->method_count; mi++) {
            const UserMethod *method = &t->methods[mi];
            const FengCallableSignature *signature =
                method->member != NULL ? &method->member->as.callable : NULL;

            if (signature != NULL && signature->type_param_count > 0U) {
                if (!cg_emit_imported_generic_method_shared_proto(
                        cg, t, method, true, NULL)) {
                    return false;
                }
            } else {
                cg_emit_user_method_proto(
                    &cg->fn_protos, t, method, false);
            }
        }
        for (size_t mi = 0; mi < t->static_method_count; mi++) {
            const UserMethod *sm = &t->static_methods[mi];
            const FengCallableSignature *sm_sig =
                sm->member != NULL ? &sm->member->as.callable : NULL;
            size_t sm_tp_count = sm_sig != NULL ? sm_sig->type_param_count : 0U;

            if (sm_tp_count > 0U && t->decl != NULL) {
                if (!cg_emit_imported_generic_method_shared_proto(
                        cg, t, sm, true, NULL)) {
                    return false;
                }
            } else {
                cg_emit_user_method_proto(&cg->fn_protos, t, sm, false);
            }
        }
        for (size_t ci = 0; ci < t->constructor_count; ci++) {
            cg_emit_user_method_proto(&cg->fn_protos, t, &t->constructors[ci], false);
        }
    }
    for (size_t i = 0; i < cg->user_fit_count; i++) {
        const UserFit *uf = &cg->user_fits[i];

        if (cg_program_origin(cg, uf->owner_program) !=
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        if (uf->target->is_generic_instance &&
            uf->target->generic_origin_decl != NULL) {
            /* Generic imported fits: wrappers are emitted below alongside
             * the imported generic type instance wrappers. Skip proto here. */
            continue;
        }
        for (size_t mi = 0; mi < uf->method_count; mi++) {
            const FengCallableSignature *signature =
                &uf->methods[mi].member->as.callable;

            if (signature->type_param_count > 0U) {
                char *shared_name = cg_fit_method_shared_cname(
                    cg, uf, uf->methods[mi].member);

                if (shared_name == NULL ||
                    !cg_emit_imported_generic_method_shared_proto(
                        cg,
                        uf->target,
                        &uf->methods[mi],
                        true,
                        shared_name)) {
                    free(shared_name);
                    return false;
                }
                free(shared_name);
            } else {
                cg_emit_user_method_proto(
                    &cg->fn_protos,
                    uf->target,
                    &uf->methods[mi],
                    false);
            }
        }
    }
    for (size_t i = 0; i < cg->builtin_fit_count; i++) {
        const BuiltinFit *bf = &cg->builtin_fits[i];

        if (cg_program_origin(cg, bf->owner_program) !=
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        for (size_t mi = 0; mi < bf->method_count; mi++) {
            cg_emit_builtin_fit_method_proto(&cg->fn_protos, bf, &bf->methods[mi], false);
        }
    }
    for (size_t i = 0; i < cg->user_type_count; i++) {
        const UserType *t = &cg->user_types[i];
        if (!t->is_generic_instance) {
            continue;
        }
        if (cg_program_origin(cg, t->owner_program) !=
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        if (t->generic_context_type_param_count > 0U) {
            continue;
        }
        const FengProgram *visibility_program = t->instantiation_program != NULL
            ? t->instantiation_program
            : t->owner_program;
        if (!cg_emit_module_header(cg, visibility_program)) {
            return false;
        }
        cg->cur_program = visibility_program;
        for (size_t ci = 0; ci < t->constructor_count; ci++) {
            if (!cg_emit_generic_type_method_wrapper(cg, t, &t->constructors[ci], NULL, NULL, NULL)) {
                cg->cur_program = NULL;
                return false;
            }
        }
        for (size_t mi = 0; mi < t->method_count; mi++) {
            if (!cg_emit_generic_type_method_wrapper(cg, t, &t->methods[mi], NULL, NULL, NULL)) {
                cg->cur_program = NULL;
                return false;
            }
        }
        for (size_t mi = 0; mi < t->static_method_count; mi++) {
            if (!cg_emit_generic_type_method_wrapper(cg, t, &t->static_methods[mi], NULL, NULL, NULL)) {
                cg->cur_program = NULL;
                return false;
            }
        }
        if (!cg_emit_user_finalizer(cg, t)) {
            cg->cur_program = NULL;
            return false;
        }
        cg->cur_program = NULL;
    }
    /* Pass 3.8b: emit wrappers for imported generic UserFit methods.
     * The shared bodies live in the library; we generate local wrappers
     * that call through to them, mirroring the local generic-type path. */
    for (size_t i = 0; i < cg->user_fit_count; i++) {
        const UserFit *uf = &cg->user_fits[i];

        if (cg_program_origin(cg, uf->owner_program) !=
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        if (!uf->target->is_generic_instance ||
            uf->target->generic_origin_decl == NULL) {
            continue;
        }
        if (uf->target->generic_context_type_param_count > 0U) {
            continue;
        }
        const FengProgram *vis_prog = uf->target->instantiation_program != NULL
            ? uf->target->instantiation_program
            : uf->target->owner_program;
        if (!cg_emit_module_header(cg, vis_prog)) return false;
        cg->cur_program = vis_prog;

        for (size_t mi = 0; mi < uf->method_count; mi++) {
            char *sname = cg_fit_method_shared_cname(cg, uf, uf->methods[mi].member);
            if (!sname) { cg->cur_program = NULL; return false; }
            if (!cg_emit_generic_type_method_wrapper(cg, uf->target,
                                                     &uf->methods[mi],
                                                     NULL, sname,
                                                     uf->decl)) {
                free(sname);
                cg->cur_program = NULL;
                return false;
            }
            free(sname);
        }
        cg->cur_program = NULL;
    }
    /* Pass 3.9: pre-register all free functions, externs, and generic
     * functions so that cross-file references within the same module are
     * resolved before any function body is emitted. */
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_pre_register_functions(cg, programs[p], target)) {
            if (!cg->failed) cg_fail(cg, programs[p]->module_token,
                "CE0355", "codegen: internal: function pre-registration failed without diagnostic");
            return false;
        }
    }
    /* Pass 4: per-program decl emission (externs / functions / methods /
     * finalizers / fit method bodies). */
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_emit_decls(cg, programs[p], target)) {
            if (!cg->failed) cg_fail(cg, programs[p]->module_token,
                "CE0356", "codegen: internal: declaration emission failed without diagnostic");
            return false;
        }
    }
    for (size_t p = 0; p < program_count; p++) {
        if (!cg_pass_emit_module_binding_ensure_inits(cg, programs[p])) {
            if (!cg->failed) cg_fail(cg, programs[p]->module_token,
                "CE0357", "codegen: internal: module binding ensure-init emission failed without diagnostic");
            return false;
        }
    }
    if (!cg_pass_emit_type_static_binding_ensure_inits(cg)) {
        if (!cg->failed && program_count > 0U) {
            cg_fail(cg,
                    programs[0]->module_token,
                    "CE0358", "codegen: internal: type static binding ensure-init emission failed without diagnostic");
        }
        return false;
    }
    return true;
}


static void cg_emit_string_literal_table(CG *cg) {
    Buf *s = &cg->statics;
    for (size_t i = 0; i < cg->string_literal_count; i++) {
        buf_append_fmt(s, "static FengString *%s = NULL;\n", cg->string_literals[i].c_var);
    }
}

/* Emit the assignment statements that initialise this unit's string-literal
 * slots into the given function body. Original behaviour: previously inlined
 * into `main()`; now reused by cg_emit_string_literal_ctor() to drive the
 * same initialisation from a per-TU `__attribute__((constructor))`. */
static void cg_emit_string_literal_init(CG *cg, Buf *body) {
    for (size_t i = 0; i < cg->string_literal_count; i++) {
        buf_append_fmt(body,
            "    %s = feng_string_literal(", cg->string_literals[i].c_var);
        buf_append_c_bytes_literal(body,
                                   cg->string_literals[i].content,
                                   cg->string_literals[i].length);
        buf_append_fmt(body, ", %zu);\n", cg->string_literals[i].length);
    }
}

/* Wrap cg_emit_string_literal_init in a per-TU constructor so the crt/loader
 * runs it before `main` regardless of which TU the caller links — bin or
 * lib archive. GCC/clang place the function pointer in `.init_array`. MSVC
 * is not currently supported by the Feng host-C path; if added later, this
 * needs a `_MSC_VER` branch using `#pragma section(".CRT$XCU", read)`. */
static void cg_emit_string_literal_ctor(CG *cg) {
    if (cg->string_literal_count == 0U) return;
    Buf *b = &cg->fn_defs;
    buf_append_cstr(b,
        "__attribute__((constructor))\n"
        "static void _feng_init_string_literals(void) {\n");
    cg_emit_string_literal_init(cg, b);
    buf_append_cstr(b, "}\n");
}

static bool cg_emit_module_binding_init(CG *cg, const ModuleBinding *mb) {
    const FengExpr *init = mb->binding->initializer;
    if (!init) {
        /* No initializer: assign the type's default zero. For managed
         * types the slot now owns a +1 reference (the static was zero-initialised
         * to NULL/0 in pass 2b). */
        if (cgtype_is_aggregate(mb->type)) {
            buf_append_cstr(cg->cur_body, "    ");
            if (!cg_append_aggregate_default_init_call(cg->cur_body, mb->type, mb->c_name)) {
                return cg_fail(cg,
                               mb->binding->token,
                               "CE0359", "codegen: missing aggregate default-init rule for module binding");
            }
            buf_append_cstr(cg->cur_body, ";\n");
            return true;
        }
        char *def_expr = NULL;
        if (!cg_default_value_expr(cg, mb->type, &mb->binding->token, &def_expr)) {
            return false;
        }
        if (cgtype_is_managed(mb->type)) {
            buf_append_fmt(cg->cur_body, "    %s = %s;\n", mb->c_name, def_expr);
        } else {
            char *cty = cg_ctype_dup(mb->type);
            buf_append_fmt(cg->cur_body, "    %s = (%s)(%s);\n",
                           mb->c_name, cty, def_expr);
            free(cty);
        }
        free(def_expr);
        return true;
    }

    /* Use a transient scope so any temporaries from the expression get
     * released after the assignment. */
    Scope *fn_scope = scope_push(NULL);
    if (!fn_scope) return cg_fail(cg, mb->binding->token,
                                  "IE0001", "codegen: out of memory");
    cg->cur_scope = fn_scope;
    /* Caller is responsible for setting cg->cur_body to the destination
     * buffer (typically a side buffer that is later spliced into main()). */
    cg->cur_return_type = NULL;
    cg->cur_fn_is_main = false;

    buf_append_cstr(cg->cur_body, "    {\n");
    ExprResult r;
    if (!cg_emit_initializer_for_declared_type(cg, init, mb->type, &r)) {
        cg->cur_scope = NULL; scope_pop_free(fn_scope);
        cg->cur_body = NULL;
        return false;
    }
    if (cgtype_is_managed(mb->type)) {
        if (r.owns_ref) {
            buf_append_fmt(cg->cur_body, "        %s = %s;\n", mb->c_name, r.c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                "        %s = %s; feng_retain(%s);\n",
                mb->c_name, r.c_expr, mb->c_name);
        }
    } else if (cgtype_is_aggregate(mb->type)) {
        const char *desc = cg_aggregate_desc_name(mb->type);

        if (desc == NULL) {
            er_free(&r);
            cg->cur_scope = NULL; scope_pop_free(fn_scope);
            cg->cur_body = NULL;
            return cg_fail(cg,
                           mb->binding->token,
                           "CE0360", "codegen: missing aggregate descriptor for module binding");
        }
        if (!cg_prepare_aggregate_assign_source(cg, &r, "_t")) {
            er_free(&r);
            cg->cur_scope = NULL; scope_pop_free(fn_scope);
            cg->cur_body = NULL;
            return cg_fail(cg, mb->binding->token, "IE0001", "codegen: out of memory");
        }
        buf_append_fmt(cg->cur_body,
            "        feng_aggregate_assign(&%s, &%s, &%s);\n",
            mb->c_name, r.c_expr, desc);
    } else {
        char *cty = cg_ctype_dup(mb->type);
        buf_append_fmt(cg->cur_body, "        %s = (%s)(%s);\n",
                       mb->c_name, cty, r.c_expr);
        free(cty);
    }
    er_free(&r);
    cg_release_scope(cg, fn_scope);
    buf_append_cstr(cg->cur_body, "    }\n");
    cg->cur_scope = NULL; scope_pop_free(fn_scope);
    cg->cur_body = NULL;
    return true;
}

static bool cg_emit_module_binding_ensure_init(CG *cg, const ModuleBinding *mb) {
    Buf *prev_body = cg->cur_body;
    Scope *prev_scope = cg->cur_scope;
    CGType *prev_return_type = cg->cur_return_type;
    bool prev_fn_is_main = cg->cur_fn_is_main;

    buf_append_fmt(&cg->fn_defs,
                   "%svoid %s(void) {\n",
                   mb->exports_public_surface ? "" : "static ",
                   mb->c_ensure_init_name);
    buf_append_fmt(&cg->fn_defs, "    if (%s) return;\n", mb->c_inited_name);

    cg->cur_body = &cg->fn_defs;
    if (!cg_emit_module_binding_init(cg, mb)) {
        cg->cur_body = prev_body;
        cg->cur_scope = prev_scope;
        cg->cur_return_type = prev_return_type;
        cg->cur_fn_is_main = prev_fn_is_main;
        return false;
    }

    cg->cur_body = &cg->fn_defs;
    buf_append_fmt(&cg->fn_defs, "    %s = true;\n", mb->c_inited_name);
    buf_append_cstr(&cg->fn_defs, "}\n\n");

    cg->cur_body = prev_body;
    cg->cur_scope = prev_scope;
    cg->cur_return_type = prev_return_type;
    cg->cur_fn_is_main = prev_fn_is_main;
    return true;
}

/** Initialize one descriptor-selected generic static storage slot. */
static bool cg_emit_type_static_binding_state_init(
    CG *cg,
    const TypeStaticBinding *binding,
    const char *state_expr) {
    const FengExpr *initializer;
    char *cty = NULL;
    Buf destination;

    if (cg == NULL || binding == NULL || binding->member == NULL ||
        binding->type == NULL || state_expr == NULL) {
        return false;
    }
    initializer = binding->member->as.field.initializer;
    if (binding->type->kind == CG_TYPE_GENERIC_PARAM) {
        if (initializer == NULL) {
            Buf storage;

            buf_init(&storage);
            buf_append_fmt(&storage, "%s->storage", state_expr);
            if (storage.data == NULL ||
                !cg_emit_generic_param_default_init_at_address(
                    cg,
                    storage.data,
                    binding->type,
                    binding->member->token)) {
                buf_free(&storage);
                return false;
            }
            buf_free(&storage);
            return true;
        }
        {
            Scope *parent_scope = cg->cur_scope;
            Scope *scope = scope_push(parent_scope);
            ExprResult value;
            Buf storage;

            if (scope == NULL) {
                return cg_fail(cg, binding->member->token,
                               "IE0001", "codegen: out of memory");
            }
            cg->cur_scope = scope;
            buf_append_cstr(cg->cur_body, "    {\n");
            if (!cg_emit_initializer_for_declared_type(cg,
                                                       initializer,
                                                       binding->type,
                                                       &value)) {
                cg->cur_scope = parent_scope;
                scope_pop_free(scope);
                return false;
            }
            buf_init(&storage);
            buf_append_fmt(&storage, "%s->storage", state_expr);
            if (storage.data == NULL ||
                !cg_emit_generic_value_store(cg,
                                                      storage.data,
                                                      binding->type,
                                                      &value,
                                                      binding->member->token,
                                                      false)) {
                buf_free(&storage);
                er_free(&value);
                cg->cur_scope = parent_scope;
                scope_pop_free(scope);
                return false;
            }
            buf_free(&storage);
            er_free(&value);
            cg_release_scope(cg, scope);
            buf_append_cstr(cg->cur_body, "    }\n");
            cg->cur_scope = parent_scope;
            scope_pop_free(scope);
            return true;
        }
    }

    cty = cg_ctype_dup(binding->type);
    if (cty == NULL) {
        return cg_fail(cg, binding->member->token,
                       "IE0001", "codegen: out of memory");
    }
    buf_init(&destination);
    buf_append_fmt(&destination,
                   "(*(%s *)%s->storage)",
                   cty,
                   state_expr);
    if (destination.data == NULL) {
        free(cty);
        return cg_fail(cg, binding->member->token,
                       "IE0001", "codegen: out of memory");
    }

    if (initializer == NULL) {
        if (cgtype_is_aggregate(binding->type)) {
            const char *descriptor = cg_aggregate_desc_name(binding->type);

            if (descriptor == NULL) {
                buf_free(&destination);
                free(cty);
                return cg_fail(cg,
                               binding->member->token,
                               "CE0374", "codegen: missing aggregate default-init rule for generic static binding");
            }
            buf_append_fmt(cg->cur_body,
                "    feng_aggregate_default_init(%s->storage, &%s);\n",
                state_expr,
                descriptor);
        } else {
            char *default_expression = NULL;

            if (!cg_default_value_expr(cg,
                                       binding->type,
                                       &binding->member->token,
                                       &default_expression)) {
                buf_free(&destination);
                free(cty);
                return false;
            }
            if (cgtype_is_by_value_struct(binding->type)) {
                buf_append_fmt(cg->cur_body,
                    "    %s = %s;\n",
                    destination.data,
                    default_expression);
            } else {
                buf_append_fmt(cg->cur_body,
                    "    %s = (%s)(%s);\n",
                    destination.data,
                    cty,
                    default_expression);
            }
            free(default_expression);
        }
        buf_free(&destination);
        free(cty);
        return true;
    }

    {
        Scope *parent_scope = cg->cur_scope;
        Scope *scope = scope_push(parent_scope);
        ExprResult value;

        if (scope == NULL) {
            buf_free(&destination);
            free(cty);
            return cg_fail(cg, binding->member->token,
                           "IE0001", "codegen: out of memory");
        }
        cg->cur_scope = scope;
        buf_append_cstr(cg->cur_body, "    {\n");
        if (!cg_emit_initializer_for_declared_type(cg,
                                                   initializer,
                                                   binding->type,
                                                   &value)) {
            cg->cur_scope = parent_scope;
            scope_pop_free(scope);
            buf_free(&destination);
            free(cty);
            return false;
        }
        if (cgtype_is_managed(binding->type)) {
            if (value.owns_ref) {
                buf_append_fmt(cg->cur_body,
                               "        %s = %s;\n",
                               destination.data,
                               value.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                    "        %s = %s; feng_retain(%s);\n",
                    destination.data,
                    value.c_expr,
                    destination.data);
            }
        } else if (cgtype_is_aggregate(binding->type)) {
            const char *descriptor = cg_aggregate_desc_name(binding->type);

            if (descriptor == NULL ||
                !cg_prepare_aggregate_assign_source(cg, &value, "_t")) {
                er_free(&value);
                cg->cur_scope = parent_scope;
                scope_pop_free(scope);
                buf_free(&destination);
                free(cty);
                return cg_fail(cg,
                               binding->member->token,
                               descriptor == NULL ? "CE0246" : "IE0001",
                               descriptor == NULL
                                   ? "codegen: missing aggregate descriptor for generic static binding write"
                                   : "codegen: out of memory");
            }
            buf_append_fmt(cg->cur_body,
                "        feng_aggregate_assign(%s->storage, &%s, &%s);\n",
                state_expr,
                value.c_expr,
                descriptor);
        } else if (cgtype_is_by_value_struct(binding->type)) {
            buf_append_fmt(cg->cur_body,
                           "        %s = %s;\n",
                           destination.data,
                           value.c_expr);
        } else {
            buf_append_fmt(cg->cur_body,
                           "        %s = (%s)(%s);\n",
                           destination.data,
                           cty,
                           value.c_expr);
        }
        er_free(&value);
        cg_release_scope(cg, scope);
        buf_append_cstr(cg->cur_body, "    }\n");
        cg->cur_scope = parent_scope;
        scope_pop_free(scope);
    }
    buf_free(&destination);
    free(cty);
    return true;
}

static bool cg_emit_type_static_binding_init(CG *cg, const TypeStaticBinding *binding) {
    const FengExpr *init;

    if (binding == NULL || binding->member == NULL || binding->type == NULL) {
        return false;
    }
    init = binding->member->as.field.initializer;
    if (init == NULL) {
        if (cgtype_is_aggregate(binding->type)) {
            buf_append_cstr(cg->cur_body, "    ");
            if (!cg_append_aggregate_default_init_call(cg->cur_body,
                                                      binding->type,
                                                      binding->c_name)) {
                return cg_fail(cg, binding->member->token,
                    "CE0374", "codegen: missing aggregate default-init rule for type static binding");
            }
            buf_append_cstr(cg->cur_body, ";\n");
            return true;
        }
        {
            char *def_expr = NULL;

            if (!cg_default_value_expr(cg, binding->type, &binding->member->token, &def_expr)) {
                return false;
            }
            if (cgtype_is_managed(binding->type)) {
                buf_append_fmt(cg->cur_body, "    %s = %s;\n", binding->c_name, def_expr);
            } else {
                char *cty = cg_ctype_dup(binding->type);

                if (cty == NULL) {
                    free(def_expr);
                    return cg_fail(cg, binding->member->token, "IE0001", "codegen: out of memory");
                }
                if (cgtype_is_by_value_struct(binding->type)) {
                    buf_append_fmt(cg->cur_body,
                                   "    %s = %s;\n",
                                   binding->c_name,
                                   def_expr);
                } else {
                    buf_append_fmt(cg->cur_body,
                                   "    %s = (%s)(%s);\n",
                                   binding->c_name,
                                   cty,
                                   def_expr);
                }
                free(cty);
            }
            free(def_expr);
        }
        return true;
    }

    {
        Scope *fn_scope = scope_push(NULL);
        ExprResult r;

        if (fn_scope == NULL) {
            return cg_fail(cg, binding->member->token, "IE0001", "codegen: out of memory");
        }
        cg->cur_scope = fn_scope;
        cg->cur_return_type = NULL;
        cg->cur_fn_is_main = false;

        buf_append_cstr(cg->cur_body, "    {\n");
        if (!cg_emit_initializer_for_declared_type(cg, init, binding->type, &r)) {
            cg->cur_scope = NULL;
            scope_pop_free(fn_scope);
            cg->cur_body = NULL;
            return false;
        }
        if (cgtype_is_managed(binding->type)) {
            if (r.owns_ref) {
                buf_append_fmt(cg->cur_body, "        %s = %s;\n", binding->c_name, r.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                               "        %s = %s; feng_retain(%s);\n",
                               binding->c_name,
                               r.c_expr,
                               binding->c_name);
            }
        } else if (cgtype_is_aggregate(binding->type)) {
            const char *desc = cg_aggregate_desc_name(binding->type);

            if (desc == NULL) {
                er_free(&r);
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                cg->cur_body = NULL;
                return cg_fail(cg,
                               binding->member->token,
                               "CE0246", "codegen: missing aggregate descriptor for static binding write");
            }
            if (!cg_prepare_aggregate_assign_source(cg, &r, "_t")) {
                er_free(&r);
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                cg->cur_body = NULL;
                return cg_fail(cg, binding->member->token,
                               "IE0001", "codegen: out of memory");
            }
            buf_append_fmt(cg->cur_body,
                           "        feng_aggregate_assign(&%s, &%s, &%s);\n",
                           binding->c_name,
                           r.c_expr,
                           desc);
        } else {
            char *cty = cg_ctype_dup(binding->type);

            if (cty == NULL) {
                er_free(&r);
                cg->cur_scope = NULL;
                scope_pop_free(fn_scope);
                cg->cur_body = NULL;
                return cg_fail(cg, binding->member->token, "IE0001", "codegen: out of memory");
            }
            if (cgtype_is_by_value_struct(binding->type)) {
                buf_append_fmt(cg->cur_body,
                               "        %s = %s;\n",
                               binding->c_name,
                               r.c_expr);
            } else {
                buf_append_fmt(cg->cur_body,
                               "        %s = (%s)(%s);\n",
                               binding->c_name,
                               cty,
                               r.c_expr);
            }
            free(cty);
        }
        er_free(&r);
        cg_release_scope(cg, fn_scope);
        buf_append_cstr(cg->cur_body, "    }\n");
        cg->cur_scope = NULL;
        scope_pop_free(fn_scope);
    }
    return true;
}

static bool cg_emit_type_static_binding_ensure_init(CG *cg,
                                                    const TypeStaticBinding *binding) {
    Buf *prev_body = cg->cur_body;
    Scope *prev_scope = cg->cur_scope;
    CGType *prev_return_type = cg->cur_return_type;
    bool prev_fn_is_main = cg->cur_fn_is_main;

    buf_append_fmt(&cg->fn_defs,
                   "%svoid %s(void) {\n",
                   binding->exports_public_surface ? "" : "static ",
                   binding->c_ensure_init_name);
    buf_append_fmt(&cg->fn_defs,
                   "    if (%s) return;\n",
                   binding->c_inited_name);

    cg->cur_body = &cg->fn_defs;
    if (!cg_emit_type_static_binding_init(cg, binding)) {
        cg->cur_body = prev_body;
        cg->cur_scope = prev_scope;
        cg->cur_return_type = prev_return_type;
        cg->cur_fn_is_main = prev_fn_is_main;
        return false;
    }

    cg->cur_body = &cg->fn_defs;
    buf_append_fmt(&cg->fn_defs,
                   "    %s = true;\n",
                   binding->c_inited_name);
    buf_append_cstr(&cg->fn_defs, "}\n\n");

    cg->cur_body = prev_body;
    cg->cur_scope = prev_scope;
    cg->cur_return_type = prev_return_type;
    cg->cur_fn_is_main = prev_fn_is_main;
    return true;
}

static bool cg_pass_emit_type_static_binding_ensure_inits(CG *cg) {
    for (size_t type_index = 0; type_index < cg->user_type_count; ++type_index) {
        const UserType *type = &cg->user_types[type_index];

        if (type->static_binding_count == 0U ||
            cg_user_type_is_generic_origin_instance(type) ||
            cg_program_origin(cg, type->owner_program) ==
                FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        if (!cg_emit_module_header(cg, type->owner_program)) {
            return false;
        }
        cg->cur_program = type->owner_program;
        for (size_t binding_index = 0; binding_index < type->static_binding_count; ++binding_index) {
            if (!cg_emit_type_static_binding_ensure_init(cg,
                                                         &type->static_bindings[binding_index])) {
                cg->cur_program = NULL;
                return false;
            }
        }
        cg->cur_program = NULL;
    }
    return true;
}

static bool cg_pass_emit_module_binding_ensure_inits(CG *cg, const FengProgram *prog) {
    if (cg_program_origin(cg, prog) == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        return true;
    }
    if (!cg_emit_module_header(cg, prog)) return false;
    cg->cur_program = prog;
    for (size_t i = 0; i < prog->declaration_count; i++) {
        const FengDecl *d = prog->declarations[i];
        const ModuleBinding *mb;

        if (d->kind != FENG_DECL_GLOBAL_BINDING) continue;
        mb = cg_find_module_binding_by_binding(cg, &d->as.binding);
        if (!mb) {
            cg->cur_program = NULL;
            return cg_fail(cg, d->token,
                "CE0361", "codegen: internal: module binding ensure-init emitted before registration");
        }
        if (!cg_emit_module_binding_ensure_init(cg, mb)) {
            cg->cur_program = NULL;
            return false;
        }
    }
    cg->cur_program = NULL;
    return true;
}

static bool cg_emit_main_wrapper(CG *cg, const FreeFn *main_fn) {
    Buf *b = &cg->fn_defs;

    if (!cg_debug_add_frame_record(cg,
                                   "main",
                                   "main",
                                   FENG_CODEGEN_MAPING_FRAME_HIDDEN,
                                   main_fn->decl->token)) {
        return false;
    }
    buf_append_cstr(b,
        "int main(int argc, char **argv) {\n");
    buf_append_cstr(b,
        "    FengArray *_args = feng_array_new(&feng_string_descriptor, sizeof(FengString *), true, (size_t)argc);\n"
        "    FengString **_slots = (FengString **)feng_array_data(_args);\n"
        "    for (int _i = 0; _i < argc; _i++) {\n"
        "        _slots[_i] = feng_string_literal(argv[_i], strlen(argv[_i]));\n"
        "    }\n");
    if (main_fn->return_type->kind == CG_TYPE_I32) {
        buf_append_fmt(b, "    int32_t _rc = %s(_args);\n", main_fn->c_name);
    } else {
        buf_append_fmt(b, "    %s(_args);\n", main_fn->c_name);
    }
    /* Release globals so leak-checkers stay quiet. */
    for (size_t i = 0; i < cg->module_binding_count; i++) {
        const ModuleBinding *mb = &cg->module_bindings[i];
        if (cgtype_is_managed(mb->type)) {
            buf_append_fmt(b, "    feng_release(%s); %s = NULL;\n",
                           mb->c_name, mb->c_name);
        } else if (cgtype_is_aggregate(mb->type)) {
            const char *desc = cg_aggregate_desc_name(mb->type);
            if (desc != NULL) {
                buf_append_fmt(b, "    feng_aggregate_release(&%s, &%s);\n",
                               mb->c_name, desc);
            }
        }
    }
    buf_append_cstr(b, "    feng_release(_args);\n");
    buf_append_cstr(b,
        "    feng_runtime_shutdown();\n");
    if (main_fn->return_type->kind == CG_TYPE_I32) {
        buf_append_cstr(b, "    return (int)_rc;\n}\n");
    } else {
        buf_append_cstr(b, "    return 0;\n}\n");
    }
    return true;
}

/* ===================== USER TYPE EMISSION (Phase 1A iter 2a) ===================== */

/* --- per-field lifetime / metadata helpers --------------------------------
 *
 * The three helpers below centralise the "how does this field participate in
 * ARC + cycle metadata" decision so cg_emit_user_type_definition can iterate
 * fields without re-deriving the rule each time. Each helper dispatches on
 * cgtype_value_kind(field_type):
 *
 *   TRIVIAL          — contributes nothing.
 *   MANAGED_POINTER  — one managed_fields[] entry; one feng_release() call.
 *   AGGREGATE        — flattened per docs/engineering/feng-value-model-delivered.md §7.2:
 *                      one descriptor per FENG_SLOT_POINTER slot inside the
 *                      aggregate (with offset = field_offset + slot_offset),
 *                      plus a feng_aggregate_release() call on the field
 *                      address. The currently-supported aggregate is the
 *                      object-form fat spec, whose layout has a single
 *                      managed `subject` pointer at slot offset 0.
 */

/* Compile-time aggregate introspection contract. This is intentionally a
 * codegen-only query: it must not emit generated-C runtime calls, allocate
 * per-value metadata, or modify the runtime descriptor ABI. New aggregate
 * kinds (tuple, value-struct, union value) join generic/field/array paths by
 * providing these static facts here plus their descriptor emission, not by
 * adding runtime dispatch. */
static void cg_spec_aggregate_emit_pointer_slot_rows(Buf *out,
                                                     const char *field_base_offsetof_expr,
                                                     const CGType *type) {
    if (type->user_spec != NULL && type->user_spec->form == FENG_SPEC_FORM_UNION) {
        buf_append_fmt(out,
            "    { %s, NULL, &%s },\n",
            field_base_offsetof_expr,
            type->user_spec->c_aggregate_desc_name);
        return;
    }
    buf_append_fmt(out,
        "    { %s + offsetof(struct %s, subject), NULL, NULL },\n",
        field_base_offsetof_expr,
        type->user_spec->c_value_struct_name);
}

static void cg_spec_aggregate_emit_cleanup_push(Buf *out,
                                                const char *cname,
                                                const CGType *type) {
    buf_append_fmt(out,
                   "    FengCleanupNode _cu_%s; feng_cleanup_push_aggregate(&_cu_%s, &%s, &%s);\n",
                   cname,
                   cname,
                   cname,
                   type->user_spec->c_aggregate_desc_name);
}

static void cg_spec_aggregate_emit_cleanup_zero(Buf *out,
                                                const char *cname,
                                                const CGType *type) {
    (void)type;
    buf_append_fmt(out, "memset(&%s, 0, sizeof %s);", cname, cname);
}

static void cg_value_aggregate_emit_pointer_slot_rows(Buf *out,
                                                      const char *field_base_offsetof_expr,
                                                      const CGType *type);
static void cg_value_aggregate_emit_cleanup_push(Buf *out,
                                                 const char *cname,
                                                 const CGType *type);
static void cg_value_aggregate_emit_cleanup_zero(Buf *out,
                                                 const char *cname,
                                                 const CGType *type);

static size_t cg_value_aggregate_flattened_pointer_slot_count(const UserType *value_type) {
    size_t count = 0U;

    if (!cg_user_type_is_value_semantics(value_type)) {
        return 0U;
    }
    for (size_t i = 0; i < value_type->field_count; ++i) {
        const CGType *field_type = value_type->fields[i].type;
        /* CG_TYPE_GENERIC_PARAM is CG_VK_TRIVIAL in cgtype_value_kind (ARC is
         * dispatch'd at call-site via descriptor), but inside a tuple it is a
         * potential managed slot — at runtime T may be string/array/object.
         * Count it so the tuple is classified as aggregate and triggers the
         * cleanup/retain/release paths. */
        if (field_type != NULL && field_type->kind == CG_TYPE_GENERIC_PARAM) {
            count++;
            continue;
        }
        switch (cgtype_value_kind(field_type)) {
            case CG_VK_TRIVIAL:
                break;
            case CG_VK_MANAGED_POINTER:
                count++;
                break;
            case CG_VK_AGGREGATE: {
                CGAggregateFacts nested = {0};
                if (cg_aggregate_facts(field_type, &nested)) {
                    count += nested.pointer_slot_count;
                }
                break;
            }
        }
    }
    return count;
}

static bool cg_aggregate_facts(const CGType *t, CGAggregateFacts *out) {
    CGAggregateFacts facts = {0};
    if (!t) {
        return false;
    }
    switch (t->kind) {
        case CG_TYPE_SPEC:
            if (t->user_spec == NULL) {
                return false;
            }
            if (t->user_spec->form != FENG_SPEC_FORM_OBJECT &&
                t->user_spec->form != FENG_SPEC_FORM_UNION &&
                t->user_spec->form != FENG_SPEC_FORM_INTERSECTION) {
                return false;
            }
            facts.value_kind = CG_VK_AGGREGATE;
            facts.descriptor_name = t->user_spec->c_aggregate_desc_name;
            facts.value_struct_name = t->user_spec->c_value_struct_name;
            facts.pointer_slot_count = 1U;
            facts.default_init_kind = CG_AGGREGATE_DEFAULT_INIT_DESCRIPTOR;
            if (facts.value_struct_name != NULL) {
                facts.emit_pointer_slot_rows = cg_spec_aggregate_emit_pointer_slot_rows;
            }
            facts.emit_cleanup_push = cg_spec_aggregate_emit_cleanup_push;
            facts.emit_cleanup_zero = cg_spec_aggregate_emit_cleanup_zero;
            break;
        case CG_TYPE_OBJECT:
            if (!cg_type_is_value_semantics(t)) {
                return false;
            }
            {
                size_t value_slot_count = cg_value_aggregate_flattened_pointer_slot_count(t->user);
                /* §2.4: 泛型值类型（tuple / @value type）全具体化实例始终走
                 * aggregate 路径——即使所有字段恰好为 trivial。声明阶段泛型
                 * 参数大小与托管性未知，统一生成 FengAggregateDescriptor。 */
                bool force_aggregate =
                    t->user->is_generic_instance &&
                    t->user->generic_context_type_param_count == 0U;

                facts.value_kind = (value_slot_count > 0U || force_aggregate)
                                       ? CG_VK_AGGREGATE
                                       : CG_VK_TRIVIAL;
                facts.descriptor_name = t->user->c_aggregate_desc_name;
                facts.value_struct_name = t->user->c_struct_name;
                facts.pointer_slot_count = value_slot_count;
                facts.default_init_kind = (value_slot_count > 0U || force_aggregate)
                                              ? CG_AGGREGATE_DEFAULT_INIT_DESCRIPTOR
                                              : CG_AGGREGATE_DEFAULT_INIT_ZERO_BYTES;
                if (facts.value_struct_name != NULL) {
                    facts.emit_pointer_slot_rows = cg_value_aggregate_emit_pointer_slot_rows;
                }
                facts.emit_cleanup_push = cg_value_aggregate_emit_cleanup_push;
                facts.emit_cleanup_zero = cg_value_aggregate_emit_cleanup_zero;
            }
            break;
        default:
            return false;
    }
    if (out != NULL) {
        *out = facts;
    }
    return true;
}

/* Returns the static FengAggregateDescriptor symbol for an aggregate
 * value type, or NULL if the type has no aggregate facts. */
static const char *cg_aggregate_desc_name(const CGType *t) {
    CGAggregateFacts facts;
    return cg_aggregate_facts(t, &facts) ? facts.descriptor_name : NULL;
}

/* Returns the flattened pointer-slot count used by object descriptors that
 * embed an aggregate field. */
static size_t cg_aggregate_pointer_slot_count(const CGType *t) {
    CGAggregateFacts facts;
    return cg_aggregate_facts(t, &facts) ? facts.pointer_slot_count : 0U;
}

/* Appends the aggregate default-initialization call/expression for one
 * lvalue. The chosen strategy is owned by the aggregate facts provider. */
static bool cg_append_aggregate_default_init_call(Buf *out,
                                                  const CGType *type,
                                                  const char *lvalue_expr) {
    CGAggregateFacts facts;
    if (out == NULL || lvalue_expr == NULL || !cg_aggregate_facts(type, &facts)) {
        return false;
    }
    switch (facts.default_init_kind) {
        case CG_AGGREGATE_DEFAULT_INIT_ZERO_BYTES:
            buf_append_fmt(out, "memset(&%s, 0, sizeof %s)", lvalue_expr, lvalue_expr);
            return true;
        case CG_AGGREGATE_DEFAULT_INIT_DESCRIPTOR:
            if (facts.descriptor_name == NULL) {
                return false;
            }
            buf_append_fmt(out, "feng_aggregate_default_init(&%s, &%s)",
                           lvalue_expr, facts.descriptor_name);
            return true;
        case CG_AGGREGATE_DEFAULT_INIT_NONE:
        default:
            return false;
    }
}

/* Walks the aggregate type's pointer slots and emits one
 * FengManagedFieldDescriptor row per slot at offset
 * `field_base_offsetof_expr + slot_offset_within_aggregate`. The
 * `field_base_offsetof_expr` is a complete C expression yielding the
 * field's offset in the enclosing struct (e.g.,
 * `offsetof(struct Foo, bar)`). For spec values we reuse the value
 * struct's own `offsetof(..., subject)` so the slot offset stays in sync
 * with the layout the C compiler picked. */
static void cg_emit_aggregate_pointer_slot_rows(Buf *td,
                                                const char *field_base_offsetof_expr,
                                                const CGType *t) {
    CGAggregateFacts facts;
    if (cg_aggregate_facts(t, &facts) && facts.emit_pointer_slot_rows != NULL) {
        facts.emit_pointer_slot_rows(td, field_base_offsetof_expr, t);
    }
}

static const char *cg_managed_pointer_static_desc_expr(const CGType *type) {
    if (type == NULL) {
        return "NULL";
    }
    switch (type->kind) {
        case CG_TYPE_STRING:
            return "&feng_string_descriptor";
        case CG_TYPE_ARRAY:
            return "&feng_array_descriptor";
        case CG_TYPE_OBJECT:
            if (cg_type_is_value_semantics(type)) {
                return "NULL";
            }
            if (type->user != NULL &&
                type->user->generic_context_type_param_count == 0U &&
                type->user->c_desc_name != NULL) {
                return type->user->c_desc_name;
            }
            return "NULL";
        default:
            return "NULL";
    }
}

static void cg_value_aggregate_emit_pointer_slot_rows(Buf *out,
                                                      const char *field_base_offsetof_expr,
                                                      const CGType *type) {
    if (!cg_type_is_value_semantics(type)) {
        return;
    }
    const UserType *value_type = type->user;
    for (size_t i = 0; i < value_type->field_count; ++i) {
        const UserField *field = &value_type->fields[i];
        switch (cgtype_value_kind(field->type)) {
            case CG_VK_TRIVIAL:
                break;
            case CG_VK_MANAGED_POINTER: {
                const char *static_desc = cg_managed_pointer_static_desc_expr(field->type);
                if (static_desc != NULL && static_desc[0] == '&') {
                    buf_append_fmt(out,
                        "    { %s + offsetof(struct %s, %s), %s, NULL },\n",
                        field_base_offsetof_expr,
                        value_type->c_struct_name,
                        field->c_name,
                        static_desc);
                } else if (static_desc != NULL && strcmp(static_desc, "NULL") != 0) {
                    buf_append_fmt(out,
                        "    { %s + offsetof(struct %s, %s), &%s, NULL },\n",
                        field_base_offsetof_expr,
                        value_type->c_struct_name,
                        field->c_name,
                        static_desc);
                } else {
                    buf_append_fmt(out,
                        "    { %s + offsetof(struct %s, %s), NULL, NULL },\n",
                        field_base_offsetof_expr,
                        value_type->c_struct_name,
                        field->c_name);
                }
                break;
            }
            case CG_VK_AGGREGATE: {
                Buf nested_base;
                buf_init(&nested_base);
                buf_append_fmt(&nested_base,
                               "%s + offsetof(struct %s, %s)",
                               field_base_offsetof_expr,
                               value_type->c_struct_name,
                               field->c_name);
                if (nested_base.data != NULL) {
                    cg_emit_aggregate_pointer_slot_rows(out, nested_base.data, field->type);
                }
                buf_free(&nested_base);
                break;
            }
        }
    }
}

static void cg_value_emit_cleanup_push_slots(Buf *out,
                                             const char *node_prefix,
                                             const char *lvalue_expr,
                                             const CGType *type) {
    switch (cgtype_value_kind(type)) {
        case CG_VK_TRIVIAL:
            return;
        case CG_VK_MANAGED_POINTER:
            buf_append_fmt(out,
                           "    FengCleanupNode _cu_%s; feng_cleanup_push(&_cu_%s, (void **)&%s);\n",
                           node_prefix,
                           node_prefix,
                           lvalue_expr);
            return;
        case CG_VK_AGGREGATE:
            if (type->kind == CG_TYPE_SPEC && type->user_spec != NULL) {
                buf_append_fmt(out,
                               "    FengCleanupNode _cu_%s; feng_cleanup_push_aggregate(&_cu_%s, &%s, &%s);\n",
                               node_prefix,
                               node_prefix,
                               lvalue_expr,
                               type->user_spec->c_aggregate_desc_name);
                return;
            }
            if (cg_type_is_value_semantics(type)) {
                const UserType *value_type = type->user;
                for (size_t i = 0; i < value_type->field_count; ++i) {
                    Buf child_prefix;
                    Buf child_lvalue;
                    buf_init(&child_prefix);
                    buf_init(&child_lvalue);
                    buf_append_fmt(&child_prefix, "%s_%zu", node_prefix, i);
                    buf_append_fmt(&child_lvalue, "%s.%s", lvalue_expr, value_type->fields[i].c_name);
                    if (child_prefix.data != NULL && child_lvalue.data != NULL) {
                        cg_value_emit_cleanup_push_slots(out,
                                                         child_prefix.data,
                                                         child_lvalue.data,
                                                         value_type->fields[i].type);
                    }
                    buf_free(&child_prefix);
                    buf_free(&child_lvalue);
                }
            }
            return;
    }
}

static void cg_value_emit_cleanup_zero_slots(Buf *out,
                                             const char *lvalue_expr,
                                             const CGType *type) {
    switch (cgtype_value_kind(type)) {
        case CG_VK_TRIVIAL:
            return;
        case CG_VK_MANAGED_POINTER:
            buf_append_fmt(out, "%s = NULL; ", lvalue_expr);
            return;
        case CG_VK_AGGREGATE:
            if (type->kind == CG_TYPE_SPEC && type->user_spec != NULL) {
                buf_append_fmt(out, "memset(&%s, 0, sizeof %s); ", lvalue_expr, lvalue_expr);
                return;
            }
            if (cg_type_is_value_semantics(type)) {
                const UserType *value_type = type->user;
                for (size_t i = 0; i < value_type->field_count; ++i) {
                    Buf child_lvalue;
                    buf_init(&child_lvalue);
                    buf_append_fmt(&child_lvalue, "%s.%s", lvalue_expr, value_type->fields[i].c_name);
                    if (child_lvalue.data != NULL) {
                        cg_value_emit_cleanup_zero_slots(out,
                                                         child_lvalue.data,
                                                         value_type->fields[i].type);
                    }
                    buf_free(&child_lvalue);
                }
            }
            return;
    }
}

static void cg_value_aggregate_emit_cleanup_push(Buf *out,
                                                 const char *cname,
                                                 const CGType *type) {
    cg_value_emit_cleanup_push_slots(out, cname, cname, type);
}

static void cg_value_aggregate_emit_cleanup_zero(Buf *out,
                                                 const char *cname,
                                                 const CGType *type) {
    cg_value_emit_cleanup_zero_slots(out, cname, type);
}

static size_t cg_field_managed_descriptor_count(CG *cg, const CGType *t,
                                                FengToken err_token) {
    switch (cgtype_value_kind(t)) {
        case CG_VK_TRIVIAL:         return 0U;
        case CG_VK_MANAGED_POINTER: return 1U;
        case CG_VK_AGGREGATE: {
            if (cg_aggregate_desc_name(t) == NULL) {
                (void)cg_fail(cg, err_token,
                    "CE0362", "codegen: aggregate field has no descriptor (unknown aggregate kind)");
                return 0U;
            }
            return 1U;
        }
    }
    return 0U;
}

static bool cg_emit_field_managed_descriptors(CG *cg, Buf *td,
                                              const char *struct_name,
                                              const char *field_c_name,
                                              const CGType *ft,
                                              FengToken err_token) {
    switch (cgtype_value_kind(ft)) {
        case CG_VK_TRIVIAL:
            return true;
        case CG_VK_MANAGED_POINTER:
            buf_append_fmt(td, "    { offsetof(struct %s, %s), ",
                           struct_name, field_c_name);
            switch (ft->kind) {
                case CG_TYPE_STRING:
                    buf_append_cstr(td, "&feng_string_descriptor");
                    break;
                case CG_TYPE_ARRAY:
                    buf_append_cstr(td, "&feng_array_descriptor");
                    break;
                case CG_TYPE_OBJECT:
                    if (ft->user != NULL &&
                        ft->user->generic_context_type_param_count == 0U &&
                        ft->user->c_desc_name != NULL) {
                        buf_append_fmt(td, "&%s", ft->user->c_desc_name);
                    } else {
                        buf_append_cstr(td, "NULL");
                    }
                    break;
                default:
                    buf_append_cstr(td, "NULL");
                    break;
            }
            buf_append_cstr(td, ", NULL },\n");
            return true;
        case CG_VK_AGGREGATE: {
            const char *aggregate_desc = cg_aggregate_desc_name(ft);

            if (aggregate_desc == NULL) {
                return cg_fail(cg, err_token,
                    "CE0362", "codegen: aggregate field has no descriptor (unknown aggregate kind)");
            }
            buf_append_fmt(td,
                "    { offsetof(struct %s, %s), NULL, &%s },\n",
                struct_name,
                field_c_name,
                aggregate_desc);
            return true;
        }
    }
    return true;
}

static bool cg_emit_field_release(CG *cg, Buf *td,
                                  const char *field_c_name,
                                  const CGType *ft,
                                  FengToken err_token) {
    switch (cgtype_value_kind(ft)) {
        case CG_VK_TRIVIAL:
            return true;
        case CG_VK_MANAGED_POINTER:
            buf_append_fmt(td, "    feng_release(_o->%s);\n", field_c_name);
            return true;
        case CG_VK_AGGREGATE: {
            const char *desc = cg_aggregate_desc_name(ft);
            if (desc == NULL) {
                return cg_fail(cg, err_token,
                    "CE0363", "codegen: aggregate field has no descriptor symbol (unknown aggregate kind)");
            }
            buf_append_fmt(td,
                "    feng_aggregate_release(&_o->%s, &%s);\n",
                field_c_name, desc);
            return true;
        }
    }
    return true;
}

/* Emit ABI surface for @value @abi types: layout struct, c_abi_ptr_name,
 * c_abi_value_name, and c_abi_base_offset. Does NOT emit c_abi_box_name
 * (@value types have no heap object; boxing belongs to §9.12).
 * The function bodies are identical to the regular @abi surface because
 * @value and @abi are orthogonal — @abi handles ABI layout independently
 * of whether the type is heap-allocated or value-semantic. */
static bool cg_emit_value_type_abi_surface(CG *cg, const UserType *t) {
    Buf *td = &cg->type_defs;

    if (!t->is_abi_type || t->c_abi_layout_name == NULL) {
        return true;
    }

    buf_append_fmt(td, "struct %s {\n", t->c_abi_layout_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        buf_append_cstr(td, "    ");
        cg_emit_c_type(td, t->fields[i].type);
        buf_append_fmt(td, " %s;\n", t->fields[i].c_name);
    }
    buf_append_cstr(td, "};\n\n");

    buf_append_fmt(td,
        "enum { %s = offsetof(struct %s, %s) };\n",
        t->c_abi_base_offset_name,
        t->c_struct_name,
        t->fields[0].c_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        buf_append_fmt(td,
            "_Static_assert(offsetof(struct %s, %s) - %s == "
            "offsetof(struct %s, %s), "
            "\"abi offset mismatch: %s.%s\");\n",
            t->c_struct_name,
            t->fields[i].c_name,
            t->c_abi_base_offset_name,
            t->c_abi_layout_name,
            t->fields[i].c_name,
            t->feng_name,
            t->fields[i].feng_name);
    }
    buf_append_fmt(td,
        "static inline struct %s *%s(struct %s *self) {\n"
        "    return (struct %s *)((char *)self + %s);\n"
        "}\n\n",
        t->c_abi_layout_name,
        t->c_abi_ptr_name,
        t->c_struct_name,
        t->c_abi_layout_name,
        t->c_abi_base_offset_name);

    buf_append_fmt(td,
        "static inline struct %s %s(const struct %s *self) {\n"
        "    struct %s _abi;\n",
        t->c_abi_layout_name,
        t->c_abi_value_name,
        t->c_struct_name,
        t->c_abi_layout_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        buf_append_fmt(td,
            "    _abi.%s = self->%s;\n",
            t->fields[i].c_name,
            t->fields[i].c_name);
    }
    buf_append_cstr(td, "    return _abi;\n}\n\n");

    /* c_abi_box_name is NOT emitted here: @value types have no heap object
     * and no FengTypeDescriptor. Boxing for @abi func interop belongs to
     * §9.12 which handles @abi func parameter/return ABI interop. */
    return true;
}

/* Emit `struct Feng__mod__T;` and the descriptor extern into `headers` so
 * cross references compile in any order. */
static bool cg_emit_user_type_abi_surface(CG *cg, const UserType *t) {
    Buf *td = &cg->type_defs;

    if (!t->is_abi_type || t->c_abi_layout_name == NULL) {
        return true;
    }

    /* @value @abi: delegate to the value-specific ABI surface emitter.
     * @value and @abi are orthogonal — each handles its own semantics
     * independently. @value types have no heap object, so c_abi_box_name
     * must not be emitted. */
    if (cg_user_type_is_value(t)) {
        return cg_emit_value_type_abi_surface(cg, t);
    }

    buf_append_fmt(td, "struct %s {\n", t->c_abi_layout_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        buf_append_cstr(td, "    ");
        cg_emit_c_type(td, t->fields[i].type);
        buf_append_fmt(td, " %s;\n", t->fields[i].c_name);
    }
    buf_append_cstr(td, "};\n\n");

    buf_append_fmt(td,
        "enum { %s = offsetof(struct %s, %s) };\n",
        t->c_abi_base_offset_name,
        t->c_struct_name,
        t->fields[0].c_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        buf_append_fmt(td,
            "_Static_assert(offsetof(struct %s, %s) - %s == "
            "offsetof(struct %s, %s), "
            "\"abi offset mismatch: %s.%s\");\n",
            t->c_struct_name,
            t->fields[i].c_name,
            t->c_abi_base_offset_name,
            t->c_abi_layout_name,
            t->fields[i].c_name,
            t->feng_name,
            t->fields[i].feng_name);
    }
    buf_append_fmt(td,
        "static inline struct %s *%s(struct %s *self) {\n"
        "    return (struct %s *)((char *)self + %s);\n"
        "}\n\n",
        t->c_abi_layout_name,
        t->c_abi_ptr_name,
        t->c_struct_name,
        t->c_abi_layout_name,
        t->c_abi_base_offset_name);

    buf_append_fmt(td,
        "static inline struct %s %s(const struct %s *self) {\n"
        "    struct %s _abi;\n",
        t->c_abi_layout_name,
        t->c_abi_value_name,
        t->c_struct_name,
        t->c_abi_layout_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        buf_append_fmt(td,
            "    _abi.%s = self->%s;\n",
            t->fields[i].c_name,
            t->fields[i].c_name);
    }
    buf_append_cstr(td, "    return _abi;\n}\n\n");

    buf_append_fmt(td,
        "static inline struct %s *%s(struct %s value) {\n"
        "    struct %s *_o = (struct %s *)feng_object_new(&%s);\n",
        t->c_struct_name,
        t->c_abi_box_name,
        t->c_abi_layout_name,
        t->c_struct_name,
        t->c_struct_name,
        t->c_desc_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        buf_append_fmt(td,
            "    _o->%s = value.%s;\n",
            t->fields[i].c_name,
            t->fields[i].c_name);
    }
    buf_append_cstr(td, "    return _o;\n}\n\n");
    return true;
}

static size_t cg_aggregate_top_level_slot_count(const UserType *t) {
    size_t count = 0U;

    if (!cg_user_type_is_value_semantics(t)) {
        return 0U;
    }
    for (size_t i = 0; i < t->field_count; ++i) {
        if (cgtype_value_kind(t->fields[i].type) != CG_VK_TRIVIAL) {
            count++;
        }
    }
    return count;
}

/* §9.16: Post-pass after field registration — update the aggregate descriptor
 * symbol name based on the computed value_kind for non-generic value-semantics
 * types (tuple and @value).
 *
 * cg_init_user_type_value_symbols runs before fields are registered and always
 * sets c_aggregate_desc_name to <struct>__aggregate_desc. After field types
 * are resolved we can distinguish trivial (all fields bit-copyable) from
 * aggregate (at least one managed slot) and rename the symbol accordingly:
 *   - trivial   → <struct>__trivial_desc
 *   - aggregate → <struct>__aggregate_desc   (unchanged)
 *
 * Generic concrete instances always use __aggregate_desc (§2.4: generic value
 * types uniformly walk the aggregate path regardless of reified field kinds).
 * Open generic instances (context_type_param_count > 0) are also skipped —
 * they never emit a descriptor definition. */
static bool cg_update_value_type_descriptor_names(CG *cg) {
    for (size_t i = 0; i < cg->user_type_count; i++) {
        UserType *t = &cg->user_types[i];

        if (!cg_user_type_is_value_semantics(t)) continue;
        /* 泛型具体实例一律 __aggregate_desc（§2.4），无需重命名。 */
        if (t->is_generic_instance) continue;

        size_t slot_count = cg_value_aggregate_flattened_pointer_slot_count(t);
        const char *suffix = (slot_count > 0U) ? "__aggregate_desc"
                                               : "__trivial_desc";
        Buf new_name;
        buf_init(&new_name);
        buf_append_fmt(&new_name, "%s%s", t->c_struct_name, suffix);
        if (new_name.data == NULL) {
            return cg_fail(cg, t->decl->token, "IE0001",
                           "codegen: out of memory");
        }
        /* 仅在 suffix 变更时替换（aggregate 沿用初始值，无需 free/realloc）。 */
        if (slot_count == 0U) {
            free(t->c_aggregate_desc_name);
            t->c_aggregate_desc_name = new_name.data;
        } else {
            buf_free(&new_name);
        }
    }
    return true;
}

/* Emit field-wise value-type equality used by both trivial and aggregate
 * descriptors (tuple and @value type). Field descriptors preserve string,
 * float, and nested aggregate semantics without changing non-generic call sites. */
static bool cg_emit_equal_function(CG *cg,
                                         UserType *t,
                                         const char *equal_fn_name) {
    Buf *td = &cg->type_defs;

    if (equal_fn_name == NULL) {
        return cg_fail(cg, t->decl->token, "CE0364", "codegen: missing value-type equality function name");
    }
    buf_append_fmt(td,
        "static bool %s(const void *left, const void *right) {\n"
        "    const struct %s *_left = (const struct %s *)left;\n"
        "    const struct %s *_right = (const struct %s *)right;\n"
        "    if (_left == _right) return true;\n"
        "    if (_left == NULL || _right == NULL) return false;\n",
        equal_fn_name,
        t->c_struct_name,
        t->c_struct_name,
        t->c_struct_name,
        t->c_struct_name);
    for (size_t i = 0; i < t->field_count; ++i) {
        const UserField *field = &t->fields[i];

        switch (cgtype_value_kind(field->type)) {
            case CG_VK_TRIVIAL: {
                char *descriptor_expr = cg_trivial_descriptor_expr(cg, field->type);

                if (descriptor_expr == NULL) {
                    /* Generic/open tuple fields can be erased placeholders at
                     * declaration emission time and may not have a concrete
                     * trivial descriptor yet. Keep declaration-time codegen
                     * valid by falling back to byte-wise equality on the
                     * emitted field representation. */
                    buf_append_fmt(td,
                        "    if (memcmp(&_left->%s, &_right->%s, sizeof(_left->%s)) != 0) {\n"
                        "        return false;\n"
                        "    }\n",
                        field->c_name,
                        field->c_name,
                        field->c_name);
                    break;
                }
                buf_append_fmt(td,
                    "    if ((%s)->equal_fn != NULL) {\n"
                    "        if (!(%s)->equal_fn(&_left->%s, &_right->%s)) return false;\n"
                    "    } else if (memcmp(&_left->%s, &_right->%s, (%s)->size) != 0) {\n"
                    "        return false;\n"
                    "    }\n",
                    descriptor_expr,
                    descriptor_expr,
                    field->c_name,
                    field->c_name,
                    field->c_name,
                    field->c_name,
                    descriptor_expr);
                free(descriptor_expr);
                break;
            }
            case CG_VK_MANAGED_POINTER: {
                char *descriptor_expr = cg_managed_pointer_descriptor_expr(field->type);

                if (descriptor_expr == NULL) {
                    return cg_fail(cg,
                                   t->decl->token,
                                   "CE0365", "codegen: value-type field '%s' has no managed equality descriptor",
                                   field->feng_name);
                }
                buf_append_fmt(td,
                    "    if ((%s)->equal_fn != NULL) {\n"
                    "        if (!(%s)->equal_fn(_left->%s, _right->%s)) return false;\n"
                    "    } else if (_left->%s != _right->%s) {\n"
                    "        return false;\n"
                    "    }\n",
                    descriptor_expr,
                    descriptor_expr,
                    field->c_name,
                    field->c_name,
                    field->c_name,
                    field->c_name);
                free(descriptor_expr);
                break;
            }
            case CG_VK_AGGREGATE: {
                const char *descriptor_name = cg_aggregate_desc_name(field->type);

                if (descriptor_name == NULL) {
                    return cg_fail(cg,
                                   t->decl->token,
                                   "CE0366", "codegen: value-type field '%s' has no aggregate equality descriptor",
                                   field->feng_name);
                }
                buf_append_fmt(td,
                    "    if ((&%s)->equal_fn == NULL) {\n"
                    "        feng_panic(\"value-type equality: aggregate field '%s' has no equality descriptor\");\n"
                    "    }\n"
                    "    if (!(&%s)->equal_fn(&_left->%s, &_right->%s)) return false;\n",
                    descriptor_name,
                    field->feng_name,
                    descriptor_name,
                    field->c_name,
                    field->c_name);
                break;
            }
        }
    }
    buf_append_cstr(td, "    return true;\n}\n\n");
    return true;
}

static void cg_emit_value_type_definition(CG *cg, UserType *t) {
    Buf *td = &cg->type_defs;
    size_t slot_count = cg_aggregate_top_level_slot_count(t);
    bool needs_agg_desc = slot_count > 0U ||
        (t->is_generic_instance && t->generic_context_type_param_count == 0U);
    Buf equal_fn_name;

    /* Struct body already emitted in cg_emit_user_type_forward (headers). */
    if (t->is_generic_instance && t->generic_context_type_param_count > 0U) {
        return;
    }

    /* @value @abi: emit ABI surface (layout struct, c_abi_ptr_name,
     * c_abi_value_name). Dispatches to cg_emit_value_type_abi_surface
     * via cg_emit_user_type_abi_surface's @value guard. */
    if (!cg_emit_user_type_abi_surface(cg, t)) {
        return;
    }

    if (t->c_aggregate_desc_name == NULL) {
        return;
    }
    buf_init(&equal_fn_name);
    buf_append_fmt(&equal_fn_name, "%s__equal", t->c_aggregate_desc_name);
    if (equal_fn_name.data == NULL) {
        (void)cg_fail(cg, t->decl->token, "IE0001", "codegen: out of memory");
        return;
    }
    if (!cg_emit_equal_function(cg, t, equal_fn_name.data)) {
        buf_free(&equal_fn_name);
        return;
    }

    if (slot_count > 0U) {
        buf_append_fmt(td,
            "static const FengManagedSlotDescriptor %s[] = {\n",
            t->c_aggregate_slots_name);
        for (size_t i = 0; i < t->field_count; ++i) {
            const UserField *field = &t->fields[i];
            switch (cgtype_value_kind(field->type)) {
                case CG_VK_TRIVIAL:
                    break;
                case CG_VK_MANAGED_POINTER:
                    buf_append_fmt(td,
                        "    { offsetof(struct %s, %s), FENG_SLOT_POINTER, NULL },\n",
                        t->c_struct_name,
                        field->c_name);
                    break;
                case CG_VK_AGGREGATE: {
                    const char *nested_desc = cg_aggregate_desc_name(field->type);
                    if (nested_desc == NULL) {
                        (void)cg_fail(cg,
                                      t->decl->token,
                                      "CE0367", "codegen: value-type field '%s' has no aggregate descriptor",
                                      field->feng_name);
                        buf_free(&equal_fn_name);
                        return;
                    }
                    buf_append_fmt(td,
                        "    { offsetof(struct %s, %s), FENG_SLOT_NESTED_AGGREGATE, &%s },\n",
                        t->c_struct_name,
                        field->c_name,
                        nested_desc);
                    break;
                }
            }
        }
        buf_append_cstr(td, "};\n\n");
    }

    if (slot_count > 0U) {
        Buf init_fn_name;

        buf_init(&init_fn_name);
        buf_append_fmt(&init_fn_name,
                       "%s__init",
                       t->c_aggregate_default_name);
        if (init_fn_name.data == NULL) {
            (void)cg_fail(cg, t->decl->token, "IE0001", "codegen: out of memory");
            buf_free(&equal_fn_name);
            return;
        }
        buf_append_fmt(td,
                       "static void %s(void *value_out) {\n"
                       "    struct %s *_out = (struct %s *)value_out;\n"
                       "    memset(_out, 0, sizeof *_out);\n",
                       init_fn_name.data,
                       t->c_struct_name,
                       t->c_struct_name);
        for (size_t i = 0; i < t->field_count; ++i) {
            const UserField *field = &t->fields[i];
            const FengToken *blame = field->member != NULL
                                         ? &field->member->token
                                         : &t->decl->token;

            switch (cgtype_value_kind(field->type)) {
                case CG_VK_TRIVIAL:
                    break;
                case CG_VK_MANAGED_POINTER: {
                    char *default_expr = NULL;

                    if (!cg_default_value_expr(cg,
                                               field->type,
                                               blame,
                                               &default_expr)) {
                        buf_free(&init_fn_name);
                        buf_free(&equal_fn_name);
                        return;
                    }
                    buf_append_fmt(td,
                                   "    _out->%s = %s;\n",
                                   field->c_name,
                                   default_expr);
                    free(default_expr);
                    break;
                }
                case CG_VK_AGGREGATE: {
                    Buf lvalue;
                    Buf init_call;

                    buf_init(&lvalue);
                    buf_init(&init_call);
                    buf_append_fmt(&lvalue, "_out->%s", field->c_name);
                    if (lvalue.data == NULL ||
                        !cg_append_aggregate_default_init_call(&init_call,
                                                               field->type,
                                                               lvalue.data)) {
                        buf_free(&lvalue);
                        buf_free(&init_call);
                        buf_free(&init_fn_name);
                        buf_free(&equal_fn_name);
                        (void)cg_fail(cg,
                                      *blame,
                                      "CE0368", "codegen: missing value-type field aggregate default initializer");
                        return;
                    }
                    buf_append_fmt(td, "    %s;\n", init_call.data);
                    buf_free(&lvalue);
                    buf_free(&init_call);
                    break;
                }
            }
        }
        buf_append_cstr(td, "}\n\n");
        buf_append_fmt(td,
            "static const FengAggregateDefaultInitDescriptor %s = {\n"
            "    .kind = FENG_DEFAULT_INIT_FN,\n"
            "    .init_fn = &%s,\n"
            "};\n",
            t->c_aggregate_default_name,
            init_fn_name.data);
        buf_free(&init_fn_name);
    } else if (needs_agg_desc) {
        buf_append_fmt(td,
            "static const FengAggregateDefaultInitDescriptor %s = {\n"
            "    .kind = FENG_DEFAULT_ZERO_BYTES,\n"
            "};\n",
            t->c_aggregate_default_name);
    }

    if (needs_agg_desc) {
        /* Reified generic params for fully-concrete generic value-type
         * instances (tuple / @value). Resolves the actual generic type args
         * so @value types whose fields do not 1:1 correspond to type
         * parameters (e.g. VGTagged<T> { label: string; value: T; }) emit
         * the correct descriptor table. */
        size_t tuple_rgp_count = 0U;
        if (t->is_generic_instance &&
            t->generic_context_type_param_count == 0U &&
            t->generic_type_arg_count > 0U) {
            const FengDecl *origin = t->generic_origin_decl;
            const UserSpec **rgp_constraints = NULL;
            if (origin != NULL &&
                !cg_build_generic_param_constraints(
                    cg, origin->as.type_decl.type_params,
                    origin->as.type_decl.type_param_count,
                    t->decl->token, &rgp_constraints)) {
                buf_free(&equal_fn_name);
                return;
            }
            const FengProgram *saved_program = cg->cur_program;
            if (t->instantiation_program != NULL) {
                cg->cur_program = t->instantiation_program;
            }
            tuple_rgp_count = t->generic_type_arg_count;
            buf_append_fmt(td,
                "static const FengGenericParamDescriptor *%s__rgp[] = {\n",
                t->c_aggregate_desc_name);
            for (size_t gi = 0; gi < t->generic_type_arg_count; ++gi) {
                CGType *arg_type = NULL;
                char *desc_expr = NULL;
                const UserSpec *cs = (rgp_constraints != NULL &&
                                     gi < (origin ? origin->as.type_decl.type_param_count : 0U))
                    ? rgp_constraints[gi] : NULL;

                if (!cg_resolve_type(cg, t->generic_type_args[gi],
                                     &t->decl->token, &arg_type)) {
                    free((void *)rgp_constraints);
                    cg->cur_program = saved_program;
                    buf_free(&equal_fn_name);
                    return;
                }
                if (!cg_generic_descriptor_expr(cg, arg_type, cs,
                                                &t->decl->token,
                                                &desc_expr)) {
                    cgtype_free(arg_type);
                    free((void *)rgp_constraints);
                    cg->cur_program = saved_program;
                    buf_free(&equal_fn_name);
                    return;
                }
                buf_append_fmt(td, "    %s,\n", desc_expr);
                free(desc_expr);
                cgtype_free(arg_type);
            }
            buf_append_cstr(td, "};\n\n");
            free((void *)rgp_constraints);
            cg->cur_program = saved_program;
        }

        /* Reified field offsets for fully-concrete generic tuple instances. */
        size_t tuple_rfo_count = 0U;
        if (t->is_generic_instance &&
            t->generic_context_type_param_count == 0U &&
            t->field_count > 0U) {
            tuple_rfo_count = t->field_count;
            buf_append_fmt(td,
                "static const size_t %s__rfo[] = {\n",
                t->c_aggregate_desc_name);
            for (size_t rfi = 0; rfi < t->field_count; ++rfi) {
                buf_append_fmt(td, "    offsetof(struct %s, %s),\n",
                               t->c_struct_name, t->fields[rfi].c_name);
            }
            buf_append_cstr(td, "};\n\n");
        }

        /* Reified deps for fully-concrete generic value-type instances.
         * The shared body of @value / tuple methods receives the aggregate
         * descriptor (not type descriptor), so it reads reified_agg_deps
         * and reified_type_deps from there. */
        size_t value_agg_dep_count = 0U;
        size_t value_type_dep_count = 0U;
        size_t value_callable_dep_count = 0U;
        if (t->is_generic_instance &&
            t->generic_context_type_param_count == 0U &&
            t->generic_origin_decl != NULL) {
            const FengReifiableDepSet *value_dep_set =
                feng_semantic_lookup_reifiable_dep_set(
                    cg->analysis, t->generic_origin_decl);
            if (value_dep_set != NULL && value_dep_set->dep_count > 0U) {
                const FengDecl *value_origin = t->generic_origin_decl;
                const FengTypeParam *value_owner_tparams =
                    value_origin->as.type_decl.type_params;
                size_t value_owner_tparam_count =
                    value_origin->as.type_decl.type_param_count;

                FengSlice *value_tp_names = (FengSlice *)calloc(
                    value_owner_tparam_count, sizeof(FengSlice));
                if (value_tp_names != NULL) {
                    for (size_t i = 0; i < value_owner_tparam_count; ++i) {
                        value_tp_names[i] = value_owner_tparams[i].name;
                    }

                    typedef struct { size_t idx; char *key; } VSD;
                    size_t vac = 0U, vtc = 0U;
                    for (size_t i = 0; i < value_dep_set->dep_count; ++i) {
                        if (value_dep_set->deps[i].kind ==
                            FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                            vac++;
                        } else {
                            vtc++;
                        }
                    }
                    VSD *va_s = vac > 0U ? (VSD *)calloc(vac, sizeof(VSD)) : NULL;
                    VSD *vt_s = vtc > 0U ? (VSD *)calloc(vtc, sizeof(VSD)) : NULL;

                    size_t vai = 0U, vti = 0U;
                    for (size_t i = 0; i < value_dep_set->dep_count; ++i) {
                        char *key = cg_reifiable_sort_key(
                            value_dep_set->deps[i].type_ref,
                            value_tp_names, value_owner_tparam_count, true);
                        if (value_dep_set->deps[i].kind ==
                            FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                            if (va_s != NULL) {
                                va_s[vai].idx = i; va_s[vai].key = key; vai++;
                            } else { free(key); }
                        } else {
                            if (vt_s != NULL) {
                                vt_s[vti].idx = i; vt_s[vti].key = key; vti++;
                            } else { free(key); }
                        }
                    }
                    for (size_t i = 1; i < vac; ++i) {
                        VSD tmp = va_s[i]; size_t j = i;
                        while (j > 0 && strcmp(va_s[j-1].key, tmp.key) > 0) {
                            va_s[j] = va_s[j-1]; j--;
                        }
                        va_s[j] = tmp;
                    }
                    for (size_t i = 1; i < vtc; ++i) {
                        VSD tmp = vt_s[i]; size_t j = i;
                        while (j > 0 && strcmp(vt_s[j-1].key, tmp.key) > 0) {
                            vt_s[j] = vt_s[j-1]; j--;
                        }
                        vt_s[j] = tmp;
                    }

                    const FengProgram *saved_prog = cg->cur_program;
                    if (t->instantiation_program != NULL) {
                        cg->cur_program = t->instantiation_program;
                    }

                    if (vac > 0U && va_s != NULL) {
                        value_agg_dep_count = vac;
                        buf_append_fmt(td,
                            "static const FengAggregateDescriptor *%s__rad[] = {\n",
                            t->c_aggregate_desc_name);
                        for (size_t i = 0; i < vac; ++i) {
                            const FengReifiableDep *dep =
                                &value_dep_set->deps[va_s[i].idx];
                            char *dn = cg_resolve_dep_descriptor_name(
                                cg, dep->type_ref,
                                value_owner_tparams, value_owner_tparam_count,
                                t->generic_type_args,
                                t->owner_program,
                                FENG_REIFIABLE_DEP_KIND_AGGREGATE,
                                &t->decl->token);
                            if (dn != NULL) {
                                buf_append_fmt(td, "    &%s,\n", dn);
                                free(dn);
                            }
                        }
                        buf_append_cstr(td, "};\n\n");
                    }
                    if (vtc > 0U && vt_s != NULL) {
                        value_type_dep_count = vtc;
                        buf_append_fmt(td,
                            "static const FengTypeDescriptor *%s__rtd[] = {\n",
                            t->c_aggregate_desc_name);
                        for (size_t i = 0; i < vtc; ++i) {
                            const FengReifiableDep *dep =
                                &value_dep_set->deps[vt_s[i].idx];
                            char *dn = cg_resolve_dep_descriptor_name(
                                cg, dep->type_ref,
                                value_owner_tparams, value_owner_tparam_count,
                                t->generic_type_args,
                                t->owner_program,
                                FENG_REIFIABLE_DEP_KIND_MANAGED,
                                &t->decl->token);
                            if (dn != NULL) {
                                buf_append_fmt(td, "    &%s,\n", dn);
                                free(dn);
                            }
                        }
                        buf_append_cstr(td, "};\n\n");
                    }

                    cg->cur_program = saved_prog;
                    for (size_t k = 0; k < vac; ++k) free(va_s[k].key);
                    for (size_t k = 0; k < vtc; ++k) free(vt_s[k].key);
                    free(va_s);
                    free(vt_s);
                    free(value_tp_names);
                }
            }
        }

        if (t->is_generic_instance &&
            t->generic_context_type_param_count == 0U &&
            t->generic_origin_decl != NULL) {
            const FengDecl *value_origin = t->generic_origin_decl;
            const FengReifiableDepSet *value_dep_set =
                feng_semantic_lookup_reifiable_dep_set(
                    cg->analysis, value_origin);
            const FengProgram *saved_program = cg->cur_program;

            if (t->instantiation_program != NULL) {
                cg->cur_program = t->instantiation_program;
            }
            if (!cg_emit_owner_callable_dep_array(
                    cg,
                    td,
                    t->c_aggregate_desc_name,
                    value_dep_set,
                    value_origin->as.type_decl.type_params,
                    value_origin->as.type_decl.type_param_count,
                    t->generic_type_args,
                    t->decl->token,
                    &value_callable_dep_count)) {
                cg->cur_program = saved_program;
                buf_free(&equal_fn_name);
                return;
            }
            cg->cur_program = saved_program;
        }

        bool ext_visible = cg_user_type_descriptor_is_externally_visible(cg, t);
        buf_append_fmt(td,
            ext_visible
                ? "const FengAggregateDescriptor %s __attribute__((weak, unused)) = {\n"
                : "static const FengAggregateDescriptor %s __attribute__((unused)) = {\n",
            t->c_aggregate_desc_name);
        buf_append_fmt(td,
            "    .name = \"%s.%s\",\n"
            "    .size = sizeof(struct %s),\n"
            "    .default_init = &%s,\n"
            "    .managed_slot_count = %zu,\n",
            cg->module_dot_name,
            t->feng_name,
            t->c_struct_name,
            t->c_aggregate_default_name,
            slot_count);
        if (slot_count > 0U) {
            buf_append_fmt(td, "    .managed_slots = %s,\n", t->c_aggregate_slots_name);
        } else {
            buf_append_cstr(td, "    .managed_slots = NULL,\n");
        }
        buf_append_fmt(td, "    .equal_fn = &%s,\n", equal_fn_name.data);
        if (tuple_rgp_count > 0U) {
            buf_append_fmt(td,
                "    .reified_generic_params_count = %zu,\n"
                "    .reified_generic_params = %s__rgp,\n",
                tuple_rgp_count, t->c_aggregate_desc_name);
        } else {
            buf_append_cstr(td,
                "    .reified_generic_params_count = 0,\n");
        }
        if (tuple_rfo_count > 0U) {
            buf_append_fmt(td,
                "    .reified_field_offset_count = %zu,\n"
                "    .reified_field_offsets = %s__rfo,\n",
                tuple_rfo_count, t->c_aggregate_desc_name);
        }
        if (value_agg_dep_count > 0U) {
            buf_append_fmt(td,
                "    .reified_agg_deps_count = %zu,\n"
                "    .reified_agg_deps = %s__rad,\n",
                value_agg_dep_count, t->c_aggregate_desc_name);
        }
        if (value_type_dep_count > 0U) {
            buf_append_fmt(td,
                "    .reified_type_deps_count = %zu,\n"
                "    .reified_type_deps = %s__rtd,\n",
                value_type_dep_count, t->c_aggregate_desc_name);
        }
        if (value_callable_dep_count > 0U) {
            buf_append_fmt(td,
                "    .reified_callable_deps_count = %zu,\n"
                "    .reified_callable_deps = %s__rcd,\n",
                value_callable_dep_count, t->c_aggregate_desc_name);
        }
        if (cg_user_type_uses_static_binding_states(t) &&
            (cg_program_origin(cg, t->owner_program) !=
                 FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE ||
             t->generic_context_type_param_count == 0U)) {
            char *states_name = cg_user_type_static_binding_states_name_dup(t);

            if (states_name == NULL) {
                (void)cg_fail(cg, t->decl->token,
                              "IE0001", "codegen: out of memory");
                buf_free(&equal_fn_name);
                return;
            }
            buf_append_fmt(td,
                "    .static_bindings = %s,\n",
                states_name);
            free(states_name);
        }
        buf_append_cstr(td, "};\n\n");
    } else {
        bool ext_visible = cg_user_type_descriptor_is_externally_visible(cg, t);
        buf_append_fmt(td,
            ext_visible
                ? "const FengTrivialDescriptor %s __attribute__((weak, unused)) = {\n"
                : "static const FengTrivialDescriptor %s __attribute__((unused)) = {\n",
            t->c_aggregate_desc_name);
        buf_append_fmt(td,
            "    .name = \"%s.%s\",\n"
            "    .size = sizeof(struct %s),\n"
            "    .equal_fn = &%s,\n"
            "};\n\n",
            cg->module_dot_name,
            t->feng_name,
            t->c_struct_name,
            equal_fn_name.data);
    }
    buf_free(&equal_fn_name);
    CGType tuple_value_type;
    memset(&tuple_value_type, 0, sizeof tuple_value_type);
    tuple_value_type.kind = CG_TYPE_OBJECT;
    tuple_value_type.user = t;

    size_t box_pointer_slot_count = cg_aggregate_pointer_slot_count(&tuple_value_type);
    buf_append_fmt(td,
                   "struct %s {\n"
                   "    FengManagedHeader _hdr;\n"
                   "    struct %s value;\n"
                   "};\n\n",
                   t->c_value_box_struct_name,
                   t->c_struct_name);
    if (box_pointer_slot_count > 0U) {
        Buf value_base;

        buf_init(&value_base);
        buf_append_fmt(&value_base,
                       "offsetof(struct %s, value)",
                       t->c_value_box_struct_name);
        if (value_base.data == NULL) {
            (void)cg_fail(cg, t->decl->token, "IE0001", "codegen: out of memory");
            return;
        }
        buf_append_fmt(td,
                       "static void %s(void *_self) {\n"
                       "    struct %s *_box = (struct %s *)_self;\n"
                       "    feng_aggregate_release(&_box->value, &%s);\n"
                       "}\n\n",
                       t->c_value_box_release_children_name,
                       t->c_value_box_struct_name,
                       t->c_value_box_struct_name,
                       t->c_aggregate_desc_name);
        buf_append_fmt(td,
                       "static const FengManagedFieldDescriptor %s__managed_fields[] = {\n",
                       t->c_value_box_desc_name);
        cg_emit_aggregate_pointer_slot_rows(td,
                                            value_base.data,
                                            &tuple_value_type);
        buf_append_cstr(td, "};\n\n");
        buf_free(&value_base);
    }
    {
        const char *box_kind = cg_user_type_is_tuple(t) ? "__tuple_box" : "__value_box";
        buf_append_fmt(td,
            "%sconst FengTypeDescriptor %s = {\n"
            "    .name = \"%s.%s.%s\",\n"
            "    .size = sizeof(struct %s),\n"
            "    .finalizer = NULL,\n"
            "    .release_children = %s,\n"
            "    .is_potentially_cyclic = %s,\n"
            "    .managed_field_count = %zu,\n",
            t->is_generic_instance ? "__attribute__((weak)) " : "",
            t->c_value_box_desc_name,
            cg->module_dot_name,
            t->feng_name,
            box_kind,
            t->c_value_box_struct_name,
            box_pointer_slot_count > 0U ? t->c_value_box_release_children_name : "NULL",
            box_pointer_slot_count > 0U ? "true" : "false",
            box_pointer_slot_count);
    }
    if (box_pointer_slot_count > 0U) {
        buf_append_fmt(td,
                       "    .managed_fields = %s__managed_fields,\n",
                       t->c_value_box_desc_name);
    } else {
        buf_append_cstr(td, "    .managed_fields = NULL,\n");
    }
    buf_append_cstr(td, "    .equal_fn = NULL,\n");
    buf_append_cstr(td, "    .reified_generic_params_count = 0,\n");
    buf_append_cstr(td, "};\n\n");
}

static void cg_emit_user_type_forward(CG *cg, const UserType *t) {
    if (cg_user_type_uses_static_binding_states(t) &&
        (cg_program_origin(cg, t->owner_program) !=
             FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE ||
         t->generic_context_type_param_count == 0U)) {
        char *states_name = cg_user_type_static_binding_states_name_dup(t);

        if (states_name == NULL) {
            (void)cg_fail(cg, t->decl->token,
                          "IE0001", "codegen: out of memory");
            return;
        }
        buf_append_fmt(&cg->headers,
                       "extern FengStaticBindingState %s[];\n",
                       states_name);
        free(states_name);
    }
    if (cg_user_type_is_value_semantics(t)) {
        if (t->field_count == 0U) {
            /* Zero-field value types (e.g. None()) have no type dependencies and
             * may be embedded by value in union spec value structs emitted
             * later in the same headers section. Emit the full definition
             * here so the type is complete when needed. */
            buf_append_fmt(&cg->headers, "struct %s {\n", t->c_struct_name);
            buf_append_cstr(&cg->headers, "    unsigned char _unit;\n");
            buf_append_cstr(&cg->headers, "};\n");
        } else {
            /* Non-empty value types may reference spec value types in their
             * fields, so only forward-declare here. The full body is
             * emitted after spec forwards. */
            buf_append_fmt(&cg->headers, "struct %s;\n", t->c_struct_name);
        }

        bool value_needs_agg = cg_aggregate_top_level_slot_count(t) > 0U ||
            (t->is_generic_instance && t->generic_context_type_param_count == 0U);
        const char *descriptor_type = value_needs_agg
                                          ? "FengAggregateDescriptor"
                                          : "FengTrivialDescriptor";

        bool ext_visible = cg_user_type_descriptor_is_externally_visible(cg, t);
        buf_append_fmt(&cg->headers,
                       ext_visible ? "extern const %s %s;\n" : "static const %s %s;\n",
                       descriptor_type,
                       t->c_aggregate_desc_name);
        buf_append_fmt(&cg->headers,
                       "struct %s;\nextern const FengTypeDescriptor %s;\n",
                       t->c_value_box_struct_name,
                       t->c_value_box_desc_name);
        if (t->is_abi_type && t->c_abi_layout_name != NULL) {
            buf_append_fmt(&cg->headers, "struct %s;\n", t->c_abi_layout_name);
        }
        return;
    }
    buf_append_fmt(&cg->headers, "struct %s;\n", t->c_struct_name);
    if (t->is_abi_type && t->c_abi_layout_name != NULL) {
        buf_append_fmt(&cg->headers, "struct %s;\n", t->c_abi_layout_name);
    }
    buf_append_fmt(&cg->headers, "extern const FengTypeDescriptor %s;\n",
                   t->c_desc_name);
}

/* Emit struct body, finalizer, and descriptor into `type_defs`. */
static void cg_emit_user_type_definition(CG *cg, UserType *t) {
    Buf *td = &cg->type_defs;
    bool descriptor_has_default_zero;

    if (cg_user_type_is_value_semantics(t)) {
        cg_emit_value_type_definition(cg, t);
        return;
    }
    descriptor_has_default_zero =
        cg_user_type_is_default_zero_safe(cg, t) &&
        (!t->is_generic_instance ||
         t->generic_context_type_param_count == 0U);
    if (descriptor_has_default_zero) {
        buf_append_fmt(
            &cg->headers,
            "static void %s__default_zero_init("
            "void *_out, const FengTypeDescriptor *_descriptor);\n",
            t->c_desc_name);
    }
    buf_append_fmt(td, "struct %s {\n", t->c_struct_name);
    buf_append_cstr(td, "    FengManagedHeader _hdr;\n");
    const UserType *open_inst = t->is_generic_instance
        ? cg_find_open_generic_instance(cg, t) : NULL;
    for (size_t i = 0; i < t->field_count; i++) {
        bool needs_pad = false;
        if (open_inst != NULL && i < open_inst->field_count &&
            open_inst->fields[i].type != NULL &&
            open_inst->fields[i].type->kind == CG_TYPE_GENERIC_PARAM) {
            switch (t->fields[i].type->kind) {
                case CG_TYPE_BOOL:
                case CG_TYPE_I8:  case CG_TYPE_U8:
                case CG_TYPE_I16: case CG_TYPE_U16:
                case CG_TYPE_I32: case CG_TYPE_U32:
                case CG_TYPE_F32:
                    needs_pad = true;
                    break;
                default:
                    break;
            }
        }
        if (needs_pad) {
            buf_append_cstr(td, "    _Alignas(sizeof(void *)) ");
        } else {
            buf_append_cstr(td, "    ");
        }
        cg_emit_c_type(td, t->fields[i].type);
        buf_append_fmt(td, " %s;\n", t->fields[i].c_name);
        if (needs_pad) {
            buf_append_fmt(td, "    char _pad_%s[sizeof(void *) - sizeof(",
                           t->fields[i].c_name);
            cg_emit_c_type(td, t->fields[i].type);
            buf_append_cstr(td, ")];\n");
        }
    }
    buf_append_cstr(td, "};\n\n");
    if (!cg_emit_user_type_abi_surface(cg, t)) {
        return;
    }

    /* release_children: codegen-emitted callback that drops every managed
     * field of an instance. Only emitted when the type actually holds at
     * least one managed reference; otherwise the descriptor's
     * .release_children slot is left NULL so the runtime can skip the call.
     * This is a separate concept from the user finalizer (which lives in
     * descriptor.finalizer); see docs/specifications/feng-lifetime.md §11/§13.2 and the
     * FengReleaseChildrenFn typedef in feng_runtime.h.
     *
     * Per-field dispatch goes through cg_emit_field_release so the AGGREGATE
     * branch (Step 4b) can hook in without touching this driver. */
    bool any_managed = false;
    for (size_t i = 0; i < t->field_count; i++) {
        if (cgtype_value_kind(t->fields[i].type) != CG_VK_TRIVIAL) {
            any_managed = true;
            break;
        }
    }
    /* UserType is allocated via calloc by the type registry; the cast is safe
     * because we own the only writer of this field. */
    if (any_managed) {
        Buf rcn; buf_init(&rcn);
        buf_append_fmt(&rcn, "%s__release_children", t->c_struct_name);
        t->c_release_children_name = rcn.data;

        buf_append_fmt(td, "static void %s(void *_self) {\n",
                       t->c_release_children_name);
        buf_append_fmt(td, "    struct %s *_o = (struct %s *)_self;\n",
                       t->c_struct_name, t->c_struct_name);
        for (size_t i = 0; i < t->field_count; i++) {
            if (!cg_emit_field_release(cg, td, t->fields[i].c_name,
                                       t->fields[i].type, t->decl->token)) {
                return;
            }
        }
        buf_append_cstr(td, "}\n\n");
    }

    /* User finalizer (`fn ~T()`). The thunk body is emitted later in Pass 4
     * — alongside methods — so it can resolve module-level externs and free
     * functions; here we only emit a forward declaration so the descriptor
     * below can take its address. The runtime invokes this through
     * descriptor.finalizer with `void *self` pointing at the
     * FengManagedHeader-prefixed instance. Per docs/specifications/feng-lifetime.md §13.2,
     * any uncaught exception escaping the body is a deterministic crash; that
     * barrier is enforced one layer up by feng_finalizer_invoke
     * (src/runtime/feng_object.c). */
    if (t->finalizer) {
        buf_append_fmt(td, "static void %s(void *_self);\n\n",
                       t->c_finalizer_name);
    }

    /* Phase 1B managed-field metadata: enumerate every slot of this type that
     * holds a managed reference. The cycle collector reads this table to do
     * non-mutating object traversal during trial deletion. The deterministic
     * ARC release path does NOT consult it; the user finalizer above remains
     * the sole owner of per-field release ordering.
     *
     * Per-field dispatch goes through cg_field_managed_descriptor_count and
     * cg_emit_field_managed_descriptors so AGGREGATE field flattening (Step
     * 4b) can be added in one place without re-walking this driver. */
    size_t managed_count = 0U;
    for (size_t i = 0; i < t->field_count; i++) {
        managed_count += cg_field_managed_descriptor_count(cg, t->fields[i].type,
                                                           t->decl->token);
    }
    if (managed_count > 0U) {
        buf_append_fmt(td,
            "static const FengManagedFieldDescriptor %s__managed_fields[] = {\n",
            t->c_desc_name);
        for (size_t i = 0; i < t->field_count; i++) {
            if (!cg_emit_field_managed_descriptors(cg, td, t->c_struct_name,
                                                   t->fields[i].c_name,
                                                   t->fields[i].type,
                                                   t->decl->token)) {
                return;
            }
        }
        buf_append_cstr(td, "};\n\n");
    }

    /* Reified fields for fully-concrete generic type instances.
     * Generated as static const arrays referenced by the descriptor. */
    size_t reified_generic_param_count = 0U;
    size_t reified_field_offset_count = 0U;
    size_t reified_agg_dep_count = 0U;
    size_t reified_type_dep_count = 0U;
    size_t reified_callable_dep_count = 0U;

    if (t->is_generic_instance &&
        t->generic_context_type_param_count == 0U &&
        t->generic_origin_decl != NULL) {
        const FengReifiableDepSet *dep_set =
            feng_semantic_lookup_reifiable_dep_set(
                cg->analysis, t->generic_origin_decl);

        /* Temporarily switch to instantiation_program so cg_resolve_type
         * can find types visible at the point where the generic instance
         * was created (e.g., test-defined types used as type args for a
         * std-library generic). Mirrors cg_register_user_type_members. */
        const FengProgram *saved_program = cg->cur_program;
        if (t->instantiation_program != NULL) {
            cg->cur_program = t->instantiation_program;
        }

        /* 3a. reified_generic_params — each entry carries the concrete
         * descriptor AND the constraint witness so the shared body can
         * call spec methods through _T->witness. */
        reified_generic_param_count = t->generic_type_arg_count;
        if (reified_generic_param_count > 0U) {
            const FengDecl *origin = t->generic_origin_decl;
            const UserSpec **rgp_constraints = NULL;
            if (!cg_build_generic_param_constraints(
                    cg, origin->as.type_decl.type_params,
                    origin->as.type_decl.type_param_count,
                    t->decl->token, &rgp_constraints)) {
                cg->cur_program = saved_program;
                return;
            }
            buf_append_fmt(td,
                "static const FengGenericParamDescriptor *%s__rgp[] = {\n",
                t->c_desc_name);
            for (size_t i = 0; i < t->generic_type_arg_count; ++i) {
                CGType *arg_type = NULL;
                char *desc_expr = NULL;
                const UserSpec *cs = (rgp_constraints != NULL &&
                                     i < origin->as.type_decl.type_param_count)
                    ? rgp_constraints[i] : NULL;

                if (!cg_resolve_type(cg, t->generic_type_args[i],
                                     &t->decl->token, &arg_type)) {
                    free((void *)rgp_constraints);
                    cg->cur_program = saved_program;
                    return;
                }
                if (!cg_generic_descriptor_expr(cg, arg_type, cs,
                                                &t->decl->token,
                                                &desc_expr)) {
                    cgtype_free(arg_type);
                    free((void *)rgp_constraints);
                    cg->cur_program = saved_program;
                    return;
                }
                buf_append_fmt(td, "    %s,\n", desc_expr);
                free(desc_expr);
                cgtype_free(arg_type);
            }
            buf_append_cstr(td, "};\n\n");
            free((void *)rgp_constraints);
        }

        /* 3b. reified_field_offsets */
        reified_field_offset_count = t->field_count;
        if (reified_field_offset_count > 0U) {
            buf_append_fmt(td,
                "static const size_t %s__rfo[] = {\n",
                t->c_desc_name);
            for (size_t i = 0; i < t->field_count; ++i) {
                buf_append_fmt(td, "    offsetof(struct %s, %s),\n",
                               t->c_struct_name, t->fields[i].c_name);
            }
            buf_append_cstr(td, "};\n\n");
        }

        /* 3c + 3d. reified_agg_deps / reified_type_deps */
        if (dep_set != NULL && dep_set->dep_count > 0U) {
            const FengDecl *origin = t->generic_origin_decl;
            const FengTypeParam *owner_tparams =
                origin->as.type_decl.type_params;
            size_t owner_tparam_count =
                origin->as.type_decl.type_param_count;

            /* Build owner type param name slices for sort key. */
            FengSlice *owner_tparam_names = (FengSlice *)calloc(
                owner_tparam_count, sizeof(FengSlice));
            if (owner_tparam_names == NULL) {
                cg->cur_program = saved_program;
                return;
            }
            for (size_t i = 0; i < owner_tparam_count; ++i) {
                owner_tparam_names[i] = owner_tparams[i].name;
            }

            /* Separate deps by kind, generate sort keys. */
            typedef struct {
                size_t dep_index;
                char *sort_key;
            } SortedDep;

            SortedDep *agg_sorted = NULL;
            SortedDep *type_sorted = NULL;
            size_t agg_count = 0U;
            size_t type_count = 0U;

            for (size_t i = 0; i < dep_set->dep_count; ++i) {
                if (dep_set->deps[i].kind ==
                    FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                    agg_count++;
                } else {
                    type_count++;
                }
            }

            if (agg_count > 0U) {
                agg_sorted = (SortedDep *)calloc(agg_count, sizeof(SortedDep));
            }
            if (type_count > 0U) {
                type_sorted = (SortedDep *)calloc(type_count,
                                                   sizeof(SortedDep));
            }

            size_t ai = 0U;
            size_t ti = 0U;
            for (size_t i = 0; i < dep_set->dep_count; ++i) {
                char *key = cg_reifiable_sort_key(
                    dep_set->deps[i].type_ref,
                    owner_tparam_names, owner_tparam_count, true);
                if (dep_set->deps[i].kind ==
                    FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                    if (agg_sorted != NULL) {
                        agg_sorted[ai].dep_index = i;
                        agg_sorted[ai].sort_key = key;
                        ai++;
                    } else {
                        free(key);
                    }
                } else {
                    if (type_sorted != NULL) {
                        type_sorted[ti].dep_index = i;
                        type_sorted[ti].sort_key = key;
                        ti++;
                    } else {
                        free(key);
                    }
                }
            }

            /* Sort by key lexicographic order. */
            for (size_t i = 1; i < agg_count; ++i) {
                SortedDep tmp = agg_sorted[i];
                size_t j = i;
                while (j > 0 &&
                       strcmp(agg_sorted[j - 1].sort_key,
                              tmp.sort_key) > 0) {
                    agg_sorted[j] = agg_sorted[j - 1];
                    j--;
                }
                agg_sorted[j] = tmp;
            }
            for (size_t i = 1; i < type_count; ++i) {
                SortedDep tmp = type_sorted[i];
                size_t j = i;
                while (j > 0 &&
                       strcmp(type_sorted[j - 1].sort_key,
                              tmp.sort_key) > 0) {
                    type_sorted[j] = type_sorted[j - 1];
                    j--;
                }
                type_sorted[j] = tmp;
            }

            /* 3c. Emit reified_agg_deps array. */
            if (agg_count > 0U && agg_sorted != NULL) {
                reified_agg_dep_count = agg_count;
                buf_append_fmt(td,
                    "static const FengAggregateDescriptor *%s__rad[] = {\n",
                    t->c_desc_name);
                for (size_t i = 0; i < agg_count; ++i) {
                    const FengReifiableDep *dep =
                        &dep_set->deps[agg_sorted[i].dep_index];
                    char *desc_name = cg_resolve_dep_descriptor_name(
                        cg, dep->type_ref,
                        owner_tparams, owner_tparam_count,
                        t->generic_type_args,
                        t->owner_program,
                        FENG_REIFIABLE_DEP_KIND_AGGREGATE,
                        &t->decl->token);
                    if (desc_name == NULL) {
                        for (size_t k = 0; k < agg_count; ++k) {
                            free(agg_sorted[k].sort_key);
                        }
                        for (size_t k = 0; k < type_count; ++k) {
                            free(type_sorted[k].sort_key);
                        }
                        free(agg_sorted);
                        free(type_sorted);
                        free(owner_tparam_names);
                        cg->cur_program = saved_program;
                        return;
                    }
                    buf_append_fmt(td, "    &%s,\n", desc_name);
                    free(desc_name);
                }
                buf_append_cstr(td, "};\n\n");
            }

            /* 3d. Emit reified_type_deps array. */
            if (type_count > 0U && type_sorted != NULL) {
                reified_type_dep_count = type_count;
                buf_append_fmt(td,
                    "static const FengTypeDescriptor *%s__rtd[] = {\n",
                    t->c_desc_name);
                for (size_t i = 0; i < type_count; ++i) {
                    const FengReifiableDep *dep =
                        &dep_set->deps[type_sorted[i].dep_index];
                    char *desc_name = cg_resolve_dep_descriptor_name(
                        cg, dep->type_ref,
                        owner_tparams, owner_tparam_count,
                        t->generic_type_args,
                        t->owner_program,
                        FENG_REIFIABLE_DEP_KIND_MANAGED,
                        &t->decl->token);
                    if (desc_name == NULL) {
                        for (size_t k = 0; k < agg_count; ++k) {
                            free(agg_sorted[k].sort_key);
                        }
                        for (size_t k = 0; k < type_count; ++k) {
                            free(type_sorted[k].sort_key);
                        }
                        free(agg_sorted);
                        free(type_sorted);
                        free(owner_tparam_names);
                        cg->cur_program = saved_program;
                        return;
                    }
                    buf_append_fmt(td, "    &%s,\n", desc_name);
                    free(desc_name);
                }
                buf_append_cstr(td, "};\n\n");
            }

            for (size_t i = 0; i < agg_count; ++i) {
                free(agg_sorted[i].sort_key);
            }
            for (size_t i = 0; i < type_count; ++i) {
                free(type_sorted[i].sort_key);
            }
            free(agg_sorted);
            free(type_sorted);
            free(owner_tparam_names);
        }

        if (!cg_emit_owner_callable_dep_array(
                cg,
                td,
                t->c_desc_name,
                dep_set,
                t->generic_origin_decl->as.type_decl.type_params,
                t->generic_origin_decl->as.type_decl.type_param_count,
                t->generic_type_args,
                t->decl->token,
                &reified_callable_dep_count)) {
            cg->cur_program = saved_program;
            return;
        }

        cg->cur_program = saved_program;
    }

    /* Look up Phase 1B cyclicity marker for this type. Acyclic types yield
     * zero collector overhead at runtime: feng_release skips the candidate
     * buffer entirely when descriptor->is_potentially_cyclic == false. */
    bool is_cyclic = feng_semantic_type_is_potentially_cyclic(cg->analysis, t->decl);

    buf_append_fmt(td,
        "%sconst FengTypeDescriptor %s = {\n"
        "    .name = \"%s.%s\",\n"
        "    .size = sizeof(struct %s),\n",
        t->is_generic_instance ? "__attribute__((weak)) " : "",
        t->c_desc_name,
        cg->module_dot_name, t->feng_name,
        t->c_struct_name);
    if (descriptor_has_default_zero) {
        buf_append_fmt(td,
                       "    .default_zero_init = %s__default_zero_init,\n",
                       t->c_desc_name);
    } else {
        buf_append_cstr(td, "    .default_zero_init = NULL,\n");
    }
    buf_append_fmt(td,
        "    .finalizer = %s,\n"
        "    .release_children = %s,\n"
        "    .is_potentially_cyclic = %s,\n"
        "    .managed_field_count = %zu,\n",
        t->c_finalizer_name ? t->c_finalizer_name : "NULL",
        t->c_release_children_name ? t->c_release_children_name : "NULL",
        is_cyclic ? "true" : "false",
        managed_count);
    if (managed_count > 0U) {
        buf_append_fmt(td,
            "    .managed_fields = %s__managed_fields,\n",
            t->c_desc_name);
    } else {
        buf_append_cstr(td, "    .managed_fields = NULL,\n");
    }
    /* 3e. Emit reified fields in the descriptor initializer. */
    if (reified_generic_param_count > 0U) {
        buf_append_fmt(td,
            "    .reified_generic_params_count = %zu,\n"
            "    .reified_generic_params = %s__rgp,\n",
            reified_generic_param_count, t->c_desc_name);
    }
    if (reified_field_offset_count > 0U) {
        buf_append_fmt(td,
            "    .reified_field_offset_count = %zu,\n"
            "    .reified_field_offsets = %s__rfo,\n",
            reified_field_offset_count, t->c_desc_name);
    }
    if (reified_agg_dep_count > 0U) {
        buf_append_fmt(td,
            "    .reified_agg_deps_count = %zu,\n"
            "    .reified_agg_deps = %s__rad,\n",
            reified_agg_dep_count, t->c_desc_name);
    }
    if (reified_type_dep_count > 0U) {
        buf_append_fmt(td,
            "    .reified_type_deps_count = %zu,\n"
            "    .reified_type_deps = %s__rtd,\n",
            reified_type_dep_count, t->c_desc_name);
    }
    if (reified_callable_dep_count > 0U) {
        buf_append_fmt(td,
            "    .reified_callable_deps_count = %zu,\n"
            "    .reified_callable_deps = %s__rcd,\n",
            reified_callable_dep_count, t->c_desc_name);
    }
    if (cg_user_type_uses_static_binding_states(t) &&
        (cg_program_origin(cg, t->owner_program) !=
             FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE ||
         t->generic_context_type_param_count == 0U)) {
        char *states_name = cg_user_type_static_binding_states_name_dup(t);

        if (states_name == NULL) {
            (void)cg_fail(cg, t->decl->token,
                          "IE0001", "codegen: out of memory");
            return;
        }
        buf_append_fmt(td,
            "    .static_bindings = %s,\n",
            states_name);
        free(states_name);
    }
    buf_append_cstr(td, "    .equal_fn = NULL,\n");
    buf_append_cstr(td, "};\n\n");

    /* Default-zero factory: per docs/specifications/feng-type.md §5/§7 every non-cyclic
     * user object type has a recursive default zero instance. The factory
     * allocates a fresh object via feng_object_new (which zeroes the struct
     * memory and runs no constructor) and then materialises non-zero
     * defaults for each managed field (string/array/object). Numeric/bool
     * fields stay 0 from the calloc inside feng_object_new. The returned
     * reference is owned by the caller (+1).
     *
     * Cyclic types intentionally have no factory; cg_default_value_expr
     * rejects them and the c_default_zero_name slot is freed below. */
    if (cg_user_type_is_default_zero_safe(cg, t)) {
        /* Forward declare into headers so default_zero callers in any pass
         * (including this same type's own field defaults) can reference it
         * regardless of source order. */
        buf_append_fmt(&cg->headers,
            "%sstruct %s *%s(void);\n",
            t->is_generic_instance ? "__attribute__((weak)) " : "",
            t->c_struct_name, t->c_default_zero_name);
        buf_append_fmt(td,
            "%sstruct %s *%s(void) {\n"
            "    struct %s *_o = (struct %s *)feng_object_new(&%s);\n",
            t->is_generic_instance ? "__attribute__((weak)) " : "",
            t->c_struct_name, t->c_default_zero_name,
            t->c_struct_name, t->c_struct_name, t->c_desc_name);
        for (size_t i = 0; i < t->field_count; i++) {
            const CGType *ft = t->fields[i].type;
            switch (ft->kind) {
                case CG_TYPE_GENERIC_PARAM:
                    break;
                case CG_TYPE_STRING:
                    buf_append_fmt(td,
                        "    _o->%s = feng_string_default();\n",
                        t->fields[i].c_name);
                    break;
                case CG_TYPE_ARRAY: {
                    char *desc = cg_array_element_descriptor(ft->element);
                    char *elem_cty = cg_ctype_dup(ft->element);
                    bool em = ft->element ? cgtype_is_managed(ft->element) : false;
                    bool ea = ft->element ? cgtype_is_aggregate(ft->element) : false;
                    if (ea) {
                        const char *agg_desc = cg_aggregate_desc_name(ft->element);
                        if (agg_desc != NULL) {
                            buf_append_fmt(td,
                                "    _o->%s = feng_array_new_kinded("
                                "FENG_VALUE_AGGREGATE_WITH_MANAGED_SLOTS, &%s, NULL, sizeof(%s), (size_t)0);\n",
                                t->fields[i].c_name, agg_desc,
                                elem_cty ? elem_cty : "void *");
                        } else {
                            buf_append_fmt(td,
                                "    _o->%s = feng_array_new(NULL, sizeof(%s), false, (size_t)0);\n",
                                t->fields[i].c_name,
                                elem_cty ? elem_cty : "void *");
                        }
                    } else {
                        buf_append_fmt(td,
                            "    _o->%s = feng_array_new(%s, sizeof(%s), %s, (size_t)0);\n",
                            t->fields[i].c_name, desc ? desc : "NULL",
                            elem_cty ? elem_cty : "void *", em ? "true" : "false");
                    }
                    free(desc);
                    free(elem_cty);
                    break;
                }
                case CG_TYPE_CALLABLE: {
                    const FengToken *field_token = t->fields[i].member != NULL
                                                       ? &t->fields[i].member->token
                                                       : &t->decl->token;
                    char *default_expr = NULL;

                    /* Open generic type instances are compile-time layout
                     * identities. Their type-parameter fields already keep
                     * the zeroed placeholder here; an open callable field
                     * must do the same because its concrete descriptor is
                     * supplied only by a closed instance. */
                    if (ft->user_spec != NULL &&
                        ft->user_spec->generic_context_type_param_count > 0U) {
                        break;
                    }
                    if (!cg_default_value_expr(cg, ft, field_token, &default_expr)) {
                        free(default_expr);
                        return;
                    }
                    buf_append_fmt(td,
                        "    _o->%s = %s;\n",
                        t->fields[i].c_name,
                        default_expr);
                    free(default_expr);
                    break;
                }
                case CG_TYPE_OBJECT:
                    if (ft->user) {
                        if (cg_user_type_is_value_semantics(ft->user)) {
                            char lvalue[512];
                            Buf init;

                            buf_init(&init);
                            if (snprintf(lvalue, sizeof(lvalue), "_o->%s", t->fields[i].c_name) > 0 &&
                                cg_append_aggregate_default_init_call(&init, ft, lvalue)) {
                                buf_append_fmt(td, "    %s;\n", init.data ? init.data : "");
                            } else {
                                buf_append_fmt(td,
                                    "    _o->%s = (struct %s){0};\n",
                                    t->fields[i].c_name,
                                    ft->user->c_struct_name);
                            }
                            buf_free(&init);
                        } else {
                            buf_append_fmt(td,
                                "    _o->%s = %s();\n",
                                t->fields[i].c_name,
                                ft->user->c_default_zero_name);
                        }
                    }
                    break;
                default:
                    /* Numeric/bool: feng_object_new already zeroed. */
                    break;
            }
        }
        buf_append_cstr(td, "    return _o;\n}\n\n");
    } else {
        free(t->c_default_zero_name);
        t->c_default_zero_name = NULL;
    }

    if (descriptor_has_default_zero) {
        /* Every closed instance already owns a statically generated recursive
         * default-zero factory. Using it here keeps private imported
         * representations local to the consumer and adds no runtime lookup. */
        buf_append_fmt(
            &cg->fn_defs,
            "static void %s__default_zero_init("
            "void *_out, const FengTypeDescriptor *_descriptor) {\n"
            "    (void)_descriptor;\n"
            "    *(void **)_out = %s();\n"
            "}\n\n",
            t->c_desc_name,
            t->c_default_zero_name);
    }
}

static void cg_free_cstr_array(char **items, size_t count) {
    if (!items) return;
    for (size_t i = 0; i < count; ++i) free(items[i]);
    free(items);
}

static void cg_free_const_cstr_array(const char **items, size_t count) {
    if (!items) return;
    for (size_t i = 0; i < count; ++i) free((void *)items[i]);
    free(items);
}

static bool cg_generic_type_param_names(CG *cg, const FengDecl *decl,
                                        char ***out_names) {
    size_t count = decl->as.type_decl.type_param_count;
    char **names = count ? calloc(count, sizeof *names) : NULL;
    if (count && !names) return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    for (size_t i = 0; i < count; ++i) {
        FengSlice name = decl->as.type_decl.type_params[i].name;
        names[i] = strndup(name.data, name.length);
        if (!names[i]) {
            cg_free_cstr_array(names, i);
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
    }
    *out_names = names;
    return true;
}

typedef enum CGGenericTypeMemberSymbolDomain {
    CG_GENERIC_TYPE_MEMBER_SYMBOL_INTERNAL = 0,
    CG_GENERIC_TYPE_MEMBER_SYMBOL_PACKAGE_BASE,
    CG_GENERIC_TYPE_MEMBER_SYMBOL_PACKAGE_DEPENDENCY
} CGGenericTypeMemberSymbolDomain;

/* Classify one generic type callable into the existing public domain, the
 * appended compiler-dependency portion of that domain, or the internal
 * domain. Existing public/capability ordinals are intentionally independent
 * of newly selected seal dependencies. */
static CGGenericTypeMemberSymbolDomain cg_generic_type_member_symbol_domain(
    const CG *cg,
    const FengDecl *decl,
    const FengTypeMember *member) {
    if (decl == NULL || member == NULL ||
        decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return CG_GENERIC_TYPE_MEMBER_SYMBOL_INTERNAL;
    }
    if (member->kind == FENG_TYPE_MEMBER_FINALIZER ||
        member->visibility != FENG_VISIBILITY_PRIVATE ||
        cg_member_is_mixable_seal_static(member)) {
        return CG_GENERIC_TYPE_MEMBER_SYMBOL_PACKAGE_BASE;
    }
    if (cg_member_is_package_symbol_dependency(cg, decl, member)) {
        return CG_GENERIC_TYPE_MEMBER_SYMBOL_PACKAGE_DEPENDENCY;
    }
    return CG_GENERIC_TYPE_MEMBER_SYMBOL_INTERNAL;
}

/* Return whether a local generic shared body keeps the existing package
 * linkage. Symbol-domain membership alone does not grant linkage to a member
 * that was collected only as a reifiable dependency. */
static bool cg_generic_member_exports_package_callable(
    const CG *cg,
    const FengDecl *owner_decl,
    const FengTypeMember *member,
    FengCompileTarget target) {
    if (target != FENG_COMPILE_TARGET_LIB || owner_decl == NULL ||
        member == NULL ||
        owner_decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return false;
    }
    if (member->kind == FENG_TYPE_MEMBER_METHOD) {
        return cg_member_uses_package_callable_surface(cg,
                                                       owner_decl,
                                                       member);
    }
    return member->kind == FENG_TYPE_MEMBER_FINALIZER ||
           member->visibility != FENG_VISIBILITY_PRIVATE;
}

/** Build the internal shared ensure-init symbol for one generic static field. */
static char *cg_generic_type_static_ensure_shared_cname(
    CG *cg,
    const FengDecl *decl,
    const FengTypeMember *member) {
    const GenericTypeDecl *generic_decl;
    const FengProgram *owner_program;
    char *owner_mangle;
    char *type_name;
    char *field_name;
    size_t ordinal = 0U;
    Buf symbol;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_TYPE ||
        member == NULL || member->kind != FENG_TYPE_MEMBER_FIELD ||
        !member->is_static) {
        return NULL;
    }
    generic_decl = cg_find_generic_type_decl_by_decl(cg, decl);
    owner_program = generic_decl != NULL
                        ? generic_decl->owner_program
                        : cg->cur_program;
    owner_mangle = owner_program != NULL
                       ? cg_module_mangle(owner_program->module_segments,
                                          owner_program->module_segment_count)
                       : (cg->module_mangle != NULL
                              ? strdup(cg->module_mangle)
                              : NULL);
    type_name = cg_sanitize(decl->as.type_decl.name.data,
                            decl->as.type_decl.name.length);
    field_name = cg_sanitize(member->as.field.name.data,
                             member->as.field.name.length);
    if (owner_mangle == NULL || type_name == NULL || field_name == NULL) {
        free(owner_mangle);
        free(type_name);
        free(field_name);
        return NULL;
    }
    for (size_t index = 0U;
         index < decl->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *candidate = decl->as.type_decl.members[index];

        if (candidate == member) {
            break;
        }
        if (candidate != NULL &&
            candidate->kind == FENG_TYPE_MEMBER_FIELD &&
            candidate->is_static) {
            ordinal++;
        }
    }
    buf_init(&symbol);
    buf_append_fmt(&symbol,
                   "FengGenericStaticEnsure__%s__%s__s%zu__%s",
                   owner_mangle,
                   type_name,
                   ordinal,
                   field_name);
    free(owner_mangle);
    free(type_name);
    free(field_name);
    return symbol.data;
}

static char *cg_generic_type_method_shared_cname(CG *cg,
                                                 const FengDecl *decl,
                                                 const FengTypeMember *member) {
    const GenericTypeDecl *gtd = cg_find_generic_type_decl_by_decl(cg, decl);
    const FengProgram *owner_program = gtd ? gtd->owner_program : NULL;
    if (owner_program == NULL) {
        /* Non-generic types have no GenericTypeDecl entry; look up the
         * UserType registry to find the correct owner_program (critical
         * for imported non-generic types with generic static methods). */
        const UserType *ut = cg_find_user_type_by_decl(cg, decl);
        owner_program = ut ? ut->owner_program : cg->cur_program;
    }
    char *owner_mangle = NULL;
    if (owner_program) {
        owner_mangle = cg_module_mangle(owner_program->module_segments,
                                        owner_program->module_segment_count);
    } else if (cg->module_mangle) {
        owner_mangle = strdup(cg->module_mangle);
    }
    char *type_san = cg_sanitize(decl->as.type_decl.name.data,
                                 decl->as.type_decl.name.length);
    char *method_san = cg_sanitize(member->as.callable.name.data,
                                   member->as.callable.name.length);
    if (!owner_mangle || !type_san || !method_san) {
        free(owner_mangle); free(type_san); free(method_san);
        return NULL;
    }
    Buf b; buf_init(&b);
    CGGenericTypeMemberSymbolDomain domain =
        cg_generic_type_member_symbol_domain(cg, decl, member);
    size_t ordinal = 0U;

    if (domain == CG_GENERIC_TYPE_MEMBER_SYMBOL_PACKAGE_DEPENDENCY) {
        /* Preserve every existing package-base ordinal, then append selected
         * compiler dependencies in declaration-relative order. */
        for (size_t index = 0U;
             index < decl->as.type_decl.member_count;
             ++index) {
            const FengTypeMember *candidate =
                decl->as.type_decl.members[index];

            if ((candidate->kind == FENG_TYPE_MEMBER_METHOD ||
                 candidate->kind == FENG_TYPE_MEMBER_CONSTRUCTOR ||
                 candidate->kind == FENG_TYPE_MEMBER_FINALIZER) &&
                cg_generic_type_member_symbol_domain(cg, decl, candidate) ==
                    CG_GENERIC_TYPE_MEMBER_SYMBOL_PACKAGE_BASE) {
                ordinal++;
            }
        }
    }
    for (size_t index = 0U;
         index < decl->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *candidate = decl->as.type_decl.members[index];

        if (candidate->kind != FENG_TYPE_MEMBER_METHOD &&
            candidate->kind != FENG_TYPE_MEMBER_CONSTRUCTOR &&
            candidate->kind != FENG_TYPE_MEMBER_FINALIZER) {
            continue;
        }
        if (cg_generic_type_member_symbol_domain(cg, decl, candidate) != domain) {
            continue;
        }
        if (candidate == member) {
            break;
        }
        ordinal++;
    }
    buf_append_fmt(&b, "FengGenericMethod__%s__%s__%s%zu__%s",
                   owner_mangle,
                   type_san,
                   domain == CG_GENERIC_TYPE_MEMBER_SYMBOL_INTERNAL ? "i" : "m",
                   ordinal,
                   method_san);
    free(owner_mangle); free(type_san); free(method_san);
    return b.data;
}

typedef enum CGGenericFitMethodSymbolDomain {
    CG_GENERIC_FIT_METHOD_SYMBOL_INTERNAL = 0,
    CG_GENERIC_FIT_METHOD_SYMBOL_PACKAGE_BASE,
    CG_GENERIC_FIT_METHOD_SYMBOL_PACKAGE_DEPENDENCY,
    CG_GENERIC_FIT_METHOD_SYMBOL_CAPABILITY
} CGGenericFitMethodSymbolDomain;

/* Classify one generic fit method using its existing capability facts and the
 * shared package-public Symbol selection. */
static CGGenericFitMethodSymbolDomain cg_generic_fit_method_symbol_domain(
    const CG *cg,
    const UserFit *uf,
    const FengTypeMember *member) {
    if (uf == NULL || uf->decl == NULL || member == NULL ||
        uf->decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return CG_GENERIC_FIT_METHOD_SYMBOL_INTERNAL;
    }
    if (cg_member_is_mixable_seal_static(member)) {
        return CG_GENERIC_FIT_METHOD_SYMBOL_CAPABILITY;
    }
    if (member->visibility != FENG_VISIBILITY_PRIVATE) {
        return CG_GENERIC_FIT_METHOD_SYMBOL_PACKAGE_BASE;
    }
    if (cg_member_is_package_symbol_dependency(cg, uf->decl, member)) {
        return CG_GENERIC_FIT_METHOD_SYMBOL_PACKAGE_DEPENDENCY;
    }
    return CG_GENERIC_FIT_METHOD_SYMBOL_INTERNAL;
}

/* Build a stable C symbol name for a fit method's shared body. Generic target
 * instances use their common origin declaration; a non-generic target uses
 * its declaration directly when the fit method itself is generic. */
static char *cg_fit_method_shared_cname(CG *cg,
                                        const UserFit *uf,
                                        const FengTypeMember *member) {
    const FengDecl *origin_decl = uf->target->generic_origin_decl != NULL
        ? uf->target->generic_origin_decl
        : uf->target->decl;
    if (origin_decl == NULL || origin_decl->kind != FENG_DECL_TYPE) return NULL;

    char *owner_mangle = NULL;
    if (uf->owner_program) {
        owner_mangle = cg_module_mangle(uf->owner_program->module_segments,
                                        uf->owner_program->module_segment_count);
    } else if (cg->module_mangle) {
        owner_mangle = strdup(cg->module_mangle);
    }
    char *type_san = cg_sanitize(origin_decl->as.type_decl.name.data,
                                 origin_decl->as.type_decl.name.length);
    char *method_san = cg_sanitize(member->as.callable.name.data,
                                   member->as.callable.name.length);
    if (!owner_mangle || !type_san || !method_san) {
        free(owner_mangle); free(type_san); free(method_san);
        return NULL;
    }
    CGGenericFitMethodSymbolDomain domain =
        cg_generic_fit_method_symbol_domain(cg, uf, member);
    size_t ordinal = 0U;
    const FengDecl *fit_decl = uf->decl;

    if (domain == CG_GENERIC_FIT_METHOD_SYMBOL_PACKAGE_DEPENDENCY) {
        for (size_t index = 0U;
             index < fit_decl->as.fit_decl.member_count;
             ++index) {
            const FengTypeMember *candidate =
                fit_decl->as.fit_decl.members[index];

            if (candidate->kind == FENG_TYPE_MEMBER_METHOD &&
                cg_generic_fit_method_symbol_domain(cg, uf, candidate) ==
                    CG_GENERIC_FIT_METHOD_SYMBOL_PACKAGE_BASE) {
                ordinal++;
            }
        }
    }
    for (size_t index = 0U;
         index < fit_decl->as.fit_decl.member_count;
         ++index) {
        const FengTypeMember *candidate = fit_decl->as.fit_decl.members[index];

        if (candidate->kind != FENG_TYPE_MEMBER_METHOD ||
            cg_generic_fit_method_symbol_domain(cg, uf, candidate) != domain) {
            continue;
        }
        if (candidate == member) {
            break;
        }
        ordinal++;
    }
    Buf b; buf_init(&b);
    buf_append_fmt(&b, "FengFitMethod__%s__%s__%s%zu__%s",
                   owner_mangle,
                   type_san,
                   domain == CG_GENERIC_FIT_METHOD_SYMBOL_CAPABILITY
                       ? "fc"
                       : (domain == CG_GENERIC_FIT_METHOD_SYMBOL_INTERNAL
                              ? "fi"
                              : "fm"),
                   ordinal,
                   method_san);
    free(owner_mangle); free(type_san); free(method_san);
    return b.data;
}

static bool cg_activate_generic_type_context(CG *cg,
                                             size_t type_param_count,
                                             char **type_param_names,
                                             const UserSpec **constraint_specs,
                                             const char **desc_names) {
    cg->in_generic_fn = true;
    cg->generic_fn_type_param_count = type_param_count;
    cg->generic_fn_type_param_names = type_param_names;
    cg->generic_fn_type_param_constraints = constraint_specs;
    cg->generic_fn_type_param_descs = desc_names;
    return true;
}

static void cg_clear_generic_type_context(CG *cg) {
    cg->in_generic_fn = false;
    cg->generic_return_uses_out = false;
    cg->generic_fn_type_param_count = 0;
    cg->generic_fn_type_param_names = NULL;
    cg->generic_fn_type_param_constraints = NULL;
    cg->generic_fn_type_param_descs = NULL;
    cg->in_generic_type_method = false;
    cg->generic_type_method_decl = NULL;
    cg->generic_type_method_field_offsets_name = NULL;
    for (size_t i = 0; i < cg->generic_type_method_rtd_count; i++) {
        free(cg->generic_type_method_rtd_descs[i]);
    }
    free(cg->generic_type_method_rtd_descs);
    cg->generic_type_method_rtd_descs = NULL;
    cg->generic_type_method_rtd_count = 0;
    cg->generic_type_method_rtd_via_desc = false;
    for (size_t i = 0; i < cg->generic_type_method_rad_count; i++) {
        free(cg->generic_type_method_rad_descs[i]);
    }
    free(cg->generic_type_method_rad_descs);
    cg->generic_type_method_rad_descs = NULL;
    cg->generic_type_method_rad_count = 0;
    cg->generic_type_method_rad_via_desc = false;
    for (size_t i = 0U; i < cg->generic_callable_dep_count; ++i) {
        free(cg->generic_callable_dep_keys[i]);
    }
    free(cg->generic_callable_dep_keys);
    cg->generic_callable_dep_keys = NULL;
    cg->generic_callable_dep_count = 0U;
    cg->generic_callable_dep_via_desc = false;
}

/* Build the nominal/type-layout view of the current owner used while emitting
 * a generic owner shared body. It is intentionally local to that body:
 * registering an erased self instance globally would let ordinary generic
 * lookup mistake it for a concrete program type. */
static bool cg_init_generic_owner_view(CG *cg,
                                       const FengDecl *decl,
                                       UserType *view) {
    const UserType *nominal_type;
    size_t field_count = 0U;
    size_t field_index = 0U;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_TYPE ||
        view == NULL) {
        return false;
    }
    nominal_type = cg_find_user_type_by_decl(cg, decl);
    /* Borrow the persistent nominal symbols and member tables, then replace
     * only the open layout data owned by this function-local view. A generic
     * declaration that has no nominal use may legitimately have no registered
     * instance; its local field view remains sufficient. */
    if (nominal_type != NULL) {
        *view = *nominal_type;
    } else {
        memset(view, 0, sizeof(*view));
    }
    view->fields = NULL;
    view->field_count = 0U;
    view->generic_type_args = NULL;
    view->generic_type_arg_count = 0U;
    for (size_t i = 0U; i < decl->as.type_decl.member_count; ++i) {
        const FengTypeMember *member = decl->as.type_decl.members[i];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_FIELD &&
            !member->is_static) {
            field_count++;
        }
    }
    view->decl = decl;
    view->is_generic_instance = true;
    view->is_ephemeral_generic_owner_view = true;
    view->generic_origin_decl = decl;
    view->generic_type_arg_count = decl->as.type_decl.type_param_count;
    view->generic_context_type_param_count =
        decl->as.type_decl.type_param_count;
    view->generic_context_type_param_names =
        cg->generic_fn_type_param_names;
    view->generic_context_type_param_constraint_indices = NULL;
    view->generic_type_args = view->generic_type_arg_count > 0U
        ? (FengTypeRef **)calloc(view->generic_type_arg_count,
                                sizeof(*view->generic_type_args))
        : NULL;
    view->fields = field_count > 0U
        ? (UserField *)calloc(field_count, sizeof(*view->fields))
        : NULL;
    if ((view->generic_type_arg_count > 0U &&
         view->generic_type_args == NULL) ||
        (field_count > 0U && view->fields == NULL)) {
        return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
    }
    for (size_t i = 0U; i < view->generic_type_arg_count; ++i) {
        FengTypeRef *arg = (FengTypeRef *)calloc(1U, sizeof(*arg));

        if (arg == NULL) {
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
        arg->token = decl->as.type_decl.type_params[i].token;
        arg->kind = FENG_TYPE_REF_NAMED;
        arg->as.named.segment_count = 1U;
        arg->as.named.segments =
            (FengSlice *)calloc(1U, sizeof(*arg->as.named.segments));
        if (arg->as.named.segments == NULL) {
            free(arg);
            return cg_fail(cg, decl->token, "IE0001", "codegen: out of memory");
        }
        arg->as.named.segments[0] =
            decl->as.type_decl.type_params[i].name;
        view->generic_type_args[i] = arg;
    }
    view->field_count = field_count;
    for (size_t i = 0U; i < decl->as.type_decl.member_count; ++i) {
        const FengTypeMember *member = decl->as.type_decl.members[i];
        UserField *field;

        if (member == NULL || member->kind != FENG_TYPE_MEMBER_FIELD ||
            member->is_static) {
            continue;
        }
        field = &view->fields[field_index++];
        field->member = member;
        field->feng_name = strndup(member->as.field.name.data,
                                   member->as.field.name.length);
        field->c_name = cg_sanitize(member->as.field.name.data,
                                    member->as.field.name.length);
        if (field->feng_name == NULL || field->c_name == NULL ||
            !cg_resolve_user_field_type(cg, view, member, &field->type)) {
            return false;
        }
    }
    return true;
}

/* Release a local generic-owner nominal/type-layout view. */
static void cg_free_generic_owner_view(UserType *view) {
    if (view == NULL) {
        return;
    }
    for (size_t i = 0U; i < view->field_count; ++i) {
        free(view->fields[i].feng_name);
        free(view->fields[i].c_name);
        cgtype_free(view->fields[i].type);
    }
    free(view->fields);
    for (size_t i = 0U; i < view->generic_type_arg_count; ++i) {
        cg_type_ref_free(view->generic_type_args[i]);
    }
    free(view->generic_type_args);
    memset(view, 0, sizeof(*view));
}

/* Build the Feng-level self expression used inside a shared method body.
 * Open generic owners retain their erased storage address because field
 * layout is descriptor-selected. Fixed-layout owners recover the concrete C
 * receiver view once at emission time; no runtime conversion is introduced. */
static char *cg_shared_method_self_expr(const UserType *owner,
                                        bool uses_reified_owner_layout) {
    Buf expression;

    if (owner == NULL) {
        return NULL;
    }
    if (uses_reified_owner_layout) {
        return strdup("_self");
    }
    if (owner->c_struct_name == NULL) {
        return NULL;
    }
    buf_init(&expression);
    if (cg_user_type_is_value_semantics(owner)) {
        buf_append_fmt(&expression,
                       "(*(struct %s *)_self)",
                       owner->c_struct_name);
    } else {
        buf_append_fmt(&expression,
                       "((struct %s *)_self)",
                       owner->c_struct_name);
    }
    return expression.data;
}

/** Emit the directly called shared ensure-init body for one generic static field. */
static bool cg_emit_generic_type_static_binding_ensure_shared(
    CG *cg,
    const FengDecl *decl,
    const FengTypeMember *member,
    FengCompileTarget target) {
    TypeStaticBinding generic_binding = {0};
    size_t type_param_count;
    char **type_param_names = NULL;
    const char **descriptor_names = NULL;
    const UserSpec **constraint_specs = NULL;
    char *function_name = NULL;
    Scope *function_scope = NULL;
    const char *descriptor_type;
    bool exports_public_surface;
    int saved_temp_counter;
    int saved_local_counter;
    bool ok = false;

    if (cg == NULL || decl == NULL || decl->kind != FENG_DECL_TYPE ||
        member == NULL || member->kind != FENG_TYPE_MEMBER_FIELD ||
        !member->is_static) {
        return false;
    }
    generic_binding.member = member;
    type_param_count = decl->as.type_decl.type_param_count;
    type_param_names = type_param_count > 0U
                           ? calloc(type_param_count,
                                    sizeof(*type_param_names))
                           : NULL;
    descriptor_names = type_param_count > 0U
                           ? calloc(type_param_count,
                                    sizeof(*descriptor_names))
                           : NULL;
    if (type_param_count > 0U &&
        (type_param_names == NULL || descriptor_names == NULL)) {
        cg_fail(cg, member->token,
                "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t index = 0U; index < type_param_count; ++index) {
        FengSlice name = decl->as.type_decl.type_params[index].name;
        Buf descriptor_name;

        type_param_names[index] = strndup(name.data, name.length);
        if (type_param_names[index] == NULL) {
            cg_fail(cg, member->token,
                    "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        buf_init(&descriptor_name);
        buf_append_fmt(&descriptor_name,
                       "_%s",
                       type_param_names[index]);
        descriptor_names[index] = descriptor_name.data;
        if (descriptor_names[index] == NULL) {
            cg_fail(cg, member->token,
                    "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }
    if (!cg_build_generic_param_constraints(cg,
                                             decl->as.type_decl.type_params,
                                             type_param_count,
                                             member->token,
                                             &constraint_specs)) {
        goto cleanup;
    }
    function_name = cg_generic_type_static_ensure_shared_cname(
        cg,
        decl,
        member);
    if (function_name == NULL) {
        cg_fail(cg, member->token,
                "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    descriptor_type = cg_type_decl_is_value_semantics(decl)
                          ? "FengAggregateDescriptor"
                          : "FengTypeDescriptor";
    exports_public_surface =
        target == FENG_COMPILE_TARGET_LIB &&
        cg_member_uses_package_static_binding_codegen(cg,
                                                       decl,
                                                       member);
    buf_append_fmt(&cg->fn_protos,
                   "%svoid %s(const %s *_type_desc, "
                   "FengStaticBindingState *_state);\n",
                   exports_public_surface ? "" : "static ",
                   function_name,
                   descriptor_type);
    buf_append_fmt(&cg->fn_defs,
                   "%svoid %s(const %s *_type_desc, "
                   "FengStaticBindingState *_state) {\n"
                   "    const %s *_td = _type_desc;\n"
                   "    (void)_type_desc; (void)_td;\n",
                   exports_public_surface ? "" : "static ",
                   function_name,
                   descriptor_type,
                   descriptor_type);
    for (size_t index = 0U; index < type_param_count; ++index) {
        buf_append_fmt(&cg->fn_defs,
            "    const FengGenericParamDescriptor *%s = "
            "_td->reified_generic_params[%zu];\n"
            "    (void)%s;\n",
            descriptor_names[index],
            index,
            descriptor_names[index]);
    }
    buf_append_cstr(&cg->fn_defs,
                    "    if (_state->initialized) return;\n");

    saved_temp_counter = cg->tmp_counter;
    saved_local_counter = cg->local_counter;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    cg_activate_generic_type_context(cg,
                                     type_param_count,
                                     type_param_names,
                                     constraint_specs,
                                     descriptor_names);
    cg->in_generic_type_method = true;
    cg->generic_type_method_decl = decl;
    cg->generic_type_method_field_offsets_name = NULL;
    {
        const FengReifiableDepSet *owner_dep_set =
            feng_semantic_lookup_reifiable_dep_set(cg->analysis, decl);
        FengSlice *active_param_names = type_param_count > 0U
            ? (FengSlice *)calloc(type_param_count,
                                  sizeof(*active_param_names))
            : NULL;

        if (type_param_count > 0U && active_param_names == NULL) {
            cg_fail(cg, member->token,
                    "IE0001", "codegen: out of memory");
            goto restore_context;
        }
        for (size_t index = 0U; index < type_param_count; ++index) {
            active_param_names[index] =
                decl->as.type_decl.type_params[index].name;
        }
        if (!cg_activate_reified_dependency_mapping(
                cg,
                owner_dep_set,
                active_param_names,
                type_param_count,
                CG_REIFIED_DEP_SOURCE_TYPE,
                member->token)) {
            free(active_param_names);
            goto restore_context;
        }
        free(active_param_names);
    }
    cg->cur_body = &cg->fn_defs;
    cg->cur_return_type = NULL;
    cg->cur_fn_is_main = false;
    function_scope = scope_push(NULL);
    if (function_scope == NULL) {
        cg_fail(cg, member->token,
                "IE0001", "codegen: out of memory");
        goto restore_context;
    }
    cg->cur_scope = function_scope;
    if (!cg_resolve_user_field_type(cg,
                                    NULL,
                                    member,
                                    &generic_binding.type)) {
        goto restore_context;
    }
    if (!cg_emit_type_static_binding_state_init(cg,
                                                &generic_binding,
                                                "_state")) {
        goto restore_context;
    }
    buf_append_cstr(&cg->fn_defs,
                    "    _state->initialized = true;\n"
                    "}\n\n");
    ok = true;

restore_context:
    if (function_scope != NULL) {
        cg->cur_scope = NULL;
        scope_pop_free(function_scope);
        function_scope = NULL;
    }
    cg->cur_body = NULL;
    cg->cur_return_type = NULL;
    cg_clear_generic_type_context(cg);
    cg->tmp_counter = saved_temp_counter;
    cg->local_counter = saved_local_counter;

cleanup:
    cgtype_free(generic_binding.type);
    free(function_name);
    free((void *)constraint_specs);
    cg_free_const_cstr_array(descriptor_names, type_param_count);
    cg_free_cstr_array(type_param_names, type_param_count);
    return ok;
}

static bool cg_emit_generic_type_method_shared(CG *cg, const FengDecl *decl,
                                               const FengTypeMember *member,
                                               FengCompileTarget target,
                                               bool has_func_desc,
                                               const char *shared_name_override,
                                               const FengDecl *reification_owner_decl,
                                               CGGenericConstructorInitMode init_mode) {
    const FengCallableSignature *sig = &member->as.callable;
    char *shared_name = shared_name_override
        ? strdup(shared_name_override)
        : cg_generic_type_method_shared_cname(cg, decl, member);
    if (!shared_name) return cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
    const FengDecl *package_owner = reification_owner_decl != NULL
        ? reification_owner_decl
        : decl;
    bool export_shared = cg_generic_member_exports_package_callable(
        cg,
        package_owner,
        member,
        target);
    bool is_static_method = member->is_static;

    size_t outer_tp_count = decl->as.type_decl.type_param_count;
    size_t method_tp_count = sig->type_param_count;
    size_t tp_count = outer_tp_count + method_tp_count;
    char **type_param_names = NULL;
    const UserSpec **constraint_specs = NULL;
    const char **desc_names = NULL;
    CGType *return_type = NULL;
    CGType **param_types = NULL;
    char **param_cnames = NULL;
    char **param_fnames = NULL;
    char **captured_names = NULL;
    size_t captured_name_count = 0U;
    char **saved_captured_names = cg->captured_binding_names;
    size_t saved_captured_name_count = cg->captured_binding_name_count;
    bool saved_captures_self = cg->current_callable_captures_self;
    const char *saved_function_descriptor_c_name =
        cg->generic_function_descriptor_c_name;
    UserType owner_view;
    bool owner_view_initialized = false;
    char *self_expr = NULL;
    Scope *fn_scope = NULL;
    int saved_tmp_counter = cg->tmp_counter;
    int saved_local_counter = cg->local_counter;
    bool ok = false;

    memset(&owner_view, 0, sizeof(owner_view));

    type_param_names = tp_count ? calloc(tp_count, sizeof *type_param_names) : NULL;
    desc_names = tp_count ? calloc(tp_count, sizeof *desc_names) : NULL;
    if ((tp_count > 0U) &&
        (type_param_names == NULL || desc_names == NULL)) {
        cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t i = 0; i < outer_tp_count; ++i) {
        FengSlice name = decl->as.type_decl.type_params[i].name;
        type_param_names[i] = strndup(name.data, name.length);
        if (type_param_names[i] == NULL) {
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }
    for (size_t i = 0; i < method_tp_count; ++i) {
        FengSlice name = sig->type_params[i].name;
        type_param_names[outer_tp_count + i] = strndup(name.data, name.length);
        if (type_param_names[outer_tp_count + i] == NULL) {
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }
    for (size_t i = 0; i < tp_count; ++i) {
        Buf b;
        buf_init(&b);
        buf_append_fmt(&b, "_%s", type_param_names[i]);
        desc_names[i] = b.data;
        if (desc_names[i] == NULL) {
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }
    {
        const CGTypeParamScope scope = {
            .first = decl->as.type_decl.type_params,
            .first_count = outer_tp_count,
            .second = sig->type_params,
            .second_count = method_tp_count,
        };

        if (!cg_type_param_scope_build_constraints(cg,
                                                   &scope,
                                                   member->token,
                                                   &constraint_specs)) {
            goto cleanup;
        }
    }

    cg_activate_generic_type_context(cg, tp_count, type_param_names,
                                     constraint_specs, desc_names);
    cg->generic_return_uses_out = true;
    cg->generic_function_descriptor_c_name = has_func_desc ? "_desc" : NULL;
    cg->in_generic_type_method = !is_static_method;
    cg->generic_type_method_decl = decl;
    cg->generic_type_method_field_offsets_name = is_static_method ? NULL : "_td->reified_field_offsets";

    /* Fields/constructors/finalizers select TYPE; ordinary methods select
     * FUNCTION. The same mapping owns all three dependency categories. */
    {
        const FengReifiableDepSet *dep_set = reification_owner_decl != NULL
            ? feng_semantic_lookup_member_reifiable_dep_set(
                  cg->analysis, reification_owner_decl, member)
            : has_func_desc && shared_name_override == NULL
                  ? feng_semantic_lookup_member_reifiable_dep_set(
                        cg->analysis, decl, member)
                  : feng_semantic_lookup_reifiable_dep_set(
                        cg->analysis, decl);
        FengSlice *active_param_names = tp_count > 0U
            ? (FengSlice *)calloc(tp_count, sizeof(*active_param_names))
            : NULL;

        if (tp_count > 0U && active_param_names == NULL) {
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        for (size_t index = 0U; index < outer_tp_count; ++index) {
            active_param_names[index] =
                decl->as.type_decl.type_params[index].name;
        }
        for (size_t index = 0U; index < method_tp_count; ++index) {
            active_param_names[outer_tp_count + index] =
                sig->type_params[index].name;
        }
        if (!cg_activate_reified_dependency_mapping(
                cg,
                dep_set,
                active_param_names,
                tp_count,
                has_func_desc
                    ? CG_REIFIED_DEP_SOURCE_FUNCTION
                    : CG_REIFIED_DEP_SOURCE_TYPE,
                member->token)) {
            free(active_param_names);
            goto cleanup;
        }
        free(active_param_names);
    }

    if (!cg_resolve_callable_return_type(
            cg, sig, member->token, &return_type)) goto cleanup;
    cg->cur_return_type = return_type;
    bool has_out_param = (return_type->kind != CG_TYPE_VOID);

    size_t param_count = sig->param_count;
    param_types = param_count ? calloc(param_count, sizeof *param_types) : NULL;
    param_cnames = param_count ? calloc(param_count, sizeof *param_cnames) : NULL;
    param_fnames = param_count ? calloc(param_count, sizeof *param_fnames) : NULL;
    if ((param_count && !param_types) || (param_count && !param_cnames) ||
        (param_count && !param_fnames)) {
        cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    for (size_t i = 0; i < param_count; ++i) {
        const FengParameter *param = &sig->params[i];
        if (!cg_resolve_type(cg, param->type, &param->token, &param_types[i])) goto cleanup;
        param_fnames[i] = strndup(param->name.data, param->name.length);
        Buf c_name; buf_init(&c_name);
        buf_append_fmt(&c_name, "_p_%.*s", (int)param->name.length, param->name.data);
        param_cnames[i] = c_name.data;
        if (!param_fnames[i] || !param_cnames[i]) {
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }

    /* §2.5: emit shared body prototype + definition signature.
     *
     * Instance method: void shared(void *_self,
     *                              const FengTypeDescriptor *_type_desc,
     *                              [method-level _U, ...],
     *                              <params>, [void *_out]);
     *   — type-level _K/_V extracted from _type_desc in prologue
     *
     * Static method:   void shared(const FengTypeDescriptor *_type_desc,
     *                              [method-level _U, ...],
     *                              <params>, [void *_out]);
     *   — type-level _K/_V extracted from _type_desc in prologue
     *
     * @value type: _type_desc is FengAggregateDescriptor (值类型没有
     * FengTypeDescriptor，reified_generic_params 在聚合描述符上)。 */
    const char *type_desc_c_type = cg_type_decl_is_value_semantics(decl)
        ? "FengAggregateDescriptor" : "FengTypeDescriptor";

    /* Helper: emit the parameter list for proto or body. */
    #define EMIT_SHARED_PARAMS(buf_ptr, has_param_ptr)                            \
    do {                                                                            \
        if (!is_static_method) {                                                   \
            buf_append_fmt((buf_ptr),                                              \
                "void *_self, const %s *_type_desc", type_desc_c_type);            \
            *(has_param_ptr) = true;                                               \
        } else {                                                                   \
            buf_append_fmt((buf_ptr), "const %s *_type_desc", type_desc_c_type);   \
            *(has_param_ptr) = true;                                               \
        }                                                                          \
        if (has_func_desc) {                                                       \
            if (*(has_param_ptr)) buf_append_cstr((buf_ptr), ", ");                \
            buf_append_cstr((buf_ptr),                                             \
                            "const FengFunctionDescriptor *_desc");                \
            *(has_param_ptr) = true;                                               \
        }                                                                          \
        for (size_t _i = outer_tp_count; _i < tp_count; ++_i) {                   \
            if (*(has_param_ptr)) buf_append_cstr((buf_ptr), ", ");                \
            buf_append_fmt((buf_ptr),                                              \
                           "const FengGenericParamDescriptor *%s",                 \
                           desc_names[_i]);                                        \
            *(has_param_ptr) = true;                                               \
        }                                                                          \
        for (size_t _i = 0; _i < param_count; ++_i) {                             \
            if (*(has_param_ptr)) buf_append_cstr((buf_ptr), ", ");                \
            if (cg_shared_generic_param_uses_address(param_types[_i])) {          \
                buf_append_fmt((buf_ptr), "const void *%s", param_cnames[_i]);     \
            } else {                                                               \
                cg_emit_c_type((buf_ptr), param_types[_i]);                        \
                buf_append_fmt((buf_ptr), " %s", param_cnames[_i]);                \
            }                                                                      \
            *(has_param_ptr) = true;                                               \
        }                                                                          \
        if (has_out_param) {                                                        \
            if (*(has_param_ptr)) buf_append_cstr((buf_ptr), ", ");                \
            buf_append_cstr((buf_ptr), "void *_out");                              \
            *(has_param_ptr) = true;                                               \
        }                                                                          \
    } while (0)

    Buf *proto = &cg->fn_protos;
    if (!export_shared) {
        buf_append_cstr(proto, "static ");
    }
    buf_append_fmt(proto, "void %s(", shared_name);
    {
        bool proto_has_param = false;
        EMIT_SHARED_PARAMS(proto, &proto_has_param);
        if (!proto_has_param) buf_append_cstr(proto, "void");
    }
    buf_append_cstr(proto, ");\n");

    Buf *body = &cg->fn_defs;
    cg->cur_body = body;
    if (!export_shared) {
        buf_append_cstr(body, "static ");
    }
    buf_append_fmt(body, "void %s(", shared_name);
    {
        bool body_has_param = false;
        EMIT_SHARED_PARAMS(body, &body_has_param);
        if (!body_has_param) buf_append_cstr(body, "void");
    }
    buf_append_cstr(body, ") {\n");

    /* §2.5 prologue: extract _td and type-level generic params from descriptor. */
    buf_append_fmt(body,
        "    const %s *_td = _type_desc;\n"
        "    (void)_type_desc; (void)_td;\n", type_desc_c_type);
    if (!is_static_method) {
        buf_append_cstr(body, "    (void)_self;\n");
    }
    if (has_func_desc) {
        buf_append_cstr(body, "    (void)_desc;\n");
    }
    for (size_t i = 0; i < outer_tp_count; ++i) {
        buf_append_fmt(body,
            "    const FengGenericParamDescriptor *%s = "
            "_td->reified_generic_params[%zu];\n",
            desc_names[i], i);
        buf_append_fmt(body, "    (void)%s;\n", desc_names[i]);
    }
    for (size_t i = outer_tp_count; i < tp_count; ++i) {
        buf_append_fmt(body, "    (void)%s;\n", desc_names[i]);
    }

    #undef EMIT_SHARED_PARAMS
    for (size_t i = 0; i < param_count; ++i) {
        buf_append_fmt(body, "    (void)%s;\n", param_cnames[i]);
    }
    if (has_out_param) buf_append_cstr(body, "    (void)_out;\n");

    fn_scope = scope_push(NULL);
    if (!fn_scope) {
        cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->cur_scope = fn_scope;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    cg->loop_depth = 0;
    cg->try_depth = 0;
    cg->cur_fn_is_main = false;
    cg->active_exception_frame_count = 0;
    cg->active_caught_unwind_count = 0;
    cg->cur_function_has_frame_marker = false;

    if (!cg_emit_function_eh_prologue(cg, member->token)) {
        goto cleanup;
    }

    if (!cg_compute_capture_requirements_in_block(
            sig->body,
            &captured_names,
            &captured_name_count,
            &cg->current_callable_captures_self)) {
        cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->captured_binding_names = captured_names;
    cg->captured_binding_name_count = captured_name_count;

    if (!is_static_method) {
        owner_view_initialized = true;
        if (!cg_init_generic_owner_view(cg, decl, &owner_view)) {
            goto cleanup;
        }
        self_expr = cg_shared_method_self_expr(
            &owner_view,
            outer_tp_count > 0U);
        if (self_expr == NULL) {
            cg_fail(cg,
                    member->token,
                    "IE0001", "codegen: failed to form shared method receiver");
            goto cleanup;
        }
    }

    if (!is_static_method && cg->current_callable_captures_self) {
        FengSlice self_name = {"self", 4U};
        CGType *self_type = cgtype_new(CG_TYPE_OBJECT);
        if (self_type != NULL) {
            self_type->user = &owner_view;
        }
        if (self_type == NULL ||
            !cg_scope_bind_capture_cell(
                cg,
                fn_scope,
                self_name,
                self_type,
                member->token,
                self_expr,
                true,
                false,
                true,
                FENG_CODEGEN_MAPING_VARIABLE_SELF) ||
            !scope_mark_last_binding_mutability(fn_scope,
                                                FENG_MUTABILITY_LET)) {
            cgtype_free(self_type);
            goto cleanup;
        }
        cgtype_free(self_type);
    } else if (!is_static_method) {
        CGType *self_type = cgtype_new(CG_TYPE_OBJECT);
        if (self_type != NULL) {
            self_type->user = &owner_view;
        }
        if (!self_type || !scope_add(fn_scope, "self", self_expr, self_type, true) ||
            !scope_mark_last_binding_mutability(fn_scope,
                                                FENG_MUTABILITY_LET)) {
            cgtype_free(self_type);
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        /* An open generic value owner keeps its descriptor-sized storage
         * address marker. A fixed-layout owner was already dereferenced by
         * self_expr and therefore follows ordinary value-member lowering. */
        if (outer_tp_count > 0U &&
            cg_type_decl_is_value_semantics(decl) &&
            !scope_mark_last_storage_address(fn_scope)) {
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
    }
    for (size_t i = 0; i < param_count; ++i) {
        if (cg_current_callable_captures_name(
                cg, param_fnames[i], strlen(param_fnames[i]))) {
            if (!cg_scope_bind_capture_cell(
                    cg,
                    fn_scope,
                    sig->params[i].name,
                    param_types[i],
                    sig->params[i].token,
                    param_cnames[i],
                    true,
                    false,
                    true,
                    FENG_CODEGEN_MAPING_VARIABLE_PARAM) ||
                !scope_mark_last_binding_mutability(
                    fn_scope, sig->params[i].mutability)) {
                goto cleanup;
            }
            continue;
        }
        CGType *pt = cgtype_clone(param_types[i]);
        if (!pt || !scope_add(fn_scope, param_fnames[i], param_cnames[i], pt, true) ||
            !scope_mark_last_binding_mutability(
                fn_scope, sig->params[i].mutability)) {
            cgtype_free(pt);
            cg_fail(cg, member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (!cg_mark_last_shared_address_parameter(cg,
                                                   fn_scope,
                                                   param_types[i],
                                                   sig->params[i].token)) {
            goto cleanup;
        }
    }

    if (member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR) {
        if (!(init_mode == CG_GENERIC_CONSTRUCTOR_INIT_DEFAULT_ZERO
                  ? cg_emit_user_type_default_field_values(
                        cg, &owner_view, "_self", member->token)
                  : cg_emit_user_type_member_initializers(
                        cg, &owner_view, "_self", member->token))) {
            goto cleanup;
        }
    }
    if (!cg_emit_block(cg, sig->body)) goto cleanup;
    cg_release_scope(cg, fn_scope);
    cg_emit_function_fallthrough_cleanup(cg);
    if (return_type->kind == CG_TYPE_VOID) {
        buf_append_cstr(body, "    return;\n");
    } else {
        buf_append_cstr(body,
            "    feng_panic(\"generic method reached end without return\");\n");
    }
    buf_append_cstr(body, "}\n\n");
    ok = true;

cleanup:
    if (!ok && !cg->failed) {
        cg_fail(cg, member->token,
            "CE0369", "codegen: internal: failed to emit shared generic method '%.*s'",
            (int)sig->name.length,
            sig->name.data);
    }
    if (fn_scope) {
        cg->cur_scope = NULL;
        scope_pop_free(fn_scope);
    }
    if (owner_view_initialized) {
        cg_free_generic_owner_view(&owner_view);
    }
    free(self_expr);
    cg->cur_body = NULL;
    cg->cur_return_type = NULL;
    cg->cur_function_has_frame_marker = false;
    cg->captured_binding_names = saved_captured_names;
    cg->captured_binding_name_count = saved_captured_name_count;
    cg->current_callable_captures_self = saved_captures_self;
    for (size_t i = 0; i < captured_name_count; ++i) {
        free(captured_names[i]);
    }
    free(captured_names);
    cg_clear_generic_type_context(cg);
    cg->generic_function_descriptor_c_name =
        saved_function_descriptor_c_name;
    if (param_types) {
        for (size_t i = 0; i < sig->param_count; ++i) cgtype_free(param_types[i]);
    }
    cg_free_cstr_array(param_cnames, sig->param_count);
    cg_free_cstr_array(param_fnames, sig->param_count);
    free(param_types);
    cgtype_free(return_type);
    cg_free_const_cstr_array(desc_names, tp_count);
    free((void *)constraint_specs);
    cg_free_cstr_array(type_param_names, tp_count);
    free(shared_name);
    cg->tmp_counter = saved_tmp_counter;
    cg->local_counter = saved_local_counter;
    return ok;
}

static bool cg_emit_generic_type_method_wrapper_into(
    CG *cg,
    const UserType *t,
    const UserMethod *m,
    const char *func_desc_expr,
    const char *shared_name_override,
    const FengDecl *reification_owner_decl,
    Buf *definition_body) {
    const FengDecl *decl = t->generic_origin_decl != NULL ? t->generic_origin_decl : t->decl;
    bool is_static_method = m != NULL && m->member != NULL && m->member->is_static;
    if (!decl || decl->kind != FENG_DECL_TYPE || definition_body == NULL) {
        return cg_fail(cg, m->member->token,
            "CE0370", "codegen: internal: generic instance method missing origin type");
    }
    const FengCallableSignature *sig = &m->member->as.callable;
    char *owned_func_desc_expr = NULL;
    char *shared_name = shared_name_override
        ? strdup(shared_name_override)
        : cg_generic_type_method_shared_cname(cg, decl, m->member);
    if (!shared_name) return cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");

    /* @value type: wrapper 的 _type_desc 参数和传给共享体的描述符
     * 使用 FengAggregateDescriptor（值类型没有 FengTypeDescriptor）。 */
    bool is_value_type = cg_user_type_is_value_semantics(t);
    const char *type_desc_c_type = is_value_type
        ? "FengAggregateDescriptor" : "FengTypeDescriptor";
    const char *desc_name = is_value_type
        ? t->c_aggregate_desc_name : t->c_desc_name;

    size_t tp_count = decl->as.type_decl.type_param_count;
    size_t method_tp_count = sig->type_param_count;
    size_t combined_tp_count = tp_count + method_tp_count;
    bool receives_func_desc =
        m->member->kind == FENG_TYPE_MEMBER_METHOD &&
        func_desc_expr == NULL &&
        (method_tp_count > 0U ||
         t->generic_context_type_param_count > 0U);
    char **type_param_names = NULL;
    char **method_type_param_names = NULL;
    char **combined_type_param_names = NULL;
    const char **wrapper_context_desc_names = NULL;
    const UserSpec **wrapper_context_constraint_specs = NULL;
    const UserSpec **constraint_specs = NULL;
    CGType **origin_param_types = NULL;
    char **origin_param_bridge_names = NULL;
    char **desc_exprs = NULL;
    const char **method_desc_names = NULL;
    int saved_tmp_counter = cg->tmp_counter;
    int saved_local_counter = cg->local_counter;
    bool ok = false;

    /* A fully closed owner and a non-generic method have one closed callable
     * instance. Bind its descriptor inside the thin wrapper, so ordinary
     * callers keep the existing wrapper ABI. Method-generic wrappers remain
     * call-site-parametric and therefore receive the callable descriptor. */
    if (m->member->kind == FENG_TYPE_MEMBER_METHOD &&
        func_desc_expr == NULL &&
        method_tp_count == 0U &&
        t->generic_context_type_param_count == 0U) {
        const FengDecl *dependency_owner = reification_owner_decl != NULL
            ? reification_owner_decl
            : decl;
        const FengReifiableDepSet *method_dep_set =
            feng_semantic_lookup_member_reifiable_dep_set(
                cg->analysis, dependency_owner, m->member);

        if (!cg_emit_closed_callable_fdesc(
                cg,
                method_dep_set,
                decl->as.type_decl.type_params,
                tp_count,
                t->generic_type_args,
                cg_find_decl_owner_program(cg, dependency_owner),
                m->member->token,
                shared_name,
                m->feng_name,
                NULL,
                &owned_func_desc_expr)) {
            goto cleanup;
        }
        func_desc_expr = owned_func_desc_expr;
    }

    if (!cg_generic_type_param_names(cg, decl, &type_param_names)) goto cleanup;
    if (!cg_build_generic_param_constraints(cg, decl->as.type_decl.type_params,
                                            tp_count, m->member->token,
                                            &constraint_specs)) goto cleanup;
    if (method_tp_count > 0U &&
        !cg_callable_type_param_names(cg, sig, m->member->token,
                                      &method_type_param_names)) {
        goto cleanup;
    }
    if (combined_tp_count > 0U) {
        combined_type_param_names = calloc(combined_tp_count,
                                           sizeof *combined_type_param_names);
        if (combined_type_param_names == NULL) {
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        for (size_t i = 0; i < tp_count; ++i) {
            combined_type_param_names[i] = strdup(type_param_names[i]);
            if (combined_type_param_names[i] == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }
        for (size_t i = 0; i < method_tp_count; ++i) {
            combined_type_param_names[tp_count + i] = strdup(method_type_param_names[i]);
            if (combined_type_param_names[tp_count + i] == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }
    }
    if (t->generic_context_type_param_count > 0U) {
        if (!cg_user_spec_constraints_from_indices(cg,
                                                   t->generic_context_type_param_constraint_indices,
                                                   t->generic_context_type_param_count,
                                                   m->member->token,
                                                   &wrapper_context_constraint_specs)) {
            goto cleanup;
        }
        wrapper_context_desc_names = calloc(t->generic_context_type_param_count,
                                            sizeof *wrapper_context_desc_names);
        if (wrapper_context_desc_names == NULL) {
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        for (size_t i = 0U; i < t->generic_context_type_param_count; ++i) {
            Buf b;

            buf_init(&b);
            buf_append_fmt(&b, "_type_desc->reified_generic_params[%zu]", i);
            wrapper_context_desc_names[i] = b.data;
            if (wrapper_context_desc_names[i] == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }
    }
    if (method_tp_count > 0U) {
        method_desc_names = calloc(method_tp_count, sizeof *method_desc_names);
        if (method_desc_names == NULL) {
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        for (size_t i = 0; i < method_tp_count; ++i) {
            Buf b;
            buf_init(&b);
            buf_append_fmt(&b, "_%s", method_type_param_names[i]);
            method_desc_names[i] = b.data;
            if (method_desc_names[i] == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }
    }

    origin_param_types = sig->param_count ? calloc(sig->param_count, sizeof *origin_param_types) : NULL;
    origin_param_bridge_names = sig->param_count
                                    ? calloc(sig->param_count,
                                             sizeof *origin_param_bridge_names)
                                    : NULL;
    desc_exprs = tp_count ? calloc(tp_count, sizeof *desc_exprs) : NULL;
    if ((sig->param_count && (!origin_param_types || !origin_param_bridge_names)) ||
        (tp_count && !desc_exprs)) {
        cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }

    cg_activate_generic_type_context(cg, combined_tp_count,
                                     combined_type_param_names,
                                     NULL,
                                     NULL);
    for (size_t i = 0; i < sig->param_count; ++i) {
        if (!cg_resolve_type(cg, sig->params[i].type, &sig->params[i].token,
                             &origin_param_types[i])) {
            goto cleanup;
        }
    }
    cg_clear_generic_type_context(cg);

    for (size_t i = 0; i < tp_count; ++i) {
        CGType *arg_type = NULL;
        if (t->generic_context_type_param_count > 0U) {
            cg_activate_generic_type_context(cg,
                                             t->generic_context_type_param_count,
                                             t->generic_context_type_param_names,
                                             wrapper_context_constraint_specs,
                                             wrapper_context_desc_names);
        }
        if (i >= t->generic_type_arg_count ||
            !cg_resolve_type(cg, t->generic_type_args[i], &m->member->token, &arg_type)) {
            if (t->generic_context_type_param_count > 0U) {
                cg_clear_generic_type_context(cg);
            }
            cgtype_free(arg_type);
            goto cleanup;
        }
        if (!cg_generic_descriptor_expr(cg, arg_type, constraint_specs[i],
                                        &m->member->token, &desc_exprs[i])) {
            if (t->generic_context_type_param_count > 0U) {
                cg_clear_generic_type_context(cg);
            }
            cgtype_free(arg_type);
            goto cleanup;
        }
        if (t->generic_context_type_param_count > 0U) {
            cg_clear_generic_type_context(cg);
        }
        cgtype_free(arg_type);
    }

    if (cg_program_origin(cg, t->owner_program) ==
        FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
        bool has_out_param = m->return_type->kind != CG_TYPE_VOID;
        buf_append_fmt(&cg->fn_protos, "void %s(", shared_name);
        bool proto_has_param = false;
        if (!is_static_method) {
            buf_append_fmt(&cg->fn_protos,
                "void *_self, const %s *_type_desc", type_desc_c_type);
            proto_has_param = true;
        } else {
            buf_append_fmt(&cg->fn_protos, "const %s *_type_desc", type_desc_c_type);
            proto_has_param = true;
        }
        if (func_desc_expr != NULL || receives_func_desc) {
            if (proto_has_param) buf_append_cstr(&cg->fn_protos, ", ");
            buf_append_cstr(&cg->fn_protos,
                            "const FengFunctionDescriptor *_desc");
            proto_has_param = true;
        }
        /* only method-level generic params in signature */
        for (size_t i = 0; i < method_tp_count; ++i) {
            if (proto_has_param) buf_append_cstr(&cg->fn_protos, ", ");
            buf_append_fmt(&cg->fn_protos,
                           "const FengGenericParamDescriptor *%s",
                           method_desc_names[i]);
            proto_has_param = true;
        }
        for (size_t i = 0; i < sig->param_count; ++i) {
            if (proto_has_param) buf_append_cstr(&cg->fn_protos, ", ");
            if (cg_shared_generic_param_uses_address(origin_param_types[i])) {
                buf_append_fmt(&cg->fn_protos, "const void *_p%zu", i);
            } else {
                cg_emit_c_type(&cg->fn_protos, origin_param_types[i]);
                buf_append_fmt(&cg->fn_protos, " _p%zu", i);
            }
            proto_has_param = true;
        }
        if (has_out_param) {
            if (proto_has_param) buf_append_cstr(&cg->fn_protos, ", ");
            buf_append_cstr(&cg->fn_protos, "void *_out");
            proto_has_param = true;
        }
        if (!proto_has_param) {
            buf_append_cstr(&cg->fn_protos, "void");
        }
        buf_append_cstr(&cg->fn_protos, ");\n");
    }

    Buf *body = definition_body;

    if (method_tp_count == 0U) {
        cg_emit_user_method_proto_ex(&cg->fn_protos, t, m, true,
                                     receives_func_desc);
        buf_append_cstr(body, "static ");
        cg_emit_c_type(body, m->return_type);
        buf_append_fmt(body, " %s(", m->c_name);
        bool body_has_param = false;
        if (!is_static_method) {
            buf_append_fmt(body, "struct %s *self", t->c_struct_name);
            body_has_param = true;
        }
        if (t->generic_context_type_param_count > 0U) {
            if (body_has_param) buf_append_cstr(body, ", ");
            buf_append_fmt(body, "const %s *_type_desc", type_desc_c_type);
            body_has_param = true;
        }
        if (receives_func_desc) {
            if (body_has_param) buf_append_cstr(body, ", ");
            buf_append_cstr(body,
                            "const FengFunctionDescriptor *_func_desc");
            body_has_param = true;
        }
        for (size_t i = 0; i < m->param_count; ++i) {
            if (body_has_param) buf_append_cstr(body, ", ");
            if (cg_shared_generic_param_uses_address(m->param_types[i])) {
                buf_append_fmt(body, "const void *%s",
                               m->param_names[i] ? m->param_names[i] : "_p");
            } else {
                cg_emit_c_type(body, m->param_types[i]);
                buf_append_fmt(body, " %s", m->param_names[i] ? m->param_names[i] : "_p");
            }
            body_has_param = true;
        }
        if (!body_has_param) {
            buf_append_cstr(body, "void");
        }
        buf_append_cstr(body, ") {\n");
    } else {
        Buf *proto = &cg->fn_protos;
        buf_append_fmt(proto, "static void %s(", m->c_name);
        bool proto_has_param = false;
        if (!is_static_method) {
            buf_append_fmt(proto, "struct %s *self", t->c_struct_name);
            proto_has_param = true;
        }
        if (t->generic_context_type_param_count > 0U) {
            if (proto_has_param) buf_append_cstr(proto, ", ");
            buf_append_fmt(proto, "const %s *_type_desc", type_desc_c_type);
            proto_has_param = true;
        }
        if (receives_func_desc) {
            if (proto_has_param) buf_append_cstr(proto, ", ");
            buf_append_cstr(proto,
                            "const FengFunctionDescriptor *_func_desc");
            proto_has_param = true;
        }
        for (size_t i = 0; i < method_tp_count; ++i) {
            if (proto_has_param) buf_append_cstr(proto, ", ");
            buf_append_fmt(proto, "const FengGenericParamDescriptor *%s",
                           method_desc_names[i]);
            proto_has_param = true;
        }
        for (size_t i = 0; i < m->param_count; ++i) {
            if (proto_has_param) buf_append_cstr(proto, ", ");
            if (cg_shared_generic_param_uses_address(m->param_types[i])) {
                buf_append_fmt(proto, "const void *%s",
                               m->param_names[i] ? m->param_names[i] : "_p");
            } else {
                cg_emit_c_type(proto, m->param_types[i]);
                buf_append_fmt(proto, " %s",
                               m->param_names[i] ? m->param_names[i] : "_p");
            }
            proto_has_param = true;
        }
        if (m->return_type->kind != CG_TYPE_VOID) {
            if (proto_has_param) buf_append_cstr(proto, ", ");
            buf_append_cstr(proto, "void *_out");
            proto_has_param = true;
        }
        if (!proto_has_param) {
            buf_append_cstr(proto, "void");
        }
        buf_append_cstr(proto, ");\n");

        buf_append_fmt(body, "static void %s(", m->c_name);
        bool wrapper_body_has_param = false;
        if (!is_static_method) {
            buf_append_fmt(body, "struct %s *self", t->c_struct_name);
            wrapper_body_has_param = true;
        }
        if (t->generic_context_type_param_count > 0U) {
            if (wrapper_body_has_param) buf_append_cstr(body, ", ");
            buf_append_fmt(body, "const %s *_type_desc", type_desc_c_type);
            wrapper_body_has_param = true;
        }
        if (receives_func_desc) {
            if (wrapper_body_has_param) buf_append_cstr(body, ", ");
            buf_append_cstr(body,
                            "const FengFunctionDescriptor *_func_desc");
            wrapper_body_has_param = true;
        }
        for (size_t i = 0; i < method_tp_count; ++i) {
            if (wrapper_body_has_param) buf_append_cstr(body, ", ");
            buf_append_fmt(body, "const FengGenericParamDescriptor *%s",
                           method_desc_names[i]);
            wrapper_body_has_param = true;
        }
        for (size_t i = 0; i < m->param_count; ++i) {
            if (wrapper_body_has_param) buf_append_cstr(body, ", ");
            if (cg_shared_generic_param_uses_address(m->param_types[i])) {
                buf_append_fmt(body, "const void *%s",
                               m->param_names[i] ? m->param_names[i] : "_p");
            } else {
                cg_emit_c_type(body, m->param_types[i]);
                buf_append_fmt(body, " %s",
                               m->param_names[i] ? m->param_names[i] : "_p");
            }
            wrapper_body_has_param = true;
        }
        if (m->return_type->kind != CG_TYPE_VOID) {
            if (wrapper_body_has_param) buf_append_cstr(body, ", ");
            buf_append_cstr(body, "void *_out");
            wrapper_body_has_param = true;
        }
        if (!wrapper_body_has_param) {
            buf_append_cstr(body, "void");
        }
        buf_append_cstr(body, ") {\n");
    }
    if (!is_static_method) {
        buf_append_cstr(body, "    (void)self;\n");
    }
    if (t->generic_context_type_param_count > 0U) {
        buf_append_cstr(body, "    (void)_type_desc;\n");
    }
    for (size_t i = 0; i < method_tp_count; ++i) {
        buf_append_fmt(body, "    (void)%s;\n", method_desc_names[i]);
    }
    if (receives_func_desc) {
        buf_append_cstr(body, "    (void)_func_desc;\n");
    }
    for (size_t i = 0; i < m->param_count; ++i) {
        buf_append_fmt(body, "    (void)%s;\n", m->param_names[i] ? m->param_names[i] : "_p");
    }
    if (method_tp_count > 0U && m->return_type->kind != CG_TYPE_VOID) {
        buf_append_cstr(body, "    (void)_out;\n");
    }

    /* An open generic object-spec instance and its concrete instantiation
     * have different C struct tags but the same fixed {subject,witness}
     * value layout. Bridge only that representation before calling the
     * shared generic body; the memcpy creates an unowned alias and therefore
     * must not introduce ARC operations. */
    for (size_t i = 0U; i < m->param_count; ++i) {
        if (origin_param_types[i] == NULL || m->param_types[i] == NULL ||
            origin_param_types[i]->kind != CG_TYPE_SPEC ||
            m->param_types[i]->kind != CG_TYPE_SPEC ||
            origin_param_types[i]->user_spec == m->param_types[i]->user_spec) {
            continue;
        }
        origin_param_bridge_names[i] = cg_fresh_temp(cg, "_spec_param");
        if (origin_param_bridge_names[i] == NULL) {
            goto cleanup;
        }
        buf_append_cstr(body, "    ");
        cg_emit_c_type(body, origin_param_types[i]);
        buf_append_fmt(body,
                       " %s;\n"
                       "    memcpy(&%s, &%s, sizeof %s);\n",
                       origin_param_bridge_names[i],
                       origin_param_bridge_names[i],
                       m->param_names[i] != NULL ? m->param_names[i] : "_p",
                       origin_param_bridge_names[i]);
    }

    char *ret_tmp = NULL;
    if (method_tp_count == 0U && m->return_type->kind != CG_TYPE_VOID) {
        ret_tmp = cg_fresh_temp(cg, "_ret");
        if (!ret_tmp) goto cleanup;
        char *ret_cty = cg_ctype_dup(m->return_type);
        if (!ret_cty) { free(ret_tmp); ret_tmp = NULL; goto cleanup; }
        buf_append_fmt(body, "    %s %s;\n", ret_cty, ret_tmp);
        free(ret_cty);
    }

    buf_append_fmt(body, "    %s(", shared_name);
    bool call_has_arg = false;
    if (!is_static_method) {
        if (t->generic_context_type_param_count > 0U) {
            buf_append_cstr(body, "(void *)self, _type_desc");
        } else {
            buf_append_fmt(body, "(void *)self, &%s", desc_name);
        }
        call_has_arg = true;
    } else if (t->generic_context_type_param_count > 0U) {
        buf_append_cstr(body, "_type_desc");
        call_has_arg = true;
    } else {
        buf_append_fmt(body, "&%s", desc_name);
        call_has_arg = true;
    }
    if (func_desc_expr != NULL || receives_func_desc) {
        if (call_has_arg) buf_append_cstr(body, ", ");
        buf_append_cstr(body,
                        func_desc_expr != NULL
                            ? func_desc_expr
                            : "_func_desc");
        call_has_arg = true;
    }
    /* only method-level desc_exprs; type-level params are from descriptor */
    for (size_t i = 0; i < method_tp_count; ++i) {
        if (call_has_arg) buf_append_cstr(body, ", ");
        buf_append_cstr(body, method_desc_names[i]);
        call_has_arg = true;
    }
    for (size_t i = 0; i < m->param_count; ++i) {
        const char *param_name = m->param_names[i] ? m->param_names[i] : "_p";
        if (call_has_arg) buf_append_cstr(body, ", ");
        if (origin_param_types[i] != NULL &&
            origin_param_types[i]->kind == CG_TYPE_GENERIC_PARAM) {
            if (origin_param_types[i]->generic_param_index < tp_count) {
                if (cg_shared_generic_param_uses_address(m->param_types[i])) {
                    buf_append_fmt(body, "%s", param_name);
                } else {
                    buf_append_fmt(body, "&%s", param_name);
                }
            } else {
                buf_append_fmt(body, "%s", param_name);
            }
        } else if (cg_shared_generic_param_uses_address(origin_param_types[i])) {
            if (cg_shared_generic_param_uses_address(m->param_types[i])) {
                buf_append_fmt(body, "%s", param_name);
            } else {
                buf_append_fmt(body, "&%s", param_name);
            }
        } else {
            const char *selected_name =
                origin_param_bridge_names[i] != NULL
                    ? origin_param_bridge_names[i]
                    : param_name;
            char *bridged_name =
                cg_shared_nominal_managed_pointer_expr_dup(
                origin_param_types[i], m->param_types[i], selected_name);

            if (bridged_name == NULL) {
                goto cleanup;
            }
            buf_append_cstr(body, bridged_name);
            free(bridged_name);
        }
        call_has_arg = true;
    }
    if (method_tp_count > 0U && m->return_type->kind != CG_TYPE_VOID) {
        if (call_has_arg) buf_append_cstr(body, ", ");
        buf_append_cstr(body, "_out");
    } else if (ret_tmp) {
        if (call_has_arg) buf_append_cstr(body, ", ");
        buf_append_fmt(body, "&%s", ret_tmp);
    }
    buf_append_cstr(body, ");\n");
    if (method_tp_count > 0U) {
        buf_append_cstr(body, "    return;\n");
    } else if (ret_tmp) {
        buf_append_fmt(body, "    return %s;\n", ret_tmp);
    } else {
        buf_append_cstr(body, "    return;\n");
    }
    buf_append_cstr(body, "}\n\n");
    free(ret_tmp);
    ok = true;

cleanup:
    if (!ok && !cg->failed) {
        cg_fail(cg, m->member->token,
            "CE0371", "codegen: internal: failed to emit generic method wrapper '%s.%s'",
            t->feng_name,
            m->feng_name);
    }
    cg_clear_generic_type_context(cg);
    if (origin_param_types) {
        for (size_t i = 0; i < sig->param_count; ++i) cgtype_free(origin_param_types[i]);
    }
    free(origin_param_types);
    cg_free_cstr_array(origin_param_bridge_names, sig->param_count);
    free((void *)constraint_specs);
    if (desc_exprs) {
        for (size_t i = 0; i < tp_count; ++i) free(desc_exprs[i]);
    }
    free(desc_exprs);
    free((void *)wrapper_context_constraint_specs);
    cg_free_const_cstr_array(wrapper_context_desc_names,
                             t->generic_context_type_param_count);
    cg_free_const_cstr_array(method_desc_names, method_tp_count);
    cg_free_cstr_array(method_type_param_names, method_tp_count);
    cg_free_cstr_array(combined_type_param_names, combined_tp_count);
    cg_free_cstr_array(type_param_names, tp_count);
    free(owned_func_desc_expr);
    free(shared_name);
    cg->tmp_counter = saved_tmp_counter;
    cg->local_counter = saved_local_counter;
    return ok;
}

/* Emit the ordinary concrete thin wrapper into the main function-definition
 * section. Callers that discover a closed callable while another function is
 * already being generated use the explicit-output variant above so a wrapper
 * can never be spliced into the current C function body. */
static bool cg_emit_generic_type_method_wrapper(CG *cg, const UserType *t,
                                                const UserMethod *m,
                                                const char *func_desc_expr,
                                                const char *shared_name_override,
                                                const FengDecl *reification_owner_decl) {
    return cg_emit_generic_type_method_wrapper_into(cg,
                                                    t,
                                                    m,
                                                    func_desc_expr,
                                                    shared_name_override,
                                                    reification_owner_decl,
                                                    &cg->fn_defs);
}

/* Bind the implicit receiver shared by concrete instance methods,
 * constructors, and finalizers. Capture requirements are computed once for
 * the enclosing callable before this helper runs; a captured receiver uses
 * the same capture-cell lowering as parameters and local bindings, while an
 * uncaptured receiver remains a direct scope alias. */
static bool cg_bind_concrete_callable_self(CG *cg,
                                           Scope *scope,
                                           const UserType *owner,
                                           FengToken blame,
                                           const char *source_expr) {
    FengSlice self_name = {"self", 4U};
    CGType *self_type = cgtype_new(CG_TYPE_OBJECT);

    if (self_type == NULL) {
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    self_type->user = owner;

    if (cg->current_callable_captures_self) {
        bool ok = cg_scope_bind_capture_cell(
            cg,
            scope,
            self_name,
            self_type,
            blame,
            source_expr,
            true,
            false,
            true,
            FENG_CODEGEN_MAPING_VARIABLE_SELF);
        if (ok) {
            ok = scope_mark_last_binding_mutability(scope,
                                                    FENG_MUTABILITY_LET);
        }
        cgtype_free(self_type);
        return ok;
    }

    if (!scope_add(scope, "self", source_expr, self_type, true) ||
        !scope_mark_last_binding_mutability(scope, FENG_MUTABILITY_LET)) {
        cgtype_free(self_type);
        return cg_fail(cg, blame, "IE0001", "codegen: out of memory");
    }
    return cg_debug_add_variable_record_cstr_cgtype(
        cg,
        "self",
        source_expr,
        NULL,
        self_type,
        FENG_CODEGEN_MAPING_VARIABLE_SELF,
        blame);
}

/* Emit a method body. Mirrors cg_emit_function but with a leading `self`
 * parameter. Managed object methods receive `struct T *`; tuple value methods
 * receive `struct T` by value. */
static bool cg_emit_user_method(CG *cg,
                                const UserType *t,
                                const UserMethod *m,
                                bool needs_static) {
    char **captured_names = NULL;
    size_t captured_name_count = 0U;
    const char **context_desc_names = NULL;
    char **saved_captured_names = cg->captured_binding_names;
    size_t saved_captured_name_count = cg->captured_binding_name_count;
    bool saved_captures_self = cg->current_callable_captures_self;
    bool saved_in_generic_fn = cg->in_generic_fn;
    bool saved_generic_return_uses_out = cg->generic_return_uses_out;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    Scope *fn_scope = NULL;
    bool ok = false;
    bool is_static_method = m != NULL && m->member != NULL && m->member->is_static;
    bool has_param = false;

    if (t->generic_context_type_param_count > 0U) {
        context_desc_names = calloc(t->generic_context_type_param_count,
                                    sizeof *context_desc_names);
        if (context_desc_names == NULL) {
            return cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
        }
        for (size_t i = 0U; i < t->generic_context_type_param_count; ++i) {
            Buf b;

            buf_init(&b);
            buf_append_fmt(&b, "_%s", t->generic_context_type_param_names[i]);
            context_desc_names[i] = b.data;
            if (context_desc_names[i] == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }
    }

    cg_emit_user_method_proto(&cg->fn_protos, t, m, needs_static);

    Buf *body = &cg->fn_defs;
    cg->cur_body = body;
    cg->cur_return_type = m->return_type;
    cg->cur_fn_is_main = false;
    if (needs_static) {
        buf_append_cstr(body, "static ");
    }
    cg_emit_c_type(body, m->return_type);
    buf_append_fmt(body, " %s(", m->c_name);
    if (!is_static_method) {
        /* §9.15: all types pass struct X *self (pointer); tuple self
         * pointerified to match @value and heap objects. */
        buf_append_fmt(body, "struct %s *self", t->c_struct_name);
        has_param = true;
    }
    for (size_t i = 0U; i < t->generic_context_type_param_count; ++i) {
        if (has_param) {
            buf_append_cstr(body, ", ");
        }
        buf_append_fmt(body,
                       "const FengGenericParamDescriptor *%s",
                       context_desc_names[i]);
        has_param = true;
    }

    fn_scope = scope_push(NULL);
    if (!fn_scope) {
        cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->cur_scope = fn_scope;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    cg->loop_depth = 0;
    cg->try_depth = 0;

    for (size_t i = 0; i < m->param_count; i++) {
        if (has_param) {
            buf_append_cstr(body, ", ");
        }
        cg_emit_c_type(body, m->param_types[i]);
        const char *pn = m->param_names[i] ? m->param_names[i] : "_p";
        buf_append_fmt(body, " %s", pn);
        has_param = true;
    }
    if (!has_param) {
        buf_append_cstr(body, "void");
    }
    buf_append_cstr(body, ") {\n");
    if (!cg_emit_function_eh_prologue(cg, m->member->token)) {
        goto cleanup;
    }
    {
        Buf frame_name;
        buf_init(&frame_name);
        buf_append_fmt(&frame_name, "%s.%s", t->feng_name, m->feng_name);
        if (frame_name.data == NULL ||
            !cg_debug_set_current_frame(cg,
                                        m->c_name,
                                        frame_name.data,
                                        FENG_CODEGEN_MAPING_FRAME_VISIBLE,
                                        m->member->token) ||
            !cg_debug_add_current_frame_module_binding_records(cg, m->member->token)) {
            buf_free(&frame_name);
            goto cleanup;
        }
        buf_free(&frame_name);
    }

    if (t->generic_context_type_param_count > 0U) {
        cg->in_generic_fn = true;
        cg->generic_return_uses_out = false;
        cg->generic_fn_type_param_count = t->generic_context_type_param_count;
        cg->generic_fn_type_param_names = t->generic_context_type_param_names;
        cg->generic_fn_type_param_constraints = NULL;
        cg->generic_fn_type_param_descs = context_desc_names;
        for (size_t i = 0U; i < t->generic_context_type_param_count; ++i) {
            buf_append_fmt(body, "    (void)%s;\n", context_desc_names[i]);
        }
    }

    if (!cg_compute_capture_requirements_in_block(m->member->as.callable.body,
                                                  &captured_names,
                                                  &captured_name_count,
                                                  &cg->current_callable_captures_self)) {
        cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->captured_binding_names = captured_names;
    cg->captured_binding_name_count = captured_name_count;

    if (!is_static_method) {
        buf_append_cstr(body, "    (void)self;\n");
    }
    for (size_t i = 0; i < m->param_count; i++) {
        const char *pn = m->param_names[i] ? m->param_names[i] : "_p";
        buf_append_fmt(body, "    (void)%s;\n", pn);
    }

    if (!is_static_method) {
        /* §9.15: value-semantics (tuple/@value) C parameter is struct X *self
         * (pointer). Bind or capture from (*self) so the stored value and
         * subsequent member access preserve value semantics. */
        const char *self_source =
            cg_user_type_is_value_semantics(t) ? "(*self)" : "self";
        if (!cg_bind_concrete_callable_self(cg,
                                            fn_scope,
                                            t,
                                            m->member->token,
                                            self_source)) {
            goto cleanup;
        }
    }

    for (size_t i = 0; i < m->param_count; i++) {
        const char *pn = m->param_names[i] ? m->param_names[i] : "_p";
        if (cg_current_callable_captures_name(cg, pn, strlen(pn))) {
            if (!cg_scope_bind_capture_cell(cg,
                                            fn_scope,
                                            m->member->as.callable.params[i].name,
                                            m->param_types[i],
                                            m->member->as.callable.params[i].token,
                                            pn,
                                            true,
                                            false,
                                            true,
                                            FENG_CODEGEN_MAPING_VARIABLE_PARAM) ||
                !scope_mark_last_binding_mutability(
                    fn_scope,
                    m->member->as.callable.params[i].mutability)) {
                goto cleanup;
            }
            continue;
        }
        CGType *pt = cgtype_clone(m->param_types[i]);
        if (!scope_add(fn_scope, pn, pn, pt, true) ||
            !scope_mark_last_binding_mutability(
                fn_scope,
                m->member->as.callable.params[i].mutability)) {
            cgtype_free(pt);
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (!cg_debug_add_variable_record_slice_type_ref(
            cg,
            pn,
            m->member->as.callable.params[i].name,
            NULL,
            m->member->as.callable.params[i].type,
            FENG_CODEGEN_MAPING_VARIABLE_PARAM,
            m->member->as.callable.params[i].token)) {
            goto cleanup;
        }
    }

    if (m->member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR &&
        !cg_emit_user_type_member_initializers(
            cg, t, "self", m->member->token)) {
        goto cleanup;
    }
    if (!cg_emit_block(cg, m->member->as.callable.body)) goto cleanup;
    cg_release_scope(cg, fn_scope);
    cg_emit_function_fallthrough_cleanup(cg);
    if (m->return_type->kind == CG_TYPE_VOID) {
        buf_append_cstr(body, "    return;\n");
    } else {
        buf_append_cstr(body,
            "    feng_panic(\"method reached end without return\");\n");
    }
    buf_append_cstr(body, "}\n\n");
    ok = true;

cleanup:
    cg->captured_binding_names = saved_captured_names;
    cg->captured_binding_name_count = saved_captured_name_count;
    cg->current_callable_captures_self = saved_captures_self;
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_return_uses_out = saved_generic_return_uses_out;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg_free_const_cstr_array(context_desc_names,
                             t->generic_context_type_param_count);
    for (size_t i = 0; i < captured_name_count; ++i) free(captured_names[i]);
    free(captured_names);
    if (fn_scope != NULL) {
        cg->cur_scope = NULL;
        scope_pop_free(fn_scope);
    }
    cg->cur_body = NULL;
    cg->cur_return_type = NULL;
    cg->current_frame_backend_symbol = NULL;
    cg->cur_function_has_frame_marker = false;
    return ok;
}

static bool cg_emit_builtin_fit_method(CG *cg,
                                       const BuiltinFit *bf,
                                       const UserMethod *m,
                                       bool needs_static) {
    char **captured_names = NULL;
    size_t captured_name_count = 0U;
    char **fit_target_type_param_names = NULL;
    const char **fit_target_desc_names = NULL;
    char **method_type_param_names = NULL;
    const char **method_desc_names = NULL;
    char **combined_type_param_names = NULL;
    const char **combined_desc_names = NULL;
    const UserSpec **combined_constraints_alloc = NULL;
    char **saved_captured_names = cg->captured_binding_names;
    size_t saved_captured_name_count = cg->captured_binding_name_count;
    bool saved_captures_self = cg->current_callable_captures_self;
    size_t saved_ambient_tp_count = cg->ambient_type_param_count;
    /* 保存 rtd/rad 状态，以便在 BuiltinFit 方法体内临时设置。 */
    char **saved_rtd_descs = cg->generic_type_method_rtd_descs;
    size_t saved_rtd_count = cg->generic_type_method_rtd_count;
    bool saved_rtd_via_desc = cg->generic_type_method_rtd_via_desc;
    char **saved_rad_descs = cg->generic_type_method_rad_descs;
    size_t saved_rad_count = cg->generic_type_method_rad_count;
    bool saved_rad_via_desc = cg->generic_type_method_rad_via_desc;
    char **saved_ambient_tp_names = cg->ambient_type_param_names;
    bool saved_in_generic_fn = cg->in_generic_fn;
    bool saved_generic_return_uses_out = cg->generic_return_uses_out;
    size_t saved_tp_count = cg->generic_fn_type_param_count;
    char **saved_tp_names = cg->generic_fn_type_param_names;
    const UserSpec **saved_tp_constraints = cg->generic_fn_type_param_constraints;
    const char **saved_tp_descs = cg->generic_fn_type_param_descs;
    const char *saved_function_descriptor_c_name =
        cg->generic_function_descriptor_c_name;
    Scope *fn_scope = NULL;
    bool ok = false;
    FengSlice self_name = {"self", 4U};
    bool is_static_method = m != NULL && m->member != NULL && m->member->is_static;
    bool return_uses_out = cg_builtin_fit_return_uses_out(bf, m);
    bool has_param = false;

    if (bf == NULL || bf->target_type == NULL || m == NULL) {
        return false;
    }
    cg->generic_function_descriptor_c_name = "_desc";

    cg_emit_builtin_fit_method_proto(&cg->fn_protos, bf, m, needs_static);

    Buf *body = &cg->fn_defs;
    cg->cur_body = body;
    cg->cur_return_type = m->return_type;
    cg->cur_fn_is_main = false;
    if (needs_static) {
        buf_append_cstr(body, "static ");
    }
    if (return_uses_out) {
        buf_append_cstr(body, "void");
    } else {
        cg_emit_c_type(body, m->return_type);
    }
    buf_append_fmt(body, " %s(", m->c_name);
    if (!is_static_method) {
        cg_emit_c_type(body, bf->target_type);
        buf_append_cstr(body, " self");
        has_param = true;
    }
    /* §6.7: _desc parameter for reified deps */
    if (has_param) buf_append_cstr(body, ", ");
    buf_append_cstr(body, "const FengFunctionDescriptor *_desc");
    has_param = true;
    for (size_t i = 0; i < bf->target_type_param_count; ++i) {
        if (has_param) {
            buf_append_cstr(body, ", ");
        }
        buf_append_fmt(body,
                       "const FengGenericParamDescriptor *_%.*s",
                       (int)bf->target_type_params[i].name.length,
                       bf->target_type_params[i].name.data);
        has_param = true;
    }
    /* method-level generic type parameter descriptors */
    {
        const FengCallableSignature *sig = &m->member->as.callable;
        for (size_t i = 0; i < sig->type_param_count; ++i) {
            if (has_param) {
                buf_append_cstr(body, ", ");
            }
            buf_append_fmt(body,
                           "const FengGenericParamDescriptor *_%.*s",
                           (int)sig->type_params[i].name.length,
                           sig->type_params[i].name.data);
            has_param = true;
        }
    }

    fn_scope = scope_push(NULL);
    if (!fn_scope) {
        cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->cur_scope = fn_scope;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    cg->loop_depth = 0;
    cg->try_depth = 0;
    cg->active_exception_frame_count = 0;
    cg->active_caught_unwind_count = 0;
    cg->cur_function_has_frame_marker = false;

    for (size_t i = 0; i < m->param_count; i++) {
        if (has_param) {
            buf_append_cstr(body, ", ");
        }
        if (m->param_types[i] != NULL && m->param_types[i]->kind == CG_TYPE_GENERIC_PARAM) {
            buf_append_fmt(body, "const void *%s",
                           m->param_names[i] ? m->param_names[i] : "_p");
        } else {
            cg_emit_c_type(body, m->param_types[i]);
            buf_append_fmt(body, " %s", m->param_names[i] ? m->param_names[i] : "_p");
        }
        has_param = true;
    }
    if (return_uses_out) {
        if (has_param) {
            buf_append_cstr(body, ", ");
        }
        buf_append_cstr(body, "void *_out");
        has_param = true;
    }
    if (!has_param) {
        buf_append_cstr(body, "void");
    }
    buf_append_cstr(body, ") {\n");
    if (!cg_emit_function_eh_prologue(cg, m->member->token)) {
        goto cleanup;
    }

    buf_append_cstr(body, "    (void)_desc;\n");
    for (size_t i = 0; i < bf->target_type_param_count; ++i) {
        buf_append_fmt(body,
                       "    (void)_%.*s;\n",
                       (int)bf->target_type_params[i].name.length,
                       bf->target_type_params[i].name.data);
    }
    /* suppress unused warnings for method-level generic type param descriptors */
    {
        const FengCallableSignature *method_sig = &m->member->as.callable;
        for (size_t i = 0; i < method_sig->type_param_count; ++i) {
            buf_append_fmt(body,
                           "    (void)_%.*s;\n",
                           (int)method_sig->type_params[i].name.length,
                           method_sig->type_params[i].name.data);
        }
    }

    if (bf->target_type_param_count > 0U) {
        if (!cg_type_param_names_from_decl(cg,
                                           bf->target_type_params,
                                           bf->target_type_param_count,
                                           m->member->token,
                                           &fit_target_type_param_names)) {
            goto cleanup;
        }
        fit_target_desc_names = calloc(bf->target_type_param_count,
                                       sizeof *fit_target_desc_names);
        if (fit_target_desc_names == NULL) {
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        for (size_t i = 0U; i < bf->target_type_param_count; ++i) {
            Buf b;

            buf_init(&b);
            buf_append_fmt(&b, "_%s", fit_target_type_param_names[i]);
            fit_target_desc_names[i] = b.data;
            if (fit_target_desc_names[i] == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
        }
    }

    /* Extract method-level generic type parameter names and descriptors. */
    {
        const FengCallableSignature *sig = &m->member->as.callable;
        if (sig->type_param_count > 0U) {
            if (!cg_callable_type_param_names(cg, sig, m->member->token,
                                              &method_type_param_names)) {
                goto cleanup;
            }
            method_desc_names = calloc(sig->type_param_count,
                                       sizeof *method_desc_names);
            if (method_desc_names == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
            for (size_t i = 0U; i < sig->type_param_count; ++i) {
                Buf b;
                buf_init(&b);
                buf_append_fmt(&b, "_%s", method_type_param_names[i]);
                method_desc_names[i] = b.data;
                if (method_desc_names[i] == NULL) {
                    cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                    goto cleanup;
                }
            }
        }
    }

    /* Merge fit-target and method-level type params into combined context. */
    {
        const FengCallableSignature *sig = &m->member->as.callable;
        size_t fit_tp_count = bf->target_type_param_count;
        size_t method_tp_count = sig->type_param_count;
        size_t total_tp_count = fit_tp_count + method_tp_count;

        if (total_tp_count > 0U) {
            combined_type_param_names = calloc(total_tp_count,
                                               sizeof *combined_type_param_names);
            combined_desc_names = calloc(total_tp_count,
                                         sizeof *combined_desc_names);
            if (combined_type_param_names == NULL || combined_desc_names == NULL) {
                cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
                goto cleanup;
            }
            for (size_t i = 0; i < fit_tp_count; ++i) {
                combined_type_param_names[i] = fit_target_type_param_names[i];
                combined_desc_names[i] = fit_target_desc_names[i];
            }
            for (size_t i = 0; i < method_tp_count; ++i) {
                combined_type_param_names[fit_tp_count + i] = method_type_param_names[i];
                combined_desc_names[fit_tp_count + i] = method_desc_names[i];
            }
            cg->ambient_type_param_count = total_tp_count;
            cg->ambient_type_param_names = combined_type_param_names;
            cg->in_generic_fn = true;
            cg->generic_fn_type_param_count = total_tp_count;
            cg->generic_fn_type_param_names = combined_type_param_names;
            {
                const CGTypeParamScope scope = {
                    .first = bf->target_type_params,
                    .first_count = fit_tp_count,
                    .second = sig->type_params,
                    .second_count = method_tp_count,
                };

                if (!cg_type_param_scope_build_constraints(
                        cg,
                        &scope,
                        m->member->token,
                        &combined_constraints_alloc)) {
                    goto cleanup;
                }
                cg->generic_fn_type_param_constraints =
                    combined_constraints_alloc;
            }
            cg->generic_fn_type_param_descs = combined_desc_names;
            cg->generic_return_uses_out = return_uses_out;
        }
    }

    if (bf->target_type_param_count > 0U) {
        /* §2.6.6 前置：预计算 BuiltinFit 方法体的 reified_type_deps 映射。
         * 使用 fit decl 查找已收集的 dep_set，按 cg_reifiable_sort_key
         * 排序后记录每个 MANAGED dep 对应的擦除描述符名称。 */
        {
            const FengReifiableDepSet *rtd_dep_set =
                feng_semantic_lookup_member_reifiable_dep_set(
                    cg->analysis, bf->decl, m->member);
            if (rtd_dep_set != NULL && rtd_dep_set->dep_count > 0U) {
                FengSlice *tp_names = (FengSlice *)calloc(
                    bf->target_type_param_count, sizeof(FengSlice));
                if (tp_names != NULL) {
                    for (size_t i = 0; i < bf->target_type_param_count; ++i) {
                        tp_names[i] = bf->target_type_params[i].name;
                    }
                    typedef struct { size_t idx; char *key; } RTDSort;
                    size_t mc = 0;
                    for (size_t i = 0; i < rtd_dep_set->dep_count; ++i) {
                        if (rtd_dep_set->deps[i].kind ==
                            FENG_REIFIABLE_DEP_KIND_MANAGED) {
                            mc++;
                        }
                    }
                    if (mc > 0U) {
                        RTDSort *sorted = (RTDSort *)calloc(mc, sizeof(RTDSort));
                        if (sorted != NULL) {
                            size_t si = 0;
                            for (size_t i = 0; i < rtd_dep_set->dep_count; ++i) {
                                if (rtd_dep_set->deps[i].kind !=
                                    FENG_REIFIABLE_DEP_KIND_MANAGED) continue;
                                sorted[si].idx = i;
                                sorted[si].key = cg_reifiable_sort_key(
                                    rtd_dep_set->deps[i].type_ref,
                                    tp_names,
                                    bf->target_type_param_count, true);
                                si++;
                            }
                            for (size_t i = 1; i < mc; ++i) {
                                RTDSort tmp = sorted[i];
                                size_t j = i;
                                while (j > 0 &&
                                       strcmp(sorted[j - 1].key, tmp.key) > 0) {
                                    sorted[j] = sorted[j - 1];
                                    j--;
                                }
                                sorted[j] = tmp;
                            }
                            cg->generic_type_method_rtd_descs =
                                (char **)calloc(mc, sizeof(char *));
                            if (cg->generic_type_method_rtd_descs != NULL) {
                                cg->generic_type_method_rtd_count = mc;
                                cg->generic_type_method_rtd_via_desc = true;
                                for (size_t i = 0; i < mc; ++i) {
                                    const FengReifiableDep *dep =
                                        &rtd_dep_set->deps[sorted[i].idx];
                                    const char *descriptor_name =
                                        cg_open_generic_managed_descriptor_name(
                                            cg,
                                            dep->type_ref);

                                    if (descriptor_name != NULL) {
                                        cg->generic_type_method_rtd_descs[i] =
                                            strdup(descriptor_name);
                                    }
                                }
                            }
                            for (size_t i = 0; i < mc; ++i) free(sorted[i].key);
                            free(sorted);
                        }
                    }
                    free(tp_names);
                }
            }
        }
    }

    /* §2.6.1-§2.6.4：预计算 BuiltinFit 方法体的 reified_agg_deps 映射。 */
    {
        const FengReifiableDepSet *rad_dep_set =
            feng_semantic_lookup_member_reifiable_dep_set(
                cg->analysis, bf->decl, m->member);
        if (rad_dep_set != NULL && rad_dep_set->dep_count > 0U) {
            FengSlice *tp_names_rad = (FengSlice *)calloc(
                bf->target_type_param_count, sizeof(FengSlice));
            if (tp_names_rad != NULL) {
                for (size_t i = 0; i < bf->target_type_param_count; ++i) {
                    tp_names_rad[i] = bf->target_type_params[i].name;
                }
                typedef struct { size_t idx; char *key; } RADSort;
                size_t ac = 0;
                for (size_t i = 0; i < rad_dep_set->dep_count; ++i) {
                    if (rad_dep_set->deps[i].kind ==
                        FENG_REIFIABLE_DEP_KIND_AGGREGATE) {
                        ac++;
                    }
                }
                if (ac > 0U) {
                    RADSort *sorted = (RADSort *)calloc(ac, sizeof(RADSort));
                    if (sorted != NULL) {
                        size_t si = 0;
                        for (size_t i = 0; i < rad_dep_set->dep_count; ++i) {
                            if (rad_dep_set->deps[i].kind !=
                                FENG_REIFIABLE_DEP_KIND_AGGREGATE) continue;
                            sorted[si].idx = i;
                            sorted[si].key = cg_reifiable_sort_key(
                                rad_dep_set->deps[i].type_ref,
                                tp_names_rad,
                                bf->target_type_param_count, true);
                            si++;
                        }
                        for (size_t i = 1; i < ac; ++i) {
                            RADSort tmp = sorted[i];
                            size_t j = i;
                            while (j > 0 &&
                                   strcmp(sorted[j - 1].key, tmp.key) > 0) {
                                sorted[j] = sorted[j - 1];
                                j--;
                            }
                            sorted[j] = tmp;
                        }
                        cg->generic_type_method_rad_descs =
                            (char **)calloc(ac, sizeof(char *));
                        if (cg->generic_type_method_rad_descs != NULL) {
                            cg->generic_type_method_rad_count = ac;
                            cg->generic_type_method_rad_via_desc = true;
                            for (size_t i = 0; i < ac; ++i) {
                                const FengReifiableDep *dep =
                                    &rad_dep_set->deps[sorted[i].idx];
                                const FengDecl *dep_origin = NULL;
                                if (dep->type_ref != NULL &&
                                    dep->type_ref->kind == FENG_TYPE_REF_NAMED &&
                                    dep->type_ref->as.named.type_arg_count > 0U) {
                                    const GenericTypeDecl *gtd =
                                        cg_find_generic_type_decl(cg,
                                            dep->type_ref);
                                    if (gtd != NULL) dep_origin = gtd->decl;
                                }
                                if (dep_origin != NULL) {
                                    const UserType *erased =
                                        cg_find_open_generic_instance(
                                            cg,
                                            &(UserType){
                                                .is_generic_instance = true,
                                                .generic_origin_decl = dep_origin
                                            });
                                    if (erased != NULL) {
                                        cg->generic_type_method_rad_descs[i] =
                                            strdup(erased->c_aggregate_desc_name);
                                    }
                                }
                            }
                        }
                        for (size_t i = 0; i < ac; ++i) free(sorted[i].key);
                        free(sorted);
                    }
                }
                free(tp_names_rad);
            }
        }
    }

    if (!cg_compute_capture_requirements_in_block(m->member->as.callable.body,
                                                  &captured_names,
                                                  &captured_name_count,
                                                  &cg->current_callable_captures_self)) {
        cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->captured_binding_names = captured_names;
    cg->captured_binding_name_count = captured_name_count;

    if (!is_static_method) {
        buf_append_cstr(body, "    (void)self;\n");
    }
    for (size_t i = 0; i < m->param_count; i++) {
        const char *pn = m->param_names[i] ? m->param_names[i] : "_p";
        buf_append_fmt(body, "    (void)%s;\n", pn);
    }

    if (!is_static_method && cg->current_callable_captures_self) {
        if (!cg_scope_bind_capture_cell(cg,
                                        fn_scope,
                                        self_name,
                                        bf->target_type,
                                        m->member->token,
                                        "self",
                                        true,
                                        false,
                                        true,
                                        FENG_CODEGEN_MAPING_VARIABLE_SELF) ||
            !scope_mark_last_binding_mutability(fn_scope,
                                                FENG_MUTABILITY_LET)) {
            goto cleanup;
        }
    } else if (!is_static_method) {
        CGType *self_t = cgtype_clone(bf->target_type);
        if (!self_t) {
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (!scope_add(fn_scope, "self", "self", self_t, true) ||
            !scope_mark_last_binding_mutability(fn_scope,
                                                FENG_MUTABILITY_LET)) {
            cgtype_free(self_t);
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (!cg_debug_add_variable_record_cstr_cgtype(cg,
                                                      "self",
                                                      "self",
                                                      NULL,
                                                      self_t,
                                                      FENG_CODEGEN_MAPING_VARIABLE_SELF,
                                                      m->member->token)) {
            goto cleanup;
        }
    }

    for (size_t i = 0; i < m->param_count; i++) {
        const char *pn = m->param_names[i] ? m->param_names[i] : "_p";
        if (cg_current_callable_captures_name(cg, pn, strlen(pn))) {
            if (!cg_scope_bind_capture_cell(cg,
                                            fn_scope,
                                            m->member->as.callable.params[i].name,
                                            m->param_types[i],
                                            m->member->as.callable.params[i].token,
                                            pn,
                                            true,
                                            false,
                                            true,
                                            FENG_CODEGEN_MAPING_VARIABLE_PARAM) ||
                !scope_mark_last_binding_mutability(
                    fn_scope,
                    m->member->as.callable.params[i].mutability)) {
                goto cleanup;
            }
            continue;
        }
        CGType *pt = cgtype_clone(m->param_types[i]);
        if (!scope_add(fn_scope, pn, pn, pt, true) ||
            !scope_mark_last_binding_mutability(
                fn_scope,
                m->member->as.callable.params[i].mutability)) {
            cgtype_free(pt);
            cg_fail(cg, m->member->token, "IE0001", "codegen: out of memory");
            goto cleanup;
        }
        if (!cg_debug_add_variable_record_slice_type_ref(
            cg,
            pn,
            m->member->as.callable.params[i].name,
            NULL,
            m->member->as.callable.params[i].type,
            FENG_CODEGEN_MAPING_VARIABLE_PARAM,
            m->member->as.callable.params[i].token)) {
            goto cleanup;
        }
    }

    if (!cg_emit_block(cg, m->member->as.callable.body)) goto cleanup;
    cg_release_scope(cg, fn_scope);
    cg_emit_function_fallthrough_cleanup(cg);
    if (m->return_type->kind == CG_TYPE_VOID) {
        buf_append_cstr(body, "    return;\n");
    } else {
        buf_append_cstr(body,
            "    feng_panic(\"method reached end without return\");\n");
    }
    buf_append_cstr(body, "}\n\n");
    ok = true;

cleanup:
    cg->captured_binding_names = saved_captured_names;
    cg->captured_binding_name_count = saved_captured_name_count;
    cg->current_callable_captures_self = saved_captures_self;
    cg->ambient_type_param_count = saved_ambient_tp_count;
    cg->ambient_type_param_names = saved_ambient_tp_names;
    cg->in_generic_fn = saved_in_generic_fn;
    cg->generic_return_uses_out = saved_generic_return_uses_out;
    cg->generic_fn_type_param_count = saved_tp_count;
    cg->generic_fn_type_param_names = saved_tp_names;
    cg->generic_fn_type_param_constraints = saved_tp_constraints;
    cg->generic_fn_type_param_descs = saved_tp_descs;
    cg->generic_function_descriptor_c_name =
        saved_function_descriptor_c_name;
    /* 清理本方法体内分配的 rtd/rad 映射，恢复先前状态。 */
    for (size_t i = 0; i < cg->generic_type_method_rtd_count; i++) {
        free(cg->generic_type_method_rtd_descs[i]);
    }
    free(cg->generic_type_method_rtd_descs);
    cg->generic_type_method_rtd_descs = saved_rtd_descs;
    cg->generic_type_method_rtd_count = saved_rtd_count;
    cg->generic_type_method_rtd_via_desc = saved_rtd_via_desc;
    for (size_t i = 0; i < cg->generic_type_method_rad_count; i++) {
        free(cg->generic_type_method_rad_descs[i]);
    }
    free(cg->generic_type_method_rad_descs);
    cg->generic_type_method_rad_descs = saved_rad_descs;
    cg->generic_type_method_rad_count = saved_rad_count;
    cg->generic_type_method_rad_via_desc = saved_rad_via_desc;
    cg_free_const_cstr_array(fit_target_desc_names, bf->target_type_param_count);
    cg_free_cstr_array(fit_target_type_param_names, bf->target_type_param_count);
    {
        const FengCallableSignature *sig = &m->member->as.callable;
        cg_free_const_cstr_array(method_desc_names, sig->type_param_count);
        cg_free_cstr_array(method_type_param_names, sig->type_param_count);
    }
    /* combined arrays are shallow (pointers borrowed from fit_target/method arrays),
     * so only free the container arrays, not the pointed-to strings. */
    free(combined_type_param_names);
    free((void *)combined_desc_names);
    free((void *)combined_constraints_alloc);
    for (size_t i = 0; i < captured_name_count; ++i) free(captured_names[i]);
    free(captured_names);
    if (fn_scope != NULL) {
        cg->cur_scope = NULL;
        scope_pop_free(fn_scope);
    }
    cg->cur_body = NULL;
    cg->cur_return_type = NULL;
    cg->current_frame_backend_symbol = NULL;
    cg->cur_function_has_frame_marker = false;
    return ok;
}

/* Emit the user finalizer entry. A closed generic type uses a thin runtime-ABI
 * thunk that binds its type descriptor to the provider's shared finalizer
 * body. A non-generic type keeps the direct body with a synthetic `self`
 * binding. The entry declaration is emitted earlier with the type descriptor. */
static bool cg_emit_user_finalizer(CG *cg, const UserType *t) {
    if (!t->finalizer) return true;
    const FengTypeMember *fm = t->finalizer;
    Buf *body = &cg->fn_defs;

    if (t->is_generic_instance && t->generic_origin_decl != NULL) {
        char *shared_name = cg_generic_type_method_shared_cname(
            cg, t->generic_origin_decl, fm);

        if (shared_name == NULL) {
            return cg_fail(cg, fm->token,
                           "IE0001", "codegen: out of memory");
        }
        if (cg_program_origin(cg, t->owner_program) ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            buf_append_fmt(&cg->fn_protos,
                           "void %s(void *_self, const "
                           "FengTypeDescriptor *_type_desc);\n",
                           shared_name);
        }
        buf_append_fmt(body,
                       "static void %s(void *_self) {\n"
                       "    %s(_self, &%s);\n"
                       "}\n\n",
                       t->c_finalizer_name,
                       shared_name,
                       t->c_desc_name);
        free(shared_name);
        return true;
    }

    char **captured_names = NULL;
    size_t captured_name_count = 0U;
    char **saved_captured_names = cg->captured_binding_names;
    size_t saved_captured_name_count = cg->captured_binding_name_count;
    bool saved_captures_self = cg->current_callable_captures_self;
    Scope *fn_scope = NULL;
    CGType *void_type = NULL;
    bool ok = false;

    buf_append_fmt(body, "static void %s(void *_self) {\n",
                   t->c_finalizer_name);
    buf_append_fmt(body, "    struct %s *self = (struct %s *)_self;\n",
                   t->c_struct_name, t->c_struct_name);
    buf_append_cstr(body, "    (void)self;\n");

    cg->cur_body = body;
    void_type = cgtype_new(CG_TYPE_VOID);
    if (void_type == NULL) {
        cg_fail(cg, fm->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->cur_return_type = void_type;
    cg->cur_fn_is_main = false;
    cg->tmp_counter = 0;
    cg->local_counter = 0;
    cg->loop_depth = 0;
    cg->try_depth = 0;
    cg->active_exception_frame_count = 0;
    cg->active_caught_unwind_count = 0;
    cg->cur_function_has_frame_marker = false;

    if (!cg_emit_function_eh_prologue(cg, fm->token)) {
        goto cleanup;
    }
    {
        Buf frame_name;
        buf_init(&frame_name);
        buf_append_fmt(&frame_name, "~%s", t->feng_name);
        if (frame_name.data == NULL ||
            !cg_debug_set_current_frame(cg,
                                        t->c_finalizer_name,
                                        frame_name.data,
                                        FENG_CODEGEN_MAPING_FRAME_VISIBLE,
                                        fm->token) ||
            !cg_debug_add_current_frame_module_binding_records(cg, fm->token)) {
            buf_free(&frame_name);
            goto cleanup;
        }
        buf_free(&frame_name);
    }

    fn_scope = scope_push(NULL);
    if (fn_scope == NULL) {
        cg_fail(cg, fm->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->cur_scope = fn_scope;

    if (!cg_compute_capture_requirements_in_block(
            fm->as.callable.body,
            &captured_names,
            &captured_name_count,
            &cg->current_callable_captures_self)) {
        cg_fail(cg, fm->token, "IE0001", "codegen: out of memory");
        goto cleanup;
    }
    cg->captured_binding_names = captured_names;
    cg->captured_binding_name_count = captured_name_count;

    if (!cg_bind_concrete_callable_self(cg,
                                        fn_scope,
                                        t,
                                        fm->token,
                                        "self")) {
        goto cleanup;
    }

    if (!cg_emit_block(cg, fm->as.callable.body)) {
        goto cleanup;
    }
    cg_release_scope(cg, fn_scope);
    cg_emit_function_fallthrough_cleanup(cg);
    buf_append_cstr(body, "    return;\n}\n\n");
    ok = true;

cleanup:
    cg->captured_binding_names = saved_captured_names;
    cg->captured_binding_name_count = saved_captured_name_count;
    cg->current_callable_captures_self = saved_captures_self;
    for (size_t i = 0U; i < captured_name_count; ++i) {
        free(captured_names[i]);
    }
    free(captured_names);
    if (fn_scope != NULL) {
        cg->cur_scope = NULL;
        scope_pop_free(fn_scope);
    }
    cgtype_free(void_type);
    cg->cur_body = NULL;
    cg->cur_return_type = NULL;
    cg->cur_fn_is_main = false;
    cg->current_frame_backend_symbol = NULL;
    cg->cur_function_has_frame_marker = false;
    return ok;
}

static const FreeFn *cg_lookup_main(const CG *cg) {
    for (size_t i = 0; i < cg->free_fn_count; i++) {
        if (strcmp(cg->free_fns[i].feng_name, "main") == 0 &&
            cg_program_origin(cg, cg->free_fns[i].owner_program) !=
                FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            return &cg->free_fns[i];
        }
    }
    return NULL;
}

static char *cg_finalize(CG *cg) {
    Buf out; buf_init(&out);
    buf_append_cstr(&out,
        "/* Feng generated code — do not edit. */\n"
        "#include \"feng_generated.h\"\n"
        "#include \"feng_runtime.h\"\n"
        "\n"
        "/* Codegen-private callable descriptor extension. The runtime reads\n"
        " * only the FengTypeDescriptor prefix; generic default factories use\n"
        " * default_invoke to select the already-typed closed noop entry. */\n"
        "typedef struct FengCallableTypeDescriptor {\n"
        "    FengTypeDescriptor base;\n"
        "    void (*default_invoke)(void);\n"
        "} FengCallableTypeDescriptor;\n"
        "\n"
        "#if defined(__clang__)\n"
        "#pragma clang diagnostic ignored \"-Wbuiltin-requires-header\"\n"
        "#endif\n"
        "\n"
        "#if defined(_WIN32)\n"
        "#define FENG_EXTERN_CALLCONV_STDCALL __stdcall\n"
        "#define FENG_EXTERN_CALLCONV_FASTCALL __fastcall\n"
        "#else\n"
        "#define FENG_EXTERN_CALLCONV_STDCALL\n"
        "#define FENG_EXTERN_CALLCONV_FASTCALL\n"
        "#endif\n"
        "\n"
        "#if defined(__APPLE__)\n"
        "#define FENG_NATIVE_SYMBOL(name) __asm__(\"_\" name)\n"
        "#else\n"
        "/* Current non-Apple delivery targets use Linux ELF. Windows/COFF is\n"
        " * not supported and requires a separate native-symbol mapping. */\n"
        "#define FENG_NATIVE_SYMBOL(name) __asm__(name)\n"
        "#endif\n\n");
    if (cg->headers.length) buf_append(&out, cg->headers.data, cg->headers.length);
    buf_append_cstr(&out, "\n");
    if (cg->enum_defs.length) buf_append(&out, cg->enum_defs.data, cg->enum_defs.length);
    buf_append_cstr(&out, "\n");
    if (cg->type_defs.length) buf_append(&out, cg->type_defs.data, cg->type_defs.length);
    buf_append_cstr(&out, "\n");
    if (cg->statics.length) buf_append(&out, cg->statics.data, cg->statics.length);
    buf_append_cstr(&out, "\n");
    if (cg->fn_protos.length) buf_append(&out, cg->fn_protos.data, cg->fn_protos.length);
    buf_append_cstr(&out, "\n");
    if (cg->eh_defs.length) buf_append(&out, cg->eh_defs.data, cg->eh_defs.length);
    buf_append_cstr(&out, "\n");
    if (cg->fn_defs.length) buf_append(&out, cg->fn_defs.data, cg->fn_defs.length);
    if (cg->witness_defs.length) buf_append(&out, cg->witness_defs.data, cg->witness_defs.length);
    return out.data;
}

static void cg_dispose(CG *cg) {
    feng_codegen_maping_info_dispose(&cg->debug_info);
    free(cg->debug_line_logical_uri);
    buf_free(&cg->headers);
    buf_free(&cg->enum_defs);
    buf_free(&cg->type_defs);
    buf_free(&cg->statics);
    buf_free(&cg->fn_protos);
    buf_free(&cg->fn_defs);
    buf_free(&cg->eh_defs);
    buf_free(&cg->witness_defs);
    free(cg->module_mangle);
    free(cg->module_dot_name);
    for (size_t i = 0; i < cg->extern_count; i++) {
        free(cg->externs[i].feng_name);
        free(cg->externs[i].generated_c_name);
        free(cg->externs[i].native_symbol);
        for (size_t j = 0; j < cg->externs[i].param_count; j++)
            cgtype_free(cg->externs[i].param_types[j]);
        free(cg->externs[i].param_types);
        cgtype_free(cg->externs[i].return_type);
    }
    free(cg->externs);
    for (size_t i = 0; i < cg->free_fn_count; i++) {
        free(cg->free_fns[i].feng_name);
        free(cg->free_fns[i].c_name);
        free(cg->free_fns[i].c_abi_name);
        for (size_t j = 0; j < cg->free_fns[i].param_count; j++) {
            cgtype_free(cg->free_fns[i].param_types[j]);
            free(cg->free_fns[i].param_names[j]);
        }
        free(cg->free_fns[i].param_types);
        free(cg->free_fns[i].param_names);
        cgtype_free(cg->free_fns[i].return_type);
    }
    free(cg->free_fns);
    for (size_t i = 0; i < cg->user_type_count; i++) {
        UserType *ut = &cg->user_types[i];
        free(ut->feng_name);
        free(ut->c_struct_name);
        free(ut->c_desc_name);
        free(ut->c_release_children_name);
        free(ut->c_finalizer_name);
        free(ut->c_default_zero_name);
        free(ut->c_aggregate_slots_name);
        free(ut->c_aggregate_default_name);
        free(ut->c_aggregate_desc_name);
        free(ut->c_value_box_struct_name);
        free(ut->c_value_box_desc_name);
        free(ut->c_value_box_release_children_name);
        free(ut->c_abi_layout_name);
        free(ut->c_abi_ptr_name);
        free(ut->c_abi_base_offset_name);
        free(ut->c_abi_value_name);
        free(ut->c_abi_box_name);
        for (size_t j = 0; j < ut->generic_type_arg_count; ++j) {
            cg_type_ref_free(ut->generic_type_args[j]);
        }
        free(ut->generic_type_args);
        for (size_t j = 0; j < ut->field_count; j++) {
            free(ut->fields[j].feng_name);
            free(ut->fields[j].c_name);
            cgtype_free(ut->fields[j].type);
        }
        free(ut->fields);
        for (size_t j = 0; j < ut->static_binding_count; j++) {
            TypeStaticBinding *binding = &ut->static_bindings[j];

            free(binding->feng_name);
            free(binding->c_name);
            free(binding->c_ensure_init_name);
            free(binding->c_inited_name);
            cgtype_free(binding->type);
        }
        free(ut->static_bindings);
        for (size_t j = 0; j < ut->method_count; j++) {
            UserMethod *um = &ut->methods[j];
            free(um->feng_name);
            free(um->c_name);
            cgtype_free(um->return_type);
            for (size_t k = 0; k < um->param_count; k++) {
                cgtype_free(um->param_types[k]);
                free(um->param_names[k]);
            }
            free(um->param_types);
            free(um->param_names);
        }
        free(ut->methods);
        for (size_t j = 0; j < ut->static_method_count; j++) {
            UserMethod *um = &ut->static_methods[j];
            free(um->feng_name);
            free(um->c_name);
            cgtype_free(um->return_type);
            for (size_t k = 0; k < um->param_count; k++) {
                cgtype_free(um->param_types[k]);
                free(um->param_names[k]);
            }
            free(um->param_types);
            free(um->param_names);
        }
        free(ut->static_methods);
        for (size_t j = 0; j < ut->constructor_count; j++) {
            UserMethod *um = &ut->constructors[j];
            free(um->feng_name);
            free(um->c_name);
            cgtype_free(um->return_type);
            for (size_t k = 0; k < um->param_count; k++) {
                cgtype_free(um->param_types[k]);
                free(um->param_names[k]);
            }
            free(um->param_types);
            free(um->param_names);
        }
        free(ut->constructors);
    }
    free(cg->user_types);
    for (size_t i = 0; i < cg->user_spec_count; i++) {
        UserSpec *us = &cg->user_specs[i];
        free(us->feng_name);
        free(us->c_value_struct_name);
        free(us->c_witness_struct_name);
        free(us->c_aggregate_desc_name);
        free(us->c_aggregate_slots_name);
        free(us->c_aggregate_default_name);
        free(us->c_aggregate_init_fn_name);
        free(us->c_default_subject_struct_name);
        free(us->c_default_subject_desc_name);
        free(us->c_default_subject_new_name);
        free(us->c_default_witness_name);
        free(us->c_closure_struct_name);
        free(us->c_closure_desc_name);
        free(us->c_abi_fn_ptr_typedef_name);
        free(us->c_default_callable_noop_name);
        free(us->c_default_callable_new_name);
        for (size_t j = 0; j < us->generic_type_arg_count; ++j) {
            cg_type_ref_free(us->generic_type_args[j]);
        }
        free(us->generic_type_args);
        free(us->direct_parent_spec_indices);
        cgtype_free(us->callable_return_type);
        for (size_t j = 0; j < us->callable_param_count; ++j) {
            cgtype_free(us->callable_param_types[j]);
        }
        free(us->callable_param_types);
        free(us->callable_param_abi_kinds);
        for (size_t j = 0; j < us->union_member_count; ++j) {
            cgtype_free(us->union_member_types[j]);
        }
        free(us->union_member_types);
        cg_user_spec_members_free(us);
    }
    free(cg->user_specs);
    for (size_t i = 0; i < cg->callable_fn_value_count; ++i) {
        free(cg->callable_fn_values[i].descriptor_c_name);
        free(cg->callable_fn_values[i].c_adapter_fn);
        free(cg->callable_fn_values[i].c_var);
    }
    free(cg->callable_fn_values);
    for (size_t i = 0U;
         i < cg->callable_static_method_value_count;
         ++i) {
        free(cg->callable_static_method_values[i].descriptor_c_name);
        free(cg->callable_static_method_values[i].c_adapter_fn);
        free(cg->callable_static_method_values[i].c_var);
    }
    free(cg->callable_static_method_values);
    for (size_t i = 0; i < cg->callable_method_value_count; ++i) {
        free(cg->callable_method_values[i].c_target_fn);
        free(cg->callable_method_values[i].c_bind_fn);
        free(cg->callable_method_values[i].c_adapter_fn);
        free(cg->callable_method_values[i].c_closure_struct);
        free(cg->callable_method_values[i].c_closure_desc);
    }
    free(cg->callable_method_values);
    for (size_t i = 0U;
         i < cg->callable_spec_method_value_count;
         ++i) {
        free(cg->callable_spec_method_values[i].c_bind_fn);
        free(cg->callable_spec_method_values[i].c_adapter_fn);
        free(cg->callable_spec_method_values[i].c_closure_struct);
        free(cg->callable_spec_method_values[i].c_closure_desc);
    }
    free(cg->callable_spec_method_values);
    for (size_t i = 0U;
         i < cg->callable_generic_spec_method_value_count;
         ++i) {
        free(cg->callable_generic_spec_method_values[i].descriptor_c_name);
        free(cg->callable_generic_spec_method_values[i].c_adapter_fn);
        free(cg->callable_generic_spec_method_values[i].c_closure_struct);
        free(cg->callable_generic_spec_method_values[i].c_closure_desc);
    }
    free(cg->callable_generic_spec_method_values);
    /* G6: generic function registry cleanup. */
    for (size_t i = 0; i < cg->generic_fn_count; i++) {
        free(cg->generic_fns[i].feng_name);
        free(cg->generic_fns[i].c_name);
        for (size_t j = 0; j < cg->generic_fns[i].type_param_count; j++)
            free(cg->generic_fns[i].type_param_names[j]);
        free(cg->generic_fns[i].type_param_names);
    }
    free(cg->generic_fns);
    free(cg->generic_type_decls);
    free(cg->generic_spec_decls);
    for (size_t i = 0; i < cg->user_fit_count; i++) {
        UserFit *uf = &cg->user_fits[i];
        for (size_t j = 0; j < uf->method_count; j++) {
            UserMethod *um = &uf->methods[j];
            free(um->feng_name);
            free(um->c_name);
            cgtype_free(um->return_type);
            for (size_t k = 0; k < um->param_count; k++) {
                cgtype_free(um->param_types[k]);
                free(um->param_names[k]);
            }
            free(um->param_types);
            free(um->param_names);
        }
        free(uf->methods);
        free(uf->specs);
        free(uf->spec_indices);
        free(uf->c_prefix);
    }
    free(cg->user_fits);
    for (size_t i = 0; i < cg->builtin_fit_count; i++) {
        BuiltinFit *bf = &cg->builtin_fits[i];
        cgtype_free(bf->target_type);
        free(bf->target_type_params);
        free(bf->specs);
        for (size_t j = 0; j < bf->method_count; j++) {
            UserMethod *um = &bf->methods[j];
            free(um->feng_name);
            free(um->c_name);
            cgtype_free(um->return_type);
            for (size_t k = 0; k < um->param_count; k++) {
                cgtype_free(um->param_types[k]);
                free(um->param_names[k]);
            }
            free(um->param_types);
            free(um->param_names);
        }
        free(bf->methods);
        free(bf->c_prefix);
    }
    free(cg->builtin_fits);
    for (size_t i = 0; i < cg->witness_table_count; i++) {
        free(cg->witness_tables[i].c_var);
    }
    free(cg->witness_tables);
    for (size_t i = 0; i < cg->spec_slot_witness_table_count; ++i) {
        free(cg->spec_slot_witness_tables[i].c_var);
    }
    free(cg->spec_slot_witness_tables);
    for (size_t i = 0; i < cg->value_box_witness_table_count; ++i) {
        free(cg->value_box_witness_tables[i].c_var);
    }
    free(cg->value_box_witness_tables);
    for (size_t i = 0; i < cg->subject_witness_table_count; ++i) {
        free(cg->subject_witness_tables[i].c_var);
    }
    free(cg->subject_witness_tables);
    for (size_t i = 0; i < cg->default_parent_witness_count; ++i) {
        free(cg->default_parent_witnesses[i].c_var);
    }
    free(cg->default_parent_witnesses);
    for (size_t i = 0; i < cg->module_binding_count; i++) {
        free(cg->module_bindings[i].feng_name);
        free(cg->module_bindings[i].c_name);
        free(cg->module_bindings[i].c_ensure_init_name);
        free(cg->module_bindings[i].c_inited_name);
        cgtype_free(cg->module_bindings[i].type);
    }
    free(cg->module_bindings);
    for (size_t i = 0U;
         i < cg->imported_generic_shared_proto_count;
         ++i) {
        free(cg->imported_generic_shared_proto_names[i]);
    }
    free(cg->imported_generic_shared_proto_names);
    for (size_t i = 0; i < cg->string_literal_count; i++) {
        free(cg->string_literals[i].content);
        free(cg->string_literals[i].c_var);
    }
    free(cg->string_literals);
    for (size_t i = 0U; i < cg->generic_callable_dep_count; ++i) {
        free(cg->generic_callable_dep_keys[i]);
    }
    free(cg->generic_callable_dep_keys);
    for (size_t i = 0U;
         i < cg->closed_callable_descriptor_node_count;
         ++i) {
        free(cg->closed_callable_descriptor_nodes[i].key);
        free(cg->closed_callable_descriptor_nodes[i].c_name);
    }
    free(cg->closed_callable_descriptor_nodes);
    for (size_t i = 0U;
         i < cg->closed_array_descriptor_node_count;
         ++i) {
        free(cg->closed_array_descriptor_nodes[i].key);
        free(cg->closed_array_descriptor_nodes[i].c_name);
    }
    free(cg->closed_array_descriptor_nodes);
    for (size_t i = 0U;
         i < cg->closed_generic_param_descriptor_node_count;
         ++i) {
        free(cg->closed_generic_param_descriptor_nodes[i].key);
        free(cg->closed_generic_param_descriptor_nodes[i].c_name);
    }
    free(cg->closed_generic_param_descriptor_nodes);
    for (size_t i = 0; i < cg->expr_narrowing_count; i++) {
        free(cg->expr_narrowings[i].c_expr);
        cgtype_free(cg->expr_narrowings[i].type);
    }
    free(cg->expr_narrowings);
}

bool feng_codegen_emit_program(const FengSemanticAnalysis *analysis,
                               FengCompileTarget target,
                               const FengCodegenOptions *options,
                               FengCodegenOutput *out_output,
                               FengCodegenError *out_error) {
    if (!analysis || !out_output) return false;
    memset(out_output, 0, sizeof(*out_output));
    if (out_error) {
        out_error->message = NULL;
        out_error->path = NULL;
        memset(&out_error->token, 0, sizeof out_error->token);
    }
    /* Collect every program in deterministic (module, program) order. Local
     * programs still own body emission; imported-package programs now also
     * participate so shell/prototype registration can expose Feng ABI types
     * and callables to consumer codegen without re-emitting bodies. */
    size_t program_total = 0;
    size_t local_program_total = 0;
    const FengProgram *first_local_program = NULL;
    for (size_t i = 0; i < analysis->module_count; i++) {
        program_total += analysis->modules[i].program_count;
        if (analysis->modules[i].origin !=
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            local_program_total += analysis->modules[i].program_count;
            if (first_local_program == NULL && analysis->modules[i].program_count > 0U) {
                first_local_program = analysis->modules[i].programs[0];
            }
        }
    }
    CG cg = {0};
    cg.error = out_error;
    cg.analysis = analysis;
    cg.options = options;
    feng_codegen_maping_info_init(&cg.debug_info);
    if (local_program_total == 0) {
        cg_fail(&cg, (FengToken){0}, "CE0372", "codegen: no programs to compile");
        cg_dispose(&cg);
        return false;
    }
    const FengProgram **programs = calloc(program_total, sizeof(*programs));
    if (!programs) {
        cg_fail(&cg, (FengToken){0}, "IE0001", "codegen: out of memory collecting programs");
        cg_dispose(&cg);
        return false;
    }
    size_t cursor = 0;
    for (size_t i = 0; i < analysis->module_count; i++) {
        for (size_t j = 0; j < analysis->modules[i].program_count; j++) {
            programs[cursor++] = analysis->modules[i].programs[j];
        }
    }

    if (!cg_emit_all_programs(&cg, programs, program_total, target)) {
        free(programs);
        cg_dispose(&cg);
        return false;
    }

    if (target == FENG_COMPILE_TARGET_BIN) {
        const FreeFn *main_fn = cg_lookup_main(&cg);
        if (!main_fn) {
            cg_fail(&cg,
                first_local_program != NULL ? first_local_program->module_token : (FengToken){0},
                    "CE0373", "codegen: bin target requires `main` function");
            free(programs);
            cg_dispose(&cg);
            return false;
        }
        if (!cg_emit_main_wrapper(&cg, main_fn)) {
            free(programs);
            cg_dispose(&cg);
            return false;
        }
    }

    /* Emit a per-TU constructor that initialises this unit's string literal
     * slots before `main`. Both bin and lib targets get one — for libs it is
     * the only initialisation path, since consumer bins do not enumerate
     * dependency packages explicitly. */
    cg_emit_string_literal_ctor(&cg);

    free(programs);

    /* Emit the string literal storage table after all bodies are generated
     * so that strings interned during module-binding initialisers are
     * captured. The init prelude inside `main()` references these slots. */
    cg_emit_string_literal_table(&cg);

    char *src = cg_finalize(&cg);
    if (!src) {
        cg_fail(&cg, (FengToken){0}, "IE0001", "codegen: out of memory finalizing output");
        cg_dispose(&cg);
        return false;
    }
    out_output->c_source = src;
    out_output->c_source_length = strlen(src);
    out_output->debug_info = cg.debug_info;
    memset(&cg.debug_info, 0, sizeof(cg.debug_info));
    cg_dispose(&cg);
    return true;
}

void feng_codegen_output_free(FengCodegenOutput *output) {
    if (!output) return;
    free(output->c_source);
    output->c_source = NULL;
    output->c_source_length = 0;
    feng_codegen_maping_info_dispose(&output->debug_info);
}

void feng_codegen_error_free(FengCodegenError *error) {
    if (!error) return;
    free(error->message);
    error->message = NULL;
}
